  [80010000] = {
    id = 80010000,
    name = "拖拽成员出战。"
  },
  [80010001] = {
    id = 80010001,
    name = "将[color=#e6ff51]「异刃」[/color]拖拽到更合适的位置，当[color=#e6ff51]「异刃」[/color]前方\n没有阻挡时，可以直接攻击敌方远程单位。"
  },
  [80010002] = {
    id = 80010002,
    name = "开始战斗吧。"
  },
  [80010003] = {
    id = 80010003,
    name = "开始战斗吧。"
  },
  [80010004] = {
    id = 80010004,
    name = "当能量条满后，队长可以指挥成员发动[color=#e6ff51]「总攻」[/color]。"
  },
  [80010005] = {
    id = 80010005,
    name = "队长就是现在，可以指挥大家发起[color=#e6ff51]「总攻」[/color]。"
  },
  [80010006] = {
    id = 80010006,
    name = "成功发动总攻后，队长可按照职业顺序选择想要施放[color=#e6ff51]「总攻技」[/color]的成员。"
  },
  [80010007] = {
    id = 80010007,
    name = "首先让我们选择[color=#e6ff51]「坚甲」[/color]职业的成员。"
  },
  [80010008] = {
    id = 80010008,
    name = "让我们继续选择[color=#e6ff51]「异刃」[/color]职业的成员。"
  },
  [80010009] = {
    id = 80010009,
    name = "请继续选择[color=#e6ff51]「言灵」[/color]职业。"
  },
  [80010010] = {
    id = 80010010,
    name = "最后让我们选择[color=#e6ff51]「猎影」[/color]职业的成员来完成最终选择。"
  },
  [80010011] = {
    id = 80010011,
    name = "我们选择的成员在施放[color=#e6ff51]「总攻技」[/color]后，会进入冷却时间，在发动下一轮[color=#e6ff51]「总攻」[/color]时，只能选择冷却时间结束的成员，请队长合理安排成员。"
  },
  [80010012] = {
    id = 80010012,
    name = "总攻会持续一段时间，在这段时间内，所有成员的输出会获得[color=#e6ff51]大幅的提升[/color]。"
  },
  [80010013] = {
    id = 80010013,
    name = "菲尼斯前方出现了魔物阻挡，我们需要调整他的位置。"
  },
  [80010014] = {
    id = 80010014,
    name = "将菲尼斯拖拽至前方无魔物阻挡的位置。"
  },
  [80010015] = {
    id = 80010015,
    name = "准备就绪，开始战斗吧。"
  },
  [80010016] = {
    id = 80010016,
    name = "队长请发起总攻吧。"
  },
  [80010017] = {
    id = 80010017,
    name = "发动总攻时，同职业有多名成员时，只能选择[color=#e6ff51]「一名」[/color]成员释放总攻技。"
  },
  [80010018] = {
    id = 80010018,
    name = "这次就让新加入队伍的成员来展现自己的实力吧。"
  },
  [80010019] = {
    id = 80010019,
    name = "胜利就在眼前了，发动总攻。"
  },
  [80010020] = {
    id = 80010020,
    name = "这次就来施放尼莉莎的总攻技吧。"
  },
  [80010200] = {
    id = 80010200,
    name = "前方魔物越来越强了，我们需要\n提升队友的实力。"
  },
  [80010201] = {
    id = 80010201,
    name = "进入成员界面。"
  },
  [80010202] = {
