    name = "接下来我们去招募新的成员吧。"
  },
  [80010204] = {
    id = 80010204,
    name = "出现了新的强力魔物，可以使用[color=#e6ff51]「异刃」[/color]优先击杀。点击魔物展开其详情。"
  },
  [80010205] = {
    id = 80010205,
    name = "前方出现了新的魔物，该魔物身形灵活，可以使用[color=#e6ff51]「坚甲」[/color]和[color=#e6ff51]「异刃」[/color]进行有效的阻挡。"
  },
