  },
  [85012141] = {
    id = 85012141,
    name = "探险者朝雾，为了探寻剑道的极致，今日正式加入探险队，接受您的指点。"
  },
  [85022141] = {
    id = 85022141,
    name = "此前队长为我指出了一些修行中的不足，我全都调整了一遍，出发探险前，队长能陪我再练习一会儿吗？"
  },
  [85032141] = {
    id = 85032141,
    name = "如果有空队长可以指导我一些探险队相关的事务吗？比如委托承接和报告，探险前准备工作之类的。最近同伴们看起来都很忙，我也希望能为大家做些力所能及的事。"
  },
  [85032142] = {
    id = 85032142,
    name = "饲养可爱的宠物虽然需要花费不少金钱和精力，但我觉得非常值得。和可爱的宠物们待在一起的时候，所有的疲惫和烦恼全都会烟消云散。"
  },
  [85042141] = {
    id = 85042141,
    name = "坚韧的意志，才是剑道修行的基石。"
  },
  [85042142] = {
    id = 85042142,
    name = "这样的成长着实令人欣喜，但距离剑道的极致仍有不少差距，我还不能松懈。"
  },
  [85042143] = {
    id = 85042143,
    name = "希望有朝一日，我的剑术能与您的探险队一起名扬深渊。"
  },
  [85052141] = {
    id = 85052141,
    name = "一些贵族喜欢将剑术当作炫耀身份的方式，或者作为欺凌他人的手段，在我看来这是对剑道的侮辱。"
  },
  [85052142] = {
    id = 85052142,
    name = "在担任剑术老师的时候，我丝毫不敢怠慢，生怕自己没能将剑道的真谛传授给学员，然而他们关注的却只是剑术是否华丽，剑技是否够强。"
  },
  [85052143] = {
    id = 85052143,
    name = "修行剑道，也是修行自己的内心，只有内心澄澈，毫无杂念，才有可能一窥剑道的极致。"
  },
  [85052144] = {
    id = 85052144,
    name = "人们常说追寻理想是一个孤独而漫长的旅程，但我却没有这样的感觉，难道是因为队长一直陪在我身边的原因吗？"
  },
  [85052145] = {
    id = 85052145,
    name = "这段时间以来，多亏了队长指导才让我取得了如此丰厚的收获，也让我觉得自己所追寻的目标不再是那么遥不可及。"
  },
  [85062141] = {
    id = 85062141,
    name = "请见识我的修行成果吧。"
  },
  [85072141] = {id = 85072141, name = "嘿！"},
  [85072142] = {id = 85072142, name = "哈！"},
  [85072143] = {id = 85072143, name = "呀啊！"},
  [85082141] = {
    id = 85082141,
    name = "剑光、绽放。"
  },
  [85082142] = {
    id = 85082142,
    name = "如风如电。"
  },
  [85092141] = {
    id = 85092141,
    name = "随我的剑起舞吧。"
  },
  [85092142] = {
    id = 85092142,
    name = "由我来画上休止符。"
  },
  [85102141] = {id = 85102141, name = "唔。"},
  [85102142] = {id = 85102142, name = "呃。"},
  [85102143] = {id = 85102143, name = "呃啊。"},
  [85112141] = {
    id = 85112141,
    name = "一点小伤，没事。"
  },
  [85122141] = {
    id = 85122141,
    name = "我的剑......还不够坚定......"
  },
  [85132141] = {
    id = 85132141,
    name = "真是一场干净利落地战斗，多亏了队长的指点，我才能拥有这样的表现。"
  },
  [85142141] = {
    id = 85142141,
    name = "队长，你带大家先撤，我来负责断后。"
  },
  [85152141] = {
    id = 85152141,
    name = "生日快乐，队长。今天暂时放下手里的工作，跟我去一个非常有趣的地方吧。那里有很多可爱的宠物，我想，一定能让你度过一个难忘的生日。"
  },
  [85162141] = {
    id = 85162141,
    name = "这个新年队长有什么安排吗？我？如果是以前，我会和可爱的宠物一起度过，但现在嘛......我更想和队长一起。不管队长想怎样度过，我都会和你一起。"
  },
  [85172141] = {
    id = 85172141,
    name = "节日快乐队长，看你怀里的礼物，今天收到了不少点心啊。呵呵，可惜我不会做点心，就让这柄定制的剑代替点心向你传达我的谢意吧。"
  },
  [85182141] = {
    id = 85182141,
    name = "小时候我跟随导师修行剑术，每次遇到这样热闹的节日时她都会让我停下一切，去安心享受节日。当时我完全不明白她所说的劳逸结合是什么意思，甚至觉得会耽误自己修行。"
  },
  [85192141] = {
    id = 85192141,
    name = "队长看起来很忙碌，有什么需要我帮忙的吗——派送礼物？当然没问题。以后这种事尽管交给我就好，我对自己的体力可是很有自信。"
  },
  [85012151] = {
    id = 85012151,
    name = "想必这位仪表堂堂、气度不凡的人就是队长了，果然百闻不如一见。雪折邸、鎺，遵从邀约而来。"
  },
  [85022151] = {
    id = 85022151,
    name = "队长每天需要处理的事务还真多啊......不过在开始忙碌前，陪我共享这片刻悠闲如何？"
  },
  [85032151] = {
    id = 85032151,
    name = "这柄刀陪伴在我身边多年，对我而言，它已不仅仅是武器，更像是一位老友。或许这深渊中有不少比它更锋利的存在，但只有它才是最适合我的。"
  },
  [85032152] = {
    id = 85032152,
    name = "这几天和探险队内不少人都切磋了一番，也算是见识到了各种流派的武技。队长的战斗风格是怎样的呢？陪我切磋一下吧，让我能更深入的领略队长的实力。"
  },
  [85042151] = {
    id = 85042151,
    name = "太锋利的刀刃很可能会伤及自身哦，队长。"
  },
  [85042152] = {
    id = 85042152,
    name = "队长的好意我收下了，请期待我为您展现全力的那一刻吧。"
  },
  [85042153] = {
    id = 85042153,
    name = "这柄刀似乎已经完全认可队长了，那么、就让它为队长斩除一切前行的阻碍吧。"
  },
  [85052151] = {
    id = 85052151,
    name = "雪折邸算是雪村的代表，所以我们的言行与雪村的声誉息息相关，以至于偶尔想稍微放纵一下都很困难。"
  },
  [85052152] = {
    id = 85052152,
    name = "一柄刀的刀刃，往往能反映使用者的内心。我这柄刀，在队长看来，可还算锋利？"
  },
  [85052153] = {
    id = 85052153,
    name = "雪村的生活很宁静，没有什么惊心动魄的大事，所以有时会让人觉得无聊。如果队长感兴趣，我可以带你去看看，和队长在一起，或许会有趣很多。"
  },
  [85052154] = {
    id = 85052154,
    name = "很久没有享受过如此酣畅淋漓的战斗了，当初答应队长的邀约果然明智。呵呵，我很期待队长还能为我带来怎样的惊喜。"
  },
  [85052155] = {
    id = 85052155,
    name = "最近似乎太放纵了？呵呵，反正没有别人看到，在队长面前稍微放纵一点也没关系吧？难道队长还想以此为把柄，胁迫我做一些超出合约的事？"
  },
  [85062151] = {
    id = 85062151,
    name = "终于可以放开手脚了。"
  },
  [85072151] = {id = 85072151, name = "呵啊。"},
  [85072152] = {id = 85072152, name = "嘿！"},
  [85072153] = {id = 85072153, name = "呀啊。"},
  [85082151] = {id = 85082151, name = "看招。"},
  [85082152] = {
    id = 85082152,
    name = "躲不掉的。"
  },
  [85092151] = {
    id = 85092151,
    name = "秘剑、雪舞。"
  },
  [85092152] = {
    id = 85092152,
    name = "与飞雪共眠吧。"
  },
  [85102151] = {id = 85102151, name = "唔。"},
  [85102152] = {id = 85102152, name = "呃。"},
  [85102153] = {id = 85102153, name = "唔啊。"},
  [85112151] = {
    id = 85112151,
    name = "不错的招式，再来！"
  },
  [85122151] = {
    id = 85122151,
    name = "刀刃......还不够锋利......"
  },
  [85132151] = {
    id = 85132151,
    name = "无论体验过多少次，胜利的感觉依然如此美妙。"
  },
  [85142151] = {
    id = 85142151,
    name = "别放在心上队长，偶尔输一场只会让我们变得更强。"
  },
  [85152151] = {
    id = 85152151,
    name = "生日这样的日子，就该放下一切，好好放松一下。走吧队长，我珍藏了一些美酒，今天就和我一起纵情享受吧。"
  },
  [85162151] = {
    id = 85162151,
    name = "雪村的冬季都是白茫茫一片，大雪封山，与外界近乎断绝联系。因此整个新年期间，村里的人几乎都会聚在一起。一起饮酒作乐，一起为新年祈愿。"
  },
  [85172151] = {
    id = 85172151,
    name = "队长竟然带了这么多点心过来，能给我一些吗，看起来很适合配酒——节日礼物？......竟然是这样的节日，看来我也得去准备些点心，作为谢礼送给队长了。"
  },
  [85182151] = {
    id = 85182151,
    name = "真是热闹的节日啊，队长，我们去找个地方喝两杯吧。这样盛大的庆典，正是享用我珍藏美酒的绝佳时机。"
  },
  [85192151] = {
    id = 85192151,
    name = "这瓶酒是我离开雪村时带出来的，偶尔想雪村了，就会喝上一小口。送给你，队长，就当作节日礼物。如果你想感受下雪村的风情，或者想我了，也可以喝上一小口。"
  },
  [85011741] = {
    id = 85011741,
    name = "您好~我是圣歌的安娜贝尔，代号司礼者。非常感谢您对圣歌理念的认可！愿我们的努力，能为这个世界带来更多希望和美好。"
  },
  [85021741] = {
    id = 85021741,
    name = "让深渊变得美好并非一朝一夕可以做到，想要取得探险成果也是如此。我们必须从每一件小事做起，比如、探险前的准备工作。"
  },
  [85031741] = {
    id = 85031741,
    name = "为了实现圣歌的夙愿，同伴们都表现得非常努力，但只靠我们自己，所能做到的事终究有限。如果能用我们的行动召集更多志同道合的同伴，或许才能为深渊带来真正的改变。"
  },
  [85031742] = {
    id = 85031742,
    name = "我们的人生就像是一场追寻未知的旅程，在旅程中，一些人慢慢沦为了欲望的奴隶，如果无法得到引导，亦或执迷不悟，最终的结局只会是毁灭。"
  },
  [85041741] = {
    id = 85041741,
    name = "我所追寻的正义，是帮助弱小，是惩戒罪恶，是守护一切美好的存在。"
  },
  [85041742] = {
    id = 85041742,
    name = "无论身处怎样的黑暗也无需畏惧，只要跟随内心的指引，必然可以找到前行的方向！"
  },
  [85041743] = {
    id = 85041743,
    name = "有人将我称作神明的使者、正义圣女......我才没有那么伟大呢！不过能得到那样的称呼，说明我所做的一切被大家认可了吧？！"
  },
  [85051741] = {
    id = 85051741,
    name = "我在各地行走时偶尔也会遇到一些不懂感恩、鲁莽粗俗的家伙，我每次都会想“懒得管他们”，可是身体却总会不由自主地行动起来......"
  },
  [85051742] = {
    id = 85051742,
    name = "圣歌的大家虽然都有相似的信念，但在执行上却有不少差别。比如赦罪人，只要被她认定为需要帮助，不管对方怎么拒绝也没用。"
  },
  [85051743] = {
    id = 85051743,
    name = "有人将欲望视作吞噬人心的恶魔，其实真正的恶魔从来不是欲望，而是丧失底线的信念和不够坚定的内心。"
  },
  [85051744] = {
    id = 85051744,
    name = "深渊中有不少诡计多端的罪恶之徒，想要追踪他们非常困难。不过、如果他们被圣光使盯上，不管怎样狡猾也很难逃掉。"
  },
  [85051745] = {
    id = 85051745,
    name = "我刚踏上旅途那段时间非常辛苦，也曾几度想要放弃。可是每当准备放弃时，我家所遭遇的一切便会浮现在我的脑海，给我继续前行的勇气。"
  },
  [85061741] = {
    id = 85061741,
    name = "为了我们所信仰的正义！"
  },
  [85071741] = {id = 85071741, name = "嘿咿~"},
  [85071742] = {id = 85071742, name = "呀啊。"},
  [85071743] = {id = 85071743, name = "嘿。"},
  [85081741] = {
    id = 85081741,
    name = "我、不会犹豫！"
  },
  [85081742] = {
    id = 85081742,
    name = "遵从内心的指引。"
  },
  [85091741] = {
    id = 85091741,
    name = "以正义之名，消弭一切罪恶！"
  },
  [85091742] = {
    id = 85091742,
    name = "以圣歌之名，守护爱与希望！"
  },
  [85101741] = {id = 85101741, name = "呜呃~"},
  [85101742] = {id = 85101742, name = "呃啊。"},
  [85101743] = {id = 85101743, name = "唔。"},
  [85111741] = {
    id = 85111741,
    name = "这点麻烦，阻止不了我。"
  },
  [85121741] = {
    id = 85121741,
    name = "只能......到此为止了吗......"
  },
  [85131741] = {
    id = 85131741,
    name = "我们都有必须前行的理由，没有任何困难可以阻碍我们。"
  },
  [85141741] = {
    id = 85141741,
    name = "现在不是垂头丧气的时候，只要大家都平安无事，我们就还有机会。"
  },
  [85151741] = {
    id = 85151741,
    name = "这两天我看大家都在筹备庆祝会的物资，是有什么活动吗？——你的生日？！......这种事应该早几天说吧？这么突然，准备礼物的时间都不够了。"
  },
  [85161741] = {
    id = 85161741,
    name = "今天还有别的事务吗？我要去参加圣歌的新年聚会，一起去吗？走吧，新年给自己放个假也没问题，明天我们再一起加油就好了！"
  },
  [85171741] = {
    id = 85171741,
    name = "现在有空吗？我按照书上的方法做了一些点心，来试试吧！——感觉很美味？呵呵，难道我真是料理天才，照着说明书就能做出让人满意的点心，看来以后有机会可以试试更复杂的料理。"
  },
  [85181741] = {
    id = 85181741,
    name = "到处都在举办节日庆典，真热闹啊~多亏了大家的努力，才能这样安心地享受节日。我们也一起去玩玩吧，作为守护这一切的人，如果不去亲自感受，是不会明白自己所做的一切有多么重要的。"
  },
  [85191741] = {
    id = 85191741,
    name = "可以帮我整理一下礼物吗？这里堆放的都是从各地募捐而来的礼物，品种非常多~必须赶紧完成分类，才能确保它们都能及时被送到有需要的人手中。"
  },
  [85011831] = {
    id = 85011831,
    name = "你好，我是云罗，请问该怎么称呼你呢——队长？真是奇怪的称呼，呵呵，不过既然你这样说了，那我就这样称呼好了。"
  },
  [85021831] = {
    id = 85021831,
    name = "队长辛苦了，来让我给你捶捶背吧。我可是知道很多捶背技巧，连父亲都经常夸我呢。"
  },
  [85031831] = {
    id = 85031831,
    name = "队长每天要处理的这些文件感觉和宗门里的文书很像呢，有时间的话队长可以教教我吗？我希望自己也能帮队长分担一些工作，这样就有更多时间一起玩了。"
  },
  [85031832] = {
    id = 85031832,
    name = "我虽然没有探险队里其他哥哥姐姐们那样丰富的战斗经验，但寻常魔物绝不是我的对手！呵呵，我可不是在说大话哦，普通的探险任务，队长就安心交给我吧。"
  },
  [85041831] = {
    id = 85041831,
    name = "真是独特的修行方式，给人的感觉真不错！"
  },
  [85041832] = {
    id = 85041832,
    name = "能获得这么强大的力量，队长一定付出了很多吧？云罗一定会好好努力，全力回报队长的！"
  },
  [85041833] = {
    id = 85041833,
    name = "队长竟然如此信任云罗......我会好好使用这份力量，绝不辜负队长对我的期待。"
  },
  [85051831] = {
    id = 85051831,
    name = "在我心中，队长和父亲大人一样，都是斩杀魔物、惩处罪恶、守护正义的大英雄，我长大了也要像你们一样！"
  },
  [85051832] = {
    id = 85051832,
    name = "不管面对怎样的魔物我都不会害怕，父亲说过，只要不畏惧敌人，无论多么强大的对手都能找到击败它的办法。"
  },
  [85051833] = {
    id = 85051833,
    name = "深渊的一切对我来说都非常新鲜，等回去后我一定要好好和大家讲述这里的故事。对了，到时候队长也和我一起回去吧，让我也带你见识一下我故乡的风景。"
  },
  [85051834] = {
    id = 85051834,
    name = "不管深渊还是我的故乡，魔物都是威胁人们安宁生活的大敌，解决魔物灾祸是我们所有探险者的责任。"
  },
  [85051835] = {
    id = 85051835,
    name = "如果有一天我突然回去了，队长会想我吗？呵呵，我肯定会想队长，会想在这里的一切。不管未来如何变化，我都绝不会忘记和队长共度的时光。"
  },
  [85061831] = {
    id = 85061831,
    name = "请期待云罗的表现吧。"
  },
  [85071831] = {id = 85071831, name = "嘿！"},
  [85071832] = {id = 85071832, name = "呵啊。"},
  [85071833] = {id = 85071833, name = "哈！"},
  [85081831] = {
    id = 85081831,
    name = "敕令，灭！"
  },
  [85081832] = {
    id = 85081832,
    name = "敕令，破！"
  },
  [85091831] = {
    id = 85091831,
    name = "大道至简、万物归真！"
  },
  [85091832] = {
    id = 85091832,
    name = "道化天地、万象森罗！"
  },
  [85101831] = {id = 85101831, name = "哇啊。"},
  [85101832] = {id = 85101832, name = "呜呃。"},
  [85101833] = {id = 85101833, name = "呀啊。"},
  [85111831] = {
    id = 85111831,
    name = "我才不会认输！"
  },
  [85121831] = {
    id = 85121831,
    name = "对不起......"
  },
  [85131831] = {
    id = 85131831,
    name = "怎么样队长，我的表现还不错吧？再强一点的敌人我也没问题哦。"
  },
  [85141831] = {
    id = 85141831,
    name = "呜呜，对不起，都怪云罗拖了大家的后腿......"
  },
  [85151831] = {
    id = 85151831,
    name = "生日快乐，队长！今天可是非常非常重要的日子，不管有什么事都先放一下吧，让云罗陪你一起好好庆祝生日！"
  },
  [85161831] = {
    id = 85161831,
    name = "哇，又到新年了！在我的故乡，新年可是最最重要的节日，人们会聚在一起表演歌舞杂技，舞狮舞龙，将对新年的祈愿传达给神明。"
  },
  [85171831] = {
    id = 85171831,
    name = "自从遇见了队长，队长就给予了我很多关照，我觉得不管怎样的谢礼也难以传达这份谢意。今后就让云罗一直陪在队长身边，回报队长的关照吧。"
  },
  [85181831] = {
    id = 85181831,
    name = "队长，我刚刚在外面玩，路过的大人们就塞了好多糖果给我，他们是想拐走云罗吗？——噢，原来是这个节日的习俗啊，竟然这么有趣，队长再给我讲讲这个节日的故事吧！"
  },
  [85191831] = {
    id = 85191831,
    name = "队长队长，快来看，我真的收到礼物了！没想到那个传说竟然是真的，呵呵，今后我也要继续做个好孩子，这样一定每年都能收到礼物！"
  },
  [85012161] = {
    id = 85012161,
    name = "你好队长，我是艾格尼丝——传闻中的魔剑士？呵呵，那都是大家的传言太夸张了，我只是一个酷爱剑术的魔法学徒而已。"
  },
  [85022161] = {
    id = 85022161,
    name = "距离出发还有段时间，队长再休息一下吧。有我在这里值守，不会出什么问题。"
  },
  [85032161] = {
    id = 85032161,
    name = "队长这里竟然收集了这么多魔法、武技有关的研究记录，对我来说就像一个宝库。我能申请自由查阅权限吗？当然，作为回报，我也会将自己掌握的一切全部献给队长。"
  },
  [85032162] = {
    id = 85032162,
    name = "在我看来剑术和魔法各有优劣，并不能单纯说谁更好，这一点，我想队长和我想法应该很相似吧？只要运用得当，无论剑术还是魔法都能掌控战局。"
  },
  [85042161] = {
    id = 85042161,
    name = "这是对我的嘉奖吗？非常感谢。"
  },
  [85042162] = {
    id = 85042162,
    name = "多亏了队长的支持，我的实力进步速度已经超过了预期，请好好期待我的表现吧。"
  },
  [85042163] = {
    id = 85042163,
    name = "我会负责斩破我们前行路上的一切阻碍，用队长给予我的力量，开创属于我们的未来。"
  },
  [85052161] = {
    id = 85052161,
    name = "小时候父母都希望我能专心修行魔法，可我却偏偏对剑术情有独钟......我不想辜负他们的期待，也不想放弃自己的兴趣，所以才同时修行了魔法和剑术。"
  },
  [85052162] = {
    id = 85052162,
    name = "修行魔法久了，我也慢慢爱上了魔法，所以在后来有机会做出选择的时候，我并没有选择放弃魔法。"
  },
  [85052163] = {
    id = 85052163,
    name = "同时修行剑术和魔法确实很辛苦，而且还要面对不少流言蜚语，比如“什么都想要，最后一定什么也得不到”。但我已经走到了这一步，我不想放弃。"
  },
  [85052164] = {
    id = 85052164,
    name = "我并不觉得自己的实力能匹配自己的名气，不过“魔剑士”这个称呼却让我在修行时有了更加清晰的目标。"
  },
  [85052165] = {
    id = 85052165,
    name = "队长对我的支持让我有了很明显的进步，我感觉和队长在一起，似乎更远大一点的目标也能实现......队长能陪我一起去见证那个未来吗？"
  },
  [85062161] = {
    id = 85062161,
    name = "交给我吧，队长。"
  },
  [85072161] = {id = 85072161, name = "喝！"},
  [85072162] = {id = 85072162, name = "哈啊。"},
  [85072163] = {id = 85072163, name = "咿呀。"},
  [85082161] = {id = 85082161, name = "看招。"},
  [85082162] = {
    id = 85082162,
    name = "受死吧。"
  },
  [85092161] = {
    id = 85092161,
    name = "魔剑，回应我吧。"
  },
  [85092162] = {
    id = 85092162,
    name = "由我来开辟前路！"
  },
  [85102161] = {id = 85102161, name = "唔。"},
  [85102162] = {id = 85102162, name = "呃。"},
  [85102163] = {id = 85102163, name = "唔啊。"},
  [85112161] = {
    id = 85112161,
    name = "不过如此。"
  },
  [85122161] = {
    id = 85122161,
    name = "到此为止了吗......"
  },
  [85132161] = {
    id = 85132161,
    name = "很久没有这种畅快的感觉了，队长的战术指挥堪称艺术。"
  },
  [85142161] = {
    id = 85142161,
    name = "真是狡诈的对手，队长带大家先撤，这里交给我。"
  },
  [85152161] = {
    id = 85152161,
    name = "今天好热闹啊，大家似乎在筹备什么庆典——队长的生日？！糟糕，生日礼物还没有......队长，请允许我请个假，有比探险更重要的事我必须马上去做！"
  },
  [85162161] = {
    id = 85162161,
    name = "过去这一年中最重要的事就是和队长的相遇，希望新的一年，能和队长有一段更加精彩的旅程。无论有多少未知和挑战，只要和队长一起便无所畏惧。"
  },
  [85172161] = {
    id = 85172161,
    name = "队长，非常感谢您这段时间以来的关照，这份点心希望队长能收下！如果不合您的口味请务必告诉我，我会立即进行调整。"
  },
  [85182161] = {
    id = 85182161,
    name = "队长今天有空吗？圈落里正在举办节日庆典，一起去看看吧。——还有些探险队事务？那我和你一起处理，等结束后我们再去庆典吧。"
  },
  [85192161] = {
    id = 85192161,
    name = "今天和探险队的大家交换了不少礼物，感觉能加入这个探险队真是太好了。对了，这个大箱子里是我为队长准备的特别礼物，希望队长能够喜欢。"
  },
  [85012171] = {
    id = 85012171,
    name = "您就是队长吧？作为您与雪折邸合作的条件之一，認前来为您效力。只要是不违背雪折邸的理念，任何事务都请尽管吩咐。"
  },
  [85022171] = {
    id = 85022171,
    name = "处理文件并非我的专长，如果队长想要这方面的助手，我可以为您推荐更合适的人选。"
  },
  [85032171] = {
    id = 85032171,
    name = "这副弓矢是我最信赖的同伴，不管身陷怎样的绝境，都可以对它完全信任。因此不管有多忙，每天的保养工作我也不会落下。"
  },
  [85032172] = {
    id = 85032172,
    name = "探险队内的成员明明有这么多，却一点也不会觉得嘈杂，这种安宁的感觉甚至让我觉得和雪折邸很像......真好奇队长是如何将这一切都管理得井井有条的。"
  },
  [85042171] = {
    id = 85042171,
    name = "非常感谢队长的栽培，我会用手中的弓矢报答队长的信任。"
  },
  [85042172] = {
    id = 85042172,
    name = "弓道的修行也是内心的修行，只有摒除杂念，人弓合一，才能做到一箭制胜。"
  },
  [85042173] = {
    id = 85042173,
    name = "队长对我的支持远远超出了合作条约中的内容，我会珍惜这份力量，为我们的未来开辟前路。"
  },
  [85052171] = {
    id = 85052171,
    name = "雪折邸的成员都是雪村中主要家族的继承人，我们共同的目的都是精进武技，为家族和雪村的未来奉献自己的力量。"
  },
  [85052172] = {
    id = 85052172,
    name = "犹豫，是弓道中的大忌，不管何种境地，不管面对怎样的对手，都应当心无旁骛，全力以赴。"
  },
  [85052173] = {
    id = 85052173,
    name = "雪村每年都会举办打猎活动，那时候我可是经常拿冠军！嗯？队长似乎不太信？呵呵，等有机会我会让你见识一下我的狩猎技艺。"
  },
  [85052174] = {
    id = 85052174,
    name = "修行没有捷径，只有拥有足够扎实的基本功，才能让自己在面对危险时拥有足够的底气。"
  },
  [85052175] = {
    id = 85052175,
    name = "这段时间以来我感觉收获很大，不仅仅是实力的提升，在人际交往、探险队事务等方面，我也有了明显的成长，这一切全都多亏了队长！"
  },
  [85062171] = {
    id = 85062171,
    name = "我已经准备完毕。"
  },
  [85072171] = {id = 85072171, name = "呀。"},
  [85072172] = {id = 85072172, name = "嘿。"},
  [85072173] = {id = 85072173, name = "喝。"},
  [85082171] = {id = 85082171, name = "专注。"},
  [85082172] = {id = 85082172, name = "凝神。"},
  [85092171] = {
    id = 85092171,
    name = "追魂夺魄。"
  },
  [85092172] = {
    id = 85092172,
    name = "以这一箭、献上终结。"
  },
  [85102171] = {id = 85102171, name = "呃啊。"},
  [85102172] = {id = 85102172, name = "嘁。"},
  [85102173] = {id = 85102173, name = "唔呃。"},
  [85112171] = {
    id = 85112171,
    name = "我可不会害怕。"
  },
  [85122171] = {
    id = 85122171,
    name = "大意了......"
  },
  [85132171] = {
    id = 85132171,
    name = "大家的配合如此默契，这样的胜利是理所当然的。走吧，一起去迎接下一场胜利。"
  },
  [85142171] = {
    id = 85142171,
    name = "失败的滋味比胜利更加刻骨铭心，我会记住这种感觉的。"
  },
  [85152171] = {
    id = 85152171,
    name = "生日快乐队长，如此重要的日子可不能呆在探险队里处理这些杂务，得好好庆祝才行！这附近有几个很好玩的地方，今天我们一起去痛快玩一番吧。"
  },
  [85162171] = {
    id = 85162171,
    name = "由于天气和地形原因，新年时雪村几乎与外界断绝联系，但村里有自己庆祝新年的方式，比如武技较量啊、歌舞比赛啊，甚至还有喝酒大赛等等，有机会队长一定要去见识一下。"
  },
  [85172171] = {
    id = 85172171,
    name = "代表感谢的节日吗......雪村也有类似的节日，不过我们是感谢神明。那么今天就让我用雪村感谢神明的方式——献上大量的食物，感谢队长吧！"
  },
  [85182171] = {
    id = 85182171,
    name = "没想到关于鬼怪的节日竟然如此热闹，着实让我大开眼界。要知道在雪村鬼怪可是让大家都很敬畏的存在，通常不会轻易提及。"
  },
  [85192171] = {
    id = 85192171,
    name = "今天这样特别的日子，队长有什么安排吗？我？我没什么特别的安排，不管做什么我自然都会和队长一起。只是如果有空的话，要一起去庆典上逛逛吗？"
  },
  [85012181] = {
    id = 85012181,
    name = "......是您唤醒了我吗。我好像......欠您一声谢谢。莎尔拉，这是我的名字......应该，没错。"
  },
  [85022181] = {
    id = 85022181,
    name = "这里没有沼泽，也没有锁链的压迫感，可我仍会下意识防御，你不会因此厌弃我吧，队长？"
  },
  [85032181] = {
    id = 85032181,
    name = "爬满藤蔓的城墙......精心修剪的花圃......来回忙碌的人群......有时候我的脑海中会出现一些破碎的画面，我分不清那是我的记忆，还是单纯的想象。"
  },
  [85032182] = {
    id = 85032182,
    name = "我偶尔会听见一阵空灵的歌声，那声音很温柔。但每次我想靠近，仔细聆听的时候，声音就会碎掉，好像在提醒我勇敢往前走，不要回头。"
  },
  [85042181] = {
    id = 85042181,
    name = "力量正在变强。但这感觉让我有些不安......感觉曾发生过什么可怕的事。"
  },
  [85042182] = {
    id = 85042182,
    name = "荆棘和利刃......都是用来保护重要之物的。我已经忘记太多东西了，所以剩下的......不能再失去了。"
  },
  [85042183] = {
    id = 85042183,
    name = "请不要让我独自待太久，那些“冲动”会回来，它们想让我继续完成某种我已经不理解的事情。"
  },
  [85052181] = {
    id = 85052181,
    name = "我好像......有过一个生日，似乎全城都在为我庆祝......之后......不记得了。这样也好。"
  },
  [85052182] = {
    id = 85052182,
    name = "荆棘女妖......教廷是这么称呼我的。我不喜欢这个名字，但也......找不到更合适的了。您觉得呢？"
  },
  [85052183] = {
    id = 85052183,
    name = "我好像做了很多错事，犯下了许多无法弥补的过错......虽然想不起来是什么，但我会怀着赎罪的心，好好活下去。"
  },
  [85052184] = {
    id = 85052184,
    name = "有时候我会觉得，歌声不是从我嘴里发出的，而是从某个已经消失的人那里借来的。"
  },
  [85052185] = {
    id = 85052185,
    name = "队长将我解救出来后，我记住的东西......变多了。您的脸，您的声音，您叫我的方式，这些......我都牢记于心。"
  },
  [85062181] = {
    id = 85062181,
    name = "我会永远在您身边，队长。"
  },
  [85072181] = {id = 85072181, name = "嘿。"},
  [85072182] = {id = 85072182, name = "咿呀。"},
  [85072183] = {id = 85072183, name = "呵啊。"},
  [85082181] = {id = 85082181, name = "刺穿。"},
  [85082182] = {id = 85082182, name = "退下。"},
  [85092181] = {
    id = 85092181,
    name = "全部，归于沉寂吧。"
  },
  [85092182] = {
    id = 85092182,
    name = "在我的歌声中安息吧。"
  },
  [85102181] = {id = 85102181, name = "唔。"},
  [85102182] = {id = 85102182, name = "呜哇。"},
  [85102183] = {id = 85102183, name = "呃啊。"},
  [85112181] = {
    id = 85112181,
    name = "我还能......撑住。"
  },
  [85122181] = {
    id = 85122181,
    name = "又要......遗忘了......"
  },
  [85132181] = {
    id = 85132181,
    name = "只要是队长的敌人，我绝不会轻饶。"
  },
  [85142181] = {
    id = 85142181,
    name = "我是不是......又变回那个地方了......"
  },
  [85152181] = {
    id = 85152181,
    name = "今天是你的生日吗，队长？我不知道该送您什么......我给您唱首歌吧。如果不好听，队长记得告诉我，我会立即停下。"
  },
  [85162181] = {
    id = 85162181,
    name = "新年......在我的记忆里，新年是要燃放烟火的。这里......有烟火吗？我想看一次，和队长一起。"
  },
  [85172181] = {
    id = 85172181,
    name = "这是我用荆棘编制的指环，队长可以收下吗？当然，我磨平了所有尖刺，不会让您觉得扎手。"
  },
  [85182181] = {
    id = 85182181,
    name = "外面的巡游很热闹，但大家扮演的怪物总让我觉得有些不安......不过如果队长能陪我一起去参加，就没那么可怕了。"
  },
  [85192181] = {
    id = 85192181,
    name = "以前......我会在这个时候给士兵们送热汤。他们的脸我已经记不清了，但那种温暖的感觉......还残留着一点点。"
  },
  [85012191] = {
    id = 85012191,
    name = "锵锵~莉莉安，前宫廷舞团候补，现役探险者！唔，这个开场怎么样？是不是很有舞台感？请多关照啦，队长~"
  },
  [85022191] = {
    id = 85022191,
    name = "啊，队长！今天也辛苦啦~要我给你跳支舞提提神吗？不收钱哦，因为是亲密同伴特供~"
  },
  [85032191] = {
    id = 85032191,
    name = "队长你知道吗，跳舞和战斗其实很像哦~节奏、步伐、呼吸，还有......在观众面前保持微笑。诶，你说敌人不算观众？那就当他们是来砸场的好了~"
  },
  [85032192] = {
    id = 85032192,
    name = "马戏团的大家要是知道我成了探险者，一定会吓一跳吧......以前那个在表演时经常出差错的小丫头，现在已经成为了能独当一面的探险者了。"
  },
  [85032193] = {
    id = 85032193,
    name = "这套衣服......会不会太正式了啊？我有点紧张，就像......就像第一次登台那样。队长，您觉得......好看吗？"
  },
  [85042191] = {
    id = 85042191,
    name = "力量又变强了！这样就能更好地保护大家了吧？队长，谢谢你。"
  },
  [85042192] = {
    id = 85042192,
    name = "以前练习舞蹈时，我曾在冰冷的地板上摔倒过无数次。现在实战练习也偶尔会摔倒，但这一次，有人会接住我了，嘿嘿~"
  },
  [85042193] = {
    id = 85042193,
    name = "我曾经以为，美好的东西都是虚幻的，迟早会碎掉。但现在......我想试试看，能不能让这份美好，一直延续下去。"
  },
  [85052191] = {
    id = 85052191,
    name = "幻境......是个很可怕的东西哦。它会让人看见最想要的东西，然后......再也不想醒来。"
  },
  [85052192] = {
    id = 85052192,
    name = "被封印的漫长时光里，我曾有过许多身份。但现在一切都已经过去了，我只想做队长专属的舞伴，直到永远。"
  },
  [85052193] = {
    id = 85052193,
    name = "那些被我变成傀儡的家伙......他们活在我编织的梦里，笑得很开心。这也让我偶尔会产生一种冲动，想要为自己也编织一个美梦。"
  },
  [85052194] = {
    id = 85052194,
    name = "马戏团的大家给了我第一个家，队长和探险队的大家给了我第二个。这一次，我不会让任何人毁掉它。绝对不会。"
  },
  [85052195] = {
    id = 85052195,
    name = "等我们攒够钱了，一起建个大房子吧！要有舞台，有花园，还要给每个人都留一间房。大家住在一起......就像真正的家人一样。"
  },
  [85062191] = {
    id = 85062191,
    name = "今天的表演要开始了哦~"
  },
  [85072191] = {id = 85072191, name = "嘿！"},
  [85072192] = {id = 85072192, name = "咻~"},
  [85072193] = {id = 85072193, name = "哈啊！"},
  [85082191] = {
    id = 85082191,
    name = "节奏乱了哦~"
  },
  [85082192] = {
    id = 85082192,
    name = "别乱动哦。"
  },
  [85092191] = {
    id = 85092191,
    name = "准备好，该谢幕啦！"
  },
  [85092192] = {
    id = 85092192,
    name = "开始最后的演出吧！"
  },
  [85092193] = {
    id = 85092193,
    name = "这场独舞，我只献给一个人。"
  },
  [85102191] = {id = 85102191, name = "呀！"},
  [85102192] = {id = 85102192, name = "唔啊。"},
  [85102193] = {id = 85102193, name = "呃。"},
  [85112191] = {
    id = 85112191,
    name = "还没到谢幕的时候......"
  },
  [85122191] = {
    id = 85122191,
    name = "舞台......要落幕了吗......"
  },
  [85132191] = {
    id = 85132191,
    name = "掌声呢？欢呼呢？诶，没有吗......那我自己给自己鼓个掌好啦~"
  },
  [85142191] = {
    id = 85142191,
    name = "都怪我，演出搞砸了......下次......下次我一定会准备得更充分！"
  },
  [85152191] = {
    id = 85152191,
    name = "生日快乐，队长！怎么知道的？呵呵，比起那种问题，快过来，我给你准备了一个超棒的表演，只为你一个人演出的那种~"
  },
  [85162191] = {
    id = 85162191,
    name = "以前在马戏团，新年是我们最忙的时候。虽然很累，但是大家在一起，就觉得很开心。今年和队长在一起，也很开心！"
  },
  [85219711] = {
    id = 85219711,
    name = "这是我做的点心，算不上完美，队长不会介意吧？——呵呵，我就知道队长会收下，因为家人会包容彼此的不完美。"
  },
  [85182191] = {
    id = 85182191,
    name = "这可是我最喜欢的节日之一！可以打扮成各种样子，还能正大光明地戏弄别人~今天一起去玩个尽兴吧，队长！"
  },
  [85192191] = {
    id = 85192191,
    name = "以前在马戏团，圣诞夜我们会围着篝火唱歌，老人会讲故事，孩子们会拆礼物......那些小玩意儿不值钱，但每个人的眼睛都亮亮的。"
  },
  [85012201] = {
    id = 85012201,
    name = "你并不在我的预测模型之中，但你却稳定地影响了结果变量，你知道这意味着什么吗，队长？"
  },
  [85022201] = {
    id = 85022201,
    name = "您今天的气场有些波动。遇到什么事了吗？如果需要建议......尽管开口。"
  },
  [85032201] = {
    id = 85032201,
    name = "我曾经以为，只要掌握了规律，就能改变一切。后来我发现......规律之外，还有人心。人心......是最难推演的变量。"
  },
  [85032202] = {
    id = 85032202,
    name = "人们害怕预言，不是因为它错误，而是因为预言有时候会让人们产生失去选择的错觉。"
  },
  [85032203] = {
    id = 85032203,
    name = "我曾推演过无数人的人生轨迹，却唯独没有想过，自己有一天也会穿上这样的衣服......命运，果然比星象更加难以预测。"
  },
  [85042201] = {
    id = 85042201,
    name = "力量......在提升。这次，我不会让这份力量失控。"
  },
  [85042202] = {
    id = 85042202,
    name = "强大的力量让我能看到更多未来，但有时候我会想，预测的事物太多，是否也让我对未来少了几分期待。"
  },
  [85042203] = {
    id = 85042203,
    name = "如果命运是一个既定的剧本，那我就要在上面写满批注。告诉所有人......这里，那里，都可以改。只要大家愿意去改。"
  },
  [85052201] = {
    id = 85052201,
    name = "燃烧的城镇，绝望的呼喊......当灾祸真正降临时，人们才想起我曾经的警告。但一切都为时已晚，我们已经失去了修改结果的机会。"
  },
  [85052202] = {
    id = 85052202,
    name = "那些嘲笑我的人，活在厚厚的城墙后面，把所有灾难的源头都推给一个“女巫”。而我......竟然还指望过他们能帮忙。"
  },
  [85052203] = {
    id = 85052203,
    name = "在漫长的时间里，我终于看清了一件事——命运从来不会偏爱谁，它只是按照自己的规律运转。只是，偶尔会有人打破规律，影响命运的轨迹。"
  },
  [85052204] = {
    id = 85052204,
    name = "我曾推演过自己的未来，但什么都看不到。直到某一天，队长突然出现在了我的预测中。当然，直到队长带我离开那个地方，我都在怀疑自己的预测是否出现了偏差。"
  },
  [85052205] = {
    id = 85052205,
    name = "我曾经想写一本关于星象的书，用来指引那些迷途的人，后来搁置了......现在，我想重新开始。这一次，我不只写星星，也写人，那些改变命运的人。"
  },
  [85062201] = {
    id = 85062201,
    name = "推演完毕，出发吧。"
  },
  [85072201] = {id = 85072201, name = "喝！"},
  [85072202] = {id = 85072202, name = "嘿呀。"},
  [85072203] = {id = 85072203, name = "哈啊。"},
  [85082201] = {
    id = 85082201,
    name = "偏差修正。"
  },
  [85082202] = {
    id = 85082202,
    name = "命运已定。"
  },
  [85092201] = {
    id = 85092201,
    name = "你们的结局，只有毁灭。"
  },
  [85092202] = {
    id = 85092202,
    name = "以命运之力，碾碎一切。"
  },
  [85092203] = {
    id = 85092203,
    name = "这一次，我会守护眼前的一切。"
  },
  [85102201] = {id = 85102201, name = "唔。"},
  [85102202] = {id = 85102202, name = "呃啊。"},
  [85102203] = {id = 85102203, name = "唔呃。"},
  [85112201] = {
    id = 85112201,
    name = "无谓的挣扎。"
  },
  [85122201] = {
    id = 85122201,
    name = "推演......又出现偏差了......"
  },
  [85132201] = {
    id = 85132201,
    name = "符合推演结果——今天无论做什么都会很顺利。"
  },
  [85142201] = {
    id = 85142201,
    name = "推演被干扰了......我们先撤，队长。"
  },
  [85152201] = {
    id = 85152201,
    name = "生日快乐队长。根据星象推演，您的命格很特别，所以在常规礼物之外，我给您做了一份星图，上面标注了您这一年的“幸运日”，希望队长能喜欢。"
  },
  [85162201] = {
    id = 85162201,
    name = "新的一年......星象会重新排列。有些人会相遇，有些人会分离，我推演不出所有细节，但有一件事我很确定......我和队长，还会在一起很久。"
  },
  [85220711] = {
    id = 85220711,
    name = "从被队长拯救的那一刻起，我欠您的，就很难报答了。请允许我永远追随在您的左右，我会为了您的意志，献上自己所有的一切。"
  },
  [85182201] = {
    id = 85182201,
    name = "外面玩闹的人群，让我想起被当成“女巫”驱逐追赶时的那段经历——介意？我并不介意。我只是好奇当年驱逐我的人中，有多少是出于恐惧，有多少是出于热闹。"
  },
  [85192201] = {
    id = 85192201,
    name = "长久以来我都是和书本、星图相伴，对这个代表分享和祝福的节日并没有太多感觉。但今年不同，队长和探险队的大家，让我感受到了这个节日的意义。"
  },
  [85012211] = {
    id = 85012211,
    name = "自由学派成员，阿芙佳朵。从今天开始，我们就是同行者了。呵呵~以后还请多多关照，队长。"
  },
  [85022211] = {
    id = 85022211,
    name = "状态看起来不错啊，队长。看来我们的行动计划你已经安排妥当了吧？我很期待接下来的行动。"
  },
  [85032211] = {
    id = 85032211,
    name = "以前我总觉得，探险一定是充满刺激和传奇的旅途......直到真正来深渊后才发现，大多数时间其实都在和危险、疲惫还有意外打交道。"
  },
  [85032212] = {
    id = 85032212,
    name = "自由学派里聚集了很多有趣的人。有人执着于研究古文明，有人热衷寻找遗迹秘宝，还有人只是单纯享受探险本身......和他们相处，总会让人觉得很自在。"
  },
  [85042211] = {
    id = 85042211,
    name = "力量并非什么值得炫耀的存在，而是在关键时刻，守护同伴的倚仗。"
  },
  [85042212] = {
    id = 85042212,
    name = "感觉实力又提升了不少，看来最近的修行没有白费。以后面对危险状况时，我也能更加从容一些了。"
  },
  [85042213] = {
    id = 85042213,
    name = "深渊里一定存在那些令人惊叹的景象，正因如此，我才会一直不断前进，想亲眼去见证它们。"
  },
  [85052211] = {
    id = 85052211,
    name = "比起孤身一人的强大，我更相信能够彼此托付后背的同伴。只有这样，才能走得更远。"
  },
  [85052212] = {
    id = 85052212,
    name = "我的导师曾告诉我，探险者真正重要的能力，并不是战斗，而是在绝境中依然愿意继续向前的勇气。"
  },
  [85052213] = {
    id = 85052213,
    name = "我原本以为，自己已经足够适应深渊了。结果真正开始深入探险后才发现，这地方总能轻易超出人的预料。"
  },
  [85052214] = {
    id = 85052214,
    name = "许多人喜欢计较过去的“失误”，在我看来那毫无意义，与其花时间懊恼，不如努力让自己做的更好。"
  },
  [85052215] = {
    id = 85052215,
    name = "最近我偶尔会产生一种感觉——或许我一直寻找的“特别经历”，其实已经在不知不觉间开始了。"
  },
  [85062211] = {
    id = 85062211,
    name = "出发吧，希望这次也能有所收获。"
  },
  [85072211] = {id = 85072211, name = "喝。"},
  [85072212] = {id = 85072212, name = "嘿咿。"},
  [85072213] = {id = 85072213, name = "呀啊。"},
  [85082211] = {
    id = 85082211,
    name = "看穿你了。"
  },
  [85082212] = {
    id = 85082212,
    name = "到此为止。"
  },
  [85092211] = {
    id = 85092211,
    name = "这一击，赌上我的荣耀！"
  },
  [85092212] = {
    id = 85092212,
    name = "胜负已定，放弃挣扎吧！"
  },
  [85102211] = {id = 85102211, name = "唔。"},
  [85102212] = {id = 85102212, name = "呃啊。"},
  [85102213] = {id = 85102213, name = "呜呃。"},
  [85112211] = {
    id = 85112211,
    name = "我、还能继续。"
  },
  [85122211] = {
    id = 85122211,
    name = "只能到这里了吗......"
  },
  [85132211] = {
    id = 85132211,
    name = "大家都平安无事，就是最好的结果了，至于其他收获......呵呵，就看运气吧。"
  },
  [85142211] = {
    id = 85142211,
    name = "不要恋战，立刻撤退。只要人没事，就还有重新来过的机会。"
  },
  [85152211] = {
    id = 85152211,
    name = "今天可是重要的日子，当然要热热闹闹地庆祝才行。我已经提前准备好食物和饮料了，今天大家都会陪您一起度过。"
  },
  [85162211] = {
    id = 85162211,
    name = "新的一年啊......总觉得会遇见许多新的风景和故事。和队长在一起的时间长了，对未来的期待已经在不知不觉中变得更多了。"
  },
  [85172211] = {
    id = 85172211,
    name = "节日快乐，队长。我不太擅长准备有“惊喜感”的礼物，所以想了很久，最终也只是做了些实用的小物件......虽然不够浪漫，但希望您会喜欢。"
  },
  [85182211] = {
    id = 85182211,
    name = "刚才在圈落看见许多人穿着奇特的服饰游行，好热闹啊。我们也一起去逛逛吧，队长！偶尔放松一下，对修行也有好处。"
  },
  [85192211] = {
    id = 85192211,
    name = "自由学派有个传统，同伴们会在这个节日互相寄送礼物，所以我每年都会准备很多份。对了，这份是给队长的，请务必收下。"
  },
  [85012221] = {
    id = 85012221,
    name = "好久不见——不对，应该说是“又见面了”才对。这段时间我可没闲着，变强了不少呢，队长可要好好看着！"
  },
  [85022221] = {
    id = 85022221,
    name = "啊，你来了。我可不是在等你，只是刚好......准备出发而已。走吧走吧，别磨蹭了。"
  },
  [85032221] = {
    id = 85032221,
    name = "以前我总想着“绝对不能输”，但现在我发现，偶尔输一下似乎也不是什么坏事。在变强的路上一直有人陪伴，是一件非常幸福的事。"
  },
  [85032222] = {
    id = 85032222,
    name = "队长，你说一个人长大了，是不是就会变得......更坦诚一点？比如表达自己心里真正的想法......算了算了，队长当我没问，你什么都没听到！"
  },
  [85042221] = {
    id = 85042221,
    name = "力量又提升了？哼，这不是理所当然的吗，我可是每天都在努力啊。"
  },
  [85042222] = {
    id = 85042222,
    name = "我感觉自己的状态前所未有的好！这一次，不管遇到什么对手，我都会堂堂正正地赢给你看！"
  },
  [85042223] = {
    id = 85042223,
    name = "曾经的我只在意输赢，但现在我明白了，比起输赢，还有更多重要的存在值得我去追寻。"
  },
  [85052221] = {
    id = 85052221,
    name = "我已经不是当初那个只会嚷嚷的小丫头了。现在的我......有足够的能力，应对一切挑战！"
  },
  [85052222] = {
    id = 85052222,
    name = "别误会，我可不是因为和西比尔重逢才高兴成这样。我只是觉得......终于能认真分个胜负了而已！"
  },
  [85052223] = {
    id = 85052223,
    name = "有时候我会想，如果当初没有错过那场告别，现在的一切会不会变得不一样......不过如果没有和西比尔分开，也许我就没机会遇到队长和大家了。"
  },
  [85052224] = {
    id = 85052224,
    name = "实力变强了，宿敌重逢了，接下来会发生什么呢？一想到这些我就觉得兴奋，对未来的旅程充满了期待。"
  },
  [85052225] = {
    id = 85052225,
    name = "这次我可不会再被轻易甩开了，不管是深渊、遗迹，还是更危险的地方，我都会紧紧跟上。当然，队长也要和我一起！"
  },
  [85062221] = {
    id = 85062221,
    name = "跟上我，别掉队了。"
  },
  [85072221] = {id = 85072221, name = "哈！"},
  [85072222] = {id = 85072222, name = "嘿呀。"},
  [85072223] = {id = 85072223, name = "喝。"},
  [85082221] = {
    id = 85082221,
    name = "接招吧！"
  },
  [85082222] = {
    id = 85082222,
    name = "破绽太明显了！"
  },
  [85092221] = {
    id = 85092221,
    name = "我，不会再输给任何人！"
  },
  [85092222] = {
    id = 85092222,
    name = "见识一下我真正的实力吧！"
  },
  [85102221] = {id = 85102221, name = "呜啊！"},
  [85102222] = {id = 85102222, name = "呃。"},
  [85102223] = {id = 85102223, name = "唔。"},
  [85112221] = {
    id = 85112221,
    name = "还、还没结束呢！"
  },
  [85122221] = {
    id = 85122221,
    name = "我......还能继续......"
  },
  [85132221] = {
    id = 85132221,
    name = "怎么样？我现在的实力算得上最顶尖的探险者了吧？！"
  },
  [85142221] = {
    id = 85142221,
    name = "再来一次，我绝对不会再输！"
  },
  [85152221] = {
    id = 85152221,
    name = "生日快乐，队长！今天什么都别想，跟我走就对了！我已经把一整天的安排都准备好了，绝对会让你过得比去年更开心！"
  },
  [85162221] = {
    id = 85162221,
    name = "以前每年新年，我都会许同一个愿望，今年换一个吧。希望......重要的人，都在身边。"
  },
  [85172221] = {
    id = 85172221,
    name = "队长，这是我做的点心......别、别用那种眼神看我！只是顺手做的，顺便给你一份而已！不过既然准备了，你可不准浪费！"
  },
  [85182221] = {
    id = 85182221,
    name = "庆典巡游是小孩子才会做的事，我现在已经是成熟的淑女——探险队内的其他人也会去？真、真没办法，那我也去看看吧。"
  },
  [85192221] = {
    id = 85192221,
    name = "我以前收到过一份礼物，一直没能回礼......当然，我有准备好回礼，只是出于种种原因，一直没能送出去。这一次，我希望能将回礼送出去。"
  },
  [85012231] = {
    id = 85012231,
    name = "守夜人罗蕾娜——不，前守夜人。非常感谢您的邀请，今后我会以探险者的身份与您同行。"
  },
  [85022231] = {
    id = 85022231,
    name = "您来了，昨晚休息得还好吗？我刚泡好茶，如果不着急出发的话......可以先坐一会儿。"
  },
  [85032231] = {
    id = 85032231,
    name = "人们总习惯将亡灵视作灾厄，可很多时候，它们只是一些无法离开的可怜灵魂罢了。真正可怕的......反而是活着的人。"
  },
  [85032232] = {
    id = 85032232,
    name = "我小时候曾以为，只要努力斩杀亡灵，就能守护一方安宁。后来才发现，如果无法根除人们心中的恶念，无论如何努力，都只是徒劳。"
  },
  [85042231] = {
    id = 85042231,
    name = "力量越强，能感觉到的异常存在就越多。如果能利用好这点，对我们的探险应该会有不少帮助。"
  },
  [85042232] = {
    id = 85042232,
    name = "守夜人的剑，本该只用于斩杀灾厄。可如果连悲伤与执念都要一并斩断......那样的正义，未免太残酷了。"
  },
  [85042233] = {
    id = 85042233,
    name = "若非必要，我不会再对无辜的亡灵出手。至于那些真正危险的......我也绝不会犹豫。"
  },
  [85052231] = {
    id = 85052231,
    name = "守夜人的训练很严苛，剑术、魔法、精神抗性......稍有失误，就可能死于意外。所以我们从小便被教导，绝不能对亡灵产生怜悯。"
  },
  [85052232] = {
    id = 85052232,
    name = "家族里的长辈曾认为，我会成为最优秀的守夜人，结果到头来......偏偏是我最先开始质疑那些“理所当然”的规则。"
  },
  [85052233] = {
    id = 85052233,
    name = "以前我从未质疑过自己的职责，每次任务都全力以赴。直到某次，我看见一个亡灵坐在废墟前，安静等着再也不会回来的人......"
  },
  [85052234] = {
    id = 85052234,
    name = "虽然背离了守夜人的使命，但我在离家时仍然带走了这把象征守夜人的剑。或许我还在期望着，自己所做的一切，有一天能得到家族的认可。"
  },
  [85052235] = {
    id = 85052235,
    name = "自从跟随队长一起探险之后，我见识到了许多全新的事物，也许有一天，我能在守夜人的职责和自己的信念之间找到新的平衡。"
  },
  [85062231] = {
    id = 85062231,
    name = "我会负责警戒周围的异常。"
  },
  [85072231] = {id = 85072231, name = "喝！"},
  [85072232] = {id = 85072232, name = "呀。"},
  [85072233] = {id = 85072233, name = "嘿咿。"},
  [85082231] = {
    id = 85082231,
    name = "交给我。"
  },
  [85082232] = {
    id = 85082232,
    name = "安息吧。"
  },
  [85092231] = {
    id = 85092231,
    name = "归于长夜吧！"
  },
  [85092232] = {
    id = 85092232,
    name = "由我来画上句点。"
  },
  [85102231] = {id = 85102231, name = "唔。"},
  [85102232] = {id = 85102232, name = "呃啊。"},
  [85102233] = {id = 85102233, name = "呃。"},
  [85112231] = {
    id = 85112231,
    name = "一点小伤，无碍。"
  },
  [85122231] = {
    id = 85122231,
    name = "终究......没能做到......"
  },
  [85132231] = {
    id = 85132231,
    name = "所有威胁都已清除，队长休息一下吧，我会完成收尾工作。"
  },
  [85142231] = {
    id = 85142231,
    name = "对手比执念深重的亡灵更麻烦......我们先撤，得重新制定应对策略。"
  },
  [85152231] = {
    id = 85152231,
    name = "生日快乐，队长。这是我亲手做的夜灯，睡觉时放在身边可以驱散噩梦，能请您收下吗？这个特别的日子，我想以自己擅长的方式为您送上祝福。"
  },
  [85162231] = {
    id = 85162231,
    name = "守夜人的工作里，总会见证许多离别......所以能像这样平静迎来新年，对我而言已经是一件值得庆幸的事了。"
  },
  [85172231] = {
    id = 85172231,
    name = "这是送给您的......别担心，不是什么危险物品，只是一枚能够安神的小护符。今天街上似乎很热闹，我想......我也应该准备些什么才对。"
  },
  [85182231] = {
    id = 85182231,
    name = "今天外面游荡的“亡灵”似乎格外多......不过仔细想想，如果真正的亡灵也能像这样热闹地融入人群，或许也不是什么坏事。"
  },
  [85192231] = {
    id = 85192231,
    name = "队长知道吗，在今天这种特别的日子里，亡灵们也会变得很安静。只需要一点特殊手段，便能与他们交流，聆听他们的故事。队长想试试吗？"
  },
  [85012241] = {
    id = 85012241,
    name = "我这副打扮还合适吗，队长？呵呵，无论扮演怎样的角色，身份如何变更，我都永远会是队长的同伴。"
  },
  [85022241] = {
    id = 85022241,
    name = "外面的风有些凉，我准备了热饮和安神的香料。不管何时，队长都要记得好好放松才行。"
  },
  [85032241] = {
    id = 85032241,
    name = "那些徘徊不去的存在，其实并没有恶意，它们只是还有些执念，或者忘记了该去哪里......所以，我想趁节日这段时间，做些力所能及的事，让它们安心一点。"
  },
  [85032242] = {
    id = 85032242,
    name = "队长知道吗？据说在这样的夜晚，只要点亮灯火，就能为迷路的人照亮归途。我们一起......多点亮几盏吧。"
  },
  [85042241] = {
    id = 85042241,
    name = "我能感觉到，那些躁动不安的气息正在慢慢平静下来。看来我的力量，确实帮上忙了。"
  },
  [85042242] = {
    id = 85042242,
    name = "呵呵~大家总担心我会不会害怕，其实......只要有人陪在身边，再黑的夜晚也没有那么可怕。"
  },
  [85042243] = {
    id = 85042243,
    name = "如果有无法安息的灵魂，就让我替它们点亮回去的路吧。至少，不该让任何人孤独地停留在黑暗里。"
  },
  [85052241] = {
    id = 85052241,
    name = "有时候我会觉得，那些游荡的身影和探险者很像。明明已经遍体鳞伤，却依旧执着地向前。"
  },
  [85052242] = {
    id = 85052242,
    name = "小时候母亲曾告诉我，真正的温柔并不是驱逐恐惧，而是在别人害怕、无助的时候，愿意陪着对方一起走下去。"
  },
  [85052243] = {
    id = 85052243,
    name = "每当夜色降临，我都会想起小时候听过的故事。那时我总以为，故事里的幽魂会伤害人。现在才发现，它们很多时候只是太寂寞了。"
  },
  [85052244] = {
    id = 85052244,
    name = "吓！呵呵~队长刚刚是不是被我吓到了？放心吧，所有不稳定的存在我都已经处理好了。接下来，一起享受庆典吧。"
  },
  [85052245] = {
    id = 85052245,
    name = "我很开心能和大家一起度过这样的庆典。热闹的灯火、可靠的队长，安心微笑的人们......这一切都是那么美好，让我觉得自己地行动有了更多意义。"
  },
  [85062241] = {
    id = 85062241,
    name = "大家别走散了哦。"
  },
  [85072241] = {id = 85072241, name = "嘿咿。"},
  [85072242] = {id = 85072242, name = "哈啊~"},
  [85072243] = {id = 85072243, name = "咿呀。"},
  [85082241] = {
    id = 85082241,
    name = "安静下来。"
  },
  [85082242] = {
    id = 85082242,
    name = "交给我吧。"
  },
  [85092241] = {
    id = 85092241,
    name = "今夜的灯火，会照亮归途。"
  },
  [85092242] = {
    id = 85092242,
    name = "由我来送你最后一程。"
  },
  [85102241] = {id = 85102241, name = "唔。"},
  [85102242] = {id = 85102242, name = "呀啊。"},
  [85102243] = {id = 85102243, name = "呃。"},
  [85112241] = {
    id = 85112241,
    name = "不能在这里停下。"
  },
  [85122241] = {
    id = 85122241,
    name = "灯火......要熄灭了......"
  },
  [85132241] = {
    id = 85132241,
    name = "所有威胁都已消除，大家可以尽情享受节日了。"
  },
  [85142241] = {
    id = 85142241,
    name = "大家都没事吧？我们先撤，现在不是勉强的时候。"
  },
  [85152241] = {
    id = 85152241,
    name = "今天是属于队长的重要日子呢。呵呵~我准备了甜点、热茶，还有象征祝福的烛火。希望今后的每一天，都能有温暖与幸运陪伴着您。"
  },
  [85162241] = {
    id = 85162241,
    name = "队长，新的一年也请多多关照，无论未来会遇到什么，我都会陪在队长身边，一起去见证。"
  },
  [85172241] = {
    id = 85172241,
    name = "这是我亲手做的小点心，队长试试看吧。味道或许不算特别优秀，但想要传达的心意我可是认真放进去了。"
  },
  [85182241] = {
    id = 85182241,
    name = "今晚街道比平时热闹很多呢。大家脸上的笑容，让这个本该有些寒冷的夜晚也变得温暖起来了。"
  },
  [85192241] = {
    id = 85192241,
    name = "雪花落下的时候，四周总会变得格外安静。一起在窗边坐一会儿吧，队长？像这样看着灯火、慢慢聊天，让我觉得无比温暖惬意。"
  },
  [85012251] = {id = 85012251, name = "..."},
  [85012271] = {
    id = 85012271,
    name = "探险者菲欧！只要报酬合适，我什么委托都接！不过先说好，我最近运气有点背，过程中可能会出点小状况......但不用担心，坏运气攒够了，好运自然就来了！"
  },
  [85022271] = {
    id = 85022271,
    name = "队长！你来啦！正好正好，我刚才还在想今天要干什么呢。对了，你吃过东西了吗？没吃的话先吃一点，空着肚子可不行。"
  },
  [85032271] = {
    id = 85032271,
    name = "我跟你说，我这个人吧，平时运气确实不太好。走路会摔跤，喝水会呛到，连晒个衣服都能突然下雨。不过这有什么好沮丧的？霉运也是有限的嘛，倒得越多，离转运就越近！"
  },
  [85032272] = {
    id = 85032272,
    name = "我以前一个人接委托，一个人赶路，一个人处理那些乱七八糟的小麻烦。虽然也挺习惯的，但现在有队长和大家在身边以后，我发现有人一起分享倒霉事......好像连霉运都没那么讨厌了。"
  },
  [85062271] = {
    id = 85062271,
    name = "幸运女神保佑，幸运女神保佑！"
  },
  [85072271] = {id = 85072271, name = "呀咿。"},
  [85072272] = {id = 85072272, name = "嘿。"},
  [85072273] = {id = 85072273, name = "呵哈。"},
  [85082271] = {
    id = 85082271,
    name = "看这里！"
  },
  [85082272] = {
    id = 85082272,
    name = "这次不会偏！"
  },
  [85092271] = {
    id = 85092271,
    name = "庇佑我吧，幸运女神！"
  },
  [85092272] = {
    id = 85092272,
    name = "贯穿吧，幸运之箭！"
  },
  [85102271] = {id = 85102271, name = "呜哇！"},
  [85102272] = {id = 85102272, name = "呃啊。"},
  [85102273] = {id = 85102273, name = "呀！"},
  [85112271] = {
    id = 85112271,
    name = "加油，霉运快结束了。"
  },
  [85122271] = {
    id = 85122271,
    name = "幸运女神......休假了吗......"
  },
  [85132271] = {
    id = 85132271,
    name = "我就说嘛！倒霉归倒霉，最后肯定还是会转运的！"
  },
  [85142271] = {
    id = 85142271,
    name = "哎呀，今天的运气用光啦......没关系！下次肯定轮到我们走运！"
  },
  [85012281] = {
    id = 85012281,
    name = "刚才我还在想，接下来该往哪个方向走呢，结果就遇见队长了。看来后续的安排已经决定好了。怎样的安排？呵呵，当然是队长去哪我就去哪，不管做什么我都会奉陪！"
  },
  [85022281] = {
    id = 85022281,
    name = "队长，今天的行程安排好了吗？咱们可别只顾着赶路噢，真正值得看的东西，往往都藏在那些没人注意的地方。"
  },
  [85032281] = {
    id = 85032281,
    name = "队长，你有没有发现？深渊里那些拼命寻找宝物的人，最后谈论的还是宝物；可那些真正喜欢探险的人，回去以后往往会先说自己遇到了什么。呵呵，这两种人看到的，可是完全不同的世界。"
  },
  [85032282] = {
    id = 85032282,
    name = "我不喜欢被规则束缚，也不喜欢为了某个目标把自己困住。不过自由从来都不是想做什么就做什么，而是知道自己为什么出发，也愿意承担自己选择的结果。这一点，我还是很清楚的。"
  },
  [85062281] = {
    id = 85062281,
    name = "麻烦的事都交给我吧。"
  },
  [85072281] = {id = 85072281, name = "嘿！"},
  [85072282] = {id = 85072282, name = "呵！"},
  [85072283] = {id = 85072283, name = "哈！"},
  [85082281] = {
    id = 85082281,
    name = "别挡路。"
  },
  [85082282] = {
    id = 85082282,
    name = "到此为止。"
  },
  [85092281] = {
    id = 85092281,
    name = "我会给你们一个痛快。"
  },
  [85092282] = {
    id = 85092282,
    name = "无谓的挣扎，受死吧！"
  },
  [85102281] = {id = 85102281, name = "呃。"},
  [85102282] = {id = 85102282, name = "唔。"},
  [85102283] = {id = 85102283, name = "呃啊。"},
  [85112281] = {
    id = 85112281,
    name = "看来......得认真一点了。"
  },
  [85122281] = {
    id = 85122281,
    name = "这次......还没走到终点......"
  },
  [85132281] = {
    id = 85132281,
    name = "轻松搞定！今天的旅途，又多了一段有趣的见闻。"
  },
  [85142281] = {
    id = 85142281,
    name = "这次算我们输了。不过没关系，胜败是常有的事，别被影响了心情。"
  },
  [85012291] = {
    id = 85012291,
    name = "探险者吉娜，代号「吉光」，接下来就一起行动吧！放心，我的运气一向不错。要是真的碰上什么倒霉事......那就让我先替大家挡下来好了。"
  },
  [85022291] = {
    id = 85022291,
    name = "队长，来得正好！我刚准备出门走走呢。今天要是没有特别安排，不如随便挑个方向出发？说不定拐个弯，就能碰上什么有意思的东西。"
  },
  [85032291] = {
    id = 85032291,
    name = "队长，你知道吗？我以前以为所谓的幸运，就是自己总能遇上好事。现在我觉得不是。能在漫长的旅途上遇见愿意同行的人，本身就无比幸运了。"
  },
  [85032292] = {
    id = 85032292,
    name = "小时候跟着家里到处跑，经常能听见旅人讲些稀奇古怪的冒险故事。那时候我最喜欢的，就是那些最后总能逢凶化吉的人。现在想想......大概从那时候起，我就决定自己也要成为那样的人了。"
  },
  [85062291] = {
    id = 85062291,
    name = "就让我给大家探路吧。"
  },
  [85072291] = {id = 85072291, name = "喝！"},
  [85072292] = {id = 85072292, name = "嘿！"},
  [85072293] = {id = 85072293, name = "哈啊！"},
  [85082291] = {
    id = 85082291,
    name = "就是现在！"
  },
  [85082292] = {
    id = 85082292,
    name = "交给我。"
  },
  [85092291] = {
    id = 85092291,
    name = "我会守护所有人！"
  },
  [85092292] = {
    id = 85092292,
    name = "厄运退散！"
  },
  [85102291] = {id = 85102291, name = "唔。"},
  [85102292] = {id = 85102292, name = "呃。"},
  [85102293] = {id = 85102293, name = "呜啊。"},
  [85112291] = {
    id = 85112291,
    name = "还没到认输的时候......"
  },
  [85122291] = {
    id = 85122291,
    name = "看来......这次运气......差了点......"
  },
  [85132291] = {
    id = 85132291,
    name = "看来今天的运气还不错嘛~不过比起运气，大家的默契配合才是胜利的关键！"
  },
  [85142291] = {
    id = 85142291,
    name = "啧......这次判断错了。先撤，等找到机会，我们再回来。"
  },
  [85012301] = {
    id = 85012301,
    name = "你好，我叫露西亚。有人说，向夜空许下的愿望，总有一天会得到回应......不过，我更愿意相信，愿望真正的意义，是让我们愿意朝着它继续走下去。"
  },
  [85022301] = {
    id = 85022301,
    name = "今天也辛苦了，队长，坐下来歇一会儿吧。无论前方还有多少路要走，也不用急着出发。对远行者而言，调整好自身状态才是重要的准备工作。"
  },
  [85032301] = {
    id = 85032301,
    name = "我很喜欢夜晚。因为天一黑，人们反而会点亮更多灯。明明只是微弱的光聚在一起，却能让原本看不清的道路重新出现......你不觉得，这很像我们吗？"
  },
  [85032302] = {
    id = 85032302,
    name = "如果一定要问我，愿望究竟能不能实现......我想答案应该是“不能只等着它实现”。星星可以替我们照亮夜空，却不能替我们走完脚下的路。所以啊，许愿之后，也要记得向前走。"
  },
  [85062301] = {
    id = 85062301,
    name = "一起出发吧。"
  },
  [85072301] = {id = 85072301, name = "嘿咿。"},
  [85072302] = {id = 85072302, name = "咿呀。"},
  [85072303] = {id = 85072303, name = "哈啊。"},
  [85082301] = {id = 85082301, name = "去吧。"},
  [85082302] = {
    id = 85082302,
    name = "交给我。"
  },
  [85092301] = {
    id = 85092301,
    name = "以愿望之火，照亮前路。"
  },
  [85092302] = {
    id = 85092302,
    name = "请见证我的意志！"
  },
  [85102301] = {id = 85102301, name = "唔。"},
  [85102302] = {id = 85102302, name = "呃啊。"},
  [85102303] = {id = 85102303, name = "呜呃。"},
  [85112301] = {
    id = 85112301,
    name = "嗯......没关系。"
  },
  [85122301] = {
    id = 85122301,
    name = "这次的旅途......比想象中更远呢......"
  },
  [85132301] = {
    id = 85132301,
    name = "顺利结束~看来队长希望“旅途顺利”的愿望已经开始实现了。"
  },
  [85142301] = {
    id = 85142301,
    name = "队长，我们先撤吧。这次的失利，会让我们下一次走得更远。"
  },
  [85012311] = {
    id = 85012311,
    name = "看起来只是换了身衣服，可真正扮演一个角色以后，才发现还有好多事情要做呢。既然大家都期待着小莎的表演，那小莎就稍微认真一点......当然，只是稍微哦！"
  },
  [85022311] = {
    id = 85022311,
    name = "早上好呀，队长。今天的任务不是去冒险，而是陪小莎完成童话里的故事哦。什么？你问有没有危险？当然有啦......所以才更需要聪明的小莎嘛～"
  },
  [85032311] = {
    id = 85032311,
    name = "如果真的遇到大灰狼，小莎才不会傻乎乎地跟它聊天呢。先装作什么都不知道，再想办法套出它的目的......嘿嘿，童话故事里可没说小红帽不能聪明一点吧？"
  },
  [85032312] = {
    id = 85032312,
    name = "以前的小莎遇到麻烦，总想着能躲就躲，能骗过去就骗过去。不过啊，如果真的有人在森林里等着自己，就算很麻烦......大概也会想回去看一眼吧。"
  },
  [85032313] = {
    id = 85032313,
    name = "武技和魔法......确实有不少人比小莎厉害。可是要论角色扮演，没人是小莎的对手！无论是可爱、温柔、委屈、倔强、凶狠......统统不在话下~不管队长喜欢什么类型，小莎都可以为你扮演！"
  },
  [85062311] = {
    id = 85062311,
    name = "又要出发了吗？好吧好吧，小红帽今天也会乖乖跟上的。"
  },
  [85072311] = {id = 85072311, name = "嘿！"},
  [85072312] = {id = 85072312, name = "哈啊！"},
  [85072313] = {id = 85072313, name = "咿呀！"},
  [85082311] = {
    id = 85082311,
    name = "嘘......别出声。"
  },
  [85082312] = {
    id = 85082312,
    name = "上当了吧？"
  },
  [85092311] = {
    id = 85092311,
    name = "小看我，可是会吃亏噢~"
  },
  [85092312] = {
    id = 85092312,
    name = "别想逃过小莎的眼睛！"
  },
  [85092313] = {
    id = 85092313,
    name = "好好享受小莎准备的“惊喜”吧！"
  },
  [85102311] = {id = 85102311, name = "哇！"},
  [85102312] = {id = 85102312, name = "呃啊。"},
  [85102313] = {id = 85102313, name = "呜哇。"},
  [85112311] = {
    id = 85112311,
    name = "哇啊，好凶......看来得认真了！"
  },
  [85122311] = {
    id = 85122311,
    name = "队长......小莎先休息一下......"
  },
  [85132311] = {
    id = 85132311,
    name = "森林里的大灰狼，可要小心小红帽的篮子哦——里面装的，可不只是点心！"
  },
  [85142311] = {
    id = 85142311,
    name = "怎么会这样......童话故事里明明不是这么写的！快跑快跑，今天的小红帽先认输了！"
  },
  [85012321] = {
    id = 85012321,
    name = "原来扮演一个与自己完全不同的角色，并没有想象中容易。至少我现在明白了，真正的‘恐惧’，和外表凶恶与否，没有直接关系。"
  },
  [85022321] = {
    id = 85022321,
    name = "今天还要继续扮演么？我知道了。只是，如果那个“小红帽”又擅自跑进森林深处，还请队长及时告诉我。"
  },
  [85032321] = {
    id = 85032321,
    name = "故事里的大灰狼应该让人感到恐惧，我按照这种感觉尝试过几次，但似乎没有什么效果。尼莉莎看到我以后，甚至一直在笑......究竟是哪里出了问题？"
  },
  [85032322] = {
    id = 85032322,
    name = "如果我是故事里的大灰狼，大概不会按照原本的结局行动。毕竟......让一个明知道危险，却还是愿意相信别人的人受伤，并没有任何意义。"
  },
  [85062321] = {
    id = 85062321,
    name = "既然我扮演了狼，就由我走在最前面。"
  },
  [85072321] = {id = 85072321, name = "喝！"},
  [85072322] = {id = 85072322, name = "哈！"},
