  [80231264] = {
    id = 80231264,
    name = "你们破除幻境后，与莉莉安交涉失败，在每个人都被莉莉安做成傀儡后，你识破了真假幻境，找到了编织梦境的莉莉安，唤醒队友。四人共同战胜莉莉安，但菲尼斯也受了伤，莉莉安清醒后，也与莎尔拉一样签订契约，答应放你们上楼，期待你们闯关成功。"
  },
  [80231265] = {
    id = 80231265,
    name = "你们破除幻境后，与莉莉安交涉失败，在每个人都被莉莉安做成傀儡后，你识破了真假幻境，找到了编织梦境的莉莉安，唤醒队友。四人共同战胜莉莉安，但菲尼斯也受了伤，莉莉安清醒后，也与莎尔拉一样签订契约，答应放你们上楼，期待你们闯关成功。"
  },
  [80231266] = {
    id = 80231266,
    name = "到了第三层休息区，熟人再次出现，看出菲尼斯隐瞒严重的伤势。休整后你们到了第四层，发现是个图书馆，书堆里坐了个病恹恹的女人玛琳娜，玛琳娜问问题，你回答后，玛琳娜很满意，接着问下一个，玛琳娜不满意，杀了三人。菲尼斯独自上四层，与玛琳娜交涉后，在死前拿出了残缺的花，拔下了一瓣，说重新开始吧。"
  },
  [80231267] = {
    id = 80231267,
    name = "到了第三层休息区，熟人再次出现，看出菲尼斯隐瞒严重的伤势。休整后你们到了第四层，发现是个图书馆，书堆里坐了个病恹恹的女人玛琳娜，玛琳娜问问题，你回答后，玛琳娜很满意，接着问下一个，玛琳娜不满意，杀了三人。菲尼斯独自上四层，与玛琳娜交涉后，在死前拿出了残缺的花，拔下了一瓣，说重新开始吧。"
  },
  [80231268] = {
    id = 80231268,
    name = "众人再次回到了塔底，这一次安妮斯和蒂娜已经记不得菲尼斯了，但你还记得，仅知道名字和身份而已，可即便失去了记忆，那份相处时的默契却依然存在......"
  },
  [80231269] = {
    id = 80231269,
    name = "众人再次回到了塔底，这一次安妮斯和蒂娜已经记不得菲尼斯了，但你还记得，仅知道名字和身份而已，可即便失去了记忆，那份相处时的默契却依然存在......"
  },
  [80231270] = {
    id = 80231270,
    name = "进入第二层后，莎尔拉见到了你们，看起来并不认识你们了，但莎尔拉能感应到和你签了契约，在与莎尔拉聊天后，你们去往第二层休息区。竟然遇到了鬼王，艾瑟儿，以及枭，进入第三层后，莉莉安本来孤独的表情在见到你们来后很开心，希望你们能评价她的舞蹈。"
  },
  [80231271] = {
    id = 80231271,
    name = "进入第二层后，莎尔拉见到了你们，看起来并不认识你们了，但莎尔拉能感应到和你签了契约，在与莎尔拉聊天后，你们去往第二层休息区。竟然遇到了鬼王，艾瑟儿，以及枭，进入第三层后，莉莉安本来孤独的表情在见到你们来后很开心，希望你们能评价她的舞蹈。"
  },
  [80231272] = {
    id = 80231272,
    name = "你们在第三层的休息区遇到了熟人，这些人记不得菲尼斯了，在交流和告别之后，你们进入第四层，咕咕也在第四层等你们，再次面对提问的玛琳，玛琳的问题和菲尼斯提出的一样，这让你非常吃惊，你谨慎应对，猜出了玛琳的身世和经历，解答了玛琳的问题，玛琳的信念崩溃，你们趁此机会找到弱点制服了玛琳，玛琳苏醒，恢复了记忆，并告诉你们，没有人可以离开塔楼，复苏之花会将你们一直囚禁在这里。"
  },
  [80231273] = {
    id = 80231273,
    name = "你们在第三层的休息区遇到了熟人，这些人记不得菲尼斯了，在交流和告别之后，你们进入第四层，咕咕也在第四层等你们，再次面对提问的玛琳，玛琳的问题和菲尼斯提出的一样，这让你非常吃惊，你谨慎应对，猜出了玛琳的身世和经历，解答了玛琳的问题，玛琳的信念崩溃，你们趁此机会找到弱点制服了玛琳，玛琳苏醒，恢复了记忆，并告诉你们，没有人可以离开塔楼，复苏之花会将你们一直囚禁在这里。"
  },
  [80231274] = {
    id = 80231274,
    name = "玛琳苏醒，恢复了记忆，并告诉你们，没有人可以离开塔楼，复苏之花会将你们一直囚禁在这里。到达第四层后，你们一个人也没再见到，这时，你向菲尼斯问出了自己的疑虑。"
  },
  [80231275] = {
    id = 80231275,
    name = "玛琳苏醒，恢复了记忆，并告诉你们，没有人可以离开塔楼，复苏之花会将你们一直囚禁在这里。到达第四层后，你们一个人也没再见到，这时，你向菲尼斯问出了自己的疑虑。"
  },
  [80231276] = {
    id = 80231276,
    name = "你和安妮斯、蒂娜在塔底醒来，决定进入魔域之塔。你们一路畅通，上了第五层，在第五层见到了成为守关人的菲尼斯。"
  },
  [80231277] = {
    id = 80231277,
    name = "你梦见一个自称杀手的小男孩和自己在道别，醒后却什么都忘记了。你去看望昏睡的尼莉莎，大家都在讨论深渊第三层开启的消息，这时有人上门来访......"
  },
  [80231278] = {
    id = 80231278,
    name = "默尔曼深夜突然拜访，在交给你莎尔拉几人的身份认证后，又和你简单聊了一下近况。面对仍在沉睡、无法醒来的尼莉莎，你犹豫是否应该前往深渊第三层看看。"
  },
  [80231279] = {
    id = 80231279,
    name = "默尔曼深夜突然拜访，在交给你莎尔拉几人的身份认证后，又和你简单聊了一下近况。面对仍在沉睡、无法醒来的尼莉莎，你犹豫是否应该前往深渊第三层看看。"
  },
  [80231280] = {
    id = 80231280,
    name = "默尔曼深夜突然拜访，在交给你莎尔拉几人的身份认证后，又和你简单聊了一下近况。面对仍在沉睡、无法醒来的尼莉莎，你犹豫是否应该前往深渊第三层看看。"
  },
  [80231281] = {
    id = 80231281,
    name = "你再次梦见阿姆罗牺牲前的场景，梦醒后，你思索着阿姆罗留下话语陷入沉思。一个名为“菲尼斯”的陌生名字突然浮现在你的脑海中，你却完全想不起这个名字究竟意味着什么。"
  },
  [80231282] = {
    id = 80231282,
    name = "你再次梦见阿姆罗牺牲前的场景，梦醒后，你思索着阿姆罗留下话语陷入沉思。一个名为“菲尼斯”的陌生名字突然浮现在你的脑海中，你却完全想不起这个名字究竟意味着什么。"
  },
  [80231283] = {
    id = 80231283,
    name = "你再次梦见阿姆罗牺牲前的场景，梦醒后，你思索着阿姆罗留下话语陷入沉思。一个名为“菲尼斯”的陌生名字突然浮现在你的脑海中，你却完全想不起这个名字究竟意味着什么。"
  },
  [80231284] = {
    id = 80231284,
    name = "彻夜未眠的你辗转来到蕾妮希雅的小院。在拉斯特的提醒下得知，当初蕾妮希雅苏醒与“生”的力量有关。你拒绝通过伤害其他生命来获取生之力，但拉斯特告诉你，深渊第三层存在着获取生之力的可能。"
  },
  [80231285] = {
    id = 80231285,
    name = "彻夜未眠的你辗转来到蕾妮希雅的小院。在拉斯特的提醒下得知，当初蕾妮希雅苏醒与“生”的力量有关。你拒绝通过伤害其他生命来获取生之力，但拉斯特告诉你，深渊第三层存在着获取生之力的可能。"
  },
  [80231286] = {
    id = 80231286,
    name = "你们来到深渊第三层，使用弗拉克制作的收集装置开始收集“生之力”。经过一段时间的等待，装置终于凝聚出第一滴纯粹的生之力。你第一次真正相信，沉睡的尼莉莎或许真的有醒来的可能。"
  },
  [80231287] = {
    id = 80231287,
    name = "你们来到深渊第三层，使用弗拉克制作的收集装置开始收集“生之力”。经过一段时间的等待，装置终于凝聚出第一滴纯粹的生之力。你第一次真正相信，沉睡的尼莉莎或许真的有醒来的可能。"
  },
  [80231288] = {
    id = 80231288,
    name = "你们在第三层探索了一段时间后，发现了一个新建立的圈落——铁壁城。通过与皮克二人交流，你们逐渐了解到深渊第三层目前的探索情况。"
  },
  [80231289] = {
    id = 80231289,
    name = "你们在第三层探索了一段时间后，发现了一个新建立的圈落——铁壁城。通过与皮克二人交流，你们逐渐了解到深渊第三层目前的探索情况。"
  },
  [80231290] = {
    id = 80231290,
    name = "在综合各方情报后，你们最终决定前往铁壁城南方探索。南下之路确实相对安宁，沿途能够看到各种探险者留下的标记。就在你们准备继续深入时，一片诡异的浓雾突然将你们笼罩。"
  },
  [80231291] = {
    id = 80231291,
    name = "在综合各方情报后，你们最终决定前往铁壁城南方探索。南下之路确实相对安宁，沿途能够看到各种探险者留下的标记。就在你们准备继续深入时，一片诡异的浓雾突然将你们笼罩。"
  },
  [80231292] = {
    id = 80231292,
    name = "面对突然出现的诡异浓雾，你们试图撤回铁壁城，然而根本无法找到铁壁城的方向，最终只得 到一个山洞中暂时躲避。待浓雾散去时，你们发现自己已身处一个完全陌生的地界。"
  },
  [80231293] = {
    id = 80231293,
    name = "面对突然出现的诡异浓雾，你们试图撤回铁壁城，然而根本无法找到铁壁城的方向，最终只得 到一个山洞中暂时躲避。待浓雾散去时，你们发现自己已身处一个完全陌生的地界。"
  },
  [80231294] = {
    id = 80231294,
    name = "你们与其他探险者继续交换情报，并逐渐怀疑自己可能已经被诡雾送到了铁壁城北面。就在此时，公会作战部部长斯彭德率领大批人员出现。他向你们证实了你们此时正身处铁壁城北面，同时也向你们透露了一些北境的消息。"
  },
  [80231295] = {
    id = 80231295,
    name = "你们与其他探险者继续交换情报，并逐渐怀疑自己可能已经被诡雾送到了铁壁城北面。就在此时，公会作战部部长斯彭德率领大批人员出现。他向你们证实了你们此时正身处铁壁城北面，同时也向你们透露了一些北境的消息。"
  },
  [80231296] = {
    id = 80231296,
    name = "蒂娜带回了更多有关北境的消息，你们整合情报后推测出北境正发生大事。休整一番后，你们决定按计划先返回铁壁城。就在你们准备动身时，诡雾再度出现。"
  },
  [80231297] = {
    id = 80231297,
    name = "蒂娜带回了更多有关北境的消息，你们整合情报后推测出北境正发生大事。休整一番后，你们决定按计划先返回铁壁城。就在你们准备动身时，诡雾再度出现。"
  },
  [80231298] = {
    id = 80231298,
    name = "再次进入诡雾后，你们遇到了此前曾见过的神秘黑衣探险者。她自称“终焉的使者”，并向你们透露诡雾中的世界实际上是现实世界另一侧的“虚界”。她还告诉你们，传奇探险者陆玄正在调查虚界，而自己则是陆玄的弟子。"
  },
  [80231299] = {
    id = 80231299,
    name = "再次进入诡雾后，你们遇到了此前曾见过的神秘黑衣探险者。她自称“终焉的使者”，并向你们透露诡雾中的世界实际上是现实世界另一侧的“虚界”。她还告诉你们，传奇探险者陆玄正在调查虚界，而自己则是陆玄的弟子。"
  },
  [80231300] = {
    id = 80231300,
    name = "诡雾散去后，你们回到铁壁城，却发现整座城市已经进入战备状态，并意外遇到了刚从外面返回的陆玄。通过陆玄的解释，你们终于得以知晓虚界的真实面貌。"
  },
  [80231301] = {
    id = 80231301,
    name = "诡雾散去后，你们回到铁壁城，却发现整座城市已经进入战备状态，并意外遇到了刚从外面返回的陆玄。通过陆玄的解释，你们终于得以知晓虚界的真实面貌。"
  },
  [80231302] = {
    id = 80231302,
    name = "你向陆玄询问铁壁城突然进入战备状态的原因，得知铁壁城北方已经几乎完全沦陷，大量虚界生物开始向周围扩张。就在你们准备等待第二天的会议时，铁壁城却突然响起了紧急号角——虚界生物已经兵临城下。"
  },
  [80231303] = {
    id = 80231303,
    name = "你向陆玄询问铁壁城突然进入战备状态的原因，得知铁壁城北方已经几乎完全沦陷，大量虚界生物开始向周围扩张。就在你们准备等待第二天的会议时，铁壁城却突然响起了紧急号角——虚界生物已经兵临城下。"
  },
  [80231304] = {
    id = 80231304,
    name = "大量虚界生物开始从北方逼近铁壁城，公会作战部部长斯彭德、高塔干部拉斯特以及大量支援部队纷纷赶到城墙。与此同时，独自出城侦察的陆玄杀出重围返回铁壁城，在向你们同步情报的同时，迅速制定了作战计划。"
  },
  [80231305] = {
    id = 80231305,
    name = "大量虚界生物开始从北方逼近铁壁城，公会作战部部长斯彭德、高塔干部拉斯特以及大量支援部队纷纷赶到城墙。与此同时，独自出城侦察的陆玄杀出重围返回铁壁城，在向你们同步情报的同时，迅速制定了作战计划。"
  },
  [80231306] = {
    id = 80231306,
    name = "进入被诡雾覆盖的战场后，陆玄迅速为所有人分配了任务。你和安妮斯、蒂娜被要求对付其中一头领主级魔物。最终，在你们三人的默契配合下，你们成功击败了领主级魔物。"
  },
  [80231307] = {
    id = 80231307,
    name = "进入被诡雾覆盖的战场后，陆玄迅速为所有人分配了任务。你和安妮斯、蒂娜被要求对付其中一头领主级魔物。最终，在你们三人的默契配合下，你们成功击败了领主级魔物。"
  },
  [80231308] = {
    id = 80231308,
    name = "虚界生物第一次真正兵临铁壁城，诡雾与现实不断重叠，铁壁城的防线面临巨大压力。面对无法用常规力量攻击的敌人，陆玄提出了一个大胆的决定——与其被动防守，不如主动进攻。"
  },
  [80231309] = {
    id = 80231309,
    name = "虚界生物第一次真正兵临铁壁城，诡雾与现实不断重叠，铁壁城的防线面临巨大压力。面对无法用常规力量攻击的敌人，陆玄提出了一个大胆的决定——与其被动防守，不如主动进攻。"
  },
  [80231310] = {
    id = 80231310,
    name = "陆玄制定反攻计划，准备利用空间魔法限制并消灭虚界生物。为了实现这一计划，铁壁城向整个深渊召集空间系魔法师，并邀请各方势力放下恩怨共同作战。与此同时，陆玄将一项特殊任务交给了你，而这项任务只有你们能够完成。"
  },
  [80231311] = {
    id = 80231311,
    name = "陆玄制定反攻计划，准备利用空间魔法限制并消灭虚界生物。为了实现这一计划，铁壁城向整个深渊召集空间系魔法师，并邀请各方势力放下恩怨共同作战。与此同时，陆玄将一项特殊任务交给了你，而这项任务只有你们能够完成。"
  },
  [80231312] = {
    id = 80231312,
    name = "铁壁城的求援通告传遍深渊，各方探险者陆续收到消息。谢利在雪莉的劝说下决定前往铁壁城，玛琳娜、莎尔拉、莉莉安以及圣歌、自由学派、荒野游骑兵、鬼牌等众多势力也纷纷响应。随着越来越多的援军赶来，一场席卷深渊第三层的反攻正在逐渐成形。"
  },
  [80231313] = {
    id = 80231313,
    name = "铁壁城的求援通告传遍深渊，各方探险者陆续收到消息。谢利在雪莉的劝说下决定前往铁壁城，玛琳娜、莎尔拉、莉莉安以及圣歌、自由学派、荒野游骑兵、鬼牌等众多势力也纷纷响应。随着越来越多的援军赶来，一场席卷深渊第三层的反攻正在逐渐成形。"
  },
  [80231314] = {
    id = 80231314,
    name = "来自各地的探险者汇聚铁壁城，为即将开始的反攻做最后准备。谢利也终于与陆玄见面，并从陆玄口中得知了这次行动真正面对的敌人究竟有多么可怕。两人约定，等战斗结束后再进行一场真正的较量，而此刻，他们唯一的目标便是击退虚界生物。"
  },
  [80231315] = {
    id = 80231315,
    name = "来自各地的探险者汇聚铁壁城，为即将开始的反攻做最后准备。谢利也终于与陆玄见面，并从陆玄口中得知了这次行动真正面对的敌人究竟有多么可怕。两人约定，等战斗结束后再进行一场真正的较量，而此刻，他们唯一的目标便是击退虚界生物。"
  },
  [80231316] = {
    id = 80231316,
    name = "反攻前夜，所有探险者完成最后的准备。第二天清晨，吉尔斯向众人发起战前动员，各方势力整装待发。然而陆玄迟迟没有下达出发命令，直到一名黑衣少女带来了“师兄他们已经开始行动”的消息。陆玄终于下令——反攻，正式开始。"
  },
  [80231317] = {
    id = 80231317,
    name = "反攻前夜，所有探险者完成最后的准备。第二天清晨，吉尔斯向众人发起战前动员，各方势力整装待发。然而陆玄迟迟没有下达出发命令，直到一名黑衣少女带来了“师兄他们已经开始行动”的消息。陆玄终于下令——反攻，正式开始。"
  },
  [80231318] = {
    id = 80231318,
    name = "为了协助陆玄完成对虚界生物的封锁，你、安妮斯与蒂娜借助特殊装置进入虚界。在这个陌生的世界中，你们遇到了陆玄的另一名弟子诺瓦，以及她的同伴瑞丝汀娜，并得知了她们一直在虚界中执行的秘密任务。"
  },
  [80231319] = {
    id = 80231319,
    name = "为了协助陆玄完成对虚界生物的封锁，你、安妮斯与蒂娜借助特殊装置进入虚界。在这个陌生的世界中，你们遇到了陆玄的另一名弟子诺瓦，以及她的同伴瑞丝汀娜，并得知了她们一直在虚界中执行的秘密任务。"
  },
  [80231320] = {
    id = 80231320,
    name = "你们向诺瓦与瑞丝汀娜说明了反攻计划——现实中的探险者负责寻找并控制虚界生物，而你们则利用诱导装置，将虚界生物吸引到指定位置。随着第一个诱导装置成功启动，反攻行动正式开始。"
  },
  [80231321] = {
    id = 80231321,
    name = "你们向诺瓦与瑞丝汀娜说明了反攻计划——现实中的探险者负责寻找并控制虚界生物，而你们则利用诱导装置，将虚界生物吸引到指定位置。随着第一个诱导装置成功启动，反攻行动正式开始。"
  },
  [80231322] = {
    id = 80231322,
    name = "大量虚界生物被成功引诱并控制，探险者们一路推进至史前遗迹。陆玄亲自出手，借助双鱼玉佩发动强大的封印阵法，终于将史前遗迹彻底封锁。所有人都以为危机即将结束，却没有意识到更可怕的存在正在遗迹深处苏醒。"
  },
  [80231323] = {
    id = 80231323,
    name = "大量虚界生物被成功引诱并控制，探险者们一路推进至史前遗迹。陆玄亲自出手，借助双鱼玉佩发动强大的封印阵法，终于将史前遗迹彻底封锁。所有人都以为危机即将结束，却没有意识到更可怕的存在正在遗迹深处苏醒。"
  },
  [80231324] = {
    id = 80231324,
    name = "封印完成后，你们返回现实，却发现陆玄已经因为施展顶尖封印阵法而极度虚弱。一声来自灵魂深处的恐怖低吼突然响彻深渊，陆玄认出了那来自虚界的恐怖存在——灭世之兽。真正的灾难，才刚刚开始。"
  },
  [80231325] = {
    id = 80231325,
    name = "封印完成后，你们返回现实，却发现陆玄已经因为施展顶尖封印阵法而极度虚弱。一声来自灵魂深处的恐怖低吼突然响彻深渊，陆玄认出了那来自虚界的恐怖存在——灭世之兽。真正的灾难，才刚刚开始。"
  },
  [80231326] = {
    id = 80231326,
    name = "灭世之兽的出现远远超出了所有人的预料。陆玄命令你们立即撤回铁壁城，并准备彻底封锁深渊第三层。面对即将降临的灭世之灾，陆玄选择独自留下，为所有人争取最后的时间。最终，他燃烧生命发动最后一击，却被灭世之兽吞没。"
  },
  [80231327] = {
    id = 80231327,
    name = "灭世之兽的出现远远超出了所有人的预料。陆玄命令你们立即撤回铁壁城，并准备彻底封锁深渊第三层。面对即将降临的灭世之灾，陆玄选择独自留下，为所有人争取最后的时间。最终，他燃烧生命发动最后一击，却被灭世之兽吞没。"
  },
  [80231328] = {
    id = 80231328,
    name = "陆玄陨落后，铁壁城彻底陷入绝境。灭世之兽挣脱封印，诡雾笼罩深渊第三层，所有退路尽数被切断。面对即将到来的灭世之兽，铁壁城只能集结最后的力量，背水一战。"
  },
  [80231329] = {
    id = 80231329,
    name = "陆玄陨落后，铁壁城彻底陷入绝境。灭世之兽挣脱封印，诡雾笼罩深渊第三层，所有退路尽数被切断。面对即将到来的灭世之兽，铁壁城只能集结最后的力量，背水一战。"
  },
  [80231330] = {
    id = 80231330,
    name = "灭世之兽逼近铁壁城，恐怖的气息令无数探险者心生畏惧。拉斯特与斯彭德放下往日恩怨，率领高塔与公会并肩作战。谢利、玛琳娜、诺瓦等人也加入战场，所有人将希望寄托于这场最后的决战。"
  },
  [80231331] = {
    id = 80231331,
    name = "灭世之兽逼近铁壁城，恐怖的气息令无数探险者心生畏惧。拉斯特与斯彭德放下往日恩怨，率领高塔与公会并肩作战。谢利、玛琳娜、诺瓦等人也加入战场，所有人将希望寄托于这场最后的决战。"
  },
  [80231332] = {
    id = 80231332,
    name = "决战正式开始，然而灭世之兽展现出的力量远远超出了所有人的想象。高塔与公会的联合攻击瞬间覆灭，战场陷入彻底的混乱。为了给众人争取逃生的机会，谢利与吉尔斯选择留下，而你们也被迫踏上寻找最后生机的道路。"
  },
  [80231333] = {
    id = 80231333,
    name = "决战正式开始，然而灭世之兽展现出的力量远远超出了所有人的想象。高塔与公会的联合攻击瞬间覆灭，战场陷入彻底的混乱。为了给众人争取逃生的机会，谢利与吉尔斯选择留下，而你们也被迫踏上寻找最后生机的道路。"
  },
  [80231334] = {
    id = 80231334,
    name = "铁壁城陷入前所未有的危机之际，蕾妮希雅与列蒂西雅突然出现，并带来了新的可能。你们发现，真正阻止灭世之兽的关键或许并不是击败它，而是彻底切断虚界与现实之间的联系。于是，你、安妮斯与蒂娜再次踏入虚界，开始一场赌上所有人命运的冒险。"
  },
  [80231335] = {
    id = 80231335,
    name = "铁壁城陷入前所未有的危机之际，蕾妮希雅与列蒂西雅突然出现，并带来了新的可能。你们发现，真正阻止灭世之兽的关键或许并不是击败它，而是彻底切断虚界与现实之间的联系。于是，你、安妮斯与蒂娜再次踏入虚界，开始一场赌上所有人命运的冒险。"
  },
  [80231336] = {
    id = 80231336,
    name = "你们在虚界中不断寻找并切断现实与虚界的连接点。随着最后的连接点被发现，一个残酷的问题也摆在三人面前——一旦虚界与现实彻底分离，留在其中的人将再也无法归来。面对无法两全的结局，安妮斯与蒂娜分别做出了自己的选择。"
  },
  [80231337] = {
    id = 80231337,
    name = "最后的连接点终于被斩断，虚界与现实开始彻底分离。灭世之兽察觉到危机，试图阻止这一切，却最终消失在规则之力中。被吞噬的探险者重新归来，列蒂西雅也在苦苦寻觅你的身影，正当她快要绝望之际，一个熟悉的身影出现在了她的视野......"
  },
  [80232001] = {id = 80232001, name = "Side Story"},
  [80232002] = {
    id = 80232002,
    name = "几经辗转，你终于找到了伊涅利丝秘密基地所需要的魔法石，但每个同伴都推诿有事，你只能独自前往她的秘密基地。"
  },
