  [80232549] = {
    id = 80232549,
    name = "根绝魔物祸患的最佳手段，便是解决引发祸患的元凶。"
  },
  [80232550] = {
    id = 80232550,
    name = "あなたたちはシェラとレムと共に手がかりに基づいて細石村に到着し、情報屋の言うオリアンという人を見つけた。話をして探りを入れてみると、オリアンは実は闇夜村から出てきた人の子孫であることが分かった。闇夜村に行きたいなら、ずっと細石村を騒がせている魔物を退治し、必要な材料を持ち帰ってほしいという。"
  },
  [80232551] = {
    id = 80232551,
    name = "あなたたちはシェラとレムと共に手がかりに基づいて細石村に到着し、情報屋の言うオリアンという人を見つけた。話をして探りを入れてみると、オリアンは実は闇夜村から出てきた人の子孫であることが分かった。闇夜村に行きたいなら、ずっと細石村を騒がせている魔物を退治し、必要な材料を持ち帰ってほしいという。"
  },
  [80232552] = {
    id = 80232552,
    name = "あなたたちはシェラとレムと共に手がかりに基づいて細石村に到着し、情報屋の言うオリアンという人を見つけた。話をして探りを入れてみると、オリアンは実は闇夜村から出てきた人の子孫であることが分かった。闇夜村に行きたいなら、ずっと細石村を騒がせている魔物を退治し、必要な材料を持ち帰ってほしいという。"
  },
  [80232553] = {
    id = 80232553,
    name = "あなたたちはシェラとレムと共に手がかりに基づいて細石村に到着し、情報屋の言うオリアンという人を見つけた。話をして探りを入れてみると、オリアンは実は闇夜村から出てきた人の子孫であることが分かった。闇夜村に行きたいなら、ずっと細石村を騒がせている魔物を退治し、必要な材料を持ち帰ってほしいという。"
  },
  [80232554] = {
    id = 80232554,
    name = "一行は魔物を退治して材料を手に入れると、オリアンに渡した。オリアンはあなたたちに闇夜村の場所と、手に入れた物を使って村に入る方法を教えた。ついでに亡くなった家族の遺品を持ち帰ってほしいと頼んだ。一行は引き受けて、闇夜村に出立した。"
  },
