  [80232557] = {
    id = 80232557,
    name = "一行は魔物を退治して材料を手に入れると、オリアンに渡した。オリアンはあなたたちに闇夜村の場所と、手に入れた物を使って村に入る方法を教えた。ついでに亡くなった家族の遺品を持ち帰ってほしいと頼んだ。一行は引き受けて、闇夜村に出立した。"
  },
  [80232558] = {
    id = 80232558,
    name = "闇夜村に着くと、そこはまるでおとぎ話の世界のようだった。しかし村長は今年の月光祭は開催できないという。これまで祈祷に使われていた宝物の鏡が割れてしまったせいだ。鏡がないと月の光を反射させて湖を照らすことも、ランタンを飛ばして霧を散らすこともできない。シェラとレム、それにあなたたちは修復の手伝いを申し出た。"
  },
  [80232559] = {
