  [80232780] = {
    id = 80232780,
    name = "诺维奇帝国的大王女蕾妮希雅出生了，她拥有顺位的王位继承权，并且获得了继承人才能拥有的白蔷薇之梦。她的母亲因难产导致之后身体愈发虚弱，在公主六岁时去世。公主魔法的天赋极高，父亲对她十分宠爱。"
  },
  [80232781] = {
