  [80232799] = {
    id = 80232799,
    name = "蕾妮希雅想拉拢被卖的女孩，却被反手举报，她在挨打时她负伤逃走，向所有人求救，却没有人救她，她拼死反抗，死之前她恢复了记忆，头饰白蔷薇之梦聚集了最极致的爱和恨，以及最深的执念，化为了守护者......"
  },
  [80232800] = {
    id = 80232800,
    name = "神秘人知道守护者所求是复活公主，跟她做交易，让她去找材料，告诉她在深渊中如何变强，成长为神秘人需要的实力之后，再将复活公主的事告诉守护者。"
  },
