  [80234247] = {
    id = 80234247,
    name = "时间一年年过去，雪莉为谢利接上新的四肢，耐心教导她如何控制、行走、运用。雪莉教导谢利知识、魔法与武技，她发现谢利武技的天赋，和对生命的漠视，开始教导她为人的底线与善良，谢利逐渐依赖并深爱这位对她全心付出的养母。"
  },
  [80234248] = {
    id = 80234248,
    name = "时间一年年过去，雪莉为谢利接上新的四肢，耐心教导她如何控制、行走、运用。雪莉教导谢利知识、魔法与武技，她发现谢利武技的天赋，和对生命的漠视，开始教导她为人的底线与善良，谢利逐渐依赖并深爱这位对她全心付出的养母。"
  },
  [80234249] = {
    id = 80234249,
    name = "雪莉带她回到高塔，宣布了谢利的身份，雪莉为防范缇法尼，出任务时时刻带上谢利。在谢利七岁时，一次任务中，遭遇强大魔物，雪莉为保护谢利与属下，身受极重的创伤，虽侥幸生还，但再也无法执行任务。"
  },
  [80234250] = {
    id = 80234250,
    name = "高塔的供给仅能维持基本生存，雪莉的重伤让家庭陷入困境。谢利无法负担昂贵的药物，目睹养母被病痛折磨，非常痛苦，梅娅和米沙（雪莉旧部）来看望母女，在梅娅走后，米沙给谢利出主意，让她也加入任务，但谢利仍在犹豫。（离开后无人照顾雪莉）"
  },
  [80234251] = {
    id = 80234251,
    name = "高塔的供给仅能维持基本生存，雪莉的重伤让家庭陷入困境。谢利无法负担昂贵的药物，目睹养母被病痛折磨，非常痛苦，梅娅和米沙（雪莉旧部）来看望母女，在梅娅走后，米沙给谢利出主意，让她也加入任务，但谢利仍在犹豫。（离开后无人照顾雪莉）"
  },
  [80234252] = {
    id = 80234252,
    name = "高塔的供给仅能维持基本生存，雪莉的重伤让家庭陷入困境。谢利无法负担昂贵的药物，目睹养母被病痛折磨，非常痛苦，梅娅和米沙（雪莉旧部）来看望母女，在梅娅走后，米沙给谢利出主意，让她也加入任务，但谢利仍在犹豫。（离开后无人照顾雪莉）"
  },
  [80234253] = {
    id = 80234253,
    name = "看着日益虚弱的雪莉，谢利决定继承母亲的职责，她找到米沙，要求执行一些力所能及的任务，赚取功勋点以换取药物和食物。梅娅开始不赞同，被谢利打动后，答应谢利会照看雪莉，梅娅叫来了尤娜，照顾雪莉。"
  },
  [80234254] = {
    id = 80234254,
    name = "看着日益虚弱的雪莉，谢利决定继承母亲的职责，她找到米沙，要求执行一些力所能及的任务，赚取功勋点以换取药物和食物。梅娅开始不赞同，被谢利打动后，答应谢利会照看雪莉，梅娅叫来了尤娜，照顾雪莉。"
  },
  [80234255] = {
    id = 80234255,
    name = "看着日益虚弱的雪莉，谢利决定继承母亲的职责，她找到米沙，要求执行一些力所能及的任务，赚取功勋点以换取药物和食物。梅娅开始不赞同，被谢利打动后，答应谢利会照看雪莉，梅娅叫来了尤娜，照顾雪莉。"
  },
  [80234256] = {
    id = 80234256,
    name = "米沙起初因谢利是雪莉养女且年纪小而稍有照顾，但谢利的杀戮天赋，和狂妄果决逐渐显现，任务完成出色，有时甚至抢了米沙的风头，引来米沙的嫉妒与不满。谢利咬牙坚持，每次完成任务后，功勋点最先兑换的都是雪莉的药物，尤娜时常担心谢利，尽力协助。"
  },
  [80234257] = {
    id = 80234257,
    name = "米沙起初因谢利是雪莉养女且年纪小而稍有照顾，但谢利的杀戮天赋，和狂妄果决逐渐显现，任务完成出色，有时甚至抢了米沙的风头，引来米沙的嫉妒与不满。谢利咬牙坚持，每次完成任务后，功勋点最先兑换的都是雪莉的药物，尤娜时常担心谢利，尽力协助。"
  },
  [80234258] = {
    id = 80234258,
    name = "米沙起初因谢利是雪莉养女且年纪小而稍有照顾，但谢利的杀戮天赋，和狂妄果决逐渐显现，任务完成出色，有时甚至抢了米沙的风头，引来米沙的嫉妒与不满。谢利咬牙坚持，每次完成任务后，功勋点最先兑换的都是雪莉的药物，尤娜时常担心谢利，尽力协助。"
  },
  [80234259] = {
    id = 80234259,
    name = "谢利在外拼搏，回家则隐藏疲惫，细心照料雪莉，讲述任务中有趣的经历，报喜不报忧。雪莉心疼不已，却无力改变，只能将担忧深藏心底，给予谢利更多的鼓励与爱。这份相依为命的亲情，是黑暗世界中最珍贵的支撑。"
  },
  [80234260] = {
    id = 80234260,
    name = "面对谢利的迅速成长，米沙因嫉妒和贪婪，设计陷害谢利，一次危险任务中，将其引入强大魔物的巢穴深处，意图借魔物之手除掉谢利。"
  },
  [80234261] = {
    id = 80234261,
    name = "面对谢利的迅速成长，米沙因嫉妒和贪婪，设计陷害谢利，一次危险任务中，将其引入强大魔物的巢穴深处，意图借魔物之手除掉谢利。"
  },
  [80234262] = {
    id = 80234262,
    name = "面对谢利的迅速成长，米沙因嫉妒和贪婪，设计陷害谢利，一次危险任务中，将其引入强大魔物的巢穴深处，意图借魔物之手除掉谢利。"
  },
  [80234263] = {
    id = 80234263,
    name = "面对绝境与魔物的虐杀，谢利濒死之际，体内浊炁力量彻底爆发，救了她一命。首次爆发带来的不仅是力量，还有嗜血心性和狂暴的杀意。她反杀了魔物，也初次体验了失控的感觉。"
  },
  [80234264] = {
    id = 80234264,
    name = "面对绝境与魔物的虐杀，谢利濒死之际，体内浊炁力量彻底爆发，救了她一命。首次爆发带来的不仅是力量，还有嗜血心性和狂暴的杀意。她反杀了魔物，也初次体验了失控的感觉。"
  },
  [80234265] = {
    id = 80234265,
    name = "面对绝境与魔物的虐杀，谢利濒死之际，体内浊炁力量彻底爆发，救了她一命。首次爆发带来的不仅是力量，还有嗜血心性和狂暴的杀意。她反杀了魔物，也初次体验了失控的感觉。"
  },
  [80234266] = {
    id = 80234266,
    name = "谢利意识到自身力量的异常与危险，她隐瞒了真相，开始暗中研究并尝试控制浊炁，发现深渊浊炁不仅不伤害她，反而成为力量源泉。她走上了自创修行体系的道路，力量快速增长，性格也更趋狂妄果决，但在雪莉面前依旧保持乖顺。"
  },
  [80234267] = {
    id = 80234267,
    name = "谢利意识到自身力量的异常与危险，她隐瞒了真相，开始暗中研究并尝试控制浊炁，发现深渊浊炁不仅不伤害她，反而成为力量源泉。她走上了自创修行体系的道路，力量快速增长，性格也更趋狂妄果决，但在雪莉面前依旧保持乖顺。"
  },
  [80234268] = {
    id = 80234268,
    name = "谢利意识到自身力量的异常与危险，她隐瞒了真相，开始暗中研究并尝试控制浊炁，发现深渊浊炁不仅不伤害她，反而成为力量源泉。她走上了自创修行体系的道路，力量快速增长，性格也更趋狂妄果决，但在雪莉面前依旧保持乖顺。"
  },
  [80234269] = {
    id = 80234269,
    name = "为了获取更好的药物治疗雪莉，也为了清算背叛，谢利暗中调查并确认了米沙的陷害行为。她秘密处决了米沙。凭借逐渐展现的力量与雪莉昔日积累的威望，收服并整合了雪莉的旧部，继承了雪莉的位置，成为高塔中令人瞩目的新锐力量。"
  },
  [80234270] = {
    id = 80234270,
    name = "谢利在人前是高塔无间狱新任的组长，狂妄锋利，任务完成率极高，令人畏惧。人后是雪莉的孝顺女儿，照顾母亲起居，分享日常趣事，努力维持着家的温暖，梅娅和尤娜成为她最得力的副手与朋友。"
  },
  [80234271] = {
    id = 80234271,
    name = "谢利在人前是高塔无间狱新任的组长，狂妄锋利，任务完成率极高，令人畏惧。人后是雪莉的孝顺女儿，照顾母亲起居，分享日常趣事，努力维持着家的温暖，梅娅和尤娜成为她最得力的副手与朋友。"
