  [80234279] = {
    id = 80234279,
    name = "缇法尼在谢利的相助下，成为了无间狱的首领。谢利也成为了缇法尼手中最锋利的刀。一天，缇法尼给谢利布置了任务：抢夺繁星之环。在繁星之环失踪后，谢利窥见了主角团一行人，命运的齿轮由此开始启动。"
  },
