  [80233001] = {
    id = 80233001,
    name = "带领魔物群奔袭冲锋的领主级魔物，脾气暴躁，破坏欲极强。\n巨大的身躯及磅礴的力量能轻易摧毁山石、建筑，对探险者们构筑的防御工事拥有极大威胁。"
  },
  [80233002] = {
    id = 80233002,
    name = "生性高傲的领主级魔物，视自己以外的一切存在为蝼蚁。\n无论探险者还是魔物，只要让它感到不快，都将承受它的无尽怒火。"
  },
  [80233003] = {
    id = 80233003,
    name = "出现在兽潮中的领主级魔物，残忍暴虐，却又充满恶趣味的存在。\n比起直接夺走猎物的生命，更喜欢残忍的折磨猎物。\n非常享受被其他生灵敬畏、恐惧的感觉。"
  },
  [80233004] = {
    id = 80233004,
    name = "个性极为恶劣的领主级魔物，非常喜欢玩弄实力不及自身的对手，享受狩猎的乐趣。\n对于势均力敌的对手则显得非常谨慎，绝不会轻敌大意。"
  },
  [80233005] = {
    id = 80233005,
    name = "魔物中强大至极，引发兽潮的存在。\n遵从自身意志而行动，为达成自己的目的不惜一切，任何试图妨碍它的存在都将被它无情吞噬。"
  },
