  },
  [80301736] = {
    id = 80301736,
    name = "刺尾凶兽"
  },
  [80301737] = {id = 80301737, name = "骨甲龙"},
  [80301738] = {
    id = 80301738,
    name = "黯面邪灵"
  },
  [80301801] = {id = 80301801, name = "凶镰"},
  [80301802] = {
    id = 80301802,
    name = "银脊恶魔"
  },
  [80301803] = {
    id = 80301803,
    name = "咏叹蔷薇"
  },
  [80301804] = {
    id = 80301804,
    name = "悲鸣蔷薇"
  },
  [80301805] = {
    id = 80301805,
    name = "恐角戮兽"
  },
  [80301904] = {id = 80301904, name = "荒狱"},
  [80301906] = {id = 80301906, name = "幽伏"},
  [80301910] = {
    id = 80301910,
    name = "无形之主"
  },
  [80301950] = {
    id = 80301950,
    name = "无形之主"
  },
  [80301903] = {id = 80301903, name = "祸影"},
  [80301907] = {id = 80301907, name = "苦厄"},
  [80301908] = {
    id = 80301908,
    name = "摄魂之主"
  },
  [80301951] = {
    id = 80301951,
    name = "摄魂之主"
  },
  [80301952] = {id = 80301952, name = "绿魔"},
  [80301953] = {id = 80301953, name = "湮灭者"},
  [80311001] = {
    id = 80311001,
    name = "对不少新人探险者而言，古岩兽是一种极为棘手的存在。\n它们蜷缩在深渊各地，伪装成一堆堆岩石，倘若不仔细辨别，很容易被它们偷袭。\n此外，古岩兽的躯壳坚硬，而且拥有着和那笨拙身躯毫不匹配的速度，\n每当遇到它们，无论是战斗还是逃跑，都变得非常艰难。"
  },
  [80311002] = {
    id = 80311002,
    name = "裂刃兽性格暴戾凶残，极其好战，时常成群在深渊各地游荡。\n即使在无需猎食的时候，它们也时常袭击其他目标。\n相较于深渊中的许多魔物，裂刃兽的体型和甲壳并不占任何优势。\n但它们刀刃般的肢体，却让任何敌人也不敢轻视它们的存在。\n特别是面对成群的裂刃兽时，稍不留意，身体便会被它们锋利的刀刃撕裂。"
  },
  [80311003] = {
    id = 80311003,
    name = "石睛兽喜欢在深渊四处游荡，许多地方都有它们的踪影。\n它们长有水晶般的独目，双臂强劲有力，是一种实力非常出色的魔物。\n相对于其他暴戾凶猛的魔物，石睛兽的性格相对温和，\n在没有进食需求或遭受威胁挑衅时，它们一般不会主动发起战斗。"
  },
  [80311004] = {
    id = 80311004,
    name = "巨翼兽长有标志性的巨大双翼，长期活跃在深渊各地。\n它们的实力平平，但凭借空中优势，也足以令一些魔物和探险者头疼。\n而且巨翼兽极其阴险狡诈，在非必要的时候，它们一般不会主动攻击其他目标。\n它们很喜欢观看别的魔物争斗，待两败俱伤之时再出手坐收渔利。"
  },
  [80311005] = {
    id = 80311005,
    name = "瑰石兽是深渊中常见的魔物，形象如同一堆石头。\n它们善于利用自己的形象迷惑对手，伺机进行攻击。\n瑰石兽的单体实力并不算出色，\n但它们集群行动时足以给敌人带来巨大威胁。"
  },
  [80311006] = {
    id = 80311006,
    name = "碎骨凶兽的嘴部长有如同刀刃般的巨大口钳，坚硬的岩石也难以抵挡它的撕咬。\n它们脾气暴躁，个性凶残，会毫不犹豫地对任何可能存在威胁的目标发起攻击。\n不过碎骨凶兽一般不会主动离开自己的生活区域，\n被它们盯上时，如果能快速离开，或许可以避免一场恶战。"
  },
  [80311007] = {
    id = 80311007,
    name = "妖鬼平时一般蛰伏在山野荒地之中，当它们苏醒时，便会四处游荡寻找猎物。\n它们的速度并不算快，但是力量极为出色，普通防护完全无法挡住它们的攻击。\n此外，妖鬼极为谨慎，从不轻敌大意。\n即便是面对远比自己弱小的猎物，它们也会全力以赴，绝不给对手任何机会。"
  },
  [80311008] = {
    id = 80311008,
    name = "幻晶石灵拥有如同晶石般的外壳，这种外壳给予了它们出色的防护和伪装能力。\n当它们静止不动时，看起来就如同一块巨大的天然晶石。\n许多探险者和魔物时常会被它迷惑，贸然接近，令自身陷入危机。"
  },
  [80311009] = {
    id = 80311009,
    name = "魔羽身形奇异，静止不动时宛如盛放的鲜花，极具迷惑性。\n它自身会散发一种无色无味的气体，倘若长时间停留在它身旁，则会陷入恍惚。\n魔羽时常利用这种气体对付猎物，\n当猎物陷入恍惚，毫无防备之际，魔羽便会发动致命攻击。\n对老练的探险者而言，对付魔羽并不算很难，但对新人探险者来说，它们却是极其危险的存在。"
  },
  [80311010] = {
    id = 80311010,
    name = "对长期在深渊行动的探险者而言，尖角地精是一种令人极其厌恶的存在。\n它们长期躲在阴暗中，伪装成碎石，趁人毫无防备之时发起突然袭击。\n尖角地精的个体实力并不强大，但它们喜欢集群行动，\n对付它们时如果太过大意，很容易为自己带来生命危险。"
  },
  [80311011] = {
    id = 80311011,
    name = "鬼面魔蛛的面容狰狞恐怖，巨大的身躯表面布满古怪的花纹，犹如从地狱爬出的恶鬼。\n它肢体修长，宛如锋利的长枪，让它既能轻易洞穿敌人的躯体，\n又拥有了在各种区域都能灵活行动的能力。\n然而自身强大的实力并未令鬼面魔蛛变得傲慢，相反，它在战斗时的表现极为谨慎。\n无论面对怎样的对手，它都会全力以赴，绝不轻敌大意。"
  },
  [80311012] = {
    id = 80311012,
    name = "接引者全身都被洁白的甲壳所包裹，表面点缀着精致的花纹，远远看去极为优雅、高洁。\n然而它其实是极为危险凶残的存在，在它活动的区域，必然存在着无数争斗和杀戮。\n接引者生性暴躁傲慢，任何令它感到不满的存在，都将被它利刃般的双臂所撕碎。\n即便是面对那些极为强大的存在，接引者也毫不畏惧。"
  },
  [80311013] = {
    id = 80311013,
    name = "凶镰拥有巨大而锋利的双爪，宛如死神的镰刀。\n它行踪诡异，动作极快，每当它出手时，许多人根本来不及反应便惨死在它的利爪之下。\n因此凶镰在探险者中一度成为了死神的代名词。\n不过凶镰虽然强大，但主要袭击对象都是落单的目标，\n对于群体行动的生物，它们通常不会贸然出击。"
  },
  [80311014] = {
    id = 80311014,
    name = "银脊恶魔身躯修长，后背长有一道宛如水晶般璀璨瑰丽的背鳍。\n它时常会利用自己的背鳍引诱猎物，待对方靠近后再发动攻击。\n此外，银脊恶魔的头颅周围长有多个细长的小头，每一个小头都拥有诡异的能力。\n当它和敌人交战时，这些小头会伺机偷袭，令敌人极难防范。"
  },
  [80311015] = {
    id = 80311015,
    name = "咏叹蔷薇的肢体宛如藤蔓，修长而灵活，在它的背后长有一朵巨大、妖艳的红蔷薇。\n蔷薇中会施放出一种无形粉尘，这种粉尘会给意志不够坚定的生物带来轻松、愉悦的幻觉。\n陷入这种幻觉的生物将会放下所有戒备，沉迷其中无法自拔。\n或许，只有它们的身躯被咏叹蔷薇贯穿时的痛感，才能令它们从那愉悦的幻境中清醒。"
  },
  [80311016] = {
    id = 80311016,
    name = "群山的霸主，天空的王者......人们给予了它许多称号。\n那些称号一个比一个夸张，让人觉得不可思议，难以想象。\n然而真正直面它时，便会发现那些称号还是太过保守。\n它的强大足以让凶猛的魔物战栗，足以让优秀的探险者畏惧......"
  },
  [80311017] = {
    id = 80311017,
    name = "作为各种故事和诗歌中的常客，人们对它并不陌生。\n但“知道”并不等于“亲眼所见”，事实上，遇到它之后还能幸存下来的人极少。\n面对它时，大部分人和魔物都会丧失战斗意志。\n如果能侥幸从它手中逃脱，已足以让幸存者在长时间内成为周围人谈论的话题。"
  },
  [80311101] = {
    id = 80311101,
    name = "食魂兽是一种极为危险的存在，主要生活在深渊中的沼泽、湿地，以及一些近水区域。\n它们速度极快，总是在对手还来不及做出反应时便已结束战斗。\n对探险者而言，在野外遇上它们绝对算不上好事。\n如果无法保持足够的专注和谨慎，稍不留神便可能陷入危机。"
  },
  [80311102] = {
    id = 80311102,
    name = "黑骨兽个性凶残，长期活跃在深渊中的阴暗区域。\n它们的外形如同深色枝丫，隐匿在阴暗密林中时很难被察觉。\n它们的实力强大而诡异，能够直接对敌人的精神进行攻击。\n倘若自身的意志不够坚定，很难在它的攻击中保持清醒，\n最终，难免沦为它们的食粮。"
  },
  [80311103] = {
    id = 80311103,
    name = "裂面凶兽长有一张恐怖的巨口，能够轻易吞下和它体型相似的目标。\n它们脾气暴烈、急躁，一旦受到打扰或者感到不安，便会对周围的目标发起攻击。\n在战斗中，任何非致命伤害都会令裂面凶兽变得更加疯狂，\n它们一旦受到伤害，便会不惜一切代价攻击敌人，不死不休。"
  },
  [80311104] = {
    id = 80311104,
    name = "狂暴魔灵犹如深渊中的角斗士，时常四处游荡寻找战斗对手。\n它们动作敏捷，双臂强劲有力，属于同等级魔物中单体实力非常出色的存在。\n因此时常会有一些极为自信的探险者去主动挑战它们，想要战胜狂暴魔灵证明自己的实力。\n可惜狂暴魔灵从来不会给败者第二次机会，\n被它们所击败的对手，从来不会有什么好结局。"
  },
  [80311105] = {
    id = 80311105,
    name = "骨甲凶兽身形硕大，犹如永远无法满足的饿兽，不断捕食所在区域内的其他目标。\n它们看似笨拙，实则反应速度极快，一旦被它们盯上，很难逃脱。\n而且它们生性极为狡猾，很喜欢主动示弱以引诱猎物，待对方靠近之后再突然暴起发动袭击。"
  },
  [80311106] = {
    id = 80311106,
    name = "碑魔平时会将身躯埋在地里，只露出背部高耸的甲壳，宛如一块石碑。\n只有需要移动时，它们才会从地里出来。\n对碑魔而言，背甲极为重要，它既是碑魔施放攻击的载体，又能为碑魔带来有效的防护和伪装。\n而且它的背甲质地坚硬、耐磨损，即便久经风雨也很少出现变形、腐蚀。\n因此一些探险者在同伴牺牲后，也会选择用碑魔的背甲为同伴制作墓碑。"
  },
  [80311107] = {
    id = 80311107,
    name = "滚地石精拥有如同圆球般的躯体，四肢强壮有力。\n它的脾气古怪，急躁暴烈，任何令它感到不满的存在都会遭受它的攻击。\n不过，这一点对同族除外。\n滚地石精无论和同族发生怎样的争执，也绝不会轻易发生战斗。"
  },
  [80311108] = {
    id = 80311108,
    name = "粉碎者长有强劲有力的双臂，可以轻松撕碎其他生物的躯体。\n它的脾气暴戾，极为自我，任何令它感到不满的存在，都会被它毫不犹豫地摧毁。\n粉碎者对自己的实力非常自信，对手越强大它便会越兴奋，\n特别是那些敢主动挑衅自己的存在，粉碎者会全力以赴，绝不给对手任何机会。"
  },
  [80311109] = {
    id = 80311109,
    name = "妖尾戮兽拥有强大的力量，生性狡猾、谨慎，\n除了那些和自身实力悬殊的目标，它们面对敌人时，很少贸然行动。\n每当它们发现心仪的猎物，便会远远地跟随猎物，观察猎物的一举一动，\n待对猎物有了足够的了解之后，它们便会趁猎物露出破绽时，发动突袭。\n倘若发现猎物的实力太过强大，或者难以判断，妖尾戮兽则会选择迅速撤离，绝不轻举妄动。"
  },
  [80311110] = {
    id = 80311110,
    name = "骨甲龙浑身都被甲壳覆盖，看似笨拙，实际上反应极快，是一种非常危险的存在。\n不过，它们除了必要的猎食之外，并不喜欢四处移动。\n它们很喜欢以一种极为舒适的姿态趴在地面，很长时间也不会挪动一下，看起来犹如死去了一般。\n骨甲龙的这种行为时常会吸引一些过往目标近前查探，\n对于这些打扰自己安宁的存在，骨甲龙则会暴起发动攻击。"
  },
  [80311111] = {
    id = 80311111,
    name = "黯面邪灵对许多事物都感到好奇，时常会在深渊四处飘荡，寻找感兴趣的存在。\n但它们的性格相对胆小、谨慎，即便发现了感兴趣的目标，也只会在暗中窥探，不会贸然上前。\n平时黯面邪灵很少主动攻击其他目标，\n但如果主动招惹它们，或者受到惊吓时，\n黯面邪灵便会对惊扰自己的目标展开疯狂攻击，直至将其彻底消灭。"
  },
  [80311112] = {
    id = 80311112,
    name = "摄魂恶魔行踪诡秘，来去悄无声息，犹如游荡在深渊中的恶灵。\n它的能力极为强大，能够直接影响敌人的心智，对其精神发动攻击。\n意志不够坚定的生物一旦被它盯上，很难有幸存的可能。\n不过在猎食之外，摄魂恶魔并不喜欢随意杀戮，\n只要不主动招惹它，它很少会在意自己兴趣之外的事物。"
  },
  [80311113] = {
    id = 80311113,
    name = "斑斓的色彩，妖娆的身姿，远远看去如同美的化身。\n有幸目睹过它存在的探险者们，总会在茶余饭后提起它的名字。\n只是它的美丽极为危险，任何试图靠近者都会沦为它的猎物。\n在承受无数折磨、痛苦、绝望之后，被它所吞噬。"
  },
  [80311114] = {
    id = 80311114,
    name = "它总是悄无声息地出现，张开巨口吞噬周围所有的存在。\n待一切归于平静，又悄无声息地消失。\n如同深渊意志的化身，清扫着深渊大地上不协调的存在。\n对探险者而言，它的强大让人恐惧，但它的神秘也让人好奇......"
  },
  [80311115] = {
    id = 80311115,
    name = "身形庞大，犹如矗立在深渊的要塞，当它行动时，连大地也会为之颤动。\n无论探险者还是魔物，没有任何生灵敢轻易招惹它。\n人类和普通魔物在它面前显得渺小无比，仅仅只是直面它，就需要莫大的勇气。\n即便是那些鲁莽的家伙，或者纯粹的笨蛋，在见到它时也会本能地逃避。"
  },
  [80311117] = {
    id = 80311117,
    name = "在探险者群体中，流传着许多关于它的故事和传闻。\n无论是它巨山般的体型，还是足以摧毁一切的力量，都时常被人们提起。\n那些亲眼见过它的探险者，无不被它的强大所折服。\n据说在面对它的时候，能够不逃走，就足以称得上勇敢了。"
  },
  [80311119] = {
    id = 80311119,
    name = "公会boss，灾厄级魔物的简介"
  },
  [80311120] = {
    id = 80311120,
    name = "公会boss，灾厄级魔物的简介"
  },
  [80311121] = {
    id = 80311121,
    name = "公会boss，灾厄级魔物的简介"
  },
  [80311201] = {
    id = 80311201,
    name = "魔球兽长有标志性的如同晶石球般的身躯，看似笨拙憨厚，实则凶残暴戾。\n它们平时蛰伏于山林草木之间，一旦有猎物出现时，便会腾空而起，进行围猎。\n魔球兽的实力非常诡异，能够轻易穿透目标的外层防护，直接对其精神展开攻击，\n面对它们时，稍有不慎，便可能令自己陷入危机。"
  },
  [80311202] = {
    id = 80311202,
    name = "深渊众多魔物中，投石兽的实力并不出众，但它们顽劣狡诈的性格却很少有魔物可以比拟。\n投石兽非常喜欢四处破坏，惹是生非，给探险者制造了不少麻烦。\n每当探险者想要彻底剿灭它们时，它们便会飞快地消失于山林荒野，\n待人们放弃追剿，它们又会卷土重来，继续制造新的麻烦。"
  },
  [80311203] = {
    id = 80311203,
    name = "炎岩铁甲浑身长满坚硬的甲壳，整个身躯犹如一个巨大的铁球。\n当它面对强敌或者休息时，便会蜷缩身躯，变成一个球状物强化自身的防护。\n炎岩铁甲性格暴戾，极为好战，\n在它的生活区域，任何令它感到不满的存在，都可能成为被它攻击目标。"
  },
  [80311204] = {
    id = 80311204,
    name = "刺尾凶兽浑身被甲壳覆盖，长有一条粗壮的长尾，在尾巴末端长有独眼。\n平时它们会在地下潜行，仅将尾巴露出地面，\n在遭遇敌人或者发现猎物之后，它们才会从地下钻出，全力应战。\n倘若遭遇棘手的敌人，它们又会伺机潜入地下遁逃，是一种极为狡猾的魔物。"
  },
  [80311205] = {
    id = 80311205,
    name = "绯冠地精的肢体修长有力，让它们拥有了在各种区域都能快速移动的能力。\n因此在一些普通魔物难以到达的区域，也能发现它们活动的痕迹。\n它们极为狡猾阴险，即便发现猎物也绝不会贸然行动，\n而是躲在暗中窥探，寻找最佳的出手时机，力求一击制敌。\n此外，它们的能力极为诡异，如果轻敌大意，很容易为自己带来致命危机。"
  },
  [80311206] = {
    id = 80311206,
    name = "赤角魔偶拥有强壮而灵巧的双臂，可以将身边的任何物品当作武器投掷。\n它们生性顽劣、蛮横，时常会在活动区域随意投掷，经常招惹到其他目标。\n倘若招惹到实力平平的目标，赤角魔偶丝毫不会在意，反而会变本加厉，展开更加凶猛的攻势。\n但是如果招惹到了那些强大的存在，赤角魔偶则会迅速遁逃，不给对方报复的机会。"
  },
  [80311207] = {
    id = 80311207,
    name = "巨峰兽长有岩石般的甲壳，后背高高隆起，远远看去犹如行走的小山丘。\n它们的性格相对温和，很少主动攻击其他目标。\n但如果有任何存在干扰它们的行动，巨峰兽则会瞬间变得狂暴，对目标展开疯狂攻击。\n鉴于它们发狂时所展现出的强大实力，无论探险者还是其他魔物，都很少主动招惹巨峰兽。"
  },
  [80311208] = {
    id = 80311208,
    name = "暴爪凶兽浑身长满角刺，双臂长有利爪，极具攻击性。\n它们性格暴戾、凶狠，时常主动袭击其他目标，\n对它们而言，除了同族之外的其他任何存在，都可以成为它们袭击的目标。\n即便是面对那些实力更强大的存在，暴爪凶兽也毫不畏惧，\n甚至，它们在和强大的对手战斗时，会变得非常兴奋，展现出更强大的力量。"
  },
  [80311209] = {
    id = 80311209,
    name = "迅魔龙身躯修长，长有巨大的双翼，动作极其灵活、迅猛，能在瞬间爆发出强大的力量。\n它对食物非常挑剔，喜欢一次性猎杀许多目标，然后挑选其中最优质的作为食物。\n除了猎食之外，迅魔龙很少外出活动，它们对自身之外的事物并没有太多兴趣。\n因此，只要不主动招惹迅魔龙，保持足够的谨慎，即便在它们生活的区域活动也不会有太大的危险。"
  },
  [80311210] = {
    id = 80311210,
    name = "湮灭者的身躯犹如一个巨大的眼球，周围长满了手臂。\n通过众多手臂和眼球般的身躯，它能施放出诸多诡异而强大的魔法。\n同时，它还拥有极强的感知能力，往往能在目标尚未发现它时，便抢先发动攻击。\n对湮灭者而言，任何可能存在威胁的生物，都需要及时消灭，\n因此，它时常会突然对别的存在发起进攻，非常难以防范。"
  },
  [80311211] = {
    id = 80311211,
    name = "迷途者时常出现在深渊中一些荒野区域，它们拖着长长的双臂四处飘荡，犹如彷徨的亡灵。\n它们只会追逐自己感兴趣的存在，对于其他任何事物都毫不关心。\n即便在它身边激战，只要未波及到迷途者，也没有让它产生兴趣，它也只会毫不在意地飘过。\n但是，一旦它们发现自己感兴趣的目标，\n即便距离还很远，它们也会急不可耐地展开攻击。"
  },
  [80311212] = {
    id = 80311212,
    name = "长期蛰伏于巢穴，很少现身深渊，但却时常被人们提起。\n每当它现身时，总会带来无数灾难和毁灭。\n它巨大的身躯周围弥漫着灼热的气息，没有任何生灵敢轻易接近。\n当然，即便没有那灼热的气息，也没多少探险者或者魔物愿意直面这位恐怖的存在。"
  },
  [80311213] = {
    id = 80311213,
    name = "它时常伫立在自己的领地中，远远看去，犹如一位眺望着远方的贵族。\n不过在那贵族般优雅稳重的表象之下，是它凶残暴虐的本质。\n对深渊中诸多生灵而言，它就如同残暴的君主。\n贪婪地吞噬一切，给这片大地带来源源不断的恐惧。"
  },
  [80311214] = {
    id = 80311214,
    name = "傲慢、残暴，如同凶恶的屠夫，将所有令它不满的存在撕碎。\n即便是那些强大的魔物，也不敢轻易招惹这位恐怖的存在。\n不过它平时喜欢呆在自己的巢穴内，很少四处游走。\n只要在行动时能避开它的巢穴，与它遭遇的概率还是可以明显降低。"
  },
  [80311216] = {
    id = 80311216,
    name = "它的名字时常被探险者们提起，但真正有勇气直面它的人却寥寥无几。\n在各种传闻中，它都是凶残暴虐的代表。\n在它绝对的力量面前，勇气变成了鲁莽，决心也显得多余。"
  },
  [80311218] = {
    id = 80311218,
    name = "公会boss，灾厄级魔物的简介"
  },
  [80311219] = {
    id = 80311219,
    name = "公会boss，灾厄级魔物的简介"
  },
  [80311220] = {
    id = 80311220,
    name = "公会boss，灾厄级魔物的简介"
  },
  [80311301] = {
    id = 80311301,
    name = "相较于深渊中其他暴戾凶猛的魔物，朽木兽显得更为狡诈阴险。\n通常它会找个阴暗的角落伪装起来，\n随时准备对靠近自己的猎物发起致命攻击。"
  },
  [80311302] = {
    id = 80311302,
    name = "刀足兽是一种常见的魔物，性格暴戾凶悍，时常在深渊四处游走。\n它们对猎物极为执着，一旦被盯上便很难摆脱。\n刀足兽的单体实力并不算出色，\n但当它们成群结队行动时，即便是老练的探险者，也只会以最快的速度逃命。"
  },
  [80311303] = {
    id = 80311303,
    name = "遁地魔灵浑身被坚硬的甲壳包裹，口中利齿可以轻松咬碎树木岩石。\n它们非常善于在地下潜行，每当它们出现在人类聚集区，便会给建筑带来巨大破坏。\n令许多在深渊中生活的人深受其害。\n人们数次组织起来想要将它们剿灭，然而它们诡秘的行踪却令那些剿灭行动一次次落空。"
  },
  [80311304] = {
    id = 80311304,
    name = "丛林巨像浑身被坚硬的甲壳包裹，犹如一尊岩石巨人。\n它们力量巨大，可以将身上的坚甲作为武器，给敌人以毁灭性的打击。\n不过丛林巨像的反应相对迟缓，\n如果遭遇它们时能够迅速撤离，丛林巨像不会轻易选择追击。"
  },
  [80311305] = {
    id = 80311305,
    name = "刺骨虫长有荆棘般的肢体和花朵般的巨口，\n只要是能够吞下的存在，都会被它们当作食物。\n它们生性残暴，时常在深渊四处游荡，寻找可以当作食物的猎物。\n倘若长时间没有进食，刺骨虫甚至会将所在区域内的草木当作食物。"
  },
  [80311306] = {
    id = 80311306,
    name = "扭曲魔藤拥有极具迷惑性的外表，当它们静止不动时看起来和树木非常相似。\n因此，它们平时会将自己伪装成树木，等待猎物主动靠近，趁其不备时发动突袭。\n它们实力强大，除了难以提防的诡异魔法，藤蔓般的手臂也会给对手带来巨大麻烦。\n有时候，扭曲魔藤也会遇到猎物迟迟不肯靠近的情况，\n每当这种时候，一些沉不住气的扭曲魔藤便会选择主动出击。"
  },
  [80311307] = {
    id = 80311307,
    name = "恐角戮兽身躯健硕，力量极其强大，头和前肢上的巨角便是它战斗时的最佳武器。\n它的脾气喜怒无常，任何一点风吹草动都可能令它变得狂躁。\n每当它发怒时，便会对周围目标进行无差别攻击，直至完全摧毁令它们感到不满的存在。\n而且恐角戮兽非常执拗，任何非致命的伤害都只会令它们变得更加狂暴。\n因此，对探险者和其他魔物而言，一旦招惹上恐角戮兽，如果无法快速结束战斗，只会令情况变得越发危急。"
  },
  [80311308] = {
    id = 80311308,
    name = "幽影戮兽躯体的关键部位都被银白的甲壳包裹，后背长有多对羽翼，看上去非常优雅、高洁。\n但它们其实非常好战，经常会主动招惹其他魔物，挑起战斗。\n肆无忌惮地行动为它们带来了不少敌人，有时候甚至会招惹到一些更加强大的存在。\n但幽影戮兽丝毫不会畏惧，不管面对怎样的敌人它们也会全力与之战斗。\n不过当它们战败后如果能侥幸存活，再一次和对方相遇时，幽影戮兽会选择主动回避。"
  },
  [80311309] = {
    id = 80311309,
    name = "伏地石灵的形象并不出众，远远看去犹如一堆长着杂草的石头，当它们静止不动时非常难以察觉。\n但它们的实力不容小觑，和其他同等级魔物相比毫不逊色。\n而且它们极为狡诈，时常利用自己的伪装偷袭过往目标，给探险者和其他魔物带来了不少麻烦。\n不过伏地石灵非常清楚自己的实力，从来不会对那些强大的目标动手。\n甚至当它们察觉危险临近时，会迅速躲避、遁逃。"
  },
  [80311310] = {
    id = 80311310,
    name = "悲鸣蔷薇长有藤蔓般的肢体，修长而灵活，背后长有一朵巨大、高洁的蔷薇。\n在它巨大的蔷薇中会施放出一种致幻的无形粉尘，\n一旦吸入这种粉尘，意志不够坚定的生物便会产生哀伤沮丧的幻觉，精神恍惚，毫无干劲。\n这种诡异而强大的能力，令不少实力比悲鸣蔷薇更加强大的存在也成为了它藤蔓下的亡灵。"
  },
  [80311311] = {
    id = 80311311,
    name = "在邪晶地龙的头部，长有一个硕大的圆形晶体，\n通过这个晶体，邪晶地龙能感应到广阔区域中的其他生物，同时它也能通过晶体施放出强大攻击。\n平时，邪晶地龙会选择阴暗的区域蛰伏起来，静静观察四周，寻找心仪的猎物。\n当它发现目标后，便会以雷霆之势向猎物发起攻击。\n倘若未能一击制敌，邪晶地龙则会快速蛰伏起来，耐心等待再次出手的机会。"
  },
  [80311312] = {
    id = 80311312,
    name = "种群缔造者、魔物的主母......在它的记录中总会出现许多类似的称呼。\n这绝非是对它的吹捧，在它存在的区域，往往会有许多魔物种群。\n这些种群无论遭受怎样的破坏，只要它无碍，很快便能恢复如初，甚至变得更加繁盛。\n它的所有行动都围绕着繁衍、生存进行。\n它的存在，便是诸多魔物种群得以存在、得以发展的基础。"
  },
  [80311313] = {
    id = 80311313,
    name = "对无数魔物和探险者而言，它是恐怖的象征。\n时常带着族群在各处战斗，抢夺领地和生存资源。\n不过它的行动并非是出于自身的兴趣，而是为了种群的发展。\n因此无论是开辟新的领地，还是守护现在的领地，它永远都会冲锋在前。"
  },
  [80311315] = {
    id = 80311315,
    name = "面目狰狞恐怖，犹如噩梦的化身，只要见过它的人，便很难将它从记忆中消除。\n不过想要见到它的机会并不多，它平时总是蛰伏在自己的领地内，很少外出活动。\n每当它被惊扰，或者主动外出活动时，对许多探险者和魔物而言，便是灾难的开始......"
  },
  [80311317] = {
    id = 80311317,
    name = "长期在自己的领地内巡视，犹如一位吝啬的领主，一遍遍盘点着自己的财产。\n对于那些觊觎自己领地的存在，它会毫不犹豫地出手。\n面对它强大的实力，大多数探险者和魔物都只能仓皇逃窜。\n然而在它绝对的速度面前，想要逃离，或许比战胜它更加困难。"
  },
  [80311319] = {
    id = 80311319,
    name = "公会boss，灾厄级魔物的简介"
  },
  [80311320] = {
    id = 80311320,
    name = "公会boss，灾厄级魔物的简介"
  },
  [80311321] = {
    id = 80311321,
    name = "公会boss，灾厄级魔物的简介"
  },
  [80311401] = {
    id = 80311401,
    name = "岩甲石灵拥有如同岩石一般的甲壳，一般攻击很难对它们造成伤害。\n它们看似笨拙的身躯，实际上有着极快的反应速度，一旦惹上它们很难摆脱。\n岩甲石灵的脾气极为暴躁，在它们活动范围内，\n任何使它们不满的存在，都将遭受它们的疯狂攻击。"
  },
  [80311402] = {
    id = 80311402,
    name = "对在深渊中受伤的探险者而言，需要担心的并非只有浊炁，\n那些被血腥味吸引而来的赤目凶兽才是更令人畏惧的存在。\n它们的肢体如同刀锋，可以轻易撕碎一切生物。\n而且，浓郁血腥味会使赤目凶兽陷入疯狂，成为更加难以对付的存在。"
  },
  [80311403] = {
    id = 80311403,
    name = "噬面虫双翼不大，飞行速度较慢，而且难以长时间飞行。\n不过它们的瞬间爆发力极为惊人，往往目标还没反应过来，它们便已突进至身前，使出致命攻击。\n此外，噬面虫对猎物异常执着，\n一旦被它们锁定，必将面对它们不死不休的攻击。"
  },
  [80311404] = {
    id = 80311404,
    name = "飘荡魔灵是一种非常特别的魔物，它们长有双翼，但平时却不会使用。\n而是将身躯和肢体收起，飘浮在低空，随风四处飘荡。\n当它们发现猎物，亦或在飘荡时遭受攻击时，飘荡魔灵才会展开双翼，自主行动。\n它们的速度极快，一旦被盯上便很难逃脱。"
  },
  [80311405] = {
    id = 80311405,
    name = "暗魔虫长有修长而尖锐的口器，可以轻松贯穿其他生物的躯体。\n它们攻击性极强，主要活跃在深渊中的一些阴暗区域。\n暗魔虫生性狡猾，比起和敌人正面战斗，它们更喜欢躲在阴暗处偷袭。\n如果偷袭失败，或者感觉难以战胜对手，它们便会借助环境掩护，快速撤离。"
  },
  [80311406] = {
    id = 80311406,
    name = "无垢者全身被洁白的甲壳包裹，表面点缀有精致的花纹，远远看去极为优雅、高洁。\n它的性格狡诈、谨慎，不管遇到任何情况都会优先考虑自身安危。\n平时，它喜欢肆意猎杀自己领地中的其他魔物，但基本都只会对实力明显低于自己的目标动手。\n面对那些和自己实力相似或难以揣摩的目标，\n无垢者则不会轻举妄动，甚至会做好随时逃遁的准备。"
  },
  [80311407] = {
    id = 80311407,
    name = "巨掌凶兽的双臂强劲有力，足以轻松击碎坚硬的岩石。\n它们生性残暴，极具攻击性，时常入侵其他魔物的巢穴，挑衅其他魔物。\n这种行为为它带来了许多敌人，甚至会招惹到一些难以抗衡的存在。\n但巨掌凶兽毫不畏惧，无论面对怎样的敌人，它都不会退却。"
  },
  [80311408] = {
    id = 80311408,
    name = "凶刃戮兽的双臂四肢以及身躯关键部位都被银白的甲壳包裹，外形威武俊朗。\n它很喜欢热闹，倘若在它生活区域发生了激烈的战斗，那凶刃戮兽一定会前往观望。\n当然，它也并非只是观望，它会静静等待战斗决出胜负，再以雷霆之势向胜者发起进攻。\n对凶刃戮兽而言，在战斗中获胜的一方才有资格成为它的猎物。\n不过倘若战斗太过持久，或者让凶刃戮兽失去兴趣，它也会直接插手，将双方一同覆灭。"
  },
  [80311409] = {
    id = 80311409,
    name = "幻象恶魔的身躯犹如一团扭曲的烟雾，表面长满了密密麻麻的眼睛。\n它的每一个眼睛都拥有强大而诡异的能力，任何直视它的生物，都会被它那诡异的力量所影响。\n即便是那些实力比它更强大的存在，倘若太过大意，也依然难以抵挡。\n平时幻象恶魔喜欢四处飘荡，肆意施放能力，然后戏弄那些被它所影响的目标。\n当它尽兴之时，便会以残忍的手段将那些被影响的目标全部杀害。"
  },
  [80311410] = {
    id = 80311410,
    name = "秽面邪灵犹如在深渊中飘荡的精灵，看似人畜无害，实则极其凶残。\n它们在战斗时极为狡猾，喜欢利用草木地形之类的作为掩护，趁目标尚未觉察时发起突袭。\n而且秽面邪灵的大多数攻击都属于临时起意，任何出现在它们视野中的生物都可能成为被攻击的目标。\n所以，对深渊中的探险者和其他魔物而言，一旦进入秽面邪灵活动的区域，\n就必须打起精神，保持警惕，以提防它们的偷袭。"
  },
  [80311411] = {
    id = 80311411,
    name = "生性孤傲，实力强大，加之英武的身姿，被不少人崇拜。然而作为深渊魔物中的至高存在，其本身极其危险。任何贸然接近它的人或魔物，都会遭受攻击。而且一旦被它认定为挑衅，那么将会承受它不死不休的追击。"
  },
  [80311501] = {
    id = 80311501,
    name = "黑甲地精浑身长满坚硬的甲壳，当它蜷缩起来时就如同一块岩石，对手很难击破。\n而当它们和敌人战斗时，肢体上的甲壳又成为了它们最佳的武器，足以给敌人带来巨大伤害。\n不过，它们实力虽然强大，但却非常胆小，任何突发情况都可能令它们受到惊吓。\n每当受到惊吓时，它们便会立即将身躯蜷缩，许久才会再次展开。"
  },
  [80311502] = {
    id = 80311502,
    name = "巨口凶兽极为好战，任何出现在它眼前的目标都可能成为它的下一个袭击对象。\n它们凭着本能在深渊四处游荡，寻找心仪的猎物和对手。\n不过巨口凶兽虽然好战，但在战斗时却极为谨慎。\n面对那些难以抗衡的强大对手时，它们会寻找一切机会逃跑，绝不轻易死战。"
  },
  [80311503] = {
    id = 80311503,
    name = "斑斓地精是一种特别的魔物，当它们静止不动时，身上的颜色会根据周围的环境改变，和环境融为一体。\n利用这样的特性，它们隐匿在深渊各处，待猎物经过时，再突然暴起发动攻击。\n在同等级魔物中，斑斓地精的单体实力并不算出色，\n但凭借自身优秀的伪装，也让它们成为了任何对手也不敢小觑的存在。"
  },
  [80311504] = {
    id = 80311504,
    name = "窥探魔眼浑身长满眼睛，犹如由眼球组成的恶魔，极为恐怖。\n它的每一个眼睛都拥有诡异而强大的能力，\n除了施放魔法，任何长时间直视它们的生物，都可能被它所影响，造成精神崩溃。\n此外，它的眼睛还拥有极其敏锐的洞察力，任何细微的变化也逃不过它的眼睛。\n和它战斗时，任何伪装和隐匿都将变得毫无意义。"
  },
  [80311505] = {
    id = 80311505,
    name = "和许多主动追寻猎物的魔物不同，蚀骨花仙很少会主动出击，\n它们很多时候都会静止不动，利用自己的伪装，等待猎物主动靠近。\n平时，蚀骨花仙会将身躯埋入地下，张开巨口伪装为一簇盛放的鲜花，引诱猎物。\n待对方进入攻击范围，它便会迅速闭合巨口，将猎物吞下，不留一点痕迹。"
  },
  [80311506] = {
    id = 80311506,
    name = "灰壳地魔的肢体极具韧性，平时会被它收缩至体内，将自身伪装为一块圆石。\n在非必要的时候，它不会轻易舒展肢体，即便需要移动时，通常也是采用翻滚的方式。\n平时灰壳地魔会寻找一个自己满意的区域停下，伪装成石头一动不动。\n在捕食之外，它很少主动出手袭击过往目标，更多时候只会静静的观看周围发生的一切。\n如果在它静止时受到了任何打扰，它则会变得非常愤怒，绝不会轻易放过打扰它安宁的目标。"
  },
  [80311507] = {
    id = 80311507,
    name = "骨面战鬼性格暴戾，极其凶残好斗，因而被探险者赋予了“战鬼”之名。\n它们如同攻守兼备的战士，身躯关键部位被坚硬的甲壳包裹，肢体则犹如利刃和镰刀。\n骨面战鬼对未曾见过的生物拥有极强的好奇心，不过这种好奇是出于将对方当作战斗的对手。\n每当它发现自己从未见过的存在，便会立即发起进攻。"
  },
  [80311508] = {
    id = 80311508,
    name = "猎魂凶兽动作敏捷，行动时悄无声息，宛如深渊中的幽灵。\n它们的正面战斗实力并不算出色，但神出鬼没的行事作风也令它们极难防范。\n猎魂凶兽一旦盯上目标，便会跟随、潜伏在目标周围，耐心等待目标放松大意时再发起突袭。\n即便是那些实力明显强于它们的存在，也时常在它们的偷袭下丧生。"
  },
  [80311509] = {
    id = 80311509,
    name = "异足戮兽浑身都被甲壳包裹，肢体修长宛如尖刺，\n这些灵活而尖锐的肢体让它可以在各种区域自由移动，也能作为武器轻易洞穿敌人的身躯。\n但对探险者而言，它最可怕的地方却并非这些肢体，它巨口所施放的魔法才更加令人感到畏惧。\n强大的实力令异足戮兽在深渊中四处横行，任何令它不满的存在都会遭受它的攻击。"
  },
  [80311510] = {
    id = 80311510,
    name = "无面梦魇形象怪异，身躯扭曲而恐怖，宛如地狱的使者。\n它的性格非常恶劣，喜欢袭击其他生物的聚集地取乐，\n深渊中许多魔物的领地以及人类的聚集地都曾遭受无面梦魇的袭击。\n为此，探险者曾多次组织围剿无面梦魇，\n但它们实力强大，且行踪飘忽不定，最终也只能不了了之。"
  },
  [80311511] = {
    id = 80311511,
    name = "时常游荡于深渊，将其他弱小存在当作取乐的目标。\n对大部分探险者和魔物而言，它就像是行走于深渊的死神，四处散播死亡和恐惧。\n不过它固然可怖，但如果能在发现它时及时回避，大概率能够逃离。\n也因此，它成为了同等级魔物中，拥有较多接触记录的存在。"
  },
  [80311703] = {
    id = 80311703,
    name = "外表极具迷惑性，在非必要时很少移动的魔物。\n自身攻击性不强，但战斗实力不容小觑。\n一旦感受到威胁便会全力回击，即便是面对比自己强大很多的存在也毫不畏惧。"
  },
  [80311704] = {
    id = 80311704,
    name = "外形奇特，整体犹如一团飘忽的阴影，最初曾被探险者当作幽灵。\n它们能力古怪，动作敏捷，对新人探险者而言是一种非常危险的存在。\n不过同其他魔物相比，小影并不算凶残。\n大部分时候它们更像是凭借自己的兴趣玩闹，当它们对目标丧失兴趣，便会丢下目标离去。"
  },
  [80321001] = {
    id = 80321001,
    name = "古岩兽主要依靠自我意志和本能在深渊四处活动，大多数时候都是独自行动。\n但如果同一区域中出现多只古岩兽时，它们会选择彼此协作，共同应对该区域中的威胁。\n当它们受到本能或自我意志的驱使，需要迁徙时，则会各自分散，丝毫不会顾及其他同族。\n平时，古岩兽在没有感受到威胁、也无需进食的时候，\n它们会选择蜷缩起来，静止不动，直至需要行动的时刻到来。"
  },
  [80321002] = {
    id = 80321002,
    name = "裂刃兽习惯于结群而居，拥有着极强的种群意识，每一个种群中都会有一个头领般的存在。\n头领是裂刃兽种群的核心，也是对应种群中个体实力相对突出的存在，\n整个种群都会以它的意志为主，在它的带领下活动。\n任何挑战头领失败，或令头领不满的裂刃兽都会被驱逐，\n这些被驱逐的个体在遇到其他落单的裂刃兽时，便会结伴而行，确认新的头领，组成新的种群。"
  },
  [80321003] = {
    id = 80321003,
    name = "石睛兽属于独居魔物，通常情况下是独自行动，但在遭受威胁或进行捕猎时，也会选择和其他同族联手。\n它们没有领地概念，更多的是游荡至一个地方，便在该区域短暂停留。\n在游荡过程中，如果遇到感兴趣的事物，石睛兽会选择停下观看。\n当失去兴趣时便会继续向其他区域移动，宛如一个没有目的地的旅人，在深渊中无止尽地游荡。"
  },
  [80321004] = {
    id = 80321004,
    name = "巨翼兽属于独居魔物，没有族群和固定的生活区域。\n为了寻求生存空间，它们会经常迁徙。\n倘若它们在迁徙中邂逅了其他同族，它们会根据实际情况选择暂时共存，或者视而不见。\n为了争夺猎物和生存机会，巨翼兽时常也会和其他魔物发生争斗。\n它们一旦感觉不敌，便会立马逃离，很少会死战到底。"
  },
  [80321005] = {
    id = 80321005,
    name = "瑰石兽喜欢结群而居，但它们的种群并不纯粹。\n它们很喜欢依附于那些拥有自己领地的强大魔物，在对方的庇护下生存。\n倘若依附的对象死亡，瑰石兽则会一哄而散，各自寻找新的依附对象。"
  },
  [80321006] = {
    id = 80321006,
    name = "碎骨凶兽生活在相对固定的区域，大多喜欢独居，很少和其他同族往来。\n即便同一区域中存在多只碎骨凶兽，彼此行动也只会以各自的意志为主。\n不过，如果它们生活的区域遭受威胁，亦或看到其他同族陷入困境时，\n周围所有的碎骨凶兽都会倾巢而出，共同对付敌人。"
  },
  [80321007] = {
    id = 80321007,
    name = "大多数妖鬼喜欢独来独往，跟随自己的意志和本能而行动。\n它们没有固定的活动区域，每当完成猎食后，便会就近寻找一处心仪的地点蛰伏起来。\n如果同一片区域中出现了多只妖鬼，它们彼此间也不会有太多协作，但也不会存在纷争。\n它们对于同族虽然并无太强的认同感，但也绝不会轻易对同族出手。"
  },
  [80321008] = {
    id = 80321008,
    name = "幻晶石灵没有固定的活动区域，通常会根据环境变化自主迁徙。\n它们习惯与其他同族结群而居，联手对付所在区域中的其他存在。\n不过它们对于同族的认同感并不算强，当区域内的猎物减少时，它们甚至会彼此争斗。\n如果所在区域遭受重大威胁，幻晶石灵会一哄而散，各自逃跑。\n成功逃走的幻晶石灵会寻找新的生存区域，并与其他幻晶石灵组建新的族群。"
  },
  [80321009] = {
    id = 80321009,
    name = "魔羽属于群居类魔物，无论捕食、休息都喜欢和同族一起。\n但在它们的族群中，并没有头领一类的存在。\n因此，有时候一些魔羽也会出于自己的意志，暂时脱离群体单独活动。\n当它想要回归时，只需要寻找一个魔羽族群，融入其中即可。"
  },
  [80321010] = {
    id = 80321010,
    name = "尖角地精并无太多自我意志，它们所有的行动几乎都是遵从于族群头领的指示。\n对它们而言，依附于强大的魔物，在对方的庇护下生活便是它们的生存法则。\n因此，在尖角地精的族群中，头领往往是那些比它们更为强大的魔物。\n倘若头领弃它们而去，整个族群也会随之解散，\n四散的尖角地精会不断游荡，寻找新的魔物依附。"
  },
  [80321011] = {
    id = 80321011,
    name = "每一头鬼面魔蛛都会占据一片较大的区域作为自己的领地。\n平时，它不会限制其他魔物进入自己的领地活动，但这些魔物进来后就别想离去。\n在鬼面魔蛛看来，这些进入自己领地的存在，都是自己蓄养的食物。\n食物可以在自己的领地中随意活动，但绝不能脱离自己的掌控。"
  },
  [80321012] = {
    id = 80321012,
    name = "接引者大多都是独自活动，它会追随着自己的本能四处游荡，并不会在一片区域长期停留。\n不过，如果在游荡时遇到了无垢者，接引者也会选择在对方的领地中滞留一段时间。\n接引者拥有着极强的战斗欲望，对它而言，除了同族之外的所有目标都可以作为猎杀对象。\n因此，在它活动的区域，许多魔物闻风而逃，或者蛰伏不出，直到接引者离去。"
  },
  [80321013] = {
    id = 80321013,
    name = "凶镰主要活跃在草木茂盛的地区或者一些阴暗地区，它们习惯以小群体为单位构建自己的领地。\n当领地遭到威胁时，凶镰会集体出动，共同守护领地。\n平时它们则依据各自的意志在领地中自由活动。\n不过，如果长时间缺少猎物，凶镰也会选择暂时离开领地搜寻猎物。\n完成猎食后再迅速返回，不会轻易放弃领地和族群。"
  },
  [80321014] = {
    id = 80321014,
    name = "银脊恶魔是一种非常谨慎的魔物，它对除了自己之外的其他存在都非常警惕，即便同族也不例外。\n因此，一片区域中通常只会存在一头银脊恶魔。\n银脊恶魔并不会对自己领地中的其他魔物赶尽杀绝，只要选择依附于它，便能获得暂时的安宁。\n当领地受到威胁时，银脊恶魔便会召集依附自己的魔物一起攻击对方。\n倘若觉察到敌人太过强大，银脊恶魔则会选择驱使依附自己的魔物应战，而自己则快速逃遁。"
  },
  [80321015] = {
    id = 80321015,
    name = "咏叹蔷薇犹如随性的游吟诗人，依凭自己的意志四处游走。\n它从来不会在一个地方长期停留，即便那里有它渴求的一切。\n它生性孤高、傲慢，只会在意自己感兴趣的存在，除此之外，对一切都毫不在意。\n不过，如果有任何魔物主动招惹它，或者败坏了它的兴致，\n咏叹蔷薇则会毫不留情地将其抹去。"
  },
  [80321016] = {
    id = 80321016,
    name = "群岭之主生性高傲霸道，在它眼中，自己便是最为高贵的存在，是无数蝼蚁的主宰。\n因此它对于深渊中的其他生物极为不屑，只有向它臣服的魔物才有资格在它的领地中生存。\n然而即便是臣服于它的魔物，群岭之主也不会真正在意对方，\n对它而言，接纳这些魔物只是为了彰显自己的尊贵地位，并非是真的需要这些随从。\n当这些随从做出任何令它不满的行为时，群岭之主会毫不犹豫地赐予对方毁灭。"
  },
  [80321017] = {
    id = 80321017,
    name = "巡道荒神生性凶残，对其他生物的生命力有着强烈渴望，\n特别是在它感到饥饿时，那种对生命力的渴求会驱使它们做出各种疯狂举动。\n因此它时常会离开巢穴四处游荡，寻找能为自己提供庞大生命力的猎物。\n在选择猎物时，比起生命力稍强的个体，巡道荒神更喜欢数量庞大的魔物种群。\n它诡异的能力能使整个猎物群体陷入幻觉，对它顶礼膜拜，然后遵从它的意志，献出生命。"
  },
  [80321101] = {
    id = 80321101,
    name = "食魂兽是深渊中一种奇特的存在，它们在幼体阶段便会寻找那些强大的魔物寄生，依靠吞噬宿主成长。\n待成熟时，宿主的身躯便会被它占据、融合，成为更加强大、恐怖的存在。\n因其凶残的个性，食魂兽偶尔也会和同族发生冲突，\n但一旦出现强敌，它们便会选择放下矛盾，和同族一起行动。"
  },
  [80321102] = {
    id = 80321102,
    name = "大多数黑骨兽都是结群生活，但种群规模不会很大。\n它们长期生活在阴暗之中，主要依靠声音辨识物体和环境，\n因此，不管在怎样黑暗的环境中，黑骨兽也能行动自如。\n它们善于利用阴暗的环境掩盖自己的行踪，借此对敌人发动袭击。"
  },
  [80321103] = {
    id = 80321103,
    name = "大多数裂面凶兽都会选择和其他同族结群而居，占据一片固定区域作为种群的领地。\n在领地没有受到威胁时，它们便会依照各自的意志在领地内自由活动，\n一旦领地遭受威胁，领地中的所有裂面凶兽便会集结起来共同对付敌人。"
  },
  [80321104] = {
    id = 80321104,
    name = "狂暴魔灵极为好斗，对同族并无太多认同感，大部分时候都是独自行动。\n它们游荡在深渊各地，寻找能满足它们战斗欲望的对手。\n倘若长期无法找到满意的对手，它们甚至会对遇到的同族发起攻击。\n它们对于力量极其崇拜，如果在和别的魔物战斗时落败且存活了下来，\n它们便会选择成为对方的附庸，跟随对方一起活动。"
  },
  [80321105] = {
    id = 80321105,
    name = "骨甲凶兽主要生活在深渊中的沼泽湿地或者其他近水区域，通常会选择和其他同族结群而居。\n但它们对同族其实并无太多认可，群居只是为了掌控更多生存区域，只能算是它们同族之间的合作。\n这种合作极不稳定，平时面对一些棘手的敌人时，它们或许会选择彼此协作，\n可是一旦面对那些强大的存在，骨甲凶兽则会果断舍弃同族，各自逃离。"
  },
  [80321106] = {
    id = 80321106,
    name = "碑魔通常会和其他同族一起，在深渊中的阴暗区域结群而居。\n它们生性较为胆小，平时都会蛰伏在地里一动不动，只有在需要捕食时才会以小团体的形式外出活动。\n当活动结束，它们便会立马折返聚居地，潜伏于地下，直到下一次需要活动的时候。\n当它们聚居区遭受威胁时，区域内所有的碑魔都会倾巢而出，将敌人击退。\n倘若面对难以抗衡的强敌，碑魔则会以各自的意志选择依附或者逃离。"
  },
  [80321107] = {
    id = 80321107,
    name = "滚地石精对同族拥有极强的认同感，但自我、古怪的脾气却令它们难以和其他同族长久相处，\n因此它们大多数时候都是独自活动。\n当滚地石精遇到其他陷入困境的同族时，它们会选择放弃自己的目的，全力协助同族。\n面对那些难以抗衡的强敌，如果滚地石精是独自战斗，它会不断寻找逃跑的机会，\n可是如果它和其他同族一起战斗，即便有逃跑的机会，它也会选择留下战斗到底，绝不抛弃同族。"
  },
  [80321108] = {
    id = 80321108,
    name = "大多数粉碎者都喜欢独来独往，依凭自己的意志自由活动。\n它们并不排斥和同族生活，但也不算喜欢，即便共同生活在一片区域，彼此也不会有太多往来。\n粉碎者很喜欢抢占其他魔物的巢穴，特别是那些舒适的巢穴，它们遇到后绝不会错过。\n它们和同族之间很少因为猎物或者对手争斗，反而时常会因为巢穴而大打出手。\n不过不管怎样的巢穴，它们居住一段时间后都会嫌弃，于是便会将其毁掉，继续抢夺新的巢穴。"
  },
  [80321109] = {
    id = 80321109,
    name = "妖尾戮兽时常会与同族组成小群体狩猎，但在狩猎之外，它们大多数时候都是独自行动。\n它对同族并无太多认同感，对它来说，和同族协作只是提高效率和确保安全的手段。\n当妖尾戮兽集体行动时，如果有同族遭遇危机，\n其他妖尾戮兽只会根据情况选择趁机袭击猎物或者立即遁逃，几乎不会考虑救援。"
  },
  [80321110] = {
    id = 80321110,
    name = "许多骨甲龙都喜欢在沼泽湿地之类的区域构筑自己的巢穴，\n它们非常大方，时常会接纳一些四处游荡的同族，与对方分享自己的巢穴。\n因此在同一个巢穴中，可能会有多头骨甲龙存在。\n此外，骨甲龙很少主动对其他目标出手，只要不打扰自己，它们便不会在意其他魔物的活动。\n因此在它们的巢穴周围，也会有不少魔物活动。"
  },
  [80321111] = {
    id = 80321111,
    name = "黯面邪灵时常和其他同族一起四处飘荡，没有固定的活动区域。\n每当它们发现自己感兴趣的存在，便会自行脱离群体，独自行动。\n有时，黯面邪灵也会被一些强大的魔物所吸引。\n如果感觉到对方并不排斥自己，黯面邪灵则会主动依附，成为对方的附庸。"
  },
  [80321112] = {
    id = 80321112,
    name = "摄魂恶魔时常独来独往，行踪诡秘，很少在一个区域长期停留。\n它和同族之间的关系算不上亲密，但在野外相遇时，偶尔也会一起活动。\n不过对摄魂恶魔而言，自己的意志高于一切。\n不管何时，只要它发现了感兴趣的存在，它便会立马舍弃当前正在做的事，全力追逐新的目标。"
  },
  [80321113] = {
    id = 80321113,
    name = "混沌行者的性格极其恶劣，时常凭借自己妖娆、美丽的身形引诱深渊中的其他生灵。\n许多生灵都会因为好奇，或者出于对美丽事物的向往而接近它。\n然而一旦进入混沌行者的攻击范围，则会被它强大的力量所压制，从而成为它戏耍的目标。\n不少生灵都难以承受它的折磨，在被戏耍的过程中死去，而侥幸存活下来的，结局也早已注定。\n当混沌行者对被引诱的生灵失去兴趣时，便会毫不犹豫地将其杀掉。"
  },
  [80321114] = {
    id = 80321114,
    name = "虚无吞噬者长期浮游于高空，茫茫然前行，没有目的，也没有原因，似乎本能就是如此。\n只有在它感到饥饿或者发现感兴趣的事物时，才会显现于地面，张开大口，肆无忌惮地吞噬一切。\n对它而言，这是一种本能而自然的行为，但对深渊万物而言，却是一场难以抵挡的灾难。\n无论实力怎样强大的存在，只要躲闪不及，都可能葬身在它那恐怖的巨口之中。\n虽然虚无吞噬者大多数时候都是很茫然的行动，但如果被其他存在招惹，它也绝不会善罢甘休。"
  },
  [80321115] = {
    id = 80321115,
    name = "霜甲巨兽极为好战，经常在各地惹事生非，不过它招惹的对象几乎都是和自己实力相差不大的存在，\n对那些极为强大，或者极为弱小的目标，它并没有什么兴趣。\n凭借自身巨大、强壮的躯体，霜甲巨兽在许多战斗中都能稳稳占据上风，它为此颇为得意。\n但有时霜甲巨兽也会招惹上一些棘手的敌人，每当它陷入苦战，就会逐渐变得愤怒，失去理智，\n在这种情况下，它即便击败了敌人，也会继续对周围其他存在进行无差别攻击，直至将怒火彻底宣泄。"
  },
  [80321117] = {
    id = 80321117,
    name = "冰脊巨兽生性高傲，对自己之外的存在极为不屑，无论其他魔物做出怎样示好、依附的举动，它都从不回应。\n不过，它也不会随意对其他魔物出手，在它看来，那些蝼蚁般的存在根本不值得它在意。\n因此在冰脊巨兽的领地中，也生活着不少魔物，它们只要不主动招惹冰脊巨兽，便能得到暂时的安宁。\n但如果冰脊巨兽受到挑衅，它则会大发雷霆，对那些招惹自己的目标发动疯狂攻击，\n如果无法快速击败对手，冰脊巨兽会认为自己的尊严受到了侮辱，进而变得更加疯狂，誓必将周围存在的一切摧毁殆尽。"
  },
  [80321119] = {
    id = 80321119,
    name = "公会boss，灾厄级魔物的习性"
  },
  [80321120] = {
    id = 80321120,
    name = "公会boss，灾厄级魔物的习性"
  },
  [80321121] = {
    id = 80321121,
    name = "公会boss，灾厄级魔物的习性"
  },
  [80321201] = {
    id = 80321201,
    name = "魔球兽属于群居魔物，通常成群生活在相对固定的区域。\n平时它们会独立行动，当发现猎物或遭受威胁时，\n便会以特有的方式召集同伴，共同对付目标。"
  },
  [80321202] = {
    id = 80321202,
    name = "投石兽拥有较强的种群意识，它们会和同族一起构筑巢穴，共同生活。\n平时它们主要在巢穴周围活动，一旦发现了猎物或其他生物的据点、巢穴时，\n投石兽便会呼唤同族，倾巢而出，进行狩猎或者破坏。\n它们的行动看似嚣张无比，但实际上投石兽非常谨慎，一旦发现不敌对手，便会果断逃跑。\n当它们的巢穴被摧毁后，投石兽便会四处流浪，寻找其他同族重新集群。"
  },
  [80321203] = {
    id = 80321203,
    name = "炎岩铁甲虽然脾气暴戾，但对同族拥有较强的认同感，通常会和同族一起生活。\n它们会占据相对固定的区域作为领地，共同协作，守护族群。\n此外，炎岩铁甲虽然好战，但它们并不鲁莽，从来不会招惹那些极为强大的存在，\n甚至在遇到强大的魔物时，它们会选择带领族群依附对方，寻求对方的庇护。"
  },
  [80321204] = {
    id = 80321204,
    name = "刺尾凶兽时常独来独往，在深渊各地游荡，寻找猎物，没有固定的活动范围。\n每当它到达一个区域时，它会优先探查四周，确认是否存在自己难以抗衡的目标，\n倘若存在这样的目标，它则会快速遁逃，直至找到它认为安全的区域后，才会开始搜寻猎物。\n当它们在游荡中遇到其他同族时，偶尔也会联手行动一段时间，待需要迁徙时再各自分散。"
  },
  [80321205] = {
    id = 80321205,
    name = "绯冠地精属于群居魔物，通常以小族群为单位在相对固定的区域生活。\n在它们的生活区域外围，平时会有专门的个体负责巡视，\n一旦发现猎物或者遭受威胁，巡视的个体便会立即召集区域内的其他成员，共同对敌。\n绯冠地精对于自己未曾见过的存在会感到好奇，每当有新奇的目标出现时，\n它们便会在暗中窥探对方的一举一动，此时只要不招惹它们，绯冠地精便绝不会主动攻击 。"
  },
  [80321206] = {
    id = 80321206,
    name = "赤角魔偶脾气古怪、自我，无论是和同族还是其他魔物都很难相处，因此时常独自活动。\n它们没有领地、种群观念，所有的行动都是遵从于自己的意志或本能。\n当一片区域中存在多只赤角魔偶时，它们也会暂时集群活动。\n当所在区域生存条件开始恶化，或者被其他强大的魔物驱赶时，\n赤角魔偶则会立即离开，寻找新的生存区域。"
  },
  [80321207] = {
    id = 80321207,
    name = "巨峰兽对同类拥有极强的认同感，喜欢和同族结群生活。\n但它们没有固定的活动区域，平时就和没有目的地的旅行者一般，凭借着本能向未知的方向前行。\n在巨峰兽的旅途中，不断会有同伴根据各自的意志离去或者加入，整体规模变化不会太大。\n每当它们遭遇威胁时，所有的巨峰兽都会联合起来共同应对，\n只要威胁不消失，巨峰兽即便是战斗至最后一刻，也绝不会退缩。"
  },
  [80321208] = {
    id = 80321208,
    name = "大部分时候暴爪凶兽都是独自行动，只有在一些特殊区域，它们才会选择和同族组成小群体行动。\n它们对于同族拥有较强的认同感，从来不会对同族出手。\n即便和同族因为猎物等问题产生争执，它们也只会相互对峙、嘶吼。\n暴爪凶兽极其崇尚力量，倘若它们在和其他魔物的争斗中落败，它们会对击败自己的魔物变得极为顺从。\n不过，也存在不少脾气倔强的暴爪凶兽，它们即便落败，也会选择死战到底。"
  },
  [80321209] = {
    id = 80321209,
    name = "迅魔龙喜欢在地势相对险要的地方构筑自己的巢穴，大多数时候都是独来独往，很少和其他同族往来。\n其实它们对同族有着较强的认同感，只是不愿意主动联系。\n在同一区域里，如果存在多头迅魔龙，它们会选择在同族的巢穴边构筑自己的巢穴。\n当其他同族遭受威胁、陷入困境时，周围的迅魔龙会集体出动，协助同族。"
  },
  [80321210] = {
    id = 80321210,
    name = "湮灭者对除了自己之外的生物存在较强的戒备心，即便是同族，它们也不会完全信任对方。\n因此在它的领地中，除了湮灭者自身之外，很少会有高等级魔物。\n平时湮灭者很少四处活动，凭借自身强大的感知力，它能轻松掌控领地中的一切。\n一旦领地被其他强大存在入侵，湮灭者会选择在远处疯狂攻击对方，倘若无法击退目标，它则会快速逃离。\n失去领地的湮灭者会根据情况选择入侵其他魔物的领地，或者选择成为其他强大魔物的附庸。"
  },
  [80321211] = {
    id = 80321211,
    name = "迷途者大多数时候都是独自行动，当它们在野外遇到其他同类时，偶尔会选择结伴而行。\n它们没有固定的活动区域，长期依凭自己的本能活动。\n当迷途者在行动中受到打扰时，它们会展开疯狂反击，无论对方如何逃遁，它们也不会轻易放弃。\n有时候迷途者也会对其他魔物产生兴趣，如果遭到对方排斥，它们则会将其杀害。\n倘若对方并不排斥它们，迷途者则会选择与目标共同生活一些时日，待感到无趣时便自行离去。"
  },
  [80321212] = {
    id = 80321212,
    name = "对探险者而言，魔焰领主是众多领主级魔物中极为神秘的存在，很少被人目击。\n其实它只是不喜欢外出活动，在非必要时几乎不会离开自己的巢穴。\n对那些在自己巢穴周围活动的魔物，只要不招惹自己，魔焰领主也很少干预。\n它看似温和，实际上极为暴躁易怒，任何一点动静都可能令它变得狂躁，进而对周围目标进行疯狂攻击。\n特别是那些打扰它安睡的存在，不彻底抹灭对方，魔焰领主绝不会轻易罢休。"
  },
  [80321213] = {
    id = 80321213,
    name = "荒芜公爵的领地范围极大，其中生活着众多依附于它的魔物。\n平时它会在领地中四处巡视，一旦发现不被自己掌控的外来者，便会果断出手将其抹杀。\n对它而言，领地便是自己的一切，任何冒然进入者都是自己的敌人。\n即便是面对那些实力极其强大的存在，它也丝毫不会妥协，\n为了捍卫自己的领地，它不惜与任何存在为敌。"
  },
  [80321214] = {
    id = 80321214,
    name = "在屠戮者的领地中，生活着不少想要依附于它的魔物，但屠戮者并不愿接受它们的附庸。\n对这些蝼蚁般的存在，屠戮者毫无兴趣，不过也不屑于对它们出手，便任由它们在自己的领地活动。\n对屠戮者而言，只有那些敢于主动向自己发起挑战的存在才是值得期待的对手。\n当它击败和自己势均力敌，甚至比自己更为强大的对手时，便会兴奋不已，四处耀武扬威。\n但是，如果挑战它的对手太过弱小，被它轻易击败，它则会觉得自己受到了轻视，进而大发雷霆，对周围其他存在宣泄怒火。"
  },
  [80321216] = {
    id = 80321216,
    name = "暴虐者生性残暴，非常喜欢猎杀其他魔物取乐，特别是遇到结群生活的弱小魔物，它从来不会错过。\n每当看到那些弱小的魔物在它的攻击下苦苦挣扎，或者仓皇逃窜时，暴虐者都会变得极其兴奋，\n进而展开更加疯狂地攻击，力求将对方赶尽杀绝，以此彰显自己的威严和强大。\n不过当屠戮者面对和自己势均力敌，甚至比自己更强大的对手时，它却会变得非常冷静，绝不会轻举妄动，\n它会摆出各种姿态威慑对方，倘若无法令对方退却，它则会在战斗中伺机逃遁，绝不轻易和对手死战。"
  },
  [80321218] = {
    id = 80321218,
    name = "公会boss，灾厄级魔物的习性"
  },
  [80321219] = {
    id = 80321219,
    name = "公会boss，灾厄级魔物的习性"
  },
  [80321220] = {
    id = 80321220,
    name = "公会boss，灾厄级魔物的习性"
  },
  [80321301] = {
    id = 80321301,
    name = "朽木兽属于独居魔物，没有领地观念，通常会跟随环境变化四处迁徙。\n不过，它虽然是独居，但并不代表它只会独自出现。\n朽木兽并不排斥和其他同族魔物一起生存，只是在行动时习惯以个体意志为主。\n在那些适宜它们生存的区域，往往存在许多朽木兽。"
  },
  [80321302] = {
    id = 80321302,
    name = "刀足兽广泛分布于深渊各地，过着以族群为单位的群体生活。\n但在群体生活的前提下，它们又有着相对较大的自由，\n时常独来独往，或三两只结成小队在族群所在区域的周围行动。\n当它们和大族群分散后，一旦遇到别的刀足兽，又会很自然地和对方汇合，形成新的族群。"
  },
  [80321303] = {
    id = 80321303,
    name = "遁地魔灵大多数时候都是结群行动，性格较为胆小，受到惊吓后会四处逃窜。\n它们没有固定的生活区域，每次行动结束后都会就近寻找一个阴暗偏僻的区域蛰伏起来。\n当受到威胁或族群需要再次活动时，它们才会继续行动。\n如果遁地魔灵在行动中和族群分散，它便会漫无目的地四处游荡，直至遇到其他遁地魔灵族群。"
  },
  [80321304] = {
    id = 80321304,
    name = "丛林巨像拥有极强的领地观念，它们会联合其他同族一起守护领地。\n它们在领地中拥有各自负责的区域，平时它们会各自巡视，一旦发现入侵者，便会立马进行驱离。\n倘若自身难以应付，丛林巨像则会召集领地内的其他同族，共同对敌。\n不过，如果那些极为强大的存在前往丛林巨像的领地常驻，\n它们则会选择依附于对方，借助对方的力量庇护自己所在的族群。"
  },
  [80321305] = {
    id = 80321305,
    name = "刺骨虫属于群居魔物，但没有自己的领地，通常会追随猎物四处迁移。\n当它们到达一片新的区域，会集体行动清扫该区域内的威胁，待威胁清除后再各自分散活动。\n倘若遭遇其他更强大的存在，刺骨虫会根据对方的态度，选择逃窜或者依附。\n当所在区域中的生物已无法满足刺骨虫种群生存时，它们便会再次集结，前往新的区域。"
  },
  [80321306] = {
    id = 80321306,
    name = "扭曲魔藤喜欢独自行动，与同族的关系算不上亲密。\n甚至，它们偶尔会因为猎物等问题发生争斗。\n不过扭曲魔藤面对一些较为棘手的敌人时，它们也会选择暂时放下成见，共同对付敌人。\n当有同族遭遇危机，周围的扭曲魔藤也会选择出手相助。"
  },
  [80321307] = {
    id = 80321307,
    name = "通常恐角戮兽会选择令自己感到满意的区域构建领地，一旦领地确认，它便很少再四处移动。\n对于领地中的其他魔物，只要它们不主动招惹自己，大多数时候恐角戮兽都不会在意。\n不过一旦这些魔物的行动让恐角戮兽感到不满，它便会彻底摧毁对方。\n恐角戮兽对同族拥有极强的认同感，当其他同族来到自己的领地时，恐角戮兽会慷慨接纳对方。\n因此在一些恐角戮兽的领地中，也会有多头恐角戮兽一起生活。"
  },
  [80321308] = {
    id = 80321308,
    name = "幽影戮兽从来不会在一个地方长期停留，为了寻找更多的对手，它喜欢在深渊各地游荡。\n当它在游荡中遇到其他同族时，有时会选择和对方共同活动一段时间。\n不过它们虽然对同族拥有较强的认同感，但彼此间偶尔也会因为猎物等问题引起冲突。\n所以幽影戮兽即便和同族共同行动，也难以维持太久，大多数时候仍是独自活动。"
  },
  [80321309] = {
    id = 80321309,
    name = "伏地石灵没有固定的活动区域，它们会选择和同族一起四处游荡、迁徙。\n当它们到达新的区域后，会优先和其他同族联手肃清区域中可能会带来威胁的目标。\n此后，便会依据各自的意志在区域内自由活动，直至下一次集体迁徙。\n当伏地石灵所在的区域遭遇难以应对的危机时，它们会选择四散奔逃，各自寻找生存的机会。\n逃散后的伏地石灵会不断游荡，直至找到其他同族，重新组建族群。"
  },
  [80321310] = {
    id = 80321310,
    name = "比起四处游走的咏叹蔷薇，悲鸣蔷薇更喜欢寻找一处自己喜欢的区域构建领地。\n在它强大实力的吸引下，不少魔物会选择依附于它换取生存机会，悲鸣蔷薇对此则是来者不拒。\n因此在悲鸣蔷薇的领地中生活着许多魔物，它们遵循悲鸣蔷薇的意志，协助它守护领地。\n对于其他同族，悲鸣蔷薇并不抵触，但也不算认同，\n任何想要染指它领地的存在，都将承受悲鸣蔷薇的怒火。"
  },
  [80321311] = {
    id = 80321311,
    name = "邪晶地龙对同族并无太多认同感，时常独自活动。\n不过如果它在野外和其他同族相遇，它们会根据周围猎物的情况选择联手或者竞争。\n当同区域中的其他邪晶地龙遭遇危机时，周围的邪晶地龙也会选择出手协助。\n但如果面对的敌人太过强大，周围的邪晶地龙则会果断舍弃同族，快速逃离。"
  },
  [80321312] = {
    id = 80321312,
    name = "异魔主母长期呆在自己的巢穴之中，平时很少外出活动。\n对它而言，不断繁衍新的魔物，维护种群的繁荣才是自己存在的意义。\n在它所在的种群中，它的意志便是唯一，不管有怎样的需求，都会由它繁衍出的魔物为它实现。\n此外，除了迁徙等少数行动外，异魔主母很少会亲自参与种群的活动，\n即便是种群遭遇危机，只要敌人尚未逼近身前，异魔主母也不会轻易出手。"
  },
  [80321313] = {
    id = 80321313,
    name = "在恐怖公活动的区域，往往会出现无数杀戮和纷争，\n不过和那些凭借自己兴趣而肆意杀戮的魔物不同，恐怖公的所有行动都是为了自己所在的种群。\n对它而言，守护种群所在的领地，为众多同族掠夺生存资源便是它的使命。\n任何妨碍它种群扩张的存在，都会被视作死敌，无论对方拥有怎样的实力，它也不会畏惧。\n每当种群遭遇危机，它都会在第一时间出现，身先士卒，率领同族魔物消灭一切威胁。"
  },
  [80321315] = {
    id = 80321315,
    name = "翠神长期在自己的巢穴中沉眠，很少外出活动，只要不惊扰它，它便不会在意其他任何事物。\n因此在它巢穴周围，生活着不少魔物，它们会在不惊扰翠神的前提下自由活动。\n倘若翠神在沉眠时受到惊扰，它便会大发雷霆，势必要将打扰自己的存在撕碎才肯罢休。\n如果无法找到对应的目标，它则会将怒火宣泄到周围其他目标身上。\n此外，当自己的领地受到威胁时，翠神也会从沉眠中醒来，与入侵者进行殊死战斗。"
  },
  [80321317] = {
    id = 80321317,
    name = "除一些必要活动之外，绿魔很少离开自己的领地，它很喜欢在领地中四处游走、巡视。\n对它而言，巡视过程中能感受到众多附庸者对自己的畏惧、崇敬，令它十分享受。\n而且频繁的巡视，也能让绿魔发现领地中那些不够完美的存在，\n它会毫不犹豫地将其摧毁，让所有的一切按照自己的意志发展，在它看来，任何无法掌控的存在都必须清除。\n对那些贸然进入自己领地的敌人，或者惦记自己领地的敌人，绿魔则会以最恐怖的手段将其处决。"
  },
  [80321319] = {
    id = 80321319,
    name = "公会boss，灾厄级魔物的习性"
  },
  [80321320] = {
    id = 80321320,
    name = "公会boss，灾厄级魔物的习性"
  },
  [80321321] = {
    id = 80321321,
    name = "公会boss，灾厄级魔物的习性"
  },
  [80321401] = {
    id = 80321401,
    name = "岩甲石灵属于群居魔物，它们拥有相对固定的活动区域，平时一般只在区域内活动。\n不过它们虽然是群居，但在活动区域内却基本都是依靠个体的意志单独行动。\n岩甲石灵非常喜欢争斗，几乎领地中的所有魔物都会成为它们的目标。\n当缺少对手时，它们甚至会将同族当作争斗对象。"
  },
  [80321402] = {
    id = 80321402,
    name = "通常情况下赤目凶兽都是独自行动，它们会凭着自己的本能四处游荡。\n它们对血腥味极其敏感，能清晰地感知到所在区域中受伤生物的位置。\n如果一个生物同时吸引了多只赤目凶兽，它们会根据猎物的实际情况选择竞争或者协作。"
  },
  [80321403] = {
    id = 80321403,
    name = "噬面虫主要以小族群为单位生活，它们没有固定的活动区域，主要跟随环境变化而四处迁徙。\n每当它们到达一个新区域时，前期会进行密集的集体行动，清剿区域内任何可能存在威胁的生物。\n当确认所在区域中的威胁排除后，噬面虫才会进行一些独立活动。\n在噬面虫群体规模发展到一定程度时，其中一些个体便会自动脱离。\n脱离的噬面虫彼此相遇后，又会很自然地汇合为一个新的群体。"
  },
  [80321404] = {
    id = 80321404,
    name = "飘荡魔灵并没有种族、领地观念，都是依靠个体意志自由行动。\n在飘荡过程中，飘荡魔灵和其他同类相遇时也不会有任何交流或协作。\n如果多只飘荡魔灵发现了同一猎物，它们会同时对猎物出手，\n击败猎物后，飘荡魔灵彼此间又会进行新一轮争斗，决定猎物的归属。"
  },
  [80321405] = {
    id = 80321405,
    name = "暗魔虫虽然时常集群活动，但它们其实属于独居魔物，在猎食之外的大部分时间都是独自活动。\n它们没有固定的活动区域，时常在深渊四处游荡。\n只有需要猎食时，才会寻找其他拥有相同目的同族联手，以提升猎食效率。\n暗魔虫对于同族并无太多认同感，即便目睹其他同族陷入危机，它们也不会有主动协助的意图。"
  },
  [80321406] = {
    id = 80321406,
    name = "出于自身安全的考虑，无垢者通常会寻找那些没有强大魔物生存的区域构建自己的领地。\n当它确定领地后，便会清剿领地内所有可能对自己产生威胁的存在。\n对于选择依附自己的魔物，无垢者通通不会拒绝，它需要足够多的附庸来协助自己守卫领地。\n无垢者对同族魔物拥有较强的认同感，无论是其他无垢者还是引领者来到自己的领地，\n它都会选择接纳对方，在领地中共同生活，直到对方选择自行离去。"
  },
  [80321407] = {
    id = 80321407,
    name = "巨掌凶兽没有固定的活动区域，时常独来独往，凭着自己的意志四处活动。\n其实它们对同族极为认可，只是自身暴躁、倔强的脾气令它们难以和同族长久相处。\n当它们在活动时，如果遇到其他陷入危机的同族，巨掌凶兽会毫不犹豫地出手相助。\n有时巨掌凶兽也会和其他同族合作猎食，但这种合作往往只会维持到行动结束。"
  },
  [80321408] = {
    id = 80321408,
    name = "凶刃戮兽生性高傲，除了同族之外的任何存在它都不会放在眼里，即便是更高等级魔物也不例外。\n不过凶刃戮兽的种族非常崇尚力量，倘若能正面击败它，也能让它低下高傲的头颅。\n每当它们和其他同族产生纷争时，双方也会以决斗的方式解决纷争。\n这种战斗会一直持续到有一方低头认输为止，否则双方便会不死不休的战斗下去。"
  },
  [80321409] = {
    id = 80321409,
    name = "幻象恶魔天性好奇，通常会遵从于自己的本能四处活动。\n它对许多事物都充满兴趣，也对许多事物感到厌倦无聊。\n幻象恶魔在四处飘荡时，如果遇到了其他同族，也会选择与对方暂时结伴而行。\n由于太过活跃，幻象恶魔偶尔也会招惹到深渊中一些极其强大的存在。\n当它察觉到自己招惹上这些存在时，会以最快的速度遁逃。"
  },
  [80321410] = {
    id = 80321410,
    name = "秽面邪灵拥有相对固定的活动区域，它们通常会与其他同族组成小族群生活。\n平时，秽面邪灵主要在种群所在区域内游荡、巡视，\n一旦它们发现任何入侵者，亦或棘手的猎物，便会立即呼唤其他同族，联手对付敌人。\n不过，如果秽面邪灵的生存区域被极为强大的魔物占据，\n区域中的秽面邪灵则会根据各自的意志选择成为附庸或者逃离。"
  },
  [80321411] = {
    id = 80321411,
    name = "银翼审判者生性高傲，平时只要不主动招惹，它不屑于对弱小的存在出手。\n可是一旦招惹到它，不管对方拥有怎样的实力，它都绝不会善罢甘休。\n即便能侥幸从它手中逃脱，也只能算是暂时得到了喘息的机会。\n为了追寻仇敌，银翼审判者可以不眠不休，在深渊中一寸寸地搜索对方的踪迹，\n直至宣泄怒火，完成复仇。"
  },
  [80321501] = {
    id = 80321501,
    name = "黑甲地精的活动区域相对固定，通常会和其他同族一起生活。\n它们以集体活动为主，不管遇到任何事都会选择联手应对。\n黑甲地精虽然平时胆小，容易受惊吓，但它们在正面战斗中却极为凶猛，\n一旦被它们当作敌人，将面临它们憾不畏死的疯狂进攻。"
  },
  [80321502] = {
    id = 80321502,
    name = "巨口凶兽对同族拥有较强的认同感，但因其暴躁的脾气，时常独来独往，很少和同族一起行动。\n当它们在游荡时遇到其他陷入危机的同族，会毫不犹豫地出手相助。\n不过，如果是面对那些极为强大的敌人，巨口凶兽也会毫不犹豫地抛下同族，快速逃跑。"
  },
  [80321503] = {
    id = 80321503,
    name = "斑斓地精属于群居类魔物，不过种群规模不会很大，而且没有固定领地。\n所以，许多斑斓地精种群习惯于依附其他高等级魔物生存。\n平时斑斓地精喜欢独自伏击猎物，或者少数几只一起围猎目标。\n只有在种群遭遇威胁时，它们才会选择集体行动。"
  },
  [80321504] = {
    id = 80321504,
    name = "窥探魔眼并无种族、领地之类的观念，\n它们犹如幽灵，凭着自己的本能在深渊四处飘行。\n当它发现心仪的猎物，或者遭受攻击时便会停下，对敌人进行攻击、报复。\n即便是面对强大的对手，它也丝毫不会畏惧，\n犹如没有知觉一般对目标展开疯狂攻击，不死不休。"
  },
  [80321505] = {
    id = 80321505,
    name = "蚀骨花仙很少单独行动，通常它们会和其他同族一起，寻找一片相对固定的区域作为猎场。\n猎场确认后，蚀骨花仙便会各自寻找心仪的位置，然后伪装起来，等待猎物上门。\n当区域内有同族遭遇威胁时，周围所有蚀骨花仙都会主动出手，共同对付敌人。\n倘若遭遇极为强大的对手，或者猎场已难以满足种群生存时，它们便会集体迁徙，寻找新的生存区域。"
  },
  [80321506] = {
    id = 80321506,
    name = "灰壳地魔习惯凭借自己的意志独自行动，寻找那些生物数量较多的区域生活。\n比起其他凶戾的魔物，它更像是一位安静的观察者，静静躲在角落，窥探一切。\n灰壳地魔对同族算不上亲密，即便和其他同族出现在同一区域，\n它也只会将对方当作是过往的众多魔物之一，不会太过在意。\n如果视野中的同族遭受危机，它则会根据敌人的实力选择协助同族或者趁机逃离。"
  },
  [80321507] = {
    id = 80321507,
    name = "为了寻找对手，骨面战鬼时常会在深渊四处活动，从来不会在同一个区域长期停留。\n平时，它除了猎食之外，很少会对那些曾被自己击败过的目标种族动手。\n但如果对方主动招惹自己，骨面战鬼则会进行大规模的无差别攻击，直至将该区域中招惹自己的存在彻底清除。\n骨面战鬼张狂的性格偶尔也会招惹到其他更强大的存在，一旦对方没能及时将骨面战鬼杀掉，\n它则会快速逃跑，然后潜伏在目标周围，等待复仇的机会。"
  },
  [80321508] = {
    id = 80321508,
    name = "猎魂凶兽对同族并无太多认同感，大多数时候都是独自生活。\n不过它们在狩猎一些没有绝对把握的目标时，也会选择和其他同族联手。\n如果在联手行动时，有同族陷入危险，其他的猎魂凶兽不但不会出手相救，反而会迅速逃离。\n对它们而言，只有自身的安危才是最优先考虑的存在。"
  },
  [80321509] = {
    id = 80321509,
    name = "异足戮兽极为自我，任何行动都会以自己为中心。\n任何贸然进入它领地的存在都会被视作敌人，遭受异足戮兽及其附庸魔物的疯狂攻击。\n即便已经成为它附庸的魔物，一旦做出任何令它感到不满的举动，也难逃毁灭的结局。\n不过异足戮兽虽然嚣张蛮横，但它从来不会招惹高等级的魔物，\n甚至高等级魔物入侵它的领地时它也不会抵抗，它会根据对方的态度，迅速选择逃离或者依附。"
  },
  [80321510] = {
    id = 80321510,
    name = "无面梦魇的性格古怪，喜欢凭自己的兴趣行动，大多数时候都是独自生活。\n它们依凭着本能四处游荡，没有固定的活动区域。\n它们和同族算不上亲密，但也没有敌意，当它们在野外相遇时，偶尔也会结伴行动。\n在行动过程中，无面梦魇会选择主动避开有高等级魔物生活的区域，\n对它而言，主动招惹那些没有绝对把握的对手并不算是一种明智的决定。"
  },
  [80321511] = {
    id = 80321511,
    name = "暗影骑士非常喜欢戏弄其他魔物取乐，对它而言，深渊中所有的存在都可以当作戏弄的目标。\n即便是那些实力强大的领主级魔物，它也经常招惹。\n每当把对方激怒之后，它便会迅速逃之夭夭，不给对方任何报复的机会。\n这样的举动并非是它畏惧战斗，而是对方怒火中烧，却又拿它无可奈何的样子令它觉得非常有趣。\n面对真正的敌人时，暗影骑士从来不会逃避，不管对方拥有怎样的实力，它都无所畏惧。"
  },
  [80321703] = {
    id = 80321703,
    name = "毒液菇习惯于独自生活，即便活动范围周围存在其他同类，也很少与其联系。\n在自身没有受到威胁的情况下，无论周围发生任何事它们也不会在意。\n不过，如果生存区域受到影响，它们便会毫不犹豫地和其他同类或者其他魔物联手战斗。"
  },
  [80321704] = {
    id = 80321704,
    name = "小影通常不会单独活动，每当它出现时，在周围看不见的地方，往往便已存在多只小影。\n甚至在它身体内，通常也有不少同类存在。\n它们特殊的能力可以让它们在需要时分裂出更多个体，也能在平时和其他同类融合在一起。"
  },
  [80331016] = {
    id = 80331016,
    name = "群岭之主对浊炁的应用极为得心应手，除了能让自己的攻击和浊炁结合，给予对手更多伤害之外，\n还能在攻击时驱使浊炁侵蚀对手的躯体，令对手难以抵挡自己的攻击。\n而且每次战斗前，群岭之主都会吸纳大量的浊炁环绕在自己身旁，\n在和对手交战的过程中，它会伺机使用这些浊炁，对自己周围的目标进行无差别攻击。\n无论意志如何坚定的对手，也难以在浊炁一次次的冲击下，坚守自己的心智。"
  },
  [80331017] = {
    id = 80331017,
    name = "巡道荒神能够精准调用对手周围的浊气，令对手及其周围目标一起承受伤害和侵蚀。\n同时，巡道荒神在战斗中也会不断聚集周围的浊气，\n当战场中的浊气达到一定浓度时，它便会催动浊气，对全体敌人发动强大攻击。\n除此之外，巡道荒神还拥有着能让周围所有目标都陷入幻觉的诡异能力，\n所有陷入幻觉的目标，都会源源不断地为它提供自己的生命力。"
  },
  [80331113] = {
    id = 80331113,
    name = "混沌行者在战斗时表现得非常狡猾，它在攻击目标时会密切关注目标周围的浊气。\n一旦达到一定浓度便会立即将其催发，令目标及其周围的存在受到的侵蚀加剧，更加难以承受自己的攻击。\n此外，混沌行者也会不断吸纳自身周围的浊气，将其凝聚之后对目标及其周围存在造成巨大伤害。\n在激烈的战斗中，混沌行者也不会放弃自己的恶趣味，它会不断对远处的敌人进行引诱，\n稍不留神便会被它所迷惑，从而陷入呆滞，毫无防备地向它靠近，即便遭受伤害也难以醒来。"
  },
  [80331114] = {
    id = 80331114,
    name = "虚无吞噬者极为贪婪，它绝不能容忍任何目标从它眼前逃离，因此它会优先选择最远处的存在作为攻击目标。\n当它攻击最远处的目标时，会充分调用目标周围的浊气，加剧对方受侵蚀的速度，以干扰对方的行动。\n同时，当虚无吞噬者在战斗中蓄积了足够的力量时，便会直接对最远处的多个目标发动精神攻击，\n一旦被它击中，精神将会变得混乱、难以自控，疯狂地对同伴进行攻击。\n此外，虚无吞噬者会伺机将自身强大的特性转移至敌人身上，以敌人为中心对敌方全体发动难以防范的攻击。"
  },
  [80331115] = {
    id = 80331115,
    name = "霜甲巨兽浑身散发着寒气，当它全力攻击时，会将寒气附着在目标身上，\n一旦被这种寒气包裹，体内的生机便会与外界逐渐隔绝，承受治疗时的效果会严重削弱。\n同时，霜甲巨兽会在战斗中不断蓄积自身的力量，\n当力量蓄积完成，它便会伺机施放，对自身前方的所有目标造成巨大伤害。"
  },
  [80331117] = {
    id = 80331117,
    name = "战斗中，冰脊巨兽会充分利用浊气和自身散发的寒气辅助自己战斗，以尽快镇压对手。每次战斗开始前，它都会根据自己判断选择使用寒气干扰敌人或者利用寒气强化自身，当它面对威胁较高的敌人时，它会驱使寒气缠绕对方，自己则不断蓄积力量。当敌人在寒气的缠绕下，防护逐渐变得脆弱时，冰脊巨兽则会使用蓄积的力量对其发动强大攻击。此外，每当冰脊巨兽周围的浊气达到一定浓度时，它便会将其催发，对周围所有的敌人造成巨大伤害。"
  },
  [80331119] = {
    id = 80331119,
    name = "公会boss，灾厄级魔物的能力"
  },
  [80331120] = {
    id = 80331120,
    name = "公会boss，灾厄级魔物的能力"
  },
  [80331121] = {
    id = 80331121,
    name = "公会boss，灾厄级魔物的能力"
  },
  [80331212] = {
    id = 80331212,
    name = "魔焰领主长期生活在浊气浓郁的巢穴中，久而久之，它的全身都被浊气所浸染，\n在身躯外层，甚至已形成一层由浊气构成的天然防护屏障，\n在这层屏障的防护下，许多魔法都难以对它造成伤害。\n此外，由于长期受浊气浸染，被它肢体所击中的敌人，也将同时承受浊气的侵蚀。\n性格暴躁的它在受到伤害时会不断蓄积怒火，当怒火达到临界点时便会瞬间宣泄出来，给敌人造成巨大伤害。"
  },
  [80331213] = {
    id = 80331213,
    name = "战斗中，荒芜公爵并不急于处理疯狂冲向自己的敌人，\n它会观察全局，将敌方群体中最具威胁的存在作为主要目标。\n只要目标出现任何情绪波动，它便会以目标的情绪作为薪柴，点燃虚无之焰，源源不断地灼烧目标的灵魂。\n同时，它也会不断蓄积力量，伺机对最远处企图伏击自己的敌人发动致命攻击。\n对于逼近自己的敌人，荒芜公爵也会伺机点燃新的烈焰，令这些敢于挑战自己的狂徒承受更多痛苦。"
  },
  [80331214] = {
    id = 80331214,
    name = "屠戮者实力极其强大，当它全力攻击时，对手即便能承受住该次的攻击，也难以化解所有的力量。那些无法及时化解的残余力量将在对手体内暴走，在一段时间内不断蚕食对方的生命力。此外，屠戮者生性高傲，如果在战斗中无法及时掌控局面，它会变得狂躁，愤怒，不断累积怒火，当怒火累积到一定程度时，它便会瞬间将其宣泄，对自己周围所有的敌人造成难以抵挡的巨大伤害。"
  },
  [80331216] = {
    id = 80331216,
    name = "暴虐者极为精明狡诈，面对不同的对手，它在利用浊气的方式上会有很大的差别，对那些陌生的对手，它会稳妥起见，将浓郁的浊气种入对方体内，令其承受剧烈的侵蚀，直至死亡。而面对熟悉的对手，它则会将浊气用于强化自身，不断提升自己的力量，力求迅速击败对方。此外，每当它身边的浊气达到一定浓度时，它便会立即将其催发，对周围的所有目标造成巨大伤害。对战场上那些威胁最大的敌人，它则会在暗中不断蓄积力量，伺机对其发动致命攻击。"
  },
  [80331218] = {
    id = 80331218,
    name = "公会boss，灾厄级魔物的能力"
  },
  [80331219] = {
    id = 80331219,
    name = "公会boss，灾厄级魔物的能力"
  },
  [80331220] = {
    id = 80331220,
    name = "公会boss，灾厄级魔物的能力"
  },
  [80331312] = {
    id = 80331312,
    name = "异魔主母在战斗时极为谨慎，攻击敌人的同时也会利用各种力量防护自身，绝不轻敌大意。\n当它击中敌人后，便会汲取对方的生命力，转化为自身周围反射伤害的屏障。\n在敌人周围的浊气达到一定浓度时，它便会将其催发，对敌人及其周围目标造成大量伤害，同时吸收四溢的浊气，转化为自身的防护屏障。\n此外，在异魔主母看来，能直面自己的敌人都能算得上优质的养料，因此它会一点点削弱敌人，\n待敌人虚弱后，便在其体内种下魔物之卵，如果敌人无法及时清除，便会作为养分被卵吞噬，孵化出新的魔物。"
  },
  [80331313] = {
    id = 80331313,
    name = "在战斗时，恐怖公会源源不断召集同族魔物协助自己，\n这些被召集而来的魔物虽然实力不及恐怖公，但却能有效牵制敌人，让它能更加专心地进行攻击或者防守。\n对恐怖公而言，这些应召而来的同族都是自己最忠诚的子民，\n它会毫不犹豫地将自己吸纳的浊气赠与同族，令它们能发挥出更强大的实力。\n每当有子民被敌人击败，恐怖公都会更加愤怒，进而对敌人展开更为暴虐的攻击。"
  },
  [80331315] = {
    id = 80331315,
    name = "在战斗中，除了利用浊气和地形，翠神还极其擅长利用敌人的力量。\n当它击中对手时，会悄无声息地汲取对手的生命力，用以强化自身。\n此外，为了掌控战局，翠神会将自己的攻击和浊气相结合，\n在蓄积了足够的力量之后伺机施放，对周围敌人造成巨大伤害，\n同时催动浊气，压制战场中的高威胁目标。"
  },
  [80331317] = {
    id = 80331317,
    name = "绿魔在战斗时极为谨慎，每次战斗开始前它都会吸纳大量的浊气环绕己身，面对初次交手，尚不清楚底细的敌人，它会选择将浊气用于构建防护屏障，以应对对方的各种偷袭。而面对熟悉的敌人时，它则会将这些浊气作为战斗中的补给，提升自己战斗时的力量。每当敌人周围的浊气达到一定浓度时，绿魔都会将其催发，令敌人承受剧烈的侵蚀。此外，当绿魔力量蓄积足够之后，它会根据战局选择全部不同的使用方式，确保自己能掌控局面。"
  },
  [80331319] = {
    id = 80331319,
    name = "公会boss，灾厄级魔物的能力"
  },
  [80331320] = {
    id = 80331320,
    name = "公会boss，灾厄级魔物的能力"
  },
  [80331321] = {
    id = 80331321,
    name = "公会boss，灾厄级魔物的能力"
  },
  [80331411] = {
    id = 80331411,
    name = "银翼审判者的自大和傲慢，也在战斗中尽数呈现。\n当它面对无法轻易解决的对手时，会变得愤怒、狂暴，以超越常态的力量对目标进行疯狂攻击。\n同时，在战斗中它会不断蓄积浊气，蓄积到一定程度时便会将浊气全部施放，贯穿对手所在方向的所有目标。\n对招惹自己的存在，银翼审判者会用浊气在对方身上留下特殊印记，\n当它攻击对手时，倘若对方身上存在印记，则会同时催动印记，令目标承受更强的侵蚀。"
  },
  [80331511] = {
    id = 80331511,
    name = "暗影骑士实力强大，但战斗时极为谨慎，不管面对怎样的敌人也不会轻敌大意。\n当它同时面对多个敌人时，暗影骑士会根据自己的判断选择其中一个作为主要目标，然后逐个击破。\n它习惯将浊气和自己的攻击相结合，驱使浊气侵蚀目标及其周围的敌人。\n面对被自己当作主要敌人的目标，暗影骑士在应对时会更加谨慎，\n为了能一击制胜，威慑群敌，它会在暗中蓄积力量，伺机对主要敌人发动极其强大的攻击。"
  },
