  [80341501] = {id = 80341501, sub_name = "MONSTER"},
  [80341502] = {id = 80341502, sub_name = "MONSTER"},
  [80341503] = {id = 80341503, sub_name = "MONSTER"},
  [80341504] = {id = 80341504, sub_name = "MONSTER"},
  [80341505] = {id = 80341505, sub_name = "MONSTER"},
  [80341506] = {id = 80341506, sub_name = "MONSTER"},
  [80341507] = {id = 80341507, sub_name = "MONSTER"},
  [80341508] = {id = 80341508, sub_name = "MONSTER"},
  [80341509] = {id = 80341509, sub_name = "MONSTER"},
  [80341510] = {id = 80341510, sub_name = "MONSTER"},
  [80341511] = {id = 80341511, sub_name = "MONSTER"},
  [80351001] = {
    id = 80351001,
    name = "岩石上有个凹洞，里面看起来空无一物。\n突然，凹洞扭曲了一瞬，整个岩石都开始蠕动起来。"
  },
  [80351002] = {
    id = 80351002,
    name = "眼前的石壁上有很多漆黑的石缝，\n延长伸直到远处的洞穴，明显是凶猛的魔物留下的痕迹。"
  },
  [80351003] = {
    id = 80351003,
    name = "安妮斯 「很漂亮的水晶啊！」\n蒂娜 「我帮你取。」\n尼莉莎 「水晶，动起来了！」\n菲尼斯 「先别惹它，这不是水晶。」"
  },
  [80351004] = {
    id = 80351004,
    name = "两只魔物互相撕咬，强大的魔物展开了双翼，将弱小的魔物吃掉了。\n你没有惊动它，悄悄转身离开。"
  },
  [80351005] = {
    id = 80351005,
    name = "旷野上，人群围剿着一堆「石头」，\n石缝里，有人在求救，好几人被「石头」吞掉。\n在你们的帮助下，大家很快救出了受害者。"
  },
  [80351006] = {
    id = 80351006,
    name = "眼前是一条狭窄的山路，你沿着通道行走，道路被奇怪的泥土堵住，\n你打算原路返回时候，身后的泥土抖落，\n魔物现身，露出了狰狞凶恶的武器。"
  },
  [80351007] = {
    id = 80351007,
    name = "一片迷雾遮蔽了去路，阴影处有什么危险藏在了暗处，\n你走入迷雾，蛰伏的魔物冲了出来！\n作为猎食者的魔物被你反杀。"
  },
  [80351008] = {
    id = 80351008,
    name = "你们找了块干净的岩石，坐在上面休息，\n此时，岩石移动了一下。\n尼莉莎 「呜哇！这是什么东西！」\n随着尼莉莎的尖叫，「石头」迅速逃走了。"
  },
  [80351009] = {
    id = 80351009,
    name = "走到半路，发现蒂娜停住了。\n蒂娜 「很漂亮啊。」她迷迷糊糊地向一朵花走了过去。\n在「花」进攻蒂娜之前，你们极快地杀掉了它。"
  },
  [80351010] = {
    id = 80351010,
    name = "你们在漆黑的洞窟里暂时休憩，里面是一堆堆静止的碎石，\n此时洞窟中的碎石齐齐飞向了你们，\n尼莉莎带火的箭矢落在碎石上，你闻到了烧焦的味道。"
  },
  [80351011] = {
    id = 80351011,
    name = "你走入洞窟探索，一处壁面崩塌的地方，布满了古怪的花纹，\n入口处的岩石松落了，你小心翼翼地后退，看到眼前巨大的骨骼在缓缓苏醒。"
  },
  [80351012] = {
    id = 80351012,
    name = "突然刮起了一阵风，巨影从月亮上横切而过，\n你们屏住呼吸，听见前方有东西重重摔在地面。\n振翅声远去了，留下了内脏被掏空的探险者。"
  },
  [80351013] = {
    id = 80351013,
    name = "远处，一块巨岩从山坡滚落，砸进了一汪水潭里，\n潭底黑色的双翼如刀锋般亮起，将巨岩切割成碎片。\n随后，魔物以比鹰隼还快的速度冲向了山坡，一群探险者在魔物的冲击下四处逃窜。"
  },
  [80351014] = {
    id = 80351014,
    name = "探险者遗体的上方有白色的东西在闪烁。\n「是记忆迷雾，可以储存短暂记忆的魔法。」你用魔法激活了它。\n一只宛如水晶的魔物映入迷雾，接着是无声的血光，然后迷雾消散了。"
  },
  [80351015] = {
    id = 80351015,
    name = "尼莉莎 「那是什么？！」前方平白出现了散发着圣物光芒的宝箱，\n在众人跃跃欲试的神情里，圣物在你眼前虚幻扭曲了一瞬，\n你果断地斩破了眼前的幻象，带着大家逃离即将吞噬众人的血色蔷薇。\n"
  },
  [80351016] = {
    id = 80351016,
    name = "遇到一只落单的魔物。它与你对峙了几秒钟，很快，更多同样的魔物出现了。"
  },
  [80351017] = {
    id = 80351017,
    name = "遇到一只落单的魔物。它与你对峙了几秒钟，很快，更多同样的魔物出现了。"
  },
  [80351101] = {
    id = 80351101,
    name = "靠山的石壁上，到处生长着苔藓与菌类，\n它们散发着磷光，与其待在一起的，还有食魂兽发光的尾翼。"
  },
  [80351102] = {
    id = 80351102,
    name = "前进途中，有声音在头上响起。是滚石！\n你急忙躲避，巨石从你旁边滚落。\n与此同时，阴暗的魔物藏在滚石后面飞扑过来！"
  },
  [80351103] = {
    id = 80351103,
    name = "衣衫褴褛的探险者正在和一只魔物搏斗，那只魔物咆哮着，妄图将眼前的猎物撕碎，\n独行的探险者忽然爆发出强大的实力，斩杀了凶猛的魔物，浑身伤痕地离开。"
  },
  [80351104] = {
    id = 80351104,
    name = "你捡到了一本破烂的探险者笔记，上面写着\n「明天我即将挑战狂暴魔灵，希望女神，乞求您赐我助力，成就响彻深渊的荣耀！」"
  },
  [80351105] = {
    id = 80351105,
    name = "进入大型的荒地区域，整个地面都异常潮湿，上面都是凌乱的爪印，\n前方不远处有一具大型魔物的躯壳，看起来刚死亡不久。"
  },
  [80351106] = {
    id = 80351106,
    name = "你走过一片扎满墓碑的坟场，宛如阴森的乱葬岗，\n这时，其中一个墓碑移动了一下，从墓碑下钻出来的，不是幽灵，是驮着碑的魔物。"
  },
  [80351107] = {
    id = 80351107,
    name = "开阔的洞穴中有一队疲惫的探险者，他们抱怨魔物怎么也杀不尽，\n那些像石头的魔物带着仇恨般，没多久就会再次找上门，\n尼莉莎 「是滚石地精吧，超记仇的魔物呢。」尼莉莎如此判断。"
  },
  [80351108] = {
    id = 80351108,
    name = "蒂娜 「等一等，什么声音？」\n尼莉莎蹦跶着往前探索，很快，她仓皇地逃了回来「没、没脸的大猩猩啊！」\n粉碎者跟在她身后，与你们撞了个正着。"
  },
  [80351109] = {
    id = 80351109,
    name = "夜晚休息时刻，你听到身后地面的声音，似乎有什么东西在匍匐寻找，来回接近，\n终于，那恐怖的东西窥视到你的脸——"
  },
  [80351110] = {
    id = 80351110,
    name = "你在平地上行走，走着走着，发现自己正在不自觉地下坡......\n行走的「路面」突然坡度陡升，一道强大的力量把你们扔了出去，\n你们从巨型魔物的脊背上被甩了下来！"
  },
  [80351111] = {
    id = 80351111,
    name = "你在河边遇到魔物的阻扰，尽数歼灭后，有魔物尸体落入河中，往下游漂去。\n半路，有一只触手不知道从何处伸出，掠走了漂流的魔物尸体。"
  },
  [80351112] = {
    id = 80351112,
    name = "潮湿的天坑里，一群滑溜溜的生物在无意识地蠕动着，\n它们描绘着边缘的轨迹，不停地绕圈，你感觉被什么盯住了，毛骨悚然。\n你拿出了武器，和同伴们一起迎来战斗，也看到了摄魂恶魔的真容。"
  },
  [80351113] = {
    id = 80351113,
    name = "遇到一只落单的魔物。它与你对峙了几秒钟，很快，更多同样的魔物出现了。"
  },
  [80351114] = {
    id = 80351114,
    name = "湖心岛上散落了很多金灿灿的东西，\n通往岛屿的水底，却潜伏着巨大的身躯，\n有魔物被金色吸引，下一刻就被卷入了黑暗中。"
  },
  [80351115] = {
    id = 80351115,
    name = "冷冽的冰原，安静寒冷，可你却感受到了鲜明的恶意。\n在你继续朝前走的时候，脚下颠簸震动，仿佛要撕裂这个冰原。\n震动停止了，眼前出现一道宽大的沟壑，深不见底。\n远处一座「冰山」升起，朝你咆哮着，势必驱逐所有的外来者。"
  },
  [80351117] = {
    id = 80351117,
    name = "你正前往水瀑装水，周围的温度开始急速下降，仿佛一切都要结成了冰。\n「不许靠近！走入领域的人，全都得死！」巨大的阴影笼罩了你，释放着恐怖的威压。\n在它还未摧毁一切之时，你逃出了它的领域。"
  },
  [80351119] = {
    id = 80351119,
    name = "遇到一只落单的魔物。它与你对峙了几秒钟，很快，更多同样的魔物出现了。"
  },
  [80351120] = {
    id = 80351120,
    name = "遇到一只落单的魔物。它与你对峙了几秒钟，很快，更多同样的魔物出现了。"
  },
  [80351121] = {
    id = 80351121,
    name = "遇到一只落单的魔物。它与你对峙了几秒钟，很快，更多同样的魔物出现了。"
  },
  [80351201] = {
    id = 80351201,
    name = "你在繁茂的密林通行，有水从草木渗透而出。\n你停下了脚步，草木变化成了一只只飞行魔物，成群结队地飞过。"
  },
  [80351202] = {
    id = 80351202,
    name = "一簇篝火在远处亮起，你看到篝火旁有几个影子。\n你正想上前打招呼，「人影」站了起来，显现出怪异扭曲的身形。"
  },
  [80351203] = {
    id = 80351203,
    name = "谷口处，水流像瀑布一样在地面形成了水坑，然而里面的水是沸腾的。\n不多时，水里钻出了一块「铁球」，蒸腾着滋滋热气。"
  },
  [80351204] = {
    id = 80351204,
    name = "前方的路被沙土掩埋，已经无法再前进了。\n沙土里，一支尖锐的尾刺冒出了头，\n随后整个身子从沙土中翻转，又很快将自身掩盖在沙土中。"
  },
  [80351205] = {
    id = 80351205,
    name = "洞穴里，潺潺流动的地下水突然被什么翻搅，停滞在不远处。\n你加强了戒备，与魔物在暗中对峙。\n良久，那搅动的水声离你远去了。"
  },
  [80351206] = {
    id = 80351206,
    name = "箭矢突然飞至眼前！你躲开后，树枝、石块随即而至！\n你回避反击，只看到两截钳夹，以及下方空洞的魔物头颅。"
  },
  [80351207] = {
    id = 80351207,
    name = "走在热气腾腾的地表上，这里离岩浆口很近了，蛰伏的魔物也越来越少，\n除了那个远处行走的，宛如山峰的巨兽。"
  },
  [80351208] = {
    id = 80351208,
    name = "你走入一个山谷，头顶像是巨大的椭圆球，\n中间是一格一格宛如建筑般的穹顶，平缓的路上，有各种粘液和腐蚀的武器。\n「我们好像进入魔物尸体里了。」你猜测得到验证，大家快速撤离了此处。"
  },
  [80351209] = {
    id = 80351209,
    name = "走入一片森林，你们发现了异样。这里太安静了，没有其他的魔物及生物。\n宽阔的落叶丛里，铺就着魔物与人类的尸骨，很明显，你们走入了大型魔物的巢穴。\n远处的空中的黑点展开双翼疾飞而至，你们看清楚了它的模样。"
  },
  [80351210] = {
    id = 80351210,
    name = "你踏入了一片荒地，黄沙之上是一座废墟，\n原本的据点已经土崩瓦解，倒塌的人工雕像旁有一块半人高的圆球，\n那圆球动了动，露出像「眼睛」一样的瞳孔「注视」着你，铺天盖地的魔法力漫溢而出！"
  },
  [80351211] = {
    id = 80351211,
    name = "不知从哪里来的浪潮拍打着岸边，冷寂的空气里混杂着腐败的气味。\n这时，夜晚的湖中突然亮起了诡异的光，缓缓闪烁游荡。\n它映照着湖面的倒影，露出硕大的骨架轮廓......"
  },
  [80351212] = {
    id = 80351212,
    name = "遇到一只落单的魔物。它与你对峙了几秒钟，很快，更多同样的魔物出现了。"
  },
  [80351213] = {
    id = 80351213,
    name = "遇到一只落单的魔物。它与你对峙了几秒钟，很快，更多同样的魔物出现了。"
  },
  [80351214] = {
    id = 80351214,
    name = "空气中飘来了若有似无的血腥味，你似乎被无形的涟漪拖入了一个幻觉。\n一股庞大的意识降临，你在恐怖的意识下渺小如尘埃。\n放眼看去，天生的修罗在起舞，屠杀着入侵它领域的魔物。"
  },
  [80351216] = {
    id = 80351216,
    name = "眼前的路本应该是平坦的荒野，但这里已经变成由低级魔物堆成的尸山。\n蒂娜 「到底是哪队探险者？」\n尼莉莎 「这也太强了！」\n「不，能做到这种地步的。只有暴虐者......」你这样回答。"
  },
  [80351218] = {
    id = 80351218,
    name = "遇到一只落单的魔物。它与你对峙了几秒钟，很快，更多同样的魔物出现了。"
  },
  [80351219] = {
    id = 80351219,
    name = "遇到一只落单的魔物。它与你对峙了几秒钟，很快，更多同样的魔物出现了。"
  },
  [80351220] = {
    id = 80351220,
    name = "遇到一只落单的魔物。它与你对峙了几秒钟，很快，更多同样的魔物出现了。"
  },
  [80351301] = {
    id = 80351301,
    name = "走在坑洼不平的森林外，似乎有什么躲在了阴影里。\n腐朽的魔物发出密密麻麻细微的声音，你们悄然退出了森林。"
  },
  [80351302] = {
    id = 80351302,
    name = "遇到一只落单的魔物。它与你对峙了几秒钟，\n很快，更多同样的魔物出现了，你迅速将他们尽数斩杀。"
  },
  [80351303] = {
    id = 80351303,
    name = "一方干涸的蓄水池，底部尽是赤黑色的污迹，以及零散的白骨。\n你稍微一靠近，蓄水池轰然塌陷，藏在地下的魔物一溜烟跑掉了。"
  },
  [80351304] = {
    id = 80351304,
    name = "废弃的矿洞里布满了碎石瓦砾，\n而在矿洞的墙面，长着许多苔藓的巨石。\n接着，这些巨石移动了起来......"
  },
  [80351305] = {
    id = 80351305,
    name = "大路旁的花木丛，有什么东西咯咯作响，\n是几朵美丽的花，花蕊里还有残留的血肉，它们发现了新猎物，扑了过来！\n你把它们杀得东倒西歪，残存的一只钻入地底逃生而去。"
  },
  [80351306] = {
    id = 80351306,
    name = "你停在一棵大树旁休憩，树枝随风摇摆，慢慢地，离你越来越近，\n你用剑斩断了树枝！整个大树震颤，发出一声咆哮，你们合力将其灭杀。"
  },
  [80351307] = {
    id = 80351307,
    name = "一阵骤风席卷而来，飓风结束后，空中掉下了许多魔物的尸体，\n「吼......」一声震天的怒吼，你抬头仰望，巨型的凶兽踏着黄沙走过，大地震颤。"
  },
  [80351308] = {
    id = 80351308,
    name = "前方的树上，坐着一个探险者，全身都被黑色斗篷覆盖了。\n他朝你扬了扬斗篷，似乎在叫你过去。\n风掀起了斗篷的一角，露出了银白色的羽翼，宛如挑衅一般显露了攻击性的身躯。"
  },
  [80351309] = {
    id = 80351309,
    name = "菲尼斯 「我好像闻到了药材的味道。」\n蒂娜 「不是药材，是闻起来像药材的魔物！」\n说话的时候，一块杂草般的石头已飞到你们的眼前！"
  },
  [80351310] = {
    id = 80351310,
    name = "眼前出现了一名陌生少女，她邀请你在篝火边休息。\n在你无法控制地沉眠时，有什么悄悄贴近了。\n你躲过了陌生东西的攻击，努力睁开眼睛，看到眼前高大瑰丽，长满尖齿的蔷薇花。"
  },
  [80351311] = {
    id = 80351311,
    name = "木屋房顶已经被掀翻了，旁边有一只大型魔物的尸体。 \n尼莉莎 「等一下，别去！那个家伙最爱装死啦！」\n她举起弓箭远远地射在甲壳上，那「龙尾」不自觉地摆动了起来。"
  },
  [80351312] = {
    id = 80351312,
    name = "遇到一只落单的魔物。它与你对峙了几秒钟，很快，更多同样的魔物出现了。"
  },
  [80351313] = {
    id = 80351313,
    name = "遇到一只落单的魔物。它与你对峙了几秒钟，很快，更多同样的魔物出现了。"
  },
  [80351315] = {
    id = 80351315,
    name = "巧遇你们的探险者侃侃而谈，告诉你们在废弃低洼的地方，还发现了巨大的骨架，\n那是死掉的领主级魔物，对人类而言，是足以生畏的庞然大物。"
  },
  [80351317] = {
    id = 80351317,
    name = "晶石镶嵌在山壁突起的尖石上，被飞行魔物衔取。\n你看见有探险者从魔物手里抢下晶石，接着整座山「动」了，尖石变成了利刃！\n「是，是领主级！！」探险者们抱着晶石疯狂逃窜。"
  },
  [80351319] = {
    id = 80351319,
    name = "遇到一只落单的魔物。它与你对峙了几秒钟，很快，更多同样的魔物出现了。"
  },
  [80351320] = {
    id = 80351320,
    name = "遇到一只落单的魔物。它与你对峙了几秒钟，很快，更多同样的魔物出现了。"
  },
  [80351321] = {
    id = 80351321,
    name = "遇到一只落单的魔物。它与你对峙了几秒钟，很快，更多同样的魔物出现了。"
  },
  [80351401] = {
    id = 80351401,
    name = "地面的岩石凹凸不平，到处都是魔物的残肢断臂，\n尼莉莎 「噢~都是同类干掉的呢。」\n安妮斯 「好惨烈，魔物也会杀死魔物吗......」"
  },
  [80351402] = {
    id = 80351402,
    name = "尼莉莎 「哇喔，是值钱货啊，快来帮忙~」\n面对斩不断的古木，蒂娜捡起脚下锋利的片状物，顺利地切断。\n尼莉莎 「等等，你手里拿的是魔物的腿吧？」"
  },
  [80351403] = {
    id = 80351403,
    name = "前面有一个背对着你们坐着的探险者，\n他一动不动，一双翅膀缓缓从他的头上煽动，\n魔物很快飞走了，那个人随即倒下，只剩下空空的躯壳。"
  },
  [80351404] = {
    id = 80351404,
    name = "平静的湖泊上飘荡着许多像死灵一样的身影，\n这时，湖中有小小的水生生物冒头，\n瞬间就被「死灵」扼制，直到撕碎，吞噬。"
  },
  [80351405] = {
    id = 80351405,
    name = "哧......哧......什么声音？像撕咬与咀嚼，又像吸食杯中的牛奶，\n寻声看去，魔物尖锐的口器洞穿了一具尸体，\n正在进食的魔物没有注意你的出现和离开。"
  },
  [80351406] = {
    id = 80351406,
    name = "成群的刀足兽像逃命般朝你们涌来，在它们的身后，有一只宛如人形的魔物。\n它挥动着洁白的刀翼，优雅地屠杀着打扰自己安眠的存在。"
  },
  [80351407] = {
    id = 80351407,
    name = "这里是一座染血的祭坛，当你想要深入调查的时候，惊醒了沉睡在祭坛下的大型魔物。\n它趴在层层白骨上，用探险者的血肉洒满了祭坛。"
  },
  [80351408] = {
    id = 80351408,
    name = "巨大的湖泊中央有一座岛屿，岛屿上正在发生激烈的战斗，\n一群魔物和探险者搏斗着，探险者战败了，你们准备营救，\n就在这时，一只银白甲壳的魔物浮出水面，秒杀了所有的争斗者。"
  },
  [80351409] = {
    id = 80351409,
    name = "丘陵的山脚下，有密密麻麻的灯火，探险者们在尽情地歌舞，像在庆祝什么，\n仔细一看，那些人们眼神空洞，陷入了幻觉不自知，如疯了般喃喃自语直到昏睡。 "
  },
  [80351410] = {
    id = 80351410,
    name = "路边有一具破烂的石像，上面有数不清的虫子爬过，脸部五官已经模糊，看起来十分不祥。\n这时，石像动了，抖落了「盖」在脸上的面具，露出邪恶的真容。"
  },
  [80351411] = {
    id = 80351411,
    name = "你忽然感到了致命的危机！是一种熟悉的，一直追在你身后的紧迫感！\n是它！又来了！\n魔物发出复仇的怒吼，令人激动惊惧！\n你们躲在暗处，看它在天空盘旋良久，月光下投下巨型阴影，接着滑翔远去。"
  },
  [80351501] = {
    id = 80351501,
    name = "黑暗的洞穴里有什么在发光。\n你悄然靠近，缓缓接近了一闪一闪的光点，\n那是坚硬甲壳上的晶石，似乎受到了惊吓，\n胆小的魔物迅速蜷缩成了一团。"
  },
  [80351502] = {
    id = 80351502,
    name = "沿着大路前行，一群魔物在小溪谷游荡，\n尼莉莎 「只、只有嘴巴的魔物？！」\n叫声惊动了那群魔物，下一秒，尼莉莎和魔物同时背过身逃走了。"
  },
  [80351503] = {
    id = 80351503,
    name = "前面一队探险者正围在水晶石边严阵以待，\n忽然，在他们眼前的水晶石动了起来！\n他们合力绞杀了魔物，「水晶」的光芒就此消失了。"
  },
  [80351504] = {
    id = 80351504,
    name = "你走进长满莹草的坑洞里，鼻尖充斥着湿润的空气。\n暗处的莹光忽然闪了一闪，露出了全貌，\n浑身长满眼睛的魔物，看得你头皮发麻。"
  },
  [80351505] = {
    id = 80351505,
    name = "前方是一朵盛开的花，弱小的虫子恰好被它吸引，停留在花蕊处。\n很快那朵花迅速闭了口，花朵再次盛放的时候，虫子消失了。"
  },
  [80351506] = {
    id = 80351506,
    name = "安妮斯 「那是......会滚的石头？」\n「嘿嘿，可以当球踢哦！」尼莉莎捡起一块，一脚踢得老远。\n隐隐看见石头长出了肢体，消失在视野中。\n安妮斯 「......好，好厉害。」"
  },
  [80351507] = {
    id = 80351507,
    name = "前方是一截断垣，一名探险者紧贴着墙壁躲着，在他身后，高大的魔物漫步游走，\n这时，它注意到了你，羊骨般的「头」朝你转了过来。\n就在探险者战战兢兢地准备逃跑时，魔物傲然地转身离开了。"
  },
  [80351508] = {
    id = 80351508,
    name = "附近的废墟里传来了激战的声音，你定睛望去，有一队探险者逃了出来，\n在你来不及考虑的时候，危机已至。\n敏捷宛如幽灵般的魔物，最终被你们合力击杀。"
  },
  [80351509] = {
    id = 80351509,
    name = "「滋——滋——」刺耳的声音从附近传来。\n像是尖锐的物品一遍又一遍刮着金属面，让人浑身暴起一层冷森森的鸡皮疙瘩。\n你快速躲了起来。\n一只全身尖刺的魔物突然出现，它在你站立过的地方转了一圈后才离开。"
  },
  [80351510] = {
    id = 80351510,
    name = "这里像是一个被石柱围起的广场，有老旧人工的痕迹，\n在其中一个石柱上，刻有灭杀魔物的过程，\n菲尼斯 「是传闻喜欢捉迷藏的那种魔物。」\n尼莉莎 「哇，随时出现在别人的身后。真是超级恶劣的魔物啊！」"
  },
  [80351511] = {
    id = 80351511,
    name = "遇到一只落单的魔物。它与你对峙了几秒钟，很快，更多同样的魔物出现了。"
  },
  [80351703] = {
    id = 80351703,
    name = "蒂娜「咦，我好像踩到了什么......」\n蒂娜抬了抬脚，似乎被什么东西黏住了。\n那东西即刻松开了鞋子溜走。\n尼莉莎「哎呀呀，它跑了。」"
  },
  [80351704] = {
    id = 80351704,
    name = "安妮斯「老师，你是老师吗？」\n尼莉莎「什么？队长被掉包了吗！」\n安妮斯「他，他有两个影子......」\n尼莉莎「不对......我怎么也有两个影子！」"
  },
