    name = "免伤提升%d%%，持续整场战斗，不可被解除。"
  },
  [80511250] = {
    id = 80511250,
    name = "被附加的目标每秒损失%s%%的最大生命值，持续%s秒，可以叠加；若被附加的目标每获得一次护盾，则会解除1层创伤效果。"
  },
  [80511260] = {
    id = 80511260,
    name = "普攻将给目标附加1层【分解】效果，持续%s秒，强化普攻状态可被解除。"
  },
  [80511270] = {
