  [80614026] = {
    id = 80614026,
    name = "This is the 「Step-Up Recruitment」"
  },
  [80614031] = {
    id = 80614031,
    name = "此招募为永久性招募，面向新探险家开启。"
  },
  [80614032] = {
    id = 80614032,
    name = "此招募存在次数上限，最高为[color=#e6ff51]30[/color]次。"
  },
  [80614033] = {
    id = 80614033,
    name = "[color=#e6ff51]30[/color]次招募后，可自选一名5星角色。"
  },
  [80614034] = {
    id = 80614034,
    name = "在「启程招募」中，每进行十次招募，必定能获得至少一位4星角色或5星角色。"
  },
  [80614041] = {
    id = 80614041,
    name = "在「常驻招募」中，如果连续[color=#e6ff51]60[/color]次没有获得5星角色，则下一次获得5星角色的概率从原本的2%%提升至[color=#e6ff51]7%%[/color]。如果该次还没有招募到5星角色，则后续每次招募获取5星角色的概率将继续依照[color=#e6ff51]5%%[/color]累加递升。"
  },
  [80614042] = {
    id = 80614042,
    name = "最多[color=#e6ff51]70[/color]次招募必定通过保底获得5星角色。"
  },
  [80614043] = {
    id = 80614043,
    name = "在「常驻招募」中，没有获得5星角色的累计次数共用，且累计次数而增加的获得概率也共用。"
  },
  [80614044] = {
    id = 80614044,
    name = "获得5星角色后，在「常驻招募」中获取5星角色的概率将恢复至[color=#e6ff51]2%%[/color]。"
  },
  [80614045] = {
    id = 80614045,
    name = "在「常驻招募」中，每进行十次招募，必定能获得至少一位4星角色或5星角色。"
  },
  [80614051] = {
    id = 80614051,
    name = "在所有「特定招募」中，如果连续[color=#e6ff51]60[/color]次没有获得5星角色，则下一次获得5星角色的概率从原本的2%%提升至[color=#e6ff51]7%%[/color]。如果该次还没有招募到5星角色，则后续每次招募获取5星角色的概率将继续依照[color=#e6ff51]5%%[/color]累加递升。"
  },
  [80614052] = {
    id = 80614052,
    name = "最多[color=#e6ff51]70[/color]次招募必定通过保底获得5星角色。"
  },
  [80614053] = {
    id = 80614053,
    name = "在所有「特定招募」中，5星角色的保底计数、随招募次数提升的抽取概率共通，且可以继承到下一期。不同类型卡池的招募次数保底相互独立计算，互不影响。（如「特定招募」保底计数与「常驻招募」不互通）"
  },
  [80614054] = {
    id = 80614054,
    name = "获得5星角色后，在「特定招募」中获取5星角色的概率将恢复至[color=#e6ff51]2%%[/color]。"
  },
  [80614055] = {
    id = 80614055,
    name = "概率UP的角色占该角色所在星级招募概率的[color=#e6ff51]50%%[/color]，如果本次招募获得的5星角色非本期5星UP角色，则下次招募获取的5星角色[color=#e6ff51]必定[/color]为本期5星UP角色。"
  },
  [80614056] = {
    id = 80614056,
    name = "在所有「特定招募」中，每进行十次招募，必定能获得至少一位4星角色或5星角色。"
  },
  [80614057] = {
    id = 80614057,
    name = "当期UP的5星和4星角色，将在招募结束的3周后加入常驻招募（具体以公告为准）。"
  },
  [80614061] = {
