  },
  [80614071] = {
    id = 80614071,
    name = "In all 「Step-Up Recruitments」, there are five steps in total for this banner, and each step allows one 10-recruit attempt to be performed. Players must perform the stages in order, each stage becomes available only after completing the previous one.\nThe first 10-recruit attempt is available at a 80%% discount (5 Originites).\nThe second 10-recruit attempt is available at a 60%% discount (10 Originites).\nThe third 10-recruit attempt is available at a 40%% discount (16 Originites) and guarantees one ★5 Explorer from the Permanent Recruitment.\nThe fourth 10-recruit attempt is available at a 20%% discount (20 Originites) and grants 500 opals.\nThe fifth 10-recruit attempt costs 25 Originites and guarantees the ★5 Featured Explorer."
  },
  [80614072] = {
    id = 80614072,
    name = "Every 10-recruit attempt in 「Step-up Recruitment」 guarantees at lease one 4-star or 5-star character."
  },
  [80614073] = {
    id = 80614073,
    name = "The pity counters for this Recruitment do not carry over from any other Recruitment, nor will they carry over after the banner ends."
  },
  [80614074] = {
    id = 80614074,
    name = "The Step-Up Recruitment cannot be repeated once all five steps are completed."
  },
  [80614075] = {
    id = 80614075,
    name = "Apart from the listed guaranteed rewards , no additional pity system applies to this Recruitment."
  },
  [80614076] = {
    id = 80614076,
    name = "No rate-up increase mechanic applies to this Recruitment."
  },
