  [80622000] = {
    id = 80622000,
    name = "[color=#d189ff]「阻挡物，可被攻击，能够承受10次攻击伤害」[/color]"
  },
  [80622001] = {
    id = 80622001,
    name = "[color=#d189ff]「阻挡物，可被攻击，能够承受5次攻击伤害」[/color]"
  },
  [80622002] = {
    id = 80622002,
    name = "[color=#d189ff]「阻挡物，可被攻击，能够承受5次攻击伤害」[/color]"
  },
  [80622003] = {
    id = 80622003,
    name = "进入泥潭区域后，当前移动速度降低50%%，且在泥潭中速度不会增加。\n[color=#d189ff]「陷阱，不可被攻击」[/color]"
  },
  [80622004] = {
    id = 80622004,
    name = "进入沼泽区域后，每秒扣除生命上限10%%的生命。\n[color=#d189ff]「陷阱，不可被攻击」[/color]"
  },
  [80622005] = {
    id = 80622005,
    name = "进入伤害陷阱后，会直接扣除生命上限20%%的生命，仅生效一次。\n[color=#d189ff]「陷阱，不可被攻击，生效成功后消失」[/color]"
  },
  [80622006] = {
    id = 80622006,
    name = "当角色触发弹射后，将按照其进入的方向击退300的距离。\n[color=#d189ff]「陷阱，不可被攻击」[/color]"
  },
  [80622007] = {
    id = 80622007,
    name = "怪物从该位置刷新入场。\n[color=#d189ff]「基础设施，不可被攻击」[/color]"
  },
  [80622008] = {
    id = 80622008,
    name = "间隔5秒，为周身范围内的友方目标回复10%%生命上限的生命。\n[color=#d189ff]「法术建筑，可被攻击，能够承受2次攻击伤害」[/color]"
  },
  [80622009] = {
    id = 80622009,
    name = "间隔5秒，为周身范围内的友方目标提升攻击10%%，可叠加。\n[color=#d189ff]「法术建筑，可被攻击，能够承受2次攻击伤害」[/color]"
  },
  [80622010] = {
    id = 80622010,
    name = "间隔5秒，为周身范围友方目标附加无敌效果，可叠加。\n[color=#d189ff]「法术建筑，可被攻击，能够承受2次攻击伤害」[/color]"
  },
  [80622101] = {
    id = 80622101,
    name = "放置在成员前方时，可以阻挡敌方。\n[color=#d189ff]「建筑，可被攻击，能够承受1次攻击」[/color]"
  },
  [80622102] = {
    id = 80622102,
    name = "进入泥泞沼泽后，移动速度降低20%%，且无法提升速度。\n[color=#d189ff]「陷阱，不可被攻击，永久生效」[/color]"
  },
  [80622103] = {
    id = 80622103,
    name = "当成员触发该装置时，该名成员会直接损失10%%生命上限的生命值。\n[color=#d189ff]「陷阱，不可被攻击，可生效1次」[/color]"
  },
  [80622104] = {
    id = 80622104,
    name = "当我方成员当前生命值低于50%%时，可为其提供10%%生命上限的生命值。\n[color=#d189ff]「建筑，可被攻击，能够承受2次攻击」[/color]"
  },
  [80622105] = {
    id = 80622105,
    name = "进入腐蚀毒沼后，移动速度降低15%%，且无法提升速度，同时每秒损失1%%生命上限的生命值。\n[color=#d189ff]「陷阱，不可被攻击，永久生效」[/color]"
  },
  [80622106] = {
    id = 80622106,
    name = "对以自身为中心且半径为200的圆形范围内的敌方全体目标造成每次0.5%%生命上限的生命值伤害。\n[color=#d189ff]「建筑，可被攻击，能够承受2次攻击」[/color]"
  },
  [80622107] = {
    id = 80622107,
    name = "当成员触发该装置时，该名成员会被传送至战场任意位置，同时该名成员会重新选择攻击目标。\n[color=#d189ff]「陷阱，不可被攻击，可生效1次」[/color]"
  },
  [80622108] = {
    id = 80622108,
    name = "当成员触发该装置时，该名成员会被击退300的距离。\n[color=#d189ff]「陷阱，不可被攻击，可生效1次」[/color]"
  },
