  [80640103] = {
    id = 80640103,
    name = "尊敬的队长：\n    系统检测到当前账号有违规退款行为，基于您的退款行为，已扣除退款金额对应的源晶。请于1个月内购买补齐差额（即账号内源晶数量大于等于0）；如在1个月后，官方核实账号源晶数量小于0，则会对账号进行封禁处理。请于规定时间内尽快购买补齐源晶。\n\n    注：如已在上述时间内补齐源晶，则本邮件在规定时间后自动失效。"
  },
  [80640111] = {
    id = 80640111,
    name = "新任队长庆贺礼"
  },
  [80640112] = {
    id = 80640112,
    name = "公会事务部"
  },
  [80640113] = {
    id = 80640113,
    name = "尊敬的队长大人，您的探险队组建申请已顺利通过，欢迎加入探险者公会！\n公会为您旅途的起点准备了些许祝贺之礼，还请笑纳。\n我们衷心祈愿您能抵达无尽深渊之底，带领我们解明那无尽灾厄与奇迹的来源。"
  },
  [80640121] = {
    id = 80640121,
    name = "队长，又要出发了吗？"
  },
  [80640122] = {
    id = 80640122,
    name = "公会事务部"
  },
  [80640123] = {
    id = 80640123,
    name = "尽管相识不久，但我能感受到你心中的决意。\n我听说过你的故事，不止那些耀眼事迹。\n\n偶尔也好，请让我能在冒险的路上，更多的了解你。\n<a href=\"https://www.wjx.cn/vm/eM7NKY7.aspx?sojumpparm={uid}\">填写调查问卷</a>\n因为你，星落真的存在。"
  },
  [80640131] = {
