  [80831295] = {id = 80831295, name = "陨落"},
  [80831301] = {id = 80831301, name = "绝境"},
  [80831302] = {id = 80831302, name = "进攻"},
  [80831303] = {id = 80831303, name = "覆灭"},
  [80831304] = {id = 80831304, name = "冒险"},
  [80831305] = {id = 80831305, name = "托付"},
  [80831306] = {id = 80831306, name = "归还"},
  [80832001] = {
    id = 80832001,
    name = "几经辗转，你终于找到了伊涅利丝秘密基地所需要的魔法石，但每个同伴都推诿有事，你只能独自前往她的秘密基地。"
  },
  [80832002] = {
    id = 80832002,
    name = "你到达了伊涅利丝的秘密基地，却只看到了一封信。你依据信上地点寻找伊涅利丝，山路上发现一张染血的公告，以及一个寡言的少女......"
  },
  [80832003] = {
    id = 80832003,
    name = "你担忧伊涅利丝上山，发现魔物明显增多，找到伊涅利丝时，她正被魔物围攻......"
  },
  [80832004] = {
    id = 80832004,
    name = "你与伊涅利丝、莫妮卡遇到了源源不断的魔物群，你让两人暂时撤退。回撤过程中，却遇到更多的魔物围攻......"
  },
  [80832005] = {
    id = 80832005,
    name = "你在山洞没有发现魔物，在各种猜测后，莫妮卡采集了很多“蘑菇”，你们也在山洞底部找到了需要的勃罗特花。"
  },
  [80832006] = {
    id = 80832006,
    name = "你与伊涅利丝、莫妮卡重新上山，点燃了迷烟，一路魔物群都睡着了过去，没想到半途却出了意外......"
  },
  [80832007] = {
    id = 80832007,
    name = "你和伊涅利丝一路逃到崖边，正在快速通过藤蔓索桥时，魔物将藤蔓撞断了......"
  },
  [80832008] = {
    id = 80832008,
    name = "你和伊涅利丝在山中寻找出路，终于与莫妮卡重新相聚。"
  },
  [80832009] = {
    id = 80832009,
    name = "在与莫妮卡道别后，伊涅利丝带你回到了秘密基地，共赏守伊花开。"
  },
  [80832010] = {
    id = 80832010,
    name = "圈落在举办一年一度的收获祭活动，你前赴黑羽的约定。"
  },
  [80832011] = {
    id = 80832011,
    name = "在大会现场，蒙娜慌乱地到处找队伍，被各队嫌弃。蒙娜看到你后，死缠烂打，你和黑羽同意她加入了队伍。主办方说破坏田地的魔物又在聚集了，让大家去除魔。"
  },
  [80832012] = {
    id = 80832012,
    name = "看起来很简单的除魔任务，由于蒙娜与黑羽无法配合，导致花了很多时间。最后打得非常狼狈，灰头土脸，踩线才完成任务。"
  },
  [80832013] = {
    id = 80832013,
    name = "休息日，大家疑惑菲尼斯的去向时，黑羽在蛋糕店打工被众人发现。黑羽因为被同伴调侃娇羞成怒，你帮忙解围，接着了解了黑羽打工的原因。"
  },
  [80832014] = {
    id = 80832014,
    name = "次日早上，蒙娜苏醒后想恶作剧，但结果却出人意料。第二天的晋级赛要求为农作物收集肥料，你们就如何收集肥料进行探讨。"
  },
  [80832015] = {
    id = 80832015,
    name = "你们跑到山中收集肥料，但收效甚微。而后蒙娜决定去偷大型魔物的排泄物，遭到一致拒绝。蒙娜为证明自己将黑羽拐跑了。你们正打算走另一条路时，听到她的求救声，赶去救两人。"
  },
  [80832016] = {
    id = 80832016,
    name = "蒙娜偷大型魔物的排泄物被发现，你们赶到现场救下被魔物吞掉的蒙娜。在一通手忙脚乱后，终于成功带回最优质的排泄物。在被主办方刁难时，菲尼斯出现解围，晋级决赛。你遭到菲尼斯的调侃，菲尼斯暗示下一场比赛的内容。"
  },
  [80832017] = {
    id = 80832017,
    name = "休息日众人去黑羽的店中消费，尼莉莎故意为难黑羽，黑羽不得不屈服......"
  },
  [80832018] = {
    id = 80832018,
    name = "第三日早上，蒙娜苏醒后继续恶作剧，结果依旧出人意料。第三天的晋级赛要求为收割农作物制作器具，你们对此展开了探讨。"
  },
  [80832019] = {
    id = 80832019,
    name = "你们在挑选魔物的时候出现了争论，一番讨论后，众人决定去猎杀最强的魔物。尽管再次出现了小意外，你们最终还是战胜了巨型魔物，剃下了它最硬的坚骨。"
  },
  [80832020] = {
    id = 80832020,
    name = "众人用心打造了一把奇怪的可以切割收获粮草的器具，并提前庆祝。但在使用的时候再次出了意外，引起了大混乱。你们不光失去了所有分数，还面临赔钱的遭遇。最后菲尼斯出现为大家解决了困境，但结局令人哭笑不得。"
  },
  [80832021] = {
    id = 80832021,
    name = "弗拉克说起升级吉米的材料，你们商议后决定分头行动，在商议过程中，你忽然听到鬼侍的声音，但鬼侍没理你，你认为是错觉。"
  },
  [80832022] = {
    id = 80832022,
    name = "你们一起逛街买材料，在看到奇趣魔法道具时，你再次听到了鬼侍的吐槽，你在听到多次后不小心回应吐槽，你与鬼侍面面相觑......"
  },
  [80832023] = {
    id = 80832023,
    name = "回到住处后，鬼侍拉你单独说话，在你和鬼侍双方试探之后发现的确能听到对方的心声，你们想可能和之前毁掉的宝物有关......"
  },
  [80832024] = {
    id = 80832024,
    name = "第二天，鬼侍和你结伴上街，期间她口是心非，心口不一，你们逛了一圈，找到了昨日的商铺，买到了材料。"
  },
  [80832025] = {
    id = 80832025,
    name = "弗拉克重组吉米，大家一起吃饭，交谈中，尼莉莎发现你和鬼侍奇奇怪怪的......"
  },
  [80832026] = {
    id = 80832026,
    name = "维克多在某个废弃的据点居住时，曾经留下了窥探魔眼的“眼珠”，而那里现在被一只巨型魔物占据，你们打算将材料偷到手就走，但却发生了意外......"
  },
  [80832027] = {
    id = 80832027,
    name = "你们撤退后重新商量作战计划，决定第二次出击，战斗到关键的时刻，你和鬼侍靠心声传递配合出手，共同击杀了魔物，拿回了材料。"
  },
  [80832028] = {
    id = 80832028,
    name = "得到材料回去后，你看见鬼侍在河边和弗拉克说话，鬼侍问起镜子的事，等弗拉克离开后，你重提了梦境里的故事。"
  },
  [80832029] = {
    id = 80832029,
    name = "弗拉克又修补了吉米并重新测试，但仍缺最后一个材料。而这时，伙伴们发现鬼侍对你的态度发生了明显改变......"
  },
  [80832030] = {
    id = 80832030,
    name = "伙伴们一起帮弗拉克重新布置工坊，你在寻找最后一道材料的同时，断断续续听到鬼侍遇险，匆忙赶过去救人，却再也无法收到鬼侍的讯息......"
  },
  [80832031] = {
    id = 80832031,
    name = "你找到鬼侍，将她救起到了山洞。两人围火夜谈，鬼侍说起了自己真实的经历，你才知道她性格大变的原因，并向她重新做出了承诺。"
  },
  [80832032] = {
    id = 80832032,
    name = "弗拉克的吉米修复完成并升级成功，你们醒来后，弗拉克将鬼侍赠送的吊坠转交给你，而鬼侍已经不知所踪。"
  },
  [80832033] = {
    id = 80832033,
    name = "尼莉莎为了尽兴，怂恿你提前去，尼莉莎、安妮斯、蒂娜一起挑礼服，准备前往舞会所在的海斯汀斯的秘密庄园。"
  },
  [80832034] = {
    id = 80832034,
    name = "进入庄园后，你们遇到了阿斯特莉亚和领主的女儿阿黛尔。在阿斯特莉亚的招待下，你们感受了豪华奢侈的环境和生活，你闲逛时遇到了正在午睡的阿斯特莉亚......"
  },
  [80832035] = {
    id = 80832035,
    name = "第二天，你无意中听到了领主女儿呵斥下属，又和阿斯特莉亚巧遇。之后，陆陆续续的探险者到达了庄园，你听到了他们正热切讨论着“女神的祝福”......"
  },
  [80832036] = {
    id = 80832036,
    name = "晚上，领主宣布舞会开始，在阿黛尔的挑衅下，阿斯特莉亚不由分说抓着你进入舞池，与你共舞一曲，结束后，你见安妮斯心情不愉，邀请安妮斯跳舞，然而这时异变突生......"
  },
  [80832037] = {
    id = 80832037,
    name = "舞会现场一片混乱，大家发现失踪的都是手持邀请函探险者中的强者，这时会场周围出现了许多魔物，要将剩余的人一起杀掉，阿斯特莉亚找到你，与你们一起分析形势，决定先离开大厅。"
  },
  [80832038] = {
    id = 80832038,
    name = "你们逃出大厅后，阿黛尔出现了，她说魔物骚动是意外，让大家会房间等待，但探险者们并不服气，而阿黛尔的耐心也即将告罄......"
  },
  [80832039] = {
    id = 80832039,
    name = "你们被迫无奈回到房间，商讨计划中，阿斯特莉亚提到庄园的内部有她没见过的魔法阵，你们决定在庄园内部分头调查。"
  },
  [80832040] = {
    id = 80832040,
    name = "你在和菲尼斯搜索舞会大宅，聊天的时候发现菲尼斯突然不见了，内部走廊重重叠叠，你进入一个秘密房间，听到了领主的秘密，正当被察觉时，阿斯特莉亚捂住你的嘴和你藏在隐秘处，等两人走了再现身，没想到阿黛尔杀了个回马枪......"
  },
  [80832041] = {
    id = 80832041,
    name = "你和阿斯特莉亚杀了出去，与菲尼斯与蒂娜汇合，四人交流线索，经过推断，你们发现魔法阵原来就在舞会大厅，而领主就在魔法阵下方的地宫中，就在你们打算破坏魔法阵时，阿黛尔早已守在了那里......"
  },
  [80832042] = {
    id = 80832042,
    name = "阿黛尔死后，你们到达了地下宫殿，看到了昏睡过去的安妮斯和其他探险者，而领主正在做最后的祈祷仪式，你们及时阻止了仪式，而领主在这时放出了一只巨型魔物......"
  },
  [80832043] = {
    id = 80832043,
    name = "你们杀掉魔物后，领主献祭了自己变成了堕落者，在大家严阵以待时，堕落者竟然自己崩毁了，而崩毁的能量竟然让整个地宫都要坍塌......"
  },
  [80832044] = {
    id = 80832044,
    name = "离开地下宫殿后，安妮斯也转醒，你们离开了庄园，阿斯特莉亚向你们道歉，也对你的相救表示感激。"
  },
  [80832045] = {
    id = 80832045,
    name = "陆玄捡到婴儿，思量了一番，打算把婴儿送到孤儿院，交由他人抚养，一路婴儿上安静乖巧，陆玄心情很好，顺利到达孤儿院。"
  },
  [80832046] = {
    id = 80832046,
    name = "陆玄去孤儿院找默尔曼，将女婴托付，但还没等到陆玄下深渊，就被孤儿院的人找到折返。"
  },
  [80832047] = {
    id = 80832047,
    name = "女婴哭闹不止，只认陆玄，无奈之下只能由陆玄带回逍遥坊。从此陆玄开启了奶爸的身份，时时为养育女婴而发愁。"
  },
  [80832048] = {
    id = 80832048,
    name = "陆玄给女婴缝制了新衣服，有一次发现女婴在玩他的玉佩，发现女婴有修行的天赋，于是为她取名为灵遥，打算大一点教她武技。"
  },
  [80832049] = {
    id = 80832049,
    name = "灵遥4岁，陆玄带灵遥去孤儿院，第一次见到了你，恰逢你正回孤儿院，陆玄让你帮忙照看灵遥。"
  },
  [80832050] = {
    id = 80832050,
    name = "你提起了你和陆玄的旧事，带着灵遥去小时候玩耍的的地方，正当高兴时，一只饿狼悄悄出现了......"
  },
  [80832051] = {
    id = 80832051,
    name = "灵遥学到新武技，去孤儿院找你，却得知你去深渊毕业考试了，灵遥想去深渊找你，陆玄告诉灵遥，只有强大的探险者才能在深渊来去自如，灵遥下恒心好好练武。"
  },
  [80832052] = {
    id = 80832052,
    name = "灵遥得知你毕业了，再次到孤儿院找你，届时你已成立了ACE探险队，要去深渊探险，在与灵遥再次玩耍后，灵遥决定以后加入你的探险队，并为此做了约定。"
  },
  [80832053] = {
    id = 80832053,
    name = "灵遥8岁了，陆玄教导灵遥学武，并以举例教导灵遥做人学武的道理，但灵遥的理解似乎出人意料。"
  },
  [80832054] = {
    id = 80832054,
    name = "陆玄和灵遥路过了一个残破的据点，在铲除参与魔物后，灵遥发现了濒死的女人护着蕾米，女人将蕾米托孤后无憾死去。"
  },
  [80832055] = {
    id = 80832055,
    name = "灵遥学陆玄的方式教蕾米，又学你的方式去带蕾米玩，差点让蕾米遭遇危险，灵遥惊险带蕾米回家，等陆玄回来的时候，竟然得知了ACE团灭的消息。"
  },
  [80832056] = {
    id = 80832056,
    name = "灵遥到你家看望你，正好看到公会人在问你话，你拒绝回答后，公会的人离开，灵遥开导你后，决心暗中调查真相。"
  },
  [80832057] = {
    id = 80832057,
    name = "灵遥12岁的时候，武技已有小成，可以独自下深渊游历。在完成陆玄的任务后，她约了情报员找绝境之地的线索，并打算早点完成回去和你赴秋日庆典之约。"
  },
  [80832058] = {
    id = 80832058,
    name = "灵遥到达一个贫民窟，她将吃的给快饿死的女孩，贪得无厌的爹来却来抢她更多的食物，被她教训了一顿，但在她离开前，却得到了女孩的道歉和感谢，也得到了女孩提供的线索。"
  },
  [80832059] = {
    id = 80832059,
    name = "灵遥找到了去绝境之地的“门”，正打算进去探查时，意外碰到了银翼审判者，银翼审判者关闭了“门”，并召唤了许多魔物，灵遥清除魔物受了不少的伤，线索也就此中断了。灵遥在整理好自己后，赶回大陆赴与你的庆典之约。"
  },
  [80832060] = {
    id = 80832060,
    name = "灵遥和你一起开心地逛庆典，并没有提起为你做的任何事，但你却知道她一直的努力与付出，在感谢灵遥时，你发现她的腿受伤了，将她背了起来，你们聊着天，走在长长的街头，直到人烟散去。"
  },
  [80832061] = {
    id = 80832061,
    name = "你到达了和艾瑟儿约定的圈落，她准备了一个自制的大箱子，里面装了许多探险装备，包括工具、书籍和补给，药，并精确地和你说路线与计划。"
  },
  [80832062] = {
    id = 80832062,
    name = "两人一路前往目的地的路上，遇到了魔物与阻碍，都被艾瑟儿冷静轻松地解决，并生切食用魔物能吃的部位，你不由惊讶她强大的野外生存能力。"
  },
  [80832063] = {
    id = 80832063,
    name = "临近傍晚，你们到达荒废的祭坛，开始寻找地宫的大门，发现地宫的入口就在祭坛下方，但因为复杂的符号和机关，无法立即打开大门，你们休息一晚准备第二天继续尝试。"
  },
  [80832064] = {
    id = 80832064,
    name = "翌日，在尝试各种办法后，艾瑟儿炸出祭坛本来的符文，又从她的大箱子中取出一本古籍，找到了符文的来源，经过一番努力，两人终于破解了谜题，地宫大门就此开启。"
  },
  [80832065] = {
    id = 80832065,
    name = "你们进入地宫，穿过一系列的机关陷阱、迷宫。发现了描绘祭祀的壁画，在解决了一系列难题后，成功进入地宫第二层。"
  },
  [80832066] = {
    id = 80832066,
    name = "你们进入了大门，通过机关重重的长廊，在其中一个房间发现了药剂师的工坊，并记录着救人的实验过程，艾瑟儿不慎被一种罕见的毒虫咬伤，开始出现幻觉，敌我不分，你将她捆缚喂解毒药水。"
  },
  [80832067] = {
    id = 80832067,
    name = "两人来到了地宫大殿，这里布满了巨型魔物雕塑，雕塑突然“复活”，你们不得不的战斗，在鏖战时，发现了一些崇拜魔物、诡异仪式的壁画，你从壁画里发现雕塑的弱点，你将弱点告诉艾瑟儿，两人协作击破魔物"
  },
  [80832068] = {
    id = 80832068,
    name = "你们发现了一个隐藏祭坛，和地面的祭坛一模一样。原来这个地宫是专门用于实验和仪式的祭坛，所谓救人的办法是要血祭他人的生命，而复活的只有魔物。艾瑟儿没找到药方，在感谢你后与你道别，继续上路。"
  },
  [80832069] = {
    id = 80832069,
    name = "蒙娜找到了罗亚，死皮赖脸缠着罗亚，要和罗亚一起完成任务。罗亚无奈，只能让蒙娜跟着。"
  },
  [80832070] = {
    id = 80832070,
    name = "一路上和罗亚聊天，对罗亚的来历和经历都很好奇。蒙娜打听她一直接取任务的原因，猜测是否是经济困难或者需要某些帮助等，但罗亚一一否认了。"
  },
  [80832071] = {
    id = 80832071,
    name = "罗亚缠不过蒙娜的好奇心，给蒙娜讲了她从进入公会探险训练学院，到毕业之后，如何加入守望探险队的过程。"
  },
  [80832072] = {
    id = 80832072,
    name = "两人到达了村庄开始帮助村民，蒙娜还想继续听之后的故事，但罗亚忙起来根本不理人，蒙娜只能跟着一起干活，直到累瘫睡着。"
  },
  [80832073] = {
    id = 80832073,
    name = "罗亚做噩梦醒来，蒙娜还在入睡，罗亚出门帮助村民，蒙娜醒来后发现罗亚已经快把活干完了，上前一起帮忙，蒙娜提出还继续想听罗亚讲故事。"
  },
  [80832074] = {
    id = 80832074,
    name = "罗亚将守望遇到危险的起因、以及过程一一讲述，蒙娜插嘴询问。罗亚发现原来守望曾经有很多条路可以走，但每次都选择了注定灭亡的路。"
  },
  [80832075] = {
    id = 80832075,
    name = "罗亚继续讲述守望的故事，他们被兽潮围困，坚持了十六个日夜，终于只剩下了她一个人。"
  },
  [80832076] = {
    id = 80832076,
    name = "罗亚活下来了，却无法安心活着，只能不停地接委托，一停下来就会非常痛苦，蒙娜开导她，让她发现不同的人生态度，也逐渐明晰了人生的目标和将来的路。"
  },
  [80832077] = {
    id = 80832077,
    name = "抚慰师来到村庄后，得知村民们无法区分颜色，也全都变成了哑巴，他们的世界变得灰暗单调，给他们的生活带来了很大的困扰。"
  },
  [80832078] = {
    id = 80832078,
    name = "三人根据找到的线索，一个个询问村民探查原因，但因为交流困难，造成了很大的阻碍。"
  },
  [80832079] = {
    id = 80832079,
    name = "在寻找线索时，抚慰师在一个小孩子身上发现了端倪，并尝试着帮助村民们恢复对颜色的感知。"
  },
  [80832080] = {
    id = 80832080,
    name = "在抚慰师的多方验证下，她发现村民是中了从未见过的毒，并将这件事告诉了颂道使和慈悲者。"
  },
  [80832081] = {
    id = 80832081,
    name = "众人一起寻找解毒的办法，抚慰师尝试食用各种毒草，发现了毒的来源，短暂失去了声音，世界也变得一片灰暗。"
  },
  [80832082] = {
    id = 80832082,
    name = "在失声和色盲期间，抚慰师与村民们找到了新的相处方式，并尝试着调配解药，根据毒物来源寻找到了解毒的方法。"
  },
  [80832083] = {
    id = 80832083,
    name = "抚慰师去往森林，和颂道使、慈悲者一起在夜晚收集花瓣，找到了解毒的花草，用魔药制作成了解药，并身先试药。"
  },
  [80832084] = {
    id = 80832084,
    name = "村民们恢复了色彩与欢声笑语，村长告诉了抚慰师中毒的原委，竟然只是阴差阳错的巧合，村民们欢送圣歌队员，给予她们最真诚的祝福。"
  },
  [80832085] = {
    id = 80832085,
    name = "列蒂西雅布置舞会会场，和莉娃忙得昏天黑地的时候，你与艾琳、菲尼斯一行人到达，与她短暂叙旧后，一起帮忙筹备会场。"
  },
  [80832086] = {
    id = 80832086,
    name = "在一同品茶后，你与列蒂西雅逛街采购物资，一路上发生了不少趣事。"
  },
  [80832087] = {
    id = 80832087,
    name = "几人筹备好会场后，奥萨丁赶到发生了一些趣事，你送奥萨丁护甲为毕业礼物，奥萨丁特别激动，恰好被列蒂西雅看到，列蒂西雅装作无事借口离开。"
  },
  [80832088] = {
    id = 80832088,
    name = "筹备中途，你以休息为由找到列蒂西雅，将早就准备好的魔法小提琴送给列蒂西雅，列蒂西雅拿到礼物非常高兴，在和你聊天后，在晚上偷偷练习，想专门为你演奏一曲。"
  },
  [80832089] = {
    id = 80832089,
    name = "你与几人讨论特邀嘉宾需要表演的节目，艾琳想表演话剧，甚至连剧本都想好了，本打算让列蒂西雅休息时，列蒂西雅强行要求参与。"
  },
  [80832090] = {
    id = 80832090,
    name = "艾琳给你与菲尼斯、列蒂西雅讲述舞台剧剧本的内容，以及每个人需要扮演的角色，在分配角色与互动过程中，发生了愉快的小插曲。"
  },
  [80832091] = {
    id = 80832091,
    name = "列蒂西雅非常忙碌，每日除了话剧排练，还要排练自己的节目，以及偷偷练习小提琴。在看到你与艾琳的默契表演后，她更加努力地在深夜独自练习，想将完美的一面呈现给你们。"
  },
  [80832092] = {
    id = 80832092,
    name = "新年舞会正式开始，学院表彰列蒂西雅、奥萨丁（舞会）等优秀学子，赋予美好的寄语，首先由特邀嘉宾带来第一个节目，你们在上演舞台剧时，没想到艾琳竟然中途突然改了剧本......"
  },
  [80832093] = {
    id = 80832093,
    name = "众人对改编的剧情大声叫好，奥萨丁（舞会）尤其捧场，维特却吐槽没什么了不起，却遭到周围观众的反驳，他哑口无言，看见演员们都回到了舞台下，但艾琳没回来。"
  },
  [80832094] = {
    id = 80832094,
    name = "你与菲尼斯回来后，奥萨丁对你们的表演赞不绝口，维特不冷不热地抱怨被菲尼斯呛了回去。不一会儿艾琳也回来了，众人并没有在意她的临时消失，都在期待列蒂西雅的压轴表演。"
  },
  [80832095] = {
    id = 80832095,
    name = "列蒂西雅上台表演钢琴曲，音乐与魔法的结合让师生震撼，她成了世界唯一的焦点。一曲结束后，全场掌声雷动。"
  },
  [80832096] = {
    id = 80832096,
    name = "钢琴演奏完毕后，列蒂西雅返回休息室准备小提琴演奏，莉娃看出来她十分紧张，会场上主持人宣布特别节目，表演者希望将这个节目献给她最好的朋友，而这时你收到消息有魔物侵袭，拉着菲尼斯、奥萨丁离开，艾琳则找借口留下了。"
  },
  [80832097] = {
    id = 80832097,
    name = "舞台上传来高跟鞋哒哒的声音，一个高挑的声影出现在舞台中央，一束灯光打了下来，列蒂西雅看向你们所在的位置发现只有艾琳，你与菲尼斯、奥萨丁都不在了，心里很是失落，但依然完美的演奏完毕。"
  },
  [80832098] = {
    id = 80832098,
    name = "会场的琴声隐约传来，你与菲尼斯、奥萨丁在击杀魔物时，渐渐让菲尼斯发现了端倪，他故意弄伤了奥萨丁，你虽然不知道原因，但仍觉得菲尼斯又有什么恶趣味。"
  },
  [80832099] = {
    id = 80832099,
    name = "晚会已经结束了，你们来到会场外庭院中休息，正在闲聊时，艾琳出现，看着菲尼斯和奥萨了灰头士脸的，就拉着两人以疗伤为由离开，而这时你听到了身后一阵悠扬的琴音......"
  },
  [80832100] = {
    id = 80832100,
    name = "一曲结束后，你与列蒂西雅相顾无言，就在你们都不知道要说什么之时，艾琳恰到好处出现缓解气氛。列蒂西雅对艾琳道谢，艾琳表示要感谢的人应该是你，当整点到来时，列蒂西雅在星空下听见了你的新年祝福。"
  },
  [80832101] = {
    id = 80832101,
    name = "米亚姆想参加圈落举办的某个竞赛，最终奖品是伊夫家提供的千里眼辅助魔法道具，她害羞地在灵遥家门口，灵遥二话不说拉着她去参加竞赛。"
  },
  [80832102] = {
    id = 80832102,
    name = "米亚姆和灵遥组队参加比赛，竟遇到了希尔和艾莉亚，蕾米和赛珂，三队人马互相赛前叫阵，谁也不服输。"
  },
  [80832103] = {
    id = 80832103,
    name = "米亚姆与灵遥在干扰攀岩中遇到的对手魁梧高大，他们以为小女孩好欺负，没想到两人以巧破力，米亚姆在灵遥的护航和配合下顺利击败对手，进入下一场比赛。"
  },
  [80832104] = {
    id = 80832104,
    name = "第二场比赛是草地排球，另一组对手在排球中施加魔法准备使诈，但被两人逐一识破，让对面自作自受，惊险进入第二天的决赛。"
  },
  [80832105] = {
    id = 80832105,
    name = "第二天，两人来到比赛会场，希尔、艾莉亚，蕾米和赛珂都来了，他们也顺利进入了决赛，三队在赛前垃圾话对抗后，准备开始比赛。"
  },
  [80832106] = {
    id = 80832106,
    name = "路段分三个阶段，分别是要塞到森林，森林到山谷、山谷到尖塔，米亚姆和灵遥起飞后，一路有魔物阻拦，她们甩掉了大部分参赛人员成功进入了山谷区域。"
  },
  [80832107] = {
    id = 80832107,
    name = "在兵荒马乱的躲避和较量后，艾莉亚得意忘形撞了山，赛珂帽子飞了去捡被淘汰，而米亚姆的扫把被骚扰的魔物打断了。"
  },
  [80832108] = {
    id = 80832108,
    name = "灵遥急中生智，带着米亚姆御剑飞行，载着米亚姆第一个冲入终点，最后却被罚犯规成绩作废，事后米亚姆仍感谢灵遥，因为过程比结果更重要，她也因此和朋友们度过了愉快的时光。"
  },
  [80832109] = {
    id = 80832109,
    name = "贫民窟小孩米娅告诉尼基塔，克里莫几天前前往了据点做生意一直没回来，尼基塔随即前往据点探查。"
  },
  [80832110] = {
    id = 80832110,
    name = "尼基塔进入暗域，陷入迷雾，在迷雾中击杀魔物，遇到蒙眼的岚，和岚不打不相识，得知岚来暗域调查的"
  },
  [80832111] = {
    id = 80832111,
    name = "岚带尼基塔去避难所找人，见到了人性百态，尼基塔没有找到克里莫，打听到了暗域更深层次的情报离开，岚若有所思，追上尼基塔。"
  },
  [80832112] = {
    id = 80832112,
    name = "尼基塔根据情报去多个调查点，在路上揭穿了岚故意跟着她的原因，岚大方承认，说是来找宝物的，这时两人听到呼救声。"
  },
  [80832113] = {
    id = 80832113,
    name = "根据线索，两人找寻途中再次遇到迷雾，遭到一个心智受影响的探险者偷袭，击败该探险者后，该探险者恢复清醒，说他遭遇到了一个实力强大的堕落者。"
  },
  [80832114] = {
    id = 80832114,
    name = "追魔物至暗域中心，两人正在讨论如何救小孩时，发现这里全是被不明物质包裹的人类，随即周围出现了众多魔物"
  },
  [80832115] = {
    id = 80832115,
    name = "两人击败周边所有的魔物后堕落者登场，与两人战斗。尼基塔被激发出战斗血性，越打越开心"
  },
  [80832116] = {
    id = 80832116,
    name = "公会的人陆续出现，尼基塔寻问无果，意外找到了穿着女装帮忙的克里莫，原来克里莫被堕落者生前认成了女儿。尼基塔嘲笑他，带着克里莫返回了贫民窟"
  },
  [80832117] = {
    id = 80832117,
    name = "菲莉亚在村庄附近收集草药的同时，发现娜莎在悄悄跟随，她开始没在意，魔物出现后，她让娜莎离开。但娜莎希望成为和她一样能帮助大家的人。"
  },
  [80832118] = {
    id = 80832118,
    name = "娜莎一直默默跟着菲莉亚，在知道原因后，菲莉亚被她的纯真和善良触动，允许让她跟自己一起学习。"
  },
  [80832119] = {
    id = 80832119,
    name = "娜莎跟着她学习魔法、植物、药理各种知识。娜莎非常有天赋，善于画画将东西记下来，但有时会头晕，菲莉亚担忧她药物过敏，将药理相关的计划暂时停止了。"
  },
  [80832120] = {
    id = 80832120,
    name = "一天娜莎照常找菲莉亚学习，验证学习成果。娜莎得到了菲莉亚的夸奖，正高兴的时候，突然病倒了。"
  },
  [80832121] = {
    id = 80832121,
    name = "原来娜莎早就得了绝症，她知道自己的情况后仍然乐观，反而安抚菲莉亚不要伤心。"
  },
  [80832122] = {
    id = 80832122,
    name = "菲莉亚重启了还在实验阶段的，魔法药理技术，在村民的回馈下，她拿到了许多必要的材料，但缺一样只能打败魔物去取。"
  },
  [80832123] = {
    id = 80832123,
    name = "她犹豫思考之后，决定前往山谷摘取药草，她辛苦打败了魔物，狼狈地拿到了最后一味药草，带着一身的伤回来了。"
  },
  [80832124] = {
    id = 80832124,
    name = "菲莉亚治好了娜莎离开了村落，临走前，娜莎送给了菲莉亚一幅画，是两人的「合照」，再之后，菲莉亚与你相遇了。"
  },
  [80832125] = {
    id = 80832125,
    name = "あなたたちはシェラとレムと共に手がかりに基づいて細石村に到着し、情報屋の言うオリアンという人を見つけた。話をして探りを入れてみると、オリアンは実は闇夜村から出てきた人の子孫であることが分かった。闇夜村に行きたいなら、ずっと細石村を騒がせている魔物を退治し、必要な材料を持ち帰ってほしいという。"
  },
  [80832126] = {
    id = 80832126,
    name = "一行は魔物を退治して材料を手に入れると、オリアンに渡した。オリアンはあなたたちに闇夜村の場所と、手に入れた物を使って村に入る方法を教えた。ついでに亡くなった家族の遺品を持ち帰ってほしいと頼んだ。一行は引き受けて、闇夜村に出立した。"
  },
  [80832127] = {
    id = 80832127,
    name = "闇夜村に着くと、そこはまるでおとぎ話の世界のようだった。しかし村長は今年の月光祭は開催できないという。これまで祈祷に使われていた宝物の鏡が割れてしまったせいだ。鏡がないと月の光を反射させて湖を照らすことも、ランタンを飛ばして霧を散らすこともできない。シェラとレム、それにあなたたちは修復の手伝いを申し出た。"
  },
  [80832128] = {
    id = 80832128,
    name = "一行は鏡を見た後、鏡を補修する材料を探し始めたが、どれも鏡に合わなかった。シェラのひょんな発見から素材について思い当たり、シェラとレムは意気込んだ。一行はひと休みしてから、翌日集落に材料を買いに行くことにした。"
  },
  [80832129] = {
    id = 80832129,
    name = "翌日、想定外の事態が起きて、あなたたちは二手に分かれざるを得なくなった。ネリッサ、ティナ、フェニスは材料を探しに行き、あなたとアネシ、シェラ、レムは魔物退治に向かった。あなたたちは湖の環境を破壊することなく無事に魔物を追い払った。"
  },
  [80832130] = {
    id = 80832130,
    name = "あなたとアネシ、シェラ、レムは宿に帰って長い間待ったが、他の3人は一向に帰ってこない。探しに行こうとしたとき、3人が帰ってきた。口ゲンカばかりしているが実は仲が良いティナとネリッサは、シェラとレムのようだ。彼らは村長に修復用の材料を渡し、鏡が復元された。月光祭は例年通り行われ、村人たちは小躍りして喜んだ。"
  },
  [80832131] = {
    id = 80832131,
    name = "月光祭前夜、一行は村人に習って、祭典で空に放つランタンを手作りした。あなたたちとシェラ、レムは心から語り合った。祭典が始まって願い事をする段になり、一行は湖のほとりに向かった。"
  },
  [80832132] = {
    id = 80832132,
    name = "一行は湖のほとりにやって来た。月光と鏡が互いに照らし合う中、皆は一斉にランタンを飛ばして、願いを訴えた。月の光の影響で空間に裂け目が開き、二人はようやく元の世界に帰れることになった。発つ直前、二人はあなたたちに感謝と別れを告げた。"
  },
  [80832133] = {
    id = 80832133,
    name = "你与同伴在赶路过程中，意外进入了古堡结界，多处调查之后，发现出不去了，在看到还有其他探险者时，你决定先进入古堡探查。"
  },
  [80832134] = {
    id = 80832134,
    name = "在古堡中也有其他探险者进入，但因为反抗被古堡主人杀掉。原来一旦进入古堡，古堡主人就在心中认定了他们各自的身份，而这时，你突然被袭击了......"
  },
  [80832135] = {
    id = 80832135,
    name = "菲比走后，众人交流，大家很意外你和埃斯特拉相识，几人交换了情报与线索，原来埃斯特拉也是被困在古堡中的人，你们探讨该如何逃出古堡，安妮斯的情绪一直很低落。"
  },
  [80832136] = {
    id = 80832136,
    name = "众人只能按照各自的身份办事和寻找逃离的线索，其他人都去了相应的位置，菲比对你不信任，指定要考验你是否能成为合格的姐夫。"
  },
  [80832137] = {
    id = 80832137,
    name = "由于你没有与贵族相处的经验，埃斯特拉决定和威士忌带你紧急补课，告诉你菲比的禁忌，以及菲比亲姐姐的喜好，打算和威士忌一起训练你。"
  },
  [80832138] = {
    id = 80832138,
    name = "你跟埃斯特拉进行礼仪训练，过程中不小心亲密接触，埃斯特拉面红耳赤说你过关，赶紧把你哄走了。"
  },
  [80832139] = {
    id = 80832139,
    name = "你到达菲比处，在令人意外的要求下通关了，你查到了菲比的一些故事和蹊跷处（古堡曾发生大火，她玩捉迷藏，姐姐为了找她死在玩具房，随即她也被大火吞噬，但菲比失去了这段记忆）"
  },
  [80832140] = {
    id = 80832140,
    name = "菲比走后，你与同伴们交流，了解到古堡其实是虚假的。这时菲比杀了个回马枪，埃斯特拉与你逢场作戏，菲比很满意，催促大家干活，将婚礼安排上了日程。"
  },
  [80832141] = {
    id = 80832141,
    name = "菲比宣布了要尽快举行姐姐的婚礼，让众人做准备，众人对此反应不一。埃斯特拉也认为太仓促，想拖延时间，但你却发现菲比即将暴走，只得暂时同意，稳住了菲比。"
  },
  [80832142] = {
    id = 80832142,
    name = "菲比走后，你们和埃斯特拉讨论破解结界的事，总结出了原因：是因为古堡主人执念不散，只要达成她的愿望，就能离开这里。"
  },
  [80832143] = {
    id = 80832143,
    name = "你与埃斯特拉寻找破解结界的办法，在花园里碰见菲比后，在菲比的“期待”下被迫秀恩爱，菲比心满意足地离开。"
  },
  [80832144] = {
    id = 80832144,
    name = "众人筹备现场，汇报自己的线索以及发现的破绽，蒂娜总结出关键点在于菲比身上，只要趁菲比送祝福的时候，杀掉她就能破开结界，这时菲比到了，把你和埃斯特拉叫走。"
  },
  [80832145] = {
    id = 80832145,
    name = "菲比把你和埃斯特拉带到了试衣间，要你给埃斯特拉穿上婚纱，她高兴地走后，埃斯特拉想自己穿婚纱，却发生了点状况......"
  },
  [80832146] = {
    id = 80832146,
    name = "你和埃斯特拉到达婚礼现场，在婚礼曲里和埃斯特拉一起踏上红毯，众人反应不一，菲比念了婚礼誓词，见证你与埃斯特拉的爱情。"
  },
  [80832147] = {
    id = 80832147,
    name = "菲比欢喜雀跃拥抱埃斯特拉，还警告你不准欺负姐姐，埃斯特拉告诉她自己很幸福后，菲比的黑气完全消散了，变成了可爱的女孩，原来女孩和姐姐早就死了，这一切都是菲比的梦。"
  },
  [80832148] = {
    id = 80832148,
    name = "菲比执念消除后，安妮斯超度了菲比，古堡结界消失。众人与埃斯特拉道别，埃斯特拉让你赶紧去罗斯伯尔家族提亲。"
  },
  [80832149] = {
    id = 80832149,
    name = "枭查到隐秘的消息有宝物出没，她去往深渊的一处人迹罕至的沙海，在去沙海的必经之路上遇见了谢利，两人发现对方身手不俗。"
  },
  [80832150] = {
    id = 80832150,
    name = "沙海入口有卖食物和情报的摊贩，枭找他们打听更多的情报，再次遇到了谢利，谢利在打听情报时对药物表现得有些在意，得知白天不宜进沙海后，枭决定入夜出发，当晚邀请谢利同行。"
  },
  [80832151] = {
    id = 80832151,
    name = "就算有情报，枭和谢利进入沙海后仍然迷了路，路上她们遇到了来寻宝的探险队，一同寻找宝藏时，前方出现类似海市屋楼的幻象，探险者们争先恐后上去，死在了沙海陷阱里，只有枭和谢利没有受到影响。"
  },
  [80832152] = {
    id = 80832152,
    name = "她们继续按照情报所指的方向前行，越接近目的地，沙化的毒物和魔物越来越多，她们碰见了几队探险者，没多久沙尘暴席卷而来，许多人葬身其中，枭和谢利躲过危机，一座尘封已久的古镇出现了。"
  },
  [80832153] = {
    id = 80832153,
    name = "一群人进入古城，就像到了陆地世界，枭走着走着，发现谢利和探险者们都不见了。原来他们看到了的幻象，是心中最渴望的场景，枭也见到了久违的，爱她的父母。"
  },
  [80832154] = {
    id = 80832154,
    name = "与此同时，谢利也进入了幻境，在看清幻境后毫不留情地斩断。她醒后发现整个古城都是幻象，只有黄沙中心一个古老的塔存在，而枭和其他的探险者都陷入了黄沙构建的美梦中，正在缓缓下沉。"
  },
  [80832155] = {
    id = 80832155,
    name = "枭和家人生活一段时间后，母亲与她道歉，和她道别，枭告别了母亲，在危机时刻醒了过来，也看见了那座塔。"
  },
  [80832156] = {
    id = 80832156,
    name = "大量的财宝从塔里溢出，枭刚要进塔被谢利叫住。原来古塔已经成被人的欲望养成了一个有意识的怪物。两人轻而易举毁掉了它，古塔腐朽倒塌在黄沙中，谢利拿了一块金币朗笑着离开了，枭则继续踏上寻找诅咒宝物的旅途。"
  },
  [80832157] = {
    id = 80832157,
    name = "永夜森林开放时，你与鬼王通过卷轴进入，包括你们在内，一起进入了七人。你们发现了森林边缘有座小屋，众人一起进入小屋后，一个戴面具的小丑说着欢迎辞，并分发给了你们每人一张神秘的卡牌。"
  },
  [80832158] = {
    id = 80832158,
    name = "你拿到了勇者杰克的身份，和露丝是恋人，任务是要得到露丝祖父的宝藏，小丑在说完游戏规则后，每个人开始介绍自己的身份和目的，露丝的扮演者正是鬼王，这时，有人违背身份设定突然死亡，众人才知，这是一场非生即死的游戏。"
  },
  [80832159] = {
    id = 80832159,
    name = "离开小屋后，潜行者提出共享秘密，被多人拒绝了，众人只能分头行动。鬼王很失望，她拿到的是弱小可怜的露丝，不擅长演戏的她好几次险些被小丑抓到，因为你的掩护才得以安全。"
  },
  [80832160] = {
    id = 80832160,
    name = "你和鬼王同行时，遇到了掘墓者和商人，他们见鬼王好欺负，想抢夺你们手中的线索，这时异变突生......"
  },
  [80832161] = {
    id = 80832161,
    name = "几人看到宝藏都很激动，在发现如何打开封印后，掘墓者和商人率先冲了上去，而后，掘墓者突然做出了让众人震惊的举动......"
  },
  [80832162] = {
    id = 80832162,
    name = "至此，参与游戏的人只剩下了三个，这时，你推断出了潜行者的秘密，鬼王也揭穿了她的伪装，潜行者竟然是鬼牌的鬼姬，而她所持有的潜行者的真实身份，也让人诧然。"
  },
  [80832163] = {
    id = 80832163,
    name = "鬼王道出了永夜森林的真相，原来森林里根本没有宝藏，而是封印了一只魔物，她说完了关于森林的传说后，你决定除掉魔物，以绝后患。"
  },
  [80832164] = {
    id = 80832164,
    name = "鬼王和鬼姬不理解你的做法，但你想让这一切都结束，不让后来人再受害，说服两人后，她们释放了魔物，你们一同除魔后，封印消失了，永夜森林重现光明，鬼王也恢复了霸道蛮横的本性，她走后给你留下了红桃扑克牌，暗示你早已获得了露丝祖父的宝藏，那就是露丝的爱。"
  },
  [80832165] = {
    id = 80832165,
    name = "到了约定的时间，圣光使与抚慰师坐船进入湖心迷雾，之后听到了幻声，圣光使用魔法隔绝声音结界，接着两人遇到漩涡被吞噬。"
  },
  [80832166] = {
    id = 80832166,
    name = "两人苏醒后，发现到了湖底的一个大型空间，船体破碎无法返航，她们搜集线索，推断出了那些失踪的人都掉到这里了，两人探测到了湖底的那道光，这时发现身后竟然有人跟踪......"
  },
  [80832167] = {
    id = 80832167,
    name = "乔伊告诉两人，原来失踪的探险者们在跌入湖底后，魔法尽失，一无所有，并划分了强者和弱者的任务，而这时，领头者罗恩走了过来......"
  },
  [80832168] = {
    id = 80832168,
    name = "两人到了他们的群居点，见罗恩放弃弱者，认为这并不公平。在将罗恩打败后，两人看到了他们的困境，众人陷入绝望时，两人鼓励大家让大家别放弃，并带队找到了那道光的入口，启动了枯涸的魔法阵，湖泊底部一座水底建筑被打开。"
  },
  [80832169] = {
    id = 80832169,
    name = "众人进入水底建筑，遇到需要协作的机关，需要同时触发多个开关，探险者们开始争吵，但在危机下被迫合作。"
  },
  [80832170] = {
    id = 80832170,
    name = "众人进入了第一道门，见到了许多奇怪的文字，经过圣光使与抚慰师分析，猜测是实验失败的信息和所谓神秘宝藏的来源，探险者们在看到结果后逐渐放下成见，共同应对困境寻找回去的路，而后圣光使解开了谜题，打开了第二道门。"
  },
  [80832171] = {
    id = 80832171,
    name = "大门内有大量的食物和财富，但一瞬间就腐烂了，其中还出现了具有传送功能的魔法阵，两人猜想这里是某个古文明的避难所，这时突然发生了变故......"
  },
  [80832172] = {
    id = 80832172,
    name = "圣光使和抚慰师启动了传送阵，成功带失踪者回到了镜湖据点郊外，家人们纷纷来迎接自己的亲人，圣光使与抚慰师见众人与家人团聚，不留姓名地，一起悄悄离开了据点，但行好事，莫问前程。"
  },
  [80832173] = {
    id = 80832173,
    name = "诺维奇帝国的大王女蕾妮希雅出生了，她拥有顺位的王位继承权，并且获得了继承人才能拥有的白蔷薇之梦。她的母亲因难产导致之后身体愈发虚弱，在公主六岁时去世。公主魔法的天赋极高，父亲对她十分宠爱。"
  },
  [80832174] = {
    id = 80832174,
    name = "国王娶了新王妃，新王妃对蕾妮希雅很好，后来新王妃生出了一名王子，在王宫大臣的劝诱下，王妃对公主的态度逐渐转变。蕾妮希雅在12岁的法礼仪式时，收到了许多礼物，包括挚友诺埃尔和王妃的贺礼。"
  },
  [80832175] = {
    id = 80832175,
    name = "王妃在表面上仍对蕾妮希雅很好，但实际拉拢背后王公大臣的势力打压她，同时公主精神状态越发差劲，并时常产生幻觉。国王也虽然依然宠爱女儿，但因为近年来边域战乱吃紧，公主15岁时，国王并没参加上蕾妮希雅的剑礼仪式。"
  },
  [80832176] = {
    id = 80832176,
    name = "蕾妮希雅18岁，在进行王储加冕仪式之前需要通过试炼，必须携带亲卫队赴深渊完成猎杀魔物。王妃背后算计，在深渊派人袭击，加上严重的精神影响，亲卫队全军覆没，蕾妮希雅在亲卫队的舍命保护下活了下来，流落深渊。"
  },
  [80832177] = {
    id = 80832177,
    name = "蕾妮希雅苏醒了，但是因为精神重创而失去了记忆，她独自在深渊艰难求生。在被魔物追杀过程中，逃到了一个村庄，被一个妇人所救。"
  },
  [80832178] = {
    id = 80832178,
    name = "玛莎把蕾妮希雅带回村庄，村里有妇女和小孩，对她都很好，他们给她衣服食物，她把这里当成第二个家，经过一段时间生活，蕾妮希雅发现夜晚有人在哭，但周围人都告诉她听错了。"
  },
  [80832179] = {
    id = 80832179,
    name = "蕾妮希雅照常和村民们一起生活，期间村长带着青壮村民回来了一趟，对蕾妮希雅这个寄居者态度很好，但蕾妮希雅却直觉敏锐不愿与他们交谈，一天夜里蕾妮希雅偷听到村民对话，发现了四方村的惊天秘密......"
  },
  [80832180] = {
    id = 80832180,
    name = "蕾妮希雅想拉拢被卖的女孩，却被反手举报，她在挨打时她负伤逃走，向所有人求救，却没有人救她，她拼死反抗，死之前她恢复了记忆，头饰白蔷薇之梦聚集了最极致的爱和恨，以及最深的执念，化为了守护者......"
  },
  [80832181] = {
    id = 80832181,
    name = "神秘人知道守护者所求是复活公主，跟她做交易，让她去找材料，告诉她在深渊中如何变强，成长为神秘人需要的实力之后，再将复活公主的事告诉守护者。"
  },
  [80832182] = {
    id = 80832182,
    name = "在不断吞噬浊炁和魔物过程中，守护者逐渐对自己的力量认知并熟练掌握，她用魔法维持冰棺，去冰原寻找保持尸身不腐的花，在路上遇到了一队探险者，与探险者交手后，源源不断的探险者来挑战她，而后她被赋予了一个称号，魔王。"
  },
  [80832183] = {
    id = 80832183,
    name = "守护者找材料的时候踏入银翼领地，和银翼发生了冲突。银翼被守护者暴打一顿，记仇离开。银翼多次回来找守护者报仇，但都被暴打一顿，银翼实在打不过守护者，决定追随她，守护者需要找材料的帮手，收复了银翼。"
  },
  [80832184] = {
    id = 80832184,
    name = "守护者找到一个材料后，与神秘人相见，神秘人说白蔷薇之梦进化成了终焉种子，并提及了星核，让守护者好好尽责，将第二层的钥匙交给了她，告诉她只有纯洁的灵魂才能复活蕾妮希雅。"
  },
  [80832185] = {
    id = 80832185,
    name = "守护者为寻找神秘人需要的材料，分裂出了拉斯特，与乌斯、默尔曼相识，三人一起同行。"
  },
  [80832186] = {
    id = 80832186,
    name = "拉斯特发现两人实力不容小觑，将乌斯、默尔曼带到了守护者面前，三人被守护者击败，作为唯一能达到这里的人，守护者打算让他们为自己长期办事。因为人类寿命对与守护来说极短，同时为了让他们听话不背叛，赐予了终焉之力，可以将他们的寿命延长数倍，但代价是无法违背守护者。"
  },
  [80832187] = {
    id = 80832187,
    name = "拉斯特和乌斯、默尔曼离开魔王城后，讨论起了分歧。乌斯在拉斯特走后，告诉默尔曼，他见到守护者的时候知道了拉斯特的身份，为了留后手，和默尔曼达成一致，让默尔曼以隐退的理由淡出拉斯特的视野。"
  },
  [80832188] = {
    id = 80832188,
    name = "公会将总部移到玛蒙之地，建立了灯塔。同时，高塔诞生，加入了许多与公会理念完全不同的人，而默尔曼退隐，成立了孤儿院。几百年后......默尔曼带着一名叫安妮斯的小女孩，回到了孤儿院。"
  },
  [80832189] = {
    id = 80832189,
    name = "两人进入研究所后，里面也有被烧的迹象，走廊上有很多魔物雕像，两人看见研究所走廊有很多房间，房间门口有标识，决定一个个房间去探索，但这些房门都锁住了，只有接待室掩着缝隙，两人正要进入，听到里面有声音。"
  },
  [80832190] = {
    id = 80832190,
    name = "蒙娜和伊莎贝尔进入接待室，发现里面是一个奇怪的机关在运转，蒙娜见多识广，认为是一种控制器，手贱想去碰一下，被伊莎贝尔的直觉阻止，两人拿到钥匙后去其他房间"
  },
  [80832191] = {
    id = 80832191,
    name = "两人开门打开楼上的工坊，工坊里有很多武器和盔甲模具,和珍贵的手稿，但因为大火烧过，模具和手稿都残缺不全了，两人发现当年的大火不是意外，这个研究所也不是伊莎贝尔要找的。"
  },
  [80832192] = {
    id = 80832192,
    name = "两人用钥匙进入了第三个房间炼药室，中间有个巨大的锅炉，四周浸泡了魔物标本，锅炉上也有一个装置在运转，伊莎贝尔发现异味让蒙娜屏气，蒙娜找到根源及时阻止了毒气释放，但却激活了装置，标本和走廊上的魔物都复活了，两人陷入困境"
  },
  [80832193] = {
    id = 80832193,
    name = "蒙娜被毒雾影响有了些醉酒效果，伊莎贝尔带蒙娜逃出炼药室，在走廊上与魔物战斗，并打开了档案室的门，两人躲了进去，竟放了一个魔物进来，击杀后，却发现破坏的墙壁里，出现了更多的资料。"
  },
  [80832194] = {
    id = 80832194,
    name = "伊莎贝尔在档案室翻找到未烧毁的资料，七七八八拼凑出当年大火的原因，是因为某研究员发现问题决定停止研究，但被人否决，研究员为了避免危害世界，将自己的心血一把烧火干净，伊莎贝尔脑中出现一些画面但不全，蒙娜的“醉酒”呐喊把她唤醒。"
  },
  [80832195] = {
    id = 80832195,
    name = "魔物在走廊徘徊，被蒙娜大喊吸引撞门，蒙娜要出去大干一场，被伊莎贝尔拉住，见魔物要将门撞破，伊莎贝尔带蒙娜藏起来，在魔物破门时偷袭杀掉，冲向接待室，两人与魔物激战（蒙娜护短爆杀），伊莎贝尔在危机时破坏了装置，魔物再次石化成雕像，碎成了石块"
  },
  [80832196] = {
    id = 80832196,
    name = "伊莎贝尔把蒙娜带出研究所大门，在院子里喊醒蒙娜，蒙娜苏醒后断片了，醒后看到暗域解除发懵，听伊莎贝尔的讲述后很惭愧，但伊莎贝尔很高兴蒙娜能陪她来这一趟，之后也会继续调查父亲研究所的事。"
  },
  [80832197] = {
    id = 80832197,
    name = "渡鸦和夜莺抵达星坠湾，这里是个环形沙滩，发现沙滩布满彩色碎裂的水晶，渡鸦捡水晶听见了水晶里的人声，发现里面有某种力量的残留，想看得更清的时候就消失了"
  },
  [80832198] = {
    id = 80832198,
    name = "两人深入星坠湾探索，发现这里有曾经人类生存的痕迹，她们找了一圈没有发现什么，到夜晚时，渡鸦睡着了，夜莺被光亮晃醒，原来是那个罗盘发出的，夜莺想叫醒渡鸦，和渡鸦一起坠入了梦境"
  },
  [80832199] = {
    id = 80832199,
    name = "渡鸦进入了梦境，夜莺找到渡鸦时，她迷路了，两人发现无法离开梦境，只能一起找路，在道路尽头看到了一个祥和美好的村庄。"
  },
  [80832200] = {
    id = 80832200,
    name = "渡鸦和夜莺前往村庄，遇到一个小女孩兰妮自称为村长，她的村民都是会说话的蘑菇，走来走去的面包，能生产糖果的云朵......它们欢迎这两个外来人来参加村长的就任仪式，这时萤火虫过来说烟花掉进河里了。"
  },
  [80832201] = {
    id = 80832201,
    name = "看见兰妮和村民们这么失落，夜莺和渡鸦一起帮忙做烟花，和并在找材料的过程中，发现了一个小屋，是个童话屋，两人猜想是梦境的来源。"
  },
  [80832202] = {
    id = 80832202,
    name = "两人找齐了烟花材料，在制作的过程中和「村民」交流，发现村民们都是女孩的家人，他们早就因为天灾离开了这个地方，但撤离的时候小女孩因为躲猫猫没跑掉，他们就用水晶制造了一个梦境，为她的灵魂圆梦"
  },
  [80832203] = {
    id = 80832203,
    name = "兰妮就任仪式开始，烟花绽放，兰妮达成了心愿，灵魂带着她的童话世界消散，渡鸦和夜莺回到了现实世界"
  },
  [80832204] = {
    id = 80832204,
    name = "渡鸦和夜莺在残破的小屋里，发现了兰妮的东西，渡鸦把那个罗盘也一起埋葬，听到夜莺招呼她，两人回到沙滩上，那些陪伴兰妮灵魂的水晶也升空消散在天地，仿佛在给她们说谢谢。"
  },
  [80832205] = {
    id = 80832205,
    name = "流火村的村民们为你们安排了住所，艾拉很快就和村民们熟络起来，她教孩子们基础剑术，你帮村民补墙，两人在村子生活了一天，这时有人回来了。"
  },
  [80832206] = {
    id = 80832206,
    name = "当晚，出去猎魔物的青壮年回村，你没见到彼得。第二天，你告诉了他们附近魔物盘踞的事，虽然村民们不以为意，但也想通过训练变强。艾拉想起你是老师，怂恿你去授课，在你授课的时候，她听得很认真。"
  },
  [80832207] = {
    id = 80832207,
    name = "晚上村民们围坐在篝火旁，一起喝酒跳舞，艾拉听村民讲述村庄的故事，也给他们讲外面世界的冒险，你被艾拉灌了很多酒，带着醉意看她笑......"
  },
  [80832208] = {
    id = 80832208,
    name = "过了几天，彼得终于回来了，你把信交给了他。艾拉还想继续在村里住，你与村民们、艾拉道别，在离开村子后，你在附近发现了许多魔物的脚印，意识到危险即将降临，立刻返回村庄。"
  },
  [80832209] = {
    id = 80832209,
    name = "你将发现魔物群行踪的事告诉村长，艾拉认为这件事不能轻视，决定跟你一起去巡查。但你们巡查了一阵没有发现什么，又重新回到了村庄，村民们依然不以为意。"
  },
  [80832210] = {
    id = 80832210,
    name = "你勘察防御工事，彼得找到了你，他说在回来的路上杀了记仇的魔物，可能引来魔物群的报复，忧心忡忡，但好在他们很早就挖了一条隐秘的地道，原来是存粮用的，后来就挖到了据点附近。你听后才知道为什么村民不怕魔物袭击，这时艾拉急冲冲跑来，魔物群突袭村庄了。"
  },
  [80832211] = {
    id = 80832211,
    name = "面对魔物群的突袭，村民团结奋战，但一场大战后仍是不敌，你让艾拉即刻带村民们从地道离开，并在最后离开时炸死了魔物群。"
  },
  [80832212] = {
    id = 80832212,
    name = "地道被彻底炸毁，到安全地点后，艾拉心情很不好，她认为自己太倒霉了。你的安慰加上她的自我开导，艾拉变回开朗，村民们感谢你和艾拉的帮忙和救助，艾拉决定留下重建村庄，和你道别。"
  },
  [80832213] = {
    id = 80832213,
    name = "星轨和风痕在热闹的集市上看到了面包店，进去之后，遇见隔壁桌的蒙娜、黑羽、罗亚和伊莎贝尔，蒙娜正怂恿她们组成一队参加丰收祭的竞赛......"
  },
  [80832214] = {
    id = 80832214,
    name = "星轨和蒙娜相遇恨晚，她们在报名的路上遇到了去年参加活动的探险队，几个人都嘲笑蒙娜上次的战绩，蒙娜和星轨一起接下对方的挑战书，这时，主办方宣布发生了紧急事件。"
  },
  [80832215] = {
    id = 80832215,
    name = "大批魔物突然前来捣毁庄稼！于是，丰收祭的比赛临时提前了，第一项的比赛竟然是实战考核？那个奖品，为什么看起来那么眼熟......"
  },
  [80832216] = {
    id = 80832216,
    name = "星轨队抽签到了去西南区消灭魔物，众人到达西南区后，星轨和风痕都发现了蓝色的花。她们将附近村庄的事告诉三人，几人合计依照星轨和风痕的办法，成功除掉了魔物，回来的时候，再次遇到了挑衅的探险队，在主办方宣布进入第二轮的队伍后，星轨队决定去吃一顿小庆祝一下。"
  },
  [80832217] = {
    id = 80832217,
    name = "第二天，主办方让晋级者去守护附近的一片果林，最新探测到有接近于领主级实力的魔物在靠近，主办方宣布谁击杀魔物就能得到奖励，星轨等人在商讨后，决定先去往果林附近。"
  },
  [80832218] = {
    id = 80832218,
    name = "金穗凯旋队率先来到了果林，在星轨和蒙娜的鬼点子下，她们积极布置陷阱，没领主级魔物的到来，却等到了一大群低级魔物，众人在消灭低级魔物后，看到先前挑衅他们的探险队逃难似的来了，他们见到星轨队以为见到了救星，却纷纷栽进了陷阱中"
  },
  [80832219] = {
    id = 80832219,
    name = "顾不得捞探险者们，巨型魔物出现了，众人配合混乱中又带点默契，有惊无险地杀掉了接近于领主级实力的魔物，救起探险队后，他们与星轨队争吵理论时，魔物突然诈尸，星轨风痕及时救下了他们，彻底杀死了魔物"
  },
  [80832220] = {
    id = 80832220,
    name = "在主办方严格的判断下，奖品颁发给了此次出力最大的星轨队，这时掉入陷阱的探险队来申讨要求赔偿，在风痕的建议下，众人同意用魔法石治疗受伤的探险者。"
  },
  [80832221] = {
    id = 80832221,
    name = "永夜穿过通道之后是无尽的风沙，她一路穿行，路上魔物众多，在穿越风沙峡谷后，看到了沙海尽头的森林。"
  },
  [80832222] = {
    id = 80832222,
    name = "永夜在森林里走累了，她发现一个湖泊去泡澡，在泡澡的时候，遇到了同样泡澡的枭，她向枭打听遗迹的消息，枭告诉她那个地方是一片废墟，三年前就被兽潮袭击没有了，永夜不信，决定再次出发"
  },
  [80832223] = {
    id = 80832223,
    name = "永夜到达了露可说的溪谷镇，这里是个繁华的小镇，她确信枭在撒谎，进入小镇，这里的每个人都过得很开心，但却对她说的遗迹和哈伦毫不知情，她先找了个地方住下，无意中看到小镇的钟，发现并没有转动过"
  },
  [80832224] = {
    id = 80832224,
    name = "永夜第二日出门，继续找人打听，令她奇怪的是，所有的一切都昨天一模一样，这让她毛骨悚然，她想离开这个小镇却发现出不去了......"
  },
  [80832225] = {
    id = 80832225,
    name = "永夜在深夜踏入钟楼，看见了一层的钟表，钟摆在摆动但钟表不转，在一层她竟然发现了关于时之砂的相关笔记......"
  },
  [80832226] = {
    id = 80832226,
    name = "第三日，永夜去寻找钟表匠，终于见到了哈伦，要将信交给了他，哈伦拿到信却流泪了......"
  },
  [80832227] = {
    id = 80832227,
    name = "到了晚上，永夜进入钟楼用钥匙打开了二楼，看到的是老哈伦坐在工作台前死去了，桌上散落着无数的信件，永夜接着打开第二扇房间，看到了那座凝固时间的钟"
  },
  [80832228] = {
    id = 80832228,
    name = "永夜终于明白了真相，那封委托信是一封跨越了时间的家书，她将露可那封家书放在哈伦的面前，哈伦想留住小镇最后的时间等露可回家，但露可却不知家乡早已不在了......"
  },
  [80832229] = {
    id = 80832229,
    name = "在和霏去晨露谷前，霏让你陪她等着她的好友湄，而湄在看到你的第一眼，并非那么地友好......"
  },
  [80832230] = {
    id = 80832230,
    name = "村庄正在筹备万圣节，可庆典筹备的材料不足，轮到你们大显身手的时候了......"
  },
  [80832231] = {
    id = 80832231,
    name = "将材料带回村庄后，你们帮忙制作美食，精灵古怪的霏想做出一些特色，而湄却不擅长厨艺，对付美食如临大敌，在大家完成美食的时候，你发现了偷吃的咕咕，咕咕看到你全身炸毛，调头就跑了"
  },
  [80832232] = {
    id = 80832232,
    name = "接下来，三人和村民们一起制作面具与服装，你做了一个南瓜帽子，咕咕很喜欢，跳出来抢你的东西，在你说明咕咕无害后，两人从惊讶到喜欢咕咕，一起等待庆典的正式开启"
  },
  [80832233] = {
    id = 80832233,
    name = "万圣节当日，你去找霏，见到霏在给湄化妆，霏自己化成了一只妖精，给湄画完之后，霏强迫给你化妆，画完了之后，几人一起出门。"
  },
  [80832234] = {
    id = 80832234,
    name = "村里美食飘香，各种造型奇特的面具和装饰品被挂起来，咕咕戴着它的小头饰，在村里兴奋地跑来跑去，三人和村民们一起布置广场、检查篝火，等待庆典开始。"
  },
  [80832235] = {
    id = 80832235,
    name = "庆典伊始，村民们集体穿假面游行，由人类扮演的魔物们纷纷上街，众人庆祝庆典，咕咕也顶着小头巾，在人群脚边欢快地蹦跶，在欢笑中亲友分享了霏父母的礼物，是一束束绽放的魔法烟花。"
  },
  [80832236] = {
    id = 80832236,
    name = "游行结束，所有人聚集在篝火旁，村民们分享着辛苦制作的美食，大家围坐在篝火旁，享受着美食、欢笑和温暖的友谊，咕咕也心满意足地饱餐一顿"
  },
  [80832237] = {
    id = 80832237,
    name = "通往暗域核心区域的路上，魔物和迷失者越来越多，安妮斯暂时为居民撑起了一片安全区，追上了燧影和蒂娜，看她们解救了许多迷失者居民，让居民去往安全区，而三人则继续深入核心区域。"
  },
  [80832238] = {
    id = 80832238,
    name = "三人一路斩杀源源不断的魔物，迷失者也越来越少，燧影杀了一个完全失去理智的迷失者，找到了地下仓库，一个被改造的临时实验室。"
  },
  [80832239] = {
    id = 80832239,
    name = "三人进入仓库，在里面发现了许多线索，燧影见到了骸骨的身份，断定她调查的人还没死，安妮斯和蒂娜在燧影提供的情报下推测，三人一起还原了真相。"
  },
  [80832240] = {
    id = 80832240,
    name = "通过源晶粉末，三人离开地下仓库追寻残留的痕迹，一路清除魔物障碍，找到了真正的暗域源头，看到了远处还在进行仪式的堕落者，战斗一触即发。"
  },
  [80832241] = {
    id = 80832241,
    name = "面对堕落者，燧影迎面而上，但该堕落者异化严重，且尚存部分理智，见不敌三人，引爆了机关，放出更多的魔物，自己逃跑了。"
  },
  [80832242] = {
    id = 80832242,
    name = "三人大战从石门中涌出的魔物，在安妮斯的细致观察下，找到了机关，三人关闭魔物涌出的石门，消灭了剩余的魔物，但山洞也开始坍塌崩坏。"
  },
  [80832243] = {
    id = 80832243,
    name = "三人逃出崩坏区域，发现整个暗域都在崩坏，必须及时杀了堕落者才能消除暗域，在三人合力下，终于将堕落者斩杀。"
  },
  [80832244] = {
    id = 80832244,
    name = "源头的堕落者死亡，暗域消散了，迷失者清醒后，纷纷来感谢三人，燧影只是像简单完成了一件任务，继续走向了下一个任务。"
  },
  [80832245] = {
    id = 80832245,
    name = "安瑞丝与诺玛将远超预期的优质材料交给镇长，镇长惊喜万分，却又对另一件事发愁，客人来了不少，小镇人手不足了。"
  },
  [80832246] = {
    id = 80832246,
    name = "在工坊里，安瑞丝和诺玛分工合作，虽然闹出了不少笑话，好在有惊无险，完成了圣诞礼物的制作和包装，安瑞丝拿出名单，决定和诺玛分头将礼物送到小镇的每个客人手中。"
  },
  [80832247] = {
    id = 80832247,
    name = "平安夜，两人开始行动。安瑞丝找到第一个客人，在艰难打开机关进入后，艾瑟儿装作不知道让她成功潜入后离开了。安瑞丝再接再厉进入第二个客人抚慰师的房间，成功放好礼物悄悄溜走，而后发现诺玛一个都没送出去，决定和诺玛一起去送礼。"
  },
  [80832248] = {
    id = 80832248,
    name = "安瑞丝带着诺玛到了第三个房间，有了诺玛的协助，安瑞丝轻松潜入，却被当作小偷袭击，在安瑞丝解释之后，发现袭击她的是两个妹妹，灵遥和米亚姆，她们来找哥哥一起过圣诞，在听到安瑞丝要发放礼物后，灵遥积极地给两人出主意，讨论哥哥喜欢的礼物，要让哥哥过一个惊喜的圣诞。"
  },
  [80832249] = {
    id = 80832249,
    name = "安瑞丝和诺玛来到了你的院落，在偷偷进入房间时，被菲尼斯发现了。在重逢之后，她将额外的礼物拿了出来，让你一起参加圣诞活动。"
  },
  [80832250] = {
    id = 80832250,
    name = "安瑞丝和诺玛将剩余的礼物送给蒂娜、安妮斯，列蒂西雅、莉娃之后，和诺玛高兴地谈心交流，感叹度过了一个平安的平安夜，诺玛看到手中还剩有礼物，离开小镇了一趟，悄悄将小礼物留给了熟睡的拾荒者孩童。"
  },
  [80832251] = {
    id = 80832251,
    name = "圣诞日，庆典热闹非凡。安瑞丝和诺玛混在人群中，享受着节日气氛，同时也观察着居民们的反应，在看到你与同伴们都在享受节日的快乐，她忽然有些不好意思......"
  },
  [80832252] = {
    id = 80832252,
    name = "夜幕降临，雪花飘落。祈愿活动正式开始，安瑞丝和诺玛各自许愿，也听到了周围人群的愿望，在美好的烟花中，圣诞活动结束了。"
  },
  [80832253] = {
    id = 80832253,
    name = "你与玛德莲进入了黑曜石城堡，遇到的其他与会学者，几乎都是像玛德莲一样富有才华但缺乏靠山的独立研究者，气氛看起来很热烈，接着，欢迎晚宴开始了。"
  },
  [80832254] = {
    id = 80832254,
    name = "晚宴气氛融洽，但主持的演讲充满了对深渊力量的鼓吹，在有学者反对后被请离了会场......"
  },
  [80832255] = {
    id = 80832255,
    name = "晚宴结束后，所有学者被要求不得随意出入，你发现房间有人看守，正想利用地形出去侦查，同样被软禁的玛德莲竟从通风口跳到了你的房间......"
  },
  [80832256] = {
    id = 80832256,
    name = "第二天研讨会再次开始，子爵出现摊牌。他宣布所谓的伟大事业，并要求在场学者签署保密协议并加入研究，多数学者严词拒绝，被强行镇压，场面十分混乱，你与玛德莲且战且退，逃出被封锁的大厅，子爵大怒，下令全力追捕。"
  },
  [80832257] = {
    id = 80832257,
    name = "两人逃入中庭和守卫周旋，逃离空间不断被压缩，发现地下通道，强行破坏地下窗口，在追兵进入前进入了通道，发现这里竟是一个地下迷宫。"
  },
  [80832258] = {
    id = 80832258,
    name = "两人进入地下通道，发现了许多以前失踪的学者，还有很多被抓的实验素材，玛德莲甚至发现了资金来往的信件，爵士做这一切也有人提点，这时警报拉响，追兵将至，在逃亡的过程中，玛德莲发现地下通道的几个魔法反应炉，她决定救出那些学者，炸毁这些炉子。"
  },
  [80832259] = {
    id = 80832259,
    name = "你与玛德莲分开行动，你引开追兵，玛德莲将人都救到通风口，帮他们解除身上的桎梏后，帮你在追兵中杀出重围，许多学者一起反抗冲出通风口，你和玛德莲引爆了地下实验室。"
  },
  [80832260] = {
    id = 80832260,
    name = "两人从另一处地下出口逃出，看到学者们在暴打爵士，你们成功带出了罪证，并摧毁了魔窟，学者们对两人感激涕零，玛德莲决定带着罪证回组织，你与玛德莲道别。"
  },
  [80832261] = {
    id = 80832261,
    name = "雪莉将濒死的女婴带回去，毅然收养这个四肢俱损，来历不明的孩子，手下议论她每天完成任务就立刻回家，为避免疑心和行为异常，决定接下一个长期的外出任务。"
  },
  [80832262] = {
    id = 80832262,
    name = "雪莉将婴儿带离高塔，为孩子取名谢利，动用所有人脉与积蓄，历经艰辛，为谢利寻找到了仿生肢，谢利逐渐对雪莉的行为有了反馈，让雪莉十分开心。"
  },
  [80832263] = {
    id = 80832263,
    name = "时间一年年过去，雪莉为谢利接上新的四肢，耐心教导她如何控制、行走、运用。雪莉教导谢利知识、魔法与武技，她发现谢利武技的天赋，和对生命的漠视，开始教导她为人的底线与善良，谢利逐渐依赖并深爱这位对她全心付出的养母。"
  },
  [80832264] = {
    id = 80832264,
    name = "雪莉带她回到高塔，宣布了谢利的身份，雪莉为防范缇法尼，出任务时时刻带上谢利。在谢利七岁时，一次任务中，遭遇强大魔物，雪莉为保护谢利与属下，身受极重的创伤，虽侥幸生还，但再也无法执行任务。"
  },
  [80832265] = {
    id = 80832265,
    name = "高塔的供给仅能维持基本生存，雪莉的重伤让家庭陷入困境。谢利无法负担昂贵的药物，目睹养母被病痛折磨，非常痛苦，梅娅和米沙（雪莉旧部）来看望母女，在梅娅走后，米沙给谢利出主意，让她也加入任务，但谢利仍在犹豫。（离开后无人照顾雪莉）"
  },
  [80832266] = {
    id = 80832266,
    name = "看着日益虚弱的雪莉，谢利决定继承母亲的职责，她找到米沙，要求执行一些力所能及的任务，赚取功勋点以换取药物和食物。梅娅开始不赞同，被谢利打动后，答应谢利会照看雪莉，梅娅叫来了尤娜，照顾雪莉。"
  },
  [80832267] = {
    id = 80832267,
    name = "米沙起初因谢利是雪莉养女且年纪小而稍有照顾，但谢利的杀戮天赋，和狂妄果决逐渐显现，任务完成出色，有时甚至抢了米沙的风头，引来米沙的嫉妒与不满。谢利咬牙坚持，每次完成任务后，功勋点最先兑换的都是雪莉的药物，尤娜时常担心谢利，尽力协助。"
  },
  [80832268] = {
    id = 80832268,
    name = "谢利在外拼搏，回家则隐藏疲惫，细心照料雪莉，讲述任务中有趣的经历，报喜不报忧。雪莉心疼不已，却无力改变，只能将担忧深藏心底，给予谢利更多的鼓励与爱。这份相依为命的亲情，是黑暗世界中最珍贵的支撑。"
  },
  [80832269] = {
    id = 80832269,
    name = "面对谢利的迅速成长，米沙因嫉妒和贪婪，设计陷害谢利，一次危险任务中，将其引入强大魔物的巢穴深处，意图借魔物之手除掉谢利。"
  },
  [80832270] = {
    id = 80832270,
    name = "面对绝境与魔物的虐杀，谢利濒死之际，体内浊炁力量彻底爆发，救了她一命。首次爆发带来的不仅是力量，还有嗜血心性和狂暴的杀意。她反杀了魔物，也初次体验了失控的感觉。"
  },
  [80832271] = {
    id = 80832271,
    name = "谢利意识到自身力量的异常与危险，她隐瞒了真相，开始暗中研究并尝试控制浊炁，发现深渊浊炁不仅不伤害她，反而成为力量源泉。她走上了自创修行体系的道路，力量快速增长，性格也更趋狂妄果决，但在雪莉面前依旧保持乖顺。"
  },
  [80832272] = {
    id = 80832272,
    name = "为了获取更好的药物治疗雪莉，也为了清算背叛，谢利暗中调查并确认了米沙的陷害行为。她秘密处决了米沙。凭借逐渐展现的力量与雪莉昔日积累的威望，收服并整合了雪莉的旧部，继承了雪莉的位置，成为高塔中令人瞩目的新锐力量。"
  },
  [80832273] = {
    id = 80832273,
    name = "谢利在人前是高塔无间狱新任的组长，狂妄锋利，任务完成率极高，令人畏惧。人后是雪莉的孝顺女儿，照顾母亲起居，分享日常趣事，努力维持着家的温暖，梅娅和尤娜成为她最得力的副手与朋友。"
  },
  [80832274] = {
    id = 80832274,
    name = "谢利的力量与飞速成长引起了缇法尼的注意。缇法尼听闻了这位新锐的事迹，对其能掌控浊炁的能力产生极大兴趣，决定见一见谢利。雪莉听到信息后，想劝谢利不要去，但谢利却想到能有更多渠道为养母治病，不能错过接近缇法尼的机会。"
  },
  [80832275] = {
    id = 80832275,
    name = "缇法尼与谢利会面，非常看重谢利的能力价值。她以提供最好的医疗资源彻底治愈雪莉、并保证其后半生无忧为条件，要求谢利带着小组为她做事。为了雪莉的生命与安宁，谢利明知前路危险，也答应了缇法尼的条件，帮她登上高位。"
  },
  [80832276] = {
    id = 80832276,
    name = "缇法尼在谢利的相助下，成为了无间狱的首领。谢利也成为了缇法尼手中最锋利的刀。一天，缇法尼给谢利布置了任务：抢夺繁星之环。在繁星之环失踪后，谢利窥见了主角团一行人，命运的齿轮由此开始启动。"
  },
  [80832277] = {
    id = 80832277,
    name = "两人掉入了迷宫里，学者不知所踪，你们开始探索出路，在迷宫中发现了小魔物，朝雾追着小魔物跑了很久，到达了一个房间。"
  },
  [80832278] = {
    id = 80832278,
    name = "小魔物消失了，你们到了一个装满书籍的房间，房间里的资料，两人发现这里曾经是个古城，曾培育和创造魔物，最终实验失控，创造的魔物反噬了造物主，导致文明毁灭。"
  },
  [80832279] = {
    id = 80832279,
    name = "抵达古城的培育池，发现古城最终极的创造物，是一颗心脏，这颗心脏到现在还在跳动，这时学者出现，感叹创造出这颗心脏的伟大，要想将这个东西带走，两人阻止制服学者。"
  },
  [80832280] = {
    id = 80832280,
    name = "你与朝雾商量决定由一人暂时守着心脏，另一人回去报告情况再行定夺，但朝雾不想留下，与你争论时学者悄悄苏醒，用备用的控制器释放了心脏。他宣称要继承古城的遗产，掌控它，并试图建立自己与心脏的连接，但仪式发生意外失败，学者被抽干死亡，但整个心脏跳动响彻迷宫，变得极其不稳定，两人决定先撤退。"
  },
  [80832281] = {
    id = 80832281,
    name = "心脏激活了古城遗留的防御机制，并刺激了迷宫内所有的魔物。通道移位，新的陷阱生成，魔物们变得空前狂暴，你们开始一路杀魔物逃亡。"
  },
  [80832282] = {
    id = 80832282,
    name = "在寻找出路的过程中，你们发现了古城一个密室，得知完整的真相：心脏是古城全城人献祭培养出来的胚胎，有无限进化的能力，也是因为心脏导致了古城文明的毁灭，面对即将爆发的灾难，朝雾决定去摧毁它，二人一致决定，必须阻止灾难。"
  },
  [80832283] = {
    id = 80832283,
    name = "两人根据密室的出路找到了真正的心脏所在，两人趁心脏还没发力时毁掉了，这时小魔物出现，心脏残余的力量到它身上，变成了强悍的魔物，朝雾心情复杂，和你一起斩杀了魔物，摧毁了心脏。"
  },
  [80832284] = {
    id = 80832284,
    name = "出了迷宫之后，朝雾整理好了调查报告，邀请你一起去拿奖励，你将奖励都送给朝雾，希望她能早日获得自己的宠物，朝雾和你道谢离开。"
  },
  [80832285] = {
    id = 80832285,
    name = "你抵达隐藏的雪村，受到了認的特殊“欢迎”让你止步，鎺出现解释后，認认为要通过考验你才能进村。"
  },
  [80832286] = {
    id = 80832286,
    name = "成功破阵后，鎺和認带你游览雪村。雪村村民对你的到来表示欢迎。"
  },
  [80832287] = {
    id = 80832287,
    name = "你感受着雪村平静的日常生活，也见到了雪村特有的试炼之境。为了更好地守护雪村，她们从不松懈训练。"
  },
  [80832288] = {
    id = 80832288,
    name = "三人在最美的樱花树下野餐。認讲述她们五人在外组建“雪折邸”的趣事，谈及未来要做出一番事业再继承家族，認和鎺都很期待第二天的赏花会。"
  },
  [80832289] = {
    id = 80832289,
    name = "第二天赏花节开始，村民们穿着华丽的服装开展活动，其中有收集魔物材料，鎺和認商议后决定接取最高难度的那一个，在你帮忙下除掉雪村的隐患，还成功带回了材料，得到了村民的夸奖和丰厚的奖励。"
  },
  [80832290] = {
    id = 80832290,
    name = "鎺教你制作雪村的樱花笺，認教你做仪式的河灯，每个人都在笺上写下了愿望。"
  },
  [80832291] = {
    id = 80832291,
    name = "你们拿着河灯去参加篝火晚会，晚会上，村民们放走编织的河灯，鎺哼唱起雪村的歌谣，認喝多了吐露心声，说起自己看似无忧无虑，实则最害怕让族人失望，也说起了鎺的责任，她们都在为雪村和雪折邸努力。"
  },
  [80832292] = {
    id = 80832292,
    name = "赏花节尾声，众人在最古老的樱花树下祈祷与约定，鎺和認送信物给你，并与你告别。"
  },
  [80832293] = {
    id = 80832293,
    name = "两人进入茧洞后，发现是一个结构复杂的立体迷宫，很快发现了第一个生命之茧，正是公会成员寻找的朋友，他说是跟随发光丝线走进来的，之后就失去了知觉，你让他回去，和司礼者继续深入。"
  },
  [80832294] = {
    id = 80832294,
    name = "根据失踪者的线索，他们在另一个洞穴找到了抚慰师。她的茧更厚，两人在救人的时候，被魔物阻拦，最后成功将人救出。"
  },
  [80832295] = {
    id = 80832295,
    name = "抚慰师苏醒后，告诉了两人更多的线索，原来森林中心有一个魔物，它以织梦的方式，将靠近的外来者，以及所有闯入者纳入梦境作为养分。"
  },
  [80832296] = {
    id = 80832296,
    name = "圣光使被困在更深处的地方，几人穿过丝网回廊，开始昏昏欲睡，为了不让大家睡觉，司礼者想了个办法赶走睡意。"
  },
  [80832297] = {
    id = 80832297,
    name = "几人想救圣光使下来，但圣光使为了对抗魔物，已经将自身和魔物的生命捆绑，决定牺牲自己炸掉这个洞穴。在三人的劝说下，圣光使放弃同归于尽，三人合力将圣光使救了出来。"
  },
  [80832298] = {
    id = 80832298,
    name = "由于圣光使的逃离，魔物提前苏醒了，巢穴活了过来，更多的变异人和魔物从茧子里掉了出来攻击四人，四人一边战斗，一边寻找逃出去的办法，最终四人被逼往一处地方。"
  },
  [80832299] = {
    id = 80832299,
    name = "四人到达了魔物巢穴的中心，是一个将整座森林都作为领域，吸收养分的巨型魔物。四人合作战斗，击溃了魔物。那些还没孵化成型的茧掉落，失踪者沉睡苏醒。"
  },
  [80832300] = {
    id = 80832300,
    name = "离开魔物巢穴，森林和之前有了变化。司礼者、圣光使和抚慰师感激你，她们送那些失踪者离开，并与你道别。"
  },
  [80832301] = {
    id = 80832301,
    name = "衍道宗宗主之女云罗正在演武场上展示法术修行成果，被众多弟子赞誉为天骄。就在她享受众人赞誉时，一位少年却提出了自己的看法。"
  },
  [80832302] = {
    id = 80832302,
    name = "云罗对少年的说法感到不满，决定和少年切磋证明自己，狠狠教训少年。"
  },
  [80832303] = {
    id = 80832303,
    name = "云罗输了，而且对方使用的法术还并不算强大。在少年的解释下，云罗清楚了自己的败因。"
  },
  [80832304] = {
    id = 80832304,
    name = "云罗接受了自己的失败，在少年的提示下，她对自己修行的法术有了新的认知。云罗决定要更加努力修行，然后堂堂正正的击败少年。"
  },
  [80832305] = {
    id = 80832305,
    name = "少年奉师命前来向云罗请罪，云罗表示自己根本没有怪罪的意思。最终，为了让少年能回去复命，云罗便让少年继续陪自己切磋。"
  },
  [80832306] = {
    id = 80832306,
    name = "又一次切磋之后，云罗感觉自己实力有了明显提升，于是和少年约定在不久后的年轻弟子定级赛上，要堂堂正正的切磋一番。"
  },
  [80832307] = {
    id = 80832307,
    name = "年轻弟子定级赛正式开始，但云罗却没能见到那个少年。即便击败了诸多同门弟子，云罗仍觉得有些失落。"
  },
  [80832308] = {
    id = 80832308,
    name = "定级赛结束，云罗毫无悬念的获得了第一。云罗找到逍遥坊弟子，询问那个少年为什么没能参赛，这才得知少年被关了禁闭。"
  },
  [80832309] = {
    id = 80832309,
    name = "云罗私自溜到宗门下的云城玩耍，意外听到了有人谈论衍道宗的年轻弟子定级赛。这些人觉得云罗轻易获胜的背后，说不定有什么故事。"
  },
  [80832310] = {
    id = 80832310,
    name = "面对流言蜚语，云罗据理力争，但却反而被几个修士调侃。云罗对这些耍无赖的修士毫无办法，只得独自委屈。"
  },
  [80832311] = {
    id = 80832311,
    name = "路过的少年逐条反驳了修士们的流言，但几名修士仍不依不饶耍无赖。少年决定不再克制，狠狠教训了几人。"
  },
  [80832312] = {
    id = 80832312,
    name = "少年称赞了云罗在年轻弟子定级赛上的表现，肯定了云罗的努力。分别时，二人约定在三年后的宗门大比上，要再一次决胜负。"
  },
  [80832313] = {
    id = 80832313,
    name = "宗门大比正式拉开帷幕，但少年却依然没有出现。正当云罗以为他又要失约时，少年突然出现。"
  },
  [80832314] = {
    id = 80832314,
    name = "云罗和少年都展现出了极强的实力，引起许多弟子的关注。最终，二人成功会师决赛。"
  },
  [80832315] = {
    id = 80832315,
    name = "决赛上，云罗和少年都全力以赴，引得众弟子侧目，就连宗门长老也不由被他们的表现震撼。"
  },
  [80832316] = {
    id = 80832316,
    name = "根据规则，云罗获得了优胜，但她却认为是自己败了。陆玄坦然表示输了就是输了，二人相互推让。最终由衍道宗宗主和众长老裁定，由陆玄和云罗共享优胜者荣耀。"
  },
  [80832317] = {
    id = 80832317,
    name = "前往水滨据点的途中，你们遇到了前来打探消息的商人。你不动声色的拒绝了这些人，浮光对你表示钦佩，坦言自己并不擅长拒绝别人。"
  },
  [80832318] = {
    id = 80832318,
    name = "越接近水滨据点，窥探货物的人就越多。你们刚逼退想要盗取货物的小偷，又遇到准备抢夺货物的劫匪。"
  },
  [80832319] = {
    id = 80832319,
    name = "经历不少波折，你们终于将货物完好送到水滨据点。就在你们准备离开之际，商人又向浮光提出了一个令你也觉得不可思议的请求。"
  },
  [80832320] = {
    id = 80832320,
    name = "在你的鼓励下，浮光坦诚说出了自己的想法，拒绝了商人的请求。但在商人的苦苦哀求下，浮光心生恻隐，最终还是答应了下来。"
  },
  [80832321] = {
    id = 80832321,
    name = "浮光从穿着泳衣开始就遇到了一些小麻烦，穿好之后，又对即将开始的工作感到紧张。在你的鼓励下，她也拿出勇气，决定全力以赴。"
  },
  [80832322] = {
    id = 80832322,
    name = "内敛的个性，加上紧张和害羞，浮光难以做好模特大方展示服饰的工作。你们被其他商人和顾客调侃，眼见局势不利，你决定更换推销思路。但就在这时，水滨据点突然出现了意外。"
  },
  [80832323] = {
    id = 80832323,
    name = "突然出现的魔物让水滨据点陷入混乱，眼见局势即将失控，你和浮光选择挺身而出。"
  },
  [80832324] = {
    id = 80832324,
    name = "浮光飒爽的身姿深深烙印在围观者的脑海中，众人也发现了她所穿的那件泳装的特殊性能，你们滞销的泳装一下变成了热销品。浮光在经历一系列事情后，也决定遵从你的建议，稍微休整一下再出发。"
  },
  [80832325] = {
    id = 80832325,
    name = "艾格尼丝赶到了约定地点，但距离约定时间已经过了几天。得知商人已经不需要模特后，艾格尼丝很快接受了现实，决定在水滨据点休整几日。"
  },
  [80832326] = {
    id = 80832326,
    name = "艾格尼丝散步时，意外得知水滨据点中有人能同时使用武技和魔法，她决定一探真假。"
  },
  [80832327] = {
    id = 80832327,
    name = "艾格尼丝借着购买泳装的名义打量你，让你很不自在。最终在浮光的追问下，她才道明了自己的真实意图。"
  },
  [80832328] = {
    id = 80832328,
    name = "在你的指点下，艾格尼丝很快领悟了魔法和武技双修的一些关键。你们相谈甚欢，决定一起参加水滨假日庆典。"
  },
  [80832329] = {
    id = 80832329,
    name = "你们正在享受水滨风光时，大批魔物从水下出现，其中甚至有领主级魔物。通过分析，你们确认了魔物的来源。艾格尼丝提出一个大胆的解决方法，希望你和浮光能帮助她。"
  },
  [80832330] = {
    id = 80832330,
    name = "大战开启，你负责统筹、调度，召集探险者们组建防线抵御魔物。浮光深入敌阵，直面领主级魔物。"
  },
  [80832331] = {
    id = 80832331,
    name = "艾格尼丝潜入水下，修复残破的结界。当一切准备完成，只差最后一步时，艾格尼丝的魔力开始短缺。"
  },
  [80832332] = {
    id = 80832332,
    name = "随着结界重新运转，魔物再度被削弱，你们成功将其击败。事后，你们三人一起参加庆典，浮光将商人的谢礼带给了艾格尼丝。艾格尼丝仔细翻阅后，发现修行笔记中的内容，和你此前的指点几乎一样。"
  },
  [80832333] = {
    id = 80832333,
    name = "抵达雪村后，認热情地接待了你，并向你介绍狩猎祭的由来与规则。面对路上遇到的异常魔物现象，她给出了合理解释，而你也正式决定参与这场雪村一年一度的重要祭典。"
  },
  [80832334] = {
    id = 80832334,
    name = "狩猎祭正式开始。你与認组成队伍踏入狩猎区域，在实战中了解积分与食材的获取规则，并开始为争夺更高排名而行动。"
  },
  [80832335] = {
    id = 80832335,
    name = "凭借默契配合，你与認接连击败大量魔物，迅速积累积分。然而随着不断深入狩猎区域，今年的魔物似乎比往年更加活跃，你心中异样的感觉再次浮现。"
  },
  [80832336] = {
    id = 80832336,
    name = "提交食材积分时，認同时上报了你们遇到的异常。但经过调查，村中确认引导装置没有问题。然而几日后，一支参赛队伍突然失踪了。"
  },
  [80832337] = {
    id = 80832337,
    name = "为了寻找失踪的探险队，你与認赶往事发现场。而在那里等待你们的，是提前一步完成调查的鎺。"
  },
  [80832338] = {
    id = 80832338,
    name = "随着调查不断深入，魔物异常活跃的原因逐渐浮出水面。面对可能存在的巨大威胁，你、認与鎺决定主动出击，在事态彻底失控前解决问题。"
  },
  [80832339] = {
    id = 80832339,
    name = "失踪的探险队终于被找到，而等待着你们的，则是引发这一切异变的强大存在。你们并肩作战，最终击败领主级魔物，救回被困探险者，并取得珍贵食材。"
  },
  [80832340] = {
    id = 80832340,
    name = "狩猎祭结束，你们的积分逆转夺得第一。因为这次危急事件，你们备受关注。闲谈间，認向你表露了自己的真实想法。"
  },
  [80832341] = {
    id = 80832341,
    name = "莎尔拉生日当天，边境领地举行盛大庆典。她在宴会后台结识了来自王都宫廷舞团的候补舞女莉莉安，两名少女因梦想与憧憬成为朋友，并约定未来在王都重逢。"
  },
  [80832342] = {
    id = 80832342,
    name = "莎尔拉收到莉莉安即将晋升正式舞女的来信。与此同时，帝国大军突然越过边境，领主决定率军迎战，并以探望朋友为由将莎尔拉提前送往王都，希望为家族留下最后的血脉。"
  },
  [80832343] = {
    id = 80832343,
    name = "途中得知帝国全面入侵的消息后，莎尔拉不顾劝阻返回故乡，却只见到被战火摧毁的领地与亲友尸骸。在绝望与悲痛中，她受到魔女之力侵蚀，最终化为失去理智的荆棘女妖。"
  },
  [80832344] = {
    id = 80832344,
    name = "荆棘女妖向帝国残军展开复仇，将边境领地化为毒沼。就在一切归于死寂之际，神秘黑衣人出现，并借助星陨之塔将失去归宿的莎尔拉封印，带往新的世界。"
  },
  [80832345] = {
    id = 80832345,
    name = "边境陷落后，失去价值的莉莉安遭到宫廷舞团抛弃，并被诬陷偷窃而除名。曾经近在咫尺的梦想顷刻崩塌，她被迫独自面对残酷现实。"
  },
  [80832346] = {
    id = 80832346,
    name = "流落街头的莉莉安被流浪星火马戏团收留。这里聚集着各种被社会遗弃的人们，他们彼此扶持，共同生活，也让莉莉安重新感受到家的温暖。"
  },
  [80832347] = {
    id = 80832347,
    name = "为了换取过冬物资，马戏团接受贵族邀请进行演出。面对贵族的恶意刁难，莉莉安被迫挑战高空钢丝表演。意外坠落后，她亲眼目睹家人们遭到屠戮，内心彻底崩溃。"
  },
  [80832348] = {
    id = 80832348,
    name = "在绝望中觉醒为魅惑魔女后，莉莉安构筑出一个没有战争与压迫的理想世界，将逝去的家人与朋友永远留在身边。然而随着时间流逝，她也逐渐遗忘了现实与自己的过去。"
  },
  [80832349] = {
    id = 80832349,
    name = "隐居深山的星象师玛琳娜通过观测星象预见王国即将迎来重大灾难。尽管老师曾告诫她不要轻易干涉命运，她仍决定前往王都示警，希望阻止悲剧发生。"
  },
  [80832350] = {
    id = 80832350,
    name = "抵达王都后，玛琳娜试图通过官员向王室传达灾难预言，却被视作危言耸听的疯子。面对权贵的轻视与冷漠，她第一次体会到现实与理想之间的巨大落差。"
  },
  [80832351] = {
    id = 80832351,
    name = "玛琳娜转而求助于曾受老师帮助的伯爵，却发现对方只关心如何借灾难攫取利益。理想主义与现实利益的冲突彻底暴露，也让玛琳娜逐渐理解老师曾经的告诫。"
  },
  [80832352] = {
    id = 80832352,
    name = "边境陷落后，玛琳娜被民众当作散播灾厄的女巫，并遭到逮捕审判。在即将被执行火刑之际，她启动老师留下的圣物星陨之塔，从众人面前消失。"
  },
  [80832353] = {
    id = 80832353,
    name = "玛琳娜根据预言来到已经化作毒沼的边境领地，并找到荆棘女妖。在窥见莎尔拉悲惨过往后，她放弃处决对方，转而使用星陨之塔为其创造新的容身之所。"
  },
  [80832354] = {
    id = 80832354,
    name = "封印莎尔拉后，玛琳娜继续追寻下一场灾难，误入魅惑魔女构筑的理想世界。面对试图守护家人与幸福的莉莉安，她逐渐了解到这场幻境背后的真相。"
  },
  [80832355] = {
    id = 80832355,
    name = "在理解莉莉安的痛苦后，玛琳娜再次启动星陨之塔，将魅惑魔女封印。随着幻境崩塌，虚假的幸福随之消散，而现实中的真相也重新展现在她面前。"
  },
  [80832356] = {
    id = 80832356,
    name = "面对将自己视为女巫的人群，玛琳娜做出最后一次预言，却依旧无人愿意相信。彻底失望的她选择进入星陨之塔，与两位少女一同离开这个世界，并最终知晓了星陨之塔真正的秘密。"
  },
  [80832357] = {
    id = 80832357,
    name = "阿芙佳朵带着藏宝图踏入黄沙区域，在寻找宝物的途中遇见了同样前往沙海深处的探险者，在得知彼此身份后，决定暂时结伴同行。"
  },
  [80832358] = {
    id = 80832358,
    name = "踏上旅途后，你发现阿芙佳朵并不急于寻找传闻中的宝藏。对她而言，沿途遇见的风景与隐藏的故事，同样是探险中珍贵的收获。"
  },
  [80832359] = {
    id = 80832359,
    name = "你们在沙海中遭遇了一伙盗宝团，面对对方的勒索，阿芙佳朵展现出了强大的实力。"
  },
  [80832360] = {
    id = 80832360,
    name = "在一处补给营地，你们遇见一名声称掌握宝物线索的商人。在一番确认后，阿芙佳朵揭穿了商人的谎言。"
  },
  [80832361] = {
    id = 80832361,
    name = "深入沙海后，你们救下了一名迷路的探险者。这次意外的相遇，让你们获得了通往宝物所在之地的重要线索。"
  },
  [80832362] = {
    id = 80832362,
    name = "按照线索，两人终于抵达藏宝图标记的位置，在解决完周围活动的魔物后，成功进入了遗迹。"
  },
  [80832363] = {
    id = 80832363,
    name = "遗迹深处的宝箱终于被开启，然而其中没有想象中的财富，只有一本记录着过往探险经历的神秘手札。一段被遗忘的旅程，也因此重新展现在你们面前。"
  },
  [80832364] = {
    id = 80832364,
    name = "阅读手札中的记录后，你们逐渐了解了一名古代探险者留下的故事，阿芙佳朵也表露了自己对探险的看法。在做出再见的约定后，你和阿芙佳朵各自离去。"
  },
  [80832365] = {
    id = 80832365,
    name = "迷迭香在密林中击败袭来的魔物，却发现自己似乎遗忘了一些重要的事情。就在她疑惑之时，熟悉的伙伴紫罗兰出现，并告诉她二人正准备前往一处被魔物围困的据点进行支援。"
  },
  [80832366] = {
    id = 80832366,
    name = "迷迭香与紫罗兰赶往被围困的据点，一路上两人配合默契，轻松解决沿途出现的魔物。紫罗兰感慨两人作为多年同行的伙伴，已经拥有了无比熟练的战斗方式。"
  },
  [80832367] = {
    id = 80832367,
    name = "迷迭香与紫罗兰抵达被魔物袭击的据点，发现当地情况比预想更加危急。凭借长期配合形成的默契，二人迅速压制魔物。然而就在危机即将解除时，更强大的头目级魔物出现。"
  },
  [80832368] = {
    id = 80832368,
    name = "经过一番激烈战斗，迷迭香与紫罗兰联手击败了头目级魔物。得救的据点居民将两人视为英雄，并对她们表达感谢。"
  },
  [80832369] = {
    id = 80832369,
    name = "面对新的区域、新的生态以及可能隐藏的秘密，迷迭香展现出了探险者最纯粹的热情。"
  },
  [80832370] = {
    id = 80832370,
    name = "迷迭香与紫罗兰遭遇一伙拦路抢劫的匪徒，迷迭香轻松将其打败。然而紫罗兰却询问迷迭香，为何不将他们都杀掉。这样的话语，不由令迷迭香感到违和。"
  },
  [80832371] = {
    id = 80832371,
    name = "在新区域的探索中，迷迭香发现紫罗兰对于这些曾经最向往的探险内容逐渐失去兴趣。随着违和感堆积，迷迭香终于意识到，眼前这个伙伴虽然拥有紫罗兰的外表，却并不真正的她。"
  },
  [80832372] = {
    id = 80832372,
    name = "迷迭香揭穿了紫罗兰的真实身份，但制造这个幻境的存在仍然试图挽留她。迷迭香果断拒绝了这个虚假的世界。"
  },
  [80832373] = {
    id = 80832373,
    name = "罗蕾娜跟着莱伊返回村庄，刚抵达村口，罗蕾娜便察觉到异常的灵力波动，而莱伊也凭借自身特殊能力感受到了村外聚集的亡灵。"
  },
  [80832374] = {
    id = 80832374,
    name = "罗蕾娜带着莱伊来到村外树林，准备处理聚集于此的亡灵。然而，在战斗过程中，她逐渐发现，这些亡灵聚集的背后似乎另有隐情。"
  },
  [80832375] = {
    id = 80832375,
    name = "解决村外的亡灵后，罗蕾娜来到莱伊家中暂时休息。莱伊向罗蕾娜讲述了自己的过往，同时也表示自己因为想要回报村子里的大家，所以才想力所能及的帮助村里人。"
  },
  [80832376] = {
    id = 80832376,
    name = "出于对罗蕾娜强大和温柔的憧憬，莱伊主动拜师罗蕾娜。面对莱伊真诚的请求，原本不愿收徒的罗蕾娜最终答应下来。"
  },
  [80832377] = {
    id = 80832377,
    name = "罗蕾娜一边调查村庄附近亡灵聚集的原因，一边指导莱伊进行修行。随着调查深入，罗蕾娜终于发现，所有异常都指向附近一处隐藏的遗迹。"
  },
  [80832378] = {
    id = 80832378,
    name = "罗蕾娜带着莱伊进入遗迹调查，发现这里残留着一个召唤亡灵的祭坛。正当二人疑惑之时，村民哈特出现，并承认祭坛是自己建立的。为了再次见到已经逝去的妻子，他从巫师那里学习了召唤亡灵的方法，却没想到因此引来了大量亡灵。"
  },
  [80832379] = {
    id = 80832379,
    name = "正当村民哈特准备拆除祭坛时，积累的灵力与亡灵怨念发生失控。大量怨念融合成强大的亡灵，罗蕾娜一边护卫二人，一边与强大的亡灵战斗。"
  },
  [80832380] = {
    id = 80832380,
    name = "经过激烈战斗，罗蕾娜终于找到了怨灵的核心，并将其净化。临别之际，罗蕾娜也与莱伊做出了再会的约定。"
  },
  [80832381] = {
    id = 80832381,
    name = "雾铃来到曾经困住自己的山谷，准备寻找合适的位置布置引渡亡灵的仪式。然而在测量过程中，她意外踏入结界范围，再次被困其中。"
  },
  [80832382] = {
    id = 80832382,
    name = "雾铃选好地方准备布置引渡仪式，然而却被山谷中的亡灵察觉，亡灵纷纷向她发起攻击。为了保护自己和争取时间，雾铃只能暂时放下仪式，与不断袭来的亡灵展开战斗。"
  },
  [80832383] = {
    id = 80832383,
    name = "雾铃暂时击退袭来的亡灵后，抓紧时间布置引渡仪式。然而亡灵似乎察觉到了她想让它们离开的意图，不断发动攻击。"
  },
  [80832384] = {
    id = 80832384,
    name = "正当雾铃陷入亡灵围攻时，一名神秘探险者及时赶到。双方交流后，雾铃得知对方的身份——前来消灭亡灵的探险者罗蕾娜。为了引渡亡灵，雾铃请求罗蕾娜先别消灭这些亡灵。"
  },
  [80832385] = {
    id = 80832385,
    name = "面对雾铃的请求，罗蕾娜没有立即答应，而是提醒她，这些亡灵不会轻易接受离开。无奈雾铃心意已决，执意想要引渡它们，罗蕾娜最终还是答应了雾铃。但也表示如果雾铃无法做到，自己便会消灭这些亡灵。"
  },
  [80832386] = {
    id = 80832386,
    name = "为了让雾铃完成引渡仪式，罗蕾娜主动承担护卫任务。越来越多的亡灵想要中断雾铃，但都被罗蕾娜击退。"
  },
  [80832387] = {
    id = 80832387,
    name = "引渡仪式即将完成，让周围的亡灵越发躁动不安。那只曾帮助过雾铃的亡灵也表现得极为挣扎。在罗蕾娜的全力护卫之下，引渡仪式终于完成。"
  },
  [80832388] = {
    id = 80832388,
    name = "雾铃的劝解下，大部分亡灵选择接受轮回，仍然执着不愿离开的亡灵也在两人的努力下被送离现世。雾铃邀请罗蕾娜一起享受庆典，却得知罗蕾娜要回去和自己的弟子团聚，雾铃索性表示自己和罗蕾娜一起回去。"
  },
  [80832389] = {
    id = 80832389,
    name = "你帶著安妮斯幾人前往未探索區域黑暗洞窟調查，途中察覺到一股怪異的魔力反應。當你們抵達洞窟深處時，只見不祥的「紅霧」正縈繞在一塊巨大結晶周圍並向四面擴散。"
  },
  [80832390] = {
    id = 80832390,
    name = "空間裂隙突然失控，兩名來自異世界的少女意外墜入黑暗洞窟。你們在魔物襲擊中與她們並肩作戰，並得知她們分別是火焰魔法師卡羚與精靈獵人蘇菲雅。"
  },
  [80832391] = {
    id = 80832391,
    name = "戰鬥引發岩壁坍塌，眾人徹底被困在地下，而幽暗封閉的環境也讓卡羚陷入強烈的恐懼之中。面對突然失控的卡羚，你們全力陪伴她度過這場突如其來的心理危機。"
  },
  [80832392] = {
    id = 80832392,
    name = "在你們的鼓勵下，卡羚終於意識到自己並不是孤身一人。重新振作起來的卡羚再次拿起魔法杖，並以強大的火焰魔法與眾人並肩作戰，徹底擊敗眼前的魔物。"
  },
  [80832393] = {
    id = 80832393,
    name = "你們成功修復神秘魔法陣，並重新啟動了通往異世界的傳送門。就在卡羚與蘇菲雅準備向眾人告別之際，洞窟卻再次發生劇烈震動，一股比先前更加恐怖的氣息從地底深處甦醒。"
  },
  [80832394] = {
    id = 80832394,
    name = "從巨大坑洞中出現的恐怖存在，正是一直阻礙黑暗洞窟探索的真正頭目。你原本希望卡羚與蘇菲雅先行返回異世界，但兩人選擇留下，與眾人共同面對危機。"
  },
  [80832395] = {
    id = 80832395,
    name = "蘇菲雅及時識破頭目的逃亡意圖，眾人抓住機會發動最後的圍攻。在卡羚強大的火焰魔法、蘇菲雅敏銳的獵人直覺以及所有人的協力之下，頭目最終被徹底擊敗。"
  },
  [80832396] = {
    id = 80832396,
    name = "卡羚與蘇菲雅透過傳送門返回了自己的世界，在臨別之際，她們約定未來有機會一定會再次相見。隨著兩人的身影消失在傳送門中，這場短暫卻難忘的探險正式落下帷幕。"
  },
  [80832397] = {
    id = 80832397,
    name = "菲欧拒绝继续为圣物吸运，缇法尼确认圣物已认主菲欧、离匣即失效，遂下令强夺，冲突升级。"
  },
  [80832398] = {
    id = 80832398,
    name = "主角团护送菲欧突围，蒂娜追查古籍，揭晓「厄运之匣」的本质——它是厄运的搬运工，只转移、从不消灭。"
  },
  [80832399] = {
    id = 80832399,
    name = "菲欧与安妮斯深夜深谈，安妮斯道出灾祸魔女的孤独，菲欧意识到自己的霉运只能自己扛"
  },
  [80832400] = {
    id = 80832400,
    name = "菲欧决定回到圣物前，并在此间领悟自己霉运与射术同源——隐士教她的不是射箭，而是与霉运厄运共生的本事。"
  },
  [80832401] = {
    id = 80832401,
    name = "昨夜缇法尼借雾突袭、声东击西，精准掳走身负转嫁霉运的安妮斯作为实验引子；今朝对峙，你与蒂娜暗中策应、接应救人，绝境中菲欧关键时刻一箭必中再度应验。"
  },
  [80832402] = {
    id = 80832402,
    name = "菲欧亲手引回厄运，你与蒂娜为她清出射箭空间，最后一箭贯穿「厄运之匣」——圣物失效，她选择与霉运共存。"
  },
  [80832403] = {
    id = 80832403,
    name = "缇法尼实验落空，带着残局退走；无间狱线收束，交界地重归平静。"
  },
  [80832404] = {
    id = 80832404,
    name = "菲欧选择与霉运共存，安妮斯与她约定下次同行；菲欧的名号自此传开，运气守恒成为她独特的活法。"
  },
  [80832405] = {
    id = 80832405,
    name = "寻宝队将二人团团围住，双方攻防来回、互有攻守，最后主角与逐幻者联手撕开包围、占得上风。"
  },
  [80832406] = {
    id = 80832406,
    name = "寻宝队暂时退开，逐幻者向主角讲起当年被打劫的经过——散步偶遇分赃、被围落败、回去苦练、独自讨回公道。主角这才明白她认真准备的分量。"
  },
  [80832407] = {
    id = 80832407,
    name = "铁牙使阴招——破坏奇景、引来魔物。逐幻者不愿奇景被毁，决定不再退让。战斗中她意外发现：植物能吸收魔物血中的浊炁、自行愈合伤口。"
  },
  [80832408] = {
    id = 80832408,
    name = "铁牙一伙再次逼上来，逐幻者正面迎战，以优雅而有力的身手击退对方。铁牙见势不妙，放出狠话撤退。"
  },
  [80832409] = {
    id = 80832409,
    name = "铁牙搬出「好东西归有本事的人」的歪理，逐幻者正面反驳：它不属于任何人。主角提议据点派人守护，逐幻者却说守得了一时守不了一世——得让它自己能保护自己。"
  },
  [80832410] = {
    id = 80832410,
    name = "铁牙狗急跳墙砸出毒液，植物却将毒中的浊炁尽数吸收、进入蜕变——真身隐入浊炁深处，表层只留幻影。逐幻者与主角联手拖住铁牙，浊炁屏障成形，贪念者再也摸不到奇景分毫。"
  },
  [80832411] = {
    id = 80832411,
    name = "铁牙被浊炁屏障拒之门外，一伙人被押送据点。逐幻者向主角讲清机制：浊炁对人有害，对以浊炁为食的植物却是铠甲——让所有人都能看见，却没有人能带走。"
  },
  [80832412] = {
    id = 80832412,
    name = "奇景「可远观不可亵玩」的传闻传遍据点，「逐幻者」一战成名。她与主角约定，等这片幻景再次变换，还要一起来看。"
  },
  [80832413] = {
    id = 80832413,
    name = "圣诞节当天，吉光背上装满礼物的袋子，追着远赴深渊的探险者们出发了。然而一路上，她发现大家真正需要的似乎并不是礼物。"
  },
  [80832414] = {
    id = 80832414,
    name = "一支探索失败的队伍让吉光明白，比起贵重的礼物，有时候一句问候、一顿热饭，以及“有人记得自己”，才是最需要的东西。"
  },
  [80832415] = {
    id = 80832415,
    name = "面对即使受伤也不愿停下的年轻探险者，吉光第一次没有阻止对方继续前进。她告诉对方，冒险可以一直向前，但也要记得什么时候该回头。"
  },
  [80832416] = {
    id = 80832416,
    name = "回到铁壁城的吉光发现，精心准备的圣诞会场几乎空无一人。可她并没有放弃，而是决定把圣诞节亲自带到那些还在深渊中的人身边。"
  },
  [80832417] = {
    id = 80832417,
    name = "吉光再次深入遗迹，为探险者们带去食物、药品和圣诞装饰。没想到越来越多的人主动加入，让深渊中的临时营地也有了节日的温度。"
  },
  [80832418] = {
    id = 80832418,
    name = "圣诞夜，探险者们带着各自准备的东西陆续回到铁壁城。空荡的广场再次热闹起来，而吉光也终于明白——只是一直没有人愿意第一个停下来。"
  },
  [80832419] = {
    id = 80832419,
    name = "圣诞晚会上，探险者们分享起各自的冒险故事。听着那些关于危险与归来的故事，吉光终于理解了自己小时候最喜欢的“逢凶化吉”究竟意味着什么。"
  },
  [80832420] = {
    id = 80832420,
    name = "圣诞夜即将结束，吉光发现礼物袋里还留下了一份不知来自谁的礼物。她第一次意识到，在漫长的旅途中，能够遇见愿意同行的人，本身就是一种幸运。"
  },
  [80832421] = {
    id = 80832421,
    name = "露西亚查明窃愿的是镇外涌来的浊炁暗潮——岁末岁火最弱时，无意识的浊潮趁虚扑食灯中愿望。老守火人莫里斯早已察觉，连日用自己的火气护着岁火，人却先撑不住了。"
  },
  [80832422] = {
    id = 80832422,
    name = "岁火祭前夜，二人沿湖巡灯，摸清浊潮专挑老灯下手的习性；商量以「拦不住就引」定计——镇外挂灯饵、老灯添双芯、岁火外围拉火气线，并动手布置。"
  },
  [80832423] = {
    id = 80832423,
    name = "岁火祭前夜，浊潮具象化成巨大的黑暗形体，无面目、无言语，只是本能地吞食灯中愿望。主角与露西亚背靠背迎战，护住一盏盏灯，将浊潮引离岁火。"
  },
  [80832424] = {
    id = 80832424,
    name = "岁火祭当夜，浊潮再临。二人以灯饵引敌、且战且退；战斗中露西亚弯腰护灯的动作让主角记起雪夜往事，约定之人终于相认；浊潮愈强，露西亚决意以旧提灯火种引燃岁火。"
  },
  [80832425] = {
    id = 80832425,
    name = "浊潮仍在膨胀。露西亚决定以旧提灯中珍藏多年的火种为引，引燃岁火，让岁火的光把被困的愿望引回各自的家；火种离手，飞向炉火镇。"
  },
  [80832426] = {
    id = 80832426,
    name = "火种落进炉火镇，岁火冲天而起。被困的愿望化作光点从浊潮中挣脱，落回各自的灯里；失去所有光芒的浊潮，在岁火的光中消散。"
  },
  [80832427] = {
    id = 80832427,
    name = "岁火冲天而起，新年的第一缕光洒满炉火镇。老守火人莫里斯由学徒小燃搀着来到火边，把守了一辈子的岁火郑重托付给小燃，然后安详地闭上了眼。露西亚与主角见证了这场传承。"
  },
  [80832428] = {
    id = 80832428,
    name = "新年夜，万家灯火。两人并肩立在广场边，看岁火熊熊。露西亚说：最好的那盏灯，是你当年帮我点亮的那盏。约定兑现，缘分之约成真。"
  },
  [80832429] = {
    id = 80832429,
    name = "巡礼当天，两人第一次戴着面具公开亮相；全镇欢呼，孩子们把她们围住，两人嘴上嫌弃，脚步却没退。"
  },
  [80832430] = {
    id = 80832430,
    name = "第一处表演点，尼莉莎因为紧张忘记了走位，只好自由发挥；蒂娜被带得错开位置，却意外被观众当成改编，全场笑成一片。"
  },
  [80832431] = {
    id = 80832431,
    name = "第二处表演点要狼嚎，蒂娜的吼声含糊得像清嗓子；孩子们送来了润喉糖，蒂娜改用眼神代替吼声，反而赢了满堂彩。"
  },
  [80832432] = {
    id = 80832432,
    name = "中场休整时尼莉莎脱口说出一句对蒂娜的夸赞，本人当场愣住；老匠人说出「戴上面具的人会说出自己的心里话」，安妮斯和你都很期待接下来的巡演。"
  },
  [80832433] = {
    id = 80832433,
    name = "城镇街道（夜）的表演点上，尼莉莎把要送去外婆家的点心一路分给孩子，还顺手替摊主扶住了被风掀翻的布棚；篮子越来越空，孩子回赠了一朵纸叠的花。"
  },
  [80832434] = {
    id = 80832434,
    name = "过窄桥时人流挤成一团，蒂娜不动声色地把靠近主角团的每一个人都挡了回去；商贩的生意做不成，孩子们却排着队要被狼送过去。"
  },
  [80832435] = {
    id = 80832435,
    name = "安妮斯在路边石板上把两人的表现讲得像一场赛事，围观的越聚越多，你和安妮斯低声交换意见，开始担心这样下去巡礼会变成什么样子。"
  },
  [80832436] = {
    id = 80832436,
    name = "豪宅外有位老妇人丢了孙子，尼莉莎心急想去寻找；被蒂娜拦住，蒂娜巧用庆典主演的身份在人群中找到丢失的孩子。"
  },
  [80832437] = {
    id = 80832437,
    name = "最后一段的后台，两人一边调试道具弓一边听孩子们追问；尼莉莎把每一件体贴的事都说成「小红帽会这么做」，说到第七句时，她自己先愣住了。"
  },
  [80832438] = {
    id = 80832438,
    name = "候场的空档里，尼莉莎追问蒂娜当初为什么答应这场委托；蒂娜说因为和尼莉莎是一个团队，尼莉莎也说出以为蒂娜不喜欢自己，原来一切都是误会。"
  },
  [80832439] = {
    id = 80832439,
    name = "入场口候场时，尼莉莎借着面具的坦率向蒂娜认真道谢——为桥上那次自己贸然要去找丢失孩子的事情；蒂娜也第一次说出「谢谢你平时保护了大家」。孩子们听见了，在边上起哄，安妮斯笑得直不起腰。"
  },
  [80832440] = {
    id = 80832440,
    name = "你看得出来两人已经不像平时的样子，却决定不点破；一个小男孩跑来替镇上的孩子问了一个问题，答案顺着人群传回了她们耳朵里。"
  },
  [80832441] = {
    id = 80832441,
    name = "压轴实景剧中最关键的幸运铃祈愿，尼莉莎连拉三弓射落高处的彩铃，蒂娜在下面扛住孩子们一整轮冲撞；配合得严丝合缝。"
  },
  [80832442] = {
    id = 80832442,
    name = "最后一幕的演绎从追逐战变成了狼女士救了小红帽，在台下观众发出疑问时，两人合力把故事圆了回来，圆满的完成了本次的巡演。"
  },
  [80832443] = {
    id = 80832443,
    name = "巡礼落幕，两人摘下面具的一刻终于反应过来自己今天说过什么；安妮斯当众念起「今日亮点回顾」，台词被一句句点名，念得她们受不了，撂下「面具的事不许再提」就跑。"
  },
  [80832444] = {
    id = 80832444,
    name = "烟火升起，整座铃穗镇都在欢呼；回到据点前，老匠人送给了二人面具挂件，两人的关系和日常有了一些微妙的变化。"
  },
  [80840001] = {
    id = 80840001,
    name = "延绵险峰"
  },
