    name = "「 Lv.%d」%s"
  },
  [80900001] = {id = 80900001, name = "绝地"},
  [80900002] = {id = 80900002, name = "崩解"},
  [80900003] = {id = 80900003, name = "狂化"},
  [80900004] = {id = 80900004, name = "吞噬"},
  [80900005] = {id = 80900005, name = "减速"},
  [80900006] = {id = 80900006, name = "穿刺"},
  [80900007] = {id = 80900007, name = "提速"},
  [80900008] = {id = 80900008, name = "亡怒"},
  [80910010] = {
    id = 80910010,
    name = "敌方全体成员防御力提升%d%%。"
  },
  [80910020] = {
    id = 80910020,
    name = "我方全体「言灵」「猎影」成员，受到伤害时提升%d%%。"
  },
  [80910030] = {
    id = 80910030,
    name = "每隔%d秒，敌方全体「言灵」「猎影」成员，伤害提升%d%%。"
  },
  [80910040] = {
    id = 80910040,
    name = "每隔%d秒，我方当前生命值最高的成员会受到%d%%生命上限的伤害。"
  },
  [80910050] = {
    id = 80910050,
    name = "敌方全体「言灵」「猎影」成员，对以自身为中心且半径200的圆形范围内的目标攻速降低%d%%。"
  },
  [80910060] = {
    id = 80910060,
    name = "敌方全体「异刃」攻击时，无视目标%d的防御力。"
  },
