    id = 81371024,
    name = "猎影赠礼Ⅲ"
  },
  [81371025] = {
    id = 81371025,
    name = "心意赠礼Ⅲ"
  },
  [82000001] = {
    id = 82000001,
    name = "由地面上多种宝石矿物加工而成的贵重晶石，通体晶莹剔透，色泽绚丽，在人类社会中拥有极高价值。"
  },
  [82000002] = {
    id = 82000002,
    name = "源矿加工而成的珍贵结晶，由于成品率极低，而且原料只存在于那些超强大魔物的巢穴，开采难度极大，在人类社会中始终拥有高昂且稳定的价值。"
  },
  [82000003] = {
    id = 82000003,
    name = "日常贸易中的通用货币，虽然不及欧泊、源晶贵重，但仍然拥有稳定的价值。"
  },
  [82000004] = {
    id = 82000004,
    name = "浊炁会不断侵蚀人类的精神、躯体，使人的理性逐渐丧失。倘若理性彻底消散，人类或许将在深渊迷失。"
  },
  [82000005] = {
    id = 82000005,
    name = "每一位声名远扬的队长都经历了无数风雨挫折，一步一步，从懵懂走向成熟，从资深迈向传说。"
  },
  [82000006] = {
    id = 82000006,
    name = "不因成功而自满，不因失败而沉沦，懂得及时吸取经验教训的探险者在深渊中才能走得更远。"
  },
  [82000007] = {
    id = 82000007,
    name = "即便只是微不足道的小事也有它存在的意义，探险凭证会如实记录队长们的每一次努力。"
  },
  [82000008] = {
    id = 82000008,
    name = "如同商店街促销活动一样，达成公会指定的目标便能获得公会发放的积点。当然，这些积点的作用也和商店街的印章一样，换取奖励而已。"
  },
  [82000009] = {
    id = 82000009,
    name = "不管任何事，精力充沛时才能做得更好。特别是在深渊中行动，没有精力时就好好休息吧，逞强可算不上明智。"
  },
  [82000010] = {id = 82000010, name = "-"},
  [82000011] = {
    id = 82000011,
    name = "感谢探险者为深渊探索付出的努力，从深渊收集到的每一份情报，都将成为人类探索事业的基石。"
  },
  [82000013] = {
    id = 82000013,
    name = "每天处理适量的探险事务就足够了，对优秀的探险者而言，休息也是修行中的重要一环。"
  },
  [82000014] = {
    id = 82000014,
    name = "击败强大的魔物是探险者的浪漫，荣耀属于敢向它们发起挑战的勇敢者。"
  },
  [82000017] = {
    id = 82000017,
    name = "一份拟定好的探索合约。"
  },
  [82000018] = {
    id = 82000018,
    name = "秘银制作的深渊凭证，颇受各个探险队欢迎。"
  },
  [82000019] = {
    id = 82000019,
    name = "黑曜制作的深渊凭证，颇受各个探险队欢迎。"
  },
  [82000020] = {
    id = 82000020,
    name = "远途动态积分"
  },
  [82000021] = {
    id = 82000021,
    name = "传说吸收了黑夜破晓时的力量，能够破除恶瘴，驱散黑暗。采集后放置一段时间便会因力量流失自然消散。"
  },
  [82000022] = {
    id = 82000022,
    name = "每一次行动都充满了风险，但也为探险者们积累了宝贵经验，为前往更广阔的区域提供了可能。"
  },
  [82000023] = {
    id = 82000023,
    name = "杰出工匠弗拉克研制的精密道具，有效调和了深渊刻印中的魔力波动，让探险者们在合成刻印时更加稳定。"
  },
  [82000024] = {
    id = 82000024,
    name = "黎明要塞为规范深渊先遣队发行的特殊物品，持有者可以在探索时享受到诸多便利。"
  },
  [82000025] = {
    id = 82000025,
    name = "散落在深渊各处的古币，据说蕴藏着有关深渊的秘密。一些商人正在四处收集这些古币。"
  },
  [82000026] = {
    id = 82000026,
    name = "做工精致的钥匙，蕴藏着追溯时光的力量。"
  },
  [82000027] = {
    id = 82000027,
    name = "闪烁着动人光彩的结晶，能从一些游商货郎手中换取特别物件。"
  },
  [82000028] = {
    id = 82000028,
    name = "由名匠亲手雕琢而成的绚丽水晶，寓意着典雅高贵，是无数人梦寐以求的臻品。"
  },
  [82000029] = {
    id = 82000029,
    name = "由名匠制作的单色水晶，寓意着优雅纯洁，深受无数人的喜爱。"
  },
  [82000030] = {
    id = 82000030,
    name = "对大部分探险者而言，采集矿物比与魔物战斗麻烦多了。不过为了开采更多的物资提升自己，只能全力以赴了。"
  },
  [82000031] = {
    id = 82000031,
    name = "探索苍青山岭时发现的古币，造型奇异，摸起来有种冰凉的触感。"
  },
  [82000032] = {
    id = 82000032,
    name = "在苍青山岭部分遗迹中发现的特殊古币，外形与金币相似，但材质存在较大差异。"
  },
  [82000033] = {
    id = 82000033,
    name = "由名匠亲手雕琢而成的璀璨水晶，寓意着纯洁高雅，是无数人梦寐以求的臻品。"
  },
  [82000034] = {
