  },
  [82090501] = {
    id = 82090501,
    name = "A festive stocking filled with... something."
  },
  [82090502] = {
    id = 82090502,
    name = "A mysterious Christmas gift box—who knows what might be hidden inside?"
  },
  [82090503] = {
    id = 82090503,
    name = "吃下美味的月餅就可以隨機獲得驚喜道具唷！"
  },
  [82090504] = {
    id = 82090504,
    name = "開啟月兔玩偶即可選擇獲得１個「命運留影」或１個「奇蹟留影」。"
  },
  [82090505] = {
    id = 82090505,
    name = "심연의 조개 속에서만 자라나는\n신비로운 결정. 운명의 인연을\n불러오는 힘이 깃들어 있다."
  },
  [82090506] = {
    id = 82090506,
    name = "심연 깊은 곳에서 발견되는\n조개. 그 안에 무엇이 들었을지는\n열어 봐야만 알 수 있다."
  },
  [82090507] = {
    id = 82090507,
    name = "列蒂希雅的专属服饰。"
  },
  [82090508] = {
    id = 82090508,
    name = "守护者的专属服饰。"
  },
  [82090509] = {
    id = 82090509,
    name = "蕾妮希雅的专属服饰。"
  },
  [82090601] = {
    id = 82090601,
    name = "是深渊对挑战者的认可，也是深渊对探险者的馈赠。"
  },
  [82090602] = {
    id = 82090602,
    name = "散落在深渊中的贵重宝盒，没人知道里面藏着什么。"
  },
  [82100001] = {
    id = 82100001,
    name = "连结命运和希望，将渴望化作穿越界限的力量。当那份力量显现之时，无论幻梦还是真实，强烈的渴望终将得以传达。"
  },
  [82100004] = {
    id = 82100004,
    name = "连结宿命和奇迹，将祈愿化作穿越时空的力量。当那份力量显现之际，无论平凡还是崇高，真挚的祈愿必将得到回应。"
  },
  [82110001] = {
    id = 82110001,
    name = "生长于深渊险峻区域，在黑暗中叶片会散发出淡淡微光的野草，口感略为酸苦，因具备稀释、驱散浊炁的功效，成为了探险者行走的深渊的必需品。"
  },
  [82110002] = {
    id = 82110002,
    name = "花期极短的洁白之花，生长于浊炁浓郁的地区。当它完全盛放之时，周围的浊炁会被迅速稀释，而当浊炁接近消散之际，它也会随之凋零。"
  },
  [82110004] = {
    id = 82110004,
    name = "精选优质莹草，以特殊方法加工而成的产品。拥有比普通莹草更好的口感，更强的效果，一经推出，便受到广大探险者群体的欢迎。"
  },
  [82110006] = {
    id = 82110006,
    name = "精心制作的蛋糕。"
  },
  [82110101] = {
    id = 82110101,
    name = "公会向各位杰出探险者颁发的挑战许可，是前往特殊副本的重要凭证。"
  },
  [82110102] = {
    id = 82110102,
    name = "公会向各位杰出探险者颁发的挑战许可，是前往特殊副本的重要凭证。"
  },
  [82130001] = {
    id = 82130001,
    name = "精选优质莹草，以特殊方法加工而成的产品。拥有比普通莹草更好的口感，更强的效果，一经推出，便受到广大探险者群体的欢迎。"
  },
  [82150001] = {
    id = 82150001,
    name = "对在深渊活动的探险者而言，一份可靠的地图足以称之为无价之宝。\n\n费尔斯赠送给菲尼斯的地图，记录着一些据点、圈落的分布和路线。"
  },
  [82150002] = {
    id = 82150002,
    name = "玛蒙之地常见的糖果，甜味十足，颇受探险者喜欢。\n\n尼莉莎赠送给娜米莉，娜米莉又赠送给了蒂娜。"
  },
  [82150003] = {
    id = 82150003,
    name = "外表黑漆漆的，存在一些奇怪纹路的石头，即便在众多奇异的深渊物品中也显得颇为特别。\n\n娜米莉赠送给蒂娜的石头。"
  },
  [82150004] = {
    id = 82150004,
    name = "做工极为精致的戒指，指环内镌刻的铭文已有些模糊，但戒面上晶莹的蔷薇仍璀璨闪耀。\n\n你从魔王手中得到的戒指。"
  },
  [82151001] = {
    id = 82151001,
    name = "你和阿芙佳朵在沙海遗迹中发现的手札。记录着一段尘封的探险旅途。"
  },
  [82151002] = {
    id = 82151002,
    name = "虽然只是一段虚幻的旅途，但就将这段旅途作为目标，全力以赴吧。"
  },
  [82151003] = {
    id = 82151003,
    name = "守夜人家族的信物。即便因为信念冲突脱离了家族，罗蕾娜也并未抛弃守夜人的使命。"
  },
  [82151004] = {
    id = 82151004,
    name = "以温柔的灯火驱散黑暗和迷惘。为迷途者点亮归路，为前行者指引方向。"
  },
  [82151005] = {
    id = 82151005,
    name = "以稀有晶石手工打磨而成的箭簇，透亮如琥珀，传说曾一箭贯穿圣物「厄运之匣」。吉娜说，这一箭攒了她二十多年的运气——吉光片羽，可遇不可求。"
  },
  [82151006] = {
    id = 82151006,
    name = "会变幻的奇景在蜕变时留下的一枝幻芽，通体流转柔和的辉光，随光变幻颜色。逐幻者说，看得见的风景，才是真正带得走的宝藏。"
  },
  [82151007] = {
    id = 82151007,
    name = "装着各种礼物的箱子。吉光为每一位探险者都准备了专属于他们的礼物。"
  },
  [82151008] = {
    id = 82151008,
    name = "露西亚珍藏了一整个雪夜的火种，火苗在水晶胆中静静跳动了许多年。当年借火的人归来时，她倾瓶引燃岁火——万灯亮起，便都是重逢的光。"
  },
  [82151009] = {
    id = 82151009,
    name = "铃穗镇老匠人亲手雕的红漆小面具挂坠，眉心嵌着红宝石碎晶。戴上它，再害羞的人也敢说出真心话——红面具底下，是终于敢开口的自己。"
  },
  [82151010] = {
    id = 82151010,
    name = "老匠人另送的墨黑胡桃木小狼面具挂坠，耳尖小巧，眉心嵌暖黄晶石。蒂娜把它和红面具系在了一起——不必再装成凶狠的狼，做安静温柔的自己就好。"
  },
  [82170001] = {
    id = 82170001,
    name = "根据被探险者们所击溃的魔物形象制作的特殊徽记，可设置为探险队的标志。\n强敌来袭结算时，此标志将直接发放给达到条件的探险队，而不会发放给各位队长。"
  },
