  [80651403] = {
    id = 80651403,
    name = "成功发动总攻后，战斗中成员的输出会获得增幅。"
  },
  [80651404] = {
    id = 80651404,
    name = "开启自动战斗时，若「总攻手动设置」已设置，则会优先进行使用；若「总攻手动设置」未设置，则总攻技的选择会根据布阵时成员的站位进行选择：越靠前以及越靠上的成员，且技能处于未冷却状态的成员优先进行选择。"
  },
  [80651405] = {
    id = 80651405,
    name = "「战斗说明」"
  },
  [80651406] = {
    id = 80651406,
    name = "在战斗中「坚甲」「言灵」「猎影」会选择距离自己最近的目标进行攻击。"
  },
  [80651407] = {
    id = 80651407,
    name = "布阵时，若「异刃」前方没有「坚甲」或「异刃」进行阻挡，则会优先选择距离自己最近的「言灵」或「猎影」进行攻击。"
  },
  [80651408] = {
    id = 80651408,
    name = "战斗中，若「异刃」正在移动时受到攻击，则会将攻击目标转移为攻击者。"
  },
  [80651409] = {
    id = 80651409,
    name = "战斗中，成员获得的免伤效果最大不会超过80%%。"
  },
  [80651411] = {
    id = 80651411,
    name = "合理安排成员出战，能左右战场局面"
  },
  [80651412] = {
    id = 80651412,
    name = "对成员进行养成，可以使成员变得更强"
  },
  [80651413] = {
    id = 80651413,
    name = "合理搭配徽章，能更好发挥成员的实力"
  },
  [80651421] = {
    id = 80651421,
    name = "布阵时：可以任意选择一名已上阵成员的队长技，并设置为战斗中总攻阶段生效。"
  },
  [80651501] = {
    id = 80651501,
    name = "总攻技施放时，优先选择「总攻手动设置」的成员，若「总攻手动设置」的成员全部不满足施放条件时，则选择「未设置」的成员。"
  },
  [80651502] = {
    id = 80651502,
    name = "「总攻手动设置」中，相同职业的成员按照从左往右的顺序进行选择；若本轮总攻需要选择的成员处于死亡或无法施放总攻的状态时，则选择下一名可施放的成员。"
  },
  [80651503] = {
    id = 80651503,
    name = "若本轮总攻技施放时，相同职业的全部成员都处于无法施放的状态，则跳过该职业。"
  },
  [80651601] = {
    id = 80651601,
    name = "服饰抽取"
  },
  [80651602] = {
    id = 80651602,
    name = "「购买抽取道具」\n 1. 抽取道具可以在宝匣商店中购买。"
  },
  [80651603] = {
    id = 80651603,
    name = "「奖项获取规则」\n 1. 每抽取1次可获得1个奖项。\n 2. 已经获得过的奖项不会再重复获得。\n 3. 10次抽取可以获得所有奖项。"
  },
  [80651604] = {
    id = 80651604,
    name = "「奖项获得概率」\n 1. 不同抽取次数下的奖项获得概率会随着抽取次数变化，由于概率显示取整会导致当前可抽取奖项概率汇总大于100%%，但是不影响真实概率。\n 2. 已获得的奖项概率将分配给尚未取得的奖项。\n 3. 按照尚未获得的奖项的预设概率，以相应比例进行分配。\n 4. 2等奖项从第2次抽取开始出现。\n 5. 1等奖项从第5次抽取开始出现。"
  },
  [80651605] = {
    id = 80651605,
    name = "「剩余抽取道具的退还」\n 1. 活动结束时，未使用的付费宝匣抽取道具会按1:1的比例自动转化为对应数量的源晶，并通过邮件退还。\n 2. 免费宝匣抽取道具不参与退还。\n 3. 复刻的典藏宝匣将不会有免费宝匣抽取道具"
  },
  [80651606] = {
    id = 80651606,
    name = "「抽取消耗」\n 第1次免费，复刻情况下第1次=1个抽取道具\n 第2次=1个抽取道具\n 第3次=1个抽取道具\n 第4次=2个抽取道具\n 第5次=4个抽取道具\n 第6次=4个抽取道具\n 第7次=6个抽取道具\n 第8次=6个抽取道具\n 第9次=6个抽取道具\n 第10次=6个抽取道具"
  },
  [80651701] = {
    id = 80651701,
    name = "宝匣抽取"
  },
  [80651702] = {
    id = 80651702,
    name = "「获得商会密钥」\n 1. 在活动开放期间内，充值达到指定金额可获取商会密钥。"
  },
  [80651703] = {
    id = 80651703,
    name = "「轮次解锁」\n 1. 周年返利宝匣有多轮奖项。\n 2. 获得本轮内所有奖项并且达到指定时间后，才会开启下一轮奖项。\n 3. 第3轮奖项将会额外重复2次。"
  },
  [80651704] = {
    id = 80651704,
    name = "「奖项获取规则」\n 1. 每抽取1次可获得1个奖项。\n 2. 已经获得过的奖项不会再重复获得。\n 3. 10次抽取可以获得本轮所有奖项。"
  },
  [80651705] = {
    id = 80651705,
    name = "「奖项获得概率」\n 1. 不同抽取次数下的奖项获得概率会随着抽取次数变化，由于概率显示取整会导致当前可抽取奖项概率汇总大于100%%，但是不影响真实概率。\n 2. 已获得的奖项概率将分配给尚未取得的奖项。\n 3. 按照尚未获得的奖项的预设概率，以相应比例进行分配。\n 4. 部分奖项需要抽取指定次数后解锁。"
  },
  [80651706] = {
    id = 80651706,
    name = "「抽取消耗」\n 每轮的抽取消耗相同。\n 第1次=1个商会密钥\n 第2次=1个商会密钥\n 第3次=2个商会密钥\n 第4次=3个商会密钥\n 第5次=4个商会密钥\n 第6次=5个商会密钥\n 第7次=6个商会密钥\n 第8次=7个商会密钥\n 第9次=8个商会密钥\n 第10次=9个商会密钥"
  },
  [80651801] = {
    id = 80651801,
    name = "1.噩梦投影为周期开放的玩法。 \n2.玩法开启时，首领可无限挑战。 \n3.每场战斗有多个阶段，首领在不同阶段将召唤多个魔物作战。  \n4.首领为无限血量，敌方全体属性会随阶段增加而加强。 \n5.本期单次最高输出的挑战，计入本期个人排名。"
  },
