  [80531611] = {
    id = 80531611,
    name = "发动总攻时，对敌方单体目标造成%s（对战模式为%s）当前攻击力的伤害。\n战斗开始时，「黑羽」在身前插入一柄巨剑，协助自身战斗。\n巨剑效果：\n1、巨剑为异刃、暗系，自身无法移动、无法受到治疗、无法被复活；战场中若我方只有巨剑存活时，则战斗判定为失败。\n2、巨剑的攻防血分别为「黑羽」基础攻防血的：%s/%s/%s；暴击率、暴击伤害、格挡率、格挡强度、闪避率基础值均为0。\n3、巨剑每隔5秒，将自身5%%当前生命值转换给「黑羽」。\n4、巨剑阵亡时，会对造成自身阵亡的敌方目标发动一次攻击，造成%s（对战模式为%s）基础攻击力的伤害。\n战斗开始后，若「黑羽」当前生命值低于20%%，且巨剑还存活时，巨剑和「黑羽」立即进入潜行状态，瞬移回巨剑处拔起巨剑，再瞬移回敌方目标处，对其造成%s（对战模式为%s）当前攻击力的伤害，本次攻击时的暴击率提升30%%；攻击后解除潜行状态。"
  },
  [80561611] = {
    id = 80561611,
    name = "自身受到致命伤害时，不会立即阵亡，当前生命值锁定为1，且无法被治疗，%s秒后强制阵亡，一场战斗最多触发1次。"
  },
  [80591611] = {
    id = 80591611,
    name = "总攻阶段时，我方全体成员，攻击力提升%s，暴击率提升%s，暴击伤害提升%s。"
  },
  [80521701] = {
    id = 80521701,
    name = "普攻时，有%s的概率触发%s基础攻击力的额外伤害；若目标附带了「制裁」效果，在触发额外伤害时，额外伤害增加%s。"
  },
  [80531701] = {
    id = 80531701,
    name = "进行5次攻击，每次造成%s当前攻击力的伤害；若敌方存活多名目标时，每次攻击选择不同的目标，会优先选择附加了「制裁」效果的敌方目标；若敌方存活数小于最大攻击次数时，同一目标多次受击，伤害会进行衰减。\n若受击目标被附加了「制裁」效果，则会触发%s当前攻击力的额外伤害。\n「伤害衰减：同一目标多次受击时，受击伤害系数和额外伤害系数会降低，↓0%%/↓40%%/↓50%%/↓60%%/↓70%%/↓80%%」"
  },
  [80541701] = {
    id = 80541701,
    name = "%s提升%s。\n总攻技中通过「制裁」效果触发的额外伤害增加%s。"
  },
  [80541702] = {
    id = 80541702,
    name = "总攻技中通过「制裁」效果触发的额外伤害增加%s。"
  },
  [80561701] = {
    id = 80561701,
    name = "总攻技中的攻击次数增加1次。"
  },
  [80591701] = {
    id = 80591701,
    name = "总攻阶段时，我方全体成员，攻击力提升%s。\n总攻阶段时，「白鸢」圣光的最终伤害提升%s。"
  },
  [80521511] = {
    id = 80521511,
    name = "普攻时，使受到攻击的敌方目标基础攻击力降低%s，并自身基础攻击力提升%s，最大可以叠加%s层。\n当攻击目标死亡后，上述效果全部解除。\n当「莫妮卡」死亡后，上述效果全部解除。"
  },
  [80531511] = {
    id = 80531511,
    name = "对敌方单体目标造成%s当前攻击力的伤害。"
  },
  [80561511] = {
    id = 80561511,
    name = "自身当前生命值百分比小于%s时，自身生命值立即恢复至100%%，一场战斗最多触发1次。"
  },
  [80591511] = {
    id = 80591511,
    name = "总攻阶段时，我方全体「异刃」成员，攻击力提升%s，暴击率提升%s。"
  },
  [80521801] = {
    id = 80521801,
    name = "每隔7秒，自身存储1次生命恢复效果，若战斗中其他成员触发3次时停状态，同样可获得1次生命恢复效果，最大可以存储3次。\n「鬼侍」拥有存储次数，且我方有成员当前生命值百分比低于50%%时，消耗1次次数，为其恢复等同于「鬼侍」%s生命上限+%s的生命值。"
  },
  [80531801] = {
    id = 80531801,
    name = "战斗开始后，我方成员受到来自敌方伤害的%s会为「鬼侍」提供共鸣值，最大存储为「鬼侍」%s生命上限+%s的共鸣值。\n「共鸣值：共鸣值的获得仅为可上阵成员，不包含建筑和战斗过程中的召唤物」\n发动总攻时，对以自身为中心且半径为160的圆形范围内的敌方全体目标造成%s当前攻击力的伤害，同时将当前全部共鸣值100%%转化为心之壁，平均提供给当前存活的全体成员，持续8秒。若我方成员拥有心之壁时，可获得10%%免伤效果。\n「心之壁：可以抵消敌方造成的伤害；不受徽章影响」\n发动总攻时，为我方当前生命值百分比最低的4名成员提供等同于「鬼侍」%s生命上限+%s的持续生命值恢复效果，持续5秒。"
  },
  [80561801] = {
    id = 80561801,
    name = "战斗开始时，自身获得%s生命上限的心之壁，持续%s秒。\n成员拥有心之壁时，免伤效果增加%s。"
  },
  [80591801] = {
    id = 80591801,
    name = "总攻阶段时，我方全体成员，攻击力提升%s，生命恢复效果提升%s。"
  },
  [80521391] = {
    id = 80521391,
    name = "普攻时，有%s的概率触发%s基础攻击力的额外伤害，同时有%s的概率给敌方目标附加机械之心效果。\n「机械之心：目标每叠加3层时，自身恢复等同于弗拉克%s生命上限+%s的生命值」"
  },
  [80531391] = {
    id = 80531391,
    name = "对敌方单体目标造成%s当前攻击力的伤害，若目标附带机械之心效果，则每层机械之心效果会触发%s当前攻击力的额外伤害，最大可以生效10层，攻击结束后，解除受击目标身上的全部机械之心层数。"
  },
  [80541391] = {
    id = 80541391,
    name = "%s提升%s。\n战技中，机械之心效果触发概率增加%s。"
