  },
  [80591621] = {
    id = 80591621,
    name = "总攻阶段时，我方全体成员，攻击力提升%s。"
  },
  [80521821] = {
    id = 80521821,
    name = "战斗开始时，立即获得以自身%s基础攻击力伤害的反伤效果，持续整场战斗。\n每第%s次普攻时，使敌方目标基础防御力降低%s，持续%s秒。"
  },
  [80531821] = {
