  [80541562] = {
    id = 80541562,
    name = "战技中，拥有「命运交织」的成员在该效果持续期间，获得%s的免伤效果。"
  },
  [80561561] = {
    id = 80561561,
    name = "自身当前生命值百分比小于%s时，自身生命值立即恢复至%s，一场战斗最多触发1次。"
  },
  [80591561] = {
    id = 80591561,
    name = "总攻阶段时，我方全体「坚甲」成员，免伤提升%s；我方全体「异刃」成员，攻击力提升%s。"
  },
  [80521591] = {
    id = 80521591,
    name = "每次普攻，获得1层基础攻击力提升%s的效果，最大可以叠加%s层。\n非暴走状态下，每次普攻，存储1次爆炎效果，最大存储为%s次。\n「爆炎：蒙娜进入暴走状态，且存储次数＞0时，每段伤害会触发并消耗1次爆炎，对半径为80的圆形范围内的敌方全体目标造成%s当前攻击力的伤害，该伤害属于普攻类型」"
  },
  [80531591] = {
    id = 80531591,
    name = "发动总攻时，若本轮总攻为奇数轮，则自动施放进入「暴走」状态，攻速提升%s，持续整个总攻阶段。\n「暴走：该状态下的攻击依然为普攻，普攻的形态会发生变化」\n「自动施放：无法手动选择，且不会占用该职业选择名额」"
  },
  [80561591] = {
