  [80522081] = {
    id = 80522081,
    name = "每次普攻，我方全体「猎影」成员攻击力提升%s，最大可以叠加%s层。\n非疾风状态下，每次普攻，存储1次裂穹效果，最大存储%s次。\n「裂穹：风痕进入疾风状态，且存储次数＞0时，每次攻击时，消耗3次裂穹，选择敌方目标中当前生命值百分比最低的1名目标造成%s当前攻击力的伤害，该伤害属于总攻技类型」"
  },
  [80532081] = {
