  [80511751] = {
    id = 80511751,
    name = "对敌方单体目标造成%s当前攻击力的伤害。"
  },
  [80521751] = {
    id = 80521751,
    name = "每次普攻，获得2层守护之志，若普攻的目标为「异刃」「猎影」时，会额外获得1层守护之志。\n守护之志：\n1、累计6层时，使距离自身最远的2名敌方目标陷入眩晕状态，持续%s秒。\n2、累计12层时，给距离自身最近的3名敌方目标附加1层%s基础攻击力的水系持续伤害效果，持续%s秒。\n3、累计18层时，对距离自身最近的3名敌方目标造成%s基础生命上限的伤害，造成伤害后立即解除自身全部守护之志层数。"
  },
  [80531751] = {
    id = 80531751,
    name = "战斗开始后，每获得1层守护之志时，同时会获得1层涌动之力。\n对距离自身最近的3名敌方目标造成%s基础生命上限的伤害，此时若涌动之力层数＞0，则每层涌动之力会造成%s基础生命上限的额外伤害，造成伤害后立即解除自身全部涌动之力层数。"
  },
  [80541751] = {
    id = 80541751,
    name = "%s提升%s。\n战技中，眩晕状态持续时间增加%s秒；持续伤害效果时间增加%s秒；累计18层时，造成的伤害倍率增加%s。"
  },
  [80541752] = {
    id = 80541752,
    name = "战技中，眩晕状态持续时间增加%s秒；持续伤害效果时间增加%s秒；累计18层时，造成的伤害倍率增加%s。"
  },
  [80561751] = {
    id = 80561751,
    name = "总攻技中，对距离自身最近的3名敌方目标造成的伤害倍率增加%s。"
  },
  [80591751] = {
    id = 80591751,
    name = "总攻阶段时，我方全体成员，攻击力提升%s，防御力提升%s，生命恢复效果提升%s。"
  },
  [80511941] = {
    id = 80511941,
    name = "对敌方单体目标造成%s当前攻击力的伤害。"
  },
  [80521941] = {
    id = 80521941,
    name = "战斗开始后，我方成员受到来自敌方伤害的%s会为「霏」提供灵炎值，灵炎值的最大存储上限为%s。\n当灵炎值达到存储上限时，消耗所有灵炎值，同时「霏」获得1朵灵炎。\n灵炎：\n1、对距离最近的敌方目标自动进行攻击，造成%s当前攻击力的伤害。\n2、每拥有1朵灵炎时，基础暴击率提升%s，基础暴击伤害提升%s；最多同时拥有3朵灵炎。\n3、若「霏」拥有的的灵炎数量等于3，且灵炎值再次达到存储上限时，会消耗所有的灵炎值，同时恢复等同于自身%s生命上限的生命值。"
  },
  [80531941] = {
    id = 80531941,
    name = "进入总攻阶段时，若「霏」拥有的灵炎数量等于3时，会消耗拥有的3朵灵炎，生成1朵魂炎。\n「魂炎：每拥有1朵魂炎时，基础攻击力提升%s，基础暴击率提升%s，基础暴击伤害提升%s，最多同时拥有10朵魂炎」\n对敌方单体目标造成%s当前攻击力的伤害，此时若魂炎的数量＞0，则每朵魂炎会使总攻技的伤害倍率增加%s。"
  },
  [80541941] = {
    id = 80541941,
    name = "%s提升%s。\n战斗开始时，灵炎的初始拥有数增加3朵。"
  },
  [80541942] = {
