  [80592131] = {
    id = 80592131,
    name = "总攻阶段时，我方全体成员，闪避率提升%s，免伤提升%s。"
  },
  [80512141] = {
    id = 80512141,
    name = "对敌方单体目标造成%s当前攻击力的伤害。\n普攻时，距离自身最近的3名敌方目标基础防御力降低%s，最大可以叠加%s层；当「朝雾」或者敌方目标死亡后，该效果会解除。"
  },
  [80522141] = {
    id = 80522141,
    name = "战斗开始时，为距离自身最近的1名我方「猎影」成员提供援护，可为其分担%s伤害；「朝雾」自身免伤提升%s，持续整场战斗。\n战斗开始时，自身获得「共振」，持续整场战斗。\n「共振：朝雾每秒损失%s基础生命上限的生命值，每通过该效果累积损失%s时，我方全体水系成员获得1层元素属性克制伤害增加%s，最大可以叠加%s层；我方全体火系、木系、光系、暗系成员获得1层元素属性克制伤害增加%s，最大可以叠加%s层；当朝雾死亡后，该效果全部解除」"
  },
  [80532141] = {
    id = 80532141,
    name = "战斗开始后，「朝雾」每通过「共振」损失%s基础生命上限的生命值时，随机对1名敌方目标造成%s当前攻击力的伤害。\n发动总攻时，若本轮总攻为奇数轮，对当前攻击力最高的4名敌方目标造成%s当前攻击力的伤害，同时自身免伤提升%s，持续%s秒。\n发动总攻时，若本轮总攻为偶数轮，对当前防御力最高的4名敌方目标造成%s当前攻击力的伤害，并自身恢复等同于「朝雾」%s生命上限的生命值。"
  },
  [80542141] = {
    id = 80542141,
    name = "%s提升%s。\n战技中，被援护的「猎影」成员基础攻速提升%s，基础攻击力提升%s；当朝雾死亡后，该效果会解除。"
  },
  [80542142] = {
    id = 80542142,
    name = "战技中，被援护的「猎影」成员基础攻速提升%s，基础攻击力提升%s；当朝雾死亡后，该效果会解除。"
  },
  [80562141] = {
    id = 80562141,
    name = "战斗开始时，施放「冻结领域」，持续整场战斗。\n冻结领域效果：\n1、敌方全体成员，基础移速降低%s，基础攻速降低%s。\n2、进入总攻阶段时，随机给3名敌方目标附加3层%s基础攻击力的水系持续伤害效果，持续%s秒；同时上述3名敌方目标中随机选择1名目标使其陷入冰冻状态，持续%s秒。"
  },
  [80592141] = {
    id = 80592141,
    name = "总攻阶段时，我方全体成员，暴击率提升%s，总攻技伤害提升%s。"
  },
  [80512151] = {
    id = 80512151,
    name = "对距离自身最近的2名敌方单体目标造成%s当前防御力的伤害。\n战斗开始后，「鎺」普攻造成伤害后的目标会强行将其普攻目标变为「鎺」。"
  },
  [80522151] = {
    id = 80522151,
    name = "「鎺」每次普攻时会存储1次鞘内光，鞘内光的最大存储上限为60；鞘内光的存储量达到不同数量时，「鎺」会转变为不同的形态，分别为「鎺现」「鸣音」「绽放」，持续整场战斗。\n「鎺现」：鞘内光存储达到5时，进入Ⅰ形态；每次进入总攻阶段时，我方全体成员，获得以「鎺」%s基础防御力的反伤效果；进入Ⅰ形态后，每隔10秒，对距离自身最近的1名敌方目标造成%s当前防御力的伤害。\n「鸣音」：鞘内光存储达到30时，进入Ⅱ形态；自身总攻技冷却时间变为45秒；普攻时将自身当前生命值的5%%转化为护盾，转换率为%s，护盾值可以叠加；进入Ⅱ形态后，对距离自身最近敌方目标攻击数量从1名变为2名。\n「绽放」：鞘内光存储达到60时，进入Ⅲ形态；自身总攻技冷却时间变为20秒；所有类型造成的伤害会无视敌方目标%s当前防御力；进入Ⅲ形态后，对距离自身最近敌方目标攻击数量从2名变为3名。\n上述三个形态中的效果不会因形态转变而消失。"
  },
  [80532151] = {
    id = 80532151,
    name = "战斗开始后，「鎺」每次普攻时会获得1层镜映效果，最大可以叠加%s层。\n「镜映：自身基础暴击伤害提升%s」\n对距离自身最近的4名敌方目标造成%s当前防御力的伤害；施放总攻技时，自身每1层镜映会额外触发%s当前防御力的伤害。\n总攻技施放结束后，立即解除自身全部镜映。"
  },
  [80542151] = {
    id = 80542151,
    name = "%s提升%s。\n战斗开始后，「鎺」每累积损失%s生命上限的生命值时：\n1、自身攻速提升%s，最大可以叠加%s层。\n2、所有类型造成的伤害，获得无视敌方目标%s的当前防御力效果，最大可以叠加%s层。"
  },
  [80542152] = {
    id = 80542152,
    name = "战斗开始后，「鎺」每累积损失%s生命上限的生命值时：\n1、自身攻速提升%s，最大可以叠加%s层。\n2、所有类型造成的伤害，获得无视敌方目标%s的当前防御力效果，最大可以叠加%s层。"
  },
  [80562151] = {
    id = 80562151,
    name = "战技中，「鎺」每存储1次鞘内光时，自身获得1层元素属性克制伤害提升%s，最大可以叠加%s层。"
  },
  [80592151] = {
    id = 80592151,
    name = "总攻阶段时，我方全体「坚甲」成员，免伤提升%s；我方全体成员，攻速提升%s。"
  },
  [80511741] = {
    id = 80511741,
    name = "对敌方单体目标造成%s当前攻击力的伤害，同时自身附加「洞悉」效果，最大可以叠加%s层。\n「洞悉：普攻时，每层可以触发%s当前攻击力的额外伤害。」\n每次普攻时，「司礼者」基础攻速提升%s，最大可以叠加%s层，持续整场战斗。"
  },
  [80521741] = {
    id = 80521741,
    name = "「洞悉」达到%s层后，消耗全部层数，对敌方单体目标造成%s当前攻击力的伤害，该伤害属于普攻类型，同时受到攻击的敌方目标基础防御力降低%s，持续%s秒。\n每累计消耗层数达到%s层后，「司礼者」和距离其最近的1名我方「异刃」成员恢复等同于「司礼者」%s当前攻击力的生命值，持续%s秒。"
  },
  [80531741] = {
    id = 80531741,
    name = "发动总攻时，自动施放进入「全能」状态，持续整个总攻阶段。\n全能效果：\n1、普攻变为2连射（总倍率不变）。\n2、普攻造成伤害时，触发溅射效果，对距离普攻目标最近的2名敌方目标造成%s当前攻击力的伤害，该伤害属于普攻类型。\n3、战技造成伤害时，触发溅射效果，对距离普攻目标最近的2名敌方目标造成%s当前攻击力的伤害，该伤害属于普攻类型。\n4、自身获得无视敌方目标%s当前防御力效果。\n「全能状态下的攻击依然为普攻，普攻的形态会发生变化」\n「自动施放：无法手动选择，且不会占用该职业选择名额，无法设置施放顺序，每次总攻技位于该职业最后一名进行施放」"
  },
  [80541741] = {
    id = 80541741,
    name = "%s提升%s。\n普攻中，洞悉的伤害倍率增加%s。\n战斗开始时，自身基础攻速提升%s，持续%s秒。"
  },
  [80541742] = {
    id = 80541742,
    name = "普攻中，洞悉的伤害倍率增加%s。"
  },
  [80561741] = {
