    name = "总攻阶段时，我方全体成员，普攻伤害提升%s，暴击伤害提升%s。"
  },
  [80512221] = {
    id = 80512221,
    name = "对敌方单体目标造成%s当前攻击力的伤害。\n每次普攻时，自身获得10点律火。"
  },
  [80522221] = {
    id = 80522221,
    name = "战斗开始后，当「迷迭香」积累的律火大于等于100时，消耗当前全部律火，「迷迭香」进入妄境状态，持续%s秒。\n妄境：\n1、该状态下「迷迭香」不再进行普攻，同时无法获得律火，该状态下「迷迭香」免疫控制效果。\n2、每%s秒施放1次流星落，每次流星落随机选择一名敌方目标，造成%s当前攻击力的伤害。\n3、每次流星落有%s的概率使目标陷入%s秒的时停状态。"
  },
  [80532221] = {
    id = 80532221,
    name = "发动总攻时，「迷迭香」自动施放总攻技，为自身附加瞬燃效果，持续整个总攻阶段。\n瞬燃：\n1、基础攻击力提升%s。\n2、基础暴击伤害提升%s。\n3、流星落施放间隔减少0.1秒。\n4、流星落触发时停时，时停时间增加0.2秒。\n5、流星落命中目标时，额外造成%s当前攻击力的伤害，该伤害属于战技类型。\n6、若自身施放总攻技时处于妄境状态，则本次妄境状态时长会延续到本次总攻阶段结束。"
  },
  [80542221] = {
    id = 80542221,
    name = "%s提升%s。\n战斗开始时，自身普攻距离增加%s。\n战斗开始时，直接进入妄境状态。"
  },
  [80542222] = {
    id = 80542222,
    name = "战斗开始时，自身普攻距离增加%s。\n战斗开始时，直接进入妄境状态。"
  },
  [80562221] = {
    id = 80562221,
    name = "战技中，流星落的伤害倍率增加%s。"
  },
  [80592221] = {
    id = 80592221,
    name = "总攻阶段时，我方全体成员，战技伤害提升%s。"
  },
  [80512231] = {
