  },
  [80732124] = {
    id = 80732124,
    name = "当自身生命低于20%%时，对敌方全体目标释放熔岩喷射，并使受到攻击的敌方目标附加持续伤害效果至战斗结束，每秒损失固定当前最大生命的生命值。"
  },
  [80732131] = {
    id = 80732131,
    name = "对距离最远的敌方单体目标造成伤害，并使受到攻击的敌方目标附加持续伤害效果。"
