  [80732132] = {
    id = 80732132,
    name = "对敌方单体目标造成伤害，概率触发额外伤害。"
  },
  [80732133] = {
    id = 80732133,
    name = "每4次普攻时，并使受到攻击的敌方目标附加点燃效果。\n「点燃：点燃的赤焰会在距离较近角色身上跳跃，且每次跳跃伤害都会翻倍。当跳跃目标距离超过200，则赤焰失效，终止跳转。」"
  },
  [80732140] = {
    id = 80732140,
    name = "对敌方单体目标造成伤害，并弹射1+当前「急速」层数的次数。"
  },
  [80732141] = {
    id = 80732141,
    name = "对敌方单体目标造成伤害，并弹射1+当前「急速」层数的次数，给受到攻击的敌方目标附加火系持续伤害效果，持续%s秒。"
  },
  [80732142] = {
