  [80739522] = {
    id = 80739522,
    name = "对敌方目标造成伤害，并给受到攻击的目标附加木系持续伤害效果，持续整场战斗，可以叠加。"
  },
  [80739523] = {
    id = 80739523,
    name = "自身获得反伤效果，持续15秒。"
  },
  [80739524] = {
    id = 80739524,
    name = "为我方战场中存活的召唤魔物提升攻击力和攻速，持续整场战斗，可以叠加。"
  },
  [80739525] = {
    id = 80739525,
    name = "自身停止攻击，进入防御状态，自身获得韧性值，持续10秒。\n自身受到攻击时优先损失韧性值，若在10秒内韧性值未被击破，则会对4名敌方目标造成伤害，优先选择不同职业的目标，韧性值剩余越多伤害越高。"
  },
  [80739526] = {
    id = 80739526,
    name = "战斗开始后，每2秒召唤一只魔物，战场中最大可以存在10只召唤的魔物。\n战场中，每存活一只召唤的魔物，我方全体成员（不含召唤的魔物）获得10%%的免伤效果；敌方每击杀一只召唤的魔物，我方全体成员（不含召唤的魔物）基础防御力降低1%%，持续整场战斗。"
  },
  [80739531] = {
    id = 80739531,
    name = "对敌方单体目标造成伤害。"
  },
  [80739532] = {
    id = 80739532,
    name = "对敌方单体目标造成伤害。"
  },
  [80739533] = {
    id = 80739533,
    name = "对以敌方目标为中心且半径为300的圆形范围内的敌方全体目标造成伤害。"
  },
  [80739534] = {
    id = 80739534,
    name = "给敌方全体目标附加降低50%%的生命恢复效果，持续30秒。"
  },
  [80739535] = {
    id = 80739535,
    name = "除自身外的我方其余成员陷入眩晕状态，同时敌方全体成员生命值恢复至100%%；3秒后，敌方全体成员中当前生命为100%%的成员，立即损失50%%最大生命值，之后对敌方全体目标造成伤害。"
  },
  [80739536] = {
    id = 80739536,
    name = "自身施放「本源奥义」后，解除我方全体成员的控制状态，同时给我方全体成员，基础攻击力提升50%%，基础防御力降低50%%，持续20秒；其中基础防御力降低效果不可被解除。"
  },
  [80750001] = {
    id = 80750001,
    name = "普通形态"
  },
  [80750002] = {
    id = 80750002,
    name = "狂化形态"
  },
  [85061001] = {
    id = 85061001,
    name = "都准备好了吗，出发。"
  },
  [85071001] = {
    id = 85071001,
    name = "接招吧。"
  },
  [85071002] = {id = 85071002, name = "嘿。"},
  [85071003] = {id = 85071003, name = "呀啊！"},
  [85081001] = {
    id = 85081001,
    name = "饶不了你。"
  },
  [85091001] = {
    id = 85091001,
    name = "见识我的意志吧！"
  },
  [85131001] = {
    id = 85131001,
    name = "大家的表现都很不错，休息一下再接着赶路吧。"
  },
  [85141001] = {
    id = 85141001,
    name = "伤员先撤，还能战斗的人，和我一起断后。"
  },
  [85069991] = {
    id = 85069991,
    name = "好，定然不负所托。"
  },
  [85079991] = {
    id = 85079991,
    name = "趁现在。"
  },
  [85079992] = {id = 85079992, name = "喝！"},
  [85079993] = {id = 85079993, name = "哈！"},
  [85089991] = {
    id = 85089991,
    name = "我们上！"
  },
  [85099991] = {
    id = 85099991,
    name = "趁现在，给它最后一击！"
  },
  [85139991] = {
    id = 85139991,
    name = "干得不错。"
  },
  [85149991] = {
    id = 85149991,
    name = "大家都别落下了，保存体力，跟我走。"
  },
  [85011011] = {
    id = 85011011,
    name = "你这家伙，以前怎么说都不为所动，现在竟然主动找我，呵呵~我能拒绝么？开玩笑的，放心，我会陪你一起。"
  },
  [85021011] = {
    id = 85021011,
    name = "真是悠闲啊，我的队长大人~又去哪逍遥快活了？下次叫上我啊，一个人玩可没什么意思~"
  },
  [85031011] = {
    id = 85031011,
    name = "这深渊中虽说少了各种舞会，但每天和魔物斗智斗勇倒也不会无聊，只是在深渊呆久了，不知道会不会有哪家的小姐在想我......"
  },
  [85031012] = {
    id = 85031012,
    name = "当初我们说好要一起去深渊探险，可是我却违背了约定。如今我们以这样的方式实现，真是命运无常......"
  },
  [85041011] = {
    id = 85041011,
    name = "真是令人愉悦的感觉，连容貌也似乎英俊了几分。"
  },
  [85041012] = {
    id = 85041012,
    name = "这样的体验可以成为不错的谈资吧，呵呵呵，等我回去一定要和美丽的小姐们好好聊聊。"
  },
  [85041013] = {
    id = 85041013,
    name = "虽然我对力量提升的原理有些兴趣，但我更想先找个地方试试现在的实力。"
  },
  [85051011] = {
    id = 85051011,
    name = "对于深渊，我了解的并不多，不过，我只要考虑如何战斗就可以了吧？"
  },
  [85051012] = {
    id = 85051012,
    name = "不管怎样的决定我都没问题。嗯，这大概就是一名优秀新人探险者的自我修养了吧。"
  },
  [85051013] = {
    id = 85051013,
    name = "险恶的深渊、凶猛的魔物、复杂的人际......哈啊，最近操了不少心，额头上似乎都有皱纹了。"
  },
  [85051014] = {
    id = 85051014,
    name = "团队作战中最重要的是信任，没有足够的信任每个人都很难发挥出自己的全力，有些令人头疼啊~"
  },
  [85051015] = {
    id = 85051015,
    name = "没人可以改变过去，以“过去”的经验指引我们的未来，才是我们现在所能做到的事。"
  },
  [85061011] = {
    id = 85061011,
    name = "也是时候出去活动一下了。"
  },
  [85071011] = {id = 85071011, name = "喝！"},
  [85071012] = {id = 85071012, name = "咿呃！"},
  [85071013] = {id = 85071013, name = "咿呀！"},
  [85081011] = {
    id = 85081011,
    name = "看得到么。"
  },
  [85081012] = {
    id = 85081012,
    name = "有破绽——"
  },
  [85091011] = {
    id = 85091011,
    name = "已经没有逃跑的机会了。"
  },
  [85091012] = {
    id = 85091012,
    name = "别担心，马上就结束。"
  },
  [85101011] = {id = 85101011, name = "唔。"},
  [85101012] = {id = 85101012, name = "呃。"},
  [85101013] = {id = 85101013, name = "呜啊~"},
  [85111011] = {
    id = 85111011,
    name = "太受关注了么，真是头疼啊~"
  },
  [85121011] = {
    id = 85121011,
    name = "轮到我了么......"
  },
  [85131011] = {
    id = 85131011,
    name = "还算不错，差不多刚热身的程度，呵呵呵~"
  },
  [85141011] = {
    id = 85141011,
    name = "竟然失手了......哼。"
  },
  [85151011] = {
    id = 85151011,
    name = "今年还是老规矩？呵呵，虽然深渊中条件有限，但我在附近圈落发现了一个不错的店，就去那庆祝吧。"
  },
  [85161011] = {
    id = 85161011,
    name = "大家都去准备新年物资了，打算今天好好庆祝一下。我？呵呵，我这不是在此恭候我们的队长大人吗？"
  },
  [85171011] = {
    id = 85171011,
    name = "以前每到这种节日，我收到的礼物足以把院子填满，可是现在......唉，如果这深渊中的魔物也懂得欣赏本公子的魅力就好了......"
  },
  [85181011] = {
    id = 85181011,
    name = "圈落那边好像在举办庆典，一起去看看？——如果可以我当然希望和美丽的小姐一起，这不是只有我们俩么，要不我去找身衣服给你换上？"
  },
  [85191011] = {
    id = 85191011,
    name = "这种日子，我家里的邮箱估计已经被各种邀请函给塞满了。还是我够义气吧，推掉了无数美丽小姐的邀约来陪你。"
  },
  [85201011] = {id = 85201011, name = "Elpis"},
  [85201012] = {
    id = 85201012,
    name = "Elpis（我没念错吧？）"
  },
  [85011021] = {
    id = 85011021,
    name = "我是露露，一名正在追寻深渊传说的探险者！如果有什么有趣的事，一定要告诉我哦！"
  },
  [85021021] = {
    id = 85021021,
    name = "我把最近听过的故事都整理好了，一起去探访这些故事的线索吧。"
  },
  [85031021] = {
    id = 85031021,
    name = "我知道深渊并非只有传奇精彩的故事，在我刚到深渊不久我就已经知道了。可是，正因为有那些悲伤的事，美好和幸福的传说才更加令人向往。"
  },
  [85031022] = {
    id = 85031022,
    name = "我第一次踏上玛蒙之地时，就被港口的繁华惊呆了。我从没想过一个地方能聚集那么多人，拥有那么多建筑......相比之下，我的故乡完全就是小乡村嘛。"
  },
  [85041021] = {
    id = 85041021,
    name = "虽然有想过探险者提升实力会付出一些代价，但这代价是不是有点高了？"
  },
  [85041022] = {
    id = 85041022,
    name = "露露的努力得到认可了吗？呵呵~我会继续努力，争取得到更多的提升。"
  },
  [85041023] = {
    id = 85041023,
    name = "我达到这种程度，所花费的代价就已经超出了想象，那些传说中的人物，不管怎么想，肯定都算得上大富豪吧？！"
  },
  [85051021] = {
    id = 85051021,
    name = "从小我就对深渊充满了向往，渴望有朝一日自己也能和各种话剧的主人公一样，在深渊创造自己的故事。"
  },
  [85051022] = {
    id = 85051022,
    name = "对地面上的人来说，深渊是个拥有无数传说的地方，可是实际到了这里才会发现一切并没有那么容易。"
  },
  [85051023] = {
    id = 85051023,
    name = "提升实力需要花费不少代价，每天还要面对各种危险......呼~探险者的生活根本没有故事中的那么悠闲浪漫。"
  },
  [85051024] = {
    id = 85051024,
    name = "我竟然也能有这样的经历！我一直以为只有故事的主人公才能遇到这样的事。"
  },
  [85051025] = {
    id = 85051025,
    name = "比起那些虚无缥缈的梦想，对现在的我而言，能够和大家一起探险，就已经很满足了。"
  },
  [85061021] = {
    id = 85061021,
    name = "来啦来啦~"
  },
  [85071021] = {id = 85071021, name = "喝咿！"},
  [85071022] = {id = 85071022, name = "呀啊。"},
  [85071023] = {id = 85071023, name = "豁！"},
  [85081021] = {
    id = 85081021,
    name = "嘿嘿~看招！"
  },
  [85081022] = {
    id = 85081022,
    name = "一下就好。"
  },
  [85091021] = {
    id = 85091021,
    name = "这一招，能承受住吗~"
  },
  [85091022] = {
    id = 85091022,
    name = "看好了~不许逃哦！"
  },
  [85101021] = {id = 85101021, name = "哇啊~"},
  [85101022] = {id = 85101022, name = "欸！"},
  [85101023] = {id = 85101023, name = "呜欸。"},
  [85111021] = {
    id = 85111021,
    name = "太活跃果然容易被盯上。"
  },
  [85121021] = {
    id = 85121021,
    name = "故事里，都是......骗人的......"
  },
  [85131021] = {
    id = 85131021,
    name = "耶！真是完美的胜利，就和故事里那些主人公一样！"
  },
  [85141021] = {
    id = 85141021,
    name = "故事里的主人公也会遇到挫折，我们还不能放弃。"
  },
  [85151021] = {
    id = 85151021,
    name = "唔...想起来今天是什么日子了？诶？！你不会忘记了吧？今天可是你的生日！我已经准备好蛋糕了，当然还有话剧，呵呵呵，请期待吧！"
  },
  [85161021] = {
    id = 85161021,
    name = "在我的家乡，新年是全年里最热闹的一天。在这天，大家不管有多忙，都会放下手中的事聚集到一起表演话剧和歌舞，庆祝新年。"
  },
  [85171021] = {
    id = 85171021,
    name = "啊，已经这个日子了吗！唔，来不及做点心了......圈落里今天应该会非常热闹，一起去逛逛怎么样，就像“约会”那样！你该不会害羞了吧？呵呵呵~"
  },
  [85181021] = {
    id = 85181021,
    name = "哇哇，圈落里竟然那么热闹，这可是在深渊里诶，竟然还有那么多人！在我的家乡可完全看不到这么热闹的场面，我们快去和大家一起庆祝吧。"
  },
  [85191021] = {
    id = 85191021,
    name = "在节日交换礼物的习俗，我还是到了深渊才知道——欸？你也是？真的吗？呵呵，那我们今天就按我们喜欢的方式来庆祝吧！"
  },
  [85011031] = {
    id = 85011031,
    name = "探险者奥菲利亚，为了追寻深渊的秘密而来。"
  },
  [85021031] = {
    id = 85021031,
    name = "虽然我很少有机会泡茶，但对这方面的手艺还挺自信的，要试试吗？"
  },
  [85031031] = {
    id = 85031031,
    name = "我曾目睹那些盲目崇拜深渊之人所造成的惨状，为了不让那样的悲剧重演，我会努力将深渊的秘密呈现在世人眼前。"
  },
  [85031032] = {
    id = 85031032,
    name = "对于未知的存在，世人总是充满敬畏。这并没有错，错的是利用这份敬畏之心，行不轨之事的人。"
  },
  [85041031] = {
    id = 85041031,
    name = "宽容是一种强大而仁慈的力量，足以为混乱的深渊带来救赎。"
  },
  [85041032] = {
    id = 85041032,
    name = "作为领主的女儿，所拥有的并非只有荣耀，还应肩负为领地人民奉献一切的责任。"
  },
  [85041033] = {
    id = 85041033,
    name = "我现在和大家一样，只是一名探险者，一名愿意为了探索深渊付出全力的探险者。"
  },
  [85051031] = {
    id = 85051031,
    name = "我不想再有人经历我所经历过的灾难，为此不管需要付出多少努力我也愿意。"
  },
  [85051032] = {
    id = 85051032,
    name = "我并不喜欢战斗，可是为了故乡和人民，我已经做好觉悟！"
  },
  [85051033] = {
    id = 85051033,
    name = "故乡的灾难虽然已暂时平息，但如果不解开深渊的秘密，那些惨痛的过去，总有一天会卷土重来。"
  },
  [85051034] = {
    id = 85051034,
    name = "为了能拥有从容面对各种灾难的实力，不管会有多么艰苦，我也绝不会放弃。"
  },
  [85051035] = {
    id = 85051035,
    name = "故乡、人民......肩负着许多事物前行确实会有些累，不过正因为有那么多期待，前进的每一步才更有意义，不是吗。"
  },
  [85061031] = {
    id = 85061031,
    name = "由我来协助大家。"
  },
  [85071031] = {id = 85071031, name = "嘿伊！"},
  [85071032] = {id = 85071032, name = "咿呀！"},
  [85071033] = {id = 85071033, name = "呀啊。"},
  [85081031] = {
    id = 85081031,
    name = "尽在掌握。"
  },
  [85081032] = {
    id = 85081032,
    name = "交给我吧。"
  },
  [85091031] = {
    id = 85091031,
    name = "请见证我的决心和意志！"
  },
  [85091032] = {
    id = 85091032,
    name = "我们没有停下的理由。"
  },
  [85101031] = {id = 85101031, name = "呃啊。"},
  [85101032] = {id = 85101032, name = "呜啊~"},
  [85101033] = {id = 85101033, name = "啊~"},
  [85111031] = {
    id = 85111031,
    name = "只是这种程度......"
  },
  [85121031] = {
    id = 85121031,
    name = "......故乡......还在等我......"
  },
  [85131031] = {
    id = 85131031,
    name = "只要有不放弃，无论怎样的阻碍都无法阻止我们前行。"
  },
  [85141031] = {
    id = 85141031,
    name = "前进的路上总会有许多风雨，一时的失利并不算什么。"
  },
  [85151031] = {
    id = 85151031,
    name = "在我们那儿，生日时的烤馅饼是必不可少的，来尝尝吧。馅料吗？嗯......忘记具体数量了，呵呵~因为我们认为馅料越多祝福便越多，所以这周围的各种食材我都添加了一些。"
  },
  [85161031] = {
    id = 85161031,
    name = "新年快乐，来试试这杯特制的新年红茶吧，当然，茶点就没办法了。唔~真想念故乡的美味茶点啊。"
  },
  [85171031] = {
    id = 85171031,
    name = "试试这份点心么？味道应该不会差，这是我小时候向家里的厨师学习的。一直在想要怎样表达谢意，果然还是美味的点心最合适吧。"
  },
  [85181031] = {
    id = 85181031,
    name = "看到庆典上大家所展露的笑容，我便更加确信了自己努力的意义。为了守护这份美好和幸福，我会拼尽全力！"
  },
  [85191031] = {
    id = 85191031,
    name = "唔......礼物的数量似乎还不够，我马上再去采购一些。这种重要的日子，我不想让任何人留下遗憾。"
  },
  [85011041] = {
    id = 85011041,
    name = "小莎虽然经验丰富，值得信赖，但也不太擅长那些很危险或者太麻烦的事~如果遇到了可以尽管拜托别人，小莎不会介意哒~"
  },
  [85021041] = {
    id = 85021041,
    name = "这么舒服的天气，再多休息一会儿也没关系吧？肯定不会耽误进度的，毕竟有“厉害”的蒂娜娜，她会努力的。"
  },
  [85031041] = {
    id = 85031041,
    name = "虽然还没找到什么宝贝，但这趟旅途还是蛮有意思的，要是拉茨也在就好了......也不知道她最近怎么样，给她留个消息吧。"
  },
  [85031042] = {
    id = 85031042,
    name = "闲下来好无聊，找谁玩呢......凶巴巴的蒂娜肯定在修行，菲尼斯么......虽然看上去笑眯眯的，但总感觉会被吃的连骨头都不剩，还是不要。算了，去找安妮斯吧，安妮斯——"
  },
  [85041041] = {
    id = 85041041,
    name = "一名优秀的探险者果然不管怎么低调，都一定会发光的，嘻嘻。"
  },
  [85041042] = {
    id = 85041042,
    name = "如果提升实力是为了对付更加凶猛的敌人，小莎不介意把这样的机会让给别人哦~"
  },
  [85041043] = {
    id = 85041043,
    name = "优秀的人固然有义务承当更多事务，但小莎觉得引导普通人去做些特别的事，也是优秀者的责任。"
  },
  [85051041] = {
    id = 85051041,
    name = "就实力而言，小莎还是很自信的，不管是战斗还是逃跑，都没问题~"
  },
  [85051042] = {
    id = 85051042,
    name = "有些凶巴巴的家伙，小莎并不怕她，只、只是不想和她一般见识罢了。"
  },
  [85051043] = {
    id = 85051043,
    name = "在深渊中行动，最重要的不是力量，而是脑子，一味追求力量的人只是莽夫而已。"
  },
  [85051044] = {
    id = 85051044,
    name = "选择比努力更重要，所以小莎的每一个决定都是最正确的选择！嗯，也许有一两次失误？大概~"
  },
  [85051045] = {
    id = 85051045,
    name = "小莎的生活很简单，休息、吃饭、闯祸——啊！如果是可爱的小莎，就算闯祸也是可以被原谅的吧？嘿嘿~"
  },
  [85061041] = {
    id = 85061041,
    name = "诶~又要工作了吗？"
  },
  [85071041] = {id = 85071041, name = "哈~"},
  [85071042] = {id = 85071042, name = "呀~"},
  [85071043] = {id = 85071043, name = "嗖~"},
  [85081041] = {
    id = 85081041,
    name = "谁也别想逃。"
  },
  [85081042] = {
    id = 85081042,
    name = "乖乖投降吧~"
  },
  [85091041] = {
    id = 85091041,
    name = "差不多该结束了。"
  },
  [85091042] = {
    id = 85091042,
    name = "这一次会正中红心！"
  },
  [85101041] = {id = 85101041, name = "呀啊！"},
  [85101042] = {id = 85101042, name = "呜呃。"},
  [85101043] = {id = 85101043, name = "呃啊。"},
  [85111041] = {
    id = 85111041,
    name = "可恶，竟然追着小莎不放。"
  },
  [85121041] = {
    id = 85121041,
    name = "说好了一起探险......对不起......"
  },
  [85131041] = {
    id = 85131041,
    name = "小莎亲自出手，胜利还不是轻轻松松~"
  },
  [85141041] = {
    id = 85141041,
    name = "可、可恶！竟然这么狡猾，大家快撤！"
  },
  [85151041] = {
    id = 85151041,
    name = "生日得好好庆祝才行，小莎上一次生日，是和拉茨在港口的一间酒馆中度过的，当时还遇到了“请客”的热心探险者呢~"
  },
  [85161041] = {
    id = 85161041,
    name = "新年也没有什么特别的不同，无非就是把去年没完成的事情丢到了今年而已，这种天气，还是更适合好好休息。"
  },
  [85171041] = {
    id = 85171041,
    name = "队长，猜猜我准备了什么~——锵锵，没错，正是甜甜的点心，送给你！ 呵呵，谢谢队长长期以来的关照，这可是专门为队长准备的，快尝尝吧。"
  },
  [85181041] = {
    id = 85181041,
    name = "这样热闹的日子，休息和探险都太浪费时间了，和大家一起庆祝、巡游，才是今天最该做的事。"
  },
  [85191041] = {
    id = 85191041,
    name = "不管怎样的节日，和重要的人一起度过才会更有意义，大家一起去庆祝吧！（拉茨在做什么呢，如果，大家能在一起就好了）"
  },
  [85011051] = {
    id = 85011051,
    name = "圣歌所属、慈悲者，应邀而来。愿我们的慈悲，可以成为堕落之人最后的救赎。"
  },
  [85021051] = {
    id = 85021051,
    name = "救赎堕落之人是我的使命，但探险队的事务我也不会懈怠，今天也请让我和您一起努力~"
  },
  [85031051] = {
    id = 85031051,
    name = "圣歌的理念是为深渊带来更多爱与正义，但具体要怎样做并没有明确说明，所以只要符合这个理念的行动我们都可以自主决定。"
  },
  [85031052] = {
    id = 85031052,
    name = "祈祷是我每天都会做的事，不过我祈祷的对象并非遥不可及的神明，而是自己的内心。"
  },
  [85041051] = {
    id = 85041051,
    name = "真正的慈悲是守护弱者、惩戒罪恶，绝非一味的纵容和忍让。"
  },
  [85041052] = {
    id = 85041052,
    name = "如果只有战斗才能贯彻我们的慈悲，那么、我会竭尽所有的力量去战斗！"
  },
  [85041053] = {
    id = 85041053,
    name = "无论是这个世界的未来还是我们自己的未来，都应该由我们自己决定，也只能由我们自己决定！"
  },
  [85051051] = {
    id = 85051051,
    name = "对那些濒临堕落之人，我会全力引导他们，真正能拯救他们的人只有他们自己，但如果已无可救药，我会毫不犹豫的为他们送上终结。"
  },
  [85051052] = {
    id = 85051052,
    name = "圣歌的成员们都在为了各自的理念和职责行动着，我也绝不能停下，必须更加努力才能无愧于大家的信任。"
  },
  [85051053] = {
    id = 85051053,
    name = "我出生于深渊，母亲费了很大的代价才将我带回地面，我本不应再回到这里......可是，我想要传承母亲的意志，必须回到这里。"
  },
  [85051054] = {
    id = 85051054,
    name = "那些罪恶之人只要诚心忏悔，我都会给他们改过的机会......但他们如果继续作恶、不思悔改，那么、我将不再留情。"
  },
  [85051055] = {
    id = 85051055,
    name = "这个混沌的世界中，武力只能带来短暂而脆弱的安宁，只有人们内心深处的善良和希望，才能为这个世界带来真正的救赎。"
  },
  [85061051] = {
    id = 85061051,
    name = "请放心，我已做好准备。"
  },
  [85071051] = {id = 85071051, name = "嘿！"},
  [85071052] = {id = 85071052, name = "呀！"},
  [85071053] = {id = 85071053, name = "哈！"},
  [85081051] = {
    id = 85081051,
    name = "忏悔吧！"
  },
  [85081052] = {
    id = 85081052,
    name = "不可饶恕。"
  },
  [85091051] = {
    id = 85091051,
    name = "我们的意志、不可阻挡！"
  },
  [85091052] = {
    id = 85091052,
    name = "绝不放过任何罪恶。"
  },
  [85101051] = {id = 85101051, name = "呃啊。"},
  [85101052] = {id = 85101052, name = "呃。"},
  [85101053] = {id = 85101053, name = "呀啊。"},
  [85111051] = {
    id = 85111051,
    name = "暴力、不会让我妥协。"
  },
  [85121051] = {
    id = 85121051,
    name = "如果、能为大家争取一些时间......"
  },
  [85131051] = {
    id = 85131051,
    name = "心怀慈悲之心，才能无往不胜。"
  },
  [85141051] = {
    id = 85141051,
    name = "我的力量还不足以贯彻我们的意志，必须变得更加强大才行。"
  },
  [85151051] = {
    id = 85151051,
    name = "生日是一个人最值得纪念的日子，不管什么时候也绝不能敷衍。所以我和大家准备了一个庆祝会，希望您喜欢~"
  },
  [85161051] = {
    id = 85161051,
    name = "新年快乐~请问、您今天有空吗？我准备去参加圣歌的新年聚会，如果您有时间，我想邀请您和我一起......可以？谢、谢谢！"
  },
  [85171051] = {
    id = 85171051,
    name = "我自己做的一些点心，请问可以收下吗？那个、非常感谢您对我的支持和关照，我知道这些远不足以表达对您的谢意，今后我会更加努力回应您的期待。"
  },
  [85181051] = {
    id = 85181051,
    name = "圈落的庆典已经开始了，一起去逛逛吗？你的表情似乎在说这很奇怪？呵呵，对我们而言，热闹的庆典是宣扬圣歌的好机会，所以只要有时间都不会错过。"
  },
  [85191051] = {
    id = 85191051,
    name = "每到这个节日，我们便会将之前在各地收到的捐赠物品整理好，将它们送到最需要的人手中。对圣歌而言，这是一种传递爱与善良的方式，也是我们纪念这个节日的方式。"
  },
  [85011061] = {
    id = 85011061,
    name = "我是诺玛，一名物种研究员，当然，也是探险者，如果有魔物相关的事情，或许我可以帮上忙。"
  },
  [85021061] = {
    id = 85021061,
    name = "抱歉队长，请稍等一下，我正在撰写一份魔物解剖报告，马上就能完成。"
  },
  [85031061] = {
    id = 85031061,
    name = "深渊中的物种和地面完全不同，几乎每一种都有自己独特的构造，如果不亲自解剖、取证，会错过很多发现。"
  },
  [85031062] = {
    id = 85031062,
    name = "现有的许多魔物研究记录都存在缺失、或者靠主观推测得出结论的情况，这给研究者带来了许多麻烦，所以编撰一本没有错误的物种记录很有必要。"
  },
  [85041061] = {
    id = 85041061,
    name = "变强的感觉......不坏，但会有一种想要解剖查看原理的冲动。"
  },
  [85041062] = {
    id = 85041062,
    name = "请不用害怕，我的解剖刀是为魔物准备的，当然，如果面对敌人，它们也不会犹豫。"
  },
  [85041063] = {
    id = 85041063,
    name = "“解剖者”吗......对探险者而言，能拥有这样的称呼似乎也很不错。"
  },
  [85051061] = {
    id = 85051061,
    name = "对研究者而言，能够获得一手素材非常重要，这也是我成为探险者的原因。"
  },
  [85051062] = {
    id = 85051062,
    name = "重复做一件事看起来会很枯燥，可是，当你能感受到其中的微妙变化后，会非常享受。"
  },
  [85051063] = {
    id = 85051063,
    name = "解剖只是探索世界的一种手段，就和使用其他工具一样，并没有什么特别。"
  },
  [85051064] = {
    id = 85051064,
    name = "魔物的声音和形象都可能具用欺骗性，唯独它们的身体绝不会撒谎，它们会清楚的告诉我有关魔物的一切......"
  },
  [85051065] = {
    id = 85051065,
    name = "距离一份完整的物种记录还很遥远，但只要努力去做，终有一天一定可以实现。"
  },
  [85061061] = {
    id = 85061061,
    name = "这次会有新发现么。"
  },
  [85071061] = {id = 85071061, name = "喝咿！"},
  [85071062] = {id = 85071062, name = "呀啊！"},
  [85071063] = {id = 85071063, name = "哈！"},
  [85081061] = {
    id = 85081061,
    name = "放弃吧。"
  },
  [85081062] = {
    id = 85081062,
    name = "弱点暴露了——"
  },
  [85091061] = {
    id = 85091061,
    name = "感谢您为研究做出的贡献，再见。"
  },
  [85091062] = {
    id = 85091062,
    name = "抱歉，这一切，都是为了研究！"
  },
  [85101061] = {id = 85101061, name = "呃——"},
  [85101062] = {id = 85101062, name = "啊。"},
  [85101063] = {id = 85101063, name = "呃啊。"},
  [85111061] = {
    id = 85111061,
    name = "我必须要......坚持住才行。"
  },
  [85121061] = {
    id = 85121061,
    name = "为研究付出一切，是研究者的宿命。"
  },
  [85131061] = {
    id = 85131061,
    name = "呼~多亏了大家，素材保存完好。"
  },
  [85141061] = {
    id = 85141061,
    name = "别管我，我的素材还没拿到——"
  },
  [85151061] = {
    id = 85151061,
    name = "生日是今天么？抱歉，我常常会因为沉迷研究搞混不少事情......不过我有准备礼物——魔物标本，这是我加入探险队后做的第一个，送给你。"
  },
  [85161061] = {
    id = 85161061,
    name = "去年收集到的新物种资料并不算多，不过我很满足，这代表现在已发现区域中的物种我基本收集齐了，有些期待去新的地方了。"
  },
  [85171061] = {
    id = 85171061,
    name = "那个......队长，可以请你收下这个吗？只是一些点心，感谢您长久以来对我研究的鼓励和帮助。"
  },
  [85181061] = {
    id = 85181061,
    name = "以前有一次在圈落中被孩子们带着参加节日巡游，当他们得知我就是那个“解剖者”后，全都吓着跑开了......那之后我便尽量避免类似的活动。"
  },
  [85191061] = {
    id = 85191061,
    name = "故事中说今天会有人骑着驯鹿跑遍世界，这种生物果然是幻想出来的吧，如果真有这样的生物，它的身体构造会是怎样的呢。"
  },
  [85011071] = {
    id = 85011071,
    name = "本小姐便是大名鼎鼎的“仲裁侦探”马尔可，把重要的案子都拿过来。对了，这里办事利索的人员名单，也帮本小姐整理一份。"
  },
  [85021071] = {
    id = 85021071,
    name = "这些人选都太普通了，就没有别的推荐了么？找一个称心如意的助手，真是比找一件圣物还难。"
  },
  [85031071] = {
    id = 85031071,
    name = "任何一件小事，都有可能演变为足以影响世界的重大事件！而仲裁侦探，则是让这一切都消弭于萌芽的存在。"
  },
  [85031072] = {
    id = 85031072,
    name = "作为仲裁侦探，本小姐所奉行的准则当然是以理服人，只有面对那些冥顽不灵的家伙时，才会使用一些特别的手段。"
  },
  [85041071] = {
    id = 85041071,
    name = "对侦探而言最重要的智慧，本小姐已经足够了，现在需要的是更多力量。"
  },
  [85041072] = {
    id = 85041072,
    name = "智慧负责推理，而力量负责执行，二者兼具才足以称作“仲裁侦探”。"
  },
  [85041073] = {
    id = 85041073,
    name = "只要我们不断去解决各种案件，“仲裁侦探”的名号总有一天会传遍深渊。"
  },
  [85051071] = {
    id = 85051071,
    name = "无论多小的细节都绝不能放过，解决棘手案件的关键往往是那些容易被忽略的事物。"
  },
  [85051072] = {
    id = 85051072,
    name = "力量对推理确实不会有太多帮助，但可以让本小姐的想法得以更好的贯彻。"
  },
  [85051073] = {
    id = 85051073,
    name = "为了贯彻正义，无论怎样的手段都应该被允许，那些在背后议论本小姐行事作风的人，我会找他们好好聊聊。"
  },
  [85051074] = {
    id = 85051074,
    name = "推理、仲裁的能力固然是判断仲裁侦探是否优秀的标准，但对本小姐而言，真正的优秀可远不止这些，比如......能否拥有一位得力助手。"
  },
  [85051075] = {
    id = 85051075,
    name = "每一次结束都是另一个新的开始，不管完成了多少案件，都只是过去，必须尽快将目光放到下一件事情上。"
  },
  [85061071] = {
    id = 85061071,
    name = "诶，新案件？我助手还没找到！"
  },
  [85071071] = {id = 85071071, name = "嘿咿~"},
  [85071072] = {id = 85071072, name = "喝！"},
  [85071073] = {id = 85071073, name = "呀啊！"},
  [85081071] = {
    id = 85081071,
    name = "线索已经明了。"
  },
  [85081072] = {
    id = 85081072,
    name = "请接受调查。"
  },
  [85091071] = {
    id = 85091071,
    name = "大罪！不可饶恕的大罪！"
  },
  [85091072] = {
    id = 85091072,
    name = "冥顽不灵，去地狱忏悔吧！"
  },
  [85101071] = {id = 85101071, name = "呃啊！"},
  [85101072] = {id = 85101072, name = "啊！"},
  [85101073] = {id = 85101073, name = "切！"},
  [85111071] = {
    id = 85111071,
    name = "本小姐绝不会向罪恶屈服！"
  },
  [85121071] = {
    id = 85121071,
    name = "罪恶的力量，如此强大了么......"
  },
  [85131071] = {
    id = 85131071,
    name = "对本小姐而言这没什么特别的，仲裁侦探才不会因为这点小事感到骄傲。"
  },
  [85141071] = {
    id = 85141071,
    name = "哼！如果本小姐有助手协助，怎么可能让这群罪恶之徒胡作非为。"
  },
  [85151071] = {
    id = 85151071,
    name = "为什么知道你生日？对仲裁侦探而言这难道不是理所应当的事么。看在你平时努力帮我寻找助手的份上，本小姐就破例为你庆祝一下这个特别的日子吧。"
  },
  [85161071] = {
    id = 85161071,
    name = "过去的一年解决了不少案件，不过还远远不够，今年的目标是100件，所以没时间休息了，得抓紧时间找到助手帮忙解决才行。"
  },
  [85171071] = {
    id = 85171071,
    name = "桌子上的东西？那，那是本小姐做的点心，不小心多做了一点，就当感谢你的帮忙，提前支付的一点报酬吧。"
  },
  [85181071] = {
    id = 85181071,
    name = "外面好像有很多人聚集......说不定里面会有优秀助手的人选，这种机会绝对不能错过，我们也赶紧去看看吧！"
  },
  [85191071] = {
    id = 85191071,
    name = "越是热闹的节日，越容易发生案件，仲裁侦探可没时间放松。如果能拥有一位得力助手，说不定偶尔也会有些享受节日的时间。"
  },
  [85011081] = {
    id = 85011081,
    name = "为什么会是我呢，优秀的探险者还有很多......不管出于怎样的目的，我会按约定做好自己该做的事。"
  },
  [85021081] = {
    id = 85021081,
    name = "今天的行程安排是怎样的，我想提前做些准备。"
  },
  [85031081] = {
    id = 85031081,
    name = "明明是个危机四伏、尔虞我诈的世界，却依然令无数人向往......果然只要存在利益，便不会缺少前赴后继的追逐者。"
  },
  [85031082] = {
    id = 85031082,
    name = "深渊世界并没有故事中那么美好，但它存在着所谓的奇迹，我还停留于此，便是在渴求奇迹，渴求着再见一眼已无法归来的人。"
  },
  [85041081] = {
    id = 85041081,
    name = "如果是为了我能更好的应对战斗，您所做的已经足够了。"
  },
  [85041082] = {
    id = 85041082,
    name = "战斗，是我现在唯一能做到的事，我会全力战斗，直至找到我所渴求的奇迹。"
  },
  [85041083] = {
    id = 85041083,
    name = "我并没有太多欲望，自然也不会有那么多犹豫和畏惧。"
  },
  [85051081] = {
    id = 85051081,
    name = "我成为探险者的回忆并不美好，但正因为那段经历，我才能更清晰的认识这个世界。"
  },
  [85051082] = {
    id = 85051082,
    name = "魔物的凶恶固然令人畏惧，但在深渊中，比魔物更可怕的，却是人心。"
  },
  [85051083] = {
    id = 85051083,
    name = "我并非想谢绝您的好意，只是经历了太多虚伪和欺骗......我不想再有那样的经历。"
  },
  [85051084] = {
    id = 85051084,
    name = "无论遭遇怎样的困难、危险，亦或者感到悲伤、绝望，我都学会了微笑面对......无法改变这个世界，只能改变自己。"
  },
  [85051085] = {
    id = 85051085,
    name = "我明白自己所渴求的奇迹有多么虚无缥缈，但如果选择放弃，我会找不到自己存在的意义。"
  },
  [85061081] = {
    id = 85061081,
    name = "我已准备完成。"
  },
  [85071081] = {id = 85071081, name = "嘿。"},
  [85071082] = {id = 85071082, name = "噫呃。"},
  [85071083] = {id = 85071083, name = "哈啊！"},
  [85081081] = {
    id = 85081081,
    name = "锁定——"
  },
  [85081082] = {
    id = 85081082,
    name = "瞄准——"
  },
  [85091081] = {
    id = 85091081,
    name = "已经结束了。"
  },
  [85091082] = {
    id = 85091082,
    name = "你们赢不了的。"
  },
  [85101081] = {id = 85101081, name = "呃。"},
  [85101082] = {id = 85101082, name = "呃啊~"},
  [85101083] = {id = 85101083, name = "呜啊~"},
  [85111081] = {
    id = 85111081,
    name = "意料之中的问题，没关系。"
  },
  [85121081] = {
    id = 85121081,
    name = "这次，可以......见到了吗......"
  },
  [85131081] = {
    id = 85131081,
    name = "我所做的准备，足以应对更复杂的战局。"
  },
  [85141081] = {
    id = 85141081,
    name = "无论如何准备，也无法应对诡变的战局吗......"
  },
  [85151081] = {
    id = 85151081,
    name = "生日是对生命的记录， 所以拥有了特别的意义。这种特别的日子，值得我们感恩和庆祝。"
  },
  [85161081] = {
    id = 85161081,
    name = "又是没有任何发现的一年，虽然我已知晓奇迹不太可能出现，但依然会在每个早晨醒来的时候，祈祷奇迹。"
  },
  [85171081] = {
    id = 85171081,
    name = "在你的身上，我感受到了和以前遇到的那些人相似的感觉，可是又不太一样......总之，谢谢您的关照。"
  },
  [85181081] = {
    id = 85181081,
    name = "我找不到和人群一起欢呼庆祝的理由，至少在我明白哪些人是我可以完全信任的之前。"
  },
  [85191081] = {
    id = 85191081,
    name = "每年这个时候，我都会许同一个愿望，可是实现愿望的地方终究只存在于故事中。"
  },
  [85011091] = {
    id = 85011091,
    name = "探险者烈风，为追寻强者之道而来，如果有任何线索，请务必告诉我。作为回报，我可以为你解决任何不违背我信念的问题。"
  },
  [85021091] = {
    id = 85021091,
    name = "我们什么时候出发，我想尽快找个对手验证一下近期的修行成果。"
  },
  [85031091] = {
    id = 85031091,
    name = "这里的生存法则，和我的家族很像。大家都狂热的崇尚力量，拥有力量的人可以拥有一切，名誉、财富、权力......不过，又似乎有些不同。"
  },
  [85031092] = {
    id = 85031092,
    name = "我想要成为强者并非是为了财富和名望，家族中的生活让我早已厌倦了那一切，我只是渴望突破自己的极限，追寻契合自己信念的未来。"
  },
  [85041091] = {
    id = 85041091,
    name = "力量是成为强者的基础，但不应该是强者的全部。"
  },
  [85041092] = {
    id = 85041092,
    name = "我所追寻的强者之道，是永不放弃的信念，毫不妥协的坚持，绝不后退的意志。"
  },
  [85041093] = {
    id = 85041093,
    name = "我的实力又有了新的突破，但我的信念和意志，还需要更多磨练。"
  },
  [85051091] = {
    id = 85051091,
    name = "如果没有坚定的信念，盲目追求力量，最终只会沦为欲望的奴隶。"
  },
  [85051092] = {
    id = 85051092,
    name = "我的童年并不美好，不过也正因如此，我才明白只有变得足够强大才能选择自己的未来。"
  },
  [85051093] = {
    id = 85051093,
    name = "真正的强者，不会沉迷于那些和修行无关的事，不管何时都应当朝着自己的目标全力以赴。"
  },
  [85051094] = {
    id = 85051094,
    name = "衡量强者的重要标准并非是他所拥有的力量，而在于他对待弱者的方式。"
  },
  [85051095] = {
    id = 85051095,
    name = "我所追寻的强者之道的确有些严苛，但如果没有自己的信念，拥有再强大的力量，也只能算得上莽夫。"
  },
  [85061091] = {id = 85061091, name = "走吧。"},
  [85071091] = {id = 85071091, name = "呵！"},
  [85071092] = {id = 85071092, name = "呀！"},
  [85071093] = {id = 85071093, name = "喝啊！"},
  [85081091] = {
    id = 85081091,
    name = "绝不妥协。"
  },
  [85081092] = {
    id = 85081092,
    name = "绝不后退。"
  },
  [85091091] = {
    id = 85091091,
    name = "不负强者的荣耀。"
  },
  [85091092] = {
    id = 85091092,
    name = "见证我的意志。"
  },
  [85101091] = {id = 85101091, name = "唔。"},
  [85101092] = {id = 85101092, name = "呃。"},
  [85101093] = {id = 85101093, name = "啊。"},
  [85111091] = {
    id = 85111091,
    name = "哼~这样就想让我停下？"
  },
  [85121091] = {
    id = 85121091,
    name = "我的选择，错了吗......"
  },
  [85131091] = {
    id = 85131091,
    name = "强者不会满足于微小胜利，继续挑战更强的对手吧。"
  },
  [85141091] = {
    id = 85141091,
    name = "前行的路上总会布满荆棘，只有不放弃的人，才能算得上强者。"
  },
  [85151091] = {
    id = 85151091,
    name = "今天是你的生日吗？之前虽然有听说，但我并不知道这边庆祝生日的习俗，也不知道该准备些什么......所以，如果有希望我做的事，请尽管开口。"
  },
  [85161091] = {
    id = 85161091,
    name = "对我而言新年并没有什么不同，在成为强者的路上，没有任何一天可以松懈。你说享受节日也是强者的一种修行？怎么可能！嗯——或许也有点道理......那、那我尝试一下，今天和你一起去庆祝新年吧。"
  },
  [85171091] = {
    id = 85171091,
    name = "代表感谢的日子吗？原来还有这样的节日，对那些有恩与自己的人心怀感激，这一点也非常契合我的强者之道。感谢你一直以来对我的支持和关照！"
  },
  [85181091] = {
    id = 85181091,
    name = "确实是很热闹的日子，不过对我的修行似乎并没有什么帮助。对我而言，任何事情都只分为两个类型，“与修行有关”和“与修行无关”。"
  },
  [85191091] = {
    id = 85191091,
    name = "已经这个点了吗，得抓紧时间去狩猎，准备节日用的物资——嗯，为什么狩猎？今天不是狩猎的节日吗，难道这里没有这样的习惯？"
  },
  [85011101] = {
    id = 85011101,
    name = "您好，我是探险者罗宾，非常感谢您的邀请，很乐意为您效力——“孤高游侠”，没、没错，是是是我本人。"
  },
  [85021101] = {
    id = 85021101,
    name = "物资分配、行动计划、探险准备......我该先处理哪个呢？抱歉，好像已经问了你很多次。虽然我已经逐渐熟悉了这些事务，但事务太多时依然会手忙脚乱。"
  },
  [85031101] = {
    id = 85031101,
    name = "“孤高游侠”，我真的很喜欢这个称呼，可是这是因为意外才获得的称号，感觉现在的自己配不上，呼~好烦恼。"
  },
  [85031102] = {
    id = 85031102,
    name = "在这竟然能看到这本游记，这可是我最喜欢的书！我想要成为探险者，很大程度是受了它的影响，而且这本书主角的名字和我很像！"
  },
  [85041101] = {
    id = 85041101,
    name = "如果以孤高游侠作为目标，不管实力还是经历我都还差的很远。"
  },
  [85041102] = {
    id = 85041102,
    name = "如果能掌握更强的实力，或许我就可以和那些传奇游侠一样，游历四方，行侠仗义。"
  },
  [85041103] = {
    id = 85041103,
    name = "竟然有种“我也算故事主角”的感觉，嘿嘿~虽然还只是错觉，但我会朝着这个方向继续努力。"
  },
  [85051101] = {
    id = 85051101,
    name = "如果没有成为探险者，或许我现在正按照家人的安排，做一些在他们看来还不错的工作吧。"
  },
  [85051102] = {
    id = 85051102,
    name = "多亏了大家的关照我才能走到这一步，今后我也会继续努力，不辜负大家的期待。"
  },
  [85051103] = {
    id = 85051103,
    name = "我很不擅长做决定，从小到大，所有的一切都是父母和师父为我安排好的，就连刚到深渊的时候，我也是模仿游记里的主人公在行动。"
  },
  [85051104] = {
    id = 85051104,
    name = "受到太多的期待会让我感到不安，所以来到这里之前我才会选择独行，不过也因此才获得了“孤高游侠”的称号，一切都好像注定的一样。"
  },
  [85051105] = {
    id = 85051105,
    name = "成为传奇游侠是我的梦想，但我也明白自己和他们之间的差距......不过，感觉只要和这里的大家一起努力，总有一天一定可以实现。"
  },
  [85061101] = {
    id = 85061101,
    name = "嗯，交给我。"
  },
  [85071101] = {id = 85071101, name = "喝呀！"},
  [85071102] = {id = 85071102, name = "噫呃！"},
  [85071103] = {id = 85071103, name = "呀喝！"},
  [85081101] = {id = 85081101, name = "退下！"},
  [85081102] = {
    id = 85081102,
    name = "接招——"
  },
  [85091101] = {
    id = 85091101,
    name = "胆大的尽管来吧！"
  },
  [85091102] = {
    id = 85091102,
    name = "无需手下留情。"
  },
  [85101101] = {id = 85101101, name = "呃啊。"},
  [85101102] = {id = 85101102, name = "呀啊。"},
  [85101103] = {id = 85101103, name = "呜啊~"},
  [85111101] = {
    id = 85111101,
    name = "唔，大意了——"
  },
  [85121101] = {
    id = 85121101,
    name = "......哈啊~可以不用逞强了......"
  },
  [85131101] = {
    id = 85131101,
    name = "对游侠而言，这样的胜利微不足道。"
  },
  [85141101] = {
    id = 85141101,
    name = "如果我不逞强，及时将内心的不安说出来，会不会有不同的结局......"
  },
  [85151101] = {
    id = 85151101,
    name = "我听说今天是你的生日，所以准备了一些饭菜，当然，也有蛋糕和果汁。因为不知道你会喜欢什么，所以就什么都准备了一些。"
  },
  [85161101] = {
    id = 85161101,
    name = "在这种重要的日子里好好休息也是游侠的修行之一，为什么？唔，据书上所说，游侠的修行应当融入生活，而非一味苦修，要学会在对应的时间做对应的事。"
  },
  [85171101] = {
    id = 85171101,
    name = "抱歉，我，那个，失败了......我尝试了好多次，可是做出来的点心依然不行。所以，可以用这本我最爱的游记作为替代么，谢谢你长久以来的关照。"
  },
  [85181101] = {
    id = 85181101,
    name = "故事里，游侠们总是会非常享受各种节日，可是我却完全做不到——让我去参加这样热闹的活动，我会感到不安和紧张......"
  },
  [85191101] = {
    id = 85191101,
    name = "在我来深渊之前，每年这个时候我们一家都会坐在火炉边，分享一年来各自的收获。我感觉非常有趣，要试试吗？那么先从我开始吧......"
  },
  [85011111] = {
    id = 85011111,
    name = "您好~我是米哈尔，今天起正式加入您的探险队，如果有任何我能帮上忙的事，请尽管吩咐！那么，今后请多多指教了~"
  },
  [85021111] = {
    id = 85021111,
    name = "物资都已准备完毕，随时可以出发——诶，辛苦？那个、只是一点力所能及的小事而已，请不必客气。"
  },
  [85031111] = {
    id = 85031111,
    name = "一夜暴富啊~呵呵，不错的愿望，想必深渊中的许多人都有这样的愿望吧......只是，对一些人而言，一夜暴富或许并不算什么好事。"
  },
  [85031112] = {
    id = 85031112,
    name = "有人将深渊视作实现愿望的圣地，有人则将此看作孕育罪恶的漩涡。但在我看来，深渊、就只是深渊而已，既不是什么圣地，也并非什么漩涡。"
  },
  [85041111] = {
    id = 85041111,
    name = "不管前方是美好还是丑恶，我都会继续前行。"
  },
  [85041112] = {
    id = 85041112,
    name = "不沉溺于过去，不期望于未来，如此、才能把握住现在。"
  },
  [85041113] = {
    id = 85041113,
    name = "这种前所未有的体验我一定不会忘记！呵呵，今后也请继续关照。"
  },
  [85051111] = {
    id = 85051111,
    name = "那是一种如美梦般的感觉......虽然很快就醒了，但如果不是那场美梦，我很难拥有现在的一切。"
  },
  [85051112] = {
    id = 85051112,
    name = "我并不清楚深渊中是否拥有我想要的答案，但我很喜欢现在正经历着的一切。"
  },
  [85051113] = {
    id = 85051113,
    name = "不管做任何事都要竭尽全力才行，即便结果不一定完美，但至少可以让自己在未来不会后悔。"
  },
  [85051114] = {
    id = 85051114,
    name = "全力以赴是我现在唯一能做到的事，不管会遭遇怎样的困难挫折，我也绝不会放弃。"
  },
  [85051115] = {
    id = 85051115,
    name = "对我而言，现在所经历的每一刻都是无可替代的存在，所以我会全力去享受，绝不给自己留下任何遗憾。"
  },
  [85061111] = {
    id = 85061111,
    name = "那么、一起前进吧！"
  },
  [85071111] = {id = 85071111, name = "呀啊。"},
  [85071112] = {id = 85071112, name = "喝啊！"},
  [85071113] = {id = 85071113, name = "哈！"},
  [85081111] = {
    id = 85081111,
    name = "无处可逃。"
  },
  [85081112] = {
    id = 85081112,
    name = "一击毙命！"
  },
  [85091111] = {
    id = 85091111,
    name = "前行之路、由我来开辟！"
  },
  [85091112] = {
    id = 85091112,
    name = "无人可以阻挡我们。"
  },
  [85101111] = {id = 85101111, name = "呜呃。"},
  [85101112] = {id = 85101112, name = "呃啊。"},
  [85101113] = {id = 85101113, name = "呃呃。"},
  [85111111] = {
    id = 85111111,
    name = "还不到放弃的时候。"
  },
  [85121111] = {
    id = 85121111,
    name = "我的旅途......到此为止了吗......"
  },
  [85131111] = {
    id = 85131111,
    name = "所有阻碍都已清除完毕，去下一个地点吧。"
  },
  [85141111] = {
    id = 85141111,
    name = "旅途漫漫，难免遭遇荆棘坎坷。"
  },
  [85151111] = {
    id = 85151111,
    name = "今天是你的生日吧？怎么知道的？呵呵，秘密！我知道一个不错的地方，一起去庆祝吧！"
  },
  [85161111] = {
    id = 85161111,
    name = "小时候每到新年我都会在门框上划一条线，看看自己今年长高了多少。那时候最大的心愿便是赶快长大，减轻母亲的负担......"
  },
  [85171111] = {
    id = 85171111,
    name = "节日快乐~非常感谢您长久以来的关照。给，一点儿小礼物——呵呵，只是一些点心，用母亲教我的方法做的，希望能合你的口味~"
  },
  [85181111] = {
    id = 85181111,
    name = "没想到这种节日在深渊中也会举办得如此热闹，我们可不能错过了！一起去看看吧！呵呵，不知道深渊里是否也会有巡游的队伍。"
  },
  [85191111] = {
    id = 85191111,
    name = "又到这个日子了吗......此前我在各地游历时，曾见识过一些极具地域特色的庆祝方式，和寻常的庆典完全不同——想知道详细？呵呵，那我们今天就聊聊这个好了！"
  },
  [85011121] = {
    id = 85011121,
    name = "鬼姬向您问好~作为鬼牌之人竟然也能收到邀请，呵呵呵~阁下真是有趣......"
  },
  [85021121] = {
    id = 85021121,
    name = "深渊中从来不缺好玩的事情，不过想要找到心仪的事物，更多时候需要我们亲自导演才行~"
  },
  [85031121] = {
    id = 85031121,
    name = "无论贪婪还是慷慨，罪恶亦或仁慈，深渊这个舞台都会将它们完美呈现出来~每一个来到深渊的人，不管是否愿意，都已经成为了这舞台上的一员。"
  },
  [85031122] = {
    id = 85031122,
    name = "对鬼牌而言这个世界会变得怎样并不重要，我们所渴求的只有那一出出有趣的戏剧~所以只要深渊这个舞台还在，便永远会存在观众的席位。"
  },
  [85041121] = {
    id = 85041121,
    name = "竟然会做出这样的举动，呵呵，非常有趣~阁下所渴求的会是什么呢？"
  },
  [85041122] = {
    id = 85041122,
    name = "解开鬼姬的束缚......很有趣的选择！希望阁下在将来不会后悔这一刻所做的决定。"
  },
  [85041123] = {
    id = 85041123,
    name = "鬼姬最擅长的便是导演各种好戏，就让在下为阁下献上更多有趣的表演吧。"
  },
  [85051121] = {
    id = 85051121,
    name = "鬼牌中一些人偶尔会指责在下对那些有趣的事情干预过多，可是如果不亲自参与会少很多乐趣吧？虽然都是观众，但理念上仍有不少差距呢~"
  },
  [85051122] = {
    id = 85051122,
    name = "阁下觉得自己已经了解鬼姬了吗？呵呵，不，你不了解！不过也不必了解，有时候知道太多只会为我们增加无谓的烦恼。"
  },
  [85051123] = {
    id = 85051123,
    name = "在寻找乐趣方面，鬼牌中很少有人能比得上鬼魅。有时候她只需要稍加引导，便能将一些无聊的小事演变为有趣的戏剧~"
  },
  [85051124] = {
    id = 85051124,
    name = "这深渊中有无数有趣的事情，见证它们便是鬼姬存在的意义，无论现在将来，这一点永远都不会改变。"
  },
  [85051125] = {
    id = 85051125,
    name = "杰姬，多么遥远的名字，在下以为再也不会听到......呵呵，不过比起杰姬，还是鬼姬更适合在下。"
  },
  [85061121] = {
    id = 85061121,
    name = "好戏、开场——"
  },
  [85071121] = {id = 85071121, name = "喝——"},
  [85071122] = {id = 85071122, name = "嘿！"},
  [85071123] = {id = 85071123, name = "呀！"},
  [85081121] = {
    id = 85081121,
    name = "尽管挣扎吧~"
  },
  [85081122] = {
    id = 85081122,
    name = "降临——"
  },
  [85091121] = {
    id = 85091121,
    name = "这场表演该进入高潮了。"
  },
  [85091122] = {
    id = 85091122,
    name = "鬼姬才是这场闹剧主宰！"
  },
  [85101121] = {id = 85101121, name = "呃。"},
  [85101122] = {id = 85101122, name = "唔呃。"},
  [85101123] = {id = 85101123, name = "呃啊。"},
  [85111121] = {
    id = 85111121,
    name = "这么渴望和鬼姬一起狂欢吗？"
  },
  [85121121] = {
    id = 85121121,
    name = "鬼姬......谢幕了吗......"
  },
  [85131121] = {
    id = 85131121,
    name = "一场闹剧——呵呵呵，不过也算是为鬼姬带来了不少乐趣。"
  },
  [85141121] = {
    id = 85141121,
    name = "搞砸了？不，是我们太过沉迷，被卷入了这场闹剧~"
  },
  [85151121] = {
    id = 85151121,
    name = "生日？呵呵呵，这可是个值得庆祝的好日子~就让鬼姬为阁下献上一场盛宴吧——还请放心，只是一场单纯的生日宴会，不会有打扰您雅兴的剧目。"
  },
  [85161121] = {
    id = 85161121,
    name = "在这种寓意着美好、希望的节日中，依然会有无数精彩的好戏上演~毕竟人越聚集的地方，越容易出现矛盾纷争，这种节日果然很棒啊！"
  },
  [85171121] = {
    id = 85171121,
    name = "鬼姬在准备点心，毕竟点心和这个日子非常匹配吧？为什么会这样做？是啊，为什么呢？呵呵呵~或许鬼姬就应该做一些让人无法预料的事吧？"
  },
  [85181121] = {
    id = 85181121,
    name = "平日里鬼姬不管在哪出现都会成为所有人的焦点，可是这种节日里，似乎所有人都已经忘记了鬼姬，真是无聊的节日......"
  },
  [85191121] = {
    id = 85191121,
    name = "诶，竟然会给鬼姬赠送礼物，阁下也总能做出一些让鬼姬难以捉摸的事~我现在可以打开吗？确定？"
  },
  [85011131] = {
    id = 85011131,
    name = "请问这份邀请上的地址是这里吗？看来没走错。我是汐，来自真理之钥，如果有和魔法奥秘相关的事请尽管交给我！"
  },
  [85021131] = {
    id = 85021131,
    name = "我在整理近期的感悟记录，有几处关键的地方还是没能想明白，可以帮我参考一下吗？"
  },
  [85031131] = {
    id = 85031131,
    name = "我学习魔法不久便产生了“魔法是如何诞生的”这种疑问，这也是真理之钥的大家都渴望了解的问题。我相信只要大家继续努力，一定可以找到这个问题的答案。"
  },
  [85031132] = {
    id = 85031132,
    name = "最初我得知真理之钥的目标时非常惊讶，那是我第一次遇到和我拥有相似理想的组织，所以在加入时我完全没有犹豫。"
  },
  [85041131] = {
    id = 85041131,
    name = "我有一种即将产生新领悟的感觉，只差一点了，再一点......"
  },
  [85041132] = {
    id = 85041132,
    name = "每一次力量的变化都能获得一些感悟，虽然不一定能起到很大的作用，但这种感觉我很喜欢。"
  },
  [85041133] = {
    id = 85041133,
    name = "情感！是人的情感！我好像又明白了一些，从某些方面来讲魔法便是我们的一种情感的具现！"
  },
  [85051131] = {
    id = 85051131,
    name = "对于同类型魔法的研究我确实有了一些收获，但对于不同魔法间的共通性和特性我依然收获甚微，今后这方面的研究还要更努力才行。"
  },
  [85051132] = {
    id = 85051132,
    name = "无论武技还是魔法，对它们的了解每多一分，实力自然会变得更强。所以不管采用怎样的方式修行，理解和领悟才是最重要的。"
  },
  [85051133] = {
    id = 85051133,
    name = "故事书中的魔法师都拥有无所不能的力量，可是我自己掌握后才发现完全是骗人的，呵呵，不过如果不是那些魔法师，我也不会学习魔法。"
  },
  [85051134] = {
    id = 85051134,
    name = "“从何开始，到哪结束”，只要能想清楚这两个问题，或许我便能找到解开魔法奥秘的钥匙。"
  },
  [85051135] = {
    id = 85051135,
    name = "对魔法的研究越是深入，便越发明白自己的渺小，我甚至开始怀疑自己能否在这深渊中找到想要的答案。"
  },
  [85061131] = {
    id = 85061131,
    name = "我会好好把握这次机会。"
  },
  [85071131] = {id = 85071131, name = "呀~"},
  [85071132] = {id = 85071132, name = "哈啊。"},
  [85071133] = {id = 85071133, name = "嘿呀。"},
  [85081131] = {
    id = 85081131,
    name = "我会加油。"
  },
  [85081132] = {
    id = 85081132,
    name = "交给我吧。"
  },
  [85091131] = {
    id = 85091131,
    name = "见识一下我的全力吧。"
  },
  [85091132] = {
    id = 85091132,
    name = "信念才是最强大的魔法！"
  },
  [85101131] = {id = 85101131, name = "噫呃。"},
  [85101132] = {id = 85101132, name = "呀啊。"},
  [85101133] = {id = 85101133, name = "呃啊。"},
  [85111131] = {
    id = 85111131,
    name = "请别分心，我还可以继续。"
  },
  [85121131] = {
    id = 85121131,
    name = "终于发现了问题，可是......"
  },
  [85131131] = {
    id = 85131131,
    name = "很完美的作战，我似乎也又有了些感悟，先记录一下......"
  },
  [85141131] = {
    id = 85141131,
    name = "对不起，都怪我没能把握好时机......"
  },
  [85151131] = {
    id = 85151131,
    name = "听说今天是你的生日，所以大家一起筹备了庆祝会，你会参加吧？如果少了主角，那庆祝会就没有意义了。"
  },
  [85161131] = {
    id = 85161131,
    name = "在我家新年是非常重要的日子，家人之间会彼此分享各自过去一年的收获，畅想新一年的愿望。来到深渊后我也依然坚持着这样的习惯，不过分享对象从家人变成了同伴。"
  },
  [85171131] = {
    id = 85171131,
    name = "非常抱歉，我尝试了很多次，也无法做出美味的甜点。比起魔法，厨艺要困难太多了......非常感谢你对我的关照！"
  },
  [85181131] = {
    id = 85181131,
    name = "平时真理之钥的同伴都在为了目标各自努力，只有这种热闹的节日才会聚到一起庆祝。今年一起去吧，大家每次都能想出些奇怪的比试，会很有趣哦！"
  },
  [85191131] = {
    id = 85191131,
    name = "这样的节日里，真理之钥的大家也会交换礼物，不过我们的礼物都是彼此修行时获得的感悟。我们在阅读后也不会保留，而是传递给下一个成员，这样便能确保大家拥有最大收获。"
  },
  [85011141] = {
    id = 85011141,
    name = "我是狄莉丝，有麻烦尽管找我，只要报酬合适，不管怎样的问题都能给你摆平。"
  },
  [85021141] = {
    id = 85021141,
    name = "不能打架不能赚钱的每一分钟都令人觉得煎熬，快收拾好出发吧。"
  },
  [85031141] = {
    id = 85031141,
    name = "赚钱是人生一大乐趣，打架也是人生的一大乐趣，两种乐趣叠加，便是我所追求的最高乐趣。"
  },
  [85031142] = {
    id = 85031142,
    name = "在深渊中，拳头才是最大的道理，强者可以拥有一切，而弱者无论如何歇斯底里也不会有人在意。"
  },
  [85041141] = {
    id = 85041141,
    name = "干得不错！我就喜欢这种直接的做事方式。"
  },
  [85041142] = {
    id = 85041142,
    name = "解放力量的感觉真是令人愉悦，赶紧为我安排更强的对手吧。"
  },
  [85041143] = {
    id = 85041143,
    name = "这疯狂混乱的世界里，唯有力量是永恒的真理！"
  },
  [85051141] = {
    id = 85051141,
    name = "所谓的守护、梦想......如果没有足够的力量，都只是奢望。"
  },
  [85051142] = {
    id = 85051142,
    name = "战斗是一种享受，但也要挑选好对手，和更强的对手战斗，才能突破自己的极限。"
  },
  [85051143] = {
    id = 85051143,
    name = "在深渊中活下去，并非是强者的专利，但强者可以选择要怎样活下去。"
  },
  [85051144] = {
    id = 85051144,
    name = "每个人都有野心和欲望，敢于直面自己内心的人，才能算得上强者。"
  },
  [85051145] = {
    id = 85051145,
    name = "我家老头子教会了我钱财和力量都是不可或缺的东西，所以我会在活着的每一天全力去享受战斗和财富。"
  },
  [85061141] = {
    id = 85061141,
    name = "大闹一场吧！"
  },
  [85071141] = {id = 85071141, name = "呀——"},
  [85071142] = {id = 85071142, name = "喝诶！"},
  [85071143] = {id = 85071143, name = "噫呃！"},
  [85081141] = {
    id = 85081141,
    name = "轮到我了！"
  },
  [85081142] = {
    id = 85081142,
    name = "没人能躲开。"
  },
  [85091141] = {
    id = 85091141,
    name = "逃吧逃吧，再逃远一些。"
  },
  [85091142] = {
    id = 85091142,
    name = "再不挣扎就要结束咯~"
  },
  [85101141] = {id = 85101141, name = "呃。"},
  [85101142] = {id = 85101142, name = "嘁。"},
  [85101143] = {id = 85101143, name = "啊。"},
  [85111141] = {
    id = 85111141,
    name = "就是这种感觉，呵呵哈哈哈！"
  },
  [85121141] = {
    id = 85121141,
    name = "也算是尽兴了吧......"
  },
  [85131141] = {
    id = 85131141,
    name = "就只有这点儿能耐吗？嘁，真是无聊。"
  },
  [85141141] = {
    id = 85141141,
    name = "这笔账，我会让他们会加倍奉还！"
  },
  [85151141] = {
    id = 85151141,
    name = "生日么，也算是特别的日子。一起去喝点吧，顺便带你和我那些“老朋友”活动一下。放心，有我在，不会出什么问题。"
  },
  [85161141] = {
    id = 85161141,
    name = "对我而言，活着的每一天都是新的，毕竟在这个混乱疯狂的世界，谁也无法预知未来，能好好享受当下才是最重要的事。"
  },
  [85171141] = {
    id = 85171141,
    name = "感谢的日子？不，我们之间似乎没有什么要感谢的吧？不过如果能请我喝一杯，说些好听的话也不是不行~"
  },
  [85181141] = {
    id = 85181141,
    name = "据说这一天，那些离去的人都会回来看看......嘁，纯粹就是胡扯，我每年倒好的酒，可从来没有被动过......"
  },
  [85191141] = {
    id = 85191141,
    name = "又是所有人都去享受节日的日子么？真是太闲了，找两个家伙切磋一下吧。......放心，我会手下留情，毕竟大家都是“同伴”嘛~"
  },
  [85011151] = {
    id = 85011151,
    name = "我是猎魔人炎狼，用你们的话来说，叫做探险者。不过，我只是为了魔物而来。"
  },
  [85021151] = {
    id = 85021151,
    name = "请不用在意我的存在，如有需要，我和格拉墨随时可以行动。"
  },
  [85031151] = {
    id = 85031151,
    name = "猎魔人并非只是一个名号，它更是一种责任，一种信念。我继承了这个名号，自然会竭尽全力，背负它所承载的一切。"
  },
  [85031152] = {
    id = 85031152,
    name = "格拉墨是历代猎魔人的武器，不过比起武器，它更像是一名伙伴。虽然偶尔会闹点小脾气，但在危急时永远是最可靠的存在。"
  },
  [85041151] = {
    id = 85041151,
    name = "我和格拉墨之间似乎更有默契了，是错觉么。"
  },
  [85041152] = {
    id = 85041152,
    name = "解放格拉墨的封印，真是大胆的选择——既然如此，便让你见识一下我们的全力。"
  },
  [85041153] = {
    id = 85041153,
    name = "我能感受到格拉墨的兴奋，它正在渴求战斗，渴求魔物的血肉。"
  },
  [85051151] = {
    id = 85051151,
    name = "猎魔人的职责是斩杀魔物和罪恶，肃清深渊，守护人类世界。"
  },
  [85051152] = {
    id = 85051152,
    name = "修行、战斗，再修行、再战斗......这便是我现在所拥有的一切。"
  },
  [85051153] = {
    id = 85051153,
    name = "师父拯救了弱小落魄的我，我也会用他给予我的力量，去拯救更多的人。"
  },
  [85051154] = {
    id = 85051154,
    name = "每个人都有自己拯救和守护的方式，我和格拉墨的方式，便是斩杀更多的魔物。"
  },
  [85051155] = {
    id = 85051155,
    name = "只要还有罪恶和魔物，我和格拉墨便将一往无前。"
  },
  [85061151] = {
    id = 85061151,
    name = "格拉墨，该出发了。"
  },
  [85071151] = {id = 85071151, name = "喝！"},
  [85071152] = {id = 85071152, name = "哈！"},
  [85071153] = {id = 85071153, name = "嘿！"},
  [85081151] = {
    id = 85081151,
    name = "发现猎物。"
  },
  [85081152] = {
    id = 85081152,
    name = "猎杀执行。"
  },
  [85091151] = {
    id = 85091151,
    name = "格拉墨——解放！"
  },
  [85091152] = {
    id = 85091152,
    name = "终结，降临！"
  },
  [85101151] = {id = 85101151, name = "呃啊~"},
  [85101152] = {id = 85101152, name = "唔-"},
  [85101153] = {id = 85101153, name = "唔啊~"},
  [85111151] = {
    id = 85111151,
    name = "格拉墨，你愤怒了吗。"
  },
  [85121151] = {
    id = 85121151,
    name = "还是......那么不堪......"
  },
  [85131151] = {
    id = 85131151,
    name = "只是微不足道的胜利，格拉墨在期待下一次出场。"
  },
  [85141151] = {
    id = 85141151,
    name = "格拉墨，你的不甘和愤怒，我明白。"
  },
  [85151151] = {
    id = 85151151,
    name = "生日么，让格拉墨给你唱首歌如何？——开玩笑的，格拉墨可不会说话。嗯？开玩笑不适合我？"
  },
  [85161151] = {
    id = 85161151,
    name = "又已是新年，我和格拉墨仍未给这深渊带来变化......请别误会，我只是在感慨，并非急于求成。难得的节日，一起去走走吧。"
  },
  [85171151] = {
    id = 85171151,
    name = "对我而言，多余的杂念只会影响我修行的速度。——我并非在否定节日的意义，只是要变得更强，就必须把握每一分钟。"
  },
  [85181151] = {
    id = 85181151,
    name = "人类真是奇怪又矛盾的生物，一边对未知感到畏惧，一边又憧憬未知的存在。"
  },
  [85191151] = {
    id = 85191151,
    name = "我独自流浪的时候，非常喜欢这种日子，因为可以相对轻松的乞讨到食物......意外吗？呵呵，对那个时候的我来说，不挨饿就已是最大的愿望，根本不敢奢求现在的生活。"
  },
  [85011161] = {
    id = 85011161,
    name = "我是薇，很高兴能收到您的邀请，从现在起我就是您的新成员了，还请多多指教。"
  },
  [85021161] = {
    id = 85021161,
    name = "红茶和点心已经准备好了，每次行动前吃饱喝足，才会更有干劲不是吗？呵呵~"
  },
  [85031161] = {
    id = 85031161,
    name = "所谓的“重要收获”就是一种、一种只可意会的存在。可能是数之不尽的财富，也可能是名扬深渊的功绩，亦或者其他的存在。总之，在找到前我也不知道具体会是什么。"
  },
  [85031162] = {
    id = 85031162,
    name = "我从小就听过许多关于深渊的故事，但是当自己真的来到深渊后，才切实感受到了它的存在。虽说这里和故事中存在巨大的差异，但并没有改变我对它的憧憬。"
  },
  [85041161] = {
    id = 85041161,
    name = "我并没有那么多远大的理想，能拥有现在这样可以帮上大家的力量，我就已经很满足了。"
  },
  [85041162] = {
    id = 85041162,
    name = "属于我的“重要收获”，一定会是我们所共同期待的存在，就由我们一起去追寻它的所在吧。"
  },
  [85041163] = {
    id = 85041163,
    name = "家人和同伴才是我最重要的存在，我所做的一切，都是为了能更好的守护自己重要的人。"
  },
  [85051161] = {
    id = 85051161,
    name = "战斗之外的事我也还算自信，如果有需要可以随时交给我。"
  },
  [85051162] = {
    id = 85051162,
    name = "我对魔法只能算得上略有研究，还称不上优秀，这也是我到深渊历练的目的之一。"
  },
  [85051163] = {
    id = 85051163,
    name = "深渊世界虽然残酷，但我们拥有可以彼此信任的同伴，因此也会有很多温柔和期待。"
  },
  [85051164] = {
    id = 85051164,
    name = "对我来说，盲目追求力量，并不是一个明智的决定，只有适合自己的，才算是最好的。"
  },
  [85051165] = {
    id = 85051165,
    name = "我所寻找的“重要收获”已经有了一些眉目——是什么？呵呵，现在还不能说，等我得到它的时候再告诉你。"
  },
  [85061161] = {
    id = 85061161,
    name = "大家一起努力吧~"
  },
  [85071161] = {id = 85071161, name = "嗯哼~"},
  [85071162] = {id = 85071162, name = "嘿——"},
  [85071163] = {id = 85071163, name = "呀啊~"},
  [85081161] = {
    id = 85081161,
    name = "交给我。"
  },
  [85081162] = {
    id = 85081162,
    name = "要认真咯~"
  },
  [85091161] = {
    id = 85091161,
    name = "大家的身后，由我来守护。"
  },
  [85091162] = {
    id = 85091162,
    name = "不必担心，我会处理好一切。"
  },
  [85101161] = {id = 85101161, name = "呃啊。"},
  [85101162] = {id = 85101162, name = "哈啊。"},
  [85101163] = {id = 85101163, name = "呃唔。"},
  [85111161] = {
    id = 85111161,
    name = "请别分心，我还可以继续。"
  },
  [85121161] = {
    id = 85121161,
    name = "果然......还是会有遗憾......"
  },
  [85131161] = {
    id = 85131161,
    name = "能和大家彼此信任、彼此依靠，胜利必然会属于我们。"
  },
  [85141161] = {
    id = 85141161,
    name = "敌人的情况超出预料太多，大家带好受伤的同伴，马上撤退。"
  },
  [85151161] = {
    id = 85151161,
    name = "今天是您的生日吧？呵呵~作为您的成员，掌握这种基本信息还是很有必要的。我准备了一些蛋糕和美食，一起来享用吧~"
  },
  [85161161] = {
    id = 85161161,
    name = "新年快乐~今天有什么安排呢？交给我？呵呵，那、我们去附近的圈落逛逛吧，听说那里有话剧和杂技表演，而且还有许多美味的小吃。"
  },
  [85171161] = {
    id = 85171161,
    name = "来，请先把眼睛闭上。张嘴——好吃么？呵呵，这是我自己做的甜点，您能喜欢真是太好了！在深渊中能遇到您是我最幸运的事，今后还请继续关照。"
  },
  [85181161] = {
    id = 85181161,
    name = "除了少数重要事务，其余杂务我已经处理完毕，今天好好享受庆典吧。节日装扮和糖果我也准备好了，随时可以出发。"
  },
  [85191161] = {
    id = 85191161,
    name = "大家的礼物我已经准备好了，请确认一下吧。多了一份？不，一份也没多。要现在打开吗，还是等大家的礼物分发完成之后......？"
  },
  [85011171] = {
    id = 85011171,
    name = "贵安~我是芙蕾雅，一名刚踏上旅途的探险者，非常开心能收到您的邀请，今后还请多多关照。"
  },
  [85021171] = {
    id = 85021171,
    name = "要来一点红茶吗？呵呵~这可是我在上一个圈落中发现的顶级红茶，虽说无法和地面相比，但在深渊中能有这样的品质，已经非常不错了。"
  },
  [85031171] = {
    id = 85031171,
    name = "如果没有经历那场变故，我也无法成为探险者，也不会对世间的人情冷暖有那么深刻的体会......呵呵~有时候，挫折和苦难或许并非全是坏事。"
  },
  [85031172] = {
    id = 85031172,
    name = "大家的过去或许差异很大，但我们现在的身份却并无不同。我们都在这深渊中追逐着自己想要的一切，或是财富，或是名望，亦或者......只是对未知的憧憬。"
  },
  [85041171] = {
    id = 85041171,
    name = "无论面对怎样的挫折苦难，只要能坚持、不放弃，必然会有新的收获。"
  },
  [85041172] = {
    id = 85041172,
    name = "我成为探险者的过程并不顺利，所以才要更珍惜这来之不易的机会，为理想全力以赴！"
  },
  [85041173] = {
    id = 85041173,
    name = "我的理想并没有那么崇高，只是在追寻深渊中的未知，追寻属于自己的未来。"
  },
  [85051171] = {
    id = 85051171,
    name = "我曾拥有令无数人仰慕的生活，可是在那样的生活中，我并没有找到自己想要的一切。"
  },
  [85051172] = {
    id = 85051172,
    name = "当我第一次知晓深渊时便对它充满了向往......不过，身为贵族的父母并不愿意他们的女儿憧憬那样危险、混乱的世界。"
  },
  [85051173] = {
    id = 85051173,
    name = "从决定成为探险者的那一刻起，我便告诉自己，无论前路多么曲折艰险，也绝对不要放弃。"
  },
  [85051174] = {
    id = 85051174,
    name = "深渊中不仅有美好和神秘，也有凶险和危机，没人知道下一刻会有怎样的际遇。也正因为如此，它才更令人着迷。"
  },
  [85051175] = {
    id = 85051175,
    name = "前行的路上必然还有许多风浪，但只要能克服恐惧，胸怀希望，无论怎样的逆境都只会让我们更加强大。"
  },
  [85061171] = {
    id = 85061171,
    name = "我的弓弦已调整完毕。"
  },
  [85071171] = {
    id = 85071171,
    name = "瞄准——"
  },
  [85071172] = {id = 85071172, name = "嘿！"},
  [85071173] = {id = 85071173, name = "哈！"},
  [85081171] = {
    id = 85081171,
    name = "没有后退可言。"
  },
  [85081172] = {
    id = 85081172,
    name = "全神贯注。"
  },
  [85091171] = {
    id = 85091171,
    name = "箭啊，见证我的意志吧！"
  },
  [85091172] = {
    id = 85091172,
    name = "由我来开辟前行之路。"
  },
  [85101171] = {id = 85101171, name = "呃啊。"},
  [85101172] = {id = 85101172, name = "呃。"},
  [85101173] = {id = 85101173, name = "呀啊。"},
  [85111171] = {
    id = 85111171,
    name = "只是一点小麻烦而已。"
  },
  [85121171] = {
    id = 85121171,
    name = "我的决心......还不够吗......"
  },
  [85131171] = {
    id = 85131171,
    name = "我的弓弦正在鸣奏胜利的乐章。"
  },
  [85141171] = {
    id = 85141171,
    name = "如此剧烈的风雨，连弓弦也忍不住悲泣。"
  },
  [85151171] = {
    id = 85151171,
    name = "生日是非常特别的日子，不管怎样都应该好好庆祝才行！嗯......做个蛋糕吧！——请放心，我小时候专门修行过厨艺，这方面还是很有自信的。"
  },
  [85161171] = {
    id = 85161171,
    name = "曾经，新年对我而言意味着数不清的宴会、数不清的应酬，现在终于不用再勉强自己去做那些事了。今天我们就按照自己喜欢的方式来庆祝吧！"
  },
  [85171171] = {
    id = 85171171,
    name = "只有这样的日子，才会觉得以前的厨艺修行有了用处，呵呵~这是我故乡风味的甜点，请试试吧，希望能合您的口味。"
  },
  [85181171] = {
    id = 85181171,
    name = "巡游的人群，嬉闹的孩子们......到处都好热闹。我从来不被允许参加这样的庆典，如此难得的机会，我不想错过，可以陪我去看看吗？"
  },
  [85191171] = {
    id = 85191171,
    name = "节日快乐~请问今天有时间吗？并不是什么要紧的事儿，而是我前段时间学会了一首曲子，想在今天为你演奏一下......"
  },
  [85011181] = {
    id = 85011181,
    name = "如果有什么事请尽管吩咐，只要是为了探险，我会全力以赴！——探险之外的事？我、我也会努力。"
  },
  [85021181] = {
    id = 85021181,
    name = "食物、淡水......呀，差点忘驱魔粉！这下物资都准备好了，我去通知大家，准备出发了~"
  },
  [85031181] = {
    id = 85031181,
    name = "能够像现在这样和大家一起探险，真像是做梦一样~拥有一起并肩作战的同伴、彼此分享见闻的朋友......如果是梦，真希望永远也不要醒来——啊！不好，锅里的食物！"
  },
  [85031182] = {
    id = 85031182,
    name = "“灾厄魔女”吗？次数多了，连自己也觉得似乎就是那样。如果不是遇到了大家，我根本无法走到现在。"
  },
  [85041181] = {
    id = 85041181,
    name = "利用深渊的力量成长这种事情竟然是真的，深渊中还有多少令人无法想象的事情呢。"
  },
  [85041182] = {
    id = 85041182,
    name = "我想和大家一起去往更多的地方，了解深渊更多的秘密，必须继续努力才行。"
  },
  [85041183] = {
    id = 85041183,
    name = "拥有了更强的力量，便也拥有了更多的责任，我已经做好了觉悟！"
  },
  [85051181] = {
    id = 85051181,
    name = "对我而言，这次机会来之不易，我一定会好好珍惜。"
  },
  [85051182] = {
    id = 85051182,
    name = "和大家成为同伴，我觉得非常开心，我会努力做的更好，不成为大家的拖累。"
  },
  [85051183] = {
    id = 85051183,
    name = "我现在已经可以做到许多以前无法做到的事了，但还不够，前路还有许多危险，不能就此懈怠。"
  },
  [85051184] = {
    id = 85051184,
    name = "不管做什么事，都要竭尽全力，就算，就算结果不一定让人满意，但至少也要让自己不会后悔。"
  },
  [85051185] = {
    id = 85051185,
    name = "书上说“宽容和善良，才是深渊中最强大的力量”，我一直不太明白，如今经历了诸多事情，终于有些理解这句话了。"
  },
  [85061181] = {
    id = 85061181,
    name = "今天会遇到些什么呢。"
  },
  [85071181] = {id = 85071181, name = "嘿咿。"},
  [85071182] = {id = 85071182, name = "哈啊~"},
  [85071183] = {id = 85071183, name = "哈！"},
  [85081181] = {
    id = 85081181,
    name = "一起努力吧。"
  },
  [85081182] = {
    id = 85081182,
    name = "全力以赴。"
  },
  [85091181] = {
    id = 85091181,
    name = "支援的事情，请交给我吧。"
  },
  [85091182] = {
    id = 85091182,
    name = "我会守护好大家的身后。"
  },
  [85101181] = {id = 85101181, name = "呃。"},
  [85101182] = {id = 85101182, name = "呃啊。"},
  [85101183] = {id = 85101183, name = "唔呃。"},
  [85111181] = {
    id = 85111181,
    name = "没，没关系，我还可以——"
  },
  [85121181] = {
    id = 85121181,
    name = "唔，如果我能再强一点......"
  },
  [85131181] = {
    id = 85131181,
    name = "大家彼此的信任，是战斗胜利的关键。"
  },
  [85141181] = {
    id = 85141181,
    name = "对不起......果然，我只会带来不幸......"
  },
  [85151181] = {
    id = 85151181,
    name = "老师，生日快乐！呵呵~大家已经准备好了蛋糕和派对，一起去庆祝吧！"
  },
  [85161181] = {
    id = 85161181,
    name = "以前新年的时候，只有蒂娜和我一起，现在能和这么多同伴一起度过，是我从未想过的事。"
  },
  [85171181] = {
    id = 85171181,
    name = "老，老师，这个——这是我自己做的一些甜点，希望老师可以喜欢。谢谢您长久以来的关照，希望您今后，也可以继续关照我。"
  },
  [85181181] = {
    id = 85181181,
    name = "今天好热闹啊，小莎她们等不及已经先出去玩了，我们也赶紧去看看吧，似乎会有很多有趣的事物。"
  },
  [85191181] = {
    id = 85191181,
    name = "以前在孤儿院的时候，每到这样的日子，院长都会组织大家一起坐在火炉旁聊天，分享故事，真是怀念啊。"
  },
  [85011191] = {
    id = 85011191,
    name = "听说这里管吃管住？哈哈，开玩笑的。我是茉莉，很高兴能收到你的邀请，今后请多多关照啦，要真的关照我哦！"
  },
  [85021191] = {
    id = 85021191,
    name = "这段时间好像没什么事，请不用担心，就算真发生了什么我们所不知道的情况，担心也没用。"
  },
  [85031191] = {
    id = 85031191,
    name = "和大家比起来我的实力并不算顶尖，但在深渊中生存的能力，我可不会输给任何人。就算什么也不带，把我扔在外面几个月也不会有问题——嗯？你那是什么眼神，不会真的有这个打算吧？！"
  },
  [85031192] = {
    id = 85031192,
    name = "呼~最近运气真差啊，探险没捞到什么好处就算了，玩游戏也一直在输，得想想办法才行......前些天好像碰到圣歌的人来着，对！去找她们帮忙！"
  },
  [85041191] = {
    id = 85041191,
    name = "竟然真的对我如此关照......这太令人意外，不，太令人感动了！"
  },
  [85041192] = {
    id = 85041192,
    name = "今后我们就是一条船上的同伴了，有福同享，有难同当！"
  },
  [85041193] = {
    id = 85041193,
    name = "没想到我也可以走到这一步，哈哈哈~属于探险者茉莉的时代，就要到来了！"
  },
  [85051191] = {
    id = 85051191,
    name = "老头经常对我说，人无法改变自己的天赋，但可以决定自己努力的程度。"
  },
  [85051192] = {
    id = 85051192,
    name = "不管有怎样的心愿和梦想，只有先想办法活下来，才有可能实现。"
  },
  [85051193] = {
    id = 85051193,
    name = "我所掌握的技巧只能算是些小聪明，想要在深渊活下去，还是得掌握更多能力才行。"
  },
  [85051194] = {
    id = 85051194,
    name = "我所做的一切，都是为了有一天能有足够的力量选择自己的道路。"
  },
  [85051195] = {
    id = 85051195,
    name = "老头希望我能过上安稳的生活，那种生活一定会非常舒适！可是现在的我，更喜欢现在这种和大家一起探险的日子。"
  },
  [85061191] = {
    id = 85061191,
    name = "希望幸运女神多多关照。"
  },
  [85071191] = {id = 85071191, name = "呀！"},
  [85071192] = {id = 85071192, name = "豁！"},
  [85071193] = {id = 85071193, name = "嘿！"},
  [85081191] = {
    id = 85081191,
    name = "别太得意了。"
  },
  [85081192] = {
    id = 85081192,
    name = "尽管来吧！"
  },
  [85091191] = {
    id = 85091191,
    name = "活着才能创造奇迹。"
  },
  [85091192] = {
    id = 85091192,
    name = "运气也是生存的关键。"
  },
  [85101191] = {id = 85101191, name = "呃。"},
  [85101192] = {id = 85101192, name = "唔呃。"},
  [85101193] = {id = 85101193, name = "呃啊。"},
  [85111191] = {
    id = 85111191,
    name = "好险，差点就完蛋了。"
  },
  [85121191] = {
    id = 85121191,
    name = "可恶，运气......真差啊......"
  },
  [85131191] = {
    id = 85131191,
    name = "哇哦，收获满满！这次运气不错嘛~"
  },
  [85141191] = {
    id = 85141191,
    name = "啊，运气真差~不过空手而归也是探险者的常态，只要我们还活着，就还有希望。"
  },
  [85151191] = {
    id = 85151191,
    name = "今天是你的生日？哇哦，那可得好好庆祝一下。我去做个蛋糕吧，虽然味道不一定能让你满意，但外形肯定没问题！哈哈哈~"
  },
  [85161191] = {
    id = 85161191,
    name = "欸？！今天居然没有行动？！呜呜呜，感谢幸运女神。以前我可没有休息的日子，就算是新年，也得为了食物奔波，不然就得饿肚子了。"
  },
  [85171191] = {
    id = 85171191,
    name = "初次见面说多多关照时，还以为只会是客套话，每想竟然真的对我这么关照。能和你相遇，来到这里，难道说.......我运气其实很不错？"
  },
  [85181191] = {
    id = 85181191,
    name = "儿时的我总会尽最大的努力去讨要糖果，然后小心翼翼的存放起来，之后再慢慢享用......呵呵，对那时候的我来说，糖果可是难得的珍品。"
  },
  [85191191] = {
    id = 85191191,
    name = "派发礼物的人选定好了吗？——有了？！那，那驯鹿呢？扮演驯鹿我也可以！只要能感受派发礼物的乐趣，就算扮演一棵树我也没问题！"
  },
  [85011201] = {
    id = 85011201,
    name = "本小姐便是莱娜，未来会名扬深渊的传奇探险者，把所有和传说相关的事都交给本小姐吧。"
  },
  [85021201] = {
    id = 85021201,
    name = "今天的计划会不会太简单了，完全没有能体现出传奇探险者实力的行动，把难度再提高两倍！"
  },
  [85031201] = {
    id = 85031201,
    name = "父母也好，身边的其他人也好，总是喜欢将我当作小孩子看待。哼，总有一天，我会证明自己，成为让谁也不敢小看的传奇探险者。"
  },
  [85031202] = {
    id = 85031202,
    name = "比起所谓的财富，深渊的混沌和未知才是本小姐所看重的，在这种世界，才有更大的可能缔造只属于本小姐的传说。"
  },
  [85041201] = {
    id = 85041201,
    name = "只要有缔造传说的可能，任何机会都不能错过。"
  },
  [85041202] = {
    id = 85041202,
    name = "只不过达到这种程度而已，比起我的目标，还差得远呢。"
  },
  [85041203] = {
    id = 85041203,
    name = "修行的过程虽然辛苦，但比起这样的辛苦，我更不想被忽视，被敷衍。"
  },
  [85051201] = {
    id = 85051201,
    name = "本小姐的未来只能由我自己选择，不需要任何人安排。"
  },
  [85051202] = {
    id = 85051202,
    name = "努力不一定会有收获，但不努力，一定什么也做不到！"
  },
  [85051203] = {
    id = 85051203,
    name = "那种努力后却得不到认可的心情，普通人是不会明白的，当然，本小姐也不需要人理解。"
  },
  [85051204] = {
    id = 85051204,
    name = "缔造传说，就必须做到普通人难以想象的事，为此付出一切我也愿意。"
  },
  [85051205] = {
    id = 85051205,
    name = "如果无法得到认可，不管多么优秀的表现都没有意义。可是，如果能得到认可，哪怕只有一个人，也会完全不同。"
  },
  [85061201] = {
    id = 85061201,
    name = "对手不会太弱吧？"
  },
  [85071201] = {id = 85071201, name = "嘿呀！"},
  [85071202] = {id = 85071202, name = "喝啊！"},
  [85071203] = {id = 85071203, name = "嘿咦！"},
  [85081201] = {
    id = 85081201,
    name = "愚蠢的家伙。"
  },
  [85081202] = {
    id = 85081202,
    name = "受死吧！"
  },
  [85091201] = {
    id = 85091201,
    name = "敢招惹本小姐，你们完了！"
  },
  [85091202] = {
    id = 85091202,
    name = "别以为可以逃掉！"
  },
  [85101201] = {id = 85101201, name = "呃。"},
  [85101202] = {id = 85101202, name = "呃啊。"},
  [85101203] = {id = 85101203, name = "诶呀。"},
  [85111201] = {
    id = 85111201,
    name = "哼，果然是个势均力敌的对手。"
  },
  [85121201] = {
    id = 85121201,
    name = "可恶......呜呜......可恶！"
  },
  [85131201] = {
    id = 85131201,
    name = "赢了！咳~这种程度的对手，还是无法体现本小姐真正的实力。"
  },
  [85141201] = {
    id = 85141201,
    name = "为什么会这么强......就算传奇探险者也不一定能应付。"
  },
  [85151201] = {
    id = 85151201,
    name = "诶？你说今天是你的生日？唔...嘛...看在你平时帮了本小姐不少忙的份上，今天的行动结束后，本小姐陪你去圈落中逛逛吧。"
  },
  [85161201] = {
    id = 85161201,
    name = "又过去了一年，无论实力还是阅历都有了不少收获，可是却并未做到任何能被称为传说的事......这样的我，在父母看来，依然还是个胡闹的小孩子吧......"
  },
  [85171201] = {
    id = 85171201,
    name = "本小姐知道今天是代表感谢的日子，但那又如何，和其他人做一样的事？不，本小姐从来就不会遵循常理，也不会做那些无趣又雷同的事。"
  },
  [85181201] = {
    id = 85181201,
    name = "竟然还在期待今天这种节日，真是幼稚，明明还有那么多的事要做，还特意去准备衣服......算了，既然都准备好了，那就去看看吧。"
  },
  [85191201] = {
    id = 85191201,
    name = "大人物的每一天都很充实，是没有心思考虑这种节日的。不过我还算不上大人物，所有趁现在享受一下节日也是理所当然的事。"
  },
  [85011211] = {
    id = 85011211,
    name = "您好，我是新加入探险队的赛格丽特，叫我丽特就行，如果有能帮上忙的地方请尽管吩咐。"
  },
  [85021211] = {
    id = 85021211,
    name = "关于接下来的行程，我有几个地方想再确认一下，请问现在有时间吗？放心，不会耽误太久。"
  },
  [85031211] = {
    id = 85031211,
    name = "每个人都在深渊追逐自己所渴求的存在，财富、名望、力量......我也不例外，不过在这些事物之外，我更想找到属于自己的未来。"
  },
  [85031212] = {
    id = 85031212,
    name = "来到深渊后我才发现这个世界远比想象中危险，为此我曾一度感到畏惧。多亏了同伴们的支持和鼓励，我才有了继续前行的勇气。"
  },
  [85041211] = {
    id = 85041211,
    name = "这是、对我的认可吗？谢谢，我会好好利用这份力量。"
  },
  [85041212] = {
    id = 85041212,
    name = "我能清晰感觉到自己力量的变化，但要实现我们的目标，只是这样还远远不够。"
  },
  [85041213] = {
    id = 85041213,
    name = "无论前路有多么危险我也不会畏惧，我会用自己的力量、开辟属于自己的未来！"
  },
  [85051211] = {
    id = 85051211,
    name = "最初我一直在各地游历，寻找历练自己的机会，然而收获并不理想。直到成为探险者之后，在一场场生死战斗中，我才感觉到了明显的进步。"
  },
  [85051212] = {
    id = 85051212,
    name = "深渊中的危险远比人们所描述的更加可怕，但和大家在一起，我便觉得无论怎样的危险也无需畏惧。"
  },
  [85051213] = {
    id = 85051213,
    name = "我在探险者学院学习的时间并不算长，但那段经历，在我成为探险者后发挥了极大的作用。"
  },
  [85051214] = {
    id = 85051214,
    name = "一个人无论怎样强大，所能做到的事终究有限，在这个变幻莫测的深渊中，值得信赖的同伴才是最可靠的存在。"
  },
  [85051215] = {
    id = 85051215,
    name = "多亏了大家的帮助我才能走到现在，我也想有足够的力量帮助大家，成为大家最可靠的同伴。"
  },
  [85061211] = {
    id = 85061211,
    name = "我会守护好所有同伴。"
  },
  [85071211] = {id = 85071211, name = "嘿！"},
  [85071212] = {id = 85071212, name = "呀啊！"},
  [85071213] = {id = 85071213, name = "哈！"},
  [85081211] = {
    id = 85081211,
    name = "决不后退。"
  },
  [85081212] = {
    id = 85081212,
    name = "到此为止。"
  },
  [85091211] = {
    id = 85091211,
    name = "我会清除所有阻碍！"
  },
  [85091212] = {
    id = 85091212,
    name = "见识一下我的意志吧！"
  },
  [85101211] = {id = 85101211, name = "唔啊。"},
  [85101212] = {id = 85101212, name = "欸~"},
  [85101213] = {id = 85101213, name = "呃啊。"},
  [85111211] = {
    id = 85111211,
    name = "你们、挡不住我。"
  },
  [85121211] = {
    id = 85121211,
    name = "如果......能再强一点......"
  },
  [85131211] = {
    id = 85131211,
    name = "大家都没事吧？全员平安才能算得上完美的胜利。"
  },
  [85141211] = {
    id = 85141211,
    name = "在大家安全撤离之前，我绝不会倒下。"
  },
  [85151211] = {
    id = 85151211,
    name = "今天是你的生日吗？不是？请不要拿这种事开玩笑，万一搞错了会很让人困扰的......我做了一个蛋糕，来试试吧~以前在家时，父母和弟弟的生日都是我在准备，口味应该不会太差。"
  },
  [85161211] = {
    id = 85161211,
    name = "据说在新年这天，如果能和家人朋友一起度过，接下来的一年一定会非常幸福。今天不管做任何事，我们都一起吧！"
  },
  [85171211] = {
    id = 85171211,
    name = "请问现在有空吗，来试试这个点心怎么样？——这是小时候母亲教我做的，她说在这种节日里，最美味的点心才能传达最真诚的谢意。"
  },
  [85181211] = {
    id = 85181211,
    name = "这会儿到处都在举办庆典，似乎很有趣的样子。一起去逛逛吗？我自从离家后便很少参加这种节日庆典，也不知道深渊中的庆典和地面有怎样的差别~"
  },
  [85191211] = {
    id = 85191211,
    name = "我离家之后，每年这个时候都会往家中寄送一些我现在所在地的特产，让父母知道我平安的同时也为他们送上一些特别的节日礼物。不知道今年的礼物有没有准时送到......"
  },
  [85011221] = {
    id = 85011221,
    name = "我是艾米莉，虽然还算不上精英探险者，但你可以提前以精英探险者的标准来要求我，我，我一定可以做到。"
  },
  [85021221] = {
    id = 85021221,
    name = "要成为精英探险者没有那么容易，我们今天也继续寻找线索吧。"
  },
  [85031221] = {
    id = 85031221,
    name = "现在的我确实没什么名气，但是，但是这只是现在而已！只要再给我一点时间，我一定能取得令人瞩目的功绩，让艾米莉这个名字传遍深渊。"
  },
  [85031222] = {
    id = 85031222,
    name = "故事里的主人公能遇到很多可以提升实力，获得名望的事件。我到深渊也有不短的时间了，却什么也没遇上，难道有什么地方弄错了？"
  },
  [85041221] = {
    id = 85041221,
    name = "这、这是精英探险者也会经历的吧？哈~哈~我准备好了。"
  },
  [85041222] = {
    id = 85041222,
    name = "我不是任何人的累赘，也不是任何麻烦和附庸，我是艾米莉，探险者艾米莉。"
  },
  [85041223] = {
    id = 85041223,
    name = "那些精英探险者所能做到的事，我也可以做到了，探险者艾米莉的传说，从现在开始！"
  },
  [85051221] = {
    id = 85051221,
    name = "只要是能提升实力的事，不管有多辛苦，我也一定会做好！"
  },
  [85051222] = {
    id = 85051222,
    name = "我所付出的一切努力，都是为了追上，不，是为了超越姐姐！"
  },
  [85051223] = {
    id = 85051223,
    name = "在某些人看来，我就是一个什么也做不好的笨蛋......哼，我才不会在意！我一定会取得成绩，让所有人刮目相看的。"
  },
  [85051224] = {
    id = 85051224,
    name = "有时候我会怀疑自己所做的一切是否有意义，怀疑成为精英探险者是否真的是我想要的未来。"
  },
  [85051225] = {
    id = 85051225,
    name = "每个成就非凡的探险者都有自己的道路，而非一味的追逐，可我却一直在追逐姐姐的背影......我终于明白了，现在开始我要全力寻找属于自己的未来。"
  },
  [85061221] = {
    id = 85061221,
    name = "希望这次能有特别的收获。"
  },
  [85071221] = {id = 85071221, name = "嘿！"},
  [85071222] = {id = 85071222, name = "咿呀！"},
  [85071223] = {id = 85071223, name = "哈！"},
  [85081221] = {
    id = 85081221,
    name = "别小看我。"
  },
  [85081222] = {
    id = 85081222,
    name = "放弃挣扎吧。"
  },
  [85091221] = {
    id = 85091221,
    name = "我也有值得信任的同伴。"
  },
  [85091222] = {
    id = 85091222,
    name = "胜利一定会属于我们。"
  },
  [85101221] = {id = 85101221, name = "诶~"},
  [85101222] = {id = 85101222, name = "诶呀。"},
  [85101223] = {id = 85101223, name = "呜哇~"},
  [85111221] = {
    id = 85111221,
    name = "精英探险者，绝不会轻易放弃。"
  },
  [85121221] = {
    id = 85121221,
    name = "果然......我什么也做不到......"
  },
  [85131221] = {
    id = 85131221,
    name = "这样的胜利还不足以被人传颂，得继续解决更多问题。"
  },
  [85141221] = {
    id = 85141221,
    name = "对不起......我果然就是姐姐说的那样，是个什么都做不好的笨蛋。"
  },
  [85151221] = {
    id = 85151221,
    name = "诶，今天生日？这、这么突然，什么都没有准备——就这样度过？不行。这么重要的日子，绝不能随意。请等一下，我先去做个蛋糕。"
  },
  [85161221] = {
    id = 85161221,
    name = "希望女神庇佑，今年能遇到更多提升实力、获得名望的机会......向女神祈祷是我新年时必须要做的事，受她的眷顾，这些年我虽然没有什么特别的奇遇，但一直都很顺利。"
  },
  [85171221] = {
    id = 85171221,
    name = "非常感谢你这段时间以来帮我寻找成为精英探险者的线索，如果有什么希望我做的事，请尽管开口，我、我会努力去做。"
  },
  [85181221] = {
    id = 85181221,
    name = "小时候，各种热闹的节日活动我都会和姐姐一起参加，可是稍大一些后，她就不肯再带着我，我便没有再参加过这些活动。"
  },
  [85191221] = {
    id = 85191221,
    name = "以前在这样的节日里我都会收到和姐姐一样的礼物，可是忘了从哪一次开始，我和她收到的礼物就不一样了......虽然新的礼物可能会更适合我，但是我更想要和姐姐一样的礼物。"
  },
  [85011231] = {
    id = 85011231,
    name = "我和那些普通的家伙们不一样，除了猎杀魔物的工作都不要来打扰我，不会做，也不想做。"
  },
  [85021231] = {
    id = 85021231,
    name = "来得正好，我刚把周围的魔物都清理了一遍，找个人去收拾一下现场吧。对了，建议找个胆大一点的人。"
  },
  [85031231] = {
    id = 85031231,
    name = "魔物就是魔物，无论拥有怎样的外表，怎样的性格，也无法改变它们是魔物的事实，对它们绝不能有任何怜悯。"
  },
  [85031232] = {
    id = 85031232,
    name = "冰冷的洞穴......无尽的黑暗......潮湿又灼热的空气......还有，还有母亲绝望的哭泣......只要一闭上眼，眼前就全是那个时候的场景......总有一天，我会杀尽所有魔物！所有！！"
  },
  [85041231] = {
    id = 85041231,
    name = "只要能更好的猎杀魔物，无论会付出怎样的代价，我都不会犹豫。"
  },
  [85041232] = {
    id = 85041232,
    name = "我曾差一点成为了魔物的食物，但现在，它们才是我的猎物！"
  },
  [85041233] = {
    id = 85041233,
    name = "撕碎所有的魔物，是我活着的意义，也是我现在唯一能为母亲做到的事。"
  },
  [85051231] = {
    id = 85051231,
    name = "若没有那场变故，这世上会少一个疯狂的探险者，也会少一个偏执的研究员。"
  },
  [85051232] = {
    id = 85051232,
    name = "没有比复仇更强的信念，也没有比和魔物厮杀更好的修行方式。"
  },
  [85051233] = {
    id = 85051233,
    name = "对那些侥幸从灾难中活下来的人而言，什么也做不到的活着才是最大的痛苦。"
  },
  [85051234] = {
    id = 85051234,
    name = "我准备来深渊时，父亲送给我这副他亲自打造的利爪，在这利爪上，我也能感受到他心中的痛苦与愤怒。"
  },
  [85051235] = {
    id = 85051235,
    name = "母亲大人，我错了吗？不会错的吧？在那最后一刻，你一定也希望能有人为你复仇吧......"
  },
  [85061231] = {
    id = 85061231,
    name = "我已经等不急了。"
  },
  [85071231] = {id = 85071231, name = "呀哈！"},
  [85071232] = {id = 85071232, name = "嘿咿！"},
  [85071233] = {id = 85071233, name = "哈呀！"},
  [85081231] = {id = 85081231, name = "去死！"},
  [85081232] = {
    id = 85081232,
    name = "撕碎你！"
  },
  [85091231] = {
    id = 85091231,
    name = "在恐惧中挣扎吧。"
  },
  [85091232] = {
    id = 85091232,
    name = "被撕碎是你们唯一的宿命。"
  },
  [85101231] = {id = 85101231, name = "呃啊-"},
  [85101232] = {id = 85101232, name = "呃。"},
  [85101233] = {id = 85101233, name = "呀啊。"},
  [85111231] = {
    id = 85111231,
    name = "熟悉的味道——"
  },
  [85121231] = {
    id = 85121231,
    name = "也算是......一种解脱......"
  },
  [85131231] = {
    id = 85131231,
    name = "不堪一击，这种程度的猎物可满足不了我。"
  },
  [85141231] = {
    id = 85141231,
    name = "放开我，就算死我也要拉它们一起——"
  },
  [85151231] = {
    id = 85151231,
    name = "生日？呵~也算是个难得的日子，一起去找个大猎物庆祝一下，目标随你选——领主级？我很期待，不过如果明年还想过生日，最好换一个。"
  },
  [85161231] = {
    id = 85161231,
    name = "大家都很享受新年嘛，真是不错~我也去找几个大家伙玩玩——别阻拦我，这种日子我对魔物的憎恨会更强烈，如果不宣泄出来，我也不知道自己会做出什么事情。"
  },
  [85171231] = {
    id = 85171231,
    name = "感谢的日子，呵~如果是以前，或许你可以期待一下我亲手制作的点心，但现在，我的双手都已被这利爪禁锢，除了猎杀魔物，什么也做不到。"
  },
  [85181231] = {
    id = 85181231,
    name = "大家都装扮得不错嘛，幽灵、巫师、魔物......呵呵，如果我不小心搞错了目标——不用紧张，人和魔物的气味完全不同，我只对真的魔物感兴趣。"
  },
  [85191231] = {
    id = 85191231,
    name = "自从那场变故之后，这样的节日对我而言已经失去了存在的意义......帮我找到新的意义？呵呵，说的真是轻松......好吧，今天我就和你一起，看看你能带我找到些什么。"
  },
  [85011241] = {
    id = 85011241,
    name = "在这里应该不会再遇到那个吵闹的家伙了吧？呼~我是探险者欧培拉，非常感谢你的邀请，请多多关照。"
  },
  [85021241] = {
    id = 85021241,
    name = "探险和商业运作在某些方面很相似，只不过商业运作失败后还有重来的机会，而探险......我们再确认一下近期的探险计划吧。"
  },
  [85031241] = {
    id = 85031241,
    name = "自由学派中大部分成员都是对深渊拥有自己独到见解或发现的探险者，而另外一些则是拥有特殊才能，同样渴求探索深渊秘密的人。"
  },
  [85031242] = {
    id = 85031242,
    name = "自由学派中有个吵闹的家伙，每次和她在一起的时候都觉得有些困扰，可是一段时间听不到她的声音，似乎又有些寂寞......"
  },
  [85041241] = {
    id = 85041241,
    name = "想要追寻深渊中的未知存在，力量是不可或缺的。"
  },
  [85041242] = {
    id = 85041242,
    name = "所谓的隐秘，便是隐藏于表象之下的真实，只有足够的严谨和细致，才能看穿那些虚伪的表象。"
  },
  [85041243] = {
    id = 85041243,
    name = "只要确定了自己的目标，就应该为之付出全力，即便最终无法实现，也绝不会因此后悔。"
  },
  [85051241] = {
    id = 85051241,
    name = "成为探险者其实并非我最初的目标，不过现在看来比起继承家族事务，还是探险者更加适合我。"
  },
  [85051242] = {
    id = 85051242,
    name = "想要追寻深渊中的未知总会遇到很多困难，虚假的情报、险恶的环境，以及凶猛的魔物。"
  },
  [85051243] = {
    id = 85051243,
    name = "同伴们在分享见闻时，偶尔也会发生争执。但无论有怎样的分歧，大家也都会在分享结束后和好。"
  },
  [85051244] = {
    id = 85051244,
    name = "力量只是追寻未知的手段，而智慧才是揭晓未知的钥匙，只有同时具备力量和智慧的人，才能发现这个世界更多的真相。"
  },
  [85051245] = {
    id = 85051245,
    name = "深渊中所隐藏的未知还有很多，无论如何追寻也难以全部揭晓，所以比起最终的答案，享受追寻的过程会更加重要。"
  },
  [85061241] = {
    id = 85061241,
    name = "准备完成，随时可以出发。"
  },
  [85071241] = {id = 85071241, name = "呵！"},
  [85071242] = {id = 85071242, name = "嘿咿！"},
  [85071243] = {id = 85071243, name = "呀啊！"},
  [85081241] = {
    id = 85081241,
    name = "别乱动。"
  },
  [85081242] = {
    id = 85081242,
    name = "瞄准——"
  },
  [85091241] = {
    id = 85091241,
    name = "能比我的箭更快吗？"
  },
  [85091242] = {
    id = 85091242,
    name = "绝不会让任何敌人逃掉。"
  },
  [85101241] = {id = 85101241, name = "唔。"},
  [85101242] = {id = 85101242, name = "呀~"},
  [85101243] = {id = 85101243, name = "呃啊。"},
  [85111241] = {
    id = 85111241,
    name = "没事，这种麻烦不算什么。"
  },
  [85121241] = {
    id = 85121241,
    name = "侥幸，终会断送一切......"
  },
  [85131241] = {
    id = 85131241,
    name = "人员、物资......战损、缴获......嗯，怎么算都是一场完胜。"
  },
  [85141241] = {
    id = 85141241,
    name = "如此周全的准备，也无法应付那些狡猾的对手吗......"
  },
  [85151241] = {
    id = 85151241,
    name = "探险途中确实无法安心享受生日，但这绝不是随便对待的理由。我会想办法筹备一些物资，今天的行动结束后一起庆祝吧。"
  },
  [85161241] = {
    id = 85161241,
    name = "学派每年都会举办“新年茶会”，这天往往是人最多、也是情报交流最多的一天，一起去吗？我觉得应该能收获一些你感兴趣的线索。"
  },
  [85171241] = {
    id = 85171241,
    name = "这束花好看吗？这是我一早去采摘的，据说这种花的花语代表着最真挚的感谢......它和今天的节日很相配吧？送给你。谢谢你长久以来的关照！"
  },
  [85181241] = {
    id = 85181241,
    name = "小时候，我虽然渴望参加这样热闹的庆典，但是为了追上姐姐我会放弃所有休息时间。现在和大家一起尽情享受节日后，我才发现自己错过了多少美好和快乐，今后我要更加努力找回来才行!"
  },
  [85191241] = {
    id = 85191241,
    name = "这种节日里，自由学派的成员也会相互交换礼物，不过我主要负责礼物的接收和寄送，确认参与人员之类的工作则是由其他人在负责。"
  },
  [85011251] = {
    id = 85011251,
    name = "你好，我是卡莎，那个，该怎么说呢......我想成为一名优秀的探险者，为此做什么都行，大概，大概就是这样。"
  },
  [85021251] = {
    id = 85021251,
    name = "..... .....你，你好。\n（呼~说出来了！今天有好好打招呼，离优秀的探险者又近了一步）"
  },
  [85031251] = {
    id = 85031251,
    name = "差不多到“冥想”的时间了，这是祖父传授我的一种修行方式，可以摒除杂念，集中注意力。\n（应该没说错话吧，好紧张......）"
  },
  [85031252] = {
    id = 85031252,
    name = "呵呵呵~今天的天气不错嘛。\n（祖父说如果找不到话题可以先谈论天气，可是为什么感觉更尴尬了？——啊，天气这么糟，惨了，我都在说些什么......）"
  },
  [85041251] = {
    id = 85041251,
    name = "我的父辈都是优秀的探险者，所以我也想要成为和他们一样优秀的人。"
  },
  [85041252] = {
    id = 85041252,
    name = "握住这柄长枪，我便能感受到无比的平静，心中也不会再有任何犹豫和畏惧。"
  },
  [85041253] = {
    id = 85041253,
    name = "我能感受到自己的成长，可是除了力量，不管哪方面，距离优秀都还有很大的差距。"
  },
  [85051251] = {
    id = 85051251,
    name = "（快想快想，这种时候该说点什么，唔，之前明明想好了。快说点什么吧，什么都行，不然好尴尬，啊，感谢，感谢的话）\n......谢谢。"
  },
  [85051252] = {
    id = 85051252,
    name = "这种程度的进步根本不算什么。\n（被夸奖时应该这样说吧......为什么大家说话可以那么轻松，我也好想能做到。）"
  },
  [85051253] = {
    id = 85051253,
    name = "不管做事、说话之前都要考虑清楚，这样才算得上优秀。\n（终于把自己的想法说出来了，呼~）"
  },
  [85051254] = {
    id = 85051254,
    name = "我想和大家一样，能从容不迫的战斗、交流......可是我只有在战斗时，才能不去考虑多余的事情。\n（感觉已经没有那么紧张了，加油。）"
  },
  [85051255] = {
    id = 85051255,
    name = "其实，我并非不想或不愿搭理别人，只是，常常在我想好要怎么表达后，一切都已经结束了。"
  },
  [85061251] = {
    id = 85061251,
    name = "如果只是战斗的话......我能做到。"
  },
  [85071251] = {id = 85071251, name = "嘿！"},
  [85071252] = {id = 85071252, name = "呀！"},
  [85071253] = {id = 85071253, name = "哈！"},
  [85081251] = {
    id = 85081251,
    name = "逃不掉！"
  },
  [85081252] = {
    id = 85081252,
    name = "有破绽！"
  },
  [85091251] = {
    id = 85091251,
    name = "已经没有机会了。"
  },
  [85091252] = {
    id = 85091252,
    name = "于此，献上终结。"
  },
  [85101251] = {id = 85101251, name = "呃。"},
  [85101252] = {id = 85101252, name = "呃啊~"},
  [85101253] = {id = 85101253, name = "唔呃-"},
  [85111251] = {
    id = 85111251,
    name = "别想干扰我。"
  },
  [85121251] = {
    id = 85121251,
    name = "......我似乎，分心了。"
  },
  [85131251] = {
    id = 85131251,
    name = "战斗不就是握紧武器，然后将一切交给身体么？\n（大家的表情好奇怪，难道我说了奇怪的话么？）"
  },
  [85141251] = {
    id = 85141251,
    name = "考虑得太多，反而没能把握好机会......"
  },
  [85151251] = {
    id = 85151251,
    name = "生日快乐。\n（很轻松就把礼物送出去了，做的不错！不过会不会说的太简单了......嗯，嗯，毕竟是优秀的探险者嘛，就应该是这样才对！）"
  },
  [85161251] = {
    id = 85161251,
    name = "新年快乐，今天有时间吧？不不不，那个、我的意思是如果有时间，可以一起去参加庆典吗？\n（明明已经练习了好多次，结果说出口还是紧张了......）"
  },
  [85171251] = {
    id = 85171251,
    name = "我做了些饼干，要试试么？\n（竟然真的吃了！糟了，忘了自己先尝尝，会不会太甜了，也忘了说感谢的话......完全没做好，明明准备了那么久......）"
  },
  [85181251] = {
    id = 85181251,
    name = "这种节日有些无聊啊~\n（好像说了很帅气的话！可是，好想和大家一起去巡游......但那样就没有优秀探险者的样子了，忍耐忍耐......）"
  },
  [85191251] = {
    id = 85191251,
    name = "由我来帮忙派发礼物么？\n（对优秀的探险者而言，承担派发礼物之类的工作是应该的吧，可是，要和那么多人说话......只能硬着头皮上了吗......）"
  },
  [85011261] = {
    id = 85011261,
    name = "我是杰西卡，还只能算得上新人，非常感谢您能同意我的申请，我会努力跟上大家的进度。"
  },
  [85021261] = {
    id = 85021261,
    name = "我的修行计划还差一点，今天的探险行动可以稍微等我一下吗？"
  },
  [85031261] = {
    id = 85031261,
    name = "人们常说，深渊是充满希望和奇迹的世界，每个人都能在这里找到属于自己的人生，我也可以吗......"
  },
  [85031262] = {
    id = 85031262,
    name = "我很羡慕大家能知道自己所追寻的事物，我虽然每天都在努力，但那只是为了能跟上大家行动的步伐，我其实并不明白自己这样做的意义。"
  },
  [85041261] = {
    id = 85041261,
    name = "对不起，我的进步太慢让您担心了——嗯，不是这样？"
  },
  [85041262] = {
    id = 85041262,
    name = "这样一来，我也有了独当一面的自信，请、请期待我的表现！"
  },
  [85041263] = {
    id = 85041263,
    name = "对我而言，努力是最容易做到的事，如果，如果我能找到努力的意义，或许会有更多收获。"
  },
  [85051261] = {
    id = 85051261,
    name = "其实我并不清楚成为探险者是否是自己真正的愿望，只是在什么也做不到的时候，遇到了成为探险者的契机。"
  },
  [85051262] = {
    id = 85051262,
    name = "作为探险者，我的天赋并不出众，所以只有付出比别人更多的努力，才能在这个世界生存下来。"
  },
  [85051263] = {
    id = 85051263,
    name = "战斗，是我现在唯一能做到的事，除了努力修行，我也不知道自己平时应该做些什么。"
  },
  [85051264] = {
    id = 85051264,
    name = "重复去做同一件事，我并不会觉得枯燥，只要是能通过“重复”做到的事，我都会做到极致。"
  },
  [85051265] = {
    id = 85051265,
    name = "虽然我还没有找到自己努力的意义，但我的内心告诉我现在所做的一切都是正确的，或许再有一些时日，我便能知道自己所渴求的存在。"
  },
  [85061261] = {
    id = 85061261,
    name = "让大家久等了。"
  },
  [85071261] = {id = 85071261, name = "咿呀！"},
  [85071262] = {id = 85071262, name = "哈！"},
  [85071263] = {id = 85071263, name = "嘿！"},
  [85081261] = {
    id = 85081261,
    name = "难不倒我。"
  },
  [85081262] = {
    id = 85081262,
    name = "接招吧！"
  },
  [85091261] = {
    id = 85091261,
    name = "我也有可以做到的事。"
  },
  [85091262] = {
    id = 85091262,
    name = "不会让你们逃掉！"
  },
  [85101261] = {id = 85101261, name = "嗯啊-"},
  [85101262] = {id = 85101262, name = "呃~"},
  [85101263] = {id = 85101263, name = "呃啊！"},
  [85111261] = {
    id = 85111261,
    name = "大家都在战斗，我也不能退缩！"
  },
  [85121261] = {
    id = 85121261,
    name = "什么也......做不到......"
  },
  [85131261] = {
    id = 85131261,
    name = "这段时间的努力没有白费，我也能跟上大家的步伐了。"
  },
  [85141261] = {
    id = 85141261,
    name = "我没能配合好大家的行动，抱歉......"
  },
  [85151261] = {
    id = 85151261,
    name = "请问今天是您的生日么？抱歉，我是不经意间听到的。那个，祝您生日快乐，我准备了一份生日礼物，希望您能喜欢。"
  },
  [85161261] = {
    id = 85161261,
    name = "对我来说，新年意味着全新的开始，无论之前遭受了多少挫折磨难，在这一天里我都会告诉自己已经结束了，然后鼓起勇气继续前行。"
  },
  [85171261] = {
    id = 85171261,
    name = "那个，我、我做了一些点心，请问您可以收下么？我也想趁着这样的节日，做些力所能及事感谢您对我的关照。当然，我知道这远远不够，我也会更努力回应您的期待。"
  },
  [85181261] = {
    id = 85181261,
    name = "我从小就羡慕那些在节日里身着盛装参加巡游的孩子，但我家里非常贫困......所以在那种时候我会非常渴望长大，渴望有钱穿上那些新奇的节日服装。"
  },
  [85191261] = {
    id = 85191261,
    name = "探险队的事务我已经处理完毕了，您只需要确认一下就好，今天请好好享受节日吧——欸，不用休息？不，那可不行，在这么重要日子里好好休息，也是一名优秀的队长该做的事儿。"
  },
  [85011271] = {
    id = 85011271,
    name = "感到荣幸吧，最优秀的探险者姬玛接受了你的邀请，希望你的表现也能配得上我的实力。"
  },
  [85021271] = {
    id = 85021271,
    name = "接下来的这些行动都可以围绕我来布置作战计划，不管同行成员的实力如何，我都能轻松搞定。"
  },
  [85031271] = {
    id = 85031271,
    name = "我已经到过许多地方，但依然没有西比尔的消息，以她的实力不应该那么默默无名才对，难道......不！我都能轻松应对的危机，她肯定也没问题！"
  },
  [85031272] = {
    id = 85031272,
    name = "和那些传奇探险者相比，无论是名气还是功绩我现在都远远比不上，不过我还有足够的时间，只要继续努力总有一天可以超越他们！"
  },
  [85041271] = {
    id = 85041271,
    name = "不管在哪，只要有足够的实力，就能获得足够的认可和名气。"
  },
  [85041272] = {
    id = 85041272,
    name = "在亲手击败西比尔之前，我会努力变得足够优秀，成为比任何人都厉害的探险者。"
  },
  [85041273] = {
    id = 85041273,
    name = "现在的我、有自信不会输给任何人，无论怎样的传奇我都会超越给你看！"
  },
  [85051271] = {
    id = 85051271,
    name = "西比尔是我的朋、不、是我的宿敌！必须亲手击败的宿敌！我来深渊便是为了找到她，然后击败她！"
  },
  [85051272] = {
    id = 85051272,
    name = "真正强大的人根本不会在意别人的看法，我们只需要按照自己的意志行动就足够了。"
  },
  [85051273] = {
    id = 85051273,
    name = "我和西比尔第一次交手时输的很惨，但那是因为她比我修行更久，所以并不算什么。以我现在的实力，再交手我一定不会输！"
  },
  [85051274] = {
    id = 85051274,
    name = "虽然成为探险者并非我最初的理想，但只要是我自己决定事，我就一定会全力做到最好！"
  },
  [85051275] = {
    id = 85051275,
    name = "只要坚持下去，我的名字一定能很快传遍深渊！呵呵，当西比尔发现我更晚来深渊、名气却比她还大的时候，会有怎样的反应呢？"
  },
  [85061271] = {
    id = 85061271,
    name = "把最强的交给我来对付！"
  },
  [85071271] = {id = 85071271, name = "哈！"},
  [85071272] = {id = 85071272, name = "嘿呀！"},
  [85071273] = {id = 85071273, name = "呀啊！"},
  [85081271] = {
    id = 85081271,
    name = "乖乖投降吧！"
  },
  [85081272] = {
    id = 85081272,
    name = "尝尝我的厉害！"
  },
  [85091271] = {
    id = 85091271,
    name = "我可不会手下留情，觉悟吧！"
  },
  [85091272] = {
    id = 85091272,
    name = "不管怎样挣扎也没用。"
  },
  [85101271] = {id = 85101271, name = "呜哇。"},
  [85101272] = {id = 85101272, name = "唔。"},
  [85101273] = {id = 85101273, name = "呀啊。"},
  [85111271] = {
    id = 85111271,
    name = "不过如此，我、我才不会认输。"
  },
  [85121271] = {
    id = 85121271,
    name = "决斗......无法完成了吗......"
  },
  [85131271] = {
    id = 85131271,
    name = "都是些不堪一击的对手，能被如此优秀的探险者击败是他们的荣幸~"
  },
  [85141271] = {
    id = 85141271,
    name = "怎么会......可恶！我才不会输！不会输！"
  },
  [85151271] = {
    id = 85151271,
    name = "生日快乐！嗯，你那是什么表情？哼，别愣着了，跟我走吧。去哪？当然是去庆祝生日！我会带你去过一个最棒的生日，好好期待吧！"
  },
  [85161271] = {
    id = 85161271,
    name = "每个新年我家都会举办派对，邀请周围的邻居一起庆祝新年，西比尔也会和她父母一起来参加。不过她总是表现得很拘谨，完全没有享受派对的样子。"
  },
  [85171271] = {
    id = 85171271,
    name = "那个、这段时间谢谢你的关照，不管是寻找西比尔的线索，还是寻找提升名气的方法，你都帮了不少忙......总、总之各种事都非常感谢。"
  },
  [85181271] = {
    id = 85181271,
    name = "这种幽灵的节日为什么大家要去外面游玩，明明呆在家里才是最好的吧？！我、我并不是害怕幽灵什么的，只要有足够的实力，不管幽灵还是什么都能轻松对付！大概。"
  },
  [85191271] = {
    id = 85191271,
    name = "这个发卡是西比尔临走前送给我的，我本来准备在那年的这个时候给她回礼，结果......哼，明明礼物都准备好了......我一定会找到她，堂堂正正的打败她之后，再把礼物送出去！"
  },
  [85011281] = {
    id = 85011281,
    name = "真理之钥，岚，我和那些普通的探险者不一样，如果没有重要的事请别打扰我。"
  },
  [85021281] = {
    id = 85021281,
    name = "准备出发的时候叫我就行，我会趁这段时间再做一些练习。休息？对我而言除了必要的睡觉时间，每一分钟都不能浪费。"
  },
  [85031281] = {
    id = 85031281,
    name = "如果能实现真理之钥的目标，我自然能成为传奇人物，无论地面还是深渊，都将传颂我们的名字。进行得怎样？很、很顺利，我们只要向着目标全力以赴肯定没问题！"
  },
  [85031282] = {
    id = 85031282,
    name = "对我而言没有什么比振兴家族更重要，所以加入真理之钥并非什么兴趣......最多、最多就一点点，但那也只是为了能更快成长，成为传奇人物。"
  },
  [85041281] = {
    id = 85041281,
    name = "如果把这种提升方式公之于众或许能提升影响力......探险者的常识？我、我当然知道。"
  },
  [85041282] = {
    id = 85041282,
    name = "我绝不会错过任何提升自己的机会，只有努力变得更强，我才能以自己的方式重现家族荣光。"
  },
  [85041283] = {
    id = 85041283,
    name = "不用付出任何代价便能获得好处，这种事我完全不信，所以有什么事尽管说，我会考虑的。"
  },
  [85051281] = {
    id = 85051281,
    name = "作为淑女，应当随时注意自己的形象，而不是像某些笨蛋一样，只顾着追求快乐，什么也不管。"
  },
  [85051282] = {
    id = 85051282,
    name = "想要实现目标并不容易，现在我能做的，便是将每件事都做到极致。"
  },
  [85051283] = {
    id = 85051283,
    name = "如果没有足够坚定的信念，很容易在追寻力量的过程中迷失自我。"
  },
  [85051284] = {
    id = 85051284,
    name = "深渊确实是个凶险的世界，但也因此隔绝了许多地面上的闲言碎语，我在这里不管做什么事都能更加专注。"
  },
  [85051285] = {
    id = 85051285,
    name = "父母常说的那种“满足”我或许已经有体会了，但我并不打算停下，如果能和大家一起见证目标实现，一定会更令人“满足”。"
  },
  [85061281] = {
    id = 85061281,
    name = "练习便是为了这一刻。"
  },
  [85071281] = {id = 85071281, name = "喝！"},
  [85071282] = {id = 85071282, name = "呀啊！"},
  [85071283] = {id = 85071283, name = "嘿！"},
  [85081281] = {
    id = 85081281,
    name = "放弃抵抗吧。"
  },
  [85081282] = {
    id = 85081282,
    name = "饶不了你！"
  },
  [85091281] = {
    id = 85091281,
    name = "我的剑，绝不会犹豫！"
  },
  [85091282] = {
    id = 85091282,
    name = "现在才想逃，已经晚了。"
  },
  [85101281] = {id = 85101281, name = "咿呀。"},
  [85101282] = {id = 85101282, name = "呃。"},
  [85101283] = {id = 85101283, name = "呃啊。"},
  [85111281] = {
    id = 85111281,
    name = "不过如此，我才不会畏惧。"
  },
  [85121281] = {
    id = 85121281,
    name = "怎么会......修行还不够吗......"
  },
  [85131281] = {
    id = 85131281,
    name = "都是意料之中的结果，并没有什么值得庆祝的地方。"
  },
  [85141281] = {
    id = 85141281,
    name = "可恶，连这样的对手都解决不了，练习必须加倍才行。"
  },
  [85151281] = {
    id = 85151281,
    name = "生日是今天吧？我想再确认一下。我已经通知大家了，她们应该都快到了。做什么？当然是庆祝生日，只有我们两的话会、会有些无聊吧？"
  },
  [85161281] = {
    id = 85161281,
    name = "每逢新年我也会和朋友们一起外出逛街......怎么，很奇怪吗？虽然因此休息了一天，但也了解了很多修行之外的趣事，并不算浪费时间。"
  },
  [85171281] = {
    id = 85171281,
    name = "那、那个，点心......啊？！你怎么自顾自就吃起来了......请不要勉强装作很好吃的样子......我知道味道可能还差很多......当然，如果你能喜欢......"
  },
  [85181281] = {
    id = 85181281,
    name = "有些笨蛋又在吵着要去参加庆典了，真是头疼，身为淑女就应该时刻注意自己的形象才行啊......算了，我们也一起去吧。"
  },
  [85191281] = {
    id = 85191281,
    name = "我正在学习同伴们分享给我的修行感悟，你要看看吗？看不懂？呵呵，很正常。我也是经过了一段时间后才明白她们想要表达的内容。"
  },
  [85011291] = {
    id = 85011291,
    name = "咳、咳咳~我是来自圣歌的颂道使，就是你在邀请我吗？很好，既然明白我的优秀，那便为我准备些可以展现实力的任务吧。"
  },
  [85021291] = {
    id = 85021291,
    name = "能被大家信任是我的荣幸，但因此就让我负责准备工作未免太大材小用了吧？多给我安排些可以展现实力的事啊！"
  },
  [85031291] = {
    id = 85031291,
    name = "不管公会还是高塔，都是一群只会说大话的家伙，但圣歌不一样，我们可是真正为了改变深渊在努力。"
  },
  [85031292] = {
    id = 85031292,
    name = "别觉得我个子不高就小瞧我，我可是天才！小时候村里那么多孩子，就只有我被邀请学习魔法~成为探险者后，我刚到港口便接到了圣歌的邀请~怎么样，不管怎么看都很厉害吧？！"
  },
  [85041291] = {
    id = 85041291,
    name = "这算是对我的认可吗？嘿嘿~这样一来便能让更多人明白我的优秀了吧？"
  },
  [85041292] = {
    id = 85041292,
    name = "和那些冥顽不灵的恶徒讲道理只是浪费口舌，绝对的实力才能让他们乖乖听话。"
  },
  [85041293] = {
    id = 85041293,
    name = "如果我的努力能为这个世界带来足够的变化，那么我一定可以成为最受瞩目的存在！"
  },
  [85051291] = {
    id = 85051291,
    name = "我所肩负的是改变深渊的艰巨使命，如果不是那种可以带来深远影响的事情，我很难展现自己的全力。"
  },
  [85051292] = {
    id = 85051292,
    name = "比起其他探险者，我的打扮已经如此特别了，可还是时常被人忽视，果然还是要再长高一点才行啊......"
  },
  [85051293] = {
    id = 85051293,
    name = "和大家相比我的个子确实不高，但那不算什么，真正的强大在于思想和信念！而且，我还在成长期，只要再等一段时间一定会有所变化。"
  },
  [85051294] = {
    id = 85051294,
    name = "大家都很和善，对我也很关照，可是、可是如果能不把我当作小孩子对待就更好了。"
  },
  [85051295] = {
    id = 85051295,
    name = "我一直按照自己的正义在行动，可是却并未给深渊带来什么明显的变化。或许、今后应该改变一下思路，多做些让人无法忽略的大事才行！"
  },
  [85061291] = {
    id = 85061291,
    name = "终于有重要的事了吗？"
  },
  [85071291] = {id = 85071291, name = "喝呃！"},
  [85071292] = {id = 85071292, name = "哈！"},
  [85071293] = {id = 85071293, name = "嘿咿！"},
  [85081291] = {
    id = 85081291,
    name = "太大意了！"
  },
  [85081292] = {
    id = 85081292,
    name = "别小瞧我！"
  },
  [85091291] = {
    id = 85091291,
    name = "见识一下我真正的实力。"
  },
  [85091292] = {
    id = 85091292,
    name = "没有什么可以难倒我！"
  },
  [85101291] = {id = 85101291, name = "呀啊。"},
  [85101292] = {id = 85101292, name = "呃呃。"},
  [85101293] = {id = 85101293, name = "呜啊。"},
  [85111291] = {
    id = 85111291,
    name = "太过分了，饶不了你！"
  },
  [85121291] = {
    id = 85121291,
    name = "呜呜......我还有好多事没做......"
  },
  [85131291] = {
    id = 85131291,
    name = "怎么样，我的表现还不错吧？对付这样的敌人，根本用不着全力~"
  },
  [85141291] = {
    id = 85141291,
    name = "可恶的家伙，下次我绝不会放过他们！"
  },
  [85151291] = {
    id = 85151291,
    name = "每个人在自己生日那天，都应该成为最受瞩目的存在。今天是你生日，我会努力让所有人都关注你，尽量任何事都听你的。当然，只是今天哦！"
  },
  [85161291] = {
    id = 85161291,
    name = "我看起来有稍微长高一点吗？没变化？唉~等下参加聚会时肯定又会被说“过了这么久还是老样子”之类的......你陪我一起去吧，至少这样能让我看起来显得更成熟一些。"
  },
  [85171291] = {
    id = 85171291,
    name = "给，这是我自己做的点心。味道不错？那、那是理所当然的，我从小就跟村子里的人学了很多事情，区区点心根本算不上什么。"
  },
  [85181291] = {
    id = 85181291,
    name = "准备好一起去参加节日庆典了吗？我每次去参加都会收到许多糖果，但其他人却往往一无所获，果然我的人气已经在不知不觉中提高了很多吧？！不知道今年会有怎样的收获呢，哈哈哈~"
  },
  [85191291] = {
    id = 85191291,
    name = "每年这个节日我们都会向大家派发物资，这可是提升名气的好机会，所以今年我争取到了最多的派发数量！......可以帮帮我吗？今天要派送的数量实在太多，已经快来不及了......"
  },
  [85011301] = {
    id = 85011301,
    name = "我是荒野游骑兵的骑士、云雀，虽然还只是见习骑士，但我很强的，所以不管什么事都可以让我帮忙！"
  },
  [85021301] = {
    id = 85021301,
    name = "我们今天去哪呢，要不要去更远的地方看看？再走远一点说不定就能发现什么好地方！"
  },
  [85031301] = {
    id = 85031301,
    name = "追寻宝物的过程并不轻松，但也没有想象的那么困难。只要能保持永不放弃的信念和积极乐观的心态，一定能有所收获。"
  },
  [85031302] = {
    id = 85031302,
    name = "荒野游骑兵中的每个成员都拥有骑士长给予的骑士封号，因为我历练不够，所以目前还只是见习骑士。嗯，她什么时候才会给我封号呢，真想要一个听起来就很厉害的~"
  },
  [85041301] = {
    id = 85041301,
    name = "每一个重要时刻，都需要背诵骑士律令！律令六，绝不觊觎任何有主的宝物。"
  },
  [85041302] = {
    id = 85041302,
    name = "这样的实力提升只要再多经历几次，我就一定能拥有属于我的骑士封号！"
  },
  [85041303] = {
    id = 85041303,
    name = "同伴们曾答应我，只要我变强就告诉我一些宝物的线索，以我现在的实力应该足够了吧！"
  },
  [85051301] = {
    id = 85051301,
    name = "祖父曾说过“深渊中遍地都是宝物”，现在已经探索过的地方宝物肯定都被大家捡走了，所以得去找没人探索过地方才行。"
  },
  [85051302] = {
    id = 85051302,
    name = "如果没有足够强大的力量，即便掌握了宝物的线索也很难得到它们。"
  },
  [85051303] = {
    id = 85051303,
    name = "寻找宝物的目的？我从没想过这样的问题，是啊，为什么呢？嗯......啊，我知道了，因为那是宝物，所以才要寻找！"
  },
  [85051304] = {
    id = 85051304,
    name = "故事的主人公总是在经历危险后获得丰厚的收获，危险啊......我到目前为止遇到的最大危险也就是和骑士长相遇那次了，结果还被她轻松解决......"
  },
  [85051305] = {
    id = 85051305,
    name = "真的会有“遍地都是宝物”的地方吗......不，祖父不会骗我，现在有这么多同伴一起努力，我一定会找到那个地方！"
  },
  [85061301] = {
    id = 85061301,
    name = "见习骑士、云雀，准备完毕。"
  },
  [85071301] = {id = 85071301, name = "呀！"},
  [85071302] = {id = 85071302, name = "嘿！"},
  [85071303] = {id = 85071303, name = "呼。"},
  [85081301] = {
    id = 85081301,
    name = "站住站住。"
  },
  [85081302] = {
    id = 85081302,
    name = "瞄准了哦~"
  },
  [85091301] = {
    id = 85091301,
    name = "小看我的家伙，一个都逃不掉。"
  },
  [85091302] = {
    id = 85091302,
    name = "已经没有后悔的机会了！"
  },
  [85101301] = {id = 85101301, name = "唔啊！"},
  [85101302] = {id = 85101302, name = "啊~"},
  [85101303] = {id = 85101303, name = "呃啊！"},
  [85111301] = {
    id = 85111301,
    name = "我才不怕......呜，好痛啊！"
  },
  [85121301] = {
    id = 85121301,
    name = "呜~还没有......找到那个地方...... "
  },
  [85131301] = {
    id = 85131301,
    name = "这样的对手根本不用封号骑士出手，我就能轻松解决！"
  },
  [85141301] = {
    id = 85141301,
    name = "等我成为封号骑士，一定会找回来！"
  },
  [85151301] = {
    id = 85151301,
    name = "生日快乐！嘿嘿~我准备了一个很多种口味的蛋糕，一起吃吧~啊，不对，要先许愿才行！祖父说过，在生日那天许下的愿望都会实现！"
  },
  [85161301] = {
    id = 85161301,
    name = "啊，又到新年了吗？！怎么办怎么办，我去年没有找到任何宝物，庆祝会上要怎么和大家说啊......要不你陪我一起去吧，好不好？"
  },
  [85171301] = {
    id = 85171301,
    name = "嘿嘿，为了感谢你对云雀的关照，我准备了一份超级特殊的礼物哦——藏宝图！这是我花光所有积蓄从黑市买来的，老板说绝对保真，以后要一起去哦！"
  },
  [85181301] = {
    id = 85181301,
    name = "我每年准备的恶作剧都吓不到人，反而经常被吓到，如果能想到些什么厉害的就好了......啊！今年我们一起恶作剧吧，这样一定可以赢过其他人！"
  },
  [85191301] = {
    id = 85191301,
    name = "我们庆祝这种节日的方式就是为彼此做一件事，队长有什么想要云雀做的吗？不管什么事都行，仅限今天哦！"
  },
  [85011311] = {
    id = 85011311,
    name = "我是来自深渊航线的辉夜，应您的邀约而来，从今天起将驻扎在您的探险队，为您提供全方位的探险支援服务。"
  },
  [85021311] = {
    id = 85021311,
    name = "近期的探险行程涉及到了几处比较危险的区域，我提议针对这些区域，制定一些更加完备的应对计划。"
  },
  [85031311] = {
    id = 85031311,
    name = "若我不曾见识过深渊的残酷、人心的阴暗，便不会有现在这样渴望守护安宁、守护善良和正义的决心。而正是这样的决心，让我选择了深渊航线。"
  },
  [85031312] = {
    id = 85031312,
    name = "深渊航线的行事准则之一便是“不得窥探客人的任何隐私”，任何违背之人都会受到组织的严惩。所以不管任何行动，我只需要知道自己的任务即可。"
  },
  [85041311] = {
    id = 85041311,
    name = "即便深渊中充斥着太多残酷的事，但依然有值得我们全力以赴的美好和希望。"
  },
  [85041312] = {
    id = 85041312,
    name = "守护，是我的任务，也是我的使命，为此，就算付出生命，我也在所不惜。"
  },
  [85041313] = {
    id = 85041313,
    name = "以我之剑，斩破长夜，以我之盾，护卫光明。——这便是，我的意志和信念！"
  },
  [85051311] = {
    id = 85051311,
    name = "对我而言，最难对付的敌人并非是凶猛的魔物，那些阴险狡诈、笑里藏刀的探险者才是最可怕的存在。"
  },
  [85051312] = {
    id = 85051312,
    name = "深渊中从事护卫支援事务的组织有很多，但像深渊航线一样拥有自己道德底线的却很少。"
  },
  [85051313] = {
    id = 85051313,
    name = "组织中的每个人都有各自的追求，但不管怎样的追求，在守护深渊秩序和正义这一点上，我们都一样。"
  },
  [85051314] = {
    id = 85051314,
    name = "我的父亲被利益熏心的友人算计永远离开了这个世界，我现在所做的一切，或许是对他最好的告慰。"
  },
  [85051315] = {
    id = 85051315,
    name = "我并不认为自己所做的一切很高尚，和那些追寻财富名望的人一样，我也只是全力追寻自己所信奉的存在而已。"
  },
  [85061311] = {
    id = 85061311,
    name = "要出发了吗？"
  },
  [85071311] = {id = 85071311, name = "哈咿！"},
  [85071312] = {id = 85071312, name = "咿啊！"},
  [85071313] = {id = 85071313, name = "嘿！"},
  [85081311] = {
    id = 85081311,
    name = "我，不会畏惧！"
  },
  [85081312] = {
    id = 85081312,
    name = "决不后退！"
  },
  [85091311] = {
    id = 85091311,
    name = "立于不败，方得全胜。"
  },
  [85091312] = {
    id = 85091312,
    name = "我的意志，绝不动摇！"
  },
  [85101311] = {id = 85101311, name = "呃。"},
  [85101312] = {id = 85101312, name = "唔呃。"},
  [85101313] = {id = 85101313, name = "呃啊。"},
  [85111311] = {
    id = 85111311,
    name = "这种情况我可经历了不少。"
  },
  [85121311] = {
    id = 85121311,
    name = "任务，要失败了吗......"
  },
  [85131311] = {
    id = 85131311,
    name = "这趟任务还算顺利，大家好好休息一下，下一次或许就没这么轻松了。"
  },
  [85141311] = {
    id = 85141311,
    name = "大家都没事吧？只要没有人员损失，我们就还有机会。"
  },
  [85151311] = {
    id = 85151311,
    name = "生日快乐~嗯，很惊讶？虽然我们的合约中并没有庆祝生日的条款，但我这样做不算违规吧？呵呵，一起去享受美食吧。"
  },
  [85161311] = {
    id = 85161311,
    name = "新年快乐，我正准备去巡逻——休息？呵呵，越是这种时候越需要警惕。当然，今天的巡逻应该会很轻松，要一起吗？"
  },
  [85171311] = {
    id = 85171311,
    name = "比起武器，厨房的工具实在太难掌控了，所以就、只能这样了......虽然这些点心看起来有些发黑，但味道肯定没问题，你不会拒绝吧？"
  },
  [85181311] = {
    id = 85181311,
    name = "真是热闹的节日，不过我暂时没空享受。啊，请别误会，不是什么紧急事件，只是、只是准备和同伴贩售一些节日商品......嗯？你想和我们一起？"
  },
  [85191311] = {
    id = 85191311,
    name = "我收到了母亲寄来的礼物，嗯，她也给你捎了一份，都是我故乡的特产。她在来信中表示非常认同我现在所做的一切，希望我能为了守护更多美好而努力......我还要再努力一点，才能回应她的期待！"
  },
  [85011321] = {
    id = 85011321,
    name = "探险者白鸢应您的邀约而来，非常感谢您对我的认可，希望我们在接下来的行程中合作愉快。"
  },
  [85021321] = {
    id = 85021321,
    name = "休息结束了吗？走吧。准备？呵呵，作为曾经的预备役骑士，不用特地为我预留准备时间。"
  },
  [85031321] = {
    id = 85031321,
    name = "我自幼跟随祖父进行骑士修行，无论武技、谋略、礼仪均有所涉猎，如果没有成为探险者，我现在应该能算得上一位优秀的骑士了吧？不过对我而言，无论成为怎样优秀的骑士也不会比现在更让我感到满足。"
  },
  [85031322] = {
    id = 85031322,
    name = "深渊固然残酷，但蕴藏着无数种可能性，它赋予了每一个探险者平等的机会，只要竭尽全力，任何人都可能在这里找到自己想要的一切。"
  },
  [85041321] = {
    id = 85041321,
    name = "不管对自己的实力有多么自信也绝不能懈怠，没有人知道下一刻会面对怎样的危险。"
  },
  [85041322] = {
    id = 85041322,
    name = "曾经，我的剑为了骑士的荣耀而挥舞，但现在，我只想为了自己的理想拼尽全力！"
  },
  [85041323] = {
    id = 85041323,
    name = "信念才是我们最强大的力量，若能拥有足够坚定的信念，无论面对怎样的困难都能无坚不摧。"
  },
  [85051321] = {
    id = 85051321,
    name = "最初我来深渊是为了完成最后的历练，然而我却在历练结束后选择了留下......那是我第一次违背约定......"
  },
  [85051322] = {
    id = 85051322,
    name = "我并不喜欢战斗，但很多时候根本没有选择的机会。所以每一次必须战斗时，我都会做好觉悟，全力以赴！"
  },
  [85051323] = {
    id = 85051323,
    name = "有人说我舍弃了骑士的荣耀，他们说的没错，但也不算全对。因为如果没有足够的信念，背负那样的荣耀只会为它蒙羞。"
  },
  [85051324] = {
    id = 85051324,
    name = "我们的人生和这个变换莫测的深渊非常相似，没有人知道前路会是怎样，不过不管是坎坷还是坦途，都只有前行的人才能知晓。"
  },
  [85051325] = {
    id = 85051325,
    name = "深渊中的种种经历，让我原本有些迷茫的内心变得更加动摇，不由得产生了想要自己决定未来的想法，所以这一次、我想为了自己选择的未来而努力。"
  },
  [85061321] = {
    id = 85061321,
    name = "我会速战速决。"
  },
  [85071321] = {id = 85071321, name = "哈啊！"},
  [85071322] = {id = 85071322, name = "呀！"},
  [85071323] = {id = 85071323, name = "嘿诶！"},
  [85081321] = {
    id = 85081321,
    name = "挡不住我。"
  },
  [85081322] = {id = 85081322, name = "退下！"},
  [85091321] = {
    id = 85091321,
    name = "精神不朽，信念长存！"
  },
  [85091322] = {
    id = 85091322,
    name = "我们的命运、由自己掌控！"
  },
  [85101321] = {id = 85101321, name = "呃~"},
  [85101322] = {id = 85101322, name = "呃啊。"},
  [85101323] = {id = 85101323, name = "咿呃。"},
  [85111321] = {
    id = 85111321,
    name = "一点意外而已，无需在意。"
  },
  [85121321] = {
    id = 85121321,
    name = "我的选择......错了吗......"
  },
  [85131321] = {
    id = 85131321,
    name = "全力以赴是对敌人的尊重，也可以减少一些不必要的痛苦。"
  },
  [85141321] = {
    id = 85141321,
    name = "我会争取足够的时间，大家先撤！"
  },
  [85151321] = {
    id = 85151321,
    name = "那个、今天是您的生日吧？请问您有什么想要的礼物吗？对不起，因为不清楚您想要的东西，所以没有提前准备礼物......或者、或者今天行动结束后可以耽误一下吗？我们一起去挑选吧！"
  },
  [85161321] = {
    id = 85161321,
    name = "以前新年是我唯一可以休息的日子，但对我而言即便休息也不知道该做些什么，无所事事的一天反而感觉非常漫长——诶，去逛新年庆典？那个、我从来没去过，没关系吗？"
  },
  [85171321] = {
    id = 85171321,
    name = "非常感谢您至今以来的关照和教诲！......太严肃了吗？对不起，我只是听说今天是代表感谢日子，所以......下次我一定会问清楚节日礼仪。"
  },
  [85181321] = {
    id = 85181321,
    name = "到处都在举办庆典，真热闹啊~我以前非常渴望参加这种庆典，但因为必须要完成修行任务所以无法参加。来到深渊后，却又觉得自己有些格格不入，不敢一个人去，那个、可以一起去看看吗？"
  },
  [85191321] = {
    id = 85191321,
    name = "自从决定留在深渊之后，每到这样的日子我都会为祖父寄送一份礼物。或许是出于愧疚，也或许是想告诉他我还平安，但不管怎样的心情，我都没有后悔过自己所做出的选择。"
  },
  [85011331] = {
    id = 85011331,
    name = "我是安伦，非常感谢您的邀请，呵呵呵~希望在此停留期间，我们能相处愉快。"
  },
  [85021331] = {
    id = 85021331,
    name = "嗯~睡了个好觉呢。深渊中随时可能发生战斗，所以我会好好把握可以休息的每一分钟。"
  },
  [85031331] = {
    id = 85031331,
    name = "我可没有在偷懒哦，只是趁着空隙休息一下而已~而且比起忙碌，我无所事事会更好吧？大家都平安无事才是我们共同的希望。"
  },
  [85031332] = {
    id = 85031332,
    name = "被叫做“圣女大人”的时候真的很有压力呢，毕竟我可没有传闻中那种救死扶伤、只身对抗邪恶的力量，不过我也希望有一天能成为那样的人。"
  },
  [85041331] = {
    id = 85041331,
    name = "力量没有善恶，只要使用者心存善意，它便代表着救赎和希望。"
  },
  [85041332] = {
    id = 85041332,
    name = "既然被大家称作圣女大人，我也不想辜负这份信任和期待，就稍微再努力一点吧。"
  },
  [85041333] = {
    id = 85041333,
    name = "对那些陷入困境的人而言，我们的举手之劳或许便能为他们带来救赎，这份救赎也许在有朝一日能孕育出更多的善意。"
  },
  [85051331] = {
    id = 85051331,
    name = "我时常对自己说“尽力就好”，可是每次看到求助者期待的眼神时，却不知道该怎样拒绝......"
  },
  [85051332] = {
    id = 85051332,
    name = "对我而言，变强是为了能做到更多的事，没想到在获得成长后，才发现自己似乎也有了更多责任。"
  },
  [85051333] = {
    id = 85051333,
    name = "被太多人期待，有时候会觉得很累，所以在能够休息时，才要尽情享受。"
  },
  [85051334] = {
    id = 85051334,
    name = "我很喜欢现在的一切，不是为了父母，也不是为了其他什么，只是单纯的喜欢我现在所拥有的这种生活。"
  },
  [85051335] = {
    id = 85051335,
    name = "我最初只是想找个不错的探险队暂留一段时间，让自己偷懒休息一下。可是现在，似乎暂时找不到继续漂泊的理由了。"
  },
  [85061331] = {
    id = 85061331,
    name = "啊~休息时间结束了吗。"
  },
  [85071331] = {id = 85071331, name = "嘿！"},
  [85071332] = {id = 85071332, name = "喝~"},
  [85071333] = {id = 85071333, name = "呀啊~"},
  [85081331] = {
    id = 85081331,
    name = "大家，拜托了！"
  },
  [85081332] = {
    id = 85081332,
    name = "乘胜追击。"
  },
  [85091331] = {
    id = 85091331,
    name = "拯救，是我的职责！"
  },
  [85091332] = {
    id = 85091332,
    name = "我绝不会放弃任何同伴。"
  },
  [85101331] = {id = 85101331, name = "咿呃~"},
  [85101332] = {id = 85101332, name = "啊~"},
  [85101333] = {id = 85101333, name = "呜啊~"},
  [85111331] = {
    id = 85111331,
    name = "不用担心我，大家务必小心。"
  },
  [85121331] = {
    id = 85121331,
    name = "可以......安心的休息了......"
  },
  [85131331] = {
    id = 85131331,
    name = "嗯，没人受伤吧？那打扫战场就拜托大家了，呵呵~"
  },
  [85141331] = {
    id = 85141331,
    name = "伤员由我负责，大家赶快撤离。"
  },
  [85151331] = {
    id = 85151331,
    name = "生日这种日子里就该放下所有事务，安心享受美食之类的吧？嗯，一起去圈落中逛逛吧，放心，如果有紧急的事情我们赶回来也来得及。"
  },
  [85161331] = {
    id = 85161331,
    name = "最后一次和父母庆祝新年时，我们之间还发生了一点不愉快的事......没能当面道歉，果然还是有些遗憾。我现在所能做的，只有守护更多人，让他们不再经历这样的遗憾。"
  },
  [85171331] = {
    id = 85171331,
    name = "非常感谢您这段时间以来的关照，我做了些点心，请尝一下吧~这可是我牺牲了不少休息时间才完成的，请务必收下~"
  },
  [85181331] = {
    id = 85181331,
    name = "真是热闹的节日，每个人的脸上都洋溢着幸福喜悦的笑容，呵呵~趁现在还没有什么紧急事件，一起去享受节日吧。"
  },
  [85191331] = {
    id = 85191331,
    name = "能够赶在今天之前把重要的事务都处理完毕真是太好了，如此一来，我们便可以稍微放松一下，享受这份难得的安宁了。"
  },
  [85011341] = {
    id = 85011341,
    name = "战斗的事尽管交给我，只要大家还在一起行动，我都会听从你的指挥。"
  },
  [85021341] = {
    id = 85021341,
    name = "这是接下来的行程么？我没有意见。"
  },
  [85031341] = {
    id = 85031341,
    name = "我不喜欢武力，但也并不排斥战斗，你不必有什么顾虑，如果发生战斗，能多照看一下安妮斯，就算是帮大忙了。"
  },
  [85031342] = {
    id = 85031342,
    name = "我和安妮斯一起长大，保护她是我的责任。可是，我虽然能暂时阻止那些胡说八道的人一时，却无法从根本上解决问题——"
  },
  [85041341] = {
    id = 85041341,
    name = "变强，总归不是坏事。"
  },
  [85041342] = {
    id = 85041342,
    name = "只要是敌人，不管是谁，我都不会犹豫。"
  },
  [85041343] = {
    id = 85041343,
    name = "无论多么强大的力量，也无法拯救一个人的灵魂。"
  },
  [85051341] = {
    id = 85051341,
    name = "深渊中的对手，比传闻中要棘手不少。"
  },
  [85051342] = {
    id = 85051342,
    name = "团队作战并非是我擅长的领域，不过我会尝试去做。"
  },
  [85051343] = {
    id = 85051343,
    name = "信任同伴并非是一件轻松的事，总之，我会尽力。"
  },
  [85051344] = {
    id = 85051344,
    name = "无论怎样的对手，都必须全力以赴，轻敌大意是探险者的大忌。"
  },
  [85051345] = {
    id = 85051345,
    name = "顾虑太多会让人迟疑，可是若没有顾虑，又失去了前行的动力。"
  },
  [85061341] = {id = 85061341, name = "走吧。"},
  [85071341] = {id = 85071341, name = "喝啊！"},
  [85071342] = {id = 85071342, name = "嘿~"},
  [85071343] = {id = 85071343, name = "呀啊！"},
  [85081341] = {
    id = 85081341,
    name = "速战速决。"
  },
  [85081342] = {
    id = 85081342,
    name = "再快一点！"
  },
  [85091341] = {
    id = 85091341,
    name = "反抗只是徒劳。"
  },
  [85091342] = {
    id = 85091342,
    name = "差不多，该结束了。"
  },
  [85101341] = {id = 85101341, name = "呃。"},
  [85101342] = {id = 85101342, name = "呃啊。"},
  [85101343] = {id = 85101343, name = "咿呃~"},
  [85111341] = {
    id = 85111341,
    name = "还差得远。"
  },
  [85121341] = {
    id = 85121341,
    name = "顾虑，太多了么......"
  },
  [85131341] = {
    id = 85131341,
    name = "别大意，还没到完全放松的时候。"
  },
  [85141341] = {
    id = 85141341,
    name = "安妮斯，队长，你们没事吧？！"
  },
  [85151341] = {
    id = 85151341,
    name = "生日是值得纪念的日子，不管怎样今天都应该放松一下，安妮斯也烤了蛋糕，一起庆祝？"
  },
  [85161341] = {
    id = 85161341,
    name = "以前新年，我大多数时候都会和安妮斯一起度过，这种日子并不适合孤零零一个人，要一起去找她么？"
  },
  [85171341] = {
    id = 85171341,
    name = "没想到今天居然是这种日子，非常感谢你的关照。这段时间以来，不管是我还是安妮斯，都让你费了不少心思，十分感谢！"
  },
  [85181341] = {
    id = 85181341,
    name = "这种热闹的日子，我并不太喜欢，当然，也算不上讨厌，只是，有些不擅长应付而已。"
  },
  [85191341] = {
    id = 85191341,
    name = "已经这个时节了么，有点想念地面上的食物了......今晚的伙食能稍微改善一下么？"
  },
  [85011351] = {
    id = 85011351,
    name = "我叫露米娅，是一名猎人——啊，不对，用你们的话说叫探险者，今天起正式加入你的探险队，请多多关照。"
  },
  [85021351] = {
    id = 85021351,
    name = "嘘~......啪！搞定，嘿嘿~我刚在蹲守一只飞虫，这种飞虫很难对付，只能抓住它停下来的瞬间，给予致命一击才行。"
  },
  [85031351] = {
    id = 85031351,
    name = "深渊和我长大的山林在地形上有些相似，但猎物完全不同，在我们那里可完全看不到长得这么奇怪的魔物。"
  },
  [85031352] = {
    id = 85031352,
    name = "“提尔”可是我花光狩猎多年的钱换来的，我见到它的第一眼就被迷住了！它不仅可以挥砍，还能化作一张血盆大口，嗷呜一口将猎物咬碎！非常棒！"
  },
  [85041351] = {
    id = 85041351,
    name = "猎人没有固定的套路，对付不同的猎物，需要掌握不同的方法。"
  },
  [85041352] = {
    id = 85041352,
    name = "“提尔”已经迫不及待了，让我们在深渊这个猎场中，尽情狩猎吧！"
  },
  [85041353] = {
    id = 85041353,
    name = "如果没有足够的实力，“猎人”也很有可能成为“猎物”。"
  },
  [85051351] = {
    id = 85051351,
    name = "猎人和探险者差别并不大，都是对付猎物，只不过猎物的种类稍微有些不同罢了。"
  },
  [85051352] = {
    id = 85051352,
    name = "无论猎物多么弱小，也必须全力以赴，轻敌大意可是猎人的大忌！"
  },
  [85051353] = {
    id = 85051353,
    name = "我在家乡已经找不到势均力敌的猎物了，所以当得知深渊的存在后，我便对这个“新猎场”充满了期待。"
  },
  [85051354] = {
    id = 85051354,
    name = "每个猎人的狩猎技巧、惯用武器都会有不同，对我来说，没有比“提尔”更完美的武器了！"
  },
  [85051355] = {
    id = 85051355,
    name = "比起我的家乡，深渊中多了不少危险，但也拥有更多乐趣。外形奇特、能力古怪的猎物，互相支持的同伴......我非常满意现在拥有的一切！"
  },
  [85061351] = {
    id = 85061351,
    name = "狩猎开始咯~"
  },
  [85071351] = {id = 85071351, name = "嘿咿！"},
  [85071352] = {id = 85071352, name = "哈！"},
  [85071353] = {id = 85071353, name = "哈啊！"},
  [85081351] = {
    id = 85081351,
    name = "接招吧！"
  },
  [85081352] = {
    id = 85081352,
    name = "发现弱点。"
  },
  [85091351] = {
    id = 85091351,
    name = "猎物逃不出猎人的掌心。"
  },
  [85091352] = {
    id = 85091352,
    name = "优秀的猎人可不会被迷惑。"
  },
  [85101351] = {id = 85101351, name = "唔。"},
  [85101352] = {id = 85101352, name = "哇啊~"},
  [85101353] = {id = 85101353, name = "呃唔。"},
  [85111351] = {
    id = 85111351,
    name = "忍耐，是猎人的基本修行！"
  },
  [85121351] = {
    id = 85121351,
    name = "......还是......太大意了么......"
  },
  [85131351] = {
    id = 85131351,
    name = "无论如何狡猾的猎物，也总会有藏不住尾巴的时候~"
  },
  [85141351] = {
    id = 85141351,
    name = "可恶，真是狡猾的家伙，下一次绝对不会放过它！"
  },
  [85151351] = {
    id = 85151351,
    name = "诶！你说今天生日？这么重要的日子，为什么不早点告诉我呢，啊，没时间了，我去看看还有些什么食材......呼~祈祷莫妮卡小姐没有全部吃掉。"
  },
  [85161351] = {
    id = 85161351,
    name = "我的家乡在山里，道路不是很方便，所以平时大家走动很少，只有新年的时候，周围的人们才会聚集到一起，享受食物和美酒，一起庆祝新年。"
  },
  [85171351] = {
    id = 85171351,
    name = "今天是代表感谢的日子......我大概知道了，和我们那感谢山神的日子一样吧？！每到山神庆典，大家都会把最好的猎物供奉给山神，我也去把最好的猎物拿来供奉给你~"
  },
  [85181351] = {
    id = 85181351,
    name = "好热闹的节日啊，圈落里似乎多了不少穿着奇怪服饰的人——欸，节日习俗吗？！竟然还有这么奇怪的习俗，外面的世界果然比山里麻烦多了。"
  },
  [85191351] = {
    id = 85191351,
    name = "请稍等，我在清点近期捕获的猎物。在我那每到这个时节大家就会把各自捕获的猎物拿出来，分一些给那些无法捕猎的人。现在我在这里，我也要把这些猎物分一些给大家。"
  },
  [85011361] = {
    id = 85011361,
    name = "你好，我是苏西，目前是一名自由探险者，虽然还算新人，那个......那个......总之，我会努力！"
  },
  [85021361] = {
    id = 85021361,
    name = "嗯......嗯？抱、抱歉！我看书太入迷了，没注意您已经来了。"
  },
  [85031361] = {
    id = 85031361,
    name = "我第一次看到深渊奇景时，便觉得所有书本中关于它的描述都太过苍白无力。那是一种无法用言语形容、不亲眼所见便绝对无法想象的梦幻场景。"
  },
  [85031362] = {
    id = 85031362,
    name = "我喜欢书本，它们就像我最好的朋友，给我讲述着关于这个世界的一切......可是，有一些事物，如果不能亲眼见识，终究还是会觉得遗憾。"
  },
  [85041361] = {
    id = 85041361,
    name = "原、原来还有这样的方法。我没在书上看到过，稍微有一点点紧张。"
  },
  [85041362] = {
    id = 85041362,
    name = "这种感觉......就好像亲眼见到书本中所描绘的那些胜景一样。"
  },
  [85041363] = {
    id = 85041363,
    name = "只要我能坚持下去，终有一天，一定能走遍深渊的每个角落。"
  },
  [85051361] = {
    id = 85051361,
    name = "我并没有具体的探险计划，只是凭着感觉在行动，这样，果然不行吗？"
  },
  [85051362] = {
    id = 85051362,
    name = "如果不能将所学的知识加以应用，那么无论读多少书，也不会有太大的不同。"
  },
  [85051363] = {
    id = 85051363,
    name = "每个人都有憧憬的事物，虽然我憧憬的存在可能和大家不同，但这份心情一定不会输给大家。"
  },
  [85051364] = {
    id = 85051364,
    name = "虽然深渊中的景色比书本中更加壮观，可是深渊中的危险，也远远超过了书本中的记录......"
  },
  [85051365] = {
    id = 85051365,
    name = "我不知道旅途的终点，也不知道准确的方向，但并非每一件事都要弄清楚之后才能去做，那样会少了很多意义。"
  },
  [85061361] = {
    id = 85061361,
    name = "我、我明白了。"
  },
  [85071361] = {id = 85071361, name = "喝啊！"},
  [85071362] = {id = 85071362, name = "嘿~"},
  [85071363] = {id = 85071363, name = "呀啊！"},
  [85081361] = {
    id = 85081361,
    name = "不要躲开哦。"
  },
  [85081362] = {
    id = 85081362,
    name = "我会努力的。"
  },
  [85091361] = {
    id = 85091361,
    name = "用这个决胜负吧。"
  },
  [85091362] = {
    id = 85091362,
    name = "应该不会打偏吧？"
  },
  [85101361] = {id = 85101361, name = "呜哇。"},
  [85101362] = {id = 85101362, name = "呀~"},
  [85101363] = {id = 85101363, name = "呃啊。"},
  [85111361] = {
    id = 85111361,
    name = "我、我还可以继续。"
  },
  [85121361] = {
    id = 85121361,
    name = "治疗的咒语，想不起来了......"
  },
  [85131361] = {
    id = 85131361,
    name = "赢了吗？好像是赢了吧？呼~好紧张。"
  },
  [85141361] = {
    id = 85141361,
    name = "到底......是什么地方没做好呢......"
  },
  [85151361] = {
    id = 85151361,
    name = "生日是今天吗？啊，我想起来了，之前大家秘密筹备的庆祝宴会，好像就是为今天准备的惊喜——啊！不不不！请忘了我刚说的话！什么都没有！"
  },
  [85161361] = {
    id = 85161361,
    name = "关于新年的来历，书本中有很多种记录呢，各地关于新年的故事传说也不一样，不过不管是怎样的传说记录，都代表着人们对新年的美好祈愿。"
  },
  [85171361] = {
    id = 85171361,
    name = "嗯...嗯......啊，抱歉，我、我刚又走神了。我在想要怎样表达谢意，可是，完全没有头绪......要不我们一起去圈落中看看吧，说不定会有发现。"
  },
  [85181361] = {
    id = 85181361,
    name = "这个节日不管哪一本书中的记载，都是和幽灵相关的呢，为什么大家不但不怕，反而还在一起狂欢呢——我、我并没有害怕。"
  },
  [85191361] = {
    id = 85191361,
    name = "我收到的第一份圣诞礼物便是一本关于深渊传说的画集，所以大概从那时候起，我便开始向往深渊了吧。"
  },
  [85011371] = {
    id = 85011371,
    name = "我并不清楚您在向我发出邀请时是怎样的心情，认真、无聊、同情，或者纯粹发错了？不过不管怎样，能收到您的邀请我很开心。"
  },
  [85021371] = {
    id = 85021371,
    name = "我近期实战方面的训练似乎有些不足，有些地方没能完全理解，如果可以的话我希望能为我增加一些实战方面的训练。"
  },
  [85031371] = {
    id = 85031371,
    name = "我修行武技的理由并非是自己没有魔法天赋，相反，我曾被称作魔法天才。只是命运——不，是我自己太看重虚名，自作自受......"
  },
  [85031372] = {
    id = 85031372,
    name = "一些人认为我来深渊是为了追寻让自己恢复的奇迹，虽说不完全对，但也没有全错。如果说我对那种奇迹没有一点兴趣肯定是假的，只是我现在更想要珍惜当下，努力超越上一秒的自己。"
  },
  [85041371] = {
    id = 85041371,
    name = "把一件力所能及的事做到极致，便是我现在唯一能做到的事。"
  },
  [85041372] = {
    id = 85041372,
    name = "我不会再逃避，也不会再放弃，我会靠自己的努力，全力追寻属于我的未来！"
  },
  [85041373] = {
    id = 85041373,
    name = "真正的奇迹只能由自己创造，一味追寻那虚无缥缈的存在只会一事无成。"
  },
  [85051371] = {
    id = 85051371,
    name = "曾经的我肯定无法想象现在的自己，那种迷失在荣誉光环中的人是不会相信他们没有经历过的事情。"
  },
  [85051372] = {
    id = 85051372,
    name = "我刚开始修行武技时，只是抱着试试看的心态，从没想过自己能到走到这一步。"
  },
  [85051373] = {
    id = 85051373,
    name = "从我无法继续学习魔法的那一刻起，我的人生就发生了巨大变化，当时我曾一度陷入绝望，但现在我早已释然。"
  },
  [85051374] = {
    id = 85051374,
    name = "我曾无比渴望获得别人的认可，但对现在的我而言，只要相信自己就足够了。"
  },
  [85051375] = {
    id = 85051375,
    name = "如果真的存在命运，我很想感谢它给了我一个重新审视自己的机会，若非如此，恐怕我仍未从那些虚伪的谎言中醒来。"
  },
  [85061371] = {
    id = 85061371,
    name = "我会全力以赴。"
  },
  [85071371] = {id = 85071371, name = "哈啊！"},
  [85071372] = {id = 85071372, name = "嘿呀！"},
  [85071373] = {id = 85071373, name = "呀！"},
  [85081371] = {
    id = 85081371,
    name = "交给我吧。"
  },
  [85081372] = {
    id = 85081372,
    name = "别妄想了！"
  },
  [85091371] = {
    id = 85091371,
    name = "只要相信，便有可能。"
  },
  [85091372] = {
    id = 85091372,
    name = "奇迹，应该由自己创造！"
  },
  [85101371] = {id = 85101371, name = "呃啊。"},
  [85101372] = {id = 85101372, name = "啊！"},
  [85101373] = {id = 85101373, name = "呃。"},
  [85111371] = {
    id = 85111371,
    name = "我绝不会退让。"
  },
  [85121371] = {
    id = 85121371,
    name = "没能......把握好机会......"
  },
  [85131371] = {
    id = 85131371,
    name = "战斗中没有侥幸，无论胜败都是我们实力的证明。"
  },
  [85141371] = {
    id = 85141371,
    name = "一时的胜败并不代表什么，任何时候都不能轻易放弃。"
  },
  [85151371] = {
    id = 85151371,
    name = "生日啊，那得准备蛋糕才行。不，你不用阻止我，不管什么事都绝不能敷衍，必须认真对待。我去准备一下，不会等太久。"
  },
  [85161371] = {
    id = 85161371,
    name = "以前每个新年我们一家人都会非常和睦的在一起庆祝，可是从我遭遇事故后就变了......大家虽然还会在一起庆祝，但那种气氛非常尴尬，令人想要逃避。"
  },
  [85171371] = {
    id = 85171371,
    name = "已经到了这个节日了吗，在这里的每一天我都感觉很充实，完全没觉察到......还好之前有准备食材，我先去做些点心，要甜一点还是淡一点呢？"
  },
  [85181371] = {
    id = 85181371,
    name = "这种热闹的节日我一度觉得只有普通人才会去庆祝，从来不屑于参加，现在看来我当初真是错过了好多乐趣，今年不能再错过了，一起去吧~"
  },
  [85191371] = {
    id = 85191371,
    name = "我很喜欢现在这样和大家一起分享礼物，庆祝节日的感觉，这是一种我被称为“魔法天才”根本无法感受到的幸福，呵呵~所幸我明白的还不算太晚。"
  },
  [85011381] = {
    id = 85011381,
    name = "您好，我是暗夜侍者的朗姆，今天起正式加入您的探险队，有什么麻烦尽管交给我吧。"
  },
  [85021381] = {
    id = 85021381,
    name = "探险的准备我已经做好了，出发前要再休息一下吗？——给，刚冲好的红茶，小心烫。"
  },
  [85031381] = {
    id = 85031381,
    name = "只要是小姐自己决定事，她就一定会做到极致。所以她既然选择了成立暗夜侍者，那么我们总有一天会成为名扬深渊的组织。哈~我也要努力才行，绝不能成为大家的拖累。"
  },
  [85031382] = {
    id = 85031382,
    name = "在许多传说中，深渊都是一个令人向往的世界，可是来到这里才发现它并没有那么美好。不过、我相信只要和大家在一起，就一定能收获我们所渴望的一切。"
  },
  [85041381] = {
    id = 85041381,
    name = "虽然还只是见习执事，但我所能提供的服务一定会让您满意！"
  },
  [85041382] = {
    id = 85041382,
    name = "竟然可以达到这样的程度，请期待执事朗姆、不，探险者朗姆的全力吧。"
  },
  [85041383] = {
    id = 85041383,
    name = "无论是侍者的工作还是探险者的事务，我感觉现在的自己一定能做得更加完美！"
  },
  [85051381] = {
    id = 85051381,
    name = "主家对我们一家人恩重如山，所以能成为执事，为主家效力是我的荣幸。"
  },
  [85051382] = {
    id = 85051382,
    name = "我渴望成为一名优秀的侍者，也渴望成为一名优秀的探险者，所以不管遇到怎样的困难，我也绝不会畏惧。"
  },
  [85051383] = {
    id = 85051383,
    name = "小姐其实非常善良，充满了正义，我记得她刚修行不久，便四处打击盗贼匪徒，帮助弱小，受到了许多人的称赞。"
  },
  [85051384] = {
    id = 85051384,
    name = "不管以前还是现在，我所能做到的事只有一件——解决麻烦！所以我会全力以赴，把这件事做到极致！"
  },
  [85051385] = {
    id = 85051385,
    name = "如果没有小姐和主家的关照，便不会有现在的我。所以在得知小姐要来深渊时，我便已做好了觉悟——即便付出生命也要护卫她的安全！"
  },
  [85061381] = {
    id = 85061381,
    name = "请交给我吧！"
  },
  [85071381] = {id = 85071381, name = "嘿！"},
  [85071382] = {id = 85071382, name = "呀！"},
  [85071383] = {id = 85071383, name = "喝！"},
  [85081381] = {
    id = 85081381,
    name = "饶不了你。"
  },
  [85081382] = {
    id = 85081382,
    name = "乖乖放弃吧！"
  },
  [85091381] = {
    id = 85091381,
    name = "我也有、必须要做到的事。"
  },
  [85091382] = {
    id = 85091382,
    name = "请见证我的觉悟！"
  },
  [85101381] = {id = 85101381, name = "呃啊~"},
  [85101382] = {id = 85101382, name = "唔。"},
  [85101383] = {id = 85101383, name = "噫呃。"},
  [85111381] = {
    id = 85111381,
    name = "一点意外而已，不要紧。"
  },
  [85121381] = {
    id = 85121381,
    name = "我、做到了吗......"
  },
  [85131381] = {
    id = 85131381,
    name = "我的表现还不错吧？呵呵，下一次我还能做得更好！"
  },
  [85141381] = {
    id = 85141381,
    name = "明明已经做足了准备，为什么会这样......还有什么地方没做好吗......"
  },
  [85151381] = {
    id = 85151381,
    name = "请问现在有空吗？我想和您确认一下庆祝会的出席名单。呵呵，今天是您的生日吧？所以我们为您准备了一个庆祝会，您只需要确认一些必要信息就好。"
  },
  [85161381] = {
    id = 85161381,
    name = "我们正在准备新年庆典，请问您有什么特别的需求吗？我想更多的了解大家的需求，让每一个参与庆典的人都能收获幸福和快乐。"
  },
  [85171381] = {
    id = 85171381,
    name = "您拿的甜点是别人送的吗？呵呵，我也在想要不要准备一点类似的谢礼。诶？是大小姐亲手做的？！大小姐竟、竟然会做甜点，一定很美味吧？！"
  },
  [85181381] = {
    id = 85181381,
    name = "大小姐很喜欢这种热闹的节日，我还是她学伴的时候，就曾帮她欺骗过护卫。可是在我被当家发现并责罚之后，大小姐就很少再让我帮忙......虽然知道她是不想连累我，但是......"
  },
  [85191381] = {
    id = 85191381,
    name = "节日快乐~呵呵，这是主家为大家准备的礼物，每个人都有！啊，快来不及了，我得赶紧去送下一份！"
  },
  [85011391] = {
    id = 85011391,
    name = "我是弗拉克，这是我的伙伴吉米，多亏了它我才能成为探险者，嘿嘿~吉米也来打个招呼吧。"
  },
  [85021391] = {
    id = 85021391,
    name = "吉米虽然很强，但如果不好好维护，关键时候无法发挥全力就麻烦了......嗯，好了，维护完成，随时可以出发。"
  },
  [85031391] = {
    id = 85031391,
    name = "许多人都觉得我没有继承父母强大的天赋非常可惜，可是我却不这么认为，正因为我天赋普通，我才能和吉米相遇，也才能成为无比特殊的探险者。"
  },
  [85031392] = {
    id = 85031392,
    name = "吉米是我跟随维克多大师学习后制作的“全能型”魔偶，除了能辅助我战斗之外，在侦察、储物、搬运之类的工作上也拥有非常出色的表现！"
  },
  [85041391] = {
    id = 85041391,
    name = "我想到了一个新的改进方案，可以让吉米变得更强！"
  },
  [85041392] = {
    id = 85041392,
    name = "超级吉米，登场！这段时间的调整让吉米变得更加完美了，请期待我们的表现吧！"
  },
  [85041393] = {
    id = 85041393,
    name = "利用深渊的力量来强化吉米，真是天才的想法！啊，真期待啊，吉米还能再一次蜕变吗。"
  },
  [85051391] = {
    id = 85051391,
    name = "我的力量并不出色，不足以支撑我成为探险者，但有了吉米的帮助，一切都不一样了。"
  },
  [85051392] = {
    id = 85051392,
    name = "优秀的工匠会根据所处环境的变化，调整修缮自身的不足。"
  },
  [85051393] = {
    id = 85051393,
    name = "维克多大师是技术方面的天才，作为弟子我也绝不能逊色于他，我会和吉米一起证明这一点！"
  },
  [85051394] = {
    id = 85051394,
    name = "吉米拥有让普通探险者难以企及的力量，但是如果太依赖于它，也并非完全是好事。至少，对我而言。"
  },
  [85051395] = {
    id = 85051395,
    name = "无论是技术还是力量，都只是探索深渊的助力，如果沉迷其中，遗忘了自己的初心，必然会迷失方向。"
  },
  [85061391] = {
    id = 85061391,
    name = "吉米，要出发咯。"
  },
  [85071391] = {id = 85071391, name = "嘿！"},
  [85071392] = {id = 85071392, name = "呀啊！"},
  [85071393] = {id = 85071393, name = "喝咿！"},
  [85081391] = {
    id = 85081391,
    name = "别小看我。"
  },
  [85081392] = {
    id = 85081392,
    name = "交给我吧。"
  },
  [85091391] = {
    id = 85091391,
    name = "吉米，拜托你了！"
  },
  [85091392] = {
    id = 85091392,
    name = "展现力量吧，超级吉米！"
  },
  [85101391] = {id = 85101391, name = "啊！"},
  [85101392] = {id = 85101392, name = "噫呃。"},
  [85101393] = {id = 85101393, name = "唔啊。"},
  [85111391] = {
    id = 85111391,
    name = "追着不放，真难缠。"
  },
  [85121391] = {
    id = 85121391,
    name = "果然......不能只靠吉米......"
  },
  [85131391] = {
    id = 85131391,
    name = "干的漂亮，吉米，真是完美的表现！"
  },
  [85141391] = {
    id = 85141391,
    name = "吉米都无法发挥全力，难道是哪里没有维护好？"
  },
  [85151391] = {
    id = 85151391,
    name = "生日！这可是值得纪念和庆祝的一天呢，先让吉米给您跳支舞吧！嘿嘿嘿~说起来，吉米的生日也快到了呢。"
  },
  [85161391] = {
    id = 85161391,
    name = "新年啊，如果今年能想到更多改进吉米的方案就好了。离开维克多大师也有不少时间了，可是我的技术进步还是太慢，今年得更加努力才行。"
  },
  [85171391] = {
    id = 85171391,
    name = "锵锵！来尝尝这个由吉米制作的吉米外形的点心——无论是外形还是制作人员都是全世界独一无二的，送给你！"
  },
  [85181391] = {
    id = 85181391,
    name = "每次这样的节日，吉米都是最受欢迎的呢~带着它去参加巡游，小孩子们都会围绕着吉米看个不停，嘿嘿~"
  },
  [85191391] = {
    id = 85191391,
    name = "今年派发礼物的人选定好了吗，让我试试怎么样？吉米可以扮演我的驯鹿，不仅可以装载很多礼物还能跑得飞快，就和故事中一样。"
  },
  [85011401] = {
    id = 85011401,
    name = "好久不见了哥哥，呵呵~姐妹们收到哥哥的邀请，就决定比赛看谁先赶过来，我是第几个到的呢？"
  },
  [85021401] = {
    id = 85021401,
    name = "陆大叔常说“天道酬勤”，就算是哥哥也不能随便荒废时间，尤其是在深渊中，每一秒都要好好珍惜。"
  },
  [85031401] = {
    id = 85031401,
    name = "希尔负责支援，艾莉亚负责诱敌......嗯，艾莉亚战斗时可不懂得什么叫停手，还是让她负责正面对抗吧......真希望她们能好好执行作战计划啊。"
  },
  [85031402] = {
    id = 85031402,
    name = "妹妹们都还不太懂事，不管是学习还是修行都需要督促，可是大叔和遥姐都有更重要的事要做，所以暂时就由我来监督调皮的妹妹们，这样一来也能让大叔他们不会因为大家的事分心。"
  },
  [85041401] = {
    id = 85041401,
    name = "知识非常重要，但只是读书还远远不够，还要懂得如何应用。"
  },
  [85041402] = {
    id = 85041402,
    name = "书籍是赛珂忠实的朋友，不管遇到怎样的问题，它们都能给出答案。"
  },
  [85041403] = {
    id = 85041403,
    name = "没有任何事可以成为荒废自己修行的借口，身为姐姐更应该以身作则。"
  },
  [85051401] = {
    id = 85051401,
    name = "姐妹们都想要到深渊见识一番，我便和大家一起来了，呵呵~我也想亲眼见识一下这个书本中的世界。"
  },
  [85051402] = {
    id = 85051402,
    name = "姐妹们都是我重要的家人，我需要足够的力量才能守护大家。"
  },
  [85051403] = {
    id = 85051403,
    name = "身为姐姐的压力其实很大，遥姐自然不必说，希尔、艾莉亚和蕾米几个人，在一些方面早已比我做的更好。"
  },
  [85051404] = {
    id = 85051404,
    name = "大叔和遥姐经常为了魔物的事情忙碌，我也希望能有更强的实力，可以为他们再分担一些。"
  },
  [85051405] = {
    id = 85051405,
    name = "有姐妹们陪在身边，能亲眼见识书中的世界......我已经很满足了，若说还有遗憾，大概就是哥哥和大叔的伴侣了。"
  },
  [85061401] = {
    id = 85061401,
    name = "大家按计划行动。"
  },
  [85071401] = {id = 85071401, name = "嘿咿~"},
  [85071402] = {id = 85071402, name = "咿哟！"},
  [85071403] = {id = 85071403, name = "哈~"},
  [85081401] = {
    id = 85081401,
    name = "这个怎么样？"
  },
  [85081402] = {id = 85081402, name = "看好咯~"},
  [85091401] = {
    id = 85091401,
    name = "这点问题交给我！"
  },
  [85091402] = {
    id = 85091402,
    name = "别小看知识的力量！"
  },
  [85101401] = {id = 85101401, name = "唔呃！"},
  [85101402] = {id = 85101402, name = "呃呃~"},
  [85101403] = {id = 85101403, name = "唔诶。"},
  [85111401] = {
    id = 85111401,
    name = "稍微，有点勉强了呢。"
  },
  [85121401] = {
    id = 85121401,
    name = "这可不是姐姐该有的样子......"
  },
  [85131401] = {
    id = 85131401,
    name = "虽然胜利了，但这次的作战计划还有不少地方可以继续完善。"
  },
  [85141401] = {
    id = 85141401,
    name = "如果出发前我能找遥姐和大叔能帮忙完善一下作战计划，结果或许会完全不同。"
  },
  [85151401] = {
    id = 85151401,
    name = "哥哥记得今天是什么日子吗？——没错，是哥哥的生日！就算身为队长，今天也应该给自己放个假好好庆祝一下吧？呵呵~走吧，姐妹们应该都到了。"
  },
  [85161401] = {
    id = 85161401,
    name = "每到新年大叔都会给我们做汤圆，今年估计他被什么事耽误了还没回来，就由我来给大家做吧，呵呵呵，毕竟这也算我们“家”的传承嘛。"
  },
  [85171401] = {
    id = 85171401,
    name = "哥哥来尝一下我新做的甜点。——味道怎么样，会不会太甜了？呵呵呵，你喜欢就最好了，还有很多请慢慢吃，我去给你倒杯茶。"
  },
  [85181401] = {
    id = 85181401,
    name = "今天不管怎么恶作剧都没关系吧？我也去准备一下，今天要让妹妹们知道她们平时那些恶作剧都只是小孩子的游戏，呵呵呵~"
  },
  [85191401] = {
    id = 85191401,
    name = "还相信会有神秘人半夜翻窗来送礼的妹妹们真是可爱啊，不过守护妹妹们的天真幻想，也是我们每一个“成熟的”家人应该做的事。"
  },
  [85011411] = {
    id = 85011411,
    name = "暗夜侍者龙舌兰，应您的邀约而来。那么，让我们先聊聊后续的计划如何？"
  },
  [85021411] = {
    id = 85021411,
    name = "想要在深渊中平安前行，除了细致的行程规划，还要学会随机应变才行。"
  },
  [85031411] = {
    id = 85031411,
    name = "让暗夜侍者成为深渊中的传奇、这并不是一件容易的事。不过“不容易”只是对普通人而言，只要我们全力以赴，一定可以做到。"
  },
  [85031412] = {
    id = 85031412,
    name = "深渊中的每个人都在追寻自己所渴求的一切，可是却只有少数人可以如愿。有时候，比起盲目的行动，缜密的计划才是成功的关键。"
  },
  [85041411] = {
    id = 85041411,
    name = "只要坚信自己所做的决定，便无所谓前路是坎坷还是坦途。"
  },
  [85041412] = {
    id = 85041412,
    name = "你已经展现了自己的诚意，那么、便让你见识一下我的意志吧！"
  },
  [85041413] = {
    id = 85041413,
    name = "无论作为探险者还是执事，我都没有止步的理由，为了实现我们的目标，我必须前进！"
  },
  [85051411] = {
    id = 85051411,
    name = "拥有贤明的雇主和足以施展才华的舞台是无数执事梦寐以求的事，而主家给我了这样的机会。"
  },
  [85051412] = {
    id = 85051412,
    name = "深渊中的危险远远不止魔物和环境，不过不管会有怎样的危险，也无法阻止我前行。"
  },
  [85051413] = {
    id = 85051413,
    name = "少爷非常宠溺大小姐，不管她有怎样的想法都会予以支持和肯定。"
  },
  [85051414] = {
    id = 85051414,
    name = "无论怎样动人的传说，都只属于那些最后活下来的人，而在那之前的无数挑战者，没人会记得他们的姓名。"
  },
  [85051415] = {
    id = 85051415,
    name = "在大小姐有需要时我自当全力以赴，在此之外，我也不会错过任何一个可以提升自己的机会。"
  },
  [85061411] = {
    id = 85061411,
    name = "希望都是些合格的对手。"
  },
  [85071411] = {id = 85071411, name = "哼！"},
  [85071412] = {id = 85071412, name = "嘿！"},
  [85071413] = {id = 85071413, name = "哈啊！"},
  [85081411] = {
    id = 85081411,
    name = "看招——"
  },
  [85081412] = {
    id = 85081412,
    name = "你、赢不了。"
  },
  [85091411] = {
    id = 85091411,
    name = "来吧，一决胜负！"
  },
  [85091412] = {
    id = 85091412,
    name = "由我来了结一切。"
  },
  [85101411] = {id = 85101411, name = "唔。"},
  [85101412] = {id = 85101412, name = "呃啊。"},
  [85101413] = {id = 85101413, name = "呃。"},
  [85111411] = {
    id = 85111411,
    name = "哼，不过如此。"
  },
  [85121411] = {
    id = 85121411,
    name = "太、轻敌了吗......"
  },
  [85131411] = {
    id = 85131411,
    name = "还算有些实力，不过也仅仅是有些实力罢了。"
  },
  [85141411] = {
    id = 85141411,
    name = "失败，没有借口。"
  },
  [85151411] = {
    id = 85151411,
    name = "今天行动结束后还有什么安排吗？有？还有哪些事今天必须完成，全部交给我吧。我们准备了一个生日庆祝会，如果您这位主角缺席就没有意义了。"
  },
  [85161411] = {
    id = 85161411,
    name = "从主家运来的物资都齐了。准备用来做什么？依照罗斯伯尔家的传统，我们准备在此举办新年庆典，这些物资如果全靠在深渊中采购要花很长时间，所以便直接从主家运送过来了。"
  },
  [85171411] = {
    id = 85171411,
    name = "什么事这么高兴？那些甜点？看起来像是可以随处买到的点心，有什么特别的吗？——大小姐亲自做的？！她竟然也会亲手做点心了吗......"
  },
  [85181411] = {
    id = 85181411,
    name = "每逢这种节日，主家的习俗便是全体出动，满城寻找大小姐的踪影。像是特别的捉迷藏活动？呵呵，或许吧。"
  },
  [85191411] = {
    id = 85191411,
    name = "节日快乐~这礼物是主家送来的，不必推辞，探险队中的每个人都有。在这种特别的节日里，为每个同伴送上祝福也是主家的习俗。"
  },
  [85011421] = {
    id = 85011421,
    name = "这份邀请上的地址是这里吗？呵呵~我就是莱克西，请多多指教啦~如果有什么有趣好玩的事请务必告诉我！"
  },
  [85021421] = {
    id = 85021421,
    name = "行程安排？这种事不必告诉我，对我而言不管去哪都是一件值得期待的事，带着未知前行、有时候会有更多惊喜~"
  },
  [85031421] = {
    id = 85031421,
    name = "深渊如同一个未曾开发的世界，除了浊炁和魔物，还有许多只属于这个世界的景色，如果能走遍深渊，必然可以收获许多前所未有的体验。"
  },
  [85031422] = {
    id = 85031422,
    name = "比起许多枯燥繁琐的工作，探险者的生活有趣多了~不过即便是那些枯燥繁琐的事务，也从来不会缺少愿意为之全力以赴的人。"
  },
  [85041421] = {
    id = 85041421,
    name = "这是给我的惊喜吗？不过还没能好好感受就结束了，下次再有这种事可以提前告诉我~"
  },
  [85041422] = {
    id = 85041422,
    name = "深渊就如同一个布满荆棘的花园，绝美的风景只属于那些不惧危险、敢于突破重重荆棘的人。"
  },
  [85041423] = {
    id = 85041423,
    name = "以我现在的实力足以去到很多地方，但想要走遍深渊，必须还要付出更多努力！"
  },
  [85051421] = {
    id = 85051421,
    name = "我曾跟随导师游历各地，许多名山大川和偏远荒地都留下了我们的足迹。"
  },
  [85051422] = {
    id = 85051422,
    name = "很久前我便在家里的研究资料中见识了不少魔物，我自认为对它们已经足够了解，但实际接触后我才发现自己的“了解”有多么片面~"
  },
  [85051423] = {
    id = 85051423,
    name = "父母一直希望我能继承他们的事业，可是我对那些枯燥的研究根本提不起兴趣。如果勉强自己去做不喜欢的事，我觉得并不会有太多意义。"
  },
  [85051424] = {
    id = 85051424,
    name = "在我看来真正的探险者应该是积极探寻未知存在、开拓这个世界的人，那些追逐名利财富的人更像是一味追逐利益的淘金者。"
  },
  [85051425] = {
    id = 85051425,
    name = "绝美的风景只是我追求的一部分，我真正渴望的、是把握好生命中的每一刻，热爱自己拥有的一切，尽情享受这世界上所有的美好！"
  },
  [85061421] = {
    id = 85061421,
    name = "我很期待今天的目的地。"
  },
  [85071421] = {id = 85071421, name = "呀！"},
  [85071422] = {id = 85071422, name = "嘿~"},
  [85071423] = {id = 85071423, name = "哈~"},
  [85081421] = {
    id = 85081421,
    name = "躲不掉的。"
  },
  [85081422] = {
    id = 85081422,
    name = "乖乖投降吧~"
  },
  [85091421] = {
    id = 85091421,
    name = "妨碍我、可算不上明智的决定。"
  },
  [85091422] = {
    id = 85091422,
    name = "不管怎么抵抗，都只是白费力气。"
  },
  [85101421] = {id = 85101421, name = "呜呃~"},
  [85101422] = {id = 85101422, name = "呀啊~"},
  [85101423] = {id = 85101423, name = "诶~"},
  [85111421] = {
    id = 85111421,
    name = "我可不会轻易放过找麻烦的家伙。"
  },
  [85121421] = {
    id = 85121421,
    name = "旅途......到此为止了吗......"
  },
  [85131421] = {
    id = 85131421,
    name = "沿途的阻碍都已清除完毕，稍微休整一下继续赶路吧~"
  },
  [85141421] = {
    id = 85141421,
    name = "旅途中难免遭遇各种意外，不必放在心上。"
  },
  [85151421] = {
    id = 85151421,
    name = "今天是你的生日？哇哦~那必须要好好庆祝一下！走吧，我带你去一个非常棒的地方，比起寻常的酒馆，在那里庆祝会有趣很多~"
  },
  [85161421] = {
    id = 85161421,
    name = "新年登山是我跟随导师修行时养成的习惯，在新年里登高望远会有一种和平时完全不同的感觉！一起去吗？走嘛~那种快乐只有亲自体验之后才能明白。"
  },
  [85171421] = {
    id = 85171421,
    name = "哼哼~看！——是的，一束花，但它可不是普通的花。这种花盛放的时间非常短暂，但却代表坚韧与永恒，很厉害吧？！送给你，我觉得它和你很配！"
  },
  [85181421] = {
    id = 85181421,
    name = "对那些关于节日的传说我很感兴趣，不过、能和大家一起享受节日会让我感到更加幸福！庆典已经快开始了，我们也准备一下出发吧！"
  },
  [85191421] = {
    id = 85191421,
    name = "节日快乐！——节日礼物？呵呵，我当然有准备，不过嘛、寻常礼物感觉没什么新意，等今天行动结束，我带你去见识一个特别的礼物！"
  },
  [85011431] = {
    id = 85011431,
    name = "拯救那些身陷困境之人总是令人愉悦，您一定也是这样认为的吧？呵呵~我便是圣歌的赦罪人，应您的邀约而来~"
  },
  [85021431] = {
    id = 85021431,
    name = "无法帮上大家的每一刻都让我感到无比煎熬......有什么我能做的吗？不管什么事都可以——"
  },
  [85031431] = {
    id = 85031431,
    name = "有人觉得圣歌的理念和行动太过天真，也有人觉得圣歌所做的一切非常高尚，呵呵~不管天真也好，高尚也罢，我们所追寻的只会是我们所信仰的正义，而不是别人对我们的看法。"
  },
  [85031432] = {
    id = 85031432,
    name = "为什么大家都不愿意让我帮忙呢？难道真如那些人所说，我看上去不像是什么正经人？真是遗憾啊，明明是那么令人愉悦的事......"
  },
  [85041431] = {
    id = 85041431,
    name = "不管别人如何评说，我也无法容忍自己对那些陷入困境的人坐视不理。"
  },
  [85041432] = {
    id = 85041432,
    name = "为了消弭这深渊中的苦难，我会解决所有罪恶的源头——"
  },
  [85041433] = {
    id = 85041433,
    name = "实现正义和美好的手段有很多，比如、将所有不懂爱的存在抹除......呵呵，开玩笑的，不用紧张~"
  },
  [85051431] = {
    id = 85051431,
    name = "每当想到深渊中还有那么多需要被救赎的人，我的心中便会涌现出难以压抑的情绪。"
  },
  [85051432] = {
    id = 85051432,
    name = "作为圣歌的成员，我们虽然有着共同的信念，但成员之间彼此的行事作风却存在不少分歧，所以在非必要时我们很少一起行动。"
  },
  [85051433] = {
    id = 85051433,
    name = "弱小即是罪过，如果没有足够的实力，无论如何强烈、崇高的信念，听起来甚至还不如那些醉汉口中的胡话动听。"
  },
  [85051434] = {
    id = 85051434,
    name = "贯彻正义，守护美好和希望这种事绝非几句话就能做到，有时候不得不使用一些特别的手段......"
  },
  [85051435] = {
    id = 85051435,
    name = "我并不在意自己所作的一切是否能算得上高尚，但如果能为这个世界带来一些变化，哪怕只有一点点，也足以令我感到前所未有的满足。"
  },
  [85061431] = {
    id = 85061431,
    name = "这些小事就交给我吧~"
  },
  [85071431] = {id = 85071431, name = "呀咿！"},
  [85071432] = {id = 85071432, name = "嘿呀！"},
  [85071433] = {id = 85071433, name = "呵呵呵~"},
  [85081431] = {
    id = 85081431,
    name = "能挡得住吗？"
  },
  [85081432] = {
    id = 85081432,
    name = "结局、已经注定。"
  },
  [85091431] = {
    id = 85091431,
    name = "谁也无法从这里逃走~"
  },
  [85091432] = {
    id = 85091432,
    name = "我会消弭所有罪恶的根源。"
  },
  [85101431] = {id = 85101431, name = "呃啊~"},
  [85101432] = {id = 85101432, name = "唔啊~"},
  [85101433] = {id = 85101433, name = "哈啊~"},
  [85111431] = {
    id = 85111431,
    name = "久违的感觉~"
  },
  [85121431] = {
    id = 85121431,
    name = "什么......也帮不上了......"
  },
  [85131431] = {
    id = 85131431,
    name = "这点小事还无法让我满足~还有什么我能为您做的吗？"
  },
  [85141431] = {
    id = 85141431,
    name = "被失败孕育出的胜利会更加美味~"
  },
  [85151431] = {
    id = 85151431,
    name = "这是专属于你的节日，生日快乐~呵呵，今天有任何心愿都可以告诉我，只要不违背我们所信仰的正义，我都会为你实现~"
  },
  [85161431] = {
    id = 85161431,
    name = "又到参加新年聚会的日子，不知道其他人都到了没......我们也抓紧时间出发吧，免得晚了又被埋怨，而且早一点到可以听到更多有趣的故事~"
  },
  [85171431] = {
    id = 85171431,
    name = "非常感谢你这段时间以来的关照，我准备了一点小礼物，希望你能喜欢——雕像？不，这是我按照自己形象制作的特别点心，你、会喜欢的吧？"
  },
  [85181431] = {
    id = 85181431,
    name = "今天是幽灵的节日吧？呵呵~幽灵鬼魅都是邪祟，必须予以驱逐~一起去外面走走吧，我们可不能让邪祟打扰了庆典。"
  },
  [85191431] = {
    id = 85191431,
    name = "又到了这个向大家派发礼物的节日~不过每年都会有人拒绝我的礼物，我看起来就那么奇怪吗？喂，今年能陪我一起去吗？这样一来说不定就不会有人拒绝我们了。"
  },
  [85011441] = {
    id = 85011441,
    name = "您好，我是浮光，在深渊航线中还只能算得上新人，非常感谢您的信任和邀约，我会好好珍惜这次机会。"
  },
  [85021441] = {
    id = 85021441,
    name = "最近的行动中我有了不少收获，可是一时还无法完全理解，如果能有机会多验证一下，或许能有新的领悟。"
  },
  [85031441] = {
    id = 85031441,
    name = "婆婆让我出来寻找自己的幸福，可我并不知道幸福是什么，也不该如何寻找，迷茫之际，我遇到了深渊航线的大家......我想深渊航线或许是命运给予我寻找幸福的线索，所以便毫不犹豫的加入了。"
  },
  [85031442] = {
    id = 85031442,
    name = "组织中明明规定了“只要接受了邀约，无论怎样的任务都不能逃避和畏惧”，可是我在执行一些任务时，还是会觉得害怕或紧张......"
  },
  [85041441] = {
    id = 85041441,
    name = "虽然我还不懂幸福是什么，但那些会让人感到难过的事一定不是幸福。"
  },
  [85041442] = {
    id = 85041442,
    name = "只要战斗就可以了吗？如果只要战斗下去，就能明白幸福的含义，那么我、会全力以赴！"
  },
  [85041443] = {
    id = 85041443,
    name = "深渊航线的大家都拥有只有她们才能做到的事，我也想找到只有自己才能做到的事。"
  },
  [85051441] = {
    id = 85051441,
    name = "我一直和婆婆一起生活，她离开之后，我便失去了所有牵绊，只能迷茫的在深渊中游荡。"
  },
  [85051442] = {
    id = 85051442,
    name = "深渊航线中的生活总是很忙碌，我不讨厌忙碌，如果我的努力能守护大家的幸福，我也会感到满足。"
  },
  [85051443] = {
    id = 85051443,
    name = "我曾询问深渊航线的大家什么是幸福，可是每个人的回答都不一样。虽然没能得到想要的答案，但我至少明白了幸福不止一种。"
  },
  [85051444] = {
    id = 85051444,
    name = "我很喜欢现在所拥有的一切，这让我第一次对力量有了渴望，我渴望拥有足以守护我现在重要事物的力量。"
  },
  [85051445] = {
    id = 85051445,
    name = "有时候太过偏执的渴望反而会迷惑自己的内心，或许从我和大家相遇的那一刻起，我就已经找到了属于自己的幸福。"
  },
  [85061441] = {
    id = 85061441,
    name = "我会珍惜这次行动的机会。"
  },
  [85071441] = {id = 85071441, name = "呵！"},
  [85071442] = {id = 85071442, name = "呀！"},
  [85071443] = {id = 85071443, name = "哈！"},
  [85081441] = {
    id = 85081441,
    name = "专注——"
  },
  [85081442] = {
    id = 85081442,
    name = "全力以赴。"
  },
  [85091441] = {
    id = 85091441,
    name = "我会证明自己的实力。"
  },
  [85091442] = {
    id = 85091442,
    name = "这是只有我才能做到的事！"
  },
  [85101441] = {id = 85101441, name = "呀啊。"},
  [85101442] = {id = 85101442, name = "呃。"},
  [85101443] = {id = 85101443, name = "啊~"},
  [85111441] = {
    id = 85111441,
    name = "这是，无法阻止我的。"
  },
  [85121441] = {
    id = 85121441,
    name = "这......并不是我想要的结局......"
  },
  [85131441] = {
    id = 85131441,
    name = "真是一次完美的行动，我也获得了一些新的感悟。"
  },
  [85141441] = {
    id = 85141441,
    name = "非常抱歉......我没能把握好这次行动的机会。"
  },
  [85151441] = {
    id = 85151441,
    name = "婆婆说过，生日是非常重要的日子，这一天中只能做开心的事。请问，有什么事能让您觉得开心呢？"
  },
  [85161441] = {
    id = 85161441,
    name = "以前新年时，我都会和婆婆一起做许愿签，然后把心愿写在上面挂在高高的地方。婆婆说，挂得越高，愿望便会越容易实现。"
  },
  [85171441] = {
    id = 85171441,
    name = "请问、可以收下这些点心吗？只是想感谢您长期以来对我的关照。当然，我知道这远远不够，可是，如果您能收下的话......"
  },
  [85181441] = {
    id = 85181441,
    name = "我并不讨厌这种热闹的节日，只是不知道该怎样才能融入大家......只需要跟上巡游的人群就可以了吗？真的吗？那、那我去试试。"
  },
  [85191441] = {
    id = 85191441,
    name = "以前每逢这种节日，我的父母都会在家中举办酒会，我会趁大家跳舞时拼命的吃很多食物，因为当酒会结束后，我们会有很长时间无法填饱肚子。"
  },
  [85011451] = {
    id = 85011451,
    name = "我是星云，听深渊航线的同伴说有赚钱，咳~呵呵呵，听说这里正在招募支援探险的人员？这方面的经验我还算丰富，请多多指教。"
  },
  [85021451] = {
    id = 85021451,
    name = "今天的行程是怎样安排的呢，沿途上有听说宝物或者圣物的传闻吗？嘿嘿，我只是好奇，毕竟如果能发现些好东西，大家都能收获更多嘛~"
  },
  [85031451] = {
    id = 85031451,
    name = "深渊航线的宗旨是为客人提供最完备的护卫支援服务，在平时没有指定任务的时候大家可以自行探险，相当于可以拿多份酬劳！可是组织中的大家对任务之外的赚钱活动都不感兴趣，稍微有点可惜。"
  },
  [85031452] = {
    id = 85031452,
    name = "他们总是成天和我念叨“钱财都是身外之物”“组织规定不得觊觎客人的任何财物”之类的话，我自然明白。可是我家里很穷，祖辈都只是普通生意人，如果我不努力挣钱早晚会流落街头。"
  },
  [85041451] = {
    id = 85041451,
    name = "赚钱和帮助别人都是很快乐的事，如果在赚钱的同时还能帮到别人，那样就能拥有双倍的快乐。"
  },
  [85041452] = {
    id = 85041452,
    name = "现在我能胜任那些酬劳更高的工作了吧？呵呵，开玩笑的，赚钱固然重要，但对现在的客人负责更加重要。"
  },
  [85041453] = {
    id = 85041453,
    name = "要实现目标就不能满足于现状。呼~加油星云，再努力一点，一定可以做到！"
  },
  [85051451] = {
    id = 85051451,
    name = "我成为探险者之后给自己定了一个小目标，先赚1个亿！嗯？为什么你的眼神那么奇怪，难道很离谱吗?"
  },
  [85051452] = {
    id = 85051452,
    name = "比起其他组织，深渊航线的规定虽然不算多，但是却极其严格，我的任务酬劳几乎都变成了罚金！"
  },
  [85051453] = {
    id = 85051453,
    name = "混乱的深渊确实是个赚钱的好地方，但想要安全的赚钱却不容易，所以我对组织想要守护深渊秩序的目的非常赞同！"
  },
  [85051454] = {
    id = 85051454,
    name = "父亲常和我念叨“商人也必须要有自己的底线和信念”，我虽然想赚钱，但任何会损害大家利益、影响任务的事我绝不会去做。"
  },
  [85051455] = {
    id = 85051455,
    name = "我很像一个财迷吧？嘿嘿，我知道大家对我看法，请不用在意。我确实渴望赚钱，但我也渴望能在这个世界找到属于自己的未来。"
  },
  [85061451] = {
    id = 85061451,
    name = "走吧，我已经准备好了。"
  },
  [85071451] = {id = 85071451, name = "哟咿~"},
  [85071452] = {id = 85071452, name = "哈！"},
  [85071453] = {id = 85071453, name = "呀！"},
  [85081451] = {
    id = 85081451,
    name = "别分心。"
  },
  [85081452] = {
    id = 85081452,
    name = "尝尝这个！"
  },
  [85091451] = {
    id = 85091451,
    name = "见识一下我的全力吧！"
  },
  [85091452] = {
    id = 85091452,
    name = "趁早投降会更好哦~"
  },
  [85101451] = {id = 85101451, name = "呃啊~"},
  [85101452] = {id = 85101452, name = "呜哇。"},
  [85101453] = {id = 85101453, name = "呀~"},
  [85111451] = {
    id = 85111451,
    name = "挣钱的工作，从来都不会轻松。"
  },
  [85121451] = {
    id = 85121451,
    name = "我的...... 1个亿......"
  },
  [85131451] = {
    id = 85131451,
    name = "胜利是我们的呢！呐呐，打扫战场的事可以交给我吗？"
  },
  [85141451] = {
    id = 85141451,
    name = "再让我试一次吧，绝不能让它们夺走我的酬劳！"
  },
  [85151451] = {
    id = 85151451,
    name = "今天是你的生日吧？嘿嘿，快来看，我准备了一个超豪华的蛋糕！嗯？客人的隐私......我只是偶然听到的，不算窥探吧？！而且，我钱全都用来买这个超豪华蛋糕了，已经没钱交罚金了，呜呜——"
  },
  [85161451] = {
    id = 85161451,
    name = "我在家时，新年就是大家聚在一起算账的日子。在我的记忆中，好像从没听父亲说过赚钱，几乎每个新年都是在他和长辈们的叹息声中度过。"
  },
  [85171451] = {
    id = 85171451,
    name = "怎样做才能表达最高的谢意呢？果然还是做一份超豪华的“至尊点心”吧，从材料到制作工具，全部挑选顶级的，这样一定能传达心意！"
  },
  [85181451] = {
    id = 85181451,
    name = "锵锵~节日快乐！快看，换装道具，糖果，我准备了非常多，在节日里贩售特定商品一定可以大赚一笔！要不......你来帮帮我？利润......五五分？"
  },
  [85191451] = {
    id = 85191451,
    name = "这一堆礼物都是父亲托人送来的，每个人都有。哈啊~明明我已经成为探险者这么久了，可是却完全没赚到钱......不过如果能有重新选择的机会，我依然会选择探险者，不然就会失去和大家成为同伴的机会。"
  },
  [85011461] = {
    id = 85011461,
    name = "呀嚯~我是岫，大名鼎鼎的真理之钥的成员——欸？没听过？！真是没办法，让我好好和你介绍一下，可千万别吓着了。"
  },
  [85021461] = {
    id = 85021461,
    name = "我们今天去哪里呢？周围基本都已经探索过了，要不要去远一点的地方看看？"
  },
  [85031461] = {
    id = 85031461,
    name = "“探寻魔法和武技的根源”这种事并没有想象中那么容易，我们目前收获非常有限......不过我相信只要和大家在一起，不管怎样的困难都难不倒我们！"
  },
  [85031462] = {
    id = 85031462,
    name = "我刚到深渊就发现朋友们都加入了真理之钥，所以我也就主动申请了！不管什么时候，能和朋友在一起才是最快乐的吧？！嘿嘿~"
  },
  [85041461] = {
    id = 85041461,
    name = "这种体验太棒了，我们再来一次吧！暂时还不行？"
  },
  [85041462] = {
    id = 85041462,
    name = "再一次完成了蜕变，如果能继续下去，说不定我会成为真理之钥中最先发现武技奥秘的人！"
  },
  [85041463] = {
    id = 85041463,
    name = "我所有的力量都是为了追寻幸福和快乐，无论成长到什么地步，这一点永远不会改变。"
  },
  [85051461] = {
    id = 85051461,
    name = "所谓的随机应变就是完全不去考虑计划，想到什么就做什么，对吧？呵呵，这种事我最擅长了！"
  },
  [85051462] = {
    id = 85051462,
    name = "多亏了同伴们的支持我才能走到现在，今后我也要努力成为大家的依靠才行！"
  },
  [85051463] = {
    id = 85051463,
    name = "我毕业时老师们给我的评价都非常“糟糕”，如果他们知道我现在正为了一个“伟大的目标”而努力，会是怎样的心情呢？"
  },
  [85051464] = {
    id = 85051464,
    name = "深渊中的生活比地面辛苦很多，但我并不后悔自己的选择，如果没有成为探险者便不会拥有现在的一切。"
  },
  [85051465] = {
    id = 85051465,
    name = "很多时候我们所遇到的困难都不是自己能决定的，但我们可以决定自己面对困难时的心情，无论何时也不能忘了这一点。"
  },
  [85061461] = {
    id = 85061461,
    name = "要去新的地方了吗？"
  },
  [85071461] = {id = 85071461, name = "咻~"},
  [85071462] = {id = 85071462, name = "嘿咿~"},
  [85071463] = {id = 85071463, name = "哟咿~"},
  [85081461] = {
    id = 85081461,
    name = "瞄准......射击！"
  },
  [85081462] = {
    id = 85081462,
    name = "站好别动。"
  },
  [85091461] = {
    id = 85091461,
    name = "一起解决吧！"
  },
  [85091462] = {
    id = 85091462,
    name = "我可不会输给大家~"
  },
  [85101461] = {id = 85101461, name = "呀。"},
  [85101462] = {id = 85101462, name = "啊~"},
  [85101463] = {id = 85101463, name = "呃啊~"},
  [85111461] = {
    id = 85111461,
    name = "有些小看敌人了。"
  },
  [85121461] = {
    id = 85121461,
    name = "不能......和大家一起了......"
  },
  [85131461] = {
    id = 85131461,
    name = "不管是“老对手”还是“新朋友”，都无法阻止我们前进。"
  },
  [85141461] = {
    id = 85141461,
    name = "啊，真是不甘心......不过我已经掌握了敌人的弱点。"
  },
  [85151461] = {
    id = 85151461,
    name = "锵锵~生日快乐！怎么知道的？嘿嘿，秘密！我和大家一起准备了蛋糕和食物，等你来了就能开始庆祝会啦~"
  },
  [85161461] = {
    id = 85161461,
    name = "这种热闹的日子最适合和大家一起外出游玩了，你也是这样想的，对吧？嘿嘿，我这就去通知大家！"
  },
  [85171461] = {
    id = 85171461,
    name = "请看看这是什么！——点心？不，它可不是普通的点心，而是被赋予了快乐和幸福魔法的点心！送给你，希望今后你也能快乐和幸福哦。"
  },
  [85181461] = {
    id = 85181461,
    name = "去年这时，我和大家比赛看谁能拿到更多的糖果，结果输的好惨......今年我一定要赢回来！"
  },
  [85191461] = {
    id = 85191461,
    name = "好叻，写完啦！我刚才在写修行感悟呢，这可是真理之钥成员之间专属的节日礼物，很厉害哦！"
  },
  [85011471] = {
    id = 85011471,
    name = "只要有宝物的地方，就有荒野游骑兵的身影！荒野游骑兵、辉煌骑士猎鹰、参上！指挥的工作就拜托你了，可以吧指挥官~"
  },
  [85021471] = {
    id = 85021471,
    name = "近期行程中的几处目的地好像都比较危险，嗯~果然需要把准备工作做得更完善一点，毕竟有备无患，哈哈哈~"
  },
  [85031471] = {
    id = 85031471,
    name = "追寻宝物是一件无比浪漫的事，不过也是一件无比危险的事，毕竟在深渊中，没有人知道危险什么时候来临~所以不管怎样的行动，都必须小心谨慎，绝不能轻敌大意！"
  },
  [85031472] = {
    id = 85031472,
    name = "不管是做事目的还是行事作风，荒野游骑兵和其他寻宝组织完全不同，我们的虽然也在寻宝，但大家追寻的都不是那种传统意义上的宝物，我们渴求的是更有意义的存在。"
  },
  [85041471] = {
    id = 85041471,
    name = "咳咳~骑士律令第二条，在任何情况下都必须坚守安全第一的原则！"
  },
  [85041472] = {
    id = 85041472,
    name = "所谓的辉煌骑士，便是如同太阳一般耀眼的存在！怎么样，现在的我足够耀眼了吧？！"
  },
  [85041473] = {
    id = 85041473,
    name = "以我现在的力量，足以前往这片大地的尽头！太夸张了？不，就算到不了尽头，也差不了多少。"
  },
  [85051471] = {
    id = 85051471,
    name = "当我决定成为探险者时，父亲便带我来深渊修行历练，他是位非常老练的探险者，我现在掌握的所有技巧几乎都是他传授的。"
  },
  [85051472] = {
    id = 85051472,
    name = "寻宝人必须清楚勇敢和鲁莽的区别，否则在追寻宝物的过程中，很容易让自己陷入绝境。"
  },
  [85051473] = {
    id = 85051473,
    name = "有时候一瞬间的犹豫就可能造成无法挽回的后果，所以在该放弃时绝不能犹豫，这个世界上没有任何事物能比得上人的生命。"
  },
  [85051474] = {
    id = 85051474,
    name = "如果拥有足够的力量，自然可以更好的保障安全，可是如果一味的依靠力量，反而会干扰自己的判断。"
  },
  [85051475] = {
    id = 85051475,
    name = "不少人都喜欢为了一些无谓的事情消沉沮丧，真奇怪啊~难道消沉沮丧就能解决问题吗？唉~人生的时间并不多，浪费在这些事上太可惜了。"
  },
  [85061471] = {
    id = 85061471,
    name = "辉煌骑士，领命！"
  },
  [85071471] = {id = 85071471, name = "哈！"},
  [85071472] = {id = 85071472, name = "呀！"},
  [85071473] = {id = 85071473, name = "喝啊！"},
  [85081471] = {
    id = 85081471,
    name = "只有这点程度吗。"
  },
  [85081472] = {
    id = 85081472,
    name = "哈哈，再来再来。"
  },
  [85091471] = {
    id = 85091471,
    name = "一个敌人也别想从我这越过！"
  },
  [85091472] = {
    id = 85091472,
    name = "见识一下辉煌骑士真正的实力吧！"
  },
  [85101471] = {id = 85101471, name = "哇！"},
  [85101472] = {id = 85101472, name = "唔。"},
  [85101473] = {id = 85101473, name = "呃。"},
  [85111471] = {
    id = 85111471,
    name = "只是皮外伤而已，不用担心。"
  },
  [85121471] = {
    id = 85121471,
    name = "虽然早有觉悟，可是......"
  },
  [85131471] = {
    id = 85131471,
    name = "大家都平安无事，真是完美！去看看有没有什么好东西吧~"
  },
  [85141471] = {
    id = 85141471,
    name = "这里交给我，大家快撤！"
  },
  [85151471] = {
    id = 85151471,
    name = "锵锵~生日快乐！虽然很想给你准备礼物来着，可是我翻遍了仓库也没找到合适的......不如这样吧，我先欠你一份礼物，如果你有任何想要的都可以告诉我，我一定会帮你弄来！"
  },
  [85161471] = {
    id = 85161471,
    name = "大家已经把新年庆祝会的地点定好了， 我们一起过去吧——不方便？怎么会！你既然做了我的指挥官，我们自然就是一伙了吧？！"
  },
  [85171471] = {
    id = 85171471,
    name = "这个、送给你！没错，就是一把锁。不过这可不是普通的锁，据说这种造型的锁能带来最紧密牢靠的关系，很适合我们吧？！"
  },
  [85181471] = {
    id = 85181471,
    name = "每年骑士长都会弄出一些新的恶作剧，让人防不胜防！不行，今年不能再输了，否则又要被她嘲笑，帮我想想办法吧，指挥官！"
  },
  [85191471] = {
    id = 85191471,
    name = "在今天这种节日里，我们每个人都要为组织中其他成员做一件事。今年我准备把父亲传授我的鉴宝技巧分享给大家，不过展示这些技巧需要一些宝物做示范......指挥官能帮帮我吗？！"
  },
  [85011481] = {
    id = 85011481,
    name = "你好，听闻这里正在招募探索深渊的同伴？我是舒芙蕾，来自自由学派，希望今后能一起探寻深渊中那些传闻。"
  },
  [85021481] = {
    id = 85021481,
    name = "我准备了红茶，要试试吗？呵呵~这是我用学派茶会上学到的“泡茶诀窍”泡制的，味道应该会很不错~"
  },
  [85031481] = {
    id = 85031481,
    name = "比起其他组织，自由学派更像一个“同好会”，成员间并没有任何从属关系，除了举办“学派茶会”时一些同伴会聚到一起分享情报外，平时很少联系。"
  },
  [85031482] = {
    id = 85031482,
    name = "组织中看起来很凶的人？呵呵~你说的应该是欧培拉小姐。她其实非常热情、善良，只是对自己要求太严格了，不习惯展露自己的内心。如果你见过她和自己闹别扭的样子，一定会被她的可爱迷住。"
  },
  [85041481] = {
    id = 85041481,
    name = "我渴望探寻深渊中的那些传闻，化解那些因此诞生的无谓纷争。"
  },
  [85041482] = {
    id = 85041482,
    name = "每个人都有追寻自己理想的权力，但如果在追寻理想时选择背弃希望和正义，那样的理想我绝不认同！"
  },
  [85041483] = {
    id = 85041483,
    name = "探寻深渊中的传闻，也是在探寻我自己的未来，无论前路会有多少曲折坎坷我也不会畏惧。"
  },
  [85051481] = {
    id = 85051481,
    name = "小时候我一直生活在阁楼之中，对外面的世界充满了向往，可是在见识过之后，才发现和想象中的巨大差别。"
  },
  [85051482] = {
    id = 85051482,
    name = "善良，不是懦弱，宽容，也并非放纵。拥有足够的力量，才能贯彻自己的信念！"
  },
  [85051483] = {
    id = 85051483,
    name = "自由学派的同伴们对于理想所展现出来的热情和执着，是激励我继续前行的动力。"
  },
  [85051484] = {
    id = 85051484,
    name = "宽容是这个世界上最强大的力量，它足以拯救一个人，甚至这个世界。"
  },
  [85051485] = {
    id = 85051485,
    name = "尽管混乱与纷争是深渊中现在的主旋律，但我坚信终有一天可以看到这个世界充满秩序与和平。"
  },
  [85061481] = {
    id = 85061481,
    name = "我明白我们前行的方向。"
  },
  [85071481] = {id = 85071481, name = "嘿——"},
  [85071482] = {id = 85071482, name = "呀咿~"},
  [85071483] = {id = 85071483, name = "哈！"},
  [85081481] = {
    id = 85081481,
    name = "集中精神。"
  },
  [85081482] = {
    id = 85081482,
    name = "沉着应对。"
  },
  [85091481] = {
    id = 85091481,
    name = "大家相互依靠，便足以战胜一切。"
  },
  [85091482] = {
    id = 85091482,
    name = "没有什么可以阻挡我们的信念。"
  },
  [85101481] = {id = 85101481, name = "呃啊~"},
  [85101482] = {id = 85101482, name = "呃。"},
  [85101483] = {id = 85101483, name = "咿呀。"},
  [85111481] = {
    id = 85111481,
    name = "前行之路，难免会有荆棘坎坷。"
  },
  [85121481] = {
    id = 85121481,
    name = "请继续追寻希望......不要悲伤......"
  },
  [85131481] = {
    id = 85131481,
    name = "无论怎样的战斗都是残酷的，但为了守护秩序与和平，我们别无选择。"
  },
  [85141481] = {
    id = 85141481,
    name = "大家没事吧？无论怎样的险境，我们也绝不能放弃希望。"
  },
  [85151481] = {
    id = 85151481,
    name = "请问今天有什么特殊安排吗？我准备了些蛋糕和食物，一起庆祝生日吧！诶，谁的生日？难道你把自己的生日忘记了吗？呵呵~"
  },
  [85161481] = {
    id = 85161481,
    name = "新年快乐~请问今天能和我出去一趟吗？呵呵，我想去参加学派的“新年茶会”，但是一个人去稍微有些寂寞，如果你能一起......呵呵，非常感谢~"
  },
  [85171481] = {
    id = 85171481,
    name = "母亲说如果想对一个人传达最真挚的感谢，最好的方法便是准备足够丰盛的美食。呵呵~所以这些美食都是为你一个人准备的，请慢慢品尝。"
  },
  [85181481] = {
    id = 85181481,
    name = "节日庆典似乎已经开始了，要去看看吗？呵呵，我当然也会一起参加，这种热闹的节日我可不想错过。"
  },
  [85191481] = {
    id = 85191481,
    name = "自由学派中参加交换礼物的人变多之后，我对收到的礼物就越来越期待了。由于大家的喜好不同，所以礼物种类很多，许多都是想象不到的存在~"
  },
  [85011491] = {
    id = 85011491,
    name = "初次见面，叫我缇米就好~虽然目前还只是一名不太成熟的探险者，但我正在努力学习各种事情，要多多指导我哦。"
  },
  [85021491] = {
    id = 85021491,
    name = "我听大家讲了不少对付魔物的技巧，今天的行动正好可以派上用场！"
  },
  [85031491] = {
    id = 85031491,
    name = "为了成为探险者，我可是付出了非常非常多的努力，所以我会珍惜这次历练自己的机会，顺便游历深渊，感受这个与众不同的世界。"
  },
  [85031492] = {
    id = 85031492,
    name = "作为家族中唯一的女孩，一直备受长辈的关照。那种感觉虽然很幸福，但有时候也会有些困扰......因为一直在他们的庇护下生活，我将永远无法长大。"
  },
  [85041491] = {
    id = 85041491,
    name = "啊，又见识了新的东西，果然加入探险队是一个明智的选择。"
  },
  [85041492] = {
    id = 85041492,
    name = "新鲜的事物层出不穷，新的对手也更加强大，缇米也要再努力一点，才能从容应对~"
  },
  [85041493] = {
    id = 85041493,
    name = "缇米虽然是女孩子，但在修行上，家族中的同辈没人能比得上我！"
  },
  [85051491] = {
    id = 85051491,
    name = "我的故乡在离深渊很遥远的地方，这次出来，也是我第一次独自出远门。"
  },
  [85051492] = {
    id = 85051492,
    name = "我从小就跟随家族中那些实力出色的探险者一起修行，是他们告诉了我关于深渊的一切。"
  },
  [85051493] = {
    id = 85051493,
    name = "离开家时，我和父母约定好一定会平安回去，所以在游历之外我也会努力提升实力，遵守这个约定。"
  },
  [85051494] = {
    id = 85051494,
    name = "大家都说缇米是修行的天才，天才是没有极限的，所以缇米也没有！"
  },
  [85051495] = {
    id = 85051495,
    name = "无论怎样的事都应该去尝试、经历，只有不怕失败，经历足够的风雨，才能变得成熟，对吧？嘻嘻~"
  },
  [85061491] = {
    id = 85061491,
    name = "没问题哦~"
  },
  [85071491] = {id = 85071491, name = "来咯~"},
  [85071492] = {id = 85071492, name = "哈！"},
  [85071493] = {id = 85071493, name = "嘿~"},
  [85081491] = {
    id = 85081491,
    name = "不准躲开哦~"
  },
  [85081492] = {
    id = 85081492,
    name = "你们完蛋了。"
  },
  [85091491] = {
    id = 85091491,
    name = "没有人可以逃过缇米的追击。"
  },
  [85091492] = {
    id = 85091492,
    name = "真是顽固，束手就擒吧！"
  },
  [85101491] = {id = 85101491, name = "好痛！"},
  [85101492] = {id = 85101492, name = "呃"},
  [85101493] = {id = 85101493, name = "呃啊。"},
  [85111491] = {
    id = 85111491,
    name = "缇米可不会轻易认输。"
  },
  [85121491] = {
    id = 85121491,
    name = "无法......完成约定了吗......"
  },
  [85131491] = {
    id = 85131491,
    name = "只要谨慎应对，不管怎样的问题都能找到解决的办法。"
  },
  [85141491] = {
    id = 85141491,
    name = "虽然我们表现不错，但对方，好像更出色......"
  },
  [85151491] = {
    id = 85151491,
    name = "生日吗，在我的家乡生日可是非常重要的日子，为了庆祝生日，大家都会聚到一起唱歌跳舞。一起跳舞吧，我来教你我故乡的传统舞蹈。"
  },
  [85161491] = {
    id = 85161491,
    name = "已经新年了吗，不知不觉离开家已经这么久了，这段时间经历了不少事情......给家里写封信吧，和大家说下我的经历，也让他们可以安心。"
  },
  [85171491] = {
    id = 85171491,
    name = "圈落里的食材太少了，完全没办法做出想要的味道......等有机会去我的故乡，让我带你感受一种味道绝妙的甜品吧~"
  },
  [85181491] = {
    id = 85181491,
    name = "竟、竟然还有装扮为幽灵的节日！我的故乡完全没有，大家都很敬畏幽灵......这、这实在太棒了，我们也快去和大家一起玩吧~"
  },
  [85191491] = {
    id = 85191491,
    name = "以前在家里，我每年都会收到很多礼物，那种感觉并没有想象中那么美好......喜欢捉弄我的哥哥和叔叔们，总是喜欢将礼物包裹得很紧，或者放一些恶作剧道具，拆那些礼物完全是一种折磨。"
  },
  [85011501] = {
    id = 85011501,
    name = "请问，是你发出的邀请吗？我就是海蒂。能收到邀请说明我已经有一定名气了吧？呵呵~请期待我的表现。"
  },
  [85021501] = {
    id = 85021501,
    name = "我以前在家时，经常会帮父亲整理文稿，如果有类似的事情也可以尽管交给我。"
  },
  [85031501] = {
    id = 85031501,
    name = "如果我能成为一位有名气的探险者，就能拥有很多财富。——想要做什么？我早已经计划好了。一部分用于雇人照料我的父母，一部分用于添置最新的探险装备，去探索更多的地方！"
  },
  [85031502] = {
    id = 85031502,
    name = "一味沉迷于幻想，无论多么美好的愿望都无法实现。只有脚踏实地，并付出足够的努力，才能让那些美好的心愿成为现实。"
  },
  [85041501] = {
    id = 85041501,
    name = "我曾无数次幻想过这个时刻，结果真的到来时，我却有些不安。"
  },
  [85041502] = {
    id = 85041502,
    name = "这样的力量，让创造传奇成为了可能，终有一天，探险者海蒂的名字会传遍深渊！"
  },
  [85041503] = {
    id = 85041503,
    name = "只要能成为有名气的探险者，不管会有多么困难我也不会放弃。"
  },
  [85051501] = {
    id = 85051501,
    name = "父亲对我说过，所有梦想都是伟大的，只要不放弃，总有一天可以实现。"
  },
  [85051502] = {
    id = 85051502,
    name = "深渊中的困难远比想象中更多，不过我都坚持了下来，胜利一定会属于我。"
  },
  [85051503] = {
    id = 85051503,
    name = "有人曾说我不适合成为探险者，可是我相信凡事无绝对，没有尝试过，是不会知道结果的。"
  },
  [85051504] = {
    id = 85051504,
    name = "我设想过无数种机遇出现的场景，虽然一个都还没出现，但我会努力提升实力，让自己可以在它们出现时把握住。"
  },
  [85051505] = {
    id = 85051505,
    name = "比起成为有名气的探险者这个梦想，或许在追寻梦想的路上，我所收获到的才更加重要。"
  },
  [85061501] = {
    id = 85061501,
    name = "请交给我吧。"
  },
  [85071501] = {id = 85071501, name = "嘿！"},
  [85071502] = {id = 85071502, name = "呀！"},
  [85071503] = {id = 85071503, name = "哈！"},
  [85081501] = {
    id = 85081501,
    name = "别小看我。"
  },
  [85081502] = {
    id = 85081502,
    name = "全力出击。"
  },
  [85091501] = {
    id = 85091501,
    name = "这一招，一决胜负！"
  },
  [85091502] = {
    id = 85091502,
    name = "没有困难可以阻拦我们。"
  },
  [85101501] = {id = 85101501, name = "呀啊-"},
  [85101502] = {id = 85101502, name = "啊~"},
  [85101503] = {id = 85101503, name = "呃啊~"},
  [85111501] = {
    id = 85111501,
    name = "稍微、有些紧张了。"
  },
  [85121501] = {
    id = 85121501,
    name = "什么......都没做到......"
  },
  [85131501] = {
    id = 85131501,
    name = "距离成为有名气的探险者又进了一步！"
  },
  [85141501] = {
    id = 85141501,
    name = "比起训练，实战中总会有更多突发状况。"
  },
  [85151501] = {
    id = 85151501,
    name = "为了庆祝这个特别的日子，我做了一个蛋糕，不过，这个花纹在我的想象中应该会更好看一点才对，不知道为什么做出来就成了这样......"
  },
  [85161501] = {
    id = 85161501,
    name = "又是默默无名的一年......不行，不能就这样放弃！我们一起去外面逛逛吧，说不定可以遇到一些出名的机会！毕竟已经是新的一年，或许我的人生从今天起就会进入新的阶段！"
  },
  [85171501] = {
    id = 85171501,
    name = "嗯......比起吃掉就没了的点心，果然还是偶尔能说说话，分享秘密的玩偶会更好吧。啊！我、我只是在选择礼物，这个玩偶可以收下吗，感谢长久以来的关照！"
  },
  [85181501] = {
    id = 85181501,
    name = "每到这样的节日，外面就会变得非常热闹，也会有不少新奇的事物。我虽然想去看看，可是，感觉太拥挤了......你能陪我一起去吗？"
  },
  [85191501] = {
    id = 85191501,
    name = "以前我很期待这种节日，可是后来就不怎么期待了，因为每年收到的礼物都是玩偶......当然，并不是不喜欢玩偶，只是、只是有时候也想和别的女孩子一样，收到一些漂亮的衣服、首饰......"
  },
  [85011511] = {
    id = 85011511,
    name = "我是莫妮卡，姑且算是探险者，特长是......处理食物中毒？大概。"
  },
  [85021511] = {
    id = 85021511,
    name = "我烤的这些都是没见过的魔物，要尝尝么？我已经试过了，好像没毒。"
  },
  [85031511] = {
    id = 85031511,
    name = "探险的地方越远，没吃过的魔物就越多。虽然这些魔物中肯定有很多都不好吃，但只要能发现一种美味的魔物，我就心满意足了。"
  },
  [85031512] = {
    id = 85031512,
    name = "“偷窥做饭的人”？......抱歉，大家说的，应该是我。我才知道原来食物有那么多种烹饪方式，我想全部记下来，以后也可以用别的方法烹饪魔物。"
  },
  [85041511] = {
    id = 85041511,
    name = "现在所做的一切，是为了发现更多没吃过的魔物。"
  },
  [85041512] = {
    id = 85041512,
    name = "每一种我未曾尝试过的味道，都会让我感到幸福和满足。"
  },
  [85041513] = {
    id = 85041513,
    name = "我想品尝更多美味的食物，除了找寻更多魔物外，还必须精进厨艺。"
  },
  [85051511] = {
    id = 85051511,
    name = "和小时候相比，我现在所品尝到的每一种味道，都是极佳的美味。"
  },
  [85051512] = {
    id = 85051512,
    name = "亲自动手捕获、烹饪的食物，也许并不好吃，但也一定是幸福的味道。"
  },
  [85051513] = {
    id = 85051513,
    name = "也许我并非讨厌以前那些便携食物，只是厌倦了那个时候的生活而已。"
  },
  [85051514] = {
    id = 85051514,
    name = "和导师分别时，我第一次品尝到了甜品，那种味道我永远也不会忘记。"
  },
  [85051515] = {
    id = 85051515,
    name = "和追寻宝物的父母相比，我就如同一个“异类”，但我知道其实我们都一样，只是目标不同而已。"
  },
  [85061511] = {
    id = 85061511,
    name = "似乎，有新的魔物。"
  },
  [85071511] = {id = 85071511, name = "嘿！"},
  [85071512] = {id = 85071512, name = "咿呃！"},
  [85071513] = {id = 85071513, name = "喝！"},
  [85081511] = {
    id = 85081511,
    name = "速战速决！"
  },
  [85081512] = {
    id = 85081512,
    name = "食物的味道。"
  },
  [85091511] = {
    id = 85091511,
    name = "目标锁定，束手就擒吧。"
  },
  [85091512] = {
    id = 85091512,
    name = "没有什么可以阻拦我！"
  },
  [85101511] = {id = 85101511, name = "唔呃~"},
  [85101512] = {id = 85101512, name = "呃啊~"},
  [85101513] = {id = 85101513, name = "呃~"},
  [85111511] = {
    id = 85111511,
    name = "没什么大碍，就像食物中毒。"
  },
  [85121511] = {
    id = 85121511,
    name = "令人......讨厌的味道......"
  },
  [85131511] = {
    id = 85131511,
    name = "虽然没有发现新的食材有些可惜，但胜利还是令人高兴。"
  },
  [85141511] = {
    id = 85141511,
    name = "失败的味道......下次，不会再失手了......"
  },
  [85151511] = {
    id = 85151511,
    name = "生日......原来是这样的日子么......抱歉，我没有这样的经历，导师也没教过我这方面的事情。我该做些什么呢，去抓一只新的魔物可以么？"
  },
  [85161511] = {
    id = 85161511,
    name = "新年快乐，这是一些金币，请自由使用吧——嗯，不是这样？以前新年时，大人们都是这样告诉我的。"
  },
  [85171511] = {
    id = 85171511,
    name = "听说今天是代表感谢的日子，所以我去抓了几只从没见过的魔物。一起享用吧，我会用新学的烹饪方式来处理，不会中毒的。"
  },
  [85181511] = {
    id = 85181511,
    name = "今天圈落里好多人，我只是路过，就有人塞给了我一堆糖果......原来是这样么，糖果很好吃，我很喜欢这个节日。"
  },
  [85191511] = {
    id = 85191511,
    name = "听说今天会有会有一头鹿拉着一位老人跑遍世界，那头鹿是魔物么？可以跑这么远，味道应该会不错。"
  },
  [85011521] = {
    id = 85011521,
    name = "闪开闪开——耶！我是第一个到的吗，哥哥？我和姐妹们在比赛看谁能先到哥哥这里，没人比我快吧？！"
  },
  [85021521] = {
    id = 85021521,
    name = "遥姐和赛珂姐好像不在，很好，我要趁这段时间研究新的武技，等我能打赢她们的时候应该就可以不用读书了！"
  },
  [85031521] = {
    id = 85031521,
    name = "我可是姐妹中最厉害的，每次战斗我都会冲在最前面，就算有遥姐和大叔参与的战斗，依然会由我来负责正面对抗！哼哼哼我厉害吧~"
  },
  [85031522] = {
    id = 85031522,
    name = "其实我并不讨厌读书，只是我抵抗不了书本中的魔法，每次都会被它催眠。比如这样——随便翻开一本书，从第一个字开始看，三、二、一......"
  },
  [85041521] = {
    id = 85041521,
    name = "我的武技研究有了新的突破，离创造出属于我的武技又近了一点！"
  },
  [85041522] = {
    id = 85041522,
    name = "我已经领悟了大叔所说的“武技的真谛”，见识一下我自创的武技吧！"
  },
  [85041523] = {
    id = 85041523,
    name = "我又创造出了新的武技，比之前的厉害十倍，不，百倍！哈哈哈哈~"
  },
  [85051521] = {
    id = 85051521,
    name = "我原本以为成为探险者就可以不用读书了，结果还是被追着学习......"
  },
  [85051522] = {
    id = 85051522,
    name = "大叔说最强的武技需要靠自己领悟，可是我感觉每次创造的新武技都会比以前的更厉害！"
  },
  [85051523] = {
    id = 85051523,
    name = "希尔和蕾米经常和我比试，每次都是我赢，等遥姐下次回来，我也要和她比试一下！"
  },
  [85051524] = {
    id = 85051524,
    name = "最近希尔和蕾米都在认真读书，难道她们可以抵御书本中的催眠魔法？不行，我也不能输给她们，看书看书......"
  },
  [85051525] = {
    id = 85051525,
    name = "如果有一天，我的实力能超过大叔和遥姐，就可以由我来保护大家，到时候大家只要做自己想做的事情就可以了。"
  },
  [85061521] = {
    id = 85061521,
    name = "只管冲就行了吧？！"
  },
  [85071521] = {id = 85071521, name = "嘿咿！"},
  [85071522] = {id = 85071522, name = "咿啊！"},
  [85071523] = {id = 85071523, name = "哈！"},
  [85081521] = {
    id = 85081521,
    name = "不堪一击！"
  },
  [85081522] = {
    id = 85081522,
    name = "乖乖投降吧！"
  },
  [85091521] = {
    id = 85091521,
    name = "见识一下我的最强武技！"
  },
  [85091522] = {
    id = 85091522,
    name = "已经没有后悔的机会了！"
  },
  [85101521] = {id = 85101521, name = "呜啊~"},
  [85101522] = {id = 85101522, name = "唔。"},
  [85101523] = {id = 85101523, name = "哇啊~"},
  [85111521] = {
    id = 85111521,
    name = "艾莉亚才不会认输！"
  },
  [85121521] = {
    id = 85121521,
    name = "我的武技还不够厉害......"
  },
  [85131521] = {
    id = 85131521,
    name = "哼哼，轻轻松松~只要我全力出击，就没有魔物能拦住我！"
  },
  [85141521] = {
    id = 85141521,
    name = "欸，我们输了吗？难道是我冲太快大家都没跟上？"
  },
  [85151521] = {
    id = 85151521,
    name = "哥哥的生日是非常重要的日子，所以我准备了一个超级巨大的蛋糕，姐妹们看到后都被吓了，哈哈哈，哥哥快去分蛋糕吧，我要最大的那块！"
  },
  [85161521] = {
    id = 85161521,
    name = "今年的汤圆真美味，赛珂姐做汤圆的手艺越来越精湛了，遥姐今天也吃了好多，哈哈哈~我记得大叔做的汤圆，她每次只吃一点点——啊，大叔？！"
  },
  [85171521] = {
    id = 85171521,
    name = "哥哥快把眼睛闭上......可以睁开了——锵锵~这本绝密的武技送给你！这可是我自己最近研究出来的最强武技，全世界独一无二的存在！"
  },
  [85181521] = {
    id = 85181521,
    name = "去年大家都被赛珂姐捉弄了一番，太不甘心了，竟然在恶作剧上输给了赛珂姐。我要去找遥姐和希尔、蕾米，一起联合起来对付赛珂姐！"
  },
  [85191521] = {
    id = 85191521,
    name = "武技武技，我要全世界最强的武技！哈啊~希望今年能收到最强的武技，往年收到的那些都不是最强的，而且和大叔传授我的武技很相似。"
  },
  [85011531] = {
    id = 85011531,
    name = "那个，请问你听说过——啊，哥哥！看来希尔这次没有迷路，嘿嘿~"
  },
  [85021531] = {
    id = 85021531,
    name = "嘘~我们快溜，等下被发现就完——啊，赛珂姐姐，我我我我正准备去训练呢！"
  },
  [85031531] = {
    id = 85031531,
    name = "赛珂姐姐非常厉害，她制定的作战计划灵遥姐姐和大叔也很少进行修改，艾莉亚和蕾米也会认真执行。可是......赛珂姐姐几乎都不会安排我和敌人正面战斗，为什么呢？"
  },
  [85031532] = {
    id = 85031532,
    name = "为什么故事里的女孩在拒绝男孩时总会说“你是个好人”呢？既然是好人，又为什么要拒绝呢......唔，难道哥哥和大叔还没有恋人的原因，就是因为你们都是好人？"
  },
  [85041531] = {
    id = 85041531,
    name = "我的弓术可是大叔亲自传授的，很厉害哦！"
  },
  [85041532] = {
    id = 85041532,
    name = "希尔的下一个挑战——命中哥哥头顶的苹果！"
  },
  [85041533] = {
    id = 85041533,
    name = "希尔的头脑似乎也变得更灵活了，这样一来，就可以知道许多问题的答案了吧？"
  },
  [85051531] = {
    id = 85051531,
    name = "希尔想成为最优秀的探险者！嗯...嗯...最优秀......嗯......除了大叔以外的最优秀吧！"
  },
  [85051532] = {
    id = 85051532,
    name = "很多问题灵遥姐姐和赛珂姐姐都能知道答案，要是希尔也能和她们一样就好了。"
  },
  [85051533] = {
    id = 85051533,
    name = "上次和艾莉亚比谁的头更硬，结果希尔输了，这次一定要赢回来！"
  },
  [85051534] = {
    id = 85051534,
    name = "灵遥姐姐说多走走就能明白很多事情，赛珂姐姐说多读书便能知道很多答案，那如果我一边走一边读书，岂不是很快就能赶上她们？！"
  },
  [85051535] = {
    id = 85051535,
    name = "其实我知道深渊非常危险，可是和姐妹们在一起，我就什么也不怕！为了姐妹们，我什么都愿意做。"
  },
  [85061531] = {
    id = 85061531,
    name = "希尔是负责支援吗？"
  },
  [85071531] = {id = 85071531, name = "嘿噫！"},
  [85071532] = {id = 85071532, name = "呀咿~"},
  [85071533] = {id = 85071533, name = "呀！"},
  [85081531] = {
    id = 85081531,
    name = "正中红心！"
  },
  [85081532] = {
    id = 85081532,
    name = "瞄准——"
  },
  [85091531] = {
    id = 85091531,
    name = "不会让你逃掉！"
  },
  [85091532] = {
    id = 85091532,
    name = "希尔的箭不会射偏。"
  },
  [85101531] = {id = 85101531, name = "呜啊~"},
  [85101532] = {id = 85101532, name = "哇~"},
  [85101533] = {id = 85101533, name = "呃啊~"},
  [85111531] = {
    id = 85111531,
    name = "好痛痛~真可恶！"
  },
  [85121531] = {
    id = 85121531,
    name = "如果修行能再努力一点......"
  },
  [85131531] = {
    id = 85131531,
    name = "希尔这次有好好按照计划行动，胜利是理所当然哒~"
  },
  [85141531] = {
    id = 85141531,
    name = "为什么会这样呢，难道是希尔又搞错计划安排了吗？"
  },
  [85151531] = {
    id = 85151531,
    name = "今天是哥哥的生日吧？嘿嘿，希尔给哥哥准备了礼物哦！是什么？现在还不能看，姐妹们都在等着给哥哥庆祝，我们先去吃蛋糕吧~"
  },
  [85161531] = {
    id = 85161531,
    name = "吃汤圆咯~嘿嘿，希尔最喜欢吃软软糯糯的汤圆了！不过好奇怪啊，为什么其他地方很少看到这样的食物呢，难道这是我们家的秘传美食？！"
  },
  [85171531] = {
    id = 85171531,
    name = "代表感谢的日子为什么要送那种苦苦的点心呢，送别的会更好吧——啊，玩具小熊怎么样！"
  },
  [85181531] = {
    id = 85181531,
    name = "赛珂姐姐不在这里吧？呼~那就好。她平时虽然很温柔，但这种节日里她也会做很多恶作剧，就连灵遥姐姐也逃不掉！"
  },
  [85191531] = {
    id = 85191531,
    name = "希尔今年就不要礼物了，老爷爷每年这个时候都要给那么多孩子送礼物，一定非常辛苦！等他今晚过来了，哥哥记得叫醒我，我想当面感谢他。"
  },
  [85011541] = {
    id = 85011541,
    name = "深渊航线，月蚀。根据邀约内容，我会以个人名义为探险行动提供支援，希望我们合作愉快。"
  },
  [85021541] = {
    id = 85021541,
    name = "你还可以多休息一下，周围的情况我已经再次确认过了，暂时没有发现危险。"
  },
  [85031541] = {
    id = 85031541,
    name = "我一度认为自己有足够的力量肃清深渊中那些罪恶，直到我亲眼见到这个混沌的世界时才明白了自己的渺小，只凭我自己根本无法为这个世界带来安宁和希望。所以当我得知深渊航线中有志同道合的同伴时，我便有了决定——"
  },
  [85031542] = {
    id = 85031542,
    name = "除了真正需要帮助的人，有时候也会有一些“讨厌的人”雇佣我们，我每次遇到都会果断拒绝。这种行为虽然算不上违反规定，但次数多了之后，我也被组织扣罚了不少酬金......"
  },
  [85041541] = {
    id = 85041541,
    name = "即便是客人的要求，我也绝不会做与自己的“正义”相违背的事。"
  },
  [85041542] = {
    id = 85041542,
    name = "我只会选择志同道合的人成为同伴，若没有相似的信念，无论拥有怎样的实力和身份我也难以认同。"
  },
  [85041543] = {
    id = 85041543,
    name = "我现在的力量依然不足以肃清这深渊中的混沌和黑暗，但只要和同伴们一起努力，终有一天可以实现这个夙愿。"
  },
  [85051541] = {
    id = 85051541,
    name = "揭露罪恶的手段有很多，但对我而言，没有什么手段比自己亲自贯彻正义更加有效。"
  },
  [85051542] = {
    id = 85051542,
    name = "深渊航线拥有众多能力各异的成员，无论怎样棘手的问题，都能在组织中找到解决办法。"
  },
  [85051543] = {
    id = 85051543,
    name = "我并不喜欢组织中那些规定，可是如果没有那些规定，我们又无法实现守护深渊秩序的目的。"
  },
  [85051544] = {
    id = 85051544,
    name = "指点我修行的人是一位剑术大师，她也曾是一位优秀的探险者，只是在见识过深渊的残酷之后她选择了离开......"
  },
  [85051545] = {
    id = 85051545,
    name = "每个人都应当为自己的选择负责，只要是自己决定的未来，即便荆棘遍布，也绝不能后退和畏惧。"
  },
  [85061541] = {
    id = 85061541,
    name = "警戒的任务请放心交给我。"
  },
  [85071541] = {id = 85071541, name = "嘿！"},
  [85071542] = {id = 85071542, name = "哈！"},
  [85071543] = {id = 85071543, name = "呀！"},
  [85081541] = {
    id = 85081541,
    name = "剑光，闪耀吧！"
  },
  [85081542] = {
    id = 85081542,
    name = "没有机会了。"
  },
  [85091541] = {
    id = 85091541,
    name = "献上终结的时刻到了。"
  },
  [85091542] = {
    id = 85091542,
    name = "没有罪恶能从我的剑下逃脱。"
  },
  [85101541] = {id = 85101541, name = "呜啊。"},
  [85101542] = {id = 85101542, name = "呃啊。"},
  [85101543] = {id = 85101543, name = "唔。"},
  [85111541] = {
    id = 85111541,
    name = "想阻止我？这种程度还差得远呢。"
  },
  [85121541] = {
    id = 85121541,
    name = "只凭我，果然......做不到......"
  },
  [85131541] = {
    id = 85131541,
    name = "已完成彻底肃清，至少近期这条路上不会再出现什么危险。"
  },
  [85141541] = {
    id = 85141541,
    name = "真是难缠的对手，我们先撤，等待支援。"
  },
  [85151541] = {
    id = 85151541,
    name = "听说今天是你的生日？我只是确认一下......听说不远的圈落中有条很繁华的商业街，今天行动结束一起去看看？当然，这只是私人邀请——"
  },
  [85161541] = {
    id = 85161541,
    name = "我的父母并不认同我成为探险者的理念，所以我们在一起时经常会发生争吵，就算新年也很少有安宁的时候。当时我非常渴望能早点离开那个家，可是真的离开了，却又有些想念......"
  },
  [85171541] = {
    id = 85171541,
    name = "来看看我雕刻的这枚护符怎么样？——很不错？谢谢。这是我参照自己佩戴的护符雕刻的，送给你。长期在深渊行动，很需要一块寓意平安的护符吧？"
  },
  [85181541] = {
    id = 85181541,
    name = "怎么？你也被人拜托帮忙贩售节日商品了？呵呵，我也是，不过被我直接轰走了。走吧，我们一起去逛逛吧，错过这样热闹的日子不免会觉得可惜。"
  },
  [85191541] = {
    id = 85191541,
    name = "我的这柄剑是父母送给我的节日礼物，他们希望我能通过剑术修行陶冶心性，可是我却爱上了剑术......我相信总有一天我们能理解彼此，毕竟我们都拥有相似的目标，只是选择的方式不同。"
  },
  [85011551] = {
    id = 85011551,
    name = "贵安~鬼牌、鬼魅应您的邀约而来，呵呵~奴家正是那个传闻中令探险者畏惧的鬼魅。不过传闻嘛，都只是些毫无根据的流言罢了~"
  },
  [85021551] = {
    id = 85021551,
    name = "贵安~鬼魅恭候您的归来。请问来点红茶还是咖啡呢，还是说直接去巡查我们的乐园？"
  },
  [85031551] = {
    id = 85031551,
    name = "深渊中有一股神秘的力量在引诱着人们隐藏于灵魂深处的欲望，有时候只需要轻轻一推，那些压抑的欲望便会喷涌而出，吞噬所谓的意志和信念。"
  },
  [85031552] = {
    id = 85031552,
    name = "对我们而言，深渊如同一个完美的乐园，无论如何挑剔的观众，都能在这欣赏到心仪的表演~而聚集了众多观众的鬼牌，则可以算得上这个乐园的主人。"
  },
  [85041551] = {
    id = 85041551,
    name = "您在渴望着怎样的好戏呢？不管悲剧喜剧还是闹剧，奴家都能为您安排~"
  },
  [85041552] = {
    id = 85041552,
    name = "掌控一切的感觉固然美妙，但真正高明的观众只需要对表演者稍加引导，就足以让演出变得更加精彩。"
  },
  [85041553] = {
    id = 85041553,
    name = "那些寻常的闹剧已经难以让奴家满足，让我们一起搅动整个乐园，来一场盛大的表演如何？"
  },
  [85051551] = {
    id = 85051551,
    name = "奴家才不喜欢和那些傲慢的人呆在一起，有她们在场，无论如何精彩的表演都会让人觉得索然无味......"
  },
  [85051552] = {
    id = 85051552,
    name = "在这乐园中我看过了无数戏剧，最令人难忘的、果然还是那些表演者演绎被欲望吞噬瞬间的场景。"
  },
  [85051553] = {
    id = 85051553,
    name = "在这个乐园中，即便是相同的剧本，不同的表演者也会演绎出只属于他们的戏剧。"
  },
  [85051554] = {
    id = 85051554,
    name = "欲望并非罪恶，无论那些庸碌的表演者还是你我，我们都在依照自己的欲望而行动，若这个世界没有了欲望，一切都将停滞不前。"
  },
  [85051555] = {
    id = 85051555,
    name = "哦~竟然知道“昆娜”这个名字，大人果然很在意奴家吧？呵呵，真是荣幸~不过鬼牌的人不存在过去，大人只要知道奴家是传闻中的鬼魅就足够了。"
  },
  [85061551] = {
    id = 85061551,
    name = "奴家会安排好一切。"
  },
  [85071551] = {id = 85071551, name = "嘿咿。"},
  [85071552] = {id = 85071552, name = "呀啊~"},
  [85071553] = {id = 85071553, name = "哈！"},
  [85081551] = {
    id = 85081551,
    name = "交给奴家。"
  },
  [85081552] = {
    id = 85081552,
    name = "尽在掌控之中~"
  },
  [85091551] = {
    id = 85091551,
    name = "来吧，让演出变得更有趣吧。"
  },
  [85091552] = {
    id = 85091552,
    name = "最精彩的一幕，即将上演~"
  },
  [85101551] = {id = 85101551, name = "呜啊~"},
  [85101552] = {id = 85101552, name = "哇~"},
  [85101553] = {id = 85101553, name = "唔~"},
  [85111551] = {
    id = 85111551,
    name = "一点小意外而已，无碍。"
  },
  [85121551] = {
    id = 85121551,
    name = "是乐园......也是囚笼......"
  },
  [85131551] = {
    id = 85131551,
    name = "就算已经感受过无数次，这种感觉依然令人陶醉~"
  },
  [85141551] = {
    id = 85141551,
    name = "竟然脱离了掌控......从哪个环节开始的呢......"
  },
  [85151551] = {
    id = 85151551,
    name = "恭祝大人生日快乐~怎么知道的？呵呵~那并不重要，这种日子里，大人只需要好好享受奴家为您安排的庆典就好了。"
  },
  [85161551] = {
    id = 85161551,
    name = "又到了乐园中重要的庆典了，呵呵~一起去四处走走吧大人，每到这个时候，乐园中总会有不少令人惊喜的事发生。"
  },
  [85171551] = {
    id = 85171551,
    name = "贵安，大人~奴家为您准备了一些特别的点心，请享用吧~虽然颜色有些发黑，但味道很不错的，您该不会拒绝奴家吧？"
  },
  [85181551] = {
    id = 85181551,
    name = "今天明明是属于“鬼”的节日，但是却成为了人们狂欢的庆典，呵呵~果然在某些层面，“人”比“鬼”更加厉害吧？"
  },
  [85191551] = {
    id = 85191551,
    name = "这是、大人送给奴家的？......非常感谢大人的赏赐，这一定是鬼魅在乐园中最值得铭记的事！奴家该为大人准备怎样的回礼呢？"
  },
  [85011701] = {
    id = 85011701,
    name = "探险者伊涅利丝，非常荣幸能收到您的邀请，希望我的表现不会辜负您的期望。"
  },
  [85021701] = {
    id = 85021701,
    name = "营地周围我已经确认过了，并无异常。不过在巡视中发现个很不错的地方，一会儿带您去看看？"
  },
  [85031701] = {
    id = 85031701,
    name = "以前我身边没有可以吐露心声的人，不管遇到什么事都只能藏在心里，直到我发现一个秘密基地......那是一片非常美丽的花田，在那里，无论开心还是沮丧，我都能毫无顾忌的呼喊出来。"
  },
  [85031702] = {
    id = 85031702,
    name = "深渊中的生活虽然辛苦，但我很喜欢现在的一切。和探险队的大家相处时，我可以安心做自己想做的事，不用考虑那么多复杂的问题，也不用担心被大家误解。"
  },
  [85041701] = {
    id = 85041701,
    name = "很高兴能得到您的认可，我会努力回报您的期望。"
  },
  [85041702] = {
    id = 85041702,
    name = "我能清晰地感受到自己的变化，多亏了队长和大家我才能成长得如此迅速。"
  },
  [85041703] = {
    id = 85041703,
    name = "变强的感觉固然不错，但对我来说，不管获得怎样的力量，都比不上您的认可。"
  },
  [85051701] = {
    id = 85051701,
    name = "我对名利、权势之类的事并不感兴趣，所以我选择了成为探险者，孤身前往深渊。"
  },
  [85051702] = {
    id = 85051702,
    name = "虽然深渊中同样存在利益纠葛，存在阴谋诡计，但在这里，我可以选择志同道合的同伴，远离纷争的漩涡。"
  },
  [85051703] = {
    id = 85051703,
    name = "养父是我父亲的挚友，父亲遇难后他便将我接到了身边，对我百般呵护......所以不管兄妹们怎么对我，我也想要回报他的恩情。"
  },
  [85051704] = {
    id = 85051704,
    name = "每次和大家一起行动时，我都感觉自己充满了勇气，似乎不管面对怎样的情况也不会畏惧。"
  },
  [85051705] = {
    id = 85051705,
    name = "我并没有什么远大的理想，能够拥有相互珍视的人，相互依靠的同伴，然后一起探寻这个神秘的世界，对我来说就足够了。"
  },
  [85061701] = {
    id = 85061701,
    name = "麻烦的敌人请尽管交给我。"
  },
  [85071701] = {id = 85071701, name = "嘿咿"},
  [85071702] = {id = 85071702, name = "咿呀"},
  [85071703] = {id = 85071703, name = "喝呃"},
  [85081701] = {
    id = 85081701,
    name = "锁定目标。"
  },
  [85081702] = {
    id = 85081702,
    name = "逃不掉的。"
  },
  [85091701] = {
    id = 85091701,
    name = "见识飓风的愤怒吧！"
  },
  [85091702] = {
    id = 85091702,
    name = "这便是飓风的意志。"
  },
  [85101701] = {id = 85101701, name = "唔呃"},
  [85101702] = {id = 85101702, name = "呃啊"},
  [85101703] = {id = 85101703, name = "呀啊"},
  [85111701] = {
    id = 85111701,
    name = "别在意，我还能继续。"
  },
  [85121701] = {
    id = 85121701,
    name = "对不起......辜负了您的期望......"
  },
  [85131701] = {
    id = 85131701,
    name = "大家都辛苦了，请先休息一下，清扫战场就交给我吧。"
  },
  [85141701] = {
    id = 85141701,
    name = "抱歉，是我太紧张了......下次，下次我一定会表现得更好！"
  },
  [85151701] = {
    id = 85151701,
    name = "今天可以分一点时间给我吗？——做什么？当然是为某个“大忙人”庆祝生日啦！毕竟如果我不准备，你一定会忙着处理各种事，就这么随意过了吧？"
  },
  [85161701] = {
    id = 85161701,
    name = "新年快乐！一起去圈落逛逛吗？请放心，探险队的各种事务我都已经处理好了，今天就稍微放松一下吧。"
  },
  [85171701] = {
    id = 85171701,
    name = "队长喜欢金木犀吗？呵呵，现在当然不是金木犀的时节。不过我此前采集了一束，用特殊方法保存了下来......请问可以收下吗？"
  },
  [85181701] = {
    id = 85181701,
    name = "加入探险队之前，我也曾参加过无数次庆典，但从没有哪一次能让我觉得如此满足......果然不管怎样的节日，都只有和重要的人一起度过才有意义。"
  },
  [85191701] = {
    id = 85191701,
    name = "队长，请问今天有时间吗？我为大家准备了些礼物，一个人分发时间有些紧张......当然，我也为队长准备了特别的谢礼，请期待吧！"
  },
  [85011611] = {
    id = 85011611,
    name = "您好，我是探险者黑羽，愿我们的努力可以为深渊带来更多正义和希望。"
  },
  [85021611] = {
    id = 85021611,
    name = "危险无处不在，任何一点疏忽都有可能带来灾祸，我们制定行动计划时得更加谨慎才行。"
  },
  [85031611] = {
    id = 85031611,
    name = "许多人被欲望蒙蔽了双眼，摒弃良知，一味追求利益。比起普通人，他们更容易被浊炁侵蚀，如果弃之不顾，等待他们的只有成为堕落者的末路。"
  },
  [85031612] = {
    id = 85031612,
    name = "委托变多固然是好事，但未说明详细内容的，绝不能轻易接受！否则要是被要求穿一些奇怪的衣服——唔，总之接受委托前，必须了解具体的工作内容，包括着装要求！"
  },
  [85041611] = {
    id = 85041611,
    name = "力量并不代表正义，但没有力量，则无法守护正义。"
  },
  [85041612] = {
    id = 85041612,
    name = "每个人都有自己的正义和坚持，我的正义，便是与所有罪恶为敌。除恶未尽，战斗不息！"
  },
  [85041613] = {
    id = 85041613,
    name = "因为有足够的理由，所以我的剑不会犹豫。"
  },
  [85051611] = {
    id = 85051611,
    name = "初到深渊时，我所见到的一切和想象中差距很大，一度想要放弃......"
  },
  [85051612] = {
    id = 85051612,
    name = "我在游历过程中，目睹了太多步入末路之人的惨状，于是开始思索自己能为他们做点什么。"
  },
  [85051613] = {
    id = 85051613,
    name = "我并没伟大到想要拯救所有人，只是在寻找自己的人生时，做些力所能及的事而已。"
  },
  [85051614] = {
    id = 85051614,
    name = "只要有足够的力量，惩戒罪恶并非难事。真正棘手的，在于如何为深渊带来救赎。"
  },
  [85051615] = {
    id = 85051615,
    name = "我来深渊是希望找到自己前行的方向，却一直没有什么进展......现在想来，我或许已经走在了正确的路上。"
  },
  [85061611] = {
    id = 85061611,
    name = "我已准备好迎接胜利。"
  },
  [85071611] = {id = 85071611, name = "喝！"},
  [85071612] = {id = 85071612, name = "嘿！"},
  [85071613] = {id = 85071613, name = "哈啊-"},
  [85081611] = {
    id = 85081611,
    name = "哼，觉悟吧！"
  },
  [85081612] = {
    id = 85081612,
    name = "到此为止。"
  },
  [85091611] = {
    id = 85091611,
    name = "心存希望，便有无尽可能。"
  },
  [85091612] = {
    id = 85091612,
    name = "以守护之名，于此显现奇迹。"
  },
  [85101611] = {id = 85101611, name = "啊。"},
  [85101612] = {id = 85101612, name = "呃。"},
  [85101613] = {id = 85101613, name = "唔啊。"},
  [85111611] = {
    id = 85111611,
    name = "我会战斗到最后一刻。"
  },
  [85121611] = {
    id = 85121611,
    name = "我还能......坚持......"
  },
  [85131611] = {
    id = 85131611,
    name = "我们有充足的理由和必胜的信念，胜利自然属于我们。"
  },
  [85141611] = {
    id = 85141611,
    name = "大家快走，这里交给我！"
  },
  [85151611] = {
    id = 85151611,
    name = "每个人的生日都是特别的，在这一天，只要不是过分的要求都会被满足，有什么我能为你做的吗？"
  },
  [85161611] = {
    id = 85161611,
    name = "小时候我特别渴望新年，那时候家里贫苦，只有新年时才能吃到稍微丰盛一点食物......后来父亲找到了我们，生活变得富足，可以随便享用各种食物，可是，那种渴望的心情却慢慢消失了......"
  },
  [85171611] = {
    id = 85171611,
    name = "我来到深渊已有不少时间，但真正能理解、并支持我的，却只有你......非常感谢，你的信任和支持让我有了继续前行的力量。"
  },
  [85181611] = {
    id = 85181611,
    name = "当没有罪恶和危险时，人们才能尽情享受节日，展露真心的笑容，我所做的一切，正是为了守护这些美好。"
  },
  [85191611] = {
    id = 85191611,
    name = "自从和父亲一起生活，每个节日他都为我准备一大堆礼物......我明白他那种想要补偿我和母亲的心情，可是有一些心结，是无法用礼物解开的。"
  },
  [85011691] = {
    id = 85011691,
    name = "您就是队长吧？虽然是初次见面，但我已经听说过您的诸多事迹。探险者阿斯特莉亚，非常荣幸能与您共事。"
  },
  [85021691] = {
    id = 85021691,
    name = "队长，这些我处理好的事务能劳烦您再确认一下吗？呵呵，这可算不上谨慎，而是我没有自信能做得像您一样好。"
  },
  [85031691] = {
    id = 85031691,
    name = "以前我并不习惯与别人打交道，只是迫于身份不得不去做，为此还进行了不少训练......具体的？呵呵，如果队长感兴趣，我可以陪您一起特训。"
  },
  [85031692] = {
    id = 85031692,
    name = "难得空闲，真想找个地方小憩一下。忙碌后适当小憩会非常舒服，队长要试试吗？请放心，我会负责叫醒你的，不会耽误之后的工作。"
  },
  [85041691] = {
    id = 85041691,
    name = "在父亲还活着的时候，在那场动乱爆发之前，我并不觉得力量是不可或缺地存在。"
  },
  [85041692] = {
    id = 85041692,
    name = "我曾畏惧那些强大的力量，认为它们只会带来灾祸和破坏，但现在，我很庆幸自己拥有这样的力量。"
  },
  [85041693] = {
    id = 85041693,
    name = "我不会再选择逃避，为了我们所渴求的存在，无论前路多么坎坷，我也会坚持下去。"
  },
  [85051691] = {
    id = 85051691,
    name = "离开领地后的生活比我想象中困难多了，不过也拜此所赐，我才切实感受到了普通人生活的艰辛与无奈，也才明白了曾经的自己有多么天真。"
  },
  [85051692] = {
    id = 85051692,
    name = "以前我会因“不喜欢”“不感兴趣”就选择放弃，现在的我，已经不会再因为这种简单的理由就做出决定了。"
  },
  [85051693] = {
    id = 85051693,
    name = "父亲意外去世后，我担任过一段时间的领主，只是那时候我能做的，仅仅是在叔伯舅舅们递来的各种看不懂的文书上，工整地写下自己的名字。"
  },
  [85051694] = {
    id = 85051694,
    name = "当悲剧发生时，我只能眼睁睁看着一个个亲密的人消失，整日担心那些熟悉的面孔是否会突然变得陌生......我不想再体验那种无能为力的感觉了。"
  },
  [85051695] = {
    id = 85051695,
    name = "如果说每个来深渊的人都有自己所渴求的事物，那么队长心中所渴求的，会是什么呢？"
  },
  [85061691] = {
    id = 85061691,
    name = "我不会再让重要的人受到伤害。"
  },
  [85071691] = {id = 85071691, name = "喝~"},
  [85071692] = {id = 85071692, name = "咿呀。"},
  [85071693] = {id = 85071693, name = "哈咿。"},
  [85081691] = {
    id = 85081691,
    name = "覆灭吧。"
  },
  [85081692] = {
    id = 85081692,
    name = "凝聚、爆裂！"
  },
  [85091691] = {
    id = 85091691,
    name = "将灾厄消灭于萌芽。"
  },
  [85091692] = {
    id = 85091692,
    name = "以毁灭守卫安宁。"
  },
  [85101691] = {id = 85101691, name = "唔呃。"},
  [85101692] = {id = 85101692, name = "呀~ "},
  [85101693] = {id = 85101693, name = "呃啊。"},
  [85111691] = {
    id = 85111691,
    name = "不会让你们得逞。"
  },
  [85121691] = {
    id = 85121691,
    name = "我依然......无能为力......"
  },
  [85131691] = {
    id = 85131691,
    name = "比起看得见的纷争，那些隐藏于暗处，不见硝烟的争斗才更值得我们警惕。"
  },
  [85141691] = {
    id = 85141691,
    name = "请允许我留下断后，我会为大家争取足够的撤离时间。"
  },
  [85151691] = {
    id = 85151691,
    name = "非常荣幸能与队长一起度过如此重要的日子，我准备了一场简单的晚宴，希望您能喜欢。"
  },
  [85161691] = {
    id = 85161691,
    name = "以前每个新年父亲都会带我一起巡视领地，那种感觉和队长带我巡查探险队驻地时很像，让人觉得无比安心、平静。"
  },
  [85171691] = {
    id = 85171691,
    name = "尽管尝试了无数次，我却始终做不出别人那样精致的点心......队长可以收下这份点心吗？虽然不够精美，但口味是按您喜欢的味道调制的。"
  },
  [85181691] = {
    id = 85181691,
    name = "我之前参加庆典时，稍微被几个孩子的装扮惊吓到了，队长可以陪我参加今天的庆典吗？有您在身边，我想不管遇到什么都不会害怕。"
  },
  [85191691] = {
    id = 85191691,
    name = "听说这种节日的习俗是和重要的人交换礼物，但我的礼物都是自己做的，并不贵重，如果您不嫌弃的话，可以和我交换吗——可以？真的可以吗？！"
  },
  [85011801] = {
    id = 85011801,
    name = "我便是鬼侍，你只需告诉我挥剑的目标，然后、挑选他们的墓地——"
  },
  [85021801] = {
    id = 85021801,
    name = "无法挥剑的每一刻都无聊至极，下一个对手确定好了吗？"
  },
  [85031801] = {
    id = 85031801,
    name = "深渊隔绝了地面，也隔绝了许多人心中模糊的界限。只要有足够的实力，便能在这个世界中尽情宣泄自己的欲望。"
  },
  [85031802] = {
    id = 85031802,
    name = "如果没有那场变故，或许在某个地方，某位领主的女儿正在享受郊游吧......如果没有那么多利欲熏心的人，或许鬼侍，不，甚至鬼牌也不会存在。"
  },
  [85041801] = {
    id = 85041801,
    name = "我对那些利益纷争并不感兴趣，任何想将我卷入纷争漩涡的人都不会有太好的结局。"
  },
  [85041802] = {
    id = 85041802,
    name = "解除了束缚的鬼侍会有多强？哼，你很快就会知道了。"
  },
  [85041803] = {
    id = 85041803,
    name = "只要能给鬼侍尽情挥剑的机会，无论人还是魔物，鬼侍都会斩给你看！"
  },
  [85051801] = {
    id = 85051801,
    name = "我并不理解鬼姬的那些恶趣味，也没有探究的兴趣，在我看来任何事都只需要考虑放任或者抹除就足够了。"
  },
  [85051802] = {
    id = 85051802,
    name = "我和鬼牌中其他人不同，并不渴求那些所谓的乐趣，从成为鬼侍的那一刻起，我所渴求的便只剩挥剑而已。"
  },
  [85051803] = {
    id = 85051803,
    name = "鬼爵的行事作风我并不讨厌，虽然不清楚她的目的，但冷眼旁观，也算得是上一种很好的放任方式。"
  },
  [85051804] = {
    id = 85051804,
    name = "只有肆意挥剑之时，我才能清晰地感受到自己的一切，所以我只要知道目标就足够了，理由、借口通通不重要。"
  },
  [85051805] = {
    id = 85051805,
    name = "柯莱...特尔......竟然还有人记得这个名字，不过已经不重要了，即便她还在，也只会沦为别人欲望之下的余烬。"
  },
  [85061801] = {
    id = 85061801,
    name = "我会抹除所有敌人。"
  },
  [85071801] = {id = 85071801, name = "哈嘿！"},
  [85071802] = {id = 85071802, name = "喝！"},
  [85071803] = {id = 85071803, name = "呀啊！"},
  [85081801] = {
    id = 85081801,
    name = "哀嚎吧！"
  },
  [85081802] = {
    id = 85081802,
    name = "挣扎只是徒劳。"
  },
  [85091801] = {
    id = 85091801,
    name = "在恐惧中颤栗吧！"
  },
  [85091802] = {
    id = 85091802,
    name = "你们的恐惧，鬼侍收下了。"
  },
  [85101801] = {id = 85101801, name = "嘁~"},
  [85101802] = {id = 85101802, name = "唔。"},
  [85101803] = {id = 85101803, name = "呃。"},
  [85111801] = {
    id = 85111801,
    name = "鬼侍记住你了。"
  },
  [85121801] = {
    id = 85121801,
    name = "或许......早该结束了......"
  },
  [85131801] = {
    id = 85131801,
    name = "下一个目标、在哪？"
  },
  [85141801] = {
    id = 85141801,
    name = "下一次，我的剑不会再犹豫。"
  },
  [85151801] = {
    id = 85151801,
    name = "我对生日已经没有太多印象了，要做些什么好呢？现在的我只会战斗......那么就让我为你战斗到最后一刻，如何？"
  },
  [85161801] = {
    id = 85161801,
    name = "今天确实是很热闹的日子，但和鬼侍没有关系......从我成为鬼侍那一刻起，所寻求的便只有挥剑的目标。"
  },
  [85171801] = {
    id = 85171801,
    name = "感谢吗......告诉我你想要抹除的存在，不管是怎样的目标，鬼侍一定会为你达成。"
  },
  [85181801] = {
    id = 85181801,
    name = "你害怕幽灵吗？这个世界上明明还有许多比它们更加可怕的存在......不必担心，只要是存在的事物，无论是什么我的剑都可以斩断！"
  },
  [85191801] = {
    id = 85191801,
    name = "礼物？我的？如果有想要抹除的敌人，无需做这种无聊的事。节日礼物？是、是嘛......谢谢。"
  },
  [85011621] = {
    id = 85011621,
    name = "妹妹们都到了吧？我在路上遇到点事，耽搁了不少时间......难得和她们比试一场，似乎让她们赢得太轻松了~"
  },
  [85021621] = {
    id = 85021621,
    name = "调皮的妹妹们又被赛珂抓回去学习了，有这样能干的妹妹真好，完全都不用我和大叔去操心。"
  },
  [85031621] = {
    id = 85031621,
    name = "最初指导妹妹们修行、制定大家行动计划的事都是我在负责，非常辛苦！所以当我发现赛珂妹妹对大家的了解程度也不亚于我之后......嘿嘿，能干的妹妹自然应该为姐姐多分担一点事情嘛~"
  },
  [85031622] = {
    id = 85031622,
    name = "我平日里基本都和大叔一起在各地奔走，处理魔物的事情，很少有机会陪伴妹妹们。这段时间难得空闲，本想和大家一起好好放松一下，却被赛珂妹妹说没有姐姐的样子，还要我带她们一起修行，唉~"
  },
  [85041621] = {
    id = 85041621,
    name = "为了能更好地解决魔物祸患，我还有很多事情要做。"
  },
  [85041622] = {
    id = 85041622,
    name = "深渊中固然隐藏着不少危机，但和信任的人在一起时稍微放松一点也没关系。"
  },
  [85041623] = {
    id = 85041623,
    name = "似乎想到些解决问题的好办法，下一次遇到魔物祸患时也许能用得上。"
  },
  [85051621] = {
    id = 85051621,
    name = "我还很小的时候大叔就经常带着我在深渊中四处奔走，所以我对深渊并不像妹妹们那样充满向往。"
  },
  [85051622] = {
    id = 85051622,
    name = "魔物的可怕并非只是强大的实力，它们的神秘和未知才更令人畏惧。"
  },
  [85051623] = {
    id = 85051623,
    name = "赛珂妹妹经常说我太惯着妹妹们了，其实我是觉得在没有危险的时候，大家能追寻各自的快乐也是一种不错的选择。"
  },
  [85051624] = {
    id = 85051624,
    name = "妹妹们都以我为目标在努力修行，那么我也以大叔为目标继续努力吧。呵呵，要是轻易被妹妹们赶上，赛珂妹妹又该说我了。"
  },
  [85051625] = {
    id = 85051625,
    name = "解决魔物祸患是我的使命，我自然会全力以赴，但妹妹们都是我最重要的家人，守护家人也是我义不容辞的责任。"
  },
  [85061621] = {
    id = 85061621,
    name = "棘手的事交给我就行。"
  },
  [85071621] = {id = 85071621, name = "看招！"},
  [85071622] = {id = 85071622, name = "看招！"},
  [85071623] = {id = 85071623, name = "看招！"},
  [85081621] = {
    id = 85081621,
    name = "有破绽。"
  },
  [85081622] = {
    id = 85081622,
    name = "不堪一击。"
  },
  [85091621] = {
    id = 85091621,
    name = "只要是敌人，我绝不留情！"
  },
  [85091622] = {
    id = 85091622,
    name = "该结束了，觉悟吧！"
  },
  [85101621] = {id = 85101621, name = "唔。"},
  [85101622] = {id = 85101622, name = "呜啊。"},
  [85101623] = {id = 85101623, name = "呃。"},
  [85111621] = {
    id = 85111621,
    name = "这样是阻止不了我的。"
  },
  [85121621] = {
    id = 85121621,
    name = "有心除魔......无力回天......"
  },
  [85131621] = {
    id = 85131621,
    name = "这次战斗还算顺利，不过胜利只是暂时的，还不能大意。"
  },
  [85141621] = {
    id = 85141621,
    name = "对方锋芒正胜，不宜久战。我会拖住它们，大家快撤！"
  },
  [85151621] = {
    id = 85151621,
    name = "哥哥你总算来了，大家已经准备好庆典了——什么庆典？难道哥哥把生日也忘了？！真是粗心啊，还好我们做妹妹的记得，走吧，等一下菜都要凉了。"
  },
  [85161621] = {
    id = 85161621,
    name = "大叔常说新年是逍遥坊最重要的日子，也是我们一家团圆的日子，不管多忙他都会赶回来团聚。呵呵~希望他能在汤圆凉掉之前赶到吧。"
  },
  [85171621] = {
    id = 85171621,
    name = "哥哥来看看这个——这是大叔教我编织的物件，好像叫“同心结”，据说同时佩戴的人可以一直保持亲密，哥哥是我重要的家人，请收下这个吧。"
  },
  [85181621] = {
    id = 85181621,
    name = "恶作剧和糖果都是孩子们最喜欢的，所以这种节日是孩子们的狂欢节，对我们来说没太多意义。不过很久没有和妹妹们一起玩了，偶尔放松一下也不错~"
  },
  [85191621] = {
    id = 85191621,
    name = "以前大家都还在一起生活的时候，这种节日大叔会给我们每个人都准备礼物，我这件衣服就是大叔亲手缝制的礼物，没错，亲手缝制！"
  },
  [85011821] = {
    id = 85011821,
    name = "我收到大哥的邀请就马上出发了，可是，我迷路了......下次，下次比赛我不会再输给姐姐们了！"
  },
  [85021821] = {
    id = 85021821,
    name = "四姐约我一起训练，可是等了很久也没看到人，难道和三姐一起玩去了？算了，今天我先按大姐和二姐的指导继续练习吧。"
  },
  [85031821] = {
    id = 85031821,
    name = "姐姐们决定的事我都不会有意见，大姐游历四方，二姐博览群书，她们的阅历和见识我还远远比不上。不过总有一天，我也会成为她们那样优秀的人。"
  },
  [85031822] = {
    id = 85031822,
    name = "我的天赋并不算出色，所以只能靠更多的努力来弥补。虽然大叔经常告诉我只需要将自己当作对手就足够了，可是如果那样做，我害怕自己会跟不上姐姐们的步伐。"
  },
  [85041821] = {
    id = 85041821,
    name = "优秀的姐姐们就是我前进最大的动力。"
  },
  [85041822] = {
    id = 85041822,
    name = "我的极限可不只是这样，只要能再努力一点，就可以变得更强！"
  },
  [85041823] = {
    id = 85041823,
    name = "大叔曾对我说，有些事我也可以做的比任何人都更好，所以我不会就此止步。"
  },
  [85051821] = {
    id = 85051821,
    name = "大姐经常跟着大叔在深渊活动，实力比其他姐姐更强，所以我也想要到深渊历练，提升实力。"
  },
  [85051822] = {
    id = 85051822,
    name = "我想拥有能守护家人的力量，也想和大姐一样随心所欲的游历四方。"
  },
  [85051823] = {
    id = 85051823,
    name = "四姐经常拉着我一起和三姐进行一些很奇怪的比试，我虽然没弄明白，但既然是姐姐们做的事，就一定有那样做的道理。"
  },
  [85051824] = {
    id = 85051824,
    name = "三姐经常用书盖着脸睡觉，我好像也曾看到大叔那样做过......这或许是某种特别的修行方式，我也试试！"
  },
  [85051825] = {
    id = 85051825,
    name = "我一直在姐姐们的关照下长大，所以我才想要有更强的力量回应大家的期待，成为让姐姐们骄傲的妹妹。"
  },
  [85061821] = {
    id = 85061821,
    name = "我明白自己该做的事。"
  },
  [85071821] = {id = 85071821, name = "哈啊！"},
  [85071822] = {id = 85071822, name = "嘿！"},
  [85071823] = {id = 85071823, name = "呀咿！"},
  [85081821] = {
    id = 85081821,
    name = "饶不了你。"
  },
  [85081822] = {
    id = 85081822,
    name = "放弃挣扎吧！"
  },
  [85091821] = {
    id = 85091821,
    name = "小看我可是会付出代价。"
  },
  [85091822] = {
    id = 85091822,
    name = "我绝不会放过任何敌人！"
  },
  [85101821] = {id = 85101821, name = "呀啊。"},
  [85101822] = {id = 85101822, name = "唔。"},
  [85101823] = {id = 85101823, name = "呃啊。"},
  [85111821] = {
    id = 85111821,
    name = "不用担心，我还能坚持。"
  },
  [85121821] = {
    id = 85121821,
    name = "我的努力，还不够吗......"
  },
  [85131821] = {
    id = 85131821,
    name = "只要我们都能按计划做好自己该做的事，胜利就一定属于我们！"
  },
  [85141821] = {
    id = 85141821,
    name = "请让我再试一次，这样的结果不是我们想要的——"
  },
  [85151821] = {
    id = 85151821,
    name = "生日快乐大哥！今天不管有什么事务，都尽管交给我吧，我一定会处理好，大哥只要安心的享受庆典就好了，姐姐们已经都到了，我们也过去吧。"
  },
  [85161821] = {
    id = 85161821,
    name = "每次新年大叔在准备汤圆的时候都会我们讲关于新年的故事，每年的故事都不一样。今年是二姐准备的汤圆，不知道大叔今天回来还会不会讲故事......"
  },
  [85171821] = {
    id = 85171821,
    name = "大哥，这块宝石好看吗？这是我第一次探险时发现的，现在送给你！听大叔如果向重要的人赠送宝石，彼此的关系就能像宝石一样永恒、闪耀。"
  },
  [85181821] = {
    id = 85181821,
    name = "三姐约我今天一起去恶作剧，可是......二姐玩起来很“可怕”，就连大姐和四姐都不太想面对她的恶作剧，我、我果然还是不要和三姐一起了吧......"
  },
  [85191821] = {
    id = 85191821,
    name = "这种节日，我和姐姐们每年都会收到礼物，可是好像从没见大叔收到过，难道是因为他不是孩子了吗？如果是这样，今年我也给大叔准备一份礼物吧。"
  },
  [85011951] = {
    id = 85011951,
    name = "探险者艾瑟儿，现在起正式加入您的探险队，今后的探险请务必允许我同行。"
  },
  [85021951] = {
    id = 85021951,
    name = "精神不错嘛队长，今天的行动计划我已经制定好了，看一下吧，没问题的话就准备行动了。"
  },
  [85031951] = {
    id = 85031951,
    name = "探险的真正乐趣在于亲自探寻那些未知的存在，在于挑战各种凶险绝境后成功脱身，至于宝物和圣物，对我来说只能算是探险中的调味剂。"
  },
  [85031952] = {
    id = 85031952,
    name = "深渊固然凶险，但这里的一切都让我感到新奇，每天经历的事都和昨天完全不同，这样的生活着实让人难以抗拒。"
  },
  [85041951] = {
    id = 85041951,
    name = "要开始新的探险了吗？请放心交给我吧。"
  },
  [85041952] = {
    id = 85041952,
    name = "无论多么凶险恶劣的环境，只要有我在，都算不上绝地。"
  },
  [85041953] = {
    id = 85041953,
    name = "这算是嘉奖吗？还是说，是对我的激励？算了，不管是什么，只要是你给的，我都不会推辞。"
  },
  [85051951] = {
    id = 85051951,
    name = "曾有人说我只会些花哨的技巧，很快就会被深渊所淘汰，但从结果来看，正是那些花哨的技巧帮我脱离了无数危险。"
  },
  [85051952] = {
    id = 85051952,
    name = "冷静才是探险者最重要的能力，无论身陷怎样的困境，面对怎样的挑战，只有保持冷静，才能发现破局点。"
  },
  [85051953] = {
    id = 85051953,
    name = "我最初并没有加入任何探险队的打算，除了不怎么习惯团队行动外，也是在担心自己能否与其他人和睦相处。"
  },
  [85051954] = {
    id = 85051954,
    name = "探索一些凶险绝地时，有时候我也会觉得吃力，所以偶尔也会想“要是有一两个志同道合的同伴就好了”。"
  },
  [85051955] = {
    id = 85051955,
    name = "感觉现在不管遇到怎样的险境绝地，我都能成功完成探索。呵呵，这可不是单纯的自信，而是出于对同伴的绝对信任！"
  },
  [85061951] = {
    id = 85061951,
    name = "随时准备出发。"
  },
  [85071951] = {id = 85071951, name = "哈！"},
  [85071952] = {id = 85071952, name = "嘿！"},
  [85071953] = {id = 85071953, name = "喝！"},
  [85081951] = {
    id = 85081951,
    name = "哼，不堪一击。"
  },
  [85081952] = {
    id = 85081952,
    name = "无用的挣扎。"
  },
  [85091951] = {
    id = 85091951,
    name = "该结束了，觉悟吧！"
  },
  [85091952] = {
    id = 85091952,
    name = "我可不会手下留情。"
  },
  [85101951] = {id = 85101951, name = "唔。"},
  [85101952] = {id = 85101952, name = "呃。"},
  [85101953] = {id = 85101953, name = "呜啊。"},
  [85111951] = {
    id = 85111951,
    name = "不过如此。"
  },
  [85121951] = {
    id = 85121951,
    name = "这次......逃不掉了吗......"
  },
  [85131951] = {
    id = 85131951,
    name = "前进的道路已清理完毕，请吧，我的队长。"
  },
  [85141951] = {
    id = 85141951,
    name = "嘁，真是麻烦的对手。跟我走吧，我会带大家找到出去的路。"
  },
  [85151951] = {
    id = 85151951,
    name = "生日快乐队长！作为庆祝，今天陪我去探险吧——为什么是由生日主角的你陪我？呵呵，那就我陪你去探险？走吧，那个地方真的非常有趣！"
  },
  [85161951] = {
    id = 85161951,
    name = "每到这种重要的节日，父亲都会去探险庆祝，不知道他有没有发现什么好地方......嗯，给他写封信吧，汇报一下我的近况，顺便再从他那里打听些情报。"
  },
  [85171951] = {
    id = 85171951,
    name = "这支金属爪从我开始探险时就一直陪着我，带我脱离了无数困境，现在送给你——收好了吗？那么今后就轮到你来带领我了，千万别忘记咯！"
  },
  [85181951] = {
    id = 85181951,
    name = "我以前独自行动时，从来不会留意这种节日。谢谢你队长，谢谢你邀请我加入了探险队，让我体会到了和以前完全不同的生活。"
  },
  [85191951] = {
    id = 85191951,
    name = "交换礼物？连最信任的同伴之间也需要这样做吗？越是亲近的人越会在意......好吧，让我想想该为你准备些什么才能体现我们的关系吧。"
  },
  [85011561] = {
    id = 85011561,
    name = "探险者罗亚，现在起我们就是最可靠的同伴了。无论何时，无论何种境地，都请站在我的身后。"
  },
  [85021561] = {
    id = 85021561,
    name = "深渊中的许多人都在为今天还能活着醒来感到庆幸，不，不应该是这样......"
  },
  [85031561] = {
    id = 85031561,
    name = "每件事都必须认真对待，每个细节都必须精准把控，只有这样才能最大限度的保证安全。如果当时的我能明白，也许......不，没时间后悔了，今天的生存训练还未完成，走吧。"
  },
  [85031562] = {
    id = 85031562,
    name = "在深渊中，每个人都有自己的目的，但“活下来”是所有人共同的愿望，我正是为了守护这个愿望而存在。"
  },
  [85041561] = {
    id = 85041561,
    name = "更强的力量，也意味着更强的责任。"
  },
  [85041562] = {
    id = 85041562,
    name = "也许这柄剑会破碎，我的身躯会被摧毁，但我的信念，绝不会动摇！"
  },
  [85041563] = {
    id = 85041563,
    name = "如果有一天能平息深渊中的纷争，消弭潜藏的危险......我愿为此付出一切。"
  },
  [85051561] = {
    id = 85051561,
    name = "危险无处不在，任何疏忽大意都可能造成无法挽回的悲剧。"
  },
  [85051562] = {
    id = 85051562,
    name = "我的剑，是为了守护同伴而存在，无论拥有怎样的力量，这一点都绝不会改变。"
  },
  [85051563] = {
    id = 85051563,
    name = "我的这些装备都是父亲留给我的，它们见证了父亲的意志，我也会继承这份意志，继续努力。"
  },
  [85051564] = {
    id = 85051564,
    name = "我曾想要拯救更多的人，并将其当作我活下去的意义，可是最后却发现，在那过程中，真正被拯救的反而是我自己。"
  },
  [85051565] = {
    id = 85051565,
    name = "闭上眼，曾经的一幕幕场景就会浮现在眼前......我不愿再经历那样的结局，不想再承受任何失去......"
  },
  [85061561] = {
    id = 85061561,
    name = "让敌人尽管冲我来吧！"
  },
  [85071561] = {id = 85071561, name = "喝！"},
  [85071562] = {id = 85071562, name = "哈！"},
  [85071563] = {id = 85071563, name = "嘿咿！"},
  [85081561] = {
    id = 85081561,
    name = "决不后退。"
  },
  [85081562] = {
    id = 85081562,
    name = "交给我！"
  },
  [85091561] = {
    id = 85091561,
    name = "以守护之名！"
  },
  [85091562] = {
    id = 85091562,
    name = "放肆，退下！"
  },
  [85101561] = {id = 85101561, name = "唔~"},
  [85101562] = {id = 85101562, name = "呃。"},
  [85101563] = {id = 85101563, name = "呜啊。"},
  [85111561] = {
    id = 85111561,
    name = "嘁，不过如此，再来！"
  },
  [85121561] = {
    id = 85121561,
    name = "我还不能......倒下......"
  },
  [85131561] = {
    id = 85131561,
    name = "有人受伤吗？只有大家都平安才是最好的结果。"
  },
  [85141561] = {
    id = 85141561,
    name = "所有人马上撤离，这里交给我！"
  },
  [85151561] = {
    id = 85151561,
    name = "生日么......该怎样做呢？抱歉，我太久没有作过类似的事了，所以稍微有些不知所措。总之，生日快乐。"
  },
  [85161561] = {
    id = 85161561,
    name = "每一个重要的日子，我们都应当心怀感激的度过。当然，感谢的并非神明，而是那些让我们平安度过节日的每一个人。"
  },
  [85171561] = {
    id = 85171561,
    name = "代表感谢的日子么？......我不太擅长说感谢的话。谢谢您长久以来的关照，让您费心了。——大概是这样？"
  },
  [85181561] = {
    id = 85181561,
    name = "请不用在意我，冰冷的表情和这热闹的节日并不相配吧？或许等到得偿所愿的那一天，我才能无所顾忌的与大家一起享受这种庆典吧。"
  },
  [85191561] = {
    id = 85191561,
    name = "差不多该去巡逻了，在大家都在尽情享受节日的时候，才更需要有人来守护这份安宁。"
  },
  [85011591] = {
    id = 85011591,
    name = "我正是上知天文，下知地理，学贯古今的天才少女蒙娜！你可以直接叫我天才蒙娜，也可以称呼我——诶，别走啊，我还没介绍完呢！"
  },
  [85021591] = {
    id = 85021591,
    name = "唔，探险队每天要处理的事也太多了，依我所见，把重要的事做好就可以了吧？诶，不行？好吧，那队长你也来帮帮我。"
  },
  [85031591] = {
    id = 85031591,
    name = "图书管理人的工作可并不是简单的将书籍分类归纳而已，污渍清理、漏缺修复、版本校对......有时候从大清早工作到深夜，也处理不了多少。"
  },
  [85031592] = {
    id = 85031592,
    name = "之前有人说我像什么“移动的图书馆”，真是太没品味了！至少也该叫我“全知的蒙娜”吧？你那是什么表情？我可不是自夸，要论阅读数量，没几个人能比得上我！"
  },
  [85041591] = {
    id = 85041591,
    name = "能经历这样的事，代表队长也认同我是个天才吧？！"
  },
  [85041592] = {
    id = 85041592,
    name = "如果馆长见到现在的我，一定会大吃一惊！当初只会看书的蒙娜，现在也成长为能独当一面的探险者了。"
  },
  [85041593] = {
    id = 85041593,
    name = "达到这种程度确实很厉害了，但我们的目标可不仅仅只是这样！所以现在不是结束，而是全新的开始！"
  },
  [85051591] = {
    id = 85051591,
    name = "中央大图书馆的生活并不枯燥，但我依然渴望到外面的世界来看看。毕竟书本中描绘得再好，也不及亲眼见识一番。"
  },
  [85051592] = {
    id = 85051592,
    name = "我突然想到几个有趣的游戏，一起来玩吧！放心，不是之前那些恶作剧。"
  },
  [85051593] = {
    id = 85051593,
    name = "中央大图书馆的藏书中，几乎记录了人们所有的探险发现。所以很多事我虽然还没见过、经历过，但我知道的并不比任何人少。"
  },
  [85051594] = {
    id = 85051594,
    name = "对我来说，中央大图书馆就是我的家，馆长和那里的工作人员都是我的家人。"
  },
  [85051595] = {
    id = 85051595,
    name = "我在书本中见过的世界，远比我们现在看到的更大、更广！今后一起去见识吧，我陪你一起！"
  },
  [85061591] = {
    id = 85061591,
    name = "轮到我大显身手了！"
  },
  [85071591] = {id = 85071591, name = "嘿！"},
  [85071592] = {id = 85071592, name = "咿呀！"},
  [85071593] = {id = 85071593, name = "哟诶！"},
  [85081591] = {
    id = 85081591,
    name = "尝尝这个！"
  },
  [85081592] = {id = 85081592, name = "看招！"},
  [85091591] = {
    id = 85091591,
    name = "这场游戏，该结束了！"
  },
  [85091592] = {
    id = 85091592,
    name = "交给全能的蒙娜吧！"
  },
  [85101591] = {id = 85101591, name = "呀啊！"},
  [85101592] = {id = 85101592, name = "好痛。"},
  [85101593] = {id = 85101593, name = "呜啊。"},
  [85111591] = {
    id = 85111591,
    name = "真是讨厌的家伙！"
  },
  [85121591] = {
    id = 85121591,
    name = "蒙娜......想回去了......"
  },
  [85131591] = {
    id = 85131591,
    name = "对于天才少女蒙娜而言，这种程度轻轻松松！"
  },
  [85141591] = {
    id = 85141591,
    name = "怎、怎么回事，敌人的表现和书上写的完全不同......"
  },
  [85151591] = {
    id = 85151591,
    name = "生日快乐！嘿嘿，来看看这份计划书，你今天的行程我已经全部安排好啦！就让天才蒙娜带你度过一个前所未有的生日吧！"
  },
  [85161591] = {
    id = 85161591,
    name = "新年好啊队长，我正在给馆长写信——啊，不是问候什么的，是计划书啦......每个新年我都要向馆长汇报这一年的计划，真是头疼，队长也帮我想想嘛。"
  },
  [85171591] = {
    id = 85171591,
    name = "节日快乐队长！猜猜我准备了什么礼物？——甜点？不不不，我才不会准备那么普通的礼物呢！锵锵，是书！这是我最喜欢的一本游记，送给你！"
  },
  [85181591] = {
    id = 85181591,
    name = "这种节日真是太棒了！不仅有盛大的庆典，还有吃不完的糖果，真希望每天都能这样——啊，不好，巡游快开始了，我们快走队长！"
  },
  [85191591] = {
    id = 85191591,
    name = "在中央大图书馆的时候，我们虽然也会庆祝节日，但馆长只允许我们在自己的房间中布置节日装饰，远没有圈落据点中这么热闹！"
  },
  [85011731] = {
    id = 85011731,
    name = "我是来自圣歌的抚慰师，非常感谢您的邀请。为了守护我们所坚信的正义，我会全力以赴！请多多指教。"
  },
  [85021731] = {
    id = 85021731,
    name = "食物能让我感到满足，每次出发前我都会通过食物调整自己的体能和精神，确保能以最佳状态应对接下来的挑战。"
  },
  [85031731] = {
    id = 85031731,
    name = "深渊中也有不少认可圣歌理念的人，如果能联合大家一起行动，说不定可以取得超乎意料的收获。不过大家都有各自的追求，即便认可我们的理念，也没有多少人愿意为此全力以赴吧......"
  },
  [85031732] = {
    id = 85031732,
    name = "最近总有人随意放置食物，还好我发现及时，在它们坏掉前全吃了——那是您的点心？......抱歉，我怕浪费才吃的......我、我会赔偿您的！"
  },
  [85041731] = {
    id = 85041731,
    name = "我无法解决深渊中的所有问题，但我绝不会放过自己遇到的任何问题。"
  },
  [85041732] = {
    id = 85041732,
    name = "守护所有的善良和美好，让每个人都能追寻自己的幸福，这、便是我战斗的意义！"
  },
  [85041733] = {
    id = 85041733,
    name = "或许我的表现还算不上优秀，但这份守护大家的信念，绝不会输给任何人。"
  },
  [85051731] = {
    id = 85051731,
    name = "没有经历过饥饿的人，不会明白食物有多么重要，没有体验过苦难的人，自然也不会珍惜善良和美好。"
  },
  [85051732] = {
    id = 85051732,
    name = "有时候我会想，如果我也能和慈悲者一样温柔随和，是不是就能有更好的表现......可是、如果真的变成那样，我还算是我吗？"
  },
  [85051733] = {
    id = 85051733,
    name = "比起饥饿和贫穷，孤独更让人更难以忍受。几天不吃饭最多只会让身体感到难受，但孤独不一样，那是一种、一种让你觉得快要疯掉的感觉。"
  },
  [85051734] = {
    id = 85051734,
    name = "颂道使总说我顾虑太多，我也知道。可是很多时候我就是无法确定自己的选择是否正确，她虽然看起来比我小，但却比我更加可靠。"
  },
  [85051735] = {
    id = 85051735,
    name = "和一些人相比，我的愿望似乎很简单，可是想要实现却并不容易，不过不管未来会遇到怎样的困难，我也绝不会放弃。"
  },
  [85061731] = {
    id = 85061731,
    name = "我已经做好了准备。"
  },
  [85071731] = {id = 85071731, name = "哈啊！"},
  [85071732] = {id = 85071732, name = "咿呀。"},
  [85071733] = {id = 85071733, name = "嘿咿。"},
  [85081731] = {
    id = 85081731,
    name = "绝不妥协。"
  },
  [85081732] = {
    id = 85081732,
    name = "我会保护大家。"
  },
  [85091731] = {
    id = 85091731,
    name = "我不会辜负自己的使命。"
  },
  [85091732] = {
    id = 85091732,
    name = "这、便是我的觉悟！"
  },
  [85101731] = {id = 85101731, name = "唔呃。"},
  [85101732] = {id = 85101732, name = "呜啊。"},
  [85101733] = {id = 85101733, name = "呃。"},
  [85111731] = {
    id = 85111731,
    name = "和饥饿比起来，这种事不值一提。"
  },
  [85121731] = {
    id = 85121731,
    name = "我还有......必须要做的事......"
  },
  [85131731] = {
    id = 85131731,
    name = "非常完美的胜利，总算没有辜负大家的期待。不过、又有点饿了......"
  },
  [85141731] = {
    id = 85141731,
    name = "都怪我还不够果断......"
  },
  [85151731] = {
    id = 85151731,
    name = "生日快乐！我和大家为您准备了食物和蛋糕，请尽情享用吧，绝对管够！——欸，我、我也一起吃？不行，这是你的生日......如果只是一点点......"
  },
  [85161731] = {
    id = 85161731,
    name = "今年的聚会地址稍微有点距离，我们也准备一下出发吧。去哪？当然是一起去参加圣歌的新年聚会啊，难道你还有别的事要处理？聚会上可是有很多难得一见的美味，错过了不一定还能吃到哦。"
  },
  [85171731] = {
    id = 85171731,
    name = "比起其他东西，果然还是最珍贵的食物才能表达最高的谢意吧？这是我一直没舍得吃的甜品，据说是这一带最美味的存在，送给你！——不，请不用客气，我真的没关系！"
  },
  [85181731] = {
    id = 85181731,
    name = "小时候我很喜欢这种节日，因为只要跟随人群一起四处巡游，就能得到不少糖果，对那个时候的我而言糖果可是无上美味！当然，现在我也很喜欢这个节日，因为庆典上总能发现一些特别的美味！"
  },
  [85191731] = {
    id = 85191731,
    name = "对圣歌而言，今天是一个非常重要的日子，我们会将收到的所有捐赠派发给最需要它们的人，所以今天会非常忙碌——你也来帮忙？欸，真的可以吗？"
  },
  [85011961] = {
    id = 85011961,
    name = "我也可以加入探险队吗？不，不对，既然已经决定好了，不管什么事我都会努力，请多多关照，队长。"
  },
  [85021961] = {
    id = 85021961,
    name = "队长，热茶和点心都已经准备好了，如果还有其他任何需要都可以随时吩咐。"
  },
  [85031961] = {
    id = 85031961,
    name = "一会儿没看到小姐就会觉得不安，唔，我果然不适合做探险者吧......不行不行，这种时候必须打起精神，做好自己的事，让小姐和队长都能安心。"
  },
  [85031962] = {
    id = 85031962,
    name = "虽然我来到深渊已有不少时日，但一直都和小姐在一起，以探险者的身份行动还是第一次，有一种既紧张又有一些期待的感觉。"
  },
  [85041961] = {
    id = 85041961,
    name = "把这如此珍贵的力量给我，真的没关系吗？"
  },
  [85041962] = {
    id = 85041962,
    name = "呼~压力好大，能被队长如此信任，我、我一定会努力回报的。"
  },
  [85041963] = {
    id = 85041963,
    name = "我从没想过自己也能拥有这样的力量，感觉现在的我有了更多可以做到的事了。"
  },
  [85051961] = {
    id = 85051961,
    name = "和优秀的大家相比，我就像一个什么也不懂的新人探险者，不，或许连新人探险者也比不上，但就是这样的我，却得到了小姐和队长的信任。"
  },
  [85051962] = {
    id = 85051962,
    name = "是小姐拯救了我的生命，也是她让我有机会体验到了完全不同的人生，这份恩情，无论怎样做也无法回报。"
  },
  [85051963] = {
    id = 85051963,
    name = "小姐有时候看起来很严厉，但其实是个非常温柔的人，不管何时都会优先为身边的人考虑，而且从来不会因为对方的身份有所区别。"
  },
  [85051964] = {
    id = 85051964,
    name = "能被小姐信任，选作贴身侍从是我的荣幸，但我有时候也会担心自己做得不够好，担心自己会辜负小姐的期望。"
  },
  [85051965] = {
    id = 85051965,
    name = "这段时间的经历，让什么也做不好的我也有了想要做到的事。我想变得更强，变得更加可靠，为小姐和队长分担更多的工作和烦恼。"
  },
  [85061961] = {
    id = 85061961,
    name = "我、我准备好了。"
  },
  [85071961] = {id = 85071961, name = "咿呀。"},
  [85071962] = {id = 85071962, name = "嘿咿。"},
  [85071963] = {id = 85071963, name = "哈。"},
  [85081961] = {
    id = 85081961,
    name = "交给我吧。"
  },
  [85081962] = {
    id = 85081962,
    name = "发现弱点了。"
  },
  [85091961] = {
    id = 85091961,
    name = "我也可以做到！"
  },
  [85091962] = {
    id = 85091962,
    name = "不会让你们逃掉！"
  },
  [85101961] = {id = 85101961, name = "哇！"},
  [85101962] = {id = 85101962, name = "呃啊。"},
  [85101963] = {id = 85101963, name = "呜哇。"},
  [85111961] = {
    id = 85111961,
    name = "不、不用担心我。"
  },
  [85121961] = {
    id = 85121961,
    name = "小姐......还在等我......"
  },
  [85131961] = {
    id = 85131961,
    name = "太好了，这一次终于没有拖大家的后腿。"
  },
  [85141961] = {
    id = 85141961,
    name = "是我做得还不够好，掩护大家撤退的任务就交给我吧，队长。"
  },
  [85151961] = {
    id = 85151961,
    name = "队长生日快乐，生日宴会就快准备好了，请稍等一下就好——怎么知道的？呵呵，当然是小姐吩咐的，这会儿小姐应该正在四处找您。"
  },
  [85161961] = {
    id = 85161961,
    name = "今年的新年庆典真热闹啊，小姐其实很喜欢这种庆典，只是出于某些方面的考虑，很少有机会安心享受，我去邀请小姐，今天大家一起去逛逛吧。"
  },
  [85171961] = {
    id = 85171961,
    name = "队长节日快乐，我准备了一个收纳箱，请看看怎么样？很不错？呵呵，谢谢队长，这样的话不管队长收到多少礼物，也不用担心存放的问题了。"
  },
  [85181961] = {
    id = 85181961,
    name = "在家的时候，每到这种节日小姐都会带着我一起去庆典上“巡查”，说是要防范不良探险者，不知道今年会不会继续“巡查”。"
  },
  [85191961] = {
    id = 85191961,
    name = "啊，队长已经来了吗？请稍等一下......这堆礼物是小姐为大家准备的，我等会儿就给大家送去——队长的礼物吗？呵呵，已经给您放好啦。"
  },
  [85011971] = {
    id = 85011971,
    name = "我一直期待着，期待着有一天能与学长并肩作战......我一定会全力以赴的学长！不，队长！"
  },
  [85021971] = {
    id = 85021971,
    name = "队长，这是今天的行动计划，您帮我看看还有哪些地方需要再优化一下吧。"
  },
  [85031971] = {
    id = 85031971,
    name = "裁决团虽然距离当初ACE还有不少差距，但成员们也都是身经百战的资深探险者，所以就算我暂时不在也不会有任何影响。"
  },
  [85031972] = {
    id = 85031972,
    name = "能如此近距离地呆在学长身边，接受学长的指点，这是我曾经梦寐以求的事。现在这一切如果是梦，我只想这个梦能晚一点醒来。"
  },
  [85041971] = {
    id = 85041971,
    name = "我一直追逐着学长的背影在前行，这次机会我一定会好好珍惜。"
  },
  [85041972] = {
    id = 85041972,
    name = "学长对我的指点，奥萨丁铭记于心！我会用这份力量为学长开辟前行之路！"
  },
  [85041973] = {
    id = 85041973,
    name = "无论有怎样的敌人，无论怎样危险的境遇，只要学长需要，奥萨丁都在所不辞！"
  },
  [85051971] = {
    id = 85051971,
    name = "裁决团能有现在的成绩，我并没有什么功劳，我只是用学长曾教我的方式协调同伴，相信同伴，仅此而已。"
  },
  [85051972] = {
    id = 85051972,
    name = "我现在确实有些实力，但也仅仅只是一些而已。我见过太多优秀的人，所以我很清楚自己和他们之间的差距，知道自己必须努力做得更好才行。"
  },
  [85051973] = {
    id = 85051973,
    name = "如果没有遇到学长，我恐怕仍然还是一个盛气凌人、目空一切的家伙，绝不会是现在这样受到他人信任的探险者。"
  },
  [85051974] = {
    id = 85051974,
    name = "这些年我带着裁决团的同伴们经历了许多事情，才终于又了解了学长一些，也才更加清晰的认识到，当年的他是多么优秀的存在。"
  },
  [85051975] = {
    id = 85051975,
    name = "那次事件后，我始终坚信学长总有一天会重返深渊，在我心里，他一直都是那个不会被任何困难击垮，永远值得我无条件信任的学长。"
  },
  [85061971] = {
    id = 85061971,
    name = "绝不辜负学长的期待。"
  },
  [85071971] = {id = 85071971, name = "喝！"},
  [85071972] = {id = 85071972, name = "哈！"},
  [85071973] = {id = 85071973, name = "呀啊！"},
  [85081971] = {
    id = 85081971,
    name = "给我退下！"
  },
  [85081972] = {
    id = 85081972,
    name = "破绽百出。"
  },
  [85091971] = {
    id = 85091971,
    name = "不怕死的家伙，尽管来吧！"
  },
  [85091972] = {
    id = 85091972,
    name = "由我来终结这一切。"
  },
  [85101971] = {id = 85101971, name = "唔。"},
  [85101972] = {id = 85101972, name = "呃。"},
  [85101973] = {id = 85101973, name = "呜呃。"},
  [85111971] = {
    id = 85111971,
    name = "嘁，不过如此。"
  },
  [85121971] = {
    id = 85121971,
    name = "至少，要让学长撤退......"
  },
  [85131971] = {
    id = 85131971,
    name = "呼~学长，我的表现还算合格吧？如果有任何需要调整的地方，请及时告诉我。"
  },
  [85141971] = {
    id = 85141971,
    name = "学长，你带着大家先走，这里交给我！"
  },
  [85151971] = {
    id = 85151971,
    name = "学长，生日快乐！我按照以前列蒂西雅小姐她们为你庆生的方式准备了一下，这会儿大家估计都到了，我们也过去吧！"
  },
  [85161971] = {
    id = 85161971,
    name = "新年快乐学长！今天难得空闲，能陪我练习一下吗？呵呵，都是你曾教我的一些技巧，我想让学长看看我现在还有哪些地方可以继续精进。"
  },
  [85171971] = {
    id = 85171971,
    name = "欸，学长你手里的礼物是——今天收到的？这么多？！不愧是学长啊，不管是在学院还是在深渊，都能如此受欢迎！"
  },
  [85181971] = {
    id = 85181971,
    name = "学长，这是圈落里送来的邀请函，邀请我们去参加节日庆典。理由？呵呵，估计是因为我去帮忙筹办了庆典，而且是以我们探险队的名义，嘿嘿。"
  },
  [85191971] = {
    id = 85191971,
    name = "前几年虽然有托人为学长送上节日礼物，但总觉得少了很多诚意，今年终于有机会亲手交给学长了，还请学长能够收下这份心意！"
  },
  [85011981] = {
    id = 85011981,
    name = "既然你展现出了足够的诚意，加入探险队也不是不行。当然，就算正式加入了，你也不能勉强本小姐。"
  },
  [85021981] = {
    id = 85021981,
    name = "虽然本小姐并不介意协助你处理探险队的事务，但也不能全交给我吧？最信任的人......就、就算你这么说，我也不会什么都帮你做的。"
  },
  [85031981] = {
    id = 85031981,
    name = "都说深渊中存在无数奇迹，可是这么久了，一点有用的线索也没有......不过也对，如果那么容易被找到，也就算不上奇迹了。"
  },
  [85031982] = {
    id = 85031982,
    name = "在学院的时候总听你们聊起深渊，现在看来也并没有你们说的那么精彩嘛。不过倒也不算差，呆在这里至少比成天参加各种交际活动轻松多了。"
  },
  [85041981] = {
    id = 85041981,
    name = "作为探险者也要面对这些麻烦的流程吗？只是惯例？我、我当然知道。"
  },
  [85041982] = {
    id = 85041982,
    name = "既然决定要以探险者的名义行动，本小姐自然也会全力以赴，成为最优秀的探险者。"
  },
  [85041983] = {
    id = 85041983,
    name = "本小姐现在的表现足够优秀了吧？呵呵，如果再与谢利交手，本小姐绝不会输！"
  },
  [85051981] = {
    id = 85051981,
    name = "本小姐留在深渊自然有本小姐的理由，你该不会认为本小姐和那些普通探险者一样，是为了财富、名望之类的庸俗目的吧？"
  },
  [85051982] = {
    id = 85051982,
    name = "学院中的那段时光着实令人怀念，一到毕业，似乎每个人都突然忙碌了起来......我并不是在缅怀过去，只是突然想到罢了。"
  },
  [85051983] = {
    id = 85051983,
    name = "本小姐的事自然有莉娃帮忙处理，但如果你真的很想帮忙，有需要的话，本小姐也可以告诉你。"
  },
  [85051984] = {
    id = 85051984,
    name = "多亏了父亲大人的研究成果，让我在深渊行动轻松了不少。当然，以本小姐的实力，即便没有那些研究成果也不会有什么问题。"
  },
  [85051985] = {
    id = 85051985,
    name = "我大概明白为什么你们当初都想成为探险者了......能与信任的人一起探险，一起面对各种危机和挑战，这种生活确实让人心潮澎湃。"
  },
  [85061981] = {
    id = 85061981,
    name = "期待本小姐的表现吧！"
  },
  [85071981] = {id = 85071981, name = "嘿！"},
  [85071982] = {id = 85071982, name = "哈咿！"},
  [85071983] = {id = 85071983, name = "喝！"},
  [85081981] = {
    id = 85081981,
    name = "别想逃！"
  },
  [85081982] = {
    id = 85081982,
    name = "饶不了你！"
  },
  [85091981] = {
    id = 85091981,
    name = "无能之辈，受死吧！"
  },
  [85091982] = {
    id = 85091982,
    name = "想逃？已经晚了！"
  },
  [85101981] = {id = 85101981, name = "呜啊。"},
  [85101982] = {id = 85101982, name = "咿呀。"},
  [85101983] = {id = 85101983, name = "唔呃。"},
  [85111981] = {
    id = 85111981,
    name = "不可原谅！"
  },
  [85121981] = {
    id = 85121981,
    name = "本小姐......还没输......"
  },
  [85131981] = {
    id = 85131981,
    name = "有本小姐在，这种程度的敌人根本不值一提。"
  },
  [85141981] = {
    id = 85141981,
    name = "怎么会......不，不可能，再来！本小姐才不会输给这种家伙！"
  },
  [85151981] = {
    id = 85151981,
    name = "探险队事务我已经全部处理好了，今天的时间你都可以自行安排——休息？不，不行，生日必须要好好庆祝，而且我都已经让莉娃去准备了......"
  },
  [85161981] = {
    id = 85161981,
    name = "听说附近圈落正在举办新年庆典——一起去？嗯，虽然没什么兴趣，但今天也没有别的安排......走吧，就当打发时间。"
  },
  [85171981] = {
    id = 85171981,
    name = "给，这是今年的礼物。没什么特别的意思，只是和往年一样，一些小点心而已。"
  },
  [85181981] = {
    id = 85181981,
    name = "今天任务结束后一起去庆典看看吧，呃，我只是想提前了解一下庆典习俗，以后有机会带小莉体验而已，这种热闹的节日，她应该也会喜欢。"
  },
  [85191981] = {
    id = 85191981,
    name = "今天有什么计划吗？还是说由我来安排？这样重要的节日由本小姐擅自决定似乎也不妥，总之先一起走走吧，然后一起商量一下。"
  },
  [85011601] = {
    id = 85011601,
    name = "您好，我是探险者米亚姆，非常高兴能加入——啊，不用这么正式也可以？我、我知道了哥哥。"
  },
  [85021601] = {
    id = 85021601,
    name = "哥哥，我们今天要去哪里探险呢？——不，并不是有什么想法，只是想确认一下计划，提前做些准备。"
  },
  [85031601] = {
    id = 85031601,
    name = "灵遥和赛珂她们去哪儿了呢，难道又去修行或者执行特别任务了吗？......我也必须抓紧时间修行才可以，否则下一次比试，说不定会落后大家很多。"
  },
  [85031602] = {
    id = 85031602,
    name = "此前独自行动的时候，时常会受到一些前辈的质疑，虽然那种感觉并不算好，但我相信很多人都是出于好意。当然，遇到真正傲慢的人，我也会用实力证明自己！"
  },
  [85041601] = {
    id = 85041601,
    name = "谢谢哥哥对我的关照，我会用更出色的表现回应你的期待。"
  },
  [85041602] = {
    id = 85041602,
    name = "对我而言，再强大的力量也比不上哥哥对我的信任，我会好好使用这份力量，努力帮到哥哥！"
  },
  [85041603] = {
    id = 85041603,
    name = "米亚姆绝不会忘记哥哥为我付出的一切，无论哥哥的任何指示，我都一定会全力做到最好！"
  },
  [85051601] = {
    id = 85051601,
    name = "加入探险队以后，事情确实比以前多了很多，但我并不觉得累，反而有一种很充实的感觉。"
  },
  [85051602] = {
    id = 85051602,
    name = "和优秀的前辈们相比我还有很多地方做得不够好，所以得好好利用闲暇时间，努力看书修行，争取早日赶上大家。"
  },
  [85051603] = {
    id = 85051603,
    name = "有时候我明明很想加入大家的话题，和大家一起行动，但总觉得难以开口......是哥哥给了我勇气，让我能勇敢说出自己的想法。"
  },
  [85051604] = {
    id = 85051604,
    name = "或许我某些方面的能力还算不错，但探险经验和大家比起来还差得很远，要成为独当一面的探险者，还有很多地方需要学习。"
  },
  [85051605] = {
    id = 85051605,
    name = "总感觉呆在哥哥身边，不管做什么事都很顺利，和大家相处也不再像以前那样紧张......谢谢你哥哥，谢谢你让我距离自己的目标又近了一步。"
  },
  [85061601] = {
    id = 85061601,
    name = "我会努力的，哥哥。"
  },
  [85071601] = {id = 85071601, name = "嘿！"},
  [85071602] = {id = 85071602, name = "咿呀！"},
  [85071603] = {id = 85071603, name = "喝！"},
  [85081601] = {
    id = 85081601,
    name = "视野不错。"
  },
  [85081602] = {
    id = 85081602,
    name = "锁定你了。"
  },
  [85091601] = {
    id = 85091601,
    name = "绝不会放过任何敌人！"
  },
  [85091602] = {
    id = 85091602,
    name = "绝不允许妨碍哥哥！"
  },
  [85101601] = {id = 85101601, name = "哇！"},
  [85101602] = {id = 85101602, name = "呀！"},
  [85101603] = {id = 85101603, name = "呜啊。"},
  [85111601] = {
    id = 85111601,
    name = "我才不会认输。"
  },
  [85121601] = {
    id = 85121601,
    name = "哥哥......对不起......"
  },
  [85131601] = {
    id = 85131601,
    name = "呼~终于结束了。我没有拖大家的后腿吧，哥哥。"
  },
  [85141601] = {
    id = 85141601,
    name = "对不起哥哥......如果我能再成熟一点，或许就能避免这种事......"
  },
  [85151601] = {
    id = 85151601,
    name = "生日快乐哥哥！——啊？忘了？呵呵，没关系！今后我会记得提醒哥哥，当然，生日料理和庆祝会我也会全部负责。"
  },
  [85161601] = {
    id = 85161601,
    name = "今年和哥哥一起探险，感觉收获好多好多，我的日记都快写不下了。下一年的打算？嗯......我还没想过，不过和哥哥在一起，一定会很充实！"
  },
  [85171601] = {
    id = 85171601,
    name = "哥哥，来看看这枚胸针怎么样？——和我戴的一样？呵呵，这是我特意找工匠定做的，送给你。"
  },
  [85181601] = {
    id = 85181601,
    name = "唔......今年的庆典看起来也好热闹，果然还是想去看看......哥哥可以陪我一起去吗？可以？真的吗？！谢谢哥哥！"
  },
  [85191601] = {
    id = 85191601,
    name = "哥哥今天有什么安排吗？不管做什么事我都会陪你一起哦。能和哥哥一起度过这种重要的节日，我已经非常满足了。"
  },
  [85011671] = {
    id = 85011671,
    name = "喂，就是你给我发的邀请？看起来不像是能打的样子，镇得住场子吗？难道说，找我就是为了帮你镇场子，呵呵哈哈哈~"
  },
  [85021671] = {
    id = 85021671,
    name = "哈——，好无聊，每次闲下来就犯困。真怀念在贫民街的日子，每天一睁开眼就是打架和调教手下。"
  },
  [85031671] = {
    id = 85031671,
    name = "师父说地面已经不适合我，要带我来深渊找属于我的机遇，我才跟他一起来了这里，结果这家伙一到这里竟然就直接消失了，可恶！他最好祈祷别再遇到我，否则我绝对会让他好看！"
  },
  [85031672] = {
    id = 85031672,
    name = "在我们那，周围人都将我称作“女王”，那些家伙都怕我怕得要紧，一点儿意思也没有。不过这里能打的家伙似乎有不少，呵呵哈哈哈，如果能打出个“深渊女王”的名号，似乎会很有意思。"
  },
  [85041671] = {
    id = 85041671,
    name = "我在贫民街时拳头便是道理和正义，这深渊中似乎也没什么区别。"
  },
  [85041672] = {
    id = 85041672,
    name = "把能打的家伙全部叫出来，我会让他们知道，谁才是这里真正的老大！"
  },
  [85041673] = {
    id = 85041673,
    name = "既然在这深渊中力量代表一切，那么我必将拥有这深渊中的一切，哈哈哈~"
  },
  [85051671] = {
    id = 85051671,
    name = "探险者的生活和我在贫民街时没什么区别，无非是对手从流氓混混变成了魔物而已。"
  },
  [85051672] = {
    id = 85051672,
    name = "师父常说我战斗不带脑子，可我觉得如果力量足够强大，不带脑子也没问题！"
  },
  [85051673] = {
    id = 85051673,
    name = "我虽然总说我师父不是个好人，但那只是说说而已。如果没有他，我早已不在这个世界。"
  },
  [85051674] = {
    id = 85051674,
    name = "最初我渴求力量只是想活下来而已，但当我发现强大的力量可以让那些混蛋变得乖巧之后，我才体会了到力量带来的快感。"
  },
  [85051675] = {
    id = 85051675,
    name = "或许我师父那家伙说的不错，就算是只知道战斗的我，依然可以在这个世界找到属于我的机遇。"
  },
  [85061671] = {
    id = 85061671,
    name = "要去打架了吗？我已经等不急了！"
  },
  [85071671] = {id = 85071671, name = "哈！"},
  [85071672] = {id = 85071672, name = "嘿！"},
  [85071673] = {id = 85071673, name = "呀啊！"},
  [85081671] = {
    id = 85081671,
    name = "别挣扎了~"
  },
  [85081672] = {
    id = 85081672,
    name = "乖乖受死！"
  },
  [85091671] = {
    id = 85091671,
    name = "不长眼的家伙们，你们完了！"
  },
  [85091672] = {
    id = 85091672,
    name = "哈哈哈~准备说再见吧！"
  },
  [85101671] = {id = 85101671, name = "呃啊。"},
  [85101672] = {id = 85101672, name = "唔呃。"},
  [85101673] = {id = 85101673, name = "唔。"},
  [85111671] = {
    id = 85111671,
    name = "嘁，再来再来！"
  },
  [85121671] = {
    id = 85121671,
    name = "我怎么......可能......"
  },
  [85131671] = {
    id = 85131671,
    name = "呵呵哈哈哈，过瘾过瘾！还有吗，下一场在哪，我们马上去！"
  },
  [85141671] = {
    id = 85141671,
    name = "嘁，竟然这么多手段，下次他们不会再有这么好的运气！"
  },
  [85151671] = {
    id = 85151671,
    name = "生日？庆祝生日的话得准备蛋糕吧？走，一起去圈落里看看，我会亲自给你搞个最大的，记得好好感谢我。"
  },
  [85161671] = {
    id = 85161671,
    name = "我还在贫民街的时候，新年就是我给那些贫民街的混蛋们划分地盘分配物资的日子。现在我来了深渊，指不定他们又在为了些蝇头小利打得不可开交。"
  },
  [85171671] = {
    id = 85171671,
    name = "在贫民街可没有人会过这种节日，每个人都在为了生存忙碌，就算是我也要忙着驱赶地盘上那些不遵守规则的混蛋。"
  },
  [85181671] = {
    id = 85181671,
    name = "这种节日，在我成为“女王”之后，才开始在贫民街中流行起来。以前人们随时都要提防那些不守规矩，抢夺、盗窃的混蛋，直到我定下规矩之后，一切才安稳下来。"
  },
  [85191671] = {
    id = 85191671,
    name = "小时候，我和老爸一起流浪，那时候虽然非常辛苦，但每到节日里，他都会给我准备一些特别的礼物。那些礼物都是他自己做的、修补的，虽然粗糙，可是却给了我一种“我和别人家孩子没什么不同”的感觉。"
  },
  [85011641] = {
    id = 85011641,
    name = "抱歉，我迟到了吗？我在过来的路上发现一些很有趣的植物，所以稍微耽误了点时间。您就是队长吧？旅人菲莉亚向您致意~"
  },
  [85021641] = {
    id = 85021641,
    name = "队长你终于来了，制定行动计划这种事，对我来说还是太难了......我所有的旅行都是随心所欲，完全没准备过计划。"
  },
  [85031641] = {
    id = 85031641,
    name = "我很喜欢四处游历，对我来说，探险最大的乐趣就是寻找未曾见识过的事物，享受意料之外的发展，至于结果如何，我并不太在意。"
  },
  [85031642] = {
    id = 85031642,
    name = "有时候我会因为发现一些新奇的事物耽误其他事情，但那绝非我的本意，而且我也在很努力的克制了——不用强行克制？谢谢......不过请放心，如果有重要的事我是绝不会耽误的！"
  },
  [85041641] = {
    id = 85041641,
    name = "这样的力量，必然能带我前往更广阔的地方。"
  },
  [85041642] = {
    id = 85041642,
    name = "竟然对我这样一个特立独行的探险者如此关照，队长也是个不可思议的人呢。"
  },
  [85041643] = {
    id = 85041643,
    name = "虽说是为了让我能更好的执行任务，但能为我做到这种程度的人，队长还是第一个。"
  },
  [85051641] = {
    id = 85051641,
    name = "我踏上旅途的理由其实很简单，就是突然有一天厌倦了固定的生活，厌倦了名利争夺，想到一个全新的地方看看而已。"
  },
  [85051642] = {
    id = 85051642,
    name = "作为探险者我并不算出色，甚至连是否合格都很难说，但如果作为旅人，我想应该算得上很优秀吧？"
  },
  [85051643] = {
    id = 85051643,
    name = "每个人都有自己的生活方式，都有各自追寻的目标，所以即便不理解，我也不会干涉别人，当然，也不会主动寻求其他人认同我的理念。"
  },
  [85051644] = {
    id = 85051644,
    name = "我很喜欢仰望天空，不管白天还是黑夜。每次看向天际的时候我都会想，会不会有人也在同一时刻仰望天空。"
  },
  [85051645] = {
    id = 85051645,
    name = "原本我只是想体验一下加入探险队的感觉，然后继续自己一个人的旅程......现在看来，未来的旅程不会再是我一个人了。"
  },
  [85061641] = {
    id = 85061641,
    name = "又要行动了吗？"
  },
  [85071641] = {id = 85071641, name = "嘿咿~"},
  [85071642] = {id = 85071642, name = "呀啊。"},
  [85071643] = {id = 85071643, name = "喝呀。"},
  [85081641] = {
    id = 85081641,
    name = "认真一下吧。"
  },
  [85081642] = {
    id = 85081642,
    name = "尽快结束吧。"
  },
  [85091641] = {
    id = 85091641,
    name = "小看我可是会付出代价。"
  },
  [85091642] = {
    id = 85091642,
    name = "别指望我会手下留情。"
  },
  [85101641] = {id = 85101641, name = "唔。"},
  [85101642] = {id = 85101642, name = "呃。"},
  [85101643] = {id = 85101643, name = "呃啊。"},
  [85111641] = {
    id = 85111641,
    name = "这也太难缠了吧。"
  },
  [85121641] = {
    id = 85121641,
    name = "这就是......我的宿命吗......"
  },
  [85131641] = {
    id = 85131641,
    name = "拦路的敌人已经解决完毕，好了，继续我们的旅程吧，队长。"
  },
  [85141641] = {
    id = 85141641,
    name = "跟我走吧，我知道撤离的安全通道。"
  },
  [85151641] = {
    id = 85151641,
    name = "生日吗......我是不是应该准备点礼物？抱歉，我确实没有注意到！所以作为补偿，一起去圈落看看吧，不管想要什么我都会满足你。"
  },
  [85161641] = {
    id = 85161641,
    name = "新年好队长，来看看我做的这个计划怎么样？——太简单了？我觉得这种程度已经够了吧，再详细一点就没什么可期待的内容了。"
  },
  [85171641] = {
    id = 85171641,
    name = "我以前到过一个古老的村落，那里的人会佩戴相同的编织手环来证明彼此的关系，我也凭着记忆编了两个，这个送给你。"
  },
  [85181641] = {
    id = 85181641,
    name = "这种节日许多地方的庆祝方式都大同小异，但也有少数地区有着自己独特的习俗——觉得很有趣？呵呵，那我把我知道的全都告诉你吧。"
  },
  [85191641] = {
    id = 85191641,
    name = "竟然又到这个节日了......不，并不是在回忆什么，只是突然想起有段时间没参加庆典了，今天一起去圈落看看吗？当然，我会为你准备礼物的。"
  },
  [85011891] = {
    id = 85011891,
    name = "我是探险者埃斯特拉——大小姐？不！不管你听到过什么传言，如你所见，本小姐只是一名普通的探险者而已！"
  },
  [85021891] = {
    id = 85021891,
    name = "嗯~这几处目的地真难抉择，这里风景最好、那一处又有很值得挑战的魔物......不如......就从这里开始全部走一趟！?"
  },
  [85031891] = {
    id = 85031891,
    name = "超越那些传奇探险者必须拥有更伟大的功绩以及更完美的表现，所以成立暗夜侍者也是我计划的一部分。总而言之，比起过去那些传奇人物，他们有的我要有，他们没有的、我也要有！"
  },
  [85031892] = {
    id = 85031892,
    name = "父亲曾邀请了许多探险者给我分享他们的见闻，我虽然从中获得了不少信息，但对深渊依然没有一个全面的认识。在这个浩瀚神秘的深渊中，或许每个人都能拥有只属于自己的经历。"
  },
  [85041891] = {
    id = 85041891,
    name = "很不错的体验，还能再来一次吗？我想试试自己的极限。"
  },
  [85041892] = {
    id = 85041892,
    name = "距离本小姐的目标又近了一步！不过要真正实现它，还需要更多的力量！"
  },
  [85041893] = {
    id = 85041893,
    name = "在故乡的大街小巷，我都已经留下了自己的传说。在这深渊中，本小姐也要创造无人能及的传奇！"
  },
  [85051891] = {
    id = 85051891,
    name = "小时候家里为我安排了不少学伴，唯有朗姆经受住了我的磨练。他现在的表现虽然还不够完美，但也算得上可靠。"
  },
  [85051892] = {
    id = 85051892,
    name = "在家时龙舌兰一直跟在二哥身边，但他完全没有学会二哥的文雅随和，总是一副冷冰冰的样子，偶尔还会和本小姐顶嘴，非常可恶！"
  },
  [85051893] = {
    id = 85051893,
    name = "威士忌是大哥的得力助手，实力确实不错，不过他总给我一种很虚假的感觉......哼，不管他多会伪装，总有一天本小姐会揭开他的假面。"
  },
  [85051894] = {
    id = 85051894,
    name = "没人能决定自己的出身，所以谈论过去身份什么的毫无意义，现在我们都在深渊，都是探险者，要谈论的、应该是未来。"
  },
  [85051895] = {
    id = 85051895,
    name = "暗夜侍者的各位成员在某些方面都拥有非常出色的表现，在本小姐的指导下，必然可以成为深渊中的传奇组织。"
  },
  [85061891] = {
    id = 85061891,
    name = "都准备好了吗？出发。"
  },
  [85071891] = {id = 85071891, name = "呀！"},
  [85071892] = {id = 85071892, name = "嘿！"},
  [85071893] = {id = 85071893, name = "喝！"},
  [85081891] = {
    id = 85081891,
    name = "哼，躲不掉！"
  },
  [85081892] = {
    id = 85081892,
    name = "接招吧。"
  },
  [85091891] = {
    id = 85091891,
    name = "就算后悔、也来不及了！"
  },
  [85091892] = {
    id = 85091892,
    name = "在本小姐的剑下忏悔吧！"
  },
  [85101891] = {id = 85101891, name = "呃啊。"},
  [85101892] = {id = 85101892, name = "唔。"},
  [85101893] = {id = 85101893, name = "呀啊。"},
  [85111891] = {
    id = 85111891,
    name = "竟敢伤本小姐，不可原谅！"
  },
  [85121891] = {
    id = 85121891,
    name = "我还有......没做完的事......"
  },
  [85131891] = {
    id = 85131891,
    name = "哼，轻轻松松🎵~大家抓紧时间休息一下，然后去下个地方。"
  },
  [85141891] = {
    id = 85141891,
    name = "放开我！本小姐绝不会轻易放过它们！"
  },
  [85151891] = {
    id = 85151891,
    name = "来看看这份庆祝会的安排，致辞、献礼......虽说还是有些简陋，但流程基本都齐全，你觉得怎样？如果没问题的话，我就通知下去，今天你的生日庆祝会就这样安排。"
  },
  [85161891] = {
    id = 85161891,
    name = "在家里的时候，每次举办新年庆典都要忙着招待来宾，根本没时间享受，现在终于可以不用去管那些礼仪和宾客了，一定要玩个痛快！"
  },
  [85171891] = {
    id = 85171891,
    name = "据说甜点是表达谢意的最佳方式，所以我准备了这些，要试一下吗？——有点苦？算了，本小姐也不想承认这种东西是我自己做出来的。"
  },
  [85181891] = {
    id = 85181891,
    name = "在家时我完全无法自在的享受这种节日，就算偶尔偷偷溜出来，很快也会被抓回去。不过现在好了，没有人来追捕我，也完全不用在意别人的看法，今天一定要好好享受一下！"
  },
  [85191891] = {
    id = 85191891,
    name = "来得正好，帮我把这些礼物搬一下，对了，还有这份名单，确认一下有没有遗漏。做什么？当然是分发礼物啊，这种节日不是应该为每个人都准备礼物吗？我家一直都是这样。"
  },
  [85011911] = {
    id = 85011911,
    name = "暗夜侍者、威士忌，非常感谢您的邀请，很荣幸能为您效劳~"
  },
  [85021911] = {
    id = 85021911,
    name = "请问来点红茶还是咖啡呢？或者说、试试我最近研发的“蒂安饮品”？它的原料全部取自于深渊，风味非常独特，您肯定没尝过🎵~"
  },
  [85031911] = {
    id = 85031911,
    name = "暗夜侍者是埃斯特拉小姐计划中的一环，小姐希望它能成为众多探险组织中的传奇，呵呵，我也差不多该再努力一点，做些能提升影响力的事，让那一天早点到来。"
  },
  [85031912] = {
    id = 85031912,
    name = "以前在大少爷身边时我曾听过一些关于深渊的传闻，可是来到这里之后才真正明白了它的凶险......不过我也比自己的想象中更加适合这个世界，呵呵~"
  },
  [85041911] = {
    id = 85041911,
    name = "真是值得铭记的一刻~非常感谢您的信任，您的意志便是我前行的方向。"
  },
  [85041912] = {
    id = 85041912,
    name = "比实力变化更让我在意的是，现在的我是否更像一名合格的探险者。"
  },
  [85041913] = {
    id = 85041913,
    name = "能达到这种程度我非常满意，不过想要让暗夜侍者成为传奇，还必须要做得更好才行。"
  },
  [85051911] = {
    id = 85051911,
    name = "家父是罗斯伯尔家族的护卫，一直希望我能继承他的衣钵，所以我从小便以此为目标，进行了许多修行。"
  },
  [85051912] = {
    id = 85051912,
    name = "虽然地点变了，面对的麻烦也和以前不同，但对于合格的执事而言，要做的事并不会有太大差别。"
  },
  [85051913] = {
    id = 85051913,
    name = "我还在大少爷身边时，便和埃斯特拉小姐打过许多交道，她给仆人和长辈的印象差别很大，当然，都不是什么坏的印象，呵呵~"
  },
  [85051914] = {
    id = 85051914,
    name = "深渊中特别的环境和食材让我的“蒂安料理”有了重大突破，无论味道还是外形都有了不少变化，距离做出全世界独一无二的料理又近了一步！"
  },
  [85051915] = {
    id = 85051915,
    name = "埃斯特拉小姐并不喜欢被人干涉，所以很多时候我会选择暗中行动，确保她的安全。辛苦？呵呵~从暗处观察这个世界也别有一番趣味。"
  },
  [85061911] = {
    id = 85061911,
    name = "我会好好招待客人~"
  },
  [85071911] = {id = 85071911, name = "喝。"},
  [85071912] = {id = 85071912, name = "咿呀。"},
  [85071913] = {id = 85071913, name = "嘿。"},
  [85081911] = {
    id = 85081911,
    name = "请就位吧~"
  },
  [85081912] = {
    id = 85081912,
    name = "别乱动。"
  },
  [85091911] = {
    id = 85091911,
    name = "这是您定制的特别服务。"
  },
  [85091912] = {
    id = 85091912,
    name = "还有什么需要交待的吗？"
  },
  [85101911] = {id = 85101911, name = "呃。"},
  [85101912] = {id = 85101912, name = "唔。"},
  [85101913] = {id = 85101913, name = "呜啊。"},
  [85111911] = {
    id = 85111911,
    name = "真是热情啊，我也该好好回应了~"
  },
  [85121911] = {
    id = 85121911,
    name = "蒂安料理......无法完成了......"
  },
  [85131911] = {
    id = 85131911,
    name = "招待不周~"
  },
  [85141911] = {
    id = 85141911,
    name = "真是挑剔的客人~请让威士忌和他们再聊聊——"
  },
  [85151911] = {
    id = 85151911,
    name = "关于生日您有什么计划吗？暂时没有？呵呵，那举办一场庆祝会如何？太麻烦？不，已经准备好了。来吧，让我带您先预演一遍流程。"
  },
  [85161911] = {
    id = 85161911,
    name = "对罗斯伯尔家族而言，每年举办的新年庆典是关乎家族名誉的大事，在深渊中我们也没有停办的理由，毕竟维护主家的名誉也执事的分内之事。"
  },
  [85171911] = {
    id = 85171911,
    name = "埃斯特拉小姐把甜点送给您了吗？呵呵~她前些天来问我怎么做甜点时便猜到了。不过从您手上拿着的东西来看，她只掌握了不到一半......我是不是也该准备一点作为谢礼呢，肯定比您拿的更美味~"
  },
  [85181911] = {
    id = 85181911,
    name = "又到这样的节日了吗？呵呵，真是怀念啊~我记得从我成为执事起，每年这个时候都会和大少爷一起去寻找埃斯特拉小姐......每年如此，几乎成为了罗斯伯尔家的特别习俗。"
  },
  [85191911] = {
    id = 85191911,
    name = "又到分发礼物的时节了，主家已经派人送来了礼物，不过派发似乎需要不少时间......可以请您一起帮忙吗，如果错过了时间礼物也就失去了意义。"
  },
  [85011991] = {
    id = 85011991,
    name = "あたしはシェラ・L・グリーンウッド。いろいろあって冒険者になろうと思っているんだ。よろしくね！"
  },
  [85021991] = {
    id = 85021991,
    name = "ね、クエスト行こうよ、暇だよ。"
  },
  [85031991] = {
    id = 85031991,
    name = "好きなこともできないで、望まない相手と結婚させられるなんておかしいよ。あたし、絶対に国には戻らない、自分の力で生きていくんだから！"
  },
  [85031992] = {
    id = 85031992,
    name = "冒険者は続けたいけど、それとは別に、あたしカフェをやってみたいな。"
  },
  [85041991] = {
    id = 85041991,
    name = "あたしだってずっとこのままは嫌だよ。ディアヴロやレムみたいに強くなって、ちゃんと一人でもやっていけるようになりたいんだ。"
  },
  [85041992] = {
    id = 85041992,
    name = "あたしだってずっとこのままは嫌だよ。ディアヴロやレムみたいに強くなって、ちゃんと一人でもやっていけるようになりたいんだ。"
  },
  [85041993] = {
    id = 85041993,
    name = "あたしだってずっとこのままは嫌だよ。ディアヴロやレムみたいに強くなって、ちゃんと一人でもやっていけるようになりたいんだ。"
  },
  [85051991] = {
    id = 85051991,
    name = "あたしは、あたしでいる理由が欲しかったんです。血筋とかじゃない、ありのままのあたしの価値が知りたかったんです。"
  },
  [85051992] = {
    id = 85051992,
    name = "あたしは、あたしでいる理由が欲しかったんです。血筋とかじゃない、ありのままのあたしの価値が知りたかったんです。"
  },
  [85051993] = {
    id = 85051993,
    name = "あたしは、あたしでいる理由が欲しかったんです。血筋とかじゃない、ありのままのあたしの価値が知りたかったんです。"
  },
  [85051994] = {
    id = 85051994,
    name = "あたしは、あたしでいる理由が欲しかったんです。血筋とかじゃない、ありのままのあたしの価値が知りたかったんです。"
  },
  [85051995] = {
    id = 85051995,
    name = "あたしは、あたしでいる理由が欲しかったんです。血筋とかじゃない、ありのままのあたしの価値が知りたかったんです。"
  },
  [85061991] = {
    id = 85061991,
    name = "ええ、あたしいやだな。"
  },
  [85071991] = {id = 85071991, name = "えい！"},
  [85071992] = {id = 85071992, name = "えい！"},
  [85071993] = {id = 85071993, name = "えい！"},
  [85081991] = {
    id = 85081991,
    name = "そんなこと言って後悔しないでよね。"
  },
  [85081992] = {
    id = 85081992,
    name = "さ、頑張っていこう！"
  },
  [85091991] = {
    id = 85091991,
    name = "どう？エンジェルシュートだよ！"
  },
  [85091992] = {
    id = 85091992,
    name = "突風の矢のトライアングルシュートだよ！"
  },
  [85121991] = {
    id = 85121991,
    name = "さようなら。今までありがとう..."
  },
  [85131991] = {
    id = 85131991,
    name = "帰ろう帰ろう、お腹へっちゃった。"
  },
  [85141991] = {
    id = 85141991,
    name = "ごめんね..."
  },
  [85012001] = {
    id = 85012001,
    name = "レム・ガレウです。私は冒険者として、強さを示し続ける必要があるのです。そのために、あなたの力を貸してください。"
  },
  [85022001] = {
    id = 85022001,
    name = "あなたの所有物ですか？そうですね、この隷従の首輪があるうちは..."
  },
  [85032001] = {
    id = 85032001,
    name = "私は今とある問題を抱えているのです。これを解決しない限り、私は将来のことを考える余裕もないのです。そしてこの問題はとても困難で、ふとした時に諦めてしまいそうになるほど、絶望的なものなのです。"
  },
  [85032002] = {
    id = 85032002,
    name = "普通の依頼なら構いませんが、不要に報酬の高いクエストはお断りです。"
  },
  [85042001] = {
    id = 85042001,
    name = "ちょこっとで大丈夫ですよ。"
  },
  [85042002] = {
    id = 85042002,
    name = "ちょこっとで大丈夫ですよ。"
  },
  [85042003] = {
    id = 85042003,
    name = "ちょこっとで大丈夫ですよ。"
  },
  [85052001] = {
    id = 85052001,
    name = "私の中には、魔王クレブスクルムの魂が封じられているんです。私の最終目標は、自分の中にある魔王クレブスクルムを倒し、その魂を消滅させることにあるのです。"
  },
  [85052002] = {
    id = 85052002,
    name = "私の中には、魔王クレブスクルムの魂が封じられているんです。私の最終目標は、自分の中にある魔王クレブスクルムを倒し、その魂を消滅させることにあるのです。"
  },
  [85052003] = {
    id = 85052003,
    name = "私の中には、魔王クレブスクルムの魂が封じられているんです。私の最終目標は、自分の中にある魔王クレブスクルムを倒し、その魂を消滅させることにあるのです。"
  },
  [85052004] = {
    id = 85052004,
    name = "私の中には、魔王クレブスクルムの魂が封じられているんです。私の最終目標は、自分の中にある魔王クレブスクルムを倒し、その魂を消滅させることにあるのです。"
  },
  [85052005] = {
    id = 85052005,
    name = "私の中には、魔王クレブスクルムの魂が封じられているんです。私の最終目標は、自分の中にある魔王クレブスクルムを倒し、その魂を消滅させることにあるのです。"
  },
  [85062001] = {
    id = 85062001,
    name = "覚悟はいいですか？"
  },
  [85072001] = {
    id = 85072001,
    name = "はあああ！"
  },
  [85072002] = {
    id = 85072002,
    name = "はあああ！"
  },
  [85072003] = {
    id = 85072003,
    name = "はあああ！"
  },
  [85082001] = {
    id = 85082001,
    name = "いまです！"
  },
  [85082002] = {
    id = 85082002,
    name = "さ、次いきます！"
  },
  [85092001] = {
    id = 85092001,
    name = "私はあなたの力を欲しています！"
  },
  [85092002] = {
    id = 85092002,
    name = "まとめて始末しなさい！"
  },
  [85122001] = {
    id = 85122001,
    name = "もう...私はダメです。後のことは..."
  },
  [85132001] = {
    id = 85132001,
    name = "私たちにできることは先に進むことです。"
  },
  [85142001] = {
    id = 85142001,
    name = "私のせいで、ごめんなさい..."
  },
  [85012011] = {
    id = 85012011,
    name = "就是你给我发的邀请？我是枭，让我们先聊聊寻宝计划吧，如果不够吸引力或者分成不合理，我可不会听你安排。"
  },
  [85022011] = {
    id = 85022011,
    name = "战斗之外的琐事就别指望我了，除非你想知道这些事情搞砸后会有什么后果。当然，吃饭玩乐不算琐事，我随时有空。"
  },
  [85032011] = {
    id = 85032011,
    name = "我留在深渊就是为了搜寻那些罕见的宝物、圣物，什么理想，什么意义完全不需要。嗯？你说这也算是一种理想？随你怎么理解，总之发现宝物的时候，记得及时告诉我就行。"
  },
  [85032012] = {
    id = 85032012,
    name = "探险队中似乎也有好些个对宝物感兴趣的人，等有机会可以和她们好好交流一下——你那是什么眼神，我真的只是想交流而已，能加入这个探险队的，至少品味不会太差。"
  },
  [85042011] = {
    id = 85042011,
    name = "这就是你所说的“实力提升”吗？感觉确实不错，我很满意。"
  },
  [85042012] = {
    id = 85042012,
    name = "战斗的事尽管交给我吧！不管有多少敌人，我都会将他们全部歼灭！"
  },
  [85042013] = {
    id = 85042013,
    name = "全身都充满力量的感觉实在太棒了！等着吧，我会让你知道你此刻的选择是多么的明智！"
  },
  [85052011] = {
    id = 85052011,
    name = "别把我和那些庸俗的宝物猎人混为一谈，我们虽然都是为了宝物而行动，但无论实力还是手段，我和那些半吊子完全不同。"
  },
  [85052012] = {
    id = 85052012,
    name = "追寻宝物并不是什么轻松的事，但正因为并不轻松，所以才更加有趣不是吗？"
  },
  [85052013] = {
    id = 85052013,
    name = "如此渴求宝物的原因？呵呵，你这个人是真的奇怪，总喜欢关注些不重要的事。算了，凭我们的关系，也不是不能告诉你。"
  },
  [85052014] = {
    id = 85052014,
    name = "我不会也不擅长思考太遥远的事，未来会怎样谁也不知道，对我来说，眼前的事就是最重要的，比如此刻与你的合作。"
  },
  [85052015] = {
    id = 85052015,
    name = "永远留在你身边，做你最可靠的同伴......哈哈哈，你还真敢说，换作别人我早动手了。不过这个提议倒也算有趣，那么你准备付出怎样的代价呢？"
  },
  [85062011] = {
    id = 85062011,
    name = "为我们的对手祈祷吧。"
  },
  [85072011] = {id = 85072011, name = "喝！"},
  [85072012] = {id = 85072012, name = "嘿噫！"},
  [85072013] = {id = 85072013, name = "哈！"},
  [85082011] = {
    id = 85082011,
    name = "轮到你了。"
  },
  [85082012] = {
    id = 85082012,
    name = "毁灭吧！"
  },
  [85092011] = {
    id = 85092011,
    name = "祈祷结束，该上路了！"
  },
  [85092012] = {
    id = 85092012,
    name = "倒霉鬼们，说再见吧！"
  },
  [85102011] = {id = 85102011, name = "呃。"},
  [85102012] = {id = 85102012, name = "唔啊。"},
  [85102013] = {id = 85102013, name = "呃啊。"},
  [85112011] = {
    id = 85112011,
    name = "有点意思......."
  },
  [85122011] = {
    id = 85122011,
    name = "这就是......我的结局吗......"
  },
  [85132011] = {
    id = 85132011,
    name = "既然选择成为我们的敌人，那被我歼灭便是早已注定的结局。"
  },
  [85142011] = {
    id = 85142011,
    name = "看来今天神明没有站在我们这边，走吧，整顿好再来收拾它们！"
  },
  [85152011] = {
    id = 85152011,
    name = "生日？呵呵，那咱们得找地方吃个爽快，喝个痛快！这附近正好有家我熟悉的店，走吧，今天我来请客！"
  },
  [85162011] = {
    id = 85162011,
    name = "新年好啊队长，在新的一年见到的第一个人就是你，感觉今年的收获会很不错。"
  },
  [85172011] = {
    id = 85172011,
    name = "竟然收到这么多礼物......不愧是我看中的人，果然很受欢迎嘛。给，这份是我的，不用急着说感想。"
  },
  [85182011] = {
    id = 85182011,
    name = "这种节日还真是热闹啊，说起来我有份藏宝图就是在节日庆典上偶然买到的......一起去看看吗队长？说不定会有什么有趣的发现。"
  },
  [85192011] = {
    id = 85192011,
    name = "以前在家里的时候，每到这种节日我们便会坐在火堆旁一起交换礼物，聊聊琐事......我偶尔也觉得那种生活还挺惬意的。"
  },
  [85011861] = {
    id = 85011861,
    name = "就是你在向本王祈求力量？......没问题，只要能让本王开心，这深渊中的一切，本王都可以赐予你。"
  },
  [85021861] = {
    id = 85021861,
    name = "本王今天的行程安排好了吗？如果太无聊了，本王可不会轻饶。"
  },
  [85031861] = {
    id = 85031861,
    name = "邪恶？正义？哼，都是笑话！不过是蝼蚁们无聊的游戏罢了，本王对那些理念并不感兴趣。主宰这个世界，只需要本王的意志和力量就足够了。"
  },
  [85031862] = {
    id = 85031862,
    name = "本王和鬼牌并非从属关系，而是合作！毕竟在这个混沌深渊中，能和本王一样看清这个世界本质的人并不多，本王不介意赐予她们与本王一起重塑深渊秩序的机会。"
  },
  [85041861] = {
    id = 85041861,
    name = "对那些在夹缝中挣扎的蝼蚁而言，取悦本王便是他们最荣耀的使命。"
  },
  [85041862] = {
    id = 85041862,
    name = "这深渊之中，能够称得上王的人只有本王一个！其他觊觎王座之人都只会有同样的结果——毁灭。"
  },
  [85041863] = {
    id = 85041863,
    name = "疯狂？呵呵、呵呵哈哈~疯狂的不是鬼王，而是这个世界！"
  },
  [85051861] = {
    id = 85051861,
    name = "本王只是因为对鬼牌感兴趣才选择了合作，鬼只是为本王提供了契机而已。那种喜欢躲在阴暗中的人，如何有资格与本王相提并论。"
  },
  [85051862] = {
    id = 85051862,
    name = "混乱是这个世界的法则，但随心所欲是王者的特权！即便是深渊的意志，也无法左右本王的决定。"
  },
  [85051863] = {
    id = 85051863,
    name = "对侍奉王者的人而言，不需要明白王者的意图，只要知道如何贯彻王者的意志就足够了！在这一点上，鬼侍做的比许多人都好。"
  },
  [85051864] = {
    id = 85051864,
    name = "在这个混乱的世界中即便即便权倾天下、富可敌国又如何，依然无法逃离无止尽的争斗，没有人能逃脱......"
  },
  [85051865] = {
    id = 85051865,
    name = "蔻琳？蔻琳......我是家产富可敌国的蔻琳？！爸爸......妈妈......不，我不是！她已经死了！我是鬼王，是主宰深渊的鬼王！"
  },
  [85061861] = {
    id = 85061861,
    name = "这便是为本王准备的乐趣？"
  },
  [85071861] = {id = 85071861, name = "哼！"},
  [85071862] = {id = 85071862, name = "嘿~"},
  [85071863] = {id = 85071863, name = "咿呀。"},
  [85081861] = {
    id = 85081861,
    name = "不可饶恕！"
  },
  [85081862] = {
    id = 85081862,
    name = "无聊至极。"
  },
  [85091861] = {
    id = 85091861,
    name = "不自量力的蠢货，死！"
  },
  [85091862] = {
    id = 85091862,
    name = "用毁灭来取悦本王吧！"
  },
  [85101861] = {id = 85101861, name = "哼。"},
  [85101862] = {id = 85101862, name = "唔。"},
  [85101863] = {id = 85101863, name = "呃。"},
  [85111861] = {
    id = 85111861,
    name = "嘁，竟敢阻碍本王！"
  },
  [85121861] = {
    id = 85121861,
    name = "区区......蝼蚁......"
  },
  [85131861] = {
    id = 85131861,
    name = "意料之中的结局，还有更有趣的猎物吗？"
  },
  [85141861] = {
    id = 85141861,
    name = "可恶！我会让它们知道惹怒本王的后果！"
  },
  [85151861] = {
    id = 85151861,
    name = "生日吗？呵呵，那就好好许愿吧~说不定慷慨的鬼王会实现你所有的愿望。"
  },
  [85161861] = {
    id = 85161861,
    name = "新年祈愿什么的根本不重要，本王喜欢的是新年里这种热闹的感觉。走吧，一起去看看今天又有哪些有趣的事。"
  },
  [85171861] = {
    id = 85171861,
    name = "似乎又是个特别的节日？说说你渴望的赏赐吧~哈？自己做的甜点？那、那是什么赏赐？！本王乃引领这深渊的存在，怎么可能做那种事！"
  },
  [85181861] = {
    id = 85181861,
    name = "幽灵的节日，呵~本王是这深渊的鬼王，这样的节日也算是在为本王庆贺了。我们也去吧，毕竟没有主角的庆典算不上圆满。"
  },
  [85191861] = {
    id = 85191861,
    name = "这是你向本王献上的礼物？呵呵，有趣。你的诚意本王收下了，那么，你渴望得到本王怎样的赏赐呢？"
  },
  [85011711] = {
    id = 85011711,
    name = "圣歌、圣光使，为消弭这深渊中的罪恶而来——"
  },
  [85021711] = {
    id = 85021711,
    name = "趁现在多休息一下也无妨，消弭罪恶不是什么轻松的事，或许很长时间都不会再有休息的机会。"
  },
  [85031711] = {
    id = 85031711,
    name = "我从不认为圣歌的愿望可以轻易实现，但不管目标有多么遥远，只要向着那个方向前行，便终有抵达的那天。"
  },
  [85031712] = {
    id = 85031712,
    name = "加入圣歌之前我也经常在各地追踪匪徒，那时候为了方便活动，易容、潜行、追踪之类的事我学了不少，如果有这方面的需求可以尽管找我。"
  },
  [85041711] = {
    id = 85041711,
    name = "无论怎样微小的罪恶也不可忽视，否则终会酿成大祸。"
  },
  [85041712] = {
    id = 85041712,
    name = "对罪人而言，没有规则的深渊宛如天堂，但我会成为他们天堂中的噩梦。"
  },
  [85041713] = {
    id = 85041713,
    name = "对罪人的宽容便是对善者的残忍，如果没有惩戒罪恶的决心，便无法贯彻守护善良的意志。"
  },
  [85051711] = {
    id = 85051711,
    name = "没有准备好一生背负自己罪孽的罪人，无论如何声泪俱下的忏悔，也不过都是为了求生而进行的表演罢了。"
  },
  [85051712] = {
    id = 85051712,
    name = "从我离开故乡那一刻起，复仇便成了我唯一的目标。如果没有加入圣歌，或许我仍沉浸在仇恨的漩涡中难以自拔。"
  },
  [85051713] = {
    id = 85051713,
    name = "有时候我会梦到父亲、梦到故乡的一切......但我已无法改变过去，所能做的只有守护现在，让那样的悲剧不再重演。"
  },
  [85051714] = {
    id = 85051714,
    name = "执念么......我对罪恶确实存在一定的执念，但我并不认为那是坏事，而且比起我的执念，赦罪人的偏执才更令人在意吧？"
  },
  [85051715] = {
    id = 85051715,
    name = "无论是为了守护善良，还是实现圣歌的目标，根除罪恶都是我必须要做的事。"
  },
  [85061711] = {
    id = 85061711,
    name = "我不会让任何敌人逃掉。"
  },
  [85071711] = {id = 85071711, name = "呵！"},
  [85071712] = {id = 85071712, name = "嘿咿。"},
  [85071713] = {id = 85071713, name = "喝啊~"},
  [85081711] = {
    id = 85081711,
    name = "跟得上吗？"
  },
  [85081712] = {
    id = 85081712,
    name = "尽在掌控。"
  },
  [85091711] = {
    id = 85091711,
    name = "这场纷争、该结束了。"
  },
  [85091712] = {
    id = 85091712,
    name = "没有罪恶可以逃过我的眼睛。"
  },
  [85101711] = {id = 85101711, name = "唔。"},
  [85101712] = {id = 85101712, name = "唔呃。"},
  [85101713] = {id = 85101713, name = "呜啊。"},
  [85111711] = {
    id = 85111711,
    name = "无论怎样挣扎，结局都已注定。"
  },
  [85121711] = {
    id = 85121711,
    name = "我早已做好了觉悟，可是......"
  },
  [85131711] = {
    id = 85131711,
    name = "比起那些穷凶极恶的罪人，这些敌人连麻烦也算不上。"
  },
  [85141711] = {
    id = 85141711,
    name = "先撤，比起大家的安危，这种失利算不上什么。"
  },
  [85151711] = {
    id = 85151711,
    name = "生日......这种日子一般需要准备礼物吧？但我已经很久没做过这种事了。你有什么想要的吗？在我所能做到的事情的范围内可以尽管开口。"
  },
  [85161711] = {
    id = 85161711,
    name = "新年聚会的通知已经送过来了，你应该有时间吧？请放心，参加聚会的都是圣歌成员，不会让你感到不自在。"
  },
  [85171711] = {
    id = 85171711,
    name = "据说表达谢意的最佳方式是亲手制作一些点心，但我的双手沾满了罪恶......当然，如果你不介意，可以和我说说你喜欢的口味。"
  },
  [85181711] = {
    id = 85181711,
    name = "我也曾和庆典中的那些肆意狂欢的人一样，直到罪恶夺走了我的一切......不过，现在的我已经有了守护大家的实力，我不会再让任何悲剧在我面前重演，为了守护大家的笑容，我会付所有。"
  },
  [85191711] = {
    id = 85191711,
    name = "节日快乐，这份礼物送给你。不用谢我，这也是大家向圣歌捐赠的，我只是负责将礼物送到需要的人手中而已。如果真的想表达谢意，可以帮忙派送一下这些礼物吗？"
  },
  [85012021] = {
    id = 85012021,
    name = "尊敬的队长，探险者蕾妮希雅向您致意。非常感谢您能让我拥有一个全新的开始。"
  },
  [85022021] = {
    id = 85022021,
    name = "贵安队长~每次见到您都感觉接下来会有好事发生——呵呵~请不要有压力，能与您一起度过这样安宁的时光，就已经是好事了。"
  },
  [85032021] = {
    id = 85032021,
    name = "尽管深渊中存在混乱和罪恶，但我依然觉得这里是个美丽的地方，是个充满梦想的世界。它赋予了探险者无限可能，让每个人都有追寻奇迹的机会。"
  },
  [85032022] = {
    id = 85032022,
    name = "我沉眠了很久很久，现在这个世界中的一切对我来说都无比新奇。所以我想把握好现在的每一刻，珍惜队长给予我的机会，尽情感受这个世界。"
  },
  [85032023] = {
    id = 85032023,
    name = "这风中传来的花香，让我不禁回想起多年以前与父王和母后一起在花园玩乐的时光......谢谢您能陪在我身边，让我能再次感受到那种的安心和惬意。"
  },
  [85042021] = {
    id = 85042021,
    name = "强大的力量让我有些不安，但如果是您的希望......我会全力以赴！"
  },
  [85042022] = {
    id = 85042022,
    name = "谢谢队长让我拥有了再次启程的勇气，让我能亲自决定自己的未来。"
  },
  [85042023] = {
    id = 85042023,
    name = "我从队长给予我的这份力量中感受到了温暖和信任，我会好好珍惜您给予我的一切，守护我们的未来！"
  },
  [85052021] = {
    id = 85052021,
    name = "时间长河带走了我曾经的亲人朋友，也带走了昔日的恩怨纠葛，带走了我曾拥有的一切......现在的我与新生的孩童并没有太多区别。"
  },
  [85052022] = {
    id = 85052022,
    name = "当我苏醒时，曾一度对这个陌生的世界感到恐惧，多亏了队长和守护者，因为有你们的陪伴，我才慢慢消除了心中的不安。"
  },
  [85052023] = {
    id = 85052023,
    name = "与死亡无异的沉眠让我度过了漫长岁月，也让我对现实的感知变得迟钝，有时候，我甚至会怀疑自己现在所经历的是真实还是幻梦。"
  },
  [85052024] = {
    id = 85052024,
    name = "我所经历的一切堪称奇迹，但我并非这个奇迹的主角，因为引发这个奇迹的，是父王母后对我爱，是守护者多年如一日的守护与坚持。"
  },
  [85052025] = {
    id = 85052025,
    name = "有这么多同伴的陪伴，我在这个崭新的世界里并不觉得孤独，当然，最重要的是队长，是你再次让我感受到了家人般的安心和温暖。"
  },
  [85062021] = {
    id = 85062021,
    name = "请注视着我吧，队长。"
  },
  [85072021] = {id = 85072021, name = "嘿咿。"},
  [85072022] = {id = 85072022, name = "呵呀。"},
  [85072023] = {id = 85072023, name = "呀咿。"},
  [85082021] = {
    id = 85082021,
    name = "交给我吧。"
  },
  [85082022] = {
    id = 85082022,
    name = "目标锁定。"
  },
  [85092021] = {
    id = 85092021,
    name = "请见证我的觉悟！"
  },
  [85092022] = {
    id = 85092022,
    name = "我不会再手下留情。"
  },
  [85092023] = {
    id = 85092023,
    name = "我们的未来，由我来守护！"
  },
  [85102021] = {id = 85102021, name = "呜啊。"},
  [85102022] = {id = 85102022, name = "呀。"},
  [85102023] = {id = 85102023, name = "呃啊。"},
  [85112021] = {
    id = 85112021,
    name = "我还可以继续。"
  },
  [85122021] = {
    id = 85122021,
    name = "又要......再次失去了吗......"
  },
  [85132021] = {
    id = 85132021,
    name = "因为队长在注视着我，所以我告诉自己绝不能输！"
  },
  [85142021] = {
    id = 85142021,
    name = "这样的结果绝不是我们想要的，下一次，我会努力做得更好。"
  },
  [85152021] = {
    id = 85152021,
    name = "小时候过生日，母后会给我准备她独创的蛋糕，外形虽然普通，但口感很棒！所以我也尝试着做了一下，队长快试试吧。"
  },
  [85162021] = {
    id = 85162021,
    name = "新年快乐，队长。没想到深渊中的新年庆典也能如此热闹，看来在我沉眠的这段时间里，这个世界发生了很多我所无法想象的事。"
  },
  [85202711] = {
    id = 85202711,
    name = "真羡慕擅长厨艺的大家，可以在今天准备精美点心送给重要的人——能表达心意就可以了？那、那么这个看起来不太好看的点心，队长可以收下吗？"
  },
  [85182021] = {
    id = 85182021,
    name = "今天的庆典真热闹啊，不知道现在的庆祝方式是怎样的，不然也可以去看看——您陪我一起去？真的吗？谢谢队长！"
  },
  [85192021] = {
    id = 85192021,
    name = "在我的故国，像队长这样能团结许多人、受许多人信赖的人，今天会被大家请出来表演节目，然后再接受所有人的祝福——听起来很有趣？呵呵，那队长要试试吗？我还记得仪式流程哦。"
  },
  [85012031] = {
    id = 85012031,
    name = "我并不讨厌“魔王”这个称呼，不过我还是更希望你能称我为守护者。嗯？不太符合我的气质？哈哈哈，是你自己让我决定的，想后悔也晚了。"
  },
  [85022031] = {
    id = 85022031,
    name = "太久没感受过这种平静的日子了，竟然有些不习惯，有什么打发时间的事吗？当然，得有趣一点的才行。"
  },
  [85032031] = {
    id = 85032031,
    name = "对曾经的我来说，深渊不过是实现目的猎场，并未觉得有什么特别之处。现在和你一起以探险者的视角来探索这个世界，感觉似乎还有点意思。"
  },
  [85032032] = {
    id = 85032032,
    name = "感觉好久没活动筋骨了，找谁切磋好呢——你那是什么眼神？我又不是什么杀人不眨眼的恶魔......既然这么不放心，那就由你陪我玩玩吧。"
  },
  [85032033] = {
    id = 85032033,
    name = "我感受到了你的情绪波动，还真是难得啊。不过只是换了身衣服而已，队长就这么好奇？呵呵，那么不妨再靠近一点，仔细欣赏一下吧。"
  },
  [85042031] = {
    id = 85042031,
    name = "这便是探险者提升力量的方式吗？确实比单纯的厮杀更有效率。"
  },
  [85042032] = {
    id = 85042032,
    name = "既然你展现出了足够的诚意，我的力量可以借给你一些，不过想要让我信服，只是这种程度还远远不够。"
  },
  [85042033] = {
    id = 85042033,
    name = "我是蕾妮希雅的守护者，今后也会是你的守护者。你的安危，你的人生，你的一切，通通交给我吧~"
  },
  [85052031] = {
    id = 85052031,
    name = "为了唤醒蕾妮希雅，我经历了无比漫长的岁月，在那段时间里，是银翼一直陪在我身边，协助我掌控深渊局势。"
  },
  [85052032] = {
    id = 85052032,
    name = "我对自己职责以外的事并不感兴趣，不过为了方便今后的行动，空闲的时候队长可以多和我说说你们人类的事。"
  },
  [85052033] = {
    id = 85052033,
    name = "我因守护的使命而诞生，所做的一切都是为了守护最重要的存在而已，任何妨碍我的人，都是敌人。"
  },
  [85052034] = {
    id = 85052034,
    name = "弥散在深渊中的负面情绪给予了我强大的力量，但也让我变得难以控制自己的理智，那种感觉，既让人痛苦，又让人陶醉。"
  },
  [85052035] = {
    id = 85052035,
    name = "看着你和你的成员同心协力的样子，连我也忍不住想要称赞你们的同伴情谊......我也是你不可或缺的同伴？队长说了有趣的话呢。"
  },
  [85062031] = {
    id = 85062031,
    name = "这就是你给我找的乐子？"
  },
  [85072031] = {id = 85072031, name = "嘿！"},
  [85072032] = {id = 85072032, name = "喝！"},
  [85072033] = {id = 85072033, name = "哈！"},
  [85082031] = {
    id = 85082031,
    name = "臣服吧！"
  },
  [85082032] = {
    id = 85082032,
    name = "不堪一击。"
  },
  [85092031] = {
    id = 85092031,
    name = "在死亡的恐惧中挣扎吧。"
  },
  [85092032] = {
    id = 85092032,
    name = "抓紧最后的机会哀嚎吧~"
  },
  [85092033] = {
    id = 85092033,
    name = "终于明白谁才是主人了吗？！"
  },
  [85102031] = {id = 85102031, name = "呃。"},
  [85102032] = {id = 85102032, name = "唔。"},
  [85102033] = {id = 85102033, name = "嘁。"},
  [85112031] = {id = 85112031, name = "狂妄！"},
  [85122031] = {
    id = 85122031,
    name = "不，我不该在这里倒下......"
  },
  [85132031] = {
    id = 85132031,
    name = "稍微宣泄了一些毁灭的欲望，不过离玩得尽兴还差得远呢。"
  },
  [85142031] = {
    id = 85142031,
    name = "很好，这些蝼蚁成功唤醒了我的愤怒，我会让它们见识真正的地狱！"
  },
  [85152031] = {
    id = 85152031,
    name = "来看看这头魔物，肉质鲜美，口感十足，即便是我和银翼也很难找到——为什么突然想到抓这种魔物？当然是为了给你庆祝生日了！"
  },
  [85162031] = {
    id = 85162031,
    name = "我此前并不明白新年的含义，但当我来到这里，见识到你们为新年所做的准备后，似乎也能慢慢感受到这一天的特别之处了。呵呵，新年快乐，队长。"
  },
  [85203711] = {
    id = 85203711,
    name = "今天为什么会有那么多人送你甜点？代表感谢的节日？人类的节日还真多啊......如果要表达感谢的话，答应你一个愿望怎么样？"
  },
  [85182031] = {
    id = 85182031,
    name = "没想到竟然还有专门装扮成亡灵、怪物的节日，哈哈哈，人类果然是有趣的存在，看来当初选择答应队长的邀请，果然是个明智决定。"
  },
  [85192031] = {
    id = 85192031,
    name = "交换礼物的节日吗？想要记住人类的节日习俗还真不容易，正好今天没什么别的安排，队长就好好和我聊聊这些节日的习俗吧。"
  },
  [85012041] = {
    id = 85012041,
    name = "呵呵，我还从未设想过会有这样一天，命运真是有趣啊。您还是叫我拉斯特吧，可爱的队长~"
  },
  [85022041] = {
    id = 85022041,
    name = "差点没感觉到我的气息？呵呵~队长越来越擅长说恭维的话了，我不是一直在您身边吗~"
  },
  [85032041] = {
    id = 85032041,
    name = "无论高塔、公会还是探险者，都对深渊中蕴藏的秘密和宝物充满了兴趣，我自然也不例外。不过嘛~比起深渊，我现在对队长更感兴趣~"
  },
  [85032042] = {
    id = 85032042,
    name = "队长最近经常将目光放到我身上呢，是担心我与其他人相处出现什么问题吗？还是说，是想寻找与我独处的机会？呵呵~请放心，既然加入了探险队，我会好好听从队长的安排~"
  },
  [85042041] = {
    id = 85042041,
    name = "竟然做出这样的决定，代表我已经完全被您信任了吗，队长？"
  },
  [85042042] = {
    id = 85042042,
    name = "被队长如此看重，真是倍感压力呢~呵呵，开玩笑的~您的这份信任，我收下了。"
  },
  [85042043] = {
    id = 85042043,
    name = "能为我做到这种程度，队长还真是慷慨啊~那么您在期待些什么呢？权势？名望？财富？还是说......我？"
  },
  [85052041] = {
    id = 85052041,
    name = "我虽然是带着守护者的记忆和部分力量而诞生，但我们的行事风格各有不同，所以我们既会合作也会单独行动。"
  },
  [85052042] = {
    id = 85052042,
    name = "与高塔中的生活相比，探险者的日常就像自由的飞鸟，不过再自由的飞鸟，也飞不出名为“命运”的囚笼。"
  },
  [85052043] = {
    id = 85052043,
    name = "如果队长早些年能投入高塔门下，说不定我们早就成为同伴了......不，也不一定，您这样优秀的人，或许在踏入高塔的那一刻，便会被我视为眼中钉，肆机清除。"
  },
  [85052044] = {
    id = 85052044,
    name = "轻易信任别人，在我看来并不算明智，不过或许正是队长所表现出的这种坦诚，才让我如此着迷。"
  },
  [85052045] = {
    id = 85052045,
    name = "蕾妮希雅已经苏醒，我最初的使命便算完成了，至于未来的打算嘛.......就让我陪在队长身边好好考虑一下吧，队长可别拒绝我哦~"
  },
  [85062041] = {
    id = 85062041,
    name = "我会尽量不让猎物感到痛苦，"
  },
  [85072041] = {id = 85072041, name = "喝！"},
  [85072042] = {id = 85072042, name = "嘿呀！"},
  [85072043] = {id = 85072043, name = "喝啊！"},
  [85082041] = {
    id = 85082041,
    name = "速战速决。"
  },
  [85082042] = {
    id = 85082042,
    name = "无用的挣扎。"
  },
  [85092041] = {
    id = 85092041,
    name = "死亡，如影随形。"
  },
  [85092042] = {
    id = 85092042,
    name = "这场猎杀，该结束了！"
  },
  [85102041] = {id = 85102041, name = "唔。"},
  [85102042] = {id = 85102042, name = "呃啊。"},
  [85102043] = {id = 85102043, name = "唔呃。"},
  [85112041] = {
    id = 85112041,
    name = "别想阻止我。"
  },
  [85122041] = {
    id = 85122041,
    name = "我还有未完成的使命......"
  },
  [85132041] = {
    id = 85132041,
    name = "久等了队长，对这次的狩猎结果还满意吗？"
  },
  [85142041] = {
    id = 85142041,
    name = "猎物的垂死挣扎比想象中更激烈啊~先撤吧，让它们再闹腾一会儿。"
  },
  [85152041] = {
    id = 85152041,
    name = "这种值得纪念的日子就该好好庆祝，就算不搞那些盛大的仪式，给自己放个假也总没错。走吧，今天就由我陪队长好好放松一下吧~"
  },
  [85162041] = {
    id = 85162041,
    name = "我从没想过自己会与您一起迎接新年，但这样的现实就是发生了。呵呵，看来我们的命运已经纠缠在了一起，未来究竟会有怎样的故事呢，我很期待~"
  },
  [85204711] = {
    id = 85204711,
    name = "我在高塔时从来不会在意这种节日，现在却觉得无比重要......呵呵，看来是在您身边呆得太久，让我在不知不觉中发生了改变，队长可以好好负起责任才行~"
  },
  [85182041] = {
    id = 85182041,
    name = "如此热闹的节日氛围，队长不觉得很适合两个人一起去逛逛吗？呵呵，别推脱了，有什么事后面我会替您处理，今天就将您的时间交给我，陪我好好享受一番吧。"
  },
  [85192041] = {
    id = 85192041,
    name = "节日快乐，队长大人~来看看这份礼物吧，虽然算不上贵重，但绝对独一无二。在我心里，队长正如同这份礼物一般，独一无二~"
  },
  [85012051] = {
    id = 85012051,
    name = "探险者伊莎贝尔，很荣幸加入您的探险队。如果有我能做的事，请尽管吩咐。"
  },
  [85022051] = {
    id = 85022051,
    name = "休息好了吗队长，今天的探险行动算不上轻松，出发前得调整好精神状态和体能才行。"
  },
  [85032051] = {
    id = 85032051,
    name = "探险队近期需要提交的各种资料我都准备好了，队长有时间请确认一下吧。嗯？感觉这种工作和我不搭？呵呵，我曾协助父亲整理过各种研究文件，这种事对我来说只是顺手而已。"
  },
  [85032052] = {
    id = 85032052,
    name = "我失去的那段记忆中似乎隐藏着许多重要信息，可我却怎么也想不起来是如何失忆的，到底失忆了多久。如果能找回那段记忆，或许我现在的诸多疑虑也都会有答案。"
  },
  [85042051] = {
    id = 85042051,
    name = "感谢队长的认可，希望我的力量真的有帮到您。"
  },
  [85042052] = {
    id = 85042052,
    name = "既然选择了成为探险者，我便会努力做到极致，无论现在还是将来。"
  },
  [85042053] = {
    id = 85042053,
    name = "我很清晰地感受到了您的期待和信任，我会全力以赴，担负属于自己的职责。"
  },
  [85052051] = {
    id = 85052051,
    name = "作为研究所所长的女儿，我虽然没能成为父亲那样的研究者，但我也在以自己的方式探索深渊中的隐秘。"
  },
  [85052052] = {
    id = 85052052,
    name = "我并不清楚父亲在别人眼里是怎样的形象，但在我眼里，他就是最伟大的研究者，是他让我拥有了探索未知的决心和勇气。"
  },
  [85052053] = {
    id = 85052053,
    name = "与同伴一起行动和独自行动时的感觉完全不同，需要考虑的东西多了很多，刚开始确实有些不习惯，不过现在，我已经慢慢喜欢上这种感觉了。"
  },
  [85052054] = {
    id = 85052054,
    name = "我尝试了很多方法也无法解读父亲留下的日记，不过我相信他一定在某个地方给我留下了提示，所以我才一直追寻着他的足迹在行动。"
  },
  [85052055] = {
    id = 85052055,
    name = "我也曾犹豫过是否还要继续寻找自己失去的那段记忆，我很担心那段记忆中隐藏着难以直面的过去......直到遇到了队长，是队长给了我信心，让我相信不管发生什么事，你也会继续支持我。"
  },
  [85062051] = {
    id = 85062051,
    name = "我明白自己的职责。"
  },
  [85072051] = {id = 85072051, name = "哈！"},
  [85072052] = {id = 85072052, name = "嘿。"},
  [85072053] = {id = 85072053, name = "呀啊！"},
  [85082051] = {id = 85082051, name = "看招。"},
  [85082052] = {
    id = 85082052,
    name = "贯穿吧。"
  },
  [85092051] = {
    id = 85092051,
    name = "死亡才是你们的终点。"
  },
  [85092052] = {
    id = 85092052,
    name = "恶敌、退散！"
  },
  [85102051] = {id = 85102051, name = "呃。"},
  [85102052] = {id = 85102052, name = "呜啊。"},
  [85102053] = {id = 85102053, name = "唔。"},
  [85112051] = {
    id = 85112051,
    name = "不必介意。"
  },
  [85122051] = {
    id = 85122051,
    name = "到此为止了吗......"
  },
  [85132051] = {
    id = 85132051,
    name = "只要遵从队长的指令行事，再强大的敌人也不足为惧。"
  },
  [85142051] = {
    id = 85142051,
    name = "出现了预料之外的情况，队长，我们先撤。"
  },
  [85152051] = {
    id = 85152051,
    name = "生日快乐队长，有想好许什么愿望了吗？啊，先别说，不然就不灵了。当然，如果愿望里有我能帮忙的事，队长直接吩咐就好，我一定会全力以赴。"
  },
  [85162051] = {
    id = 85162051,
    name = "谢谢队长在过去的一年里陪我寻找父亲的足迹，今年请让我陪队长一起去往更多地方吧。这并非回礼，我只是想这么做而已。"
  },
  [85172051] = {
    id = 85172051,
    name = "没想到在如此重要的节日里能和队长一起度过——感觉不自在？不，完全没有！不如说......反而感觉很庆幸。"
  },
  [85182051] = {
    id = 85182051,
    name = "受父亲的影响，我以前对这种鬼怪相关的节日完全不感兴趣，但自从父亲遇害后我就开始在意这个节日，甚至希望有关节日的传说都能变为现实。"
  },
  [85192051] = {
    id = 85192051,
    name = "以前帮父亲整理研究文件时，我曾看到过不少有关这个节日的故事——似乎很有趣？呵呵，那我就挑几个有意思的和队长讲讲吧。"
  },
  [85011771] = {
    id = 85011771,
    name = "渡鸦，荒野游骑兵。差不多就这样，其他的以后慢慢了解吧。"
  },
  [85021771] = {
    id = 85021771,
    name = "这个世界充满了太多虚伪且毫无意义的事，比如明明知道对方是去吃饭，打招呼时还是要问别人“去吃饭吗？”，完全感觉不到任何意义。"
  },
  [85031771] = {
    id = 85031771,
    name = "一味追逐着财富和名望的人群，在我看来是那么地狭隘。那些人根本不明白，当灵魂腐朽时，无论多么华丽的躯壳也都会如同这深渊一般空洞。"
  },
  [85031772] = {
    id = 85031772,
    name = "庸俗的人自然无法理解荒野游骑兵的理念，宝物就应该是拯救人的灵魂，让它的主人明悟自己人生意义的存在。"
  },
  [85041771] = {
    id = 85041771,
    name = "荒野游骑兵律令，处置宝物时必须要尊重宝物的意志。"
  },
  [85041772] = {
    id = 85041772,
    name = "断罪骑士这种称呼什么的，随便吧~我只想找到让自己明悟人生意义的宝物，其他事怎样都无所谓。"
  },
  [85041773] = {
    id = 85041773,
    name = "云雀那个孩子很不错啊，那种为了自己相信的一切而全力以赴的样子真的很耀眼。"
  },
  [85051771] = {
    id = 85051771,
    name = "我曾渴望成为和父亲一样的传奇探险者，可是当我逐渐明悟人生意义的时候，才发现那样的愿望并非我真正想要的。"
  },
  [85051772] = {
    id = 85051772,
    name = "所谓的挚友，和认识的时间长短并没有什么关系，正如同我和猎鹰，只要能彼此心意相通，在相遇那一刻就已经算得上挚友了。"
  },
  [85051773] = {
    id = 85051773,
    name = "命运为我们套上了名为物质的枷锁，若无法找到自己人生的意义将永远无法解脱。"
  },
  [85051774] = {
    id = 85051774,
    name = "努力并非坏事，但也不一定是好事，如果没有想清楚自己真正渴求的事物，再怎么努力也不过是从一个牢笼到另一个牢笼罢了。"
  },
  [85051775] = {
    id = 85051775,
    name = "深渊就是神明恶趣味的具现，被它引诱的灵魂将会慢慢腐朽、堕落，而能看清这一切的人，才有可能得到救赎和希望。"
  },
  [85061771] = {
    id = 85061771,
    name = "去寻宝？那快出发吧！"
  },
  [85071771] = {id = 85071771, name = "咻~"},
  [85071772] = {id = 85071772, name = "嘿！"},
  [85071773] = {id = 85071773, name = "哈咿。"},
  [85081771] = {
    id = 85081771,
    name = "锁定你了。"
  },
  [85081772] = {id = 85081772, name = "断罪。"},
  [85091771] = {
    id = 85091771,
    name = "堕落的灵魂啊，让我为你解脱。"
  },
  [85091772] = {
    id = 85091772,
    name = "别担心，马上就结束了。"
  },
  [85101771] = {id = 85101771, name = "呀啊。"},
  [85101772] = {id = 85101772, name = "唔。"},
  [85101773] = {id = 85101773, name = "呜哇。"},
  [85111771] = {
    id = 85111771,
    name = "可恶的家伙，不可原谅！"
  },
  [85121771] = {
    id = 85121771,
    name = "命运......真是残酷啊......"
  },
  [85131771] = {
    id = 85131771,
    name = "虽然收获不错，但还是没找到我想要的......嘛，也算是预料之内~"
  },
  [85141771] = {
    id = 85141771,
    name = "命运并不喜欢我们得到自己想要的结果，无论是谁都不会例外。"
  },
  [85151771] = {
    id = 85151771,
    name = "生日吗？生日快乐。其实我一直没有想明白为什么生日一定要吃蛋糕，明明还有更好的庆祝方式吧？比如......这样一起躺着休息，思考未来。"
  },
  [85161771] = {
    id = 85161771,
    name = "又过去了一年，冷漠的神明依然没有给我降下任何指引。新年庆祝会......这个混沌的世界中也只有这样的事情能为空洞的灵魂带来些微满足了。"
  },
  [85171771] = {
    id = 85171771,
    name = "感谢吗......人们总是喜欢在那些无聊的事上纠结、犹豫，要来一起躺着休息一下吗？这个枕头是给你的，可以抱着也可以倚靠，很实用吧。"
  },
  [85181771] = {
    id = 85181771,
    name = "人们对未知的存在总是充满恐惧和向往，幽灵如此，深渊也是如此，不过真的会有幽灵吗？它们也会思考自己存在的意义吗？......"
  },
  [85191771] = {
    id = 85191771,
    name = "所谓的节日就是空洞灵魂的安慰剂，精神强大的人根本不在乎。嗯~这句话好像很不错，我先记录一下，晚点就和大家分享这句话好了。"
  },
  [85011781] = {
    id = 85011781,
    name = "您、您好！我是夜莺，来自荒野游骑兵，谢、谢谢您的邀请。"
  },
  [85021781] = {
    id = 85021781,
    name = "这个应该是假的......这个也不太可靠......抱歉，我在整理最近收到的宝物情报，没注意到您已经来了。"
  },
  [85031781] = {
    id = 85031781,
    name = "情报分析和物资整理的工作确实有些繁琐，但我并不讨厌。因为忙碌的时候便会有一种“我也在和大家一起努力”的感觉，我很喜欢那种感觉。"
  },
  [85031782] = {
    id = 85031782,
    name = "我们收藏了许多“宝物”，骑士长说它们都在等待自己的主人，可是我至今还没见过有人来认领......不过既然是骑士长说的，那么一定不会错。"
  },
  [85041781] = {
    id = 85041781,
    name = "这样重要的时候，要、要背诵律令吧。律令三，做任何事都要以宝物为中心——"
  },
  [85041782] = {
    id = 85041782,
    name = "在荒野游骑兵中，我也有自己的封号——圣光骑士。只要是我可以做到的事，请尽管吩咐！"
  },
  [85041783] = {
    id = 85041783,
    name = "如果萨莉亚、不，如果骑士长知道我的实力达到这种程度，一定也会觉得开心吧。"
  },
  [85051781] = {
    id = 85051781,
    name = "我的故乡在一条交通要道边上，偶尔会有路过的大人物在那停留休息，导师就是在路过村庄时把我收为弟子的。"
  },
  [85051782] = {
    id = 85051782,
    name = "雪雁虽然喜欢吐槽大家，但心里其实一直都很在意我们，经常帮我分析情报、整理物资......我也想成为她那样可靠的人。"
  },
  [85051783] = {
    id = 85051783,
    name = "每次遇到问题的时候，比起依赖大家我更习惯于自己思考。我知道这样做或许会慢很多，但我不喜欢给大家添麻烦的感觉......"
  },
  [85051784] = {
    id = 85051784,
    name = "我刚到深渊时，尽管有足够的力量对付魔物，可是依然会感到害怕和孤独......对我而言，力量并不能让我感到安心。"
  },
  [85051785] = {
    id = 85051785,
    name = "一直以来我都非常胆小，对陌生和未知感到恐惧。是骑士长和大家给了我勇气，让我有了继续前行的力量。"
  },
  [85061781] = {
    id = 85061781,
    name = "我、我会努力跟上大家。"
  },
  [85071781] = {id = 85071781, name = "嘿噫。"},
  [85071782] = {id = 85071782, name = "哈啊！"},
  [85071783] = {id = 85071783, name = "喝呀。"},
  [85081781] = {
    id = 85081781,
    name = "交给我吧。"
  },
  [85081782] = {
    id = 85081782,
    name = "要、要上了。"
  },
  [85091781] = {
    id = 85091781,
    name = "请见证我的决心吧！"
  },
  [85091782] = {
    id = 85091782,
    name = "我也有自己可以做到的事。"
  },
  [85101781] = {id = 85101781, name = "呜啊。"},
  [85101782] = {id = 85101782, name = "呃。"},
  [85101783] = {id = 85101783, name = "呀啊。"},
  [85111781] = {
    id = 85111781,
    name = "没、没事，请不用担心。"
  },
  [85121781] = {
    id = 85121781,
    name = "我成为......大家的拖累了吗......"
  },
  [85131781] = {
    id = 85131781,
    name = "这次行动我有好好帮上忙吗？"
  },
  [85141781] = {
    id = 85141781,
    name = "对不起，是我拖了大家的后腿......"
  },
  [85151781] = {
    id = 85151781,
    name = "生、生日快乐！那个、礼物，还有蛋糕，我都准备好了，希望您喜欢......"
  },
  [85161781] = {
    id = 85161781,
    name = "那个、新年庆祝会，能一起去吗？虽然是我们组织的集会，但如果您能一起，大家都会很开心。"
  },
  [85171781] = {
    id = 85171781,
    name = "谢谢您一直以来的关照！那个、这个送给您！这是我记录的一些深渊情报，应该不会有错，希望能有用。"
  },
  [85181781] = {
    id = 85181781,
    name = "我一直很想见一眼幽灵，每到这种节日我都会努力寻找它们的身影，可是一直未能如愿，今年能和我一起去找找吗？"
  },
  [85191781] = {
    id = 85191781,
    name = "荒野游骑兵庆祝这种节日的方式是为其他成员做一件事，我完全不知道该为大家做些什么，队长有什么建议吗？"
  },
  [85012061] = {
    id = 85012061,
    name = "按照约定，探险者艾拉正式加入您的探险队。从这一刻起，我们就算是真正的同伴了吧，队长？"
  },
  [85022061] = {
    id = 85022061,
    name = "队长来得正好，快救救我，探险队的这些资料看得我犯困......我果然不擅长处理文稿之类的工作，要不我聘请一个秘书来处理？"
  },
  [85032061] = {
    id = 85032061,
    name = "探险队中不少人都有自己的组织，比如圣歌、自由学派什么的，让我有种势单力薄的感觉......要不咱俩也去成立一个组织？这样以后自报家门的时候，感觉会更有气势！"
  },
  [85032062] = {
    id = 85032062,
    name = "休息的时候就该好好休息，什么也不要想，让身体和头脑都彻底放松，如此一来才能在行动中完美展现自己的实力。"
  },
  [85042061] = {
    id = 85042061,
    name = "好好期待吧，我的剑术绝对不会让你失望。"
  },
  [85042062] = {
    id = 85042062,
    name = "你有冷静聪明的头脑，我有精湛绝伦的剑术，只要我们完美配合，就没有什么能阻拦我们！"
  },
  [85042063] = {
    id = 85042063,
    name = "以我现在的实力，比起师父可能就只差一点点了，如果能继续成长，我一定可以成为她那样的剑术大师。"
  },
  [85052061] = {
    id = 85052061,
    name = "我选择成为探险者是想要历练自己，希望有朝一日能成为师父那样的大师，所以比起宝物什么的，我更在意历练的机会。"
  },
  [85052062] = {
    id = 85052062,
    name = "师父经常告诫我，凡事多动脑，多思考，否则就算学会了最顶尖的剑术，也无法发挥作用。"
  },
  [85052063] = {
    id = 85052063,
    name = "我这一路可真够倒霉的，似乎把这世间所有的坎坷全都经历了一遍......不过归根到底还是我不够强大，不然不管什么麻烦肯定都能轻松解决。"
  },
  [85052064] = {
    id = 85052064,
    name = "武技方面我距离顶尖探险者确实还存在不少差距，但作为淑女，我对自己在文学方面的修行成果有不会输给任何人的自信！"
  },
  [85052065] = {
    id = 85052065,
    name = "我一直很倒霉，还经常连累身边的人，你是第一个陪我一起倒霉却毫无怨言的人......现在我的实力已经提升了，今后只会遇到幸运的事，接下来就让我带你去感受幸运吧。"
  },
  [85062061] = {
    id = 85062061,
    name = "好好期待我的表现吧。"
  },
  [85072061] = {id = 85072061, name = "喝！"},
  [85072062] = {id = 85072062, name = "哈咿。"},
  [85072063] = {id = 85072063, name = "哈！"},
  [85082061] = {
    id = 85082061,
    name = "有破绽。"
  },
  [85082062] = {id = 85082062, name = "看招。"},
  [85092061] = {
    id = 85092061,
    name = "在我的剑下战栗吧。"
  },
  [85092062] = {
    id = 85092062,
    name = "剑光，闪耀吧！"
  },
  [85102061] = {id = 85102061, name = "唔啊。"},
  [85102062] = {id = 85102062, name = "呃。"},
  [85102063] = {id = 85102063, name = "呜哇。"},
  [85112061] = {
    id = 85112061,
    name = "竟然偷袭。"
  },
  [85122061] = {
    id = 85122061,
    name = "旅程......结束了吗......"
  },
  [85132061] = {
    id = 85132061,
    name = "能倒在我这么高明的剑术下，敌人也可以安息了。"
  },
  [85142061] = {
    id = 85142061,
    name = "可恶——不对，现在不是较劲的时候，不然就落入敌人的圈套了。"
  },
  [85152061] = {
    id = 85152061,
    name = "生日快乐队长！——没想到我会记得？呵呵，就算平时再怎么放空自己，重要的东西我也绝不会忘记！做好准备了吗，今天就由我来陪你庆祝！"
  },
  [85162061] = {
    id = 85162061,
    name = "竟然已经到新年了......果然和信赖的人一起努力，时间就过得飞快。我们先商量一下今年的计划吧，今年必须比去年做得更好才行。"
  },
  [85172061] = {
    id = 85172061,
    name = "为什么这种节日一定要送亲手做的点心呢，就算是淑女，有些不擅长的事也很正常吧？不必在意？不，不行。一起去购物吧，不管你看上什么，我都会为你买下。"
  },
  [85182061] = {
    id = 85182061,
    name = "因为我总是倒霉，还容易影响到周围的人，所以我很久没有参加过这种节日庆典了。最近倒霉的情况少了很多，似乎可以去看看？你能陪我一起吗？"
  },
  [85192061] = {
    id = 85192061,
    name = "温暖的火堆、松软的坐垫......还有食物的香味......这种感觉太安宁了，似乎回到了以前和师父在一起的时候，队长如果能再给我讲讲故事，就更像了。"
  },
  [85012071] = {
    id = 85012071,
    name = "队长你好，我是探险者星轨。兴趣是探险，特长是魔法，暂时能想到的差不多就这些了，今后请多多指教咯。"
  },
  [85022071] = {
    id = 85022071,
    name = "队长，行动计划我已经处理完啦，是不是可以去玩了？欸，太粗略了？这种程度已经够了吧，再详细的话，感觉会少很多惊喜。"
  },
  [85032071] = {
    id = 85032071,
    name = "难得空闲，就这样呆着感觉有些浪费时间啊。队长有空吗，要不一起去周围走走？走嘛~就当去侦察一下情报，提前为行动做准备。"
  },
  [85032072] = {
    id = 85032072,
    name = "我在周围采集了一些野果，队长来试试吧。放心，每一种我都试过了，没毒。不过这其中有一种超级酸，会不会吃到就看你运气了！"
  },
  [85042071] = {
    id = 85042071,
    name = "哇哦，感谢队长提拔！这是准备对我委以重任了吗？"
  },
  [85042072] = {
    id = 85042072,
    name = "谢谢队长！能获得如此强大的力量，今后执行任务一定会更有效率，休闲娱乐的时间自然也就更多了。"
  },
  [85042073] = {
    id = 85042073,
    name = "我从没想过自己能达到这种程度，果然当初选择加入队长的探险队，是一个无比英明的决定！"
  },
  [85052071] = {
    id = 85052071,
    name = "作为探险者，力量是我们不可或缺的存在，但绝不能一味地追求力量，不管何时，我们都应该牢记自己启程时的初心。"
  },
  [85052072] = {
    id = 85052072,
    name = "我从小就很喜欢探险，对各种未知事物感到好奇，所以成为探险者是我一直以来的目标。希望有朝一日，自己的足迹能遍布深渊各地。"
  },
  [85052073] = {
    id = 85052073,
    name = "每一次成长我都会觉得非常开心，但紧接着我便会有一些迷茫......我很清楚更强的实力也代表着更多的责任，我不知道自己能否承担那份职责。"
  },
  [85052074] = {
    id = 85052074,
    name = "就算目的地的风景并不迷人，努力揭露的真相无法让人满意也不用在意，对踏上旅途的人而言，最重要的从来都不是结果。"
  },
  [85052075] = {
    id = 85052075,
    name = "太阳总会落山，旅途也总有终点，不过在那之前，我们可以做更多有意义的事。比如？比如和队长一起，走遍这深渊的每一个角落。"
  },
  [85062071] = {
    id = 85062071,
    name = "终于要出发了吗？"
  },
  [85072071] = {id = 85072071, name = "嘿咿。"},
  [85072072] = {id = 85072072, name = "哈呀。"},
  [85072073] = {id = 85072073, name = "呵。"},
  [85082071] = {
    id = 85082071,
    name = "交给我吧。"
  },
  [85082072] = {
    id = 85082072,
    name = "很快就好。"
  },
  [85092071] = {
    id = 85092071,
    name = "就用这招结束一切。"
  },
  [85092072] = {
    id = 85092072,
    name = "妨碍我们的家伙，消失吧！"
  },
  [85102071] = {id = 85102071, name = "哇啊。"},
  [85102072] = {id = 85102072, name = "呜啊。"},
  [85102073] = {id = 85102073, name = "唔呃。"},
  [85112071] = {
    id = 85112071,
    name = "好痛啊，太可恶了。"
  },
  [85122071] = {
    id = 85122071,
    name = "群星......也终会落幕......"
  },
  [85132071] = {
    id = 85132071,
    name = "呼~真是费了不少功夫，不过前行道路已经全部清理好了，继续出发吧，队长。"
  },
  [85142071] = {
    id = 85142071,
    name = "真是难缠的对手......我们绕路吧，队长。"
  },
  [85152071] = {
    id = 85152071,
    name = "生日快乐！嘻嘻，队长，今天这么重要的日子，就别考虑探险工作啦，一起玩个尽兴吧！放心，后面我会陪你把落下的工作做好的。"
  },
  [85162071] = {
    id = 85162071,
    name = "队长来看这个地图，上面画着红叉的地方我们都去过了，今年要陪我去更多地方哦。不许拒绝，这可是我的新年愿望！"
  },
  [85172071] = {
    id = 85172071,
    name = "队长节日快乐。我今早去采了一束花，送给你。这些花都有不同的花语，比如这种是思念，这种是感谢，至于这种嘛......就留给队长自己查吧。"
  },
  [85182071] = {
    id = 85182071,
    name = "真是热闹的节日啊，如果能和队长一起参加庆典就更加完美了！繁忙的队长大人，能让我拥有一个完美的节日吗？"
  },
  [85192071] = {
    id = 85192071,
    name = "节日快乐队长，这是给你的礼物，一套全新的探险装备，快试试吧！回礼？呵呵，我已经收到最棒的礼物了哦，那可是会陪我走遍这个世界的存在。"
  },
  [85012081] = {
    id = 85012081,
    name = "非常感谢您的邀请，我是探险者风痕，如果有我能帮忙的事请尽管吩咐，我一定会全力以赴，回应您的期待。"
  },
  [85022081] = {
    id = 85022081,
    name = "整理探险队资料这种工作很有趣，从这一页页记录里，我能清晰地感受到队长对探险队的付出，对每一位成员的重视。"
  },
  [85032081] = {
    id = 85032081,
    name = "我很喜欢风，因为风里总会夹杂着旅途的气息。每当它们从我身边刮过，我都会有一种别样的感觉，让我觉得自己充满了勇气，对下一个目的地也更加期待。"
  },
  [85032082] = {
    id = 85032082,
    name = "“群星从天际坠落......是灾难、也是希望......”这本书里的猜想真是让人大开眼界——欸，队长也看过吗？没想到这么冷门的书您也知道......可以和我聊聊您的读后感吗？"
  },
  [85042081] = {
    id = 85042081,
    name = "队长对我的关照就如同和煦的风，无微不至。"
  },
  [85042082] = {
    id = 85042082,
    name = "非常感谢队长为我解答疑惑，让我能有机会窥探更广阔的世界。"
  },
  [85042083] = {
    id = 85042083,
    name = "如果能完全掌握这份力量，或许我也可以像狂风一样，摧毁前行路上的所有阻碍。"
  },
  [85052081] = {
    id = 85052081,
    name = "除了战斗相关的工作，资料整理、情报分析的工作队长也可以尽管交给我，我觉得自己在这些方面应该也能帮上忙。"
  },
  [85052082] = {
    id = 85052082,
    name = "“知己知彼，百战不殆。”对情报的收集、分析能力，往往能决定一次重要行动的成败。"
  },
  [85052083] = {
    id = 85052083,
    name = "您对这本笔记感兴趣？请看吧，里面是我做的各种旅行记录。每次遇到特别的事物我都会记下来，希望有一天，我也能拥有属于自己的游记。"
  },
  [85052084] = {
    id = 85052084,
    name = "我在观察和分析方面表现得还算不错，但不太善于决断，所以有时候反而会被自己的分析干扰，陷入纠结。"
  },
  [85052085] = {
    id = 85052085,
    name = "每当迟疑的时候，我便会渴求风的指引。但来到探险队后，不管遇到什么事都可以依靠队长，或许队长已经成为我新的“风”了。"
  },
  [85062081] = {
    id = 85062081,
    name = "准备完毕，随时可以出发。"
  },
  [85072081] = {id = 85072081, name = "嘿。"},
  [85072082] = {id = 85072082, name = "呀啊。"},
  [85072083] = {id = 85072083, name = "呵。"},
  [85082081] = {
    id = 85082081,
    name = "锁定目标。"
  },
  [85082082] = {
    id = 85082082,
    name = "束手就擒。"
  },
  [85092081] = {
    id = 85092081,
    name = "用这一箭，终结一切！"
  },
  [85092082] = {
    id = 85092082,
    name = "用这一箭，开辟前路！"
  },
  [85102081] = {id = 85102081, name = "呃。"},
  [85102082] = {id = 85102082, name = "呜啊。"},
  [85102083] = {id = 85102083, name = "唔呃。"},
  [85112081] = {
    id = 85112081,
    name = "我、不会停下。"
  },
  [85122081] = {
    id = 85122081,
    name = "这里......就是终点吗......"
  },
  [85132081] = {
    id = 85132081,
    name = "队长出色的决断力和临场应变能力，是我们能取胜的关键。"
  },
  [85142081] = {
    id = 85142081,
    name = "这阵风里夹杂着危险的味道，队长，我们先撤吧。"
  },
  [85152081] = {
    id = 85152081,
    name = "生命拥有无限可能，所以每一个生日都值得庆祝，不管有多繁忙，今天都请好好享受吧，当然，如果您愿意，我也想一起分享您的这份喜悦。"
  },
  [85162081] = {
    id = 85162081,
    name = "过去一年的计划都已经完成，今年要做些什么好呢......尝试一些和以往完全不同的事？似乎是个好主意，那么就请队长协助我完成这个计划吧。"
  },
  [85172081] = {
    id = 85172081,
    name = "一起去吹吹风吗队长？很抱歉我不擅长厨艺，无法为您制作代表节日的点心，所以我想用这种专属于我的方式向您传达谢意。"
  },
  [85182081] = {
    id = 85182081,
    name = "今天怎么这么热闹？原来如此，竟然是这样的节日......不过真的会有幽灵吗？您见过，真的吗？！请务必和我详细说说，拜托了。"
  },
  [85192081] = {
    id = 85192081,
    name = "因为太过随性，我很难遇到同行之人。自从踏上旅途，我还是第一次和别人一起度过这个节日，非常感谢风能指引我遇到您，让我的旅途不再是孤身一人。"
  },
  [85011751] = {
    id = 85011751,
    name = "非常感谢您对深渊航线的信任，这段时间关于您的护卫支援任务将由我负责。我是赫拉迪斯，代号永夜。"
  },
  [85021751] = {
    id = 85021751,
    name = "这是近期的探险计划吗？我没问题。我所在意的，是要怎样做才能最大限度确保您的安全，对于目的和行程并没有太多想法。"
  },
  [85031751] = {
    id = 85031751,
    name = "我来深渊是想要寻找自己的未来，可是在见识太多残酷的场面之后，我也希望自己能为这个世界做点什么，所以加入了深渊航线......或许这便是我对自己未来的选择。"
  },
  [85031752] = {
    id = 85031752,
    name = "我经常和辉夜一起执行任务，她很注重组织的各种流程规范，唯独对于“极端情况下，允许放弃任务带领客人撤退”这种规定从不理会，我从未见过她因为任何困难选择放弃任务。"
  },
  [85041751] = {
    id = 85041751,
    name = "我并不懂那些太深奥的道理，只要能守护深渊中的安宁，不管什么事我都会全力去做。"
  },
  [85041752] = {
    id = 85041752,
    name = "追寻力量的目的？我还从来没考虑过这个问题，我只是想将自己能做到的事做到极致，守护更多的人，仅此而已。"
  },
  [85041753] = {
    id = 85041753,
    name = "每次完成护卫任务后，大家展露的笑容都让我觉得满足，这也让我更加确信了自己所追寻的未来。"
  },
  [85051751] = {
    id = 85051751,
    name = "我曾犹豫是否该成为探险者，是父亲消除了我的迷惘，他鼓励我勇敢向前，在更广阔的世界寻找自己的未来。"
  },
  [85051752] = {
    id = 85051752,
    name = "执行组织的任务时常常需要在各地奔走，每次前往新的地方时我都会有一些期待，我仍在期望着能够见一次我从未见过面的母亲。"
  },
  [85051753] = {
    id = 85051753,
    name = "守护深渊的秩序绝非一个深渊航线可以做到，所以我们需要更加活跃，召集更多拥有共同理念的组织，联合起来实现这个愿望。"
  },
  [85051754] = {
    id = 85051754,
    name = "强大的力量可以轻易摧毁敌人，却改变不了深渊的残酷，唯有宽容和希望，才能为这个世界带来救赎。"
  },
  [85051755] = {
    id = 85051755,
    name = "我并不清楚自己现在的表现是否符合父亲的期望，但队长对我的认可，让我确信自己做出了最适合自己的选择。"
  },
  [85061751] = {
    id = 85061751,
    name = "我会全力护卫您的安全。"
  },
  [85071751] = {id = 85071751, name = "喝啊！"},
  [85071752] = {id = 85071752, name = "哈！"},
  [85071753] = {id = 85071753, name = "嘿呀！"},
  [85081751] = {
    id = 85081751,
    name = "别想逃！"
  },
  [85081752] = {
    id = 85081752,
    name = "尽管来吧！"
  },
  [85091751] = {
    id = 85091751,
    name = "你们已经错过了后悔的时机。"
  },
  [85091752] = {
    id = 85091752,
    name = "战斗，是为了更好地守护。"
  },
  [85101751] = {id = 85101751, name = "呃~"},
  [85101752] = {id = 85101752, name = "唔。"},
  [85101753] = {id = 85101753, name = "呜啊。"},
  [85111751] = {
    id = 85111751,
    name = "别想从我这里通过。"
  },
  [85121751] = {
    id = 85121751,
    name = "如果......能见一面就好了......"
  },
  [85131751] = {
    id = 85131751,
    name = "这次的发挥还不够出色，下次我会表现得更加从容。"
  },
  [85141751] = {
    id = 85141751,
    name = "怎么会......大家快撤，至少让我保证大家的安全！"
  },
  [85151751] = {
    id = 85151751,
    name = "生日？抱歉，我竟然没有注意到，生日快乐。......嗯，生日的话是不是还少了些什么？啊，蛋糕！抱歉！请稍等一下，我马上去准备！"
  },
  [85161751] = {
    id = 85161751,
    name = "在我的故乡，新年代表着团聚。我现在身处深渊，无法和父亲一起度过，确实有些想念......不过，能和这么多同伴一起，我也觉得非常有意义。"
  },
  [85171751] = {
    id = 85171751,
    name = "父亲说真诚感谢他人的时候，需要低头、双手握紧对方的手......可以请您把手伸出来吗？——非常感谢您对我的支持和信任，我会努力回应您的期待！"
  },
  [85181751] = {
    id = 85181751,
    name = "听说圈落里今天会举办盛大的节日庆典，要一起去看看吗？——我也叫了其他的同伴，可是大家似乎都有事，所以，能请您陪我一起吗？"
  },
  [85191751] = {
    id = 85191751,
    name = "小时候我每个节日都会收到许多的礼物，父亲告诉我那些都是母亲给我的，直到长大后我才明白父亲善意的谎言......他给予了我他所有的一切，让我在成长过程中不会感受到缺失和遗憾。"
  },
  [85011931] = {
    id = 85011931,
    name = "真理之钥的同伴受您关照了，队长。我是湄，在探险方面还算有些经验，如果有能帮上忙的地方请尽管吩咐。"
  },
  [85021931] = {
    id = 85021931,
    name = "近期探险计划中的物资我已经全都准备好了，请确认一下吧~在真理之钥时这些事也都是我在负责，应该不会出错。"
  },
  [85031931] = {
    id = 85031931,
    name = "真理之钥的成员确实不多，不过并不是我们拒绝招收新成员，而是能达到“拥有相似理想并愿意为之全力以赴”这个条件的人太少了，如果无法达到这样的条件，成员再多也没有意义。"
  },
  [85031932] = {
    id = 85031932,
    name = "刚到深渊时我和霏都曾感到迷茫，感觉自己和其他探险者格格不入，直到真理之钥成立，我们才有了明确的目标，找到了前行的方向。"
  },
  [85041931] = {
    id = 85041931,
    name = "我曾听说过这种提升实力的方法，但实际体验还是第一次。"
  },
  [85041932] = {
    id = 85041932,
    name = "并非所有问题都能在书本中找到答案，这个世界上还有许多问题需要我们亲自去探索。"
  },
  [85041933] = {
    id = 85041933,
    name = "我现在所追寻的一切在别人看来或许有些荒谬，但不管别人怎么看待，只要是自己认定的事，我就绝不会动摇！"
  },
  [85051931] = {
    id = 85051931,
    name = "我有许多渴望做到的事，可是常常都只是“想”，直到来到深渊，和真理之钥的大家一起行动后，才逐渐有了改变。"
  },
  [85051932] = {
    id = 85051932,
    name = "我对武技和魔法都略有研究，只是在实战中更喜欢用剑而已。队长对我的魔法感兴趣？呵呵，如果有机会可以为你展示一下。"
  },
  [85051933] = {
    id = 85051933,
    name = "对探险者来说，任何“小事”都可能带来严重后果，或许魔法和武技的奥秘也一样，那些习以为常的“小事”才是窥探本源的关键。"
  },
  [85051934] = {
    id = 85051934,
    name = "真理之钥的其他人都觉得我可靠，其实我也只是“看起来”可靠而已，偶尔我也会和大家一样不知所措，对未知感到恐惧。"
  },
  [85051935] = {
    id = 85051935,
    name = "探寻武技和魔法的本源这种话并不适合挂在嘴边，但因为是队长，所以总想和你谈论最近的收获和未来的打算......你不会介意吧？"
  },
  [85061931] = {
    id = 85061931,
    name = "准备完毕，大家出发吧。"
  },
  [85071931] = {id = 85071931, name = "呀咿~"},
  [85071932] = {id = 85071932, name = "喝！"},
  [85071933] = {id = 85071933, name = "嘿呀。"},
  [85081931] = {
    id = 85081931,
    name = "我不会退缩。"
  },
  [85081932] = {
    id = 85081932,
    name = "全力以赴！"
  },
  [85091931] = {
    id = 85091931,
    name = "这是我才能做到的事。"
  },
  [85091932] = {
    id = 85091932,
    name = "我会清除所有的阻碍！"
  },
  [85101931] = {id = 85101931, name = "呃啊~"},
  [85101932] = {id = 85101932, name = "唔。"},
  [85101933] = {id = 85101933, name = "唔呃。"},
  [85111931] = {
    id = 85111931,
    name = "我才不会就这样放弃。"
  },
  [85121931] = {
    id = 85121931,
    name = "如果......我能再强一点......"
  },
  [85131931] = {
    id = 85131931,
    name = "只要做好了充足的准备，无论怎样的困难都无法阻止我们。"
  },
  [85141931] = {
    id = 85141931,
    name = "变成这样，一定是我还有什么地方没有考虑到......"
  },
  [85151931] = {
    id = 85151931,
    name = "请问今天有时间吗？并不是急事，我们想举办一个生日庆祝会——谁的？难道你忘了今天生日吗？呵呵，行动结束后也没问题，大家会一起等你。"
  },
  [85161931] = {
    id = 85161931,
    name = "新年快乐队长，新的一年有什么打算吗？想先听听我的？呵呵，我自然是想继续为了真理之钥的目标而努力，现在有队长陪在身边，我相信一定会有所收获。"
  },
  [85171931] = {
    id = 85171931,
    name = "队长来试试这个点心的味道怎么样——嗯？买的？不，这是我自己做的。看起来不像吗？呵呵，我擅长的事还有不少，今后有机会我会为队长展示的。"
  },
  [85181931] = {
    id = 85181931,
    name = "之前参加庆典时，真理之钥的大家都喜欢进行一些有趣的比试。岚虽然嘴上说着不符合淑女的形象，但却表现得比任何人都要努力。呵呵，不知道今年会有怎样的比试。"
  },
  [85191931] = {
    id = 85191931,
    name = "真理之钥最初交换的礼物也都是很常见的那种，我就想着“我们能否有些特别的礼物呢”，于是就和大家商量，考虑了很久后我们才决定将彼此修行时获得的感悟作为礼物交换。"
  },
  [85011941] = {
    id = 85011941,
    name = "您好，我是真理之钥的霏——嗯？队长已经听说过我了？呵呵，非常感谢您的邀请，让我们一起去揭晓更多问题的答案吧🎵~"
  },
  [85021941] = {
    id = 85021941,
    name = "今天的探险行程确定好了吗？我有几个新的想法想验证一下，所以想找些更合适的对手。"
  },
  [85031941] = {
    id = 85031941,
    name = "“探寻魔法和武技的根源”这种事在一般人看来根本就是白日梦，可是如果不去尝试永远都不会知道结果。而且就算最后真的什么也没发现，在追逐的过程中我们一定也会有许多收获。"
  },
  [85031942] = {
    id = 85031942,
    name = "真理之钥刚成立时，成员只有三个人，那段时间真的非常辛苦啊，很多计划都无法实施，探险的收获也很少，而且还经常被人嘲笑。"
  },
  [85041941] = {
    id = 85041941,
    name = "如此运用力量......不错的思路，感觉可以深入了解一下。"
  },
  [85041942] = {
    id = 85041942,
    name = "我能清晰感觉到自己的感悟正在变多，如果继续变强，或许便能触摸到全新的领域。"
  },
  [85041943] = {
    id = 85041943,
    name = "并非每个问题都能找到答案，但拥有追寻未知的信念，才算得上真正的探险者。"
  },
  [85051941] = {
    id = 85051941,
    name = "我从小跟随父母修行，不管什么魔法很快就能掌握，算得上天才吧？可是完全比不上湄，她最初掌握的魔法全都是自己领悟的！"
  },
  [85051942] = {
    id = 85051942,
    name = "许多在地面难以做到的事在深渊中都成为了可能，不过想要尝试的话，得先确保自己能在这个凶险的世界中活下来。"
  },
  [85051943] = {
    id = 85051943,
    name = "其实我的研究并不怎么顺利，经常出现刚解决完一个问题，又马上诞生出更多问题的局面......探寻魔法根源这种事远比想象中更加困难。"
  },
  [85051944] = {
    id = 85051944,
    name = "最初我认为魔法只需要掌握就足够了，从未想过进一步了解，直到有一天我突然想了解它们的原理时，才发现自己竟然一无所知。"
  },
  [85051945] = {
    id = 85051945,
    name = "我还有很多做得不够好、考虑不够周全的地方，多亏了队长和大家的支持我才能走到这一步，未来的路，希望队长也能继续陪我走下去。"
  },
  [85061941] = {
    id = 85061941,
    name = "真是个验证魔法的好机会。"
  },
  [85071941] = {id = 85071941, name = "嘿咿！"},
  [85071942] = {id = 85071942, name = "咿呀。"},
  [85071943] = {id = 85071943, name = "哈~"},
  [85081941] = {
    id = 85081941,
    name = "好好看着吧！"
  },
  [85081942] = {
    id = 85081942,
    name = "试试这个~"
  },
  [85091941] = {
    id = 85091941,
    name = "看好了，这才是真正的魔法。"
  },
  [85091942] = {
    id = 85091942,
    name = "验证的时间该结束了~"
  },
  [85101941] = {id = 85101941, name = "呜哇~"},
  [85101942] = {id = 85101942, name = "呃啊。"},
  [85101943] = {id = 85101943, name = "唔呃。"},
  [85111941] = {
    id = 85111941,
    name = "竟然能突破我的魔法，好强——"
  },
  [85121941] = {
    id = 85121941,
    name = "大意了吗......明明只差一点了......"
  },
  [85131941] = {
    id = 85131941,
    name = "非常不错的战斗，又验证了我的一些想法~"
  },
  [85141941] = {
    id = 85141941,
    name = "呜啊，挑选错验证魔法的对手了，我们先撤吧，队长。"
  },
  [85151941] = {
    id = 85151941,
    name = "诶？！生日是今天吗？那必须要好好庆祝才行！我想想......嗯，我先去准备蛋糕，然后叫上大家一起庆祝，这样会更加热闹！"
  },
  [85161941] = {
    id = 85161941,
    name = "以前在家的时候，新年便是父母检验我修行成果的日子。我们会一起探讨还有哪些地方做得不够好，一起商量来年的修行计划......多亏了他们的指导，我才能一步步走到现在。"
  },
  [85171941] = {
    id = 85171941,
    name = "来到深渊也有不少时间了，可是研究方面的收获却非常有限，还好遇到了队长，也算是在别的方面赚了一些回来。"
  },
  [85181941] = {
    id = 85181941,
    name = "又到这样的节日了吗？去年我和岫一起去圈落中参加巡游收到了好多糖果，嘿嘿，今年一起去吧！"
  },
  [85191941] = {
    id = 85191941,
    name = "每到这个时候，真理之钥的大家都会把自己在修行、战斗中的感悟整理好，作为礼物彼此分享，对我们而言没有比这更棒的礼物了~"
  },
  [85012091] = {
    id = 85012091,
    name = "禁卫队、燧影，今日正式加入您的探险队。任何暗域和堕落者相关的事务都可以交给我，希望我们合作愉快。"
  },
  [85022091] = {
    id = 85022091,
    name = "探险队的行动计划比我想象中要详尽很多——想象中是怎样的？嗯......我一直觉得探险者都很随心所欲，所以行动计划应该会很粗略，甚至不存在。"
  },
  [85032091] = {
    id = 85032091,
    name = "禁卫队的职责是解决暗域和堕落者，在没有任务的时候我们可以自由活动，所以我才有机会加入探险队，体验探险者的生活。"
  },
  [85032092] = {
    id = 85032092,
    name = "最近有空的时候我都会翻看探险队的行动记录，从那些文字中我能感受到你们曾经的探险有多么精彩。我很庆幸能来到这里，希望我也有机会经历和这些记录一样精彩的探险。"
  },
  [85042091] = {
    id = 85042091,
    name = "感谢队长给予我的信任，不管面对怎样的对手，我都会全力以赴。"
  },
  [85042092] = {
    id = 85042092,
    name = "能拥有这样的力量，面对暗域和堕落者时，我一定可以表现得更加从容。"
  },
  [85042093] = {
    id = 85042093,
    name = "做个约定吧队长，今后的行动战略由您把控，战术则由我决断，如何？"
  },
  [85052091] = {
    id = 85052091,
    name = "你又感受到我的目光？抱歉，我只是习惯用观察的方式了解对方。在我看来你是怎样的人？这个嘛，总之不是坏人，其他的先保密。"
  },
  [85052092] = {
    id = 85052092,
    name = "队长最近指导我训练的次数越来越少了，是我的实力得到您的认可了吗，还是说太忙了？如果是第一种，我很开心，如果是太忙，请务必让我协助。"
  },
  [85052093] = {
    id = 85052093,
    name = "我平时看起来总是很严肃？其实我也注意到了这个问题，只是在这个危险环绕的深渊，我不知道该如何让自己放松下来。"
  },
  [85052094] = {
    id = 85052094,
    name = "禁卫队成员虽然都有共同目标，但偶尔也会发生争执，可是这个探险队中的人却都能和睦相处......能将这么多不同势力的人团结起来，队长的能力真的很不可思议。"
  },
  [85052095] = {
    id = 85052095,
    name = "和煦的风，温暖的茶，美味的点心，还有突然出现在身边、陪我享受这份安宁的队长......这样的氛围竟让我有一种“一直这样持续下去也不错”的感觉。"
  },
  [85062091] = {
    id = 85062091,
    name = "我明白自己的职责。"
  },
  [85072091] = {id = 85072091, name = "喝。"},
  [85072092] = {id = 85072092, name = "嘿。"},
  [85072093] = {id = 85072093, name = "呵啊。"},
  [85082091] = {
    id = 85082091,
    name = "百发百中。"
  },
  [85082092] = {
    id = 85082092,
    name = "锁定目标。"
  },
  [85092091] = {
    id = 85092091,
    name = "在这硝烟中消失吧。"
  },
  [85092092] = {
    id = 85092092,
    name = "铳声会吞噬所有罪恶。"
  },
  [85102091] = {id = 85102091, name = "唔呃。"},
  [85102092] = {id = 85102092, name = "呃啊。"},
  [85102093] = {id = 85102093, name = "呜啊。"},
  [85112091] = {
    id = 85112091,
    name = "糟糕，被发现了。"
  },
  [85122091] = {
    id = 85122091,
    name = "如果......能再冷静一点......"
  },
  [85132091] = {
    id = 85132091,
    name = "所有可疑对象都已解决完毕，我们继续赶路吧。"
  },
  [85142091] = {
    id = 85142091,
    name = "请保持秩序撤退，我会负责掩护。"
  },
  [85152091] = {
    id = 85152091,
    name = "按照禁卫队的习俗，生日这天会为过生日的人准备所有他想吃的美食，队长有什么想吃的吗？不管什么都可以，我会负责买单。"
  },
  [85162091] = {
    id = 85162091,
    name = "新年快乐队长，没想到今天也能和你一起度过，让我有些受宠若惊。我的新年愿望吗......如果可以，希望能与队长一起度过更多重要的节日。"
  },
  [85172091] = {
    id = 85172091,
    name = "我一直以为自己体验一段时间的探险者生活后就会放弃，可是队长却不断带给我新的体验，让我开始期待明天，期待下一次探险。遇到队长，果然是最幸运的事。"
  },
  [85182091] = {
    id = 85182091,
    name = "在禁卫队时，我很少有机会参加这样的庆典，所以庆典中的很多活动对我来说都非常新奇。队长今天有空吗？如果有空，能否陪我一起去逛逛？"
  },
  [85192091] = {
    id = 85192091,
    name = "我为探险队的大家准备了一些礼物，队长可以帮我派发一下吗？当然，作为答谢，我为队长准备了双份节日礼物。"
  },
  [85012101] = {
    id = 85012101,
    name = "探险者安瑞丝，兴趣是探险，特长是魔法。好了，自我介绍完毕，让我们商量一下今后的行动计划吧，队长。"
  },
  [85022101] = {
    id = 85022101,
    name = "最近这么忙碌，队长要再多休息一会儿吗？有我担任助手，队长就放心吧，不管是探险计划还是物资准备，我全都可以搞定！"
  },
  [85032101] = {
    id = 85032101,
    name = "加入探险队的感觉真不错，不仅有各种各样的探险委托，休息时还有队长陪我聊天，和之前一个人旅行的时候比起来，现在的生活简直是天堂。"
  },
  [85032102] = {
    id = 85032102,
    name = "我很早就明白一个道理，如果考虑太多，往往什么也做不好。所以我现在只要想到了就会马上去做——万一是错误地决定怎么办？错了就错了吧，任何成功都是无数错误的积累，对吧？"
  },
  [85042101] = {
    id = 85042101,
    name = "非常感谢队长对我的关照，这样的恩情，就让我用更出色的表现来报答吧。"
  },
  [85042102] = {
    id = 85042102,
    name = "队长竟然为我做到这种程度，真令人开心，可是也觉得有点压力，对我如此信任，我真的能回应您的期待吗？"
  },
  [85042103] = {
    id = 85042103,
    name = "决定了，今后我和队长就是最亲密的同伴，无论前路是风雨还是阳光，我们都要一起去闯荡。"
  },
  [85052101] = {
    id = 85052101,
    name = "以前一个人探险的时候，比起魔物，孤独才让我最难以忍受！有时候憋得太久，我甚至会和路边的花花草草说话。"
  },
  [85052102] = {
    id = 85052102,
    name = "我一直觉得魔法是可以被称作奇迹的存在，纵然有人使用魔法做了很多坏事，但我仍然坚信魔法是为这个世界带来美好的存在。"
  },
  [85052103] = {
    id = 85052103,
    name = "最初踏上旅途的时候，我其实还有些犹豫，直到见识了无数奇妙的景色，经历无数新奇的探险之后，我才坚定了作为探险者的决心。"
  },
  [85052104] = {
    id = 85052104,
    name = "对我来说，风险和未知并不是什么值得害怕的存在，每次克服风险，见识未知存在的时候，都会让我非常有成就感！"
  },
  [85052105] = {
    id = 85052105,
    name = "自从加入探险队以来，那种枯燥、孤独的感觉再也没有出现过......和信任的人一起探险果然很棒，不管有怎样的收获，也都会觉得满足。"
  },
  [85062101] = {
    id = 85062101,
    name = "准备好了，出发。"
  },
  [85072101] = {id = 85072101, name = "嘿咿！"},
  [85072102] = {id = 85072102, name = "呀啊。"},
  [85072103] = {id = 85072103, name = "呵啊。"},
  [85082101] = {
    id = 85082101,
    name = "要动真格咯。"
  },
  [85082102] = {
    id = 85082102,
    name = "尝尝这招！"
  },
  [85092101] = {
    id = 85092101,
    name = "见识一下我的全力吧！"
  },
  [85092102] = {
    id = 85092102,
    name = "我可不会手下留情。"
  },
  [85102101] = {id = 85102101, name = "呜哇。"},
  [85102102] = {id = 85102102, name = "呃啊。"},
  [85102103] = {id = 85102103, name = "咿呀。"},
  [85112101] = {
    id = 85112101,
    name = "好痛，真可恶啊！"
  },
  [85122101] = {
    id = 85122101,
    name = "旅途......到此为止了吗......"
  },
  [85132101] = {
    id = 85132101,
    name = "只要我和队长联手，这样的敌人根本不足为惧。"
  },
  [85142101] = {
    id = 85142101,
    name = "队长，情况好像有点不太妙啊，要不......我们先撤？"
  },
  [85152101] = {
    id = 85152101,
    name = "生日快乐队长！看，这是我为你准备的蛋糕，我给它起了一个名字——美妙旅途。希望队长今后的探险之旅，都能和这个蛋糕一样美好！"
  },
  [85162101] = {
    id = 85162101,
    name = "今天的工作我都处理好了，一起去享受新年庆典吧队长！听说今年圈落里来了不少表演杂技的，一定会非常热闹，我们快走吧。"
  },
  [85172101] = {
    id = 85172101,
    name = "这一路走来，队长是第一个不嫌我唠叨，甚至时常主动找我聊天的人。我非常开心能遇到队长，希望今后也能和队长一起，去见证我们旅途的终点。"
  },
  [85182101] = {
    id = 85182101,
    name = "每逢这样的节日，各地都会举办庆典，由于风俗差异，一些庆典会有很强的地方特色。不知道附近圈落的庆典是怎样的......一起去看看吧，队长。"
  },
  [85192101] = {
    id = 85192101,
    name = "队长，来看看我为你准备的这份节日礼物怎么样？......想要什么回礼？呵呵，对我来说最好的礼物就是和队长的相遇，所以我已经收到回礼了。"
  },
  [85011761] = {
    id = 85011761,
    name = "你好，我是自由学派的玛德莲，请多指教🎵——不像自由学派的人？难道你认为自由学派中都是那种穿着礼服的学者吗？"
  },
  [85021761] = {
    id = 85021761,
    name = "我之前参加茶会时听说过一个很神奇的地方，据说那里能看到绝对无法想象的景色，要不要一起去看看？"
  },
  [85031761] = {
    id = 85031761,
    name = "最初听说“自由学派”这个组织，我还以为成员都是迂腐古板的老学者呢，结果接触后才发现大家都是很好相处的探险者，每次参加茶会都能听大家讲不少有趣的秘闻。"
  },
  [85031762] = {
    id = 85031762,
    name = "有段时间没见到舒芙蕾了，难道她又发现了什么隐秘事件吗？如果是这样，下一次茶会又有新的故事可以听了！队长也觉得好奇？呵呵，那下次和我一起去参加吧。"
  },
  [85041761] = {
    id = 85041761,
    name = "有了这份力量，就能在深渊中追寻更多的秘闻了！"
  },
  [85041762] = {
    id = 85041762,
    name = "在战斗上我可不允许自己输给任何人，无论怎样强大的对手，我都会赢给你看！"
  },
  [85041763] = {
    id = 85041763,
    name = "所谓的超越极限，就是这种感觉吧？！哈哈哈，就由我带大家去揭示深渊中所有的秘密吧！"
  },
  [85051761] = {
    id = 85051761,
    name = "最初母亲传授我武技是希望消磨我的体力，让我能像普通女孩那样安静，可惜失算了，呵呵，对我而言修行武技可是件非常快乐的事！"
  },
  [85051762] = {
    id = 85051762,
    name = "我很早就跟随父母一起来深渊中历练，那些能通过战斗能解决的问题，没什么可以难倒我~"
  },
  [85051763] = {
    id = 85051763,
    name = "探险是一件非常有趣的事，可是欧培拉完全不会享受，每次看到她都是板着脸，如果她能稍微放松一点明明会更可爱~"
  },
  [85051764] = {
    id = 85051764,
    name = "比起所谓的财富和名望，我更想见识一下这个奇幻的世界，毕竟有些特别的经历是任何财富也无法换来的。"
  },
  [85051765] = {
    id = 85051765,
    name = "一边探索深渊一边享受战斗，这样的日子我非常喜欢！如果能一直这样持续下去，了解深渊的根源也是迟早的事。"
  },
  [85061761] = {
    id = 85061761,
    name = "我来开路，大家跟紧我。"
  },
  [85071761] = {id = 85071761, name = "喝啊！"},
  [85071762] = {id = 85071762, name = "哈！"},
  [85071763] = {id = 85071763, name = "嘿。"},
  [85081761] = {
    id = 85081761,
    name = "躲不掉的！"
  },
  [85081762] = {
    id = 85081762,
    name = "没机会啦~"
  },
  [85091761] = {
    id = 85091761,
    name = "战斗，可不仅仅只靠蛮力！"
  },
  [85091762] = {
    id = 85091762,
    name = "出其不意，才是获胜的诀窍！"
  },
  [85101761] = {id = 85101761, name = "呃啊！"},
  [85101762] = {id = 85101762, name = "呜啊。"},
  [85101763] = {id = 85101763, name = "唔呃。"},
  [85111761] = {
    id = 85111761,
    name = "只有这点程度吗。"
  },
  [85121761] = {
    id = 85121761,
    name = "只能......到这里了吗......"
  },
  [85131761] = {
    id = 85131761,
    name = "下个目的地在哪，让我们加速前进！"
  },
  [85141761] = {
    id = 85141761,
    name = "可恶！你们先撤，我绝不会放过这些家伙！"
  },
  [85151761] = {
    id = 85151761,
    name = "生日快乐队长！这种日子就该把所有琐事全都丢掉，找个地方好好庆祝一下！嗯，上次路过那个圈落里好像有不少好玩的，我们一起去看看！"
  },
  [85161761] = {
    id = 85161761,
    name = "每次新年的时候，自由学派都会准备一场盛大的茶会来庆祝。今年一起去吧，在那可以听到许多有趣的事噢，绝对不会让你后悔。"
  },
  [85171761] = {
    id = 85171761,
    name = "快来尝尝这个点心味道怎么样——还不错？呼~太好了！母亲虽然教了我不少做菜方法，但我基本都忘了，今天差点什么都做不出来......"
  },
  [85181761] = {
    id = 85181761,
    name = "这可是我们一家绝不会错过的节日，每年我都会和父母一起精心装扮参加节日庆典！今年有这么多同伴在一起庆祝，一定会超级热闹！"
  },
  [85191761] = {
    id = 85191761,
    name = "已经这个日子了吗？自由学派的同伴们准备的礼物也差不多要送过来了吧。这一天我们也有交换礼物的习惯，不知道今年谁会收到我送的“宝贝”。"
  },
  [85012111] = {
    id = 85012111,
    name = "没想到我们也会有并肩战斗的那天，命运还真是有趣啊。希望今后能相处愉快，队长。"
  },
  [85022111] = {
    id = 85022111,
    name = "让我们来看看今天的对手是谁——由我决定？呵呵，队长对我还真是信任啊，就不怕我惹出一些你收拾不了的烂摊子？"
  },
  [85032111] = {
    id = 85032111,
    name = "这探险队中有不少老熟人啊，希望曾经和我交手的经历没给她们落下心理阴影。当然，如果她们想找回场子，我也很乐意陪她们再玩玩。"
  },
  [85032112] = {
    id = 85032112,
    name = "最近雪莉的状态看起来很不错，看来答应她加入这个探险队是个明智的决定——谢谢夸奖？呵呵，没错，就是对你的夸奖，既然你这么厉害，也陪我热热身，让我也开心一下吧。"
  },
  [85032113] = {
    id = 85032113,
    name = "难得休息，要陪我玩玩吗？呵呵，别那么紧张，我又没说陪我玩就一定是战斗。比如就这样聊聊天，享受下这久违的安宁也很愉悦吧？或者说，你有什么更好的建议？"
  },
  [85042111] = {
    id = 85042111,
    name = "呵呵呵，想要我发挥全力，这种程度、还远远不够。"
  },
  [85042112] = {
    id = 85042112,
    name = "真是令人愉悦的感觉，我已经忍不住想要大闹一场了，为我准备些合适的对手吧，队长。"
  },
  [85042113] = {
    id = 85042113,
    name = "做好觉悟了吗队长，当我展现全力的时候，想要驾驭我这柄剑可没那么容易。"
  },
  [85052111] = {
    id = 85052111,
    name = "自从来到这，探险的乐趣我还没感觉到，但战斗方面我很满意。一场又一场的战斗，毫无顾忌的厮杀......这种感觉实在太棒了。"
  },
  [85052112] = {
    id = 85052112,
    name = "论谋略我确实比不上你和高塔的那些人，所以我很清楚自己的定位，一柄利剑，一柄可以消灭一切敌人，也可能反噬使用者的利剑。"
  },
  [85052113] = {
    id = 85052113,
    name = "尤娜那家伙很吵吧？不管何时她都喜欢说个不停，遇到事情也很容易慌乱......可是一段时间不听她吵闹，就会觉得有些不习惯。"
  },
  [85052114] = {
    id = 85052114,
    name = "探险者的生活倒也没有想象中那么无聊，各种各样的战斗，新奇古怪的宝物......这段时间，似乎有点理解你所说的“探险的乐趣”了。"
  },
  [85052115] = {
    id = 85052115,
    name = "今后就将享受战斗、享受探险作为目标吧。准备怎么实现？呵呵，那不是应该由你这位执掌利剑的人来考虑吗？"
  },
  [85062111] = {
    id = 85062111,
    name = "希望这次的对手能让我满意。"
  },
  [85072111] = {id = 85072111, name = "喝。"},
  [85072112] = {id = 85072112, name = "哈啊！"},
  [85072113] = {id = 85072113, name = "嘿！"},
  [85082111] = {
    id = 85082111,
    name = "别死得太快了。"
  },
  [85082112] = {
    id = 85082112,
    name = "尽情挣扎吧。"
  },
  [85092111] = {
    id = 85092111,
    name = "真正的好戏现在才开始！"
  },
  [85092112] = {
    id = 85092112,
    name = "一起玩个尽兴吧！"
  },
  [85092113] = {
    id = 85092113,
    name = "去地狱为我探路吧！"
  },
  [85102111] = {id = 85102111, name = "呃。"},
  [85102112] = {id = 85102112, name = "唔"},
  [85102113] = {
    id = 85102113,
    name = "。呃啊。"
  },
  [85112111] = {
    id = 85112111,
    name = "有趣，再来！"
  },
  [85122111] = {
    id = 85122111,
    name = "怎么......可能......"
  },
  [85132111] = {
    id = 85132111,
    name = "真是过瘾，快去下一个地方吧，我还要更多的战斗！"
  },
  [85142111] = {
    id = 85142111,
    name = "好好活着吧，你们的小命，下次我会亲自来取。"
  },
  [85152111] = {
    id = 85152111,
    name = "生日？我并不觉得这种日子有多么特别，不过雪莉倒是很在意......走吧，我带你去好好享受一番，用雪莉给我们庆祝生日的方式。"
  },
  [85162111] = {
    id = 85162111,
    name = "每个新年，雪莉都会要求我整理今年的计划，这种事真的有必要吗？......算了，还是整理一下吧，免得又被她念叨。队长也可以整理一下，她喜欢有计划的人。"
  },
  [85172111] = {
    id = 85172111,
    name = "你手里的点心是给我的吗？礼物？原来又到这种日子了啊，我虽然不在意，但也听说过这种节日习俗。你那是什么眼神，难道还在期待我送你？呵呵，点心我可不会做，倒是可以陪你玩玩。"
  },
  [85182111] = {
    id = 85182111,
    name = "明明都惧怕着幽灵鬼怪，却又在这种节日扮演幽灵鬼怪，所以说人类是真的很有趣啊。我？我自然不怕，不管是幽灵还是邪魔，都逃不过我的剑。"
  },
  [85192111] = {
    id = 85192111,
    name = "这是给我的礼物？呵呵，你虽然很特别，但过节时也和普通人没什么两样，那我也扮演一下普通人吧。想要什么回礼，尽管开口吧。"
  },
  [85012121] = {
    id = 85012121,
    name = "您就是谢利所说的队长吗？非常感谢您对她的关照，您对我们的恩情，就让我这个无用之人，用余生回报吧。"
  },
  [85022121] = {
    id = 85022121,
    name = "辛苦了队长，探险队后勤的这些琐事都交给我吧。您的职责是引领探险队前行，有时间的时候应该多休息一下。"
  },
  [85032121] = {
    id = 85032121,
    name = "我从没想过有一天能加入探险队和大家一起探险，感受最纯粹的探险者生活，也更加无法想象，深渊中竟然真的存在氛围如此融洽的探险队。"
  },
  [85032122] = {
    id = 85032122,
    name = "尤娜虽然有些贪玩，但是个很可靠的孩子。这些年多亏她陪在谢利身边，谢利才没那么辛苦，更重要的是无论遇到怎样的情况都能保持清醒，坚守我们之间的约定。"
  },
  [85042121] = {
    id = 85042121,
    name = "对我这样的无用之人如此关照，我该如何回应队长的信任呢？"
  },
  [85042122] = {
    id = 85042122,
    name = "我会珍惜队长给予我的这份力量，只要有我能做到的事，请尽管吩咐。"
  },
  [85042123] = {
    id = 85042123,
    name = "从队长这里获得的支持远比想象中更多......请注视着我吧，队长，今后我将为您献上我的所有。"
  },
  [85052121] = {
    id = 85052121,
    name = "离开深渊久了，很多事我都已经陌生，谢谢队长能给我适应的时间和机会，我会全力以赴，不辜负您的期望。"
  },
  [85052122] = {
    id = 85052122,
    name = "比起战斗，我更喜欢为探险整理队文件，调配物资之类的工作。当然，需要战斗的时候，我也一定会竭尽全力。"
  },
  [85052123] = {
    id = 85052123,
    name = "这些年谢利一直在为了我的事奔走，被高塔利用......她虽然从来不在我面前说那些事，但我知道她的辛苦和忍耐。为了她，今后我会努力振作，让她可以去追寻自己的人生。"
  },
  [85052124] = {
    id = 85052124,
    name = "多亏了队长的关照，最近无论是探险还是修行都非常顺利，让我似乎又找到了以前刚踏足深渊时，对一切都充满期待的感觉。"
  },
  [85052125] = {
    id = 85052125,
    name = "这种纯粹的探险，让我这个无用之人也对未来有了更多憧憬，队长，能请您今后也与我同行吗？有您在身边，未来才会更让人期待。"
  },
  [85062121] = {
    id = 85062121,
    name = "请交给我吧，队长。"
  },
  [85072121] = {id = 85072121, name = "呵啊。"},
  [85072122] = {id = 85072122, name = "咿呀。"},
  [85072123] = {id = 85072123, name = "嘿咿。"},
  [85082121] = {
    id = 85082121,
    name = "湮灭吧。"
  },
  [85082122] = {
    id = 85082122,
    name = "逃不掉的。"
  },
  [85092121] = {
    id = 85092121,
    name = "安息吧，马上就能结束。"
  },
  [85092122] = {
    id = 85092122,
    name = "万物，都将归于尘埃。"
  },
  [85102121] = {id = 85102121, name = "唔呃。"},
  [85102122] = {id = 85102122, name = "呃啊。"},
  [85102123] = {id = 85102123, name = "呜啊。"},
  [85112121] = {
    id = 85112121,
    name = "无碍，我还可以继续。"
  },
  [85122121] = {
    id = 85122121,
    name = "该说......再见了吗......"
  },
  [85132121] = {
    id = 85132121,
    name = "真是一场完美的战斗，再一次让我感受到了队长的指挥艺术。"
  },
  [85142121] = {
    id = 85142121,
    name = "队长，你带领大家先撤，我来负责善后。"
  },
  [85152121] = {
    id = 85152121,
    name = "生日快乐队长，今天准备怎么庆祝呢？不用这么在意？不行，这样重要的日子绝不可以轻视，就由我来为队长筹备庆祝会吧。"
  },
  [85162121] = {
    id = 85162121,
    name = "自从加入探险队，生活变得越来越充实，对新的一年也有了更多期待。新的一年队长有什么打算吗？想先听听我的？呵呵，我想做的事很多，需要队长花一些时间聆听了。"
  },
  [85172121] = {
    id = 85172121,
    name = "队长来试试这份点心吧。很久没做过了，手艺生疏了很多——很不错？那真是太好了，我只给谢利她们做过，还一直在担心是否符合您的口味。"
  },
  [85182121] = {
    id = 85182121,
    name = "谢利小时候很喜欢这种节日，每次参加巡游回来都会滔滔不绝地和我说那些庆典上的事。可是自从她懂事之后，就再也没有参加过这些庆典了。"
  },
  [85192121] = {
    id = 85192121,
    name = "一整天都在忙着给探险队成员分发礼物，辛苦队长了。给，这是给努力工作的队长的慰问，也是给最信任的同伴的礼物。都是我亲手做的一些物件，希望队长能喜欢。"
  },
  [85012131] = {
    id = 85012131,
    name = "还记得我吗队长？嘿嘿，这次加入你的探险队，老大也同意了噢，以后我们就能一起玩啦！"
  },
  [85022131] = {
    id = 85022131,
    name = "队长今天我们去哪玩呢？欸，又要去探险？那种事交给老大去做就行了吧？反正我们去也是拖后腿，不如一起去圈落玩。"
  },
  [85032131] = {
    id = 85032131,
    name = "听说圈落中最近流行一种魔物竞速活动，就是一群魔物赛跑，然后观众在旁边押注。可惜老大不允许我去观看，不然以我的阅历，说不定能从里面大赚一笔。"
  },
  [85032132] = {
    id = 85032132,
    name = "老大看起来是很凶啦，一副谁也不放在眼里的感觉，但她其实很在意身边的人，很看重同伴！而且在雪莉大人面前，她表现得比我还乖呢。"
  },
  [85042131] = {
    id = 85042131,
    name = "这种获得力量的感觉太棒了，队长，能让我多感受几次吗？"
  },
  [85042132] = {
    id = 85042132,
    name = "如果能一直这样成长下去，说不定有一天，我也能拥有老大那样的实力。"
  },
  [85042133] = {
    id = 85042133,
    name = "我感觉现在的自己强得可怕，呵呵，下次遇到麻烦让我先上吧，我会将敌人全都打飞！"
  },
  [85052131] = {
    id = 85052131,
    name = "探险者的生活比在高塔时自由多了，那时候虽然有老大罩着，但我也只是比其他人稍微自由一点，和现在这样的日子完全没得比。"
  },
  [85052132] = {
    id = 85052132,
    name = "以前跟在老大身边时，我见识过她和各种各样的敌人战斗，所以我对许多魔物的弱点都一清二楚，有麻烦尽管交给我就行！"
  },
  [85052133] = {
    id = 85052133,
    name = "雪莉大人平时都非常的谦虚、温柔，但教育我们时也会显露出严肃的一面。所以我们会尽量不惹她生气，不然会被说教很久。"
  },
  [85052134] = {
    id = 85052134,
    name = "处理不完的委托，讨伐不完的魔物，最近感觉好忙啊！不过竟然不觉得累，也不觉得无聊......奇怪，难道是因为和大家一起的原因吗？"
  },
  [85052135] = {
    id = 85052135,
    name = "以我现在这样的进步速度，想要超越老大很难啦，除非有什么奇迹......说到奇迹，和队长在一起的时候我就觉得自己什么都能做到，这算是奇迹吗？"
  },
  [85062131] = {
    id = 85062131,
    name = "这种事应该交给老大吧？"
  },
  [85072131] = {id = 85072131, name = "呵啊！"},
  [85072132] = {id = 85072132, name = "哈！"},
  [85072133] = {id = 85072133, name = "嘿呀。"},
  [85082131] = {id = 85082131, name = "看招！"},
  [85082132] = {
    id = 85082132,
    name = "饶不了你！"
  },
  [85092131] = {
    id = 85092131,
    name = "见识一下我的全力吧！"
  },
  [85092132] = {
    id = 85092132,
    name = "就由我来结束一切！"
  },
  [85102131] = {id = 85102131, name = "呀。"},
  [85102132] = {id = 85102132, name = "呜哇。"},
  [85102133] = {id = 85102133, name = "呃啊。"},
  [85112131] = {
    id = 85112131,
    name = "好痛啊，饶不了你！"
  },
  [85122131] = {
    id = 85122131,
    name = "可恶......就差一点......"
  },
  [85132131] = {
    id = 85132131,
    name = "我们的配合真默契，今天的晚饭就由队长请客咯！"
  },
  [85142131] = {
    id = 85142131,
    name = "呜哇，惹到了好惹的家伙，我们快跑吧队长！"
  },
  [85152131] = {
    id = 85152131,
    name = "队长，生日快乐！我们过生日时，雪莉大人都会给我们准备庆祝会，所以今天我们也给队长准备了庆祝会，快把工作放下，一起去参加吧！"
  },
  [85162131] = {
    id = 85162131,
    name = "新年快乐队长！来看看我的新年计划怎么样？——都很不错？！嘿嘿，自从加入探险队后，我想做的事就越来越多，感觉这份计划书根本不够写！"
  },
  [85172131] = {
    id = 85172131,
    name = "欸，这种节日要赠送点心代表心意吗？我不会做啊，以前都是雪莉大人做给我们吃的......要不我把我的武器送给你吧，反正我们一直在一起，我需要的时候你再给我就行。"
  },
  [85182131] = {
    id = 85182131,
    name = "高塔并不禁止大家举办节日庆典，但大家出于对大人物们的畏惧，也不敢私自举办。直到老大出现后，她告诉我们想怎么做就怎么做，高塔中才开始有了这种节日的庆典。"
  },
  [85192131] = {
    id = 85192131,
    name = "队长，快来拆礼物咯~雪莉大人已经把我们的礼物送来了，队长的就在边上——对，最大的那个！队长快打开看看吧。"
  },
