  [86407001] = {
    id = 86407001,
    name = "公会情报部突然找到了你，让你帮忙寻找他们消失的调查员，这与一个神秘的村庄有关。"
  },
  [86407002] = {
    id = 86407002,
    name = "你找到公会情报屋时，竟然遇到了侦探马尔可，她也在打听村庄的秘密。"
  },
  [86407003] = {
    id = 86407003,
    name = "你和马尔可伪装进入村庄，开始调查事件，打听到三年前曾有探险者来，但那名探险者最后失踪了，你忽然想起了同样发生在三年前的事件。"
  },
  [86407004] = {
    id = 86407004,
    name = "你与马尔可到达那名英雄曾经战斗的地方，发现了一把光辉之剑，而这把剑竟然在原地铸就了一方魔法阵。"
  },
  [86407005] = {
    id = 86407005,
    name = "你们到圈落发现了更多的失踪者，但大多数人认为是魔物所为。"
  },
  [86407006] = {
    id = 86407006,
    name = "进入山林里，马尔可找错了路，你们不得不面对一个大麻烦。"
  },
  [86407007] = {
    id = 86407007,
    name = "逃到战场遗址处时，魔物忽然退去了，原来这个魔法阵仍然在运作，并囊括了整个村庄，你忽然窥得了某些真相。"
  },
  [86407008] = {
    id = 86407008,
    name = "你们暗中村庄调查，发现了与村庄神秘交易的黑衣人，你与马尔可分头行动，回来时却发现马尔可失踪了。"
  },
  [86407009] = {
    id = 86407009,
    name = "你在后山山顶发现大量的尸骨及祭台，也找到了被抓的马尔可，这时村民启动了魔法阵。"
  },
  [86407010] = {
    id = 86407010,
    name = "魔物闯入村庄，村民变回了劫匪，你和马尔可隔岸观火，看着那群恶人自食其果。"
  },
  [86420001] = {
    id = 86420001,
    name = "一个神秘的黑衣人找到你，想跟你卖点消息。"
  },
  [86420002] = {
    id = 86420002,
    name = "金发女孩莱娜在据点挑战“长得好看的家伙”，你被她看到后，成了下一个挑战的对象，但她似乎有其他目的。"
  },
  [86420003] = {
    id = 86420003,
    name = "你与莱娜去山洞取她藏起来的宝图，发现莱娜与众不同的战斗方式。"
  },
  [86420004] = {
    id = 86420004,
    name = "你们根据线索到达废弃的据点，在魔物战斗后发现一具尸体，这时莱娜要求你去搜尸。"
  },
  [86420005] = {
    id = 86420005,
    name = "你们去往河边一无所获，你察觉藏宝图路线的不同，似乎是走错了。"
  },
  [86420006] = {
    id = 86420006,
    name = "你们穿越山坳时，碰到一队探险者，而这队探险者竟然是伪装的劫匪。"
  },
  [86420007] = {
    id = 86420007,
    name = "你与莱娜终于到了藏宝图指示的地点，在战胜魔物后，发现了宝物竟然。"
  },
  [86420008] = {
    id = 86420008,
    name = "你们成功逃出山谷，莱娜与你约定下一次同行。"
  },
  [86446001] = {
    id = 86446001,
    name = "你在魔物手中救下酷似探险者的少年埃拉，埃拉的神色却很慌忙，在跟踪他后，竟然发现了还有一个人。"
  },
  [86446002] = {
    id = 86446002,
    name = "埃拉偷偷进入一个地方消失了，而少女紧跟进入，你打算也进去看看。"
  },
  [86446003] = {
    id = 86446003,
    name = "你进入一个叫西默蒂瑞的村庄，这里与世隔绝，从未受到魔物侵扰，引得岫接连感叹，但这里的人似乎并不欢迎外来人。"
  },
  [86446004] = {
    id = 86446004,
    name = "原来岫一直在寻找世外桃源，在感叹西默蒂瑞美好的时刻，有孩童出现，让你与岫去山里找埃拉，但无意中你们发现了村庄的重大秘密。"
  },
  [86446005] = {
    id = 86446005,
    name = "你与岫在神殿找到了埃拉，原来多年前村庄发生了意外，关闭了于外界的通道，同时时间停滞了，村民们不老不死，但埃拉觉得这是一种病。"
  },
  [86446006] = {
    id = 86446006,
    name = "村长在山脚下等你们，告诉了你们异常残酷的真相，而埃拉认为村民有权知道这样的真相。"
  },
  [86446007] = {
    id = 86446007,
    name = "你们找到医师询问如何治疗病症，医师索要大量欧泊，埃拉送上了全部的积蓄。"
  },
  [86446008] = {
    id = 86446008,
    name = "进入黑森林后，你发现有人跟踪你们，但并没有找到人。"
  },
  [86446009] = {
    id = 86446009,
    name = "你们回到村庄，村民们已得知了真相，埃拉将药物交给了村长，村长率先做出了选择，但也有村民不愿意改变现状，认为一切是神的恩赐，一场争议在所难免。"
  },
  [86446010] = {
    id = 86446010,
    name = "你们快速赶赴祭坛，原来黑衣人追源晶意外发现了光阴沙漏，在双方争抢过程中，沙漏出现了破损，所有人都即将面临最后的抉择。"
  },
  [86446011] = {
    id = 86446011,
    name = "埃拉最终选择离开了西默蒂瑞，他感谢你们，去追求新的梦想，岫也对更多的未知心生向往。"
  },
  [86416001] = {
    id = 86416001,
    name = "你从魔物手里救下了一名商人，他告诉你前方据点发生了抢劫和袭击事件，劝你绕道而行。"
  },
  [86416002] = {
    id = 86416002,
    name = "你遇到一名浑身是血的女人正要对小女孩下手，赶走她后才发现是一场误会。"
  },
  [86416003] = {
    id = 86416003,
    name = "来到据点后，你听到路人讨论嚣张的劫匪，夜晚休息时听到外面有人战斗，于是追了出去。"
  },
  [86416004] = {
    id = 86416004,
    name = "你跟着人影追出据点，发现白衣女人在战斗中陷入困境，于是帮助她击退了黑衣人，并得知了她的名字......"
  },
  [86416005] = {
    id = 86416005,
    name = "你与薇一同帮助据点击退了魔物，而因为魔物袭击据点，薇而担心她的朋友海伦，你决定与薇一起去看看。"
  },
  [86416006] = {
    id = 86416006,
    name = "你们赶到海伦藏身点小木屋，发现海伦失踪了，木屋一片狼藉......"
  },
  [86416007] = {
    id = 86416007,
    name = "你们根据线索到了山林，救下一名正在被黑衣人袭击的探险者，而探险者被追杀是因为目睹一群黑衣人抓了一个女孩......"
  },
  [86416008] = {
    id = 86416008,
    name = "你们在河谷追上黑衣人救下了被绑的女孩，可惜不是海伦，于是开始逼问黑衣人......"
  },
  [86416009] = {
    id = 86416009,
    name = "你们到达了黑衣人的巢穴，却被黑衣人组织发现了，危难之际，薇做出了一个大胆的决定......"
  },
  [86416010] = {
    id = 86416010,
    name = "被薇转移后，你抓了个黑衣人，质问他们的目的，并想办法营救薇与海伦......"
  },
  [86416011] = {
    id = 86416011,
    name = "你听见路人讨论附近魔物蠢蠢欲动，威胁到附近据点，决定去森林探查情况......"
  },
  [86416012] = {
    id = 86416012,
    name = "你到山上，打算将魔物引到黑衣人的巢穴......"
  },
  [86416013] = {
    id = 86416013,
    name = "魔物冲入了据点，你趁乱将薇和海伦一起救了出来......"
  },
  [86416014] = {
    id = 86416014,
    name = "三人返回小屋，双方相互感谢，薇准备带走海伦寻找治疗她的办法。"
  },
  [86427001] = {
    id = 86427001,
    name = "一个受伤的人向你求助，得知对方竟然是从地下决斗场逃出来的......"
  },
  [86427002] = {
    id = 86427002,
    name = "你将受伤的人送到圈落，公会的人找到了你，请求你的协助调查地下决斗场......"
  },
  [86427003] = {
    id = 86427003,
    name = "你在地下决斗场遇到了一名赌徒，他告诉了你许多规矩，而这时，赌徒压中的参赛者姬玛出场了......"
  },
  [86427004] = {
    id = 86427004,
    name = "你向姬玛询问关于药物的事，得知她只是来此寻人。而这时，从决斗场逃出来的人被抓了回去，且被灌下了某种吸引浊炁的药物......"
  },
  [86427005] = {
    id = 86427005,
    name = "姬玛带你回据点并提供了情报，同时也让你帮他一起打听西比尔的事情，你们决定过几日后再次前往决斗场......"
  },
  [86427006] = {
    id = 86427006,
    name = "你们发现地下决斗场已经关闭，探查后发现了仍有留守人，在你们的逼问下，得知了一些线索......"
  },
  [86427007] = {
    id = 86427007,
    name = "你们根据线索见到了两名黑衣人，悄悄跟上后打晕了两人，并救出了他们绑架的人，知道了新的决斗场地点。"
  },
  [86427008] = {
    id = 86427008,
    name = "你们走入山腹中，发现了更加残忍的死斗场，而曾经和姬玛对战的比斗者也在，并以饮下药剂的方式获胜了，你们在决斗比赛高潮时溜入后台，找到了幕后老板......"
  },
  [86427009] = {
    id = 86427009,
    name = "你们挟持老板逃离了现场后，姬玛也从他嘴里知道了西比尔的下落，老板并没有否认想把西比尔也制成堕落者的想法，遭到姬玛的暴打......"
  },
  [86431001] = {
    id = 86431001,
    name = "你在路上突然遭遇埋伏，而这群埋伏的人发现攻击的对象好像不该是你......"
  },
  [86431002] = {
    id = 86431002,
    name = "雨中，你再次碰到那群黑衣人，而他们正在欺负一个女孩......"
  },
  [86431003] = {
    id = 86431003,
    name = "你与辉夜到黑衣人提供的位置，但黑衣人组织已人去楼空......"
  },
  [86431004] = {
    id = 86431004,
    name = "两人到了贫民窟，却发现了黑衣人组织造成的惨状，这时驻守在贫民窟的黑衣人回来了......"
  },
  [86431005] = {
    id = 86431005,
    name = "你们在山林追丢了黑衣人，发现那些魔物受某讯号控制着，而魔物也开始听从讯号袭击你们......"
  },
  [86431006] = {
    id = 86431006,
    name = "辉夜为收集情报，带你到深渊航线的临时歇脚处休息，在这里，你了解了辉夜做这份工作的原因......"
  },
  [86431007] = {
    id = 86431007,
    name = "你们在山谷遭到黑衣组织的包围和绝杀，黑衣人头目竟然献祭了队员，想和辉夜同归于尽，而你也陷入了困境......"
  },
  [86431008] = {
    id = 86431008,
    name = "你们失去了黑衣人头目的踪影，在途中碰到公会成员，他说看到了一个非常危险的人......"
  },
  [86431009] = {
    id = 86431009,
    name = "黑衣人被你们打败后变成了堕落者，你与辉夜只能将其击杀......"
  },
  [86470001] = {
    id = 86470001,
    name = "在野外，尼莉莎看到咕咕，大家都跟着咕咕追了上去......"
  },
  [86470002] = {
    id = 86470002,
    name = "你们追着小魔物到一处结界包围的山谷里，这里看起来一直有人居住，小魔物一口吃掉了屋顶的魔法石逃走了......"
  },
  [86470003] = {
    id = 86470003,
    name = "你和尼莉莎、少女一起去了圈落，寻找材料却一无所获，这时少女突然想起......"
  },
  [86470004] = {
    id = 86470004,
    name = "你们去往废弃的矿场，发现矿场已经坍塌了......"
  },
  [86470005] = {
    id = 86470005,
    name = "你和伊涅利丝将材料运送到山谷后，大家合力重铸木屋，伊涅利丝也说起了一些往事......"
  },
  [86470006] = {
    id = 86470006,
    name = "众人决定去圈落筹备物资，你看到花种，跟几人商量后，决定去买花种......"
  },
  [86470007] = {
    id = 86470007,
    name = "你们几人去往森林采集花种，合力杀掉魔物，采集种子后，却发生了意外......"
  },
  [86470008] = {
    id = 86470008,
    name = "你们回到山谷，用药剂溶解了黏液，开始布置剩下的装饰，在空地上种下了花种......"
  },
  [86461001] = {
    id = 86461001,
    name = "你正打算去和同伴们汇合，在路上遇到村民呼救，有魔物破坏他们的农作物，你随即前往，村民继续找人求救。"
  },
  [86461002] = {
    id = 86461002,
    name = "你来到村落和村民一起抵抗魔物，僵持之际遇到黑羽相助，击退魔物后，你和黑羽打算帮村民修复损毁的防御设施"
  },
  [86461003] = {
    id = 86461003,
    name = "你与村民一同来到附近森林获取材料，在获取材料时遇到魔物，与村民们配合解决了危机。"
  },
  [86461004] = {
    id = 86461004,
    name = "返回村庄后，你与黑羽说话期间，魔物再次来袭，你与黑羽展现出了相当高的默契，面对大批魔物，你们陷入困境时，同伴们出现了......"
  },
  [86461005] = {
    id = 86461005,
    name = "众人和村民来到山谷，发现很多魔物聚集，打算返回村庄再做打算，村民不小心被魔物发现，你为了救人，被迫与他人分散。"
  },
  [86461006] = {
    id = 86461006,
    name = "你与村民躲入山洞，却见到了巨型魔物，面对魔物的穷追不舍，你带着村民苦苦鏖战，正当村民绝望的时候，黑羽找到了你。"
  },
  [86461007] = {
    id = 86461007,
    name = "村民为了报答你和黑羽开了一场晚会，得知附近圈落准备举办收获祭，黑羽邀请你一起参加。"
  },
  [86432001] = {
    id = 86432001,
    name = "一个公会的人濒死前跑向你，朝你求救，你发现这人已经浊炁侵蚀了......"
  },
  [86432002] = {
    id = 86432002,
    name = "你在前往据点的路上遇到了白鸢，她以骑士的身份劝你这个普通探险者不要去据点，你提出帮忙后，却被她拒绝，这时出现了“变异”的魔物......"
  },
  [86432003] = {
    id = 86432003,
    name = "你和白鸢路过发现一个刚搭起不久的临时营地，原来营地中都是白鸢家族的人，而那个爆炸的据点是白鸢家族长居的据点，人们知道白鸢是来救他们的，给白鸢提了很多无理的要求。"
  },
  [86432004] = {
    id = 86432004,
    name = "在做好防护措施后，你与白鸢进入了据点，根据线索找到了爆炸发生地，这时有一只行动迅速的堕落者出现了。"
  },
  [86432005] = {
    id = 86432005,
    name = "你与白鸢回到临时营地，告诉大家据点有堕落者，据点短时间内不适合生活，众人迷茫无助，让白鸢帮忙解决问题。"
  },
  [86432006] = {
    id = 86432006,
    name = "你们再次到达据点，在那片炸碎的房屋附近寻找线索，发现这个地方是据点管理的办事处，这时堕落者再次出现，阻止你们靠近......"
  },
  [86432007] = {
    id = 86432007,
    name = "你带着白鸢来到山洞，听白鸢断断续续的喊祖父，发现她神志不清，竟然受到了盒子中的东西影响......"
  },
  [86432008] = {
    id = 86432008,
    name = "你们回到临时营地后，据点负责人向白鸢索要盒子，被白鸢拒绝。"
  },
  [86432009] = {
    id = 86432009,
    name = "白鸢对负责人所说的话产生了迷茫，你细心安慰后，她对人生的方向有所明悟。"
  },
  [86432010] = {
    id = 86432010,
    name = "你悄悄找到据点负责人，从他的嘴里撬出了关于黑衣人的消息，但负责人所知甚少，最后不了了之。"
  },
  [86455001] = {
    id = 86455001,
    name = "你在途中帮人脱困，那人告诉你他正打算采集材料，制作庆典所用的天灯。"
  },
  [86455002] = {
    id = 86455002,
    name = "你在途中遇到一女子沐浴，正打算悄悄离开之际，突然杀出两人袭击女子......"
  },
  [86455003] = {
    id = 86455003,
    name = "鬼魅带你去山里，让你帮忙采集一些驱散魔物的药草，在赶走魔物摘取药草时，突然有其他人出现抢夺药草......"
  },
  [86455004] = {
    id = 86455004,
    name = "鬼魅告诉你埃兰据点每年都会为祭祀牺牲女孩献祭宝物，护佑据点平安，而宝物里实际束缚了一只魔物。"
  },
  [86455005] = {
    id = 86455005,
    name = "你和鬼魅来到据点后，一路听到了很多人对鬼魅的误解，鬼魅并不在意，打算与你一明一暗分开寻找线索。"
  },
  [86455006] = {
    id = 86455006,
    name = "鬼魅找了偏僻的地方准备放出魔物，打开时发现神石是假的，鬼魅中了迷雾，祭司带人包围了你们。"
  },
  [86455007] = {
    id = 86455007,
    name = "你带着鬼魅在湖边休息，鬼魅恢复后感谢你的相助，但却决定与你分道扬镳......"
  },
  [86455008] = {
    id = 86455008,
    name = "你们伪装回到据点，找机会把矿石粉末放进火石里，等待祭祀的开始......"
  },
  [86455009] = {
    id = 86455009,
    name = "你和鬼魅离开了据点，忽然想送给她一件礼物......"
  },
  [86480001] = {
    id = 86480001,
    name = "你们找了宛如镜子的宝物，鬼侍希望你们将宝物卖给她，而在此时，异变突生......"
  },
  [86480002] = {
    id = 86480002,
    name = "你醒来后发现自己成为了普尔兰伯爵的继承人，脑中也混进一段奇怪的记忆，树下的小女孩叫你哥哥，让你去筹备宴会......"
  },
  [86480003] = {
    id = 86480003,
    name = "你和柯莱特尔一起回家筹备宴会，她趁你忙的时候跑不见了，就在你忙得晕头转向的时候，耳边传来了妹妹的呼救声......"
  },
  [86480004] = {
    id = 86480004,
    name = "柯莱特尔偷跑出去给家人准备礼物，不敢让父母知道。你找到她回家后，一起挨了父亲的训斥，在半夜睡觉的时候，你又听到了她的声音。"
  },
  [86480005] = {
    id = 86480005,
    name = "次日，你处理事务时，查到仇家会在宴会有动作。加强了布防之后，柯莱特尔邀你一起喝下午茶，一个小小的恶作剧随之“扑面而来”......"
  },
  [86480006] = {
    id = 86480006,
    name = "宴会开始后，仇家果然找上了门，在你的布局下，完美解决了这次危机，却在这时，听见了柯莱特尔的求救声......"
  },
  [86480007] = {
    id = 86480007,
    name = "你一路不断和柯莱特尔聊天，在诛杀背叛者后，将柯莱特尔救了出来，而这时，梦境出现了支离的迹象......"
  },
  [86480008] = {
    id = 86480008,
    name = "破碎的镜子导致你和鬼侍昏睡后，同伴们来找维克多大师求救，维克多大师的首徒弗拉克愿意出手相助，将你和鬼侍救醒，前提是完成他的要求。"
  },
  [86469001] = {
    id = 86469001,
    name = "扎营休息时，你和菲尼斯外出采集材料，遇到一群黑衣人抢劫了商队，你让菲尼斯通知团队，自己一路跟踪黑衣人，观察到商队中有一个少女，和其他受害者不同......"
  },
  [86469002] = {
    id = 86469002,
    name = "黑衣人将人交到头目手中，并把他们用魔法束缚起来，莉亚暗中解除控制跟踪突然离开的黑衣人头目，你在确保了商队暂时安全后，决定跟上去一探究竟。"
  },
  [86469003] = {
    id = 86469003,
    name = "莉亚跟踪黑衣人头目到了森林的营地，营地看管严密，莉亚打算进入查探，却被黑衣人发现了踪迹，你出手帮忙掩护，两人快速逃走。"
  },
  [86469004] = {
    id = 86469004,
    name = "莉亚解除了魔法束缚后，打算重返神秘营地，原来她不光要救商队，还要知道黑衣人的阴谋，因为在运送途中弄，她听到了堕落者的字眼，你决定帮她一起调查。"
  },
  [86469005] = {
    id = 86469005,
    name = "你们回到森林后，制定了战斗方案，两人配合伪装，偷摸进了中心，并打听到黑衣人制造堕落者的阴谋，两人再次被发现，你们再次逃走"
  },
  [86469006] = {
    id = 86469006,
    name = "你们摆脱追兵来到河边暂歇，与莉亚商量之后，莉亚同意先赶回去救商队。"
  },
  [86469007] = {
    id = 86469007,
    name = "你们回到废弃的据点，黑衣人已经开始转移商队，莉亚出手救人，商队激烈反抗，迟来的同伴加入战局，这时黑衣人却逃跑了。"
  },
  [86469008] = {
    id = 86469008,
    name = "莉亚追击并杀掉了黑衣人头目，商队被你们救出，莉亚为感谢你们，送给你们一份舞会邀请函，邀请函上有一块“女神的祝福”的圆盘徽章。"
  },
  [86462001] = {
    id = 86462001,
    name = "祥和安宁的伽罗安据点里，有一对夫妇，一直过着平静而幸福的生活，他们等待着一个小生命的降临。"
  },
  [86462002] = {
    id = 86462002,
    name = "瑟瑞很多天都没有回来，而铃的肚子这时候却有了动静......"
  },
  [86462003] = {
    id = 86462003,
    name = "女儿出生后，瑟瑞和铃接受着邻里的恭贺，整个据点其乐融融，而瑟瑞外出久归的原因，竟然是为了给孩子准备了许多意想不到的东西......"
  },
  [86462004] = {
    id = 86462004,
    name = "铃为女儿缝制衣服的时候，有受伤的探险者出现了，带来了不好的消息：有魔物群在附近徘徊。大家听后，立刻加固防御工事，并找人求援。"
  },
  [86462005] = {
    id = 86462005,
    name = "探险者伤好后离开了，瑟瑞准备出门时，铃摔了一跤，瑟瑞只能在家照顾母女，好不容易才给女儿喂了吃的，没想到晚上魔物竟然真的来了。"
  },
  [86462006] = {
    id = 86462006,
    name = "面对魔物的突袭，瑟瑞和大家一起抵抗，却无法阻挡魔物冲入据点......"
  },
  [86462007] = {
    id = 86462007,
    name = "瑟瑞毅然前去战斗，和铃与女儿告别，铃发现瑟瑞受伤了，泪别瑟瑞，离开时，却发现魔物早已包围了据点......"
  },
  [86462008] = {
    id = 86462008,
    name = "铃把女儿在家里某处藏起来，出门和瑟瑞一起战死，魔物还在破坏房屋时，陆玄赶到杀尽魔物，捡到了啼哭的遗孤。"
  },
  [86495001] = {
    id = 86495001,
    name = "你与同伴们在遗迹历险时发现一个无论如何也解不开的机关，这时你忽然想到了一个办法，临时制作了一个工具打开了，大家问起时，你讲述在很多年前与艾瑟儿相遇的事"
  },
  [86495002] = {
    id = 86495002,
    name = "在ACE还没正式成立时，你到了一个村庄打算休息一晚就离开，却发现村庄中的人都死板僵硬，并出现了种种怪象。在你遇到危机时，被陌生的少女救了出去。"
  },
  [86495003] = {
    id = 86495003,
    name = "你和艾瑟儿躲进了一所房屋，村中归于平静，房间里有许多玩偶和木偶，像小孩的玩具房。艾瑟儿告诉你村庄不安全，让你天亮就走，你答应艾瑟儿，但却不小心触碰了房间里的东西，引起房间中玩偶异变......"
  },
  [86495004] = {
    id = 86495004,
    name = "离开房间后，所有村民都守着你们，这些村民就像傀儡被控制了，你决定将这件事告诉公会，让艾瑟儿一起走，艾瑟儿却拒绝离开，你没丢下艾瑟儿逃走，拉她一起躲回木偶房子。"
  },
  [86495005] = {
    id = 86495005,
    name = "你们回到房间，门口彻底被堵死，那些人并不敢进入房间，但房间里的玩偶也难以应付，艾瑟儿通过自制的工具，彻底摧毁了控制他们的丝线，打开了房间中的暗门。"
  },
  [86495006] = {
    id = 86495006,
    name = "你们进入密室后，听到一个傀儡在唱生日歌，这里堆满了玩偶，傀儡还在缝制玩偶。你与艾瑟儿倾听傀儡的语言和行为，出口询问傀儡也不理，但在碰到最真的女娃傀儡时，傀儡突然发狂了。"
  },
  [86495007] = {
    id = 86495007,
    name = "毁灭傀儡的伎俩后，你和艾瑟儿发现原来傀儡还有残留的意识，他本是魔偶师，女儿死后，把女儿做成了傀儡，因为全村人的见死不救，把他们都做成了傀儡。原来这个父亲生前一直在给女儿寻药，但却只有一场空。"
  },
  [86495008] = {
    id = 86495008,
    name = "屋外安静了。艾瑟儿在调查时，发现了地宫的线索，这条治病线索正是艾瑟儿为父亲正好寻找的，她邀请你去地宫探秘，你欣然同意。你与艾瑟儿暂时离开，和你约好时间后道别。"
  },
  [86456001] = {
    id = 86456001,
    name = "蒙娜到市场买材料，见到了罗亚在接任务，公会的人让她休息被她拒绝，并继续执行任务，蒙娜目睹这一切后离开。"
  },
  [86456002] = {
    id = 86456002,
    name = "蒙娜去山谷寻找铃铛草改良田地的种植效率，在谷中里看见罗亚单枪匹马，负伤击杀魔物的完整过程，她给罗亚药物，罗亚拒绝后继续独行执行下一个任务。"
  },
  [86456003] = {
    id = 86456003,
    name = "蒙娜研究农作物成功，哈克斯为了表达感谢给她放了长假。蒙娜出门逛街时再次看到罗亚，发现罗亚的状态比上次更差了，出于好奇蒙娜便跟着罗亚进入公会办事处......"
  },
  [86456004] = {
    id = 86456004,
    name = "罗亚因为太累靠在大树边睡着，因蒙娜的靠近而惊醒警惕。蒙娜知道罗亚的战斗任务，想帮忙，被罗亚拒绝。蒙娜认为罗亚状态不对，追上去帮罗亚解决了战斗，罗亚让蒙娜不要管自己，再次走了。"
  },
  [86456005] = {
    id = 86456005,
    name = "蒙娜完成任务回到圈落，公会的人提起罗亚的状态不好，打算给她一个轻松的任务，让她找蒙娜合作。蒙娜欣然同意，美滋滋回去等罗亚来找自己。"
  },
  [86456006] = {
    id = 86456006,
    name = "蒙娜等了两天没等到罗亚上门，找到公会询问，得知罗亚早已独自离开，蒙娜立刻出发，去追罗亚。"
  },
  [86448001] = {
    id = 86448001,
    name = "你听到两个劫匪在计划怎么抢劫附近的少女，这时两人先发现了你......"
  },
  [86448002] = {
    id = 86448002,
    name = "你再次碰到两个劫匪和正在「被抢劫」的少女，而两人却反而求助少女对付你......"
  },
  [86448003] = {
    id = 86448003,
    name = "你和舒芙蕾到达据点，恰逢有人犯病，而在此时，似乎还有一道视线在暗中观察......"
  },
  [86448004] = {
    id = 86448004,
    name = "你和跟随舒芙蕾到山谷口，一队探险者把守着山谷，并发现了你们......"
  },
  [86448005] = {
    id = 86448005,
    name = "你们再次碰到了那两个「劫匪」，他们却有着与默尔克领队截然不同的说辞，到底该相信谁呢？"
  },
  [86448006] = {
    id = 86448006,
    name = "你与舒芙蕾商议后，决定从旁边的山上侧面调查山谷，却遇到了那个神秘的黑衣人......"
  },
  [86448007] = {
    id = 86448007,
    name = "领队带你们进入山谷，说出了自己的身份和计划，原来不止一个据点出现了「传染病」的事......"
  },
  [86448008] = {
    id = 86448008,
    name = "你们进入山洞，按照路线和计划成功收下「宝物」，却在那一刻突发变故......"
  },
  [86448009] = {
    id = 86448009,
    name = "三人回到据点发现据点大乱，房屋起火，人们互相残杀，「劫匪」原来是黑衣人手下，把他们藏起来的堕落者放出来了。三人阻止乱象，卧底被领队狠心斩杀"
  },
  [86447001] = {
    id = 86447001,
    name = "你碰到了情侣吵架的现场，而第三人却突然邀请你同行......"
  },
  [86447002] = {
    id = 86447002,
    name = "你在酒馆听到路人都在谈起藏宝图，有探险者看你独自一人想拉拢你，而这时候猎鹰出现了......"
  },
  [86447003] = {
    id = 86447003,
    name = "大型魔物追赶探险者，你也被卷入其中，猎鹰将你拉走，却发现魔物紧追不放......"
  },
  [86447004] = {
    id = 86447004,
    name = "你和猎鹰回到据点，准备筹备物资和寻宝所需道具，又遇到了那对先前吵架的男女......"
  },
  [86447005] = {
    id = 86447005,
    name = "你们三人一起上路，西缇丝似乎有意在接近你......"
  },
  [86447006] = {
    id = 86447006,
    name = "面对山洞里大型魔物的蹲守，猎鹰准备充分，西缇丝却做了计划之外的事......"
  },
  [86447007] = {
    id = 86447007,
    name = "你们边战边退，终于成功脱困，你逼迫西缇丝说出一切，而西缇丝的目的竟然是......"
  },
  [86447008] = {
    id = 86447008,
    name = "你们终于找到了宝藏，探险者们也不吝啬与你们一同分享......"
  },
  [86411001] = {
    id = 86411001,
    name = "你遇见一个神秘的男人向你卖货，就在此时，出现了一名追债的男人......"
  },
  [86411002] = {
    id = 86411002,
    name = "你到圈落休整，办理入住时老板向你介绍新开的地下赌场......"
  },
  [86411003] = {
    id = 86411003,
    name = "你被带至圈落外的赌场，看见了狂热的赌徒们......"
  },
  [86411004] = {
    id = 86411004,
    name = "你打算返回圈落，在路上遇到了被魔物围攻的少女，于是出手相助......"
  },
  [86411005] = {
    id = 86411005,
    name = "你来到米哈尔家中做客闲聊，一群人架着她的父亲回来要债......"
  },
  [86411006] = {
    id = 86411006,
    name = "你们找到了米哈尔的父亲，他痛哭流涕地忏悔、决定痛改前非......"
  },
  [86411007] = {
    id = 86411007,
    name = "几天后，米哈尔再次找到了你，她的父亲又不见了，希望你能带他去赌场找人......"
  },
  [86411008] = {
    id = 86411008,
    name = "你们来到赌场，果然找到了米哈尔的父亲，他却再次向米哈尔伸手要钱......"
  },
  [86451001] = {
    id = 86451001,
    name = "你在野外救下一个人，得知他是圈落里的餐馆老板......"
  },
  [86451002] = {
    id = 86451002,
    name = "进入圈落后，你慕名前往餐馆，看到了长长的队伍和附近的莫妮卡......"
  },
  [86451003] = {
    id = 86451003,
    name = "你在河边看到了一具干尸，探险队却认为你是凶手，你百口莫辩......"
  },
  [86451004] = {
    id = 86451004,
    name = "你找到死者的同伴，得知死者死前爱吃餐馆的黑布丁，进入再次遇到了莫妮卡......"
  },
  [86451005] = {
    id = 86451005,
    name = "莫妮卡带你找到了店老板的家，店老板给了你们热情的招待......"
  },
  [86451006] = {
    id = 86451006,
    name = "让你想不到的是，莫妮卡对食物的味觉与众不同，竟能尝出每个人的喜怒哀乐......"
  },
  [86451007] = {
    id = 86451007,
    name = "又出现了新鲜的干尸，这一次，黑衣人被你们及时捕获......"
  },
  [86451008] = {
    id = 86451008,
    name = "你们前往黑衣人的巢穴，得知黑衣人通过餐饮控制着部分探险者......"
  },
  [86451009] = {
    id = 86451009,
    name = "店老板带你们去救他的女儿，却被黑衣人包围，危急时刻，黑衣人的身体突然出现异样......"
  },
  [86451010] = {
    id = 86451010,
    name = "你们再次回到圈落，找到了继承了父亲手艺的萝丝，莫妮卡吃到了久违的味道。"
  },
  [86473001] = {
    id = 86473001,
    name = "抚慰师收到了圣歌成员的消息，要去寻找三样药材，在路上遇到一群疲惫不堪的商人，他们因为缺水而陷入了困境。抚慰师一路跟着商队，和大家一起寻找水源。"
  },
  [86473002] = {
    id = 86473002,
    name = "抚慰师带人找到了水源，在她走后，那些心情不安的人喝了水后，都变得更加平和了，大家团结合作继续前行。"
  },
  [86473003] = {
    id = 86473003,
    name = "抚慰师找第二个材料，在森林里遇到一个间歇性失忆的老人，老人只记得自己年轻时候的事，跟她不厌其烦地说着过去，抚慰师耐心地听着，并采集了第二个药材，打算将老人送往村庄。"
  },
  [86473004] = {
    id = 86473004,
    name = "抚慰师带老人回到住所，将老人交给了他的女儿，但他的女儿却认为老人是负担，耽误了她成为探险者的未来，不如让他自生自灭，抚慰师发现女儿受浊炁影响，将其净化，父女和好如初。"
  },
  [86473005] = {
    id = 86473005,
    name = "抚慰师在寻找第三个材料时，遇到一个离家出走的小女孩，在看见围绕小孩周围的浊炁后，送小孩回家。"
  },
  [86473006] = {
    id = 86473006,
    name = "抚慰师将小女孩送回了家，找到她的母亲，原来她的父母在焦急地找她，小孩将离家的原因告诉父母，抚慰师送了小女孩一朵花，让她暂时不受浊炁干扰，希望她能平安实现她的理想。"
  },
  [86498001] = {
    id = 86498001,
    name = "学院的人找到菲尼斯，让菲尼斯邀请你和艾琳作为上一届优秀毕业生来参加这一届的学院毕业晚会，菲尼斯私下找到列蒂西雅，告诉她此事，让她要好好准备钢琴演奏节目表演给你和艾琳看。"
  },
  [86498002] = {
    id = 86498002,
    name = "菲尼斯找到了你和艾琳说明了来意，并表示今年的特邀嘉宾需要准备节目。你与艾琳本就打算为列蒂西雅和奥萨丁准备毕业礼物，欣然同意。"
  },
  [86498003] = {
    id = 86498003,
    name = "一路上，你们讨论着准备什么礼物给列蒂西雅与奥萨丁，又在圈落逛了一圈，并没有找到如意的礼物，你想，与其买不如自己做。"
  },
  [86498004] = {
    id = 86498004,
    name = "两人十分赞同你的提议，因为时间关系，你们对礼物的选择有限。菲尼斯甚至想给奥萨丁送个脑子，你想给列蒂西雅做一把小提琴，想弥补列蒂西雅热爱音乐的遗憾。"
  },
  [86498005] = {
    id = 86498005,
    name = "你们准备制作小提琴的材料，找寻适合做琴弦的魔物，在杀掉魔物得到琴弦之后，同时意外得到了坚韧的护甲材料，正好可以给奥萨丁送护甲，并继续找制作琴身的材料。"
  },
  [86498006] = {
    id = 86498006,
    name = "你们寻找制作琴身的树木，在打听下，得到了一棵树美好的传说，最终你们一起找到了那棵树，斩下了枝干作为琴身和面板。"
  },
  [86498007] = {
    id = 86498007,
    name = "你们回到圈落制作礼物，几天后终于拿到了成品，出发赶去参加新年毕业晚会。"
  },
  [86460001] = {
    id = 86460001,
    name = "你遇到了米亚姆，见米亚姆心事重重，你旁敲侧击，发现米亚姆想去参加圈落竞赛，但她武器损坏了，你决定帮忙。"
  },
  [86460002] = {
    id = 86460002,
    name = "你带米亚姆去修武器，但工匠太忙，没时间修，你问过材料，决定帮助米亚姆，在确定好材料后，你们再次出发。"
  },
  [86460003] = {
    id = 86460003,
    name = "你和米亚姆外出找材料，根据魔物特性，你们找到魔物，没想到很多人也在蹲守。魔物出现时，大家一拥而上，人群散去，米亚姆就拿到一根羽毛。"
  },
  [86460004] = {
    id = 86460004,
    name = "你和米亚姆从长计议，寻找代替品。在否决几个想法后，你仍决定去帮她找最好的材料。"
  },
  [86460005] = {
    id = 86460005,
    name = "你和米亚姆到迅魔龙的所在地，与它周旋了许久，成功拿到了材料。"
  },
  [86460006] = {
    id = 86460006,
    name = "你和米亚姆回到圈落修好了武器，在得知米亚姆这次竞赛还没有搭档时，让她去找灵遥。鉴于米亚姆的害羞，你思考后私下去找到了灵遥。"
  },
  [86467001] = {
    id = 86467001,
    name = "有人找你问路后，你发现财物被盗了，你追上窃贼，遇到尼基塔和窃贼战斗，劫匪诬陷你，并把财物扔给你跑掉。尼基塔认为你是同谋，和你打了一架，她打得上头，你不得不找机会溜走。"
  },
  [86467002] = {
    id = 86467002,
    name = "你进入圈落找人买东西，再次遇到尼基塔，她正和克里莫在卖东西，并认出了你，在知道先前是误会后，给你卖了不少好货，还想和你再打一架。"
  },
  [86467003] = {
    id = 86467003,
    name = "离开圈落后，你救下了被魔物袭击的克里莫，但克里莫不理你，匆匆跑走，没隔多久尼基塔来找小孩，你得知克里莫的身世，你们到达森林，发现克里莫被魔物攻击，危急时刻你和尼基塔一起出手，杀掉魔物。"
  },
  [86467004] = {
    id = 86467004,
    name = "再次回到圈落后，看见克里莫讨价还价发挥出商人天赋，尼基塔带你去她所在的贫民窟，作为大姐头，很受孩子们爱戴，尼基塔说等以后有机会把跟着她的孩子们都送回大陆，而后她想和你一战被你婉拒。"
  },
  [86467005] = {
    id = 86467005,
    name = "尼基塔让你陪她去工匠处做东西，工匠说负责运柴火和材料的人很久没回来，你和尼基塔分头行动，你根据线索找人，发现运货的人死在路上，材料也损坏了，你推断材料获取并不难，决定帮尼基塔拿到。"
  },
  [86467006] = {
    id = 86467006,
    name = "你深入森林找到魔物老巢，出现了意外，在战斗中被困，尼基塔及时相救，在拿到材料后，两人互相感谢。"
  },
  [86467007] = {
    id = 86467007,
    name = "回到圈落后交给工匠打造物品，克里莫叫走了尼基塔，看到你受伤了，让你去贫民窟帮忙送东西，你到达贫民窟后，收到了小孩的欢迎并帮你治疗，在夜幕时分尼基塔收摊回来再次感谢你，和你约定时间打架后道别。"
  },
  [86464001] = {
    id = 86464001,
    name = "旅者菲莉亚到了一处森林，看到有人正准备杀掉一只低级无害的小魔物，便将魔物买了下来。通过研究魔物施展魔法的原理，菲莉亚取得了不错的收获。"
  },
  [86464002] = {
    id = 86464002,
    name = "她来到一个山洞前，看到一群探险者在诱捕魔物，在探险者打斗中，她隔岸观火，仔细记录魔物的习性，并分析弱点。探险者扛不住求助于她，她出手解除危机，待探险者想要寻找她时，她已经离开了。"
  },
  [86464003] = {
    id = 86464003,
    name = "她出现在热闹的圈落里，观察身边的新鲜事物，却对人际关系并不擅长，想拉拢她的，被她的漠然态度不敢靠近，只有在对一件事感兴趣的时候她才会开口，在发现圈落无趣之后，她独行离开了。"
  },
  [86464004] = {
    id = 86464004,
    name = "她路过一座村庄，发现了这个村庄有很多奇特的花草，她停留了下来、专心研究花草，顺便在村庄看病帮忙，受到村民的喜欢和亲近。"
  },
  [86464005] = {
    id = 86464005,
    name = "菲莉亚经过多次实验之后，记录花草和药理的关系，认为那个魔法实验弊大于利，再研究下去会有不可预知的效果，于是将它封存了起来。"
  },
  [86464006] = {
    id = 86464006,
    name = "菲莉亚再次帮助村民的时候，发现一个小女孩偷偷在看她，她从村民口中了解到，娜莎是一个吃百家饭长大的小姑娘，在村民撺掇下，她们一起吃了一顿饭，她突然觉得这个村子很好，可以暂时留在这里研究药理，整理资料直到结束。"
  },
  [86489001] = {
    id = 86489001,
    name = "你在外出时发现陷阱中掉了一个少女，将少女埃斯特拉救上来之后，埃斯特拉要雇佣你做护卫，你因为顺路，同意送埃斯特拉回圈落。"
  },
  [86489002] = {
    id = 86489002,
    name = "你和埃斯特拉到达临时营地，你发现埃斯特拉缺乏生活常识，又对探险充满好奇，有人要骗她钱被你拦下，她认为你和她那些一直说假话的侍从不一样。"
  },
  [86489003] = {
    id = 86489003,
    name = "在埃斯特拉的要求下，她要走另外一条路，原来只要通过她长兄的考验，收集足够的纹章，就可以离家独自探险。而后，在收集第二枚纹章时，你们发生了意外......"
  },
  [86489004] = {
    id = 86489004,
    name = "你带埃斯特拉出陷阱后，得到了第二枚纹章。埃斯特拉说起她家里人都很溺爱她，长兄还给了她求助的信号，但她不会去用。"
  },
  [86489005] = {
    id = 86489005,
    name = "你们到达宽阔的河边，乘船行驶到河中间时，船夫要埃斯特拉交出藏宝图，原来他误认为你们拥有藏宝图，船夫被你制服后，凿船逃走，唤醒了水底的魔物。"
  },
  [86489006] = {
    id = 86489006,
    name = "你们合力击杀了魔物，船夫也咎由自取葬于魔物之口。上岸后，埃斯特拉正自夸她解决了危机时，差一点掉下了第三个陷阱，被你及时拉住。"
  },
  [86489007] = {
    id = 86489007,
    name = "你把埃斯特拉安全送到圈落，交到了下属手中。埃斯特拉把纹章送给了你，突然让你去罗斯伯尔家族提亲。"
  },
  [86421001] = {
    id = 86421001,
    name = "公会的人再一次找到了你，拜托你帮忙调查隐身魔物事件。"
  },
  [86421002] = {
    id = 86421002,
    name = "你根据地图指示到达目的地附近的据点，在用餐时，你看到店里的宣传单竟然是生擒隐身的魔物，当地传闻隐身魔物竟然是顶级的美味食材......"
  },
  [86421003] = {
    id = 86421003,
    name = "赛格丽特装备齐全，筹备了许多东西和你一起上山，在山上的时候，你们突然陷入了迷雾，又听到了诡异的魔物声......"
  },
  [86421004] = {
    id = 86421004,
    name = "你们撤回到据点，服务员看到你们铩羽而归，说出了之前接取委托的探险者，都接连失踪的消息......"
  },
  [86421005] = {
    id = 86421005,
    name = "你们上山时再次遇到了迷雾，驱散迷雾后，发现这里遗落了许多探险者遗失的物品，但却没发现尸骨和战斗过的痕迹......"
  },
  [86421006] = {
    id = 86421006,
    name = "你翻过山的背后，找到了有探险者战斗的痕迹，顺着痕迹找到漆黑的山洞，发现和小魔物搏斗的赛格丽特，听到你声音的赛格丽特反而很紧张......"
  },
  [86421007] = {
    id = 86421007,
    name = "你们回到店里，服务员看到你们后立刻逃走了，你给赛格丽特买好衣服，等赛格丽特整顿好后，你和她交流掉落山洞后的细节，以及小魔物的特征，大概猜测出了真相。"
  },
  [86421008] = {
    id = 86421008,
    name = "你们再次到了那座山，这次顺利地避过了陷阱，重新进入了那个山洞，果然找到了赛格丽特要找的矿石，可这时你们却看到更加离奇的事......"
  },
  [86421009] = {
    id = 86421009,
    name = "你与赛格丽特离开后，赛格丽特再次感激你，向你道别。"
  },
  [86419001] = {
    id = 86419001,
    name = "你在路上遇到正在追逐的两个人..."
  },
  [86419002] = {
    id = 86419002,
    name = "你看到先前的骗子在骗老人钱财，出面制止，老人得知真相后显得有些落寞，似乎不愿相信这一切......"
  },
  [86419003] = {
    id = 86419003,
    name = "你随茉莉找到酒馆老板，询问诈骗团伙的线索，酒馆老板正好需要茉莉做一件事......"
  },
  [86419004] = {
    id = 86419004,
    name = "你们到银月谷据点，发现整个据点的老人都被骗走了积蓄......"
  },
  [86419005] = {
    id = 86419005,
    name = "你们到达莫科据点，才发现骗术层出不穷，连酒店老板也上当受骗了......"
  },
  [86419006] = {
    id = 86419006,
    name = "回圈落的路上，你们救下了一个与魔物战斗的老人......"
  },
  [86419007] = {
    id = 86419007,
    name = "你们找到了藏在山里的养子，可惜事与愿违......"
  },
  [86419008] = {
    id = 86419008,
    name = "你们羁押着骗子回到据点，将投资款还给受害者，老人们的反应却各不相同......"
  },
  [86419009] = {
    id = 86419009,
    name = "你们回圈落将骗子的事告诉了老板，老板及时醒悟，让茉莉有了点宽慰......"
  },
  [86450001] = {
    id = 86450001,
    name = "夜深后，你独自在野外安营扎寨休息，半夜听到两个人靠近的声音......"
  },
  [86450002] = {
    id = 86450002,
    name = "你到据点后，看到免赔商会旗下的商品，遇到了同样感兴趣的海蒂，海蒂成功被安利，散漫的她有了新目标......"
  },
  [86450003] = {
    id = 86450003,
    name = "你们在森林里遇到魔物和两个探险者，帮他们打退魔物后，得知他们也是去商会总部的，本打算一起同行，没想到那两个探险者趁你们休息的时候，找借口甩掉你们离开了。"
  },
  [86450004] = {
    id = 86450004,
    name = "你和海蒂到达临时营地，这里正好有一个商会的讲座，许多人在这里听，结束之后还能获得一份小礼物，海蒂越听越起劲，甚至幻想自己拥有财富名望和下属的日子，但却拒绝了讲师的招揽。"
  },
  [86450005] = {
    id = 86450005,
    name = "海蒂为了尽快到达总部，和你走了一条荆棘小路，在抄近路的时候，一个受伤的人出现，支支吾吾不愿意提来历，并且希望你们不要泄露他的行踪，着急负伤离开。"
  },
  [86450006] = {
    id = 86450006,
    name = "你们跟着那个人到了免赔商会，他把你带到“后门”与人交涉时，海蒂听到“带了两个人”以为他们把自己当作了下线，拒绝进入......"
  },
  [86450007] = {
    id = 86450007,
    name = "你们逃出了免赔商会，在休息时发现了另一位逃出来的受害者。"
  },
  [86450008] = {
    id = 86450008,
    name = "海蒂和你到达圈落，并将此事告知了公会。"
  },
  [86408001] = {
    id = 86408001,
    name = "夜晚你路过祭坛，看到一队探险者在祭坛休息，而其中一个叫瓦莱沙的女孩似乎不合群......"
  },
  [86408002] = {
    id = 86408002,
    name = "据点的负责人告诉你们，他们一直被突然出现的魔物袭击，希望能解决这个困扰。面对瓦莱沙打破砂锅的询问，负责人开始怀疑你们执行任务的能力......"
  },
  [86408003] = {
    id = 86408003,
    name = "你和众人往负责人所说的线索，一路上能看到人为活动的痕迹，瓦莱沙发现了异常......"
  },
  [86408004] = {
    id = 86408004,
    name = "你们顺着线索进入山洞，听到里面的呼救争吵，先前的同伴竟然被一大群魔物围困住了。"
  },
  [86408005] = {
    id = 86408005,
    name = "瓦莱沙和你被三人误解，认为瓦莱沙是故意没有告诉他们，你出面斥责三人，三人决定和你们分道扬镳......"
  },
  [86408006] = {
    id = 86408006,
    name = "回到据点后，负责人推测了那堆财宝的来历。除了魔物之外，据点时不时会受到劫匪的骚扰，那堆财宝很可能是劫匪藏匿宝物的地方，就在这时劫匪果然突袭了据点......"
  },
  [86408007] = {
    id = 86408007,
    name = "你们跟着劫匪来到山里的窝点，发现山里窝点的地下连通了之前的山洞，几名劫匪与你们战斗后逃跑，你们顺着逃跑路线，发现这群劫匪饲养着一群魔物......"
  },
  [86408008] = {
    id = 86408008,
    name = "你们回去找到负责人，发现他正要逃跑，抓住了他，原来负责人竟然是劫匪的领头人......"
  },
  [86499001] = {
    id = 86499001,
    name = "シェラとレムは魔法の店で、見たこともない魔術書を見つけた。興味を惹かれてめくると、二人は「星落」の世界に転移してしまった。"
  },
  [86499002] = {
    id = 86499002,
    name = "わけも分からず深淵にやって来たシェラとレムの二人は、自分たちが密林にいることに気づいた。力が抑えつけられるような感じがして、召喚術も使えなくなっていた。二人が慎重に周囲を探っていると、魔物の大群に出くわし、危機的状況に陥った。"
  },
  [86499003] = {
    id = 86499003,
    name = "あわやというとき、あなたたちが現れて二人を危機から救った。二人が異世界から来たことを知り、アネシの提案で元の世界に戻る方法を探すのを手伝うことにした。ひとまずここで一晩休み、翌日皆で集落に行って手がかりを探すことにした。"
  },
  [86499004] = {
    id = 86499004,
    name = "翌日、一行は集落にやって来た。ネリッサが女の子たちを連れて街を散策し、シェラとレムはこの世界と人々のことが少しずつ分かってきた。あなたとフィニスは事情を知る情報屋を探しに出かけた。"
  },
  [86499005] = {
    id = 86499005,
    name = "あなたとフィニスはスラムにやって来た。路地の果てにボロ酒場がある。あなたが先頭に立ってもぐり込むと、情報屋が二人を待ち構えていたかのように、座って一緒に飲むよう呼びかけた。二人は情報屋に事情を聞き、闇夜村という場所と行き方の手がかりを知った。"
  },
  [86499006] = {
    id = 86499006,
    name = "夜が更け、二人は酒場から出ると、泊まっていた宿に戻った。シェラとレムは女の子3人とすっかり仲良くなっていた。あなたとフィニスは闇夜村という場所に元の世界に帰れる方法があるはずだと皆に伝えた。翌日、一行は闇夜村から出てきた人を探しに出発した。"
  },
  [86601001] = {
    id = 86601001,
    name = "幼时的枭在据点练习箭术，天赋异禀。父母外出探险时，邻居都很照顾枭，他们非常敬佩枭的父母的能力，枭崇拜父母，想成为和他们一样的逐秘者。"
  },
  [86601002] = {
    id = 86601002,
    name = "伊戈尔母回来后，给枭带了礼物，一家人十分温馨地生活，并共同许诺着美好的未来。枭为能成为逐秘者，对修行更有干劲。"
  },
  [86601003] = {
    id = 86601003,
    name = "枭的父母再次出门了，这一次很久才回来。枭的母亲开始变得暴躁无常，并且不准枭再练习，再三追问，父亲告知了枭，原来母亲被宝物诅咒了，而诅咒的宝物就此消失不见。"
  },
  [86601004] = {
    id = 86601004,
    name = "母亲的脾气变得反复无常，常常因为一点小事就大发雷霆牵连枭，父亲用了各种办法，反而惹来母亲猜疑。一次家庭矛盾爆发，父亲终于下定了决心，从村庄搬出来离群生活。"
  },
  [86601005] = {
    id = 86601005,
    name = "父亲下定决心为母亲找药，准备好一切后，和母女好好道别，决定去寻找诅咒的宝物，在离开时，父亲拥抱了母女，让枭照顾好母亲。"
  },
  [86601006] = {
    id = 86601006,
    name = "父亲走后，母亲按时服药，有时也会爆发病症，枭照顾母亲，母亲却非常痛苦，她害怕枭以后也这么痛苦，甚至想杀掉枭。一天，村里的人将父亲的死讯带给了母女。"
  },
  [86601007] = {
    id = 86601007,
    name = "父亲死后，母亲突然恢复了原状。在枭生日那天，母亲支开枭拿礼物，枭拿到礼物回家后，母亲已经去世，并给枭留下了遗书。宝物成了枭的执念，从此她成了逐秘者，决心找到诅咒母亲的宝物。"
  },
  [86486001] = {
    id = 86486001,
    name = "你去黑市高价倒卖稀有魔物，遇见少女正在被诈骗，你上前暗示少女那是骗子，骗子发现自己露馅想要逃走，少女这才明白过来，把骗子抓回来打了一顿，让骗子交出了被骗的钱。"
  },
  [86486002] = {
    id = 86486002,
    name = "你在野外休息时又遇见了那个少女，她正在烧烤食物，但每次都烤成一堆炭，看到你做了香喷喷的食物，她命令你帮她烤。你出手帮忙，她十分不解自己照着食谱也能烤糊，给了你不菲的报酬后，你做了更多的食物给她，她对此很满意。"
  },
  [86486003] = {
    id = 86486003,
    name = "你进入圈落后，想打听一年一度的拍卖有什么稀有的宝贝，你听到大家都谈论永夜森林的情报。传说开放日期快到了，森林里有无尽珍宝，需要的稀有特殊钥匙，会在拍卖行拍卖。你有了点兴趣，考虑是否公开身份进入拍卖行。"
  },
  [86486004] = {
    id = 86486004,
    name = "正在圈落吃饭时，鬼王发现了你，她也听说了拍卖行的事，让你陪她去。她要买东西，你明白她想让你帮她掌眼，顺势答应了。鬼王很高兴，给你点了吃不完的美食，你受宠若惊。"
  },
  [86486005] = {
    id = 86486005,
    name = "吃完饭后，你一路陪鬼王逛集市。发现鬼王两极分化，对于战斗十分擅长，但不通人情世故也不明白商品的价格，遇到喜欢但无用的都想买，被你劝阻了。"
  },
  [86486006] = {
    id = 86486006,
    name = "鬼王用特殊身份带你进入了拍卖会，进入了高级宾客才能坐的雅间。主持人宣布拍卖会开始后，鬼王大买特买，并将你评价不错的拍卖品全部收入囊中。面对其他竞争者的怨气，你已经不好意思再开口评价拍卖品了。"
  },
  [86486007] = {
    id = 86486007,
    name = "一直到最后一个压轴商品，一张魔法卷轴出现，鬼王才打起了精神，那张卷轴正是去永夜森林的钥匙，她以极高的价格买到了魔法卷轴，之后在拿到的第一时间给了你，邀请你同去永夜森林。你还来不及诧异，鬼王已经离开了，显得十分蛮横霸道。"
  },
  [86471001] = {
    id = 86471001,
    name = "有村民找到抚慰师，说家里人很久没回来了，请她帮忙去湖泊附近的据点找人。抚慰师询问一番后，村民说家人不知从哪儿拿到一张藏宝图，去了湖泊据点的方向，至今没有信息，抚慰师收集线索后，离开村子出发。"
  },
  [86471002] = {
    id = 86471002,
    name = "抚慰师抵达据点后，发现这里气氛诡异，询问之后，大家都对寻宝避而不谈，她进入酒馆调查，听说了两个消息，一是讨论什么时候上船最好，二是有圣歌组织的成员在这里做好人好事。"
  },
  [86471003] = {
    id = 86471003,
    name = "抚慰师找到组织成员，见到圣光使正在帮人治疗，在帮忙一起治愈伤员后，她询问圣光使据点中的怪像，圣光使说起据点失踪人口的情况，一起共享了相关的线索。"
  },
  [86471004] = {
    id = 86471004,
    name = "圣光使带抚慰师去了一个老渔夫的家中。二人在渔民家中发现所有失踪者都拥有「风吟果壳」，果壳上有相关的线索。两人追问老渔夫，老渔夫交代了失踪的亲人，是因为月圆之夜会听到召唤的歌声，第二天一早，亲人就不见了，两人决定先去码头看看。"
  },
  [86471005] = {
    id = 86471005,
    name = "两人来到湖边码头，码头泛起灰雾，湖中隐约传来缥缈的人声，圣光使暂时驱散雾气，短暂看见湖面有船只虚影，然后魔物出现，两人击退魔物，同时也得到了风吟果壳，两人有了想法，一拍即合决定去找到那个醉汉。"
  },
  [86471006] = {
    id = 86471006,
    name = "圣光使经过调查，让失踪者的家属说出了真相。两人在提出想帮忙的意图时，有的人认为两人多管闲事，也有失踪者的亲人怀疑家人出了事，希望她们能去找到真相，帮忙找回亲朋好友，两人同意，约定月圆之夜一起登船去湖心看看。"
  },
  [86603001] = {
    id = 86603001,
    name = "白蔷薇之梦是天生的圣物，被一名边境伯爵的独女意外获得，她将花枝别在婚服上祈求幸福，却在婚礼当日目睹未婚夫与政敌勾结屠戮全族。血溅在花瓣上时，它第一次尝到了人类的鲜血。"
  },
  [86603002] = {
    id = 86603002,
    name = "一位士兵在废墟里拾得这个不败的白蔷薇。当他发现白蔷薇能随心意改变形状后，将它示做天意，士兵从守护平民的起义军领袖沦为暴君，最终他被亲信割喉。"
  },
  [86603003] = {
    id = 86603003,
    name = "它被一名炼金术师发现，他将白蔷薇之梦植入少女的心脏进行永生实验。当实验体挣脱锁链冲出地牢时，它目睹少女在晨光中化作灰烬。"
  },
  [86603004] = {
    id = 86603004,
    name = "濒死的将军在山洞里得到了白蔷薇之梦，因为将军强烈的愿望，白蔷薇之梦变成了他的一把剑，它刺穿敌将，见证了他成立了大陆第一的诺维奇帝国，国王早逝，在去世前将白蔷薇之梦奉为了诺维奇帝国的圣物，只有继承者才能拥有。"
  },
  [86603005] = {
    id = 86603005,
    name = "海莉女王继承皇位后，白蔷薇之梦成为了她的权杖，诺维奇帝国迎来黄金时代。她通过白蔷薇之梦聆听万物，掌控帝国，在庆典上颁布了惠于后世的法典，却逐渐丧失五感死去。她深知获得力量会付出代价，在死前让大言灵师将白蔷薇之梦的力量封存。"
  },
  [86603006] = {
    id = 86603006,
    name = "此后过了上百年，白蔷薇之梦传承了一代又一代，成了象征权利的圣物。克修斯在十五岁剑礼仪式后，正式从国王手中获得了它。它随克修斯的心意变成了克修斯的发冠，见证克修斯从少年到青年，在他二十岁继位国王时变成了王冠。"
  },
  [86603007] = {
    id = 86603007,
    name = "新王即位多年后，帝国的大王女出生了，国王从边陲赶回来，看到了虚弱的母亲和可爱的女儿，按照顺位这个女儿以后就会继承他的王位。他将王冠摘下来，放在小公主手中，王冠变成了一枝白蔷薇花，数百年来象征绝对权力的圣物，此刻回归了本来的模样。"
  },
  [86605001] = {
    id = 86605001,
    name = "蒙娜在看书的时候发现一个好玩的东西，想改良自己的装备，出门约罗亚一起吃饭，在店中遇到打工的黑羽吃饭，蒙娜说要去找维克多大师，罗亚有事拒绝，黑羽也说没空，蒙娜只能自己出发。"
  },
  [86605002] = {
    id = 86605002,
    name = "蒙娜去找维克多，但只见到了他的弟子弗拉克，在提出各种升级要求后，弗拉克说没有材料，要让她自己去找，这时伊莎贝尔来了。"
  },
  [86605003] = {
    id = 86605003,
    name = "蒙娜和伊莎贝尔打招呼，得知伊莎贝尔来找弗拉克要资料，弗拉克将维克多打听到的资料交给伊莎贝尔，蒙娜过去一起看，资料上讲的是一个传说中的废弃研究所。"
  },
  [86605004] = {
    id = 86605004,
    name = "弗拉克说起伊莎贝尔的事，蒙娜热心地说自己的升级材料也需要相关方面的东西，要和伊莎贝尔一起去，在做好准备工作后，两人出发启程。"
  },
  [86605005] = {
    id = 86605005,
    name = "两人一路吃吃喝喝玩玩，在到达研究所附近后，发现这里已经变成了暗域。"
  },
  [86605006] = {
    id = 86605006,
    name = "蒙娜出了鬼点子，和伊莎贝尔顺利进入暗域，雾中的研究所大概是暗域中心，魔物也开始变异，种类和数量越来越多。"
  },
  [86605007] = {
    id = 86605007,
    name = "蒙娜掩护伊莎贝尔顺利进入研究所的院子，自己也狼狈地进去了，把魔物阻挡在外面，但大门紧闭无法进入，研究所有被火烧过的痕迹，两人尝试各种办法，意外激活了开关。"
  },
  [86477001] = {
    id = 86477001,
    name = "猎鹰找到了一个宝物，召集组织的成员聚集一起玩，夜莺和云雀先来，渡鸦姗姗来迟。猎鹰展示宝物，宝物发光的时候，渡鸦睡着了，做了一个梦。"
  },
  [86477002] = {
    id = 86477002,
    name = "渡鸦醒来之后忘记了梦中内容，大家讨论猎鹰的罗盘有问题，猎鹰很困扰，提到了拿宝物的地方是在星坠湾附近，那里还有未曾解开的秘密，渡鸦说去看看也不错，众人十分惊讶。"
  },
  [86477003] = {
    id = 86477003,
    name = "确定渡鸦要去星坠湾后，猎鹰把星轨罗盘送给了渡鸦，说自己没空，不能陪她去星坠湾了，云雀也因为委托走不开。夜莺提出和渡鸦一起去，约好与渡鸦一起出发，并帮渡鸦做好前期准备。"
  },
  [86477004] = {
    id = 86477004,
    name = "渡鸦晚上又做梦了，醒来还是忘了梦里的事，她拿着罗盘去找夜莺，两人出发去星坠湾，路上渡鸦说了罗盘对自己睡眠的影响，夜莺讲了关于梦相关的传说，渡鸦认为是无稽之谈。"
  },
  [86477005] = {
    id = 86477005,
    name = "两人到了附近的据点，在餐馆听到了星坠湾的来历，传说是深渊形成时，由巨石砸出的环形大湾，以及里面砸出了很多宝物的传闻，但因为地质特殊，没人能下去，下去的人都没回来，渡鸦和夜莺去现场察看，想到了办法。"
  },
  [86477006] = {
    id = 86477006,
    name = "次日，两人自制了滑板，从坑顶滑了下去。过程中星轨罗盘反应剧烈导致渡鸦看到了幻觉，很多人影和声音一闪而过，两人成功到达了坑底，看到了壮丽的星坠湾的奇观。"
  },
  [86606001] = {
    id = 86606001,
    name = "艾拉一直很倒霉，但她对倒霉习以为常。这天她被藤蔓吊在树上，你路过的时候看见她把藤蔓当秋千玩，将她救下后，她又中了另一个陷阱，你把她捞起来后，她决定跟你同行。"
  },
  [86606002] = {
    id = 86606002,
    name = "在知道你是学院老师后，艾拉一路分享自己以往探险的趣事和倒霉的经历。你偶尔应和，在再次遇到倒霉事件时，发现她锲而不舍的坚韧和豁达。"
  },
  [86606003] = {
    id = 86606003,
    name = "在将艾拉送到据点后，你去找人，得知那人不在，而在流火村后，你又遇到了倒霉的艾拉在追小偷，你帮她追回了小偷的东西，她向你致谢，请你吃饭"
  },
  [86606004] = {
    id = 86606004,
    name = "在知道你任务没完成时，艾拉为报答决定帮忙，陪你一起去流火村找人，尽管别人说她倒霉鬼她也并不介意，因为这样可以把身边的霉运吸走，你就不会倒霉了。吃完饭后，你们一起出发"
  },
  [86606005] = {
    id = 86606005,
    name = "你们在路上遇到了很多魔物，你发现艾拉的战斗并不逊色，但总是差点运气，比如这次就惊扰了领主级魔物，仓皇之下，你和艾拉一起掉下悬崖掉进河里，醒后两人看见了一座村庄，正是你要找的流火村。"
  },
  [86606006] = {
    id = 86606006,
    name = "你们进入流火村后，打听到了彼得过两天才回来，你提醒村长附近的领主级魔物，村长认为魔物不会擅自离开领地，不会有事。因为要等人回来，艾拉也喜欢村庄的环境，你们决定在村庄住一段时间。"
  },
  [86607001] = {
    id = 86607001,
    name = "星轨和风痕路过一个村庄，附近长满了蓝色的花，两人在欣赏时，听到附近村民叹气。原来丰收季要到了，这些蓝色的花会导致农作物枯萎，怎么灭杀第二天都会重新长起来，让他们十分忧心。"
  },
  [86607002] = {
    id = 86607002,
    name = "星轨和风痕用了各种办法，也没办法阻止花第二天的生长，星轨尝试用火，差点将稻田一起点燃，幸好及时补救，才没酿成大祸。两人只好想想别的办法"
  },
  [86607003] = {
    id = 86607003,
    name = "大半夜，两人到烧毁的山上观察花是如何生长的，却发现花下面有小东西在移动，两人去抓，用尽了手段，捣毁了大部分的花之后，终于发现了下面移动的魔物，但被它钻地跑了"
  },
  [86607004] = {
    id = 86607004,
    name = "天亮之后，两人把情况告诉了村民们，原来是魔物繁衍的花，一旦繁衍村庄必然覆灭。村民们招待两人留下来吃饭，而后星轨观察到线索，找到了克制魔物逃跑的办法"
  },
  [86607005] = {
    id = 86607005,
    name = "到了晚上，两人用驱魔粉做了一圈隔离带，将魔物围困，再进行捕杀，在差不多杀完魔物时，魔物首领出现了，两人怕魔物影响庄稼，将其引走"
  },
  [86607006] = {
    id = 86607006,
    name = "两人引走魔物首领后，将它彻底击杀。又一次天亮，花没有再开，星轨感叹深渊越美丽的东西越危险。两人受到村民们的感激，村民们邀请她们去参加今年圈落的丰收祭"
  },
  [86475001] = {
    id = 86475001,
    name = "母亲离家出走后，永夜一直在寻找母亲，她打听到母亲在追寻古代遗迹，而沙漠驿站最近传出了遗迹的传闻，她为了打探母亲的消息，独自穿越险地前往沙漠驿站"
  },
  [86475002] = {
    id = 86475002,
    name = "永夜到达黄金据点，向摊贩、行商打听古代遗迹的消息，大多数人都认为是个多年前的传说，这时一行商队认出她是深渊航线的人，提出要她护送去送货，报酬是遗迹的线索。"
  },
  [86475003] = {
    id = 86475003,
    name = "永夜和商队出发，在峡谷里遇到了另一队探险者，他们之中有一个叫露可的少女引起了永夜的注意，然而这队探险队，竟然起了不好的心思......"
  },
  [86475004] = {
    id = 86475004,
    name = "永夜在据点研究笔记，她找人帮忙解读，笔记里写了古代遗迹的线索“时之砂”，她认为这次一定能找到母亲，于是根据笔记的线索再次出发。"
  },
  [86475005] = {
    id = 86475005,
    name = "永夜到达了老人说的祭坛，这里已是废墟，她和灰岩探险队再次相遇，露可暗中向永夜求救，终于找到了机会和她交流，她能打开这个通道，但要请永夜帮忙送信。"
  },
  [86475006] = {
    id = 86475006,
    name = "在探险队的多次催促下，露可成功打开祭坛的机关，魔物出现，众人激战，露可趁机开启地下通道，率先将她推入了通道，希望永夜能帮自己送到信，在永夜进入通道后，通道入口就关闭了"
  },
  [86494001] = {
    id = 86494001,
    name = "你在圈落休整偶遇岫，岫正愁找不到帮手，拉你到霏的地方帮忙，霏的父母为家乡亲友准备了节日礼物放在了某地，但那个地方很远，走近路危险。时间紧迫，岫又有事离开，于是将霏交给你，你答应后与霏一同上路"
  },
  [86494002] = {
    id = 86494002,
    name = "随着岫的离开，你和霏一起出发了，霏非常热爱新事物，什么都想尝试一下，好几次你及时阻止，才免于危机。"
  },
  [86494003] = {
    id = 86494003,
    name = "穿行危险地带时，你们遇到了几波魔物都被霏轻松解决，你发现霏虽然行事不计后果，但是战斗能力非常强，但就在即将通过峡谷，霏被一颗植物吸引了......"
  },
  [86494004] = {
    id = 86494004,
    name = "霏被植物“同化”了，认为自己是那株植物不能行走，你无奈只能背着她离开，一路上她吵着要晒太阳、喝水，然后，她清醒了过来......"
  },
  [86494005] = {
    id = 86494005,
    name = "离开峡谷后，霏拿出父母的提示，推断这是父母给自己的考验，决定不让你帮忙，孤身进入洞穴，你听到一声尖叫冲进去，结果发现是乌龙一场......"
  },
  [86494006] = {
    id = 86494006,
    name = "你和霏根据她父母的留言到达了隔壁圈落，成功拿到了父母给霏和亲友的东西，霏感谢你，并邀请你去家乡过节。"
  },
  [86402001] = {
    id = 86402001,
    name = "你打听到灰岩圈落即将举行一场通过猎杀魔物的积分来换取物资的活动，并且还有活动表演，对此十分感兴趣。"
  },
  [86402002] = {
    id = 86402002,
    name = "到达圈落后，广场上正好有人在表演杂耍，你驻足观看时，意外发生了......"
  },
  [86402003] = {
    id = 86402003,
    name = "你和露露去魔术团所在地调查，发现他们并不是仅仅是一个魔术团，令整件事疑窦丛生......"
  },
  [86402004] = {
    id = 86402004,
    name = "第二天，杂耍团照常在集市广场开工，果然没一会儿，魔术团的人又来捣乱了，露露按计划用激将法，魔术师掉入了你布置的陷阱......"
  },
  [86402005] = {
    id = 86402005,
    name = "你和露露结伴前往魔术团的藏匿点，得知了魔术团真正的阴谋......"
  },
  [86402006] = {
    id = 86402006,
    name = "回到圈落后，你们和公会说了情况，公会感激你们阻止了一场阴谋，并邀请杂耍团表演节目......"
  },
  [86424001] = {
    id = 86424001,
    name = "你在路上碰到一个来回犹豫的公会成员，他拜托你帮忙调查据点的三大奇闻。"
  },
  [86424002] = {
    id = 86424002,
    name = "你和欧培拉回到据点后，公会人员来了解情况，欧培拉说出了对第一奇闻真相的猜测，而后欧培拉注意到一个行为鬼祟的人......"
  },
  [86424003] = {
    id = 86424003,
    name = "服务生跑到野外，你们碰见他正和一个黑衣人碰面......"
  },
  [86424004] = {
    id = 86424004,
    name = "你们找到幽灵魔物的目击者，他大谈圣水净化了他身体内的浊炁，你们听后决定亲自去会一会幽灵魔物，但在此前欧培拉的强迫症又犯了......"
  },
  [86424005] = {
    id = 86424005,
    name = "欧培拉跟你一起到有幽灵魔物的森林，看到奇景和巨型幽灵魔物，却被眼尖的欧培拉看出破绽，在抓住“幽灵魔物”后......"
  },
  [86424006] = {
    id = 86424006,
    name = "药剂师带你们到了废弃据点，药剂师告诉了你们制造奇闻竟然是因为一群孤儿......"
  },
  [86424007] = {
    id = 86424007,
    name = "无悔之路一片荒凉，仿佛没有尽头，你们在这里失去了时间概念，直到你背着体力耗尽的欧培拉，看到了终点前的一块石碑......"
  },
  [86433001] = {
    id = 86433001,
    name = "你遇到了探险者在抢劫普通人，于是上前帮忙，在看到有帮手后，探险者逃走，原来他们是来抢水的，因为水源被污染，他们不得不去更远的地方打水......"
  },
  [86433002] = {
    id = 86433002,
    name = "你和被救者回到据点，得知附近其实有其他水源，但被一波盗宝贼团伙垄断了，据点民众为了取水源被盗宝贼暴打回来，你看见少女安伦正在帮忙处理受伤的人......"
  },
  [86433003] = {
    id = 86433003,
    name = "你和安伦到达取水地，得知他们不愿意分水的原因。他们态度嚣张，安伦却安抚你暂时不要他们起冲突，这件事一定另有隐情......"
  },
  [86433004] = {
    id = 86433004,
    name = "你们一路灭杀魔物到达水源处，发现底部有一只巨大的魔物，你与安伦及时撤退，发现盗宝贼还跟在身后，于是心生一计......"
  },
  [86433005] = {
    id = 86433005,
    name = "有居民帮忙，你们利用地形优势追上盗宝贼一行，埋伏在潭水四周，等待盗宝贼诱出魔物后再行击杀，盗宝贼果然上当，好几人被魔物吓跑，但却没有像计划一样朝你们跑过来，而是调头冲向了另外一方的居民......"
  },
  [86433006] = {
    id = 86433006,
    name = "盗宝贼竟想拉居民挡魔物，你们救下群众，盗宝贼不敌魔物，求助你和安伦，你不为所动，他们以水源为条件找安伦求情，安伦亦不为所动，盗宝贼团伙受到严重重创，你与安伦联手击杀疲惫的魔物。"
  },
  [86433007] = {
    id = 86433007,
    name = "你们解决了水源和盗宝贼的问题，居民们对你们表达了感激，邀请你们参与篝火晚会，期间，安伦收到了小女孩送的小礼物，而你也收到了安伦的赠礼。"
  },
  [86443001] = {
    id = 86443001,
    name = "你到达某据点后，被热心接待，百姓一直在谈论德高望重的「圣父」，而此时，身边一个自称圣歌的女人想去见见这个「圣父」......"
  },
  [86443002] = {
    id = 86443002,
    name = "被赶出据点后，赦罪人向你道歉，但却和狂热的居民共情，这时传出求救声，你二人看到一群民众绑着受害者，要把他扔下悬崖......"
  },
  [86443003] = {
    id = 86443003,
    name = "你们送妇人回家，看见了他重病在床的儿子，圣父让她献祭放弃一切救回儿子，而赦罪人看出，那小孩并不是生病，而是中毒......"
  },
  [86443004] = {
    id = 86443004,
    name = "赦罪人和你一起打败魔物之后找到了药草，你们救醒了孩童，从他口中得知了圣父的许多恶行，妇人恍然大悟......"
  },
  [86443005] = {
    id = 86443005,
    name = "由于你们被赶出过据点一次，这次只能乔装进入，和群众一起以聆听圣谕为由，到圣父的面前......"
  },
  [86443006] = {
    id = 86443006,
    name = "赦罪人和你找到了地下室，里面除了不忍直视的惨状，还有许多研究器皿，赦罪人一个个帮他尝试，让他感受和民众们一样的痛苦，终于他受不了了......"
  },
  [86454001] = {
    id = 86454001,
    name = "你走在路上，遇到一个瑟缩的小女孩，小女孩给了你一根发带，她不敢靠近月蚀，希望你帮忙归还，你与小女孩谈话时，小女孩家长寻来，说起据点最近有行商失踪的事，你送两人一起前往据点。"
  },
  [86454002] = {
    id = 86454002,
    name = "你们到达据点后，小女孩带你找到了月蚀，你将发带还给她，得知月蚀接到委托，正在调查行商失踪的事，月蚀邀请你一起调查......"
  },
  [86454003] = {
    id = 86454003,
    name = "你和月蚀到失踪者家中找线索，月蚀发现一些疑点和细节，你在和月蚀推敲后，屋主人竟然在家中，他自称是失踪者的家人，但你发现了端倪......"
  },
  [86454004] = {
    id = 86454004,
    name = "你抓住了屋主人，原来「屋主人」是劫匪，顶替了原本屋主人，在你的审讯下，他吐露出了更大的秘密......"
  },
  [86454005] = {
    id = 86454005,
    name = "你和月蚀前往地窖探查，找到了对方真正的窝点，在制服劫匪首领后，你才知那些行商竟被炼成了魔法器具，被灰鼠等人假扮行商卖掉了......"
  },
  [86454006] = {
    id = 86454006,
    name = "你们追出地窖，追上了劫匪首领，他用魔法器具抵抗，几次交锋后，竟然被魔具中的浊炁侵蚀，逐渐变成了堕落者......"
  },
  [86609001] = {
    id = 86609001,
    name = "安妮斯采集了材料，打算和蒂娜一起进入据点休息，附近魔物异变，在战斗时，遇到一个冷淡的少女。"
  },
  [86609002] = {
    id = 86609002,
    name = "蒂娜认出少女燧影是公会的人，单独找到燧影谈话，燧影以机密任务冷淡回应，街上安妮斯正在治疗被浊炁侵蚀的居民，蒂娜发现了异常。"
  },
  [86609003] = {
    id = 86609003,
    name = "夜晚，蒂娜和安妮斯讨论据点的异常，听到外面异响，出门碰见燧影。燧影和她们一起去异响发生的地方，人们被惊醒，一路朝外逃窜，三人到达村庄广场，发现暗域正在急速形成。"
  },
  [86609004] = {
    id = 86609004,
    name = "暗域形成，尝试逃离者被无形壁垒阻挡。恐慌爆发，与此同时吸引来了大量魔物，燧影现身击杀魔物，蒂娜为保护安妮斯要送她离开，安妮斯不同意。"
  },
  [86609005] = {
    id = 86609005,
    name = "在恐慌和浊炁侵蚀下，许多居民和探险者变成了迷失者，守卫队长也成了堕落者，燧影和蒂娜一起将其击杀。"
  },
  [86609006] = {
    id = 86609006,
    name = "堕落者死亡，但暗域并没有消失，据点的人无法逃离，燧影要斩杀源头堕落者，但必须先确定暗域形成的原因，三人调查询问后，找到了线索，在确认地点后，三人前往暗域的核心区域。"
  },
  [86610001] = {
    id = 86610001,
    name = "圣诞气氛渐浓，小镇筹备庆典活动。安瑞丝和诺玛积极参加，准备好就出发！"
  },
  [86610002] = {
    id = 86610002,
    name = "两人在雪原寻找材料时，因为话痨的安瑞丝惊动了一群打窝的小魔物，两人追着魔物而去发现了一片美景，获得了第一个材料。"
  },
  [86610003] = {
    id = 86610003,
    name = "两人采集第二个材料时，安瑞丝不慎被粘住了脚，诺玛用了出色的解剖术分离了安瑞丝和粘连植物，两人小心翼翼地采集，还是出了意外，最后安瑞丝只能把半棵树背回营地。"
  },
  [86610004] = {
    id = 86610004,
    name = "营地人来人往，看到安瑞丝抱树都很惊奇，两人遇到了正与同伴们准备休息的你，在你的帮助下，安瑞丝和树成功分离了。"
  },
  [86610005] = {
    id = 86610005,
    name = "次日安瑞丝和诺玛再次出发寻找材料，发现你们已经离开，猜到你们会去圈落，安瑞丝认为应该给你们一份圣诞礼物，以此表达感谢，两人出发寻找礼物。"
  },
  [86610006] = {
    id = 86610006,
    name = "两人进入迷雾谷狩猎魔物，在成功击杀魔物之后，诺玛解剖魔物，将无用的一起装了起来，在路过圈落外时，几个拾荒小孩跟诺玛打招呼，诺玛将边角料给了他们，却收到了意外的礼物，是孩子们做的小手工，两人和小孩们道别，回到小镇家乡。"
  },
  [86476001] = {
    id = 86476001,
    name = "你意外击杀魔物之后，得到一件宝物，将这个宝物拿到鉴定市场，鉴宝人认为不值钱，被玛德莲否认，玛德莲想购买你的这件宝物，但细节需要详谈。"
  },
  [86476002] = {
    id = 86476002,
    name = "玛德莲约你到酒馆谈这笔交易，表明自己的身份，并想将宝物用于学术研究，在谈判中，玛德莲展示了优秀的谈判技巧，而后交易成功。"
  },
  [86476003] = {
    id = 86476003,
    name = "你出城后，遇到玛德莲与魔物战斗，和她一起杀掉魔物后，两人关系拉近。玛德莲提及她即将前往参加一个学术研讨会，认为你有资格一同前往，邀请你前去。"
  },
  [86476004] = {
    id = 86476004,
    name = "前往学术会议的旅途中，玛德莲并未停止她的研究，她记录深渊中事物的变化和发展，你也从各个角度分享了经验和见解，当晚扎营两人谈心，你了解了更多她的事。"
  },
  [86476005] = {
    id = 86476005,
    name = "两人走了很远，都没有到目的地，你疑惑学术研究为什么要选偏远的地方，玛德莲分享这次学术会议的情报，两人都认为此行可能不只是学术交流那么简单，决定互相照应，共享信息。"
  },
  [86476006] = {
    id = 86476006,
    name = "两人抵达了一座城堡之外，遇到了几位性格各异的学者，通过简短交谈，得知这次学术会议有重大发现和进步，两人怀着疑虑进入了守卫森严的城堡。"
  },
  [86611001] = {
    id = 86611001,
    name = "在缇法尼还不是无间狱首领的时候，她为了变强，自创了一种武技，抽取浊炁与魔法融合，威力强大但却十分伤身，她疯狂寻求副作用的解决之道，终于得知至亲血脉可作为浊炁的最佳容器，于是她决定孕育一个孩子。"
  },
  [86611002] = {
    id = 86611002,
    name = "她选中了暴食门首领梅斯。梅斯天才绝顶却冷漠无情，对生命缺乏敬畏，只对研究感兴趣。在缇法尼的精心设计下，缇法尼顺利接近了梅斯，并怀了梅斯的孩子，两人之间并无情爱，只有相互的算计与利用。"
  },
  [86611003] = {
    id = 86611003,
    name = "缇法尼成功怀孕。在整个孕期，她持续将体内淤积的浊炁导入胎儿体内。孩子诞生的那一刻，周身被浊炁萦绕，但缇法尼却感到前所未有的轻松，她发现婴儿体质的特殊性，决定用婴儿做实验。"
  },
  [86611004] = {
    id = 86611004,
    name = "缇法尼开启了一项实验，让人去寻找更多的实验品，在做实验期间，婴孩好几次濒死，缇法尼都只把她当作实验品毫无感情，直到缇法尼发现了新的突破口。"
  },
  [86611005] = {
    id = 86611005,
    name = "缇法尼用婴儿做实验想突破新的突破口，最终还是失败了，并且婴儿的四肢也都废掉了，她没有对女儿的爱，只有实验失败的惋惜，打算重新寻找更多的实验品，命人将婴儿丢弃。"
  },
  [86611006] = {
    id = 86611006,
    name = "雪莉正结束了一个任务，无意间看见了垃圾堆里爬行的婴儿，将她抱起，决定将婴儿救活。"
  },
  [86614001] = {
    id = 86614001,
    name = "朝雾喜欢宠物魔物，奈何价格昂贵，正当为钱发愁时，看到一份委托奖励丰盛，她接下委托后听老板说这个委托需要两人合作，并且另一人已经接下，她认为有人要分走奖励不开心。"
  },
  [86614002] = {
    id = 86614002,
    name = "朝雾前往矿洞，发现你在那里等待搭档。朝雾来后劝你离开，她自己也可以完成委托，但你是为帮公会调查异动才接下的委托，朝雾赶不走你，只能和你一起同行。"
  },
  [86614003] = {
    id = 86614003,
    name = "两人进入矿洞后，遭遇了一群魔物，在战斗中，你与朝雾从陌生到默契，并在洞窟深处遇见了逃难到这里的学者。"
  },
  [86614004] = {
    id = 86614004,
    name = "学者被你们吓了一跳，看清之后申请你们的庇护，声称知道一条安全的近路，可以拿到宝藏。你识破其谎言但选择将计就计，与朝雾假意跟随，被引至封印之地。"
  },
  [86614005] = {
    id = 86614005,
    name = "学者启动机关，惊醒了沉睡魔物，并逃走。你和朝雾将魔物艰难困在了一个地方，追上学者。"
  },
  [86614006] = {
    id = 86614006,
    name = "两人在矿洞最深处追上学者，看到学者在研究怎么开始宝藏所在地，这时魔物追击而来，两人联合抵抗，杀掉魔物的时候引发坍塌，三人一同坠入地宫。"
  },
  [86615001] = {
    id = 86615001,
    name = "你接受了一个委托，勘察深渊二层的一个新地形，到了某个山坳里发现了美景，与鎺相遇，鎺看见你手中绘制的地图，邀请你和她一起喝茶。"
  },
  [86615002] = {
    id = 86615002,
    name = "你和鎺喝茶交谈时，发现鎺对深渊地理了解很深，而且她也在绘制一份路径图，想和你合作，你拿出自己的探险地图，发现彼此的地图可以完美互补，决定与鎺合作完成地图。"
  },
  [86615003] = {
    id = 86615003,
    name = "在对完地图后，鎺和你去往地图上没有的两处陌生区域。一路上，你得知鎺是一个名为雪村的鎺家继承人，这次的绘制地图，也是考验之一。"
  },
  [86615004] = {
    id = 86615004,
    name = "两人到达第一处区域，看到了大量的小魔物，这些小魔物都无害，在一一记录后，在谈话中，鎺将深渊当作自己的家园，而你也发现了深渊的多样性。"
  },
  [86615005] = {
    id = 86615005,
    name = "两人到达第二处陌生区域的时候，遇到了驻守此地的魔物，在两人合力清除隐患后，你发现她的武技你从没见过，你们回到茶棚完成了剩下的地图。"
  },
  [86615006] = {
    id = 86615006,
    name = "鎺为感谢你，泡起樱花茶，和你一起赏月，并向你介绍了她与同伴们创立的雪折邸，希望之后能和你一起探险。最后，鎺邀请你参加雪村的赏花节。你欣然接受。"
  },
  [86474001] = {
    id = 86474001,
    name = "你在据点休息的时候，被公会成员拜托寻找朋友，你同意和公会成员前往，在补给营地遇到了司礼者，她也在找寻同伴。"
  },
  [86474002] = {
    id = 86474002,
    name = "你与司礼者交换情报，发现失踪者与圣歌同伴最后前往的方向完全一致，决定一起前行。"
  },
  [86474003] = {
    id = 86474003,
    name = "三人到达了森林入口的营地，调查营地的线索和痕迹，找到了大致的方向，发现这些人都是自行前往森林的。"
  },
  [86474004] = {
    id = 86474004,
    name = "三人根据营地的线索到达了一个森林外围的祭坛，祭坛上有个人晕过去。被救醒后说看见了失踪者们，他们举止异常，开启了传送阵。几人根据线索判断传送阵在森林深处，于是一同前往。"
  },
  [86474005] = {
    id = 86474005,
    name = "几人向森林出发，看到一些不同寻常的魔物，这些魔物都有吐丝裹茧子的属性，吉姆与探险者看见危机不敢再前进，于是你和司礼者共同前往。"
  },
  [86474006] = {
    id = 86474006,
    name = "两人深入森林，看到了森林里挂满了很多茧，两人穿梭在茧林中，最终找到了同伴的标记，通往一个茧丝做的巨大洞口，在交流之后，两人决定跳下去营救同伴。"
  },
  [86483001] = {
    id = 86483001,
    name = "你在深渊探险时，意外在塌陷的石室中发现了一坛美酒。想到好酒的陆大叔后，你决定带着它去拜访陆玄。"
  },
  [86483002] = {
    id = 86483002,
    name = "你来到陆玄的临时落脚点，还没开口陆玄便注意到了你的异样。不等你休息就让你陪他过几招，你只得将酒放在一旁，被迫接受陆玄的“指点”。"
  },
  [86483003] = {
    id = 86483003,
    name = "在陆玄指点下，你开始尝试改变战斗方式，从单纯进攻转为寻找时机，逐步理解战斗节奏与判断的重要性。"
  },
  [86483004] = {
    id = 86483004,
    name = "你与陆玄共饮美酒，陆玄确认此酒并非深渊之物。美酒特殊气息引发陆玄短暂失神，也唤起他对过往的模糊记忆。"
  },
  [86483005] = {
    id = 86483005,
    name = "你提及深渊中魔物异常与环境变化，陆玄虽表面敷衍却明显知情，并隐约提到一个比深渊更“热闹”的地方。"
  },
  [86483006] = {
    id = 86483006,
    name = "随着一些记忆缓缓被唤醒，陆玄开始提及一些让你感到陌生的词汇，并提到一个与深渊不同的世界——云海道域。"
  },
  [86483007] = {
    id = 86483007,
    name = "陆玄向你讲述了一些云海道域的基本情况，让你对那个修士纵横、宗门林立的世界有了一个模糊的印象。"
  },
  [86444001] = {
    id = 86444001,
    name = "浮光正执行深渊航线的委托，意外遇到一头棘手的魔物。焦灼之际，你突然出现，协助浮光解决了眼前的危机。"
  },
  [86444002] = {
    id = 86444002,
    name = "得知你的身份后，浮光不再那么戒备。在你的提议下，你们决定一起前往商业据点。"
  },
  [86444003] = {
    id = 86444003,
    name = "赶路途中，你们遇到一支小型商队正被劫匪围攻。不待你提议，浮光便主动提出营救。在你们默契地配合下，劫匪被轻松击溃。"
  },
  [86444004] = {
    id = 86444004,
    name = "完成委托后，浮光正准备在商业据点逛一逛，此前确认委托的商人却突然找了过来。商人表示自己还有一桩委托，希望能由浮光亲自执行。"
  },
  [86444005] = {
    id = 86444005,
    name = "你刚逛完几家熟悉的店铺，便发现了四处张望的浮光。浮光告诉你自己私自承接了一个委托，因为担心自己无法完成，希望能得到你的协助。"
  },
  [86444006] = {
    id = 86444006,
    name = "你向商人详细了解的护送的内容和要求，初步判断后，决定和浮光一起执行本次委托。"
  },
  [86616001] = {
    id = 86616001,
    name = "艾格尼丝前往素材商店购买物资，为接下来的修行做准备。在素材商店内，她意外发现了一份修行笔记。为了获得修行笔记，她自告奋勇帮老板解决麻烦。"
  },
  [86616002] = {
    id = 86616002,
    name = "艾格尼丝太过沉迷修行，待她反应过来时，才发现已经快到和商人约定的时间了。为了能准时赶到约定地点，她决定抄近路。"
  },
  [86616003] = {
    id = 86616003,
    name = "穿越峡湾时，艾格尼丝发现这里地形复杂，魔力流动不稳定。尽管她已经很谨慎地行动了，依然不小心踏入一个空间封锁结界。"
  },
  [86616004] = {
    id = 86616004,
    name = "结界的精妙设计让艾格尼丝惊叹，但为了尽快脱困，她决定暴力破解结界。"
  },
  [86616005] = {
    id = 86616005,
    name = "尝试暴力破解结界无果，艾格尼丝只得按照规则破解结界。经过一番尝试，她终于找到了结界的破绽所在。"
  },
  [86616006] = {
    id = 86616006,
    name = "反复尝试后，艾格尼丝终于开辟出离开结界的通道，可是时间浪费了很多。为了赶路，艾格尼丝没有完全破解结界，而是准备让结界自行崩溃，不再困住行人。"
  },
  [86617001] = {
    id = 86617001,
    name = "你结束探险回到据点，发现桌上放着一封来自雪村的邀请信。你决定找鎺商量同行事宜，鎺却因家族委托无法立刻出发，你只好先行一步。"
  },
  [86617002] = {
    id = 86617002,
    name = "为表心意，你翻阅探险记录，锁定了一头头目级魔物“雪兽”。经过一番激战，你成功将其讨伐，取下珍贵的尾肉与素材，带着礼物踏上前往雪村的路。"
  },
  [86617003] = {
    id = 86617003,
    name = "前往雪村的道路上，成群结队的探险者络绎不绝。有人讨论狩猎祭的奖励，有人结伴壮胆。你婉拒了所有同行邀请，按照自己的节奏独自前进。"
  },
  [86617004] = {
    id = 86617004,
    name = "越接近雪村，魔物活动越发频繁。你接连遭遇袭击，清理挡路的魔物。虽然战斗不断，但周围的探险者们似乎对此习以为常，并不紧张。"
  },
  [86617005] = {
    id = 86617005,
    name = "前方传来激烈的战斗声，几名探险者被魔物包围。你出手相助，从他们口中得知：每年狩猎祭前后，雪村都会故意吸引魔物聚集，方便集中清剿。"
  },
  [86617006] = {
    id = 86617006,
    name = "临近雪村的最后路段，你遭遇了一波远超常规规模的魔物袭击。其中混杂着数头精英级魔物，数量之多已超出普通探险者的承受范围。"
  },
  [86617007] = {
    id = 86617007,
    name = "你终于到达雪村外围。奇怪的是，靠近村落后魔物的活动反而变得规律有序，仿佛被某种力量压制。你带着几分不安，踏入了这座传闻中的“隐秘之乡”。"
  },
  [86620001] = {
    id = 86620001,
    name = "沉寂许久的星陨之塔忽然再次产生异动。面对这件始终无法解析的古老圣物，你试图寻找其中隐藏的秘密，却只感受到一股混乱而残缺的力量。为了查明异动的来源，你决定前往孤儿院，向最信任的人寻求帮助。"
  },
  [86620002] = {
    id = 86620002,
    name = "从默尔曼那里，你得知星陨之塔远比想象中更加古老，其中残留着时间与空间的力量。然而即便见多识广的她，也无法解读圣物真正的秘密。在她的建议下，你决定拜访陆玄，寻求更多线索。"
  },
  [86620003] = {
    id = 86620003,
    name = "面对神秘的星陨之塔，陆玄同样无法看穿其本质，但却确认了它与时间、空间存在联系。同时，他也提醒你，与其研究圣物本身，不如去请教曾经被封印于塔中的三位少女。"
  },
  [86620004] = {
    id = 86620004,
    name = "为了调查星陨之塔，你拜访了莎尔拉、莉莉安与玛琳娜。虽然三人的记忆早已残缺不全，但关于星陨之塔的只言片语，依旧拼凑出部分真相。而玛琳娜提出的一个猜想，则让事情迎来了新的转机。"
  },
  [86620005] = {
    id = 86620005,
    name = "为了验证猜测，莎尔拉主动以自己的鲜血尝试唤醒星陨之塔。沉睡已久的圣物终于产生回应，而伴随着光芒出现的，则是一段被时间掩埋的陌生过往。"
  },
  [86620006] = {
    id = 86620006,
    name = "继莎尔拉之后，莉莉安也选择以鲜血唤醒星陨之塔。随着更多记忆碎片浮现，你们不仅看见了莉莉安遗失的过去，更发现她与莎尔拉之间，似乎存在着某种早已被遗忘的联系。"
  },
  [86620007] = {
    id = 86620007,
    name = "零散的记忆碎片证明了方向正确，却也让更多谜团浮出水面。为了彻底揭开星陨之塔隐藏的秘密，你们决定进行一次大胆地尝试。当鲜血与圣物的力量交汇之时，一段跨越时间与空间的往事，也即将重现于世。"
  },
  [86621001] = {
    id = 86621001,
    name = "阿芙佳朵在自由学派集会中心休整时，得知北方丘陵地区有一个废弃遗迹，最近那里出现了不少魔物。出于好奇，她决定接下委托，独自前往探查。"
  },
  [86621002] = {
    id = 86621002,
    name = "深入遗迹调查后，阿芙佳朵发现这里并非普通废墟，隐藏在岁月之下的痕迹，似乎记录着一段不为人知的过去。"
  },
  [86621003] = {
    id = 86621003,
    name = "在探索遗迹深处时，阿芙佳朵触发了隐藏机关，并遭遇守护秘密的强大魔物。经过一场战斗，她终于找到了遗迹真正隐藏的区域。"
  },
  [86621004] = {
    id = 86621004,
    name = "在遗迹密室中，阿芙佳朵发现了一张通往黄沙深处的藏宝图。同行的探险者果断将藏宝图让与阿芙佳朵，表示只有她这样实力出色的探险者，才有能力去追寻。"
  },
  [86621005] = {
    id = 86621005,
    name = "面对金币、素材等报酬，阿芙佳朵选择了那份真假未知的地图。对她而言，比起财富，更吸引人的是隐藏在传闻背后的故事。"
  },
  [86621006] = {
    id = 86621006,
    name = "做好准备后，阿芙佳朵带着藏宝图前往黄沙区域。新的旅程即将开始，而等待她的，将是一段意想不到的冒险。"
  },
  [86622001] = {
    id = 86622001,
    name = "探险队收到情报，距离驻扎地不远的地方发现了一个新的遗迹。由于休假原因，大部分成员都不在，留在驻地修行的姬玛决定同你一起去调查一番。"
  },
  [86622002] = {
    id = 86622002,
    name = "你和姬玛来到情报所在地，发现这里有不少魔物活动。姬玛主动提议由自己解决，检验最近的修行成果。"
  },
  [86622003] = {
    id = 86622003,
    name = "解决完魔物后，你们进入了遗迹，发现这里其实是一个天然形成的奇异场所。姬玛对此大为惊叹，毫不掩饰自己对深渊中这些神秘景象的憧憬。"
  },
  [86622004] = {
    id = 86622004,
    name = "探索途中，姬玛和你谈起自己踏上探险之路的另一个原因——想要战胜自己的“宿敌”。曾经为了超越对方而不断努力的她，如今已经明白，真正重要的不只是胜负，而是在不断前进的过程中成为更好的自己。"
  },
  [86622005] = {
    id = 86622005,
    name = "遗迹深处突然出现了一群如同幽灵的怪异魔物，姬玛虽然初见时受到惊吓，但很快调整好了状态。成功击败这些魔物后，你们发现前方似乎隐藏着更加重要的秘密。"
  },
  [86622006] = {
    id = 86622006,
    name = "遗迹中心区域，是一个宛如梦境的奇幻世界。为了进一步探查这个区域的情报，姬玛决定稍微冒些风险。"
  },
  [86623001] = {
    id = 86623001,
    name = "亡灵庆典将至，大量探险者聚集圈落，公会中的委托几乎被一扫而空。然而一份与亡灵有关的特殊委托却无人愿意接取。面对附近居民可能遭遇的危险，公会成员最终决定寻找曾经的守夜人——罗蕾娜。"
  },
  [86623002] = {
    id = 86623002,
    name = "公会成员找到罗蕾娜，希望她能够处理废弃村庄中的亡灵事件。然而已经离开守夜人的罗蕾娜并不愿再次承担过去的职责。在公会成员的请求下，她最终决定调查此事，而那把象征守夜人的短剑，也再次被她握在手中。"
  },
  [86623003] = {
    id = 86623003,
    name = "罗蕾娜来到废弃村庄调查亡灵事件，却发现这里并没有想象中的强烈怨念。在探索过程中，她意外发现一个躲藏在废墟中的小女孩。面对罗蕾娜的询问，小女孩似乎隐藏着一些关于亡灵的秘密。"
  },
  [86623004] = {
    id = 86623004,
    name = "随着夜幕降临，废弃村庄中的灵力开始异常活跃。在调查中，罗蕾娜发现了这里会聚集亡灵的原因。为了彻底解决问题，罗蕾娜提前布置战场，准备独自面对即将出现的亡灵群。"
  },
  [86623005] = {
    id = 86623005,
    name = "亡灵群在夜晚出现，罗蕾娜凭借守夜人的力量展开战斗。面对失去意识、只剩本能的亡灵，她最终选择将它们消灭。然而就在她准备处理最后一只亡灵时，莱伊突然出现，请求她不要伤害那个特殊的存在。"
  },
  [86623006] = {
    id = 86623006,
    name = "莱伊向罗蕾娜讲述了自己与那只善意亡灵之间的相遇，也揭示了自己能够看见亡灵的特殊能力。得知莱伊所在村庄附近也出现大量亡灵后，罗蕾娜决定帮助她解决异常。"
  },
  [86624001] = {
    id = 86624001,
    name = "探险归途，薇意外进入了一处由亡灵布下的特殊结界。薇尝试破解结界，而隐藏在山谷中的亡灵，也逐渐向她靠近。"
  },
  [86624002] = {
    id = 86624002,
    name = "为了离开结界，薇不断尝试寻找破解的方法。然而结界中的亡灵似乎察觉到了她的行动，不断发动袭击，让她无法集中精神调查。虽然薇凭借强大的魔法一次次击退亡灵，但局势却逐渐变得不利。"
  },
  [86624003] = {
    id = 86624003,
    name = "面对不断袭来的亡灵，薇的体力逐渐下降，破解结界也陷入停滞。就在她陷入困境时，一只特殊的亡灵出现在她面前。与其他充满敌意的亡灵不同，它似乎正在向薇传达某种信息。经过短暂犹豫，薇决定相信这个神秘的亡灵。"
  },
  [86624004] = {
    id = 86624004,
    name = "在亡灵的帮助下，薇成功离开了困住自己的结界。薇向它表达感谢，同时也为曾经误会它而道歉。"
  },
  [86624005] = {
    id = 86624005,
    name = "回到据点休整的薇，从旅店老板那里得知了附近发生的异常。随着亡灵庆典临近，大量亡灵开始活跃，不仅影响了山谷道路，也让据点居民受到困扰。"
  },
  [86624006] = {
    id = 86624006,
    name = "据点中的人们终于找到了一名强大的探险者，准备消灭山谷中的亡灵。薇虽然为大家安心而感到高兴，但她无法忘记那些善意的亡灵。经过思考，她决定在对方到来之前，尝试用一种古老的方法——引渡，送所有亡灵进入轮回。"
  },
  [86627001] = {
    id = 86627001,
    name = "深渊第一、二层交界地带传出圣物「厄运之匣」的传闻——能洗净厄运，却只有霉运缠身之人才能靠近，公会与塔同时盯上了它。"
  },
  [86627002] = {
    id = 86627002,
    name = "公会确认霉运缠身的菲欧最适合触碰圣物，菲欧接下委托，与主角、蒂娜一同前往交界地带。"
  },
  [86627003] = {
    id = 86627003,
    name = "前往交界地途中与安妮斯汇合，安妮斯自认灾祸魔女，菲欧却毫不在意，两个被厄运标记的人意外合拍。"
  },
  [86627004] = {
    id = 86627004,
    name = "临近交界地带时，缇法尼率无间狱截胡——圣物关乎她毕生研究的「理智堕落者」实验，菲欧沦为被争抢的钥匙。"
  },
  [86627005] = {
    id = 86627005,
    name = "圣物现世，菲欧在多方注视下触碰「厄运之匣」——厄运被吸走，她第一次感到不倒霉。"
  },
  [86627006] = {
    id = 86627006,
    name = "被吸走的厄运转嫁到安妮斯身上，菲欧怔住——这违背她信奉的运气守恒，悬念就此埋下。"
  },
  [86628001] = {
    id = 86628001,
    name = "据点内，逐幻者像往常一样逛街吃喝，听人热议「变幻的奇景」的传闻。她对秘宝毫无兴趣，却对那片从未被人完整记录过的奇异区域动了心。"
  },
  [86628002] = {
    id = 86628002,
    name = "回到探险队，逐幻者与主角聊起传闻，说想去看那片区域本身。主角注意到她难得认真，提议结伴同行，逐幻者爽快答应。"
  },
  [86628003] = {
    id = 86628003,
    name = "出发前夜，逐幻者一反常态地仔细检查装备、研究路线。主角问起，她只说难得有个有意思的地方，当然要认真一点。"
  },
  [86628004] = {
    id = 86628004,
    name = "赶路途中，二人迎面遇上一支寻宝队，领头者正是当年打劫过逐幻者的那伙无良探险者。逐幻者表面笑盈盈地糊弄过去，主角却察觉她眼底的神色不对。"
  },
  [86628005] = {
    id = 86628005,
    name = "深入奇异区域后，景色不断变幻、颠覆常识。逐幻者兴奋又专业地观察记录，尽显真正探险者的做派；寻宝队的身影却在暗处若隐若现。"
  },
  [86628006] = {
    id = 86628006,
    name = "抵达区域核心附近，二人窥见所谓秘宝的真相——它不是财宝，而是这片区域孕育出的活的奇观。与此同时寻宝队现身拦截，逐幻者决定新账旧账一起算。"
  },
  [86629001] = {
    id = 86629001,
    name = "圣诞节即将到来，但铁壁城里的探险者们依旧忙着为下一次冒险做准备。对他们来说，圣诞节似乎并没有那么重要。"
  },
  [86629002] = {
    id = 86629002,
    name = "吉光询问大家为什么不过圣诞节，却发现每个人都有必须继续前进的理由。或许，他们只是已经习惯了不停下脚步。"
  },
  [86629003] = {
    id = 86629003,
    name = "望着远去的探险者，吉光想起了小时候听过的冒险故事。几番思索后，她决定自己担任圣诞老人，为忙碌的大家筹办圣诞庆典。"
  },
  [86629004] = {
    id = 86629004,
    name = "既然要当圣诞老人，当然要准备礼物。可当吉光问遍所有人的愿望后，却发现大家想要的似乎全都是冒险所需的东西。"
  },
  [86629005] = {
    id = 86629005,
    name = "比起询问大家想要什么，吉光开始追问另一个问题——他们当初为什么成为探险者？那些被遗忘的愿望，或许才是圣诞节真正应该带来的东西。"
  },
  [86629006] = {
    id = 86629006,
    name = "礼物、圣诞树、美食......一切都准备好了。可就在圣诞节当天，新的遗迹被发现，所有探险者再次踏上旅途。于是，吉光决定亲自去找他们。"
  },
  [86630001] = {
    id = 86630001,
    name = "多年前的新年夜，你在少年时路过一座小城，帮少女露西亚点亮将熄的灯；临别，你留下一句「世界上还有各种各样的灯，你应该出去看看，我们总有一天相遇的话，你可以讲给我听」。"
  },
  [86630002] = {
    id = 86630002,
    name = "多年后，炉火镇岁火祭将近，灯油断货、浊炁异动，公会发布委托。同行者嫌报酬低、要回家过年纷纷拒单，最终只有主角独自接下委托，也想去看看那位守了一辈子岁火的老守火人。"
  },
  [86630003] = {
    id = 86630003,
    name = "主角抵达炉火镇，正逢新年灯市。采购灯油时，听闻「守灯人」的传闻——一个每到一地先看灯的女法师，她说：灯是人们愿望的象征。"
  },
  [86630004] = {
    id = 86630004,
    name = "广场中央，露西亚正为岁火添灯油。她对主角说话的语气像见着老友，说这里是「最后一站」——看完了这里的灯，就该把看过的灯讲给那个人听了。"
  },
  [86630005] = {
    id = 86630005,
    name = "入夜，岁火忽然明灭不定。露西亚神色凝重，断定岁火在害怕——有东西在偷走灯里托付的愿望，取走愿望的浊炁越吃愿望就越强。"
  },
  [86630006] = {
    id = 86630006,
    name = "深夜，露西亚提着旧提灯独自巡接，因为浊炁的而感到不安，在主角的鼓励下露西亚燃起了守护之心，和主角一起守护岁火，守护期待与希望。"
  },
  [86631001] = {
    id = 86631001,
    name = "刚交完护送委托，队伍下一站本就往铃穗镇方向，顺路到据点委托板挑趟短活；尼莉莎挑了张报酬最高、看着最轻松的庆典护卫委托，没看条款就签了名；蒂娜被安妮斯拜托，一同前往。"
  },
  [86631002] = {
    id = 86631002,
    name = "主角团抵达正在筹备庆典的铃穗镇；主办方核对名单，报出的正是她俩的名字——排练表和戏服尺寸早已备好。"
  },
  [86631003] = {
    id = 86631003,
    name = "老匠人捧出积压多年的两副主角面具，两人戴上意外服帖；老匠人一句「终于等到人了」，并留下「戴上面具的人会比平常坦率些」的传说。"
  },
  [86631004] = {
    id = 86631004,
    name = "尼莉莎嫌小红帽的故事到处是麻烦，蒂娜却把大灰狼的台词研究了个透；两人互相挑刺，又各自偷偷认真起来。"
  },
  [86631005] = {
    id = 86631005,
    name = "戴上面具的蒂娜吓哭了孩子，慌忙摘面具哄人；尼莉莎被孩子围住喊「小红帽姐姐」，嘴上嫌弃、人却蹲了下来。"
  },
  [86631006] = {
    id = 86631006,
    name = "两人各自躲起来偷偷排练被主角撞破，一个说只是在试衣服，一个说只是确认语气；天亮，面具被放回木匣，巡礼就要开始。"
  },
  [86700001] = {
    id = 86700001,
    name = "清剿魔物"
  },
  [86700002] = {
    id = 86700002,
    name = "散落的线索"
  },
  [86700003] = {
    id = 86700003,
    name = "物资搜索"
  },
  [86700004] = {id = 86700004, name = "路牌"},
  [86700005] = {id = 86700005, name = "秘境"},
  [86700006] = {
    id = 86700006,
    name = "寻幽探秘"
  },
  [86700007] = {
    id = 86700007,
    name = "强敌来袭"
  },
  [86700008] = {
    id = 86700008,
    name = "混乱冰脊"
  },
  [86700009] = {id = 86700009},
  [86700010] = {
    id = 86700010,
    name = "丛林秘境"
  },
  [86700011] = {id = 86700011},
  [86700012] = {
    id = 86700012,
    name = "炎流之涡"
  },
  [86700013] = {id = 86700013},
  [86700014] = {
    id = 86700014,
    name = "前往新区域"
  },
  [86700015] = {
    id = 86700015,
    name = "深渊先遣队"
  },
  [86700016] = {
    id = 86700016,
    name = "山岭探索"
  },
  [86700101] = {
    id = 86700101,
    name = "失落秘境"
  },
  [86700102] = {
    id = 86700102,
