  [86741164] = {
    id = 86741164,
    name = "商店中可以选择的宝物数量增加1"
  },
  [86751001] = {
    id = 86751001,
    name = "在辉月之下，没有谁可以更改已注定的命运。"
  },
  [86751002] = {
    id = 86751002,
    name = "传说中与星辰和月光共舞的神奇生物的尾羽，经历了月光和星辰能量的滋养，拥有不朽的魔力。"
  },
  [86751003] = {
    id = 86751003,
    name = "女神为勤劳的人们赐下的徽章，通体光芒夺目，蕴含强大力量。"
  },
  [86751004] = {
    id = 86751004,
    name = "相传是原初之树的断枝，在断裂后仍然不朽。"
  },
  [86751005] = {
    id = 86751005,
    name = "带上它，它会为你冲锋陷阵，直至毁灭。"
  },
  [86751006] = {
    id = 86751006,
    name = "摇动铜铃时听不到任何声响，却能感受心底的希冀。"
  },
  [86751007] = {
    id = 86751007,
    name = "水火相生相融的徽记，奇异而美丽的花。"
  },
  [86751008] = {
    id = 86751008,
    name = "历经了悠久的岁月，仍然崭新如故的怀表，偶然浮现的画面，倒映着一片陌生的天地。"
  },
  [86751009] = {
    id = 86751009,
    name = "某古老部族先知的手镯，有着不可言说的力量。"
  },
  [86751010] = {
    id = 86751010,
    name = "深渊某处神殿发现的一块石板，沐浴在神像下千百年，据说有预知危机的能力。"
  },
  [86751011] = {
    id = 86751011,
    name = "令人进入短暂沉思之境的魔法书，能解锁未知的魔法。"
  },
  [86751012] = {
    id = 86751012,
    name = "黑暗中的光消失之时，天空落下雷霆，照亮前进的路。"
  },
  [86751013] = {
    id = 86751013,
    name = "一朵永不衰败的花。它诞生于星辰陨灭，从深渊挣扎而出。"
  },
  [86751014] = {
    id = 86751014,
    name = "冷静思考的能力，是一切智慧的开端。"
  },
  [86751015] = {
    id = 86751015,
    name = "它早已死亡，却以另一种方式永恒存在。"
  },
  [86751016] = {
    id = 86751016,
    name = "放在耳边，似乎能听见海妖在悲戚地歌唱，不断回响。"
  },
  [86751017] = {
    id = 86751017,
    name = "幸运是机会的影子，抓住它，就能抓住机遇。"
  },
  [86751018] = {
    id = 86751018,
    name = "你永远不知道，下一刻帽子里面会出现什么。"
  },
  [86751019] = {
    id = 86751019,
    name = "它可以锁住恐惧，锁住痛苦，却无法锁住希望。"
  },
  [86751020] = {
    id = 86751020,
    name = "看似平平无奇，却拥有令人无法忽视的魅力。"
  },
  [86751021] = {
    id = 86751021,
    name = "流落在遗迹世界的神秘袋子，其内的物资令人好奇。"
  },
  [86751022] = {
    id = 86751022,
    name = "华丽精致的音乐盒，播放着诡异飘渺的童谣。"
  },
  [86751023] = {
    id = 86751023,
    name = "恶龙折断了翅膀，被蜕下龙鳞，用鲜血浇筑成了诅咒的盒子。"
  },
  [86751024] = {
    id = 86751024,
    name = "据传这枚纹章能发挥探险者的最大潜力，但也很容易迷失自我。"
  },
  [86751025] = {
    id = 86751025,
    name = "朝圣者的脚步不会停歇，他带着神赐的头冠，走向黎明。"
  },
  [86751026] = {
    id = 86751026,
    name = "传说将海妖的眼泪带在身上，也会拥有与海妖同样蛊惑人心的能力。"
  },
  [86751027] = {
    id = 86751027,
    name = "五彩斑斓的水晶，能将能量转化为实物。"
  },
  [86751028] = {
    id = 86751028,
    name = "瓶中的景观精巧细致，宛如另一方世界。"
  },
  [86751029] = {
    id = 86751029,
    name = "不论你通过它得到了什么，不用客气，这是你应得的。"
  },
  [86751030] = {
    id = 86751030,
    name = "向神灯许下心愿时，它会喷出烟雾给予模糊的指引。"
  },
  [86751031] = {
    id = 86751031,
    name = "轻盈而柔软的毯子，可以载人飞行，但限载重量较小。"
  },
  [86751032] = {
    id = 86751032,
    name = "遵循它的指引，终会得见黎明。"
  },
  [86751033] = {
    id = 86751033,
    name = "埋葬在深渊中的宝石，仿佛藏着整个星空。"
  },
  [86751034] = {
    id = 86751034,
    name = "不知名材质的骰子，每一面都铭刻着古老的符文。"
  },
  [86751035] = {
    id = 86751035,
    name = "黄金浇筑的盔甲只剩下残缺的手套，连它的主人也不知去向。"
  },
  [86751036] = {
    id = 86751036,
    name = "除了杀死身体，连精神也要一同摧毁的秘宝。"
  },
  [86751037] = {
    id = 86751037,
    name = "一把可以探测方位的舵，指引着旅程的航向。"
  },
  [86751038] = {
    id = 86751038,
    name = "充满谜团的面具，听闻有人戴着它寻到了稀有的秘宝。"
  },
  [86751039] = {
    id = 86751039,
    name = "一枚闪耀的佩饰，散发着月华的光芒。"
  },
  [86751040] = {
    id = 86751040,
    name = "通过它，能窥见漫天星河。"
  },
  [86751041] = {
    id = 86751041,
    name = "传闻中圣者的法器，他深受人民拥护，却一生孤独。"
  },
  [86751042] = {
    id = 86751042,
    name = "汇聚着燃烧星火的灯，点亮它，照亮前进的路。"
  },
  [86751043] = {
    id = 86751043,
    name = "一个用不停歇转动的星盘，无法用来引导方向，但能指示命运。"
  },
  [86751044] = {
    id = 86751044,
    name = "疾驰的流星缠绕着命运的光影，群星之环叩问着宇宙的未来。"
  },
  [86751045] = {
    id = 86751045,
    name = "蕴藏着奇异力量的卡牌，据传得到它的人将被命运眷顾。"
  },
  [86751046] = {
    id = 86751046,
    name = "古老而神秘的玉璧，镌刻在剑上的神谕无人能解。"
  },
  [86751047] = {
    id = 86751047,
    name = "从天而降的神杵，那是世界终末的审判。"
  },
  [86751048] = {
    id = 86751048,
    name = "以未知的金属打造，从造型与材质来看都不属于这个时代。"
  },
  [86751049] = {
    id = 86751049,
    name = "一对具有诅咒的锁环，使得靠近者都会受到它的伤害。"
  },
  [86751050] = {
    id = 86751050,
    name = "当它砸落时，会将整个星空灼亮。"
  },
  [86751051] = {
    id = 86751051,
    name = "古旧神坛中遗留的骨片，上方刻印着模糊不清的文字。"
  },
  [86751052] = {
    id = 86751052,
    name = "可以轻易撕裂空气的拳刺，它感应主人的意念，也吞噬主人的意志。"
  },
  [86751053] = {
    id = 86751053,
    name = "枪尖如雪山之巅的孤峰，直刺苍穹。"
  },
  [86751054] = {
    id = 86751054,
    name = "相传是勇者陨落前留下的断剑，能够轻易刺穿一切阻碍。"
  },
  [86751055] = {
    id = 86751055,
    name = "荒原尽头的花化为了金银，永存不灭。"
  },
  [86751056] = {
    id = 86751056,
    name = "绝望中的祈祷唤醒了风铃。它聆听着夙愿，将希冀传到更远的地方。"
  },
  [86751057] = {
    id = 86751057,
    name = "晦暗的月光映入了森林，炉中的香气引诱着猎物。"
  },
  [86751058] = {
    id = 86751058,
    name = "流浪者在硝烟与尘沙中消亡，他们不甘地伸出手，想抓住每一个过路的人陪葬。"
  },
  [86751059] = {
    id = 86751059,
    name = "长着金翅的靴子，据说能踏空作战，但并不能原地起飞。"
  },
  [86751060] = {
    id = 86751060,
    name = "拿起它，举弓逐猎的幻影朝你投来微笑，她将与你共同作战。"
  },
  [86751061] = {
    id = 86751061,
    name = "战死的勇士睁着双眼，紧握着它，期盼能拦下每一个入侵者。"
  },
  [86751062] = {
    id = 86751062,
    name = "杀死魔物的第一滴血永远留在了武器上。"
  },
  [86751063] = {
    id = 86751063,
    name = "它吞噬了铸造者的血肉，带去更多的死亡。"
  },
  [86751064] = {
    id = 86751064,
    name = "据说是远古神庙坍塌后留下的一颗钉子，有古庙遗存的魔力。"
  },
  [86751065] = {
    id = 86751065,
    name = "沉睡于戒指中的力量，被炽热的信念惊醒。"
  },
  [86751066] = {
    id = 86751066,
    name = "神话中第一只神鸟，为驱散黑暗，填补深渊裂缝而死。"
  },
  [86751067] = {
    id = 86751067,
    name = "古蚺的眼球化成的宝珠，它的出现总是伴随着无数的考验和磨难。"
  },
  [86751068] = {
    id = 86751068,
    name = "预言家能看到他人的死生，但看不到自己的未来。"
  },
  [86751069] = {
    id = 86751069,
    name = "永不沉寂的海浪，传达着从远古带来的歌谣。"
  },
  [86751070] = {
    id = 86751070,
    name = "一把能挥舞出幻觉的双刺，唤醒了沉睡的愚民。"
  },
  [86751071] = {
    id = 86751071,
    name = "刻划了某种符号的石板，藏着不为人知的奥秘。"
  },
  [86751072] = {
    id = 86751072,
    name = "飞鸟衔着羽毛献礼，众生欢欣踊跃，庆贺新生。"
  },
  [86751073] = {
    id = 86751073,
    name = "古兽裂齿的一角，约拇指大小，仍能让对手感到面对古兽的恐惧。"
  },
  [86751074] = {
    id = 86751074,
    name = "杯中盈满月光，如水倾斜而下，照亮每一寸角落。"
  },
  [86751075] = {
    id = 86751075,
    name = "传说，是它劈开了广袤的世界，开启了漫长征途的序言。"
  },
  [86751076] = {
    id = 86751076,
    name = "彷如跪在世人前忏悔的剔透石像，它封印着怨恨，渴望着复仇。"
  },
  [86751077] = {
    id = 86751077,
    name = "质地非金非玉的扇子，刀枪不入，不知来历。"
  },
  [86751078] = {
    id = 86751078,
    name = "神像倒塌后的断手，有残余的信仰之力。"
  },
  [86751079] = {
    id = 86751079,
    name = "星与月没有遗忘这片角落，它化为守望之环，给予了人们力量。"
  },
  [86751080] = {
    id = 86751080,
    name = "人们将信仰刻在臂章上，呼喊着英雄的名字。"
  },
  [86751081] = {
    id = 86751081,
    name = "当日月都被遮蔽，只有星星指明路途。"
  },
  [86751082] = {
    id = 86751082,
    name = "纵横交错的轨迹谱写着预言，如何选择未来，由你而定。"
  },
  [86751083] = {
    id = 86751083,
    name = "曙光穿越厚重的阴霾，亲吻整个世界。"
  },
  [86751084] = {
    id = 86751084,
    name = "时刻保持着温暖的项链，拥有对抗黑暗的神赐之力。"
  },
  [86751085] = {
    id = 86751085,
    name = "罕见的金属制作的神秘假面，容易收藏和隐蔽。"
  },
  [86751086] = {
    id = 86751086,
    name = "远古魔物被制成了镰刀，带着冰冷的凶光，击穿所有生灵。"
  },
  [86751087] = {
    id = 86751087,
    name = "邪恶的魔物被龙牙之剑带去地狱，也斩断其往生的路。"
  },
  [86751088] = {
    id = 86751088,
    name = "诡异的饰物，宛如一只眼睛凝视着你，令人毛骨悚然。"
  },
  [86751089] = {
    id = 86751089,
    name = "传闻有神使堕落，祂背负长索流亡四方，鲜血染红了祂前进的路。"
  },
  [86751090] = {
    id = 86751090,
    name = "刻满了古老符文的金属固件，据说蕴藏着不可言说的力量。"
  },
  [86751091] = {
    id = 86751091,
    name = "把世间最好的祝福折叠成星星的形状，寄托在遥远的星海。"
  },
  [86751092] = {
    id = 86751092,
    name = "它愿望不灭，它永不坠落。"
  },
  [86751093] = {
    id = 86751093,
    name = "灵魂的多面性被映照在镜面上，你看到的是什么模样？"
  },
  [86751094] = {
    id = 86751094,
    name = "一块神奇的石头，能将怨恨装载，打破虚空。"
  },
  [86751095] = {
    id = 86751095,
    name = "被抛弃的巫女迎来了爱人的一剑穿心，哀怨的血洒落在胸花之上，诅咒着世间的一切。"
  },
  [86751096] = {
    id = 86751096,
    name = "它用自己震慑同类，收缴罪恶的生命。"
  },
  [86751097] = {
    id = 86751097,
    name = "笼罩着厄运的笼子，接近它，会看到被一一封锁在笼中的噩梦。"
  },
  [86751098] = {
    id = 86751098,
    name = "它存在于深渊大地，伫立在永恒的岁月间。"
  },
  [86751099] = {
    id = 86751099,
    name = "源自远古时代的水晶，将祝福染成星河的颜色。"
  },
  [86751100] = {
    id = 86751100,
    name = "它将黑暗打碎，照亮深藏在囚牢中的灵魂。"
  },
  [86751101] = {
    id = 86751101,
    name = "无尽长夜消失之际，它开始转动，解开光明的枷锁。"
  },
  [86751102] = {
    id = 86751102,
    name = "灾难来临时，守护是唯一的慈悲。"
  },
  [86751103] = {
    id = 86751103,
    name = "土地孕育着新生，奇石祝福着生命。"
  },
  [86751104] = {
    id = 86751104,
    name = "传言是天地初开存在的幻树枯萎后留下的心脏，拿在手里，能感受到它的心跳。"
  },
  [86751105] = {
    id = 86751105,
    name = "一块奇异的精铁，能够激发体内的潜在能力，短时间提升自身力量。"
  },
  [86751106] = {
    id = 86751106,
    name = "注视它的那一刻，时间仿佛停滞，你看到了永恒的虚空。"
  },
  [86751107] = {
    id = 86751107,
    name = "人们齐聚在祭祀仪式上，对着天空高唱颂歌，就能得到力量。"
  },
  [86751108] = {
    id = 86751108,
    name = "它像一座高峰，无数人奋力爬上顶端，越靠近巅峰，越容易跌落。"
  },
  [86751109] = {
    id = 86751109,
    name = "随意捏于掌中柔韧的傀儡，却能不受控制地独舞。"
  },
  [86751110] = {
    id = 86751110,
    name = "永不静止的时空里，它缓缓运行着独有的轨道，那是众生的命运。"
  },
  [86751111] = {
    id = 86751111,
    name = "神鸟的幼雏不幸身亡，无处安放的羽翼被镶嵌在金徽之上。"
  },
  [86751112] = {
    id = 86751112,
    name = "一道道惊雷将坚石切割成苍鹰的模样，它振翅欲飞，却又被岁月凝固，成为永续的守望。"
  },
  [86751113] = {
    id = 86751113,
    name = "昔日的信仰皆为尘土，鲜血被赋予了全新的意义。"
  },
  [86751114] = {
    id = 86751114,
    name = "它以力量回馈，轻而易举地开出诱人的价码。"
  },
  [86751115] = {
    id = 86751115,
    name = "忘记痛苦吧，忘记那些怀念的记忆，你将一往无前。"
  },
  [86751116] = {
    id = 86751116,
    name = "戴上它，任何弱点都将无所遁形。"
  },
  [86751117] = {
    id = 86751117,
    name = "不知来处的甲胄，轻便又坚固。"
  },
  [86751118] = {
    id = 86751118,
    name = "认清自己，人类已不再是野兽。"
  },
  [86751119] = {
    id = 86751119,
    name = "特殊的晶矿之芯，具有催化魔法，高效转换的能力。"
  },
  [86751120] = {
    id = 86751120,
    name = "它在空中肆意起舞，聚起风雨迎面而来。"
  },
  [86751121] = {
    id = 86751121,
    name = "传闻鎏金色的圆规铸就了天地秩序，拟定了世界的规则。"
  },
  [86751122] = {
    id = 86751122,
    name = "一支化为金石的羽毛，浸润着月色与梦境。从某天起，深渊再也没有鸟儿飞过。"
  },
  [86751123] = {
    id = 86751123,
    name = "一面照进人心的镜子，放大了心绪的阴暗面。你在笑，镜子里的人在哭。"
  },
  [86751124] = {
    id = 86751124,
    name = "远古凶镰的尖刺，至今也一样锋芒四射。"
  },
  [86751125] = {
    id = 86751125,
    name = "带着天地之力的方锤，带给对手不可抗拒的噩梦。"
  },
  [86751126] = {
    id = 86751126,
    name = "握住它，你将更加渴望血液与杀戮。"
  },
  [86751127] = {
    id = 86751127,
    name = "极为罕见的液态流晶体，可吸收于法杖中，提升施法速度。"
  },
  [86751128] = {
    id = 86751128,
    name = "以湖心之羽制作的长弓，轻如羽快如风。"
  },
  [86751129] = {
    id = 86751129,
    name = "能将力量蓄积的轮盘，正一刻不停地旋转着。"
  },
  [86751130] = {
    id = 86751130,
    name = "据说解开它，就能打开某处隐秘的大门。"
  },
  [86751131] = {
    id = 86751131,
    name = "它向出征的勇士致意，赐予其祝福。"
  },
  [86751132] = {
    id = 86751132,
    name = "有人说里面封印了一只恶魔，待它释放，必将危害人间。"
  },
  [86751133] = {
    id = 86751133,
    name = "当它倾倒而出，一切会变慢得如泉水一般缓慢。"
  },
  [86751134] = {
    id = 86751134,
    name = "一把锁，锁住邪恶的灵魂与其疯狂的欲求。"
  },
  [86751135] = {
    id = 86751135,
    name = "宛如冰晶中囚禁的幽梦，凝结着岁月的孤寂与哀愁。"
  },
  [86751136] = {
    id = 86751136,
    name = "它避开时代的漩涡，静观岁月流转，守护那抹不灭的星光。"
  },
  [86751137] = {
    id = 86751137,
    name = "渺渺空灵的曲调，流淌过鲜血的战场，洗涤杀戮与仇恨。"
  },
  [86751138] = {
    id = 86751138,
    name = "当你展开它，能感受到灵魂被安抚。"
  },
  [86751139] = {
    id = 86751139,
    name = "沉寂于地下的魔晶重现天日，照亮冰冷的黑夜。"
  },
  [86751140] = {
    id = 86751140,
    name = "古老的祭司向光明祷告，呢喃吟咏被时间埋没，传奇的故事世代相传。"
  },
  [86751141] = {
    id = 86751141,
    name = "当善良被腐蚀，丑恶就成了释放欲望的毒蛇。"
  },
  [86751142] = {
    id = 86751142,
    name = "传闻里面封印了罪恶，不时会跳动，证明它还活着。"
  },
  [86751143] = {
    id = 86751143,
    name = "真正的恐惧源于未知，所有的生物对未知的想象都太过浅薄。"
  },
  [86751144] = {
    id = 86751144,
    name = "亘古的魔法被勾绘施加在披风上，给予后人久远的祝福。"
  },
  [86751145] = {
    id = 86751145,
    name = "万物更迭不息，星辰流转无常，时光不朽，它亦如初。"
  },
  [86751146] = {
    id = 86751146,
    name = "只要怀抱希望，死去的意志也会在你的内心复活。"
  },
  [86751147] = {
    id = 86751147,
    name = "传说中的言灵师送给爱人的定情之物，也是幸运的象征。紫晶不毁，我情不灭。"
  },
  [86751148] = {
    id = 86751148,
    name = "一对神乎其神的晶石，在其中一块发生变化时，另一块也互相感应般随之变化。"
  },
  [86751149] = {
    id = 86751149,
    name = "古老的禁术，将灵魂中的恶念封入魔偶中，烧毁主人指向的一切。"
  },
  [86751150] = {
    id = 86751150,
    name = "如蛇类般冰冷粗糙的雕塑，瓦解着敌人抵抗的意志。"
  },
  [86751151] = {
    id = 86751151,
    name = "迷局禁锢着记忆，你掌控着整个疆域。"
  },
  [86751152] = {
    id = 86751152,
    name = "以辰星的名义，构筑一场盛大的梦境。"
  },
  [86751153] = {
    id = 86751153,
    name = "受到毒咒的人偶，迫不及待地要把痛苦分享给对方品尝。"
  },
  [86751154] = {
    id = 86751154,
    name = "能将身形与外貌一同遮蔽的斗篷，使魔物分辨不出光源与气味。"
  },
  [86751155] = {
    id = 86751155,
    name = "遗落在尘世的宝珠，成就了预言的灵摆，昭示灾厄与不详。"
  },
  [86751156] = {
    id = 86751156,
    name = "悠扬悦耳的天籁，为战士注入勇气与希望。"
  },
  [86751157] = {
    id = 86751157,
    name = "戴上它，就能拥有神赐之力。"
  },
  [86751158] = {
    id = 86751158,
    name = "能够穿透黑暗的提灯，照亮未知的领域。"
  },
  [86751159] = {
    id = 86751159,
    name = "能在黑暗中发光的细沙，及其容易附在魔法箭矢之上。"
  },
  [86751160] = {
    id = 86751160,
    name = "它锐利如刃，丝丝入扣，织就毁灭的囚笼。"
  },
  [86751161] = {
    id = 86751161,
    name = "它力聚千钧，束缚万物，将敌人禁锢在黑暗之中。"
  },
  [86751162] = {
    id = 86751162,
    name = "当烛火燃尽，黑夜会重新降临。"
  },
  [86751163] = {
    id = 86751163,
    name = "世界掉入深渊的牢笼，就让它来编织新的美梦。"
  },
  [86751164] = {
    id = 86751164,
    name = "命运在回环往复中螺旋而上，永不停息。"
  },
  [86760000] = {id = 86760000, name = "%s"},
  [86761001] = {
    id = 86761001,
    name = "光辉之誓"
  },
  [86761002] = {
    id = 86761002,
    name = "魔力源流"
  },
  [86761003] = {
    id = 86761003,
    name = "破魔辉羽"
  },
  [86761004] = {
    id = 86761004,
    name = "光阴沙漏"
  },
  [86761005] = {
    id = 86761005,
    name = "神裁之秤"
  },
  [86761006] = {
    id = 86761006,
    name = "寒冰王冠"
  },
  [86761007] = {
    id = 86761007,
    name = "虚无的恩赐"
  },
  [86761008] = {
    id = 86761008,
    name = "谎言之心"
  },
  [86761009] = {
    id = 86761009,
    name = "邪灵法典"
  },
  [86761010] = {
    id = 86761010,
    name = "贪婪之眼"
  },
  [86761011] = {
    id = 86761011,
    name = "黄昏之袍"
  },
  [86771001] = {
    id = 86771001,
    name = "需「辉夜」出战才会生效\n1、战斗开始后，「辉夜」获得以自身100%%基础攻击力伤害的反伤效果，持续整场战斗。\n2、战斗开始后，「辉夜」受到攻击时，发动攻击方有10%%的概率陷入眩晕状态，持续1秒。"
  },
  [86771002] = {
    id = 86771002,
    name = "需「星云」出战才会生效\n1、战斗开始后，「星云」为敌方全体目标，附加30%%当前攻击力的木系持续伤害效果，持续整场战斗。\n2、「星云」在施放总攻技时，使敌方全体目标防御力降低30%%，持续整个总攻阶段。"
  },
  [86771003] = {
    id = 86771003,
    name = "需「月蚀」出战才会生效\n1、战斗开始后，「月蚀」为我方全体成员，基础攻速提升100%%，持续30秒。\n2、战斗开始后，「月蚀」为我方全体「猎影」成员，附加攻击时无视敌方目标10%%防御力的效果，持续整场战斗。"
  },
  [86771004] = {
    id = 86771004,
    name = "战斗开始后，每隔15秒，我方全体成员，获得无敌效果，持续5秒，无敌效果结束后，重新计时。"
  },
  [86771005] = {
    id = 86771005,
    name = "战斗开始时，敌方全体目标，受到等同于各自生命上限20%%的伤害。"
  },
  [86771006] = {
    id = 86771006,
    name = "战斗开始后，每隔15秒，基于战场中我方当前攻击力最高的成员的当前攻击力，对敌方全体目标造成50%%的水属性伤害，并有50%%的概率使受到攻击的敌方目标陷入冰冻状态，持续2秒。"
  },
  [86771007] = {
    id = 86771007,
    name = "战斗开始后，每隔4秒，我方全体成员恢复等同于自身4%%生命上限的生命值。"
  },
  [86771008] = {
    id = 86771008,
    name = "战斗开始后，每隔10秒，生成以我方全体成员20%%生命上限的等量护盾值，并基于我方当前攻击力最高的角色的当前攻击力，对敌方全体目标造成50%%的火属性伤害。"
  },
  [86771009] = {
    id = 86771009,
    name = "战斗开始后，我方全体成员，每次普攻时无视敌方目标20%%的当前防御力。"
  },
  [86771010] = {
    id = 86771010,
    name = "战斗开始后，每拥有50货券，我方全体成员造成的伤害提升10%%。"
  },
  [86771011] = {
    id = 86771011,
    name = "每消耗10点荣誉，我方全体成员，暴击伤害提升5%%。"
  },
  [86781001] = {
    id = 86781001,
    name = "“只要深渊仍有罪恶存在，那么我便没有收鞘的理由。”"
  },
  [86781002] = {
    id = 86781002,
    name = "星云小姐的家族徽记，虽然本人表示只是普通物品，但拥有如此强大的力量，绝不可能普通吧？"
  },
  [86781003] = {
    id = 86781003,
    name = "月蚀前往深渊前，父母送给她的饯别礼物——是和解，是传承，或者只是希望与关怀。"
  },
  [86781004] = {
    id = 86781004,
    name = "是永生，亦是坟墓。"
  },
  [86781005] = {
    id = 86781005,
    name = "古老而神秘的天平，据传可以衡量一切存在，无论是物质还是能量，无论是生命还是情感。"
  },
  [86781006] = {
    id = 86781006,
    name = "在这片领域中，它便是唯一的主宰。"
  },
  [86781007] = {
    id = 86781007,
    name = "当光线穿过水晶，映照在宝石上，仿佛能窥见另一个世界。"
  },
  [86781008] = {
    id = 86781008,
    name = "以谎言蛊惑人心，以谎言吞噬灵魂。"
  },
  [86781009] = {
    id = 86781009,
    name = "宛如一切邪恶的汇聚，宛如一切灾祸的根源。"
  },
  [86781010] = {
    id = 86781010,
    name = "多一点，再多一点......无休无止，永无止尽。"
  },
  [86781011] = {
    id = 86781011,
    name = "是烈阳坠落，步入黑夜的黄昏，抑或黑夜破晓，走向新生的黎明。"
  },
  [86790001] = {
    id = 86790001,
    name = "我方成员，处于控制状态时，防御力降低%d%%。"
  },
  [86790002] = {
    id = 86790002,
    name = "我方成员，受到普攻时的伤害提升%d%%。"
  },
  [86790003] = {
    id = 86790003,
    name = "我方「言灵」「猎影」成员，防御力降低%d，防御力不会为负值。"
  },
  [86790004] = {
    id = 86790004,
    name = "我方「异刃」成员，受到的伤害提升%d%%。"
  },
  [86790005] = {
    id = 86790005,
    name = "我方成员，处于防御力降低效果时，受到的伤害提升%d%%。"
  },
  [86790006] = {
    id = 86790006,
    name = "本次战斗中，敌我双方的成员若攻速受到影响，则会影响该目标的伤害。\n「攻速每提升%d%%，造成的伤害提升%d%%」\n「攻速每降低%d%%，造成的伤害降低%d%%」"
  },
  [86790007] = {
    id = 86790007,
    name = "本次战斗中，敌我双方的成员若被治疗，则被治疗者的攻击力提升%d%%，防御力提升%d%%，持续%d秒。"
  },
  [86790008] = {
    id = 86790008,
    name = "本次战斗中，敌我双方的成员若处于控制状态时，受到的伤害提升%d%%。"
  },
  [86791001] = {
    id = 86791001,
    name = "战斗开始后，我方全体成员，攻速提升%d%%，持续整场战斗。"
  },
  [86791002] = {
    id = 86791002,
    name = "战斗开始后，每隔%d秒，我方全体成员，获得等同于自身%d%%生命上限的护盾值。"
  },
  [86791003] = {
    id = 86791003,
    name = "通过战斗、远途奇遇区域后，荣誉和货券产量提高%d%%。"
  },
  [86791021] = {
    id = 86791021,
    name = "敌方全体目标，攻击力提升%d%%，防御力提升%d%%，生命值提升%d%%。"
  },
  [86791022] = {
    id = 86791022,
    name = "商店中宝物购买所需的货券数量提高%d%%。"
  },
  [86791031] = {
    id = 86791031,
    name = "敌方全体目标，攻击力提升%d%%，防御力提升%d%%，生命值提升%d%%。"
  },
  [86791032] = {
    id = 86791032,
    name = "商店中宝物购买所需的货券数量提高%d%%。"
  },
  [86791033] = {
    id = 86791033,
    name = "提升成员实力时，荣誉消耗提高1。"
  },
  [86791041] = {
    id = 86791041,
    name = "敌方全体目标，攻击力提升%d%%，防御力提升%d%%，生命值提升%d%%。"
  },
  [86791042] = {
    id = 86791042,
    name = "商店中宝物购买所需的货券数量提高%d%%。"
  },
  [86791043] = {
    id = 86791043,
