  },
  [88411002] = {
    id = 88411002,
    name = "对敌方2名目标造成[color=#e6ff51]&damage_rate&%%[/color]当前攻击力+[color=#e6ff51]&damage&[/color]的伤害。"
  },
  [88411003] = {
    id = 88411003,
    name = "以自身为起点向攻击目标方向的直线范围内的敌方全体目标造成[color=#e6ff51]&damage_rate&%%[/color]当前攻击力+[color=#e6ff51]&damage&[/color]的伤害，直线范围：宽30，长1000。"
  },
  [88412001] = {
    id = 88412001,
    name = "普攻时，有%s%%的概率触发[color=#e6ff51]&param&%%[/color]基础攻击力+[color=#e6ff51]&param&[/color]的额外伤害。"
  },
  [88412002] = {
    id = 88412002,
    name = "每次普攻，获得1层基础攻击力提升[color=#e6ff51]&param&%%[/color]+[color=#e6ff51]&param&[/color]的效果，最大可以叠加%s层。"
  },
  [88412003] = {
    id = 88412003,
    name = "每隔%s秒，为我方当前生命值百分比最低的2名成员恢复等同于自身[color=#e6ff51]&param&%%[/color]生命上限+[color=#e6ff51]&param&[/color]的生命值。"
  },
  [88412004] = {
    id = 88412004,
    name = "每隔%s秒，自身恢复[color=#e6ff51]&param&%%[/color]生命上限+[color=#e6ff51]&param&[/color]的生命值。"
  },
  [88412005] = {
    id = 88412005,
    name = "每隔%s秒，使受到普攻的敌方目标基础防御力降低[color=#e6ff51]&param&%%[/color]+[color=#e6ff51]&param&[/color]，持续%s秒。"
  },
  [88413001] = {
    id = 88413001,
    name = "对敌方单体目标造成[color=#e6ff51]&damage_rate&%%[/color]当前攻击力+[color=#e6ff51]&damage&[/color]的伤害。"
  },
  [88413002] = {
    id = 88413002,
    name = "进入「疾风」状态，攻速提升[color=#e6ff51]&param&%%[/color]，基础攻击力提升[color=#e6ff51]&param&[/color]，持续正整个总攻阶段。"
  },
  [88413003] = {
    id = 88413003,
    name = "为我方当前生命值百分比最低的%s名成员恢复等同于自身[color=#e6ff51]&param&%%[/color]生命上限+[color=#e6ff51]&param&[/color]的生命值。"
  },
  [88413004] = {
    id = 88413004,
    name = "对敌方单体目标造成[color=#e6ff51]&damage_rate&%%[/color]当前攻击力+[color=#e6ff51]&damage&[/color]的伤害，并随机对3名敌方目标施放嘲讽效果，持续%s秒。"
  },
  [88413005] = {
    id = 88413005,
    name = "对距离自身最近的2名敌方目标造成[color=#e6ff51]&damage_rate&%%[/color]当前攻击力+[color=#e6ff51]&damage&[/color]的伤害。"
  },
  [88414001] = {
    id = 88414001,
    name = "基础攻击力提升[color=#e6ff51]&param&[/color]，基础攻击力提升[color=#e6ff51]&param&%%[/color]。"
  },
  [88414002] = {
    id = 88414002,
    name = "基础攻速提升[color=#e6ff51]&param&%%[/color]，基础攻击力提升[color=#e6ff51]&param&[/color]。"
  },
  [88414003] = {
    id = 88414003,
    name = "自身与受击目标每距离50时，对敌方造成伤害时，会额外造成[color=#e6ff51]&param&%%[/color]基础攻击力+[color=#e6ff51]&param&[/color]的伤害。"
  },
  [88414004] = {
