    name = "基础生命力提升[color=#e6ff51]&param&[/color]，基础生命力提升[color=#e6ff51]&param&%%[/color]。"
  },
  [88414006] = {
    id = 88414006,
    name = "战斗开始时，自身免伤提升[color=#e6ff51]&param&%%[/color]，生命恢复效果提升[color=#e6ff51]&param&[/color]。"
  },
  [88414007] = {
    id = 88414007,
    name = "普攻时，有%s%%的概率给敌方目标附加[color=#e6ff51]&param&%%[/color]基础攻击力+[color=#e6ff51]&param&[/color]的当前元素属性持续伤害效果，持续%s秒，最大可以叠加%s层。"
  },
  [88414008] = {
    id = 88414008,
    name = "自身获得反伤效果，反伤时造成[color=#e6ff51]&param&%%[/color]基础攻击力+[color=#e6ff51]&param&[/color]的伤害。"
  },
  [88414009] = {
