  [200010001] = {
    id = 200010001,
    name = "行至途中，你总感觉有双眼睛在身后盯着你。"
  },
  [200010002] = {
    id = 200010002,
    name = "你停下脚步，不一会儿，一个少女从树影中走了出来。"
  },
  [200010003] = {
    id = 200010003,
    name = "她身着黑色长袍，看不清面容，手中托着一颗紫色的水晶球，熠熠发光。"
  },
  [200010004] = {
    id = 200010004,
    name = "「吾神明示，神秘的灾祸即将会发生在你的身上。」"
  },
  [200010005] = {
    id = 200010005,
    name = "少女的声音极其平静，听不出悲喜。"
  },
  [200010006] = {
    id = 200010006,
    name = "「但你是幸运的，你遇到了我。」"
  },
  [200010007] = {
    id = 200010007,
    name = "「只需要一枚金币，我的占卜水晶便会为你指明方向。」"
  },
  [200010008] = {
    id = 200010008,
    name = "你看了看兜里，掏出一枚金币递了过去。"
  },
  [200010009] = {
    id = 200010009,
    name = "少女接过金币，送给你一枚护符。"
  },
  [200010010] = {
    id = 200010010,
    name = "她让你将护符随时带在身边，可以护佑你平安。"
  },
  [200010011] = {
    id = 200010011,
    name = "少女离开后不久，一只飞行魔物突然朝你俯冲而来！"
  },
  [200010012] = {
    id = 200010012,
    name = "你身上护符大亮，却没有半点防护作用。"
  },
  [200010013] = {
    id = 200010013,
    name = "情况紧急，你急忙顺势翻滚，才躲过了魔物的袭击。"
  },
  [200010014] = {
    id = 200010014,
    name = "魔物见偷袭失败，急忙转身飞走。"
  },
  [200010015] = {
    id = 200010015,
    name = "你急忙跟上魔物，发现它飞到了那名占卜少女的身边，随即化作烟雾消散。"
  },
  [200010016] = {
    id = 200010016,
    name = "一切都是少女的幻术。"
  },
  [200010017] = {
    id = 200010017,
    name = "少女发现了你，见势不妙，转身便逃。"
  },
  [200010018] = {
    id = 200010018,
    name = "你立即出手，试图拦下她。"
  },
  [200010019] = {
    id = 200010019,
    name = "然而终究慢了一步，随着一阵烟雾爆散，少女已不见了踪影。"
  },
  [200010020] = {
    id = 200010020,
    name = "不过她手中的那颗紫色水晶球掉在了地上。"
  },
  [200010021] = {
    id = 200010021,
    name = "水晶球体光华流转，你输入了些许魔法力，看到了少女曾经生活的画面。"
  },
  [200010022] = {
    id = 200010022,
    name = "原来少女自幼被卖到贵族家做奴隶，受尽折辱打骂。"
  },
  [200010023] = {
    id = 200010023,
    name = "终于有一天，她偷走了这颗水晶球逃进了深渊。"
  },
  [200010024] = {
    id = 200010024,
    name = "她依靠自己的天赋自学了幻术，从此以行骗为生。"
  },
  [200010025] = {
    id = 200010025,
    name = "你追上了少女，将水晶球还给了她。"
  },
  [200010026] = {
    id = 200010026,
    name = "少女警惕地接过水晶球，扔给了你一些金币，飞快地跑开了。"
  },
  [200010027] = {
    id = 200010027,
    name = "你决定带走水晶球，如此一来，那位少女短期内应该无法再行骗了。"
  },
  [200010028] = {
    id = 200010028,
    name = "然而你刚走没多久，收起来的水晶球突然爆裂，将你炸了个灰头土脸。"
  },
  [200010029] = {
    id = 200010029,
    name = "你立即朝魔物施放魔法。"
  },
  [200010030] = {
    id = 200010030,
    name = "魔物被击中的瞬间，便化作烟雾消散。"
  },
  [200010031] = {
    id = 200010031,
    name = "你听到附近传来的声响，发现了受伤的黑袍少女。"
  },
  [200010032] = {
    id = 200010032,
    name = "原来你刚才破除了她的幻术，她因此受到了反噬。"
  },
  [200010033] = {
    id = 200010033,
    name = "少女说，她是为了生活，迫不得已才骗人。"
  },
  [200010034] = {
    id = 200010034,
    name = "但她从不害人，希望你能放过她，她会赔偿你的损失。"
  },
  [200010035] = {
    id = 200010035,
    name = "你放过了少女，她对你表示感激，留下了些金币便匆匆离去。"
  },
  [200010036] = {
    id = 200010036,
    name = "你打算毁掉水晶球，没想到它突然炸开。"
  },
  [200010037] = {
    id = 200010037,
    name = "你防不胜防，被炸了个灰头土脸。"
  },
  [200010038] = {
    id = 200010038,
    name = "少女拿起水晶球耐心地跟你解释。"
  },
  [200010039] = {
    id = 200010039,
    name = "从水晶球发出的光芒来看，你接下来会有血光之灾。"
  },
  [200010040] = {
    id = 200010040,
    name = "而且很有可能危及你的生命。"
  },
  [200010041] = {
    id = 200010041,
    name = "她希望你能相信她，并表示这是你唯一能拯救自己的机会。"
  },
  [200010042] = {
    id = 200010042,
    name = "你赶紧拿出几枚金币，换取了少女口中可以避免灾祸的护符。"
  },
  [200010043] = {
    id = 200010043,
    name = "你拿着护符端详了半晌。"
  },
  [200010044] = {
    id = 200010044,
    name = "发现这不过就是一块再普通不过的石头。"
  },
  [200010045] = {
    id = 200010045,
    name = "你恍然大悟，自己落入了骗局。"
  },
  [200010046] = {
    id = 200010046,
    name = "你揭穿了她的骗术，少女怒不可遏。"
  },
  [200010047] = {
    id = 200010047,
    name = "她手中的水晶球一瞬间光芒大盛。"
  },
  [200010048] = {
    id = 200010048,
    name = "趁你抬手躲避的瞬间，少女抓起你的钱袋逃之夭夭。"
  },
  [200010049] = {
    id = 200010049,
    name = "你追上了少女，很快将她制服。"
  },
  [200010050] = {
    id = 200010050,
    name = "少女含泪求饶。"
  },
  [200010051] = {
    id = 200010051,
    name = "她说自己也是为了生活迫不得已。"
  },
  [200010052] = {
    id = 200010052,
    name = "希望你能放她一马，她愿意给你赔罪。"
  },
  [200010053] = {
    id = 200010053,
    name = "你打算毁掉水晶球，没想到它突然炸开。"
  },
  [200010054] = {
    id = 200010054,
    name = "你防不胜防，被炸了个灰头土脸。"
  },
  [200010055] = {
    id = 200010055,
    name = "少女又惧又怕，恭恭敬敬地将钱袋还给了你，又给你了一些金币，随即迅速逃走了。"
  },
  [200020001] = {
    id = 200020001,
    name = "「啊——！」"
  },
  [200020002] = {
    id = 200020002,
    name = "女人的尖叫声传来。"
  },
  [200020003] = {
    id = 200020003,
    name = "你循着声音赶去，只见一个女人捂着衣服站在原地。"
  },
  [200020004] = {
    id = 200020004,
    name = "她泫然欲泣，发现你这个陌生人后，收起了表情，警觉地后退了一步。"
  },
  [200020005] = {
    id = 200020005,
    name = "在你身后突然冲出来几名男性探险者。"
  },
  [200020006] = {
    id = 200020006,
    name = "在你身后突然冲出来几名男性探险者。"
  },
  [200020007] = {
    id = 200020007,
    name = "「可算让我逮着你了！」"
  },
  [200020008] = {
    id = 200020008,
    name = "女人摇摇头。"
  },
  [200020009] = {
    id = 200020009,
    name = "「不是他，淫贼往树林跑了，快去抓住他！」"
  },
  [200020010] = {
    id = 200020010,
    name = "众人一听，又急急忙忙跑回树林。"
  },
  [200020011] = {
    id = 200020011,
    name = "女探险者向你道歉。"
  },
  [200020012] = {
    id = 200020012,
    name = "她说附近有一名喜欢偷女人内衣，玩弄女性的淫贼，他们正对其进行诱捕。"
  },
  [200020013] = {
    id = 200020013,
    name = "「他非常擅长逃跑。」"
  },
  [200020014] = {
    id = 200020014,
    name = "「有人曾看到他利用长索在树木之间灵活穿梭。」"
  },
  [200020015] = {
    id = 200020015,
    name = "「之前设置了各种陷阱都没有抓到他。」"
  },
  [200020016] = {
    id = 200020016,
    name = "「如果能得到你的帮助，抓住他的机会便又多了几分。」"
  },
  [200020017] = {
    id = 200020017,
    name = "「无论成功与否，都拜托了。」"
  },
  [200020018] = {
    id = 200020018,
    name = "你进入树林，听见前方传来男人们的声音。"
  },
  [200020019] = {
    id = 200020019,
    name = "「淫贼，看你这次你往哪儿跑！」"
  },
  [200020020] = {
    id = 200020020,
    name = "「就凭你们这群杂虫，老子的衣角都别想摸到！」"
  },
  [200020021] = {
    id = 200020021,
    name = "你循声追了过去，只见那几名探险者已经将一名黑袍人围了起来。"
  },
  [200020022] = {
    id = 200020022,
    name = "那人抬手射出长索勾在树上，轻轻一跃便跳上树梢。"
  },
  [200020023] = {
    id = 200020023,
    name = "随即双手交替射出长索在树木间移动，轻松突破了众人的包围。"
  },
  [200020024] = {
    id = 200020024,
    name = "「哈哈哈哈，想抓老子，再送十个女人来吧！」"
  },
  [200020025] = {
    id = 200020025,
    name = "探险者们面面相觑。"
  },
  [200020026] = {
    id = 200020026,
    name = "「怎么办！还追吗？」"
  },
  [200020027] = {
    id = 200020027,
    name = "「追到了怎么抓，你能随时背个梯子吗？」"
  },
  [200020028] = {
    id = 200020028,
    name = "几人决定先回去，重新制定抓捕计划。"
  },
  [200020029] = {
    id = 200020029,
    name = "「那人的身手很高明，可惜做什么不好，偏偏去做下流的事......」"
  },
  [200020030] = {
    id = 200020030,
    name = "你循着淫贼消失的方向继续前行，没多久便发现他正坐在一棵树上休息。"
  },
  [200020031] = {
    id = 200020031,
    name = "你放慢脚步，悄悄走到那棵树下，捡起一块石头掷向了他。"
  },
  [200020032] = {
    id = 200020032,
    name = "淫贼被你突袭，大叫一声从树上摔落下来，你一脚踩住了他的脑袋。"
  },
  [200020033] = {
    id = 200020033,
    name = "「你这个家伙，竟然偷袭我！」"
  },
  [200020034] = {
    id = 200020034,
    name = "「对付你这种龌龊的淫贼，还需要提前打招呼吗？」"
  },
  [200020035] = {
    id = 200020035,
    name = "「哼，偷袭算什么本事！你个胆小鬼，有种放了我，咱们正面打一场！」"
  },
  [200020036] = {
    id = 200020036,
    name = "你从他身上搜出了长索和女人的内衣。"
  },
  [200020037] = {
    id = 200020037,
    name = "你用长索捆住了他的双手，并堵住了他的嘴巴，把他拖出了树林。"
  },
  [200020038] = {
    id = 200020038,
    name = "甘做诱饵的女人果然还在原地和探险者们商讨对策，看见你们十分惊讶。"
  },
  [200020039] = {
    id = 200020039,
    name = "几人说要将淫贼交往公会，完成公会的赏金任务，于是送了一些物资给你表示感谢。"
  },
  [200020040] = {
    id = 200020040,
    name = "你刚放开他，他便射出长索，重新跳上了树，并赶在你出手前快速离去。"
  },
  [200020041] = {
    id = 200020041,
    name = "「傻了吧？！你又不是女人，老子才没功夫和你玩！」"
  },
  [200020042] = {
    id = 200020042,
    name = "你再次朝着他消失的方向追去，却再也没能追上。"
  },
  [200020043] = {
    id = 200020043,
    name = "「啧，被耍了。」"
  },
  [200020044] = {
    id = 200020044,
    name = "你刚走不远，便发现一名身着黑袍的男子正哼着小曲，慢悠悠地走在你前方。"
  },
  [200020045] = {
    id = 200020045,
    name = "你没有隐匿脚步，径直向前走去。"
  },
  [200020046] = {
    id = 200020046,
    name = "他惊觉回头，却见只有你一个人，便没有过多理会，只是加快脚步再次从你眼前消失。"
  },
  [200020047] = {
    id = 200020047,
    name = "没过多久，你又见到了男子。"
  },
  [200020048] = {
    id = 200020048,
    name = "他正坐在一块石头后方，拿着一件女人的内衣捂在自己脸上，发出下流猥琐的声音。"
  },
  [200020049] = {
    id = 200020049,
    name = "「哇，你这个淫贼，也太变态了吧。」"
  },
  [200020050] = {
    id = 200020050,
    name = "「可恶，你是什么时候......」"
  },
  [200020051] = {
    id = 200020051,
    name = "「哼，我喜欢女人的内衣，买来收藏的不行吗？」"
  },
  [200020052] = {
    id = 200020052,
    name = "「可是你这件上面还有汗渍啊。」"
  },
  [200020053] = {
    id = 200020053,
    name = "「嗯？兄弟，同道中人啊......」"
  },
  [200020054] = {
    id = 200020054,
    name = "「......」"
  },
  [200020055] = {
    id = 200020055,
    name = "「其实，我刚才看到了你和那女的在一起。」"
  },
  [200020056] = {
    id = 200020056,
    name = "「咱们商量商量。」"
  },
  [200020057] = {
    id = 200020057,
    name = "「你就当没看到我。」"
  },
  [200020058] = {
    id = 200020058,
    name = "「而我呢把这件内衣给你，再送你一份独门秘药。」"
  },
  [200020059] = {
    id = 200020059,
    name = "「交个朋友怎么样？」"
  },
  [200020060] = {
    id = 200020060,
    name = "「先说好，我可不是看上了你的东西，只是单纯喜欢交朋友。」"
  },
  [200020061] = {
    id = 200020061,
    name = "「我懂我懂！哈哈哈，这条路上，我终于不是孤独一个人了，哈哈哈哈......」"
  },
  [200020062] = {
    id = 200020062,
    name = "男子将内衣交给了你，并送给你一瓶所谓的秘药，随即大笑着离去。"
  },
  [200020063] = {
    id = 200020063,
    name = "他的笑声回荡在树林中，久久方才散去。"
  },
  [200020064] = {
    id = 200020064,
    name = "「......」"
  },
  [200020065] = {
    id = 200020065,
    name = "这样的变态，你才不想和他扯上关系。"
  },
  [200020066] = {
    id = 200020066,
    name = "那淫贼见你拒绝得果断，不由恼羞成怒，突然暴起向你发动攻击，但均被你轻松化解。"
  },
  [200020067] = {
    id = 200020067,
    name = "他脸色一变，自知不敌，想射出长索逃走。"
  },
  [200020068] = {
    id = 200020068,
    name = "你根本不给他逃跑的机会，一剑斩断了长索，他在慌乱中被你一脚踩在地上。"
  },
  [200020069] = {
    id = 200020069,
    name = "你用长索捆住了他的双手，并堵住了他的嘴巴，将他带了回去。"
  },
  [200020070] = {
    id = 200020070,
    name = "甘做诱饵的女人果然还在原地和探险者们商讨对策，看见你们十分惊讶。"
  },
  [200020071] = {
    id = 200020071,
    name = "几人说要将淫贼交往公会，完成公会的赏金任务，于是送了一些物资给你表示感谢。"
  },
  [200020072] = {
    id = 200020072,
    name = "你离开了树林绕道而行。"
  },
  [200030001] = {
    id = 200030001,
    name = "你路过一片湖泊，看到一名少女在湖边焦急踱步，大声呼喊，便上前询问。"
  },
  [200030002] = {
    id = 200030002,
    name = "少女告诉你她的同伴被困湖中，生死不明，可是她不会游泳，只能干着急。"
  },
  [200030003] = {
    id = 200030003,
    name = "你跳入湖中，很快便发现一名被魔物困住的探险者。"
  },
  [200030004] = {
    id = 200030004,
    name = "你杀掉了魔物，救出被困的探险者。"
  },
  [200030005] = {
    id = 200030005,
    name = "二人对你的实力非常钦佩，也不断对你的慷慨相助表示感激。"
  },
  [200030006] = {
    id = 200030006,
    name = "在你即将离去的时候，探险者叫住了你。"
  },
  [200030007] = {
    id = 200030007,
    name = "他告诉你，他们有一件宝物遗失在了湖中，刚才在水下没来得及取。"
  },
  [200030008] = {
    id = 200030008,
    name = "如果你愿意帮他们找回宝物，他们愿意付出厚礼表达谢意。"
  },
  [200030009] = {
    id = 200030009,
    name = "你告诉他们魔物已死，湖中是安全的，让他们自己去搜寻，于是探险者再次下水，但往返数次皆空手而回。"
  },
  [200030010] = {
    id = 200030010,
    name = "宝物不会无故消失，你提议解剖魔物查看，两人的面色一僵，只能照你的话去做。"
  },
  [200030011] = {
    id = 200030011,
    name = "果然在魔物的体内发现了宝物。"
  },
  [200030012] = {
    id = 200030012,
    name = "探险者和少女再次对你表示感谢，送给了你一些物资作为谢礼。"
  },
  [200030013] = {
    id = 200030013,
    name = "你再次进入水中，并没有看到他们形容的宝物。"
  },
  [200030014] = {
    id = 200030014,
    name = "在气竭之前，你重新回到了水面，却发现岸边已空无一人。"
  },
  [200030015] = {
    id = 200030015,
    name = "你走到被剖开的魔物尸体身边，似乎明白了什么。"
  },
  [200030016] = {
    id = 200030016,
    name = "少女见你无动于衷，拿出了身上的财物。"
  },
  [200030017] = {
    id = 200030017,
    name = "她告诉你湖中有一头魔物，她的同伴进入湖中后就失去了讯息，只求你能帮忙，她愿意把所有的财物给你。"
  },
  [200030018] = {
    id = 200030018,
    name = "你见湖面虽然平静，但其中暗潮汹涌，于是捡起一块石头投入其中。"
  },
  [200030019] = {
    id = 200030019,
    name = "湖中瞬间波涛激荡，翻腾的水浪间，一个被魔物触手缠着的人影短暂露出水面。"
  },
  [200030020] = {
    id = 200030020,
    name = "「逃——」"
  },
  [200030021] = {
    id = 200030021,
    name = "探险者向少女发出了最后的警告。"
  },
  [200030022] = {
    id = 200030022,
    name = "少女惊慌失措，把唯一的希望寄托在了你身上。"
  },
  [200030023] = {
    id = 200030023,
    name = "你刚跳入湖中，魔物便直接奔你而来。"
  },
  [200030024] = {
    id = 200030024,
    name = "面对这头猛兽你不敢大意，全力施放魔法，终于在气竭前将其斩杀。"
  },
  [200030025] = {
    id = 200030025,
    name = "魔物死后，你并未发现方才看到的那名探险者，只在水底找到一枚发光的宝石。"
  },
  [200030026] = {
    id = 200030026,
    name = "待你上岸，才发现那名探险者不知何时已经上岸，少女正在为他疗伤。"
  },
  [200030027] = {
    id = 200030027,
    name = "少女向你问起湖中的情况，并问你是否看到一枚发光的宝石。"
  },
  [200030028] = {
    id = 200030028,
    name = "你告诉少女刚才战斗太过激烈，并未发现什么，少女的表情显得有些落寞、遗憾。"
  },
  [200030029] = {
    id = 200030029,
    name = "你正准备告辞，突然感受到包裹中的宝石出现了魔力波动。"
  },
  [200030030] = {
    id = 200030030,
    name = "你来不及做出反应，便晕了过去......"
  },
  [200030031] = {
    id = 200030031,
    name = "醒来后你发现自己的随身财物，以及那枚宝石均已消失不见。"
  },
  [200030032] = {
    id = 200030032,
    name = "你告诉了少女自己的发现，并将宝石交给了她。"
  },
  [200030033] = {
    id = 200030033,
    name = "少女显得非常高兴，她从包裹中翻找出各种有用的物品，一股脑地塞到了你的手中。"
  },
  [200030034] = {
    id = 200030034,
    name = "二人再次对你表示感谢后，便告辞离去。"
  },
  [200030035] = {
    id = 200030035,
    name = "少女见你拒绝，眼中露出绝望。"
  },
  [200030036] = {
    id = 200030036,
    name = "下一秒，她就跳入了湖泊。"
  },
  [200030037] = {
    id = 200030037,
    name = "湖中一阵浪潮汹涌，不多时一头巨大的魔物浮出湖面。"
  },
  [200030038] = {
    id = 200030038,
    name = "你来不及隐藏，魔物径直向你袭来。"
  },
  [200030039] = {
    id = 200030039,
    name = "你见已无法躲避，便全力出手，费了不少精力才将魔物斩杀。"
  },
  [200030040] = {
    id = 200030040,
    name = "随后，你在魔物的体内发现了两人的尸骨，不由叹了口气。"
  },
  [200030041] = {
    id = 200030041,
    name = "你离开了湖泊，隐隐察觉到身后少女的绝望。"
  },
  [200030042] = {
    id = 200030042,
    name = "没走几步，你听到身后传来重物落水的声音。"
  },
  [200030043] = {
    id = 200030043,
    name = "回头看去，那少女竟然跳入了湖泊。"
  },
  [200030044] = {
    id = 200030044,
    name = "湖中一阵浪潮汹涌，不多时一头巨大的魔物浮出湖面。"
  },
  [200030045] = {
    id = 200030045,
    name = "你来不及隐藏，魔物便径直向你袭来。"
  },
  [200030046] = {
    id = 200030046,
    name = "你见已无法躲避，便全力出手，费了不少精力才将魔物斩杀。"
  },
  [200030047] = {
    id = 200030047,
    name = "随后，你在魔物的体内发现了两人的尸骨，不由叹了口气。"
  },
  [200040001] = {
    id = 200040001,
    name = "你走在山道上，忽然听到前方传来争吵声。"
  },
  [200040002] = {
    id = 200040002,
    name = "你走近一看，几名凶恶的壮汉正将一名探险者逼到崖边。"
  },
  [200040003] = {
    id = 200040003,
    name = "你靠近了些，从他们的对话中得知了大概情况。"
  },
  [200040004] = {
    id = 200040004,
    name = "那名探险者原本是这几名壮汉的同伙，他们一直做着杀人抢劫的勾当，现在那名探险者想拆伙，不想再继续作恶了。"
  },
  [200040005] = {
    id = 200040005,
    name = "领头的壮汉告诉那人，一旦踏上了这条路，便只能一直走到黑，绝不存在退路。"
  },
  [200040006] = {
    id = 200040006,
    name = "探险者一直求饶，表示愿意拿出所有的财物换取自由。"
  },
  [200040007] = {
    id = 200040007,
    name = "壮汉威胁探险者必须跟他们回去。"
  },
  [200040008] = {
    id = 200040008,
    name = "「你要是在路上想通了，我们还是一起宰肥羊过日子的好兄弟。」"
  },
  [200040009] = {
    id = 200040009,
    name = "「要是想不开，我们就送你上路。」"
  },
  [200040010] = {
    id = 200040010,
    name = "（看样子这群劫匪是在逼迫这个想改邪归正的同伙......）"
  },
  [200040011] = {
    id = 200040011,
    name = "你站了出来，让这群劫匪给探险者一个机会，既然人各有志，就不该再勉强。"
  },
  [200040012] = {
    id = 200040012,
    name = "「你算什么东西，莫名其妙管闲事。」"
  },
  [200040013] = {
    id = 200040013,
    name = "这群壮汉将矛头对准了你。"
  },
  [200040014] = {
    id = 200040014,
    name = "探险者让你快走，他不想让陌生人受牵连。"
  },
  [200040015] = {
    id = 200040015,
    name = "「想走？让你知道多管闲事的后果！」"
  },
  [200040016] = {
    id = 200040016,
    name = "几名壮汉将你围住，向你发起了攻击。"
  },
  [200040017] = {
    id = 200040017,
    name = "对你而言，他们的攻势看似凌厉凶狠，实则破绽百出。"
  },
  [200040018] = {
    id = 200040018,
    name = "不一会儿便被你打得趴在地上哭爹喊娘，纷纷求饶。"
  },
  [200040019] = {
    id = 200040019,
    name = "探险者对你非常感激，向你讲述了往事。"
  },
  [200040020] = {
    id = 200040020,
    name = "「这一切都是为了我在大陆的妻子。」"
  },
  [200040021] = {
    id = 200040021,
    name = "「我一直很厌恶这样的生活，但为了满足我妻子的愿望，我一直在强迫自己。」"
  },
  [200040022] = {
    id = 200040022,
    name = "「我不断告诉自己再坚持一下，只要再多赚一点就可以回家了......」"
  },
  [200040023] = {
    id = 200040023,
    name = "「可是前些日子，我却收到了她和别的男人私奔的消息。」"
  },
  [200040024] = {
    id = 200040024,
    name = "「唉，所以我便决定离开，只是没想到这些曾经的兄弟们......」"
  },
  [200040025] = {
    id = 200040025,
    name = "「幸好有你出现，才让我重新拥有了自由。」"
  },
  [200040026] = {
    id = 200040026,
    name = "「那你以后打算做些什么呢？」"
  },
  [200040027] = {
    id = 200040027,
    name = "「我会烹饪一些食材，之前也做过工匠的活计。」"
  },
  [200040028] = {
    id = 200040028,
    name = "「所以一直在厨师与工匠中犹豫，不知道做哪个好。」"
  },
  [200040029] = {
    id = 200040029,
    name = "「深渊中有各种各样的材料，用这些材料制作的器具不少都有特殊功效。」"
  },
  [200040030] = {
    id = 200040030,
    name = "「探险者对这方面的需求量很大。」"
  },
  [200040031] = {
    id = 200040031,
    name = "「做一名工匠的话，养活自己不成问题。」"
  },
  [200040032] = {
    id = 200040032,
    name = "探险者非常感激你的提议。"
  },
  [200040033] = {
    id = 200040033,
    name = "他将包袱中的一些物资作为谢礼送给了你，笑着向你道别。"
  },
  [200040034] = {
    id = 200040034,
    name = "「深渊中有许多珍奇的魔物、植物，如果能深入研究、烹调，想必可以做出许多美味佳肴。」"
  },
  [200040035] = {
    id = 200040035,
    name = "「这也算是不错的生计。」"
  },
  [200040036] = {
    id = 200040036,
    name = "探险者非常感激你的提议。"
  },
  [200040037] = {
    id = 200040037,
    name = "作为报答，他将自己多余的物资全都送给了你。"
  },
  [200040038] = {
    id = 200040038,
    name = "从此轻装上阵，向着厨师之路进发。"
  },
  [200040039] = {
    id = 200040039,
    name = "探险者后退了一步，走向了崖边。"
  },
  [200040040] = {
    id = 200040040,
    name = "「像我这样的人，这一生不如就这样结束了吧。」"
  },
  [200040041] = {
    id = 200040041,
    name = "他转身跳下了悬崖。"
  },
  [200040042] = {
    id = 200040042,
    name = "崖边卷起飓风，壮汉们震惊地愣在原地，没有一个人敢上前。"
  },
  [200040043] = {
    id = 200040043,
    name = "有人提议去找他的尸体，终究兄弟一场。"
  },
  [200040044] = {
    id = 200040044,
    name = "但很快就被其他人否定了。"
  },
  [200040045] = {
    id = 200040045,
    name = "「收个屁！让那家伙喂魔物吧！」"
  },
  [200040046] = {
    id = 200040046,
    name = "「就是，就是！要不是他，我们那几桩生意还不会被搅黄。」"
  },
  [200040047] = {
    id = 200040047,
    name = "几人骂骂咧咧地离开了。"
  },
  [200040048] = {
    id = 200040048,
    name = "他们走后，你注意到崖边的石头上出现了一只手，跳崖的探险者半悬在空中。"
  },
  [200040049] = {
    id = 200040049,
    name = "你走上前将他拉了起来。"
  },
  [200040050] = {
    id = 200040050,
    name = "探险者很感激你的帮助，苦笑着说起了自己的往事。"
  },
  [200040051] = {
    id = 200040051,
    name = "「虽然当年我是被逼跟着他们一起杀人抢劫......」"
  },
  [200040052] = {
    id = 200040052,
    name = "「......但确实做了很多不可饶恕的事。」"
  },
  [200040053] = {
    id = 200040053,
    name = "「我也一直没有勇气离开。」"
  },
  [200040054] = {
    id = 200040054,
    name = "「直到今天，我其实一直都活在煎熬和痛苦之中。」"
  },
  [200040055] = {
    id = 200040055,
    name = "「幸好你拉了我一把，不然我可能会就这样带着不甘和痛苦死去吧......」"
  },
  [200040056] = {
    id = 200040056,
    name = "「你以后打算做些什么呢？」"
  },
  [200040057] = {
    id = 200040057,
    name = "「我会烹饪一些食材，之前也做过工匠的活计。」"
  },
  [200040058] = {
    id = 200040058,
    name = "「所以一直在厨师与工匠中犹豫，不知道做哪个好。」"
  },
  [200040059] = {
    id = 200040059,
    name = "「深渊中有各种各样的材料，用这些材料制作的器具不少都有特殊功效。」"
  },
  [200040060] = {
    id = 200040060,
    name = "「探险者对这方面的需求量很大。」"
  },
  [200040061] = {
    id = 200040061,
    name = "「做一名工匠的话，养活自己不成问题。」"
  },
  [200040062] = {
    id = 200040062,
    name = "探险者非常感激你的提议。"
  },
  [200040063] = {
    id = 200040063,
    name = "他将包袱中的一些物资作为谢礼送给了你，笑着向你道别。"
  },
  [200040064] = {
    id = 200040064,
    name = "「深渊中有许多珍奇的魔物、植物，如果能深入研究、烹调，想必可以做出许多美味佳肴。」"
  },
  [200040065] = {
    id = 200040065,
    name = "「这也算是不错的生计。」"
  },
  [200040066] = {
    id = 200040066,
    name = "探险者非常感激你的提议。"
  },
  [200040067] = {
    id = 200040067,
    name = "作为报答，他将自己多余的物资全都送给了你，转身离去。"
  },
  [200050001] = {
    id = 200050001,
    name = "「哎哟......哎哟......」"
  },
  [200050002] = {
    id = 200050002,
    name = "前方有人呻吟，你循着声音走了过去。"
  },
  [200050003] = {
    id = 200050003,
    name = "一名背着包袱的男子靠在大石头边休息，他拿着一瓶药剂，正往自己的腿上涂药。"
  },
  [200050004] = {
    id = 200050004,
    name = "他看到了你，惊喜地和你打招呼。"
  },
  [200050005] = {
    id = 200050005,
    name = "他说他只是一个普通人，听闻深渊风景和大陆的完全不同，想来见识一番。"
  },
  [200050006] = {
    id = 200050006,
    name = "他一路都跟着一支探险队行动，还算安稳，没想到今天出了意外。"
  },
  [200050007] = {
    id = 200050007,
    name = "他在魔物袭击中负伤，而那支探险队在杀掉魔物之后却弃他而去。"
  },
  [200050008] = {
    id = 200050008,
    name = "「他们真是太可恶了，你说对不对？」"
  },
  [200050009] = {
    id = 200050009,
    name = "他向你寻求认同。"
  },
  [200050010] = {
    id = 200050010,
    name = "旅者沉默了一会儿，说起了自己的事。"
  },
  [200050011] = {
    id = 200050011,
    name = "「唉，其实我也很困扰。」"
  },
  [200050012] = {
    id = 200050012,
    name = "「我曾想成为一个探险者，为此做了许多努力，但全都失败了。」"
  },
  [200050013] = {
    id = 200050013,
    name = "「为了学习魔法，我花重金从一个魔法师那里买了这块石头，没想到毫无用处。」"
  },
  [200050014] = {
    id = 200050014,
    name = "你看着那块灰扑扑的石头，发现眼前这个人的确是冤大头。"
  },
  [200050015] = {
    id = 200050015,
    name = "（从某种程度来看，这人还挺顽强的。）"
  },
  [200050016] = {
    id = 200050016,
    name = "「呵呵，不用安慰我，其实我已经知道自己不是做探险者的料。」"
  },
  [200050017] = {
    id = 200050017,
    name = "旅者认为自己的确不适合深渊，这次回去后应该好好考虑一下以后的生活了。"
  },
  [200050018] = {
    id = 200050018,
    name = "「不过，听说公会的伊芙大人正在研制普通人也能使用的强力器具。」"
  },
  [200050019] = {
    id = 200050019,
    name = "「如果那些东西平民也能用的话，像我这样的普通人也能不依靠任何人了！」"
  },
  [200050020] = {
    id = 200050020,
    name = "（列蒂西雅家还在研究这些东西吗？）"
  },
  [200050021] = {
    id = 200050021,
    name = "旅者把那块灰扑扑的石头递给了你，希望你能送他去圈落。"
  },
  [200050022] = {
    id = 200050022,
    name = "你拿着那块石头，隐隐感觉到其中似乎存在魔力。"
  },
  [200050023] = {
    id = 200050023,
    name = "于是你将表层剥离，意外发现竟然是一块蕴含魔力的罕见矿物。"
  },
  [200050024] = {
    id = 200050024,
    name = "旅者一脸惊讶羡慕，对你满口称赞，但并未表露出想把这块矿物要回去的想法。"
  },
  [200050025] = {
    id = 200050025,
    name = "你依照旅者的意愿将他送回了圈落，他十分感激地离开了。"
  },
  [200050026] = {
    id = 200050026,
    name = "「这算不算是意外收获呢。」"
  },
  [200050027] = {
    id = 200050027,
    name = "「可是只有成为探险者，才可以去到普通人到不了的地方，看更多的风景吧。」"
  },
  [200050028] = {
    id = 200050028,
    name = "「要是只听别人讲述，自己却看不到，那可是很遗憾的事情啊。」"
  },
  [200050029] = {
    id = 200050029,
    name = "「......」"
  },
  [200050030] = {
    id = 200050030,
    name = "旅者叹了口气，认为自己的确不适合深渊，这次回去后应该好好考虑一下以后的生活了。"
  },
  [200050031] = {
    id = 200050031,
    name = "他把那块灰扑扑的石头递给了你，希望你能送他去圈落。"
  },
  [200050032] = {
    id = 200050032,
    name = "「拜托了。」"
  },
  [200050033] = {
    id = 200050033,
    name = "你拿着那块石头，隐隐感觉到其中蕴藏着魔力，虽然微弱，但并不难察觉。"
  },
  [200050034] = {
    id = 200050034,
    name = "你将旅者送回圈落，他十分感激地离开了。"
  },
  [200050035] = {
    id = 200050035,
    name = "「唔，长期携带这块石头也没能感受到其中的魔力波动，看来他的魔法天赋......」"
  },
  [200050036] = {
    id = 200050036,
    name = "「算了，祝他好运吧。」"
  },
  [200050037] = {
    id = 200050037,
    name = "「对吧，你也这么认为！」"
  },
  [200050038] = {
    id = 200050038,
    name = "他像是找到了知音，喋喋不休地吐槽着那支探险队的不是。"
  },
  [200050039] = {
    id = 200050039,
    name = "你向他打听附近的情报时，他却不吭声了。"
  },
  [200050040] = {
    id = 200050040,
    name = "「我哪儿敢去那些疯子们才去的地方......」"
  },
  [200050041] = {
    id = 200050041,
    name = "他讪讪一笑，希望你能送他回圈落。"
  },
  [200050042] = {
    id = 200050042,
    name = "「拜托了。」"
  },
  [200050043] = {
    id = 200050043,
    name = "你将旅者送回圈落，他连谢谢都没有说就消失在了人群中。"
  },
  [200050044] = {
    id = 200050044,
    name = "「......」"
  },
  [200050045] = {
    id = 200050045,
    name = "你摇了摇头，他那样看待探险者，吃力不讨好的赔本买卖你才不干。"
  },
  [200050046] = {
    id = 200050046,
    name = "旅者露出了害怕的神情。"
  },
  [200050047] = {
    id = 200050047,
    name = "「你不管我，我会死在这儿的！」"
  },
  [200050048] = {
    id = 200050048,
    name = "「那也与我无关。」"
  },
  [200050049] = {
    id = 200050049,
    name = "旅者骂你冷血无情，但见你真的转身离开后，又慌忙追上了你。"
  },
  [200050050] = {
    id = 200050050,
    name = "「我有钱，我给你钱！」"
  },
  [200050051] = {
    id = 200050051,
    name = "你停下来，旅者急忙拿出一些金币递给你。"
  },
  [200050052] = {
    id = 200050052,
    name = "看在金币的面子上，你将他送回了圈落。"
  },
  [200050053] = {
    id = 200050053,
    name = "旅者感恩戴德，跟你鞠躬道谢才离去。"
  },
  [200050054] = {
    id = 200050054,
    name = "「嗤，不知道又该跟其他人怎么骂我了。」"
  },
  [200050055] = {
    id = 200050055,
    name = "「你！」"
  },
  [200050056] = {
    id = 200050056,
    name = "他愤怒地看着你，但不多时就泄了气。"
  },
  [200050057] = {
    id = 200050057,
    name = "「是我没本事，才落得这样的下场。」"
  },
  [200050058] = {
    id = 200050058,
    name = "他叹了口气，希望你能送他去圈落，他会付钱给你。"
  },
  [200050059] = {
    id = 200050059,
    name = "说着他拿出一些金币给你。"
  },
  [200050060] = {
    id = 200050060,
    name = "你摇了摇头，继续看着他。"
  },
  [200050061] = {
    id = 200050061,
    name = "旅者瞪大了眼。"
  },
  [200050062] = {
    id = 200050062,
    name = "「没想到刚走一群没心没肺的探险者，又来一个狮子大开口的强盗。」"
  },
  [200050063] = {
    id = 200050063,
    name = "「这一路魔物很多的。」"
  },
  [200050064] = {
    id = 200050064,
    name = "旅者一哆嗦，又掏出一些。"
  },
  [200050065] = {
    id = 200050065,
    name = "「你的命就值这点钱？」"
  },
  [200050066] = {
    id = 200050066,
    name = "旅者咬了咬牙，把那一袋都给了你。"
  },
  [200050067] = {
    id = 200050067,
    name = "看在金币的面子上，你将他送回了圈落。"
  },
  [200050068] = {
    id = 200050068,
    name = "一进圈落，旅者怕你再找他要钱，撒腿便跑，瞬间没了踪影。"
  },
  [200050069] = {
    id = 200050069,
    name = "「啧啧。」"
  },
  [200060001] = {
    id = 200060001,
    name = "你路过一条河流，看到一个人正站在河边唉声叹气。"
  },
  [200060002] = {
    id = 200060002,
    name = "「唉，下面会不会有魔物......」"
  },
  [200060003] = {
    id = 200060003,
    name = "你上前了解情况，发现这人竟然准备跳河。"
  },
  [200060004] = {
    id = 200060004,
    name = "原来他是一名药剂师，刚才被抢走了所有的钱，还被毒打了一顿。"
  },
  [200060005] = {
    id = 200060005,
    name = "「那是我倾家荡产，打算用来买药草的钱。」"
  },
  [200060006] = {
    id = 200060006,
    name = "「我想就这样死了一了百了，可是被淹死的话一定会很痛苦吧。」"
  },
  [200060007] = {
    id = 200060007,
    name = "「如果河中还有魔物，那岂不是更加——唔，太可怕了。」"
  },
  [200060008] = {
    id = 200060008,
    name = "「......」"
  },
  [200060009] = {
    id = 200060009,
    name = "「其实你根本不想死吧。」"
  },
  [200060010] = {
    id = 200060010,
    name = "「我本想用那批药草研制新的药剂，但现在什么都没有了，完全找不到活下去的意义。」"
  },
  [200060011] = {
    id = 200060011,
    name = "「要是能拿到那批药草......」"
  },
  [200060012] = {
    id = 200060012,
    name = "「唉。」"
  },
  [200060013] = {
    id = 200060013,
    name = "「平时买药草我都会找商会，可这几个月手头紧......」"
  },
  [200060014] = {
    id = 200060014,
    name = "「有人给我介绍了一伙便宜的游商，约我在这里见面。」"
  },
  [200060015] = {
    id = 200060015,
    name = "「没想到我刚到这里，他们就打了我一顿，把我的钱全部抢走了。」"
  },
  [200060016] = {
    id = 200060016,
    name = "「很明显，介绍人和那伙打劫你的人是同伙。」"
  },
  [200060017] = {
    id = 200060017,
    name = "「说起来他正好是这一带的采石工，我才对他没有防范。」"
  },
  [200060018] = {
    id = 200060018,
    name = "「......」"
  },
  [200060019] = {
    id = 200060019,
    name = "这个可怜鬼的遭遇让你有些生气，决定帮他抢回财物，于是向他询问了那伙人的详细情况。"
  },
  [200060020] = {
    id = 200060020,
    name = "根据药剂师提供的线索，你在附近找到了那名正在挖矿石的工人。"
  },
  [200060021] = {
    id = 200060021,
    name = "「想便宜搞些好东西的话......」"
  },
  [200060022] = {
    id = 200060022,
    name = "介绍人见你独自一人，咂了咂嘴。"
  },
  [200060023] = {
    id = 200060023,
    name = "他把你带到旁边树林中，让你在原地等候。"
  },
  [200060024] = {
    id = 200060024,
    name = "没过多久，几名壮汉走了过来。"
  },
  [200060025] = {
    id = 200060025,
    name = "「就是你找我们？」"
  },
  [200060026] = {
    id = 200060026,
    name = "「是的，想问你们一个问题。」"
  },
  [200060027] = {
    id = 200060027,
    name = "「那个药剂师被你们抢了多少钱？」"
  },
  [200060028] = {
    id = 200060028,
    name = "「你在说什么鬼话？」"
  },
  [200060029] = {
    id = 200060029,
    name = "「把钱交出来，你们这些强盗。」"
  },
  [200060030] = {
    id = 200060030,
    name = "你干脆利索地将他们打倒在地，直到他们没有还手之力。"
  },
  [200060031] = {
    id = 200060031,
    name = "几个壮汉轮番求饶，表示愿意把钱都还给你，希望你不要杀他们。"
  },
  [200060032] = {
    id = 200060032,
    name = "你将几人捆起来，带到附近据点交给了公会。"
  },
  [200060033] = {
    id = 200060033,
    name = "药剂师得知你帮他找回了财物，还惩治了恶人，却依然愁眉不展。"
  },
  [200060034] = {
    id = 200060034,
    name = "「钱虽然回来了，那些恶棍也得到了惩罚，但是药草......唉。」"
  },
  [200060035] = {
    id = 200060035,
    name = "你看着他唉声叹气的样子，也不知该如何安慰，只能说些慢慢来之类的话。"
  },
  [200060036] = {
    id = 200060036,
    name = "正当你准备离去时，药剂师叫住了你。"
  },
  [200060037] = {
    id = 200060037,
    name = "他递给你一些药剂，说是自己之前研制的。"
  },
  [200060038] = {
    id = 200060038,
    name = "「我知道这些难以回报你的恩情，但还请先收下！等我攒好材料研究出新药剂，一定会送上正式的谢礼！」"
  },
  [200060039] = {
    id = 200060039,
    name = "几名壮汉感激不尽，将药剂师的财物都还给了你，并许诺再也不骗人了。"
  },
  [200060040] = {
    id = 200060040,
    name = "药剂师见你成功夺回了财物，还教训了骗子，非常感激你。"
  },
  [200060041] = {
    id = 200060041,
    name = "他将之前研制的珍贵的药剂赠送给了你，希望能对你的探险提供帮助。"
  },
  [200060042] = {
    id = 200060042,
    name = "「你真是个好心人！」"
  },
  [200060043] = {
    id = 200060043,
    name = "「遇到你真是太幸运了，我的药剂研究、我的生命都可以继续向前了！」"
  },
  [200060044] = {
    id = 200060044,
    name = "「你们在这里做无本买卖这么久，就只能拿出这点？」"
  },
  [200060045] = {
    id = 200060045,
    name = "「好汉饶命啊！我、我们真的就只弄到这么点，现在深渊中骗子劫匪太多，傻子就那么一些，真的不好骗啊！」"
  },
  [200060046] = {
    id = 200060046,
    name = "「只要好汉能放过我们，我们兄弟一定不干这事了！」"
  },
  [200060047] = {
    id = 200060047,
    name = "「对，对对！我想起了，我知道几个干这行的，好汉你放过我们，下次我带你去找他们，他们很有钱的！」"
  },
  [200060048] = {
    id = 200060048,
    name = "你看眼前这几人着实也拿不出钱来了，便又警告了一番才放他们离开。"
  },
  [200060049] = {
    id = 200060049,
    name = "药剂师得知你帮他找回了财物，还帮他出了气，表现得非常高兴。"
  },
  [200060050] = {
    id = 200060050,
    name = "「遇到你真是太幸运了，我的药剂研究、我的生命都可以继续向前了！」"
  },
  [200060051] = {
    id = 200060051,
    name = "你对这个倒霉鬼的遭遇感到同情，决定资助他一些金币，同时叮嘱他别再贪便宜了。"
  },
  [200060052] = {
    id = 200060052,
    name = "药剂师非常感激你，送给你一些他曾经研制的药剂作为谢礼。"
  },
  [200060053] = {
    id = 200060053,
    name = "「你真是个好心人！」"
  },
  [200060054] = {
    id = 200060054,
    name = "「下次我一定不会再贪便宜了！」"
  },
  [200060055] = {
    id = 200060055,
    name = "看着药剂师慢慢远去的背影，你隐约有种不好的预感。"
  },
  [200060056] = {
    id = 200060056,
    name = "「下次吗......看来这次经历还没让他吸取到足够的教训。」"
  },
  [200060057] = {
    id = 200060057,
    name = "你没有接话，静静地站在一旁听他倒苦水。"
  },
  [200060058] = {
    id = 200060058,
    name = "药剂师将自己所有的辛酸事全部说了出来，随后又沉默了，盯着河流陷入沉思，直到你准备离去时，他才叫住了你。"
  },
  [200060059] = {
    id = 200060059,
    name = "「能拜托你送我回据点吗？」"
  },
  [200060060] = {
    id = 200060060,
    name = "「我果然还是没办法放弃药剂研究的梦想。」"
  },
  [200060061] = {
    id = 200060061,
    name = "（果然是不想死啊。）"
  },
  [200060062] = {
    id = 200060062,
    name = "在他一路痛斥骗子劫匪的无耻，以及憧憬研究成果的话语中，你护送他回到了据点。"
  },
  [200070001] = {
    id = 200070001,
    name = "一个女子正坐在树下哭泣。"
  },
  [200070002] = {
    id = 200070002,
    name = "你看她的衣着打扮并不像探险者，便上前询问。"
  },
  [200070003] = {
    id = 200070003,
    name = "见有人搭话，女人哭得更伤心了。"
  },
  [200070004] = {
    id = 200070004,
    name = "女人哭哭啼啼，好半天才说出了她的遭遇。"
  },
  [200070005] = {
    id = 200070005,
    name = "她与丈夫原来居住的据点被魔物袭击，两人便打算转移到更安全的圈落。"
  },
  [200070006] = {
    id = 200070006,
    name = "为了确保安全，他们还特意雇佣了探险队护送。"
  },
  [200070007] = {
    id = 200070007,
    name = "没想到出发不久，他们就遇到了一群魔物。"
  },
  [200070008] = {
    id = 200070008,
    name = "「呜呜......没想到，他们打不过魔物，就逃走进了林子，呜呜......」"
  },
  [200070009] = {
    id = 200070009,
    name = "「那魔物呢？」"
  },
  [200070010] = {
    id = 200070010,
    name = "「呜呜......当然是追着他们跑了，就留我一个人在这里，呜呜......」"
  },
  [200070011] = {
    id = 200070011,
    name = "「被抛弃了啊......」"
  },
  [200070012] = {
    id = 200070012,
    name = "「呜呜......你能找找我的丈夫吗，呜呜......」"
  },
  [200070013] = {
    id = 200070013,
    name = "你按照女人所指的方向前行，没走多远便发现了几名正与魔物战斗的人。"
  },
  [200070014] = {
    id = 200070014,
    name = "从服饰判断，那些人正是女人所说的探险者，于是你立即加入战斗。"
  },
  [200070015] = {
    id = 200070015,
    name = "在你的帮助下，众人很快将魔物全部击杀。"
  },
  [200070016] = {
    id = 200070016,
    name = "探险者们很感激你，但还没来得及表示谢意，他们便发现雇主不见了。"
  },
  [200070017] = {
    id = 200070017,
    name = "众人四下寻找，总算在一个角落发现了吓得瑟瑟发抖的雇主。"
  },
  [200070018] = {
    id = 200070018,
    name = "你告诉他，自己是受他妻子所托，前来帮忙的，他皱了皱眉，看起来很不满意。"
  },
  [200070019] = {
    id = 200070019,
    name = "原来男子本就想找机会甩掉没用的妻子，重新找一个能和他并肩的女人，所以不愿意跟你回去。"
  },
  [200070020] = {
    id = 200070020,
    name = "在几名探险者的保护下，男子带着行李毫不犹豫地离开了。"
  },
  [200070021] = {
    id = 200070021,
    name = "你回到女人所在之处，心中不免迟疑。"
  },
  [200070022] = {
    id = 200070022,
    name = "你告诉女人，她丈夫已经被魔物吃掉了，让她重新开始新的生活。"
  },
  [200070023] = {
    id = 200070023,
    name = "女人愣了愣，陷入了沉默，过了一会儿才喃喃道「那就算了吧」。"
  },
  [200070024] = {
    id = 200070024,
    name = "你问她以后有什么打算，女人说自己决定离开深渊，回到大陆寻找她的父母。"
  },
  [200070025] = {
    id = 200070025,
    name = "你决定帮人帮到底，将她送去了最近的圈落。"
  },
  [200070026] = {
    id = 200070026,
    name = "女人对你表示了感谢，并将一些物资送给了你。"
  },
  [200070027] = {
    id = 200070027,
    name = "「我要回家了，这些多余的物资也用不上，全都留给你吧。谢谢你，好心的探险者。」"
  },
  [200070028] = {
    id = 200070028,
    name = "你告诉女人，她的丈夫是为了甩掉她，才故意抛下她不管。"
  },
  [200070029] = {
    id = 200070029,
    name = "女人愣了愣，苦笑一声。"
  },
  [200070030] = {
    id = 200070030,
    name = "「为什么要告诉我真相呢。我一直想骗自己他不会这么做的。」"
  },
  [200070031] = {
    id = 200070031,
    name = "「没想到他真的这么狠心，把我扔在这里不顾我的死活。」"
  },
  [200070032] = {
    id = 200070032,
    name = "「我就说他之前鬼鬼祟祟，在和那些探险者说些什么，原来藏了这样的心思。」"
  },
  [200070033] = {
    id = 200070033,
    name = "女人说着，拿出了一个包裹。"
  },
  [200070034] = {
    id = 200070034,
    name = "「幸好我已经提前把行李中最值钱的东西全都拿出来了，他会乖乖回来找我的。」"
  },
  [200070035] = {
    id = 200070035,
    name = "「能麻烦你先把我送到最近的圈落吗？我会付你报酬的。」"
  },
  [200070036] = {
    id = 200070036,
    name = "你将她送去了最近的圈落，她交给你一些物资后便离开了。"
  },
  [200070037] = {
    id = 200070037,
    name = "你告诉女人，她丈夫既然已经抛弃了她，还找他干嘛？"
  },
  [200070038] = {
    id = 200070038,
    name = "「残忍，你真的太残忍了。」"
  },
  [200070039] = {
    id = 200070039,
    name = "「为什么要把这种事实说出来呢。」"
  },
  [200070040] = {
    id = 200070040,
    name = "「我一直想骗自己他不会这么做的。」"
  },
  [200070041] = {
    id = 200070041,
    name = "「没想到他真的这么狠心，把我扔在这里不顾我的死活。」"
  },
  [200070042] = {
    id = 200070042,
    name = "「要不是我提前把值钱的东西都拿了出来，现在真的就一无所有了。」"
  },
  [200070043] = {
    id = 200070043,
    name = "你叹了口气，问她接下来的打算。"
  },
  [200070044] = {
    id = 200070044,
    name = "她决定离开深渊，回到大陆寻找她的父母，重新开始新的生活。"
  },
  [200070045] = {
    id = 200070045,
    name = "她希望你能送她去最近的据点，之后再找机会返回大陆。"
  },
  [200070046] = {
    id = 200070046,
    name = "将女人安全护送到据点后，她送给你一些物资作为报酬。"
  },
  [200070047] = {
    id = 200070047,
    name = "「这些东西你们探险者应该用得上吧？谢谢你了，探险者。」"
  },
  [200070048] = {
    id = 200070048,
    name = "你从她身边路过却不搭理，女人哭得更大声了。"
  },
  [200070049] = {
    id = 200070049,
    name = "「呜呜......那边的探险者，看到女人在哭却不闻不问，真无情啊，呜呜......」"
  },
  [200070050] = {
    id = 200070050,
    name = "你无奈地过去问了她两句，她上下打量了你半晌，垂下了眼睛。"
  },
  [200070051] = {
    id = 200070051,
    name = "「呜呜......我迷路了，呜呜......」"
  },
  [200070052] = {
    id = 200070052,
    name = "虽然知道女人在撒谎，但一个普通人留在野外的确很危险，你静待她说出自己的目的。"
  },
  [200070053] = {
    id = 200070053,
    name = "果然，她是想让你带她去一个很远的圈落。"
  },
  [200070054] = {
    id = 200070054,
    name = "你无意介入她的事件中，只答应将她送至最近的据点。"
  },
  [200070055] = {
    id = 200070055,
    name = "她思考了一会儿，同意了你的提议。"
  },
  [200070056] = {
    id = 200070056,
    name = "你将她送到了最近的据点，她给你了一些物资作为酬劳。"
  },
  [200080001] = {
    id = 200080001,
    name = "「唉......」"
  },
  [200080002] = {
    id = 200080002,
    name = "你忽然听到附近传来一阵叹息声。"
  },
  [200080003] = {
    id = 200080003,
    name = "你循声看去，发现一名青年探险者。他离你并不算远，但在他出声前，你却没能觉察到他的存在。"
  },
  [200080004] = {
    id = 200080004,
    name = "青年探险者正对着一头死去的魔物叹息。"
  },
  [200080005] = {
    id = 200080005,
    name = "见你靠近，他惊讶地看着你。"
  },
  [200080006] = {
    id = 200080006,
    name = "「你竟然可以发现我。」"
  },
  [200080007] = {
    id = 200080007,
    name = "「我为什么不能发现你？你难道是幽灵吗？」"
  },
  [200080008] = {
    id = 200080008,
    name = "青年又叹了口气，说起了他的苦衷。"
  },
  [200080009] = {
    id = 200080009,
    name = "原来他从小就没什么存在感。"
  },
  [200080010] = {
    id = 200080010,
    name = "大部分人都很难注意到他，甚至连魔物也不例外。"
  },
  [200080011] = {
    id = 200080011,
    name = "不过他也因此获得了出色的潜行能力，成为了还算优秀的探险者。"
  },
  [200080012] = {
    id = 200080012,
    name = "可这样的能力，也给他的生活带来了诸多不便。"
  },
  [200080013] = {
    id = 200080013,
    name = "不管购物还是交流，他永远是被忽略的那一个。"
  },
  [200080014] = {
    id = 200080014,
    name = "这种失落感在他遇见喜欢的女孩后达到了顶峰。"
  },
  [200080015] = {
    id = 200080015,
    name = "「我昨天和她碰面，她一开始都没注意到我，甚至不记得我们以前见过。」"
  },
  [200080016] = {
    id = 200080016,
    name = "「唉，到底要怎样做，才能让她注意到我呢？」"
  },
  [200080017] = {
    id = 200080017,
    name = "「可我应该怎么做呢？大家说，追求一个女孩就要送她喜欢的东西。」"
  },
  [200080018] = {
    id = 200080018,
    name = "「我送过她很多东西了，可是一次回应都没有。」"
  },
  [200080019] = {
    id = 200080019,
    name = "「她看我的目光，甚至没有那个好吃懒做的同伴多。」"
  },
  [200080020] = {
    id = 200080020,
    name = "「这样啊，那送她东西的时候，你都说了什么？」"
  },
  [200080021] = {
    id = 200080021,
    name = "「难道不是在她睡着的时候，放在她的身边吗？」"
  },
  [200080022] = {
    id = 200080022,
    name = "青年说起他赠礼的经历。"
  },
  [200080023] = {
    id = 200080023,
    name = "从始至终，他竟然还没有主动和女孩说过一句话！"
  },
  [200080024] = {
    id = 200080024,
    name = "然而你从他的谈吐来看，并不存在沟通能力方面的问题。"
  },
  [200080025] = {
    id = 200080025,
    name = "难道是害羞导致他不敢靠近那个女孩？"
  },
  [200080026] = {
    id = 200080026,
    name = "你将想法告诉了他，他顿时涨红了脸。"
  },
  [200080027] = {
    id = 200080027,
    name = "「是的，这次的魔物，其实也是为她狩猎的。」"
  },
  [200080028] = {
    id = 200080028,
    name = "「只是，我还没想好要怎么送给她......」"
  },
  [200080029] = {
    id = 200080029,
    name = "「我也不知道，有时候我觉得自己像一个懦夫。」"
  },
  [200080030] = {
    id = 200080030,
    name = "「只是一个劲地想要她注意我，却什么事也做不到。」"
  },
  [200080031] = {
    id = 200080031,
    name = "「啊，真厌恶这样的自己啊。」"
  },
  [200080032] = {
    id = 200080032,
    name = "「连我自己都讨厌自己，她又怎么会喜欢呢......」"
  },
  [200080033] = {
    id = 200080033,
    name = "青年喃喃自语，陷入了纠结。"
  },
  [200080034] = {
    id = 200080034,
    name = "你转身走了很远，回头看去，那青年仍然站在原地，盯着魔物的尸体。"
  },
  [200080035] = {
    id = 200080035,
    name = "什么都没改变。"
  },
  [200080036] = {
    id = 200080036,
    name = "「去告诉她，最坏的结果，也不会比现在更差了吧。」"
  },
  [200080037] = {
    id = 200080037,
    name = "青年沉默良久，随即握紧了拳头。"
  },
  [200080038] = {
    id = 200080038,
    name = "「是的......你说得不错。」"
  },
  [200080039] = {
    id = 200080039,
    name = "「我想我应该做出改变了。」"
  },
  [200080040] = {
    id = 200080040,
    name = "他拿出解剖刀，两三下分解了魔物，将需要的素材收集了起来。"
  },
  [200080041] = {
    id = 200080041,
    name = "然后他又从包裹中拿出一些物资递给你。"
  },
  [200080042] = {
    id = 200080042,
    name = "「谢谢，这个是我的一点心意，请收下吧。」"
  },
  [200080043] = {
    id = 200080043,
    name = "他深吸了一口气，握紧双拳，迈着坚定的步伐离去，走向自己的刑场，等待心上人的判决。"
  },
  [200080044] = {
    id = 200080044,
    name = "「你为什么不尝试一下亲手送给她？」"
  },
  [200080045] = {
    id = 200080045,
    name = "「亲......亲手送给她？」"
  },
  [200080046] = {
    id = 200080046,
    name = "「把你的心意都告诉她，至少让她知道你的名字。」"
  },
  [200080047] = {
    id = 200080047,
    name = "听着你的话，青年嘴唇紧咬，双手不停地揉搓衣角。"
  },
  [200080048] = {
    id = 200080048,
    name = "「最坏的结果，也不会比现在更差了吧，她现在可是根本不知道你的存在。」"
  },
  [200080049] = {
    id = 200080049,
    name = "「我......真的可以做到吗？」"
  },
  [200080050] = {
    id = 200080050,
    name = "「很多事，需要做了才知道。」"
  },
  [200080051] = {
    id = 200080051,
    name = "青年沉默良久，随即握紧了拳头。"
  },
  [200080052] = {
    id = 200080052,
    name = "「是的......你说得不错。」"
  },
  [200080053] = {
    id = 200080053,
    name = "「失败的结果我已经尝试过了。」"
  },
  [200080054] = {
    id = 200080054,
    name = "「只要多出现在她面前，她也会注意到我的存在。」"
  },
  [200080055] = {
    id = 200080055,
    name = "「......你的这份心意，一定可以传达的。」"
  },
  [200080056] = {
    id = 200080056,
    name = "青年沉默片刻，随即如下定决心般重重地点了点头。"
  },
  [200080057] = {
    id = 200080057,
    name = "「谢谢你的鼓励，我感觉自己现在已经拥有了面对她的勇气。」"
  },
  [200080058] = {
    id = 200080058,
    name = "他拿出了一些物资送给你，随即开始麻利地分解魔物、收集素材，口中喃喃着「我可以」、「这次一定可以」之类的话语。"
  },
  [200080059] = {
    id = 200080059,
    name = "「你！你才注孤生！你这种人，一辈子都找不到恋人！」"
  },
  [200080060] = {
    id = 200080060,
    name = "「我是不会放弃的！我现在就去找她！」"
  },
  [200080061] = {
    id = 200080061,
    name = "青年麻利地分解了魔物，取走其中有用的素材。"
  },
  [200080062] = {
    id = 200080062,
    name = "随即轻哼一声，大踏步地离开了此地。"
  },
  [200080063] = {
    id = 200080063,
    name = "你揉了揉鼻子，发现地上还散落着些东西。"
  },
  [200080064] = {
    id = 200080064,
    name = "正是那急匆匆离去的青年没有带走的物资。"
  },
  [200080065] = {
    id = 200080065,
    name = "「咦，这些物资也不要了吗？算了，留在这里也只会被魔物糟蹋，我就不客气了」"
  },
  [200080066] = {
    id = 200080066,
    name = "你捡起地上的物资，悠哉地离开了。"
  },
  [200080067] = {
    id = 200080067,
    name = "「没戏吗......所以她才不想关注我吗......」"
  },
  [200080068] = {
    id = 200080068,
    name = "青年把头垂了下去，看起来更颓丧了。"
  },
  [200080069] = {
    id = 200080069,
    name = "「我明白了，她其实是借用我存在感低的这件事，想让我放弃吧。」"
  },
  [200080070] = {
    id = 200080070,
    name = "「既然这是她的意愿......」"
  },
  [200080071] = {
    id = 200080071,
    name = "青年失魂落魄地转身离开。"
  },
  [200080072] = {
    id = 200080072,
    name = "你提醒他这具魔物的尸体还未处理。"
  },
  [200080073] = {
    id = 200080073,
    name = "他愣了愣，露出一个苦笑。"
  },
  [200080074] = {
    id = 200080074,
    name = "「这本来是为她狩猎的。」"
  },
  [200080075] = {
    id = 200080075,
    name = "「现在已经没用了，随你处置吧。」"
  },
  [200080076] = {
    id = 200080076,
    name = "说罢，青年便头也不回地离开了。"
  },
  [200080077] = {
    id = 200080077,
    name = "「我是不是打击到他了？」"
  },
  [200080078] = {
    id = 200080078,
    name = "你处理了魔物的尸体，取走了其中有用的素材。"
  },
  [200090001] = {
    id = 200090001,
    name = "行至林中，你看到路边放着一个闪光的宝箱。"
  },
  [200090002] = {
    id = 200090002,
    name = "你走近看了看，宝箱被魔力屏障封锁，其中不知道装了什么宝物。"
  },
  [200090003] = {
    id = 200090003,
    name = "你四下观望了一番，没看到任何人。"
  },
  [200090004] = {
    id = 200090004,
    name = "「放在这么明显的地方，很明显是陷阱......不过，也有可能是横财。」"
  },
  [200090005] = {
    id = 200090005,
    name = "管他陷阱还是什么，你决定先打开再说，于是你谨慎地开启了宝箱的魔法屏障。"
  },
  [200090006] = {
    id = 200090006,
    name = "「现在应该安全了。」"
  },
  [200090007] = {
    id = 200090007,
    name = "你打开了箱子，闻到一股奇怪的味道。"
  },
  [200090008] = {
    id = 200090008,
    name = "还没看清宝箱中的东西，一阵眩晕感袭来，你晕倒在地。"
  },
  [200090009] = {id = 200090009, name = "......"},
  [200090010] = {
    id = 200090010,
    name = "苏醒后，你发现自己被捆绑了起来，两名探险者正怒气冲冲地看着你。"
  },
  [200090011] = {
    id = 200090011,
    name = "「就是你，竟然破坏了本小姐的作战计划，快赔我们的损失！」"
  },
  [200090012] = {
    id = 200090012,
    name = "「到底......怎么回事？」"
  },
  [200090013] = {
    id = 200090013,
    name = "原来女青年打算利用宝箱里的特殊药粉诱杀魔物，没想到被你破坏了。"
  },
  [200090014] = {
    id = 200090014,
    name = "「......用宝箱诱杀魔物？确定不是吸引探险者吗？」"
  },
  [200090015] = {
    id = 200090015,
    name = "女青年不依不饶，气急败坏地指责你，男青年则在一旁思索补救的办法。"
  },
  [200090016] = {
    id = 200090016,
    name = "最终，二人决定让你成为新的诱饵。"
  },
  [200090017] = {
    id = 200090017,
    name = "「都怪你破坏了我们的计划！现在诱饵被你毁了，就该由你去吸引魔物！」"
  },
  [200090018] = {
    id = 200090018,
    name = "「你们要抓的是什么魔物？」"
  },
  [200090019] = {
    id = 200090019,
    name = "「是一头巨型魔物。」"
  },
  [200090020] = {
    id = 200090020,
    name = "「我们蹲守了它很多天，一直没有出现，才想出了这个办法。」"
  },
  [200090021] = {
    id = 200090021,
    name = "「本来能抓到的。」"
  },
  [200090022] = {
    id = 200090022,
    name = "「都被你这个家伙破坏了！」"
  },
  [200090023] = {
    id = 200090023,
    name = "「宝箱真的可以引诱魔物？」"
  },
  [200090024] = {
    id = 200090024,
    name = "「这是大小姐的主意。」"
  },
  [200090025] = {
    id = 200090025,
    name = "「哼，那种闪闪发光的东西，谁会不喜欢？」"
  },
  [200090026] = {
    id = 200090026,
    name = "女青年怒不可遏，让你自己走进树林，再把魔物引出来由他们猎杀。"
  },
  [200090027] = {
    id = 200090027,
    name = "「我能拒绝吗？」"
  },
  [200090028] = {
    id = 200090028,
    name = "两人无视了你，为了让你不逃走，男青年一路跟你走到了树林深处。"
  },
  [200090029] = {
    id = 200090029,
    name = "他放出了一道烟雾吸引魔物，不多时你便感觉到了魔物接近的危机。"
  },
  [200090030] = {
    id = 200090030,
    name = "眼见魔物出现，男青年解开了你的绳索。"
  },
  [200090031] = {
    id = 200090031,
    name = "「可以逃了。」"
  },
  [200090032] = {
    id = 200090032,
    name = "然而不等你有所动作，魔物已然逼近，直扑你二人而来。"
  },
  [200090033] = {
    id = 200090033,
    name = "你见已错过最佳的逃跑机会，抬手便是一记魔法轰向魔物。"
  },
  [200090034] = {
    id = 200090034,
    name = "在你全力攻击下，魔物很快被斩杀。"
  },
  [200090035] = {
    id = 200090035,
    name = "那二人站在不远处看着这一切，女青年的表情显得非常复杂。"
  },
  [200090036] = {
    id = 200090036,
    name = "「你这个家伙，竟然还有点本事。」"
  },
  [200090037] = {
    id = 200090037,
    name = "「既然是你杀了它，那就归你了。」"
  },
  [200090038] = {
    id = 200090038,
    name = "她招呼着男青年匆忙离去，看样子并不想继续和你扯上关系。"
  },
  [200090039] = {
    id = 200090039,
    name = "你取下了魔物身上有用的素材，没有计较太多，重新上路了。"
  },
  [200090040] = {
    id = 200090040,
    name = "「终于出现了！」"
  },
  [200090041] = {
    id = 200090041,
    name = "女青年兴奋地扔出各种魔法道具，与此同时，你们也一起加入了战斗。"
  },
  [200090042] = {
    id = 200090042,
    name = "巨型魔物倒下，男青年默默地割取素材，女青年走向你，面露欣赏。"
  },
  [200090043] = {
    id = 200090043,
    name = "「咳咳，你挺厉害的嘛，不过魔物归我了，这些算是给你的报酬。」"
  },
  [200090044] = {
    id = 200090044,
    name = "她扔给你一袋金币，你掂了掂，很有分量。"
  },
  [200090045] = {
    id = 200090045,
    name = "你将酬金收下，轻笑一声，告别了这奇怪的二人组。"
  },
  [200090046] = {
    id = 200090046,
    name = "「敬酒不吃吃罚酒，把他扔进林子里！」"
  },
  [200090047] = {
    id = 200090047,
    name = "绳索被魔法强化过，你一时无法挣脱。"
  },
  [200090048] = {
    id = 200090048,
    name = "你被男青年拖进了树林，扔在了树林深处，他在你身边放出了一道烟雾。"
  },
  [200090049] = {
    id = 200090049,
    name = "隔了不久，你察觉到危险，回头看到一头巨型魔物正向你奔来。"
  },
  [200090050] = {
    id = 200090050,
    name = "你双手被缚无法行动，只能不停奔逃。"
  },
  [200090051] = {
    id = 200090051,
    name = "「终于出现了！」"
  },
  [200090052] = {
    id = 200090052,
    name = "女青年兴奋地扔出各种魔法道具，与此同时，男青年加入了战斗。"
  },
  [200090053] = {
    id = 200090053,
    name = "两人合作，费了不少力气才杀掉这头巨型魔物。"
  },
  [200090054] = {
    id = 200090054,
    name = "男青年默默地割取素材，女青年走向你，神色高傲，眼中满是鄙夷。"
  },
  [200090055] = {
    id = 200090055,
    name = "「你这个家伙，也算将功补过，本小姐就不追究了！」"
  },
  [200090056] = {
    id = 200090056,
    name = "说着，她伸手从你眼前划过，一缕香气袭来，你再次晕了过去。"
  },
  [200090057] = {id = 200090057, name = "......"},
  [200090058] = {
    id = 200090058,
    name = "醒来的时候，你的双手已经被解开。"
  },
  [200090059] = {
    id = 200090059,
    name = "身边放着一袋金币，如同对你的施舍和嘲笑。"
  },
  [200090060] = {
    id = 200090060,
    name = "「......神经病。」"
  },
  [200090061] = {
    id = 200090061,
    name = "这么明显的陷阱你才不会上当，你继续往树林深处走去，听见了魔物发出的低沉声响。"
  },
  [200090062] = {
    id = 200090062,
    name = "你小心翼翼地靠近声源处，看见一头巨型的魔物正在睡觉。"
  },
  [200090063] = {
    id = 200090063,
    name = "「好机会。」"
  },
  [200090064] = {
    id = 200090064,
    name = "你凝聚魔力，全力施放出一记魔法轰向魔物。"
  },
  [200090065] = {
    id = 200090065,
    name = "魔物甚至来不及发出任何声响便被你击杀。"
  },
  [200090066] = {
    id = 200090066,
    name = "你正悠闲地收集着魔物身上的素材，忽然听到有人靠近。"
  },
  [200090067] = {
    id = 200090067,
    name = "你迅速将所有素材收起，离开了现场。"
  },
  [200090068] = {
    id = 200090068,
    name = "你将箱子抱了起来，准备去附近据点找人打开，这样就算是陷阱也不用担心。"
  },
  [200090069] = {
    id = 200090069,
    name = "一男一女忽然朝你跑来，拦住了你。"
  },
  [200090070] = {
    id = 200090070,
    name = "「你这个小偷，竟然偷了我的宝箱！」"
  },
  [200090071] = {
    id = 200090071,
    name = "「这是你的？」"
  },
  [200090072] = {
    id = 200090072,
    name = "「这是我放在树林里的，快还给本小姐！」"
  },
  [200090073] = {
    id = 200090073,
    name = "「你怎么证明这个箱子是你的？」"
  },
  [200090074] = {
    id = 200090074,
    name = "「你！」"
  },
  [200090075] = {
    id = 200090075,
    name = "温和的男青年看你实力不俗，拦下了准备发作的女青年。"
  },
  [200090076] = {
    id = 200090076,
    name = "「到底......怎么回事？」"
  },
  [200090077] = {
    id = 200090077,
    name = "原来女青年正打算利用箱子里的特殊药粉诱杀魔物。"
  },
  [200090078] = {
    id = 200090078,
    name = "「......用宝箱做诱饵，只能引诱到探险者吧？」"
  },
  [200090079] = {
    id = 200090079,
    name = "听你这么说，女青年更生气了。"
  },
  [200090080] = {
    id = 200090080,
    name = "她让你把宝箱还给她。"
  },
  [200090081] = {
    id = 200090081,
    name = "看她信誓旦旦的样子，也许宝箱里真的只是药粉而已。"
  },
  [200090082] = {
    id = 200090082,
    name = "你把箱子还给了两人，男青年向你道谢，并将箱子重新放回了原位。"
  },
  [200090083] = {
    id = 200090083,
    name = "你悻悻地离开了树林。"
  },
  [200090084] = {
    id = 200090084,
    name = "你告诉二人，真要对付魔物，与其采用这些愚蠢的手段，不如多找些人手。"
  },
  [200090085] = {
    id = 200090085,
    name = "男青年认为你的提议不错，如果你能帮忙，或许可以轻松战胜魔物，你暂无要紧事务，便与他们一起前往密林深处。"
  },
  [200090086] = {
    id = 200090086,
    name = "男青年放出了一道奇怪的烟雾吸引魔物。"
  },
  [200090087] = {
    id = 200090087,
    name = "没过一会儿，果然有一头巨型魔物嗅着烟雾向你们走来。"
  },
  [200090088] = {
    id = 200090088,
    name = "「来了。」"
  },
  [200090089] = {
    id = 200090089,
    name = "你凝聚魔力，全力施放出魔法轰向魔物。"
  },
  [200090090] = {
    id = 200090090,
    name = "在你们三人的配合下，魔物很快被斩杀。"
  },
  [200090091] = {
    id = 200090091,
    name = "「你这个家伙，竟然还有点本事。」"
  },
  [200090092] = {
    id = 200090092,
    name = "「既然你出了大部分力气，那就由你先拿了。」"
  },
  [200090093] = {
    id = 200090093,
    name = "你从魔物身上取下了部分对你有用的素材，剩下的则留给了两人。"
  },
  [200090094] = {
    id = 200090094,
    name = "男青年呼出一口气，感谢了你的帮助，他迅速收集好剩下的素材，拉着女青年急匆匆地离开了。"
  },
  [200100001] = {
    id = 200100001,
    name = "「我是无辜的！我没有杀人！」"
  },
  [200100002] = {
    id = 200100002,
    name = "「听到没有，快放了我！」"
  },
  [200100003] = {
    id = 200100003,
    name = "「你们这两个瞎了眼的家伙！竟然冤枉我！」"
  },
  [200100004] = {
    id = 200100004,
    name = "前方传来一阵骂喊声，你看到两名探险者羁押着一个大肚子男人。"
  },
  [200100005] = {
    id = 200100005,
    name = "那大肚子男人高喊自己冤枉，见你出现，仿佛看到了救星，请求你帮帮他。"
  },
  [200100006] = {
    id = 200100006,
    name = "「我只是看到有人倒在血泊里，想帮忙扶起来而已！」"
  },
  [200100007] = {
    id = 200100007,
    name = "他虽然双手沾着血渍，但仍努力争辩着。"
  },
  [200100008] = {
    id = 200100008,
    name = "不远处的案发现场，受害者正躺在血泊中。"
  },
  [200100009] = {
    id = 200100009,
    name = "「他们根本不听我的辩解，就把我当成了凶手！」"
  },
  [200100010] = {
    id = 200100010,
    name = "「别狡辩了，你就是凶手！」"
  },
  [200100011] = {
    id = 200100011,
    name = "「一会儿就乖乖偿命吧！」"
  },
  [200100012] = {
    id = 200100012,
    name = "「这位先生，等一下！」"
  },
  [200100013] = {
    id = 200100013,
    name = "「你先别走，你救救我啊，我是冤枉的！」"
  },
  [200100014] = {
    id = 200100014,
    name = "你不想蹚这趟浑水，扭头离去。"
  },
  [200100015] = {
    id = 200100015,
    name = "还没走多远，你就看到之前被羁押的男人跑了过来。"
  },
  [200100016] = {
    id = 200100016,
    name = "「这事与你无关，就当没看到我啊！」"
  },
  [200100017] = {
    id = 200100017,
    name = "说完他就跑向了前方岔道口的右侧，消失在你的视野中。"
  },
  [200100018] = {
    id = 200100018,
    name = "不一会儿，一名探险者也追了上来。"
  },
  [200100019] = {
    id = 200100019,
    name = "「刚才那个杀人犯跑去哪儿了！」"
  },
  [200100020] = {
    id = 200100020,
    name = "「你看到了吗？」"
  },
  [200100021] = {
    id = 200100021,
    name = "你向他指明了方向，探险者向你道谢，急忙赶了过去。"
  },
  [200100022] = {
    id = 200100022,
    name = "没过多久，大肚子男人被追赶着又逃了回来。"
  },
  [200100023] = {
    id = 200100023,
    name = "「就是你这个多管闲事的家伙出卖我的吧？」"
  },
  [200100024] = {
    id = 200100024,
    name = "男人突然将一件东西砸了过来，你条件性地想要防御，他却突然窜出，想从你身旁逃走。"
  },
  [200100025] = {
    id = 200100025,
    name = "你伸腿一绊，大肚子男人摔了个四脚朝天。他见你身手不凡，急忙向你求饶。"
  },
  [200100026] = {
    id = 200100026,
    name = "「用这种阴损的手段，那人果然就是你杀的吧？」"
  },
  [200100027] = {
    id = 200100027,
    name = "「阁下饶命啊，我把值钱的东西都给你，你放过我吧！」"
  },
  [200100028] = {
    id = 200100028,
    name = "他从身上倒出了许多宝石与赃物，哗啦啦洒了一地，身形一下变得瘦弱起来。"
  },
  [200100029] = {
    id = 200100029,
    name = "「原来这也是伪装啊。」"
  },
  [200100030] = {
    id = 200100030,
    name = "探险者追了上来，看见你已经制服了凶手，松了口气。"
  },
  [200100031] = {
    id = 200100031,
    name = "他将其中的一块宝石捡了起来。"
  },
  [200100032] = {
    id = 200100032,
    name = "他说那块宝石是受害者的，并且他们也是在查验受害者伤口后，才断定大肚子男人是凶手。"
  },
  [200100033] = {
    id = 200100033,
    name = "你将杀人犯的赃物都交给了他，他却只拿走了那颗宝石，把其余的赃物都留给了你。"
  },
  [200100034] = {
    id = 200100034,
    name = "「该怎么处理呢？」"
  },
  [200100035] = {
    id = 200100035,
    name = "「谢了！这是那家伙的好东西，就留给你了。」"
  },
  [200100036] = {
    id = 200100036,
    name = "他扔给你一块宝石后就立即逃走了，不一会儿那名探险者追了上来。"
  },
  [200100037] = {
    id = 200100037,
    name = "他看到你手中的宝石，怒气冲天。"
  },
  [200100038] = {
    id = 200100038,
    name = "「你跟他是一伙的！」"
  },
  [200100039] = {
    id = 200100039,
    name = "探险者不由分说向你攻击。"
  },
  [200100040] = {
    id = 200100040,
    name = "然而他根本不是你的对手，很快被你击败。你将他制服后便告知了他事情的原委。"
  },
  [200100041] = {
    id = 200100041,
    name = "他愤恨地告诉你，那块宝石是受害者的，并且他们也是在查验受害者伤口后，才断定大肚子男人是凶手。"
  },
  [200100042] = {
    id = 200100042,
    name = "「那家伙就是杀人凶手！」"
  },
  [200100043] = {
    id = 200100043,
    name = "你将宝石交给了他，探险者收下宝石，有些不甘地哼了一声，继续向大肚子男人消失的方向追去。"
  },
  [200100044] = {
    id = 200100044,
    name = "「......」"
  },
  [200100045] = {
    id = 200100045,
    name = "你摊了摊手，表示没有注意到，他判断了一番，向岔道口左侧追去。"
  },
  [200100046] = {
    id = 200100046,
    name = "你停留了一会儿，选择了走向大肚子男人逃亡的那条路。"
  },
  [200100047] = {
    id = 200100047,
    name = "「是你啊。」"
  },
  [200100048] = {
    id = 200100048,
    name = "大肚子男人从路旁钻了出来，向你道谢。"
  },
  [200100049] = {
    id = 200100049,
    name = "他拿出了一枚金币抛向你，你下意识接住。"
  },
  [200100050] = {
    id = 200100050,
    name = "你感觉掌心像被针刺了一下，疼痛快速蔓延到了胳膊、大脑，很快你就失去了知觉。"
  },
  [200100051] = {
    id = 200100051,
    name = "等再次醒来，你发现身上的财物已被洗劫一空，身边只留下了一张纸条。"
  },
  [200100052] = {
    id = 200100052,
    name = "「看你没有揭穿我的份儿上，饶你一命。」"
  },
  [200100053] = {
    id = 200100053,
    name = "你上前劝阻，两名探险者情绪激动，认为你不辨黑白，包庇杀人凶手，跟你动起手来。"
  },
  [200100054] = {
    id = 200100054,
    name = "在你与两人打斗时，那个大肚子男人趁机溜走了。"
  },
  [200100055] = {
    id = 200100055,
    name = "两名探险者气急败坏，责怪你放跑了杀人犯。"
  },
  [200100056] = {
    id = 200100056,
    name = "一个人追着凶手而去，另一个人则打算背起尸体跟上去。"
  },
  [200100057] = {
    id = 200100057,
    name = "你发现受害者的腹部有一处撕裂的伤口，看样子是魔物爪牙造成的。"
  },
  [200100058] = {
    id = 200100058,
    name = "「......凶手是魔物？」"
  },
  [200100059] = {
    id = 200100059,
    name = "你们二人在附近查找，找到了一段被斩落的魔物肢体。"
  },
  [200100060] = {
    id = 200100060,
    name = "肢体上的利爪还残留着鲜血，形状也和受害者的伤口相符。"
  },
  [200100061] = {
    id = 200100061,
    name = "这时另一名探险者也回来了，他没有追上大肚子男人，让他逃走了。"
  },
  [200100062] = {
    id = 200100062,
    name = "说话间，一头断了前肢的魔物突然跳了出来。"
  },
  [200100063] = {
    id = 200100063,
    name = "你们迅速做出反应，很快将魔物击杀。"
  },
  [200100064] = {
    id = 200100064,
    name = "「就是这只？」"
  },
  [200100065] = {
    id = 200100065,
    name = "两人开始采集魔物身上的素材，你则再次查验起遇难探险者的情况。"
  },
  [200100066] = {
    id = 200100066,
    name = "仔细查看下，你发现遇难的探险者身上存在多处伤口，其中最致命的，却并非是魔物造成。"
  },
  [200100067] = {
    id = 200100067,
    name = "（难道魔物不是真凶？）"
  },
  [200100068] = {
    id = 200100068,
    name = "你还在思考的时候，两人已经收拾完毕，他们丢给你一个小包裹。"
  },
  [200100069] = {
    id = 200100069,
    name = "「这份算你的。」"
  },
  [200100070] = {
    id = 200100070,
    name = "说罢，二人背着遇难者渐渐远去，你心情复杂。"
  },
  [200100071] = {
    id = 200100071,
    name = "原来是这两名探险者的同伴遇难了。"
  },
  [200100072] = {
    id = 200100072,
    name = "在杀人现场只发现了这名大肚子男人。"
  },
  [200100073] = {
    id = 200100073,
    name = "于是两名探险者便认定此人就是杀人凶手。"
  },
  [200100074] = {
    id = 200100074,
    name = "你走向不远处的案发现场，查验起遇难者的遗体。"
  },
  [200100075] = {
    id = 200100075,
    name = "你发现遇难者腹部有一道明显的伤口，从形状来看，并不像利器所伤，更像是魔物造成。"
  },
  [200100076] = {
    id = 200100076,
    name = "你指出了疑点，怀疑受害人是因魔物导致的死亡，而不是男人导致。"
  },
  [200100077] = {
    id = 200100077,
    name = "「他说得不错，我只是看到有人倒在血泊里才去救人，我冤枉啊！」"
  },
  [200100078] = {
    id = 200100078,
    name = "两名探险者半信半疑，便在附近调查了一番，还真发现了一截被斩落的魔物肢体。"
  },
  [200100079] = {
    id = 200100079,
    name = "肢体上的利爪还残留着鲜血，形状也和受害者的伤口相符。"
  },
  [200100080] = {
    id = 200100080,
    name = "二人确定了同伴是被魔物所杀，决定为同伴报仇。"
  },
  [200100081] = {
    id = 200100081,
    name = "「现在真相大白，可以放过我了吗？」"
  },
  [200100082] = {
    id = 200100082,
    name = "二人还在犹豫时，一头断了前肢的魔物突然跳出来，扑向你们。"
  },
  [200100083] = {
    id = 200100083,
    name = "「吼——」"
  },
  [200100084] = {
    id = 200100084,
    name = "你与二人联手，很快将魔物击杀。"
  },
  [200100085] = {
    id = 200100085,
    name = "「这样就算报仇了吗？」"
  },
  [200100086] = {
    id = 200100086,
    name = "「总觉得不甘心啊......」"
  },
  [200100087] = {
    id = 200100087,
    name = "两人向你致谢，带着同伴的尸体离开了。"
  },
  [200100088] = {
    id = 200100088,
    name = "「真可怜呢。」"
  },
  [200100089] = {
    id = 200100089,
    name = "大肚子男人望着远去的二人，嘀咕了几句。"
  },
  [200100090] = {
    id = 200100090,
    name = "「？？？」"
  },
  [200100091] = {
    id = 200100091,
    name = "「没什么。谢谢啦，好心人，这只魔物就留给你处理啦。」"
  },
  [200100092] = {
    id = 200100092,
    name = "说罢，男人也转身离去。"
  },
  [200100093] = {
    id = 200100093,
    name = "结局还算不错，但你总觉得似乎哪里不对。"
  },
  [200110001] = {
    id = 200110001,
    name = "「前面那位，请等一下！」"
  },
  [200110002] = {
    id = 200110002,
    name = "有人突然叫住了你。"
  },
  [200110003] = {
    id = 200110003,
    name = "你转头看去，叫住你的是一名眼眶通红的少女，她看起来非常悲伤。"
  },
  [200110004] = {
    id = 200110004,
    name = "「不好意思，请问可以帮我一个忙吗？」"
  },
  [200110005] = {
    id = 200110005,
    name = "「有什么事吗？」"
  },
  [200110006] = {
    id = 200110006,
    name = "少女自称是鹰猎探险队的成员。"
  },
  [200110007] = {
    id = 200110007,
    name = "她的队长前几日在探路时遇难，但他的遗骨却至今还未回收。"
  },
  [200110008] = {
    id = 200110008,
    name = "少女所在的队伍现在已经选出了新的队长，出于安全考虑，决定放弃回收。"
  },
  [200110009] = {
    id = 200110009,
    name = "只有少女仍在坚持，她知道希望渺茫，但依然想要将前队长的遗骨回收，让他安息。"
  },
  [200110010] = {
    id = 200110010,
    name = "「为什么你不去呢？」"
  },
  [200110011] = {
    id = 200110011,
    name = "「我实力低微，而且掌握的基本都是支援型魔法，难以独自战斗。」"
  },
  [200110012] = {
    id = 200110012,
    name = "「其他人都觉得太过危险，不想为了一个已经死去的人犯险。」"
  },
  [200110013] = {
    id = 200110013,
    name = "「所以没人愿意帮我。」"
  },
  [200110014] = {
    id = 200110014,
    name = "「你能帮帮我吗，拜托了。」"
  },
  [200110015] = {
    id = 200110015,
    name = "她非常感激你，告诉了你大概的位置、路线，以及周围的魔物信息。"
  },
  [200110016] = {
    id = 200110016,
    name = "「如果实在找不到也不用勉强，请一定注意安全。」"
  },
  [200110017] = {
    id = 200110017,
    name = "你根据少女的指引进入了密林。"
  },
  [200110018] = {
    id = 200110018,
    name = "沿着他们曾经的路线行进，在一棵大树下，你发现了散落的遗骸。"
  },
  [200110019] = {
    id = 200110019,
    name = "遗骸不远处，还有一柄断裂的长弓。结合少女说过的话，你确认了遗骸的身份。"
  },
  [200110020] = {
    id = 200110020,
    name = "「应该就是这个了。」"
  },
  [200110021] = {
    id = 200110021,
    name = "你收敛遗骸和遗物时，忽然感受到一道冰冷的视线。"
  },
  [200110022] = {
    id = 200110022,
    name = "你正欲有所动作，魔物已然扑了上来。"
  },
  [200110023] = {
    id = 200110023,
    name = "你见无可退避，便迅速展开防御，借着魔物的攻击顺势滚到一旁，再向魔物发起攻击。"
  },
  [200110024] = {
    id = 200110024,
    name = "费了些精力，你将魔物斩杀，重新收敛地上遗骸和遗物。"
  },
  [200110025] = {
    id = 200110025,
    name = "「嗯？这是什么？」"
  },
  [200110026] = {
    id = 200110026,
    name = "你发现了一封残缺的信，便捡了起来查看内容。"
  },
  [200110027] = {
    id = 200110027,
    name = "信是另一个探险队写给死者的。"
  },
  [200110028] = {
    id = 200110028,
    name = "大概内容是他们只接受死者一人加入，让死者找机会摆脱那些弱小的成员，前往指定地点与他们会合。"
  },
  [200110029] = {
    id = 200110029,
    name = "「......这是背叛了原来的队伍，前往与新队伍会合的途中遇到意外了吧。」"
  },
  [200110030] = {
    id = 200110030,
    name = "你摇了摇头，将收敛好的东西都包裹起来，沿着原路返回。"
  },
  [200110031] = {id = 200110031, name = "......"},
  [200110032] = {
    id = 200110032,
    name = "你将包裹交给了少女。"
  },
  [200110033] = {
    id = 200110033,
    name = "她尽管已经做好了心理准备，但在看到那柄断裂的长弓时，依然崩溃地哭了出来。"
  },
  [200110034] = {
    id = 200110034,
    name = "（......要不要把信件给她呢？）"
  },
  [200110035] = {
    id = 200110035,
    name = "「这就是他所有的遗物吗？」"
  },
  [200110036] = {
    id = 200110036,
    name = "你点点头，少女露出苦涩的笑容。"
  },
  [200110037] = {
    id = 200110037,
    name = "「总算把他带了回来，这下他也能安息了......」"
  },
  [200110038] = {
    id = 200110038,
    name = "「其实他是我的恋人。」"
  },
  [200110039] = {
    id = 200110039,
    name = "「他还说要鞭笞我成长，直到能和他并肩而行。」"
  },
  [200110040] = {
    id = 200110040,
    name = "「我一直这样憧憬着。」"
  },
  [200110041] = {
    id = 200110041,
    name = "「现在，一直憧憬的人死掉了，我活着还有什么意义呢。」"
  },
  [200110042] = {
    id = 200110042,
    name = "少女沉默良久，长舒了一口气，露出一个释然的笑容。"
  },
  [200110043] = {
    id = 200110043,
    name = "「以后我会一直带着这柄断弓，就像他从未离我远去。」"
  },
  [200110044] = {
    id = 200110044,
    name = "「非常感谢你帮我把他带了回来，这里有些物资，还请不要客气。」"
  },
  [200110045] = {
    id = 200110045,
    name = "少女带着她的恋人离去了，你看着她消失的背影，不禁有些感慨。"
  },
  [200110046] = {
    id = 200110046,
    name = "「这是......」"
  },
  [200110047] = {
    id = 200110047,
    name = "「这......他要抛弃我们......」"
  },
  [200110048] = {
    id = 200110048,
    name = "「怎么会这样......呵......」"
  },
  [200110049] = {
    id = 200110049,
    name = "「呵呵呵呵......」"
  },
  [200110050] = {
    id = 200110050,
    name = "「原来我们在他心里，是随时可以抛弃的、弱小的累赘......」"
  },
  [200110051] = {
    id = 200110051,
    name = "「他对我总是很严厉。」"
  },
  [200110052] = {
    id = 200110052,
    name = "「我以为他只是想让我快一些成长，让我能尽快与他并肩前行。」"
  },
  [200110053] = {
    id = 200110053,
    name = "「没想到......呵呵呵，真是没想到......」"
  },
  [200110054] = {
    id = 200110054,
    name = "「这位先生，谢谢你，让我知道了这一切。」"
  },
  [200110055] = {
    id = 200110055,
    name = "「这里有些物资，还请收下。我要去和队友们会合了。」"
  },
  [200110056] = {
    id = 200110056,
    name = "「......」"
  },
  [200110057] = {
    id = 200110057,
    name = "「已经没有什么值得留恋的了。」"
  },
  [200110058] = {
    id = 200110058,
    name = "少女露出一个惨淡的笑容，向你行了一礼，消失在了道路尽头。"
  },
  [200110059] = {
    id = 200110059,
    name = "你以武技低微的理由拒绝了少女，建议她找专业的队伍帮忙，如此也能保障安全。"
  },
  [200110060] = {
    id = 200110060,
    name = "少女愣了愣，短暂沉默后，她向你表示了感谢，转身离开了。"
  },
  [200110061] = {
    id = 200110061,
    name = "你没有搭理少女，径直朝着密林走去。"
  },
  [200110062] = {
    id = 200110062,
    name = "少女看着你离去的背影，嘴巴张了张，似乎想喊住你，但直到你从她视野消失，也没有出声。"
  },
  [200110063] = {
    id = 200110063,
    name = "进入密林不久，你突然感觉到一股寒意，像是有什么东西躲在暗处紧盯着你。"
  },
  [200110064] = {
    id = 200110064,
    name = "你不敢大意，小心翼翼地前行。"
  },
  [200110065] = {
    id = 200110065,
    name = "你走到一棵大树下，发现一些散落的骸骨，从痕迹来看，应该是不久前遇害的探险者。"
  },
  [200110066] = {
    id = 200110066,
    name = "正当你观察四周时，一头魔物突然窜出，径直扑你而来。"
  },
  [200110067] = {
    id = 200110067,
    name = "所幸你早有准备，在魔物出现的瞬间便闪躲开来，随即向魔物发起了攻击。"
  },
  [200110068] = {
    id = 200110068,
    name = "经过一番战斗，你成功将魔物击杀，取走有用素材后，你继续向远处走去。"
  },
  [200120001] = {
    id = 200120001,
    name = "「嗯？」"
  },
  [200120002] = {
    id = 200120002,
    name = "走至偏远的山脚，你被某个东西绊了一下，低头看去，发现是一段人类的腿骨。"
  },
  [200120003] = {
    id = 200120003,
    name = "仔细一看，这具骸骨表面大部分都被风沙侵蚀，不过整体还算完整。"
  },
  [200120004] = {
    id = 200120004,
    name = "该骸骨背靠山崖坐在角落，头部抬起，似乎正在仰望天空。"
  },
  [200120005] = {
    id = 200120005,
    name = "骸骨的胸腹部分，可以看到一团明显的黑紫色。"
  },
  [200120006] = {
    id = 200120006,
    name = "「看来是中毒死去的。」"
  },
  [200120007] = {
    id = 200120007,
    name = "你叹了口气，准备离开时，发现那骸骨身旁有一个不起眼的盒子。"
  },
  [200120008] = {
    id = 200120008,
    name = "你扫了扫尘泥，盒子表面露出了精致华美的图案。"
  },
  [200120009] = {
    id = 200120009,
    name = "（盒子里面装的什么？）"
  },
  [200120010] = {
    id = 200120010,
    name = "你打开盒子，里面猛地窜出一股烟雾，随即幻化为一头恐怖的魔物！"
  },
  [200120011] = {
    id = 200120011,
    name = "你与魔物缠斗了起来，费了些力气才将其杀掉。"
  },
  [200120012] = {
    id = 200120012,
    name = "「这是什么魔物？」"
  },
  [200120013] = {
    id = 200120013,
    name = "你打败魔物后，那东西又溃散为烟雾，消失在了空气中，随即盒子中显露出一本书籍。"
  },
  [200120014] = {
    id = 200120014,
    name = "你正打算查看，突然听到身后传来脚步声。"
  },
  [200120015] = {
    id = 200120015,
    name = "你回头看去，来人是一名年轻的探险者。"
  },
  [200120016] = {
    id = 200120016,
    name = "「我说，好东西是不是该见者有份啊。」"
  },
  [200120017] = {
    id = 200120017,
    name = "探险者也看到了那本书籍，书籍包装精美，甚至用魔法保护着外层。"
  },
  [200120018] = {
    id = 200120018,
    name = "「死前都要放在手边，一定是很有用的魔法秘籍。」"
  },
  [200120019] = {
    id = 200120019,
    name = "「或者失传已久的炼药秘方。」"
  },
  [200120020] = {
    id = 200120020,
    name = "「也有可能是极为珍贵的魔物笔记......」"
  },
  [200120021] = {
    id = 200120021,
    name = "他提出了诸多猜测，随后上前和你商量。"
  },
  [200120022] = {
    id = 200120022,
    name = "「既然我们同时发现了这本书——」"
  },
  [200120023] = {
    id = 200120023,
    name = "「打个商量，我给你钱，这东西归我怎么样？」"
  },
  [200120024] = {
    id = 200120024,
    name = "「好东西当然见者有份。」"
  },
  [200120025] = {
    id = 200120025,
    name = "「噢，兄弟真是慷慨啊！那我们快打开看看吧！」"
  },
  [200120026] = {
    id = 200120026,
    name = "在他期待的眼光中，你小心翼翼地翻开了书籍......"
  },
  [200120027] = {
    id = 200120027,
    name = "「wohoo......这、这真是一本奇书啊！」"
  },
  [200120028] = {
    id = 200120028,
    name = "你快速合上了书籍。"
  },
  [200120029] = {
    id = 200120029,
    name = "「喂，再给我看一眼，我刚才什么都没看见！」"
  },
  [200120030] = {
    id = 200120030,
    name = "「......」"
  },
  [200120031] = {
    id = 200120031,
    name = "「说好的见者有份啊！快再给我看一眼。」"
  },
  [200120032] = {
    id = 200120032,
    name = "「我没有在陌生人面前看这种书的习惯，不过，你好像很喜欢这本书？」"
  },
  [200120033] = {
    id = 200120033,
    name = "「谁能不喜欢呢，我可不自欺欺人。」"
  },
  [200120034] = {
    id = 200120034,
    name = "「在孤独的夜晚，这简直就是抚慰心灵的极品。」"
  },
  [200120035] = {
    id = 200120035,
    name = "「兄弟，我有个主意。」"
  },
  [200120036] = {
    id = 200120036,
    name = "「如果把这本书复刻发行，一定能成为深渊中的畅销书！」"
  },
  [200120037] = {
    id = 200120037,
    name = "你俩一拍即合，随即开始制定计划，联系商人制作贩售。"
  },
  [200120038] = {
    id = 200120038,
    name = "然而正当你们投入大价钱复刻印刷时，突然有人找了过来。"
  },
  [200120039] = {
    id = 200120039,
    name = "来人正是此书的作者，他要求你们立即终止贩书计划，否则要让你们赔偿。"
  },
  [200120040] = {
    id = 200120040,
    name = "你们极力与原作者沟通，希望他能同意甚至加入这个商业计划，但他始终不为所动。"
  },
  [200120041] = {
    id = 200120041,
    name = "无奈之下，你们只得放弃。"
  },
  [200120042] = {
    id = 200120042,
    name = "你认为他的想法很好，但你没有兴趣加入他的商业计划。"
  },
  [200120043] = {
    id = 200120043,
    name = "于是，他为了带走书本给了你一些补偿，并约定等到正式贩售后，再按比例给你分利。"
  },
  [200120044] = {
    id = 200120044,
    name = "然而一段时间后，你等来的并非是利润分配，而是他破产的消息。"
  },
  [200120045] = {
    id = 200120045,
    name = "据说原作者找上了他，无奈之下他只得终止已经投入了巨大资金的计划......"
  },
  [200120046] = {
    id = 200120046,
    name = "那一刻，你很庆幸当初没有答应他的提议。"
  },
  [200120047] = {
    id = 200120047,
    name = "「哼！你不要敬酒不吃吃罚酒！」"
  },
  [200120048] = {
    id = 200120048,
    name = "他伸手就要去拿盒子里的书籍，被你一把打掉，你反手将书籍牢牢握在手中。"
  },
  [200120049] = {
    id = 200120049,
    name = "探险者发现你身手不凡，立刻停手，嬉皮笑脸地看着你。"
  },
  [200120050] = {
    id = 200120050,
    name = "「开个玩笑嘛，别当真！」"
  },
  [200120051] = {
    id = 200120051,
    name = "「我就是想见识见识，这本奇书到底写了些什么。」"
  },
  [200120052] = {
    id = 200120052,
    name = "在他期待的眼光中，你小心翼翼地翻开了书籍......"
  },
  [200120053] = {
    id = 200120053,
    name = "「wohoo......这、这真是一本奇书啊！」"
  },
  [200120054] = {
    id = 200120054,
    name = "你默默收起书籍，他想继续说些什么，但又慑于你的实力，只能委屈地看着你。"
  },
  [200120055] = {
    id = 200120055,
    name = "「真遗憾啊~」"
  },
  [200120056] = {
    id = 200120056,
    name = "在探险者的叹息声中，你将书放回盒子，带着盒子离开了此地。"
  },
  [200120057] = {
    id = 200120057,
    name = "他见你答应得很果断，便多给了你些钱。"
  },
  [200120058] = {
    id = 200120058,
    name = "随后他小心翼翼地把书从盒子中取出，翻开查看。"
  },
  [200120059] = {
    id = 200120059,
    name = "你见他双眼瞪大，瞳孔紧缩，一脸的不可思议，引得你也想凑近查看一番。"
  },
  [200120060] = {
    id = 200120060,
    name = "然而你刚伸头，他便啪地一声将书合上。"
  },
  [200120061] = {
    id = 200120061,
    name = "他眼神瞟向你，露出一个意味深长的笑容，然后将书贴身藏在怀中，匆匆离去。"
  },
  [200120062] = {
    id = 200120062,
    name = "「难道我错过了什么吗？」"
  },
  [200120063] = {
    id = 200120063,
    name = "你觉得好奇害死猫，决定不去窥探，将盒子放回了原处，正当你准备离去时，迎面走来了一名年轻的探险者。"
  },
  [200120064] = {
    id = 200120064,
    name = "他探头望向你身后的骸骨。"
  },
  [200120065] = {
    id = 200120065,
    name = "「啧啧，多可怜啊，怎么没人给他收尸呢，那我来帮忙好了。」"
  },
  [200120066] = {
    id = 200120066,
    name = "他俯身捡起那盒子打开，霎时一股烟雾窜出，紧接着烟雾幻化成一头恐怖的魔物！"
  },
  [200120067] = {
    id = 200120067,
    name = "「哇......救、救命！」"
  },
  [200120068] = {
    id = 200120068,
    name = "探险者被魔物一爪击倒。"
  },
  [200120069] = {
    id = 200120069,
    name = "但他仍紧紧抱着盒子不放，不停地以随身武器刺向魔物。"
  },
  [200120070] = {
    id = 200120070,
    name = "过了好一会儿，魔物化作烟雾消失，年轻的探险者也累得气喘吁吁。"
  },
  [200120071] = {
    id = 200120071,
    name = "「啊啊，真是无情啊，竟然就这样冷漠地看着——」"
  },
  [200120072] = {
    id = 200120072,
    name = "「你，你该不会想趁人之危吧！」"
  },
  [200120073] = {
    id = 200120073,
    name = "「......」"
  },
  [200120074] = {
    id = 200120074,
    name = "「我警告你啊，你别打歪主意，这是你不要，我才拿的。」"
  },
  [200120075] = {
    id = 200120075,
    name = "他一步步后退，直到退出了你的攻击范围。"
  },
  [200120076] = {
    id = 200120076,
    name = "「算你识相。」"
  },
  [200120077] = {
    id = 200120077,
    name = "他长吁一口气，抱着盒子一溜烟跑走了。"
  },
  [200120078] = {
    id = 200120078,
    name = "在魔物即将击中年轻探险者的那一刻，你出手了。"
  },
  [200120079] = {
    id = 200120079,
    name = "年轻的探险者见你帮忙，也立即起身和你一起攻击魔物。"
  },
  [200120080] = {
    id = 200120080,
    name = "在你二人的攻击下，魔物很快被击杀，化作烟雾消散，随即盒子中显露出一本书籍。"
  },
  [200120081] = {
    id = 200120081,
    name = "「哇，这一定是什么好东西吧？」"
  },
  [200120082] = {
    id = 200120082,
    name = "「我说，我能看一眼吗？好歹是我先发现的。」"
  },
  [200120083] = {
    id = 200120083,
    name = "但是鉴于刚才的教训，探险者不敢去拿书籍，似乎害怕下一秒再窜出一只魔物。"
  },
  [200120084] = {
    id = 200120084,
    name = "于是在他期待的眼神中，你小心翼翼的翻开了书籍......"
  },
  [200120085] = {
    id = 200120085,
    name = "「wohoo......这、这真是一本奇书啊！」"
  },
  [200120086] = {
    id = 200120086,
    name = "「你喜欢这种书？」"
  },
  [200120087] = {
    id = 200120087,
    name = "你没有在陌生人面前看这种成人书本的习惯，将书快速合上。"
  },
  [200120088] = {
    id = 200120088,
    name = "「谁能不喜欢呢，我可不自欺欺人。」"
  },
  [200120089] = {
    id = 200120089,
    name = "「兄弟，打个商量。」"
  },
  [200120090] = {
    id = 200120090,
    name = "「魔物是你打的，这本书本该归你。」"
  },
  [200120091] = {
    id = 200120091,
    name = "「但这本书着实罕见，要不我给你些钱，你让给我怎么样？」"
  },
  [200120092] = {
    id = 200120092,
    name = "说着，他拿出一些钱递到你面前，满怀期待地看着你。"
  },
  [200120093] = {
    id = 200120093,
    name = "「在孤独的夜晚，这简直就是抚慰心灵的极品。」"
  },
  [200120094] = {
    id = 200120094,
    name = "「而且这种品质，如果找人复刻贩售，一定能畅销深渊吧？！」"
  },
  [200120095] = {
    id = 200120095,
    name = "「那得加价。」"
  },
  [200120096] = {
    id = 200120096,
    name = "「开玩笑的，兄弟。这种好书，我当然是私下收藏了。」"
  },
  [200120097] = {
    id = 200120097,
    name = "他急忙将钱袋塞给你，接过书和盒子，如获至宝般抱在了怀里。"
  },
  [200120098] = {
    id = 200120098,
    name = "「啊！真是可惜~」"
  },
  [200120099] = {
    id = 200120099,
    name = "他叹了口气，想继续说些什么，但又慑于你的实力，只能委屈地看着你。"
  },
  [200120100] = {
    id = 200120100,
    name = "「那就让我再看一眼吧。」"
  },
  [200120101] = {
    id = 200120101,
    name = "你没有理会他的请求，将书装进盒子收好，在他遗憾的叹息声中离开了。"
  },
  [200130001] = {
    id = 200130001,
    name = "你行至小溪，发现一个小孩正蹲在岸边，专心看着水中游来游去的小鱼。"
  },
  [200130002] = {
    id = 200130002,
    name = "你环顾四周无人，便走上前去。"
  },
  [200130003] = {
    id = 200130003,
    name = "「怎么一个人在这里，你家里人呢？」"
  },
  [200130004] = {
    id = 200130004,
    name = "小孩站了起来，露出天真的笑容看着你。"
  },
  [200130005] = {
    id = 200130005,
    name = "「大哥哥，我好无聊啊，你陪我玩吧？」"
  },
  [200130006] = {
    id = 200130006,
    name = "小孩开心地跳了起来。"
  },
  [200130007] = {
    id = 200130007,
    name = "「大哥哥，你最好了！」"
  },
  [200130008] = {
    id = 200130008,
    name = "他朝着小溪对岸的树林大喊。"
  },
  [200130009] = {
    id = 200130009,
    name = "「快出来，你们快出来啊！」"
  },
  [200130010] = {
    id = 200130010,
    name = "一旁的大树后钻出来两个小脑袋。"
  },
  [200130011] = {
    id = 200130011,
    name = "「怎么了？」"
  },
  [200130012] = {
    id = 200130012,
    name = "「你又惹事了？」"
  },
  [200130013] = {
    id = 200130013,
    name = "「我没有惹事，是这个大哥哥刚才欺负我，想打劫我！」"
  },
  [200130014] = {
    id = 200130014,
    name = "「喂！我没有——」"
  },
  [200130015] = {
    id = 200130015,
    name = "「他看我一个小孩子好欺负，呜呜呜......」"
  },
  [200130016] = {
    id = 200130016,
    name = "「你这个欠揍的小子！」"
  },
  [200130017] = {
    id = 200130017,
    name = "「你看，他就是要欺负我！哥哥，我们一起打败他吧！」"
  },
  [200130018] = {
    id = 200130018,
    name = "「敢欺负我们小溪三人组，是要给他一个教训！」"
  },
  [200130019] = {
    id = 200130019,
    name = "「真、真的没关系吗？」"
  },
  [200130020] = {
    id = 200130020,
    name = "「就用叔叔教我们的本事！」"
  },
  [200130021] = {
    id = 200130021,
    name = "「好啊好啊，正好可以练习一下！」"
  },
  [200130022] = {
    id = 200130022,
    name = "几名小孩冲了上来！"
  },
  [200130023] = {
    id = 200130023,
    name = "你没怎么用力，就把他们推到了一边。"
  },
  [200130024] = {
    id = 200130024,
    name = "他们三个跌在地上喘气。"
  },
  [200130025] = {
    id = 200130025,
    name = "「这个大哥哥好厉害啊，不知道和叔叔比谁更厉害呢。」"
  },
  [200130026] = {
    id = 200130026,
    name = "「为什么夸他？你不是说他欺负你？」"
  },
  [200130027] = {
    id = 200130027,
    name = "「哎呀，我就是看大家都很无聊，恰好大哥哥也说愿意陪我们玩啊。」"
  },
  [200130028] = {
    id = 200130028,
    name = "「......你是故意的啊。」"
  },
  [200130029] = {
    id = 200130029,
    name = "「可是，我们输得很惨诶。」"
  },
  [200130030] = {
    id = 200130030,
    name = "「我们该回去了，再这样贪玩下去，不但会输，还会死得很惨。」"
  },
  [200130031] = {
    id = 200130031,
    name = "「对噢，这一路很危险啊。」"
  },
  [200130032] = {
    id = 200130032,
    name = "「如果有魔物就死定了。」"
  },
  [200130033] = {
    id = 200130033,
    name = "「大哥哥，能送我们回去吗？」"
  },
  [200130034] = {
    id = 200130034,
    name = "「......」"
  },
  [200130035] = {
    id = 200130035,
    name = "「哎呀呀，大哥哥原来是胆小鬼啊。」"
  },
  [200130036] = {
    id = 200130036,
    name = "「如果真的是陷阱，哥哥敢不敢跳进来呢？」"
  },
  [200130037] = {
    id = 200130037,
    name = "「想激我，你还太嫩了。」"
  },
  [200130038] = {
    id = 200130038,
    name = "你转身离开，三人没有挽留你，吵吵闹闹往回走去。"
  },
  [200130039] = {
    id = 200130039,
    name = "突然，三人离开的方向响起了魔物的吼叫。"
  },
  [200130040] = {
    id = 200130040,
    name = "你听到声响，迅速返回救人。"
  },
  [200130041] = {
    id = 200130041,
    name = "可惜一切都晚了，三个小孩已经惨死在魔物的利爪之下。"
  },
  [200130042] = {
    id = 200130042,
    name = "你杀掉了魔物，却无法挽回三人的性命。"
  },
  [200130043] = {
    id = 200130043,
    name = "「快走吧，这一带魔物这么多，你们也是胆大。」"
  },
  [200130044] = {
    id = 200130044,
    name = "你护送着几人往回走，路上果然遇到零星的魔物。"
  },
  [200130045] = {
    id = 200130045,
    name = "好在你早有准备，将所遇到的魔物尽数消灭。"
  },
  [200130046] = {
    id = 200130046,
    name = "「大哥哥太厉害了，能不能教我刚才那一手？」"
  },
  [200130047] = {
    id = 200130047,
    name = "「这个简单。」"
  },
  [200130048] = {
    id = 200130048,
    name = "你将运转魔法的方式告诉了小孩。"
  },
  [200130049] = {
    id = 200130049,
    name = "他按照你说的做，手心亮起一团小小的光芒，顿时高兴地跳了起来。"
  },
  [200130050] = {
    id = 200130050,
    name = "「太好了，我以后也要变得像大哥哥一样能保护大家！」"
  },
  [200130051] = {
    id = 200130051,
    name = "「你们不是还有叔叔吗？」"
  },
  [200130052] = {
    id = 200130052,
    name = "「可是叔叔已经死了。」"
  },
  [200130053] = {
    id = 200130053,
    name = "「他是说过要守护我们，但他死了，没办法守护了吧。」"
  },
  [200130054] = {
    id = 200130054,
    name = "在三人的引领下，你将他们送到了一个贫民窟，小孩开心地和你道别，并把他们叔叔遗留的一些物资赠予了你。"
  },
  [200130055] = {
    id = 200130055,
    name = "「我不会再贪玩了，要成为出色的探险者，必须从今天就开始修行！」"
  },
  [200130056] = {
    id = 200130056,
    name = "「你说过很多次了，一次也没做到。」"
  },
  [200130057] = {
    id = 200130057,
    name = "「那是因为叔叔教的东西不适合我。」"
  },
  [200130058] = {
    id = 200130058,
    name = "「我现在学会了新的方法，等着瞧吧！」"
  },
  [200130059] = {
    id = 200130059,
    name = "多年后，三人组建了小溪探险队，因乐善好施，行侠仗义，在深渊中声名远扬。"
  },
  [200130060] = {
    id = 200130060,
    name = "「我没欺负你，别污蔑我！」"
  },
  [200130061] = {
    id = 200130061,
    name = "「呜哇，你看他好凶。哥哥，我们一起打败他！」"
  },
  [200130062] = {
    id = 200130062,
    name = "「敢欺负我们小溪三人组，是要给他一个教训！」"
  },
  [200130063] = {
    id = 200130063,
    name = "「真、真的没关系吗？」"
  },
  [200130064] = {
    id = 200130064,
    name = "「就用叔叔教我们的本事！」"
  },
  [200130065] = {
    id = 200130065,
    name = "「来吧，正好可以练习一下！」"
  },
  [200130066] = {
    id = 200130066,
    name = "几名小孩冲了上来！"
  },
  [200130067] = {
    id = 200130067,
    name = "你没怎么用力，就把他们推到了一边。"
  },
  [200130068] = {
    id = 200130068,
    name = "他们三个跌在地上喘气。"
  },
  [200130069] = {
    id = 200130069,
    name = "你觉得和小孩置气很无趣，正要离开，天真的小孩拦下了你。"
  },
  [200130070] = {
    id = 200130070,
    name = "「不许走！再打一场！」"
  },
  [200130071] = {
    id = 200130071,
    name = "「这点教训还不够？怎么，你就这么喜欢吃苦头吗？」"
  },
  [200130072] = {
    id = 200130072,
    name = "「你、你再有本事，也是个谁都讨厌的坏家伙！」"
  },
  [200130073] = {
    id = 200130073,
    name = "「别惹他了，我们该回去了。」"
  },
  [200130074] = {
    id = 200130074,
    name = "「我不想打......我害怕。」"
  },
  [200130075] = {
    id = 200130075,
    name = "「怕就乖乖回去找你家大人。」"
  },
  [200130076] = {
    id = 200130076,
    name = "「在外面溜达的话，不知道什么时候就会变成魔物的午餐哦。」"
  },
  [200130077] = {
    id = 200130077,
    name = "「你这个大坏人！」"
  },
  [200130078] = {
    id = 200130078,
    name = "「我看你是没见过真正的坏人吧。」"
  },
  [200130079] = {
    id = 200130079,
    name = "「你、你想要干什么？」"
  },
  [200130080] = {
    id = 200130080,
    name = "「坏人嘛，当然是敲诈勒索抢劫一条龙服务了。」"
  },
  [200130081] = {
    id = 200130081,
    name = "「你......」"
  },
  [200130082] = {
    id = 200130082,
    name = "「我们快走！」"
  },
  [200130083] = {
    id = 200130083,
    name = "见你沉着脸走过去，三人撒腿就跑。"
  },
  [200130084] = {
    id = 200130084,
    name = "「再不跑快点就追上了哦。」"
  },
  [200130085] = {
    id = 200130085,
    name = "「哇......呜呜！」"
  },
  [200130086] = {
    id = 200130086,
    name = "「吼......」"
  },
  [200130087] = {
    id = 200130087,
    name = "此时，一只魔物突然窜出，直扑三人！"
  },
  [200130088] = {
    id = 200130088,
    name = "你及时出手，挡在三人面前。"
  },
  [200130089] = {
    id = 200130089,
    name = "所幸这头魔物并不算强，被你轻松解决。"
  },
  [200130090] = {
    id = 200130090,
    name = "你看着躲在一旁，抱成一团瑟瑟发抖的三人，笑着摇了摇头。"
  },
  [200130091] = {
    id = 200130091,
    name = "趁你收集魔物身上素材的功夫，几个小孩一溜烟跑没了影。"
  },
  [200130092] = {
    id = 200130092,
    name = "你环顾四周，发现三人正跑向远处的贫民窟，确认他们安全抵达后，你才松了口气。"
  },
  [200130093] = {
    id = 200130093,
    name = "（希望这件事能给他们一个教训。）"
  },
  [200130094] = {
    id = 200130094,
    name = "（在不清楚情况的时候，最好不要胡乱行动。）"
  },
  [200130095] = {
    id = 200130095,
    name = "多年后，三人组建了专门的情报组织——小溪情报组。"
  },
  [200130096] = {
    id = 200130096,
    name = "因谨小慎微的行事作风，以及可靠的消息渠道受到许多探险者推崇。"
  },
  [200130097] = {
    id = 200130097,
    name = "「你们以为惹到了我，今天可以轻易离开这里吗？」"
  },
  [200130098] = {
    id = 200130098,
    name = "「你、你想要干什么？」"
  },
  [200130099] = {
    id = 200130099,
    name = "「要你们赔钱啊。」"
  },
  [200130100] = {
    id = 200130100,
    name = "「可是，你没有受到伤害啊，为什么要赔钱？你这是打劫！」"
  },
  [200130101] = {
    id = 200130101,
    name = "「废话少说，快赔钱！不然谁也别想离开！」"
  },
  [200130102] = {
    id = 200130102,
    name = "你尽量扮演得像一个真正的坏人，想给这群小孩一个深刻的教训。"
  },
  [200130103] = {
    id = 200130103,
    name = "小孩们站在原地发抖。"
  },
  [200130104] = {
    id = 200130104,
    name = "淡定的小孩鼓起勇气扔出了一块素材，随即拉着两人飞快地逃跑。"
  },
  [200130105] = {
    id = 200130105,
    name = "此时，一头魔物突然窜出，直扑三人！"
  },
  [200130106] = {
    id = 200130106,
    name = "你立即出手，将手中的素材扔出干扰魔物，随即趁魔物注意力转移的瞬间，给予它致命一击。"
  },
  [200130107] = {
    id = 200130107,
    name = "你轻松解决了魔物，打扫战场时瞥见了远处的贫民窟，瞬间对几个小孩的来历有了判断。"
  },
  [200130108] = {
    id = 200130108,
    name = "「为什么救我们？」"
  },
  [200130109] = {
    id = 200130109,
    name = "「当然是为了下一次啊。难道你们没听过，羊要养肥之后再杀吗？」"
  },
  [200130110] = {
    id = 200130110,
    name = "「你、你......」"
  },
  [200130111] = {
    id = 200130111,
    name = "「嘘~不想和那头魔物一样的话就闭嘴。对了，下次再来这边，记得多带点东西，不然别怪我不客气。」"
  },
  [200130112] = {
    id = 200130112,
    name = "三个小孩恐惧地看了你一眼，逃一样地跑回了贫民窟。"
  },
  [200130113] = {
    id = 200130113,
    name = "多年后，三人成了这一带无恶不作的劫匪，"
  },
  [200130114] = {
    id = 200130114,
    name = "许多来此的探险者都遭了殃。"
  },
  [200130115] = {
    id = 200130115,
    name = "「可是我朋友还在这里啊。」"
  },
  [200130116] = {
    id = 200130116,
    name = "他指了指附近的树林。"
  },
  [200130117] = {
    id = 200130117,
    name = "「朋友？」"
  },
  [200130118] = {
    id = 200130118,
    name = "「是啊！喂，你们快出来！」"
  },
  [200130119] = {
    id = 200130119,
    name = "随着小孩的呼喊，一旁的大树后钻出两个小脑袋。"
  },
  [200130120] = {
    id = 200130120,
    name = "「你又惹事了？」"
  },
  [200130121] = {
    id = 200130121,
    name = "「是有吃的了吗？」"
  },
  [200130122] = {
    id = 200130122,
    name = "「我没有惹事，是这个大哥哥说要送我们回家，还会给我们吃的。」"
  },
  [200130123] = {
    id = 200130123,
    name = "「喂！你讹我啊——」"
  },
  [200130124] = {
    id = 200130124,
    name = "「大哥哥，你刚才说过的不算数了吗，呜呜呜......」"
  },
  [200130125] = {
    id = 200130125,
    name = "你见三人面黄肌瘦的模样，于心不忍，决定送他们回去。"
  },
  [200130126] = {
    id = 200130126,
    name = "在几个小孩的引领下，你将他们送回了附近的贫民窟。"
  },
  [200130127] = {
    id = 200130127,
    name = "「怎么一个人都没有？」"
  },
  [200130128] = {
    id = 200130128,
    name = "「因为都死了，叔叔出去找食物就再也没回来。」"
  },
  [200130129] = {
    id = 200130129,
    name = "「他说过要守护我们的。」"
  },
  [200130130] = {
    id = 200130130,
    name = "「但他死了，已经没办法守护了吧。」"
  },
  [200130131] = {
    id = 200130131,
    name = "「好饿......」"
  },
  [200130132] = {
    id = 200130132,
    name = "你拿出了干粮，三个小孩吃得很开心。"
  },
  [200130133] = {
    id = 200130133,
    name = "「好好吃......谢谢你，大哥哥你真是一个好人。」"
  },
  [200130134] = {
    id = 200130134,
    name = "「这里很容易被魔物袭击，你们为什么不去附近的圈落呢？」"
  },
  [200130135] = {
    id = 200130135,
    name = "「那个圈落不要拾荒者。」"
  },
  [200130136] = {
    id = 200130136,
    name = "「真拿你们没办法。」"
  },
  [200130137] = {
    id = 200130137,
    name = "放任这三个小孩在这里，很可能随时会死掉，你决定帮人帮到底。"
  },
  [200130138] = {
    id = 200130138,
    name = "与三人交流后，你将他们带到了附近圈落。"
  },
  [200130139] = {
    id = 200130139,
    name = "你找到了当地公会成员，在你的恳求以及三名孩子的努力下，他们得以在公会中从事简单的工作，换取公会的庇护。"
  },
  [200130140] = {
    id = 200130140,
    name = "「谢谢，谢谢你！」"
  },
  [200130141] = {
    id = 200130141,
    name = "「我们会认真工作的。这个送给你，谢谢你帮我们。」"
  },
  [200130142] = {
    id = 200130142,
    name = "小孩拿出了一些探险者的物资送给你，据说是那位叔叔留下的。"
  },
  [200130143] = {
    id = 200130143,
    name = "「我不会再贪玩了，为了能守护同伴，我要从现在开始认真学习。」"
  },
  [200130144] = {
    id = 200130144,
    name = "「你说过很多次了。」"
  },
  [200130145] = {
    id = 200130145,
    name = "「这次是认真的！」"
  },
  [200130146] = {
    id = 200130146,
    name = "「大哥哥，我不会辜负你为我们做的一切。」"
  },
  [200130147] = {
    id = 200130147,
    name = "「嗯，一起加油。」"
  },
  [200130148] = {
    id = 200130148,
    name = "多年后，三人成为了公会的正式成员。"
  },
  [200130149] = {
    id = 200130149,
    name = "因精明能干、热情友善受到许多人称赞。"
  },
  [200140001] = {
    id = 200140001,
    name = "前行途中，你发现附近树下一名男子正蹲坐在地上休息。"
  },
  [200140002] = {
    id = 200140002,
    name = "他身旁有一辆小木车，上面装满了药草。"
  },
  [200140003] = {
    id = 200140003,
    name = "你走近时，听见他唉声叹气。"
  },
  [200140004] = {
    id = 200140004,
    name = "他察觉到了你，顿时双瞳紧缩，露出恐惧的姿态，往后连退了好几步。"
  },
  [200140005] = {
    id = 200140005,
    name = "随即他急忙向你求饶，祈求你能放过他最后的货物。"
  },
  [200140006] = {
    id = 200140006,
    name = "你安抚了这个看起来像游商的男子。"
  },
  [200140007] = {
    id = 200140007,
    name = "男子见你没有抢劫的心思，松了一口气。"
  },
  [200140008] = {
    id = 200140008,
    name = "他向你倒苦水，诉说这一路的艰辛。"
  },
  [200140009] = {
    id = 200140009,
    name = "原来他并不是深渊游商，而是为了找寻一种药草，特意来到深渊的普通人。"
  },
  [200140010] = {
    id = 200140010,
    name = "在雇佣的探险者都逃走之后，他独自继续前进，发誓要找到传说中的药草。"
  },
  [200140011] = {
    id = 200140011,
    name = "「那是一株包治百病的药草。」"
  },
  [200140012] = {
    id = 200140012,
    name = "男子说起了药草的功效，原来他这次的目的是把药草带回去救她的女儿。"
  },
  [200140013] = {
    id = 200140013,
    name = "那株药草就长在他身后的山顶上。"
  },
  [200140014] = {
    id = 200140014,
    name = "但山顶有魔物的巡视，作为一个普通人，他根本无法靠近。"
  },
  [200140015] = {
    id = 200140015,
    name = "「如果没有药草的话，我女儿的命也就......」"
  },
  [200140016] = {
    id = 200140016,
    name = "你告诉男人世界上不可能存在那种药草，让他认清现实。"
  },
  [200140017] = {
    id = 200140017,
    name = "男人非常生气，认为你是胆小鬼，不想和你继续交流，推车跑向了山顶。"
  },
  [200140018] = {
    id = 200140018,
    name = "山顶有魔物出没，非常危险，你急忙追了上去，然而却没有见到男子的踪影。"
  },
  [200140019] = {
    id = 200140019,
    name = "就在你沿途搜寻时，一头魔物突然窜了出来，你不敢分心，全力迎战。"
  },
  [200140020] = {
    id = 200140020,
    name = "打败了魔物后，你继续寻找男子的踪影。"
  },
  [200140021] = {
    id = 200140021,
    name = "然而你在山顶找了一圈都一无所获，只在山崖附近发现了一辆破损的、趋近于腐烂的小推车。"
  },
  [200140022] = {
    id = 200140022,
    name = "推车旁倚着一副枯骨，枯骨边放着一张有些腐朽的羊皮纸。"
  },
  [200140023] = {
    id = 200140023,
    name = "「女神在上，请赐予我的爱女祝福，消弭她所有的病痛。」"
  },
  [200140024] = {
    id = 200140024,
    name = "枯骨的手中拿着一棵干枯的草，里面虽然还有少量魔力残留，但已失去价值。"
  },
  [200140025] = {
    id = 200140025,
    name = "从外形来看，这人已经死去了很长的时间。"
  },
  [200140026] = {
    id = 200140026,
    name = "「这是怎么回事？」"
  },
  [200140027] = {
    id = 200140027,
    name = "你沿原路下山，在山下看到了一个女探险者。"
  },
  [200140028] = {
    id = 200140028,
    name = "她主动跟你打招呼，问你在山顶上有没有看到包治百病的药草。"
  },
  [200140029] = {
    id = 200140029,
    name = "你将男子上山的事告诉了她。"
  },
  [200140030] = {
    id = 200140030,
    name = "所谓的药草不过只是蕴含了魔力的植物。"
  },
  [200140031] = {
    id = 200140031,
    name = "「是这样吗，我早就说过不可能了啊......」"
  },
  [200140032] = {
    id = 200140032,
    name = "「他还没有付给你的报酬，就由我来补偿吧。」"
  },
  [200140033] = {
    id = 200140033,
    name = "女探险者从包裹中取出一些物资交给了你。"
  },
  [200140034] = {
    id = 200140034,
    name = "随后她和你告别，继续朝山上走去。"
  },
  [200140035] = {
    id = 200140035,
    name = "「......果然还是想亲眼确认吗？」"
  },
  [200140036] = {
    id = 200140036,
    name = "你拿着报酬离开，没有看见之后发生的一切——"
  },
  [200140037] = {
    id = 200140037,
    name = "女探险者到达山崖附近时，行动突然变得迟缓，身躯容颜以肉眼可见的速度老去......"
  },
  [200140038] = {
    id = 200140038,
    name = "你转身离开，迎面走来一名女探险者。"
  },
  [200140039] = {
    id = 200140039,
    name = "她见到你眼睛一亮，朝你走了过来。"
  },
  [200140040] = {
    id = 200140040,
    name = "她问你有没有见到一个采药草的男子。"
  },
  [200140041] = {
    id = 200140041,
    name = "你将男子上山的事告诉了她。"
  },
  [200140042] = {
    id = 200140042,
    name = "她叹了口气，口中嘀咕几句，决定继续上山，寻找那个摘药草的男子。"
  },
  [200140043] = {
    id = 200140043,
    name = "「如果是那家伙的话，一定会被魔物吃掉吧。」"
  },
  [200140044] = {
    id = 200140044,
    name = "你们分别不久，突然从山上传来一声魔物的嘶吼。"
  },
  [200140045] = {
    id = 200140045,
    name = "你听到声音立即向山上赶去，然而只看到一具魔物的枯骨。"
  },
  [200140046] = {
    id = 200140046,
    name = "山崖附近，还有一辆破损的小推车倒在地上。"
  },
  [200140047] = {
    id = 200140047,
    name = "你走近一看，那小推车看起来和之前男子的推车很像，只是车身早已腐朽。"
  },
  [200140048] = {
    id = 200140048,
    name = "你沿途寻找，男子和女探险者都不见了踪影。"
  },
  [200140049] = {
    id = 200140049,
    name = "「人呢？」"
  },
  [200140050] = {
    id = 200140050,
    name = "你巡视一周没有任何发现，也并没看到传说中的药草。"
  },
  [200140051] = {
    id = 200140051,
    name = "「看来他们不知道用什么办法，已经离开了。」"
  },
  [200140052] = {
    id = 200140052,
    name = "男子感激你的帮助，但他想跟你一起。"
  },
  [200140053] = {
    id = 200140053,
    name = "你隐隐感觉到山顶的魔物并不好对付，如果带上他必定是一件十分危险的事。"
  },
  [200140054] = {
    id = 200140054,
    name = "你告知了男子可能的危险，但他仍然坚持，你只得带着他一起上山。"
  },
  [200140055] = {
    id = 200140055,
    name = "你们刚到山顶，魔物便窜了出来，你将男子护到身后，与魔物激战。"
  },
  [200140056] = {
    id = 200140056,
    name = "费了些功夫，你将魔物击败，男子在你的保护下也并无大碍。"
  },
  [200140057] = {
    id = 200140057,
    name = "你们继续在山顶寻找，最终在山崖附近发现一株药草。"
  },
  [200140058] = {
    id = 200140058,
    name = "男子欣喜若狂地跑上去摘取了药草，这株药草内蕴含着奇特的魔力。"
  },
  [200140059] = {
    id = 200140059,
    name = "或许真有传说中包治百病的效果也说不定。"
  },
  [200140060] = {
    id = 200140060,
    name = "男子说他终于可以医治女儿的病了，从包裹中拿出一堆物资塞给你，希望你能收下他的谢礼。"
  },
  [200140061] = {
    id = 200140061,
    name = "此时，一个女探险者出现在了你们的面前，男子叫他妹妹。"
  },
  [200140062] = {
    id = 200140062,
    name = "原来她担忧哥哥的安全，追寻着哥哥的踪迹也来到了这里。"
  },
  [200140063] = {
    id = 200140063,
    name = "「没想到你真的做到了啊。」"
  },
  [200140064] = {
    id = 200140064,
    name = "「为什么你们看起来没有变化？」"
  },
  [200140065] = {
    id = 200140065,
    name = "女探险者说着莫名其妙的话。"
  },
  [200140066] = {
    id = 200140066,
    name = "「只是摘药草而已，能有什么变化。」"
  },
  [200140067] = {
    id = 200140067,
    name = "「......总之，没有发生意外真是太好了。」"
  },
  [200140068] = {
    id = 200140068,
    name = "男子急着回去救女儿，两人与你挥手道别。"
  },
  [200140069] = {
    id = 200140069,
    name = "你告诉男人山顶可能非常危险，让他在此等候，自己如果拿到药草一定送回来。男子得到你的许诺，同意在原地等你归来。"
  },
  [200140070] = {
    id = 200140070,
    name = "你刚到山顶，魔物便突然窜了出来。"
  },
  [200140071] = {
    id = 200140071,
    name = "你早有准备，也没有后顾之忧，全力迎战魔物，不多时便将其击败。"
  },
  [200140072] = {
    id = 200140072,
    name = "在山顶寻找了一圈，你终于在山崖边见到一株和男子描述相符的药草。"
  },
  [200140073] = {
    id = 200140073,
    name = "你得到药草后沿原路返回，那名男子却已消失不见。"
  },
  [200140074] = {
    id = 200140074,
    name = "「人呢？」"
  },
  [200140075] = {
    id = 200140075,
    name = "你继续向山脚走去，看到了一名女探险者和一位年纪很大的老人。"
  },
  [200140076] = {
    id = 200140076,
    name = "老人见到你，露出了惊恐的眼神。"
  },
  [200140077] = {
    id = 200140077,
    name = "「你为什么没有改变？这个药草......药草......」"
  },
  [200140078] = {
    id = 200140078,
    name = "他说着莫名其妙的话，指着你手中的药草，突然晕了过去。"
  },
  [200140079] = {
    id = 200140079,
    name = "女探险者叹息着将他安顿在一边，朝你走了过来。"
  },
  [200140080] = {
    id = 200140080,
    name = "「你竟然没有遭遇任何意外？真是奇迹......」"
  },
  [200140081] = {
    id = 200140081,
    name = "「非常感谢你帮我们拿到了这株药草！」"
  },
  [200140082] = {
    id = 200140082,
    name = "随后，她和你讲起了她所知道的一切。"
  },
  [200140083] = {
    id = 200140083,
    name = "原来这名老人就是之前找药草的男子。"
  },
  [200140084] = {
    id = 200140084,
    name = "而这株传说中的药草，的确能治百病，但它的生长区域十分恐怖诡异。"
  },
  [200140085] = {
    id = 200140085,
    name = "任何接近的人或物，都可能突然衰老，甚至死去，就如同自身的时间被剥夺一般。"
  },
  [200140086] = {
    id = 200140086,
    name = "只有这株药草周围本就存在的一切，才不会受到影响。"
  },
  [200140087] = {
    id = 200140087,
    name = "这名老人，也就是她的哥哥，在你上山后不知道出于什么原因，也跟着上了山，所以变成了现在的模样。"
  },
  [200140088] = {
    id = 200140088,
    name = "所幸她及时赶到，将他带了下来，否则他现在可能已经化作枯骨。"
  },
  [200140089] = {
    id = 200140089,
    name = "她也正是得知这一切后，才赶来阻止她哥哥靠近那株药草的......"
  },
  [200140090] = {
    id = 200140090,
    name = "「所以我没受影响是因为运气？」"
  },
  [200140091] = {
    id = 200140091,
    name = "「这......可能吧，至少我调查过的资料中，没有发现规避的方法。」"
  },
  [200140092] = {
    id = 200140092,
    name = "「还好你没被影响，不然就被我哥哥连累了。」"
  },
  [200140093] = {
    id = 200140093,
    name = "女探险者给了你一些物资作为谢礼，随后将昏迷的老人放到推车上，带着他离去。"
  },
  [200140094] = {
    id = 200140094,
    name = "你看着他们离去的背景，不禁陷入了沉思......"
  },
  [200140095] = {
    id = 200140095,
    name = "「我可没有抢劫的兴趣。」"
  },
  [200140096] = {
    id = 200140096,
    name = "你继续走向前方，发现男子悄悄跟在你身后，被你发现后又躲在了一边。"
  },
  [200140097] = {
    id = 200140097,
    name = "「奇怪的人。」"
  },
  [200140098] = {
    id = 200140098,
    name = "你对男子的态度感到怀疑，用眼神警告他不要再跟着你。"
  },
  [200140099] = {
    id = 200140099,
    name = "「可以拜托您一件事吗？」"
  },
  [200140100] = {
    id = 200140100,
    name = "原来他希望能去山顶摘一株药草。"
  },
  [200140101] = {
    id = 200140101,
    name = "「如果您方便的话，我愿意高价购买那株药草。」"
  },
  [200140102] = {
    id = 200140102,
    name = "「在此之前，我绝对不会打扰到您任何行动的。」"
  },
  [200140103] = {
    id = 200140103,
    name = "他露出哀求的神色。"
  },
  [200140104] = {
    id = 200140104,
    name = "但你仍然怀疑他真正的目的。"
  },
  [200140105] = {
    id = 200140105,
    name = "男子非常感激，提醒你山上有巡视的魔物。"
  },
  [200140106] = {
    id = 200140106,
    name = "你刚到山顶，魔物便突然窜了出来。"
  },
  [200140107] = {
    id = 200140107,
    name = "你早有准备，全力释放魔法攻击魔物，不多时便将其击败。"
  },
  [200140108] = {
    id = 200140108,
    name = "在山顶寻找了一圈，你终于在山崖边见到一株和男子描述相符的药草。"
  },
  [200140109] = {
