  [200140111] = {
    id = 200140111,
    name = "「所以你就让别人去冒险吗？」"
  },
  [200140112] = {
    id = 200140112,
    name = "「以他的实力，就算有魔物应该也不会有什么危险吧。」"
  },
  [200140113] = {
    id = 200140113,
    name = "「就算解决了魔物，那株草......真是气死我了，又把无辜的人牵连进来。」"
  },
  [200140114] = {
    id = 200140114,
    name = "两人说着奇怪的话，直到看到你出现，女探险者露出了惊讶的表情。"
  },
  [200140115] = {
    id = 200140115,
    name = "「看起来......没有变化？」"
  },
  [200140116] = {
    id = 200140116,
    name = "「啊，那、那个就是你帮助我哥哥的吧？非常感谢您的帮忙！」"
  },
  [200140117] = {
    id = 200140117,
    name = "「刚刚你们在说什么？」"
  },
  [200140118] = {
    id = 200140118,
    name = "「没、没什么，只是埋怨我哥哥而已。」"
  },
  [200140119] = {
    id = 200140119,
    name = "「没想到您的实力如此强大，能够轻松应对这山上的危机。」"
  },
  [200140120] = {
    id = 200140120,
    name = "你莫名地看了看那座普通的山，山顶的魔物对普通人来说确实危险，但对探险者而言，也算不上多么凶险。"
  },
  [200140121] = {
    id = 200140121,
    name = "「不管怎么说，我女儿有救了啊。」"
  },
  [200140122] = {
    id = 200140122,
    name = "「对了，这个给您，非常感谢。」"
  },
  [200140123] = {
    id = 200140123,
    name = "男人说着，拿出一堆物资塞到你的手里。"
  },
  [200140124] = {
