    name = "「如果你见到过她，请一定要告诉我。好吗？」"
  },
  [200410028] = {
    id = 200410028,
    name = "「她受伤了，看起来还受到了很严重的惊吓。」"
  },
  [200410029] = {
    id = 200410029,
    name = "「她在哪儿？」"
  },
  [200410030] = {
    id = 200410030,
    name = "「快带我去找她！」"
  },
  [200410031] = {
    id = 200410031,
    name = "「嗯，我带你过去看看。」"
  },
  [200410032] = {
    id = 200410032,
    name = "「那么小的孩子，你也太不小心了。」"
  },
  [200410033] = {
    id = 200410033,
    name = "你带他走到小女孩刚才待的树下。"
  },
  [200410034] = {
    id = 200410034,
    name = "但已经不见小女孩的身影。"
  },
  [200410035] = {
    id = 200410035,
    name = "一瓶没用完的止血药粉倒洒在旁边。"
  },
  [200410036] = {
    id = 200410036,
    name = "「啊，刚才就是在这里啊。」"
  },
  [200410037] = {
    id = 200410037,
    name = "血迹零散地洒落在附近，延续到了森林深处。"
  },
  [200410038] = {
    id = 200410038,
    name = "（为什么要逃？）"
  },
  [200410039] = {
    id = 200410039,
    name = "「糟糕，她流血了啊。」"
  },
  [200410040] = {
    id = 200410040,
    name = "「我们得快点找到她！」"
  },
  [200410041] = {
    id = 200410041,
    name = "「不然要是把魔物吸引来就糟了！」"
  },
  [200410042] = {
    id = 200410042,
    name = "你们顺着血迹到了一条岔路，血迹突然消失了。"
  },
  [200410043] = {
