    name = "「魔物！」"
  },
  [200410054] = {
    id = 200410054,
    name = "你毫不犹豫地跑进洞穴，准备救出小女孩。"
  },
  [200410055] = {
    id = 200410055,
    name = "在洞穴深处的阴暗角落，你看到一头魔物正在撕咬一个小女孩的身体。"
