    name = "「她已经......」"
  },
  [200410059] = {
    id = 200410059,
    name = "「怎么回事？怎么会这样？」"
  },
  [200410060] = {
    id = 200410060,
    name = "「我们来晚了。」"
  },
  [200410061] = {
    id = 200410061,
    name = "「该死！」"
  },
  [200410062] = {
    id = 200410062,
    name = "他愤愤地拔出匕首切割魔物，取走有用的素材。"
  },
  [200410063] = {
    id = 200410063,
    name = "小女孩残缺的身躯被晾在了一边。"
  },
  [200410064] = {
    id = 200410064,
    name = "（他看起来并不伤心。）"
  },
  [200410065] = {
    id = 200410065,
    name = "你奇怪地看着他，他忽然愣住了。"
  },
  [200410066] = {
    id = 200410066,
    name = "接着他扑在了小女孩身上放声痛哭。"
  },
  [200410067] = {
    id = 200410067,
    name = "你皱了皱眉，默默离开了这个地方。"
  },
  [200410068] = {
    id = 200410068,
    name = "「你还没回答我。」"
  },
  [200410069] = {
    id = 200410069,
    name = "「你究竟做了什么，让她听到你的声音就逃了？」"
  },
  [200410070] = {
    id = 200410070,
    name = "「我只想快点把她找回来。」"
  },
  [200410071] = {
    id = 200410071,
    name = "「不对，她为什么会害怕你？」"
  },
  [200410072] = {
