    name = "「你伤害过她？」"
  },
  [200410073] = {
    id = 200410073,
    name = "「别问那么多，你帮我找到她，我给你钱，很多钱！」"
  },
  [200410074] = {
    id = 200410074,
    name = "「不。你太可疑了。」"
  },
  [200410075] = {
    id = 200410075,
    name = "你朝他走了一步，他突然拔出匕首指着你，匕首上还有血痕。"
  },
  [200410076] = {
    id = 200410076,
    name = "「她的伤果然是你造成的。」"
  },
  [200410077] = {
    id = 200410077,
    name = "「原来你也不是她的亲戚。」"
  },
  [200410078] = {
    id = 200410078,
    name = "「我该称呼你什么？人贩？」"
  },
  [200410079] = {
    id = 200410079,
    name = "「哼，劝你不要多管闲事！」"
  },
  [200410080] = {
    id = 200410080,
    name = "「这可不是闲事。」"
  },
  [200410081] = {
    id = 200410081,
    name = "你轻松踹飞了他的匕首，他吓得拔腿就跑。"
  },
  [200410082] = {
    id = 200410082,
    name = "「......」"
  },
  [200410083] = {
    id = 200410083,
    name = "「出来吧。」"
  },
  [200410084] = {
    id = 200410084,
    name = "附近窸窸窣窣，传出了忐忑的脚步声。"
  },
  [200410085] = {
