  [200410191] = {
    id = 200410191,
    name = "「还有事吗？」"
  },
  [200410192] = {
    id = 200410192,
    name = "「哈哈，没事。」"
  },
  [200410193] = {
    id = 200410193,
    name = "等他彻底消失在森林，你才走了回去。"
  },
  [200410194] = {
    id = 200410194,
    name = "小女孩明显松了一口气。"
  },
  [200410195] = {
    id = 200410195,
    name = "「谢谢。」"
  },
  [200410196] = {
    id = 200410196,
    name = "她的脚上已经涂好了伤药。"
  },
  [200410197] = {
    id = 200410197,
    name = "「不必客气。」"
  },
  [200410198] = {
    id = 200410198,
    name = "「你认识刚才那个人？」"
  },
  [200410199] = {
    id = 200410199,
    name = "小女孩突然身体紧绷，摇了摇头。"
  },
  [200410200] = {
    id = 200410200,
    name = "「呃......好吧。」"
  },
  [200410201] = {
    id = 200410201,
    name = "「你的家人在哪里？」"
  },
  [200410202] = {
    id = 200410202,
    name = "「一个人在外面太危险了。」"
  },
  [200410203] = {
    id = 200410203,
    name = "小女孩又紧张了起来。"
  },
  [200410204] = {
    id = 200410204,
    name = "「我不能告诉你......」"
  },
  [200410205] = {
    id = 200410205,
    name = "察觉到她的反应，你明白她可能遭受过某种威胁。"
  },
  [200410206] = {
    id = 200410206,
    name = "「好吧，待在这里也不是办法。」"
  },
  [200410207] = {
    id = 200410207,
    name = "「你有什么打算吗？」"
  },
  [200410208] = {
    id = 200410208,
    name = "「要不我送你去附近的据点？」"
  },
  [200410209] = {
    id = 200410209,
    name = "「不行！会、会碰到那个人......」"
  },
  [200410210] = {
    id = 200410210,
    name = "「刚才那个人？」"
  },
  [200410211] = {
    id = 200410211,
    name = "小女孩畏缩地点了点头。"
  },
  [200410212] = {
    id = 200410212,
    name = "「他打不过我。」"
  },
  [200410213] = {
    id = 200410213,
    name = "小女孩抬头朝你眨了眨眼睛。"
  },
  [200410214] = {
    id = 200410214,
    name = "「刚才我不是吓跑他了吗？」"
  },
  [200410215] = {
    id = 200410215,
    name = "「所以我可以保护你。」"
  },
  [200410216] = {
    id = 200410216,
    name = "「......」"
  },
  [200410217] = {
    id = 200410217,
    name = "小女孩缓缓松了一口气，朝你点了点头。"
  },
  [200410218] = {
    id = 200410218,
    name = "你们穿过森林，找到了据点中的公会办事处。"
  },
  [200410219] = {id = 200410219, name = "......"},
  [200410220] = {
    id = 200410220,
    name = "「事情就是这样。」"
  },
  [200410221] = {
    id = 200410221,
    name = "「唔，这个小家伙吗。」"
  },
  [200410222] = {
    id = 200410222,
    name = "「最近收到好几起孩子失踪的事件，我们正在调查。」"
  },
  [200410223] = {
    id = 200410223,
    name = "「非常感谢你提供的线索，我会立即上报，争取早日解决。」"
  },
  [200410224] = {
    id = 200410224,
    name = "「这个小妹妹我们会重点照顾，帮她找到家人的。」"
  },
  [200410225] = {
    id = 200410225,
    name = "你将小女孩交给了公会，她朝你投来了不舍的目光。"
  },
  [200410226] = {
    id = 200410226,
    name = "你朝她挥了挥手，然后转身离开了。"
  },
  [200410227] = {
    id = 200410227,
    name = "你感受到了她的恐惧，于是收敛了气息，与她一起躲了起来。"
  },
  [200410228] = {
    id = 200410228,
    name = "「小不点，你在哪里？」"
  },
  [200410229] = {
    id = 200410229,
    name = "声音越来越近。"
  },
  [200410230] = {
    id = 200410230,
    name = "小女孩忍不住开始发抖。"
  },
  [200410231] = {
    id = 200410231,
    name = "你轻轻拍着她的肩，安抚着她。"
  },
  [200410232] = {
    id = 200410232,
    name = "「小不点，再不出来，就会被魔物吃掉哦~」"
  },
  [200410233] = {
    id = 200410233,
    name = "脚步声在周围打转，忽然停了下来。"
  },
  [200410234] = {
    id = 200410234,
    name = "小女孩倒吸一口气，捂住了嘴巴。"
  },
  [200410235] = {
    id = 200410235,
    name = "旁边的杂草似乎被扒开了！"
  },
  [200410236] = {
    id = 200410236,
    name = "「在这里吗？」"
  },
  [200410237] = {
    id = 200410237,
    name = "「还是在这里？」"
  },
  [200410238] = {
    id = 200410238,
    name = "「啊，在这边啊......」"
  },
  [200410239] = {
    id = 200410239,
    name = "小女孩缩了缩脚，地上发出了一点摩擦的声音。"
  },
  [200410240] = {
    id = 200410240,
    name = "「哈哈哈，找到你了哟！」"
  },
  [200410241] = {
    id = 200410241,
    name = "近处的草再次被扒开了——"
  },
  [200410242] = {
    id = 200410242,
    name = "「啊啊啊啊！」"
  },
  [200410243] = {
    id = 200410243,
    name = "「吼！」"
  },
  [200410244] = {
    id = 200410244,
    name = "被打扰的魔物发出一声咆哮，追着男人跑远了。"
  },
  [200410245] = {
    id = 200410245,
    name = "这时，小女孩才如逃出生天般，大口大口地喘气。"
  },
  [200410246] = {
    id = 200410246,
    name = "她感激地看着你，朝你笑了笑。"
  },
  [200410247] = {
    id = 200410247,
    name = "「待在这里也不是办法。」"
  },
  [200410248] = {
    id = 200410248,
    name = "「我先送你回据点吧。」"
  },
  [200410249] = {
    id = 200410249,
    name = "她双目一震，低头犹豫着。"
  },
  [200410250] = {
    id = 200410250,
    name = "「唔，刚才那个男人，是欺负你的人吗？」"
  },
  [200410251] = {
    id = 200410251,
    name = "小女孩点点头。"
  },
  [200410252] = {
    id = 200410252,
    name = "「放心，这路上我会保护你，就算再遇到他，也不用害怕。」"
  },
  [200410253] = {
    id = 200410253,
    name = "小女孩看着你的眼睛，确定你没有骗她后，点了点头。"
  },
  [200410254] = {
    id = 200410254,
    name = "你带着小女孩刚走出森林，便看到一具残破尸体，尸体已看不清原本的面貌。"
  },
  [200410255] = {
    id = 200410255,
    name = "现场还散落着些华丽的衣衫饰品。"
  },
  [200410256] = {
    id = 200410256,
    name = "小女孩看着眼前的一切，久久没回神。"
  },
  [200410257] = {
    id = 200410257,
    name = "「是他？」"
  },
  [200410258] = {
    id = 200410258,
    name = "「嗯，是大坏人！」"
  },
  [200410259] = {
    id = 200410259,
    name = "「我很高兴。」"
  },
  [200410260] = {
    id = 200410260,
    name = "「看出来了。」"
  },
  [200410261] = {
    id = 200410261,
    name = "你护送小女孩到达了据点。"
  },
  [200410262] = {
    id = 200410262,
    name = "「送到这里，就可以了。」"
  },
  [200410263] = {
    id = 200410263,
    name = "「大哥哥，谢谢你！」"
  },
  [200410264] = {
    id = 200410264,
    name = "小女孩向你深深地鞠了一躬，随后跑进了茫茫人潮。"
  },
  [200410265] = {
    id = 200410265,
    name = "她似乎有什么秘密，但不愿意和你吐露。"
  },
  [200420001] = {
    id = 200420001,
    name = "前面有一座猎户小屋。"
  },
  [200420002] = {
    id = 200420002,
    name = "「也许有物资可以交换。」"
  },
  [200420003] = {
    id = 200420003,
    name = "你这样想着，敲响了小屋的门。"
  },
  [200420004] = {
    id = 200420004,
    name = "「儿子，你终于回来啦！」"
  },
  [200420005] = {
    id = 200420005,
    name = "开门瞬间，一个苍老的声音响起。"
  },
  [200420006] = {
    id = 200420006,
    name = "一个衣着脏乱的老人出现在你眼前。"
  },
  [200420007] = {
    id = 200420007,
    name = "他非常瘦弱，几乎全靠拐杖支撑着身体。"
  },
  [200420008] = {
    id = 200420008,
    name = "「你这个混小子，我还以为你不管我了！」"
  },
  [200420009] = {
    id = 200420009,
    name = "「你认错人了，我不是你儿子。」"
  },
  [200420010] = {
    id = 200420010,
    name = "「啊......」"
  },
  [200420011] = {
    id = 200420011,
    name = "「对、对不起。」"
  },
  [200420012] = {
    id = 200420012,
    name = "「是的，我认错了。」"
  },
  [200420013] = {
    id = 200420013,
    name = "「我怎么会认错呢......」"
  },
  [200420014] = {
    id = 200420014,
    name = "「对了，我刚才要做什么......」"
  },
  [200420015] = {
    id = 200420015,
    name = "老人似乎遗忘了什么。"
  },
  [200420016] = {
    id = 200420016,
    name = "「你是和你的儿子一起住在这里吗？」"
  },
  [200420017] = {
    id = 200420017,
    name = "「对，对，我想起来了。」"
  },
  [200420018] = {
    id = 200420018,
    name = "「我儿子昨天去隔壁据点换物资了。」"
  },
  [200420019] = {
    id = 200420019,
    name = "「到现在都还没回来。」"
  },
  [200420020] = {
    id = 200420020,
    name = "「年轻人啊，你能帮我找一找吗？」"
  },
  [200420021] = {
    id = 200420021,
    name = "「他说他就在西南方向的那个据点里。」"
  },
  [200420022] = {
    id = 200420022,
    name = "你想起来时的路上，路过了一个废弃的据点。"
  },
  [200420023] = {
    id = 200420023,
    name = "那个据点几年前被魔物袭击，早就废弃掉了......"
  },
  [200420024] = {
    id = 200420024,
    name = "「我记得附近没有据点......」"
  },
  [200420025] = {
    id = 200420025,
    name = "「哦。」"
  },
  [200420026] = {
    id = 200420026,
    name = "「......」"
  },
  [200420027] = {
    id = 200420027,
    name = "「儿子，你刚才说什么来着？」"
  },
  [200420028] = {
    id = 200420028,
    name = "「别说那么多了。」"
  },
  [200420029] = {
    id = 200420029,
    name = "「这次没伤着哪里吧？」"
  },
  [200420030] = {
    id = 200420030,
    name = "「深渊很危险啊，不要找什么药啦。」"
  },
  [200420031] = {
    id = 200420031,
    name = "「你看我精神很好的啊。」"
  },
  [200420032] = {
    id = 200420032,
    name = "「别把我想得那么虚弱。」"
  },
  [200420033] = {
    id = 200420033,
    name = "「......」"
  },
  [200420034] = {
    id = 200420034,
    name = "「对了，我熬了汤等你回来。」"
  },
  [200420035] = {
    id = 200420035,
    name = "「快去喝点。」"
  },
  [200420036] = {
    id = 200420036,
    name = "老人领着你走了进去。"
  },
  [200420037] = {
    id = 200420037,
    name = "这是一个标准的猎户小屋。"
  },
  [200420038] = {
    id = 200420038,
    name = "但屋内的猎具、兽骨早已落灰，地板上散落着杂乱的食物残渣和器具。"
  },
  [200420039] = {
    id = 200420039,
    name = "就像是......很久没人打理过的感觉。"
  },
  [200420040] = {
    id = 200420040,
    name = "「诶？我熬的汤呢？」"
  },
  [200420041] = {
    id = 200420041,
    name = "「哎呀......」"
  },
  [200420042] = {
    id = 200420042,
    name = "「我怎么这点小事都做不好......」"
  },
  [200420043] = {
    id = 200420043,
    name = "「老人家，我不是你儿子。」"
  },
  [200420044] = {
    id = 200420044,
    name = "「啊对，你不是......」"
  },
  [200420045] = {
    id = 200420045,
    name = "「对不起，我这记性太差了。」"
  },
  [200420046] = {
    id = 200420046,
    name = "「那你看到我儿子了吗？」"
  },
  [200420047] = {
    id = 200420047,
    name = "你将据点的真实情况告诉了老人。"
  },
  [200420048] = {
    id = 200420048,
    name = "老人突然像小孩一样哭了。"
  },
  [200420049] = {
    id = 200420049,
    name = "「我想起来了......」"
  },
  [200420050] = {
    id = 200420050,
    name = "「他说去据点，他没回来......」"
  },
  [200420051] = {
    id = 200420051,
    name = "「......两年、三年，还是五年......我不记得了......」"
  },
  [200420052] = {
    id = 200420052,
    name = "「他大概是死了吧。」"
  },
  [200420053] = {
    id = 200420053,
    name = "「他说过，就算是腿断了，也会爬回来看我的。」"
  },
  [200420054] = {
    id = 200420054,
    name = "「......」"
  },
  [200420055] = {
    id = 200420055,
    name = "「年轻人，我想起来儿子在小屋的树后面埋了一样东西。」"
  },
  [200420056] = {
    id = 200420056,
    name = "「你去帮我拿过来吧。」"
  },
  [200420057] = {
    id = 200420057,
    name = "你点点头，依言帮老人去树下找到了一个盒子。"
  },
  [200420058] = {
    id = 200420058,
    name = "你打开盒子，发现是一只木马，雕刻得栩栩如生。"
  },
  [200420059] = {
    id = 200420059,
    name = "你回到小屋，发现老人坐在唯一干净的摇椅上睡着了。"
  },
  [200420060] = {
    id = 200420060,
    name = "他充满皱纹的眼角还流着泪。"
  },
  [200420061] = {
    id = 200420061,
    name = "你叫了他两声，没有任何反应。"
  },
  [200420062] = {
    id = 200420062,
    name = "你探了探他的鼻息......"
  },
  [200420063] = {
    id = 200420063,
    name = "老人已经永远地离开了这个世界。"
  },
  [200420064] = {
    id = 200420064,
    name = "你叹息一声，就近将老人与那只木马安葬了。"
  },
  [200420065] = {
    id = 200420065,
    name = "「他去了另一个据点。」"
  },
  [200420066] = {
    id = 200420066,
    name = "「他要我带你过去。」"
  },
  [200420067] = {
    id = 200420067,
    name = "「哎呀，这个傻孩子。」"
  },
  [200420068] = {
    id = 200420068,
    name = "「他一直都在说要给我换个好的地方住。」"
  },
  [200420069] = {
    id = 200420069,
    name = "「我早就跟他讲别那么辛苦了，我在这里住着也挺好的。」"
  },
  [200420070] = {
    id = 200420070,
    name = "「......」"
  },
  [200420071] = {
    id = 200420071,
    name = "「等一下，出发之前我得拿一样东西。」"
  },
  [200420072] = {
    id = 200420072,
    name = "他在杂乱的房间里四处寻找。"
  },
  [200420073] = {
    id = 200420073,
    name = "过了好一会儿才翻出一个盒子，朝着你笑了起来。"
  },
  [200420074] = {
    id = 200420074,
    name = "「猜猜这是什么？」"
  },
  [200420075] = {
    id = 200420075,
    name = "「我儿子说要给我一个惊喜，所以我也要给他一个惊喜。」"
  },
  [200420076] = {
    id = 200420076,
    name = "「这是一个探险者跟我交换的，好东西！」"
  },
  [200420077] = {
    id = 200420077,
    name = "你笑了笑，决定带老人去安全的据点，帮老人拿起了行李。"
  },
  [200420078] = {
    id = 200420078,
    name = "到了据点后，老人看着往来的人流停下了脚步。"
  },
  [200420079] = {
    id = 200420079,
    name = "「......」"
  },
  [200420080] = {
    id = 200420080,
    name = "「我来过这里。」"
  },
  [200420081] = {
    id = 200420081,
    name = "「谢谢你啊，年轻人。」"
  },
  [200420082] = {
    id = 200420082,
    name = "老人朝你笑，但看着却像哭一般。"
  },
  [200420083] = {
    id = 200420083,
    name = "「我好像......想起来了......」"
  },
  [200420084] = {
    id = 200420084,
    name = "「我儿子......应该回不来了......」"
  },
  [200420085] = {
    id = 200420085,
    name = "「......节哀。」"
  },
  [200420086] = {
    id = 200420086,
    name = "你把盒子递给老人，他摆了摆手拒绝了。"
  },
  [200420087] = {
    id = 200420087,
    name = "而后走向了茫茫人海。"
  },
  [200420088] = {
    id = 200420088,
    name = "「......」"
  },
  [200420089] = {
    id = 200420089,
    name = "失去了庇护的失独老人，该如何在深渊里活下去呢。"
  },
  [200420090] = {
    id = 200420090,
    name = "你觉得老人举止疯癫，不想惹祸上身。"
  },
  [200420091] = {
    id = 200420091,
    name = "你离开了小屋。"
  },
  [200420092] = {
    id = 200420092,
    name = "「还不快滚进来！」"
  },
  [200420093] = {
    id = 200420093,
    name = "「锅里剩了点汤，你爱喝不喝！」"
  },
  [200420094] = {
    id = 200420094,
    name = "「每次都走这么久，也不怕我死在这里！」"
  },
  [200420095] = {
    id = 200420095,
    name = "「......」"
  },
  [200420096] = {
    id = 200420096,
    name = "「哦，你当然不怕了。」"
  },
  [200420097] = {
    id = 200420097,
    name = "「我死了，你就没有负担了。」"
  },
  [200420098] = {
    id = 200420098,
    name = "「你就自由了。」"
  },
  [200420099] = {
    id = 200420099,
    name = "「要不然我现在就去死，这样你就自由啦——」"
  },
  [200420100] = {
    id = 200420100,
    name = "「......」"
  },
  [200420101] = {
    id = 200420101,
    name = "「你怎么不说话？啊？是默认吗？真是出息了啊，那我现在就去死！」"
  },
  [200420102] = {
    id = 200420102,
    name = "老人怒气冲冲地出门了。"
  },
  [200420103] = {
    id = 200420103,
    name = "（这里虽然种植了驱赶魔物的植物，但如果离开太远，也会有危险吧......）"
  },
  [200420104] = {
    id = 200420104,
    name = "你追上老人的时候，前面正好出现了一头魔物，老人吓得一动不动。"
  },
  [200420105] = {
    id = 200420105,
    name = "你见状立即冲了上去，不一会儿便将魔物解决。"
  },
  [200420106] = {
    id = 200420106,
    name = "老人似乎恢复了些许神智。"
  },
  [200420107] = {
    id = 200420107,
    name = "「太可怕了。」"
  },
  [200420108] = {
    id = 200420108,
    name = "「绝对不能留在这了。」"
  },
  [200420109] = {
    id = 200420109,
    name = "「谢谢你啊，年轻人！」"
  },
  [200420110] = {
    id = 200420110,
    name = "（看来恢复正常了。）"
  },
  [200420111] = {
    id = 200420111,
    name = "「你见过我的儿子吗？」"
  },
  [200420112] = {
    id = 200420112,
    name = "「他也是探险者，背着一柄长剑。」"
  },
  [200420113] = {
    id = 200420113,
    name = "「他很喜欢他的武器，经常拿出来炫耀......」"
  },
  [200420114] = {
    id = 200420114,
    name = "「哎，我说这些干什么。」"
  },
  [200420115] = {
    id = 200420115,
    name = "「你知道附近的据点吗？」"
  },
  [200420116] = {
    id = 200420116,
    name = "「就是西南方向那个。」"
  },
  [200420117] = {
    id = 200420117,
    name = "「我儿子去那个据点换物资了，让我等他回来。」"
  },
  [200420118] = {
    id = 200420118,
    name = "「年轻人，帮帮忙，你带我去那个据点吧。」"
  },
  [200420119] = {
    id = 200420119,
    name = "「我想快点找到我儿子。」"
  },
  [200420120] = {
    id = 200420120,
    name = "你想起来时的路上，路过了一个废弃的据点。"
  },
  [200420121] = {
    id = 200420121,
    name = "那个据点几年前被魔物袭击，早就废弃掉了......"
  },
  [200420122] = {
    id = 200420122,
    name = "你将据点的真实情况告诉了老人。"
  },
  [200420123] = {
    id = 200420123,
    name = "老人突然像小孩一样哭了。"
  },
  [200420124] = {
    id = 200420124,
    name = "「我想起来了......」"
  },
  [200420125] = {
    id = 200420125,
    name = "「他说去据点，他没回来......」"
  },
  [200420126] = {
    id = 200420126,
    name = "「......两年、三年，还是五年......我不记得了......」"
  },
  [200420127] = {
    id = 200420127,
    name = "「难道死在那边了？」"
  },
  [200420128] = {
    id = 200420128,
    name = "「不，不会的。」"
  },
  [200420129] = {
    id = 200420129,
    name = "老人颤巍巍地走向小屋的方向。"
  },
  [200420130] = {
    id = 200420130,
    name = "「老人家，这里毕竟是野外，你一个人很不安全的。」"
  },
  [200420131] = {
    id = 200420131,
    name = "「我送你去别的据点吧。」"
  },
  [200420132] = {
    id = 200420132,
    name = "「不行，他要我在这等他的。」"
  },
  [200420133] = {
    id = 200420133,
    name = "「他要是回来，看不见我怎么办？」"
  },
  [200420134] = {
    id = 200420134,
    name = "「他是一个孝顺的乖孩子。」"
  },
  [200420135] = {
    id = 200420135,
    name = "「不管什么都会优先考虑我。」"
  },
  [200420136] = {
    id = 200420136,
    name = "「他说会回来就一定会回来的。」"
  },
  [200420137] = {
    id = 200420137,
    name = "老人走进小屋，锁上了门。"
  },
  [200420138] = {
    id = 200420138,
    name = "你停住了半晌，叹了口气离开了。"
  },
  [200420139] = {
    id = 200420139,
    name = "你带他到了那个废弃的据点。"
  },
  [200420140] = {
    id = 200420140,
    name = "「这里已经荒废了，你儿子应该去了别的地方。」"
  },
  [200420141] = {
    id = 200420141,
    name = "「......」"
  },
  [200420142] = {
    id = 200420142,
    name = "「在那里！」"
  },
  [200420143] = {
    id = 200420143,
    name = "「是那个，我看到了！」"
  },
  [200420144] = {
    id = 200420144,
    name = "老人走进废墟里，佝偻着腰扒拉着。"
  },
  [200420145] = {
    id = 200420145,
    name = "他从废墟里找出了一把断剑。"
  },
  [200420146] = {
    id = 200420146,
    name = "「这是我儿子的剑。」"
  },
  [200420147] = {
    id = 200420147,
    name = "「哎呀，怎么断掉了。」"
  },
  [200420148] = {
    id = 200420148,
    name = "「他真是一点也不爱惜啊......」"
  },
  [200420149] = {
    id = 200420149,
    name = "（通常断掉的剑意味着......）"
  },
  [200420150] = {
    id = 200420150,
    name = "老人抱紧了剑，忽然哭了起来。"
  },
  [200420151] = {
    id = 200420151,
    name = "「......」"
  },
  [200420152] = {
    id = 200420152,
    name = "（看来他已经知道了。）"
  },
  [200420153] = {
    id = 200420153,
    name = "老人哭了很久，才想起你还在旁边。"
  },
  [200420154] = {
    id = 200420154,
    name = "「谢谢你......带我来这里。」"
  },
  [200420155] = {
    id = 200420155,
    name = "「这里不安全，我送你回去吧。」"
  },
  [200420156] = {
    id = 200420156,
    name = "「不用了......」"
  },
  [200420157] = {
    id = 200420157,
    name = "「儿子没了，我活着也没什么意思了。」"
  },
  [200420158] = {
    id = 200420158,
    name = "「本来我也活不久的。」"
  },
  [200420159] = {
    id = 200420159,
    name = "「都是他一直在努力赚钱给我治病。」"
  },
  [200420160] = {
    id = 200420160,
    name = "「......是我害了儿子......」"
  },
  [200420161] = {
    id = 200420161,
    name = "老人又开始哭，哭了一会儿突然没有了声音。"
  },
  [200420162] = {
    id = 200420162,
    name = "他充满皱纹的眼角还流着泪。"
  },
  [200420163] = {
    id = 200420163,
    name = "你叫了他两声，没有任何反应。"
  },
  [200420164] = {
    id = 200420164,
    name = "你探了探他的鼻息......"
  },
  [200420165] = {
    id = 200420165,
    name = "老人已经永远地离开了这个世界。"
  },
  [200420166] = {
    id = 200420166,
    name = "你叹息一声，将老人与断剑葬在了一起，离开了废墟。"
  },
  [200430001] = {
    id = 200430001,
    name = "「参加猎魔大会夺旗的探险者们在这里集合啦！」"
  },
  [200430002] = {
    id = 200430002,
    name = "圈落外，前方一阵人潮涌动，你听见人们欢呼的声音。"
  },
  [200430003] = {
    id = 200430003,
    name = "「猎魔大会？」"
  },
  [200430004] = {
    id = 200430004,
    name = "你挤进了人群，发现一些探险者正在招募成员，组建临时行动小组。"
  },
  [200430005] = {
    id = 200430005,
    name = "「各位探险者，分组时间即将结束，马上准备出发了！」"
  },
  [200430006] = {
    id = 200430006,
    name = "「等等，我们还少一个人！」"
  },
  [200430007] = {
    id = 200430007,
    name = "「我们队也少一个！」"
  },
  [200430008] = {
    id = 200430008,
    name = "「还有一分钟的时间，你们最好快点找到人。」"
  },
  [200430009] = {
    id = 200430009,
    name = "几组探险者齐刷刷地看向了落单的你。"
  },
  [200430010] = {
    id = 200430010,
    name = "「诶？这位探险者，你还没选好小组吗？」"
  },
  [200430011] = {
    id = 200430011,
    name = "「来我们这啊，攻防兼备，保证得第一！」"
  },
  [200430012] = {
    id = 200430012,
    name = "「不不，应该来我们这，你去夺宝，我们全力掩护你，绝对没问题！」"
  },
  [200430013] = {
    id = 200430013,
    name = "「来我们这一组吧，快些结束拿奖励，还不耽误参加下一轮活动。」"
  },
  [200430014] = {
    id = 200430014,
    name = "「喂，你们本来就多一个人，还和我们抢人！」"
  },
  [200430015] = {
    id = 200430015,
    name = "「别听他们的，他们只想让你冲锋可不会管你的死活！」"
  },
  [200430016] = {
    id = 200430016,
    name = "「......」"
  },
  [200430017] = {
    id = 200430017,
    name = "「比赛就是为了赢的，我当然选猎影的队伍。」"
  },
  [200430018] = {
    id = 200430018,
    name = "你的选择引起了另外两队的敌视，他们忿忿地看着你，仿佛将你视为此生大敌。"
  },
  [200430019] = {
    id = 200430019,
    name = "猎影小组的成员则露出势在必得的神色。"
  },
  [200430020] = {
    id = 200430020,
    name = "「嘿，明智的选择，第一名非我们莫属！」"
  },
  [200430021] = {
    id = 200430021,
    name = "「看起来不妙，他们两组好像联合起来了。」"
  },
  [200430022] = {
    id = 200430022,
    name = "你看到言灵探险者队找到了异刃探险者队，他们商量了一阵，决定合作对付你所在的小组。"
  },
  [200430023] = {
    id = 200430023,
    name = "「哼，他们不敢乱来！比赛禁止一切手段的互相伤害，组织者会全程监视我们的行动，一旦违规成绩就会作废。」"
  },
  [200430024] = {
    id = 200430024,
    name = "「看到前面那个山头了吗，只要把上面的旗帜抢回来就能获胜。我们已经发现一条近路，你小子跟紧点。」"
  },
  [200430025] = {
    id = 200430025,
    name = "组织成员吹响短笛，比赛开始，你身旁的猎影探险者以最快的速度冲了出去。"
  },
  [200430026] = {
    id = 200430026,
    name = "「新来的，一会儿到了山顶有只魔物，你去把它引开，我们夺旗！」"
  },
  [200430027] = {
    id = 200430027,
    name = "你点了点头，决定听从他的指挥。"
  },
  [200430028] = {
    id = 200430028,
    name = "「很好，那只魔物又蠢又硬，你无需和它死斗，引走以后尽快下山，我们拿了旗子去山下等你！」"
  },
  [200430029] = {
    id = 200430029,
    name = "你们率先到达山顶，山顶果然盘踞着一头魔物，看有人到来，它立刻直起了庞大的身躯朝你们冲来。"
  },
  [200430030] = {
    id = 200430030,
    name = "你果断出手，全力吸引魔物的注意，身旁几名猎影则迅速散开，直奔旗帜而去。"
  },
  [200430031] = {
    id = 200430031,
    name = "你将魔物引到远处，听到了山顶的欢呼声，知道队友夺旗成功便不再恋战，疾步下山与小组会合。"
  },
  [200430032] = {
    id = 200430032,
    name = "然而当你到达山下的时候，那里站着的胜利者竟然不是猎影小组。"
  },
  [200430033] = {
    id = 200430033,
    name = "「没想到吧，最后胜利的是我们。」"
  },
  [200430034] = {
    id = 200430034,
    name = "「只要不让你们得到第一，奖励分半也无所谓，总归胜利了不是吗？」"
  },
  [200430035] = {
    id = 200430035,
    name = "你望着他们志得意满的目光，惊觉自己的临时加入，似乎破坏了几个小组之间的平衡，不禁有些感慨。"
  },
  [200430036] = {
    id = 200430036,
    name = "你想了想，提出了一些建议。"
  },
  [200430037] = {
    id = 200430037,
    name = "「前有魔物，后有两个小组，这些都是我们的阻碍，如果一起遇上，情况会对我们很不利，不如给他们两队制造点障碍？」"
  },
  [200430038] = {
    id = 200430038,
    name = "「你可别乱来，到时成绩作废我们就扒了你的皮！」"
  },
  [200430039] = {
    id = 200430039,
    name = "「不，我的意思是利用魔物来拦住他们。」"
  },
  [200430040] = {
    id = 200430040,
    name = "「哈哈，你可真是个天才，这的确是个好主意，行，到时候驱赶魔物的事就交给你了！」"
  },
  [200430041] = {
    id = 200430041,
    name = "你们率先到达山顶，山顶果然盘踞着一头魔物，看有人到来，它立刻直起了庞大的身躯朝你们冲来。"
  },
  [200430042] = {
    id = 200430042,
    name = "你果断出手，全力吸引魔物的注意，身旁几名猎影则迅速散开，直奔旗帜而去。"
  },
  [200430043] = {
    id = 200430043,
    name = "你将魔物带到了另外两队到来的方向，朝他们招了招手。"
  },
  [200430044] = {
    id = 200430044,
    name = "「这个可恶的家伙，想用魔物拦住我们！」"
  },
  [200430045] = {
    id = 200430045,
    name = "「各位请多加小心，再见了。」"
  },
  [200430046] = {
    id = 200430046,
    name = "你听到了山顶的欢呼声，得知队友夺旗成功，不再恋战，疾步下山与小组会合。"
  },
  [200430047] = {
    id = 200430047,
    name = "回到山下，猎影探险者招呼你来到组织者身边分享奖励。"
  },
  [200430048] = {
    id = 200430048,
    name = "「多亏了你的计划，我们才能拿到第一，这份奖励是你应得的！下次比赛再来啊~」"
  },
  [200430049] = {
    id = 200430049,
    name = "你思考了一阵，选择加入言灵探险者的队伍，异刃探险者有些遗憾，而猎影探险者眯了眯眼睛，一副不怀好意的模样。"
  },
  [200430050] = {
    id = 200430050,
    name = "比赛正式开始之前，言灵探险者将比赛的规则告知与你：先夺得旁边山头的旗帜，并安全返回的队伍，就是本次比赛的优胜者。"
  },
  [200430051] = {
    id = 200430051,
    name = "「我们已经探查过山路的情况，途中有一种类似植物的魔物十分难缠，只要避开它，就能很快到达山顶。」"
  },
  [200430052] = {
    id = 200430052,
    name = "「最后提醒大家一句，禁止一切手段的互相伤害，我们会全程监视你们的一举一动，一旦发现违规，成绩直接作废。好了，比赛开始！」"
  },
  [200430053] = {
    id = 200430053,
    name = "组织成员吹响短笛，比赛开始。猎影组成员以最快的速度冲了出去，你们紧随其后，很快上了山。"
  },
  [200430054] = {
    id = 200430054,
    name = "「他们走了另一条路，我们按照原计划前进！」"
  },
  [200430055] = {
    id = 200430055,
    name = "很快，你们发现了前方类似植物的魔物。"
  },
  [200430056] = {
    id = 200430056,
    name = "你们决定潜行绕过魔物。"
  },
  [200430057] = {
    id = 200430057,
    name = "就在大家快通过时，其中一名成员不小心被荆棘绊倒，惊扰了魔物。"
  },
  [200430058] = {
    id = 200430058,
    name = "魔物暴起攻击，成员们立刻展开防御，你让他们先走，独自拦下魔物。"
  },
  [200430059] = {
    id = 200430059,
    name = "你全力出手与魔物战斗，不多时便将其击败。"
  },
  [200430060] = {
    id = 200430060,
    name = "你迅速追上了其他成员，然而到达山顶时却发现猎影小组已经抢先一步夺走旗帜。"
  },
  [200430061] = {
    id = 200430061,
    name = "你们因在途中选择绕开魔物而放缓了前进速度，错失比赛胜利。"
  },
  [200430062] = {
    id = 200430062,
    name = "你快速评判了敌我双方的实力，决定除掉魔物。"
  },
  [200430063] = {
    id = 200430063,
    name = "于是你召集众人协助，果断向魔物发起突袭。"
  },
  [200430064] = {
    id = 200430064,
    name = "在你全力攻击之下，几乎瞬间将魔物击毙。"
  },
  [200430065] = {
    id = 200430065,
    name = "随即你们再无顾忌，全速前进，终于率先抵达终点，夺得了本次比赛的第一名。"
  },
  [200430066] = {
    id = 200430066,
    name = "你想了想，猎影小组缺少防护，而言灵小组步伐太缓慢，攻防兼备的队伍更适合你，你选择加入异刃的队伍，言灵小组丧气地摇了摇头。"
  },
  [200430067] = {
    id = 200430067,
    name = "「兄弟，我会证明你的选择没错！让我们一起拿回旗帜，夺得这次比赛的魁首！」"
  },
  [200430068] = {
    id = 200430068,
    name = "队友们跃跃欲试，听组织者宣读最后的比赛规则，谁先夺得旁边山头的旗帜返回，谁就能取得猎魔大会组织为大家准备的赏金。"
  },
  [200430069] = {
    id = 200430069,
    name = "一声短笛响起，比赛开始。猎影组成员率先冲出了起跑线，异刃探险者一下忍不住笑了起来。"
  },
  [200430070] = {
    id = 200430070,
    name = "「这群家伙仗着腿脚快，走了最危险的路，等会儿有他们苦头吃！」"
  },
  [200430071] = {
    id = 200430071,
    name = "「而且山顶还有魔物看守，他们就算先到也很难解决。」"
  },
  [200430072] = {
    id = 200430072,
    name = "「不过咱们这条路上也会有一些魔物干扰，而且......万一他们不和看守魔物死磕，而是将其引走就糟了......」"
  },
  [200430073] = {
    id = 200430073,
    name = "「咱们得想个法子才行，你有什么主意吗？」"
  },
  [200430074] = {
    id = 200430074,
    name = "「我们的目的是夺旗，不用管拦路的魔物，至于山顶的看守魔物，就让他们去引开，只要比他们更快抢到旗帜就行。」"
  },
  [200430075] = {
    id = 200430075,
    name = "「说得倒是轻松，拦路的魔物如果不管，很可能我们还没到终点就有人受伤了。」"
  },
  [200430076] = {
    id = 200430076,
    name = "「或者......你去对付魔物，我们去夺旗。」"
  },
  [200430077] = {
    id = 200430077,
    name = "「如果能获得胜利的话，这样也不是不行。」"
  },
  [200430078] = {
    id = 200430078,
    name = "异刃探险者同意了你的提议，你们加速前进，没过多久果然与魔物狭路相逢。"
  },
  [200430079] = {
    id = 200430079,
    name = "你率先出击，并将一路的魔物都吸引了过来，确保小组其他成员顺利通行。"
  },
  [200430080] = {
    id = 200430080,
    name = "战斗结束后，你加速赶至山顶。此时猎影小组已率先一步夺旗，异刃小组因中了猎影小组的圈套，错失了夺魁的机会。"
  },
  [200430081] = {
    id = 200430081,
    name = "「等着吧，下一次我们一定拿第一名！」"
  },
  [200430082] = {
    id = 200430082,
    name = "「有句话叫做兵贵神速，只要我们够快，不管是魔物还是人，都追不上我们。」"
  },
  [200430083] = {
    id = 200430083,
    name = "「可我们这条路上有不少魔物阻拦，依你看要怎样才能快得起来？」"
  },
  [200430084] = {
    id = 200430084,
    name = "「如果你们相信我的话，由我去夺旗，你们牵制途中魔物，顺便干扰其他小组的判断。」"
  },
  [200430085] = {
    id = 200430085,
    name = "「......好，如果成功了，那你就是我们的奇兵！」"
  },
  [200430086] = {
    id = 200430086,
    name = "异刃小组同意了你的提议，你们加速前进，没过多久果然与魔物狭路相逢，成员们悉数出击，你则趁机直奔山顶。"
  },
  [200430087] = {
    id = 200430087,
    name = "到达山顶时，你见猎影小组正试图引走看守的魔物，你抓住时机，成功夺走了旗帜。"
  },
  [200430088] = {
    id = 200430088,
    name = "「不可能！你怎么可能比我们还快？！」"
  },
  [200430089] = {
    id = 200430089,
    name = "在猎影小组成员不可思议的眼神中，你潇洒离去。"
  },
  [200430090] = {
    id = 200430090,
    name = "「哈哈哈哈，我就知道，我们的合作一定能成功！」"
  },
  [200430091] = {
    id = 200430091,
    name = "「这份奖励你拿好了！下次比赛再一起合作啊！」"
  },
  [200430092] = {
    id = 200430092,
    name = "你想了想，决定先去圈落整顿补给，等一切搞定后再来看看这个所谓的猎魔大会。"
  },
  [200430093] = {
    id = 200430093,
    name = "不过等你返回时，发现活动已经结束了。"
  },
  [200440001] = {
    id = 200440001,
    name = "「参加猎魔大会寻宝的探险者们在这里集合啦！」"
  },
  [200440002] = {
    id = 200440002,
    name = "圈落外，前方一阵人潮涌动，你听见人们欢呼的声音。"
  },
  [200440003] = {
    id = 200440003,
    name = "「猎魔大会？」"
  },
  [200440004] = {
    id = 200440004,
    name = "你挤入人群，听见组织者正在介绍猎魔大会的寻宝规则。"
  },
  [200440005] = {
    id = 200440005,
    name = "「本次寻宝的线索我们都以谜题的方式告诉了大家。在天黑前，第一个找到宝物并带回给我的，将获得丰厚奖励！」"
  },
  [200440006] = {
    id = 200440006,
    name = "「线索......谜题？」"
  },
  [200440007] = {
    id = 200440007,
    name = "「你是第一次参加这个活动吗？」"
  },
  [200440008] = {
    id = 200440008,
    name = "「是啊，我是路过遇到的。」"
  },
  [200440009] = {
    id = 200440009,
    name = "「那你运气真好啊！你如果想参加，就快去找裁判要线索吧！」"
  },
  [200440010] = {
    id = 200440010,
    name = "你按他所说，从裁判员那里得到一张纸条，上面写着——魔物翅膀的颜色。"
  },
  [200440011] = {
    id = 200440011,
    name = "「怎么样，拿到线索了吗？」"
  },
  [200440012] = {
    id = 200440012,
    name = "「嗯。」"
  },
  [200440013] = {
    id = 200440013,
    name = "「呵呵，只要能解开谜题，就能找到宝物！」"
  },
  [200440014] = {
    id = 200440014,
    name = "「不好，大家都出发了，你还不动身吗？还是说想找个同伴组队？」"
  },
  [200440015] = {
    id = 200440015,
    name = "「呵呵，你不也还没出发。」"
  },
  [200440016] = {
    id = 200440016,
    name = "「嘿嘿......我脑子笨，总是比别人慢一步，我先想想线索再出发。」"
  },
  [200440017] = {
    id = 200440017,
    name = "你向探险者表示了感谢，随即独自展开行动。"
  },
  [200440018] = {
    id = 200440018,
    name = "你分析着谜题，带翅膀的魔物常分布在山林溪谷，附近正好有一条河，于是你快步向河流跑去。"
  },
  [200440019] = {
    id = 200440019,
    name = "果然这里已经聚集了不少人，但似乎并无发现，有人甚至已经开始下水摸索河底。"
  },
  [200440020] = {
    id = 200440020,
    name = "见到这一幕，你再次思索起谜题。"
  },
  [200440021] = {
    id = 200440021,
    name = "你根据魔物翅膀这个线索来到了此地，那么颜色又指代什么呢？"
  },
  [200440022] = {
    id = 200440022,
    name = "你正思索着，忽然瞥见河滩上的几棵树，树上开满了蓝紫色的花。"
  },
  [200440023] = {
    id = 200440023,
    name = "你快步朝大树走去。"
  },
  [200440024] = {
    id = 200440024,
    name = "一阵大风吹来，河滩上的众人都闻到了一股幽香，其中一些人也纷纷向大树跑去。"
  },
  [200440025] = {
    id = 200440025,
    name = "这股香味让你觉得有些熟悉，不禁停下了脚步。"
  },
  [200440026] = {
    id = 200440026,
    name = "你忽然想起这种花香具有安眠麻痹的效果！于是立即后退一段距离，屏住呼吸等待风停。"
  },
  [200440027] = {
    id = 200440027,
    name = "冲在最前方的探险者已经被花香影响，逐渐瘫软在地上。"
  },
  [200440028] = {
    id = 200440028,
    name = "你环顾四周，发现被风吹散的花朵纷纷飘向附近一处石壁。"
  },
  [200440029] = {
    id = 200440029,
    name = "所有的线索忽然在你的脑海汇集，你知道宝物在哪里了！"
  },
  [200440030] = {
    id = 200440030,
    name = "你冲向石壁仔细搜寻，果然找到一个金属盒子，盒子上还刻画着圈落的标记。"
  },
  [200440031] = {
    id = 200440031,
    name = "你将盒子带回交给了组织者。"
  },
  [200440032] = {
    id = 200440032,
    name = "「这么快？！这次其实藏了比以往更多的盒子，但你是第一个将它带回的人，恭喜你！」"
  },
  [200440033] = {
    id = 200440033,
    name = "宣告胜者出现的钟声响起，在无数人羡慕的眼神下，你取走了丰厚的奖励。"
  },
  [200440034] = {
    id = 200440034,
    name = "为了抢占先机，你继续迎着花香跑了过去，但没走几步，一阵晕眩感袭来。"
  },
  [200440035] = {
    id = 200440035,
    name = "（想起来了！这种花香具有安眠麻痹的效果！）"
  },
  [200440036] = {
    id = 200440036,
    name = "你急忙屏住呼吸，但为时已晚，强烈的晕眩感让你们这些靠近的人都瘫软在了地上。"
  },
  [200440037] = {
    id = 200440037,
    name = "过了好一会儿你才缓过来，随即捂住口鼻前往大树附近搜寻。"
  },
  [200440038] = {
    id = 200440038,
    name = "你和众人找了很久，直到日落也没有找到所谓的宝物，只能败兴而归。"
  },
  [200440039] = {
    id = 200440039,
    name = "「我们一起找吧，多个人多一双眼睛，要是侥幸胜出，那我们就平分奖励。」"
  },
  [200440040] = {
    id = 200440040,
    name = "「呜哇，你真是个大好人，对了这是我的线索，你脑子聪明，你帮我看看吧。」"
  },
  [200440041] = {
    id = 200440041,
    name = "你接过了她递来的纸条，上面写的内容和你的不同。"
  },
  [200440042] = {
    id = 200440042,
    name = "「我的提示是魔物翅膀的颜色，而你得到的提示却是没有光明的地方......」"
  },
  [200440043] = {
    id = 200440043,
    name = "你陷入了思索，两条线索似乎毫无关联，热心的探险者突然一拍脑袋。"
  },
  [200440044] = {
    id = 200440044,
    name = "「魔物！没有光明！或许我知道！」"
  },
  [200440045] = {
    id = 200440045,
    name = "她告诉你周围有一个山谷，很符合没有光明的描述，而那个山谷中正好存在一些带翅膀的魔物。"
  },
  [200440046] = {
    id = 200440046,
    name = "你们决定去山谷看看，但刚走到附近，便发现此处已经有不少探险者了。"
  },
  [200440047] = {
    id = 200440047,
    name = "「哇，原来其他人也猜到了，咱们也得抓紧了！」"
  },
  [200440048] = {
    id = 200440048,
    name = "你们立即加入搜寻的人群，在山谷中四处摸索。"
  },
  [200440049] = {
    id = 200440049,
    name = "「啊！快、快跑啊！」"
  },
  [200440050] = {
    id = 200440050,
    name = "突然，热心的探险者尖叫着跑了回来，她身后是一大群魔物。"
  },
  [200440051] = {
    id = 200440051,
    name = "场面开始混乱。"
  },
  [200440052] = {
    id = 200440052,
    name = "眼见她陷入危机，你果断冲了出去，将她护在身后，并全力迎击魔物。"
  },
  [200440053] = {
    id = 200440053,
    name = "你的举动瞬间引起了周围人的注意，混乱的局面稍微安定了一点。"
  },
  [200440054] = {
    id = 200440054,
    name = "此时众人才发现来袭的都是些普通魔物，于是纷纷高喊着跟随你一起反击。"
  },
  [200440055] = {
    id = 200440055,
    name = "局面瞬间逆转，你带着众人很快便将所有魔物剿灭。"
  },
  [200440056] = {
    id = 200440056,
    name = "众人欢呼过后，寻宝继续进行。"
  },
  [200440057] = {
    id = 200440057,
    name = "「好险......谢谢你，呜呜呜......要不是你，我今天就要被魔物吃掉了。」"
  },
  [200440058] = {
    id = 200440058,
    name = "「不必客气，而且托你的福，我知道宝物在哪里了！」"
  },
  [200440059] = {
    id = 200440059,
    name = "「啊？在哪里？」"
  },
  [200440060] = {
    id = 200440060,
    name = "「刚才袭击的魔物中，飞行的魔物大部分翅膀都是紫色，而这个山谷中，紫色的地方就是——」"
  },
  [200440061] = {
    id = 200440061,
    name = "「山腰的大树！」"
  },
  [200440062] = {
    id = 200440062,
    name = "她顺着你指的方向看去，一棵枝叶为紫色的大树正耸立在那里。"
  },
  [200440063] = {
    id = 200440063,
    name = "「我知道一条小路可以快速过去，你跟我来！」"
  },
  [200440064] = {
    id = 200440064,
    name = "她显得非常激动，急忙带着你抄小路直奔大树。"
  },
  [200440065] = {
    id = 200440065,
    name = "你们在树下搜寻，果然在一个树缝里发现了一个盒子。"
  },
  [200440066] = {
    id = 200440066,
    name = "你们拿着盒子交给了组织者，幸运地获得了本次比赛的第一名。"
  },
  [200440067] = {
    id = 200440067,
    name = "你见魔物虽然跟在她身后，但还有一段安全距离，便决定先观察一下情况。"
  },
  [200440068] = {
    id = 200440068,
    name = "然而山谷中寻宝的众人听到魔物来袭，看见慌乱四散的人群后，纷纷逃窜，局面瞬间失控。"
  },
  [200440069] = {
    id = 200440069,
    name = "「没办法，先救人吧！」"
  },
  [200440070] = {
    id = 200440070,
    name = "你被逃窜的人群不停冲撞，好不容易才赶到了她身边。"
  },
  [200440071] = {
    id = 200440071,
    name = "虽然你将魔物快速解决，但她也在混乱中被魔物所伤，你只得将她背回圈落治疗。"
  },
  [200440072] = {
    id = 200440072,
    name = "「呜呜，对不起，我就知道我只会拖大家的后腿......」"
  },
  [200440073] = {
    id = 200440073,
    name = "她非常自责，你费了些时间才安慰好她，待她情绪稳定后，你也离开了。"
  },
  [200440074] = {
    id = 200440074,
    name = "你向探险者表示了感谢，随即准备找其他人合作。"
  },
  [200440075] = {
    id = 200440075,
    name = "经过观察，你发现了一对兄妹，他们也正在招募合作对象，于是你向二人走去。"
  },
  [200440076] = {
    id = 200440076,
    name = "「我们同意你加入，找到了奖励就平分吧。不过比起寻宝，我们需要优先保护我妹妹，没问题吧？」"
  },
  [200440077] = {
    id = 200440077,
    name = "这位兄长看起来不在乎什么奖励，对他而言，显然妹妹更加重要。"
  },
  [200440078] = {
    id = 200440078,
    name = "「那么我们先交换情报吧。」"
  },
  [200440079] = {
    id = 200440079,
    name = "随即你们互相展示了收到的线索。"
  },
  [200440080] = {
    id = 200440080,
    name = "「魔物翅膀的颜色、火焰无法升起的地方、温柔的所在......会是在哪里呢......」"
  },
  [200440081] = {
    id = 200440081,
    name = "「魔物的翅膀颜色太多了，但火焰无法升起，一定是水中吧？温柔的话，也是水吧？那么一定就在河里啦！」"
  },
  [200440082] = {
    id = 200440082,
    name = "哥哥立马同意了妹妹的意见，似乎不管她说什么，哥哥也不会有异议。"
  },
  [200440083] = {
    id = 200440083,
    name = "你们来到河边，此时这里已经聚集了不少人。"
  },
  [200440084] = {
    id = 200440084,
    name = "见有人已经进入河中搜寻，妹妹玩性大起，瞬间跳入河中玩起水来。"
  },
  [200440085] = {
    id = 200440085,
    name = "你告诉她水中可能有潜藏的危险，而且还要找寻宝物，将妹妹劝了上来。"
  },
  [200440086] = {
    id = 200440086,
    name = "哥哥皱了皱眉，对你的反应很不满意。"
  },
  [200440087] = {
    id = 200440087,
    name = "随即你们在河畔找了一会儿，但是没有任何发现。"
  },
  [200440088] = {
    id = 200440088,
    name = "妹妹对这种枯燥的寻找失去了耐性，发起脾气，为了哄她哥哥准备带她回圈落逛街，你们就此分开。"
  },
  [200440089] = {
    id = 200440089,
    name = "你独自又搜寻了一阵，但直到胜者出现的钟声响起，你也没有任何发现。"
  },
  [200440090] = {
    id = 200440090,
    name = "你想了想，妹妹的分析似乎也有道理，便也跟着下了水。"
  },
  [200440091] = {
    id = 200440091,
    name = "妹妹认为你也是下水游玩，立即捧起水向你洒来。"
  },
  [200440092] = {
    id = 200440092,
    name = "受到水花攻击的你不甘示弱，也捧起水向妹妹洒去，同时你们将本来没打算下水的哥哥也卷入了战局。"
  },
  [200440093] = {
    id = 200440093,
    name = "你们几人似乎完全忘记了寻宝这件事，尽情在水中嬉闹。"
  },
  [200440094] = {
    id = 200440094,
    name = "过了一会儿，一些周围寻宝的人也被你们带动，放弃了搜寻加入你们。"
  },
  [200440095] = {
    id = 200440095,
    name = "当远处胜者出现的钟声响起，你们才停止了嬉闹。"
  },
  [200440096] = {
    id = 200440096,
    name = "「啊！糟了！都忘记寻找宝物了！」"
  },
  [200440097] = {
    id = 200440097,
    name = "「呵呵，不过度过了一段不错的时间，不是吗？」"
  },
  [200440098] = {
    id = 200440098,
    name = "「反正参加活动也是为了能享受乐趣而已。」"
  },
  [200440099] = {
    id = 200440099,
    name = "「呵呵，你说的没错！不过玩了半天，感觉有点饿了，去吃点东西吧！」"
  },
  [200440100] = {
    id = 200440100,
    name = "「好啊。这位探险者要一起来吗？我知道圈落里有家很棒的餐厅。」"
  },
  [200440101] = {
    id = 200440101,
    name = "你跟随二人向圈落走去，虽然未能找到宝物，但也度过了一段愉悦的时光。"
  },
  [200440102] = {
    id = 200440102,
    name = "你想了想，决定先去圈落整顿补给，等一切搞定后再来看看这个所谓的猎魔大会。"
  },
  [200440103] = {
    id = 200440103,
    name = "不过等你返回时，发现活动已经结束了。"
  },
  [200450001] = {
    id = 200450001,
    name = "「参加猎魔大会诛戮的探险者们在这里集合啦！」"
  },
  [200450002] = {
    id = 200450002,
    name = "圈落外，前方一阵人潮涌动，你听见人们欢呼的声音。"
  },
  [200450003] = {
    id = 200450003,
    name = "「猎魔大会？」"
  },
  [200450004] = {
    id = 200450004,
    name = "你挤入人群，听见组织者正在介绍规则。"
  },
  [200450005] = {
    id = 200450005,
    name = "「......还是按照老规矩来，相同时间内谁击杀的魔物最多，谁就能带走今天的奖励！」"
  },
  [200450006] = {
    id = 200450006,
    name = "「比赛杀魔物？」"
  },
  [200450007] = {
    id = 200450007,
    name = "「噫，新面孔啊。」"
  },
  [200450008] = {
    id = 200450008,
    name = "「嗯，我今天刚到这里。」"
  },
  [200450009] = {
    id = 200450009,
    name = "「哇！那你可不能错过我们一年一度的盛典啊！无论亲自参加还是观赛，都能让你永生难忘！」"
  },
  [200450010] = {
    id = 200450010,
    name = "「我也能参赛吗？」"
  },
  [200450011] = {
    id = 200450011,
    name = "「当然！不管是谁，只要报名就能参赛。」"
  },
  [200450012] = {
    id = 200450012,
    name = "「今年有好几位明星选手，你要是参赛的话可得加油啦，哈哈哈。」"
  },
  [200450013] = {
    id = 200450013,
    name = "「既然如此，那我还是和你一起观赛吧。」"
  },
  [200450014] = {
    id = 200450014,
    name = "「好，那我们赶紧过去赛场，要是晚了，好位置就被抢光了。」"
  },
  [200450015] = {
    id = 200450015,
    name = "你跟着他来到一处山坡上，周围早已聚集了不少人。"
  },
  [200450016] = {
    id = 200450016,
    name = "此处确实如他所说是个观赛的好地方，能将下方猎场的情况尽收眼底。"
  },
  [200450017] = {
    id = 200450017,
    name = "探险者向你介绍起猎场的情况，魔物在哪里放出，选手在哪里入场他都一清二楚。"
  },
  [200450018] = {
    id = 200450018,
    name = "他正和你说着，赛场内响起三声钟声。"
  },
  [200450019] = {
    id = 200450019,
    name = "「哦哦！马上就要开始了！」"
  },
  [200450020] = {
    id = 200450020,
    name = "随着第一名选手入场，比赛正式开始。"
  },
  [200450021] = {
    id = 200450021,
    name = "在一波又一波的欢呼声中，前几名选手分别斩杀了一定数目的魔物。"
  },
  [200450022] = {
    id = 200450022,
    name = "「今年竞争果然激烈啊，不知道能不能打破之前的猎杀记录。」"
  },
  [200450023] = {
    id = 200450023,
    name = "又一位选手上场了，你看了他一眼，随即皱起眉头。"
  },
  [200450024] = {
    id = 200450024,
    name = "此人看上去并不强，但防护却是已经上场的选手中最简单的。"
  },
  [200450025] = {
    id = 200450025,
    name = "这样的装备确实可以充分发挥自身的灵活性，但如果敌人众多......"
  },
  [200450026] = {
    id = 200450026,
    name = "果然，开场不久，此人便被魔物群逼得节节败退，所谓的灵活性在众多魔物前毫无作用。"
  },
  [200450027] = {
    id = 200450027,
    name = "他的表现令周围观众非常不满，不时有嘘声传出，随着场内局面演变为参赛者一个劲地逃跑，魔物不停追赶时，周围更是爆发出阵阵哄笑。"
  },
  [200450028] = {
    id = 200450028,
    name = "参赛者已经负伤，但主办方似乎仍没有干预的打算。"
  },
  [200450029] = {
    id = 200450029,
    name = "「再这么下去，他会死的。」"
  },
  [200450030] = {
    id = 200450030,
    name = "「啊？」"
  },
  [200450031] = {
    id = 200450031,
    name = "你刚说完，参赛者又被魔物击中一次，这次主办方终于决定干预了。"
  },
  [200450032] = {
    id = 200450032,
    name = "但进场协助的人员似乎出了岔子，意外将另一波魔物放了出来......"
  },
  [200450033] = {
    id = 200450033,
    name = "赛场内一大群魔物追着几人狂奔，眼看惨剧即将上演，周围却爆发出一阵又一阵的热烈呼声。"
  },
  [200450034] = {
    id = 200450034,
    name = "你拨开人群向着赛场冲了过去，几名赛场管理人员想拦住你，却被你一个眼神瞪了回去。"
  },
  [200450035] = {
    id = 200450035,
    name = "你翻身进入赛场，一边轰击魔物，转移魔物的注意力，一边迂回旋转，将冲向你的魔物绕得团团转。"
  },
  [200450036] = {
    id = 200450036,
    name = "同时你也招呼着逃窜的人，让他们往你的方向逃。"
  },
  [200450037] = {
    id = 200450037,
    name = "几人见你相救，如同抓住了救命稻草，全力向你奔来。"
  },
  [200450038] = {
    id = 200450038,
    name = "其中跑得最快的人距离你仅几步之远时，你一个箭步冲出，抓起他的衣领，猛地向场外人群中丢去。"
  },
  [200450039] = {
    id = 200450039,
    name = "「哇！！！」"
  },
  [200450040] = {
    id = 200450040,
    name = "人群响起一阵惊呼，稳稳地将他接住了。"
  },
  [200450041] = {
    id = 200450041,
    name = "随即你采用相同的方式，又将其他几人全部扔出场外后，你才寻找机会跳了出去，留下一群魔物在场内嘶吼咆哮。"
  },
  [200450042] = {
    id = 200450042,
    name = "「谢、谢谢你。」"
  },
  [200450043] = {
    id = 200450043,
    name = "「你们的应急措施也太不可靠了！算了，赶紧救治伤员，解决场内魔物吧。」"
  },
  [200450044] = {
    id = 200450044,
    name = "「好、好的！我这就安排，这就安排。」"
  },
  [200450045] = {
    id = 200450045,
    name = "看着他一路小跑的样子，你不禁感到扫兴。"
  },
  [200450046] = {
    id = 200450046,
    name = "摇了摇头，你混入四散的人群离开了赛场。"
  },
  [200450047] = {
    id = 200450047,
    name = "参赛者陷入危机，营救人员也陷入危机，你见组织者正在下方跑来跑去召集人手，似乎在准备更大规模的救援。"
  },
  [200450048] = {
    id = 200450048,
    name = "但就在此时，人群中爆发出一阵惊呼。"
  },
  [200450049] = {
    id = 200450049,
    name = "你向赛场内看去，一名营救人员不小心被石头绊到，摔倒在地，身后的魔物已经一拥而上。"
  },
  [200450050] = {
    id = 200450050,
    name = "新的救援尚未到位，但场内的情况已不容乐观，你知道不能再等了。"
  },
  [200450051] = {
    id = 200450051,
    name = "随即，你一个纵身跃下山坡，踩着前方观众的头，在一声声惊呼中跳入了赛场。"
  },
  [200450052] = {
    id = 200450052,
    name = "你一记魔法击退了营救人员周围的魔物，他虽拼死抵抗，但此刻已是身受重伤。"
  },
  [200450053] = {
    id = 200450053,
    name = "你抓起他的衣领，猛地向场外人群中丢去。"
  },
  [200450054] = {
    id = 200450054,
    name = "（是生是死，就看你自己的造化了。）"
  },
  [200450055] = {
    id = 200450055,
    name = "人群响起一阵惊呼，稳稳地将他接住了。"
  },
  [200450056] = {
    id = 200450056,
    name = "随即你向着还在奔逃的几人冲去，将他们全部扔出场外后，你才寻找机会跳了出去，留下一群魔物在场内嘶吼咆哮。"
  },
  [200450057] = {
    id = 200450057,
    name = "此时，组织者才带着新组建的救援队出现。"
  },
  [200450058] = {
    id = 200450058,
    name = "你看他气喘吁吁的样子，没有多说什么，只是瞥了一眼场内的魔物。"
  },
  [200450059] = {
    id = 200450059,
    name = "他瞬间明白了你的意思。"
  },
  [200450060] = {
    id = 200450060,
    name = "「你们赶紧出动，把赛场内所有魔物全部剿灭！」"
  },
  [200450061] = {
    id = 200450061,
    name = "当他安排好一切，准备向你道谢时，你已经混入四散的人群，离开了赛场。"
  },
  [200450062] = {
    id = 200450062,
    name = "「来都来了，我也去试试吧。」"
  },
  [200450063] = {
    id = 200450063,
    name = "你按照探险者的指引找到了报名者，他递给你一个牌子，上面写着一个数字。"
  },
  [200450064] = {
    id = 200450064,
    name = "「你的号码是28，叫到这个数字的时候你就上场。」"
  },
  [200450065] = {
    id = 200450065,
    name = "报名者又和你讲了些比赛规则，比如每轮挑战都是单人进行。"
  },
  [200450066] = {
    id = 200450066,
    name = "如果在限定时间内击杀完放出来的所有魔物，裁判会暂停时间，继续放出新的魔物给参赛者继续挑战。"
  },
  [200450067] = {
    id = 200450067,
    name = "最终在指定时间内，击杀魔物最多的人获得优胜。"
  },
  [200450068] = {
    id = 200450068,
    name = "「嗯，我明白了。」"
  },
  [200450069] = {
    id = 200450069,
    name = "了解完规则，你根据他的指引走向赛场。"
  },
  [200450070] = {
    id = 200450070,
    name = "伴随着三声钟声响起，比赛正式开启。"
  },
  [200450071] = {
    id = 200450071,
    name = "你坐在候场席位上，观察着前面选手的挑战。"
  },
  [200450072] = {
    id = 200450072,
    name = "第一轮3头，第二轮5头，第三轮7头......"
  },
  [200450073] = {
    id = 200450073,
    name = "但直到11号选手登场前，也没有人能将前三轮魔物全部击杀。"
  },
  [200450074] = {
    id = 200450074,
    name = "「请直接放出前两轮的魔物。」"
  },
  [200450075] = {
    id = 200450075,
    name = "听着他的话你心里一惊，竟然还能这样？！但同时面对8头魔物......看来他很自信啊。"
  },
  [200450076] = {
    id = 200450076,
    name = "观众席爆发出热烈的欢呼，原来11号正是今天的明星选手之一。"
  },
  [200450077] = {
    id = 200450077,
    name = "经过一番精彩的战斗，他赶在计时结束前将第四轮怪物全部歼灭。"
  },
  [200450078] = {
    id = 200450078,
    name = "「哼，跳梁小丑罢了。」"
  },
  [200450079] = {
    id = 200450079,
    name = "和周围观众山呼海啸的欢呼声不同，24号选手似乎对11号很不满。"
  },
  [200450080] = {
    id = 200450080,
    name = "「阁下对他很熟悉吗？」"
  },
  [200450081] = {
    id = 200450081,
    name = "24号看了你一眼，眼中满是不屑，似乎与你们坐在一起已经是对你们的恩赐。"
  },
  [200450082] = {
    id = 200450082,
    name = "「熟悉？不，我的脑海中容不下小丑的存在。」"
  },
  [200450083] = {
    id = 200450083,
    name = "「哟，我以为是谁呢，原来是我之前破纪录时的背景板啊。」"
  },
  [200450084] = {
    id = 200450084,
    name = "「是你？」"
  },
  [200450085] = {
    id = 200450085,
    name = "「哎~几年没来参加，这记录竟然还是我当年打下的。」"
  },
  [200450086] = {
    id = 200450086,
    name = "你眉头微挑，看向了说话之人，此人外表看似普通，但举手投足间，都透露着一种强者独有的感觉。"
  },
  [200450087] = {
    id = 200450087,
    name = "（竟然也收敛了气息吗......）"
  },
  [200450088] = {
    id = 200450088,
    name = "「这位兄弟是第一次来吗？运气不错嘛。」"
  },
  [200450089] = {
    id = 200450089,
    name = "眼见你打量他，17号来到你身边，拍了拍你的肩膀，看似和善，但所说的话却无比傲慢。"
  },
  [200450090] = {
    id = 200450090,
    name = "「第一次来就能和这位背景板一起见证新纪录的诞生，哈哈哈，真是好运气啊。」"
  },
  [200450091] = {
    id = 200450091,
    name = "「......」"
  },
  [200450092] = {
    id = 200450092,
    name = "「啊，兄弟，我可没有贬低你的意思，不仅是你，今天在座的诸位，也都是背景板，啊哈哈哈哈~」"
  },
  [200450093] = {
    id = 200450093,
    name = "看着17号的嚣张模样，24号眼中似乎要喷出火来。"
  },
  [200450094] = {
    id = 200450094,
    name = "又过了一段时间，终于轮到你上场了。"
  },
  [200450095] = {
    id = 200450095,
    name = "此前，17号再次突破大赛记录，将第一名的斩杀记录重新定在了第七轮魔物。"
  },
  [200450096] = {
    id = 200450096,
    name = "而24号即使拼尽了全力，也还是差了一点。"
  },
  [200450097] = {
    id = 200450097,
    name = "你走进赛场，舒展了一番身体，此时组织者向你问起释放魔物的顺序。"
  },
  [200450098] = {
    id = 200450098,
    name = "你决定给现场这些人一点震撼。"
  },
  [200450099] = {
    id = 200450099,
    name = "「第一次放1-4轮魔物，第二次放5-7轮，第三次......再说吧。」"
  },
  [200450100] = {
    id = 200450100,
    name = "寂静，绝对的寂静。你话音一落，全场一片死寂。"
  },
  [200450101] = {
    id = 200450101,
    name = "「你、你确定吗？这么多，发生意外我们可来不及救援。」"
  },
  [200450102] = {
    id = 200450102,
    name = "「确定。」"
  },
  [200450103] = {
    id = 200450103,
    name = "又是一阵沉默，片刻后，随着一声哨响，一大群魔物嘶吼着冲出牢笼，向你扑来。"
  },
  [200450104] = {
    id = 200450104,
    name = "你在之前的观察中，早已知晓这些魔物的实力，洞悉了他们的弱点。"
  },
  [200450105] = {
    id = 200450105,
    name = "此时，你决定全力展现实力，让小看你的人闭嘴。"
  },
  [200450106] = {
    id = 200450106,
    name = "你原地站定，任由魔物冲来。"
  },
  [200450107] = {
    id = 200450107,
    name = "「喂喂，他就那样站着，这是在找死吧？！」"
  },
  [200450108] = {
    id = 200450108,
    name = "十米、八米、五米......"
  },
  [200450109] = {
    id = 200450109,
    name = "你默数着魔物们与你的距离，许多观众已经害怕地扭过头，紧闭双眼。"
  },
  [200450110] = {
    id = 200450110,
    name = "三米、两米、一米——"
  },
  [200450111] = {
    id = 200450111,
    name = "就在魔物即将撕碎你的前一秒，你一脚踏地，跃上高空，随即将早已准备完成的魔法术式向下全力施放。"
  },
  [200450112] = {id = 200450112, name = "轰——"},
  [200450113] = {
    id = 200450113,
    name = "巨大的爆炸席卷了整个赛场，爆炸的强风将近距离的观众也吹得倒退几步。"
  },
  [200450114] = {
    id = 200450114,
    name = "烟尘消散，你立于赛场中央。"
  },
  [200450115] = {
    id = 200450115,
    name = "短暂寂静之后，现场爆发出山呼海啸般地呼喊......"
  },
  [200450116] = {
    id = 200450116,
    name = "这一次，你将大赛的记录刷新到了一个前所未有的数字。"
  },
  [200450117] = {
    id = 200450117,
    name = "第二天，为了躲避上门采访、求助、握手、邀约等等的人群，你化妆扮成拾荒者悄悄离开了。"
  },
  [200450118] = {
    id = 200450118,
    name = "你决定稳扎稳打，尝试挑战自己的极限。"
  },
  [200450119] = {
    id = 200450119,
    name = "「一轮一轮地放吧，每当我解决完请立即放下一轮，直到我喊停。」"
  },
  [200450120] = {
    id = 200450120,
    name = "「这样你可就没有休息的时间了，确定吗？」"
  },
  [200450121] = {
    id = 200450121,
    name = "「确定。」"
  },
  [200450122] = {
    id = 200450122,
    name = "随着一声哨响，第一波魔物直扑你而来。"
  },
  [200450123] = {
    id = 200450123,
    name = "你全力运转魔法，抬手便是多段攻击，几乎在一瞬间便将几头魔物解决。"
  },
  [200450124] = {
    id = 200450124,
    name = "紧接着便是第二轮......"
  },
  [200450125] = {
    id = 200450125,
    name = "「喂喂，他这也太强了吧，说不定能打破17号的记录。」"
  },
  [200450126] = {
    id = 200450126,
    name = "「这不太可能，17号第一次可是直接放出了前三轮的魔物。」"
  },
  [200450127] = {
    id = 200450127,
    name = "「他看起来每一轮都很快，但时间就那么点，而且后面魔物越来越多，我才不信他能维持这样的速度。」"
  },
  [200450128] = {
    id = 200450128,
    name = "第三轮、第四轮、第五轮......"
  },
  [200450129] = {
    id = 200450129,
    name = "每一轮几乎都是魔物刚出来不久便被你剿灭......"
  },
  [200450130] = {
    id = 200450130,
    name = "观众们停下了欢呼，紧张地看着你，几乎忘记了呼吸，释放魔物的组织者手心也已出汗。"
  },
  [200450131] = {
    id = 200450131,
    name = "你仍忘情地战斗着，似乎忘记了时间，忘记了地点，肆意施放着魔法......"
  },
  [200450132] = {
    id = 200450132,
    name = "这种感觉你已经很久没感受过了，直到突然的一声长哨，将你拉回了现实。"
  },
  [200450133] = {
    id = 200450133,
    name = "你环顾四周，赛场内一片死寂。"
  },
  [200450134] = {
    id = 200450134,
    name = "「请问结束了吗？」"
  },
  [200450135] = {
    id = 200450135,
    name = "话音刚落，周围便响起山呼海啸般的喝彩声，组织者不断高喊着「新纪录」。"
  },
  [200450136] = {
    id = 200450136,
    name = "你这才反应过来。"
  },
  [200450137] = {
    id = 200450137,
    name = "庆祝会上，无数贵族才俊向你敬酒，和你攀谈，希望拉近你们的关系。"
  },
  [200450138] = {
    id = 200450138,
    name = "你实在难以应对，最终在庆祝会间隙，找了个时机偷偷溜走了。"
  },
  [200450139] = {
    id = 200450139,
    name = "你想了想，决定先去圈落整顿补给，等一切搞定后再来看看这个所谓的猎魔大会。"
  },
  [200450140] = {
    id = 200450140,
    name = "不过等你返回时，发现活动已经结束了。"
  },
  [200460001] = {
    id = 200460001,
    name = "你走在路途中，突然感觉到一阵眩晕。"
  },
  [200460002] = {
    id = 200460002,
    name = "当你发现不对劲时，已经手脚酸软，浑身无力，你凭着意志没有让自己晕过去。"
  },
  [200460003] = {
    id = 200460003,
    name = "此时前方出现了两个模糊的影子，正向你走来，你思忖着该如何应对。"
  },
  [200460004] = {
    id = 200460004,
    name = "你倒在地上假装昏迷，暗中以魔力刺激自己，以强烈的痛感让自己保持清醒，同时做好了随时拼死一搏的准备。"
  },
  [200460005] = {
    id = 200460005,
    name = "对方逐渐靠近。通过声音，你判断是两人......不，一人一宠物？"
  },
  [200460006] = {
    id = 200460006,
    name = "虽有疑惑，但你并未睁眼，静静等待对方的动作。"
  },
  [200460007] = {
    id = 200460007,
    name = "对方在你面前站了一会儿，随即周围响起一阵窸窸窣窣的声音。"
  },
  [200460008] = {
    id = 200460008,
    name = "又过了一会儿，你听到一个少女开始吟唱起咒语。"
  },
  [200460009] = {
    id = 200460009,
    name = "伴随着少女的咒语，你敏锐地觉察到地面的魔力开始以你为中心流动。"
  },
  [200460010] = {
    id = 200460010,
    name = "（似乎并无危险，是在治疗我吗？）"
  },
  [200460011] = {
    id = 200460011,
    name = "虽然并未感觉到身体有加速恢复的迹象，但流动的魔力让你觉得非常舒适。"
  },
  [200460012] = {
    id = 200460012,
    name = "少女停止了吟唱，又仔细观察了你一阵，似乎对你的情况感到疑惑。"
  },
  [200460013] = {
    id = 200460013,
    name = "少女陷入了沉默，过了一会儿她向你凑了过来，你甚至能感觉到她的鼻息。"
  },
  [200460014] = {
    id = 200460014,
    name = "你睁开了眼睛，少女正用她明亮清澈的大眼睛打量你，距离你的脸只有几厘米。"
  },
  [200460015] = {
    id = 200460015,
    name = "她被你突然睁眼吓了一大跳，怪叫着摔倒在地，倒爬了好几米。"
  },
  [200460016] = {
    id = 200460016,
    name = "你发现除了少女，之前感受到的另一个存在是一头魔物，不，长得像魔物的傀儡。"
  },
  [200460017] = {
    id = 200460017,
    name = "此刻它正乖巧地坐在一旁。"
  },
  [200460018] = {
    id = 200460018,
    name = "「你你你，你吓死我了！」"
  },
  [200460019] = {
    id = 200460019,
    name = "少女拍着胸口，好一阵才平息下来。"
  },
  [200460020] = {
    id = 200460020,
    name = "「既然没晕的话就早点说话啊，我还以为成功了呢......」"
  },
  [200460021] = {
    id = 200460021,
    name = "「阿妈给的迷烟完全没用嘛，还说什么可以轻松放倒魔物，哼。」"
  },
  [200460022] = {
    id = 200460022,
    name = "「你想做什么？」"
  },
  [200460023] = {
    id = 200460023,
    name = "「当然是把你炼成傀儡啦，如果刚才契约成功，你现在就已经是我的傀儡了！」"
  },
  [200460024] = {
    id = 200460024,
    name = "「契约？」"
  },
  [200460025] = {
    id = 200460025,
    name = "你看向地面，原来刚才的动静是少女在画魔法阵。"
  },
  [200460026] = {
    id = 200460026,
    name = "你动了动身体，发现之前的晕眩感已经减轻了很多，遂起身准备离去。"
  },
  [200460027] = {
    id = 200460027,
    name = "「喂！你要去哪里？」"
  },
  [200460028] = {
    id = 200460028,
    name = "「我没有回答你的义务，你偷袭我的事都还没和你计较，别得寸进尺。」"
  },
  [200460029] = {
    id = 200460029,
    name = "「你！我也不想啊，可是不偷袭我根本抓不住人嘛......」"
  },
  [200460030] = {
    id = 200460030,
    name = "「......」"
  },
  [200460031] = {
    id = 200460031,
    name = "「你抓人做什么？」"
  },
  [200460032] = {
    id = 200460032,
    name = "「我说过了啊，契约傀儡啊。」"
  },
  [200460033] = {
    id = 200460033,
    name = "「......」"
  },
  [200460034] = {
    id = 200460034,
    name = "眼见你又准备离开，少女立即朝你扑来，抱住了你的脚。"
  },
  [200460035] = {
    id = 200460035,
    name = "「不要走嘛，不要走嘛。」"
  },
  [200460036] = {
    id = 200460036,
    name = "少女抱着你的脚不放，开始撒娇，你继续追问她的目的。"
  },
  [200460037] = {
    id = 200460037,
    name = "「你假装我的傀儡好不好？」"
  },
  [200460038] = {
    id = 200460038,
    name = "「我拒绝。」"
  },
  [200460039] = {
    id = 200460039,
    name = "「求求你了！你一看就是好心人，好心的大哥哥，你帮帮我吧！」"
  },
  [200460040] = {
    id = 200460040,
    name = "「对了，我可以给你钱！阿秋！」"
  },
  [200460041] = {
    id = 200460041,
    name = "少女将名为阿秋的傀儡叫了过来，从它肚子里掏出一堆金币。"
  },
  [200460042] = {
    id = 200460042,
    name = "「只要你装作我的傀儡，帮我完成任务，这些钱我都给你！」"
  },
  [200460043] = {
    id = 200460043,
    name = "「我可不是看在钱的份上，只想看看到底是谁想出这种任务！」"
  },
  [200460044] = {
    id = 200460044,
    name = "眼见你答应，少女破涕为笑，立即与你商量了起来。"
  },
  [200460045] = {
    id = 200460045,
    name = "少女告诉你，她想外出游历，但母亲要她先证明自己，用契约炼制一个傀儡。"
  },
  [200460046] = {
    id = 200460046,
    name = "「契约炼制傀儡？」"
  },
  [200460047] = {
    id = 200460047,
    name = "「嗯！阿秋就是阿妈炼制的傀儡，别看它笨笨的，但普通魔物根本不是它的对手。」"
  },
  [200460048] = {
    id = 200460048,
    name = "你对她的母亲不禁感到好奇。"
  },
  [200460049] = {
    id = 200460049,
    name = "你跟随少女回到了她家。"
  },
  [200460050] = {
    id = 200460050,
    name = "你还在思索如何扮演傀儡，找机会从她母亲口中套话，没想到她母亲却一眼将你识破。"
  },
  [200460051] = {
    id = 200460051,
    name = "你只得将事情挑明，质问她为何要对探险者下手。"
  },
  [200460052] = {
    id = 200460052,
    name = "听完你的话，少女母亲愣住了，随即将少女叫到了跟前教训起来。"
  },
  [200460053] = {
    id = 200460053,
    name = "随后她才向你解释存在的误会。"
  },
  [200460054] = {
    id = 200460054,
    name = "原来那个魔法阵根本不是什么契约用的，只是一个限制魔物的阵法，她们的魔法对人类也没效果。"
  },
  [200460055] = {
    id = 200460055,
    name = "而且母亲根本没有让女儿对探险者动手，只是告诉女儿，想出去游历，先证明自己的能力再说。"
  },
  [200460056] = {
    id = 200460056,
    name = "随后又感慨到要是她外出游历了，这个家就只剩自己一个人，空荡荡的，想说话都找不到人。"
  },
  [200460057] = {
    id = 200460057,
    name = "结果少女完全误解了母亲的意思，不知道怎么想的，竟然理解为要去外面抓个探险者证明自己。"
  },
  [200460058] = {
    id = 200460058,
    name = "还想炼制一个探险者傀儡留在家中陪伴母亲......"
  },
  [200460059] = {
    id = 200460059,
    name = "知晓事情的真相后，你长舒了一口气。"
  },
  [200460060] = {
    id = 200460060,
    name = "在这位母亲不停的道歉、以及少女的哭声中，你离开了。"
  },
  [200460061] = {
    id = 200460061,
    name = "「我没有帮你的义务，而且我也不认识你，撒娇也没用。」"
  },
  [200460062] = {
    id = 200460062,
    name = "你甩开了少女向远处走去，身后再次传来少女的哭声和祈求。"
  },
  [200460063] = {
    id = 200460063,
    name = "你叹了口气，加快脚步离开了。"
  },
  [200460064] = {
    id = 200460064,
    name = "被迷烟偷袭让你觉得很不快，加之少女甚至对你使用奇奇怪怪的魔法......"
  },
  [200460065] = {
    id = 200460065,
    name = "你本想给她个教训，但你仔细观察后发现那个魔法阵虽然玄妙，但和契约什么的毫无关联。"
  },
  [200460066] = {
    id = 200460066,
    name = "加之少女本人看上去并无恶意，你决定不予理会。"
  },
  [200460067] = {
    id = 200460067,
    name = "对这种不知道哪来的任性自大的小姑娘，你不想和她牵扯到一起。"
  },
  [200460068] = {
    id = 200460068,
    name = "「喂！你不准走！」"
  },
  [200460069] = {
    id = 200460069,
    name = "你头也不回地走远了。"
  },
  [200460070] = {
    id = 200460070,
    name = "「我说了不许走啊！」"
  },
  [200460071] = {
    id = 200460071,
    name = "「呜呜呜，阿秋，我又失败了......」"
  },
  [200460072] = {
    id = 200460072,
    name = "少女抱着魔物傀儡伤心地哭了起来。"
  },
  [200460073] = {
    id = 200460073,
    name = "判断少女的魔法对你并无危害后，你继续假装昏迷，想看看她究竟想做什么。"
  },
  [200460074] = {
    id = 200460074,
    name = "少女陷入了长时间的沉默，似乎在思索什么难题。"
  },
  [200460075] = {
    id = 200460075,
    name = "你沉浸在魔力流转的舒适感中，不知不觉忘记了维系清醒，昏睡了过去。"
  },
  [200460076] = {
    id = 200460076,
    name = "等你苏醒时，发现自己已经躺在一张床上，房间内还有一对母女。"
  },
  [200460077] = {
    id = 200460077,
    name = "见你醒来，母亲急忙带着女儿上前道歉。"
  },
  [200460078] = {
    id = 200460078,
    name = "「非常抱歉，我女儿任性的行为给你添麻烦了。」"
  },
  [200460079] = {
    id = 200460079,
    name = "「对、对不起，我知道错了，请原谅我！」"
  },
  [200460080] = {
    id = 200460080,
    name = "在二人后续说明中，你知道了整个事情的经过。"
  },
  [200460081] = {
    id = 200460081,
    name = "原来女儿误解了母亲的话，才自作主张将你绑了回来。"
  },
  [200460082] = {
    id = 200460082,
    name = "你无奈地摇了摇头，在二人不停的道歉中离开了。"
  },
  [200460083] = {
    id = 200460083,
    name = "你暗掐掌心，辅以魔力刺激，通过痛觉维持着清醒。"
  },
  [200460084] = {
    id = 200460084,
    name = "两个身影逐渐靠近，你这才看清来者是一名少女和一头——魔物？！"
  },
  [200460085] = {
    id = 200460085,
    name = "但你仔细观察后发现，那魔物行动僵硬，毫无生机，看来是以魔物为素材制作的傀儡。"
  },
  [200460086] = {
    id = 200460086,
    name = "「咦？你为什么还醒着啊？！中了我的迷烟，应该会昏迷才对啊。」"
  },
  [200460087] = {
    id = 200460087,
    name = "「你是故意对我下手的？」"
  },
  [200460088] = {
    id = 200460088,
    name = "「当然啦！不过竟然失败了，难道是剂量太低了吗......」"
  },
  [200460089] = {
    id = 200460089,
    name = "少女看上去充满了朝气，一双眼睛尤为灵动，但她的回答却令你非常意外。"
  },
  [200460090] = {
    id = 200460090,
    name = "「你故意袭击我，究竟想做什么？」"
  },
  [200460091] = {
    id = 200460091,
    name = "「哎呀，你问题真多！当然是把你做成和阿秋一样的傀儡啊。」"
  },
  [200460092] = {
    id = 200460092,
    name = "少女拍了拍魔物傀儡的脑袋，傀儡立即乖乖地坐在了她脚下。"
  },
  [200460093] = {
    id = 200460093,
    name = "「你能把人做成傀儡？」"
  },
  [200460094] = {
    id = 200460094,
    name = "「当然了，阿秋就是我做的！」"
  },
  [200460095] = {
    id = 200460095,
    name = "少女显得极为自信，你却感到恐惧。"
  },
  [200460096] = {
    id = 200460096,
    name = "如果真的可以做到，这种技术或许将带来无尽的灾祸。"
  },
  [200460097] = {
    id = 200460097,
    name = "「你真有这么厉害？看起来不像啊~」"
  },
  [200460098] = {
    id = 200460098,
    name = "「你、你竟敢小看我！」"
  },
  [200460099] = {
    id = 200460099,
    name = "「毕竟你看起来就是不会嘛。要不你说说具体的操作？」"
  },
  [200460100] = {
    id = 200460100,
    name = "「我......我才不告诉你！」"
  },
  [200460101] = {
    id = 200460101,
    name = "「哼，虽然这次失败了，但我是不会放弃的！」"
  },
  [200460102] = {
    id = 200460102,
    name = "少女带着魔物跑远了。"
  },
  [200460103] = {
    id = 200460103,
    name = "你虽然还有许多疑问，但此时身体也尚未恢复，只得之后再调查了。"
  },
  [86170001] = {id = 86170001, name = "辉夜"},
  [86170002] = {id = 86170002, name = "月蚀"},
  [86170003] = {id = 86170003, name = "星云"},
  [130010001] = {
    id = 130010001,
    name = "我们离开据点也有不少距离了，但遇到的都只是些普通魔物......委托会不会太简单了？"
  },
  [130010002] = {
    id = 130010002,
    name = "这不是我们该考虑的事，我们只需依照委托指示，将物品送到目的地即可。"
  },
  [130010003] = {
    id = 130010003,
    name = "我当然知道，只是从目前的情况来看，这种难度的委托不管我们中的哪一位都能独自完成吧？"
  },
  [130010004] = {
    id = 130010004,
    name = "竟然指派我们三人，难道是组织良心发现，体谅我们平时太累，或者护送的物品——"
  },
  [130010005] = {
    id = 130010005,
    name = "星云，别忘了「深渊航线」的规定。"
  },
  [130010006] = {
    id = 130010006,
    name = "没错，再说下去，恐怕你这个月的酬金又得被组织回收了。"
  },
  [130010007] = {
    id = 130010007,
    name = "说起来你已经几个月蝉联「深渊航线」罚金榜的第一了吧？"
  },
  [130010008] = {
    id = 130010008,
    name = "哼，我明明只是和客人们正常聊天而已，是组织单方面认为我有探听客人隐私的嫌疑，根本不公平！"
  },
  [130010009] = {
    id = 130010009,
    name = "而且你们两也没比我好多少嘛，虽然罚金少一些，但被投诉的次数可比我多。"
  },
  [130010010] = {id = 130010010, name = "......"},
  [130010011] = {id = 130010011, name = "......"},
  [130010012] = {
    id = 130010012,
    name = "哼哼，无话可说了吧？"
  },
  [130010013] = {
    id = 130010013,
    name = "我和辉夜都是不想理会一些客人无理的要求而已。"
  },
  [130010014] = {
    id = 130010014,
    name = "别想太多了，组织既然安排我们三人一起行动，自然有自己的考虑。"
  },
  [130010015] = {
    id = 130010015,
    name = "唉，这也太大材小用了。"
  },
  [130010016] = {
    id = 130010016,
    name = "要我说，不如接下来就由我独自完成护送任务，你们呢就回去据点休息，或者去找点兼职赚外快。"
  },
  [130010017] = {
    id = 130010017,
    name = "到时候这次委托的酬金，你们一人分我一半就行！"
  },
  [130010018] = {id = 130010018, name = "你......"},
  [130010019] = {
    id = 130010019,
    name = "休息结束，走吧。"
  },
  [130010020] = {
    id = 130010020,
    name = "欸，等等我啊！你们真的不考虑一下吗？分我三分之一也行！"
  },
  [130020001] = {
    id = 130020001,
    name = "喂，你们俩快点啊，我发现一个绝佳的宿营地，今晚可以在那休息了！"
  },
  [130020002] = {
    id = 130020002,
    name = "你跑太快了，注意周围情况，当心魔物。"
  },
  [130020003] = {
    id = 130020003,
    name = "远处那个山峰好壮观啊！是我们的目的地吗？"
  },
  [130020004] = {id = 130020004, name = "......"},
  [130020005] = {
    id = 130020005,
    name = "呵呵，她还是一如既往的随性。"
  },
  [130020006] = {
    id = 130020006,
    name = "她有些太放松了，自从进入这片区域，魔物的数量和实力都有明显提升，如果不多加小心......"
  },
  [130020007] = {
    id = 130020007,
    name = "我明白你的意思，不过她的实力我们有目共睹，而且这片区域的魔物虽然变强了不少，但还算不上威胁。"
  },
  [130020008] = {
    id = 130020008,
    name = "其实，你在意的也是组织委派我们三人这件事吧？"
  },
  [130020009] = {
    id = 130020009,
    name = "嗯。我们大多数时候都是独自负责委托，但这次却特意安排我们一起......后续的敌人恐怕会很棘手。"
  },
  [130020010] = {
    id = 130020010,
    name = "确实如此，不过也正因为这样，才需要适当休息放松吧？一直紧绷着神经，在关键时刻可没法发挥出全力。"
  },
  [130020011] = {
    id = 130020011,
    name = "而且既然安排了我们三人，说明组织也确信即便真出现了恐怖的家伙，我们三人联手也足以应对。"
  },
  [130020012] = {
    id = 130020012,
    name = "抱歉，让你担心了。"
  },
  [130020013] = {
    id = 130020013,
    name = "恐怖的家伙！哪里有恐怖的家伙？！"
  },
  [130020014] = {id = 130020014, name = "！！！"},
  [130020015] = {
    id = 130020015,
    name = "你、你从哪里钻出来的。"
  },
  [130020016] = {
    id = 130020016,
    name = "刚才你不是让我注意周围吗，所以我就绕去旁边查探了一下。"
  },
  [130020017] = {
    id = 130020017,
    name = "啊？难道你们刚刚在讲恐怖故事，我突然出现吓到你了？"
  },
  [130020018] = {
    id = 130020018,
    name = "......没有。"
  },
  [130020019] = {
    id = 130020019,
    name = "恐怖故事......嗯，今晚宿营时一起来讲恐怖故事吧。"
  },
  [130020020] = {
    id = 130020020,
    name = "好欸！那我先想一些，绝对不要输给你们！"
  },
  [130020021] = {
    id = 130020021,
    name = "你们俩是不是太放松了？我们还在执行委托。"
  },
  [130020022] = {
    id = 130020022,
    name = "放心，休息的时候稍微放松一点也没关系，不会耽误委托。"
  },
  [130020023] = {
    id = 130020023,
    name = "咱们快去宿营地吧，我已经迫不及待了！"
  },
  [130030001] = {
    id = 130030001,
    name = "没想到这些魔物竟然会趁我们休息时偷袭，真是狡诈。"
  },
  [130030002] = {
    id = 130030002,
    name = "没什么大不了的啦，反正已经全部解决掉了，咱们也没什么事，趁现在再休息一会儿吧，天亮了还得接着赶路呢。"
  },
  [130030003] = {
    id = 130030003,
    name = "你们先休息吧，我去附近巡视一下。"
  },
  [130030004] = {
    id = 130030004,
    name = "月蚀、星云，你们快过来。"
  },
  [130030005] = {
    id = 130030005,
    name = "怎么了辉夜？"
  },
  [130030006] = {
    id = 130030006,
    name = "有一个包裹在刚才的混战中被魔物给毁掉了。"
  },
  [130030007] = {
    id = 130030007,
    name = "啊！可恶的魔物，明明有好几个包裹，为什么偏偏毁掉了装食物这个！"
  },
  [130030008] = {
    id = 130030008,
    name = "应该庆幸它们毁掉的只是食物吧？"
  },
  [130030009] = {
    id = 130030009,
    name = "可是距离下一个补给点还有很远的距离，难道这段时间只能吃野果，喝溪水了吗......"
  },
  [130030010] = {
    id = 130030010,
    name = "抱歉，是我没能守护好物资。"
  },
  [130030011] = {
    id = 130030011,
    name = "这可不关你的事，如果不是你及时反应，这会儿被毁掉的就不只是食物了，甚至连我们也可能陷入危险。"
  },
  [130030012] = {
    id = 130030012,
    name = "在到达下一个补给点前，就由我来负责搜寻猎物，为大家准备食物吧。"
  },
  [130030013] = {id = 130030013, name = "嗯？"},
  [130030014] = {
    id = 130030014,
    name = "不不不！辉夜，你千万别这么自责，我和月蚀也有责任。"
  },
  [130030015] = {
    id = 130030015,
    name = "对对，辉夜你千万别太苛责自己了。"
  },
  [130030016] = {
    id = 130030016,
    name = "你要是真过意不去，就负责抓捕猎物好了，至于食物，就交给我和月蚀吧。"
  },
  [130030017] = {
    id = 130030017,
    name = "嗯，毕竟我们现在是一个团队，不管有什么问题，大家都应该一起面对。"
  },
  [130030018] = {
    id = 130030018,
    name = "你们......谢谢。"
  },
  [130030019] = {
    id = 130030019,
    name = "能与你们这样温柔的同伴一起行动，我也要努力才行。"
  },
  [130030020] = {
    id = 130030020,
    name = "那么我现在就先去抓些猎物，作为我们的早餐。"
  },
  [130030021] = {
    id = 130030021,
    name = "辉夜，你小心啊。"
  },
  [130030022] = {
    id = 130030022,
    name = "呼，还好她这次没较真，不然要是真让她制作食物......"
  },
  [130030023] = {id = 130030023, name = "同感。"},
  [130040001] = {
    id = 130040001,
    name = "这个宝箱真的不打开看看吗？"
  },
  [130040002] = {
    id = 130040002,
    name = "绝不能打开，这荒郊野岭怎么可能存在如此精致的宝箱？"
  },
  [130040003] = {
    id = 130040003,
    name = "而且像是生怕别人注意不到，还特意将周围的杂草除掉了，怎么看都是陷阱。"
  },
  [130040004] = {
    id = 130040004,
    name = "这个宝箱做工精致，想必是有主之物。"
  },
  [130040005] = {
    id = 130040005,
    name = "这条路上不时有游商往来，或许是某位商人暂放在此的物资，我们不能擅自打开。"
  },
  [130040006] = {
    id = 130040006,
    name = "依我看，我们就在这歇息一下吧，避免魔物破坏这个宝箱，也顺便等一下它的主人。"
  },
  [130040007] = {id = 130040007, name = "......"},
  [130040008] = {
    id = 130040008,
    name = "不不不，比起这个宝箱有主人，我更愿意相信月蚀所说的陷阱。"
  },
  [130040009] = {
    id = 130040009,
    name = "呵呵，二比一，那么这个宝箱就是陷阱了，星云也放弃打开的想法吧。"
  },
  [130040010] = {
    id = 130040010,
    name = "我们赶了不少路，就在这稍微歇息一下再出发。"
  },
  [130040011] = {
    id = 130040011,
    name = "可我总觉得里面装着好东西，要是错过了，肯定会后悔。"
  },
  [130040012] = {
    id = 130040012,
    name = "而且就算是陷阱，也总会给些饵料吧？"
  },
  [130040013] = {
    id = 130040013,
    name = "饵料是用来吸引猎物的，你不是已经被吸引了吗？"
  },
  [130040014] = {
    id = 130040014,
    name = "好不甘心。"
  },
  [130040015] = {
    id = 130040015,
    name = "那边过来了几位游商，我去打听一下。"
  },
  [130040016] = {
    id = 130040016,
    name = "辉夜你不一起去吗，说不定就是这个宝箱的主人来了！"
  },
  [130040017] = {
    id = 130040017,
    name = "你放弃吧，不能确定是无主之物前，我不会让你擅自打开。"
  },
  [130040018] = {
    id = 130040018,
    name = "啊，小气！"
  },
  [130040019] = {
    id = 130040019,
    name = "和两个木头一起行动，真是无聊。"
  },
  [130040020] = {
    id = 130040020,
    name = "打听到了，刚刚的游商说这个箱子是他们同行放在这里的陷阱。"
  },
  [130040021] = {
    id = 130040021,
    name = "据说是货物被盗了，但又找不到偷盗之人，于是便在这布置了陷阱，想要报复小偷。"
  },
  [130040022] = {
    id = 130040022,
    name = "这哪里是报复小偷，分明是在诱捕热心善良的人。"
  },
  [130040023] = {
    id = 130040023,
    name = "总之事实就是这样，我们也休息得差不多了，继续赶路吧。"
  },
  [130050001] = {
    id = 130050001,
    name = "没想到竟然真的存在温泉，月蚀果然值得信赖。"
  },
  [130050002] = {
    id = 130050002,
    name = "呵呵，我也只是根据地图上所标注的信息推测出来的。"
  },
  [130050003] = {
    id = 130050003,
    name = "这种天然温泉据说拥有非常强大的功效，像我们这种赶路的行人，只需稍微泡一下便能舒缓身体。"
  },
  [130050004] = {
    id = 130050004,
    name = "辉夜你很喜欢温泉吗？"
  },
  [130050005] = {
    id = 130050005,
    name = "算是吧，以前曾有幸泡过几次，每一次都让我拥有不一样的体验。"
  },
  [130050006] = {
    id = 130050006,
    name = "那我们就在这临时休整一下，泡一泡温泉吧。"
  },
  [130050007] = {
    id = 130050007,
    name = "那个，你们先泡，我在周边巡视一下，避免魔物偷袭。"
  },
  [130050008] = {
    id = 130050008,
    name = "嗯，我们过来时不是在辉夜的提议下优先清剿了周围的魔物吗？这会儿应该不会有问题。"
  },
  [130050009] = {
    id = 130050009,
    name = "魔物很狡诈嘛，说不定有一些刚刚躲了起来，就想趁我们放松偷袭。"
  },
  [130050010] = {
    id = 130050010,
    name = "没想到你也会怀疑自己的探查能力啊~"
  },
  [130050011] = {
    id = 130050011,
    name = "我的探查能力当然非常优秀！我、我只是考虑到万一有漏网之鱼，岂不是会很危险。"
  },
  [130050012] = {id = 130050012, name = "是吗？"},
  [130050013] = {id = 130050013, name = "是的！"},
  [130050014] = {
    id = 130050014,
    name = "难道星云小姐还没在野外泡过温泉？或者说，星云小姐从没泡过？"
  },
  [130050015] = {id = 130050015, name = "......"},
  [130050016] = {
    id = 130050016,
    name = "我只是开玩笑，竟然是真的吗？"
  },
  [130050017] = {
    id = 130050017,
    name = "没泡过也没什么特别的吧？"
  },
  [130050018] = {
    id = 130050018,
    name = "抱歉星云，我本以为你只是放不开而已。"
  },
  [130050019] = {
    id = 130050019,
    name = "这里没洗浴用品，也没有遮挡，确实有点......"
  },
  [130050020] = {
    id = 130050020,
    name = "而且大家经常说温泉多么好，多么舒适，我一直觉得应该和家里的浴池差不多......"
  },
  [130050021] = {
    id = 130050021,
    name = "没关系的，我第一次也不习惯这种硫磺味，但很快就接受了，而且泡起来和浴池完全不同，对吧辉夜。"
  },
  [130050022] = {id = 130050022, name = "辉夜？"},
  [130050023] = {
    id = 130050023,
    name = "你竟然就已经泡上了，之前的紧张感呢......"
  },
  [130050024] = {
    id = 130050024,
    name = "星云，这水温真的非常舒适，一起来试试吧。"
  },
  [130060001] = {
    id = 130060001,
    name = "这些魔物已经不只是棘手了，不全力以赴根本无法应对。"
  },
  [130060002] = {
    id = 130060002,
    name = "你此前不是还打算独自执行委托吗？"
  },
  [130060003] = {
    id = 130060003,
    name = "独自执行自然有独自执行的方法啦，比如尽量躲着走，遇到强大的家伙也以逃跑为主。"
  },
  [130060004] = {
    id = 130060004,
    name = "我们此行的目的虽然只是运送指定物件，但在有余力的情况下，我认为可以顺便解决沿途的魔物。"
  },
  [130060005] = {
    id = 130060005,
    name = "这些魔物太过凶戾，如果不及时处理，很可能给往来行人带来灾祸。"
  },
  [130060006] = {
    id = 130060006,
    name = "当然，我们既然是小队行动，我也觉得彻底解决这些可恶的家伙是正确的选择！"
  },
  [130060007] = {
    id = 130060007,
    name = "不过如果组织能再多安排些人就好了，哪怕只是再多安排一人，我们也可以轻松不少。"
  },
  [130060008] = {
    id = 130060008,
    name = "与其指望组织能多安排人手，你还不如许愿魔物能安分一些。"
  },
  [130060009] = {
    id = 130060009,
    name = "组织中但凡酬金相对丰厚一点的委托，就没有哪个是能轻松完成的。"
  },
  [130060010] = {
    id = 130060010,
    name = "我们一起抗议「深渊航线」欺压成员吧，辉夜，就由你来领头！"
  },
  [130060011] = {id = 130060011, name = "......"},
  [130060012] = {
    id = 130060012,
    name = "以辉夜的名望，想必能策应组织中的大部分成员吧？"
  },
  [130060013] = {
    id = 130060013,
    name = "没错，到时候辉夜大头目就将「深渊航线」的财政交给我来负责吧！"
  },
  [130060014] = {
    id = 130060014,
    name = "那么采访一下未来的财政干部星云小姐，您接手后准备怎样来改善成员们的待遇呢？"
  },
  [130060015] = {
    id = 130060015,
    name = "咳咳咳，最优先的嘛，当然是让所有人的酬金翻倍！"
  },
  [130060016] = {
    id = 130060016,
    name = "那对于我这样最先响应的成员，会有特别优待吗？"
  },
  [130060017] = {
    id = 130060017,
    name = "当然！咱们毕竟是共患难的同伴，美丽的月蚀小姐不管承接什么委托，酬金都加十倍！"
  },
  [130060018] = {
    id = 130060018,
    name = "那我就先感谢星云小姐和辉夜大头目了。"
  },
  [130060019] = {
    id = 130060019,
    name = "你们俩......"
  },
  [130060020] = {
    id = 130060020,
    name = "虽然现在是休息时间，但也别太放松了，越是临近最后关头越不能大意。"
  },
  [130060021] = {
    id = 130060021,
    name = "遵命，辉夜大头目。"
  },
  [130060022] = {
    id = 130060022,
    name = "噗，呵呵呵。"
  },
  [130070001] = {
    id = 130070001,
    name = "这趟委托已经完成，我们稍微休整一下便回去复命。"
  },
  [130070002] = {
    id = 130070002,
    name = "完成了吗，总感觉忽略了些什么......"
  },
  [130070003] = {
    id = 130070003,
    name = "我们确实有将物品亲手交到目标手中，所以这趟委托完成了。"
  },
  [130070004] = {
    id = 130070004,
    name = "这一路经历了不少事，回去后一起庆祝一下？"
  },
  [130070005] = {
    id = 130070005,
    name = "好，那就这么决定了！"
  },
  [130070006] = {
    id = 130070006,
    name = "......别擅自就决定了啊。"
  },
  [130070007] = {
    id = 130070007,
    name = "难道你有什么急事？"
  },
  [130070008] = {
    id = 130070008,
    name = "虽然确实有些想处理的事，但庆祝的时间还是有的。"
  },
  [130070009] = {
    id = 130070009,
    name = "这不就没问题了~大家一起行动这么久，我们已经是同生共死的同伴了，就别见外啦。"
  },
  [130070010] = {
    id = 130070010,
    name = "欸，我突然有个想法，既然我们已经如此默契，要不再一起承接些更有挑战的委托？"
  },
  [130070011] = {
    id = 130070011,
    name = "我记得组织中有几个高额悬赏的委托至今无人认领。"
  },
  [130070012] = {
    id = 130070012,
    name = "我可不想去挑战那些恐怖的存在。"
  },
  [130070013] = {
    id = 130070013,
    name = "我也并无兴趣。"
  },
  [130070014] = {
    id = 130070014,
    name = "你们也拒绝得太果断了......"
  },
  [130070015] = {
    id = 130070015,
    name = "我们不都是想要帮助更多人，践行自己的正义吗？如果有钱的话，实现起来会轻松很多吧？"
  },
  [130070016] = {
    id = 130070016,
    name = "财物只是生活的必要，并非我为之行动的理由。"
  },
  [130070017] = {
    id = 130070017,
    name = "如果想依靠钱财实现自己的正义，或许我回家继承父母的事业会更有效率。"
  },
  [130070018] = {
    id = 130070018,
    name = "而且他们也很希望我能作出那样的选择吧。"
  },
  [130070019] = {
    id = 130070019,
    name = "说起来你父母前段时间出版了新作品，里面有称赞你哦。"
  },
  [130070020] = {id = 130070020, name = "是吗？"},
  [130070021] = {
    id = 130070021,
    name = "嗯，下次有机会介绍我们认识一下吧，说不定我和他们会有很多共同话题，辉夜也一起！"
  },
  [130070022] = {
    id = 130070022,
    name = "我也要去吗？"
  },
  [130070023] = {
    id = 130070023,
    name = "当然，我们是同伴嘛。"
  },
  [130070024] = {
    id = 130070024,
    name = "又擅自决定了......"
  },
  [130080001] = {
    id = 130080001,
    name = "我虽然曾设想过无数种可能，但目标人物死去这种情况，完全在预料之外。"
  },
  [130080002] = {
    id = 130080002,
    name = "唉，我也从没想过会有这样的事。辉夜处理过的委托最多，有遇到过类似的吗？"
  },
  [130080003] = {
    id = 130080003,
    name = "我也几乎没遇到过，不过在这深渊中，出现任何情况都不奇怪。"
  },
  [130080004] = {
    id = 130080004,
    name = "话虽如此，但这种结果比起因魔物导致委托失败，或者运送物品丢失之类的情况更让人难受。"
  },
  [130080005] = {
    id = 130080005,
    name = "感觉心里空落落的，好像失去了执行委托的意义。"
  },
  [130080006] = {
    id = 130080006,
    name = "这可不像你，不过我也有类似的感觉。"
  },
  [130080007] = {
    id = 130080007,
    name = "现在不是消沉的时候，无论结果如何，我们都需要回去复命。"
  },
  [130080008] = {
    id = 130080008,
    name = "而且执行的委托多了，就会发现比这种结果更复杂、更令人沮丧的委托还有很多。"
  },
  [130080009] = {
    id = 130080009,
    name = "我们能做的，只有变得更强，让自己能更有效率地执行委托，赶在结果出现变化前解决一切。"
  },
  [130080010] = {
    id = 130080010,
    name = "这算是“前辈”的忠告吗？"
  },
  [130080011] = {
    id = 130080011,
    name = "不，我并没有说教的意思——"
  },
  [130080012] = {
    id = 130080012,
    name = "好啦，辉夜“前辈”，我们明白你的意思，不用解释哦。"
  },
  [130080013] = {
    id = 130080013,
    name = "确实如辉夜“前辈”所说，我们现在能做的，是努力将下一个委托做得更好！"
  },
  [130080014] = {id = 130080014, name = "......"},
  [130080015] = {
    id = 130080015,
    name = "好了星云，别逗辉夜了，她的脸都已经红了。"
  },
  [130080016] = {
    id = 130080016,
    name = "欸，明明是你先说的，真是狡猾啊，月蚀“前辈”。"
  },
  [130080017] = {id = 130080017, name = "......"},
  [130080018] = {
    id = 130080018,
    name = "我记得某人好奇这次护送的物品来着，如果组织不小心得知某人又出现“窥探客人隐私”的意图，会不会责罚呢？"
  },
  [130080019] = {
    id = 130080019,
    name = "月蚀，你你你！你也没少说组织吝啬！"
  },
  [130080020] = {
    id = 130080020,
    name = "可是「深渊航线」的条例中，并不存在“不能抱怨组织”之类的规定。"
  },
  [130080021] = {
    id = 130080021,
    name = "辉夜，你得帮我作证啊，买了那么多伴手礼，我真没钱交罚金了......"
  },
  [130080022] = {
    id = 130080022,
    name = "噗——咳咳，休整结束，该回去了。"
  },
  [130090001] = {
    id = 130090001,
    name = "这一片都找遍了，完全没有任何发现。"
  },
  [130090002] = {
    id = 130090002,
    name = "我这边也是，没发现目标人物踪迹。"
  },
  [130090003] = {
    id = 130090003,
    name = "那么基于现状，此次委托暂时判定为失败，我们回去复命吧。"
  },
  [130090004] = {
    id = 130090004,
    name = "失败......"
  },
  [130090005] = {
    id = 130090005,
    name = "辉夜，我们再找找吧，或许、或许是我们哪里疏漏了，不，肯定是我们哪里疏漏了。"
  },
  [130090006] = {
    id = 130090006,
    name = "嗯，我们再更加仔细地搜索一下，哪怕能找到一些线索都行。"
  },
  [130090007] = {
    id = 130090007,
    name = "已经搜索了好几次，无论再怎么寻找，也不会有结果。"
  },
  [130090008] = {
    id = 130090008,
    name = "可是都已经来到了目的地，就这样放弃，根本无法说服自己。"
  },
  [130090009] = {
    id = 130090009,
    name = "月蚀，你也曾处理过类似的委托吧？"
  },
  [130090010] = {
    id = 130090010,
    name = "对，所以我一想到复命后那些委托人失望的表情，就无法允许自己放弃。"
  },
  [130090011] = {
    id = 130090011,
    name = "我也一样，每次我都无法直视委托人失望的双眼，甚至有时候会觉得自己什么也守护不了。"
  },
  [130090012] = {
    id = 130090012,
    name = "但这并非我们滞留与此的理由，否则就真的什么做不到了。"
  },
  [130090013] = {id = 130090013, name = "......"},
  [130090014] = {
    id = 130090014,
    name = "好不甘心。"
  },
  [130090015] = {
    id = 130090015,
    name = "不过目标人物失踪，也并非代表他遇到了危险，说不定是遇上好事了呢，所以已不需要我们护送的物品。"
  },
  [130090016] = {
    id = 130090016,
    name = "毕竟这里是深渊，一切皆有可能。"
  },
  [130090017] = {
    id = 130090017,
    name = "你就是这样安慰自己的吗？"
  },
  [130090018] = {
    id = 130090018,
    name = "这也并非单纯的安慰，我只是阐述了一种可能。"
  },
  [130090019] = {
    id = 130090019,
    name = "如果按你所说，那我们护送的物品是可以解决危险的？"
  },
  [130090020] = {
    id = 130090020,
    name = "辉夜，你是不是也涉嫌“窥探客户隐私”了？"
  },
  [130090021] = {
    id = 130090021,
    name = "我、我只是说可能。"
  },
  [130090022] = {
    id = 130090022,
    name = "放心，我不会揭发你的，今后组织要再罚我钱，你记得帮我说好话呀。"
  },
  [130090023] = {id = 130090023, name = "......"},
  [130090024] = {
    id = 130090024,
    name = "我们放弃吧星云，就像辉夜所说，或许委托人已经去享受新的生活了。"
  },
  [130090025] = {
    id = 130090025,
    name = "嗯，一起回去吧。"
  },
  [130100001] = {
    id = 130100001,
    name = "没想到这次委托背后，竟然还存在着不为人知的故事。"
  },
  [130100002] = {
    id = 130100002,
    name = "是啊，又完成一个有意义的委托。你在写什么呢月蚀，难道想将这次经历写成故事发表？"
  },
  [130100003] = {
    id = 130100003,
    name = "只是日记而已，每次完成有特殊意义的委托，我都会记录下来。"
  },
  [130100004] = {
    id = 130100004,
    name = "没想到你还有这种习惯，不过这次委托背后的故事着实令人感慨，写成故事的话一定会很受欢迎。"
  },
  [130100005] = {
    id = 130100005,
    name = "要不你试试？我和辉夜实名加入，增加故事可信度，到时候故事热销，分我们一些出场费就行。"
  },
  [130100006] = {
    id = 130100006,
    name = "只要是事实，我并不介意自己的名字出现在任何地方。"
  },
  [130100007] = {
    id = 130100007,
    name = "辉夜，你这就太外行了，你知道对现在的探险者来说最重要的是什么吗？"
  },
  [130100008] = {
    id = 130100008,
    name = "战斗的理由，守护安宁的意志，追寻未知的决心。"
  },
  [130100009] = {
    id = 130100009,
    name = "你......说的也没错。"
  },
  [130100010] = {
    id = 130100010,
    name = "不过对有名气的探险者来说，姓名权、肖像权、名誉权都是重要的资产，绝不能随便处置。"
  },
  [130100011] = {
    id = 130100011,
    name = "我并不觉得自己能与那些传奇探险者相提并论。"
  },
  [130100012] = {
    id = 130100012,
    name = "而且比起你说的那些，能顺利完成委托，帮助到困扰的人，我会觉得更加满足。"
  },
  [130100013] = {
    id = 130100013,
    name = "不错，每一个不起眼的委托背后或许都有着曲折的故事，我们的举手之劳，也可能成为他人的救赎。"
  },
  [130100014] = {
    id = 130100014,
    name = "这并不冲突吧？"
  },
  [130100015] = {
    id = 130100015,
    name = "你要是真感兴趣就自己去写吧，至于出场费，就当我赞助你了。"
  },
  [130100016] = {
    id = 130100016,
    name = "你们俩还真是慷慨，就不怕我胡乱捏造吗？"
  },
  [130100017] = {
    id = 130100017,
    name = "比如什么辉夜推荐的药物，购买商品抽取月蚀的见面会门票之类的，一定能吸引不少人！"
  },
  [130100018] = {
    id = 130100018,
    name = "如果你那样做我会很困扰。"
  },
  [130100019] = {
    id = 130100019,
    name = "你如果想和我的剑亲近一番，就尽管去做。"
  },
  [130100020] = {
    id = 130100020,
    name = "你、你那是什么眼神，开玩笑嘛！"
  },
  [130100021] = {
    id = 130100021,
    name = "我只是觉得这次经历着实令人印象深刻，如果能分享给更多人就好了。"
  },
  [130100022] = {
    id = 130100022,
    name = "决定了，今后我也要多接一些委托，将类似的经历全部记录下来，让更多人了解深渊，了解这个世界中存在的美好和希望。"
  },
  [130110001] = {
    id = 130110001,
    name = "大丰收！这下所有人的伴手礼都足够了！"
  },
  [130110002] = {
    id = 130110002,
    name = "等等，伴手礼？这些东西你不是买回去自己收藏吗？"
  },
  [130110003] = {
    id = 130110003,
    name = "有少数几件我确实会用来收藏啦，但这么多全用来收藏——我看起来像是会做那种事的人吗？"
  },
  [130110004] = {id = 130110004, name = "像。"},
  [130110005] = {
    id = 130110005,
    name = "你刚刚购物时好几次问我们有没有喜欢的，难道是想准备我们的礼物？"
  },
  [130110006] = {
    id = 130110006,
    name = "对啊，正好你们俩也在，能自己挑选的话我就可以不用考虑该给你们准备什么了。"
  },
  [130110007] = {
    id = 130110007,
    name = "我还以为你只是单纯地想让我们帮你参考一下。"
  },
  [130110008] = {
    id = 130110008,
    name = "话说你买这么多礼物花费了不少吧？万一再被组织处罚，还有钱交罚金吗？"
  },
  [130110009] = {
    id = 130110009,
    name = "哼哼，这你就不懂了吧，我刚刚在这可赚了不少，除去购买礼物的钱，甚至还有盈余。"
  },
  [130110010] = {
    id = 130110010,
    name = "什么？！难道你去变卖了什么贵重物品？"
  },
  [130110011] = {
    id = 130110011,
    name = "怎么可能！我是去卖消息啦。"
  },
  [130110012] = {id = 130110012, name = "消息？"},
  [130110013] = {
    id = 130110013,
    name = "对！想要赚钱不一定需要货物，只靠头脑也能做到。"
  },
  [130110014] = {
    id = 130110014,
    name = "比如我们此前经过的据点因为魔物活动，普通物资和素材价格都比这边贵上不少。"
  },
  [130110015] = {
    id = 130110015,
    name = "而我们来的途中解决了不少魔物，道路已经通畅，所以我就将这个消息卖给这边的商人。"
  },
  [130110016] = {
    id = 130110016,
    name = "虽然再过不久他们也能发现，但如果能抢占先机，这些商人很乐意付出一点酬劳的。"
  },
  [130110017] = {
    id = 130110017,
    name = "原来如此......既然星云如此慷慨，要不我们再回去看看？"
  },
  [130110018] = {
    id = 130110018,
    name = "月蚀，我们本就是与星云一起出来的，还从她这里收取伴手礼，有失礼仪了。"
  },
  [130110019] = {
    id = 130110019,
    name = "星云都特意为大家准备了，我们如果不收才有愧她的好意，而且你刚才不是很中意一把匕首吗，不是正好——"
  },
  [130110020] = {
    id = 130110020,
    name = "算不上中意，只是稍微觉得有点特别而已。"
  },
  [130110021] = {
    id = 130110021,
    name = "特别也行，等星云送给你后慢慢把玩，我们就再去看看吧。"
  },
  [130110022] = {
    id = 130110022,
    name = "已经晚了。"
  },
  [130110023] = {
    id = 130110023,
    name = "嗯，什么意思？"
  },
  [130110024] = {
    id = 130110024,
    name = "刚才你们都不说话，我已经准备好了。"
  },
  [130110025] = {
    id = 130110025,
    name = "至于是什么，回去后再揭晓答案！"
  },
  [130120001] = {
    id = 130120001,
    name = "哇哦，是浮光的信！哎呀呀，她还是一如既往地认真呢。"
  },
  [130120002] = {
    id = 130120002,
    name = "她的任务已经完成了，真羡慕啊......哎，同样作为穷人家的孩子，一起努力吧！"
  },
  [130120003] = {id = 130120003, name = "......"},
  [130120004] = {
    id = 130120004,
    name = "话说回来，她在信中提到的情报很让人在意。"
  },
  [130120005] = {
    id = 130120005,
    name = "啊，你说火山地动的事，那个会有什么影响？"
  },
  [130120006] = {
    id = 130120006,
    name = "如果爆发过的火山发生地动，很可能会引起火山的再次爆发，熔岩会将周围的森林、草原，一切生物都化为灰烬。"
  },
  [130120007] = {
    id = 130120007,
    name = "好可怕，月蚀见过吗？"
  },
  [130120008] = {
    id = 130120008,
    name = "没有，我只在书里看到过。据说很多年前诺维奇帝国的北部火山苏醒吞噬了森林和房舍，至今那里仍然是一片无人区，成了罪大恶极的犯人才会被流放的死亡之地。"
  },
  [130120009] = {
    id = 130120009,
    name = "月蚀真是见多识广。那照这么说，咱们这一趟任务岂不是很危险？"
  },
  [130120010] = {
    id = 130120010,
    name = "嗯，只能更加小心行事了。"
  },
  [130120011] = {
    id = 130120011,
    name = "辉夜回答得很坚决啊，一点也没有放弃的样子。"
  },
  [130120012] = {
    id = 130120012,
    name = "难道你想放弃？"
  },
  [130120013] = {
    id = 130120013,
    name = "当然不会，我是那么容易放弃的人吗？这次任务委托人给得可是很多的。"
  },
  [130130001] = {
    id = 130130001,
    name = "哈哈哈哈哈！"
  },
  [130130002] = {
    id = 130130002,
    name = "在笑什么那么开心？咦，这是什么？长眼睛的萝卜？"
  },
  [130130003] = {
    id = 130130003,
    name = "哈哈哈，是浮光的画像，哦不对，浮光画的人像。"
  },
  [130130004] = {
    id = 130130004,
    name = "噗......呵呵。"
  },
  [130130005] = {
    id = 130130005,
    name = "哇哦，好难得看到月蚀笑了。"
  },
  [130130006] = {
    id = 130130006,
    name = "......浮光的画......很生动。"
  },
  [130130007] = {
    id = 130130007,
    name = "真有长得像萝卜的人吗？"
  },
  [130130008] = {
    id = 130130008,
    name = "也许吧。"
  },
  [130130009] = {
    id = 130130009,
    name = "唔......如果是长成这样，在哪里都很引人注目吧。"
  },
  [130130010] = {
    id = 130130010,
    name = "没错，可是我们没有在附近见过这人。"
  },
  [130130011] = {
    id = 130130011,
    name = "也没有听过有人谈论这个人。"
  },
  [130130012] = {
    id = 130130012,
    name = "或许他不是往这边逃走呢，因为火山的传言，已经很少人过来了。"
  },
  [130130013] = {
    id = 130130013,
    name = "是哦，而且他还带着一堆东西，是没必要逃到这边的，除非他想销赃。"
  },
  [130130014] = {
    id = 130130014,
    name = "销赃。你说得没错，星云。"
  },
  [130130015] = {id = 130130015, name = "啊？"},
  [130130016] = {
    id = 130130016,
    name = "他不能把偷来的东西在附近卖掉，只能去很远的地方，也许我们真的能碰上这个人。"
  },
  [130130017] = {
    id = 130130017,
    name = "好啊，那咱们把眼睛放亮点，决不能让这种小贼逃走了！"
  },
  [130140001] = {
    id = 130140001,
    name = "星云，浮光的信到了。"
  },
  [130140002] = {
    id = 130140002,
    name = "真的？！她说了什么？"
  },
  [130140003] = {
    id = 130140003,
    name = "她提到了我们两个。"
  },
  [130140004] = {
    id = 130140004,
    name = "啊......我猜不会说什么称赞的话啦，让我看看......果然！"
  },
  [130140005] = {
    id = 130140005,
    name = "她说得不错。"
  },
  [130140006] = {
    id = 130140006,
    name = "星云贪功冒进，辉夜循规蹈矩，浮光说得真是毫不留情。"
  },
  [130140007] = {
    id = 130140007,
    name = "月蚀，为什么你没有缺点啊。"
  },
  [130140008] = {
    id = 130140008,
    name = "呵呵，我的平庸就是最大的缺点了。"
  },
  [130140009] = {
    id = 130140009,
    name = "不要妄自菲薄啦，你做的每一件事都很完美啦。"
  },
  [130140010] = {
    id = 130140010,
    name = "......也许太过于追求完美就是我的缺点吧。"
  },
  [130140011] = {
    id = 130140011,
    name = "不管怎样，月蚀，在我固执的地方，你一定要提醒我。"
  },
  [130140012] = {
    id = 130140012,
    name = "还有我，要是有什么打乱计划的想法，也一定要阻止我啊。"
  },
  [130140013] = {
    id = 130140013,
    name = "嗯，我也有做得不好的地方，我们一起互相监督吧。"
  },
  [130140014] = {id = 130140014, name = "嗯。"},
  [130140015] = {id = 130140015, name = "好！"},
  [130150001] = {
    id = 130150001,
    name = "没想到在这里也能见到促销单，看起来的确很吸引人。"
  },
  [130150002] = {
    id = 130150002,
    name = "哼，竟然用这种卑鄙的促销方式与我家竞争！"
  },
  [130150003] = {
    id = 130150003,
    name = "差点忘了，星云家里的商会和行商们是竞争对手。"
  },
  [130150004] = {
    id = 130150004,
    name = "就是这群人扰乱市场，这下我家该怎么办啊，又要变得更穷了怎么办......"
  },
  [130150005] = {
    id = 130150005,
    name = "......不会的。"
  },
  [130150006] = {
    id = 130150006,
    name = "每次出现这种事，家里长辈们都忙得焦头烂额，虽然最后大家都没有饿死，但生活真的变得更艰难了啊。"
  },
  [130150007] = {
    id = 130150007,
    name = "......星云对自家的产业似乎还是不太了解啊。"
  },
  [130150008] = {id = 130150008, name = "嗯。"},
  [130150009] = {
    id = 130150009,
    name = "你们在嘀嘀咕咕说什么？"
  },
  [130150010] = {
    id = 130150010,
    name = "在说这份促销单，看起来很诱人，但没有看到实物之前，很难对品质下定义。"
  },
  [130150011] = {
    id = 130150011,
    name = "对哦，我父亲说做生意切记不可以以次充好，我家卖的东西虽然普普通通，但大家用了都觉得不错的。"
  },
  [130150012] = {
    id = 130150012,
    name = "......普......通吗？"
  },
  [130150013] = {
    id = 130150013,
    name = "咦，这背面真画了地图。让我看看，我们已经走到这个位置了吧。"
  },
  [130150014] = {
    id = 130150014,
    name = "离据点还有些距离，今晚得加紧赶路了。"
  },
  [130150015] = {id = 130150015, name = "走吧。"},
  [130150016] = {
    id = 130150016,
    name = "嗯，让我好好看看，那个卡卡玛的新店到底如何。"
  },
  [130160001] = {
    id = 130160001,
    name = "这封信是留给另一支商队的，看来他们已经进入沼泽地了。"
  },
  [130160002] = {
    id = 130160002,
    name = "果然是富贵险中求，这么危险的地方，他们还打算继续往前，难道有什么我们不知道情报？"
  },
  [130160003] = {
    id = 130160003,
    name = "比如说......宝物或者......圣物？"
  },
  [130160004] = {
    id = 130160004,
    name = "他们能成功到达此处，实力已经很强了，这是什么商会？"
  },
  [130160005] = {
    id = 130160005,
    name = "唔，你听过黑市吗？"
  },
  [130160006] = {
    id = 130160006,
    name = "黑市......"
  },
  [130160007] = {
    id = 130160007,
    name = "就是那些见不得人的交易，在黑市里，你可以找到魔法物品，禁忌的卷轴，失窃的宝物......以及公会禁止公开售卖的东西。"
  },
  [130160008] = {
    id = 130160008,
    name = "听起来不是什么好地方。"
  },
  [130160009] = {
    id = 130160009,
    name = "咳咳，确实是这样的，那个地方不受任何约束，但很少有人在黑市捣乱，有传言说是高塔在背后帮他们撑腰。"
  },
  [130160010] = {
    id = 130160010,
    name = "星云，你很熟悉黑市啊。"
  },
  [130160011] = {
    id = 130160011,
    name = "呵呵，偶然一次跟家里人去过，那一次父亲发了很大的火，后来我才知道那地方是黑市。"
  },
  [130160012] = {
    id = 130160012,
    name = "那里的商人都是亡命之徒，他们为了宝物可以做出任何事，也不会顾及自己的安危，这封信的疯劲，让我突然想起了这群人，尤其那个记号，我也只在黑市见到过。"
  },
  [130160013] = {
    id = 130160013,
    name = "......原来如此。"
  },
  [130160014] = {
    id = 130160014,
    name = "辉夜原本是打算提醒他们撤离吗？"
  },
  [130160015] = {
    id = 130160015,
    name = "嗯，毕竟这个地方已经不适合人类长留了。"
  },
  [130160016] = {
    id = 130160016,
    name = "生死有命，他们既然选择了这条路，就随他们去吧，我们还有更重要的任务。"
  },
  [130160017] = {
    id = 130160017,
    name = "嗯，走吧。"
  },
  [130170001] = {
    id = 130170001,
    name = "黑市入口？"
  },
  [130170002] = {
    id = 130170002,
    name = "在哪里？我看看......唔，果然很机灵啊，这种地方绝对不会在信上说明白的。"
  },
  [130170003] = {
    id = 130170003,
    name = "黎明要塞也有这样的黑市？"
  },
  [130170004] = {
    id = 130170004,
    name = "嗯，为了躲避公会的调查，黑市往往是流动的，需要有熟人带进去，毕竟交易的都是见不得人的东西嘛。"
  },
  [130170005] = {
    id = 130170005,
    name = "你上次说黑市的人都是亡命之徒，那他们会交易什么见不得人的东西？"
  },
  [130170006] = {
    id = 130170006,
    name = "啊哈哈，就是我们平常看不见的......我们不说这个了吧。"
  },
  [130170007] = {
    id = 130170007,
    name = "是有什么难言之隐吗？"
  },
  [130170008] = {
    id = 130170008,
    name = "或者是我们难以想象的宝物？道具？药品？"
  },
  [130170009] = {
    id = 130170009,
    name = "唔......我见过......人。"
  },
  [130170010] = {id = 130170010, name = "？？？"},
  [130170011] = {
    id = 130170011,
    name = "就是卖小孩子......把小孩子做成药人，那些血有治愈的效果，传言还能长生......"
  },
  [130170012] = {
    id = 130170012,
    name = "太过分了！"
  },
  [130170013] = {
    id = 130170013,
    name = "别生气，别生气，这件事被公会调查之后，就消停了很长的时间，现在大多是卖没有在商会记录的东西了。"
  },
  [130170014] = {
    id = 130170014,
    name = "这也不好，深渊里的很多东西，没有净化浊炁，很容易被侵蚀，太危险了。"
  },
  [130170015] = {
    id = 130170015,
    name = "这样的黑市就不应该存在。"
  },
  [130170016] = {
    id = 130170016,
    name = "唉，世间的恶事每一刻都在发生，我们也没有能力事事去阻止。"
  },
  [130170017] = {
    id = 130170017,
    name = "我知道，但我没办法习惯不管。"
  },
  [130170018] = {
    id = 130170018,
    name = "等这之后，我们找个时间去调查一下吧。"
  },
  [130170019] = {
    id = 130170019,
    name = "好，打听消息的事交给我。"
  },
  [130180001] = {
    id = 130180001,
    name = "是账本。"
  },
  [130180002] = {
    id = 130180002,
    name = "喔，这个我熟！这谁记的，比咱们的又清楚又详细啊！"
  },
  [130180003] = {
    id = 130180003,
    name = "我们大多自给自足，很少用到组织的东西。"
  },
  [130180004] = {
    id = 130180004,
    name = "嗯，但这个一目了然，完全可以作为探险手册来记啊。"
  },
  [130180005] = {id = 130180005, name = "手册？"},
  [130180006] = {
    id = 130180006,
    name = "比如说，我们今天走了哪些地方，杀了哪些魔物，吃了什么用了什么，都记下来，等到回去之后整理成册，不就是很好的一本探险日记嘛！"
  },
  [130180007] = {
    id = 130180007,
    name = "不错，只靠记忆，的确会忘记许多事，但记下之后又有什么用？"
  },
  [130180008] = {
    id = 130180008,
    name = "这可是深渊航线的宝贵经验啊，如果将这本日记拿出去卖，那咱们组织的经费就再也不用发愁了！"
  },
  [130180009] = {id = 130180009, name = "不行。"},
  [130180010] = {id = 130180010, name = "啊？"},
  [130180011] = {
    id = 130180011,
    name = "我们的路线与经历，都与委托人的任务息息相关，如果将这些告诉别人，和出卖委托人没有区别。"
  },
  [130180012] = {
    id = 130180012,
    name = "噢，知道了。"
  },
  [130180013] = {
    id = 130180013,
    name = "星云，别灰心，其实你如果不想忘记那些回忆，可以自己记下来。"
  },
  [130180014] = {
    id = 130180014,
    name = "我的父母都有写手记的习惯，他们会记录一切值得记下的事，他们也想我这样做，可惜我对这件事不感兴趣。"
  },
  [130180015] = {
    id = 130180015,
    name = "呵呵，不用啦，我也只是说说而已，每天写多累啊......有时候杀完魔物只想躺下，连眼睛都不想睁开。"
  },
  [130190001] = {
    id = 130190001,
    name = "飘友？很新的词汇。"
  },
  [130190002] = {
    id = 130190002,
    name = "这个写信的好有意思，可惜信的残余的魔法力不足，看完就自己销毁了。"
  },
  [130190003] = {
    id = 130190003,
    name = "怎么，你还想给他回一封信？"
  },
  [130190004] = {
    id = 130190004,
    name = "不愧是月蚀，真的很了解我啊，这种人走过很多地方，一定知道哪里有宝藏。"
  },
  [130190005] = {
    id = 130190005,
    name = "恐怕这个人并不想收到你的回信。"
  },
  [130190006] = {
    id = 130190006,
    name = "有来有往才可以叫朋友，这样单方面联系什么也做不到啊。"
  },
  [130190007] = {
    id = 130190007,
    name = "也许对他而言就足够了。"
  },
  [130190008] = {
    id = 130190008,
    name = "害怕陌生人，又想把自己的想法告诉别人，用这样的办法，也算对内心的一种宣泄。如果你回了信，他反而应该更害怕吧。"
  },
  [130190009] = {id = 130190009, name = "......"},
  [130190010] = {
    id = 130190010,
    name = "怎么一脸惋惜的样子？"
  },
  [130190011] = {
    id = 130190011,
    name = "这个人还是挺厉害的，如果我能知道这个魔法，是不是就可以很轻松给其他人写信了？"
  },
  [130190012] = {
    id = 130190012,
    name = "没那么简单。这样的信没有目的地，随风飞扬，不能送到指定的人手里。"
  },
  [130190013] = {
    id = 130190013,
    name = "你想写信吗？如果有紧急的事，可以让信使送去近区的据点。"
  },
  [130190014] = {
    id = 130190014,
    name = "只是说说而已啦，真有急事的话，家里人给了我东西，应该可以及时传达消息的吧。"
  },
  [130190015] = {
    id = 130190015,
    name = "......差点忘了，你身上的东西比这只千纸鹤更不简单。"
  },
  [130200001] = {
    id = 130200001,
    name = "湖泊......这哪儿有湖泊？"
  },
  [130200002] = {
    id = 130200002,
    name = "这些血迹，也许有人遭遇了危机。"
  },
  [130200003] = {
    id = 130200003,
    name = "可能是送消息的人，也可能是......赶来支援的人。"
  },
  [130200004] = {
    id = 130200004,
    name = "等等，看这地图......好像的确指的是这里，这是怎么回事？"
  },
  [130200005] = {
    id = 130200005,
    name = "地图画错了？"
  },
  [130200006] = {
    id = 130200006,
    name = "......应该不会错，可这里，并没有信上所说的禁锢之湖。"
  },
  [130200007] = {
    id = 130200007,
    name = "那就是人错了？"
  },
  [130200008] = {
    id = 130200008,
    name = "人错了？是什么意思？"
  },
  [130200009] = {
    id = 130200009,
    name = "辉夜的意思，是这个叫苏克的人，传了假消息。"
  },
  [130200010] = {
    id = 130200010,
    name = "可为什么要传假消息呢？还让他的队长白跑一趟。"
  },
  [130200011] = {
    id = 130200011,
    name = "如果你是队长，你收到信会这么做？"
  },
  [130200012] = {
    id = 130200012,
    name = "那还用想，肯定带上人去支援啊！"
  },
  [130200013] = {
    id = 130200013,
    name = "辉夜呢？"
  },
  [130200014] = {
    id = 130200014,
    name = "......我，应该会一个人去。"
  },
  [130200015] = {
    id = 130200015,
    name = "嗯。这里没有厮杀的痕迹，只有地图上沾了血，所以我猜想......"
  },
  [130200016] = {
    id = 130200016,
    name = "队长在这里遇到了魔物？他们一起把魔物杀掉，然后这个苏克就带队长去了那个湖泊。嗯，应该是这样吧......"
  },
  [130200017] = {
    id = 130200017,
    name = "这附近没有湖泊，再远的地方，也没有。"
  },
  [130200018] = {
    id = 130200018,
    name = "那就只有一种可能了。"
  },
  [130200019] = {id = 130200019, name = "......"},
  [130200020] = {
    id = 130200020,
    name = "咦？怎么不说话都走了。算了，我也不想了，你们等等我呀！"
  },
  [130210001] = {
    id = 130210001,
    name = "这就是最后一页......前面的，都撕掉了。"
  },
  [130210002] = {
    id = 130210002,
    name = "只为了一个宝物，连多年的情义都可以弃而不顾，也太不是人了吧！"
  },
  [130210003] = {
    id = 130210003,
    name = "不，不会只因为这个，既然是一起战斗，共同患难的伙伴，又怎么会轻易地把刀剑刺向对方呢？假如有一天我们之间有了争执，你会这么做吗？"
  },
  [130210004] = {
    id = 130210004,
    name = "当然不会！我怎么会是这种人！"
  },
  [130210005] = {
    id = 130210005,
    name = "也许一开始，他们也不是这种人。"
  },
  [130210006] = {
    id = 130210006,
    name = "......你是说，在这之前，他们的队伍里就已经出现了矛盾？"
  },
  [130210007] = {
    id = 130210007,
    name = "也许这个宝物，是压垮那份信任最后的稻草。"
  },
  [130210008] = {
    id = 130210008,
    name = "那也用不着动手啊......有什么坐下来慢慢谈不好吗？"
  },
  [130210009] = {
    id = 130210009,
    name = "你们猜，他在那个时候，有没有动手？"
  },
  [130210010] = {
    id = 130210010,
    name = "他应该是躲起来了吧，或者跑掉了？不然怎么会后悔......"
  },
  [130210011] = {
    id = 130210011,
    name = "是啊，他为什么会后悔，那件宝物的下落会在哪里？"
  },
  [130210012] = {
    id = 130210012,
    name = "难道他......"
  },
  [130210013] = {
    id = 130210013,
    name = "不知道，都只是我的猜测。"
  },
  [130210014] = {
    id = 130210014,
    name = "伙伴，是最亲密的战友，也是最容易刺伤对方的一把利刃。因为互相信任了解，一旦有了猜忌，只会万劫不复。"
  },
  [130210015] = {
    id = 130210015,
    name = "伙伴就是伙伴，不应该成为敌人，我永远也不会像他那样，等失去了一切才去后悔。"
  },
  [130210016] = {
    id = 130210016,
    name = "......希望他能在记忆的灰烬中，能找回他想要的光明吧，哪怕只有一瞬。"
  },
  [130220001] = {id = 130220001, name = "噗嗤。"},
  [130220002] = {
    id = 130220002,
    name = "笑什么？"
  },
  [130220003] = {
    id = 130220003,
    name = "原来吟游诗人也要吃饭睡觉打魔物的呀。"
  },
  [130220004] = {id = 130220004, name = "......"},
  [130220005] = {
    id = 130220005,
    name = "我还以为他们只会到处走走，抱着琴唱唱歌，然后找人索要金币。"
  },
  [130220006] = {
    id = 130220006,
    name = "你被索要过金币？"
  },
  [130220007] = {
    id = 130220007,
    name = "对啊，说金币是所谓的......聆听神的指引，传达神谕所需的媒介。"
  },
  [130220008] = {
    id = 130220008,
    name = "你给了吗？"
  },
  [130220009] = {
    id = 130220009,
    name = "给了。他在我家门口坐了一整天，一口饭也没吃，我看他太可怜了，就给了他金币。"
  },
  [130220010] = {
    id = 130220010,
    name = "后来他拿到钱也没着急走，那时我还以为他们这群神秘的人真的有什么力量能让自己不吃饭呢。"
  },
  [130220011] = {id = 130220011, name = "......"},
  [130220012] = {
    id = 130220012,
    name = "不过这家伙也挺有勇气的，要不是他们亲自走到这些地方来，我们在大陆也听不到深渊的许多传说吧。"
  },
  [130220013] = {
    id = 130220013,
    name = "「踏遍深渊之每一个角落，唱遍世间所有已知与未知之事」这就是他的决心。"
  },
  [130220014] = {
    id = 130220014,
    name = "靠旅行写作唱歌来赚钱，真是不容易啊，下一次我再见到诗人的话，就再多给一块金币吧。"
  },
  [130220015] = {
    id = 130220015,
    name = "为什么要多给一块？"
  },
  [130220016] = {
    id = 130220016,
    name = "这样他们就更有动力唱给更多的人，大家不用下深渊也能听到深渊的传奇和见闻啦。"
  },
  [130230001] = {
    id = 130230001,
    name = "啊，看起来真让人心动。"
  },
  [130230002] = {
    id = 130230002,
    name = "是的，如果财迷心窍的人，或许就真的进山洞找人了。"
  },
  [130230003] = {
    id = 130230003,
    name = "......呵呵，你不是在说我吧？"
  },
  [130230004] = {
    id = 130230004,
    name = "不是，你还是有分寸的。"
  },
  [130230005] = {
    id = 130230005,
    name = "当然，我时刻记得，这次有重要任务在身的。"
  },
  [130230006] = {
    id = 130230006,
    name = "嗯，你没心动就好。"
  },
  [130230007] = {
    id = 130230007,
    name = "......嘿嘿，话说回来，这洞穴和宝物的事，等咱们回来路上可以探一探啊。"
  },
  [130230008] = {
    id = 130230008,
    name = "探一探也不是不可以，前提是这封信的情报的准确的。"
  },
  [130230009] = {
    id = 130230009,
    name = "你怀疑事有玄机？"
  },
  [130230010] = {
    id = 130230010,
    name = "说不准，深渊里的情况复杂多变，一个探险者怎么可能单凭一己之力就找到宝物呢？"
  },
  [130230011] = {
    id = 130230011,
    name = "要是他只是想利用我们对抗守护魔物，然后独吞宝藏。那咱们就亏死了！"
  },
  [130230012] = {
    id = 130230012,
    name = "呵呵，不管真假，等我们任务结束之后，都可以来探一探。"
  },
  [130230013] = {
    id = 130230013,
    name = "没错，咱们几个在一起，再强的魔物也不是对手！"
  },
  [130230014] = {
    id = 130230014,
    name = "这样一来，既能完成任务，又能得到宝......历练，岂不是一举两得？"
  },
  [130230015] = {
    id = 130230015,
    name = "嗯，如果是额外挑战的话，我同意。"
  },
  [130230016] = {
    id = 130230016,
    name = "我也同意。"
  },
  [130230017] = {
    id = 130230017,
    name = "好耶，全票赞成，就这么说定了。"
  },
  [130240001] = {
    id = 130240001,
    name = "藏宝图，真的是藏宝图！"
  },
  [130240002] = {
    id = 130240002,
    name = "嗯，意外收获呢。"
  },
  [130240003] = {
    id = 130240003,
    name = "让我看看，宝藏在哪儿......啊，这个地方，好像在火山深处的位置。"
  },
  [130240004] = {
    id = 130240004,
    name = "那里......似乎与我们的目的地背道而驰吧？"
  },
  [130240005] = {
    id = 130240005,
    name = "是吗，如果从这边绕过去的话——"
  },
  [130240006] = {
    id = 130240006,
    name = "不行，太远了。"
  },
  [130240007] = {
    id = 130240007,
    name = "唉，我就是推测一下路线，果然还是不行啊。"
  },
  [130240008] = {
    id = 130240008,
    name = "这张藏宝图，他竟然就这样轻而易举地放弃了。"
  },
  [130240009] = {
    id = 130240009,
    name = "对啊，就算自己拿不到宝藏，卖给其他人也有赚啊。"
  },
  [130240010] = {
    id = 130240010,
    name = "也许他有其他的目的。"
  },
  [130240011] = {
    id = 130240011,
    name = "卖给其他人，就不会知道宝藏的样子和去处了。"
  },
  [130240012] = {
    id = 130240012,
    name = "没错，他还没找到宝藏，就想将这个机遇和这份希望寄予他人，由他人来达成他的心愿。"
  },
  [130240013] = {
    id = 130240013,
    name = "嗯，如果是我，我也会不甘心的，但伙伴的生命更重要。这样将藏宝图留下，也是求一个心理安慰吧。也许真的会遇到我这样的好人，找到宝藏会和他分享喜悦呢。"
  },
  [130240014] = {
    id = 130240014,
    name = "我们去不了。"
  },
  [130240015] = {
    id = 130240015,
    name = "我只是说说而已。"
  },
  [130250001] = {
    id = 130250001,
    name = "这这这，有宝藏欸！！"
  },
  [130250002] = {
    id = 130250002,
    name = "伽丝茉......是公会情报部部长吧？这封信竟然是公会的秘密，让咱们知道了，会不会不太好啊？"
  },
  [130250003] = {
    id = 130250003,
    name = "这公会的秘密......怎么跑进魔物肚子里去了？难道送信的人被吃了？"
  },
  [130250004] = {
    id = 130250004,
    name = "不一定，公会有许多传递情报的方式。比如利用飞鸟、魔偶、魔法阵、信号标记，总之不一定是人。"
  },
  [130250005] = {
    id = 130250005,
    name = "不用人传递情报，那中途被别人......或者这家伙截获了，那该怎么办？"
  },
  [130250006] = {
    id = 130250006,
    name = "也许他们有他们的规则吧，这个就不是我们考虑的事了。说起来，我们要把这个消息传回给公会吗？"
  },
  [130250007] = {
    id = 130250007,
    name = "我觉得可以先给公会传一封消息，告诉他们咱们拿到了一封情报。"
  },
  [130250008] = {
    id = 130250008,
    name = "然后呢？"
  },
  [130250009] = {
    id = 130250009,
    name = "然后就等他们开价啊，情报可是有市无价，这么好的赚钱机会，怎么能放过。"
  },
  [130250010] = {
    id = 130250010,
    name = "可这本就是公会的东西......你想待价而沽？"
  },
  [130250011] = {
    id = 130250011,
    name = "如果不是公会的情报，我还想送到组织里，给组织填补点家用呢。要不是咱们，他们是永远没机会知道这个消息了。月蚀，你说呢？"
  },
  [130250012] = {
    id = 130250012,
    name = "我快被你说服了，你让我想想，让我想想......"
  },
  [130250013] = {
    id = 130250013,
    name = "不用想了，看看这上面写的，刻不容缓！这魔物应该刚吃了它没多久就被我们干掉了，现在送信，一来一回，可要耽搁不少时间呢。"
  },
  [130250014] = {
    id = 130250014,
    name = "就不能直接送到公会手里吗？"
  },
  [130250015] = {
    id = 130250015,
    name = "我不是为了稳妥一点嘛，万一收到的......不是公会的人呢？当面交易更妥当。"
  },
  [130250016] = {id = 130250016, name = "交易？"},
  [130250017] = {
    id = 130250017,
    name = "啊哈哈，交不交易到时候再说吧，总之先把人叫来。"
  },
  [130250018] = {
    id = 130250018,
    name = "嗯，这个我同意。"
  },
  [130250019] = {
    id = 130250019,
    name = "好吧，我还是认为既然是别人的，就应该还给别人，而不是作为筹码。"
  },
  [130250020] = {
    id = 130250020,
    name = "知道啦。"
  },
  [130260001] = {
    id = 130260001,
    name = "是传讯用的魔法石，很少见......竟然会在这里。"
  },
  [130260002] = {
    id = 130260002,
    name = "好东西啊，虽然刻的文字是固定的，但输入一点魔法就能看到，可以反复观看，价格很贵的！"
  },
  [130260003] = {
    id = 130260003,
    name = "不过，我之前见过这类型的魔法石，通常里面刻的都是魔法书籍，或者魔法阵一类的，没想到还有人拿它来写信，真奢侈啊。"
  },
  [130260004] = {
    id = 130260004,
    name = "星云，辉夜，你们听过这个祭坛吗？"
  },
  [130260005] = {
    id = 130260005,
    name = "被星星照亮的祭坛......没听过。"
  },
  [130260006] = {
    id = 130260006,
    name = "我也没听过。"
  },
  [130260007] = {
    id = 130260007,
    name = "你看，他找这个克莱尔跟他一起去祭坛，说明这个克莱尔真是他最好的朋友，连这么隐秘的事都能告诉他，还愿意分享那份力量。"
  },
  [130260008] = {
    id = 130260008,
    name = "......是吗？他为什么请求克莱尔帮他拿到所谓的遗产？他说的挑战，为什么要让别人和他一起面对？"
  },
  [130260009] = {
    id = 130260009,
    name = "祭坛有危险，他一个人应付不来。"
  },
  [130260010] = {
    id = 130260010,
    name = "原......原来是这样的吗？！"
  },
  [130260011] = {
    id = 130260011,
    name = "他没有说明白那个挑战是什么，甚至......连落名都没有。"
  },
  [130260012] = {
    id = 130260012,
    name = "等待克莱尔的也许是挑战，也许是陷阱。"
  },
  [130260013] = {
    id = 130260013,
    name = "那那那......这个白骨会是谁？"
  },
  [130260014] = {
    id = 130260014,
    name = "我也不知道，被骗来的克莱尔，亦或是计划失败的写信人，最好谁也不是。"
  },
  [130260015] = {
    id = 130260015,
    name = "可是他们，明明应该是最好的朋友吧。"
  },
  [130260016] = {
    id = 130260016,
    name = "嗯，我也希望谁都不是。"
  },
  [130270001] = {
    id = 130270001,
    name = "信在这里就中断了。"
  },
  [130270002] = {
    id = 130270002,
    name = "他说的那个山洞......是不是我们刚才路过的那个？"
  },
  [130270003] = {id = 130270003, name = "嗯。"},
  [130270004] = {
    id = 130270004,
    name = "队员们在那里发现残缺的衣物，这个探险者应该已经......"
  },
  [130270005] = {id = 130270005, name = "......"},
  [130270006] = {
    id = 130270006,
    name = "虽然已经经历过很多次，但每当看到有人死去的时候，心里仍然觉得不安。"
  },
  [130270007] = {
    id = 130270007,
    name = "当他踏上寻宝之路时，就应该知道会有与魔物恶战的一天。"
  },
  [130270008] = {
    id = 130270008,
    name = "可惜很多人只看到眼前的利益，并没有相应的胆识和能力。"
  },
  [130270009] = {
    id = 130270009,
    name = "可他们只是想寻宝，并没有错。"
  },
  [130270010] = {
    id = 130270010,
    name = "嗯，我们只能用自己的力量，减少这样的悲剧发生。"
  },
  [130270011] = {
    id = 130270011,
    name = "对，你说得没错。"
  },
  [130270012] = {
    id = 130270012,
    name = "只是我们更幸运吧。"
  },
  [130280001] = {
    id = 130280001,
    name = "很美的画......"
  },
  [130280002] = {
    id = 130280002,
    name = "都被血弄脏了啊。唉，这血迹斑斑的，感觉不太吉利，可能卖不出什么好价钱。"
  },
  [130280003] = {
    id = 130280003,
    name = "不，它比我所见过的画都要美，它的价值不该用金钱来衡量。这是我从没见过的色彩......"
  },
  [130280004] = {
    id = 130280004,
    name = "有火山泥的味道。这画中的某些颜料，应该来自火山附近的泥土。"
  },
  [130280005] = {
    id = 130280005,
    name = "是吗？我闻闻？唔，确实有股怪味，但还挺有意思的。"
  },
  [130280006] = {
    id = 130280006,
    name = "可惜根据这幅画的磨损程度来看，已经过去至少一个月了。"
  },
  [130280007] = {
    id = 130280007,
    name = "那这个画家岂不是凶多吉少。"
  },
  [130280008] = {
    id = 130280008,
    name = "嗯。他在写下遗言的时候，应该已经遭遇不测。但他没有放弃这幅画，而是坚持完成了它。"
  },
  [130280009] = {
    id = 130280009,
    name = "啊？你怎么看出来的？"
  },
  [130280010] = {
    id = 130280010,
    name = "除了这些血迹，画上没有添补的痕迹，说明他是在短时间内完成了画作，而没有停下来疗伤。"
  },
  [130280011] = {
    id = 130280011,
    name = "我还是不能理解，一幅画而已，以后还可以再画，命没了就没了啊。"
  },
  [130280012] = {
    id = 130280012,
    name = "也许在他心里，这不仅是一幅画。"
  },
  [130280013] = {
    id = 130280013,
    name = "是意志，或者信仰，就像正义对于深渊航线一样。"
  },
  [130280014] = {
    id = 130280014,
    name = "我有点明白了，这么说，这幅画又变得很值钱了啊。"
  },
  [130280015] = {
    id = 130280015,
    name = "......星云，这不是我们的画。"
  },
  [130280016] = {
    id = 130280016,
    name = "咳咳，你说得对，这种东西不能据为己有，先收起来吧，也许能找到他的家人也说不定呢。"
  },
  [130280017] = {
    id = 130280017,
    name = "嗯，走吧。"
  },
  [130290001] = {
    id = 130290001,
    name = "火山花......"
  },
  [130290002] = {
    id = 130290002,
    name = "他被骗了啊......我们看到的火山花根本没有那种作用吧。"
  },
  [130290003] = {
    id = 130290003,
    name = "世界上真的有能治愈一切疾病的药吗？"
  },
  [130290004] = {
    id = 130290004,
    name = "也许有吧，比如还没出世的圣物？"
  },
  [130290005] = {
    id = 130290005,
    name = "真这种东西，又怎么会落在普通人手里呢，告诉他的那个人，肯定也知道没有这种东西，只是想骗他的钱吧。"
  },
  [130290006] = {
    id = 130290006,
    name = "为什么？"
  },
  [130290007] = {
    id = 130290007,
    name = "小辉夜呀，你想想，你会劝一个从未下过深渊的人，来火山脚下找什么火山花吗？"
  },
  [130290008] = {id = 130290008, name = "不会。"},
  [130290009] = {
    id = 130290009,
    name = "这就对咯，那个人骗光了他的钱，然后再让他进深渊，这样他死了，也没有人知道那个人是元凶，元凶又可以继续去骗别人......"
  },
  [130290010] = {
    id = 130290010,
    name = "不可原谅！"
  },
  [130290011] = {
    id = 130290011,
    name = "竟然利用弱者求药心切的心情来谋财害命，这种心肠歹毒的恶人，应该绳之以法，在广场审判。"
  },
  [130290012] = {
    id = 130290012,
    name = "唉，可是谁又有证据证明他们是骗子呢，只凭这一封信吗？里面可没提到那个骗子的名字。"
  },
  [130290013] = {id = 130290013, name = "......"},
  [130290014] = {
    id = 130290014,
    name = "是啊，就算我们抓到他，他也可以一直否认，这是无法改变的。"
  },
  [130290015] = {
    id = 130290015,
    name = "会改变的。总有一天，会改变的。"
  },
  [130290016] = {
    id = 130290016,
    name = "嗯，咱们不就是在做这种事嘛。"
  },
  [130290017] = {
    id = 130290017,
    name = "我也相信的，总有一天。"
  },
  [130300001] = {
    id = 130300001,
    name = "真是狡猾的魔物啊。"
  },
  [130300002] = {
    id = 130300002,
    name = "伪装成货物，好像也不是什么稀奇的事。"
  },
  [130300003] = {
    id = 130300003,
    name = "对哦，我记得上次你杀掉了一个伪装成鲜花的魔物，差点咬掉了你的头。"
  },
  [130300004] = {
    id = 130300004,
    name = "......那种事就不用再提了。"
  },
  [130300005] = {
    id = 130300005,
    name = "不过这位魔物鉴定师，写的那些方法真的有用吗？尤其是这个粉末鉴定，阿嚏，阿嚏！"
  },
  [130300006] = {
    id = 130300006,
    name = "星云，没事吧？"
  },
  [130300007] = {
    id = 130300007,
    name = "没事没事，一点点粉末而已。"
  },
  [130300008] = {
    id = 130300008,
    name = "将其洒在货物上......如果有魔物......就会出现荧光反应......"
  },
  [130300009] = {
    id = 130300009,
    name = "看来这些货箱并不是魔物。"
  },
  [130300010] = {
    id = 130300010,
    name = "那他们为什么把货箱留在这里？难道遇到了难以对付的魔物逃走了？"
  },
  [130300011] = {
    id = 130300011,
    name = "不是，他们是有序撤退的。"
  },
  [130300012] = {
    id = 130300012,
    name = "你看路面统一的车辙，还有这些明显剩下的箱子，也许是为了轻装简行，故意留下的。"
  },
  [130300013] = {
    id = 130300013,
    name = "那是什么原因把这些东西留下了？"
  },
  [130300014] = {
    id = 130300014,
    name = "或许是真的遇到了魔物，也或许是知道、发现了什么，总之有不得不离开这里的原因。"
  },
  [130300015] = {
    id = 130300015,
    name = "啊，每次辉夜推断的时候，我总觉得事情在往不好的方向发展。"
  },
  [130300016] = {
    id = 130300016,
    name = "只有做好最坏的打算，真正遇到危机的时候才不会惊慌。"
  },
  [130300017] = {
    id = 130300017,
    name = "知道了，我们快离开这里吧。"
  },
  [130310001] = {
    id = 130310001,
    name = "字迹到这里就中断了。"
  },
  [130310002] = {
    id = 130310002,
    name = "他活下来了吗？那个巨型魔物又去了哪里？"
  },
  [130310003] = {
    id = 130310003,
    name = "我们一路过来，没有探查到巨型魔物的足迹，先遣队的情报里，也只有零散游荡的魔物。"
  },
  [130310004] = {
    id = 130310004,
    name = "他说他看到两只巨型魔物打架，一只还把另一只杀掉了。可这杀掉了总该有尸体吧......"
  },
  [130310005] = {
    id = 130310005,
    name = "巨型魔物......辉夜，你来看！"
  },
  [130310006] = {
    id = 130310006,
    name = "这个大坑是？"
  },
  [130310007] = {
    id = 130310007,
    name = "快看，那边也有！天，这是什么地方，好多深坑，要是车队一定很难走啊。"
  },
  [130310008] = {
    id = 130310008,
    name = "这些深坑分步均匀......就像是按照尺寸印上去的。"
  },
  [130310009] = {
    id = 130310009,
    name = "你别吓我啊月蚀，你是说这些坑就是巨型魔物的脚印？那这得多大的魔物啊！"
  },
  [130310010] = {
    id = 130310010,
    name = "传闻荒芜公爵喜欢在熔岩火山处栖息，它身如山丘，会在领地中四处巡视，为了捍卫自己的领地，不惜与任何存在为敌。"
  },
  [130310011] = {
    id = 130310011,
    name = "这个人看到的场景，也许就是荒芜公爵灭杀入侵者的时刻。"
  },
  [130310012] = {
    id = 130310012,
    name = "被领主级魔物追杀，这个人大概......"
  },
  [130310013] = {
    id = 130310013,
    name = "那我们也快离开这里吧！别惹怒那个大家伙！"
  },
  [130310014] = {id = 130310014, name = "好。"},
  [130320001] = {
    id = 130320001,
    name = "双月探险队，以前是不是还找过我们做过委托？是个老客户啊。"
  },
  [130320002] = {
    id = 130320002,
    name = "他们遇到麻烦了。"
  },
  [130320003] = {
    id = 130320003,
    name = "可这封信说了半天，那个裂缝在哪儿也不知道。"
  },
  [130320004] = {
    id = 130320004,
    name = "信息缺失，魔偶鸟里的魔法石也耗尽了，星云，你那还有多余的魔法石吗？"
  },
  [130320005] = {
    id = 130320005,
    name = "有有，在这里。欸，等等，辉夜你是想把魔法石放进魔偶鸟里继续让它飞？"
  },
  [130320006] = {
    id = 130320006,
    name = "嗯，情况紧急，我们也抽不出人手离开，只能这样吧。"
  },
  [130320007] = {
    id = 130320007,
    name = "可这里离迷雾之都很远，这点容量是不够的。"
  },
  [130320008] = {
    id = 130320008,
    name = "可以改变目的地吗？"
  },
  [130320009] = {
    id = 130320009,
    name = "对哦，让我看看！"
  },
  [130320010] = {
    id = 130320010,
    name = "好办法，只要到附近的营地，找到组织中转，就能一路传递到迷雾之都。"
  },
  [130320011] = {
    id = 130320011,
    name = "好，就这么办，成功了！鸟儿快快加油飞吧！"
  },
  [130320012] = {
    id = 130320012,
    name = "希望这个消息能成功传递。地裂导致的浊炁和魔物涌出，很多年前也出过类似的事。"
  },
  [130320013] = {
    id = 130320013,
    name = "那是怎么解决的？"
  },
  [130320014] = {
    id = 130320014,
    name = "我家里提到过这个，听说是被魔法阵重新封印起来了，但具体的情况谁也不清楚。"
  },
  [130320015] = {
    id = 130320015,
    name = "当年的动静很大吗？"
  },
  [130320016] = {
    id = 130320016,
    name = "不知道，希望我们别这么倒霉碰上吧，要是真碰上了，这不帮忙也说不过去啊。"
  },
  [130320017] = {
    id = 130320017,
    name = "你还真是......"
  },
  [130330001] = {
    id = 130330001,
    name = "远征探险队，没听过这个名字。"
  },
  [130330002] = {
    id = 130330002,
    name = "好像是一支较为活跃的探险队，我在公会委托上见过。"
  },
  [130330003] = {
    id = 130330003,
    name = "唉，太有名也是烦恼呀，找上门的人真多！"
  },
  [130330004] = {
    id = 130330004,
    name = "至于要不要与他们合作，也要等我们的任务结束之后再说。"
  },
  [130330005] = {
    id = 130330005,
    name = "好吧，那咱们要给他们回信吗？"
  },
  [130330006] = {
    id = 130330006,
    name = "暂时不必了，前面不远处就是营地，等到了营地和队员们商量之后再做决定。"
  },
  [130330007] = {
    id = 130330007,
    name = "好啊好啊，今晚终于不用露宿，可以睡个好觉了。"
  },
  [130330008] = {
    id = 130330008,
    name = "嗯，星云有什么想吃的吗？"
  },
  [130330009] = {
    id = 130330009,
    name = "有啊，我想喝诺维奇的红茶，再配上恰到甜味的华夫饼......"
  },
  [130330010] = {
    id = 130330010,
    name = "营地不是据点，应该不会提供这些。"
  },
  [130330011] = {
    id = 130330011,
    name = "好吧......辉夜，咦，你一直在看这封信，有什么不对吗？"
  },
  [130330012] = {
    id = 130330012,
    name = "嗯，这背后有一些符号，但不全。"
  },
  [130330013] = {
    id = 130330013,
    name = "我看看，是乐谱。♪♪♪......♪♪♪......就是这些了吧。"
  },
  [130330014] = {
    id = 130330014,
    name = "哇，月蚀真厉害！"
  },
  [130330015] = {
    id = 130330015,
    name = "小时候跟父母学过一点点，也只能认一些简单的谱子。这个旋律好像是一段童谣，但具体我也记不清了。"
  },
  [130330016] = {
    id = 130330016,
    name = "这个探险队还挺聪明的，知道欲擒故纵，放了一点线索，也不放全。"
  },
  [130330017] = {
    id = 130330017,
    name = "如果他们有诚意合作，我们在任务结束之后，也不妨去看看。"
  },
  [130340001] = {
    id = 130340001,
    name = "带血的信......"
  },
  [130340002] = {
    id = 130340002,
    name = "看起来有点恐怖啊。"
  },
  [130340003] = {
    id = 130340003,
    name = "既然已经这样了，他为什么不找人求助？"
  },
  [130340004] = {
    id = 130340004,
    name = "他在试炼。试炼是对自己的挑战，只有不断锤炼意志与抗性，才可以变得更强。"
  },
  [130340005] = {
    id = 130340005,
    name = "一旦求助，就会不自觉地依赖，也容易让自己软弱。"
  },
  [130340006] = {
    id = 130340006,
    name = "但是......遇到自己没有办法解决的问题，还是求助更好吧......"
  },
  [130340007] = {
    id = 130340007,
    name = "就算失败了，好过丢掉一条命嘛。"
  },
  [130340008] = {
    id = 130340008,
    name = "也许有的人不会这么想，闯不过去的难关，宁可死也不会找人求助。"
  },
  [130340009] = {
    id = 130340009,
    name = "哇，你不会在说你自己吧？"
  },
  [130340010] = {
    id = 130340010,
    name = "不是，我没那么蠢。"
  },
  [130340011] = {id = 130340011, name = "......"},
  [130340012] = {
    id = 130340012,
    name = "唉，可惜我们不知道他在哪里，如果顺路的话，还能救他一命。"
  },
  [130340013] = {
    id = 130340013,
    name = "很难，这封信应该已经写了很久了，背后的魔法印记无法溯源他的位置。"
  },
  [130340014] = {
    id = 130340014,
    name = "要带上吗？"
  },
  [130340015] = {
    id = 130340015,
    name = "我拿着吧，等回去之后，我找家里人找找，也许会有线索呢。"
  },
  [130340016] = {id = 130340016, name = "好。"},
  [130340017] = {
    id = 130340017,
    name = "但愿他能得到希望女神的护佑。"
  },
  [130350001] = {
    id = 130350001,
    name = "这个人疯了吧......好好的一个石板，还以为是什么魔法书籍呢。"
  },
  [130350002] = {id = 130350002, name = "......"},
  [130350003] = {
    id = 130350003,
    name = "他很痛苦。"
  },
  [130350004] = {
    id = 130350004,
    name = "做了个噩梦而已，我也经常梦见我会飞，或者跳进湖里淹死，醒来的时候发现被子盖太紧堵住呼吸了。"
  },
  [130350005] = {
    id = 130350005,
    name = "不一样。"
  },
  [130350006] = {
    id = 130350006,
    name = "哪里不一样了？不都是噩梦嘛，别去想它不就好了，晚上睡觉前想想好事，甚至还能做个美梦呢。"
  },
  [130350007] = {
    id = 130350007,
    name = "我知道辉夜的意思了。"
  },
  [130350008] = {
    id = 130350008,
    name = "啊？你也觉得不一样？"
  },
  [130350009] = {
    id = 130350009,
    name = "嗯，他很痛苦，他已经分不清梦境和现实了，分不清自己到底是人还是魔物。"
  },
  [130350010] = {
    id = 130350010,
    name = "这不就是疯了嘛，应该是遇到了什么不开心的事，让他难受了，再加上做了个噩梦，这本就难受的心情就更难受了呗。"
  },
  [130350011] = {
    id = 130350011,
    name = "不，你看这句：那是另一个我。"
  },
  [130350012] = {
    id = 130350012,
    name = "他是因为梦境疯的。"
  },
  [130350013] = {
    id = 130350013,
    name = "等等，我有点不太理解。"
  },
  [130350014] = {
    id = 130350014,
    name = "不用试图去理解一个已经疯掉的人，他的信息也许有用，也许没有，我们看过就好了。"
  },
  [130350015] = {
    id = 130350015,
    name = "嗯嗯，你说得对，我要是连疯子都能理解，那我应该也疯了，哈哈。"
  },
  [130360001] = {
    id = 130360001,
    name = "啊？我没看错吧......这家伙真的来火山脚下，不要命了？"
  },
  [130360002] = {
    id = 130360002,
    name = "祈祷或许会发生神迹，但他们不能全指望神迹来阻止灾难的发生。"
  },
  [130360003] = {
    id = 130360003,
    name = "在这种地方祈祷还是算了吧，一不小心小命就没了，要是侥幸活下来，信仰也崩塌了，得多残忍啊。"
  },
  [130360004] = {
    id = 130360004,
    name = "毕竟传言中的灾难，不是人类可以阻拦和拯救的事，将希望寄托于神灵，也是无奈之举吧。"
  },
  [130360005] = {
    id = 130360005,
    name = "......嗯，你说的也对。"
  },
  [130360006] = {
    id = 130360006,
    name = "星云，你怎么也在祈祷？"
  },
  [130360007] = {
    id = 130360007,
    name = "愿希望女神保佑这些心地善良的人，也许信仰之力真的能唤来神迹呢，祈祷一下也不耽误时间。"
  },
  [130360008] = {
    id = 130360008,
    name = "......你这是实用主义的祈祷。"
  },
  [130360009] = {
    id = 130360009,
    name = "来嘛，来嘛。"
  },
  [130360010] = {id = 130360010, name = "......"},
  [130360011] = {id = 130360011, name = "......"},
  [130360012] = {
    id = 130360012,
    name = "好耶，大家都祈祷结束了，我们继续出发吧。"
  },
  [130360013] = {
    id = 130360013,
    name = "总觉得心情宁静了一些。"
  },
  [130360014] = {
    id = 130360014,
    name = "这也许就是祈祷的力量吧。"
  },
  [130360015] = {id = 130360015, name = "嗯。"},
  [130370001] = {
    id = 130370001,
    name = "这写信的人真啰嗦啊，老半天才说清楚，果然还是“前面有危险，大家快跑吧”这种老掉牙的告示。"
  },
  [130370002] = {
    id = 130370002,
    name = "公会的情报比我们更加完善，对于这种事不可以掉以轻心。"
  },
  [130370003] = {
    id = 130370003,
    name = "嗯嗯，知道啦，如果他们不是每一次都这样危言耸听的话。"
  },
  [130370004] = {
    id = 130370004,
    name = "魔物袭击了三个临时营地......"
  },
  [130370005] = {
    id = 130370005,
    name = "辉夜每次都能抓住重点啊，这里是我唯一比较在意的地方了。"
  },
  [130370006] = {
    id = 130370006,
    name = "明明其他的信息也很重要吧。"
  },
  [130370007] = {
    id = 130370007,
    name = "还好吧，毕竟躁动的魔物到处都是，随便离开栖息地的可不多。难道火山里......"
  },
  [130370008] = {
    id = 130370008,
    name = "事到如今，我们——"
  },
  [130370009] = {
    id = 130370009,
    name = "我知道了，火山里一定有宝物！"
  },
  [130370010] = {id = 130370010, name = "？？？"},
  [130370011] = {
    id = 130370011,
    name = "一定是有非常厉害的宝物，让这些魔物不敢靠近，所以才会出现这样的谣言。"
  },
  [130370012] = {
    id = 130370012,
    name = "那公会的提醒......"
  },
  [130370013] = {
    id = 130370013,
    name = "也许他们也没深入火山调查呢，咱们一路走来可没见到几个人，谁知道真相是什么。"
  },
  [130370014] = {id = 130370014, name = "星云。"},
  [130370015] = {
    id = 130370015,
    name = "知道啦，任务为重嘛，我只是在思考这样的可能性，如果能顺手牵羊的话，嘿嘿嘿嘿......"
  },
  [130370016] = {
    id = 130370016,
    name = "唉，小财迷。"
  },
  [130380001] = {
    id = 130380001,
    name = "你们说公会是不是有点紧张过度了？咱们深渊航线什么时候怕过这些？"
  },
  [130380002] = {
    id = 130380002,
    name = "公会的信息向来准确，我们不能掉以轻心。"
  },
  [130380003] = {
    id = 130380003,
    name = "可咱们不能就这么回去吧，任务目标还没见着呢。"
  },
  [130380004] = {
    id = 130380004,
    name = "如果真的这样放弃，那我们可是第一次让深渊航线违约了。"
  },
  [130380005] = {
    id = 130380005,
    name = "不，还不到放弃的时候。"
  },
  [130380006] = {
    id = 130380006,
    name = "辉夜还是老样子呢，在你心中，就没有放弃这两个字吧。"
  },
  [130380007] = {
    id = 130380007,
    name = "......因为一旦放弃，就失去了前进的任何可能。"
  },
  [130380008] = {
    id = 130380008,
    name = "那咱们现在怎么办？"
  },
  [130380009] = {
    id = 130380009,
    name = "先遣小组快回来了，等得到确切的情报我们再考虑下一步的决定吧。"
  },
  [130380010] = {
    id = 130380010,
    name = "如果真如公会所说，那我们可以选择绕路，虽然远一些，但能到达目的地也行。"
  },
  [130380011] = {
    id = 130380011,
    name = "我同意，如果只是小规模地动，我们就加快速度通过危险区域。"
  },
  [130380012] = {
    id = 130380012,
    name = "嗯，那就这么说定了！"
  },
  [130390001] = {
    id = 130390001,
    name = "哎呀呀，看来公会已经放弃说服我们撤退了。"
  },
  [130390002] = {
    id = 130390002,
    name = "他们的担忧不无道理，这里每走一步都必须万分小心。"
  },
  [130390003] = {
    id = 130390003,
    name = "是啊，先前那几次危机的确很惊险，如果不是我们应对得当，也已葬身在火山脚下了。"
  },
  [130390004] = {
    id = 130390004,
    name = "嗯，之前那么多艰难困苦，咱们都闯过来了，下一步咱们也要好好地走，可不能在最后栽了跟头。"
  },
  [130390005] = {
    id = 130390005,
    name = "不过他们倒是说得好听，如果我们决定返程，会给我们支持......会有什么支持啊？"
  },
  [130390006] = {
    id = 130390006,
    name = "精神上的支持......也算吧？"
  },
  [130390007] = {
    id = 130390007,
    name = "噗哈哈哈，你说的没错。"
  },
  [130390008] = {
    id = 130390008,
    name = "速战速决吧，我有预感，我们的时间不多了。"
  },
  [130390009] = {
    id = 130390009,
    name = "嗯！等任务完成回去之后，我打算好好躺上两天。"
  },
  [130390010] = {
    id = 130390010,
    name = "我喜欢基地的那个软木枕，没有它我这段时间的脖子都快断掉了。你们呢？"
  },
  [130390011] = {
    id = 130390011,
    name = "暂且整顿一下，再看看有没有新的委托吧。"
  },
  [130390012] = {
    id = 130390012,
    name = "辉夜你——好吧，我没什么说的，佩服。月蚀呢？"
  },
  [130390013] = {
    id = 130390013,
    name = "我已经将这次的任务情况都记录了下来，回去以后打算好好复盘，总结不足，这样以后就能避免犯错了。"
  },
  [130390014] = {
    id = 130390014,
    name = "果然是个精致的完美主义者......不过我总觉得我好像忘了什么。"
  },
  [130390015] = {id = 130390015, name = "浮光。"},
  [130390016] = {
    id = 130390016,
    name = "对对，她还等着跟我们好好吃一顿呢，我要把咱们路上的事都说给她听。"
  },
  [130390017] = {
    id = 130390017,
    name = "包括你的糗事吗？"
  },
  [130390018] = {id = 130390018, name = "喂！"},
  [130390019] = {
    id = 130390019,
    name = "呵呵......"
  },
  [130400001] = {
    id = 130400001,
    name = "这么大规模的迁移，一定很热闹啊。"
  },
  [130400002] = {
    id = 130400002,
    name = "这件事很不寻常。"
  },
  [130400003] = {
    id = 130400003,
    name = "嗯？不就是搬家吗，有什么好奇怪的？"
  },
  [130400004] = {
    id = 130400004,
    name = "辉夜说得没错，连整个据点都必须迁移的原因，一定不简单。"
  },
  [130400005] = {
    id = 130400005,
    name = "......这么一说我倒是明白了，难道有什么他们对付不了的危险，才必须离开的？"
  },
  [130400006] = {
    id = 130400006,
    name = "哇，会是什么呢，大型魔物？浊炁突变？啊，难道是传闻里的兽潮？"
  },
  [130400007] = {
    id = 130400007,
    name = "也有可能是天灾。"
  },
  [130400008] = {
    id = 130400008,
    name = "你是说火山爆发？可咱们行走这么多天，也没感觉到啊。"
  },
  [130400009] = {
    id = 130400009,
    name = "能在火山脚下存活的据点必然有一定的实力，他们长期生活在那里，也一定掌握了我们无法知道的动向。"
  },
  [130400010] = {
    id = 130400010,
    name = "有道理，说不定浮光提到的危机，也是他们提前透露出去的。"
  },
  [130400011] = {
    id = 130400011,
    name = "啊，大家都在逃走，我们还要继续往前吗？"
  },
  [130400012] = {id = 130400012, name = "嗯。"},
  [130400013] = {
    id = 130400013,
    name = "别担心，这都是我们的猜测。"
  },
  [130400014] = {
    id = 130400014,
    name = "知道啦，担心那么多也是没用的，总之咱们走一步看一步吧！"
  },
  [130400015] = {id = 130400015, name = "好。"},
  [130400016] = {
    id = 130400016,
    name = "呵呵，等完成任务，也许还能追上那群人，跟他们做点小生意呢。"
  },
  [130400017] = {id = 130400017, name = "......"},
  [130410001] = {id = 130410001, name = "......"},
  [130410002] = {
    id = 130410002,
    name = "怎么了，月蚀？"
  },
  [130410003] = {
    id = 130410003,
    name = "这是一封家书。"
  },
  [130410004] = {
    id = 130410004,
    name = "嗯，刚刚你念的时候我听到了，哥哥为了妹妹，到一个所谓的“裂缝”里给妹妹寻找治疗的方法。不过，你的脸色看起来很不好啊。"
  },
  [130410005] = {
    id = 130410005,
    name = "这封家书......你说送到妹妹手里了吗？"
  },
  [130410006] = {
    id = 130410006,
    name = "......送、送到了吧......"
  },
  [130410007] = {id = 130410007, name = "......"},
  [130410008] = {
    id = 130410008,
    name = "怎么都沉默了，这封信有什么紧急情况吗？"
  },
  [130410009] = {
    id = 130410009,
    name = "没有。就是，有点伤心。"
  },
  [130410010] = {
    id = 130410010,
    name = "为什么？"
  },
  [130410011] = {
    id = 130410011,
    name = "......我还是希望没送到。"
  },
  [130410012] = {
    id = 130410012,
    name = "你们在说什么？"
  },
  [130410013] = {
    id = 130410013,
    name = "在说这封家书，它装在这个音乐盒里，应该是哥哥送给妹妹的礼物。"
  },
  [130410014] = {id = 130410014, name = "嗯。"},
  [130410015] = {
    id = 130410015,
    name = "如果家书已经送到妹妹手里了，这个音乐盒又怎么会在这里？"
  },
  [130410016] = {
    id = 130410016,
    name = "说明妹妹带着音乐盒来找哥哥了。"
  },
  [130410017] = {
    id = 130410017,
    name = "......嗯。如果没有送到，妹妹就不会知道哥哥失踪的消息。"
  },
  [130410018] = {
    id = 130410018,
    name = "如果是我，我希望这封信不要送到，那样妹妹就不会以身犯险......"
  },
  [130410019] = {id = 130410019, name = "月蚀？"},
  [130410020] = {
    id = 130410020,
    name = "有时候，没有消息，才是一种希望嘛。"
  },
  [130420001] = {
    id = 130420001,
    name = "符文消失了。"
  },
  [130420002] = {
    id = 130420002,
    name = "你们记住了吗？"
  },
  [130420003] = {
    id = 130420003,
    name = "文字很复杂......我只看清了两行。"
  },
  [130420004] = {
    id = 130420004,
    name = "我有点晕，这不是什么新的魔法符文吧？"
  },
  [130420005] = {
    id = 130420005,
    name = "不，有点像诗歌。"
  },
  [130420006] = {
    id = 130420006,
    name = "吟游诗人唱的那种？"
  },
  [130420007] = {
    id = 130420007,
    name = "不太像，更晦涩的诗歌，不像这个时代流行的。"
  },
  [130420008] = {
    id = 130420008,
    name = "讲了什么？"
  },
  [130420009] = {
    id = 130420009,
    name = "一处虚无之海，有一个失落的文明......这个人，看到一幅壁画，壁画上有神祇和英雄，还有灭世的景象......"
  },
  [130420010] = {
    id = 130420010,
    name = "我早听父亲说过，深渊里藏有许多不为人知的秘密，也许这也是其中之一。"
  },
  [130420011] = {
    id = 130420011,
    name = "失落的文明吗......如果找到，会不会有很多宝藏啊！"
  },
  [130420012] = {
    id = 130420012,
    name = "可这样的文明，还是湮灭了。星云，你在做什么？"
  },
  [130420013] = {
    id = 130420013,
    name = "我再敲敲这个山壁呀，万一真的有什么宝藏呢？"
  },
  [130420014] = {
    id = 130420014,
    name = "别敲了，这种符文只是一次性的映射，也许是很久以前的大魔法师留下的残影，能看到已经算是我们的幸运了。"
  },
  [130420015] = {
    id = 130420015,
    name = "唉，真可惜。看来幸运并不会眷顾每一个人啊。"
  },
  [130430001] = {
    id = 130430001,
    name = "哇，吓我一跳，怎么突然吼起来了。这东西在说什么？"
  },
  [130430002] = {
    id = 130430002,
    name = "又是一个疯掉的人。永生啊......这个世界上真的有永生吗？"
  },
  [130430003] = {
    id = 130430003,
    name = "他说他永生了。"
  },
  [130430004] = {
    id = 130430004,
    name = "不，他应该是死了。"
  },
  [130430005] = {id = 130430005, name = "......"},
  [130430006] = {
    id = 130430006,
    name = "听他的声音，是被关在哪里了？那个地方好像很可怕，他说人都变成了怪物，人怎么会变成怪——"
  },
  [130430007] = {
    id = 130430007,
    name = "......堕落者，难道那些人都成了堕落者？"
  },
  [130430008] = {
    id = 130430008,
    name = "大概是。堕落者无日无月，无知无觉，它们没有情感和记忆，只懂得杀戮，但他们却不会死。"
  },
  [130430009] = {
    id = 130430009,
    name = "可堕落者是人人都该知道的事吧，这个人怎么还口口声声说怪物呢？能去找什么长生不老，总不会是第一次下深渊的探险者吧？"
  },
  [130430010] = {
    id = 130430010,
    name = "是这个沙海螺。它能保存几十年，甚至上百年的声音。"
  },
  [130430011] = {
    id = 130430011,
    name = "也许这里在很久之前，也不像现在这样。"
  },
  [130430012] = {
    id = 130430012,
    name = "这是过去的声音。"
  },
  [130430013] = {
    id = 130430013,
    name = "对，只有这样才能解释，他在意识消散前，都不知道自己会变成的怪物，名叫堕落者。"
  },
  [130430014] = {
    id = 130430014,
    name = "意识消散了......人还是人吗？像堕落者一样地活着，算活着吗？"
  },
  [130430015] = {
    id = 130430015,
    name = "不算。堕落者必须死。"
  },
  [130430016] = {
    id = 130430016,
    name = "是啊，即便他们曾经是人类。"
  },
  [130430017] = {
    id = 130430017,
    name = "嗯，只是曾经。"
  },
  [130440001] = {
    id = 130440001,
    name = "写给无间狱统领的信......是高塔的人？"
  },
  [130440002] = {
    id = 130440002,
    name = "我记得无间狱统领叫缇法尼，传言她的性格阴晴不定，没人能猜到她在想什么。"
  },
  [130440003] = {
    id = 130440003,
    name = "这个......会是背叛她的人吗？"
  },
  [130440004] = {
    id = 130440004,
    name = "不知道。既然已经撕碎了信纸，又为什么要重新粘合起来？"
  },
  [130440005] = {
    id = 130440005,
    name = "撕碎信纸的肯定是缇法尼，她看到这封信很生气，于是找到了这个男的，杀掉他还把信还给他。"
  },
  [130440006] = {
    id = 130440006,
    name = "不合常理，既然撕碎了，没必要再重新粘合，除非有什么特别重要的信息。"
  },
  [130440007] = {
    id = 130440007,
    name = "可这翻来覆去看，哪里有什么重要的信息......不对，这应该是证据！"
  },
  [130440008] = {
    id = 130440008,
    name = "什么证据？"
  },
  [130440009] = {
    id = 130440009,
    name = "背叛高塔的证据吧，就像借钱的一样，总要写个欠条，才能证明有过借钱的行为，信中承认了他的背叛行为，有这个证据，就能用高塔的规矩惩罚背叛者了。"
  },
  [130440010] = {
    id = 130440010,
    name = "......不太像，这个钥匙，这个秘密......高塔没这么傻。"
  },
  [130440011] = {
    id = 130440011,
    name = "唔......这家伙看起来也不像个小偷啊。唉......"
  },
  [130440012] = {
    id = 130440012,
    name = "为什么要叹气？"
  },
  [130440013] = {
    id = 130440013,
    name = "就是觉得有点可惜。他背叛了原来的组织，得到的只有死亡。"
  },
  [130440014] = {
    id = 130440014,
    name = "先将他埋葬了吧。"
  },
  [130440015] = {
    id = 130440015,
    name = "那这封信怎么处理？是毁了，还是交给......"
  },
  [130440016] = {
    id = 130440016,
    name = "回去之后问问浮光，也许她会知道些什么呢。"
  },
  [130440017] = {id = 130440017, name = "好啊。"},
  [130450001] = {
    id = 130450001,
    name = "威尔森，我听过这个名字，是个有名的贵族姓氏。"
  },
  [130450002] = {
    id = 130450002,
    name = "盗走贵重物品来勒索贵族，很多盗宝人都这样做过。"
  },
  [130450003] = {
    id = 130450003,
    name = "这地上的宝石碎片......是贵族的人带着信来过了？"
  },
  [130450004] = {
    id = 130450004,
    name = "看起来交易好像失败了呢。"
  },
  [130450005] = {
    id = 130450005,
    name = "不对，这个宝石碎片......看起来很劣质，不像是他信里说的那颗宝石，难道盗贼用了个假宝石骗赎金？"
  },
  [130450006] = {
    id = 130450006,
    name = "不，没有赎金。"
  },
  [130450007] = {id = 130450007, name = "嗯？"},
  [130450008] = {
    id = 130450008,
    name = "脚印很浅。来的人很多，而且都是轻装，没有携带那么多金币。"
  },
  [130450009] = {
    id = 130450009,
    name = "哇，这就是说，贵族想带人抓住这个盗贼拿回宝石，但盗贼也用了假的宝石来蒙骗贵族，两边都很精明嘛。"
  },
  [130450010] = {
    id = 130450010,
    name = "这里也没有打斗的痕迹，看来盗贼根本没有出现过。他应该一早就看穿了贵族的计划。"
  },
  [130450011] = {
    id = 130450011,
    name = "根据这些脚步和痕迹，他们应该是昨天离开这里的。"
  },
  [130450012] = {
    id = 130450012,
    name = "虽然不赞同这个贼人的做法，但能让平时欺压平民的贵族吃瘪也是大快人心的一件事啊。"
  },
  [130450013] = {
    id = 130450013,
    name = "......其实这并不是一件好事，如果他能成功，以后的盗贼只会越来越猖獗。"
  },
  [130450014] = {
    id = 130450014,
    name = "说起来，星云家里最近是不是在出售稀有的魔法宝石，可要小心这些盗宝贼啊。"
  },
  [130450015] = {
    id = 130450015,
    name = "不用在意，他们会先偷贵族和有钱人的东西，我家这样勤恳老实的普通家庭，短时间内是不会成为他们的目标的。"
  },
  [130450016] = {id = 130450016, name = "......"},
  [130450017] = {id = 130450017, name = "......"},
  [130460001] = {
    id = 130460001,
    name = "被我们猜中了啊。这家伙，果然识破了威尔森的计划，拿了假的宝石去交易。"
  },
  [130460002] = {
    id = 130460002,
    name = "纸条被撕碎了，这位威尔森阁下看起来很生气。"
  },
  [130460003] = {
    id = 130460003,
    name = "没抓到小贼，还被耍了，换成任何人都会气死吧，噗嗤。"
  },
  [130460004] = {
    id = 130460004,
    name = "你在笑什么？"
  },
  [130460005] = {
    id = 130460005,
    name = "我在笑那些贵族啊，他们一天到晚一本正经的，不把贱民放在眼里，现在被一个他们眼中的贱民耍得团团转。"
  },
  [130460006] = {
    id = 130460006,
    name = "你很看不惯贵族吗？"
  },
  [130460007] = {
    id = 130460007,
    name = "也不是啦，只是觉得不太公平。"
  },
  [130460008] = {
    id = 130460008,
    name = "当然我知道，这个世界就是不公平的，有的人生下来就住在宫殿，有的人一出生只能在贫民窟。"
  },
  [130460009] = {
    id = 130460009,
    name = "贫民窟的人不管再努力，也没有办法跨越那道阶梯，爬到主人的位置......"
  },
  [130460010] = {
    id = 130460010,
    name = "星云想做贵族？"
  },
  [130460011] = {
    id = 130460011,
    name = "我才没这么想过，只是想为什么贵族那么有钱，却不愿意分一点点给大家，哪怕只是一点点，很多人也不会饿死了。"
  },
  [130460012] = {
    id = 130460012,
    name = "如果我那么有钱，我会把能干活的都召集在一起，他们干活，我给他们发钱，这样他们就不用饿死了。"
  },
  [130460013] = {
    id = 130460013,
    name = "星云的想法很好，我也想为这个世界做些什么，不只是付之于文字，更想亲自改变这一切。"
  },
  [130460014] = {
    id = 130460014,
    name = "世间多不公，所以我们才要一点点地去改变它。即使正义不能在所有的地方都能实现，但总比什么都不做更好。"
  },
  [130460015] = {
    id = 130460015,
    name = "但我还是想说，这个盗贼的做法并不正确，偷盗始终——"
  },
  [130460016] = {
    id = 130460016,
    name = "嗯嗯，希望他们的交易能顺利达成！我们走吧。"
  },
  [86180001] = {
    id = 86180001,
    name = "干杯，为了世界和平！"
  },
  [86180002] = {
    id = 86180002,
    name = "滚吧，潜规则。"
  },
  [86180003] = {
    id = 86180003,
    name = "抱歉，我酒量不好。"
  },
  [86180004] = {
    id = 86180004,
    name = "跟他好好讲道理"
  },
  [86180005] = {
    id = 86180005,
    name = "帮忙推车"
  },
  [86180006] = {
    id = 86180006,
    name = "卸掉车轮"
  },
  [86180007] = {
    id = 86180007,
    name = "我全要了！"
  },
  [86180008] = {
    id = 86180008,
    name = "这是什么魔法药理？"
  },
  [86180009] = {
    id = 86180009,
    name = "点个火试试"
  },
  [86180010] = {
    id = 86180010,
    name = "买，以备不时之需"
  },
  [86180011] = {
    id = 86180011,
    name = "不买，看上去就有问题"
  },
  [86180012] = {
    id = 86180012,
    name = "教他说个冷笑话"
  },
  [86180013] = {
    id = 86180013,
    name = "教他一个魔法"
  },
  [86180014] = {
    id = 86180014,
    name = "先答应他，套取了情报再说"
  },
  [86180015] = {
    id = 86180015,
    name = "拒绝，让一个陌生人加入非常危险"
  },
