  [86280087] = {id = 86280087, name = "继续"},
  [140000101] = {
    id = 140000101,
    name = "“想打听炎日溶洞的情报？”酒保用手指了指里面黑漆漆的屋子，又指了指吧台上的三杯烈酒，“先喝下它们，让里面的人看看你的诚意。”烈酒鲜红浓郁，像一种危险又致命的邀请。"
  },
  [140000102] = {
    id = 140000102,
    name = "你毫不犹豫地喝下了三杯烈酒，酒意直冲头顶，酒馆里烟雾一片。你刚走一步，眼前所有的酒与人都在转动......意识清醒后，你已被全身扒光，扔了在酒馆门口。"
  },
  [140000103] = {
    id = 140000103,
    name = "情报是死的，规则是活的。你把三杯酒灌进了酒保的嘴里，拖着不省人事的他进入了小黑屋。房间狭小暗黑，只有角落里亮着一扇窗，你耐心等了许久，窗里不情不愿地扔出了一张通往尼塔炎日溶洞的地图。"
  },
  [140000104] = {
    id = 140000104,
    name = "你拒绝了他的要求，扔了三枚金币当酒钱，酒保饶有兴趣地收下了，带你进了房间。房间狭小暗黑，只有角落里亮着一扇窗，片刻后，窗里扔出了一张羊皮卷。卷上记载了「尼塔炎日溶洞地下码头的航运路线目前已荒废」的消息。"
  },
  [140000201] = {
    id = 140000201,
    name = "行商看到你们一行人准备出远门，竭力地推荐自己的货物，你们听到他便宜的价格，收购了一批莹草。\n你们回来后，发现里面混杂了许多腐烂的莹草，你决定去找他讨个说法，可他却拒绝承认那是他卖的莹草。"
  },
  [140000202] = {
    id = 140000202,
    name = "你拿出一根根腐烂的莹草跟他的货物比对，又拉了几个人证来问他怎么办。他一口吃了苍蝇的样子，脸色难看地把钱退给了你。"
  },
  [140000301] = {
    id = 140000301,
    name = "经过一条巷道的时候，那里已经堵了许多人。\n“哎，不是我不让啊......”男人盯着卡在石缝里的推车，十分无奈的样子，“你们要通过这里？抱歉，这辆车的轮子卡在这里了，我也无能为力。”"
  },
  [140000302] = {
    id = 140000302,
    name = "你提出帮忙，男人急急让开了一些位置。\n你们用了九牛二虎之力推车，只听“咔”地一声，车身下出现好大一道裂缝。\n轮毂断了，男人的表情也碎裂了。\n你歉意地帮他料理之后的事，也因此耽搁了不少时间。"
  },
  [140000303] = {
    id = 140000303,
    name = "你卸掉了车轮扔在一边，听到男人的尖叫：“你怎么把我的东西弄坏了？！”\n但很快他看到推车成功挪走，激动地抱起了地上的轮子，向你道谢：“太棒了，我怎么没有想到这个办法呢，愿希望女神保佑你！”"
  },
  [140000401] = {
    id = 140000401,
    name = "“你们要去炎日溶洞？哎呀呀，那边的河里流的都是火叻，涂抹我的药，就算着了火也不会烧伤涅！“\n药商口若悬河，一手往助手身上涂抹药粉，接着一把火点燃，助手全身燃起了绿色的火焰！\n众人屏息等着火焰燃尽，助手的皮肤竟然完好无损。"
  },
  [140000402] = {
    id = 140000402,
    name = "你拍下几枚金币全部买下。\n“客人大气！”药商急忙把几个药包递到你手中。\n“祝客人顺风如意，履险如夷，万事亨通，百事大吉！”\n你到达休息处后打开药包，发现其中只有一件宝物，想来是药商在匆忙中拿错了。\n你返回原处准备调换商品时，才发现刚才的药商已经消失不见。"
  },
  [140000403] = {
    id = 140000403,
    name = "你提出疑问，药商故作神秘不告诉你，只说这是他秘密研制的药粉。\n在你再三追问下，他拿出一小包药粉塞给了你，让你自己去研究，别挡住他做别的生意。\n你走远了拆开闻了闻，发现只是普通治疗烧伤的草药粉而已。"
  },
  [140000404] = {
    id = 140000404,
    name = "“真有这么神奇？刚才没看清。”\n药商看你来了兴趣，招呼助手再抹了药粉，你没等他们自己点火，扔出了一个火球，烫得助手哇哇地在地上打滚，竟然发现那些药粉都是普通药草做的。\n众人也意识到这是一场骗局，哄然而散。"
  },
  [140000405] = {
    id = 140000405,
    name = "你拍下几枚金币全部买下。\n“客人大气！”药商谄媚地把几个药包递到你手中。\n“祝客人顺风如意，履险如夷，万事亨通，百事大吉！”\n你没走多远，手里的药包忽然全都燃了起来！\n极力扑救后，你发现现场没有任何灼烧的痕迹，猛地意识到自己被骗了。"
  },
  [140000501] = {
    id = 140000501,
    name = "你们走到一家买食材的店铺前，店主最新推出了一道价格低廉又可携带食物“炖肉罐头”。\n店员隆重地介绍这是由深渊中挖掘出的秘密配方，里面包含了不朽的豆腐、无水的香菜以及魔物精肉等精心搭配的食材，无需加热，开罐即食。\n在店铺的一侧还放有试吃的罐头，看上去难以下咽。"
  },
  [140000502] = {
    id = 140000502,
    name = "虽然卖相不是太好，但饥饿是能够使所有食物都变得美味的万能调味品。\n你买了好些个罐头，店主激动地告诉你，你是他们今天的第一位顾客，特别给你多加了一些赠品。\n你满载而归，没去考虑之后谁吃的问题。"
  },
  [140000503] = {
    id = 140000503,
    name = "你还没走近，就能闻到那股让人崩溃的霉味，难以想象这种东西可以吃。\n在询问了没有其他食物后，你离开这个飘散着奇怪味道的地方。"
  },
  [140000601] = {
    id = 140000601,
    name = "据你所知，圈落里藏着许多能人异士，要到达地形特殊的地方，也许可以问问去过的人。\n你找了几日，打听到了那人的所在处，只是他提出的条件让人匪夷所思——让你教他一个他没见过的技艺。"
  },
  [140000602] = {
    id = 140000602,
    name = "你讲了一个关于海鸥的冷笑话。\n他一拍大腿，双眼放光，“你说得对，人生的目标不就是整点吃的！”\n他如遇知音，把你请进屋欢快地畅谈了许久，你也知道了他探险火山口的经验与旅程。"
  },
  [140000603] = {
    id = 140000603,
    name = "你思考着在某探险者身上见过的稀奇魔法，当场给他表演了一个。\n他眨了眨眼睛，勉强表示满意，跟你说了几点注意事项就关门谢客了。"
  },
  [140000701] = {
    id = 140000701,
    name = "一个灰头土脸的拾荒者打听到你们即将去炎日溶洞，又是毛遂自荐，又是溜须拍马，请求你们带着他一起去。\n你们并不准备招揽陌生人进入队伍，拒绝了他，他摸了半天摸出了一块亮闪闪的源晶。\n“看见这个没，就是溶洞下面那个据点的，你让我跟着你，我告诉你地下据点的秘密？”"
  },
  [140000702] = {
    id = 140000702,
    name = "你假意思考片刻，同意了他的请求，让他说出一些情报证实他的可信度。\n他又拿出了一块船员的身份牌，那是地下据点曾经存在码头的证明。\n你装作不信，得到了这个情报离开了。"
  },
  [140000703] = {
    id = 140000703,
    name = "你警惕地拒绝了他，虽然不知道护送的东西是什么，但也许别人早已拿到了情报。\n就像你早已知道曾经的地下据点早已被一年前的兽潮摧毁。"
  },
  [140000801] = {
    id = 140000801,
    name = "你在街角尽头发现一处新的房屋，全新的砖瓦和整洁的院落，让你有些在意。\n你看了好一会儿，引起了屋主人的注意。他走出来，打量了你一番：“看什么呢？”"
  },
  [140000802] = {
    id = 140000802,
    name = "你感叹地说这间屋子相当别致，屋主人也一定是个有品味的人。\n他得意地夸你有眼光，说是去年才从炎日据点搬来的，那时炎日火山不知为什么爆发了一场兽潮，摧毁了他曾经的定居点。"
  },
  [140000803] = {
    id = 140000803,
    name = "你想打听些消息，打算先旁敲侧击询问原来在这里住的人，他却一脸茫然地看着你。“你是不是记错啦，这里原来是空地，没人住的。”"
  },
  [140000804] = {
    id = 140000804,
    name = "你被他盯着有点心虚，赶紧道了歉离开。\n他撇了撇嘴，似乎觉得你不是什么好人，看着你走远才回屋。"
  },
  [140000901] = {
    id = 140000901,
    name = "你们赶路了一整天，入夜时你沉沉入睡。直觉比听觉更加灵敏，没有脚步声，但你已经感到了危险迫近，附近的草丛里，有明晃晃的刀尖泛着森冷的光。在同伴的呼喊声中，你们纷纷拿起了武器，不一会儿就将来人打退了。"
  },
  [140000902] = {
    id = 140000902,
    name = "“他们还有同伙，决不能让他们回去报信！”你高声喊道，几名同伴振奋了起来。\n一场追击战后，将几人抓住捆在树上，并搜刮了他们随身携带的物资。"
  },
  [140000903] = {
    id = 140000903,
    name = "一场战斗后，你们筋疲力尽，为了更好地赶路，你们决定抓紧时间休息，但没想的是，那些强盗带了更多的人杀了个回马枪。\n你们再次击退了强盗，好几人受了皮外伤。"
  },
  [140000904] = {
    id = 140000904,
    name = "他们撤退得非常有规律，也许只是一批打探消息的先行者。\n你将这个想法告诉了同伴，决定熄灭火堆，消除痕迹，快速离开这里。"
  },
  [140001001] = {
    id = 140001001,
    name = "一场大雨突如其来，你们躲入了附近的山洞，山洞里横躺着几具遗骸，他们如同被时间遗忘的幽灵，无声地诉说着山洞深处的恐怖秘密。"
  },
  [140001002] = {
    id = 140001002,
    name = "你默念了一声得罪了，取走了遗骸周围散落的资源。"
  },
  [140001003] = {
    id = 140001003,
    name = "你没有去打扰那些人的安眠，默默在洞中等待着。\n雨不知什么时候停了，你们整顿行装继续上路。"
  },
  [140001004] = {
    id = 140001004,
    name = "遗骸周围弥漫着一种令人窒息的恐怖氛围，连空气都被染上了死亡的冰冷。\n窒息的感受仿佛在挤压你的心脏，你们察觉到山洞的怪异与危机，冒着大雨继续前进。"
  },
  [140001101] = {
    id = 140001101,
    name = "尽管天地无言，深渊无序，尽管这里没有春秋四季、星月交辉......此时长夜未尽，已经有光如浪涛涌来，你知道，那或许是宝物出世的启示。"
  },
  [140001102] = {
    id = 140001102,
    name = "你跟随那光的节奏前进，顺着光的指引，你发现那光芒也在不断移动，待你想细细看时，光芒大盛，一声魔物的叫嚣如电光般逼近。"
  },
  [140001103] = {
    id = 140001103,
    name = "你停在原地观察了一阵，发现那光芒正有规律地移动着，但很快又在原地消失了，你怅然若失，似乎觉得错过了什么。"
  },
  [140001201] = {
    id = 140001201,
    name = "你们沿着河边前行，在一处岸边看到了搁浅的船只，但船只已经十分腐朽了，也许在下一秒就会四分五裂。"
  },
  [140001202] = {
    id = 140001202,
    name = "“看起来已经不能用了。”\n你遗憾地叹息，只简单地搜索了船只，发现了一些能用的探险工具，也算有些收获。"
  },
  [140001203] = {
    id = 140001203,
    name = "“这是一个节省时间的机会。”你们四处找工具，终于在天黑之前修补好了这条船，船只在驶入河道时，全员爆发出欢呼声。"
  },
  [140001204] = {
    id = 140001204,
    name = "如此破旧的船只已经无法行船，你们只能放弃水路，继续沿着山路朝炎日火山前行。"
  },
  [140001301] = {
    id = 140001301,
    name = "眼前是一堆形态各异的蘑菇，它们的色彩缤纷，有的鲜艳如火，有的柔和如霞，散发出一种难以抗拒的魅力，然而你也深知，在这美丽背后，隐藏着未知的危险。"
  },
  [140001302] = {
    id = 140001302,
    name = "根据经验，你避开了那些颜色鲜艳的菌类，仅采取了部分自己认识的蘑菇。"
  },
  [140001303] = {
    id = 140001303,
    name = "你不打算分辨蘑菇是否有毒，然而，就在你准备摘取它们的时候，突然一阵头晕目眩，周围的树木变得扭曲而诡异，你感到自己的身体变得轻盈，仿佛随时都会飘起来。"
  },
  [140001304] = {
    id = 140001304,
    name = "你知道，这不是一个完美的解决方案，但至少可以避免因为误食毒蘑菇而陷入危险。"
  },
  [140001401] = {
    id = 140001401,
    name = "前方的巨石上蹲坐着一个人，他身穿破旧的皮衣，手持一把古老的弓箭，与周围的环境融为一体。\n直觉告诉你，这个猎人并非寻常之辈，你向他打听情报，他漠然地看了你一眼：“我不想和弱者说话。”"
  },
  [140001402] = {
    id = 140001402,
    name = "你希望能从他那里打探到更多的情报，虚心地请教。\n他微微一笑，“年轻人，秘密并非轻易可以揭示。你需要学会聆听自己内心的声音，它会告诉你一切。”他说完就离开了。\n你若有所思，在原地搜寻一番后，发现一件有用的物件。"
  },
  [140001403] = {
    id = 140001403,
    name = "你打量了他一番，突然出手朝他攻击。\n他露出惊慌失措的表情，一翻跟斗消失在了巨石后，你没再看见他。\n真是虚张声势的家伙。"
  },
  [140001404] = {
    id = 140001404,
    name = "你希望能从他那里打探到更多的情报，虚心地请教。\n他微微一笑，“年轻人，秘密并非轻易可以揭示。你需要学会聆听自己内心的声音，它会告诉你一切。”他说完就离开了。\n你觉得此人故作玄虚，也不再停留。"
  },
  [140001501] = {
    id = 140001501,
    name = "一个高大的路牌倒在地上，断裂的部分露出尖锐的边缘，警告着过往的行人。\n路牌上的指示文字已经模糊不清，无法辨认出原来的方向。\n你看了一眼前方，左边的岔路蜿蜒曲折，消失在茂密的树丛中；右边的岔路则相对宽阔，似乎通向一个未知的地方。"
  },
  [140001502] = {
    id = 140001502,
    name = "你们商讨后，选择了左边的岔路，前行不远，一阵低沉的咆哮声打破了周围的宁静，不多时，一群模样狰狞的魔物从树丛中窜了出来，挡在了你们的去路上。"
  },
  [140001503] = {
    id = 140001503,
    name = "你们商讨后，选择了右边的岔路，没过多久，就发现了一个废弃的据点。据点内房屋残破不堪，墙壁上长满了青苔和藤蔓。尽管如此，你们还是找到了一些有用的物品。"
  },
  [140001601] = {
    id = 140001601,
    name = "巨大的陶罐矗立在河滩旁，比一般的陶罐要大数倍，上面雕刻着复杂的图案，你敲了敲，发现里面并不是空无一物。"
  },
  [140001602] = {
    id = 140001602,
    name = "你果断推倒了陶罐，陶罐以一种惊人的速度向一侧倾斜，重重地倒在了地上，发出震耳欲聋的碎裂声，里面的魔法器具滚落了出来。"
  },
  [140001603] = {
    id = 140001603,
    name = "你迅速寻找了一块合适的石头，深吸一口气，然后用力砸向陶罐。\n随着一声震耳欲聋的碎裂声，陶罐在你眼前破碎，尘土和碎片四溅，露出了里面存放的魔法器具。\n虽然被尘土覆盖，但你能感受到它蕴含其中的魔法力量。"
  },
  [140001604] = {
    id = 140001604,
    name = "你继续前行，但心中始终惦记着那个陶罐——\n希望它能继续成为探险者们的路标，指引他们在这片神秘的森林中找到自己的方向。"
  },
  [140001605] = {
    id = 140001605,
    name = "你果断推倒了陶罐，陶罐以一种惊人的速度向一侧倾斜，重重地倒在了地上，发出震耳欲聋的碎裂声，里面空空如也。"
  },
  [140001606] = {
    id = 140001606,
    name = "你迅速寻找了一块合适的石头，深吸一口气，然后用力砸向陶罐。\n随着一声震耳欲聋的碎裂声，陶罐在你眼前破碎，尘土和碎片四溅，里面空空如也。"
  },
  [140001701] = {
    id = 140001701,
    name = "河面上漂浮着一只受伤的大型水龟。它身下水域泛红，身体似乎受到了伤害，无法自主游动，身体上有一些明显的伤痕，似乎是被尖锐的物体划伤的。"
  },
  [140001702] = {
    id = 140001702,
    name = "你们小心翼翼地将它抬上船，准备进行紧急处理，它突然一跃而起，向你们发起了猛烈的攻击！真是太天真了，深渊里可没有什么善茬！"
  },
  [140001703] = {
    id = 140001703,
    name = "你察觉到了一丝不同寻常的浊炁，立刻发出前进三的指令，船身猛然加速，轰地一声撞开了那只不明生物，扬长而去。"
  },
  [140001801] = {
    id = 140001801,
    name = "浓密的迷雾从森林深处迅速弥漫开来，将你们的视线完全遮挡，使你们无法看清前方的道路。"
  },
  [140001802] = {
    id = 140001802,
    name = "意识到这片迷雾可能隐藏着未知的危险，你们决定原地扎营，时刻准备应对可能出现的敌人。\n第二天，迷雾果然消失了，你们得以顺利通行。"
  },
  [140001803] = {
    id = 140001803,
    name = "唯有探索才能前进！你们紧紧握住手中的武器，不约而同步走进了这片迷雾。微弱的魔石荧光无法照亮前方的路，却为敌人指明了方向。当同伴受伤惨叫时，你才发现魔物已经近在咫尺！"
  },
  [140001804] = {
    id = 140001804,
    name = "你迅速做出了决定，调整了方向，寻找一个可以绕过迷雾的路径，最终成功地绕过了迷雾区域，重新回到了清晰的视野。"
  },
  [140001901] = {
    id = 140001901,
    name = "“看，那是什么？！”\n行至森林深处，竟有一座巍峨的雕像，它坐落在古老的祭坛上，被茂密的藤蔓和厚厚的苔藓所覆盖，四周散落着许多珍奇，包括破旧的魔法卷轴、古老的武器碎片以及璀璨的宝石。它们散发出魔法的光芒，仿佛在引诱人们一步步靠近。"
  },
  [140001902] = {
    id = 140001902,
    name = "天予不取，反受其咎。面对这样的横财，你当仁不让地拿走宝石。\n就在你将宝石握在手中的那一刻，整个祭坛开始震动，被封印的魔物从沉睡中苏醒，发出一声震耳欲聋的咆哮。你顿感不妙，急忙拿着宝石逃走了。"
  },
  [140001903] = {
    id = 140001903,
    name = "你拿起了地上的魔法卷轴，它的材料异常坚韧，你费了些力气才轻轻地将其展开。\n这时，卷轴上的符文像是被激活了一般，开始在空中漂浮并旋转，一道强烈的光芒从卷轴中射出，一个巨大的身影在光芒下逐渐显现，你打开了魔法封印，放出了埋藏已久的魔物！"
  },
  [140001904] = {
    id = 140001904,
    name = "人生如逆旅，很多人在某一刻，会涌起一种逃跑的冲动，包括这时候的你。\n你相信自己的直觉，转身离开祭坛，放弃了一切的诱惑。"
  },
  [140002001] = {
    id = 140002001,
    name = "夜幕降临，你们在河边的空地上安营扎寨，营火熊熊燃烧，映照着你们忙碌的身影。\n不久，另一队探险者出现在视野中，他们被你们的火光吸引而来。"
  },
  [140002002] = {
    id = 140002002,
    name = "你和他们打了个招呼，并邀请他们过来休息，一起围在温暖的篝火旁。\n听说你们要去的地方，他们紧张地告诉你：“不要再前进了，那边是绝路，是滚烫的岩浆，还有像小山一般燃烧的魔物！”"
  },
  [140002003] = {
    id = 140002003,
    name = "你默默地看着他们，见他们也没有主动过来交谈的意思，默契地互不干扰，直到人影消失。"
  },
  [140002101] = {
    id = 140002101,
    name = "你们筋疲力尽地攀上了山顶，一个鲜有人迹的高度，你放眼俯瞰，远处的火山弥漫着朦胧的烟雾，那是你们即将要到达的地方。"
  },
  [140002102] = {
    id = 140002102,
    name = "你在原地驻足片刻，突然，远处发出一阵震动和巨吼声，火山脚下的魔物如潮水般倾巢而出！"
  },
  [140002103] = {
    id = 140002103,
    name = "你们决定立刻出发，没走多久，杂乱躁动的脚步声声逼近。\n只见一群小型魔物从四面八方涌来，眼中闪烁着红光，誓要将你们撕成腹中餐。"
  },
  [140002104] = {
    id = 140002104,
    name = "你看到火山中的异动，想到那里应该有魔物们更惧怕的东西存在。\n为了任务目标，你决定谨慎绕道，寻找安全的地方离开，迅速撤离了山顶。"
  },
  [140002105] = {
    id = 140002105,
    name = "你们决定立刻出发，没走多久，杂乱躁动的脚步声声逼近，只见一群小型魔物从四面八方涌来，眼中闪烁着红光，誓要将你们撕成腹中餐。"
  },
  [140002201] = {
    id = 140002201,
    name = "蜿蜒的小径尽头，伫立着几根规整的圆木，复杂的符号和图案刻画在圆木正中，发出淡蓝色的光。\n“这个魔法阵还在运转！”同伴发现了这件事，却不知道是否该继续前进。"
  },
  [140002202] = {
    id = 140002202,
    name = "你缓慢地走向魔法阵，一阵温暖的光治愈着你疲惫的身体，你感觉轻飘飘的，似乎有悠远的声音在吟唱：“停下来吧，劳累的旅人。离开是你最后的归途......”"
  },
  [140002203] = {
    id = 140002203,
    name = "谨慎起见，你们决定在此做个标记，并决定完成任务后再回来研究。\n可当你们走出森林时，一阵迷雾遮盖了一切，你们失去了标记，再也无法回到魔法阵的位置。"
  },
  [140002301] = {
    id = 140002301,
    name = "一辆破烂的推车倒在路边，有人在附近呻吟求救，你寻声找去，一个行商趴在地上，双眼猛睁，露出微光：“救救我！”\n与此同时，巨型魔物声如雷霆，仿佛灵魂都被这股力量撕扯，令人胆颤心惊。虽然还没看到那家伙的模样，但你知道，它与你也许只是一个转身的距离。"
  },
  [140002302] = {
    id = 140002302,
    name = "你立即向旁边施放了一记魔法，魔物被突如其来的巨响所吸引，你趁机窜到了行商身边，一把将他扛起逃走了。待脱险后，行商为了表示感谢，拿出许多物资让你挑选。"
  },
  [140002303] = {
    id = 140002303,
    name = "你接受了行商的好意，只拿了一些钱，行商郑重道谢后离开了。"
  },
  [140002304] = {
    id = 140002304,
    name = "你接受了行商的好意，拿取了一件宝物，行商郑重道谢后离开了。"
  },
  [140002305] = {
    id = 140002305,
    name = "你救人的时候并没有想过报酬，婉拒了他的好意。\n行商得知你们要去炎日溶洞，说知道一条水路，并告诉了你们河道停泊船只的位置。"
  },
  [140002306] = {
    id = 140002306,
    name = "没想到魔物更快扑向了那名行商，行商身亡，你们陷入了一番鏖战。"
  },
  [140002307] = {
    id = 140002307,
    name = "你及时撤离了原地，魔物在不远处吼了一声，似乎停了下来，而后再无声息。"
  },
  [140002401] = {
    id = 140002401,
    name = "“诅咒！是诅咒啊！”久居此地的人如此感叹，“一定是它发怒了，和去年一样！什么？你问我诅咒会怎么样？不，什么都不会有了，那里即将化为一片灰烬......”\n不远处是一场逆水而流的火焰盛宴，仿佛被施予了古老的魔法，水波逆向翻涌而上，炽热的火焰随着波涛燃烧，水火共舞，打破了天地间的自然法则。"
  },
  [140002402] = {
    id = 140002402,
    name = "你知道这不止是诅咒这么简单，它可能隐藏着某种深层的秘密。\n你靠近了，发现这是一个巨大的山洞洞口，逆流如同水帘般遮掩住了洞口，那能焚尽一切的火焰阻挡着你们的脚步。"
  },
  [140002403] = {
    id = 140002403,
    name = "你拦下了慌忙逃走的路人，他惊慌地告诉你：“那是禁忌！当河水倒流，火焰燃起，它会复苏，那个巨大的，古老的魔物！我才搬回来，现在又必须得搬走了......“"
  },
  [140002404] = {
    id = 140002404,
    name = "你望着那逆流的水火，心中有不祥的预感，还是远离为妙。"
  },
  [140002501] = {
    id = 140002501,
    name = "一棵倒塌的古树拦住了你们的去路，横亘在狭窄的小径上，犹如一道天然的屏障，面对旁边高耸的山壁，你思考着应对的办法。"
  },
  [140002502] = {
    id = 140002502,
    name = "古树大约有二人高的长度，你判断了一下，率先踏了上去，决定翻过去。\n“小心，那上面有毒！”你没来得及判断已经触碰了树皮，在你晕过去之前，看到了同伴中的医者担忧的目光。"
  },
  [140002503] = {
    id = 140002503,
    name = "树皮全身剧毒，一群人尝试了许久，也没办法安然无恙地从上面翻过去，只能拿起武器砍树，在你们力竭之前，你们成功地劈开了古树，挪开了一段距离。\n然而，就在你们准备继续前进的时候，突然从树洞中钻出了一只魔物。它的身体庞大而丑陋，眼中闪烁着凶恶的光芒。它发出一声怒吼，朝你们猛烈地攻击过来。"
  },
  [140002504] = {
    id = 140002504,
    name = "你拿出了朽木药剂，它能使坚固的木材松动，登山开路时时常会用到，不久，树干上传来了一阵阵细微的碎裂声，接着是更大的崩裂声。古树的树干开始逐渐解体，化为一堆堆松软的木屑，你们顺利地通过了峡谷，继续向深处前进。"
  },
  [140002601] = {
    id = 140002601,
    name = "忽然有什么红色的影子在你眼前跑过去了，你顺着红色残影的摆尾追到了角落。这是一只幼时形态的魔物，它的外貌与某种成年巨型的魔物相似，但体型更为娇小。"
  },
  [140002602] = {
    id = 140002602,
    name = "凡是源于深渊的生物，都是恶。这是所有探险者奉行的圭臬，也是他们生存的重要准则。\n遇见魔物就该毫不留情地斩杀。你们拔出武器时，小魔物似乎察觉到了危机，发出尖锐的叫声，与此同时，一阵轰鸣声从远处传来。"
  },
  [140002603] = {
    id = 140002603,
    name = "小魔物趁机喷出一道火焰拦下了去路，迎面而来的那只巨型魔物，正朝你们发出激愤的怒吼......"
  },
  [140002604] = {
    id = 140002604,
    name = "“走！”你快速地做了决定，避免了一场恶战，保存了宝贵的体力。"
  },
  [140002605] = {
    id = 140002605,
    name = "你向它伸出手，手心躺着一块火山石。\n小魔物看着你手中的火山石，缓缓靠近你，用鼻子嗅了嗅你手中的火山石，而后发出了一声欢快的叫声，朝你喷出了一团火焰，将你的头发烧断了一大片便跑走了。\n“果然......是畜生啊！”"
  },
  [140002606] = {
    id = 140002606,
    name = "这种幼时形态的魔物非常具有研究价值，你们决定将它捕获，可小魔物似乎察觉到了威胁，转身逃走了。"
  },
  [140002701] = {
    id = 140002701,
    name = "本该在地图上的路消失了，取而代之的是一个火山灰蔓延的迷宫，层层火山岩遮挡住了去往溶洞的路。你听到岩浆在涌动，你闻到大地在燃烧，你看到浓烟深处，幽幽邃邃的道路，宛如生死之间的甬道。"
  },
  [140002702] = {
    id = 140002702,
    name = "你仔细观察周围的环境，寻找可能的线索和迹象。\n在火山灰的覆盖下，你发现了一些被火山活动破坏的痕迹。\n这些痕迹证明这里曾经有一处据点，但被火山灰所淹没了。\n你们在此停留了一段时间后，继续前行。"
  },
  [140002703] = {
    id = 140002703,
    name = "你思忖片刻，指尖释放出一缕魔法，光芒如丝般游走前行，逐渐扩散到整个迷宫。\n你感受到魔法力量在岩石间碰撞，揭示出了一条隐秘的路径。\n“走这边。”确定道路后，你们很快走出了迷宫，到达了地图所指的另一处。"
  },
  [140002801] = {
    id = 140002801,
    name = "那是一把直插大地的法杖，杖柄质地非金非玉，上面布满了尘灰，杖头镶嵌的宝石，犹如一颗被囚禁的流星，被束缚在这片土地，镌刻的符文仍旧流淌着魔法力，它不知在这里伫立了多久，坐看岁月变幻，沧海桑田。"
  },
  [140002802] = {
    id = 140002802,
    name = "“这是不可多得的宝物吧？！”同伴们显得很激动，能在探险过程中找到宝物竟是这么难得的事，你同样激动地握着法杖试着将其拔了出来，但那一瞬间，仿佛有什么东西正在苏醒。\n“是魔物！！”隐藏在火山周围的魔物纷纷涌现，它们似乎受到了法杖力量的吸引，向你们袭来。"
  },
  [140002803] = {
    id = 140002803,
    name = "认出这柄法杖是深渊不可多得的宝物，同伴们跃跃欲试，你发现了法杖下方的魔法阵，试着注入了一些魔法，奇迹发生了。\n一个未知的传送门在你面前缓缓开启，你们还来不及露出震惊之色时，法杖轰然碎裂，所有的魔力都汇入了下方的魔法阵中。"
  },
  [140002804] = {
    id = 140002804,
    name = "认出这柄法杖是深渊不可多得的宝物，同伴们跃跃欲试，你围绕着法杖缓缓走动，发现法杖周围的地面上有一些细小的裂缝。这些裂缝呈现出规则的图案，与法杖上的符文相呼应。\n“这是一种封印魔法阵，也许这里镇压着未知的魔物，还是不要轻举妄动了。”"
  },
  [140002901] = {
    id = 140002901,
    name = "“冶炼台，锁钩......还有这些过期的药剂瓶子......“种种迹象来看，眼前的几间残垣断壁，并不像是一个废弃的营地或据点，反而是某个探险组织的长期基地。"
  },
  [140002902] = {
    id = 140002902,
    name = "你们在基地中进行探查，在废墟中找到了一些探险者遗留的物资，以及一本残缺的日记：\n“......战斗持续了整整一天一夜。当最后一缕光消失在地平线后，我们的基地已经不复存在了。只剩下我躲在一个角落里，眼睁睁地看着曾经熟悉的一切化为灰烬......兽潮摧毁了一切，包括我们的希望、梦想和生命......”"
  },
  [140002903] = {
    id = 140002903,
    name = "虽然基地已经废弃，但四周的防御工事依旧能发挥作用，你们长途跋涉，已是十分疲惫，正好在这里休息，在补充适量的食物与水后，你们接着上路了。"
  },
  [140002904] = {
    id = 140002904,
    name = "你们在基地中搜查了一番，并没有发现有价值的物件，看来是白费一番力气。"
  },
  [140003001] = {
    id = 140003001,
    name = "如同踏入一片被时光遗忘的幻境，无数的花朵在岩浆的滋养下绽放出绚烂的色彩，花香与火山的硫磺味交织在一起，让人感到危险又迷人。\n“天哪。那些花在动！”\n“不，是大地在移动！”\n你们站在岩石上，感觉自身正在被缓缓推入那片花海中。"
  },
  [140003002] = {
    id = 140003002,
    name = "你顺着岩石缓缓移动，空气中弥漫着一种奇异而浓重的香味，穿透了你们构筑的魔法屏障，让人饥饿难耐，你们的意识开始飘忽，真实与虚假的界限开始模糊......不知过了多久，你醒了。\n那片花海已离你们远去，虽然大家平安无事，你却仍心有余悸。"
  },
  [140003003] = {
    id = 140003003,
    name = "“这个地方很诡异，还是快走吧。”\n你皱了皱眉，直觉让你不要探究，你们纷纷离开岩石，绕道而行。"
  },
  [140003101] = {
    id = 140003101,
    name = "顺着热气来源的方向，你看到了小峡谷中被河流环绕的一片热泉。\n周围弥漫着白茫茫的蒸汽，泉水清澈碧蓝，温度适中，一股淡淡的硫磺味热浪喷薄而起。“温泉？”同伴们期待地看着你：“要试试吗？”"
  },
  [140003102] = {
    id = 140003102,
    name = "你同意了，和大家一同踏入热泉。那一刻，你感受到了前所未有的舒适与放松，缓缓放松了防备，从浑身僵硬到每一根神经舒展苏醒放松。\n“泡汤真是一项伟大的发明啊！”"
  },
  [140003103] = {
    id = 140003103,
    name = "“这些温泉......好像有魔力，应该有治愈的效果。”有魔法师勘探出泉水中的魔法力，听闻此话后，你们用水囊与药瓶装了一些温泉水，接着继续赶路。"
  },
  [140003201] = {
    id = 140003201,
    name = "走过一条细长的河流，岸边散落着越来越多由浅入深的深红色石头，这些石头散发着温热，偶有金丝附在表面，坚硬度远超过普通石头，是难得一见的矿石。"
  },
  [140003202] = {
    id = 140003202,
    name = "你们使用镐子挖到了一块矿石，却无论如何也取不出来，你们不断凿击，等矿石刚好有了些松动时候，你听到了同伴的大喊：“魔物！我们闯进它的领域了！”\n猛然，一股力量刺痛了手脚，将你们暂时定在了原地，那感觉似雷击与灼伤交汇，让你们无法撤离。"
  },
  [140003203] = {
    id = 140003203,
    name = "“这种稀有矿石，竟然无人问津......”你思绪一转，让一名队员爬上附近的岩石观察周围情况，很快那名队员连滚带爬地摔了下来。\n“魔物，很大一只！朝这边过来了！”\n你当机立断，带着众人撤离。"
  },
  [140003301] = {
    id = 140003301,
    name = "“像我这样能到这里的商人不多了。”游商披着一层防火的魔物皮甲，向你展示了他的商品，“真的不看看？错过这家可没这店了。”"
  },
  [140003302] = {
    id = 140003302,
    name = "这样的交易犹如幸运的时机，只要你稍有延误，它就将与你擦肩而过。"
  },
  [140003303] = {
    id = 140003303,
    name = "“这里人迹罕至，你怎么会到这里来？”你并不认为普通行商会出现在如此危险的地方。“风浪越大鱼越贵，富贵险中求嘛。”听了他的话，你决定看看他售卖的物品。"
  },
  [140003304] = {
    id = 140003304,
    name = "你对这位商人和他的商品并不感兴趣，摆了摆手离开了。"
  },
  [140003401] = {
    id = 140003401,
    name = "稀疏的云层，焦灼的大地。你站在那里，目光锁定在一群逃窜的魔物身上。\n它们狂野而暴躁，仿佛是被无形的恐惧所驱使，慌乱地在火山灰中穿梭。\n是什么样的危险，让这些魔物都感到畏惧？"
  },
  [140003402] = {
    id = 140003402,
    name = "通过溶洞，是你无可避免的任务，你们必须继续前行。\n靠近溶洞时候，你感到地面在微微震动，一道巨大的影子尘雾中显现，现在还来得及做决定。"
  },
  [140003403] = {
    id = 140003403,
    name = "一时间地动山摇，烈火冲天，火山将溶洞彻底掩埋。那些逃窜的魔物，被火山灰和岩浆所吞噬，你们仓皇退遁，却见到一只魔物拦在跟前，发出了震耳欲聋的咆哮！"
  },
  [140003404] = {
    id = 140003404,
    name = "面对无法匹敌的力量，你并没有试图去挑战它，而是选择了离开。下一刻，伴随着震耳欲聋的咆哮声，地动山摇，烈火冲天，火山将溶洞彻底掩埋。\n那些逃窜的魔物，连同你刚刚消灭的敌人，都被火山灰和岩浆所吞噬，你们躲过了一场惊天浩劫。"
  },
  [140003405] = {
    id = 140003405,
    name = "这些魔物并非因为你们而慌乱逃窜。你决定暂时避开这群魔物，就在这时，你遇到了一个探险者。\n“兽潮来了，快走！”他急促地告诉你们，必须尽快撤离。"
  },
  [140003406] = {
    id = 140003406,
    name = "你决定原地等待，让魔物群先过去，然后趁机进入溶洞，只要能够准确地把握时机，就能避免与魔物正面冲突。\n“......好吧，愿希望女神护佑你。”探险者复杂地看了你一眼快速离开了。\n不久后，巨大的火山灰和岩浆冲天而起，形成一道壮观的景象。你感到一股强烈的热浪扑面而来，同时朝你本来的还有铺天盖地的魔物群。"
  },
  [140003407] = {
    id = 140003407,
    name = "你与探险者交流得知，他从火山另一侧的溶洞探险归来，亲眼目睹了火山即将爆发的迹象。他劝你们跟随他一起撤退。你们迅速撤离，远离火山的方向。\n没多久，伴随着震耳欲聋的咆哮声，地动山摇，烈火冲天，火山将溶洞彻底掩埋。\n你们躲过了一场惊天浩劫。"
  },
  [140003408] = {
    id = 140003408,
    name = "你决定避开它们，选择绕行山林，却意外地发现了一个探险者居住的小屋，小屋外墙上挂着一些探险者的装备和工具，杂乱无序。\n“我正为这事发愁，你们来得正好！“原来他是去年兽潮的幸存者，而兽潮实际上是被巨型魔物所驱使，魔物释放的能量也同时提前引发了火山的暴动。\n“只要能够杀掉那只巨型魔物，就有可能延缓甚至阻止火山的爆发！”"
  },
  [140003409] = {
    id = 140003409,
    name = "你决定加入他的行动。\n“太好了，我来为你们做向导！这个地方我最熟了！能直捣黄龙，杀他个神不知鬼不觉！”探险者指出了巨型魔物的习性和弱点，你们悄然绕后，布置陷阱与魔法阵，在它发难之前，便将其快速斩杀！"
  },
  [140003410] = {
    id = 140003410,
    name = "你是一个“安全至上”的人，不仅对你自己，还要对与你同行的同伴们负责。\n你拒绝了探险者的提议，他显得有些失望，“那你们走吧，我不走了，我要去战场，逃避无法阻止灾难降临。”\n你们撤离后，伴随着震耳欲聋的咆哮声，地动山摇，烈火冲天，火山将溶洞彻底掩埋。你们躲过了一场惊天浩劫。"
  },
  [140003501] = {
    id = 140003501,
    name = "黑暗中，你们被一群红色的眼睛注视着。它们密密麻麻地挂在枯枝树梢，无数的影子在地面晃动。翅膀扑扇卷着腥风向你们发起了猛烈的攻击。"
  },
  [140003502] = {
    id = 140003502,
    name = "你们迅速组成防御阵型，抵挡住了魔物的攻击，魔物久攻不下，纷纷退去。"
  },
  [140003503] = {
    id = 140003503,
    name = "你树立起一道魔法屏障，同时挥出了一束光芒，照彻大地。\n那一刻，箭矢与魔法齐飞，魔物们纷纷撞向光明。"
  },
  [140003504] = {
    id = 140003504,
    name = "为了所有人的安全，你迅速组织撤离，魔物紧追了一会儿便被你们彻底甩掉。"
  },
  [140003601] = {
    id = 140003601,
    name = "你们走了很长的路，是时候休息了，在清点人数时候，竟然发现多了一个。\n盯着一个个熟悉的脸，一种不安蔓延到你的心间，是谁多余了呢？"
  },
  [140003602] = {
    id = 140003602,
    name = "你挨个探查，很快就引起了其中一个队员的注意，你还没来得及动手，那“队员”扒开了自己的皮，快速地溜走了，留下了一堆粗糙的甲壳。\n只是它是什么时候混在大家中间的呢？"
  },
  [140003603] = {
    id = 140003603,
    name = "你将这件事告诉后勤管理员，他瞪大了眼睛，观察了半晌四周的同伴，语气生硬地说：“队长，你看错了吧？数量没错啊。”\n你盯着他，平静地拿出了武器，“是没错，但你忘记了数你自己。”\n“管理员”发出了奇怪的笑声，肢体随即开始扭曲，不等它完成异变，你便一剑将它解决。"
  },
  [140003701] = {
    id = 140003701,
    name = "由于火山喷发的缘故，即使相隔遥远，瞭望塔也受到了损害，变得歪歪斜斜。\n它曾兼备着给船只指引的灯塔功能，也许能向你们提供情报和线索呢？"
  },
  [140003702] = {
    id = 140003702,
    name = "你们轻手轻脚地走入瞭望塔内部，发现这里早已空了，看来在发生危险之前，这里的人早已撤离。"
  },
  [140003703] = {
    id = 140003703,
    name = "你们走向塔身周围，发现周围竟然有许多魔物与人类骸骨，它们都被火山灰掩埋了半身。\n一把长剑插在地上，有队员惊叹它精致的铸造工艺，将它拔了出来。\n然而下一刻，你们发现身边的塔楼正以缓慢的速度倒了下去，队员们急速撤退，也无可避免地受到了擦伤。"
  },
  [140003704] = {
    id = 140003704,
    name = "君子不立危墙之下，这座即将倒塌的建筑，还是离远一点比较好。"
  },
  [140003801] = {
    id = 140003801,
    name = "那是一朵从贫瘠的岩石夹缝里长出的花，状似球形，鲜艳夺目。能在如此恶劣条件下生长，它已然是个奇迹。"
  },
  [140003802] = {
    id = 140003802,
    name = "这种花曾被公会和黑市高价收购，你并不想错失它，正打算伸手摘取时，一只隐匿在它身边的魔物慢慢显形。"
  },
  [140003803] = {
    id = 140003803,
    name = "你对这朵花顽强的生命力报以敬意，静静注视了一会儿后便离开了。"
  },
  [140003901] = {
    id = 140003901,
    name = "“我还以为我死定了。”路人捧着你们给的水囊喝了一大口，“为了感谢你们把我从魔物嘴里拽出来，我好心提醒你们一句，你们要去的地方已经被彻底摧毁了。”\n在得知他曾是一名向导以后，你也许能从他口中问出想要的答案。"
  },
  [140003902] = {
    id = 140003902,
    name = "你向他询问新的道路，他叹息着，趴在地上为你们手绘了一张地图。\n“既然你们这么执着不死心，那就去看看吧。这是我刚从地下据点来时走的路，还算安全，祝你们好运。”"
  },
  [140003903] = {
    id = 140003903,
    name = "“哦，我知道了，你们也跟那些探险者一样，想去看看有没有什么好东西吧？”路人一派了然于胸的作态，“行吧，我给你们带路，能不能进去就看你们的运气啦。”\n在此人的指引下，你们到达了一片废墟。你经过观察分析，发现了可通行的道路和一些物资。"
  },
  [140003904] = {
    id = 140003904,
    name = "“哦，我知道了，你们也跟那些探险者一样，想去看看有没有什么好东西吧？”路人一派了然于胸的作态，“行吧，我给你们带路，能不能进去就看你们的运气啦。”\n在此人的指引下，你们到达了一片废墟。看来的确如他所说，这里已经彻底被摧毁了。"
  },
  [140004001] = {
    id = 140004001,
    name = "你在枯林里发现了一个奇怪的图案，那上方还似有若无地传出了魔力的波动，你不知道它有什么效用，但也无疑是一项艰难的选择。"
  },
  [140004002] = {
    id = 140004002,
    name = "你试探性地注入了一些魔法，没想到触发了魔法阵的关键。\n眼前的图案越来越大，瞬间将你们所有人笼罩，仿佛进入了一个奇怪的钢铁洞穴，你们看到身着奇装异服的人们来回忙碌，却无法触碰他们。\n“这是残留的幻象。”\n这些人是谁？他们说的各类词汇让你们困惑，还没仔细看得更多，一道排斥的力量将你们推了出来，那个图案的魔力波动停止，接着渐渐消失了。"
  },
  [140004003] = {
    id = 140004003,
    name = "不管是什么都与任务无关，不是吗？那就继续出发吧。"
  },
  [140004101] = {
    id = 140004101,
    name = "由于许多地方都被破坏，迂回路线比想象的更长。\n你们走了很长的路，已经到了必须休息的时刻。在点燃篝火，队友们都鼾声入梦时，你也慢慢地放松自己。"
  },
  [140004102] = {
    id = 140004102,
    name = "休息是对身体上某些损失的弥补，包括任何人。\n你放松自己沉入睡眠，以精神饱满的状态醒来，迎接未知的未来。"
  },
  [140004201] = {
    id = 140004201,
    name = "那是一只巨型魔物的骸骨，半个身体陷在火山积岩中。\n岩石因年久日深已被侵蚀得斑驳陆离，而魔物的骸骨却依旧坚硬如钢，散发着淡淡的魔力。\n当你们靠近它时，竟然还发现其下方隐藏着一颗晶莹剔透的水晶。"
  },
  [140004202] = {
    id = 140004202,
    name = "你们想尽办法终于取下了一截骸骨，它几乎可以直接作为武器使用，在队员兴奋地拿着坚骨的时候，遭到了其他人的提醒：“别大意！这些浊炁还没净化！”"
  },
  [140004203] = {
    id = 140004203,
    name = "由于骸骨太过坚固，普通的工具和魔法都难以轻易破开。\n经过一番努力，你们终于成功地将水晶从骸骨下方挖出，在它得见天日的那一瞬间，一只魔物从水晶里破壳而出。\n“哦，天哪，这是魔物的巢穴！”"
  },
  [140004204] = {
    id = 140004204,
    name = "你观察了一会儿，并没有发现什么有用信息，稍作休整后便离开了。"
  },
  [140004301] = {
    id = 140004301,
    name = "码头搁浅着一艘巨型船只，船身布满了岁月的痕迹和伤痕，面对这样的庞然大物，你们不可能错过它所留下的线索。"
  },
  [140004302] = {
    id = 140004302,
    name = "你们不止找到了没过期的药剂和实用的武器，还发现了关于地下据点的地图。\n它标记着码头深处，曾有一处据点所在地。"
  },
  [140004303] = {
    id = 140004303,
    name = "你们走向船底仓库，里面寂静一片。\n下一刻，你的危机感猛然爆发，在门扉打开的那一刹，一头魔物窜出。幸好你已做好准备，一剑将其击毙。"
  },
  [140004304] = {
    id = 140004304,
    name = "甲板上残留了许多魔物的骨骸和人类的武器，看来那场兽潮中，人类已经为此拼尽了全力。"
  },
  [140004401] = {
    id = 140004401,
    name = "你听到附近有什么痛苦地在呻吟，像幼儿在哭泣一般。“小孩子？！”你们走近一看，竟然是一个身披草叶，蜷缩在树下的幼童，祂不断发出哭泣的声音。"
  },
  [140004402] = {
    id = 140004402,
    name = "当你们正打算扶起祂时候，那张幼小的脸忽然转过了头，仿佛无数恐怖场景那样，露出了没有五官，只有如枯萎花朵般的尖锐口器，朝你扑面而来！"
  },
  [140004403] = {
    id = 140004403,
    name = "你们停在原地，无声无息地等了几个呼吸的时间，那张幼小的脸抬起了头，露出了没有五官，只有如枯萎花朵般的尖锐口器，它发出嘶叫的声音，沿着上树藏匿了起来。"
  },
  [140004501] = {
    id = 140004501,
    name = "“这就是因为去年那场兽潮被迫废弃的码头吗......好可惜啊......”队员们纷纷叹息着。\n而今，这座码头仍然保留着一些残破不堪的设施和船只残骸，这些遗迹见证了曾经的繁忙，连接着溶洞与外界的世界。"
  },
  [140004502] = {
    id = 140004502,
    name = "那些船只在远处搁浅着，本应是能行船的大河如今只剩大大小小的滩涂，你们在其中搜寻了一番，除了几头潜伏的魔物，并没有其他发现。"
  },
  [140004503] = {
    id = 140004503,
    name = "栈桥上有一处倒塌的路牌，你抹去码头上路牌的灰尘，上面写着“炎日据点——沿河向北”。\n“那就是目的地......可这里已经没有人了。”有队员疑惑着，“真的可以在那里找到任务目标人物吗？”"
  },
  [140004504] = {
    id = 140004504,
    name = "你们确认目的地就在前方，加快脚步继续走向既定的路。"
  },
  [140004601] = {
    id = 140004601,
    name = "“你们是从火山过来的？不可思议！”\n你们遇到了一个独行探险者，他对刚刚发生的火山喷发很感兴趣，想知道那边到底发生了什么，而你们打算去哪里。"
  },
  [140004602] = {
    id = 140004602,
    name = "对方感谢你的情报，并告诉了你们要去的地下据点早已荒废，不会再有人了。\n但到达目的地是组织许下的承诺，在那之前，你们之间没有人会放弃。"
  },
  [140004603] = {
    id = 140004603,
    name = "你告诉了他火山的凶险，随便告诉了他一个目的地。\n他听完后心有余悸，本打算去火山，现在决定改变计划，并随手赠了你一点物资。\n“既然不去了，那这些东西也用不着了，你们带走吧。”"
  },
  [140004604] = {
    id = 140004604,
    name = "他的目的性不明，你只说他看错了，反而问他最近的圈落在哪儿。\n他愣了愣，给你指了一个方向，那正是去往地下据点的路，你对他表示感谢，欣然前往。"
  },
  [140004701] = {
    id = 140004701,
    name = "“找到了！我们离目标还剩一步！”队员兴奋地指着墙上的地图。\n你们整理起了屋内的物品，离开之前，你发现了一个小箱子，里面有手写的笔记和散碎的石板，笔记上的字迹已经模糊不清，但依稀可以辨认出一些文字。"
  },
  [140004702] = {
    id = 140004702,
    name = "你敲了敲石板，石板碎裂，露出了里面封存的宝石，真是一笔意外之财，谁也没想到会将宝石封在石板里。"
  },
  [140004703] = {
    id = 140004703,
    name = "“这是一本记录笔记。”有队员拼出了笔记里的文字，“暗域......释放浊炁......难道这里曾经在做暗域相关的研究，但这本笔记记载得也太简略了。“\n你带走了这本笔记，虽然它看起来没有什么有用的消息。"
  },
  [140004801] = {
    id = 140004801,
    name = "眼前的河滩本是码头旁的一支河流，而今却一片灰蒙蒙的，火山灰的细腻颗粒均匀地散布在地面上，整个河滩呈现出一种暗淡而神秘的色调。你们在此驻扎营地，夜幕降临时，天空一颗发光物坠落大地。\n“快看，是流星！”\n“瞎说，深渊怎么会有流星？”"
  },
  [140004802] = {
    id = 140004802,
    name = "随着你们逐渐接近，确认了那个发光体并非流星，而是一个闪烁着神秘光芒的物体。\n它静静地躺在地面上，不规则的表面镶嵌着许多闪烁的晶体、\n当你们试图触摸这个神秘的物体时，它的周围散发着一股奇异的能量，让你们无法靠近。"
  },
  [140004803] = {
    id = 140004803,
    name = "你们花了很大的力气将它从地里刨出来，一群魔物已经悄然靠近，他们发出了和晶体一样的光芒。"
  },
  [140004804] = {
    id = 140004804,
    name = "你没有兴趣去看所谓的流星，应该利用这个时间让队员们好好睡觉，养足精神。"
  },
  [140004901] = {
    id = 140004901,
    name = "一场突如其来的风暴猛然袭至，队员狼狈地惊声呼叫：“风暴！快找地方躲避！”"
  },
  [140004902] = {
    id = 140004902,
    name = "船舱内部昏暗而潮湿，空气中弥漫着一种腐朽的气息。\n你们点燃火把，照亮了周围的环境。船舱内部散落着一些破损的家具和腐烂的货物，显然已经很久没有人来过了。"
  },
  [140004903] = {
    id = 140004903,
    name = "你们找到了地下舱室，随着风暴的接近，船身开始剧烈摇晃，船舱内不时传来物体碰撞的声音，一些原本固定在船舱内的玻璃瓶开始松动，眼看就要掉落下来。"
  },
  [140004904] = {
    id = 140004904,
    name = "你下意识伸手将那个“玻璃瓶”接了下来，里面有一颗拇指大的珠子，它光滑而温润，让人一看就知道是难得的宝物。"
  },
  [140004905] = {
    id = 140004905,
    name = "你认识玻璃瓶里的珠子，它是忆梦珠，能短暂记录和呈现当事人的回忆的一次性宝物，也许记载了某个人不为世事所知的故事。只是现在并不是对故事感兴趣的时候，你带上它离开了船只，继续前往地下据点。"
  },
  [140004906] = {
    id = 140004906,
    name = "掉落的物品碎了一地，你贴紧了船边抓紧室内栏杆。在船舱里度过了一段时间后，风暴终于逐渐减弱，你们继续前往地下据点。"
  },
  [140005001] = {
    id = 140005001,
    name = "前方是一片无人踏入的沼泽，而在沼泽之中，巨大的鲸骨横跨在两处安全区之间，也许是先前探险者留下的温柔。"
  },
  [140005002] = {
    id = 140005002,
    name = "你尝试着走了上去，没走两步，便听到咔嚓的声音——\n巨骨断裂了。\n与此同时，沼泽下有魔物正在苏醒，你趁它没有完全倾倒之前，返回了安全地带。\n这时，那些魔物已统统浮出了水面。"
  },
  [140005003] = {
    id = 140005003,
    name = "你发现这根巨大的骨头是某类鱼形动物的骸骨，它已趋近腐烂，无法承载任何重量。"
  },
  [140005101] = {
    id = 140005101,
    name = "地下据点比你们想象的宽大，街道石壁上还有各式各样的符号，每隔一段距离，就有一个熟悉的标志：“这是火魔法吧，这是酒馆......这是药店......”"
  },
  [140005102] = {
    id = 140005102,
    name = "你将手放在这些符号上，忽然感应到魔法波动，一道墙发出轰响，竟然是一个隐藏的石门。\n石门之后是一间空旷的房间，你正打算离开时，感觉到被什么锁定了。\n抬眼的一瞬，你看到天花板上的魔物朝你袭来！"
  },
  [140005103] = {
    id = 140005103,
    name = "不用在意这些符号，通道尽头会有更重要的目标。"
  },
  [140005201] = {
    id = 140005201,
    name = "有什么声音从附近传了出来，那是一首流行在大陆的小调，是吟游诗人将它广泛传唱。有队员惊得跳了起来：“据点里还有人！”\n那调子呕哑嘲哳，像是坏掉的竖琴弹奏，呲呲声让人感到诡异。"
  },
  [140005202] = {
    id = 140005202,
    name = "哪怕只是万分之一的可能，你也想试一试拯救。\n可惜事与愿违，从废墟一跃而出的，是一只张牙舞爪的魔物。"
  },
  [140005203] = {
    id = 140005203,
    name = "你察觉到声音的异常，驻足了片刻。\n过了一会儿那声音发出尖锐的“呲”声，你与队友相视一眼，明白了在那废墟的东西，是一只正努力模仿人类发音的魔物，而此时那魔物正痛苦地挣扎，过了许久没了声息。"
  },
  [140005301] = {
    id = 140005301,
    name = "“那边该怎么过去？”队员站在你身边，伸手指向河对岸，河水漆黑，深不见底，而悬空之中，漂浮着几块木板，似乎被什么魔法和机关控制着。"
  },
  [140005302] = {
    id = 140005302,
    name = "你们在四处找控制木板的器具，发现在一只魔物尸体下正压着一个轮盘，在转动它后，那些木板缓缓归位，形成了完整的浮空桥。\n“这......真的能上去吗？”"
  },
  [140005303] = {
    id = 140005303,
    name = "你们借助河面上的魔法波动，将一名队员送上悬浮木板上，他以极强的跳跃力落到另一个木板上，以此类推，过了许久，他才到达了对岸。\n幸运的是，他在对岸找到了机关，那些木板缓缓归位，形成了完整的浮空桥。"
  },
  [140005401] = {
    id = 140005401,
    name = "地下据点的广场并不是完全黑暗的，灯柱上的萤石还散发着微光，广场上的石碑横倒在地，上方的文字倒扣着。\n周围寂静如死，唯有你们的到来才添了些人气。"
  },
  [140005402] = {
    id = 140005402,
    name = "你们齐心协力将石碑翻了过来，上面深深刻着一行字，此刻已被凝固的鲜血覆盖了痕迹：\n“当所有的火种暗淡无光，当所有的法则崩坏毁灭，我也会留在至深至暗的深渊寻找最后的光......”"
  },
  [140005403] = {
    id = 140005403,
    name = "这不过是每个据点都存在的指路石碑，倒就倒了吧。"
  },
  [140005501] = {
    id = 140005501,
    name = "前方有一摊散落的物资，它们布满了尘土，在地上无人问津，不知什么魔物的尸体在附近，已经发出了腐烂的臭味。"
  },
  [140005502] = {
    id = 140005502,
    name = "只是腐烂的食物而已，也许有其他能用的东西呢？\n你上前掀开了一个盒子，蛰伏在其中的魔物向你发起了攻击。"
  },
  [140005503] = {
    id = 140005503,
    name = "你们的物资还很充足，没有必要去捡垃圾。"
  },
  [140005601] = {
    id = 140005601,
    name = "推开房屋的大门，一股腐朽味扑面而来直冲鼻腔。\n这是一间荒废的商店，货架上已经没有了商品，但其他设施有条不紊地摆放着，你看见后方有一排书架上还摆满了书，上面有干瘪的蛆虫趴在上方，看样子已经因温度过高被烧死了。"
  },
  [140005602] = {
    id = 140005602,
    name = "你继续推开里面的门走了进去，这是一个极度简约的卧室，卧室的房间中，还有主人留下的东西，你拿起了其中一件收藏品，发现里面还有魔法力波动。"
  },
  [140005603] = {
    id = 140005603,
    name = "你的视线从书架上扫过，一排排书本排列有序，你翻看了好几本书，讲述的都这座炎日据点的建造过程。\n“是没来得及搬走吗？”\n“据点毁灭的时候，也许有比它们更值得带走的东西。”"
  },
  [140005604] = {
    id = 140005604,
    name = "你继续推开里面的门走了进去，这是一个极度简约的卧室，卧室的房间中，还有主人留下的东西，你正准备仔细查看，腐朽的房屋开始坍塌，你急忙退了出来。"
  },
  [140005701] = {
    id = 140005701,
    name = "你们找到据点中最大的房间，看起来是一处图书馆，其中许多书已经被搬空了。那些人，都已经撤离了吧。"
  },
  [140005702] = {
    id = 140005702,
    name = "你想到目标任务是学者，这里应该是他常来的地方，也许能留下什么线索。\n“咦，这是一封信？”队员从垃圾桶里抓出来了一张揉成一团的纸：“亲爱的格温多琳......没了。格温多琳，听起来是个女人的名字。“\n可惜只有一个开头，这封信便被废弃了。"
  },
  [140005703] = {
    id = 140005703,
    name = "这里一眼望尽，没什么可看的了，走吧。"
  },
  [140005801] = {
    id = 140005801,
    name = "你们就地夜宿，一阵阴风袭来，篝火熄灭，引起了全员的警醒，你们望着从地底飘上来的人影，仿若陷入了一场深沉地幻觉。"
  },
  [140005802] = {
    id = 140005802,
    name = "一声令下，队员们拿出武器，挥散了眼前的人影，什么都没有发生。\n众人惊觉虚惊一场，重新点燃了篝火，那夜却无人入睡。"
  },
  [140005803] = {
    id = 140005803,
    name = "“幽灵”飘到了你们的身前，撞向了你身边呆愣的魔法师。\n你瞬间拉开魔法师，那一刹那，有什么似乎穿过了你的身体，是走马观花的回忆，又像琉璃碎片的念想，最终汇聚成了一个名字：\n“阿列科。”"
  },
  [140005901] = {
    id = 140005901,
    name = "你们走了好几条街，却发现了曾经走过商铺前刻下的标记。“我们又回到了原点。”"
  },
  [140005902] = {
    id = 140005902,
    name = "这个迷阵布阵已久，魔法波动都十分微弱了，你召集了几名魔法师，耗费了不少魔法，终于破除了魔法阵，离开了迷宫。"
  },
  [140005903] = {
    id = 140005903,
    name = "你们找了很久，也没有找到迷宫的出口。最后被迫就地住了一晚，第二日才发现了角落的异常，打破出口离开。"
  },
  [140006001] = {
    id = 140006001,
    name = "“那些是......”眼前的景象震惊了你们所有人。层层叠叠的魔物尸体整齐地排在地上，叠了一层又一层，宛如一座小山。\n“这是怎么做到的？”有队员指着地下若隐若现的光，“是魔法阵！”"
  },
  [140006002] = {
    id = 140006002,
    name = "你缓缓走到魔法阵旁边，感到这个阵法还在持续运行着，运行它的来源远在地底，它穿丝拉网地吸收着每一只魔物的能量。\n能用如此庞大的魔法阵将上百只魔物绞杀，制成魔法阵的人一定有天纵之才。"
  },
  [140006003] = {
    id = 140006003,
    name = "这些尸体里没有人类，多一事不如少一事，继续去看看别的地方。"
  },
  [140006101] = {
    id = 140006101,
    name = "在寻找线索的途中，你看到四周的黑雾，都是魔物吐出的糟心玩意儿，你知道，你们已经被包围了。"
  },
  [140006102] = {
    id = 140006102,
    name = "你知道，接下来是一场艰难的战斗，但你们必须是胜利者。"
  },
  [140006103] = {
    id = 140006103,
    name = "你们停在原地组成了防御阵法，等着那群魔物一个个送上门来。没费太多力气，你们便将魔物斩杀殆尽。"
  },
  [140006201] = {
    id = 140006201,
    name = "你们穿越一片密林，一阵簌簌声不断从空中逼近，接着一片黑影由天而降！\n“是魔物！准备作战！”你果断下令。\n“不，请等一下，让我来！”旁边突然出现的魔法师跑了过来。"
  },
  [140006202] = {
    id = 140006202,
    name = "你无法信任来路不明的魔法师，让队友准备战斗。\n下一刻，铺天盖地的魔物已经到达你们眼前。"
  },
  [140006203] = {
    id = 140006203,
    name = "你看魔法师笃定自信的神情，或许他真的有什么解决的办法。\n只看见他从衣中拿出了一根细管，按下某个机关后，细管发出一声啸叫。\n同时，一道魔法光束击中魔物群，那些魔物在天上相互乱撞，最后如下雨般砸在地上。\n一场危机就这么轻易地过去了。"
  },
  [140006301] = {
    id = 140006301,
    name = "崖壁高耸入云，几乎无法攀爬，这是条近路，但如今大家的体力已经消耗得差不多了。"
  },
  [140006302] = {
    id = 140006302,
    name = "你们找来了绳索和固定器，制定了详细的攀爬计划。\n由几个体力和技巧都较好的队员担任先锋，负责开辟攀爬路线和固定绳索，其他人则提供支援。\n虽说有队员因为碎石划伤，但最终你们成功翻过了悬崖，极大缩短了回程的时间。"
  },
  [140006303] = {
    id = 140006303,
    name = "一路人困马乏，你们决定不再冒险，寻找其他路，但没想到四周都是茂密的森林和崎岖的山地，你们绕了好几天的路，才翻过了那座悬崖。"
  },
  [140006401] = {
    id = 140006401,
    name = "行至夜晚，前方有一簇火光在远处闪烁。\n“是篝火，队长！”\n你们打算接近那团篝火，却惊奇地发现，无论我们如何努力，那团篝火似乎总是保持在同一个距离，既不远离也不靠近。\n队员挠头不解：“难道是我看错了？”"
  },
  [140006402] = {
    id = 140006402,
    name = "行路一天你们已经耗尽了体力，你察觉到事情并不简单，决定就地扎营以逸待劳。\n果然到了半夜，那簇火光突然逼近，散成了十余只魔物发动了夜袭。"
  },
  [140006403] = {
    id = 140006403,
    name = "你猜想你们陷入了某种迷宫或者幻觉之中，为了寻找出路，你们尝试改变方向，甚至倒退绕道，但那团篝火始终如一地在你们前方闪烁，直到天明才消失，你们只能拖着疲惫的身体继续前行。"
  },
  [140006501] = {
    id = 140006501,
    name = "“好东西，要吗？”鬼鬼祟祟的男人拿着一颗石头在你面前晃荡，“这可是我冒死从火山脚下拿到的，市面上可值这个数，今天便宜你了！”\n队友看了你一眼：这是能随便拿到的吗？"
  },
  [140006502] = {
    id = 140006502,
    name = "你们三两下制服了那个男人，他不断地求饶，说要将石头送给你们，却趁你们不注意的时候，扔了一个烟雾弹逃走了。"
  },
  [140006503] = {
    id = 140006503,
    name = "你看了下那块石头，之前的确在火山脚下见过，你揭穿了男人的谎言，以便宜的价格买了下来。\n男人悻悻地走了，你拿着石头，感应到了其中诡异的魔力。"
  },
  [140006601] = {
    id = 140006601,
    name = "本来有路的前方被折断的树枝和破损的灌木阻挡了，地面上有一些凌乱的痕迹，却不像任何魔物留下的。"
  },
  [140006602] = {
    id = 140006602,
    name = "兵来将挡水来土掩，以你们团队的实力，不必畏畏缩缩。\n果然如你所料，前方出现了一只巨型魔物。"
  },
  [140006603] = {
    id = 140006603,
    name = "谨慎起见，先遣队到周围探查了一圈，果然发现了附近的巨型魔物的巢穴。\n那些痕迹都是魔物拖拽食物留下的，你们绕开了魔物，避开了这次无谓的战斗。"
  },
  [140006701] = {
    id = 140006701,
    name = "你们从魔物嘴里救下了一名独行的魔法师，他拿着一颗精致的收藏品，向你表达谢意。"
  },
  [140006702] = {
    id = 140006702,
    name = "你拿到了那个收藏品，发现身体突然变得很虚弱。“糟了，那家伙竟然把诅咒转移给你了！”\n你废了不少的力气才消除了魔法的影响，始终觉得心底空无，好像失去了什么。"
  },
  [140006703] = {
    id = 140006703,
    name = "你回绝了他的好意，他却骂骂咧咧地离开了。"
  },
  [130011001] = {
    id = 130011001,
    name = "“已经搜遍了整个据点，只有那里没有看过了。”队员站在你身边，伸手指向河对岸的一栋建筑。"
  },
  [130011002] = {
    id = 130011002,
    name = "你们走向那唯一的一栋石屋，令人惊讶的是，这栋石屋并没有门窗，就像一个砖砌的雕塑，伫立在孤岛之上。"
  },
  [130011003] = {
    id = 130011003,
    name = "门边有一块镶嵌在墙壁上的石板，随着魔法的施展，门上的符文开始发光，并逐渐连接起来，激活了一个完整的魔法阵。"
  },
  [130011004] = {
    id = 130011004,
    name = "“你们......是谁？”空旷的石屋中，一位老人推着轮椅而出，双方都露出了惊讶的神色。这是你在据点看到的第一个人。"
  },
  [130011005] = {
    id = 130011005,
    name = "“没想到在死前还能再见到探险者......是的，我就是阿列科。”"
  },
  [130011006] = {
    id = 130011006,
    name = "你们在说明原因后，将盒子与一封信交给了他。"
  },
  [130011007] = {
    id = 130011007,
    name = "他展开信的手变得越来越颤抖，水痕从眼眶旁纵横的沟壑滑落，他伸手抱紧手中的盒子，下巴颤抖地放在上面，竭力地忍耐着，念出了那个名字：“格温多琳......”"
  },
  [130011008] = {
    id = 130011008,
    name = "隔了许久，他才抬起了头，“谢谢......你们走吧。”他转过了轮椅，缓缓进入了石屋深处。"
  },
  [130011009] = {
    id = 130011009,
    name = "既然任务已经完成，你们也没有了逗留的理由，老人给了你们丰厚的报酬，你们离开石屋后，石门轰然落下，阻断了你们的视线。"
  },
  [130011010] = {
    id = 130011010,
    name = "这座没有门窗的石屋，俨然就像他为自己选定的坟墓。"
  },
  [130011011] = {
    id = 130011011,
    name = "你们离开石屋后，石屋里一阵沉静。"
  },
  [130011012] = {
    id = 130011012,
    name = "过了很久，阿列科才将盒子珍而重之地打开，里面是一只材质迥异的竖笛。"
  },
  [130011013] = {
    id = 130011013,
    name = "竖笛上的符文微亮，清幽的旋律无风自响，他陷入了许久前的回忆——"
  },
  [130011014] = {
    id = 130011014,
    name = "“这首曲子，是你创作的？”"
  },
  [130011015] = {
    id = 130011015,
    name = "“嗯，送给你的，生日快乐，小琳。”"
  },
  [130011016] = {
    id = 130011016,
    name = "“这是我的生日礼物？”"
  },
  [130011017] = {
    id = 130011017,
    name = "“当然不止，只是一首曲子怎么够。还有这个，我用深渊的材料打磨的竖笛。”"
  },
  [130011018] = {
    id = 130011018,
    name = "“深渊？”"
  },
  [130011019] = {
    id = 130011019,
    name = "“对！我这次跟他们去深渊，发现那里和大陆完全不一样！小琳，我第一次知道世界原来这么大，以后我也想......”"
  },
  [130011020] = {
    id = 130011020,
    name = "“阿列科。”"
  },
  [130011021] = {
    id = 130011021,
    name = "“什么？”"
  },
  [130011022] = {
    id = 130011022,
    name = "“谢谢，你的礼物。”"
  },
  [130011023] = {id = 130011023, name = "......"},
  [130011024] = {
    id = 130011024,
    name = "“小琳......”老人轻抚着竖笛，喃喃念着那个名字，“你说的对，我的确是个笨蛋......”"
  },
  [130011025] = {
    id = 130011025,
    name = "“我不该躲在这里，让你以为我死了，是我的愚蠢，错过了与你最后的告别......”"
  },
  [130011026] = {
    id = 130011026,
    name = "“小琳，你会原谅我吗？”"
  },
  [130011027] = {
    id = 130011027,
    name = "老人拿起了一块颜色诡异的能量石，放入了魔法阵的凹槽中。"
  },
  [130011028] = {
    id = 130011028,
    name = "明亮而耀眼的魔法阵在原地豁然亮起，整个据点的光破土而出，从地面逐次点亮如白昼。"
  },
  [130011029] = {id = 130011029, name = "......"},
  [130011030] = {
    id = 130011030,
    name = "“队长！快看那边！”"
  },
  [130011031] = {
    id = 130011031,
    name = "远处地下据点的方向，如星辰最后爆发的璀璨，光亮照彻了深渊。"
  },
  [130011032] = {
    id = 130011032,
    name = "你及时地捂住了眼，轰鸣和地动同时从脚下传来。"
  },
  [130011033] = {
    id = 130011033,
    name = "“火山要爆发了！快走！”"
  },
  [130011034] = {
    id = 130011034,
    name = "数不清的魔物从火山底部冲了出来，它们像蚁群一样逃命，滚烫的岩浆迸发而出，它们挣扎着、颤抖着、发出悲鸣，然后湮灭。"
  },
  [130011035] = {
    id = 130011035,
    name = "熔岩改道扑向了据点的方向，滚滚浓烟朝那团光压了过去，明亮的据点逐渐黯淡。"
  },
  [130011036] = {id = 130011036, name = "......"},
  [130011037] = {
    id = 130011037,
    name = "“阿列科，阿列科......”"
  },
  [130011038] = {
    id = 130011038,
    name = "仿佛听到了少女的呼唤，老人微微睁开眼，好像透过熊熊火光看到了触手可及的故乡，还有曾遗落天涯的那个人。"
  },
  [130011039] = {
    id = 130011039,
    name = "深渊的尽头是黑暗，它无所谓人类的牺牲，哪怕是以生命力为代价的闪耀，也只能照亮一瞬间。"
  },
  [130011040] = {
    id = 130011040,
    name = "只剩下了无尽的孤独。"
  },
  [130011041] = {
    id = 130011041,
    name = "最后一刻，他微笑着说：“格温多琳，我来见你了......”"
  },
  [130012001] = {
    id = 130012001,
    name = "你们找到了据点的另一个出口。"
  },
  [130012002] = {
    id = 130012002,
    name = "踏上地面时，一片荒凉的废墟映入眼帘，冷却后的岩浆如同黑色的河流，将废墟分割成了不同的区域，而地势较高的山外，竟然有一片青翠的山坡。"
  },
  [130012003] = {
    id = 130012003,
    name = "黄土与翠绿被一层魔法屏障彻底分割，它闪烁着规律的纹路，散发出一种不可逾越的力量。"
  },
  [130012004] = {
    id = 130012004,
    name = "“幸存者都在那里吧！”队员兴奋地说着，能将天灾隔绝，定然有强者守护。"
  },
  [130012005] = {
    id = 130012005,
    name = "你们顺利地攀上了山坡，可是没有看到一个人，只有一片凄凉的墓地，无数墓碑整齐地排列着。"
  },
  [130012006] = {
    id = 130012006,
    name = "你们互相看了一眼，穿行在墓碑之间，寻找着任务目标的名字。"
  },
  [130012007] = {
    id = 130012007,
    name = "“找到了，阿列科在这里。”队员惋惜地叹了口气。"
  },
  [130012008] = {
    id = 130012008,
    name = "“你曾怀抱炽热，你曾追星逐月，你曾想让光明照耀每一寸大地，可希望并不眷顾深渊，你逃避了不幸，逃避了使命，也逃避了对她的承诺。阿列科，你是一个懦夫。”"
  },
  [130012009] = {
    id = 130012009,
    name = "墓碑还很新，墓志铭也是最近刻上去的，是有谁来过了吗？"
  },
  [130012010] = {
    id = 130012010,
    name = "“队长，这里有一本日记。”"
  },
  [130012011] = {
    id = 130012011,
    name = "你拿起日记，日记的封面写着阿列科的名字。"
  },
  [130012012] = {id = 130012012, name = " "},
  [130012013] = {
    id = 130012013,
    name = "《阿列科的日记》"
  },
  [130012014] = {id = 130012014, name = "9月20日"},
  [130012015] = {
    id = 130012015,
    name = "我找到了！我就说深渊的火山下一定有我要找的东西！"
  },
  [130012016] = {
    id = 130012016,
    name = "等着我，小琳，我会证明我的路才是正确的路！"
  },
  [130012017] = {id = 130012017, name = " "},
  [130012018] = {id = 130012018, name = "10月2日"},
  [130012019] = {
    id = 130012019,
    name = "今天找商队换了三颗火山石，他们竟然像看傻子一样看着我，或许这就是无知的快乐吧。"
  },
  [130012020] = {
    id = 130012020,
    name = "格温多琳，他们永远不知道我用源晶换来了多么珍贵的宝物。"
  },
  [130012021] = {
    id = 130012021,
    name = "他们会感谢我的，因为我会成为这个世界的救世主。"
  },
  [130012022] = {id = 130012022, name = " "},
  [130012023] = {id = 130012023, name = "10月21日"},
  [130012024] = {
    id = 130012024,
    name = "一切都准备好了，暗域会消失的，我相信。"
  },
  [130012025] = {
    id = 130012025,
    name = "你也相信，对吧？"
  },
  [130012026] = {id = 130012026, name = " "},
  [130012027] = {
    id = 130012027,
    name = "一天一页地看下去，基本都是阿列科对于研究的记录，有时只有一两句话毫无新意，你能感觉到他是真的忙起来了。"
  },
  [130012028] = {
    id = 130012028,
    name = "然而就是这样的字迹，你发现它正逐渐变得潦草。"
  },
  [130012029] = {id = 130012029, name = " "},
  [130012030] = {id = 130012030, name = "12月30日"},
  [130012031] = {
    id = 130012031,
    name = "不对，这不对，符文没有问题啊，为什么启动不了？！"
  },
  [130012032] = {id = 130012032, name = " "},
  [130012033] = {id = 130012033, name = "1月2日"},
  [130012034] = {
    id = 130012034,
    name = "符文激活了，可他在吸收我的生命力！为什么会这样？！为什么为什么！"
  },
  [130012035] = {id = 130012035, name = " "},
  [130012036] = {id = 130012036, name = "1月6日"},
  [130012037] = {
    id = 130012037,
    name = "我知道为什么了！我要去纠正这个错误，我要拿回我的生命力，我还年轻，不能就这样老死！"
  },
  [130012038] = {
    id = 130012038,
    name = "格温多琳，我还要回来见你......"
  },
  [130012039] = {id = 130012039, name = " "},
  [130012040] = {id = 130012040, name = "1月15日"},
  [130012041] = {
    id = 130012041,
    name = "我失败了我失败了我失败了我失败了我失败了我失败了我失败了......"
  },
  [130012042] = {id = 130012042, name = " "},
  [130012043] = {id = 130012043, name = "2月3日"},
  [130012044] = {
    id = 130012044,
    name = "啊，原来我还活着。"
  },
  [130012045] = {id = 130012045, name = " "},
  [130012046] = {id = 130012046, name = "2月4日"},
  [130012047] = {
    id = 130012047,
    name = "符文阵异变了，兽潮是被它吸引来的......"
  },
  [130012048] = {
    id = 130012048,
    name = "我的朋友们、我的研究、我的一切都在这一夜之间消失殆尽了......"
  },
  [130012049] = {id = 130012049, name = " "},
  [130012050] = {id = 130012050, name = "2月5日"},
  [130012051] = {
    id = 130012051,
    name = "如果我没有创造出这个符文，是不是这一切都不会发生......"
  },
  [130012052] = {
    id = 130012052,
    name = "是我，是我亲手葬送了他们的生命和我们的未来......"
  },
  [130012053] = {id = 130012053, name = " "},
  [130012054] = {id = 130012054, name = "3月13日"},
  [130012055] = {
    id = 130012055,
    name = "我感觉我活不了多久了，格温多琳，我就不来见你了。"
  },
  [130012056] = {
    id = 130012056,
    name = "我永远爱你。"
  },
  [130012057] = {id = 130012057, name = " "},
  [130012058] = {id = 130012058, name = "......"},
  [130012059] = {
    id = 130012059,
    name = "站在碑林前，你翻完了日记本的最后一页。"
  },
  [130012060] = {
    id = 130012060,
    name = "“一年前的兽潮，竟然是符文异变引发的。”"
  },
  [130012061] = {
    id = 130012061,
    name = "“这些人，都是在那场兽潮里丧命的话，那阿列科的名字，又是谁写下的？”"
  },
  [130012062] = {
    id = 130012062,
    name = "“谁知道呢。”队员叹了口气，收起了日记本，“队长，接下来怎么办？”"
  },
  [130012063] = {
    id = 130012063,
    name = "另一名队员提醒道：“委托人不是还给了我们一封信吗？”"
  },
  [130012064] = {
    id = 130012064,
    name = "你立刻拆开了信，信中内容十分简单，告诉你们如果找不到阿列科，就将盒子埋在当地。"
  },
  [130012065] = {
    id = 130012065,
    name = "“这么远也要交给阿列科的，一定是很重要的东西吧，就这样埋了？”"
  },
  [130012066] = {
    id = 130012066,
    name = "“既然是委托人的要求，我们照办就好。”"
  },
  [130012067] = {
    id = 130012067,
    name = "承诺的任务就是组织的使命，不管里面是圣物亦或者一张白纸，都与你们无关。"
  },
  [130012068] = {
    id = 130012068,
    name = "“这本日记我们带回去吧，交给委托人，也许他知道该怎么做。”"
  },
  [130012069] = {
    id = 130012069,
    name = "你们将盒子埋在阿列科身边后，一一下山去了，没有再回头。"
  },
  [130012070] = {
    id = 130012070,
    name = "这座孤零零的青山周围到处是灰褐色的尘土与滚烫的岩浆，只有这里青翠如春，花香四溢。"
  },
  [130012071] = {
    id = 130012071,
    name = "一个个石碑静谧地沉睡在这里，鲜花安静地摇曳。"
  },
  [130012072] = {
    id = 130012072,
    name = "结界很快会消失，而它们依旧无人铭记。"
  },
  [130013001] = {
    id = 130013001,
    name = "一场恶战后，你们重新审视着当下的环境。"
  },
  [130013002] = {
    id = 130013002,
    name = "你抬头，看见一片广袤的山头，它在火山的南面，却与岩浆隔了一道万丈深渊。"
  },
  [130013003] = {
    id = 130013003,
    name = "那是熔岩无法触碰的地方。它如青山一般郁郁葱葱，即使刚过去的灾难也没有影响那山中所有的植物。"
  },
  [130013004] = {
    id = 130013004,
    name = "“不，那些不是植物！”魔法师队友将魔力汇聚在瞳孔，盯得双眼发红，“那是墓碑，很多很多的墓碑......”"
  },
  [130013005] = {
    id = 130013005,
    name = "你已经猜想到那些墓碑下长眠的人们是谁，你双手合十，无悲无喜。"
  },
  [130013006] = {
    id = 130013006,
    name = "终结于深渊是大多数探险者的宿命，但你仍然希望他们的灵魂得到安息，希望他们的信仰得以延续。"
  },
  [130013007] = {
    id = 130013007,
    name = "有时，信仰是可以创造奇迹的。"
  },
  [130013008] = {
    id = 130013008,
    name = "“队长，我们是不是......”"
  },
  [130013009] = {
    id = 130013009,
    name = "队员的话咽了下去，你也知道这次的任务大概是失败了。"
  },
  [130013010] = {
    id = 130013010,
    name = "“对了，委托人不是还给了我们一封信吗？”"
  },
  [130013011] = {
    id = 130013011,
    name = "你立刻拆开了信，信中内容十分简单，告诉你们如果找不到阿列科，就将盒子埋在当地。"
  },
  [130013012] = {
    id = 130013012,
    name = "“这么远也要交给阿列科的，一定是很重要的东西吧，真的......要埋了？”"
  },
  [130013013] = {
    id = 130013013,
    name = "队员十分犹豫，一路风尘跋山涉水，真的就这样结束了吗。"
  },
  [130013014] = {
    id = 130013014,
    name = "“既然是委托人的要求，我们照办就好。”"
  },
  [130013015] = {
    id = 130013015,
    name = "承诺的任务就是组织的使命，不管里面是圣物亦或者一张白纸，都与你们无关。"
  },
  [130013016] = {
    id = 130013016,
    name = "你们将盒子埋在了高处，正好与那座青山遥遥相望。"
  },
  [130013017] = {
    id = 130013017,
    name = "“你们说阿列科会不会在那里。”队员指着那座被魔法屏障守护着的青山，上面伫立了一座座石碑。"
  },
  [130013018] = {
    id = 130013018,
    name = "“别多想了，你飞过去吗？”另一个队员打趣地说着，拽着队友离开了。"
  },
  [130013019] = {
    id = 130013019,
    name = "你不禁回头忘了一眼，脚下晦暗的深渊正张着巨大的裂口，所见得到的只有空虚与黑暗。"
  },
  [130013020] = {
    id = 130013020,
    name = "而青山已被蒙上了一层灰雾，无法得见真容。"
  },
  [130013021] = {
    id = 130013021,
    name = "终究是山冥永隔，相去天渊。"
  },
  [130014001] = {
    id = 130014001,
    name = "“已经搜遍了整个据点，只有那里没有看过了。”队员站在你身边，伸手指向河对岸的一栋建筑。"
  },
  [130014002] = {
    id = 130014002,
    name = "你们走向那唯一的一栋石屋，令人惊讶的是，这栋石屋并没有门窗，就像一个砖砌的雕塑，伫立在孤岛之上。"
  },
  [130014003] = {
    id = 130014003,
    name = "门边有一块镶嵌在墙壁上的石板，随着魔法的施展，门上的符文开始发光，并逐渐连接起来，激活了一个完整的魔法阵。"
  },
  [130014004] = {
    id = 130014004,
    name = "“你们......是谁？”空旷的石屋中，一位老人推着轮椅而出，双方都露出了惊讶的神色。这是你在据点看到的第一个人。"
  },
  [130014005] = {
    id = 130014005,
    name = "“没想到在死前还能再见到探险者......是的，我就是阿列科。”"
  },
  [130014006] = {
    id = 130014006,
    name = "你们在说明原因后，将盒子与一封信交给了他。"
  },
  [130014007] = {
    id = 130014007,
    name = "他展开信的手变得越来越颤抖，水痕从眼眶旁纵横的沟壑滑落，他伸手抱紧手中的盒子，下巴颤抖地放在上面，竭力地忍耐着，念出了那个名字：“格温多琳......”"
  },
  [130014008] = {
    id = 130014008,
    name = "隔了许久，他才抬起了头，“谢谢......你们走吧。”他转过了轮椅，缓缓进入了石屋深处。"
  },
  [130014009] = {
    id = 130014009,
    name = "你看着老人 没入黑暗，忍不住叫住了他，询问他是否需要帮助。"
  },
  [130014010] = {
    id = 130014010,
    name = "他沉默了一阵，打开了附近的一个抽屉，“把这里面的手稿带走吧，也许有人能找到更好的方向。”"
  },
  [130014011] = {
    id = 130014011,
    name = "你接过他的研究手稿，上面写着《暗域再生阻绝》，而老人却在你的腰间发现了玻璃瓶，他轻声问：“那是什么？”"
  },
  [130014012] = {
    id = 130014012,
    name = "你想起这颗忆梦珠是船舱里得到的，将这件事告诉了老人，而老人捧着忆梦珠后，手心忽然散发了微光——"
  },
  [130014013] = {
    id = 130014013,
    name = "“能......看到吗？”"
  },
  [130014014] = {
    id = 130014014,
    name = "少女在魔法影像前微微歪了歪头。"
  },
  [130014015] = {
    id = 130014015,
    name = "“这个影像......莉莉说可以代替信件。”"
  },
  [130014016] = {
    id = 130014016,
    name = "“虽然还没弄明白魔法原理，不过阿列科能看见就行了。”"
  },
  [130014017] = {
    id = 130014017,
    name = "她轻轻启唇，声音变得严肃了一些，尽管听起来和平时也没什么区别。"
  },
  [130014018] = {
    id = 130014018,
    name = "“阿列科，我找到解决暗域的办法了。”"
  },
  [130014019] = {
    id = 130014019,
    name = "“虽然这个计划还在实验，但我想是有用的。”"
  },
  [130014020] = {
    id = 130014020,
    name = "“等到计划成功，你就不用再留在深渊了。”......"
  },
  [130014021] = {
    id = 130014021,
    name = "游离的画面散了，很快又汇聚了成了另一个。"
  },
  [130014022] = {
    id = 130014022,
    name = "“阿列科，听我说，不可以用你说的那个能量石，它会吞噬你的生命力。”"
  },
  [130014023] = {
    id = 130014023,
    name = "“记着，阿列科，不要用它，它非常危险。”"
  },
  [130014024] = {
    id = 130014024,
    name = "“格温，快来看，我发现了什么！”"
  },
  [130014025] = {
    id = 130014025,
    name = "旁边有个女人朝少女挥了挥手，招呼她过去，少女点点头，淡然地关闭了传讯的魔法影像。"
  },
  [130014026] = {
    id = 130014026,
    name = "“格温，你又在给恋人传讯呀？”"
  },
  [130014027] = {
    id = 130014027,
    name = "“恋人，你说的是阿列科？也许是吧。”"
  },
  [130014028] = {
    id = 130014028,
    name = "“什么叫也许是吧，是就是，不是就不是。”"
  },
  [130014029] = {
    id = 130014029,
    name = "“我跟阿列科之前，好像从来没有说过恋人之间的承诺。”"
  },
  [130014030] = {
    id = 130014030,
    name = "“你们呀，明明心中都爱着对方，为什么不能好好相处呢？”"
  },
  [130014031] = {
    id = 130014031,
    name = "“有好好相处的。我们的目的是一样的，都是为了让家乡变成回来的样子，只是我们都有各自的计划，也不愿为对方妥协。”"
  },
  [130014032] = {
    id = 130014032,
    name = "“啧，都一样固执。”"
  },
  [130014033] = {
    id = 130014033,
    name = "“至少，那是我们都想看到的未来。”"
  },
  [130014034] = {
    id = 130014034,
    name = "“也对，到时你的计划成功了，也让他好好瞧瞧，是他的办法有用，还是我们格温更厉害！”"
  },
  [130014035] = {
    id = 130014035,
    name = "“嗯。”"
  },
  [130014036] = {
    id = 130014036,
    name = "少女轻声应和着。"
  },
  [130014037] = {id = 130014037, name = "......"},
  [130014038] = {
    id = 130014038,
    name = "“炎日据点真的毁灭了？”"
  },
  [130014039] = {
    id = 130014039,
    name = "“格温，你先冷静一下，炎日据点确实已经被兽潮毁灭了，这是公会的消息，不会有错。但仅剩的幸存者到了圈落，也许阿列科还没死。”"
  },
  [130014040] = {
    id = 130014040,
    name = "“我提醒过他的，他还是做了，那个由火山石凝练的能量石，虽然能用于清除浊炁的魔法阵，但也会将无数的魔物引来，这是当初我们发生分歧的缘由。”"
  },
  [130014041] = {
    id = 130014041,
    name = "“那个，你不担心阿列科吗？”"
  },
  [130014042] = {
    id = 130014042,
    name = "“担心没有用，他失败了也不会来找我，要是他死了，就更不会来。我还有一个实验要做，先去了。”"
  },
  [130014043] = {
    id = 130014043,
    name = "“啊，你好歹先去睡觉啊......”"
  },
  [130014044] = {id = 130014044, name = "......"},
  [130014045] = {
    id = 130014045,
    name = "“哒哒哒......”有什么砸在了地面上。"
  },
  [130014046] = {
    id = 130014046,
    name = "是少女的眼泪。"
  },
  [130014047] = {
    id = 130014047,
    name = "“......为什么，明明是你的错，为什么我要哭呢。”"
  },
  [130014048] = {
    id = 130014048,
    name = "少女的眼泪不断的落下。"
  },
  [130014049] = {
    id = 130014049,
    name = "“你输了，阿列科，在确认你死讯的这一刻，你就输在了和我竞争的路上。”"
  },
  [130014050] = {
    id = 130014050,
    name = "“所以......我不会输的。”"
  },
  [130014051] = {
    id = 130014051,
    name = "“那个器械，已经到最后一步了，只差最后一步。”"
  },
  [130014052] = {
    id = 130014052,
    name = "“你说得对，拯救必然伴随着牺牲，所以我会带着你的理想，一起去走上这最后一步。”"
  },
  [130014053] = {
    id = 130014053,
    name = "“在这之前，我想和你好好道别。”“阿列科，你还活着吗？”......"
  },
  [130014054] = {
    id = 130014054,
    name = "“......”"
  },
  [130014055] = {
    id = 130014055,
    name = "“你是对的，也许我们都不会成功，但至少我们尝试过。”"
  },
  [130014056] = {
    id = 130014056,
    name = "“阿列科，我终于明白生命力消失是什么感觉，我留下了很多灵感，足够他们去进一步改进。”"
  },
  [130014057] = {
    id = 130014057,
    name = "“好遗憾，我们说要一起回到没有暗域的家乡，眼看我的计划有了起色，可惜我们都看不到了。”"
  },
  [130014058] = {
    id = 130014058,
    name = "少女流下了两行泪，身边的人忍不住回应。"
  },
  [130014059] = {
    id = 130014059,
    name = "“格温，你放心，我们不会放弃的，我们会继续做下去，直到成功的那天！”"
  },
  [130014060] = {
    id = 130014060,
    name = "“好。莉莉，我死了以后，你就把这颗忆梦珠销毁了吧......本来是想送给他的礼物，现在也不需要了......”"
  },
  [130014061] = {
    id = 130014061,
    name = "“......嗯。”"
  },
  [130014062] = {
    id = 130014062,
    name = "“还有，那支竖笛，帮我送去炎日据点。我将那首曲子用符文刻了进去，这样他就算在深渊，也能听到那首曲子了......要是他真的死了，就把它埋了吧。”"
  },
  [130014063] = {
    id = 130014063,
    name = "“好......格温，你原谅他了吗？”"
  },
  [130014064] = {
    id = 130014064,
    name = "“无所谓原不原谅，只是......没有他在身边，真的有些......寂寞啊......”"
  },
  [130014065] = {id = 130014065, name = "......"},
  [130014066] = {
    id = 130014066,
    name = "忆梦珠的画面到此彻底消失了，竖笛清幽的旋律缓缓飘过每个人的心间，老人紧紧地握着笛子怔愣了许久。"
  },
  [130014067] = {
    id = 130014067,
    name = "他无声地流着泪，一样哽咽抽泣：“我知道，我都知道......”"
  },
  [130014068] = {
    id = 130014068,
    name = "他郑重地向你们道谢，决定和你们一起离开，“带我回去吧，拜托了。”"
  },
  [130014069] = {id = 130014069, name = "......"},
  [130014070] = {
    id = 130014070,
    name = "你们离开地下据点，带阿列科见了委托人莉莉，莉莉看着阿列科和他手中的珠子，惊讶地说不出话。"
  },
  [130014071] = {
    id = 130014071,
    name = "莉莉：“你是阿列科？”"
  },
  [130014072] = {
    id = 130014072,
    name = "得知事情原委，莉莉叹息了一声：“本来打算将忆梦珠损毁，后来研究室遭了贼，忆梦珠也失窃了。”"
  },
  [130014073] = {
    id = 130014073,
    name = "“想不到失窃的忆梦珠，会用那种方式到阿列科的手里。也许这也是格温冥冥中的心愿吧。”"
  },
  [130014074] = {
    id = 130014074,
    name = "“那不是她的心愿。”老人突然出声，目光灼灼地望着你们，沧桑垂老的双眼里迸发着蓬勃的生命力。"
  },
  [130014075] = {
    id = 130014075,
    name = "“我会完成她的心愿。这是我穷极一生的赎罪，也是我最后的承诺。”"
  },
  [130015001] = {
    id = 130015001,
    name = "「深渊航线」接到了一份来自秘密研究所的委托——护送一个盒子到迷雾之都南部的尼塔炎日溶洞。"
  },
  [130015002] = {
    id = 130015002,
    name = "该溶洞的深处，曾有探险者组织建立了一处据点和码头，方便深渊中的河道航行。"
  },
  [130015003] = {
    id = 130015003,
    name = "但在一次兽潮袭击后，这里成为了一片废墟，河道也变为滩涂无法使用。"
  },
  [130015004] = {
    id = 130015004,
    name = "“拜托了，到那里找到阿列科，把盒子交给他。”"
  },
  [130015005] = {
    id = 130015005,
    name = "委托人莉莉慎重地将盒子交给了组织。"
  },
  [130015006] = {
    id = 130015006,
    name = "“如果......找不到他的话，请打开这封信，它会告诉你怎么做的。”"
  },
  [130015007] = {
    id = 130015007,
    name = "“愿你们一路平安，百事大吉。”"
  },
  [111700001] = {
    id = 111700001,
    name = "沙沙......前方有什么从你眼前一晃而过。"
  },
  [111700002] = {id = 111700002, name = "那是？"},
  [111700003] = {
    id = 111700003,
    name = "什么？什么？让我看看！"
  },
  [111700004] = {
    id = 111700004,
    name = "大惊小怪。"
  },
  [111700005] = {
    id = 111700005,
    name = "......你们看，在那边！"
  },
  [111700006] = {
    id = 111700006,
    name = "哼，激动什么？"
  },
  [111700007] = {
    id = 111700007,
    name = "细碎的草丛里，一只黑色的尖角露出了一小截，尖角下的身躯不耐烦地抖了抖。"
  },
  [111700008] = {
    id = 111700008,
    name = "咕，咕咕？（怎么又是你们？）"
  },
  [111700009] = {
    id = 111700009,
    name = "是咕咕？"
  },
  [111700010] = {
    id = 111700010,
    name = "是那个可爱的小魔物！"
  },
  [111700011] = {
    id = 111700011,
    name = "咕咕扭了扭身体，一头窜进了草丛里，野草打了个浪花，延绵到了远处。"
  },
  [111700012] = {
    id = 111700012,
    name = "我去看看！"
  },
  [111700013] = {
    id = 111700013,
    name = "......哼，激动什么。假正经，等等我们啊！"
  },
  [111700014] = {
    id = 111700014,
    name = "啊，蒂娜一个人去前面了。"
  },
  [111700015] = {
    id = 111700015,
    name = "我们也过去吧，看看咕咕打算做什么。"
  },
  [111700016] = {
    id = 111700016,
    name = "每次见到这只小魔物，似乎总有好事发生啊。"
  },
  [111700017] = {id = 111700017, name = "好事？"},
  [111700018] = {
    id = 111700018,
    name = "它的能力很有意思，如果真的能和人类交流，那就更有意思了。"
  },
  [111700019] = {
    id = 111700019,
    name = "菲尼斯，你又在想什么坏主意？"
  },
  [111700020] = {id = 111700020, name = "......"},
  [111700021] = {
    id = 111700021,
    name = "队长，别用这种怀疑的眼神看我，我只会想对咱们有用的事。"
  },
  [111700022] = {
    id = 111700022,
    name = "咕咕跑不见了！我们快跟上啊！"
  },
  [111700023] = {id = 111700023, name = "呵呵。"},
  [111700024] = {
    id = 111700024,
    name = "你们追上去的时候，蒂娜已经把咕咕抱在怀里揉了好几圈。"
  },
  [111700025] = {
    id = 111700025,
    name = "咕咕！咕，咕咕！（愚蠢的人类！放我下来！）"
  },
  [111700026] = {
    id = 111700026,
    name = "上次帮了我们，还没来得及和你说谢谢。"
  },
  [111700027] = {
    id = 111700027,
    name = "咕，咕咕......（哼，谁稀罕你们说的谢谢......）"
  },
  [111700028] = {
    id = 111700028,
    name = "咕咕咕......（唔，再搓个背，唔舒服......）"
  },
  [111700029] = {
    id = 111700029,
    name = "咕......咕咕！（香味......在那边，差点就被你迷惑了！）"
  },
  [111700030] = {
    id = 111700030,
    name = "咕咕一个机灵，猛地挣脱了蒂娜，朝一处峡谷跑了过去。"
  },
  [111700031] = {
    id = 111700031,
    name = "咕咕，你去哪儿？"
  },
  [111700032] = {
    id = 111700032,
    name = "欸？怎么又跑了？"
  },
  [111700033] = {
    id = 111700033,
    name = "它好像发现了什么东西。"
  },
  [111700034] = {
    id = 111700034,
    name = "哇，难道是宝物？"
  },
  [111700035] = {
    id = 111700035,
    name = "老师，我们要去看看吗？"
  },
  [111700036] = {
    id = 111700036,
    name = "去看看吧。"
  },
  [111700037] = {
    id = 111700037,
    name = "好欸，出发！"
  },
  [111700038] = {
    id = 111700038,
    name = "呼，跑得真快啊。"
  },
  [111700039] = {
    id = 111700039,
    name = "它一直朝这个方向来，难道真的有什么东西？"
  },
  [111700040] = {
    id = 111700040,
    name = "眼前雾气深重，你们跟着咕咕来到了一处峡谷，而峡谷的尽头是死路。"
  },
  [111700041] = {
    id = 111700041,
    name = "......没路了？"
  },
  [111700042] = {id = 111700042, name = "咕咕！"},
  [111700043] = {
    id = 111700043,
    name = "咕！！（香香的食物，我来了！）"
  },
  [111700044] = {
    id = 111700044,
    name = "咕咕浑身一炸，冒起了微光，一头撞向山壁，菲尼斯快步上前，触摸着咕咕跳入的地方，那里已变成了一片坚实的山壁。"
  },
  [111700045] = {
    id = 111700045,
    name = "它进去了？"
  },
  [111700046] = {
    id = 111700046,
    name = "这里应该有结界。"
  },
  [111700047] = {
    id = 111700047,
    name = "别担心蒂娜，这只是普通的防护结界。"
  },
  [111700048] = {
    id = 111700048,
    name = "队长，那咱们快把它打开吧！我已经迫不及待看到宝物了！"
  },
  [111700049] = {
    id = 111700049,
    name = "你走向结界，尝试着伸手触碰那抹光幕，眼前一片光色迷离，你几乎没用什么力气，就感受到了结界的波动，整个人陷了进去。"
  },
  [111700050] = {
    id = 111700050,
    name = "队长好厉害！"
  },
  [111700051] = {
    id = 111700051,
    name = "......（这个结界很薄弱，看起来只能维持伪装的样子了）"
  },
  [111700052] = {
    id = 111700052,
    name = "咕咕，你往哪里去？！"
  },
  [111700053] = {
    id = 111700053,
    name = "你们几次折绕，视野渐渐开阔，竟然走到了一处山谷内部。"
  },
  [111700054] = {
    id = 111700054,
    name = "那边有座房子！"
  },
  [111700055] = {
    id = 111700055,
    name = "竟然有人住在这里吗？"
  },
  [111700056] = {
    id = 111700056,
    name = "那个结界......我们是不是误闯入别人家里了......"
  },
  [111700057] = {
    id = 111700057,
    name = "......看起来，好像是这样。"
  },
  [111700058] = {
    id = 111700058,
    name = "咕咕，别跑啊！"
  },
  [111700059] = {
    id = 111700059,
    name = "咕咕回头瞅了尼莉莎一眼，翘着尾巴窜到了那座木屋前，撞开了木门钻了进去。"
  },
  [111700060] = {
    id = 111700060,
    name = "这家伙！"
  },
  [111700061] = {
    id = 111700061,
    name = "你们跟着追进木屋，咕咕东窜西跑，撞倒了屋内的桌椅。"
  },
  [111700062] = {
    id = 111700062,
    name = "糟了......咕咕，不要乱来了！"
  },
  [111700063] = {
    id = 111700063,
    name = "咕咕，咕咕，咕咕......（在哪里，在哪里，到底在哪里？）"
  },
  [111700064] = {
    id = 111700064,
    name = "别让它再破坏东西了。"
  },
  [111700065] = {
    id = 111700065,
    name = "我去抓住它。"
  },
  [111700066] = {
    id = 111700066,
    name = "咕咕咕！（不要，我还没找到食物！）"
  },
  [111700067] = {
    id = 111700067,
    name = "咕咕悚然一惊，在屋子里横冲直撞，整座木屋不停震荡。"
  },
  [111700068] = {
    id = 111700068,
    name = "在我这边！"
  },
  [111700069] = {
    id = 111700069,
    name = "小心，那个花盆！"
  },
  [111700070] = {
    id = 111700070,
    name = "——哐！桌上的花盆陶器哗啦啦碎了一地。"
  },
  [111700071] = {id = 111700071, name = "......"},
  [111700072] = {
    id = 111700072,
    name = "抓到你了！"
  },
  [111700073] = {
    id = 111700073,
    name = "咕咕！！（放开我！）"
  },
  [111700074] = {
    id = 111700074,
    name = "咕咕倏然变得更小，一溜烟从蒂娜手里滑了出去，正朝你跑来，看见你拦住前方，它一个紧急急刹，转向了门口。"
  },
  [111700075] = {
    id = 111700075,
    name = "菲尼斯！"
  },
  [111700076] = {
    id = 111700076,
    name = "交给我！"
  },
  [111700077] = {
    id = 111700077,
    name = "菲尼斯严阵以待守住了大门，但没想到下一刻，咕咕朝菲尼斯吐了一口浊炁，侧身撞向窗户！"
  },
  [111700078] = {
    id = 111700078,
    name = "该死的小家伙，我就不信抓不到你了！"
  },
  [111700079] = {
    id = 111700079,
    name = "哗啦啦！窗框破裂，尼莉莎踢开烂掉的窗户，跃身翻了出去！"
  },
  [111700080] = {id = 111700080, name = "！！！"},
  [111700081] = {
    id = 111700081,
    name = "事情好像变得有些糟糕了。"
  },
  [111700082] = {
    id = 111700082,
    name = "喀嚓，喀嚓......有什么正在裂开的声音从头顶传来。"
  },
  [111700083] = {
    id = 111700083,
    name = "......大家小心！先出去！"
  },
  [111700084] = {
    id = 111700084,
    name = "你来不及考虑，一手拉上身边的一个人立刻冲出了木屋。"
  },
  [111700085] = {
    id = 111700085,
    name = "轰！！木屋在下一秒倒塌。"
  },
  [111700086] = {id = 111700086, name = "......"},
  [111700087] = {id = 111700087, name = "......"},
  [111700088] = {
    id = 111700088,
    name = "你左手牵着安妮斯，右手抓着蒂娜，看着菲尼斯从废墟里跑了出来。"
  },
  [111700089] = {
    id = 111700089,
    name = "呼，差一点就被砸到了，队长，你可真不厚道......好吧，救美丽的女孩子们更重要。"
  },
  [111700090] = {
    id = 111700090,
    name = "他摊了摊手，看向了附近蹦跶的尼莉莎，露出笑眯眯的神情，你忽然有了不好的预感。"
  },
  [111700091] = {id = 111700091, name = "小莎！"},
  [111700092] = {
    id = 111700092,
    name = "蒂娜和安妮斯走了过去，看着小莎抱着咕咕在地上打滚。"
  },
  [111700093] = {
    id = 111700093,
    name = "吐出来，你给我吐出来！假正经，快来帮忙！"
  },
  [111700094] = {
    id = 111700094,
    name = "咕！（不！这是我的食物！）"
  },
  [111700095] = {
    id = 111700095,
    name = "咕咕一听有人帮忙，再次吐出一股浊炁，趁尼莉莎分心一溜烟跑掉了，再也没了影子。"
  },
  [111700096] = {
    id = 111700096,
    name = "怎么回事？"
  },
  [111700097] = {
    id = 111700097,
    name = "咕咕吃掉了屋顶的魔法石！"
  },
  [111700098] = {id = 111700098, name = "！！！"},
  [111700099] = {
    id = 111700099,
    name = "那一定是一个宝物，可恶的咕咕，竟然吃独食！下次别让我逮着它！"
  },
  [111700100] = {
    id = 111700100,
    name = "我想，现在不是它吃独食的问题，而是这里被我们弄成了这样......"
  },
  [111700101] = {
    id = 111700101,
    name = "队长，不如趁主人没回家之前，咱们快走吧。"
  },
  [111700102] = {
    id = 111700102,
    name = "好好，我同意！"
  },
  [111700103] = {
    id = 111700103,
    name = "你还没回话，谷口出现了脚步声，一个少女的轮廓渐渐清晰。"
  },
  [111700104] = {
    id = 111700104,
    name = "乌鸦嘴就是乌鸦嘴。"
  },
  [111700105] = {id = 111700105, name = "......"},
  [111700106] = {
    id = 111700106,
    name = "少女愣愣地站在你们对面，看着眼前的一片狼藉，茫然的双眼轰然迸发出愤怒的火焰。"
  },
  [111700107] = {
    id = 111700107,
    name = "你们，闯进我家，弄坏了我的屋子？！"
  },
  [111700108] = {
    id = 111700108,
    name = "不是我们......是......"
  },
  [111700109] = {
    id = 111700109,
    name = "是什么？是你们从天而降，落在我的屋子里了吗？"
  },
  [111700110] = {
    id = 111700110,
    name = "抱歉......我们无意闯入这里，这是意外。"
  },
  [111700111] = {
    id = 111700111,
    name = "想起罪魁祸首已经逃之夭夭，你无奈地叹口气，将事情的原委告诉了少女。"
  },
  [111700112] = {
    id = 111700112,
    name = "虽然不是我们直接造成的，但这件事也的确因我们而起，对你这里的破坏，我们愿意悉数赔偿。"
  },
  [111700113] = {
    id = 111700113,
    name = "被魔物......破坏了？虽然不太可信，但你认错的态度挺诚恳的......等等，你们是怎么进来的？"
  },
  [111700114] = {
    id = 111700114,
    name = "我们跟着咕咕一起进来的。"
  },
  [111700115] = {
    id = 111700115,
    name = "你们竟然还给魔物起了名字？（这里通常被人发现不了，难道结界失效了？）"
  },
  [111700116] = {
    id = 111700116,
    name = "不，重点不是这个。你们赔我多少钱也没用，这是我父亲给我留下的秘密基地，现在被你们弄成这样，你们不会想赔点钱就一走了之吧？"
  },
  [111700117] = {
    id = 111700117,
    name = "那你的意思是？"
  },
  [111700118] = {
    id = 111700118,
    name = "当然是把这里恢复到被你们破坏之前的样子，修好我的基地，我的房屋，以及被你们破坏掉的，所有东西！"
  },
  [111700119] = {
    id = 111700119,
    name = "什么？要我们修房子？"
  },
  [111700120] = {
    id = 111700120,
    name = "不止是房子，门口的结界没了也一定是你们的关系。结界一旦消失，我的基地就不再安全......总之，你们得负责。"
  },
  [111700121] = {
    id = 111700121,
    name = "队长，怎么办？"
  },
  [111700122] = {
    id = 111700122,
    name = "先把房子修好吧。或许圈落里有石料，我去买来，另外还要想办法弄些木材，之后再添置其他的......"
  },
  [111700123] = {
    id = 111700123,
    name = "木材的话交给我，我应该有办法弄到。"
  },
  [111700124] = {
    id = 111700124,
    name = "我申请和队长去圈落！"
  },
  [111700125] = {
    id = 111700125,
    name = "那我和安妮斯留在这里打扫收拾，你可别贪玩。"
  },
  [111700126] = {
    id = 111700126,
    name = "知道啦。"
  },
  [111700127] = {
    id = 111700127,
    name = "安排好分工之后，你们准备出发，被少女跟了上来。"
  },
  [111700128] = {
    id = 111700128,
    name = "你是他们的队长？我要和你一起去。"
  },
  [111700129] = {
    id = 111700129,
    name = "也好，有你在，找材料也方便很多。"
  },
  [111700130] = {
    id = 111700130,
    name = "修好我的基地本就是你们应该做的事，我只是监视你别想逃跑。"
  },
  [111700131] = {
    id = 111700131,
    name = "放心吧，我们队长会负责的！"
  },
  [111700132] = {id = 111700132, name = "......"},
  [111700133] = {
    id = 111700133,
    name = "哦......那就走吧。"
  },
  [111700134] = {
    id = 111700134,
    name = "队长，我去那边看看！咱们一会儿就在这里会合吧！"
  },
  [111700135] = {
    id = 111700135,
    name = "一到圈落，尼莉莎就找借口跟你分开了，也不知道有没有把蒂娜的话放心上。"
  },
  [111700136] = {
    id = 111700136,
    name = "那个，你知道这里的市集在哪儿吗？"
  },
  [111700137] = {
    id = 111700137,
    name = "少女莫名地看了你一眼，确认你真的在问她，转身朝前带路，到了一堆卖石头的地方。"
  },
  [111700138] = {
    id = 111700138,
    name = "这里有能盖房子的材料吗？"
  },
  [111700139] = {
    id = 111700139,
    name = "盖房子的话，还是需要切割好的石料吧？我这里的材料都不太适合啊。"
  },
  [111700140] = {
    id = 111700140,
    name = "那走吧，去别的地方看看。"
  },
  [111700141] = {
    id = 111700141,
    name = "咦，原来是伊涅利丝小姐盖新房子啊？"
  },
  [111700142] = {
    id = 111700142,
    name = "摊贩朝旁边的你看了看，露出会心的笑容。"
  },
  [111700143] = {
    id = 111700143,
    name = "哦，原来是这样，两个人住的话，确实该换了。伊涅利丝小姐的眼光不错啊，这小伙子俊得很呢！"
  },
  [111700144] = {
    id = 111700144,
    name = "你别误会，他才不是什么......"
  },
  [111700145] = {
    id = 111700145,
    name = "嗯嗯，圈落里租房太贵，还是自己盖得有保障啊。"
  },
  [111700146] = {id = 111700146, name = "......"},
  [111700147] = {
    id = 111700147,
    name = "欸，这边这位尊贵的客人，您随便看看？咱这做武器做防具用的磨石都有！"
  },
  [111700148] = {
    id = 111700148,
    name = "摊贩没再和她闲聊，乐呵呵地接待下一位客人，伊涅利丝瞥了你一眼，去往前方的材料摊。"
  },
  [111700149] = {
    id = 111700149,
    name = "伊涅利丝......小姐？"
  },
  [111700150] = {
    id = 111700150,
    name = "不用在意他说什么。"
  },
  [111700151] = {
    id = 111700151,
    name = "对了，虽然你们弄坏了我的基地，但我的确是忘了自我介绍，我叫伊涅利丝，是常居在这里的探险者。"
  },
  [111700152] = {
    id = 111700152,
    name = "她自我介绍时睫毛微垂，虽然身形未动，但指尖却下意识做了个手势，看来，她受过非常良好的教育。"
  },
  [111700153] = {
    id = 111700153,
    name = "（她是贵族？）"
  },
  [111700154] = {
    id = 111700154,
    name = "与她交换姓名后，你们在圈落中继续寻找可用的材料，一路也没有看到尼莉莎的踪影。"
  },
  [111700155] = {
    id = 111700155,
    name = "逛了一圈，都是一些物资药品，就连修复结界的材料也没有......"
  },
  [111700156] = {
    id = 111700156,
    name = "如果说盖房子的话，需要找摊贩说的那种坚固的石料吧？"
  },
  [111700157] = {
    id = 111700157,
    name = "石料......我知道附近有一座废弃的矿场，年初的时候垮塌了，死了几个矿工，之后矿场就废弃了。"
  },
  [111700158] = {
    id = 111700158,
    name = "正好，如果是矿场的话，那一定有完整的石料，我们可以去碰碰运气。"
  },
  [111700159] = {
    id = 111700159,
    name = "好。等等，我们需要的石料很多，你打算怎么把它们搬去我的基地？"
  },
  [111700160] = {
    id = 111700160,
    name = "那就只能找帮手了。"
  },
  [111700161] = {
    id = 111700161,
    name = "你......要让那个女孩帮你搬石料？"
  },
  [111700162] = {
    id = 111700162,
    name = "她不可思议地看着你，仿佛见到了仗势欺人的权贵。"
  },
  [111700163] = {
    id = 111700163,
    name = "不，这种事怎么能交给女孩子去做。"
  },
  [111700164] = {
    id = 111700164,
    name = "你在街市上看了一圈，走向更偏僻的街区。"
  },
  [111700165] = {
    id = 111700165,
    name = "你在这里有其他认识的人？"
  },
  [111700166] = {id = 111700166, name = "没有。"},
  [111700167] = {
    id = 111700167,
    name = "那你在找谁？"
  },
  [111700168] = {
    id = 111700168,
    name = "找到了，你看。"
  },
  [111700169] = {
    id = 111700169,
    name = "巷子尽头，坐着一名拾荒者，在他身后，是一堆被废弃的垃圾堆，看到你们靠近时，露出了警惕的眼神。"
  },
  [111700170] = {
    id = 111700170,
    name = "你要找他搬石料？不行，那是我的地方，绝对不能让外人知道。"
  },
  [111700171] = {
    id = 111700171,
    name = "放心吧，我们都不是多嘴的人，不会把你的秘密说出去。"
  },
  [111700172] = {
    id = 111700172,
    name = "哼，谅你们是误闯，等修好了基地就乖乖离开知道吗？喂，你还过去干什么？"
  },
  [111700173] = {
    id = 111700173,
    name = "看到那个人背后的推车了吗？"
  },
  [111700174] = {
    id = 111700174,
    name = "你拿出了一袋食物，走向了拾荒者。"
  },
  [111700175] = {
    id = 111700175,
    name = "我用这些，换你背后的推车。"
  },
  [111700176] = {
    id = 111700176,
    name = "......不不，那是我睡觉的床板。"
  },
  [111700177] = {
    id = 111700177,
    name = "可你的推车只值这么多。不同意，我就找别人买了。"
  },
  [111700178] = {
    id = 111700178,
    name = "那，那你再加一袋食物！"
  },
  [111700179] = {
    id = 111700179,
    name = "你没有理他，转身走了，拾荒者慌张地追了上来。"
  },
  [111700180] = {
    id = 111700180,
    name = "我换我换，你拿走吧！"
  },
  [111700181] = {
    id = 111700181,
    name = "嗯，多谢了。"
  },
  [111700182] = {
    id = 111700182,
    name = "交易成功，你推着车出了小巷，伊涅利丝探究地看着你。"
  },
  [111700183] = {
    id = 111700183,
    name = "你把车拿走了，他睡哪儿？"
  },
  [111700184] = {
    id = 111700184,
    name = "这辆车上都是干枯的药草灰，没人睡过。"
  },
  [111700185] = {
    id = 111700185,
    name = "原来他是想多赚一笔，你倒是洞察入微。"
  },
  [111700186] = {
    id = 111700186,
    name = "过奖了，我们去找尼莉莎会合吧。"
  },
  [111700187] = {
    id = 111700187,
    name = "你们到了汇合点，没见着尼莉莎，倒是看到一个摊贩朝你们招手。"
  },
  [111700188] = {
    id = 111700188,
    name = "是英俊潇洒帅气威武的队长大人吧？那位美丽可爱聪明绝顶的小莎小姐要跟你们带句话。"
  },
  [111700189] = {
    id = 111700189,
    name = "你和你的同伴称号都很长啊。"
  },
  [111700190] = {
    id = 111700190,
    name = "......说吧，什么话？"
  },
  [111700191] = {
    id = 111700191,
    name = "她说她找到了一些室内用具，先带回去了，剩下的就交给队长大人。"
  },
  [111700192] = {
    id = 111700192,
    name = "知道了，谢谢告知。"
  },
  [111700193] = {
    id = 111700193,
    name = "你的同伴跑了？"
  },
  [111700194] = {
    id = 111700194,
    name = "......没有。她只想把你的房子装点得更好。"
  },
  [111700195] = {
    id = 111700195,
    name = "面对伊涅利丝怀疑的眼神，你赶快岔开了话题。"
  },
  [111700196] = {
    id = 111700196,
    name = "运输石料的工具已经有了，趁天还早，现在就出发去矿场吧。"
  },
  [111700197] = {id = 111700197, name = "......"},
  [111700198] = {
    id = 111700198,
    name = "就是那里。"
  },
  [111700199] = {
    id = 111700199,
    name = "伊涅利丝指向了一个矮矮的岩坡。"
  },
  [111700200] = {
    id = 111700200,
    name = "自从矿洞坍塌了之后，就没有什么人来这里了，过去看看吧，希望不要白跑这一趟。"
  },
  [111700201] = {
    id = 111700201,
    name = "大部分的人挖矿，都是为了提炼出欧泊与源晶，很少有人需要石料了。"
  },
  [111700202] = {
    id = 111700202,
    name = "希望如此。"
  },
  [111700203] = {
    id = 111700203,
    name = "你们到达了矿场。"
  },
  [111700204] = {
    id = 111700204,
    name = "这个矿洞竟然还保留着。"
  },
  [111700205] = {
    id = 111700205,
    name = "洞口延伸里面本是矿洞深处，被垮塌的山石堵住了去路。"
  },
  [111700206] = {
    id = 111700206,
    name = "看来只能从这里面找了。"
  },
  [111700207] = {
    id = 111700207,
    name = "伊涅利丝走进一片乱石堆，那里杂乱无章地堆放着许多石块。"
  },
  [111700208] = {
    id = 111700208,
    name = "这些石料良莠不齐，先把能用的挑出来吧。"
  },
  [111700209] = {
    id = 111700209,
    name = "你把推车放在门口，和伊涅利丝一起寻找可用的石料。"
  },
  [111700210] = {
    id = 111700210,
    name = "你这个太大了，不行不行。"
  },
  [111700211] = {id = 111700211, name = "......"},
  [111700212] = {
    id = 111700212,
    name = "这个太小了，不能用。"
  },
  [111700213] = {id = 111700213, name = "......"},
  [111700214] = {
    id = 111700214,
    name = "这个一捏就碎了......这个太锋利了，只能做石斧吧......"
  },
  [111700215] = {
    id = 111700215,
    name = "伊涅利丝清点着石料，把淘汰的扔在一边，眉间的郁色越来越重。"
  },
  [111700216] = {
    id = 111700216,
    name = "嗯？你看着我做什么？"
  },
  [111700217] = {
    id = 111700217,
    name = "如果按照你的要求，这里恐怕没几块合格啊。"
  },
  [111700218] = {
    id = 111700218,
    name = "......那该怎么办？"
  },
  [111700219] = {
    id = 111700219,
    name = "你刨出地里被掩埋的錾子和小锤。"
  },
  [111700220] = {
    id = 111700220,
    name = "用这个试试看？"
  },
  [111700221] = {
    id = 111700221,
    name = "她露出意外的表情。"
  },
  [111700222] = {
    id = 111700222,
    name = "你会切割石头？"
  },
  [111700223] = {id = 111700223, name = "不会。"},
  [111700224] = {id = 111700224, name = "......"},
  [111700225] = {
    id = 111700225,
    name = "那就，随便凿凿看吧。也许能行呢？"
  },
  [111700226] = {
    id = 111700226,
    name = "......嗯。也许呢。"
  },
  [111700227] = {id = 111700227, name = "铛！！"},
  [111700228] = {id = 111700228, name = "......"},
  [111700229] = {id = 111700229, name = "......"},
  [111700230] = {
    id = 111700230,
    name = "好像没什么动静，再试试呢？"
  },
  [111700231] = {id = 111700231, name = "铛！！"},
  [111700232] = {id = 111700232, name = "......"},
  [111700233] = {id = 111700233, name = "......"},
  [111700234] = {
    id = 111700234,
    name = "嗯，有点痕迹了。"
  },
  [111700235] = {
    id = 111700235,
    name = "这样凿下去不行。"
  },
  [111700236] = {
    id = 111700236,
    name = "你不想做了？！"
  },
  [111700237] = {
    id = 111700237,
    name = "不，我们想想别的办法。那些矿工切割一个石头，一定用不了这么久的时间。"
  },
  [111700238] = {
    id = 111700238,
    name = "好歹你也是一个探险者，不会连矿工都不如吧？"
  },
  [111700239] = {
    id = 111700239,
    name = "......那你来试试？"
  },
  [111700240] = {
    id = 111700240,
    name = "我，我也不会......"
  },
  [111700241] = {
    id = 111700241,
    name = "不对！这是你的责任！你是不是想偷懒？"
  },
  [111700242] = {id = 111700242, name = "......"},
  [111700243] = {
    id = 111700243,
    name = "论战斗的技巧，矿工不如探险者，但切割石头，他们一定有诀窍和辅助的东西。"
  },
  [111700244] = {
    id = 111700244,
    name = "他们不可能用到魔法器具。"
  },
  [111700245] = {
    id = 111700245,
    name = "的确，用魔法赋予力量切割石料的确更快，但魔法器具的价值远远大于石料本身。"
  },
  [111700246] = {
    id = 111700246,
    name = "让我想想......对了！我记得父亲用过一种砂石，洒在石头上，很快就能磨平石头。"
  },
  [111700247] = {
    id = 111700247,
    name = "难道是解玉砂？"
  },
  [111700248] = {
    id = 111700248,
    name = "那是什么？"
  },
  [111700249] = {
    id = 111700249,
    name = "从一位前辈那里听说的，是一种可以切割任何东西的矿砂。"
  },
  [111700250] = {
    id = 111700250,
    name = "既然有这种东西，那这里应该能找到吧......"
  },
  [111700251] = {
    id = 111700251,
    name = "矿洞的角落里，有几罐陶器，里面装满了褐灰色的砂石。"
  },
  [111700252] = {
    id = 111700252,
    name = "你说得不错。附近没有专门切割石料的地方，应该都是切好了再售卖的。"
  },
  [111700253] = {
    id = 111700253,
    name = "你走到角落端起了一坛陶罐。"
  },
  [111700254] = {
    id = 111700254,
    name = "唔，什么味......阿......阿嚏！"
  },
  [111700255] = {
    id = 111700255,
    name = "伊涅利丝一个喷嚏将砂石吹到了你的脸上。"
  },
  [111700256] = {
    id = 111700256,
    name = "啊，对不......阿嚏......阿嚏！"
  },
  [111700257] = {
    id = 111700257,
    name = "阿......阿嚏！"
  },
  [111700258] = {
    id = 111700258,
    name = "鼻子痒痒的，你也没忍住。"
  },
  [111700259] = {
    id = 111700259,
    name = "阿嚏......快，阿......放下......阿嚏！！"
  },
  [111700260] = {
    id = 111700260,
    name = "不用伊涅利丝提醒，你已经放下了陶罐，但空气中的细尘仍在，你拉着她跑出矿洞。"
  },
  [111700261] = {
    id = 111700261,
    name = "阿嚏......阿嚏！！抱歉，我的鼻子特别敏感。"
  },
  [111700262] = {
    id = 111700262,
    name = "她揉了揉鼻子，被解玉砂一抹，立刻变红了。"
  },
  [111700263] = {
    id = 111700263,
    name = "别擦，会受伤，用水洗。"
  },
  [111700264] = {
    id = 111700264,
    name = "......嗯，谢谢。"
  },
  [111700265] = {
    id = 111700265,
    name = "你打开水袋，清澈的水落在她双手中。"
  },
  [111700266] = {
    id = 111700266,
    name = "噗！你也洗洗啊。"
  },
  [111700267] = {
    id = 111700267,
    name = "你抹了把脸，举起沾满砂的手对她笑了笑。收拾好后，你们重新进入矿洞，开始挑选和切割......"
  },
  [111700268] = {
    id = 111700268,
    name = "嗯？这是什么？"
  },
  [111700269] = {
    id = 111700269,
    name = "看起来像未完成的雕塑。"
  },
  [111700270] = {
    id = 111700270,
    name = "唔，和墙上的壁画还有些像。"
  },
  [111700271] = {
    id = 111700271,
    name = "你顺着伊涅利丝的目光看去，山壁上有一张神像壁画，是女神手执法杖，朝天祈祷的模样。"
  },
  [111700272] = {
    id = 111700272,
    name = "是希望女神。"
  },
  [111700273] = {
    id = 111700273,
    name = "......神。你信这个世界有神吗？"
  },
  [111700274] = {id = 111700274, name = "你呢？"},
  [111700275] = {
    id = 111700275,
    name = "我不信，我只信我自己。"
  },
  [111700276] = {
    id = 111700276,
    name = "嗯？为什么？"
  },
  [111700277] = {
    id = 111700277,
    name = "我曾经是希望有神的，可那一天，我祈求到最后，都没有一个神明降临。我甚至想过，不管谁出现在我面前，就算是恶魔，我也信。"
  },
  [111700278] = {
    id = 111700278,
    name = "那一天？"
  },
  [111700279] = {
    id = 111700279,
    name = "没什么。差不多足够了吧。"
  },
  [111700280] = {
    id = 111700280,
    name = "她拍了拍装满的推车。"
  },
  [111700281] = {
    id = 111700281,
    name = "嗯，回去吧。如果其他材料收集顺利，应该可以修好你的屋子了。"
  },
  [111700282] = {
    id = 111700282,
    name = "结界果然失效了。"
  },
  [111700283] = {
    id = 111700283,
    name = "你们毫无阻力地走进了山谷，伊涅利丝看着身后的谷口发愁。"
  },
  [111700284] = {
    id = 111700284,
    name = "算了，先修好房子。等等，你们几个会修吗？"
  },
  [111700285] = {
    id = 111700285,
    name = "......大家一起的话，应该会？"
  },
  [111700286] = {
    id = 111700286,
    name = "伊涅利丝将信将疑地看了你一眼，走入山谷，她的眼神又黯淡了下来。"
  },
  [111700287] = {
    id = 111700287,
    name = "老师，你们回来了。"
  },
  [111700288] = {
    id = 111700288,
    name = "这里已经基本打理好了，原来的地基碎石都清扫出去了。"
  },
  [111700289] = {
    id = 111700289,
    name = "木材我已经弄到手了，但要等明天才能送过来。"
  },
  [111700290] = {
    id = 111700290,
    name = "好，大家辛苦了。"
  },
  [111700291] = {
    id = 111700291,
    name = "锵锵~看！这是小莎的战利品！"
  },
  [111700292] = {
    id = 111700292,
    name = "你看到空地旁摆了一大堆桌椅摆件，锅碗瓢盆，忽然觉得有些头疼。"
  },
  [111700293] = {
    id = 111700293,
    name = "你的同伴......都还挺热心的。"
  },
  [111700294] = {
    id = 111700294,
    name = "......我们先把准备工作做好吧。"
  },
  [111700295] = {
    id = 111700295,
    name = "等等，你们在打扫的时候，有没有看到一颗魔法石？"
  },
  [111700296] = {id = 111700296, name = "没有。"},
  [111700297] = {
    id = 111700297,
    name = "魔法石，难道是......咕咕吃掉的那个？"
  },
  [111700298] = {
    id = 111700298,
    name = "什么？！被魔物吃了？！"
  },
  [111700299] = {
    id = 111700299,
    name = "......你，你别生气啊，我们会赔给你的。"
  },
  [111700300] = {
    id = 111700300,
    name = "伊涅利丝张了张嘴，她恶狠狠地看了你一眼，眼底伤心比愤怒更多。"
  },
  [111700301] = {id = 111700301, name = "抱歉。"},
  [111700302] = {
    id = 111700302,
    name = "那是可以防护巨型魔物的攻击的魔法石，父亲把它镶嵌在屋顶，可以保护屋子不被外力攻击。你们确定都找过了？"
  },
  [111700303] = {
    id = 111700303,
    name = "如果你说屋顶的那个，那......真的是被咕咕吃掉了，嘿嘿，我当时还和它抢来着......"
  },
  [111700304] = {id = 111700304, name = "......"},
  [111700305] = {
    id = 111700305,
    name = "原来如此，所以房子突然塌了是因为咕咕从内部撞断了房梁，又将加固的宝石吞掉了。"
  },
  [111700306] = {
    id = 111700306,
    name = "......算了。"
  },
  [111700307] = {
    id = 111700307,
    name = "再坚固的东西，从内部都会被轻易瓦解，何况只是一座房子。嗯？你在做什么？"
  },
  [111700308] = {
    id = 111700308,
    name = "尼莉莎趴在地上，用树枝将宝石的模样画了出来。"
  },
  [111700309] = {
    id = 111700309,
    name = "我怕忘了，先画下来，之后也好找给你啊。"
  },
  [111700310] = {
    id = 111700310,
    name = "......如果是防护型的魔法石，我倒是想到好几种可能性。"
  },
  [111700311] = {
    id = 111700311,
    name = "那我们明天去圈落找找，看能不能买到一样的。"
  },
  [111700312] = {
    id = 111700312,
    name = "买不到的，那块宝石，父亲找了很久才只找到一小块，目前为止，我也没有见到可以代替的魔法宝石，之后再说吧。"
  },
  [111700313] = {
    id = 111700313,
    name = "清扫得也差不多了，你开工吧。"
  },
  [111700314] = {
    id = 111700314,
    name = "伊涅利丝向你抛来一块石料，你接在手中沉甸甸的。"
  },
  [111700315] = {
    id = 111700315,
    name = "菲尼斯。"
  },
  [111700316] = {
    id = 111700316,
    name = "好好，这种苦累的活，当然是我们上了。"
  },
  [111700317] = {
    id = 111700317,
    name = "快天黑了，尼莉莎，跟我去弄点吃的。"
  },
  [111700318] = {
    id = 111700318,
    name = "小莎累了要休......哇啊，你拖我干嘛！"
  },
  [111700319] = {
    id = 111700319,
    name = "别想偷懒。"
  },
  [111700320] = {
    id = 111700320,
    name = "尼莉莎被蒂娜拖出了山谷，伊涅利丝看见准备生火的安妮斯，决定去帮忙。"
  },
  [111700321] = {
    id = 111700321,
    name = "我来帮你。"
  },
  [111700322] = {
    id = 111700322,
    name = "嗯，伊涅利丝小姐，麻烦你了。"
  },
  [111700323] = {
    id = 111700323,
    name = "别太在意，我知道你们不是故意的，没有责怪你们。况且你们应该有自己的行程吧，发生这种意外谁也不想。"
  },
  [111700324] = {
    id = 111700324,
    name = "呵呵，我竟然反过来安慰你了。"
  },
  [111700325] = {
    id = 111700325,
    name = "伊涅利丝架着柴火，朝你看了过来。"
  },
  [111700326] = {
    id = 111700326,
    name = "你们的队长，真的会盖房子吗？"
  },
  [111700327] = {
    id = 111700327,
    name = "老师很厉害，什么都会。"
  },
  [111700328] = {
    id = 111700328,
    name = "......是吗。但盖房子就是把石头堆起来？怎么看也不牢固吧？"
  },
  [111700329] = {
    id = 111700329,
    name = "你听到了伊涅利丝的质疑，戳了戳石块。刺啦——石块移动了一截。"
  },
  [111700330] = {id = 111700330, name = "......"},
  [111700331] = {
    id = 111700331,
    name = "队长，你想拖延进度也别搞破坏啊，这可是我辛辛苦苦堆起来的城堡。"
  },
  [111700332] = {
    id = 111700332,
    name = "......别玩了。"
  },
  [111700333] = {
    id = 111700333,
    name = "你忽然想到了什么，在收拾出的工具里找出了一罐瓶子。"
  },
  [111700334] = {
    id = 111700334,
    name = "果然有。这是鬼面魔蛛的黏液，能严丝合缝地将石料粘在一起。"
  },
  [111700335] = {
    id = 111700335,
    name = "啊，那是父亲留下的东西，我不知道有什么用，就让它一直在角落里了，没想到还能用来修补房屋。"
  },
  [111700336] = {
    id = 111700336,
    name = "想不到，你们队长还挺见多识广的。"
  },
  [111700337] = {
    id = 111700337,
    name = "老师很厉害，什么都会。"
  },
  [111700338] = {
    id = 111700338,
    name = "知道了，不用强调第二次。"
  },
  [111700339] = {
    id = 111700339,
    name = "安妮斯点燃了火焰，火光映照着她的脸，柔和的微笑让伊涅利丝平静了下来。"
  },
  [111700340] = {
    id = 111700340,
    name = "我过去监督他们。"
  },
  [111700341] = {
    id = 111700341,
    name = "你来了，正好，麻烦把你脚下的那块给我。"
  },
  [111700342] = {
    id = 111700342,
    name = "伊涅利丝配合地协助你。"
  },
  [111700343] = {id = 111700343, name = "谢谢。"},
  [111700344] = {
    id = 111700344,
    name = "噗嗤，明明是你在修我的房子，怎么还跟我说“谢谢”。"
  },
  [111700345] = {
    id = 111700345,
    name = "......弄坏了你的房子，真的很抱歉。"
  },
  [111700346] = {
    id = 111700346,
    name = "哼，看你们这么诚心的份上，我就勉强原谅你们了。咳，别以为我原谅了，你们就可以不干活了。"
  },
  [111700347] = {
    id = 111700347,
    name = "放心吧，这位美丽的小姐，我们队长会对你负责的。"
  },
  [111700348] = {id = 111700348, name = "......"},
  [111700349] = {
    id = 111700349,
    name = "伊涅利丝赶紧扔了一个石块过来。"
  },
  [111700350] = {
    id = 111700350,
    name = "还有时间聊天，别偷懒！"
  },
  [111700351] = {
    id = 111700351,
    name = "......多嘴。"
  },
  [111700352] = {
    id = 111700352,
    name = "菲尼斯耸耸肩，跑到旁边去搭石块。你默默闭嘴干活。半晌，你听到了一声叹息。"
  },
  [111700353] = {
    id = 111700353,
    name = "本来有了新的打算，这下不得不再耽搁几天了。"
  },
  [111700354] = {
    id = 111700354,
    name = "打算做什么？"
  },
  [111700355] = {
    id = 111700355,
    name = "去附近那座狮山历练，顺便找找父亲的遗物。"
  },
  [111700356] = {
    id = 111700356,
    name = "你父亲已经......抱歉。"
  },
  [111700357] = {
    id = 111700357,
    name = "没关系，那已经是十多年前的事了。"
  },
  [111700358] = {
    id = 111700358,
    name = "那你现在是......独自一个人？"
  },
  [111700359] = {
    id = 111700359,
    name = "如果说像你的队友们那样的同伴吗？没有的。"
  },
  [111700360] = {
    id = 111700360,
    name = "......父亲死后，我被诺伯特叔叔收养，诺伯特叔叔被陛下敕封为男爵，我也成了他名义上的女儿。"
  },
  [111700361] = {
    id = 111700361,
    name = "原来如此，这就是你举手投足都不像一个普通的探险者的原因。"
  },
  [111700362] = {
    id = 111700362,
    name = "伊涅利丝摇摇头。"
  },
  [111700363] = {
    id = 111700363,
    name = "“贵族大小姐”的身份，让我很难交到真心的朋友。"
  },
  [111700364] = {
    id = 111700364,
    name = "深渊中一个人行动很危险，以你的身份，找一个帮手并不难。"
  },
  [111700365] = {
    id = 111700365,
    name = "可我只想和信任的人并肩作战，就像父亲和诺伯特叔叔那样，为其付出性命也甘愿的人。"
  },
  [111700366] = {
    id = 111700366,
    name = "再说，我已经习惯一个人了。虽然诺伯特叔叔待我很好，但在那个家里，我始终是外人。"
  },
  [111700367] = {
    id = 111700367,
    name = "伊涅利丝淡淡地笑了笑，你看得出她眼中有羡慕的光。"
  },
  [111700368] = {
    id = 111700368,
    name = "我们回来了。"
  },
  [111700369] = {
    id = 111700369,
    name = "简直大丰收啊！伊涅利丝，来我们一起做吃的啊~"
  },
  [111700370] = {
    id = 111700370,
    name = "......好。"
  },
  [111700371] = {
    id = 111700371,
    name = "一段时间后......"
  },
  [111700372] = {
    id = 111700372,
    name = "好香啊，伊涅利丝小姐的手艺真棒。"
  },
  [111700373] = {
    id = 111700373,
    name = "哼哼，那我呢？"
  },
  [111700374] = {
    id = 111700374,
    name = "小莎还有蒂娜也很棒！"
  },
  [111700375] = {
    id = 111700375,
    name = "我已经闻到香味了。"
  },
  [111700376] = {
    id = 111700376,
    name = "很快就好了。"
  },
  [111700377] = {
    id = 111700377,
    name = "日暮将近，你们才重新搭好了地基与框架，赶上了晚餐时间。"
  },
  [111700378] = {
    id = 111700378,
    name = "好了，等明天的材料一到，把木材装上去，就应该没问题了。"
  },
  [111700379] = {
    id = 111700379,
    name = "这种房子真的牢固吗？"
  },
  [111700380] = {
    id = 111700380,
    name = "老师修的，一定没问题。"
  },
  [111700381] = {
    id = 111700381,
    name = "嗯。很厉害，已经出乎我的意料了。"
  },
  [111700382] = {
    id = 111700382,
    name = "不负所托，你满意就好。"
  },
  [111700383] = {
    id = 111700383,
    name = "你扬了扬手里的食物，伊涅利丝展开了笑颜。"
  },
  [111700384] = {
    id = 111700384,
    name = "咦，那边是？"
  },
  [111700385] = {
    id = 111700385,
    name = "哦，你说房子后面那块空地？顺便整理出来的，明天我打算再去一趟圈落。"
  },
  [111700386] = {
    id = 111700386,
    name = "报名参加！"
  },
  [111700387] = {
    id = 111700387,
    name = "呵呵，那我和蒂娜也去吧，正好筹备一些物资。"
  },
  [111700388] = {id = 111700388, name = "好。"},
  [111700389] = {
    id = 111700389,
    name = "行吧，你们都走了，我就留在这搭木材，脏活累活都交给我。"
  },
  [111700390] = {
    id = 111700390,
    name = "别装可怜，我知道你有帮手。"
  },
  [111700391] = {id = 111700391, name = "哦。"},
  [111700392] = {id = 111700392, name = "......"},
  [111700393] = {
    id = 111700393,
    name = "你们到达了圈落，蒂娜与安妮斯决定去筹备物资。"
  },
  [111700394] = {
    id = 111700394,
    name = "老师是打算去那边看看吗？"
  },
  [111700395] = {
    id = 111700395,
    name = "嗯，房子后面的空地，我想添置一些东西，作为给伊涅利丝小姐的赔偿。"
  },
  [111700396] = {
    id = 111700396,
    name = "那我们分开行动，安妮斯，我们去筹备物资吧。"
  },
  [111700397] = {id = 111700397, name = "啊？"},
  [111700398] = {
    id = 111700398,
    name = "不是你说要去的吗？"
  },
  [111700399] = {
    id = 111700399,
    name = "......那个，好吧。小莎呢？"
  },
  [111700400] = {
    id = 111700400,
    name = "我和队长走！"
  },
  [111700401] = {
    id = 111700401,
    name = "嗯，那一会儿见。"
  },
  [111700402] = {
    id = 111700402,
    name = "你正打算去市集处，尼莉莎好像发现了什么新奇玩意儿，又跑掉了。"
  },
  [111700403] = {
    id = 111700403,
    name = "这家伙，就是想撇下蒂娜去玩吧......算了。"
  },
  [111700404] = {
    id = 111700404,
    name = "......队长。"
  },
  [111700405] = {
    id = 111700405,
    name = "伊涅利丝小姐。你怎么也来了？"
  },
  [111700406] = {
    id = 111700406,
    name = "......我不是跟你们来的，你们弄坏了我的东西，我也要添置的。"
  },
  [111700407] = {
    id = 111700407,
    name = "好，需要买什么，算在我头上。"
  },
  [111700408] = {
    id = 111700408,
    name = "伊涅利丝看冤大头似的看了你一眼，朝市集走了过去。很显然，伊涅利丝是这里的常客，除了对这里非常熟悉，路边的摊贩都认识她。"
  },
  [111700409] = {
    id = 111700409,
    name = "伊涅利丝小姐很受欢迎啊，大家都和你打招呼。"
  },
  [111700410] = {
    id = 111700410,
    name = "啊，也许是我买东西从来没砍过价吧。"
  },
  [111700411] = {
    id = 111700411,
    name = "早啊，伊涅利丝小姐。上次您预定的药剂还没到货呢，不过我这里有最新的药剂，愈合伤口的时间能快一倍！"
  },
  [111700412] = {
    id = 111700412,
    name = "很有用的药剂，我买了。"
  },
  [111700413] = {
    id = 111700413,
    name = "不用了，我只是随便看看。"
  },
  [111700414] = {
    id = 111700414,
    name = "拿着吧，就当是赔礼了。"
  },
  [111700415] = {
    id = 111700415,
    name = "你把新的药剂塞进伊涅利丝的手里。"
  },
  [111700416] = {
    id = 111700416,
    name = "哦哦，这位......是伊涅利丝小姐的同伴？以前从来没有见过呢。"
  },
  [111700417] = {
    id = 111700417,
    name = "他不是......"
  },
  [111700418] = {
    id = 111700418,
    name = "唉，你以前受再重的伤也不吭声，总是默默买了药就走了，现在有个人照顾你也是好事啊。"
  },
  [111700419] = {
    id = 111700419,
    name = "你以前总是受伤吗？"
  },
  [111700420] = {
    id = 111700420,
    name = "别听他胡说，我们去看别的吧。"
  },
  [111700421] = {
    id = 111700421,
    name = "伊涅利丝快步走开了。"
  },
  [111700422] = {
    id = 111700422,
    name = "......等等。"
  },
  [111700423] = {
    id = 111700423,
    name = "你几步跟上了伊涅利丝。"
  },
  [111700424] = {
    id = 111700424,
    name = "我没有逞强，我也不是逞强的人。"
  },
  [111700425] = {
    id = 111700425,
    name = "伊涅利丝忽然回头看你，神色认真。"
  },
  [111700426] = {
    id = 111700426,
    name = "相反，我很珍惜自己的性命，因为这是父亲期望的，我也会照他说的那样，活下去，追求自己的未来。"
  },
  [111700427] = {
    id = 111700427,
    name = "但什么也不做的话，只会懦弱地死在深渊里，没有了父亲的守护，我必须自己变得更强。"
  },
  [111700428] = {
    id = 111700428,
    name = "奇怪，我跟你说这些干什么。"
  },
  [111700429] = {
    id = 111700429,
    name = "伊涅利丝小姐，和我见过的贵族小姐都不同。"
  },
  [111700430] = {
    id = 111700430,
    name = "哦？你见过很多贵族小姐？"
  },
  [111700431] = {
    id = 111700431,
    name = "也没有......啊，找到了。"
  },
  [111700432] = {
    id = 111700432,
    name = "你走向卖花的少女，在她的小摊前，琳琅满目地布置了很多种类的花。"
  },
  [111700433] = {
    id = 111700433,
    name = "你想买花？"
  },
  [111700434] = {
    id = 111700434,
    name = "嗯，你喜欢花吗？"
  },
  [111700435] = {
    id = 111700435,
    name = "哈哈，哪有女孩子不喜欢花的？伊涅利丝，你来啦，这朵花送给你。"
  },
  [111700436] = {
    id = 111700436,
    name = "一朵娇滴滴的小红花放在了伊涅利丝手中。"
  },
  [111700437] = {id = 111700437, name = "谢谢。"},
  [111700438] = {
    id = 111700438,
    name = "谢什么，上次要不是你帮我，我都回不了圈落了。"
  },
  [111700439] = {
    id = 111700439,
    name = "咦，这位是......好英俊的帅哥啊~是伊涅利丝的朋友吗？"
  },
  [111700440] = {
    id = 111700440,
    name = "是，所以有友情价吗？"
  },
  [111700441] = {id = 111700441, name = "......"},
  [111700442] = {
    id = 111700442,
    name = "哎呀呀，你这个人真小气~给女孩子买花还砍价的啊？"
  },
  [111700443] = {
    id = 111700443,
    name = "就算不砍价，我要的花，你这里好像也没有。"
  },
  [111700444] = {
    id = 111700444,
    name = "什么？！我这里的花包含上百种！你想要什么奇花异草，我都能找到！"
  },
  [111700445] = {
    id = 111700445,
    name = "那“守伊”呢？"
  },
  [111700446] = {
    id = 111700446,
    name = "不就是守......什么？你要守伊？好吧，我这里的确没有守伊......"
  },
  [111700447] = {
    id = 111700447,
    name = "那种弱不禁风的花完全无法移栽啊！以我的经验，试过很多次，都失败了！没有人可以把它从土里带出来还能继续存活。"
  },
  [111700448] = {
    id = 111700448,
    name = "你在哪里见过守伊？"
  },
  [111700449] = {
    id = 111700449,
    name = "越过那座山，就在山后的森林北边，你要去摘花？奉劝你还是别去了，你带不回来的，而且最近一大群魔物占领了那个地方，来往的人都要绕着走。"
  },
  [111700450] = {
    id = 111700450,
    name = "嗯，但我还是想去看看。"
  },
  [111700451] = {
    id = 111700451,
    name = "那种花，有什么特别吗？"
  },
  [111700452] = {
    id = 111700452,
    name = "嗯，它叫“守伊”，拥有守护的力量，除了让你的新房子更坚固以外，对魔法阵也有增幅的作用。那些魔物喜欢待在那里，也应该有这个原因。"
  },
  [111700453] = {
    id = 111700453,
    name = "原来是这样。"
  },
  [111700454] = {
    id = 111700454,
    name = "既然无法移栽，我们去找些种子，种在那片空地里。"
  },
  [111700455] = {
    id = 111700455,
    name = "好，我们一起去。"
  },
  [111700456] = {
    id = 111700456,
    name = "只种一种花太单一了，这个、这个和这个都给我来几株吧。"
  },
  [111700457] = {
    id = 111700457,
    name = "好的！一共十欧泊！等等，新房子？种植？"
  },
  [111700458] = {
    id = 111700458,
    name = "哎呀呀，原来是我误会了啊。又会讨你欢心，又会过日子，还想着随时保护你，伊涅利丝，你找到好男人了呢！"
  },
  [111700459] = {
    id = 111700459,
    name = "你别误会，他不是——"
  },
  [111700460] = {
    id = 111700460,
    name = "嗯嗯，我懂的~"
  },
  [111700461] = {
    id = 111700461,
    name = "我，我们快去森林吧！"
  },
  [111700462] = {
    id = 111700462,
    name = "伊涅利丝脸色涨红地走掉了。"
  },
  [111700463] = {
    id = 111700463,
    name = "欸，她害羞了，你还不快去追人？"
  },
  [111700464] = {id = 111700464, name = "......"},
  [111700465] = {
    id = 111700465,
    name = "你赶到圈落大门，正好遇上了安妮斯几人，将接下来的打算告诉了他们。"
  },
  [111700466] = {
    id = 111700466,
    name = "那正好，去森林的话，我们可以帮忙。"
  },
  [111700467] = {
    id = 111700467,
    name = "你们去吧，我和尼莉莎把物资带回去。"
  },
  [111700468] = {
    id = 111700468,
    name = "啊，小莎才不想和你这个假正经一起。"
  },
  [111700469] = {
    id = 111700469,
    name = "别废话，走了。"
  },
  [111700470] = {
    id = 111700470,
    name = "蒂娜把一大包东西压在尼莉莎头上，尼莉莎掂了掂并不沉，跟你和安妮斯眨了眨眼走了。"
  },
  [111700471] = {
    id = 111700471,
    name = "小莎和蒂娜不会再吵了吧。"
  },
  [111700472] = {
    id = 111700472,
    name = "不会的，我们尽快出发吧，伊涅利丝小姐已经先走了。"
  },
  [111700473] = {id = 111700473, name = "嗯。"},
  [111700474] = {
    id = 111700474,
    name = "她说的就是这个森林。"
  },
  [111700475] = {
    id = 111700475,
    name = "找到伊涅利丝后，三人一同来到了森林北面。"
  },
  [111700476] = {
    id = 111700476,
    name = "不愧是常住的探险者，对附近了如指掌呢。"
  },
  [111700477] = {
    id = 111700477,
    name = "当然，我也许还知道“守伊”所在之处。"
  },
  [111700478] = {
    id = 111700478,
    name = "从这里往北走，的确有一处魔物聚集的密林，我有时会在那里历练，却未敢深入，也一直没有见到“守伊”的真面目。"
  },
  [111700479] = {
    id = 111700479,
    name = "太好了，这次有机会看到了。"
  },
  [111700480] = {
    id = 111700480,
    name = "你们走入森林，沿着一条幽暗的小道找到了北边的一株巨树。"
  },
  [111700481] = {
    id = 111700481,
    name = "你感受到了吗？越来越近了。是魔物的气息，还有......"
  },
  [111700482] = {
    id = 111700482,
    name = "还有“守伊”的香味。"
  },
  [111700483] = {
    id = 111700483,
    name = "清淡的花香混合着潮湿的泥土气息，又仿佛坠入了五彩缤纷的云朵，沁人心脾。"
  },
  [111700484] = {
    id = 111700484,
    name = "原来这就是“守伊”的味道，让人很舒适，变得清爽了。"
  },
  [111700485] = {
    id = 111700485,
    name = "我以前还以为是什么毒雾......难怪那群魔物不肯离开。"
  },
  [111700486] = {
    id = 111700486,
    name = "嗯，我们先处理掉那些魔物。"
  },
  [111700487] = {
    id = 111700487,
    name = "等等，那群魔物实力不高，但很麻烦。它们会喷射一种黏液来防止猎物逃走，那种黏液无色无味，粘性牢固，一旦粘上，只能用药剂才能洗掉。"
  },
  [111700488] = {
    id = 111700488,
    name = "我知道了，安妮斯也尽量别靠近它们。"
  },
  [111700489] = {
    id = 111700489,
    name = "是，老师。"
  },
  [111700490] = {
    id = 111700490,
    name = "你们悄悄靠近了巨树，遮掩了魔物的视线，你示意两人按兵不动，暗中看了一眼。"
  },
  [111700491] = {
    id = 111700491,
    name = "七八只魔物在紫白色的花丛沉睡，更远处，还有一只在享用落单的食物。"
  },
  [111700492] = {
    id = 111700492,
    name = "（小声）得想个办法引开它们。"
  },
  [111700493] = {
    id = 111700493,
    name = "（小声）那些花......"
  },
  [111700494] = {
    id = 111700494,
    name = "（小声）没错，我们需要保留花种。"
  },
  [111700495] = {
    id = 111700495,
    name = "（小声）我想到一个办法。"
  },
  [111700496] = {
    id = 111700496,
    name = "片刻后......"
  },
  [111700497] = {
    id = 111700497,
    name = "（小声）这样魔法阵就成功了。"
  },
  [111700498] = {
    id = 111700498,
    name = "（小声）好，我去把魔物引到这个魔法阵里，你们躲起来。"
  },
  [111700499] = {
    id = 111700499,
    name = "（小声）嗯，我就在这里等你的信号。"
  },
  [111700500] = {
    id = 111700500,
    name = "（小声）你可以去那里。"
  },
  [111700501] = {
    id = 111700501,
    name = "你指了指树上，伊涅利丝看懂了你的示意，灵巧无声地攀上了一节树梢。"
  },
  [111700502] = {
    id = 111700502,
    name = "（小心。）"
  },
  [111700503] = {
    id = 111700503,
    name = "她朝你做了个无声的口型，安妮斯也藏在了树后。"
  },
  [111700504] = {
    id = 111700504,
    name = "那么，要上了。"
  },
  [111700505] = {
    id = 111700505,
    name = "你的动静引起了魔物的注意，它们从沉睡中醒来，露出尖利的锐器，朝你扑杀而来！"
  },
  [111700506] = {
    id = 111700506,
    name = "你快速击杀了一只魔物，领了剩下的进入了魔法阵。"
  },
  [111700507] = {
    id = 111700507,
    name = "安妮斯，伊涅利丝！"
  },
  [111700508] = {
    id = 111700508,
    name = "魔法阵光芒大盛，伊涅利丝攥紧手中弓箭，瞬时拉满。箭矢裹挟着魔法，穿过枝叶与山风，一箭射穿了魔物，死死钉在魔法阵眼上！"
  },
  [111700509] = {
    id = 111700509,
    name = "吼——！！！"
  },
  [111700510] = {
    id = 111700510,
    name = "七八只魔物虚弱地倒下，被你轻松斩杀在阵中。"
  },
  [111700511] = {
    id = 111700511,
    name = "小心！！"
  },
  [111700512] = {
    id = 111700512,
    name = "一道黏液疾速喷射而来，你快速避开，与此同时，伊涅利丝的箭已经穿透了它的身躯，接着是第二箭，第三箭......直到魔物无法动弹。"
  },
  [111700513] = {
    id = 111700513,
    name = "好险，这些魔物竟然还会偷袭。"
  },
  [111700514] = {
    id = 111700514,
    name = "那家伙应该是听到同类召唤了。"
  },
  [111700515] = {
    id = 111700515,
    name = "伊涅利丝小姐箭无虚发，很厉害啊。"
  },
  [111700516] = {
    id = 111700516,
    name = "能穿行在那么多魔物里，不被摸到一片衣角，你也很厉害。"
  },
  [111700517] = {
    id = 111700517,
    name = "太好了，现在没有魔物的阻碍，我们可以采集“守伊”的种子了。"
  },
  [111700518] = {
    id = 111700518,
    name = "激烈的战斗没有波及那片紫白色的花海，此时微风吹来，花海里升起无数紫色的花瓣，花雨纷纷扬扬，仿佛洗净了山里的戾气。"
  },
  [111700519] = {
    id = 111700519,
    name = "好美啊......"
  },
  [111700520] = {
    id = 111700520,
    name = "如果在山谷里种下，也会变成这样梦幻的，像童话世界的颜色吗？"
  },
  [111700521] = {
    id = 111700521,
    name = "当然，你想怎么布置都可以。"
  },
  [111700522] = {
    id = 111700522,
    name = "我已经开始期待了。"
  },
  [111700523] = {
    id = 111700523,
    name = "你们小心翼翼采集好了花种。"
  },
  [111700524] = {
    id = 111700524,
    name = "这么多的种子，能铺满整个山谷吧？"
  },
  [111700525] = {
    id = 111700525,
    name = "种子也是有存活率的，把它们都洒在后院，看运气吧。"
  },
  [111700526] = {
    id = 111700526,
    name = "这样啊......"
  },
  [111700527] = {
    id = 111700527,
    name = "差不多了，我们回去吧。"
  },
  [111700528] = {
    id = 111700528,
    name = "那个，老师，这么美的“守伊”，我也想带几朵给蒂娜和小莎。"
  },
  [111700529] = {
    id = 111700529,
    name = "好主意，我也摘一朵。"
  },
  [111700530] = {
    id = 111700530,
    name = "安妮斯看中了脚边最大的那朵，正当她俯身正要摘下时，你看到了上面一闪而过的反光。"
  },
  [111700531] = {id = 111700531, name = "等等！"},
  [111700532] = {
    id = 111700532,
    name = "安妮斯警觉地躲开了，你正松口气，却看到伊涅利丝将它摘了下来。"
  },
  [111700533] = {
    id = 111700533,
    name = "安妮斯，给你。"
  },
  [111700534] = {id = 111700534, name = "谢谢。"},
  [111700535] = {
    id = 111700535,
    name = "你睁大眼睛，看着伊涅利丝摊开了手心，伸手阻止了安妮斯，你却不小心碰到了那朵花。"
  },
  [111700536] = {id = 111700536, name = "......"},
  [111700537] = {
    id = 111700537,
    name = "老师，怎么了？"
  },
  [111700538] = {
    id = 111700538,
    name = "伊涅利丝不赞同地看了你一眼，抓紧了这朵花，想从你手中抢过来。"
  },
  [111700539] = {
    id = 111700539,
    name = "这是给这位可爱小姐的，放手。"
  },
  [111700540] = {
    id = 111700540,
    name = "抱歉，我想我放不了手。"
  },
  [111700541] = {id = 111700541, name = "？？？"},
  [111700542] = {id = 111700542, name = "！！！"},
  [111700543] = {
    id = 111700543,
    name = "你看着和你一起无法分开的纤纤素手，不知该叹气还是该笑。"
  },
  [111700544] = {
    id = 111700544,
    name = "这是魔物的黏液？"
  },
  [111700545] = {
    id = 111700545,
    name = "我们、我们被黏液粘在一起了？!欸......欸？！！！"
  },
  [111700546] = {
    id = 111700546,
    name = "伊涅利丝小姐，不要慌，我这里有药剂。"
  },
  [111700547] = {
    id = 111700547,
    name = "伊涅利丝动来动去，你被扯了一个踉跄，安妮斯正拿出一瓶药水，还没倒出来就看你和伊涅利丝扑了上来。"
  },
  [111700548] = {
    id = 111700548,
    name = "快让开！！"
  },
  [111700549] = {id = 111700549, name = "！！！"},
  [111700550] = {
    id = 111700550,
    name = "你与伊涅利丝失去了重心，两只手如同探戈一般甩了个方向，正好落在安妮斯闭眼抬起的手上。"
  },
  [111700551] = {id = 111700551, name = "......"},
  [111700552] = {
    id = 111700552,
    name = "耳畔风声猎猎作响，轻柔的花瓣如精灵般在你们身上跳跃。那一刻，时间无限拉长，你眼睁睁地看着安妮斯的手落在了你们的手上，就那样三个人一起栽到了地面。"
  },
  [111700553] = {
    id = 111700553,
    name = "老师，伊涅利丝小姐！"
  },
  [111700554] = {
    id = 111700554,
    name = "我没事，队长好像被压到了。"
  },
  [111700555] = {
    id = 111700555,
    name = "两人慌张地从你身上起来，又被黏住的手拉了回去，再次栽倒在地，你感到一阵窒息。"
  },
  [111700556] = {
    id = 111700556,
    name = "唔......我们三个一起吧。"
  },
  [111700557] = {id = 111700557, name = "好......"},
  [111700558] = {
    id = 111700558,
    name = "......几分钟后，你们顺利起身后，面面相觑。"
  },
  [111700559] = {
    id = 111700559,
    name = "怎么办？那个药剂也洒了......"
  },
  [111700560] = {
    id = 111700560,
    name = "对不起，是我不好。"
  },
  [111700561] = {
    id = 111700561,
    name = "不，是我的错，我太大意了。"
  },
  [111700562] = {
    id = 111700562,
    name = "被两只手紧贴覆盖着，你叹了口气。"
  },
  [111700563] = {
    id = 111700563,
    name = "......这样下去不是办法，我们暂时互做对方的眼睛，先回去再说。"
  },
  [111700564] = {
    id = 111700564,
    name = "森林有不少陡峭的地方，要是遇到那种情况......"
  },
  [111700565] = {
    id = 111700565,
    name = "转圈圈？这样就算遇到魔物也不怕。"
  },
  [111700566] = {
    id = 111700566,
    name = "好，好吧......"
  },
  [111700567] = {
    id = 111700567,
    name = "你无奈地起步，一路转着圈离开了森林，如同一只笨拙失灵的风车。"
  },
  [111700568] = {
    id = 111700568,
    name = "回到山谷，尼莉莎和蒂娜好奇地走了上来。"
  },
  [111700569] = {
    id = 111700569,
    name = "你们在玩什么游戏？"
  },
  [111700570] = {
    id = 111700570,
    name = "转风车？"
  },
  [111700571] = {
    id = 111700571,
    name = "我们被魔物的黏液黏住了。"
  },
  [111700572] = {
    id = 111700572,
    name = "需要分离的溶解药剂。"
  },
  [111700573] = {
    id = 111700573,
    name = "尼莉莎噗嗤大笑出声，吸引了菲尼斯的目光。"
  },
  [111700574] = {
    id = 111700574,
    name = "哟，队长，你们手拉手在做什么约定吗？"
  },
  [111700575] = {
    id = 111700575,
    name = "别开玩笑了，快点帮我们解开。"
  },
  [111700576] = {
    id = 111700576,
    name = "冤枉，我看你们玩得挺开心的。"
  },
  [111700577] = {
    id = 111700577,
    name = "溶解药剂倒在你们交握的手心里，你感觉到了久违的自由。"
  },
  [111700578] = {
    id = 111700578,
    name = "呼......总算，总算洗掉了......"
  },
  [111700579] = {
    id = 111700579,
    name = "嗯，你们的手没事吧？"
  },
  [111700580] = {
    id = 111700580,
    name = "老师我没事。"
  },
  [111700581] = {
    id = 111700581,
    name = "还好，就是可惜了这朵花......"
  },
  [111700582] = {
    id = 111700582,
    name = "她举起手，朝你展示了一下。"
  },
  [111700583] = {
    id = 111700583,
    name = "伊涅利丝小姐真的没问题吗？脸和手心一样红......"
  },
  [111700584] = {
    id = 111700584,
    name = "我没事！"
  },
  [111700585] = {
    id = 111700585,
    name = "......不过我们还是先看看房子吧。"
  },
  [111700586] = {
    id = 111700586,
    name = "放心吧，公会......咳，从公会拿到的木材，必属佳品，绝对牢固，可防止大型魔物的撞击。"
  },
  [111700587] = {
    id = 111700587,
    name = "......还，还可以吧。"
  },
  [111700588] = {
    id = 111700588,
    name = "你满意就好。还差一个魔法石，我们找了整个圈落也没看到，不过我们会想办法的。"
  },
  [111700589] = {
    id = 111700589,
    name = "嗯，那种东西，可遇不可求，没有就算了。"
  },
  [111700590] = {
    id = 111700590,
    name = "你走向屋后的空地，用工具松松土。"
  },
  [111700591] = {
    id = 111700591,
    name = "咦，队长，你要干嘛？"
  },
  [111700592] = {
    id = 111700592,
    name = "既然带回了花种，就顺道种下去吧。"
  },
  [111700593] = {
    id = 111700593,
    name = "好啊好啊，我们一起来帮忙吧！"
  },
  [111700594] = {
    id = 111700594,
    name = "几人协作，很快就把大片空地种好了种子，安妮斯还特意加护了一个生长魔法和防护魔法，以防止魔物的破坏。"
  },
  [111700595] = {
    id = 111700595,
    name = "你们真有默契。"
  },
  [111700596] = {
    id = 111700596,
    name = "当然，我们可是同伴！是吧队长！"
  },
  [111700597] = {
    id = 111700597,
    name = "你点点头，将先前买的花拿了出来，一同洒了下去。"
  },
  [111700598] = {
    id = 111700598,
    name = "嗯？这些种子？"
  },
  [111700599] = {
    id = 111700599,
    name = "我额外买的，如果只有“守伊”一种花，未免太孤寂了，放在你的院子里吧，也算一种点缀。"
  },
  [111700600] = {
    id = 111700600,
    name = "伊涅利丝愣了愣神，忽然想起什么。"
  },
  [111700601] = {
    id = 111700601,
    name = "对了，山谷口的结界，我会重启一个魔法阵，这样外人就不能随便闯入了。"
  },
  [111700602] = {
    id = 111700602,
    name = "那太好了，我们可不想辛苦修好的房子再被破坏。"
  },
  [111700603] = {
    id = 111700603,
    name = "“守伊”不需要特殊灌养，深渊就是它最好的生存环境，等花开时，魔法力会充斥山谷，自然运转，你也会住得更舒适。"
  },
  [111700604] = {
    id = 111700604,
    name = "......谢谢，谢谢你们。"
  },
  [111700605] = {
    id = 111700605,
    name = "这是我们应该负责的。"
  },
  [111700606] = {
    id = 111700606,
    name = "差不多的话，我们也该出发了，队长。"
  },
  [111700607] = {
    id = 111700607,
    name = "你，你们要走了吗？"
  },
  [111700608] = {id = 111700608, name = "嗯。"},
  [111700609] = {id = 111700609, name = "哦......"},
  [111700610] = {
    id = 111700610,
    name = "伊涅利丝小姐，我们得到你的原谅了吗？"
  },
  [111700611] = {
    id = 111700611,
    name = "噗嗤，勉勉强强吧。"
  },
  [111700612] = {
    id = 111700612,
    name = "同伴们一一和她道别，说说笑笑地走出山谷。你感觉到身后的视线，是她一直在注视着你。"
  },
  [111700613] = {id = 111700613, name = "......"},
  [111700614] = {
    id = 111700614,
    name = "等一下。"
  },
  [111700615] = {
    id = 111700615,
    name = "你听到了靠近的脚步声，回头。"
  },
  [111700616] = {
    id = 111700616,
    name = "这个，给你吧。"
  },
  [111700617] = {id = 111700617, name = "这是？"},
  [111700618] = {
    id = 111700618,
    name = "一块木质的薄片，上面流转着特殊的魔法力。"
  },
  [111700619] = {
    id = 111700619,
    name = "能让你们自由进入山谷的东西。"
  },
  [111700620] = {
    id = 111700620,
    name = "别误会，我可不是在邀请你们，我的意思是，你们要是找到了魔法石，就自觉带回来......顺，顺便看看你种的花。"
  },
  [111700621] = {
    id = 111700621,
    name = "我知道了。"
  },
  [111700622] = {
    id = 111700622,
    name = "嗯......那么，再见了。"
  },
  [111700623] = {
    id = 111700623,
    name = "好。希望花开之时，我们能再见。"
  },
  [111610001] = {
    id = 111610001,
    name = "吼！！！行至途中，你看见一人匆匆从山头跑了下来，身后还追着两只魔物。"
  },
  [111610002] = {
    id = 111610002,
    name = "救、救命！"
  },
  [111610003] = {
    id = 111610003,
    name = "你几步上去，将魔物杀掉了，那人盯着你，露出求助的目光。"
  },
  [111610004] = {
    id = 111610004,
    name = "拜托你，救救我的村落，我们被魔物袭击了！"
  },
  [111610005] = {id = 111610005, name = "村落？"},
  [111610006] = {
    id = 111610006,
    name = "对，魔物......魔物在破坏我们的农田！"
  },
  [111610007] = {
    id = 111610007,
    name = "农田？深渊里怎么会有农田和村落？"
  },
  [111610008] = {
    id = 111610008,
    name = "没时间了，这位探险者大人，求求你快去我们村落吧！"
  },
  [111610009] = {
    id = 111610009,
    name = "......可是我也有要紧的事。"
  },
  [111610010] = {
    id = 111610010,
    name = "（安妮斯他们还等着我，这会儿跟着他去的话，恐怕会错过约定的时间。）"
  },
  [111610011] = {
    id = 111610011,
    name = "探险者大人，要是你也不帮忙的话，我们村落里的人今天都会死的！！求求你，求求你了！"
  },
  [111610012] = {
    id = 111610012,
    name = "他痛哭流涕，哽咽的语调让人动容，你仔细观察着那个人，双脚沾了许多泥，手上满是茧子，是一双经常劳作的手。"
  },
  [111610013] = {
    id = 111610013,
    name = "好吧，我们边走边说。"
  },
  [111610014] = {
    id = 111610014,
    name = "确定他只是一个没有武技与魔法的村民后，你让他带路并一路了解情况。"
  },
  [111610015] = {
    id = 111610015,
    name = "谢谢！！谢谢大人！！请走这边。"
  },
  [111610016] = {
    id = 111610016,
    name = "你刚才说你的村落和农田，深渊里还能种粮食？"
  },
  [111610017] = {
    id = 111610017,
    name = "是的，我们都是霍德圈落附近的村民，先前有一名大药剂师，是他改良了附近的土地，让圈落都能种植麦子，虽然收成不高，但好歹也比那些野草强。"
  },
  [111610018] = {
    id = 111610018,
    name = "（霍德圈落？没听说过这个圈落的名字，能让深渊种出粮食的药剂师，也应该鼎鼎有名了吧......）"
  },
  [111610019] = {
    id = 111610019,
    name = "最近到了那些麦子成熟的时候，魔物就会来抢......"
  },
  [111610020] = {
    id = 111610020,
    name = "现在魔物来了一波又一波，村民们都快扛不住了，只能去外面求援。"
  },
  [111610021] = {
    id = 111610021,
    name = "大、大人！魔物又来了！"
  },
  [111610022] = {
    id = 111610022,
    name = "又是几只魔物冲了上来，你解决掉之后，村民扒拉下了魔物的尖角用来防身，看他半点不会武技的样子，你也没有阻止他，有个东西也聊胜于无。"
  },
  [111610023] = {
    id = 111610023,
    name = "大人，魔物应该还不止这些。"
  },
  [111610024] = {
    id = 111610024,
    name = "那就快带路吧。"
  },
  [111610025] = {
    id = 111610025,
    name = "大人，您沿着这条路穿过去，就能看到我们的村落了。"
  },
  [111610026] = {
    id = 111610026,
    name = "那你......"
  },
  [111610027] = {
    id = 111610027,
    name = "我还要继续找人求救，拜托了，大人！"
  },
  [111610028] = {
    id = 111610028,
    name = "村民朝你深深鞠了一躬，飞快地跑向了圈落的方向。"
  },
  [111610029] = {
    id = 111610029,
    name = "扰乱农作物的魔物吗，先去看看，再想办法通知安妮斯他们吧。"
  },
  [111610030] = {
    id = 111610030,
    name = "大家先往后退！把这几个魔物引到东南方向！"
  },
  [111610031] = {
    id = 111610031,
    name = "不行，再坚持一下，那是最后一个陷阱了......一旦魔物越过去，村落就完了！我还能战斗，不能退！"
  },
  [111610032] = {
    id = 111610032,
    name = "你来到村落的时候，正好看到村民和魔物在殊死搏斗，你快速加入了战斗，魔法闪电般刺穿魔物的身体，魔物发出一声痛苦的嚎叫，但它并未被击溃，反而更加愤怒地挥舞着巨臂向你袭来。"
  },
  [111610033] = {
    id = 111610033,
    name = "探险者大人！"
  },
  [111610034] = {
    id = 111610034,
    name = "你躲闪反击，击退了一只魔物，而另一只又冲上来朝村民扑了过去！"
  },
  [111610035] = {id = 111610035, name = "趴下！"},
  [111610036] = {
    id = 111610036,
    name = "你挥手击中魔物下颌，一脚将魔物踹了出去，魔物咆哮着再次带着几只冲了上来！"
  },
  [111610037] = {
    id = 111610037,
    name = "糟了，它被激怒了！"
  },
  [111610038] = {
    id = 111610038,
    name = "小心，探险者大人！"
  },
  [111610039] = {
    id = 111610039,
    name = "利爪和尖牙凶悍地撕裂着眼前的一切，你只身一人难以分神，无法在战斗同时兼顾村民，没一会儿那几人又被魔物抓伤了。"
  },
  [111610040] = {id = 111610040, name = "跑！"},
  [111610041] = {
    id = 111610041,
    name = "你是来救我们的，怎么可以抛下你！"
  },
  [111610042] = {
    id = 111610042,
    name = "我们留在这里也是累赘，糟了，探险者大人，后续的魔物也快来了，我们一起撤退！"
  },
  [111610043] = {
    id = 111610043,
    name = "好不容易杀掉了一只魔物，你竟然见到远处更多的魔物，心下迅速判断，浮起一种危机的感觉。"
  },
  [111610044] = {
    id = 111610044,
    name = "我的天，这些魔物......那个陷阱也没用的！村落要完了吗！"
  },
  [111610045] = {
    id = 111610045,
    name = "又一只魔物朝伤员扑了上去，你刚处理掉手中的魔物，眼见已经来不及了！"
  },
  [111610046] = {
    id = 111610046,
    name = "先躲开！"
  },
  [111610047] = {id = 111610047, name = "！！！"},
  [111610048] = {
    id = 111610048,
    name = "千钧一刻之际，一道弧光瞬息而至，魔物被击中了要害，尖叫嘶吼地倒在伤员面前。与此同时，一名少女踏入了战圈之中，她的衣衫华美，手中长剑寒芒闪烁。"
  },
  [111610049] = {
    id = 111610049,
    name = "圣剑使！圣剑使大人！"
  },
  [111610050] = {
    id = 111610050,
    name = "少女没理会这个人，反而看向了你，她的目光锐利，从容不迫。"
  },
  [111610051] = {
    id = 111610051,
    name = "接下来的魔物，你我左右合击，先清理周围的，再解决中间那个。"
  },
  [111610052] = {id = 111610052, name = "可以。"},
  [111610053] = {
    id = 111610053,
    name = "她只看了一眼就制定好了目前最适合的作战计划，你什么都没问，仿佛早有默契般和她一起冲了上去！"
  },
  [111610054] = {
    id = 111610054,
    name = "我负责右边，左边的交给你了！"
  },
  [111610055] = {
    id = 111610055,
    name = "少女的身影快如闪电，在逼近魔物之时原地踏跃而起，一剑至上而下，狠狠刺入魔物要害，紧接着翻身挥剑，在尸体落下的同时恰好挡住了另一只魔物的攻击。"
  },
  [111610056] = {
    id = 111610056,
    name = "不愧是圣剑使大人！三两下就杀掉了魔物！"
  },
  [111610057] = {
    id = 111610057,
    name = "战斗之余，你看了一眼少女，她的剑又快又准，并且越战越快，刚抽出魔物的躯体的剑，很快刺向下一个魔物。有血液飞溅而至，她横剑挡下，繁丽的衣裙没有沾染半分。"
  },
  [111610058] = {
    id = 111610058,
    name = "有了强势的战力加入，你摆脱了顾此失彼的困境，全力应付眼前的魔物，很快战斗就到了尾声。"
  },
  [111610059] = {
    id = 111610059,
    name = "魔物，听从剑的圣裁吧！"
  },
  [111610060] = {
    id = 111610060,
    name = "少女目光坚定明亮，手中长剑剑芒暴涨，泠泠剑意刺穿了最后一只魔物的头颅，魔物轰然倒地，她看到已经结束战斗的你，眼里闪过一抹意外之色，接着看向了那两个村民。"
  },
  [111610061] = {
    id = 111610061,
    name = "结束了，你们没事了。"
  },
  [111610062] = {
    id = 111610062,
    name = "感谢你们！圣剑使大人，探险者大人，要不是你们，我们的村落就保不住了！"
  },
  [111610063] = {
    id = 111610063,
    name = "把这些魔物收拾一下吧。"
  },
  [111610064] = {
    id = 111610064,
    name = "不，不，这些魔物材料归属是两位大人的，我们怎么敢要。"
  },
  [111610065] = {
    id = 111610065,
    name = "不收拾的话，其他魔物闻到气味会很快赶来的。"
  },
  [111610066] = {
    id = 111610066,
    name = "我，我们来帮忙！"
  },
  [111610067] = {
    id = 111610067,
    name = "你收起武器开始拖拽魔物的尸体。一切收拾结束后，她的胸膛微微起伏着，湿润的发丝粘在额角边，刚忙碌后的脸上有些微红。"
  },
  [111610068] = {
    id = 111610068,
    name = "好了，我该走了。"
  },
  [111610069] = {
    id = 111610069,
    name = "请等一等。"
  },
  [111610070] = {
    id = 111610070,
    name = "怎么了？圣剑使？"
  },
  [111610071] = {
    id = 111610071,
    name = "黑羽。叫我黑羽，慈悲的圣剑使只是一个虚名。"
  },
  [111610072] = {
    id = 111610072,
    name = "她的目光看向了你，迟疑了一瞬后，向你发出了邀请。"
  },
  [111610073] = {
    id = 111610073,
    name = "那个，这些魔物只是危机的一部分。他们的防御工事需要人手......你，你能和我一起去吗？"
  },
  [111610074] = {
    id = 111610074,
    name = "不好意思，黑羽小姐，我和同伴有约定，现在已经快迟到了。"
  },
  [111610075] = {
    id = 111610075,
    name = "抱歉，我知道这很突然，但我一个人也许无法完全保护那些手无寸铁的人。"
  },
  [111610076] = {
    id = 111610076,
    name = "我看得出你是一个武技和魔法都很精湛的探险者，如果能一起去的话，面对魔物的突袭，村落也会多一份安全的保障。"
  },
  [111610077] = {
    id = 111610077,
    name = "......（既然已经说到这个份上，我再推辞就是见死不救了。）"
  },
  [111610078] = {
    id = 111610078,
    name = "两位大人，我们必须马上赶回去，村落的很多防御工事被魔物破坏，如果不修好，那些魔物再来的时候，村落就真的一点抵抗的力量都没有了。"
  },
  [111610079] = {
    id = 111610079,
    name = "你等等，我写一封信给我的同伴。"
  },
  [111610080] = {
    id = 111610080,
    name = "没问题！请交给我！我一定找人帮您送到！"
  },
  [111610081] = {id = 111610081, name = "你......"},
  [111610082] = {
    id = 111610082,
    name = "走吧，一起去村庄。"
  },
  [111610083] = {
    id = 111610083,
    name = "多谢圣剑使大人，探险者大人！"
  },
  [111610084] = {
    id = 111610084,
    name = "两人领着你和黑羽进入了村庄，村民很快将信交给了一名精瘦的小伙，根据你告诉他的地址飞快地离开了。"
  },
  [111610085] = {
    id = 111610085,
    name = "黑羽主动帮助村民修筑防御工事，一群人见到你们肯帮忙，无不欢喜雀跃。"
  },
  [111610086] = {
    id = 111610086,
    name = "圣剑使、探险者大人，请喝水。"
  },
  [111610087] = {
    id = 111610087,
    name = "这些魔物到底怎么回事？目前已经袭击了第三次了吧？"
  },
  [111610088] = {
    id = 111610088,
    name = "唉......每年这个时候魔物都会袭击我们的农田，今年尤其多一些。"
  },
  [111610089] = {
    id = 111610089,
    name = "知道是什么原因吗？"
  },
  [111610090] = {
    id = 111610090,
    name = "也许是因为农作物吧，圈落每年都在改良种子和配方，虽然收成越来越好，但袭击的魔物也一年比一年多。"
  },
  [111610091] = {
    id = 111610091,
    name = "只靠这些简单的栅栏......要是夜里魔物暗袭，恐怕防不胜防。"
  },
  [111610092] = {
    id = 111610092,
    name = "这也是没有办法的办法，许多人都离开村落探险了，剩下的就我们两个会一些武技，一开始还能应付，到后来越来越多，我们就只能做一些陷阱和工事，能挡多少是多少。"
  },
  [111610093] = {
    id = 111610093,
    name = "只是再这样下去，村落就真的保不住了......村里的人，该怎么办啊......"
  },
  [111610094] = {
    id = 111610094,
    name = "不要太忧心，还没有到最绝望的时候，我和......"
  },
  [111610095] = {
    id = 111610095,
    name = "黑羽看向你的时候，你点了点头，她才认真地继续说了下去。"
  },
  [111610096] = {
    id = 111610096,
    name = "我和他都会帮你们的，先把这些陷阱和栅栏修好吧。"
  },
  [111610097] = {
    id = 111610097,
    name = "谢谢，谢谢你们，有你们相助，我的家人就有救了啊。"
  },
  [111610098] = {
    id = 111610098,
    name = "......大人，这些材料都损坏了，劳烦两位大人在这里等候，我叫几个人去山里背些材料回来。"
  },
  [111610099] = {
    id = 111610099,
    name = "外面魔物环伺，我跟你一起出去。"
  },
  [111610100] = {
    id = 111610100,
    name = "还是我去吧，顺便也能帮他多拿一些材料。你就留下来，如果魔物再来偷袭，也好有个防范。"
  },
  [111610101] = {
    id = 111610101,
    name = "黑羽意外地看了看你，淡色的眼角微微弯了弯，你感觉到了一丝若有似无的笑意。"
  },
  [111610102] = {
    id = 111610102,
    name = "......好。你们请多小心。"
  },
  [111610103] = {
    id = 111610103,
    name = "你与几个村民一同到达了附近的森林，领头人快速地指挥村民们砍树搬石料。"
  },
  [111610104] = {
    id = 111610104,
    name = "我们抓紧时间。探险者大人，麻烦你在这里等候。"
  },
  [111610105] = {
    id = 111610105,
    name = "不用我帮忙吗？"
  },
  [111610106] = {
    id = 111610106,
    name = "探险者大人能护送我们过来，我们已经感激不尽了，先前大人才经历了一场战斗，请先在这里休息吧。"
  },
  [111610107] = {
    id = 111610107,
    name = "村民们坚持不让你帮忙，你也就顺他们靠在树边休息，观察着四周的动静。"
  },
  [111610108] = {
    id = 111610108,
    name = "你们是什么时候搬来这里的？怎么没留在地面？"
  },
  [111610109] = {
    id = 111610109,
    name = "好几年了。大人，现在地面上的日子越来越不好过了，大家都在说进深渊探险能赚大钱，就算没拿到圣物宝物，就算摘莹草也能卖个好价钱。"
  },
  [111610110] = {
    id = 111610110,
    name = "唉，谁知道下了深渊才知道，除了要担心饿肚子，还要想能不能活过明天。"
  },
  [111610111] = {
    id = 111610111,
    name = "没想过回地面吗？"
  },
  [111610112] = {
    id = 111610112,
    name = "回不去喽。"
  },
  [111610113] = {
    id = 111610113,
    name = "他摇了摇头，继续搬下一捆木料，你忽然想起先前在村落中看到其中还有妇孺儿童，那是他们的家人。许多人为了所谓的梦想，拖家带口离开生活多年的地方，就只是为了得到埋藏在深渊中的财富吗？"
  },
  [111610114] = {
    id = 111610114,
    name = "那个村民又抱了一大堆木料过来，一个个缠绕打结，长满老茧的手也勒出了几道血痕，但他看起来毫不在意。"
  },
  [111610115] = {
    id = 111610115,
    name = "像我们这样，能有固定的村落住着已经不错了，跟我们一起下来的好些个都死在了去圈落的路上。好在大家到了圈落之后，日子总算能过下去了一点。"
  },
  [111610116] = {
    id = 111610116,
    name = "那怎么又从圈落出来了？"
  },
  [111610117] = {
    id = 111610117,
    name = "没办法，我们空有一肚子想法，没本事啊，到圈落里的哪个不是拿刀拿剑的，等以前的老本吃完，只能当个拾荒者了，还好圈落给了我们活下去的机会。"
  },
  [111610118] = {
    id = 111610118,
    name = "那些地和种子都是圈落给的，每年上交一定数额的收成，来年就能继续种地。呵呵，能有个安定的日子，谁想东奔西走呢？"
  },
  [111610119] = {id = 111610119, name = "......"},
  [111610120] = {
    id = 111610120,
    name = "村民们一直忙碌着，你看不清他们脸上究竟是什么表情，或许能就此结束颠沛流离，奔波流浪的日子，也是他们心中所希望的；又或许他们无法满足现状，却也无力改变现状......"
  },
  [111610121] = {id = 111610121, name = "吼——"},
  [111610122] = {
    id = 111610122,
    name = "不远处魔物咆哮，几个村民身体同时一颤，看向了声音的方向。"
  },
  [111610123] = {
    id = 111610123,
    name = "抓紧时间！魔物快来了！"
  },
  [111610124] = {
    id = 111610124,
    name = "大家别慌，我去看看。"
  },
  [111610125] = {
    id = 111610125,
    name = "村民们立刻收拾好，纷纷从背后抽出了棍棒弓箭，你没往前走几步，几只魔物似乎察觉到了这边人类活动的痕迹，已经摸索着爬了过来。"
  },
  [111610126] = {
    id = 111610126,
    name = "你们几个快去布置陷阱，我们随时准备支援探险者大人！"
  },
  [111610127] = {
    id = 111610127,
    name = "你观察了几只魔物，估算了一下战力，一起应付恐怕吃力，只能分而击破，思忖之下，你屏息等着魔物爬过之时果断出击，将队伍最后一只魔物斩成两段！"
  },
  [111610128] = {id = 111610128, name = "吼——"},
  [111610129] = {
    id = 111610129,
    name = "魔物齐齐转身，敏捷地一只又一只扑了上来，你快速跑走，心想着将如何引走再一只只分解灭杀。"
  },
  [111610130] = {
    id = 111610130,
    name = "魔物去追探险者大人了......"
  },
  [111610131] = {
    id = 111610131,
    name = "他愣了愣，瞬间陷入了纠结，很快他便做下了决定，让村民们收拾从另一条路下山，却被拒绝了。"
  },
  [111610132] = {
    id = 111610132,
    name = "要走一起走啊，兄弟，咱们少了谁都不行！"
  },
  [111610133] = {
    id = 111610133,
    name = "一个人的力量微不足道，但他们联合起来的防御阵线却能阻挡魔物，这是他们在多次生死存亡后的生存至理，那就是不到最后一刻不放弃任何一个人。"
  },
  [111610134] = {
    id = 111610134,
    name = "......好，我们一起去帮探险者大人！"
  },
  [111610135] = {
    id = 111610135,
    name = "此刻你正好见到路边倒塌的枝干，挑起最近的魔物砸进了魔物群中心，冷静地杀掉飞向你的魔物后，竟然看到了几个人影从后面跑了过来。"
  },
  [111610136] = {
    id = 111610136,
    name = "大人，我们来帮你！"
  },
  [111610137] = {id = 111610137, name = "......"},
  [111610138] = {
    id = 111610138,
    name = "你想让他们别出声，但已来不及了，几只魔物的注意力被他们吸引了过去，而你也只能优先应付眼前的魔物。"
  },
  [111610139] = {
    id = 111610139,
    name = "防御阵线列队！杀魔物！"
  },
  [111610140] = {
    id = 111610140,
    name = "几人有序地背靠背组成了齿轮形状的阵型，面对多只魔物的进攻，几人相互照应，竟然也打得有来有往。"
  },
  [111610141] = {
    id = 111610141,
    name = "你处理了手里的魔物，很快加入了支援，将剩下的魔物灭杀殆尽。"
  },
  [111610142] = {
    id = 111610142,
    name = "都没事吧？"
  },
  [111610143] = {
    id = 111610143,
    name = "没事，一点小伤不用在意，倒是大人的武技，一点也不比圣剑使大人差啊！"
  },
  [111610144] = {
    id = 111610144,
    name = "你们为什么一直叫她圣剑使？"
  },
  [111610145] = {
    id = 111610145,
    name = "因为大家都叫她圣剑使大人啊，村里还有诗人专门为她写的歌，我家小孩都会唱呢。"
  },
  [111610146] = {
    id = 111610146,
    name = "是吗......"
  },
  [111610147] = {
    id = 111610147,
    name = "说起黑羽，村民们都是一副敬仰的模样。那个善战的少女看起来优雅淡然，却总保持着模糊的距离感，让人敬而远之。"
  },
  [111610148] = {
    id = 111610148,
    name = "大人，这里都出现了魔物，我怕村里也......"
  },
  [111610149] = {
    id = 111610149,
    name = "村里有圣剑使大人守着呢，兄弟也别太担心了，那些材料都收集得差不多了，咱们快回去吧。"
  },
  [111610150] = {
    id = 111610150,
    name = "嗯，走吧。"
  },
  [111610151] = {
    id = 111610151,
    name = "我们回来了！"
  },
  [111610152] = {
    id = 111610152,
    name = "一声呐喊，村里的人纷纷跑了出来，你看到黑羽身后跟着几个小孩子，她上前朝你走了两步。"
  },
  [111610153] = {
    id = 111610153,
    name = "辛苦了，这本该是我去帮忙的事。"
  },
  [111610154] = {
    id = 111610154,
    name = "他们把材料都搬回来了，我先去帮忙修筑防御工事。"
  },
  [111610155] = {
    id = 111610155,
    name = "嗯，我跟你一起去。"
  },
  [111610156] = {
    id = 111610156,
    name = "你和黑羽到村口加入了重建的工作，黑羽毫不嫌弃那些石料与长满木刺的栅栏，仍旧淡然地帮助村民，而且看起来心情不错。"
  },
  [111610157] = {
    id = 111610157,
    name = "啊，我还没唱歌给圣剑使大人听呢......"
  },
  [111610158] = {
    id = 111610158,
    name = "行了，没事就回去了，别在这碍手碍脚的。"
  },
  [111610159] = {
    id = 111610159,
    name = "哼，你也是伤员，还说我碍手碍脚，以后我要去学剑，变得和圣剑使大人一样厉害，看你还敢不敢小瞧我！"
  },
  [111610160] = {
    id = 111610160,
    name = "啧，人不大野心不小，麻溜地滚回去。"
  },
  [111610161] = {
    id = 111610161,
    name = "喂喂，你看，圣剑使大人刚刚是不是笑了啊？她笑得可真好看，就像歌里唱得一样好看。"
  },
  [111610162] = {
    id = 111610162,
    name = "黑羽的确笑了，当她听到你独自引开魔物，最后和村民们一起杀掉魔物的过程，露出了浅浅的笑。"
  },
  [111610163] = {
    id = 111610163,
    name = "不要小瞧了他们，为守护家人和田地的这份决心就是他们最强的力量了。"
  },
  [111610164] = {
    id = 111610164,
    name = "的确，保护没有武技和魔法的普通人，是我作为探险者下意识的决定。不过如果是你，你当时会怎么选？"
  },
  [111610165] = {
    id = 111610165,
    name = "黑羽怔愣了一瞬，很慎重地点了点头。"
  },
  [111610166] = {
    id = 111610166,
    name = "......你说得不错，我会和你做一样的选择。"
  },
  [111610167] = {
    id = 111610167,
    name = "沙沙——"
  },
  [111610168] = {
    id = 111610168,
    name = "那边有异动！"
  },
  [111610169] = {
    id = 111610169,
    name = "我去看看，你们小心。"
  },
  [111610170] = {
    id = 111610170,
    name = "......不用看了，这个声音是魔物！我跟你一起去。"
  },
  [111610171] = {
    id = 111610171,
    name = "魔物又要来了吗？"
  },
  [111610172] = {
    id = 111610172,
    name = "刚回来的村民还非常疲惫，黑羽的眼光扫过他们，抿了抿嘴。"
  },
  [111610173] = {
    id = 111610173,
    name = "要尽快杀掉这些魔物，不能让它们靠近村庄。"
  },
  [111610174] = {
    id = 111610174,
    name = "她奔向声源所在处，果然几只魔物在附近蠢蠢欲动，你与她对视一眼，同时出手。这一次她没有指挥计划，你们有默契地一左一右将眼前的魔物击杀。"
  },
  [111610175] = {
    id = 111610175,
    name = "真的很让人意外......"
  },
  [111610176] = {id = 111610176, name = "什么？"},
  [111610177] = {
    id = 111610177,
    name = "不管是作战能力，还是与人配合的节奏，你是第一个在战斗里和我这么有默契的人。"
  },
  [111610178] = {
    id = 111610178,
    name = "是吗，我只是习惯关注和照顾同伴。"
  },
  [111610179] = {
    id = 111610179,
    name = "不，不一样。和你一起战斗，就像、就像另一把剑，也不对，虽然这样说很令人羞耻，但就像我的另一半意识。"
  },
  [111610180] = {
    id = 111610180,
    name = "甚至不需要一个眼神，你就知道我想做什么，然后代替我的意识去完成，不由自主地让人信任......你是和每个同伴都配合得这样默契吗？"
  },
  [111610181] = {
    id = 111610181,
    name = "呵呵，那个......"
  },
  [111610182] = {
    id = 111610182,
    name = "圣剑使大人！那边，那边！！"
  },
  [111610183] = {
    id = 111610183,
    name = "远方乌云密布，数不清的魔物轰隆隆如雷声般接近，村民们惊恐地扔下武器坐倒在地。"
  },
  [111610184] = {
    id = 111610184,
    name = "完了，这次彻底完了......"
  },
  [111610185] = {
    id = 111610185,
    name = "别慌，先让孩子们藏起来，这种程度的魔物......只能将它们引开......"
  },
  [111610186] = {
    id = 111610186,
    name = "黑羽毫不犹豫地走了出去，你也准备上，被村民慌忙拉住。"
  },
  [111610187] = {
    id = 111610187,
    name = "探险者大人！圣剑使大人，请你们一定要安全回来！"
  },
  [111610188] = {
    id = 111610188,
    name = "你几步追上黑羽，与她并肩奔跑。"
  },
  [111610189] = {
    id = 111610189,
    name = "你不去找你的同伴了吗？"
  },
  [111610190] = {
    id = 111610190,
    name = "好歹一起战斗过，我可没有半路扔下同伴的习惯。你呢，想过一个人去的后果吗？"
  },
  [111610191] = {
    id = 111610191,
    name = "既然来到深渊，与魔物战斗理所应当。要是还能护住弱小——"
  },
  [111610192] = {
    id = 111610192,
    name = "魔物近在眼前，她举起长剑高高跃起，赫然斩下！"
  },
  [111610193] = {
    id = 111610193,
    name = "那我便不会后悔！"
  },
  [111610194] = {id = 111610194, name = "吼！！"},
  [111610195] = {
    id = 111610195,
    name = "凄厉的惨叫吸引了其他魔物的注意力，齐齐凝固了一瞬，狂怒地扑向你们！"
  },
  [111610196] = {id = 111610196, name = "这边！"},
  [111610197] = {
    id = 111610197,
    name = "黑羽默契地与你靠背而战，洪荒般的怒吼震耳欲聋，魔物们如猛兽奔袭将你们团团围住，朝你们袭来！"
  },
  [111610198] = {id = 111610198, name = "来吧！"},
  [111610199] = {
    id = 111610199,
    name = "嗤！！黑羽挥出长剑，你配合进攻，魔法释放到最大，魔物们纷纷退却，又重新组织攻势攻了上来！"
  },
  [111610200] = {
    id = 111610200,
    name = "......鏖战许久，你们体力不支，魔物趁黑羽喘息间隙猛攻，你挥动武器挡下，却仍然不小心遭到重击，狠狠地摔在地上。"
  },
  [111610201] = {
    id = 111610201,
    name = "你没事吧？！"
  },
  [111610202] = {
    id = 111610202,
    name = "太多了，我们得想个办法......"
  },
  [111610203] = {
    id = 111610203,
    name = "我去引开它们！"
  },
  [111610204] = {id = 111610204, name = "不行！"},
  [111610205] = {
    id = 111610205,
    name = "你起身吐了口滚烫的血气，重新执起武器，正打算倾尽全力救人，一个声音如利箭般穿透而来。"
  },
  [111610206] = {
    id = 111610206,
    name = "魔物，看箭！！"
  },
  [111610207] = {
    id = 111610207,
    name = "尖锐响亮的箭鸣伴随着尼莉莎的声音破风而来，击倒了靠近黑羽的一只魔物。"
  },
  [111610208] = {
    id = 111610208,
    name = "队长，我们来帮你！"
  },
  [111610209] = {
    id = 111610209,
    name = "尼莉莎身后，蒂娜、菲尼斯与安妮斯疾速奔跑而来，很快来到了你身边，默契十足地加入了战斗。"
  },
  [111610210] = {
    id = 111610210,
    name = "好，一起上！"
  },
  [111610211] = {
    id = 111610211,
    name = "好啊，正好活动活动筋骨。"
  },
  [111610212] = {
    id = 111610212,
    name = "速战速决吧。"
  },
  [111610213] = {
    id = 111610213,
    name = "支援的事，请交给我。"
  },
  [111610214] = {
    id = 111610214,
    name = "你们同时加入了战圈，瞬间缓解了黑羽的压力。"
  },
  [111610215] = {
    id = 111610215,
    name = "这位——"
  },
  [111610216] = {
    id = 111610216,
    name = "闭嘴，战斗！"
  },
  [111610217] = {
    id = 111610217,
    name = "他们是......"
  },
  [111610218] = {
    id = 111610218,
    name = "是我的同伴。"
  },
  [111610219] = {
    id = 111610219,
    name = "数十只魔物蜂拥而至，周遭气流流转，在数不清的剑光与魔法中，黑羽成为了那个最无畏的先锋，直到最后一只魔物彻底死去。"
  },
  [111610220] = {
    id = 111610220,
    name = "呼，总算结束了。"
  },
  [111610221] = {
    id = 111610221,
    name = "老师，你没事吧？"
  },
  [111610222] = {
    id = 111610222,
    name = "我没事，你先给黑羽疗伤。"
  },
  [111610223] = {
    id = 111610223,
    name = "黑羽仍站在魔物尸体中，大口大口地喘气，身上大大小小被魔物抓裂的伤口还在渗血。"
  },
  [111610224] = {
    id = 111610224,
    name = "黑羽......小姐？请让我为你疗伤。"
  },
  [111610225] = {
    id = 111610225,
    name = "谢谢......麻烦你了。"
  },
  [111610226] = {
    id = 111610226,
    name = "哇，队长，没想到你就走开这么一小会儿，竟然也能出事故。"
  },
  [111610227] = {
    id = 111610227,
    name = "我们是不是来得不是时候，有没有耽误队长——"
  },
  [111610228] = {
    id = 111610228,
    name = "没有，你们来得正是时候，我差点应付不过来。"
  },
  [111610229] = {
    id = 111610229,
    name = "我们看到你的信，安妮斯就想过来帮你，还好赶上了。"
  },
  [111610230] = {
    id = 111610230,
    name = "你们正说着话，看见不远处的村民正拿着铁锹锄头过来帮忙，见到你们安然无恙，不禁欢欣雀跃。"
  },
  [111610231] = {
    id = 111610231,
    name = "他们在修什么？"
  },
  [111610232] = {
    id = 111610232,
    name = "防御工事。这段时间魔物频繁袭击，这已经是不知道第几次补修了。"
  },
  [111610233] = {
    id = 111610233,
    name = "看起来有点意思，我们也去帮忙吧！"
  },
  [111610234] = {
    id = 111610234,
    name = "安妮斯也结束了对黑羽的治疗。"
  },
  [111610235] = {
    id = 111610235,
    name = "我好多了。谢谢你，安妮斯小姐。"
  },
  [111610236] = {
    id = 111610236,
    name = "不用客气，你也救了老师，大家互相帮助是应该的。老师，该给你治疗了。"
  },
  [111610237] = {
    id = 111610237,
    name = "啊，我这点小伤就......"
  },
  [111610238] = {
    id = 111610238,
    name = "不行哦，老师，伤口如果感染了浊炁可轻可重，要彻底治疗才行。"
  },
  [111610239] = {
    id = 111610239,
    name = "在安妮斯的治疗下，你感受到一股目光，旁边黑羽正专注地看着你，被你发现时，忽然莫名地开了口。"
  },
  [111610240] = {
    id = 111610240,
    name = "......能成为你的探险队友，真是一件幸运的事。"
  },
  [111610241] = {
    id = 111610241,
    name = "不不，是我的幸运。"
  },
  [111610242] = {
    id = 111610242,
    name = "她察觉先前的失态，立刻正了正表情，重新回到了那个优雅淡然的神色，转移了话题。"
  },
  [111610243] = {
    id = 111610243,
    name = "魔物已经灭杀，继续回去帮他们修筑防御工事吧。"
  },
  [111610244] = {
    id = 111610244,
    name = "众人一起回到了村落。村民们的防御工事正在有条不紊地修葺，活泼的小孩和妇人们一边劳作，一边唱着歌。"
  },
  [111610245] = {
    id = 111610245,
    name = "“希望女神洒下恩泽，把阳光织进了圣剑使的发丝，把天空浸入圣剑使的双眸，她走过的深渊，恶魔都将臣服，凶恶皆会泯灭，连明月都低下头颅，融化在她的慈悲之心......”"
  },
  [111610246] = {
    id = 111610246,
    name = "听清歌词在唱什么后，黑羽有些不好意思侧过了头。"
  },
  [111610247] = {
    id = 111610247,
    name = "圣剑使大人和探险者大人回来啦！哇，探险者大人还带来了好看的哥哥姐姐！"
  },
  [111610248] = {
    id = 111610248,
    name = "众人看到你们安然回来，都纷纷迎了上来，也对安妮斯等人露出了疑惑的目光。"
  },
  [111610249] = {
    id = 111610249,
    name = "这几位是我的同伴，有他们帮忙，也不用怕魔物的再次袭击。"
  },
  [111610250] = {
    id = 111610250,
    name = "多亏了他们，刚才那批魔物已经击退了，大家暂时可以安心了。"
  },
  [111610251] = {
    id = 111610251,
    name = "村民们一听，欣喜地拥抱，接着朝你们跪了下来，一遍又一遍说着感谢。"
  },
  [111610252] = {
    id = 111610252,
    name = "大家不用这样......"
  },
  [111610253] = {
    id = 111610253,
    name = "你们快起来......"
  },
  [111610254] = {
    id = 111610254,
    name = "圣剑使大人，各位探险者大人，如果没有你们，今天我们的村庄都会被魔物毁掉，我们也许都葬身于此，是你们守护了我们，请接受这份谢意吧！"
  },
  [111610255] = {
    id = 111610255,
    name = "不，仅仅是杀几只魔物而已，况且你们的危机还没有解除。那些魔物一次又一次出现在附近，绝对不是偶然。"
  },
  [111610256] = {
    id = 111610256,
    name = "她思考了片刻，转过头看向你们，眼神坚定明亮。"
  },
  [111610257] = {
    id = 111610257,
    name = "我打算深入魔物的巢穴调查，能不能拜托各位，这个村庄暂时——"
  },
  [111610258] = {
    id = 111610258,
    name = "哎呀，去不得啊！那个山洞深不见底，以前的探险者去了就没回来过，圣剑使大人，您还是别去了。"
  },
  [111610259] = {
    id = 111610259,
    name = "这么说，你知道附近的魔物巢穴地点？"
  },
  [111610260] = {
    id = 111610260,
    name = "哎......知道是知道，之前圈落也派出了探险队去剿灭，可最后依然没有结果。圣剑使大人，您要是真的折里面了，那我们该——"
  },
  [111610261] = {
    id = 111610261,
    name = "说什么胡话！圣剑使大人怎么会有事？！"
  },
  [111610262] = {
    id = 111610262,
    name = "镇定的村民给了老实人一个爆栗子，朝黑羽露出了笑脸。"
  },
  [111610263] = {
    id = 111610263,
    name = "要是圣剑使大人能解决那群藏起来的魔物，那咱们村子以后的每一年都不会再有魔物来袭了吧！"
  },
  [111610264] = {
    id = 111610264,
    name = "只是圣剑使大人一个人，也许照应不过来，要是有各位探险者大人的相助，那一定攻无不克无往不胜！"
  },
  [111610265] = {
    id = 111610265,
    name = "啊？（小声）蒂娜，我们什么时候说过要帮忙？"
  },
  [111610266] = {id = 111610266, name = "......"},
  [111610267] = {
    id = 111610267,
    name = "呵呵......"
  },
  [111610268] = {
    id = 111610268,
    name = "（想利用黑羽的善良和力量来解决村庄的危机，还想以关心她的名义拉我的人下水，真是好算计啊......）"
  },
  [111610269] = {
    id = 111610269,
    name = "不用，他们已经帮得够多了，再说我只是去探查一下。"
  },
  [111610270] = {
    id = 111610270,
    name = "老师，以刚才的魔物数量，那些藏起来的恐怕只多不少，如果黑羽小姐独自前往，确实会有危险，我们能不能去帮帮她？"
  },
  [111610271] = {
    id = 111610271,
    name = "（叹息）安妮斯。"
  },
  [111610272] = {
    id = 111610272,
    name = "他们一直在这里生活，我们可以赶走魔物一次，两次，那之后呢......如果能彻查原因，也许就能解决他们多年的困扰了。"
  },
  [111610273] = {id = 111610273, name = "......"},
  [111610274] = {
    id = 111610274,
    name = "对对，这位心善的探险者小姐，如果各位大人去的话，我们愿意带路！"
  },
  [111610275] = {
    id = 111610275,
    name = "（算了，这家伙也是为了村里的人，而且安妮斯这么坚持，看来也不得不帮了。）"
  },
  [111610276] = {
    id = 111610276,
    name = "好啊，不过我建议在一切未知的情况下，先到附近打探形势，再制定剿灭魔物的计划。安妮斯，你就和蒂娜留在村落吧，我带尼莉莎和菲尼斯去就行了。"
  },
  [111610277] = {
    id = 111610277,
    name = "我同意。"
  },
  [111610278] = {
    id = 111610278,
    name = "啊？又要工作了吗？"
  },
  [111610279] = {
    id = 111610279,
    name = "那事不宜迟，我们出发吧。"
  },
  [111610280] = {
    id = 111610280,
    name = "谢谢你们。那这一路就由你指挥了，队长。"
  },
  [111610281] = {
    id = 111610281,
    name = "圣剑使大人、各位探险者大人，这前面就接近我们说的那个山洞了。不过这里雾气太浓了，啥也看不清，很多大人就是被这雾气给坑了，咱们一定要多小心啊！"
  },
  [111610282] = {
    id = 111610282,
    name = "知道了，谢谢你的提醒。"
  },
  [111610283] = {
    id = 111610283,
    name = "雾气融入浊炁，使得整个山谷的视野变得模糊，每一步都需要小心谨慎地迈出。"
  },
  [111610284] = {
    id = 111610284,
    name = "你对这一带很熟？"
  },
  [111610285] = {
    id = 111610285,
    name = "当然，要说对这片熟悉的程度，我第二没人敢认第一。"
  },
  [111610286] = {
    id = 111610286,
    name = "平时这里也这么多雾气？"
  },
  [111610287] = {
    id = 111610287,
    name = "其实这里平时没这么大雾气，每年这段时间，浊炁和雾气都格外浓，要是没有几位大人，我根本不敢靠近这里啊。"
  },
  [111610288] = {
    id = 111610288,
    name = "难怪你的兄弟向我们推荐你来带路。"
  },
  [111610289] = {
    id = 111610289,
    name = "嘿嘿。唉他啊，每天愁得睡不好觉。还好这会儿没魔物去打扰了，大家也能趁这个时候多休息休息，这样魔物来了也有劲儿不是吗。"
  },
  [111610290] = {
    id = 111610290,
    name = "前面浓雾太重，你就别再进去了，里面的情景，应该不是你能应付的。"
  },
  [111610291] = {
    id = 111610291,
    name = "圣剑使大人，我能帮忙的！这个地方我闭着眼睛都能走！再说有几位大人，再危险的局面，也有你们不是吗？"
  },
  [111610292] = {
    id = 111610292,
    name = "那你的腿打哆嗦干什么？"
  },
  [111610293] = {
    id = 111610293,
    name = "哈哈，有点冷，活动起来就好了。"
  },
  [111610294] = {
    id = 111610294,
    name = "是吗，那你很快就可以活动起来了。"
  },
  [111610295] = {id = 111610295, name = "......"},
  [111610296] = {
    id = 111610296,
    name = "雾气中传来一阵低沉的咆哮声，回荡在重重山谷里，透过雾气，你能望见远处闪烁的红光和绰绰黑影。"
  },
  [111610297] = {
    id = 111610297,
    name = "魔、魔、魔物......"
  },
  [111610298] = {
    id = 111610298,
    name = "村民捂紧了嘴巴，双腿颤抖得更厉害了。你朝几人挥了挥手，无声无息地绕道而行，直到一处开阔地，才停了下来。"
  },
  [111610299] = {
    id = 111610299,
    name = "前面应该就是魔物的聚集地了。"
  },
  [111610300] = {
    id = 111610300,
    name = "根据气息和声响判断，数量可不少。"
  },
  [111610301] = {
    id = 111610301,
    name = "咱们快撤退吧？"
  },
  [111610302] = {
    id = 111610302,
    name = "等一下，我总觉得这件事背后没那么简单。"
  },
  [111610303] = {
    id = 111610303,
    name = "杀进去也许就知道了。"
  },
  [111610304] = {
    id = 111610304,
    name = "如果不查探清楚魔物的数量与来源，又怎么制定针对性的作战计划？"
  },
  [111610305] = {
    id = 111610305,
    name = "那......各位大人，我们？？"
  },
  [111610306] = {
    id = 111610306,
    name = "嘘，噤声，它们来了！"
  },
  [111610307] = {
    id = 111610307,
    name = "唔唔......"
  },
  [111610308] = {
    id = 111610308,
    name = "村民发出卑微又细小的声音，你比划手势让大家暂时撤退。等到接近山谷，你示意他先离开，找个安全的地方等你们的消息，而你们找了处掩体的角落，几人紧紧靠在一起。"
  },
  [111610309] = {
    id = 111610309,
    name = "感觉到魔物的行进方向，众人闭口不言，你想了想，抬起手指了个方向，黑羽慎重地点点头，持剑率先出去。"
  },
  [111610310] = {
    id = 111610310,
    name = "你紧跟而上，俯下身贴着掩体前进，利用每个细微的遮挡物，尽量隐藏自己的身形，与此同时魔物相互撞击，脚步挤压着发出咚咚咚的声音，仿佛你们轰鸣的心跳。"
  },
  [111610311] = {id = 111610311, name = "呜！"},
  [111610312] = {
    id = 111610312,
    name = "突然间，一只魔物朝着你们慢慢移动。你心一沉，立刻停下脚步，拉住了前方的黑羽，她被突然扯回，撞在你的下巴上，你疼得吸气，只能尽量减小自己的呼吸声。"
  },
  [111610313] = {id = 111610313, name = "......"},
  [111610314] = {
    id = 111610314,
    name = "魔物越来越靠近，仿佛能够嗅到你们的气息，黑羽想退后，被你稳固着身形，她猛然抬眼，抓紧你的手臂，怔愣地张了张嘴。"
  },
  [111610315] = {
    id = 111610315,
    name = "（小声）这样不是办法，我们做个标记，分开调查吧。"
  },
  [111610316] = {
    id = 111610316,
    name = "（小声）不，我们先回去，等雾气散——"
  },
  [111610317] = {
    id = 111610317,
    name = "然而这时，一声巨响突然响起！更远处的魔物发出咆哮声，吸引了其他魔物的注意力，纷纷朝一个方向涌了过去。"
  },
  [111610318] = {id = 111610318, name = "！！！"},
  [111610319] = {
    id = 111610319,
    name = "（怎么回事？）"
  },
  [111610320] = {
    id = 111610320,
    name = "黑羽松开你的手臂，握住了腰间的剑，神色肃然。"
  },
  [111610321] = {
    id = 111610321,
    name = "（小声）那边发生什么了？！"
  },
  [111610322] = {
    id = 111610322,
    name = "魔物地奔跑声掩盖了他的话音，这时一声惊惶的尖叫声响起。"
  },
  [111610323] = {
    id = 111610323,
    name = "啊啊啊啊！！！"
  },
  [111610324] = {
    id = 111610324,
    name = "在谷口那边！"
  },
  [111610325] = {
    id = 111610325,
    name = "嗷呜——"
  },
  [111610326] = {
    id = 111610326,
    name = "魔物朝谷口涌去，你们没有再掩藏身形，屏气跟在那群魔物后，那呼救声越来越近。"
  },
  [111610327] = {
    id = 111610327,
    name = "圣剑使大人，探险者大人，救命，救命啊！！！"
  },
  [111610328] = {
    id = 111610328,
    name = "我去接应他，你们帮我掩护。"
  },
  [111610329] = {
    id = 111610329,
    name = "交给我们。"
  },
  [111610330] = {
    id = 111610330,
    name = "好好，我的箭可是有眼睛的。"
  },
  [111610331] = {
    id = 111610331,
    name = "好......请小心。"
  },
  [111610332] = {
    id = 111610332,
    name = "你出发后，菲尼斯拿出了一颗常用的信号弹，当着一群魔物的面，轰地一声砸向了谷壁上，强烈的光吸引了魔物重新回头，朝几人扑了过去。"
  },
  [111610333] = {
    id = 111610333,
    name = "来吧，躲猫猫开始了！"
  },
  [111610334] = {
    id = 111610334,
    name = "另一头，村民飞奔而来，他感到魔物的气息越来越近，忍不住回头一看，魔物张开巨大的血盆大口，准备将他一口吞噬，被你一招击中要害倒地。"
  },
  [111610335] = {
    id = 111610335,
    name = "怎么回事，不是让你先走吗？"
  },
  [111610336] = {
    id = 111610336,
    name = "你拉着村民到掩体之后，他恐惧地咽了咽口水，缓过一口气。"
  },
  [111610337] = {
    id = 111610337,
    name = "圣剑使大人，我看到魔物来了，就藏起来了，本来藏得好好的，谁知道那魔物越来越近，最后贴在我脸上了，我......我没忍住就叫出来了......"
  },
  [111610338] = {id = 111610338, name = "......"},
  [111610339] = {
    id = 111610339,
    name = "我先送你出去，再去接应他们，你在谷口等我们出来。"
  },
  [111610340] = {
    id = 111610340,
    name = "是是是，大人。"
  },
  [111610341] = {
    id = 111610341,
    name = "可惜你们离开的路并不顺利，比起探险者而言，村民行动缓慢，好几次险些遭了魔物的毒手，等回过神你们已经不知到了哪里。"
  },
  [111610342] = {
    id = 111610342,
    name = "大人，那边有个山洞，我们过去躲一躲吧！"
  },
  [111610343] = {id = 111610343, name = "山洞？"},
  [111610344] = {
    id = 111610344,
    name = "是啊，以前我常在这边来采药，赚点小钱，那个山洞是我临时落脚的地方，我知道在哪里。"
  },
  [111610345] = {
    id = 111610345,
    name = "（这里魔物没再来了，也不知道他们几个现在情况如何，只能先找个安全的地方，一路作记号，等他们找过来。）"
  },
  [111610346] = {
    id = 111610346,
    name = "好，那你带路吧。"
  },
  [111610347] = {
    id = 111610347,
    name = "村民带着你穿梭在山谷迷雾间，绕了半天终于见到了山洞，他激动地握了握拳。"
  },
  [111610348] = {
    id = 111610348,
    name = "大人，就是这里。"
  },
  [111610349] = {
    id = 111610349,
    name = "你们进入了山洞，村民一路奔逃，一头倒在墙边睡着了，你甚至听到了鼾声。"
  },
  [111610350] = {
    id = 111610350,
    name = "......（希望他们快点过来吧）"
  },
  [111610351] = {
    id = 111610351,
    name = "鼾声越来越响，也越来越近，你心中一凛，小心转过头看向村民。"
  },
  [111610352] = {
    id = 111610352,
    name = "呜呜......"
  },
  [111610353] = {
    id = 111610353,
    name = "村民早就醒了，他惶恐地捂着嘴，使劲缩在角落，瞪大眼看向你的身后。"
  },
  [111610354] = {
    id = 111610354,
    name = "吼！！！"
  },
  [111610355] = {
    id = 111610355,
    name = "震耳欲聋的吼叫令你耳朵嗡鸣，千钧一发之际，你翻身躲过了魔物的攻击，与它正面交锋，一半的阴影下，你看清了它的模样，那是一只高达两人的巨型魔物。"
  },
  [111610356] = {
    id = 111610356,
    name = "......跑！！"
  },
  [111610357] = {
    id = 111610357,
    name = "魔物毫无意外地扑了上来，你拖着村民扔出了山洞，回身跃起，落在一块岩石上，借着洞顶滴落的水珠快速凝聚魔法能量，一串冰锥从不同角度射向魔物，冰锥在接触魔物坚硬的表皮时瞬间爆裂，魔物愤怒地咆哮，一爪挥来。"
  },
  [111610358] = {
    id = 111610358,
    name = "砰！！岩石碎裂，你开始与庞大的魔物展开了巧妙地周旋，村民跌坐在地上，后退了好几步，踉跄着逃跑了。"
  },
  [111610359] = {
    id = 111610359,
    name = "我，我去找他们来救你！"
  },
  [111610360] = {
    id = 111610360,
    name = "一个人对付这样的巨型魔物几乎是不可能的，你判断眼下的局势，再不离开山洞，到最后体力耗尽什么也做不了，可是魔物牢牢挡住了出口，你只能陷入无尽的缠斗。"
  },
  [111610361] = {id = 111610361, name = "......"},
  [111610362] = {
    id = 111610362,
    name = "你的体力与魔力逐渐被榨干，每一次呼吸都变得异常沉重，汗水浸湿了衣襟。魔物的每一次攻击，虽然都勉强避开了，但你的动作已经开始迟缓，甚至在一次躲闪中，一块飞溅的石块划伤了你的脸颊，鲜血顺着下巴滴落，染红了衣领。"
  },
  [111610363] = {
    id = 111610363,
    name = "（真是难缠啊，只能用这招了......）"
  },
  [111610364] = {
    id = 111610364,
    name = "你趁魔物扑来时，奋力与它对冲而上，一跃踩到它的头顶，找到了洞口的缝隙，翻身滚了出去！"
  },
  [111610365] = {
    id = 111610365,
    name = "走出洞口不远处，更多的魔物徘徊着，它们沿着气息追来，仿佛已经在这里等很久了，他们等的是高高趴在大树上的村民，等着食物落下。"
  },
  [111610366] = {
    id = 111610366,
    name = "......唉。"
  },
  [111610367] = {
    id = 111610367,
    name = "呜呜呜......探险者大人，你快走吧，别管我了......"
  },
  [111610368] = {
    id = 111610368,
    name = "（以我的能力，现在或许还有机会逃出去，一旦山洞里的魔物追出来，恐怕都难逃厄运。）"
  },
  [111610369] = {
    id = 111610369,
    name = "就在你犹豫的时候，听到了另一个声音，由远及近。"
  },
  [111610370] = {
    id = 111610370,
    name = "那是一次又一次不规律的剑刃撞击声，伴着女孩的娇喝，以及魔物的哀嚎，越来越近......"
  },
  [111610371] = {
    id = 111610371,
    name = "是黑羽杀了过来，她从魔物的队尾突围，沿路都是鲜血与魔物尸体，双目露出傲然冷淡的寒光，一尺剑锋下，十数只魔物纷纷倒下，她步履平稳地前进着，一点也不在乎魔物的反向围攻，甚至还大声呼唤。"
  },
  [111610372] = {
    id = 111610372,
    name = "队长！你在吗？！"
  },
  [111610373] = {id = 111610373, name = "......"},
  [111610374] = {
    id = 111610374,
    name = "魔物听到响动，轰隆隆地冲了过去，村民见到救星大声哭喊。"
  },
  [111610375] = {
    id = 111610375,
    name = "圣剑使大人，我们在这里！！"
  },
  [111610376] = {
    id = 111610376,
    name = "黑羽在战斗，她一剑又一剑地挥下去，剑势越来越锋利，明明只是一把剑，在她手中宛若游龙，时而如雷霆万钧，斩灭一切来犯之物，时而又如丝如盾，密密麻麻守住魔物的每一处攻势，她走一步挥一剑，气势如山，不输眼前成群的魔物半点。"
  },
  [111610377] = {id = 111610377, name = "小心！"},
  [111610378] = {
    id = 111610378,
    name = "一只魔物正从身后偷袭黑羽，被你一招击倒，你与她再次背靠背作战。"
  },
  [111610379] = {
    id = 111610379,
    name = "队长，你受伤了？！"
  },
  [111610380] = {
    id = 111610380,
    name = "都是小伤。我们快杀出去，离开这里再说。"
  },
  [111610381] = {id = 111610381, name = "好！"},
  [111610382] = {
    id = 111610382,
    name = "黑羽胸膛微微起伏，额间渗出不少汗。而这时魔物接连不断地进攻，你们再次合作，默契地杀了一大片。"
  },
  [111610383] = {
    id = 111610383,
    name = "果然是这样，队长。这样酣畅淋漓战斗的感觉，我以前从来没有感受到过，有你和我一起作战，我有信心将这些魔物全部清理掉。"
  },
  [111610384] = {
    id = 111610384,
    name = "黑羽的双目闪烁，是兴奋，也是找到知己的满足。"
  },
  [111610385] = {
    id = 111610385,
    name = "不要恋战，山洞里有个大家伙——"
  },
  [111610386] = {
    id = 111610386,
    name = "吼！！！"
  },
  [111610387] = {
    id = 111610387,
    name = "一只巨型魔物从山洞走了出来，发红的“眼睛”正死死“盯”着你们，它在愤怒地嘶吼，喉管中漫天的血色，仿佛能听见被它杀过的人类的哀嚎......"
  },
  [111610388] = {id = 111610388, name = "快走！"},
  [111610389] = {
    id = 111610389,
    name = "大人，大人！别，别丢下我！"
  },
  [111610390] = {
    id = 111610390,
    name = "队长，这只魔物不能留在这里。"
  },
  [111610391] = {
    id = 111610391,
    name = "你是说......"
  },
  [111610392] = {
    id = 111610392,
    name = "嗯，它要是离开山谷，村落必然有灭顶之灾。必须把它留在这里，就算杀不死它，也要让它重伤，无力去作恶。"
  },
  [111610393] = {
    id = 111610393,
    name = "队长，你先带着他走吧，我在这里拦住他，等你的同伴。"
  },
  [111610394] = {
    id = 111610394,
    name = "那你......"
  },
  [111610395] = {
    id = 111610395,
    name = "你不用担心，我没有到为了一群陌生人而不珍惜生命的地步，或许你会认为我不自量力，但修行就是这样，明知不可为而为之。我不去试试，永远不知道自己的极限在哪里，只会到此止步了。"
  },
  [111610396] = {
    id = 111610396,
    name = "那就一起战斗吧，你既然叫我一声队长，那我就没有拒绝队友的道理。"
  },
  [111610397] = {
    id = 111610397,
    name = "黑羽眉目微垂，此刻抬眼，熠熠生辉。"
  },
  [111610398] = {
    id = 111610398,
    name = "好！只要再等半刻钟，他们都会到的。"
  },
  [111610399] = {
    id = 111610399,
    name = "吼！！！"
  },
  [111610400] = {
    id = 111610400,
    name = "这一瞬间，你们双人合攻，倾力一击，空气里剑啸长鸣，久久不散。"
  },
  [111610401] = {
    id = 111610401,
    name = "不多时，一个身影从侧面闪现而来，剑芒闪烁，直刺魔物的要害，魔物惊吼一声，奋力挣扎，又被另一支箭击中了要害。"
  },
  [111610402] = {
    id = 111610402,
    name = "抱歉，来晚了。"
  },
  [111610403] = {
    id = 111610403,
    name = "难得看到队长这么狼狈的样子啊，哈哈。"
  },
  [111610404] = {
    id = 111610404,
    name = "别说了，赶紧杀了这只魔物。"
  },
  [111610405] = {
    id = 111610405,
    name = "遵命，队长！"
  },
  [111610406] = {
    id = 111610406,
    name = "在你的指挥辅助下，剑与箭同时出击，是比黑羽更默契的配合，黑羽只震惊了一瞬，很快和大家一起行动，天衣无缝地弥补了魔物撤退的方位，直到魔物气息灭绝，轰然倒地。"
  },
  [111610407] = {
    id = 111610407,
    name = "呼，累死啦，每次出来都有意外发生。"
  },
  [111610408] = {
    id = 111610408,
    name = "这么大一只魔物，一直藏在前面的山洞里？"
  },
  [111610409] = {
    id = 111610409,
    name = "大型魔物占领了这个区域，原本在这里活动的魔物只能到更远的地方为大型魔物觅食。"
  },
  [111610410] = {
    id = 111610410,
    name = "难怪每年村落都会被袭击......好在这个隐患已经解决了。"
  },
  [111610411] = {
    id = 111610411,
    name = "好耶，队长我们回去吧！"
  },
  [111610412] = {
    id = 111610412,
    name = "好，回去吧。"
  },
  [111610413] = {
    id = 111610413,
    name = "嗯，我总觉得好像忘了什么......"
  },
  [111610414] = {
    id = 111610414,
    name = "是那个家伙吧？"
  },
  [111610415] = {
    id = 111610415,
    name = "菲尼斯指着树上，村民趴在枝干上，不知什么时候被吓晕了过去......"
  },
  [111610416] = {
    id = 111610416,
    name = "当你们踏入村落大门时，村民们已经聚集在了门口，安妮斯与蒂娜也在其中，他们一拥而上，昏迷的村民被大呼小叫的声音吵醒了。"
  },
  [111610417] = {
    id = 111610417,
    name = "菲尼斯感觉到动静，将他放了下去。"
  },
  [111610418] = {
    id = 111610418,
    name = "啧，这么扛着真是不轻。"
  },
  [111610419] = {
    id = 111610419,
    name = "以前背某小姐的时候，你可没这么说过。"
  },
  [111610420] = {
    id = 111610420,
    name = "大人快跑！快跑！"
  },
  [111610421] = {
    id = 111610421,
    name = "跑什么呢，醒醒。"
  },
  [111610422] = {
    id = 111610422,
    name = "......我们回来了？"
  },
  [111610423] = {
    id = 111610423,
    name = "嗯，回来了，以后你们不会再困扰了。"
  },
  [111610424] = {
    id = 111610424,
    name = "真的？！！"
  },
  [111610425] = {
    id = 111610425,
    name = "黑羽点点头，几句话说清了前因后果。"
  },
  [111610426] = {
    id = 111610426,
    name = "一些村民傻在了原地，过了几秒，他们反应了过来，原地蹦跶了一下，围在你们身边，不停地说着道谢的话。"
  },
  [111610427] = {
    id = 111610427,
    name = "圣剑使大人、探险者大人！你们是拯救我们的英雄！感谢你们拯救了我们的家！"
  },
  [111610428] = {
    id = 111610428,
    name = "不用这样......你们......"
  },
  [111610429] = {
    id = 111610429,
    name = "大家别激动，他们很累了，让他们先去疗伤和休息。"
  },
  [111610430] = {
    id = 111610430,
    name = "对对对，各位大人，请尽快好起来，有什么是我们需要做的，我，我这条命都是你们的！"
  },
  [111610431] = {
    id = 111610431,
    name = "老师，你又受伤了......请你一定要保重自己......"
  },
  [111610432] = {id = 111610432, name = "嗯......"},
  [111610433] = {
    id = 111610433,
    name = "你们到了休息室，安妮斯为你疗伤结束后，先前的村民走了过来。"
  },
  [111610434] = {
    id = 111610434,
    name = "几位大人，为表达我们的感激和敬佩，请允许我们为你们献上精心准备的晚餐与晚会！"
  },
  [111610435] = {
    id = 111610435,
    name = "晚餐，晚会？好啊好啊！走去看看！"
  },
  [111610436] = {
    id = 111610436,
    name = "尼莉莎一溜烟离开了，没过多久，又拖着手将蒂娜和安妮斯拉了出去。"
  },
  [111610437] = {
    id = 111610437,
    name = "放手，我自己走。"
  },
  [111610438] = {
    id = 111610438,
    name = "......好，我也去看看吧。"
  },
  [111610439] = {
    id = 111610439,
    name = "快来啊队长，我竟然看到了面包！不是魔物做的食物，真是太棒了！"
  },
  [111610440] = {
    id = 111610440,
    name = "咦，我忽然有些兴趣了。"
  },
  [111610441] = {
    id = 111610441,
    name = "菲尼斯离开时，瞧了瞧黑羽，忽然回头对你坏笑了一声。"
  },
  [111610442] = {id = 111610442, name = "无聊。"},
  [111610443] = {id = 111610443, name = "......"},
  [111610444] = {
    id = 111610444,
    name = "黑羽迟疑地站在原地，一时有些无所适从，只是面色却依然淡然，看不出太大的情绪，但不知是否是外面的声音太过吵闹，你能感受到她杂乱的心情。"
  },
  [111610445] = {
    id = 111610445,
    name = "圣剑使大人......是不喜欢热闹吗？"
  },
  [111610446] = {
    id = 111610446,
    name = "小孩在门口偷偷露了个脑袋，怯生生地看向黑羽。"
  },
  [111610447] = {
    id = 111610447,
    name = "没有，我只是没想到......"
  },
  [111610448] = {
    id = 111610448,
    name = "那就一起去看看吧。你们准备了什么吃的？累了一天，真的有些饿了。"
  },
  [111610449] = {
    id = 111610449,
    name = "你适当地转移了话题，小孩子兴奋地拉着你们走向了村庄的中心空地，此时那里已经摆满了食物、鲜花和酒。"
  },
  [111610450] = {
    id = 111610450,
    name = "大人们，请品尝一下我们自酿的美酒吧！"
  },
  [111610451] = {
    id = 111610451,
    name = "还有酒？！"
  },
  [111610452] = {
    id = 111610452,
    name = "小孩子不能喝酒。"
  },
  [111610453] = {
    id = 111610453,
    name = "你说谁是小孩？！"
  },
  [111610454] = {
    id = 111610454,
    name = "是......野果酿的酒？"
  },
  [111610455] = {
    id = 111610455,
    name = "这酒意外的不错。"
  },
  [111610456] = {
    id = 111610456,
    name = "黑羽小姐，你不喝吗？"
  },
  [111610457] = {
    id = 111610457,
    name = "那，那我就不客气了。"
  },
  [111610458] = {
    id = 111610458,
    name = "为了村庄的安宁，为了剿清山谷的胜利，为了你的明知不可为而为之，干杯！！！"
  },
  [111610459] = {
    id = 111610459,
    name = "呵呵，干杯。"
  },
  [111610460] = {
    id = 111610460,
    name = "干杯！！！"
  },
  [111610461] = {
    id = 111610461,
    name = "村民们满怀喜悦之情迎接得来不易的安稳，至少在很长的一段时间里，他们不会再提心吊胆，担惊受怕，繁花的芳香混合着美酒的浓烈，变成了快乐的味道，感染了整个村落。"
  },
  [111610462] = {
    id = 111610462,
    name = "这一刻，村民和小孩们开始唱起了歌：“希望女神洒下恩泽，把阳光织进了圣剑使的发丝，把天空浸入圣剑使的双眸，她走过的深渊，恶魔都将臣服，凶恶皆会泯灭，连明月都低下头颅，融化在她的慈悲之心......”"
  },
  [111610463] = {
    id = 111610463,
    name = "唱到欢快处，几名妇人拉上伴侣跳起了舞，一起为你们，也为他们庆贺。这样欢快的氛围，就连黑羽都露出了轻松的笑，她一直紧绷的战斗神经终于放松了下来。"
  },
  [111610464] = {
    id = 111610464,
    name = "哈哈哈哈，圣剑使大人来一起跳啊！"
  },
  [111610465] = {
    id = 111610465,
    name = "......不用了。"
  },
  [111610466] = {
    id = 111610466,
    name = "哪有你这样叫大人跳舞的，美丽的小姐都是要帅气的绅士邀请才会同意的，你滚一边玩去吧！"
  },
  [111610467] = {
    id = 111610467,
    name = "那探险者大人就可以啊——呜哇！"
  },
  [111610468] = {
    id = 111610468,
    name = "小孩被一巴掌呼噜到了另一边，安妮斯、蒂娜、尼莉莎与黑羽同时侧头看了你一眼，很快又同时转了过去，目不斜视。"
  },
  [111610469] = {
    id = 111610469,
    name = "队长还是这么受欢迎啊。"
  },
  [111610470] = {
    id = 111610470,
    name = "......少胡说八道。"
  },
  [111610471] = {
    id = 111610471,
    name = "我这样一个帅气优雅的绅士都被无视掉了，真是令人伤心难过。"
  },
  [111610472] = {
    id = 111610472,
    name = "我突然很赞同列蒂西雅的一句话。"
  },
  [111610473] = {
    id = 111610473,
    name = "菲尼斯紧紧闭上了嘴。"
  },
  [111610474] = {
    id = 111610474,
    name = "几人说着闲话，在座位上愉快地用餐，这时刚才的村民笑着跑了过来。"
  },
  [111610475] = {
    id = 111610475,
    name = "几位大人对今天的晚餐还满意吗？"
  },
  [111610476] = {
    id = 111610476,
    name = "你们的心意我们收到了，其实没有必要这么破费的。"
  },
  [111610477] = {
    id = 111610477,
    name = "这些其实是我们本来打算为收获祭大赛那些勇者们准备的，不算什么。"
  },
  [111610478] = {
    id = 111610478,
    name = "收获祭？！"
  },
  [111610479] = {
    id = 111610479,
    name = "咦，大人不知道吗？霍德圈落过几日就要召开一年一度的收获祭大赛了，这是圈落专门为庆祝这段时间粮食收获而定制的比赛，因为提供的奖励非常丰富，很多探险者都会慕名参加！"
  },
  [111610480] = {
    id = 111610480,
    name = "......我从未听过这个圈落的名字。"
  },
  [111610481] = {
    id = 111610481,
    name = "啊，其实它叫霍达科帕......什么......阿格德圈落，名字太长了，我们都叫它霍德圈落了。"
  },
  [111610482] = {
    id = 111610482,
    name = "竟然还有比赛？比赛的内容是什么？奖品是什么？怎么参与比赛？！"
  },
  [111610483] = {
    id = 111610483,
    name = "你激动什么？"
  },
  [111610484] = {
    id = 111610484,
    name = "这个就不知道了，不过每年都不一样，我记得去年的比赛内容是比哪支队伍谁先摘到山顶最高一颗树的果子，那比赛过程，别提有多精彩了！"
  },
  [111610485] = {
    id = 111610485,
    name = "村民洋洋洒洒说起了比赛的规则和过程，跌宕起伏，引人入胜，尼莉莎兴奋地跳到你眼前，期待地看着你。"
  },
  [111610486] = {
    id = 111610486,
    name = "这可好玩啊！队长，咱们也去吧！"
  },
  [111610487] = {
    id = 111610487,
    name = "冷静点，咱们还有更重要的事。"
  },
  [111610488] = {
    id = 111610488,
    name = "哎呀，就这么几天不会耽搁什么时间的！"
  },
  [111610489] = {
    id = 111610489,
    name = "可是，比赛规定小队是6个人才能报名。"
  },
  [111610490] = {
    id = 111610490,
    name = "尼莉莎愣了愣，忽然笑眯眯地看向了黑羽。"
  },
  [111610491] = {
    id = 111610491,
    name = "嘿嘿，黑羽......小姐，要不要跟我们一起参与啊？"
  },
  [111610492] = {
    id = 111610492,
    name = "我，我吗？"
  },
  [111610493] = {
    id = 111610493,
    name = "别闹，队长还没同意。"
  },
  [111610494] = {
    id = 111610494,
    name = "其实，大家都想去试试的话，也不是不可以，黑羽的意思呢？"
  },
  [111610495] = {
    id = 111610495,
    name = "圣剑使大人要是去，就凭您和几位探险者大人的本事，一定能摘得桂冠，夺得魁首啊！"
  },
  [111610496] = {
    id = 111610496,
    name = "听见没有，魁首，冠军，第一名！是我们的！不管什么奖励，去试试吧，队长！"
  },
  [111610497] = {
    id = 111610497,
    name = "呵呵，光队长答应也不行啊，我们还差一个人呢。"
  },
  [111610498] = {
    id = 111610498,
    name = "众人齐齐看向了黑羽，尼莉莎双手合十，做了个祈求的动作，黑羽有点无措。"
  },
  [111610499] = {
    id = 111610499,
    name = "听起来是很利于修行和历练的活动。我真的可以和你们一起去参加收获祭吗？"
  },
  [111610500] = {
    id = 111610500,
    name = "当然可以。"
  },
  [111610501] = {
    id = 111610501,
    name = "好耶，太好了！"
  },
  [111610502] = {
    id = 111610502,
    name = "......嗯。"
  },
  [111610503] = {
    id = 111610503,
    name = "尼莉莎，你把酒洒我身上了！"
  },
  [111610504] = {
    id = 111610504,
    name = "安妮斯救命！"
  },
  [111610505] = {
    id = 111610505,
    name = "尼莉莎一副俏皮的模样，灵巧地跳到安妮斯身后，三人嬉闹的笑声汇成了夜的乐章。在酒香与欢歌交织的温馨夜晚，人们举杯共饮，悠扬的旋律载着欢声笑语，萦绕在每个人的耳畔。"
  },
  [111610506] = {
    id = 111610506,
    name = "队长，谢谢你。"
  },
  [111610507] = {
    id = 111610507,
    name = "她盈盈弯起了眼角，第一次从眉眼流溢而出的笑意，眼中闪烁着细碎的光，粲然夺目。"
  },
  [111320001] = {
    id = 111320001,
    name = "你离开补给营地一会儿，前面跑来了一个人。"
  },
  [111320002] = {
    id = 111320002,
    name = "嗯？好眼熟的装扮......"
  },
  [111320003] = {
    id = 111320003,
    name = "那个人跑得跌跌撞撞，好几次摔在了地上又爬起，你眯了眯眼睛，那身公会制服上，浸湿了一大片鲜红，那人越跑越近，你看到他周围微微散发的黑色丝雾。"
  },
  [111320004] = {
    id = 111320004,
    name = "莹......莹草......救，救救我......"
  },
  [111320005] = {
    id = 111320005,
    name = "他看到了你，朝你伸出手，噗通跌倒在地，竭尽力量抬头看着你。"
  },
  [111320006] = {
    id = 111320006,
    name = "这是发生什么事了？"
  },
  [111320007] = {
    id = 111320007,
    name = "你拿出莹草药剂喂进了他的嘴里，暂时遏制了他体内侵蚀的浊炁，又拿出伤药为他治疗，发现他身上的伤口一道道的，还渗着血。"
  },
  [111320008] = {
    id = 111320008,
    name = "多谢......咳咳咳......我奉命调查......帕尔据点，那里出现了爆炸......咳咳咳......"
  },
  [111320009] = {
    id = 111320009,
    name = "爆炸？！"
  },
  [111320010] = {
    id = 111320010,
    name = "这个公会的人不停地咳嗽，吐出了一大口黑血，挣扎着站了起来，你觉得这不是办法，打算把他送到附近的营地再通知公会的人来接应。"
  },
  [111320011] = {
    id = 111320011,
    name = "我......堕落者......咳咳咳......"
  },
  [111320012] = {
    id = 111320012,
    name = "我已经给你服用了莹草，你不会变成堕落者的，先去营地休息吧，就在那边。"
  },
  [111320013] = {
    id = 111320013,
    name = "你将公会成员安置在补给营地，给他简单包扎后，决定到他说的帕尔据点看看。"
  },
  [111320014] = {
    id = 111320014,
    name = "据点爆炸这么大的事......我还是去看看，你休息好了就自己去找人吧。"
  },
  [111320015] = {
    id = 111320015,
    name = "不，别、别......去......危险......"
  },
  [111320016] = {
    id = 111320016,
    name = "呵呵，不用劝我。虽然我很讨厌麻烦，但遇到这种事，可不能当没听到。"
  },
  [111320017] = {
    id = 111320017,
    name = "公会成员拦你不成，躺在担架上目送你远去，心中着急却无可奈何。"
  },
  [111320018] = {
    id = 111320018,
    name = "你沿着公会成员来时的方向，走向帕尔据点的方向，踏入了一片枯萎的森林。"
  },
  [111320019] = {
    id = 111320019,
    name = "这些植物......"
  },
  [111320020] = {
    id = 111320020,
    name = "眼前的树干草木和来时路途的迥然不同，它们几乎都枯萎了。枝干像被抽尽了水分，树皮皴皱，满地铺满了厚厚的落叶，黑的、灰的，还有褪色的红，整个森林仿佛被吸干了生气。"
  },
  [111320021] = {id = 111320021, name = "浊炁。"},
  [111320022] = {
    id = 111320022,
    name = "你皱了皱眉，发现这里浊炁比普通的浊炁更浓郁，更让人产生颓丧、哀怨的情绪，立刻定了定心神，继续前进。"
  },
  [111320023] = {
    id = 111320023,
    name = "请不要再前进了。"
  },
  [111320024] = {
    id = 111320024,
    name = "卷曲飘散的落叶中，一个拿剑的少女缓缓走了过来，她走得不急不缓，每一步踏着相同的距离，仿佛被精确丈量过，飒爽的英姿，优雅的举止，让你感觉自己看到了一名贵族骑士。"
  },
  [111320025] = {
    id = 111320025,
    name = "在下是预备役骑士白鸢，这位探险者，前方非常危险，请退后，改变你的目的地。"
  },
  [111320026] = {
    id = 111320026,
    name = "......那么请问，前方出了什么事吗？"
  },
  [111320027] = {
    id = 111320027,
    name = "准骑士的脚步停了下来，站在了离你五步左右的地方，正好能看清，却又让人陌生的距离，她看起来克制又正经，说的话却很温和。"
  },
  [111320028] = {
    id = 111320028,
    name = "那不是普通探险者能应付的，也与你无关。故而，无关紧要的打听毫无意义，请离开吧。"
  },
  [111320029] = {
    id = 111320029,
    name = "白鸢打量了你一眼，神色淡淡的，好像那种温和的情绪也只是覆盖在表面的假象。"
  },
  [111320030] = {
    id = 111320030,
    name = "如果你有什么必须要做的事，可以到安全的据点等待，待危机解除后再去吧。"
  },
  [111320031] = {
    id = 111320031,
    name = "可我就是打算去调查爆炸的，你也知道危险，那何必在这里拦人，进去救人要紧吧。"
  },
  [111320032] = {
    id = 111320032,
    name = "你知道爆炸？！那你是......"
  },
  [111320033] = {
    id = 111320033,
    name = "白鸢微怔，正想问什么时候，附近一声异响，她警觉地面对异响传来的方向，并将你护在身后。"
  },
  [111320034] = {
    id = 111320034,
    name = "魔物来了，你快走吧。"
  },
  [111320035] = {
    id = 111320035,
    name = "你没有离开，反而拿出了剑站在她身边。"
  },
  [111320036] = {
    id = 111320036,
    name = "预备役骑士小姐，面对危险就退缩，可不是男人所为。"
  },
  [111320037] = {
    id = 111320037,
    name = "嗷呜呜——"
  },
  [111320038] = {
    id = 111320038,
    name = "魔物发现了你们，发出了震人心肺的啸声，它形如暗影，迅速地扑了上来，利爪闪烁着狰狞的光，你提剑一档，发出刺耳的噼啪声。"
  },
  [111320039] = {id = 111320039, name = "！！"},
  [111320040] = {
    id = 111320040,
    name = "白鸢意外地看了你一眼，而后也加入了战局。她战斗的身姿如骑士之舞，精准迅捷，你们使出一连串合击，预判了魔物的行动方向，在魔物身上划出了一道伤口。"
  },
  [111320041] = {
    id = 111320041,
    name = "嗷呜呜——"
  },
  [111320042] = {
    id = 111320042,
    name = "魔物发出嗜血的咆哮，利爪如幽光般张开了尖锐的利刺，白鸢和你不约而同皱了皱眉。"
  },
  [111320043] = {
    id = 111320043,
    name = "这不是普通的——小心！"
  },
  [111320044] = {
    id = 111320044,
    name = "你躲掉了魔物的一次扑击，魔物没有停顿地朝白鸢扑了上去，但你的剑比它更快，狠狠地扎入了它的弱点处。魔物发出一声尖锐的惨叫，身体瞬间破碎，一股浓厚的浊炁喷发而出！"
  },
  [111320045] = {id = 111320045, name = "走！"},
  [111320046] = {
    id = 111320046,
    name = "你与白鸢快速离开现场，走了很长一段路，直到看不见那团黑雾。"
  },
  [111320047] = {
    id = 111320047,
    name = "那只魔物应该已经变异了，速度很快。"
  },
  [111320048] = {id = 111320048, name = "多谢。"},
  [111320049] = {
    id = 111320049,
    name = "你愣了愣，想起最后魔物是朝她扑去的，笑着摇了摇头，余光瞥见她的袖口处粘上了魔物破碎的肢体，正想提醒她，就看见白鸢已经取出了一块银红相间的帕子，仔仔细细地擦干净了。"
  },
  [111320050] = {id = 111320050, name = "......"},
  [111320051] = {
    id = 111320051,
    name = "让你见笑了，保持衣冠整洁是骑士的准则之一。"
  },
  [111320052] = {
    id = 111320052,
    name = "白鸢小姐，刚刚你也看到了，这一路并不平静，不如一起同行如何？"
  },
  [111320053] = {
    id = 111320053,
    name = "......你真的执意要去？"
  },
  [111320054] = {
    id = 111320054,
    name = "唔，你还想拦着我吗？"
  },
  [111320055] = {
    id = 111320055,
    name = "不，我只能劝解你，无法强制拦下你。我没有这样的权利，也没有拦下你所需的绝对武力。"
  },
  [111320056] = {
    id = 111320056,
    name = "呵呵，多谢夸奖，那一起走吧。"
  },
  [111320057] = {
    id = 111320057,
    name = "你先走吧，这不合骑士的规矩。"
  },
  [111320058] = {
    id = 111320058,
    name = "在你靠近她后，她反而往后退了一步，直到回到了刚才的距离。"
  },
  [111320059] = {
    id = 111320059,
    name = "呵呵，你们的规矩真多。那我走前面吧，开路的事就让我来。"
  },
  [111320060] = {
    id = 111320060,
    name = "好。我会一直在你身后守护。"
  },
  [111320061] = {
    id = 111320061,
    name = "她的声音清淡温和，却没什么起伏的情绪。你无奈地朝前走，身后的脚步声有规律地跟了上来。"
  },
  [111320062] = {
    id = 111320062,
    name = "离开那片枯萎的森林后，植被越发荒凉，不过没走多久，就看到了几个简易的帐篷伫立在前方，像搭建了一个临时的营地。"
  },
  [111320063] = {
    id = 111320063,
    name = "嗯？难道是公会来人了？"
  },
  [111320064] = {
    id = 111320064,
    name = "公会的人知道这件事？"
  },
  [111320065] = {
    id = 111320065,
    name = "我就是从公会那里得知的，你难道不是？"
  },
  [111320066] = {
    id = 111320066,
    name = "不是。但这件事是家族的事，和公会无关。"
  },
  [111320067] = {
    id = 111320067,
    name = "白鸢声音微沉，似乎不太愿意公会的干预。"
  },
  [111320068] = {
    id = 111320068,
    name = "你的家族？"
  },
  [111320069] = {
    id = 111320069,
    name = "是，住在帕尔据点的人都是我亚莉西斯家族的旁支，他们出了事求助于主家，祖父就让我来处理这件事。"
  },
  [111320070] = {
    id = 111320070,
    name = "你们往前走了几步，白鸢看清了那些帐篷，声音温淡。"
  },
  [111320071] = {
    id = 111320071,
    name = "帐篷上的花纹是亚莉西斯家族的家徽，还有家族预警魔物的铃铛，不是公会的人。"
  },
  [111320072] = {
    id = 111320072,
    name = "嗯？他们竟然没住在据点？看来据点真的出事了。"
  },
  [111320073] = {
    id = 111320073,
    name = "你们走进了临时营地，他们之中的人也发现了你们的到来，统统凑到一起，原地注视着你们，一个中年人摸着胡子走上前来。"
  },
  [111320074] = {
    id = 111320074,
    name = "你就是白鸢？"
  },
  [111320075] = {
    id = 111320075,
    name = "是的，祖父让我过来调查情况。"
  },
  [111320076] = {
    id = 111320076,
    name = "只是调查？难道不应该帮我们解决事件吗？作为预备役骑士，这不是理所应当的事吗？"
  },
  [111320077] = {id = 111320077, name = "......"},
  [111320078] = {
    id = 111320078,
    name = "这是你的侍从？竟然敢用这种眼神直视我们，真是不分长幼尊卑。"
  },
  [111320079] = {
    id = 111320079,
    name = "在你说话前，白鸢朝前走了半步，神色镇定，眼中却闪着锐利的光，她看向据点负责人，一字一句从容地回应。"
  },
  [111320080] = {
    id = 111320080,
    name = "你不要误会，他不是家族的人。你有什么要我帮忙吗？"
  },
  [111320081] = {
    id = 111320081,
    name = "帮忙？白鸢小姐，你看不到吗？我们现在无家可归了。"
  },
  [111320082] = {
    id = 111320082,
    name = "是啊，白鸢小姐，你看咱们的据点被爆炸毁了，什么时候才能回去住啊？"
  },
  [111320083] = {
    id = 111320083,
    name = "我的布偶还在里面没拿回来呢......"
  },
  [111320084] = {
    id = 111320084,
    name = "......好，我会先去据点看看，到底是什么原因，再寻找解决问题的办法。"
  },
  [111320085] = {
    id = 111320085,
    name = "等等，你不知道我们现在需要什么吗？吃的喝的统统没了，你们必须先给我解决当下的问题。"
  },
  [111320086] = {
    id = 111320086,
    name = "是啊，是啊，事发之后我们就写信了，这都好几天了，你才过来，我们的食物都吃光了。"
  },
  [111320087] = {
    id = 111320087,
    name = "我还想吃雀眼糖！"
  },
  [111320088] = {
    id = 111320088,
    name = "我身上没有糖果。"
  },
  [111320089] = {
    id = 111320089,
    name = "我就要吃就要吃嘛呜呜呜......"
  },
  [111320090] = {
    id = 111320090,
    name = "你扫了一眼那群家族里的人，发现其中好几个身负武器，明显是会武技和魔法的人，可竟然会出现物资匮乏的情况，让你觉得有些不可思议。"
  },
  [111320091] = {
    id = 111320091,
    name = "大家冷静，当务之急，是解决这里的浊炁问题。这些浊炁不同寻常，我这里带了一些莹草，你们记得按时服用。"
  },
  [111320092] = {
    id = 111320092,
    name = "白鸢把一袋莹草药剂交给了负责人，正打算询问据点情况时，负责人冷笑了一声。"
  },
  [111320093] = {
    id = 111320093,
    name = "呵，光是莹草怎么能吃饱饭，不如去给我们找点食物来吧。"
  },
  [111320094] = {
    id = 111320094,
    name = "还有淡水和防寒的衣物，住在这里真的快冻死了！"
  },
  [111320095] = {
    id = 111320095,
    name = "呜呜呜呜，为什么不能住房子？喂，你们骑士不是无所不能吗？快给我们盖几间房子！"
  },
  [111320096] = {id = 111320096, name = "......"},
  [111320097] = {
    id = 111320097,
    name = "越来越多地拥上来，对着白鸢提出自己的要求，有的让她拾柴火，更有甚者让她去买酒，还有对她的剑感兴趣的，妄图想拿去把玩的......白鸢依旧端庄地站在那里，只是眼神空茫了一瞬，像迷路的白鹤，有些无所适从。"
  },
  [111320098] = {
    id = 111320098,
    name = "我说，你们是断手断脚了吗？就连寻找食物这么简单的事，都要白鸢小姐去做。"
  },
  [111320099] = {
    id = 111320099,
    name = "你是谁？！"
  },
  [111320100] = {
    id = 111320100,
    name = "我是谁跟你有什么关系？"
  },
  [111320101] = {
    id = 111320101,
    name = "哼，连名字都不敢说的小贼，滚出我们的地方！"
  },
  [111320102] = {
    id = 111320102,
    name = "这可不是你们的地方，你们的据点现在被砰地炸了啊。"
  },
  [111320103] = {
    id = 111320103,
    name = "说话的时候，你放出一道魔法力，临近树上的枯枝与你的话相呼应，砰地一声断裂了一大截，落在负责人的身边。"
  },
  [111320104] = {id = 111320104, name = "你！！"},
  [111320105] = {
    id = 111320105,
    name = "你们正可怜巴巴地等白鸢小姐来解决问题，如果她没办法及时地解决问题，你们很快就会被浊炁侵蚀，皮肤溃烂，神智疯癫，接着，你会杀了你的家人，朋友，最后是自己，然后彻底变成一个堕落者，等人来将你灭除，最后灰飞烟灭，一点痕迹也不留。"
  },
  [111320106] = {
    id = 111320106,
    name = "就算是这样，你们还想让白鸢小姐浪费时间，为你们做寻找食物这么简单的事吗？"
  },
  [111320107] = {
    id = 111320107,
    name = "你说的话不徐不疾，但却令整个营地安静了好一阵，负责人面色紧绷，恶狠狠地盯着你，难堪地一言不发，倒是旁边年长的人很快出来和稀泥。"
  },
  [111320108] = {
    id = 111320108,
    name = "哈哈，怎么能让白鸢小姐做这些无关紧要的事呢，正事要紧，正事要紧啊，这个正好做干柴，小子快去点火。"
  },
  [111320109] = {
    id = 111320109,
    name = "他捡起了干柴扔给身边的小辈，目光看向你时还有些畏惧。"
  },
  [111320110] = {
    id = 111320110,
    name = "（武力震慑果然有用，都是些欺软怕硬的家伙啊。）"
  },
  [111320111] = {
    id = 111320111,
    name = "那你们先安顿在这里，我会在调查清楚后，再行下一步安排。"
  },
  [111320112] = {
    id = 111320112,
    name = "......哼，好吧。"
  },
  [111320113] = {id = 111320113, name = "等等。"},
  [111320114] = {
    id = 111320114,
    name = "你还有什么事？！"
  },
  [111320115] = {
    id = 111320115,
    name = "你们既然从据点里出来，总知道里面的基本情况吧？"
  },
  [111320116] = {
    id = 111320116,
    name = "还能有什么情况，白鸢、白鸢小姐去看看就知道了。"
  },
  [111320117] = {
    id = 111320117,
    name = "你把知道的都告诉我们，这样不是更能节省时间吗？难道你想拖到被浊炁侵蚀？"
  },
  [111320118] = {id = 111320118, name = "......"},
  [111320119] = {
    id = 111320119,
    name = "负责人狠狠地瞪了你一眼，倒是白鸢家族的长辈识趣，赶紧拉着你们将自己知道的都说了出来。"
  },
  [111320120] = {
    id = 111320120,
    name = "爆炸就在据点里？为什么会产生爆炸，知道具体原因吗？"
  },
  [111320121] = {
    id = 111320121,
    name = "因为有家族的预警魔法铃，那晚大家都在熟睡，巨响响起的时候，我们当时还以为是地震，跑出房间后，才发现是一场爆炸。只可惜约翰尼了，他运气不好，那样被炸死了......哎。"
  },
  [111320122] = {
    id = 111320122,
    name = "约翰尼？"
  },
  [111320123] = {
    id = 111320123,
    name = "他是我们旁支的一个小辈，和长老，就是负责人最亲了，他死了以后，负责人的脾气就很不好。"
  },
  [111320124] = {
    id = 111320124,
    name = "你默默地将他说的话记在心里，又询问了其他问题，都没什么收获，最终决定去据点看看再说。"
  },
  [111320125] = {
    id = 111320125,
    name = "离开临时营地，白鸢走了一段在前方停下了，神情微顿，眉眼安静。"
  },
  [111320126] = {
    id = 111320126,
    name = "刚才，谢谢你为我解围。"
  },
  [111320127] = {
    id = 111320127,
    name = "不用客气，与其听他们抱怨，不如尽快解决问题。"
  },
  [111320128] = {
    id = 111320128,
    name = "作为为家族而生的骑士，无法直言拒绝家族成员的需求，即便怎么不合理，骑士都必须怀有慈悲之心去包容和保护他们。是你帮我解决了困扰的难题，所以我想说一声谢谢。"
  },
  [111320129] = {
    id = 111320129,
    name = "呵呵，那就别再讲究那么多的规矩了。"
  },
  [111320130] = {
    id = 111320130,
    name = "白鸢诧异了一瞬，而后轻轻展开了笑颜。"
  },
  [111320131] = {
    id = 111320131,
    name = "这......就是帕尔据点？"
  },
  [111320132] = {
    id = 111320132,
    name = "还没到达据点，你们已经看到了笼罩在据点上空的黑雾，似乎将一切吞没在一片混沌之中，一间间屋舍门户大开，木门和杂物散落在地上，看得出所有人都撤离得非常及时。"
  },
  [111320133] = {
    id = 111320133,
    name = "看来那位负责人不是不懂，跑得这么快。"
  },
  [111320134] = {
    id = 111320134,
    name = "这里的浊炁，和森林里的不同，侵蚀力更强了，如果不尽快解决，浊炁一旦扩散开来，会非常危险。"
  },
  [111320135] = {
    id = 111320135,
    name = "你与白鸢对视一眼，准备好后，踏向了那个黑雾升起的地方，一阵悲嚎的狂风在房屋之间旋转而上，毫不留情地扭曲了天空的颜色，毫无生机的景象让人感到一股深深的孤寂。"
  },
  [111320136] = {
    id = 111320136,
    name = "在那里，爆炸的地方。"
  },
  [111320137] = {
    id = 111320137,
    name = "尘土弥漫，残存的墙壁裂开，你们找到了爆炸的地点——位于据点中心的一间屋舍被夷为平地，仿佛被一双巨大的手撕裂，寂静笼罩了整片黑雾中，没有鸟鸣声，只有微弱的脚步回声穿越废墟的缝隙。"
  },
  [111320138] = {
    id = 111320138,
    name = "看来那里就是爆炸的地点了。"
  },
  [111320139] = {
    id = 111320139,
    name = "簌簌——"
  },
  [111320140] = {
    id = 111320140,
    name = "什么声音？"
  },
  [111320141] = {
    id = 111320141,
    name = "你忽然背上一凉，寒毛直竖，不好的警报在脑中拉响，下一刻，突如其来的黑影扑了上来，狠狠地撞在你刚拔出的剑刃之上！"
  },
  [111320142] = {
    id = 111320142,
    name = "是堕落者！"
  },
  [111320143] = {
    id = 111320143,
    name = "堕落者一击不成，落在了破损的墙边，暴露出腐烂的血肉和骨架。空洞的眼眶中闪烁着恶意的红色光芒，发出低沉而令人毛骨悚然的嘶吼声。"
  },
  [111320144] = {id = 111320144, name = "吼！！"},
  [111320145] = {
    id = 111320145,
    name = "它的手臂扭曲而畸形，指甲变成了尖锐的利爪，恶心的口水从嘴角不断淌下，白鸢皱了皱眉，却毅然地拿剑挥了过去。"
  },
  [111320146] = {id = 111320146, name = "！！！"},
  [111320147] = {
    id = 111320147,
    name = "堕落者敏捷地躲掉了白鸢的攻击，反而掠到她的身后，你快速地将白鸢揽了过来，挡下了那只利爪的攻击。"
  },
  [111320148] = {
    id = 111320148,
    name = "情急之下，抱歉了。"
  },
  [111320149] = {
    id = 111320149,
    name = "你很快放开了白鸢，继续投入战斗，没注意到白鸢怔愣了半晌，才跟上你的脚步重新进入战斗。"
  },
  [111320150] = {
    id = 111320150,
    name = "这不是普通的堕落者。"
  },
  [111320151] = {
    id = 111320151,
    name = "嗯，它的速度太快了，也许和这里的浊炁有关。"
  },
  [111320152] = {
    id = 111320152,
    name = "在一番缠斗之后，你找准了一个机会，剑刺入堕落者的心脏，他尖叫着拔出剑，怪力将剑与你一同抬起甩飞！"
  },
  [111320153] = {
    id = 111320153,
    name = "小心！！"
  },
  [111320154] = {
    id = 111320154,
    name = "你被扔在地上，借力翻滚迅速爬了起来，却看着堕落者竟然已逃走消失了。"
  },
  [111320155] = {
    id = 111320155,
    name = "这个堕落者不同寻常，他被我刺中了要害，竟然毫发无损......"
  },
  [111320156] = {
    id = 111320156,
    name = "你受伤了。"
  },
  [111320157] = {
    id = 111320157,
    name = "你看着手臂的擦伤，朝她笑了笑。"
  },
  [111320158] = {
    id = 111320158,
    name = "没事，只是破了点皮。"
  },
  [111320159] = {
    id = 111320159,
    name = "白鸢走上前，固执地拿出伤药，你无奈地伸出手。伤药洒在被乱石割裂的皮肤上，丝丝凉意浸入血脉，似乎连人也清醒了一些。"
  },
  [111320160] = {
    id = 111320160,
    name = "呵呵，现在你倒有点人气，没那么讲规矩了。"
  },
  [111320161] = {
    id = 111320161,
    name = "白鸢为你包扎的手一滞，你明显感到了她的僵硬，很快她又退了回去，回到疏离客气的距离。"
  },
  [111320162] = {
    id = 111320162,
    name = "作为预备役骑士，让你为我受伤，是我的失职。"
  },
  [111320163] = {
    id = 111320163,
    name = "别把什么责任都揽在自己的身上，很累的。"
  },
  [111320164] = {
    id = 111320164,
    name = "白鸢神情微顿，平静的双眸里有了一丝波澜。"
  },
  [111320165] = {
    id = 111320165,
    name = "先回去吧。"
  },
  [111320166] = {
    id = 111320166,
    name = "不继续查下去了？"
  },
  [111320167] = {
    id = 111320167,
    name = "这里出现了堕落者，又离临时营地不远，得尽快通知他们转移。"
  },
  [111320168] = {
    id = 111320168,
    name = "嗯，那你快去通知吧，我在这里等你，顺便再调查一下爆炸的起因。"
  },
  [111320169] = {
    id = 111320169,
    name = "不，堕落者不知何时又会卷土重来，你要和我一起走。"
  },
  [111320170] = {id = 111320170, name = "诶？"},
  [111320171] = {
    id = 111320171,
    name = "白鸢面色不变，安静地看着你，难得表现出了强硬的态度。"
  },
  [111320172] = {id = 111320172, name = "......"},
  [111320173] = {
    id = 111320173,
    name = "许久，你在她沉静的注视下败下阵来。"
  },
  [111320174] = {
    id = 111320174,
    name = "好吧，一起回去，正好我也有些疑问需要他们解答。"
  },
  [111320175] = {
    id = 111320175,
    name = "好。你的伤口也需要仔细处理，以免浊炁进一步侵蚀。"
  },
  [111320176] = {
    id = 111320176,
    name = "白鸢的眼神似乎有了些笑意，但仔细看去，还是平常那样温和无害的样子，你揉了揉太阳穴，怀疑自己是不是看错了。"
  },
  [111320177] = {
    id = 111320177,
    name = "你先在这里治疗，我去跟负责人说。"
  },
  [111320178] = {id = 111320178, name = "好。"},
  [111320179] = {
    id = 111320179,
    name = "回到临时营地后，白鸢找人为你腾出了一间空帐篷，又重新敷药包扎后才离开，你目视着她走向那群人，不由地有些担忧。"
  },
  [111320180] = {
    id = 111320180,
    name = "（那么温和单纯的性格，能应付那些老狐狸吗？）"
  },
  [111320181] = {
    id = 111320181,
    name = "白鸢没有拖沓，见到负责人的那一刻，她便说出了遇到的麻烦与忧虑。"
  },
  [111320182] = {
    id = 111320182,
    name = "我们去看过据点了，在里面发现了堕落者。"
  },
  [111320183] = {id = 111320183, name = "！！！"},
  [111320184] = {
    id = 111320184,
    name = "堕落者？怎么会有堕落者的？"
  },
  [111320185] = {
    id = 111320185,
    name = "堕落者......好可怕......我们，我们会变成堕落者吗......"
  },
  [111320186] = {
    id = 111320186,
    name = "只要没有被浊炁侵蚀，就不会。"
  },
  [111320187] = {
    id = 111320187,
    name = "面对惧怕的小辈，白鸢不太会安慰他人，只温和耐心地说话。"
  },
  [111320188] = {
    id = 111320188,
    name = "这个临时营地离帕尔据点太近了，那边不仅出现了堕落者，还是变异浊炁的源头，过不了两天，这里也会受到影响。"
  },
  [111320189] = {id = 111320189, name = "......"},
  [111320190] = {
    id = 111320190,
    name = "那该如何是好啊？"
  },
  [111320191] = {
    id = 111320191,
    name = "我的建议是暂时离开这里，浊炁险恶，加之堕落者的行踪无法断定，大家可以暂时寻一处安全的地方暂住，等危机解除后再返回。"
  },
  [111320192] = {
    id = 111320192,
    name = "什么？你竟然没有杀掉那个堕落者吗？！"
  },
  [111320193] = {
    id = 111320193,
    name = "那堕落者速度太快，与一般堕落者不同，我们刚才失手了。"
  },
  [111320194] = {
    id = 111320194,
    name = "那怎么办？它要是发现我们该怎么办？你是不是人手不够，我让那几个会魔法武技的去帮你！必须把那个堕落者杀掉啊！"
  },
  [111320195] = {
    id = 111320195,
    name = "我，我不要去，我的火球术只能生火，还打不了魔物，怎么杀能堕落者。白鸢，你，你不是骑士吗？骑士就该守护我们呀，你快去把那个堕落者杀掉！"
  },
  [111320196] = {
    id = 111320196,
    name = "......可就算杀掉了堕落者，没有解决浊炁变异的问题，你们也不能在此久居。"
  },
  [111320197] = {
    id = 111320197,
    name = "唉，我们的家在这里，要我们举家搬迁，我们该去哪里啊......"
  },
  [111320198] = {
    id = 111320198,
    name = "要走吗？我哪儿也不想去......"
  },
  [111320199] = {
    id = 111320199,
    name = "白鸢安静地听他们说着，因为家族的庇佑，他们会定时得到物资，培养的探险者也散落到了深渊各地，而剩下的普通人已经习惯了这里的生活，这种情况下要让他们搬走......面对他们的迷茫，白鸢忽然深感无力，这时，据点负责人突然开口了。"
  },
  [111320200] = {
    id = 111320200,
    name = "跟你一起的那个人呢？"
  },
  [111320201] = {
    id = 111320201,
    name = "他吗？他受了点伤，我让他暂时在那边休息。"
  },
  [111320202] = {
    id = 111320202,
    name = "咦，看他之前趾高气扬的样子，我还以为他有多厉害呢，结果连个堕落者都对付不了......"
  },
  [111320203] = {
    id = 111320203,
    name = "闭嘴，我在和白鸢小姐商量要事，你一边去。"
  },
  [111320204] = {
    id = 111320204,
    name = "你有办法了吗？"
  },
  [111320205] = {
    id = 111320205,
    name = "那家伙是你什么人？"
  },
  [111320206] = {
    id = 111320206,
    name = "嗯？他是......萍水相逢的......朋友吧。"
  },
  [111320207] = {
    id = 111320207,
    name = "呵呵，那就好，听我说，你让他去找到那个堕落者，然后让他引诱......"
  },
  [111320208] = {
    id = 111320208,
    name = "负责人拉着白鸢去了旁边，越说越小声，最后只有白鸢听得见，而后负责人做了一个手势，白鸢睁大了眼睛。"
  },
  [111320209] = {
    id = 111320209,
    name = "不行！这有悖于骑士道义，我做不到。"
  },
  [111320210] = {
    id = 111320210,
    name = "你，你竟然为了一个外人拒绝保护家族，算什么预备役骑士！"
  },
  [111320211] = {
    id = 111320211,
    name = "白鸢直视着他，坚定的眼神不由让负责人退后了好几步。"
  },
  [111320212] = {
    id = 111320212,
    name = "总之，这是你该尽的责任和义务！你好好想想你的任务是什么，别辜负了你的祖父对你的期望！"
  },
  [111320213] = {id = 111320213, name = "......"},
  [111320214] = {
    id = 111320214,
    name = "我会再去据点，尽快找到爆炸的原因，解决这次危机，在我回来之前请负责人拉拢预警铃，保护临时营地不受魔物侵扰。"
  },
  [111320215] = {
    id = 111320215,
    name = "白鸢端正地行了一个骑士礼，没再看那个气得吹胡子瞪眼的负责人，步伐沉稳地向你走了过来。"
  },
  [111320216] = {
    id = 111320216,
    name = "怎么，吵架了？"
  },
  [111320217] = {
    id = 111320217,
    name = "没什么......"
  },
  [111320218] = {
    id = 111320218,
    name = "白鸢面色犹豫，摇了摇头。"
  },
  [111320219] = {
    id = 111320219,
    name = "呵呵，他们不愿意听你的劝告？"
  },
  [111320220] = {
    id = 111320220,
    name = "其实，我很理解他们，离开这里，又该搬去哪里呢？"
  },
  [111320221] = {
    id = 111320221,
    name = "那就把事故解决了吧。"
  },
  [111320222] = {
    id = 111320222,
    name = "嗯，我正打算去看看，你就在这里——"
  },
  [111320223] = {
    id = 111320223,
    name = "我没那么弱不禁风，骑士小姐。"
  },
  [111320224] = {
    id = 111320224,
    name = "你甩了甩手臂，对战斗已经没什么大碍了，白鸢露出了微笑。"
  },
  [111320225] = {
    id = 111320225,
    name = "好，有你助力，这次一定能抓到那个堕落者。"
  },
  [111320226] = {
    id = 111320226,
    name = "很快，你们再次出发前往黑雾弥漫的帕尔据点。"
  },
  [111320227] = {
    id = 111320227,
    name = "这一路都没见到那个堕落者，难道是藏起来了？"
  },
  [111320228] = {
    id = 111320228,
    name = "小心为上，我们直接去爆炸中心的地方吧，上一次被堕落者拦截......拦截......没错，那堕落者行为古怪，好像一直在阻止我们做什么。"
  },
  [111320229] = {
    id = 111320229,
    name = "白鸢眼眸微亮，不再警惕四周，反而加快了脚步。"
  },
  [111320230] = {
    id = 111320230,
    name = "被你说中了，这一路上都没有其他危险，那家伙真的守在据点里。"
  },
  [111320231] = {
    id = 111320231,
    name = "到达据点后，白鸢停了下来，神色肃然。"
  },
  [111320232] = {
    id = 111320232,
    name = "堕落者没有出现......"
  },
  [111320233] = {
    id = 111320233,
    name = "我去看看，你在这里观察情况。"
  },
  [111320234] = {
    id = 111320234,
    name = "不，我们一起，你一个人行动，我无法及时援护。"
  },
  [111320235] = {id = 111320235, name = "好吧。"},
  [111320236] = {
    id = 111320236,
    name = "她与你一同并肩走向那黑雾最深处，你想起她的那些骑士规矩，朝她笑了笑，白鸢似乎也反应了过来，窘迫地轻咳了一声。"
  },
  [111320237] = {
    id = 111320237,
    name = "堕落者速度诡异，固守骑士准则或有不利之处......况且，这里没有其他人。"
  },
  [111320238] = {
    id = 111320238,
    name = "你笑而不语，走向了那处爆炸的深坑，深坑一片狼藉，一缕缕黑雾不断从地下渗透而出。"
  },
  [111320239] = {
    id = 111320239,
    name = "这栋房子已经完全被炸毁了。"
  },
  [111320240] = {
    id = 111320240,
    name = "是的，不过总会有一些残留的线索，咦，你看这是什么？"
  },
  [111320241] = {
    id = 111320241,
    name = "牛皮纸？上面写的是......开支和......据点物资分配......下面看不清......"
  },
  [111320242] = {
    id = 111320242,
    name = "这里地处据点中心，难道不是一般的平民屋爆炸？而是管理处出了事故？"
  },
  [111320243] = {
    id = 111320243,
    name = "管理处......"
  },
  [111320244] = {
    id = 111320244,
    name = "你继续搜集附近的残留物，找到了更多可证实的这里是据点管理处的证据。"
  },
  [111320245] = {
    id = 111320245,
    name = "为什么负责人不告诉我？"
  },
  [111320246] = {
    id = 111320246,
    name = "......不告诉你，就是不想让你知道，看来这里还有秘密呢。"
  },
  [111320247] = {
    id = 111320247,
    name = "既然是秘密......又为什么专门找祖父求救？"
  },
  [111320248] = {
    id = 111320248,
    name = "下去看看就知道了。"
  },
  [111320249] = {
    id = 111320249,
    name = "你踏了踏脚底的石砖，感受到空空的共振。"
  },
  [111320250] = {
    id = 111320250,
    name = "下面有东西？！"
  },
  [111320251] = {
    id = 111320251,
    name = "找找看，入口一定在附近。"
  },
  [111320252] = {
    id = 111320252,
    name = "就在你们仔细寻找时，一股微风袭来，熟悉的簌簌声响起，你没回头之前就率先拔出了武器。有了上一次的交锋，你轻易抵御了堕落者的进攻，很快，堕落者又被你的剑刺伤了。"
  },
  [111320253] = {id = 111320253, name = "吼——"},
  [111320254] = {
    id = 111320254,
    name = "可这一次，堕落者没有离开，反而朝着白鸢的地方扑了过去。"
  },
  [111320255] = {
    id = 111320255,
    name = "我拦着它，你继续找入口！"
  },
  [111320256] = {
    id = 111320256,
    name = "白鸢点点头，信任地将后背交给了你，没过一会儿真的发现了一个地下通道。"
  },
  [111320257] = {
    id = 111320257,
    name = "找到了！"
  },
  [111320258] = {
    id = 111320258,
    name = "轰隆隆——地下通道打开的时候，比外界浓郁十倍的黑雾猛然喷发而出，白鸢不觉被呛了一声，染红了双目。"
  },
  [111320259] = {
    id = 111320259,
    name = "我下去看看！"
  },
  [111320260] = {
    id = 111320260,
    name = "黑雾暴起，堕落者的力量明显加强了，你无暇回应，心中产生不妙的直觉。"
  },
  [111320261] = {
    id = 111320261,
    name = "高强度地与堕落者交战，耗损了不少的体力，身上也被抓破了好几道痕迹，而堕落者即使受伤却越加暴戾凶猛，直到你听到了地下的动静，白鸢脚步缓慢地抱了一方盒子出来。"
  },
  [111320262] = {
    id = 111320262,
    name = "你没事吧？！"
  },
  [111320263] = {id = 111320263, name = "吼——"},
  [111320264] = {
    id = 111320264,
    name = "堕落者见到了那方盒子，猛地尖声叫嚣了一声，不顾一切地冲白鸢袭击过去。"
  },
  [111320265] = {id = 111320265, name = "！！！"},
  [111320266] = {
    id = 111320266,
    name = "白鸢一手抱着盒子，拿剑抵挡堕落者的袭击，没想到竟然一个踉跄，后退了好几步。"
  },
  [111320267] = {
    id = 111320267,
    name = "白鸢小姐！"
  },
  [111320268] = {
    id = 111320268,
    name = "白鸢双目泛红，嘴唇乌紫，身上抱着的盒子源源不断地溢出浊炁，仿佛她整个人在不断散发着黑气。你心中一凛，白鸢恐怕受到了这个盒子的影响。"
  },
  [111320269] = {
    id = 111320269,
    name = "走开，走开！"
  },
  [111320270] = {
    id = 111320270,
    name = "白鸢抱紧盒子，剑锋挥舞得嚯嚯响，堕落者敏捷地躲避，还想袭击时，被你一剑刺穿了脖颈，接着整个头颅削了下来，骨碌碌地滚落在地。"
  },
  [111320271] = {
    id = 111320271,
    name = "呜呜呜——"
  },
  [111320272] = {
    id = 111320272,
    name = "眼前的人形怪物烟消云散，掉落了一块小木牌子，上面刻着你在帐篷上看到的花纹。你拾了起来，无暇思考这块牌子的意义，白鸢此刻已跪在了地上，双手抱着头，似乎非常痛苦。"
  },
  [111320273] = {
    id = 111320273,
    name = "这个盒子......"
  },
  [111320274] = {
    id = 111320274,
    name = "你用魔法暂时封印了这块盒子，立刻去看白鸢的状况。"
  },
  [111320275] = {
    id = 111320275,
    name = "不......妈妈......爸爸......不要死......"
  },
  [111320276] = {
    id = 111320276,
    name = "白鸢小姐，白鸢，白鸢！"
  },
  [111320277] = {
    id = 111320277,
    name = "白鸢的眼睛猛然睁开，瞳仁一片暗黑，浊炁已入侵了她的双眼，你按下那只不安分的手，缴获了武器，一狠心将她击晕，连盒带人一起带走。"
  },
  [111320278] = {
    id = 111320278,
    name = "抱歉了，白鸢小姐。这里不能久待，我带你去安全的地方。"
  },
  [111320279] = {
    id = 111320279,
    name = "令人遗憾的是，在离开据点不久就下雨了。带着浊炁的黑雨似乎具有腐蚀性，你快速在山边寻了一个山洞，带着白鸢躲了进去。"
  },
  [111320280] = {
    id = 111320280,
    name = "祖父......祖父......"
  },
  [111320281] = {
    id = 111320281,
    name = "你长叹了一口气，搜出最后一支莹草药剂给她喂了下去。"
  },
  [111320282] = {
    id = 111320282,
    name = "......为了一个盒子，何必以性命冒险呢？"
  },
  [111320283] = {
    id = 111320283,
    name = "白鸢的情况不容乐观，以往侵蚀到这个份上的探险者，几乎都变成了堕落者，接着会失去人性，变成五官变形的怪物，再在某个时候被人类杀掉，甚至不知道杀死自己的，是不是自己认识的人......"
  },
  [111320284] = {
    id = 111320284,
    name = "能不能醒来，就看你自己了，如果你......"
  },
  [111320285] = {
    id = 111320285,
    name = "你摇了摇头，手里已经没有莹草了。希望白鸢身为预备役骑士，有着更坚韧的意志力来抵抗浊炁的侵蚀，在那个结果出现之前，你不会轻易动手......"
  },
  [111320286] = {
    id = 111320286,
    name = "......祖父......祖父......我错了......"
  },
  [111320287] = {
    id = 111320287,
    name = "白鸢断断续续地呢喃着，似乎陷入了噩梦之中。看着外面渐晚的天色，恼怒的雨下个不停，你随意在山洞中拾了些枯枝，点燃了火堆。"
  },
  [111320288] = {id = 111320288, name = "......"},
  [111320289] = {
    id = 111320289,
    name = "你重新拿起了那个被封印的盒子，一瞬间心跳如鼓，竟有一种想将其打开的冲动。你狠狠地掐了一下手心，恢复了清醒的目光，将盒子放在了一边。"
  },
  [111320290] = {
    id = 111320290,
    name = "这个盒子果然不简单，难道白鸢小姐打开过盒子了？"
  },
  [111320291] = {
    id = 111320291,
    name = "想起白鸢抱着盒子出来时，伴随的浓烈黑雾，你扶了扶额，大概肯定了自己的猜想。"
  },
  [111320292] = {
    id = 111320292,
    name = "......热......好热......"
  },
  [111320293] = {
    id = 111320293,
    name = "你听到白鸢的呢喃，走到她身边唤了她一声，在没有回应后，你轻轻触碰着她的额头，果然感受到了滚烫的温度。"
  },
  [111320294] = {
    id = 111320294,
    name = "这可不好办啊。"
  },
  [111320295] = {
    id = 111320295,
    name = "可白鸢似乎感觉到了那一抹清凉，忽然抓紧了你的手，你一惊，稳住了身形才没被扯过去。"
  },
  [111320296] = {
    id = 111320296,
    name = "......好热......好热......"
  },
  [111320297] = {
    id = 111320297,
    name = "白鸢小姐，你先放手。"
  },
  [111320298] = {
    id = 111320298,
    name = "昏迷中的人哪里听得见，你束手束脚地在手中凝结魔法为她降温，可没一会儿白鸢又一把将你推开，双手抱紧了自己，蜷缩成了一团，嘴里呜咽着。"
  },
  [111320299] = {
    id = 111320299,
    name = "......冷......好冷......好冷......"
  },
  [111320300] = {
    id = 111320300,
    name = "呼......真是......"
  },
  [111320301] = {
    id = 111320301,
    name = "你看着白鸢冷得发抖的样子，抓住了她冰冷的手，白鸢却瞬时爬到了你身上，环紧了你的腰腹。"
  },
  [111320302] = {id = 111320302, name = "......"},
  [111320303] = {
    id = 111320303,
    name = "迷迷蒙蒙中，白鸢忽冷忽热，一会儿喊渴一会儿说头疼，似乎头疼得厉害了，低声呻吟着，哭哭啼啼的声音听不清在说什么，你凑近了仔细听，听清之后难免惊讶。"
  },
  [111320304] = {
    id = 111320304,
    name = "不要......不做骑士......我不要做骑士......"
  },
  [111320305] = {
    id = 111320305,
    name = "谁让你做骑士？"
  },
  [111320306] = {
    id = 111320306,
    name = "祖父......我不做骑士......我不要......不要像妈妈那样......呜呜呜......"
  },
  [111320307] = {
    id = 111320307,
    name = "好好，不想做就不做。"
  },
  [111320308] = {id = 111320308, name = "......"},
  [111320309] = {
    id = 111320309,
    name = "你像哄小孩一样的语气，白鸢却像听到了答案一般，渐渐安静下来，陷入了睡眠。你折腾了一晚上，看白鸢四周的浊炁已经散去，终于松口气，也沉沉睡去。"
  },
  [111320310] = {
    id = 111320310,
    name = "翌日天明，感觉怀中人苏醒的时候，你也醒了过来，立刻坐起了身。"
  },
  [111320311] = {
    id = 111320311,
    name = "白鸢小姐，你醒了。"
  },
  [111320312] = {
    id = 111320312,
    name = "轰然之间，昨晚的记忆伴着嘴里的药草味从脑海深处飞出，白鸢头晕脑胀，双颊发烫。"
  },
  [111320313] = {
    id = 111320313,
    name = "我......我......"
  },
  [111320314] = {
    id = 111320314,
    name = "是还有哪里不舒服吗？"
  },
  [111320315] = {
    id = 111320315,
    name = "没事，我已经没事了！昨晚......谢谢你......"
  },
  [111320316] = {
    id = 111320316,
    name = "白鸢起身抓紧了手心，左看右看，觉得山洞太小，无处容身。"
  },
  [111320317] = {
    id = 111320317,
    name = "没事就好，你是不是在找这个？"
  },
  [111320318] = {
    id = 111320318,
    name = "你指了指角落的盒子，白鸢一看，那些旖旎的心思瞬间消失了，皱了皱眉。"
  },
  [111320319] = {
    id = 111320319,
    name = "这个盒子，你带过来了？！"
  },
  [111320320] = {
    id = 111320320,
    name = "嗯，想必这就是变异浊炁的源头。"
  },
  [111320321] = {
    id = 111320321,
    name = "难怪......我打开它之后，就有些神志不清了......"
  },
  [111320322] = {
    id = 111320322,
    name = "我想这就是负责人要找的东西。他自己没本事拿，又不想让别人知道，就让你来做这件事。"
  },
  [111320323] = {
    id = 111320323,
    name = "这里面到底是什么？"
  },
  [111320324] = {
    id = 111320324,
    name = "不会是好东西，你再看这个，从堕落者身上掉下来的。"
  },
  [111320325] = {
    id = 111320325,
    name = "你拿出那块小木牌，白鸢在看到木牌上的花纹，变了眼神。"
  },
  [111320326] = {
    id = 111320326,
    name = "堕落者，也是家族的人？！"
  },
  [111320327] = {
    id = 111320327,
    name = "说起来，他们好像说过，爆炸之后有人失踪了。"
  },
  [111320328] = {id = 111320328, name = "......"},
  [111320329] = {
    id = 111320329,
    name = "白鸢沉默了一阵，抬眸看向你，恢复了镇定与优雅的气质。"
  },
  [111320330] = {
    id = 111320330,
    name = "我们把这个盒子带回去吧，我有很多疑问想问他们。"
  },
  [111320331] = {id = 111320331, name = "好。"},
  [111320332] = {
    id = 111320332,
    name = "白鸢小姐回来了！"
  },
  [111320333] = {
    id = 111320333,
    name = "远远的，有人看到了你们，纷纷通知了临时营地的众人，他们脸上个个都堆满了笑。"
  },
  [111320334] = {
    id = 111320334,
    name = "白鸢小姐，我就知道你一定能做到！你一去，那些黑雾就淡去很多了。"
  },
  [111320335] = {
    id = 111320335,
    name = "你......你真的做到了？！"
  },
  [111320336] = {
    id = 111320336,
    name = "负责人看到白鸢手中的盒子，露出了贪婪的眼神，他匆匆跑来，就打算接过那方盒子，被白鸢躲开了。"
  },
  [111320337] = {
    id = 111320337,
    name = "这个盒子里面是什么？"
  },
  [111320338] = {
    id = 111320338,
    name = "呵呵，别管是什么，这盒子里是什么，白鸢小姐就不用再问了，把这个盒子给我，这次的考核你就通过了。"
  },
  [111320339] = {id = 111320339, name = "考核？"},
  [111320340] = {
    id = 111320340,
    name = "白鸢顿了顿，拒绝了他的要求。"
  },
  [111320341] = {
    id = 111320341,
    name = "我可以把盒子给你，但在这之前，你需要回答我的问题，盒子里面是什么？"
  },
  [111320342] = {
    id = 111320342,
    name = "问这么多做什么，你的祖父给你的任务，只让你帮我们解决问题，可不包括弄清楚盒子里的东西。"
  },
  [111320343] = {
    id = 111320343,
    name = "为什么里面会有大量的浊炁，为什么那个堕落者身上会掉落家族的木牌？"
  },
  [111320344] = {
    id = 111320344,
    name = "......多管闲事！你都说那是堕落者，那就已经不是人了，还管他到底是谁？！"
  },
  [111320345] = {
    id = 111320345,
    name = "不说清楚，我是不会给你的。"
  },
  [111320346] = {
    id = 111320346,
    name = "白鸢，你想清楚了，你祖父的信在我手里，考核的印鉴也在我手里，我记得这次的任务是你成为正式骑士的考核之一吧？"
  },
  [111320347] = {
    id = 111320347,
    name = "白鸢脸色微白，双眉一蹙。"
  },
  [111320348] = {
    id = 111320348,
    name = "负责人说这个是什么意思？"
  },
  [111320349] = {
    id = 111320349,
    name = "不该你过问的事别问，不该你管的事别管。盒子给我，我呢就给你祖父写封亲笔信，如何？"
  },
  [111320350] = {
    id = 111320350,
    name = "不。这个盒子十分危险，对于据点、家族来说，它本不应该存在，如果你不告诉我，那我会带回家族，或者将其销毁。"
  },
  [111320351] = {
    id = 111320351,
    name = "你敢！！"
  },
  [111320352] = {
    id = 111320352,
    name = "负责人一听白鸢的决定，气得跳了起来，指着白鸢几乎情绪失控，言辞激烈。"
  },
  [111320353] = {
    id = 111320353,
    name = "我告诉你白鸢，你不过是家族指派的一个骑士，不你连骑士都算不上，小小的预备役，还敢过问我的事！"
  },
  [111320354] = {
    id = 111320354,
    name = "即使......只是预备役，我也有责任守护大家的安全。"
  },
  [111320355] = {
    id = 111320355,
    name = "哈哈哈哈，说得那么崇高，还不就是家族的一个工具！什么时候骑士也有自己的选择了？还是乖乖跟你父母一样，该死的时候就去死吧！"
  },
  [111320356] = {
    id = 111320356,
    name = "白鸢脸色发白，嘴唇微颤，想说什么却说不出话，负责人看她的状态，又想伸手抢过盒子，被你挡在了跟前。"
  },
  [111320357] = {
    id = 111320357,
    name = "不好意思，我想这盒子不能给你。"
  },
  [111320358] = {
    id = 111320358,
    name = "你这个外人，还想插手我们家族的事？"
  },
  [111320359] = {
    id = 111320359,
    name = "这可不是一个家族的问题，这个盒子导致变异浊炁外泄，对于整个深渊来说，是很严重的事件，我恰好有很好的公会朋友，他们会很乐意处理这件事的，这个盒子，就由我代为上交公会了。"
  },
  [111320360] = {
    id = 111320360,
    name = "你你你——"
  },
  [111320361] = {
    id = 111320361,
    name = "不用感谢我，至少把这个危险品带走，变异的浊炁也不会再发生了。白鸢小姐已经找到了事件症结，完成了她的使命，至于之后的事，就请你们自求多福吧。"
  },
  [111320362] = {
    id = 111320362,
    name = "无意于他们多做纠缠，你拉着晃神的白鸢快步离开了，身后是气急败坏的痛骂。"
  },
  [111320363] = {
    id = 111320363,
    name = "你一路将白鸢拉到了无人的森林里，确认环境的安全后，你放开了她的手。"
  },
  [111320364] = {
    id = 111320364,
    name = "你不用听他说了什么，那个负责人明显是被说中了秘密，才气得跳脚。"
  },
  [111320365] = {id = 111320365, name = "嗯。"},
  [111320366] = {
    id = 111320366,
    name = "白鸢无意识地点点头，整个人懵懵的，似乎还在想着负责人之前的话。"
  },
  [111320367] = {
    id = 111320367,
    name = "（那个人提到了白鸢的父母......看来她父母的死对她的打击很大......）"
  },
  [111320368] = {
    id = 111320368,
    name = "你安静了一阵，默默等白鸢回过神，等到她双眼恢复了神采，却苦涩地看向了你。"
  },
  [111320369] = {
    id = 111320369,
    name = "骑士真的如他所说，只是一个赴死的工具吗？"
  },
  [111320370] = {
    id = 111320370,
    name = "当然不是。"
  },
  [111320371] = {
    id = 111320371,
    name = "我的剑放在这里。我将牢记谦卑，怜悯，公正，荣誉，牺牲......"
  },
  [111320372] = {
    id = 111320372,
    name = "她静静呢喃着，扯出了一个笑。"
  },
  [111320373] = {
    id = 111320373,
    name = "祖父让我每天诵读的骑士宣言，原来只是想让我像父母那样牺牲......为了家族，为了荣誉，将鲜血洒在战场上，奉献出自己的一切......这就是他想要的吗？"
  },
  [111320374] = {
    id = 111320374,
    name = "白鸢的双眸忧伤，却因为一直以来的习惯克制着，你却感受到了她心中的痛苦和失落。"
  },
  [111320375] = {
    id = 111320375,
    name = "白鸢小姐，骑士只是一个身份，不是你这个人本身，你还是你。"
  },
  [111320376] = {
    id = 111320376,
    name = "白鸢偏头看你，迷离的眼睛里浸满了哀伤和疑问。"
  },
  [111320377] = {
    id = 111320377,
    name = "如果抛开骑士身份，白鸢小姐想成为一个什么样的人呢？"
  },
  [111320378] = {
    id = 111320378,
    name = "我......我......"
  },
  [111320379] = {
    id = 111320379,
    name = "白鸢思考了半晌，竟然想不到她除了骑士应该做什么，只能向你摇了摇头。"
  },
  [111320380] = {
    id = 111320380,
    name = "从小祖父就将我以骑士的方式训练着，不管是行为准则，还是生活习惯......我所有的一切，都是为了成为骑士。可是现在，我不知道，成为骑士之后的意义是什么呢......像父亲和母亲那样......牺牲吗？就好像，我不是我......我只是一个为了别人而存在的骑士，我......我不知道该怎么做......"
  },
  [111320381] = {
    id = 111320381,
    name = "不想做骑士，就不做吧。"
  },
  [111320382] = {
    id = 111320382,
    name = "白鸢一震，睁大眼睛看着你。想起她在发烧时的痛苦呓语，你不忍她的挣扎，继续说了下去。"
  },
  [111320383] = {
    id = 111320383,
    name = "每个人都是独立的个体，没有谁是为了谁而存在，如果骑士的身份对你是桎梏，为什么不摆脱它呢？每个人都有权利追求自己的理想，你也是。"
  },
  [111320384] = {
    id = 111320384,
    name = "从来、从来没有人和我说过这些，所有人都认为，我该成为骑士......祖父说，为了家族而死是一种荣耀，是理想中骑士的典范。"
  },
  [111320385] = {
    id = 111320385,
    name = "可你不是为他们活的，你有你自己的人生，自己的理想，不是吗？"
  },
  [111320386] = {
    id = 111320386,
    name = "我的一切都是被安排好的，就连殉道般的结局，都是注定的，好像一直有个声音告诉我，你只能走这条路，这才是你该有的结局。我的人生，我的理想，我没有理想......"
  },
  [111320387] = {
    id = 111320387,
    name = "没有理想，那就去寻找吧。"
  },
  [111320388] = {
    id = 111320388,
    name = "找......能找到吗？"
  },
  [111320389] = {
    id = 111320389,
    name = "当然可以，等到你找到自己想要的未来，你会发现成为骑士不是你人生的终点。你的前路无限宽广，那个时候，你也会有更多的选择，选择继续做骑士，还是为了新的人生理想而活。"
  },
  [111320390] = {
    id = 111320390,
    name = "白鸢不可思议地微微张开了唇，她的眼角微微弯了起来，泪比笑更先落了下来，就像震惊和困惑后，在思而不得之中，倏然间恍然大悟。"
  },
  [111320391] = {
    id = 111320391,
    name = "......原来......如此，我明白了。"
  },
  [111320392] = {
    id = 111320392,
    name = "原来我真的可以重新选择，是骑士荣誉，还是遥远的理想，都是我能选择的......我会用我的剑，在深渊里探索，问寻我未来的路。"
  },
  [111320393] = {
    id = 111320393,
    name = "白鸢冲你开心地笑了笑，你仿佛看见有什么枷锁在她眼中打破了，欣喜、感动而开怀。"
  },
  [111320394] = {
    id = 111320394,
    name = "谢谢你，让我如梦初醒。"
  },
  [111320395] = {
    id = 111320395,
    name = "呵呵，这个盒子，你打算怎么办？"
  },
  [111320396] = {
    id = 111320396,
    name = "我想把他带回家族的圈落，你......要把它送去公会吗？"
  },
  [111320397] = {
    id = 111320397,
    name = "你带回去吧，如果发现这个盒子不属于家族，你也最好通知公会的人。至于我嘛，还是会去一趟公会的，那个据点整体完好，废弃的话也十分可惜，如果能挽救的话，他们也不用搬走了。"
  },
  [111320398] = {
    id = 111320398,
    name = "......谢谢你。"
  },
  [111320399] = {
    id = 111320399,
    name = "好啦，感谢的话不用说两次，我收到了。"
  },
  [111320400] = {id = 111320400, name = "呵呵。"},
  [111320401] = {
    id = 111320401,
    name = "白鸢的眼里盈满了笑意，她走两步就转身回头看你一眼，最后朝你挥了挥手，消失在山林绿意中。"
  },
  [111320402] = {
    id = 111320402,
    name = "......接下来，还有一个小小的问题。"
  },
  [111320403] = {
    id = 111320403,
    name = "你重新回到了临时营地，远远地还能听到负责人的骂声。"
  },
  [111320404] = {
    id = 111320404,
    name = "看来那个盒子对他很重要啊。"
  },
  [111320405] = {
    id = 111320405,
    name = "你悄悄走到帐篷附近，趁负责人落单时，一掌打晕了他，拖到了不远处隐蔽的山脚处。"
  },
  [111320406] = {
    id = 111320406,
    name = "呜呜......"
  },
  [111320407] = {
    id = 111320407,
    name = "负责人苏醒了，感受到被绑缚的双手双脚，和遮住双眼的黑布，狰狞恐惧的脸妄图挣扎着想大喊，却被你用破布堵上了嘴。"
  },
  [111320408] = {
    id = 111320408,
    name = "呜呜......呜呜......"
  },
  [111320409] = {
    id = 111320409,
    name = "你没管他的叫唤，拿出了食物，生起了火堆，一边哼歌一边烤着，负责人闻到了食物的香气，挣扎得更厉害了。"
  },
  [111320410] = {
    id = 111320410,
    name = "安静点，不然一会儿拿你去喂魔物。"
  },
  [111320411] = {
    id = 111320411,
    name = "......嗝。"
  },
  [111320412] = {
    id = 111320412,
    name = "负责人安静了好一阵，等你吃饱喝足，他又开始挣扎了起来，你看他夹紧的双腿，大笑了一声，提着他的后颈让他站稳了。"
  },
  [111320413] = {
    id = 111320413,
    name = "你好好回答我的问题，我就放你去解决你的问题，怎么样？"
  },
  [111320414] = {
    id = 111320414,
    name = "唔唔唔！"
  },
  [111320415] = {
    id = 111320415,
    name = "如果你想尝试着喊救命，可以试试是救你的人先来，还是我的剑更快。"
  },
  [111320416] = {
    id = 111320416,
    name = "负责人狂点头，看起来已经快憋不住了，你扯掉了他嘴里的破布，在他大口地喘气的时候，慢悠悠地提问。"
  },
  [111320417] = {
    id = 111320417,
    name = "那个盒子你从哪里拿到的？别和我装傻，你知道我说的是什么。"
  },
  [111320418] = {
    id = 111320418,
    name = "负责人身体一僵，在长时间黑暗的恐惧与绝望中选择了回答。"
  },
  [111320419] = {
    id = 111320419,
    name = "是一个黑衣人，黑衣人寄放在这里的，我也不知道他是谁！"
  },
  [111320420] = {
    id = 111320420,
    name = "寄放？他有说里面是什么吗？"
  },
  [111320421] = {
    id = 111320421,
    name = "是宝物！他说那里面有宝物，还没净化的宝物，他说过几天会有人拿走它。可他放在我这里几个月了，一直没人来拿啊！"
  },
  [111320422] = {
    id = 111320422,
    name = "所以你就当无主之物自己打开了？"
  },
  [111320423] = {
    id = 111320423,
    name = "我没有！我怎么会擅自打开，是约翰尼！那个不听话的家伙，是他悄悄打开了那个盒子，害得我们整个据点遭殃！"
  },
  [111320424] = {
    id = 111320424,
    name = "呵呵，怕宝物没净化，专门找了个替死鬼，难怪听到堕落者的时候，你的表情一点也不意外啊。"
  },
  [111320425] = {
    id = 111320425,
    name = "对对，都是我的错，是我一时贪欲害了大家，阁下，你放了我......放了我吧......我要憋不住了......"
  },
  [111320426] = {
    id = 111320426,
    name = "没有打听到你想要的关键信息，你失望地摇了摇头，正打算放了他时，竟然听到了渍渍的水流声。"
  },
  [111320427] = {
    id = 111320427,
    name = "啊......啊......"
  },
  [111320428] = {
    id = 111320428,
    name = "真是丑陋啊。"
  },
  [111320429] = {
    id = 111320429,
    name = "你毫不留情地转身离开。身后负责人凄惨的嚎叫，还有临时营地里寻人的声音，都与你无关了。"
  },
  [111550001] = {
    id = 111550001,
    name = "唔！那边有人吗？快来帮帮我！"
  },
  [111550002] = {
    id = 111550002,
    name = "你听到求救的人声，靠近了见到了一个腿被藤蔓束缚的人，他正卯足劲挣扎，用匕首切割着藤蔓。"
  },
  [111550003] = {
    id = 111550003,
    name = "别动了，不然它会缠得更紧。"
  },
  [111550004] = {
    id = 111550004,
    name = "好好，你快来帮帮我！"
  },
  [111550005] = {
    id = 111550005,
    name = "路人听话地不动了，你挥剑轻巧地斩断了藤蔓，打量着这个背着篓筐的人。"
  },
  [111550006] = {
    id = 111550006,
    name = "怎么一个人出门？"
  },
  [111550007] = {
    id = 111550007,
    name = "这座山的魔物都被咱们据点的探险者杀光了，很安全，我经常来的。唉，今天是运气不好着了道，谢谢小哥啊。"
  },
  [111550008] = {
    id = 111550008,
    name = "不客气，不过你拿这些藤蔓做什么？"
  },
  [111550009] = {
    id = 111550009,
    name = "你指了指他篓筐里的东西。"
  },
  [111550010] = {
    id = 111550010,
    name = "你说这个草枯藤，这是我用来编织星星灯的。"
  },
  [111550011] = {
    id = 111550011,
    name = "星星灯，听起来挺有趣。"
  },
  [111550012] = {
    id = 111550012,
    name = "哈哈，在编好的灯里面扔几块萤石，它就能自己发光，我准备做一些在庆典上卖，每年就这个最好卖啦。"
  },
  [111550013] = {
    id = 111550013,
    name = "庆典？有据点在举办庆典吗？"
  },
  [111550014] = {
    id = 111550014,
    name = "小哥是第一次到咱们埃兰据点吧，我们每年都会举办一次祭祀，祈求埃兰安宁昌盛，托神的护佑，从祭祀仪式开始之后，埃兰的确没有魔物的侵扰了。"
  },
  [111550015] = {
    id = 111550015,
    name = "是嘛，庆典的话，一定很热闹了。"
  },
  [111550016] = {
    id = 111550016,
    name = "当然，附近的探险者和据点的人都会来参加，也就这个时候，我的生意才好做一些。"
  },
  [111550017] = {
    id = 111550017,
    name = "他在筐里摸索着，理出了一条细长的草枯藤递给你。"
  },
  [111550018] = {
    id = 111550018,
    name = "这是我搓好的草枯藤，可以直接编的，送给你。"
  },
  [111550019] = {
    id = 111550019,
    name = "不用了，我不会编。"
  },
  [111550020] = {
    id = 111550020,
    name = "很简单的，我教你！"
  },
  [111550021] = {
    id = 111550021,
    name = "路人重新拿出了一根草枯藤，藤条在他铺满茧子的掌心来回揉搓变得圆滑，拧着扭动的头部转出螺纹打了个结，接着把藤条举了起来。"
  },
  [111550022] = {
    id = 111550022,
    name = "来跟我一步步学，很快的。"
  },
  [111550023] = {id = 111550023, name = "......"},
  [111550024] = {
    id = 111550024,
    name = "你无法拒绝他的热情，照着他的手法打了结。"
  },
  [111550025] = {
    id = 111550025,
    name = "你真是太聪明了！接下来你也一定能做到！"
  },
  [111550026] = {
    id = 111550026,
    name = "一段时间后......"
  },
  [111550027] = {
    id = 111550027,
    name = "不好意思，我的眼睛会了，手还不会。"
  },
  [111550028] = {
    id = 111550028,
    name = "哈哈，没关系年轻人，你已经很棒了，就这样好好练习，一定能做出一盏星星灯的。"
  },
  [111550029] = {
    id = 111550029,
    name = "我走啦，你要有时间就来祭典玩吧。"
  },
  [111550030] = {
    id = 111550030,
    name = "路人没入了山林，你手中的藤条转来转去，仿佛有生命一般，又重新回到了最初的位置。"
  },
  [111550031] = {
    id = 111550031,
    name = "你无聊地摆弄着手中的藤条，回忆当时的手法，不知不觉走到了一处湖泊边。清浅薄雾，光影斑斓，你走近一步，看到了一个朦胧的身影。"
  },
  [111550032] = {id = 111550032, name = "......"},
  [111550033] = {
    id = 111550033,
    name = "少女的背影半沉在湖水里，素手徐徐掬起一捧清水，肌肤胜雪，纤腰柔弱，仿若星河之中纯粹而诱人的鬼魅。"
  },
  [111550034] = {
    id = 111550034,
    name = "（......我还是快些离开吧。）"
  },
  [111550035] = {
    id = 111550035,
    name = "你立刻转过身，捏了捏手里的藤条，平复了摇曳的心旌，悄然后退。"
  },
  [111550036] = {id = 111550036, name = "嗯？"},
  [111550037] = {
    id = 111550037,
    name = "少女似乎察觉到了什么，你停下了脚步，正在思考如何解释时，猛地感觉一道异样的风掠过。"
  },
  [111550038] = {
    id = 111550038,
    name = "鬼魅，你去死吧！"
  },
  [111550039] = {
    id = 111550039,
    name = "锋利的箭尖泛着冷光，从林中窜出，飞向湖中的人影。与此同时，你顺手打出了一击魔法，将迎风而去的箭矢搅碎了。"
  },
  [111550040] = {
    id = 111550040,
    name = "谁？谁敢拦我们！"
  },
  [111550041] = {id = 111550041, name = "......"},
  [111550042] = {
    id = 111550042,
    name = "你无奈地现身，偷袭少女的两个人此时也出现在了你的附近，你听到身后轻微的水声，并没有回头去看。"
  },
  [111550043] = {
    id = 111550043,
    name = "呵，鬼魅，没想到你还找了看门狗！"
  },
  [111550044] = {
    id = 111550044,
    name = "我去杀鬼魅，你干掉这条碍事的狗，没问题吧？！"
  },
  [111550045] = {
    id = 111550045,
    name = "当然，鬼魅，你这个蛊惑人心的女巫，就永远留在湖底吧！"
  },
  [111550046] = {
    id = 111550046,
    name = "等等，我可没同意你们的计划。"
  },
  [111550047] = {
    id = 111550047,
    name = "你什么意思？"
  },
  [111550048] = {
    id = 111550048,
    name = "第一，我不是狗，更不是看门狗，我只是碰巧路过了这里，本来打算走的，是你们认错了人。"
  },
  [111550049] = {
    id = 111550049,
    name = "听到你不是鬼魅的人，两人放松下来，露出阴狠的杀意。"
  },
  [111550050] = {
    id = 111550050,
    name = "第二，我讨厌偷袭，尤其是对正在洗澡的女人偷袭，那真是世界上最无耻的行径。"
  },
  [111550051] = {
    id = 111550051,
    name = "你！多管闲事，那你就一起去死吧！"
  },
  [111550052] = {
    id = 111550052,
    name = "探险者犹如猎豹般扑了过来，你收起藤条，单手出剑，准确无误地划开了他的手背。"
  },
  [111550053] = {
    id = 111550053,
    name = "啊啊啊！"
  },
  [111550054] = {
    id = 111550054,
    name = "好快......好快的剑！"
  },
  [111550055] = {
    id = 111550055,
    name = "两人震惊地望着你，眼中闪过一丝惊恐，同时退后了好几步。"
  },
  [111550056] = {
    id = 111550056,
    name = "鬼魅！这次算你走运，但你要敢在庆典上捣乱，就等着脑袋搬家吧！"
  },
  [111550057] = {
    id = 111550057,
    name = "虽是这么说着，两人的脚下却停也不停，奋力地逃得没了影。"
  },
  [111550058] = {id = 111550058, name = "呵呵。"},
  [111550059] = {
    id = 111550059,
    name = "身后传来了一声魅惑的笑声，那声笑似乎化作了钩子，痒在了耳朵，勾得人心微漾。"
  },
  [111550060] = {
    id = 111550060,
    name = "你转身，一道红雾笼罩了湖泊，逐渐围成了一个茧，将鬼魅完全包裹，红雾散去后，她缓缓地踏出水面走向了你。你很难见到这样的女性，优雅和艳丽并存，双眸既天真又魅惑。"
  },
  [111550061] = {
    id = 111550061,
    name = "谢谢你，为奴家解围。"
  },
  [111550062] = {
    id = 111550062,
    name = "......举手之劳。"
  },
  [111550063] = {
    id = 111550063,
    name = "鬼魅好奇地将你从头到脚一一端量，最后目光灼灼地盯着你的眼睛，你有些不自在，转身离开时候，她却拦下了你。"
  },
  [111550064] = {
    id = 111550064,
    name = "请留步。"
  },
  [111550065] = {
    id = 111550065,
    name = "还有什么事吗？"
  },
  [111550066] = {
    id = 111550066,
    name = "请留步。"
  },
  [111550067] = {
    id = 111550067,
    name = "她含着笑看你，你却并不觉得她真的在笑，她的笑像戴着她认为最美丽的一层面具。"
  },
  [111550068] = {
    id = 111550068,
    name = "帮人帮到底，你既然都救了奴家，就再帮奴家一个忙好不好？"
  },
  [111550069] = {
    id = 111550069,
    name = "为什么？"
  },
  [111550070] = {
    id = 111550070,
    name = "奴家都请你看了一场戏，你也陪奴家看一场戏吧？"
  },
  [111550071] = {
    id = 111550071,
    name = "你什么时候请我看的戏？"
  },
  [111550072] = {
    id = 111550072,
    name = "佳人出浴的戏不好看吗？"
  },
  [111550073] = {
    id = 111550073,
    name = "那个......是我唐突了，不过我什么也没看到。"
  },
  [111550074] = {
    id = 111550074,
    name = "奴家当然知道，你是个克己守礼的正人君子，否则奴家也不会邀请你继续看戏了。"
  },
  [111550075] = {
    id = 111550075,
    name = "看什么戏，难道和那两个人有关？"
  },
  [111550076] = {
    id = 111550076,
    name = "呵呵，跳梁小丑，不过尔尔。奴家邀请你看的，是更加盛大的庆典。"
  },
  [111550077] = {
    id = 111550077,
    name = "（庆典？刚才那两个人说她打算在庆典上捣乱，这个鬼魅到底有什么目的？）"
  },
  [111550078] = {
    id = 111550078,
    name = "只是目前，奴家遇到了一些难处，需要一个人帮忙，你好人做到底，帮帮奴家，奴家会好好......感谢你的。"
  },
  [111550079] = {
    id = 111550079,
    name = "她将语气揉得匀称玲珑，有意无意间的缱绻让你心生防备。"
  },
  [111550080] = {
    id = 111550080,
    name = "......好。但你要做出违背道义的事，也别怪我不客气。"
  },
  [111550081] = {
    id = 111550081,
    name = "呵呵，既是同行，那奴家就将所有的防护交给你了。"
  },
  [111550082] = {
    id = 111550082,
    name = "她脚步翩跹，轻巧地与你擦肩而过。"
  },
  [111550083] = {
    id = 111550083,
    name = "鬼魅带你越过了附近的山，在一处林子里停了下来。"
  },
  [111550084] = {
    id = 111550084,
    name = "（走了这么久的山路不急不喘，她果然不是一般的探险者。）"
  },
  [111550085] = {
    id = 111550085,
    name = "嗯？你手里在编什么？"
  },
  [111550086] = {
    id = 111550086,
    name = "一个小玩意儿，不重要。"
  },
  [111550087] = {
    id = 111550087,
    name = "你收起编得稍有头绪的藤条，放眼朝林间望了过去。"
  },
  [111550088] = {
    id = 111550088,
    name = "你是要让我帮忙除掉魔物？"
  },
  [111550089] = {
    id = 111550089,
    name = "没错，这里的魔物困扰奴家好久了，奴家一直想采集一些驱散魔物的药草，却对看守的那只巨型魔物无计可施。"
  },
  [111550090] = {
    id = 111550090,
    name = "只是这样？"
  },
  [111550091] = {
    id = 111550091,
    name = "呵呵，你希望不只是这样？或者还对奴家抱有怎样的期待？"
  },
  [111550092] = {id = 111550092, name = "......"},
  [111550093] = {
    id = 111550093,
    name = "你适宜地闭上了嘴，安静地跟她潜入了雾霭沉寂的山林间。一段时间后，你见到了那只沉睡的魔物。"
  },
  [111550094] = {
    id = 111550094,
    name = "鬼魅驾轻就熟地走到了一棵大树后，纤纤手指朝你招了招，你敛声匿迹，靠近了她身边。"
  },
  [111550095] = {
    id = 111550095,
    name = "（小声）就是它了，一会儿我用魔法限制它的行动，斩杀就交给你啦~"
  },
  [111550096] = {
    id = 111550096,
    name = "你衡量了一下魔物的实力，在有了对策后，缓缓出剑，靠近了魔物，而此时鬼魅手指舞动，一道金光闪现，向魔物狠狠砸了过去！"
  },
  [111550097] = {
    id = 111550097,
    name = "吼！！！"
  },
  [111550098] = {
    id = 111550098,
    name = "喂，你怎么突然——"
  },
  [111550099] = {
    id = 111550099,
    name = "你猝不及防地躲掉了魔物应激的反应，来不及说话，和魔物缠斗起来。"
  },
  [111550100] = {
    id = 111550100,
    name = "抱歉啊，奴家只是想先下手为强呢~"
  },
  [111550101] = {
    id = 111550101,
    name = "一道光线自她的法杖破空而出，像有生命般交横勾连，盘结环绕在魔物身边，而后猛然束紧！"
  },
  [111550102] = {
    id = 111550102,
    name = "你看准机会，长剑刺入弱点一击即中，魔物发出痛苦的嘶吼，越是挣扎，丝线束缚得越紧，而后丝线猛烈灼烧，火焰点燃了它最后的生命力，直到泯没。"
  },
  [111550103] = {
    id = 111550103,
    name = "你果然是难得一见的强者，奴家没有看错人呢，第一次就和奴家配合得天衣无缝。"
  },
  [111550104] = {
    id = 111550104,
    name = "好了，快去采集驱魔草吧。"
  },
  [111550105] = {
    id = 111550105,
    name = "鬼魅嫣然一笑，走向魔物看守的区域，而此时一个更快的身影冲了出来，极快地摘下了那株最大的驱魔草。"
  },
  [111550106] = {
    id = 111550106,
    name = "哈哈哈，我抢到了！我抢到了！原来是你，鬼魅魔女，你休想得逞！"
  },
  [111550107] = {
    id = 111550107,
    name = "得逞的人，难道不是你吗？"
  },
  [111550108] = {
    id = 111550108,
    name = "背着药筐的男人凶狠地瞪着她，忽然憋红了脸。"
  },
  [111550109] = {
    id = 111550109,
    name = "别以为你杀了魔物，我就会把驱魔草还给你，你想害我们埃兰据点的事，我们都知道了！"
  },
  [111550110] = {
    id = 111550110,
    name = "哦？我要怎么害你们埃兰据点？"
  },
  [111550111] = {
    id = 111550111,
    name = "哼，祭司大人说他收到了你的恐吓信，你想我们取消祭祀，停止庆典，否则据点就会大难临头。"
  },
  [111550112] = {
    id = 111550112,
    name = "这个啊，我确实写过这么一封信，还有呢？"
  },
  [111550113] = {
    id = 111550113,
    name = "你，你竟然承认了，真是不要脸！你今天来采驱魔草，一定是想让我们没有驱魔草可以用，我告诉你，我，我的朋友就在山下接应我，你要是识趣就把驱魔草让出来，否则，否则......"
  },
  [111550114] = {
    id = 111550114,
    name = "鬼魅轻笑了一声，不以为意地走向那片长满药草的区域。"
  },
  [111550115] = {
    id = 111550115,
    name = "否则怎么样？哦对了，你的朋友，怎么没上来帮你杀掉魔物呢？"
  },
  [111550116] = {
    id = 111550116,
    name = "你这个魔女，你给我等着，我这就去叫人！"
  },
  [111550117] = {
    id = 111550117,
    name = "好啊，我会在此恭候的。"
  },
  [111550118] = {
    id = 111550118,
    name = "......你你你又想耍什么花招，想连我的朋友一起杀人灭口吗，我才不会回来上你的当！"
  },
  [111550119] = {
    id = 111550119,
    name = "采药人一边退后，一边顺手拔了好几株驱魔草，朝山下飞奔而去了。"
  },
  [111550120] = {
    id = 111550120,
    name = "呵呵......"
  },
  [111550121] = {
    id = 111550121,
    name = "鬼魅看着他连滚带爬的样子，捂嘴笑得花枝颤动，她湿漉漉的眼睛看向了一脸镇定的你。"
  },
  [111550122] = {
    id = 111550122,
    name = "又是一个自说自洽的活现眼，你不觉得很好笑吗？"
  },
  [111550123] = {
    id = 111550123,
    name = "你真的给据点送了一封恐吓信？"
  },
  [111550124] = {
    id = 111550124,
    name = "哦？你真的认为奴家给据点送的是恐吓信？"
  },
  [111550125] = {
    id = 111550125,
    name = "没有人会无缘无故对这个据点恐吓。"
  },
  [111550126] = {
    id = 111550126,
    name = "呵呵，也许奴家就是想看一场好戏呢？"
  },
  [111550127] = {
    id = 111550127,
    name = "你似笑非笑地看着她，并不相信这件事会这么简单。"
  },
  [111550128] = {
    id = 111550128,
    name = "那对你来说，什么才是好戏？"
  },
  [111550129] = {
    id = 111550129,
    name = "鬼魅被问得沉默了一瞬，随即又娇媚地眨了眨眼睛。"
  },
  [111550130] = {
    id = 111550130,
    name = "呵呵，你和别人不太一样。先采完驱魔草吧，之后奴家再告诉你。"
  },
  [111550131] = {
    id = 111550131,
    name = "这里，可以看得很清楚啊。"
  },
  [111550132] = {
    id = 111550132,
    name = "采集药草后，你们从山的另一头下来，恰好走到一片坡地上，能看清远处原野上被围墙合抱的大小屋脊。"
  },
  [111550133] = {
    id = 111550133,
    name = "那里就是埃兰据点？"
  },
  [111550134] = {
    id = 111550134,
    name = "是啊，是不是很热闹？每年到了祭祀的那天，会更热闹。"
  },
  [111550135] = {
    id = 111550135,
    name = "宽阔的原野四面，到处有零零散散正在赶往埃兰据点的探险者，宛如蚂蚁统一地挪向巢穴。"
  },
  [111550136] = {
    id = 111550136,
    name = "还有两天，他们就会点燃篝火，放飞纸灯，聆听祭司的祈祷、探险者的喝彩......还有祭品的悲鸣......"
  },
  [111550137] = {id = 111550137, name = "祭品？"},
  [111550138] = {
    id = 111550138,
    name = "对，每年祭祀，高高在上的祭司就会向所谓的神石献上纯洁的少女，以护佑据点平安的名义。"
  },
  [111550139] = {
    id = 111550139,
    name = "人祭？那，那些少女......"
  },
  [111550140] = {
    id = 111550140,
    name = "都是还未成人就被神石吞噬，早早夭亡了。"
  },
  [111550141] = {
    id = 111550141,
    name = "这算什么神石？！"
  },
  [111550142] = {
    id = 111550142,
    name = "呵呵，你别激动，要是你知道那石头里其实藏了，不对，是封印了一只魔物，是不是会更有趣呢？"
  },
  [111550143] = {
    id = 111550143,
    name = "......如果没有祭品，会怎么样？"
  },
  [111550144] = {
    id = 111550144,
    name = "谁知道呢，也许魔物就会挣脱封印，跑出来吃掉据点的其他人吧。"
  },
  [111550145] = {id = 111550145, name = "......"},
  [111550146] = {
    id = 111550146,
    name = "看着鬼魅满不在乎地微笑，你忽然窥到了真相的一部分，也剥开了她试图遮掩的心绪。"
  },
  [111550147] = {
    id = 111550147,
    name = "你想救无辜的女孩，才给他们发预告信？不对，这并不能阻止他们疯狂的祭祀，难道......"
  },
  [111550148] = {
    id = 111550148,
    name = "没错，你真的和别人不一样。奴家想的，的确是一劳永逸。"
  },
  [111550149] = {
    id = 111550149,
    name = "你想放出石头里的魔物，再彻底毁掉所谓的神石？"
  },
  [111550150] = {
    id = 111550150,
    name = "呵呵呵呵，跟你在一起，总是让人觉得很轻松，你比那些愚昧凡俗的家伙睿哲太多了。"
  },
  [111550151] = {
    id = 111550151,
    name = "那你为什么不解释？任由他们败坏你的名声？"
  },
  [111550152] = {
    id = 111550152,
    name = "奴家哪里还有名声？"
  },
  [111550153] = {
    id = 111550153,
    name = "她拿出了一张红心Q的扑克牌，抛上天的瞬间变成了一朵绚烂的玫瑰，轻嗅芬芳后，又眨眼消失了。"
  },
  [111550154] = {
    id = 111550154,
    name = "（鬼牌？）"
  },
  [111550155] = {
    id = 111550155,
    name = "你忽然想起曾经在深渊的酒馆里听说过这个组织，除了它的神秘，你一无所知。"
  },
  [111550156] = {
    id = 111550156,
    name = "呵呵，发什么呆呢，接下来可是至关重要的一场戏哦~"
  },
  [111550157] = {
    id = 111550157,
    name = "你回过神，有些担忧无辜者的安危。"
  },
  [111550158] = {
    id = 111550158,
    name = "如果在祭祀当日放出魔物，那在场的群众一定会有危险。"
  },
  [111550159] = {
    id = 111550159,
    name = "是啊，奴家对魔物吃人的戏码不感兴趣，所以才寄了一封信过去，可惜呢，他们一点也不领情，奴家只能用另外一个办法啦~"
  },
  [111550160] = {
    id = 111550160,
    name = "你猜猜看，奴家会怎么做呢？"
  },
  [111550161] = {
    id = 111550161,
    name = "在仪式开始时放魔物现身；或者救下小女孩，以自身诱杀魔物......都不是你会做的事。"
  },
  [111550162] = {
    id = 111550162,
    name = "呵呵，你还挺了解奴家的。"
  },
  [111550163] = {
    id = 111550163,
    name = "所以，你在得到他们否决的回复后，打算在祭祀开始前就解决这件事，是吗？"
  },
  [111550164] = {
    id = 111550164,
    name = "你真聪明。奴家打算找到神石，在祭祀开始前将宝物借出来，好好地和魔物交流交流。"
  },
  [111550165] = {
    id = 111550165,
    name = "可是，奴家现在成了人人喊打的过街老鼠，不便露面了。这件事，你会帮我的，对吗？"
  },
  [111550166] = {
    id = 111550166,
    name = "......不需要用这种语气和我说话。"
  },
  [111550167] = {
    id = 111550167,
    name = "在你说出这句话时，鬼魅柔媚无骨的神态忽然间定格了。转眼间，她的眉眼舒缓，变得优雅高傲。"
  },
  [111550168] = {
    id = 111550168,
    name = "那打听神石线索的事，就拜托你了。"
  },
  [111550169] = {
    id = 111550169,
    name = "你确保不会被发现？这难道不会更加引人注目吗？"
  },
  [111550170] = {
    id = 111550170,
    name = "放心吧，他们蠢蠢的，什么都不会看出来。"
  },
  [111550171] = {
    id = 111550171,
    name = "鬼魅只蒙了一层面纱，适情率意地和你走在埃兰据点的街道上，虽有不少人频频回目，但都对你露出了羡慕又嫉妒的光。"
  },
  [111550172] = {
    id = 111550172,
    name = "你看，他们总是这么肤浅，认为奴家是你的女伴，来专程参加庆典的呢。"
  },
  [111550173] = {
    id = 111550173,
    name = "......这样真的能打探到神石的线索？"
  },
  [111550174] = {
    id = 111550174,
    name = "你有些头疼，鬼魅用指尖点了点眉边，看起来比你更苦恼的样子，尽管你知道她表现出的仅是面具上的假象。"
  },
  [111550175] = {
    id = 111550175,
    name = "......你知道那两个去杀鬼魅的家伙吗，他们失踪了！"
  },
  [111550176] = {
    id = 111550176,
    name = "失踪？！不、不会被鬼魅干掉了吧！"
  },
  [111550177] = {
    id = 111550177,
    name = "哼，那个狠毒的女人，什么做不出来？！前年引诱了一堆魔物到据点周围，幸好祭司英明防了一手，才没让她得逞，去年她又炸了祭台，还让她险些救走了祭品，真是罪无可恕！"
  },
  [111550178] = {
    id = 111550178,
    name = "这个可恶的女人，为什么总想破坏我们的庆典？"
  },
  [111550179] = {
    id = 111550179,
    name = "呵，坏就是坏，能有什么原因，这个深渊要是每个人都那么善良，也不会有那么多惨事发生了。"
  },
  [111550180] = {
    id = 111550180,
    name = "你说得没错，这一次鬼魅又来了，不知道她又会耍什么手段......"
  },
  [111550181] = {
    id = 111550181,
    name = "有祭司在怕什么，他早就知道那两个刺杀的没用，已经设好陷阱等她了！"
  },
  [111550182] = {
    id = 111550182,
    name = "那就好，就让祭司惩戒她，最好能像教廷对付女巫一样，只有烧死才不会有邪恶的怨灵出现！"
  },
  [111550183] = {
    id = 111550183,
    name = "两人说着话一前一后地和你们擦肩而过，鬼魅饶有兴趣地听着，仿佛在听别人的故事。"
  },
  [111550184] = {
    id = 111550184,
    name = "那个女人原来这么坏啊~"
  },
  [111550185] = {
    id = 111550185,
    name = "当然了，诶，这位小姐是外面来参加庆典的吗？那你可要小心了，听说那鬼魅最恨别的女人比她长得好看了！会先毁容再杀掉的！"
  },
  [111550186] = {
    id = 111550186,
    name = "鬼魅像被吓到一般，朝你靠近了一些，仰头颤声对你说话。"
  },
  [111550187] = {
    id = 111550187,
    name = "那你要好好保护我啊~"
  },
  [111550188] = {
    id = 111550188,
    name = "你听得耳朵发麻，正打算说些什么时，那两人见她小鸟依人的模样，自打没趣走了。"
  },
  [111550189] = {
    id = 111550189,
    name = "......你去年炸了祭台？"
  },
  [111550190] = {
    id = 111550190,
    name = "只是小小地放了一把火而已。可惜啊，那些火能将庆典的祭台烧成灰烬，却无法焚尽人心的欲望。"
  },
  [111550191] = {id = 111550191, name = "......"},
  [111550192] = {
    id = 111550192,
    name = "唉，你带着奴家的确不方便，那奴家就勉为其难不和你一起了。我们比比看，你我一明一暗，谁更先找到神石的线索吧？"
  },
  [111550193] = {
    id = 111550193,
    name = "鬼魅眼眸一转，眉眼一弯，优雅地离去了。"
  },
  [111550194] = {
    id = 111550194,
    name = "突然走得那么快，难道是有眉目了？那我也去探查一下吧，该从哪儿查起呢？"
  },
  [111550195] = {
    id = 111550195,
    name = "你思考了一阵，决定先在这里找到公会成员，也许他们可以提供更多的线索。可你绕着据点走了两圈，也没有看到公会留下的任何痕迹。"
  },
  [111550196] = {
    id = 111550196,
    name = "请问，这里公会的商社在哪儿啊？"
  },
  [111550197] = {
    id = 111550197,
    name = "公会？埃兰据点可没有公会的人。"
  },
  [111550198] = {
    id = 111550198,
    name = "（没有？据点里的人不少，还有相应的庆典，公会怎么会放弃？）"
  },
  [111550199] = {
    id = 111550199,
    name = "你是来参加庆典的吧，要补充物资直接去酒馆，或者等明天庆典开始了，去集贸广场更热闹。"
  },
  [111550200] = {
    id = 111550200,
    name = "啊不，我是来找人的，是一个公会的人，他也来参加庆典。"
  },
  [111550201] = {
    id = 111550201,
    name = "我就说嘛，上次他们的商会想入驻，还好祭司大人拒绝了，否则哪里轮得到我们这些普通探险者赚钱。"
  },
  [111550202] = {
    id = 111550202,
    name = "祭司大人？他是这里的管理者吗？"
  },
  [111550203] = {
    id = 111550203,
    name = "大人虽然不是管理者，可比管理者还受人尊敬的。"
  },
  [111550204] = {
    id = 111550204,
    name = "你见鬼魅已没入了人群中，也打算随便走走，先探听一下整个埃兰的据点的情况。"
  },
  [111550205] = {
    id = 111550205,
    name = "客人想买点什么？"
  },
  [111550206] = {
    id = 111550206,
    name = "听说这几天这里有庆典，我是专门过来参加的，真的很热闹啊。"
  },
  [111550207] = {
    id = 111550207,
    name = "当然了，这是我们一年一度的盛会，每年我们伟大的祭司大人都会主持祭祀典礼，护佑埃兰安定昌盛呢。"
  },
  [111550208] = {
    id = 111550208,
    name = "祭司大人？哪里可以拜会祭司大人呢？"
  },
  [111550209] = {
    id = 111550209,
    name = "大人平时不喜欢被打扰，庆典就在明天，你自然就能看到啦。"
  },
  [111550210] = {
    id = 111550210,
    name = "见暂时问不出什么线索，你继续在路上无目的地走了半晌，在一片广场处看到一排栅栏，门口守着几个探险者，没多久一群人又是抬又是扛的，架着长长的木桩，往里面走了进去。"
  },
  [111550211] = {
    id = 111550211,
    name = "他们在做什么？"
  },
  [111550212] = {
    id = 111550212,
    name = "搭祭台啊，去年的祭坛被该死的魔女给炸了，不过“希望女神”保佑，终于在祭祀之前找到了搭建祭台的木桩。"
  },
  [111550213] = {
    id = 111550213,
    name = "......嗯。祭台是什么？"
  },
  [111550214] = {
    id = 111550214,
    name = "你连祭台都不知道，是第一次来吧？祭台就是向神石献祭祭品的地方。"
  },
  [111550215] = {
    id = 111550215,
    name = "祭品？我听他们说祭品是女孩子，真的吗？"
  },
  [111550216] = {
    id = 111550216,
    name = "对啊，只要将祭品献祭，整一年埃兰据点都能获得祥和安宁的日子。"
  },
  [111550217] = {
    id = 111550217,
    name = "可那是一条人命......"
  },
  [111550218] = {
    id = 111550218,
    name = "能为整个据点牺牲，是作为祭品的荣幸，她的父母也会获得无上的殊荣和物质补偿，还有什么不满意的？"
  },
  [111550219] = {id = 111550219, name = "......"},
  [111550220] = {
    id = 111550220,
    name = "你就好好欣赏欣赏我们的庆典吧，这在别的据点可看不见。"
  },
  [111550221] = {
    id = 111550221,
    name = "不过我听说你们收到了一封警告信......"
  },
  [111550222] = {
    id = 111550222,
    name = "什么警告，那明明是恐吓！该死的魔女，明天她要是敢来破坏庆典，就是和我们据点的所有人作对，到时候定叫她有来无回！"
  },
  [111550223] = {
    id = 111550223,
    name = "这件事你就别担忧了，有祭司大人在，她的阴谋不会得逞的。"
  },
  [111550224] = {
    id = 111550224,
    name = "（又是祭司大人......）"
  },
  [111550225] = {
    id = 111550225,
    name = "你的目光放投往祭台，神石会不会也在附近呢......思考时，身边传来了一声轻笑。"
  },
  [111550226] = {
    id = 111550226,
    name = "呵呵，你找到线索了？"
  },
  [111550227] = {
    id = 111550227,
    name = "没完全打听到，倒是听到他们因为前几次你的破坏，会更加严密地提防你。"
  },
  [111550228] = {
    id = 111550228,
    name = "那些都是奴家为他们布置的舞台，可惜都是一场场闹剧，令人扫兴。你一直在看着那边，神石在那里？"
  },
  [111550229] = {
    id = 111550229,
    name = "也只是猜测而已，通常情况下最令人尊敬的人，住的地方应该不差。"
  },
  [111550230] = {
    id = 111550230,
    name = "你指向广场背后那一间鲜花环绕的高阁，不用猜测就知道是祭司的居所。"
  },
  [111550231] = {
    id = 111550231,
    name = "这个给你。"
  },
  [111550232] = {
    id = 111550232,
    name = "鬼魅忽然拉住你的手，在你的手心里放了一枚圆溜溜的魔法弹，弹珠在手心里滚来滚去，你感到一阵酥麻。"
  },
  [111550233] = {id = 111550233, name = "这是？"},
  [111550234] = {
    id = 111550234,
    name = "只要扔出去，他们就会像无头的苍蝇乱窜，这样奴家就有机会进去拿取神石了。"
  },
  [111550235] = {
    id = 111550235,
    name = "......要我引开他们？其实你出面承认自己是鬼魅，再由我潜入盗取神石，这样成功的几率也许更大一些。"
  },
  [111550236] = {
    id = 111550236,
    name = "唉，奴家这样做，也是不得已啊，你并不认识神石的模样，万一拿错了，引起他们的注意，想要再成功就难了......"
  },
  [111550237] = {
    id = 111550237,
    name = "鬼魅似嗔似怪，将你的手指翻进手心里，轻轻拍了拍。"
  },
  [111550238] = {
    id = 111550238,
    name = "拜托了。"
  },
  [111550239] = {
    id = 111550239,
    name = "......你说得有道理。"
  },
  [111550240] = {
    id = 111550240,
    name = "见你点头后，她掩唇在面纱后闷笑了两声翩翩而去。等她藏好后，你走到那一群看守附近，将手中的魔法弹扔了出去。"
  },
  [111550241] = {
    id = 111550241,
    name = "轰！！！一声如烟花般地炸响，五彩斑斓的火焰在地面窜出，惊动了周围的路人和守卫，他们张着嘴注视了一阵，警惕着靠拢，突然火焰迸出了第二道炸响！"
  },
  [111550242] = {
    id = 111550242,
    name = "哗啦啦！！！焰火绽放的形状流畅而完美，落下的烟尘飘洒在地面，宛如一幅优雅的艺术品，铺呈着红心Q的图案。"
  },
  [111550243] = {id = 111550243, name = "......"},
  [111550244] = {
    id = 111550244,
    name = "是鬼魅！鬼魅来了！！！"
  },
  [111550245] = {
    id = 111550245,
    name = "不知是谁在人群中喊了一句，守卫开始慌乱起来，真如鬼魅预言的那样——像无头的苍蝇乱窜，守卫们如临大敌。"
  },
  [111550246] = {
    id = 111550246,
    name = "“有人偷走了神石！！”"
  },
  [111550247] = {
    id = 111550247,
    name = "又有人高叫了一声，人们在一圈震耳欲聋的喊叫声中瞎碰乱撞，踩乱了地上的图案，掀起漫天的灰土，纷纷攘攘地混洒在尘埃里。"
  },
  [111550248] = {
    id = 111550248,
    name = "鬼魅从这边逃走了！！"
  },
  [111550249] = {
    id = 111550249,
    name = "人群一阵寂静，爆发出更大的混乱，你趁机挤了出去，奔赴据点门口，恰好看到好几个守卫拦下了她。"
  },
  [111550250] = {
    id = 111550250,
    name = "你来得真及时啊~"
  },
  [111550251] = {
    id = 111550251,
    name = "呼，这就是你的声东击西？"
  },
  [111550252] = {
    id = 111550252,
    name = "不，这是盛大的出场方式。"
  },
  [111550253] = {
    id = 111550253,
    name = "鬼魅盈盈一笑，高举起赤焰般的法杖，几道金光朝守卫奔涌而去，那群守卫躲得狼狈逃窜。"
  },
  [111550254] = {
    id = 111550254,
    name = "快走，后面的追来了。"
  },
  [111550255] = {
    id = 111550255,
    name = "你掩护鬼魅加快撤离出了据点。"
  },
  [111550256] = {
    id = 111550256,
    name = "终于甩掉了那些守卫。"
  },
  [111550257] = {
    id = 111550257,
    name = "唔......这个石头，就是他们每年拜祭的宝物啊......"
  },
  [111550258] = {
    id = 111550258,
    name = "鬼魅摩挲着手里的石头，银白的，四四方方的石头如同璀璨的玻璃魔盒，熠熠夺目。"
  },
  [111550259] = {
    id = 111550259,
    name = "这里面封印着魔物？"
  },
  [111550260] = {
    id = 111550260,
    name = "嗯，这块石头用祭品的血肉作为封印魔物的能量。而有了这个魔物在这里，许多低级魔物也不敢靠近埃兰据点，所以他们才那么坚定不移地支持祭司的决定，甚至成为了每年整个据点欢庆的盛典。"
  },
  [111550261] = {
    id = 111550261,
    name = "建立在无辜女孩生命之上的祥和安宁......"
  },
  [111550262] = {
    id = 111550262,
    name = "呵呵呵呵，无辜的女人，深渊的魔物，这两者最不可思议的结合......也许等神石消失的时候，他们才会想起，自己是被什么保护着。"
  },
  [111550263] = {
    id = 111550263,
    name = "一场场滑稽又荒谬绝伦的闹剧......等明天也该结束了。你站远一些，我准备解开封印了。"
  },
  [111550264] = {
    id = 111550264,
    name = "请多小心。"
  },
  [111550265] = {
    id = 111550265,
    name = "你第一次看见她露出了慎重的神情，退避在附近把守。鬼魅将“神石”往空中一抛，一道魔法飞射而去！"
  },
  [111550266] = {
    id = 111550266,
    name = "你目不转睛地看着那块石头，在破碎的瞬间，一股迷雾般的烟雾从碎片中涌出，烟雾缭绕在鬼魅周围，而鬼魅的目光却迟迟变得迷惘，仿佛陷入了混沌。"
  },
  [111550267] = {
    id = 111550267,
    name = "鬼魅小姐？"
  },
  [111550268] = {
    id = 111550268,
    name = "至此魔物也没出现，你心中有不好的预感，只见鬼魅眼一闭，竟然在原地倒下，你毫无迟疑地冲了出去，闻到一股令人陶醉的甜香味。"
  },
  [111550269] = {
    id = 111550269,
    name = "是迷药！鬼魅小姐！"
  },
  [111550270] = {
    id = 111550270,
    name = "你迅速将鬼魅抱离原地，正给她喂了一口水，听见了身后杂乱无章的脚步声。"
  },
  [111550271] = {
    id = 111550271,
    name = "祭司大人！她果然上当了！"
  },
  [111550272] = {
    id = 111550272,
    name = "你回头看，一群守卫簇拥着祭司上前将你们团团围住，那祭司身着洁白的长袍，面容庄重，露出悲悯的表情，声音肃穆。"
  },
  [111550273] = {
    id = 111550273,
    name = "魔女鬼魅，扰乱祭祀，罪该当诛。"
  },
  [111550274] = {
    id = 111550274,
    name = "当诛！当诛！当诛！"
  },
  [111550275] = {
    id = 111550275,
    name = "唔......呵呵。"
  },
  [111550276] = {
    id = 111550276,
    name = "鬼魅转醒后，无力地躺在你怀里，讥讽地笑出了声。"
  },
  [111550277] = {
    id = 111550277,
    name = "鬼魅，你一而再，再而三地破坏祭祀，置埃兰民众生死不顾，已是触及了每个埃兰人的底线。而今，你还造谣惑众，鼓动探险者危害埃兰据点，为了埃兰的安宁，你不得不死。"
  },
  [111550278] = {
    id = 111550278,
    name = "至于这位探险者，你误信鬼魅传言，便将你驱逐出埃兰，永远不得进入！"
  },
  [111550279] = {
    id = 111550279,
    name = "祭司大人仁慈！祭司大人仁慈！"
  },
  [111550280] = {
    id = 111550280,
    name = "鬼魅对祭司的话置若罔闻，反而对你柔婉一笑。"
  },
  [111550281] = {
    id = 111550281,
    name = "这次是我疏忽大意了，竟然真的中了圈套......你走吧，他们打算放过你呢。"
  },
  [111550282] = {id = 111550282, name = "......"},
  [111550283] = {
    id = 111550283,
    name = "呵呵，你在担心奴家吗？放心吧，就凭他们想杀了鬼魅......还没那个本事。"
  },
  [111550284] = {
    id = 111550284,
    name = "等等，这位祭司大人，鬼魅只是好心提醒你们，神石里真的有魔物，那就是一个不受控制的危机，哪一天魔物挣脱封印，据点必然——"
  },
  [111550285] = {
    id = 111550285,
    name = "呸！这是魔女的谣言，神石就是神石！是祭司大人神殿祈祷来的！魔女想煽动我们毁了神石，祭司大人再宽宏大量，也不会饶恕她！"
  },
  [111550286] = {
    id = 111550286,
    name = "你看着守卫愤愤不平的脸色，毫无撒谎的迹象，猜想祭司连这些守卫一起骗了。"
  },
  [111550287] = {
    id = 111550287,
    name = "其实有没有魔物，祭司大人把真正的神石封印打开一看不就知道了？"
  },
  [111550288] = {
    id = 111550288,
    name = "大言不惭！竟敢亵渎神物！理应同诛！！"
  },
  [111550289] = {
    id = 111550289,
    name = "呵呵，你呀。不过奴家就喜欢你多管闲事，还有他们丑态百出，原形毕露的模样......"
  },
  [111550290] = {
    id = 111550290,
    name = "鬼魅稍稍缓了过来，她站起身，依旧将重量放在了你身上，柔若无骨。"
  },
  [111550291] = {
    id = 111550291,
    name = "与此同时，守卫们已经攻了上来，你拉着鬼魅躲开了一人的袭击，而后用力地一脚踢中另一人的胸口。"
  },
  [111550292] = {
    id = 111550292,
    name = "你还真是心善呢。"
  },
  [111550293] = {
    id = 111550293,
    name = "见你不动用武器，鬼魅伏在你的肩上，用魔法击退了从背后袭击你的人，那人愣了愣，发现自己没怎么受伤，又冲了上来。"
  },
  [111550294] = {
    id = 111550294,
    name = "不过看来他们并不领情啊~"
  },
  [111550295] = {
    id = 111550295,
    name = "你感受到鬼魅的虚弱无力，迷药对她造成了很大的影响，必须尽快脱险才行。"
  },
  [111550296] = {
    id = 111550296,
    name = "看看这些是什么？"
  },
  [111550297] = {
    id = 111550297,
    name = "你拿出一袋亮晃晃的欧泊，猛地洒向了空中！"
  },
  [111550298] = {
    id = 111550298,
    name = "是......欧泊！欧泊啊！"
  },
  [111550299] = {
    id = 111550299,
    name = "一颗颗欧泊在空中划过优雅的弧线，如彩色的雨，剔透流转，闪烁着令人陶醉的光辉，守卫们被这突如其来的一招怔住，随即纷纷仰望，视线随着欧泊落在地上，沉醉在追逐拾掇欧泊的狂喜之中。"
  },
  [111550300] = {
    id = 111550300,
    name = "废物，一群废物！"
  },
  [111550301] = {
    id = 111550301,
    name = "等他们反应过来时，你早已带着鬼魅扬长而去。"
  },
  [111550302] = {
    id = 111550302,
    name = "这里应该安全了。"
  },
  [111550303] = {
    id = 111550303,
    name = "你扶着半昏迷的鬼魅在湖边靠树而坐，又喂了一些缓解的草药，无聊之时，你拿出了没编完的藤条继续编织着，没多久她的双眼逐渐睁开，恢复了神采。"
  },
  [111550304] = {
    id = 111550304,
    name = "他们呢？"
  },
  [111550305] = {
    id = 111550305,
    name = "都甩掉了，这片湖泊附近有魔物出没的痕迹，他们不敢随便追来。"
  },
  [111550306] = {
    id = 111550306,
    name = "呵呵呵......魔物的存在，竟然比人还令人心安吗？"
  },
  [111550307] = {
    id = 111550307,
    name = "鬼魅慢慢站起身来，朝你笑了笑，你感受到这份笑意里并不是那样的开心，她仍旧戴着那副美丽的假面。"
  },
  [111550308] = {
    id = 111550308,
    name = "他们不会善罢甘休的。为了避免他们无止境地追杀，你还是走吧。"
  },
  [111550309] = {
    id = 111550309,
    name = "你不想阻止祭祀了？"
  },
  [111550310] = {
    id = 111550310,
    name = "那个家伙扮祭司扮得太久了，演得入戏了，都忘记自己原本只是小丑，他还没有出丑，戏还没结束呢。"
  },
  [111550311] = {
    id = 111550311,
    name = "那你还赶我走？不想我跟你一起看完这场戏？"
  },
  [111550312] = {
    id = 111550312,
    name = "呵呵，好吧，你要是喜欢，就留下来和我一起看戏......"
  },
  [111550313] = {
    id = 111550313,
    name = "却之不恭。"
  },
  [111550314] = {
    id = 111550314,
    name = "鬼魅的唇微微一抿，浮出点儿笑意，如红纱薄雾，很快收敛了起来。"
  },
  [111550315] = {
    id = 111550315,
    name = "谢谢你。"
  },
  [111550316] = {
    id = 111550316,
    name = "你听出她话中认真的感激之意，很快把心思转到了祭祀上。"
  },
  [111550317] = {
    id = 111550317,
    name = "被你说中了，这一次他们早有准备，我们算是打草惊蛇，再要做些什么就不容易了。"
  },
  [111550318] = {
    id = 111550318,
    name = "要不然还是像去年一样，把祭台炸了再说......"
  },
  [111550319] = {
    id = 111550319,
    name = "......这也只能暂缓祭祀的时间，要想以后都不再有祭祀，还是要釜底抽薪，把神石里的魔物除掉才行。"
  },
  [111550320] = {
    id = 111550320,
    name = "可要怎样，才能让那个装神弄鬼的家伙乖乖地拿出神石让我们毁掉呢......"
  },
  [111550321] = {
    id = 111550321,
    name = "鬼魅手托腮，目光盈盈望着湖面，湖水波平如镜，有微风吹过，激起一皱潋滟的水纹和水下晶莹的流光溢彩。"
  },
  [111550322] = {
    id = 111550322,
    name = "你看，那是什么？"
  },
  [111550323] = {id = 111550323, name = "嗯？"},
  [111550324] = {
    id = 111550324,
    name = "你埋头编着藤条灯，这时顺着鬼魅的指向看去，水底映射出微弱的光芒，如同夜空繁星。"
  },
  [111550325] = {
    id = 111550325,
    name = "水底有东西？是什么？"
  },
  [111550326] = {
    id = 111550326,
    name = "......你去把它捞出来给奴家看看吧？"
  },
  [111550327] = {
    id = 111550327,
    name = "为什么要我——"
  },
  [111550328] = {
    id = 111550328,
    name = "话说到一半时，你想起了那天的美人出浴，忽然闭上了嘴。"
  },
  [111550329] = {
    id = 111550329,
    name = "奴家是发现这水底的，好像是一种能致幻的矿石，你想到了什么？怎么欲言又止的？"
  },
  [111550330] = {
    id = 111550330,
    name = "没什么。你说湖底有能致幻的矿石？"
  },
  [111550331] = {
    id = 111550331,
    name = "对。把它洒在火焰里，会有意想不到的效果，要是放入火堆里就能制造幻象......"
  },
  [111550332] = {
    id = 111550332,
    name = "幻象？你能控制这个幻象吗？"
  },
  [111550333] = {
    id = 111550333,
    name = "捞出来试试不就知道了？"
  },
  [111550334] = {
    id = 111550334,
    name = "你心中一动，脱鞋踏入湖水，缓缓走向那块散发着微光的矿石，伸手捞出了一块。感受到了矿石的温度和能量，你朝岸边的鬼魅笑了。"
  },
  [111550335] = {
    id = 111550335,
    name = "真的具有魔力，我多捞几块再......"
  },
  [111550336] = {
    id = 111550336,
    name = "突然，你的脚下一踩空，失去了平衡，身体不受控制地向前倾斜。时间在这一刻变得缓慢起来，你感受到了空气的阻力和风声呼啸在耳边，眼中的景色变得模糊，接着重重地摔倒在湖水中！"
  },
  [111550337] = {id = 111550337, name = "！！！"},
  [111550338] = {
    id = 111550338,
    name = "水花四溅，你下意识翻身，游了上去。"
  },
  [111550339] = {
    id = 111550339,
    name = "咳咳咳咳咳......"
  },
  [111550340] = {
    id = 111550340,
    name = "哈哈哈哈......"
  },
  [111550341] = {
    id = 111550341,
    name = "看着你狼狈不堪，全身湿透的模样，鬼魅捧腹大笑，笑得弯了眼，弯了腰，那是你第一次见到，她摒弃了一切面具后，真挚灿烂的笑容。"
  },
  [111550342] = {
    id = 111550342,
    name = "真的有必要扮成这样吗？"
  },
  [111550343] = {
    id = 111550343,
    name = "唔，哥哥不喜欢这身打扮吗？那不如接受奴家的提议——"
  },
  [111550344] = {
    id = 111550344,
    name = "不用了。"
  },
  [111550345] = {
    id = 111550345,
    name = "由于时间与条件有限，鬼魅提出你们扮作主仆，因为种种考虑被你拒绝后，退而求次选择了蒙头盖面的游商兄妹。次日，你们通过了严防死守的据点口，这时心照不宣地走向了祭台附近，只到傍晚，人群已开始聚集。"
  },
  [111550346] = {
    id = 111550346,
    name = "已经这么多人了。"
  },
  [111550347] = {
    id = 111550347,
    name = "嗯，等暗夜降临，火堆燃起，就是祭祀开始的时候。"
  },
  [111550348] = {
    id = 111550348,
    name = "你们两个外来做生意的，集市地点在隔壁街，别在这瞎逛！"
  },
  [111550349] = {
    id = 111550349,
    name = "据点守卫打量了你们两眼，视线咕溜溜在鬼魅身上转了一圈，突然皱起了眉头。"
  },
  [111550350] = {
    id = 111550350,
    name = "神神秘秘的！你们两个把头巾都摘下来！！"
  },
  [111550351] = {
    id = 111550351,
    name = "哥哥......"
  },
  [111550352] = {
    id = 111550352,
    name = "抱歉，前段时间我们翻山的时候，不小心被奇怪的植物刮伤了脸，现在不太好看。"
  },
  [111550353] = {
    id = 111550353,
    name = "你凑在守卫前面，将鬼魅挡在身后，拨开了面巾的一角，露出了事先涂抹的拟真疤痕，守卫顿时露出了恶心和嫌弃的表情，不愿再多看一眼。"
  },
  [111550354] = {
    id = 111550354,
    name = "走走走！真是晦气，白瞎了那么好的身材。"
  },
  [111550355] = {id = 111550355, name = "......"},
  [111550356] = {
    id = 111550356,
    name = "你一本正经地撒谎，还真让人无法分辨呢。"
  },
  [111550357] = {
    id = 111550357,
    name = "看来他们会对两人结伴的严加盘查，不然你先找个地方休息。"
  },
  [111550358] = {
    id = 111550358,
    name = "鬼魅思考了片刻，同意了你的决定，将一袋粉末交给了你。"
  },
  [111550359] = {
    id = 111550359,
    name = "这些都是矿石粉末，洒在木柴上可以自动吸附，我就能用魔法力催动它。我去四周布置驱魔草，以免魔物出现伤到无辜者。"
  },
  [111550360] = {
    id = 111550360,
    name = "好，我们庆典上汇合。"
  },
  [111550361] = {
    id = 111550361,
    name = "鬼魅走后不久，你绕着空旷的广场走了一圈，中间的台子空空，那是用来放篝火的地方，四周都被栅栏包围，站满了观赏祭祀仪式的人。"
  },
  [111550362] = {
    id = 111550362,
    name = "让一让，让一让啊！"
  },
  [111550363] = {
    id = 111550363,
    name = "一群人抱着一堆堆木柴进入广场，你立刻接近了他们，趁机将粉末洒在了其中一捆木柴上，一切完成后，你决定找个高地方便行动，却听到了墙角里的哭声。"
  },
  [111550364] = {
    id = 111550364,
    name = "别哭啦，你们的女儿能为了整个据点牺牲，这是多大的荣耀啊~"
  },
  [111550365] = {
    id = 111550365,
    name = "......呜呜，女儿啊......老爸没用......连你都保护不了......"
  },
  [111550366] = {
    id = 111550366,
    name = "你看你隔壁的亚伦，他家现在过得多好？少一个女儿，就能换一辈子用不完的欧泊，吃不完的食物！他前几天还跟我说，可惜另外一个是儿子，否则今年还轮不上你呢。"
  },
  [111550367] = {
    id = 111550367,
    name = "守卫大人，我去行不行？我老了也没什么用了，让我去死，放过我女儿吧......"
  },
  [111550368] = {
    id = 111550368,
    name = "你想得真美，还妄想去希望女神身边侍奉，那是你女儿成为神仆的机会，不是你的！你也别动其他歪脑筋，破坏祭祀的人会受到神的诅咒，也会被赶出据点，你要想和你的家人好好在深渊活下来，这也是应该付出的代价！"
  },
  [111550369] = {
    id = 111550369,
    name = "......呜呜......那再让我去看她最后一眼吧......求求你，我求求你......"
  },
  [111550370] = {
    id = 111550370,
    name = "马上祭祀就开始了，上了祭台大家都能看得见，反正你现在看了，她也不会跟你说话。"
  },
  [111550371] = {
    id = 111550371,
    name = "走吧，我们去找个前面一些的位置，别在这挡着人了。"
  },
  [111550372] = {
    id = 111550372,
    name = "呜呜呜......"
  },
  [111550373] = {id = 111550373, name = "......"},
  [111550374] = {
    id = 111550374,
    name = "这位父亲明明正值壮年，却已露出了花白的发，你默默跟在他身后，看着他佝偻的背和委顿的步伐。"
  },
  [111550375] = {
    id = 111550375,
    name = "随着人潮涌动，祭祀开始了。"
  },
  [111550376] = {
    id = 111550376,
    name = "一群守卫身着盛装，手捧白烛，垂头虔诚地向围在祭台周围，而后，祭司出现，现场一片安静，他步伐庄重地迈向祭台，闭目默念祷告，随着祷告声回荡，广场上的氛围忽然变得压抑而沉重。"
  },
  [111550377] = {
    id = 111550377,
    name = "（他用了精神类魔法？）"
  },
  [111550378] = {
    id = 111550378,
    name = "伴随着祭司的呼唤，广场中响起了守卫合唱的歌声，同时四人高抬着祭品走上了祭台，祭司环视一周，法杖凌空画了个圈，四四方方的神石凭空出现，众人屏住了呼吸瞻仰，期待神圣时刻的到来。"
  },
  [111550379] = {
    id = 111550379,
    name = "敬告神谕！"
  },
  [111550380] = {
    id = 111550380,
    name = "祭司法杖一扬，祭台上的火苗高高窜起，却在此时轰地一声，火焰幻化出了一个魔物的虚影！"
  },
  [111550381] = {
    id = 111550381,
    name = "魔......魔物啊！！！"
  },
  [111550382] = {
    id = 111550382,
    name = "是预言、魔女的预言！！"
  },
  [111550383] = {id = 111550383, name = "！！！"},
  [111550384] = {
    id = 111550384,
    name = "火焰的虚影逐渐凝实，庞大可怖，黑鳞遍布，尖锐的爪子和锋利的牙齿仿佛随时都能撕裂空气，化为真实。围观的人们目瞪口呆，这时随着有人大叫，现场乱作一团。"
  },
  [111550385] = {id = 111550385, name = "......！"},
  [111550386] = {
    id = 111550386,
    name = "你在混乱中看到了鬼魅，此时她已经卸去伪装，不断挥动着法杖，一身红衣映照着火光回旋舞动，四周是散乱尖叫的人群，守卫们发现了她，而她只是遥远地朝你一笑。"
  },
  [111550387] = {
    id = 111550387,
    name = "火焰燃烧着，很快就要烧到祭品的所在位置，你知道该你行动了。"
  },
  [111550388] = {
    id = 111550388,
    name = "保护祭司大人！！"
  },
  [111550389] = {
    id = 111550389,
    name = "有人发现了你逆向而行的举动，但已经晚了，你长驱直入冲向了高台上的祭司，他惊恐的目光投映在你锃亮的剑身上，身体下意识地后退了一大步，收回了空中的神石。"
  },
  [111550390] = {
    id = 111550390,
    name = "这个祭品，我先带走了。"
  },
  [111550391] = {
    id = 111550391,
    name = "你没有看神石一眼，而是腾空一脚，踢开了放着女孩的木架，在女孩未落地前快速地接住了她，与愤怒的祭司隔火相望。"
  },
  [111550392] = {
    id = 111550392,
    name = "扰乱祭祀，冒犯神祇，其罪当诛！给我抓住他们！"
  },
  [111550393] = {
    id = 111550393,
    name = "附近的守卫很快攻了上来，你躲避刀锋的威胁，还要保护女孩，不禁有点手忙脚乱，这时一道魔法助你击退了守卫。"
  },
  [111550394] = {
    id = 111550394,
    name = "交给奴家！"
  },
  [111550395] = {
    id = 111550395,
    name = "间隙之间，你将女孩抛向接应的鬼魅，专心拦下那群守卫，鬼魅很快将女孩带到了目瞪口呆的其父身边。"
  },
  [111550396] = {
    id = 111550396,
    name = "你就是她的父亲吧。以后也不会再有活祭的事发生，你们从此都安全了。"
  },
  [111550397] = {
    id = 111550397,
    name = "你，你是那个魔女......"
  },
  [111550398] = {
    id = 111550398,
    name = "男人慌乱地接过了女儿，警惕地看着鬼魅，身边的路人拉了拉他的衣袖提醒。"
  },
  [111550399] = {
    id = 111550399,
    name = "快走啊，你不怕和她说话被神灵诅咒吗！"
  },
  [111550400] = {
    id = 111550400,
    name = "男人欲言又止，抱着女儿和那群人逃走了。"
  },
  [111550401] = {
    id = 111550401,
    name = "罪不可恕，罪不可恕！！"
  },
  [111550402] = {
    id = 111550402,
    name = "祭司的法杖重重杵在地上，从怀中重新取出了神石，宛如星光闪耀，他将这颗石头紧握在手中，轻轻摩挲着它的光滑表面，仿佛在与它进行一种默契的交流。"
  },
  [111550403] = {
    id = 111550403,
    name = "他要开启神石了，不能让它吞噬无辜人！"
  },
  [111550404] = {
    id = 111550404,
    name = "......这场戏该落幕了！"
  },
  [111550405] = {
    id = 111550405,
    name = "鬼魅缥缈的声音传了过来，与之同时，一道耀眼的光芒缠绕在神石周围，耀眼的光芒愈发强烈，訇然炸破！"
  },
  [111550406] = {
    id = 111550406,
    name = "不，不！！"
  },
  [111550407] = {
    id = 111550407,
    name = "悦耳的清脆声响，犹如开启了唱诗的节奏，碎片在空中翻飞，闪烁着迷人的光华，仿若定格在了繁星坠落的瞬间。"
  },
  [111550408] = {
    id = 111550408,
    name = "而此刻，一种神秘的力量释放涌动，巨型魔物诡异地凭空出现，它仰天怒吼，像是陷入了极度的愤怒与饥饿，一口将浊炁喷在祭司脸上。"
  },
  [111550409] = {
    id = 111550409,
    name = "不要，不要！！"
  },
  [111550410] = {
    id = 111550410,
    name = "魔物无情地咬断了祭司的法杖，接着是手臂，身躯和腿，直到完全吞噬。"
  },
  [111550411] = {
    id = 111550411,
    name = "祭司大人死了，祭司大人死了！！"
  },
  [111550412] = {
    id = 111550412,
    name = "守卫们东逃西窜，魔物还在咀嚼刚入腹的食物，广场上只剩下了你与鬼魅——这是一幅极其诡异的画面。"
  },
  [111550413] = {
    id = 111550413,
    name = "四周已经放好驱魔草了，它的活动范围仅止于此。"
  },
  [111550414] = {
    id = 111550414,
    name = "辛苦了，那接下来就是这个家伙了吧。"
  },
  [111550415] = {
    id = 111550415,
    name = "奴家从未想过，有一天还能有人与我并肩作战。"
  },
  [111550416] = {
    id = 111550416,
    name = "这么说我是第一个？不甚荣幸。"
  },
  [111550417] = {
    id = 111550417,
    name = "鬼魅傲然一笑，高举法杖，穿透地狱的火焰，施放出最璀璨的光华！"
  },
  [111550418] = {id = 111550418, name = "......"},
  [111550419] = {
    id = 111550419,
    name = "拂晓来临之前，你们终于将魔物彻底击杀，自身也累倒在地。"
  },
  [111550420] = {
    id = 111550420,
    name = "都结束了......"
  },
  [111550421] = {
    id = 111550421,
    name = "嗯，一个完美的结局，不是吗。"
  },
  [111550422] = {
    id = 111550422,
    name = "你朝鬼魅笑了笑，相互将对方扶了起来，鬼魅正想说些什么，却越过你看见了一群人正朝这边走来。"
  },
  [111550423] = {
    id = 111550423,
    name = "都是据点的人，他们终于看清事实了，来向你道歉的吧？"
  },
  [111550424] = {id = 111550424, name = "是吗？"},
  [111550425] = {
    id = 111550425,
    name = "鬼魅怔愣了一瞬，眼里萌生着期待。"
  },
  [111550426] = {
    id = 111550426,
    name = "就是她，是她带来了魔物！！我看得清清楚楚！她用魔法发出了一道光，神石就变成了魔物！！"
  },
  [111550427] = {
    id = 111550427,
    name = "她就是那个预言魔物降临的魔女鬼魅！不仅引来了魔物，还害死了祭司大人！！你这个无耻的魔女，滚出埃兰！"
  },
  [111550428] = {
    id = 111550428,
    name = "滚出埃兰！滚出埃兰！滚出埃兰！"
  },
  [111550429] = {id = 111550429, name = "......"},
  [111550430] = {
    id = 111550430,
    name = "明明——"
  },
  [111550431] = {
    id = 111550431,
    name = "不用说了，走吧。"
  },
  [111550432] = {
    id = 111550432,
    name = "鬼魅再次笑了，你感觉到她又重新戴上了那张美丽的假面，跳动的火光中，她的微笑怅惘又落寞。"
  },
  [111550433] = {
    id = 111550433,
    name = "真是，有趣的彩蛋呢。"
  },
  [111550434] = {
    id = 111550434,
    name = "离开据点后，你们一言不发地走着，一前一后。"
  },
  [111550435] = {
    id = 111550435,
    name = "你本想加快脚步与她并行时，她也以同样的速度走得更快了一些，你察觉到她似乎在回避什么，脚步放慢了。"
  },
  [111550436] = {id = 111550436, name = "......"},
  [111550437] = {id = 111550437, name = "......"},
  [111550438] = {
    id = 111550438,
    name = "想起受益者的污蔑、指责、数落、逼问......你叹息了一声，烦躁地拿出了之前差一点就编织完成的星星灯。蹊跷的是，这一次你似乎找到了关键的技巧，无师自通地将草枯藤缠绕勾连，编串成结。"
  },
  [111550439] = {
    id = 111550439,
    name = "美丽的星星。"
  },
  [111550440] = {id = 111550440, name = "......"},
  [111550441] = {
    id = 111550441,
    name = "你抬头，鬼魅不知什么时候停了下来，她瞭望着远处的据点，晨光熹微，灯火如星。"
  },
  [111550442] = {
    id = 111550442,
    name = "你喜欢星星？"
  },
  [111550443] = {
    id = 111550443,
    name = "鬼魅点了点头，但你却觉得她更喜欢这样安定而美好的世界，就像尘埃落定、布满星火的埃兰据点。"
  },
  [111550444] = {
    id = 111550444,
    name = "星星有时会很耀眼，有时又闪烁不定，它漂浮不定，最终坠落，它的一生也像一场无常的游戏，和人类并没有什么区别。"
  },
  [111550445] = {
    id = 111550445,
    name = "可惜，深渊里没有星星，在黑暗的世界，即使是能发光的星星，也会迷失。"
  },
  [111550446] = {
    id = 111550446,
    name = "不会的。"
  },
  [111550447] = {id = 111550447, name = "嗯？"},
  [111550448] = {
    id = 111550448,
    name = "鬼魅回头看你，你笑着将几块萤石扔进了灯罩里，大小不一的“星星”汇聚在一起，星辰仿佛活了起来。"
  },
  [111550449] = {
    id = 111550449,
    name = "因为星星不再孤单了。送给你。"
  },
  [111550450] = {id = 111550450, name = "！！！"},
  [111550451] = {
    id = 111550451,
    name = "这些萤石......"
  },
  [111550452] = {
    id = 111550452,
    name = "当时在湖泊里捞的，我留了几块。"
  },
  [111550453] = {
    id = 111550453,
    name = "呵呵呵......"
  },
  [111550454] = {
    id = 111550454,
    name = "鬼魅捧着灯笑了。你难得再次看到了这样的笑，没有伪装与假面，双眸投射出细碎而明亮的光点，在破晓的天色里随着笑意溢满了星河。"
  },
  [111550455] = {
    id = 111550455,
    name = "谢谢你，你是第一个送奴家礼物的人。这个礼物，奴家很喜欢。"
  },
  [111550456] = {
    id = 111550456,
    name = "你也是第一个，没有认定奴家是魔女恶鬼的人......尽管多一个人布置剧场是有些不习惯，但你真的令奴家很意外。"
  },
  [111550457] = {
    id = 111550457,
    name = "唔，能与鬼魅小姐共同演绎剧目，是我的荣幸。"
  },
  [111550458] = {
    id = 111550458,
    name = "鬼魅突然倾身靠了过来，一只手轻轻拂动了你耳边的发。"
  },
  [111550459] = {
    id = 111550459,
    name = "呵呵，那就期待我们的下次合作了。"
  },
  [111550460] = {
    id = 111550460,
    name = "声音轻柔而婉转，如一阵风，淡薄而不真实。"
  },
  [111550461] = {id = 111550461, name = "......"},
  [111550462] = {
    id = 111550462,
    name = "待你正想回应时，鬼魅已经消失了，空中旋转飘落了一张扑克牌，你接着翻看正面，神秘典雅的桃心纹饰上，描绘着漆黑的图案“Q”。"
  },
  [111800001] = {
    id = 111800001,
    name = "就是这里！队长，你看，前面的魔物，脑袋上发光的那个！"
  },
  [111800002] = {
    id = 111800002,
    name = "岩甲石灵？"
  },
  [111800003] = {
    id = 111800003,
    name = "这不就是普通的岩甲石灵？它们身上总有会发光的地方。"
  },
  [111800004] = {
    id = 111800004,
    name = "一点也不普通！不说个头大了一圈，队长，你仔细看它的脑袋，那里有一面镜子！"
  },
  [111800005] = {
    id = 111800005,
    name = "你放眼看去，岩石与水晶堆砌的甲壳上，有一处光芒与其他水晶不同，像镜面反射般，亮得刺眼。"
  },
  [111800006] = {
    id = 111800006,
    name = "看到了。不管怎样，先打下来再说。"
  },
  [111800007] = {
    id = 111800007,
    name = "欸嘿！交给小莎！"
  },
  [111800008] = {
    id = 111800008,
    name = "......没过多久，你们就顺利除掉了岩甲石灵，摘取了它头上的“镜子”。"
  },
  [111800009] = {
    id = 111800009,
    name = "哈哈，真的是一面镜子呢，安妮斯快来看！"
  },
  [111800010] = {
    id = 111800010,
    name = "尼莉莎把镜子往前一伸，里面映照出了安妮斯微笑的模样。"
  },
  [111800011] = {
    id = 111800011,
    name = "咦？明明有魔法的波动，这镜子怎么没反应？"
  },
  [111800012] = {
    id = 111800012,
    name = "尼莉莎揽镜自照，挨个走到你们面前，照到你的时候，你在镜子里看到一个黑衣白发的女人，正悄无声息地站在你身后。"
  },
  [111800013] = {
    id = 111800013,
    name = "呜哇！！！"
  },
  [111800014] = {
    id = 111800014,
    name = "尼莉莎当场吓得跳起来，镜子脱手被你稳稳接住，你回头看向那个女人，她什么时候出现的，你们之中竟然没有一个人发现。"
  },
  [111800015] = {
    id = 111800015,
    name = "这位是......"
  },
  [111800016] = {
    id = 111800016,
    name = "鬼牌，鬼侍。"
  },
  [111800017] = {
    id = 111800017,
    name = "（那个神秘组织......）"
  },
  [111800018] = {
    id = 111800018,
    name = "我想买你的镜子。"
  },
  [111800019] = {
    id = 111800019,
    name = "啊？这么快就有买家了？"
  },
  [111800020] = {
    id = 111800020,
    name = "鬼侍小姐，你为什么要买它？"
  },
  [111800021] = {
    id = 111800021,
    name = "只是想买而已。你卖吗？"
  },
  [111800022] = {
    id = 111800022,
    name = "这是我和同伴们一起获得的，得看他们的意见。"
  },
  [111800023] = {
    id = 111800023,
    name = "我没关系。"
  },
  [111800024] = {
    id = 111800024,
    name = "如果这位小姐需要的话......"
  },
  [111800025] = {
    id = 111800025,
    name = "价格可不便宜，这可是从......好吧，虽然不是什么稀奇的魔物，但也是难得的好东西。"
  },
  [111800026] = {
    id = 111800026,
    name = "正所谓宝镜配美人，这是队长和鬼侍小姐的缘分啊。"
  },
  [111800027] = {
    id = 111800027,
    name = "菲尼斯你闭嘴。"
  },
  [111800028] = {
    id = 111800028,
    name = "多少钱？"
  },
  [111800029] = {
    id = 111800029,
    name = "你和鬼侍说了一个合理的价格，她干脆地同意了，正当你将镜子递给鬼侍时，旁边的草丛猛然跳出了四五个黑衣人。"
  },
  [111800030] = {
    id = 111800030,
    name = "什么人？！"
  },
  [111800031] = {
    id = 111800031,
    name = "竟然慢了一步，那就一起杀了吧！"
  },
  [111800032] = {
    id = 111800032,
    name = "几名黑衣人悍然出手，还没等你说出口，鬼侍已经一手探出，横剑一挡，只听“砰”的一声，冲上前的一个黑衣人已经被大剑砸得远远的，翻了好几个跟头。"
  },
  [111800033] = {
    id = 111800033,
    name = "你找死！"
  },
  [111800034] = {
    id = 111800034,
    name = "面对凛凛刀光，鬼侍一言不发，抡起大剑挡了过去，黑衣人被撞得头晕眼花，鼻血直流。尼莉莎眨了眨眼，暗自竖起一根大拇指。"
  },
  [111800035] = {
    id = 111800035,
    name = "厉害啊，人狠话不多！"
  },
  [111800036] = {
    id = 111800036,
    name = "这群人来路不明，一来就干杀人夺宝的勾当，你也觉得没有交流的必要。"
  },
  [111800037] = {
    id = 111800037,
    name = "大家小心，专心应敌！"
  },
  [111800038] = {
    id = 111800038,
    name = "几只阴沟里的老鼠，也不知道在嚣张什么。"
  },
  [111800039] = {
    id = 111800039,
    name = "蒂娜也加入了战局，长剑呼啸，阻挡了偷袭鬼侍的一击，同时反手一剑，直奔黑衣人的面门，金铁交鸣声毫无节奏地响起。"
  },
  [111800040] = {id = 111800040, name = "多谢。"},
  [111800041] = {
    id = 111800041,
    name = "客气了。"
  },
  [111800042] = {
    id = 111800042,
    name = "面对黑衣人的围攻，菲尼斯也毫不犹豫地出手，你让安妮斯站在身边，尼莉莎早已翻上了树，瞄准了正在后方施展魔法的黑衣人。"
  },
  [111800043] = {
    id = 111800043,
    name = "来咯，看小莎的天外流星！"
  },
  [111800044] = {
    id = 111800044,
    name = "“嗖——”箭矢划破空气的声音尖锐而刺耳，黑衣人只觉眼前一花，还未等反应过来，箭矢已穿透了他的护臂，深深钉入了他的肩膀。"
  },
  [111800045] = {
    id = 111800045,
    name = "啊啊啊！"
  },
  [111800046] = {
    id = 111800046,
    name = "该死的家伙！先把东西抢过来！"
  },
  [111800047] = {
    id = 111800047,
    name = "一群人的目标从先杀人变成了先夺宝，几名黑衣人打算绕过阻碍，夺走你手里的那面镜子。你注意到其中一名黑衣人悄悄地退了一步，而此时另一人从背后袭来。"
  },
  [111800048] = {
    id = 111800048,
    name = "老师，这边！"
  },
  [111800049] = {
    id = 111800049,
    name = "交给我就好。"
  },
  [111800050] = {
    id = 111800050,
    name = "你无暇他顾，和菲尼斯共同御敌，几名黑衣人被打得踉跄后退。突然，一道光束从暗处倏然而至！"
  },
  [111800051] = {
    id = 111800051,
    name = "你还没来得及抵挡，鬼侍的剑已经挡住了光，恍若一瞬间将光芒吸入了大剑之中。"
  },
  [111800052] = {
    id = 111800052,
    name = "藏头露尾的东西。"
  },
  [111800053] = {
    id = 111800053,
    name = "她反手一挥，刚才凝聚在剑里的魔法力如魔法弹一般爆破开来，炸得黑衣人四处逃窜。"
  },
  [111800054] = {
    id = 111800054,
    name = "可恶！撤退！"
  },
  [111800055] = {
    id = 111800055,
    name = "不能放走他们！"
  },
  [111800056] = {
    id = 111800056,
    name = "这群人目的明确，下手熟练，明显有组织和预谋，且坏事做尽，不能再让他们去祸害无辜。"
  },
  [111800057] = {
    id = 111800057,
    name = "你们反守为攻，很快就制服了那群黑衣人。"
  },
  [111800058] = {
    id = 111800058,
    name = "你们到底是什么人？"
  },
  [111800059] = {
    id = 111800059,
    name = "领头的黑衣人并不回答，只是比了个手势，其余的黑衣人竟然齐齐举剑自尽。"
  },
  [111800060] = {id = 111800060, name = "！！！"},
  [111800061] = {
    id = 111800061,
    name = "嘿嘿嘿，想知道？就一起去地狱吧！"
  },
  [111800062] = {
    id = 111800062,
    name = "趁众人震惊之际，黑衣人抛出了一枚原形的魔法珠，还没靠近你已感受到其中蕴含的恐怖魔法力，当机立断将手中的镜子扔了出去抵挡！"
  },
  [111800063] = {id = 111800063, name = "散开！"},
  [111800064] = {
    id = 111800064,
    name = "所有人都快速躲闪，唯有鬼侍妄图将魔法珠打开，你一见拉住鬼侍，转身趴在地下，千钧一发之际，你听到魔法珠击中镜面的声音。"
  },
  [111800065] = {
    id = 111800065,
    name = "轰——你的脑中一片嗡鸣，低头看被你扑倒的鬼侍，她的眼中灼灼闪耀，那是镜子破碎后反射的光芒。"
  },
  [111800066] = {id = 111800066, name = "......"},
  [111800067] = {
    id = 111800067,
    name = "你想礼节性地问她有没有事，也想赶快起身，可你什么也做不了，下一秒你头晕目眩，瞬间失去了意识。"
  },
  [111800068] = {id = 111800068, name = "老师！"},
  [111800069] = {
    id = 111800069,
    name = "队长！怎么回事？"
  },
  [111800070] = {
    id = 111800070,
    name = "队长晕过去了！"
  },
  [111800071] = {
    id = 111800071,
    name = "我......我治疗了，不行。"
  },
  [111800072] = {
    id = 111800072,
    name = "不应该的。"
  },
  [111800073] = {
    id = 111800073,
    name = "镜子碎了，会不会和这个有关？"
  },
  [111800074] = {
    id = 111800074,
    name = "不管怎样，这里不能久留，先离开这里，再找治好队长的办法。"
  },
  [111800075] = {
    id = 111800075,
    name = "蒂娜安抚地拍了拍安妮斯，尼莉莎也罕见地没有和她拌嘴，慎重地带上了你和鬼侍。"
  },
  [111800076] = {
    id = 111800076,
    name = "嗯？这个是鬼侍小姐的东西。"
  },
  [111800077] = {
    id = 111800077,
    name = "安妮斯看着落在鬼侍身边光芒暗淡的一对吊坠，小心地将它们收了起来。"
  },
  [111800078] = {
    id = 111800078,
    name = "走吧，我知道有个人，也许有办法。"
  },
  [111800079] = {id = 111800079, name = "好。"},
  [111800080] = {
    id = 111800080,
    name = "意识回笼，你听见了鸟鸣声，似乎还感觉到阳光照在身上的温度。"
  },
  [111800081] = {
    id = 111800081,
    name = "（阳光？深渊里怎么会有阳光？）"
  },
  [111800082] = {
    id = 111800082,
    name = "你猛地睁眼，头顶树叶斑斓，午后的光星星点点地洒进阴翳，你眨了眨眼睛，抬手遮住了许久不见的日光。"
  },
  [111800083] = {
    id = 111800083,
    name = "（这里是？）"
  },
  [111800084] = {
    id = 111800084,
    name = "你的手指白皙修长，根骨分明，一看就是养尊处优的贵公子才能有的一双手。"
  },
  [111800085] = {
    id = 111800085,
    name = "不对，这根本不是你的手。"
  },
  [111800086] = {
    id = 111800086,
    name = "你豁然起身，脑中一阵胀痛，忽然涌入了一段不属于你的记忆，以新奇又离谱的方式，如走马灯一般闪烁着，强行灌入脑中，直到疼痛减缓，你才缓缓回过神。"
  },
  [111800087] = {
    id = 111800087,
    name = "（幻境？）"
  },
  [111800088] = {
    id = 111800088,
    name = "（不，不像是幻境。）"
  },
  [111800089] = {
    id = 111800089,
    name = "幻境没有这样完全的真实，也不会将你变成另外一个人。"
  },
  [111800090] = {
    id = 111800090,
    name = "你身上穿着宝石蓝的锦缎外套，身旁挂着天鹅绒的披风，边缘的织金熠熠闪烁，披风上绣着似剑非剑的纹路，你觉得有一丝眼熟。"
  },
  [111800091] = {
    id = 111800091,
    name = "（当然眼熟了，这是普尔兰伯爵家族的家徽。）"
  },
  [111800092] = {
    id = 111800092,
    name = "你反应过来，自嘲了一声。"
  },
  [111800093] = {
    id = 111800093,
    name = "是的，你现在是普尔兰伯爵的继承人，16岁。你有忙碌的伯爵父亲，慈爱的母亲，还有一个可爱的妹妹。"
  },
  [111800094] = {
    id = 111800094,
    name = "你们普尔兰一族拥有属于自己的领地，有古老的城堡和庄园。"
  },
  [111800095] = {
    id = 111800095,
    name = "你从小养尊处优，所有的人都称你为少爷。家庭教师特意教导你骑术与剑术，德高望重的老者为你授课历史与哲学，他们都希望将你培养成为合格的下一任领主。"
  },
  [111800096] = {
    id = 111800096,
    name = "但你少年心性，散漫贪玩，趁着家里忙成一团的时候，见缝插针地躲到了这里睡觉。"
  },
  [111800097] = {
    id = 111800097,
    name = "（好真实的梦，呵呵，暂时当作是梦吧。）"
  },
  [111800098] = {
    id = 111800098,
    name = "上一刻你和同伴们还在为宝物争抢不休，这会儿竟然闲逸地躺在了树上睡大觉，你抿了抿嘴，难得地感受到了一瞬间不可思议的安宁。"
  },
  [111800099] = {
    id = 111800099,
    name = "哥哥，我就知道，你又来这里偷懒了！"
  },
  [111800100] = {
    id = 111800100,
    name = "你低头看下去，粉雕玉琢的小女孩抬头叉腰，嘟着嘴，脸颊鼓鼓囊囊地看着你，但你知道她并不是真的生气。"
  },
  [111800101] = {id = 111800101, name = "妹妹？"},
  [111800102] = {
    id = 111800102,
    name = "你看到她的第一眼，脑中就想起关于她的记忆，这是“你”的亲妹妹，柯莱特尔。"
  },
  [111800103] = {
    id = 111800103,
    name = "她骄横顽皮，也纯真善良，带着源自贵族的自信与傲娇。这时，她的眼中闪过狡黠的光。"
  },
  [111800104] = {
    id = 111800104,
    name = "哥哥，刚刚父亲大人好像在找你呢，你猜我怎么跟他说的？"
  },
  [111800105] = {
    id = 111800105,
    name = "你告诉他了？"
  },
  [111800106] = {
    id = 111800106,
    name = "哼哼，你猜呀？"
  },
  [111800107] = {
    id = 111800107,
    name = "你翻身跳下了树，朝柯莱特尔走了过去，一步一行中，感受到了这具少年身体的蓬勃朝气。"
  },
  [111800108] = {
    id = 111800108,
    name = "让哥哥偷懒不去，被我抓到了吧！"
  },
  [111800109] = {
    id = 111800109,
    name = "我的好妹妹，我现在就回去，你可别跟父亲大人告状。"
  },
  [111800110] = {
    id = 111800110,
    name = "你回想之前和柯莱特尔的相处方式，模仿着继承人的口吻应付着。"
  },
  [111800111] = {
    id = 111800111,
    name = "（在不知道为什么会出现这样的情况之前，还是不要改变现状吧。）"
  },
  [111800112] = {
    id = 111800112,
    name = "只有不动声色地获取周围的情报，也许才能找到办法离开这个“幻境”。果然，柯莱特尔对你的“求饶”习以为常，摆出了一副“你看着办”的表情。"
  },
  [111800113] = {
    id = 111800113,
    name = "你说不告诉我就不告诉吗？"
  },
  [111800114] = {
    id = 111800114,
    name = "你思考了一瞬，想起这个哥哥给妹妹准备了一个礼物，正打算找机会送出去。"
  },
  [111800115] = {
    id = 111800115,
    name = "呵呵，那哥哥送你一个东西，你帮我跟父亲大人瞒着。"
  },
  [111800116] = {
    id = 111800116,
    name = "什么东西？"
  },
  [111800117] = {
    id = 111800117,
    name = "小女孩的脸说变就变，柯莱特尔一点看不出刚才在生气，期待地睁着大眼睛望着你。"
  },
  [111800118] = {
    id = 111800118,
    name = "你拿出了一块方盒，蹲下身打开了它，果然听到了女孩子的惊叹声。"
  },
  [111800119] = {
    id = 111800119,
    name = "哇！好漂亮的吊坠！"
  },
  [111800120] = {
    id = 111800120,
    name = "方盒中静静安放着两块吊坠，一个白金镶嵌着月光石，如月华般皎洁，一个银边缠绕着紫水晶，似夜幕下的星辰。"
  },
  [111800121] = {
    id = 111800121,
    name = "咦，是两个吊坠？都是我的吗？"
  },
  [111800122] = {
    id = 111800122,
    name = "你挑一个，剩下那个留给哥哥。"
  },
  [111800123] = {
    id = 111800123,
    name = "哼，哪有送礼物送一半的。哥哥，你不会是舍不得吧？"
  },
  [111800124] = {
    id = 111800124,
    name = "当然不是。这是一对魔法吊坠，据说戴在两个人身上，不管两人相隔多远，也能听到对方的呼唤。"
  },
  [111800125] = {
    id = 111800125,
    name = "真的吗？！"
  },
  [111800126] = {
    id = 111800126,
    name = "嗯，你戴一个，哥哥戴一个。这样以后父亲找我的时候，你就可以在心里悄悄告诉我。"
  },
  [111800127] = {
    id = 111800127,
    name = "柯莱特尔有点发愣，随即露出了娇憨的模样。"
  },
  [111800128] = {
    id = 111800128,
    name = "原来送我魔法吊坠原来是这个目的！哼，我要去告诉父亲！"
  },
  [111800129] = {
    id = 111800129,
    name = "那你不要哥哥的礼物了吗？"
  },
  [111800130] = {
    id = 111800130,
    name = "......唔。"
  },
  [111800131] = {
    id = 111800131,
    name = "她盯着亮晶晶的吊坠，很舍不得的样子。"
  },
  [111800132] = {
    id = 111800132,
    name = "喜欢哪个？哥哥给你戴上。"
  },
  [111800133] = {
    id = 111800133,
    name = "小小的手指在方盒里滑来滑去，指了指左边的白金色，又指向了右边的银紫色。"
  },
  [111800134] = {
    id = 111800134,
    name = "我要这个紫色石头的吧！这个好像星星呀！"
  },
  [111800135] = {id = 111800135, name = "好。"},
  [111800136] = {
    id = 111800136,
    name = "你抽出盒中的银链，调整了适合柯莱特尔的长度，小心地挂在了她身上，她立刻抓起了吊坠，看到了其中流动的魔法符文，仿佛一场梦幻的流星雨。"
  },
  [111800137] = {
    id = 111800137,
    name = "真美啊......"
  },
  [111800138] = {
    id = 111800138,
    name = "收了哥哥的礼物，就要替哥哥保密哦。"
  },
  [111800139] = {
    id = 111800139,
    name = "柯莱特尔想压下嘴边的笑容，却怎么也做不出生气的假样，只能作罢。"
  },
  [111800140] = {
    id = 111800140,
    name = "好吧，这一次就饶过你了。哥哥，你也快戴上啊！"
  },
  [111800141] = {
    id = 111800141,
    name = "你将白金吊坠挂在了身上，那一瞬，心底有什么被触动了一下，接着你听到了柯莱特尔的声音。"
  },
  [111800142] = {id = 111800142, name = "哥哥？"},
  [111800143] = {id = 111800143, name = "哥哥？"},
  [111800144] = {id = 111800144, name = "嗯？"},
  [111800145] = {
    id = 111800145,
    name = "哥哥，你是不是被言灵骗了，我这样叫你，好像和之前没什么差别啊？"
  },
  [111800146] = {
    id = 111800146,
    name = "呵呵，你要在心里叫我。"
  },
  [111800147] = {
    id = 111800147,
    name = "心里叫？这样吗？"
  },
  [111800148] = {
    id = 111800148,
    name = "【哥哥。】"
  },
  [111800149] = {
    id = 111800149,
    name = "稚嫩的声音在耳边响起，仿若近在咫尺，但柯莱特尔的嘴巴并没有张开。"
  },
  [111800150] = {
    id = 111800150,
    name = "听不见吗？"
  },
  [111800151] = {
    id = 111800151,
    name = "【哥哥、哥哥、哥哥、哥哥。】"
  },
  [111800152] = {
    id = 111800152,
    name = "【听见了，妹妹。】"
  },
  [111800153] = {
    id = 111800153,
    name = "你扶额，阻止了这次魔音贯耳，柯莱特尔却开心地跳了起来。"
  },
  [111800154] = {
    id = 111800154,
    name = "啊！哥哥，刚才是你回答我了吗？"
  },
  [111800155] = {id = 111800155, name = "对。"},
  [111800156] = {
    id = 111800156,
    name = "太棒了！这个好好玩！"
  },
  [111800157] = {
    id = 111800157,
    name = "你看着她可爱的笑容，不由得也被感染了笑出声。正打算让她和你一起回家，柯莱特尔却一溜跑得远远的。"
  },
  [111800158] = {
    id = 111800158,
    name = "【哥哥，你听得到吗？】"
  },
  [111800159] = {
    id = 111800159,
    name = "你无奈地笑了笑，点点头。柯莱特尔大笑着转身跑了好几步，回头朝你招手。"
  },
  [111800160] = {
    id = 111800160,
    name = "【哥哥，你听得到吗？！】"
  },
  [111800161] = {
    id = 111800161,
    name = "【听到了。】"
  },
  [111800162] = {
    id = 111800162,
    name = "柯莱特尔原地蹦跳了起来，躲在了一棵树后。"
  },
  [111800163] = {
    id = 111800163,
    name = "【哥哥，你听得到吗？！！】"
  },
  [111800164] = {
    id = 111800164,
    name = "【听~到~了~】"
  },
  [111800165] = {
    id = 111800165,
    name = "【哈哈，哥哥，这个太好玩啦！】"
  },
  [111800166] = {
    id = 111800166,
    name = "柯莱特尔在原地转了几个圈圈，紫水晶随她飞起，熠熠生光。"
  },
  [111800167] = {
    id = 111800167,
    name = "【哥哥，不管我在哪里，你都能听到我的话吗？】"
  },
  [111800168] = {
    id = 111800168,
    name = "【嗯，能听到。】"
  },
  [111800169] = {
    id = 111800169,
    name = "【到君主的城堡那么远也可以吗？】"
  },
  [111800170] = {
    id = 111800170,
    name = "柯莱特尔跑了回来，晶晶亮亮地望着你。你笑了笑，牵起了她的手。"
  },
  [111800171] = {id = 111800171, name = "可以。"},
  [111800172] = {
    id = 111800172,
    name = "不管你在哪儿，只要你呼唤我，我就一定能找到你。"
  },
  [111800173] = {
    id = 111800173,
    name = "太好了！要是还有这样的吊坠，可以给父亲大人一个，母亲大人一个......"
  },
  [111800174] = {
    id = 111800174,
    name = "只有这一对哦，那个言灵已经不在了。"
  },
  [111800175] = {
    id = 111800175,
    name = "啊，这样呀......咦，哥哥，这边不是回家的路。"
  },
  [111800176] = {
    id = 111800176,
    name = "出来了这么久，总要找个再理由回去。"
  },
  [111800177] = {
    id = 111800177,
    name = "我之前发现宴会需要的鲜花不足，亲自去城里挑选了一些，现在该去拿货了。"
  },
  [111800178] = {
    id = 111800178,
    name = "【啊，狡猾的哥哥。】"
  },
  [111800179] = {
    id = 111800179,
    name = "【我听见了哦。】"
  },
  [111800180] = {id = 111800180, name = "哼。"},
  [111800181] = {
    id = 111800181,
    name = "你牵着柯莱特尔在城里转了一大圈，没有找到更多的线索，只能根据记忆从花农那运了一大车鲜花，和妹妹愉快地回了城堡。"
  },
  [111800182] = {
    id = 111800182,
    name = "少爷和小姐回来了！"
  },
  [111800183] = {
    id = 111800183,
    name = "众多仆人迎了上来，你愣了愣，对这个称呼还不太习惯。"
  },
  [111800184] = {
    id = 111800184,
    name = "（如果是菲尼斯，应该如鱼得水吧。）"
  },
  [111800185] = {
    id = 111800185,
    name = "【哎呀，父亲大人来了！哥哥我困了，先回房午睡啦！】"
  },
  [111800186] = {
    id = 111800186,
    name = "一回头，柯莱特尔已经不见了。"
  },
  [111800187] = {id = 111800187, name = "......"},
  [111800188] = {
    id = 111800188,
    name = "你看到远处走来的中年男人，身披绸缎长袍，银扣随着他稳健的步伐闪烁着微光，流露出不经意的优雅与从容。"
  },
  [111800189] = {
    id = 111800189,
    name = "父亲大人。"
  },
  [111800190] = {
    id = 111800190,
    name = "出门了？"
  },
  [111800191] = {
    id = 111800191,
    name = "是的，父亲大人，我看需要布置的鲜花不够了，就去城里挑选了一些，都在这里了。"
  },
  [111800192] = {
    id = 111800192,
    name = "你让侍卫把花车拉走，看向普尔兰面无表情的脸，转开了眼光。你不敢保证他发现不了你的异状。"
  },
  [111800193] = {
    id = 111800193,
    name = "行了。去把宾客名单再检查一遍，确保不能遗漏。"
  },
  [111800194] = {id = 111800194, name = "是。"},
  [111800195] = {
    id = 111800195,
    name = "侍卫的安保部署怎么样了？"
  },
  [111800196] = {
    id = 111800196,
    name = "你呆住了。“你”好像已经完全忘了这件事，可就是这犹豫的时间，普尔兰伯爵的眉头就皱了起来，你赶忙开口补救。"
  },
  [111800197] = {
    id = 111800197,
    name = "是这样的。之前计划的方案，我发现仍有漏洞，就打算在偏僻的角落安装一些简单的魔法陷阱，尊贵的宾客不会去那里，这样也可以防止宵小擅自闯入庄园。"
  },
  [111800198] = {
    id = 111800198,
    name = "嗯，你看着安排吧。"
  },
  [111800199] = {
    id = 111800199,
    name = "看普尔兰伯爵松开了眉头，你也松了一口气。这时，他伸出手，把你脑袋上的叶子拿了下来放在你手上。"
  },
  [111800200] = {id = 111800200, name = "......"},
  [111800201] = {
    id = 111800201,
    name = "你也不小了，不要整天想着出去玩，德温特教授已经在阁楼等你很久了。"
  },
  [111800202] = {
    id = 111800202,
    name = "他轻哼了一声，带着侍卫走远了，你赶紧把手里的叶子扔掉。"
  },
  [111800203] = {
    id = 111800203,
    name = "（还好不是真的，但为什么还是会觉得尴尬......）"
  },
  [111800204] = {
    id = 111800204,
    name = "你抬眼望着眼前巨大的庄园，仍然想不通为何会出现这样的“幻境”。"
  },
  [111800205] = {
    id = 111800205,
    name = "（要怎么样才能离开这个“幻境”？目前也没有发现其他同伴的存在......）"
  },
  [111800206] = {
    id = 111800206,
    name = "少爷，宾客名单都准备好了。您看看，是先去见德温特教授，还是......"
  },
  [111800207] = {
    id = 111800207,
    name = "先看名单。你去跟德温特教授说，这两日太忙，他布置的课业我之后会一同补上。"
  },
  [111800208] = {
    id = 111800208,
    name = "是的，少爷。"
  },
  [111800209] = {
    id = 111800209,
    name = "你暗自呼了一口气，印象里，那个老教授古板刚正，一去就耽搁一整天，还是能不见就不见吧。"
  },
  [111800210] = {
    id = 111800210,
    name = "（当务之急，还是寻找脱身的办法，也许这个“宴会”才是关键。）"
  },
  [111800211] = {
    id = 111800211,
    name = "你回到了属于自己的房间，随侍的仆人递上了一张金丝册子，你暗自吐槽了贵族的奢靡，仔细地看了起来。"
  },
  [111800212] = {
    id = 111800212,
    name = "（奥布里昂勋爵，格兰瑟姆公爵，德温特小姐，哦，是阁楼那个老爷子的孙女......啊，头晕脑胀。）"
  },
  [111800213] = {
    id = 111800213,
    name = "你帮我看看。"
  },
  [111800214] = {
    id = 111800214,
    name = "你把册子扔给了仆人，却见他眼神闪烁，低着头翻开了名单，隔了好一阵，才垂首回答。"
  },
  [111800215] = {
    id = 111800215,
    name = "回少爷，目前没有发现遗漏的宾客。"
  },
  [111800216] = {
    id = 111800216,
    name = "确定没有？"
  },
  [111800217] = {
    id = 111800217,
    name = "仆人表情凝固，又慌乱了一下。"
  },
  [111800218] = {
    id = 111800218,
    name = "诺瓦克家族虽然和大主教有亲缘，但伯爵大人一直没打算原谅他，少爷，您打算邀请诺瓦克家族参加宴会吗？"
  },
  [111800219] = {
    id = 111800219,
    name = "（什么跟什么啊？听他的意思，这个家还有个仇人？）"
  },
  [111800220] = {
    id = 111800220,
    name = "要不，你给我出出主意？"
  },
  [111800221] = {
    id = 111800221,
    name = "少爷，大主教在上个月试图说服陛下没收伯爵大人的领地，这时候激怒他们，并不是一件明智的事。"
  },
  [111800222] = {
    id = 111800222,
    name = "哦，你是指责父亲大人昏庸无能吗？还是，你有其他的想法？"
  },
  [111800223] = {
    id = 111800223,
    name = "仆人嘭地跪了下去，发出的撞击声吓了你一跳，也越来越觉得这个仆人有问题。"
  },
  [111800224] = {
    id = 111800224,
    name = "少爷，我向希望女神起誓，我对普尔兰家族忠心耿耿，但凡有一句虚言，我将万箭穿心，永堕地狱！"
  },
  [111800225] = {
    id = 111800225,
    name = "希望女神不管死后的事，永堕地狱这种无聊的誓言对我没有意义。"
  },
  [111800226] = {
    id = 111800226,
    name = "再说，我又没有说你背叛了家族，你紧张什么？"
  },
  [111800227] = {
    id = 111800227,
    name = "仆人的脸涨得通红。"
  },
  [111800228] = {
    id = 111800228,
    name = "除了诺瓦克家族，还有别的什么遗漏吗？"
  },
  [111800229] = {
    id = 111800229,
    name = "回少爷的话，没，没有了。"
  },
  [111800230] = {
    id = 111800230,
    name = "那你走吧，别吵我睡午觉。"
  },
  [111800231] = {
    id = 111800231,
    name = "少爷，德温特教授那边——"
  },
  [111800232] = {
    id = 111800232,
    name = "不是说了这两天很忙吗，宴会之后再说。"
  },
  [111800233] = {
    id = 111800233,
    name = "是。愿您有个好梦。"
  },
  [111800234] = {
    id = 111800234,
    name = "仆人离开之后，你揉了揉脑袋，走向窗台，尝试着敲了三下。果然，暗中保护你的侍卫出现在了树荫下，你指了指走远的仆人。"
  },
  [111800235] = {
    id = 111800235,
    name = "跟着他，有什么发现回来告诉我。"
  },
  [111800236] = {
    id = 111800236,
    name = "侍卫不言不语，朝你行了一礼后就藏入了阴影中。"
  },
  [111800237] = {
    id = 111800237,
    name = "（藏在影子里的魔法？有意思。）"
  },
  [111800238] = {
    id = 111800238,
    name = "将身边的人都支走后，你一头砸进了柔软的床铺里。"
  },
  [111800239] = {
    id = 111800239,
    name = "（呼，终于没人了。）"
  },
  [111800240] = {
    id = 111800240,
    name = "你的头埋在软软的天鹅绒中，这是你从未体验过的感受，只是梦境恐怕没有办法模拟出来，也绝对不会这样真实。"
  },
  [111800241] = {
    id = 111800241,
    name = "（难道，我和这位普尔兰少爷互换了身体？）"
  },
  [111800242] = {
    id = 111800242,
    name = "你笑了笑，甩开这种荒诞的想法，看向窗外的阳光，似乎出现了一条裂缝，又很快消失了。"
  },
  [111800243] = {
    id = 111800243,
    name = "果然，再真实也是假的。"
  },
  [111800244] = {
    id = 111800244,
    name = "你试想过告诉别人你的身份，但临到头却犹豫了。如果不能破境，那你面临的也许是无法逆转的灭顶之灾——这个世界不会饶恕抢夺他人灵魂的恶魔。"
  },
  [111800245] = {
    id = 111800245,
    name = "【哥哥！救命救命！】"
  },
  [111800246] = {
    id = 111800246,
    name = "耳边传来柯莱特尔着急的呼唤，你心中一紧。"
  },
  [111800247] = {
    id = 111800247,
    name = "【妹妹，怎么了？！你在哪儿？！】"
  },
  [111800248] = {
    id = 111800248,
    name = "【我在城里迷路啦，这里好多人，我不知道该往哪个方向走......】"
  },
  [111800249] = {
    id = 111800249,
    name = "【......】"
  },
  [111800250] = {
    id = 111800250,
    name = "【哥哥，你听见了吗？哥哥！】"
  },
  [111800251] = {
    id = 111800251,
    name = "【你把周围的建筑物告诉我，然后站在原地别动，我找人来接你。】"
  },
  [111800252] = {
    id = 111800252,
    name = "【不要不要，这次我是瞒着母亲大人出来的。】"
  },
  [111800253] = {
    id = 111800253,
    name = "【......】"
  },
  [111800254] = {
    id = 111800254,
    name = "【哥哥，你能不能亲自出来一趟？】"
  },
  [111800255] = {
    id = 111800255,
    name = "【唉，好吧。】"
  },
  [111800256] = {
    id = 111800256,
    name = "【耶，我最喜欢你啦！那哥哥，在你找到我之前，我能跟你一直说话吗？】"
  },
  [111800257] = {
    id = 111800257,
    name = "【吊坠里的魔法力总有用完的时候，你省着点。】"
  },
  [111800258] = {
    id = 111800258,
    name = "【嗯，那我乖乖在这里等你来接我吧。】"
  },
  [111800259] = {
    id = 111800259,
    name = "你回应了一声，突然后悔把这件礼物送给她了。"
  },
  [111800260] = {
    id = 111800260,
    name = "好麻烦。"
  },
  [111800261] = {
    id = 111800261,
    name = "原本你也只是暂时藏在这具身体里，明明可以不用管那个调皮的小女孩，但却又忍不住宠爱她。"
  },
  [111800262] = {
    id = 111800262,
    name = "算了，谁让她可爱呢。"
  },
  [111800263] = {
    id = 111800263,
    name = "根据柯莱特尔所说的地点，你在一个摊贩前找到了她。她的眼睛亮晶晶的，得意地将廉价的玩具送到你的手里，说花了两枚金币买下了它。"
  },
  [111800264] = {
    id = 111800264,
    name = "哥哥，这个可好玩啦，转一转就能飞起来哦！"
  },
  [111800265] = {
    id = 111800265,
    name = "你笑着把昂贵的风车收了起来，牵着她回到了家门口，正好迎上了普尔兰伯爵严厉的目光。"
  },
  [111800266] = {
    id = 111800266,
    name = "柯莱特尔见着却一点不惧，笑着拿出了另一支风车，跑上前去。"
  },
  [111800267] = {
    id = 111800267,
    name = "爸爸！你看，我给你买了风车！这样在你太热的时候，它能呼啦啦地吹风哦！"
  },
  [111800268] = {
    id = 111800268,
    name = "喔，好极了。爸爸很喜欢！"
  },
  [111800269] = {
    id = 111800269,
    name = "我给妈妈也买了一支哦！"
  },
  [111800270] = {
    id = 111800270,
    name = "好啊，你亲自送去给她吧。"
  },
  [111800271] = {
    id = 111800271,
    name = "柯莱特尔跑走后，专属于她的慈父转眼就变了。"
  },
  [111800272] = {id = 111800272, name = "......"},
  [111800273] = {
    id = 111800273,
    name = "日安，父亲大人。"
  },
  [111800274] = {
    id = 111800274,
    name = "柯莱特尔年纪尚幼，你作为兄长，有责任做出表率。"
  },
  [111800275] = {id = 111800275, name = "是。"},
  [111800276] = {
    id = 111800276,
    name = "然而，你似乎没有将我的话放在心上。"
  },
  [111800277] = {
    id = 111800277,
    name = "你开口想狡辩，想起“你”以前的样子，立刻低头道歉。"
  },
  [111800278] = {
    id = 111800278,
    name = "我知道错了，以后也不会再犯这种错误。"
  },
  [111800279] = {
    id = 111800279,
    name = "知道就好。"
  },
  [111800280] = {
    id = 111800280,
    name = "领完罚就早点休息，明天宴会就开始了，会更忙的。"
  },
  [111800281] = {
    id = 111800281,
    name = "是，父亲大人。"
  },
  [111800282] = {
    id = 111800282,
    name = "你答应得爽快，普尔兰伯爵意外地看了你一眼，少见地朝你笑了笑，转身离开。"
  },
  [111800283] = {
    id = 111800283,
    name = "（他笑什么？）"
  },
  [111800284] = {
    id = 111800284,
    name = "少爷，请跟我来。"
  },
  [111800285] = {
    id = 111800285,
    name = "干什么？"
  },
  [111800286] = {
    id = 111800286,
    name = "少爷，您忘了，地下牢房在这边。主人说这次您如果认错态度不错，就只罚您悬吊反省四个小时，背诵德温特教授的五节课文就可以出来了。"
  },
  [111800287] = {
    id = 111800287,
    name = "只？罚四小时？"
  },
  [111800288] = {
    id = 111800288,
    name = "你麻木地跟在管家身后，不由得深深怀疑了起来。"
  },
  [111800289] = {
    id = 111800289,
    name = "（怎么对儿子和对女儿的态度不一样？这家伙是他亲生的吗？）"
  },
  [111800290] = {id = 111800290, name = "......"},
  [111800291] = {id = 111800291, name = "......"},
  [111800292] = {
    id = 111800292,
    name = "从地下牢房出来的时候，已是月上中天，你浑身的力气都没了，整个人蔫巴巴的，顶着惨白的脸倒在华贵的床铺里。"
  },
  [111800293] = {
    id = 111800293,
    name = "（普尔兰伯爵真是教子有方，对贪玩的少爷用这种办法，就算是头猪也能培养成合格的继承人。）"
  },
  [111800294] = {
    id = 111800294,
    name = "不止是肉体和精神的折磨，整整四个小时一盏灯都看不见，黑漆漆的令人恐惧。地牢里不知被关过什么，总发出耐人寻味的声音，再加上腐烂的味道，真让人觉得头皮发麻。"
  },
  [111800295] = {
    id = 111800295,
    name = "也难怪你一看见地牢门口，就不自觉地想后退，竟然是被罚过，怕了。"
  },
  [111800296] = {
    id = 111800296,
    name = "（就连疼痛也是真实的......）"
  },
  [111800297] = {
    id = 111800297,
    name = "你排解着脑子里的不适，努力想怎么解决眼下的难题。"
  },
  [111800298] = {
    id = 111800298,
    name = "（如果不能离开，难道一辈子留在这里吗？）"
  },
  [111800299] = {
    id = 111800299,
    name = "【哥哥。】"
  },
  [111800300] = {
    id = 111800300,
    name = "耳边又传来了柯莱特尔的声音，这一次她的声音很轻，如同在你耳边说着悄悄话。"
  },
  [111800301] = {
    id = 111800301,
    name = "【哥哥，你睡了吗？】"
  },
  [111800302] = {
    id = 111800302,
    name = "【没有。】"
  },
  [111800303] = {
    id = 111800303,
    name = "【哥哥，对不起呀。是我让你出来，才被父亲罚了。】"
  },
  [111800304] = {
    id = 111800304,
    name = "柯莱特尔的心声竟然是哽咽的，你能想到她眼红红的可怜模样，一下就心软了。"
  },
  [111800305] = {
    id = 111800305,
    name = "【没关系，你也是想给家人们准备礼物才出去的是不是？】"
  },
  [111800306] = {
    id = 111800306,
    name = "【本来还想给你们一个惊喜，但我好笨，找不到回家的路了。】"
  },
  [111800307] = {
    id = 111800307,
    name = "【不会找不到的。你叫我，我不是就带你回家了吗？】"
  },
  [111800308] = {
    id = 111800308,
    name = "【嗯！】"
  },
  [111800309] = {
    id = 111800309,
    name = "【哥哥，我知道你没吃东西，晚餐之后，我悄悄藏了几块蛋糕放在你床底下啦！】"
  },
  [111800310] = {id = 111800310, name = "？？？"},
  [111800311] = {
    id = 111800311,
    name = "你垂下半个身子吊在床边，向床底望去，果然看到了摆着一盘小蛋糕，不由会心一笑。"
  },
  [111800312] = {
    id = 111800312,
    name = "【看见了，谢谢妹妹。】"
  },
  [111800313] = {
    id = 111800313,
    name = "你边吃边听柯莱特尔悄悄说话，蛋糕十分合你的口味。"
  },
  [111800314] = {
    id = 111800314,
    name = "【这个魔法吊坠真的太神奇了。】"
  },
  [111800315] = {
    id = 111800315,
    name = "【嗯？】"
  },
  [111800316] = {
    id = 111800316,
    name = "【我一叫哥哥，哥哥真的会回应我。中午的时候，我还以为会被父亲大人抓回去呢。】"
  },
  [111800317] = {
    id = 111800317,
    name = "【但是哥哥真的来了......太好了。】"
  },
  [111800318] = {
    id = 111800318,
    name = "【你喜欢这个礼物就好。】"
  },
  [111800319] = {
    id = 111800319,
    name = "【嘻嘻，哥哥，你吃完了吗？】"
  },
  [111800320] = {
    id = 111800320,
    name = "【嗯。】"
  },
  [111800321] = {
    id = 111800321,
    name = "休息了好一阵，你有了些精神，虽然地下牢房没让你沾染那些脏东西，但你还是打算沐浴之后再入睡。"
  },
  [111800322] = {id = 111800322, name = "来人。"},
  [111800323] = {
    id = 111800323,
    name = "仆人应声而进，听到你的要求，诧异地看了你一眼，随即立刻去准备了。"
  },
  [111800324] = {
    id = 111800324,
    name = "【哈欠......】"
  },
  [111800325] = {
    id = 111800325,
    name = "【好了，你该去睡觉了。】"
  },
  [111800326] = {
    id = 111800326,
    name = "【不要，我还想和哥哥说话。】"
  },
  [111800327] = {
    id = 111800327,
    name = "【想说什么？】"
  },
  [111800328] = {
    id = 111800328,
    name = "【想听哥哥多跟我说话......平时哥哥不是在学习剑术，就是在完成父亲布置的课业，很少有时间陪我玩的。】"
  },
  [111800329] = {
    id = 111800329,
    name = "【那......我给你讲个故事好不好？】"
  },
  [111800330] = {
    id = 111800330,
    name = "【好呀！】"
  },
  [111800331] = {
    id = 111800331,
    name = "咚咚咚。仆人在外面提醒你准备好了，你进入浴室，三下五除二跳进了宽大的浴缸中，发出一声喟叹。"
  },
  [111800332] = {
    id = 111800332,
    name = "【你想听什么样的故事？】"
  },
  [111800333] = {
    id = 111800333,
    name = "【只要是哥哥讲的就好。】"
  },
  [111800334] = {
    id = 111800334,
    name = "柯莱特尔的声音更轻了，像只扑朔的蝴蝶。"
  },
  [111800335] = {
    id = 111800335,
    name = "【那我给你讲一个关于魔法的故事吧。】"
  },
  [111800336] = {
    id = 111800336,
    name = "【嗯。】"
  },
  [111800337] = {
    id = 111800337,
    name = "【在很久很久以前，北方有一个冰封的地方，那里住着一个小女孩，她拥有一件魔法斗篷，能将她自己变成想要的任何模样......】"
  },
  [111800338] = {
    id = 111800338,
    name = "【哈欠......什么样子......都可以吗......】"
  },
  [111800339] = {
    id = 111800339,
    name = "【可以的。她还有一个很好的朋友，是隔壁擅长打猎的哥哥，他们一起生活在村庄里，非常地幸福。】"
  },
  [111800340] = {
    id = 111800340,
    name = "你顿了顿，柯莱特尔没有回应，但你继续讲了下去。"
  },
  [111800341] = {
    id = 111800341,
    name = "【可是，恶名昭彰的国王听说了这件事，他想抢走那件魔法斗篷，于是用魔法将村庄冻起来了。】"
  },
  [111800342] = {
    id = 111800342,
    name = "【......】"
  },
  [111800343] = {
    id = 111800343,
    name = "【妹妹，你还在听吗？】"
  },
  [111800344] = {
    id = 111800344,
    name = "【......】"
  },
  [111800345] = {
    id = 111800345,
    name = "回答你的是窗外偶尔的蝉鸣，柯莱特尔睡着了。你微微一笑，对着无人的天花板，轻轻开口。"
  },
  [111800346] = {
    id = 111800346,
    name = "晚安，柯莱特尔。祝你好梦。"
  },
  [111800347] = {
    id = 111800347,
    name = "一夜好眠，精神抖擞。"
  },
  [111800348] = {
    id = 111800348,
    name = "你根据回忆，大概摸清了这个家庭的规律，于是一大早就听管家所陈述的“伯爵的安排”，在书房抄写功课，得到了管家欣慰的眼神——这个废物总算懂事了。"
  },
  [111800349] = {
    id = 111800349,
    name = "（唉，人可不会在一夜之间改变，他在期待些什么？）"
  },
  [111800350] = {
    id = 111800350,
    name = "而后你阅览了众多书籍和信件，大致发现了一件事——现在的时间，是十五年前。"
  },
  [111800351] = {
    id = 111800351,
    name = "这里是普尔兰城，诺维奇帝国下属的领地之一，属普尔兰家族世代所有，离玛蒙之地有上万里的距离。"
  },
  [111800352] = {
    id = 111800352,
    name = "由于地面的暗域还没有扩张得那么快，深渊对普通的帝国居民来说，更多的是探险者的冒险之地。"
  },
  [111800353] = {
    id = 111800353,
    name = "（如果现在能去玛蒙之地，也许能看到十五年前的我也说不定，呵呵。）"
  },
  [111800354] = {
    id = 111800354,
    name = "明知不可能，你也忍不住胡思乱想。就在这时，一封信从书籍中掉了出来。"
  },
  [111800355] = {id = 111800355, name = "嗯？"},
  [111800356] = {
    id = 111800356,
    name = "这是一封带火漆的信，上面印着一个家族的徽章，这是——"
  },
  [111800357] = {
    id = 111800357,
    name = "嗯？诺瓦克？我们还与他们有交流？"
  },
  [111800358] = {
    id = 111800358,
    name = "你想起来那是个与你们有仇的家族，却没在记忆中翻到你们两家反目成仇的原因，你毫不犹豫打开了信封，正打算展开时，一道黑影从你身边缓缓站立。"
  },
  [111800359] = {
    id = 111800359,
    name = "主人，这是昨晚的调查结果。"
  },
  [111800360] = {
    id = 111800360,
    name = "他拿出了一截竹筒，抽出了其中的情报，里面清清楚楚记录了仆人从房间离开后到睡觉的行动轨迹。"
  },
  [111800361] = {
    id = 111800361,
    name = "他去过地下牢房？"
  },
  [111800362] = {id = 111800362, name = "是。"},
  [111800363] = {
    id = 111800363,
    name = "侍卫回答之后一言不发，垂目而站，等待你的下一步指示。"
  },
  [111800364] = {
    id = 111800364,
    name = "你却随意地扔在了一边，在侍卫的欲言又止下打开了那封火漆的信，信上明确地告知，诺瓦克家族会在今晚的宴会上有所行动。"
  },
  [111800365] = {
    id = 111800365,
    name = "不请自来吗？"
  },
  [111800366] = {
    id = 111800366,
    name = "你思考了一阵，想不清楚这个“有所行动”到底是指什么。"
  },
  [111800367] = {
    id = 111800367,
    name = "【妹妹，你有空吗？】"
  },
  [111800368] = {
    id = 111800368,
    name = "【哥哥！我在学小白鸟唱歌，它唱得可真好听！】"
  },
  [111800369] = {
    id = 111800369,
    name = "【你来书房一趟，带哥哥去喝下午茶好不好？】"
  },
  [111800370] = {
    id = 111800370,
    name = "【我知道了，哥哥，你又想偷懒，我才不会帮你呢，要是你又被罚了怎么办？】"
  },
  [111800371] = {
    id = 111800371,
    name = "【不会，我已经完成了今日的课业，只是不方便离开而已。拜托了，妹妹。】"
  },
  [111800372] = {
    id = 111800372,
    name = "【唔，哥哥有点可怜呢，那我就帮哥哥这一次，等我哦，很快就到！】"
  },
  [111800373] = {
    id = 111800373,
    name = "【好。】"
  },
  [111800374] = {id = 111800374, name = "主人？"},
  [111800375] = {
    id = 111800375,
    name = "你回过神，开始安排宴会的布防人员。"
  },
  [111800376] = {
    id = 111800376,
    name = "今日宾客就会逐一到来。总之，这件事就交给你了，务必部署到位。"
  },
  [111800377] = {id = 111800377, name = "是。"},
  [111800378] = {
    id = 111800378,
    name = "对了，尤其是东南角一定要严加防范，那个地方我的魔法陷阱总缺了一块，怎么也布置不好。"
  },
  [111800379] = {id = 111800379, name = "是。"},
  [111800380] = {
    id = 111800380,
    name = "这可是我全家的身家性命，你是我最相信的人了。"
  },
  [111800381] = {
    id = 111800381,
    name = "为主人死不足惜。"
  },
  [111800382] = {
    id = 111800382,
    name = "你摆了摆手，侍卫仍然站立不动。"
  },
  [111800383] = {
    id = 111800383,
    name = "主人的身边需要有人守护。"
  },
  [111800384] = {
    id = 111800384,
    name = "这是我家，不是深渊，要是我家都不安全，要你们去布防做什么？"
  },
  [111800385] = {id = 111800385, name = "哥哥！"},
  [111800386] = {
    id = 111800386,
    name = "柯莱特尔，你来做什么？"
  },
  [111800387] = {
    id = 111800387,
    name = "柯莱特尔错愕地眨了眨眼，瞬间反应了过来。"
  },
  [111800388] = {
    id = 111800388,
    name = "下午茶时间到了哦，哥哥快来呀！"
  },
  [111800389] = {
    id = 111800389,
    name = "好好，别拖我，我跟你走就是了。"
  },
  [111800390] = {
    id = 111800390,
    name = "你顺理成章地被柯莱特尔拉着离开了房间，挺拔的侍卫又重新消失在了阴影中。"
  },
  [111800391] = {id = 111800391, name = "......"},
  [111800392] = {
    id = 111800392,
    name = "少爷，小姐。今天的茶品是薰衣草、圣约翰草与玫瑰的混合红茶，中和了木质与果香的味道。"
  },
  [111800393] = {
    id = 111800393,
    name = "甜点有黑森林浆果制成的果酱塔，陶瓷奶油奶酪布丁和蜂蜜核桃蛋糕。"
  },
  [111800394] = {
    id = 111800394,
    name = "咸点是烤鹌鹑配肉桂、丁香与姜粉；烟熏鹿肉薄片，以及香草酱甜菜根。"
  },
  [111800395] = {
    id = 111800395,
    name = "另外为少爷与小姐准备了黑莓，可以搭配蜂蜜与肉桂粉食用。"
  },
  [111800396] = {id = 111800396, name = "......"},
  [111800397] = {
    id = 111800397,
    name = "（我总算是知道那些贵族瞧不上学院下午茶的原因了......）"
  },
  [111800398] = {
    id = 111800398,
    name = "哥哥，我想尝尝那个......"
  },
  [111800399] = {id = 111800399, name = "嗯？"},
  [111800400] = {
    id = 111800400,
    name = "就是那个......"
  },
  [111800401] = {
    id = 111800401,
    name = "呵呵，小姐说的是蜂蜜奶酒吧？上次不小心尝了一点少爷的，一直闹着要喝呢。"
  },
  [111800402] = {
    id = 111800402,
    name = "不行，小孩子不能喝酒。"
  },
  [111800403] = {id = 111800403, name = "哼。"},
  [111800404] = {
    id = 111800404,
    name = "柯莱特尔转过身，不理你了。"
  },
  [111800405] = {id = 111800405, name = "......"},
  [111800406] = {
    id = 111800406,
    name = "你忍住品尝美食的冲动，好说歹说，柯莱特尔却总是背过身不愿看你，你叹了口气。"
  },
  [111800407] = {
    id = 111800407,
    name = "酒是绝对不可以喝的，但哥哥可以答应你另外一件事行不行？"
  },
  [111800408] = {
    id = 111800408,
    name = "另外一件事？说话算话？"
  },
  [111800409] = {
    id = 111800409,
    name = "不能是喝酒这种小孩子不可以做的事。"
  },
  [111800410] = {
    id = 111800410,
    name = "听到这里，柯莱特尔转过了身。"
  },
  [111800411] = {
    id = 111800411,
    name = "那好吧，我要吃那个布丁。"
  },
  [111800412] = {
    id = 111800412,
    name = "你立刻把布丁放在了她的桌前，这时柯莱特尔慧黠一笑，端起布丁就砸向了你的脸。"
  },
  [111800413] = {id = 111800413, name = "......"},
  [111800414] = {
    id = 111800414,
    name = "哈哈哈哈！"
  },
  [111800415] = {
    id = 111800415,
    name = "你是躲得掉的，但闪避的一瞬间却停了下来，硬生生挨了一脸的奶油。柯莱特尔笑得甜点也不吃了，直在地上打滚。"
  },
  [111800416] = {
    id = 111800416,
    name = "呼，开心了？这就是你说的事，我做到了哦。"
  },
  [111800417] = {
    id = 111800417,
    name = "你接过仆人递来的毛巾，擦了半晌才擦干净。"
  },
  [111800418] = {
    id = 111800418,
    name = "不是哦，这可不是我的要求，是哥哥自己把布丁给我的。"
  },
  [111800419] = {
    id = 111800419,
    name = "（鬼灵精怪。）"
  },
  [111800420] = {
    id = 111800420,
    name = "那你想要我做什么？"
  },
  [111800421] = {
    id = 111800421,
    name = "哥哥帮我挑裙子呀！今晚宴会的裙子，我要哥哥帮我挑！"
  },
  [111800422] = {
    id = 111800422,
    name = "以往不都是母亲大人给你挑的吗？"
  },
  [111800423] = {
    id = 111800423,
    name = "她给我挑的又紧又难受，说要做什么乖乖的淑女，走几步路背上都疼死啦。"
  },
  [111800424] = {
    id = 111800424,
    name = "（难怪列蒂西雅总是从宴会逃走。）"
  },
  [111800425] = {
    id = 111800425,
    name = "你要我做的就是这件事？"
  },
  [111800426] = {id = 111800426, name = "对呀。"},
  [111800427] = {
    id = 111800427,
    name = "好，喝完下午茶，我们就去吧。"
  },
  [111800428] = {id = 111800428, name = "好耶！"},
  [111800429] = {
    id = 111800429,
    name = "不过你也答应我一件事好不好？"
  },
  [111800430] = {id = 111800430, name = "嗯？"},
  [111800431] = {
    id = 111800431,
    name = "今晚宴会的时候，跟好哥哥，不要乱跑。"
  },
  [111800432] = {
    id = 111800432,
    name = "嘻嘻，哥哥每次都这么说。"
  },
  [111800433] = {id = 111800433, name = "？？？"},
  [111800434] = {
    id = 111800434,
    name = "哥哥放心，我一定牵紧你，你就好好带着我去炫耀一番，让他们看看我有多可爱！"
  },
  [111800435] = {id = 111800435, name = "......"},
  [111800436] = {
    id = 111800436,
    name = "（原来你们是如此自信的兄妹。）"
  },
  [111800437] = {
    id = 111800437,
    name = "你在柯莱特尔的笑容里咬下了一口果酱塔。"
  },
  [111800438] = {
    id = 111800438,
    name = "（啧，有点太甜了。）"
  },
  [111800439] = {
    id = 111800439,
    name = "夕阳的余晖渐渐淡去，城堡在暮色中迎来了灯火。"
  },
  [111800440] = {
    id = 111800440,
    name = "宴会厅内灯火辉煌，烛光摇曳，映照出金碧辉煌的装饰，宾客们身着华丽的服饰，妆容精致，步履轻盈地步入宴会厅。"
  },
  [111800441] = {
    id = 111800441,
    name = "哥哥，她们的裙子都没有我的好看。"
  },
  [111800442] = {
    id = 111800442,
    name = "嘘，这种话放在心里说就好了。"
  },
  [111800443] = {
    id = 111800443,
    name = "【这种闹哄哄的场合，谁会听见呀。】"
  },
  [111800444] = {
    id = 111800444,
    name = "正经点。"
  },
  [111800445] = {
    id = 111800445,
    name = "是，父亲大人。"
  },
  [111800446] = {
    id = 111800446,
    name = "柯莱特尔朝你吐了吐舌头，你无奈地笑笑，牵着她跟在普尔兰伯爵与夫人身后，走上主宾席前的舞台，在伯爵一段欢迎说辞后，宴会正式开始了。"
  },
  [111800447] = {
    id = 111800447,
    name = "乐师们奏响了悠扬的乐曲，贵族们围坐在长桌旁，开始享用这场视觉与味觉的双重盛宴。他们或轻声交谈，讨论着时下流行的风尚与文学艺术作品，默契地不谈风雨飘摇的帝国根基。"
  },
  [111800448] = {
    id = 111800448,
    name = "你一边听着众人的谈论，一边享用着珍馐美味。"
  },
  [111800449] = {
    id = 111800449,
    name = "（就算是幻境，这种从未有过的体验也真不错啊。）"
  },
  [111800450] = {
    id = 111800450,
    name = "别躲在这里了，好好去跟你的几个叔父说说话，另外德温特教授的孙女也来了，你们年轻人也多交流交流。"
  },
  [111800451] = {
    id = 111800451,
    name = "......是，父亲大人。"
  },
  [111800452] = {
    id = 111800452,
    name = "【可怜的哥哥。】"
  },
  [111800453] = {
    id = 111800453,
    name = "你回头看一眼柯莱特尔，提醒她别到处乱走，她朝你举了一杯草莓汁，学大人喝酒一般朝你喝了一口，你没好气地走向舞池。"
  },
  [111800454] = {
    id = 111800454,
    name = "你晃了一圈，都是“你”似乎见过的面孔，每个人都有些熟悉，但与名字无法匹配。"
  },
  [111800455] = {
    id = 111800455,
    name = "（啊，完全记不得那个德温特小姐的模样......）"
  },
  [111800456] = {
    id = 111800456,
    name = "正当一曲结束，宾客们心满意足地离开舞池时，你看到几名侍从不自在的脸。"
  },
  [111800457] = {
    id = 111800457,
    name = "时间差不多了。"
  },
  [111800458] = {
    id = 111800458,
    name = "你将杯中的美酒饮尽，然后，松开了手。"
  },
  [111800459] = {
    id = 111800459,
    name = "啪！玻璃碎裂，接着，宴会厅的大门被猛然推开！"
  },
  [111800460] = {
    id = 111800460,
    name = "几个杀气腾腾的不速之客冲了进来。虽然记不住人脸，但你认得那群人身上的花纹，的确是诺瓦克家族。"
  },
  [111800461] = {
    id = 111800461,
    name = "他们一进来就打碎了一座香槟塔，清脆尖锐的声音响彻宴会厅，众人那一瞬都安静了下来。"
  },
  [111800462] = {
    id = 111800462,
    name = "（看来，这就是破局的关键。）"
  },
  [111800463] = {
    id = 111800463,
    name = "诸位贵宾不要慌乱，这几位似乎有重要的事跟我们说，大家先到楼上暂时休息。"
  },
  [111800464] = {
    id = 111800464,
    name = "由于你太过镇定，场上的宾客都被你这句话安抚了，正打算一一离开时，一个阴恻恻的声音在冷笑，冰冷的锐器放在了你的脖颈。"
  },
  [111800465] = {
    id = 111800465,
    name = "谁也跑不了，今晚，你们全部都要死。"
  },
  [111800466] = {id = 111800466, name = "是你。"},
  [111800467] = {
    id = 111800467,
    name = "不错，普尔兰少爷。很可惜，你信错了人。这里里外外都是我们的人。"
  },
  [111800468] = {
    id = 111800468,
    name = "普尔兰伯爵和夫人紧张地看着你，你扫视了一圈，竟然没有看到柯莱特尔。"
  },
  [111800469] = {
    id = 111800469,
    name = "【妹妹？】"
  },
  [111800470] = {
    id = 111800470,
    name = "【柯莱特尔？】"
  },
  [111800471] = {
    id = 111800471,
    name = "柯莱特尔没有回应，你心中有不太好的感觉。"
  },
  [111800472] = {
    id = 111800472,
    name = "呵呵，少爷已经吓傻了，大家别藏了，都出来吧！"
  },
  [111800473] = {
    id = 111800473,
    name = "宾客们左右相顾，除了那几个面有异色的侍从，再也没有其他人出现。"
  },
  [111800474] = {
    id = 111800474,
    name = "人呢？！"
  },
  [111800475] = {
    id = 111800475,
    name = "氛围凝固了一瞬，侍卫抓紧了武器，惊慌地在你脖子上留下一道血迹。"
  },
  [111800476] = {
    id = 111800476,
    name = "你做了什么？！"
  },
  [111800477] = {
    id = 111800477,
    name = "他们进不来的，都在陷阱里吧。说起来，应该是你邀请他们进入的，我猜猜，是不是防守“薄弱”的东南角？"
  },
  [111800478] = {
    id = 111800478,
    name = "你骗我？！我弄死你！"
  },
  [111800479] = {
    id = 111800479,
    name = "短剑即将划破肌肤的那一刻，你猛地一侧身，抓住他的手腕，将短剑的方向巧妙地偏移开来，避免了致命的威胁同时，也卸掉了他的武器，抓在了手中。"
  },
  [111800480] = {
    id = 111800480,
    name = "怎么可能！我一刻不停地在监视你，你不过是个只会偷懒的废物！！"
  },
  [111800481] = {
    id = 111800481,
    name = "也许吧。"
  },
  [111800482] = {
    id = 111800482,
    name = "你眼中露出一丝狠绝，心中涌起一股直觉——如果不解决一切，将会给家族带来无尽的麻烦和威胁，而你，也永远会滞留在这片虚无之地。"
  },
  [111800483] = {
    id = 111800483,
    name = "侍卫见行事彻底失利，脸色大变，忙施展魔法，准备逃进影子里。"
  },
  [111800484] = {
    id = 111800484,
    name = "逃不了的。"
  },
  [111800485] = {
    id = 111800485,
    name = "你翻身一剑插入阴影中，一股光束冲天而起！光与暗在空中碰撞、激荡，发出耀眼的光芒和震耳欲聋的轰鸣。"
  },
  [111800486] = {
    id = 111800486,
    name = "啊啊啊啊！"
  },
  [111800487] = {
    id = 111800487,
    name = "在绝望的挣扎中，他只能眼睁睁地看着自己的身体被一股无形的力量撕裂、吞噬，最终化为一缕青烟，消散在宴会厅的空气中。"
  },
  [111800488] = {
    id = 111800488,
    name = "这一幕让在场的所有人都震惊不已，而这段时间，管家已带来了忠心的侍卫，将背叛家族的人团团围住。"
  },
  [111800489] = {
    id = 111800489,
    name = "所有的不轨者都被押出了宴会厅，而散乱的大厅也重新布置一新，你惊叹仆从们的收拾速度和宾客们的强装镇定，真不愧是见多识广的贵族。"
  },
  [111800490] = {
    id = 111800490,
    name = "让诸位受惊了，这件小事已经解决，大家可以继续这场宴会，不用拘礼。"
  },
  [111800491] = {
    id = 111800491,
    name = "普尔兰伯爵示意宴会继续，音乐再起响起，你见普尔兰夫人朝你笑了笑，又混入了贵妇群中谈笑风生，心里不禁感叹他们面不改色的心理素质。"
  },
  [111800492] = {
    id = 111800492,
    name = "干得不错。"
  },
  [111800493] = {
    id = 111800493,
    name = "普尔兰伯爵走到了你身边，你甚至在他眼中看到了自豪的光。"
  },
  [111800494] = {
    id = 111800494,
    name = "（......那种看废物的眼神不见了。）"
  },
  [111800495] = {
    id = 111800495,
    name = "你是怎么阻止他们会在宴会上行事的？"
  },
  [111800496] = {
    id = 111800496,
    name = "多亏了管家。"
  },
  [111800497] = {
    id = 111800497,
    name = "你将两天发现的线索总结告诉了普尔兰伯爵。"
  },
  [111800498] = {
    id = 111800498,
    name = "管家无意中发现了诺瓦克家族的刺杀行动，来不及告诉外出的伯爵。而你身边随时跟着可疑的侍卫，也不知道庄园中还有多少其他势力的人。他只能以留书信的方式，给你留下关键的信息。"
  },
  [111800499] = {
    id = 111800499,
    name = "你阅览管家为你准备的书籍，梳理了一大批可能的人，并告诉侍卫“东南角”有破绽。"
  },
  [111800500] = {
    id = 111800500,
    name = "他们打算在宴会开始后，大家都松懈的时候再闯入宴会，大开杀戒。"
  },
  [111800501] = {
    id = 111800501,
    name = "可没想到的是，大批杀手已经在进入的那一刻，就掉入你布置的魔法阵中，伤亡惨重，只有零散撞门的几个，不足为惧。"
  },
  [111800502] = {
    id = 111800502,
    name = "少爷足智多谋，胆识过人，才能让主家完好无损地度过这一次危机啊。"
  },
  [111800503] = {
    id = 111800503,
    name = "普尔兰伯爵也赞同地点点头。"
  },
  [111800504] = {
    id = 111800504,
    name = "嗯，你长大了。"
  },
  [111800505] = {
    id = 111800505,
    name = "这都是父亲大人的教导。"
  },
  [111800506] = {
    id = 111800506,
    name = "你有些尴尬地笑了笑。"
  },
  [111800507] = {
    id = 111800507,
    name = "音乐的节奏似乎到了高潮，女士们的裙摆旋转、跳跃，飞扬，热烈又不失文雅，本是一场美好欢乐的宴会，却让你始终不安，总觉得少了些什么。"
  },
  [111800508] = {
    id = 111800508,
    name = "（对了，柯莱特尔！）"
  },
  [111800509] = {
    id = 111800509,
    name = "【妹妹！你在吗？柯莱特尔！】"
  },
  [111800510] = {
    id = 111800510,
    name = "还是没有回应。"
  },
  [111800511] = {
    id = 111800511,
    name = "父亲大人，柯莱特尔不见了！"
  },
  [111800512] = {
    id = 111800512,
    name = "怎么回事？！"
  },
  [111800513] = {
    id = 111800513,
    name = "小姐刚刚还在这里，怎么......"
  },
  [111800514] = {
    id = 111800514,
    name = "刚才抓的那些人里，难道还有漏网之鱼？！"
  },
  [111800515] = {
    id = 111800515,
    name = "主人放心，城堡已经被封锁了，没有人可以逃出去。"
  },
  [111800516] = {
    id = 111800516,
    name = "加派人手去找，无论如何都要找到柯莱特尔！"
  },
  [111800517] = {
    id = 111800517,
    name = "嘈杂的音乐让你此刻的心情突然变得混乱不堪，你不知道是先思考怎么破局离开幻境，还是先找到柯莱特尔。"
  },
  [111800518] = {
    id = 111800518,
    name = "（明明，一切都是假的啊......为什么还要被她牵动情绪......）"
  },
  [111800519] = {
    id = 111800519,
    name = "【......哥哥！！】"
  },
  [111800520] = {
    id = 111800520,
    name = "你猛然听到了一声哭喊，带着难以言喻的绝望与恐惧。"
  },
  [111800521] = {
    id = 111800521,
    name = "【哥哥，救我啊啊啊！！】"
  },
  [111800522] = {
    id = 111800522,
    name = "【柯莱特尔！你在哪里！】"
  },
  [111800523] = {
    id = 111800523,
    name = "【我不知道，我不知道，这里好黑！！】"
  },
  [111800524] = {
    id = 111800524,
    name = "【哥哥，你在哪里，我好冷，这里好湿，你快来救我啊！！】"
  },
  [111800525] = {
    id = 111800525,
    name = "你霍然冲出了宴会厅，心底却以最温柔的语气，安抚着柯莱特尔。"
  },
  [111800526] = {
    id = 111800526,
    name = "【别怕，我来找你了。】"
  },
  [111800527] = {
    id = 111800527,
    name = "你离开宴会厅时，外面的月亮消失了。夏夜的雨说来便来，毫无预兆地冲刷而下。"
  },
  [111800528] = {
    id = 111800528,
    name = "【啊啊啊！】"
  },
  [111800529] = {
    id = 111800529,
    name = "【妹妹，你怎么了？！】"
  },
  [111800530] = {
    id = 111800530,
    name = "【有什么活的东西，从我身上跑过去了！】"
  },
  [111800531] = {
    id = 111800531,
    name = "你脚步一顿，立刻冷静了下来。"
  },
  [111800532] = {
    id = 111800532,
    name = "【你先别慌，仔细听周围的声音，告诉我。】"
  },
  [111800533] = {
    id = 111800533,
    name = "【我......我什么都听不见，呜呜呜，哥哥，我好害怕......呜呜呜......】"
  },
  [111800534] = {
    id = 111800534,
    name = "柯莱特尔听起来快崩溃了，你仿佛听到了幼兽无力地哀鸣。"
  },
  [111800535] = {
    id = 111800535,
    name = "【别着急，柯莱特尔，你是普尔兰家族的小女儿，不要露出怯懦的姿态让坏人看到嘲笑你，哥哥相信，你会像父亲大人一样勇敢的。来跟我念：我是普尔兰的骄傲与荣耀！】"
  },
  [111800536] = {
    id = 111800536,
    name = "【我......我......我是普尔兰家族的小女儿，我不能露出怯懦的姿态，我要像父亲和哥哥一样勇敢！我是普尔兰的骄傲与荣耀，我是普尔兰的骄傲与荣耀，我是普尔兰的骄傲与荣耀......】"
  },
  [111800537] = {
    id = 111800537,
    name = "柯莱特尔学着跟你念了起来，一开始颤抖的声音逐渐变得平和，而在此期间，你把附近角落的黑暗处都找遍了。"
  },
  [111800538] = {
    id = 111800538,
    name = "【柯莱特尔，还害怕吗？】"
  },
  [111800539] = {
    id = 111800539,
    name = "【不怕了。我是普尔兰的骄傲与荣耀，我不能害怕。】【哥哥，你怎么还没找到我......】"
  },
  [111800540] = {
    id = 111800540,
    name = "【你现在告诉我，你能听到什么吗？】"
  },
  [111800541] = {
    id = 111800541,
    name = "【......很......很奇怪的声音。】"
  },
  [111800542] = {
    id = 111800542,
    name = "【奇怪？关着你的地方很小吗？衣柜？箱子？】"
  },
  [111800543] = {
    id = 111800543,
    name = "【不，我摸不到周围的东西，地上有水。那个声音，一会儿有，一会儿又消失了......啊，出现了！吱吱......呀呀......】"
  },
  [111800544] = {
    id = 111800544,
    name = "（奇怪的声音......水，是地下牢房！）"
  },
  [111800545] = {
    id = 111800545,
    name = "你曾在地下牢房中，也听到过奇怪的声音，那里一片漆黑，你无法判断那是什么东西制造出的声响，只会让人在黑暗中无限恐惧，心里崩塌......"
  },
  [111800546] = {
    id = 111800546,
    name = "脑中闪过那个向你表达忠心的仆人，你回想这次宴会，他并没有和往常一样跟在你身后。"
  },
  [111800547] = {
    id = 111800547,
    name = "【柯莱特尔，我想我知道你在哪儿了，等我。】"
  },
  [111800548] = {
    id = 111800548,
    name = "【真的吗！我在这里乖乖等哥哥！】"
  },
  [111800549] = {
    id = 111800549,
    name = "你在雨中奔跑。城堡很大，就算不停歇地奔跑，现在也还剩三分之二的距离。"
  },
  [111800550] = {
    id = 111800550,
    name = "普尔兰是诺维奇帝国赫赫有名的家族，所属的领地堪比其余贵族的好几倍，难免遭遇嫉妒与不满，这次的刺杀安排不像试探，更像是灭门的手段。"
  },
  [111800551] = {
    id = 111800551,
    name = "【对不起，柯莱特尔，是我疏忽了。】"
  },
  [111800552] = {
    id = 111800552,
    name = "你很清楚，是你轻视了对手。轻视的原因，不是小看对手，而是不太在意。"
  },
  [111800553] = {
    id = 111800553,
    name = "比起如何解决宴会的危机，你更在乎的是，该如何离开这个幻境。你将自己划作了局外的人，虽然更清楚地掌握了整个局势的发展，但也忽略了应该在意的人。"
  },
  [111800554] = {
    id = 111800554,
    name = "【哥哥，你没有错哦，是我没有听你的话，我应该一直牵着你。】"
  },
  [111800555] = {
    id = 111800555,
    name = "【你是怎么到那个地方的？】"
  },
  [111800556] = {
    id = 111800556,
    name = "【我不知道，我醒来就在这里了......】"
  },
  [111800557] = {
    id = 111800557,
    name = "【那苏醒之前呢？】"
  },
  [111800558] = {
    id = 111800558,
    name = "【我喝了你的仆人递给我的一杯草莓汁，后来就什么都不知道了。】"
  },
  [111800559] = {
    id = 111800559,
    name = "（那个仆人果然有问题。）"
  },
  [111800560] = {
    id = 111800560,
    name = "你跑到了一处花园，要绕过很大一圈才能到出口的那方，你毫不犹豫踏上泥泞的草坪，穿过花圃，脆弱的鲜花被碾出一片嫣红。"
  },
  [111800561] = {
    id = 111800561,
    name = "【妹妹，怎么不说话了，你还好吗？】"
  },
  [111800562] = {
    id = 111800562,
    name = "【嗯......还是不说了......我怕把吊坠的魔法力用完，你就找不到我了。】"
  },
  [111800563] = {
    id = 111800563,
    name = "你心中一疼，轻声回答。"
  },
  [111800564] = {
    id = 111800564,
    name = "【不会的。我说过，只要你呼唤我，我就一定能找到你。】"
  },
  [111800565] = {
    id = 111800565,
    name = "【......哥哥，我好冷啊。】"
  },
  [111800566] = {
    id = 111800566,
    name = "【我很快就到了！】"
  },
  [111800567] = {
    id = 111800567,
    name = "你停在了地下牢房的门口。"
  },
  [111800568] = {
    id = 111800568,
    name = "地牢的门口有一口井，现在有好几个人正冒着雨从井里打捞金币。"
  },
  [111800569] = {
    id = 111800569,
    name = "是的，金币。麻绳的一端系着一只沉重的木桶，正缓缓降入井中，发出“吱吱呀呀”的声响。"
  },
  [111800570] = {
    id = 111800570,
    name = "而在旁边指挥的，正是那个发誓永不背叛的仆人。"
  },
  [111800571] = {
    id = 111800571,
    name = "藏得真多啊。"
  },
  [111800572] = {
    id = 111800572,
    name = "大雨浇落到你的脸上，你朝他们露出了一个冰冷的笑。"
  },
  [111800573] = {
    id = 111800573,
    name = "仆人猛然转身，脸色惨白，双腿不由自主地发抖。他试图辩解，但喉咙却像被什么堵住了一般，发不出半点声音。"
  },
  [111800574] = {
    id = 111800574,
    name = "我早就说过，希望女神管不了地狱，你的誓言，我不信的。"
  },
  [111800575] = {
    id = 111800575,
    name = "主人！我没有背叛您！您听我说！诺瓦克的阴谋我没参加，我、我是想为您保住这些财富，才出此下策，我——"
  },
  [111800576] = {
    id = 111800576,
    name = "黑暗中剑光弯月般地掠下，鲜血从仆人咽喉中喷溅而出，他向后摔进泥泞里。"
  },
  [111800577] = {
    id = 111800577,
    name = "我不想听，也没时间听。绑架柯莱特尔的，都是普尔兰的背叛者。"
  },
  [111800578] = {
    id = 111800578,
    name = "背叛者，永远只有一个下场。"
  },
  [111800579] = {
    id = 111800579,
    name = "几乎在同一时间，打捞金币的几个人丢下木桶跑得飞快，你将剑扔了出去，又扔出了几个魔法，很快他们都与泥浆融为了一体。"
  },
  [111800580] = {
    id = 111800580,
    name = "【......哥哥，是你在外面吗？我好像听到你的声音了。】"
  },
  [111800581] = {
    id = 111800581,
    name = "【是我，妹妹。】"
  },
  [111800582] = {
    id = 111800582,
    name = "你踹开了平日里避如蛇蝎的大门，径直朝里走去，在一片漆黑处站定，正想打个聚光的魔法，就听到了柯莱特尔的声音。"
  },
  [111800583] = {
    id = 111800583,
    name = "哥哥！我在这里！"
  },
  [111800584] = {
    id = 111800584,
    name = "也许是门外带来的光亮，柯莱特尔的脚步声匆匆地朝你靠近。"
  },
  [111800585] = {id = 111800585, name = "你——"},
  [111800586] = {
    id = 111800586,
    name = "你被她一把抱住了，胸前一股暖暖的绒毛，如同捡到了被遗弃在荒野的小猫。你心中一暖，彻底放下了心。"
  },
  [111800587] = {
    id = 111800587,
    name = "找到你了。"
  },
  [111800588] = {id = 111800588, name = "......"},
  [111800589] = {
    id = 111800589,
    name = "你牵着柯莱特尔回到了地牢门口，在漫天的雨势里，柯莱特尔发现了躺在雨中的尸体。"
  },
  [111800590] = {
    id = 111800590,
    name = "仆人的身体在泥浆里沉沉浮浮，身边散落着发光的金币。"
  },
  [111800591] = {
    id = 111800591,
    name = "坏人死了吗？"
  },
  [111800592] = {
    id = 111800592,
    name = "嗯，都死了，你安全了，别怕。"
  },
  [111800593] = {
    id = 111800593,
    name = "爸爸妈妈呢？"
  },
  [111800594] = {
    id = 111800594,
    name = "他们都没事，在等你回家。"
  },
  [111800595] = {
    id = 111800595,
    name = "柯莱特尔笑了，你却在她眼中看到了泪花。"
  },
  [111800596] = {
    id = 111800596,
    name = "他们不会死了对不对？"
  },
  [111800597] = {
    id = 111800597,
    name = "当然不会。"
  },
  [111800598] = {
    id = 111800598,
    name = "哥哥也不会死了是不是？"
  },
  [111800599] = {
    id = 111800599,
    name = "我不是好端端在你面前吗？"
  },
  [111800600] = {
    id = 111800600,
    name = "柯莱特尔仍然朝你笑着，眼泪却在不停地滚落。"
  },
  [111800601] = {
    id = 111800601,
    name = "怎么了，柯莱特尔？"
  },
  [111800602] = {
    id = 111800602,
    name = "哥哥，那我们和爸爸妈妈永远在一起好不好？"
  },
  [111800603] = {
    id = 111800603,
    name = "柯莱特尔的身后出现了一道空间裂痕，如同一个密封的箱子，被剑锋扎出了一道天光。"
  },
  [111800604] = {
    id = 111800604,
    name = "......对不起，柯莱特尔。"
  },
  [111800605] = {
    id = 111800605,
    name = "你明白了，这是幻境即将破裂的征兆。"
  },
  [111800606] = {
    id = 111800606,
    name = "（这个家很好。出身高贵，生活优渥，有一个即将将领主交予自己的父亲，还有一个无比聪慧可爱的妹妹，也许很多人的一生追求也不过如此了。）"
  },
  [111800607] = {
    id = 111800607,
    name = "（可我有同伴，有无数的回忆和羁绊，也有属于自己的人生。）"
  },
  [111800608] = {
    id = 111800608,
    name = "（我不是普尔兰少爷，我是探险者，我要回到真实的地方，那才是我的世界。所以......）"
  },
  [111800609] = {
    id = 111800609,
    name = "对不起，柯莱特尔，我该走了。"
  },
  [111800610] = {id = 111800610, name = "哥哥！"},
  [111800611] = {
    id = 111800611,
    name = "柯莱特尔死死地抓住了你的衣角，她睁大眼睛看着你，似乎想把你牢牢记在心中。"
  },
  [111800612] = {
    id = 111800612,
    name = "就在你以为她会说些挽留的话时，她却露出了释然和悲伤的笑容。"
  },
  [111800613] = {
    id = 111800613,
    name = "谢谢你，哥哥。"
  },
  [111800614] = {
    id = 111800614,
    name = "谢谢你，给我的这一场美好的梦。"
  },
  [111800615] = {
    id = 111800615,
    name = "咔嚓——"
  },
  [111800616] = {
    id = 111800616,
    name = "天际仿佛被无形的巨手猛然撕开，光明与黑暗在这一刻变得扭曲而狂乱。"
  },
  [111800617] = {
    id = 111800617,
    name = "四周的空间崩塌成碎片，如琉璃般下落，在虚空中旋转、消散，直到世间只剩下了你与柯莱特尔......"
  },
  [111800618] = {
    id = 111800618,
    name = "然后，你睁开了眼睛。"
  },
  [111800619] = {
    id = 111800619,
    name = "醒了，醒了！"
  },
  [111800620] = {
    id = 111800620,
    name = "老师，你怎么样？还好吗？"
  },
  [111800621] = {
    id = 111800621,
    name = "他怎么没反应？那个药是不是有什么后遗症？"
  },
  [111800622] = {
    id = 111800622,
    name = "不可能，我老师的药剂，绝对不可能出问题！"
  },
  [111800623] = {
    id = 111800623,
    name = "我们当然相信维克多大师，只是怕在计量上......"
  },
  [111800624] = {
    id = 111800624,
    name = "你一睁眼就看着四五个脑袋围着你转，左一句右一句的吵闹，本来头疼的脑子更晕了，索性又闭上了眼。"
  },
  [111800625] = {
    id = 111800625,
    name = "哎呀！队长又晕过去了！"
  },
  [111800626] = {
    id = 111800626,
    name = "都说了等等，你们着什么急！我先去看看吉米啊，有事再叫我。"
  },
  [111800627] = {
    id = 111800627,
    name = "你闭着眼听见弗拉克的声音，年纪并不大，脚步也很轻快。"
  },
  [111800628] = {
    id = 111800628,
    name = "鬼侍小姐，你醒了。"
  },
  [111800629] = {id = 111800629, name = "嗯。"},
  [111800630] = {
    id = 111800630,
    name = "有没有哪里不舒服？"
  },
  [111800631] = {id = 111800631, name = "没有。"},
  [111800632] = {
    id = 111800632,
    name = "听着冷淡地回答，你忽然想起，失去意识前，你还将她护在了身下。"
  },
  [111800633] = {
    id = 111800633,
    name = "（怎么，她也晕过去了吗？听声音，其他人好像没事......）"
  },
  [111800634] = {
    id = 111800634,
    name = "你嘴里蔓延着微苦的药剂，很快头疼也逐渐缓解了过来，你重新睁开了眼睛。"
  },
  [111800635] = {
    id = 111800635,
    name = "这次看起来正常了。"
  },
  [111800636] = {
    id = 111800636,
    name = "老师，太好了，你没事。"
  },
  [111800637] = {
    id = 111800637,
    name = "这里是？"
  },
  [111800638] = {
    id = 111800638,
    name = "我们在维克多大师的家里，不过他不在，是他的弟子弗拉克救了你和鬼侍。"
  },
  [111800639] = {
    id = 111800639,
    name = "还记得吗，来我们学院给我们上过课的维克多大师。"
  },
  [111800640] = {
    id = 111800640,
    name = "嗯，是那个有名的技术大师。"
  },
  [111800641] = {
    id = 111800641,
    name = "当时菲尼斯提出建议的时候，我还纳闷呢，你和鬼侍看起来是中了某个魔法诅咒，怎么不去找言灵，反而来找技术大师。"
  },
  [111800642] = {
    id = 111800642,
    name = "是我们孤陋寡闻了，没想到维克多的弟子真的有解开诅咒的能力。"
  },
  [111800643] = {
    id = 111800643,
    name = "老师，你现在感觉怎么样？"
  },
  [111800644] = {
    id = 111800644,
    name = "放心，已经没事了。"
  },
  [111800645] = {
    id = 111800645,
    name = "你朝众人笑笑，忽然察觉到了一道目光。看过去的时候，鬼侍僵滞了一下，只是一瞬，她就移开了眼。"
  },
  [111800646] = {
    id = 111800646,
    name = "啊，都醒了啊。"
  },
  [111800647] = {
    id = 111800647,
    name = "房间里走出了一个少年，看起来只有十三四岁，他手上拿着一只不停挥动翅膀的金属球。"
  },
  [111800648] = {
    id = 111800648,
    name = "你是......维克多大师的弟子？"
  },
  [111800649] = {
    id = 111800649,
    name = "没错，我叫弗拉克！别总叫我维克多的弟子，我还没有师父那么厉害。呜哇，吉米！"
  },
  [111800650] = {
    id = 111800650,
    name = "他手里的金属球突然挣脱，又被他抓了回去。"
  },
  [111800651] = {
    id = 111800651,
    name = "这是我自己做的魔偶，它叫吉米！来，吉米，给他们打个招呼！"
  },
  [111800652] = {
    id = 111800652,
    name = "“喀嚓”金属球的翅膀停下来，缩成了一团，一动不动。"
  },
  [111800653] = {
    id = 111800653,
    name = "别害羞，他们是给你找材料的人，喂！"
  },
  [111800654] = {
    id = 111800654,
    name = "金属球一头冲向里面的房间，弗拉克挪脚踩了踩脚边的机关，“嘭！”大门关闭，吉米整个球撞在门上，在地上滚了两圈，不动了。"
  },
  [111800655] = {
    id = 111800655,
    name = "不好意思，吉米有点怕生。"
  },
  [111800656] = {id = 111800656, name = "......"},
  [111800657] = {
    id = 111800657,
    name = "呃呵呵呵。"
  },
  [111800658] = {
    id = 111800658,
    name = "（小声）安妮斯，你说他脑子是不是有点问题，把魔偶当人呢。"
  },
  [111800659] = {id = 111800659, name = "......"},
  [111800660] = {
    id = 111800660,
    name = "你是傀儡师？"
  },
  [111800661] = {
    id = 111800661,
    name = "操控魔偶的言灵通常被称之为傀儡师，但你看那个奇奇怪怪的金属球，怎么也不是正常魔偶的样子。"
  },
  [111800662] = {
    id = 111800662,
    name = "嗯，虽然大家都这么说，但我不认为吉米是我的傀儡魔偶，它可是我最好的朋友！"
  },
  [111800663] = {
    id = 111800663,
    name = "说起来这次多亏了弗拉克，是他用维克多大师的药剂救了队长，所以，我们也替队长答应了他的合理要求。"
  },
  [111800664] = {
    id = 111800664,
    name = "你瞧着似笑非笑的菲尼斯，总觉得有个坑在等着你跳，决定转移话题。"
  },
  [111800665] = {
    id = 111800665,
    name = "这样啊，那真的很谢谢你们。"
  },
  [111800666] = {
    id = 111800666,
    name = "说起来，我们找到的那面镜子呢？"
  },
  [111800667] = {
    id = 111800667,
    name = "碎掉啦，在你们昏迷之后，我们收起来去检验过，什么都看不出来。"
  },
  [111800668] = {
    id = 111800668,
    name = "那个宝物里的力量，应该在破碎的时候进入到你们的身体里了，才产生了副作用让你们昏迷不醒。"
  },
  [111800669] = {
    id = 111800669,
    name = "由于我擅长的是机械不是魔法，只能通过解析血液找到解决的办法，还好师父给我留了解除特殊魔法的药剂，算你们运气不错。"
  },
  [111800670] = {
    id = 111800670,
    name = "哦，对了，你们昏迷之后，有没有看到什么东西？比如说梦境，幻境，或者一系列不真实的场景？"
  },
  [111800671] = {
    id = 111800671,
    name = "鬼侍不自然地皱了皱眉，你感觉到她全身绷紧了，似乎十分紧张。"
  },
  [111800672] = {
    id = 111800672,
    name = "梦境？幻境？问这个做什么？"
  },
  [111800673] = {
    id = 111800673,
    name = "我好做研究啊！这是我一直思考的问题，如果能把对应的魔法和结构动力用在吉米身上，它也许有一天就能跟我好好交流了啊！"
  },
  [111800674] = {id = 111800674, name = "......"},
  [111800675] = {
    id = 111800675,
    name = "你突然有些赞同尼莉莎的话，年纪小小的，怎么脑子就出了问题。"
  },
  [111800676] = {
    id = 111800676,
    name = "不过你这么回答，那就是见到了，快跟我说说，你看到了什么？"
  },
  [111800677] = {
    id = 111800677,
    name = "唔，只是一场美梦而已。"
  },
  [111800678] = {
    id = 111800678,
    name = "你不愿多说，那不是你的人生。但此刻回想起来，却仍然觉得温暖。"
  },
  [111800679] = {
    id = 111800679,
    name = "那你呢，你有看到什么吗？"
  },
  [111800680] = {
    id = 111800680,
    name = "弗拉克看向了你旁边的鬼侍。"
  },
  [111800681] = {
    id = 111800681,
    name = "......我不记得了。"
  },
  [111800682] = {
    id = 111800682,
    name = "鬼侍起身就要离开，另一处机关被弗拉克随手一拉，大门“嘭”地关上了。"
  },
  [111800683] = {
    id = 111800683,
    name = "在交易没完成之前，你们不能走哦。"
  },
  [111800684] = {
    id = 111800684,
    name = "（小声）菲尼斯，你答应了他什么？"
  },
  [111800685] = {
    id = 111800685,
    name = "队长，原谅我病急乱投医，但至少你醒了不是吗？"
  },
  [111800686] = {
    id = 111800686,
    name = "你要我做什么？"
  },
  [111800687] = {
    id = 111800687,
    name = "你的朋友说，只要能把你们救醒，就答应我的要求。"
  },
  [111800688] = {
    id = 111800688,
    name = "现在，是承诺应该兑现的时候啦。"
  },
  [111800689] = {
    id = 111800689,
    name = "我的要求很简单：帮我找到升级吉米的材料，我这里有一份材料单。对你们几个来说，应该很容易吧？"
  },
  [111800690] = {
    id = 111800690,
    name = "（嗯，这不算什么难事。）"
  },
  [111800691] = {
    id = 111800691,
    name = "鬼侍扫了一眼单子上的材料，立刻朝门口走去。"
  },
  [111800692] = {
    id = 111800692,
    name = "喂喂，你不是打算白喝了我师父的药剂吧？"
  },
  [111800693] = {
    id = 111800693,
    name = "不是说要找材料吗？"
  },
  [111800694] = {
    id = 111800694,
    name = "鬼侍侧过脸，似乎竭力隐藏了某种情绪，淡然地看向了你。"
  },
  [111800695] = {
    id = 111800695,
    name = "那就一起吧。"
  },
  [111690001] = {
    id = 111690001,
    name = "你与同伴们扎好了临时营地，安妮斯布置驱魔粉守着营地，尼莉莎与蒂娜去拾捡柴火，你和菲尼斯出来狩猎。"
  },
  [111690002] = {
    id = 111690002,
    name = "走了这么半天也没看见一个能吃的魔物，不对，是没看见一个猎物。"
  },
  [111690003] = {
    id = 111690003,
    name = "也许这附近有其他的探险者。"
  },
  [111690004] = {
    id = 111690004,
    name = "噢，被捷足先登了啊。"
  },
  [111690005] = {
    id = 111690005,
    name = "再找找看吧，实在不行就吃干粮。"
  },
  [111690006] = {
    id = 111690006,
    name = "虽然那些虫子和干柴的魔物肉口感很差，但我更不想啃硬得像石头一样的面包。"
  },
  [111690007] = {
    id = 111690007,
    name = "不远处有声响传来，你们同时看了过去，几名看不清容貌的黑衣人拉着两辆破旧的木车，挂着某个商队的标志。"
  },
  [111690008] = {id = 111690008, name = "商队？"},
  [111690009] = {
    id = 111690009,
    name = "不，你仔细看！"
  },
  [111690010] = {
    id = 111690010,
    name = "那些车上，躺着许多人，他们横七竖八地倒在车里，和货物装在一起，有的受了伤，明显失去了意识。"
  },
  [111690011] = {
    id = 111690011,
    name = "呵呵，这种事竟然都能遇上。"
  },
  [111690012] = {
    id = 111690012,
    name = "......这支商队被打劫了，得把他们救出来。"
  },
  [111690013] = {
    id = 111690013,
    name = "我们两个？队长，这对面可不下七八人。"
  },
  [111690014] = {
    id = 111690014,
    name = "既然看到了，没办法见死不救。"
  },
  [111690015] = {
    id = 111690015,
    name = "你回去通知尼莉莎她们，我先跟着，会一路留下记号，你们尽快跟上来，到时再一起行动。"
  },
  [111690016] = {
    id = 111690016,
    name = "唔，好吧。那队长，你要等着我们，可千万别贸然行事。"
  },
  [111690017] = {
    id = 111690017,
    name = "嗯，快去吧。"
  },
  [111690018] = {
    id = 111690018,
    name = "看着车辆一路走远，你就近在树上划下了一个记号，跟菲尼斯挥了挥手，追着车的轨迹而去。"
  },
  [111690019] = {
    id = 111690019,
    name = "两辆车很快停在了附近的河边，看起来那几个黑衣人是打算就地休息，你随手在石头上刻了新的记号，悄然靠近了车队。"
  },
  [111690020] = {
    id = 111690020,
    name = "都给我老实点！"
  },
  [111690021] = {
    id = 111690021,
    name = "那些商人看起来已经醒了，挤在一起瑟瑟发抖。"
  },
  [111690022] = {
    id = 111690022,
    name = "各位大哥，我们已经把所有财物都给你们了，求求你们放过我们吧！"
  },
  [111690023] = {
    id = 111690023,
    name = "送上门的货，还想我放了你们？别做梦了，碰到我们，你们的好运也就到此为止了。"
  },
  [111690024] = {
    id = 111690024,
    name = "不要啊，求求你们了，家里还有老小等着我们回去啊！"
  },
  [111690025] = {
    id = 111690025,
    name = "那商人不停地磕头求饶时，车里一个年轻的商人趁人不注意，猛地挣脱束缚，跑了好几步，又被黑衣人拖着踹了回来。"
  },
  [111690026] = {
    id = 111690026,
    name = "竟敢逃跑！把他绑起来！"
  },
  [111690027] = {
    id = 111690027,
    name = "啊啊——"
  },
  [111690028] = {
    id = 111690028,
    name = "逃走的商人发出惨叫，在受到拳打脚踢和捆绑后，被扔上了车。"
  },
  [111690029] = {
    id = 111690029,
    name = "（看来，这群黑衣人抓人另有目的。）"
  },
  [111690030] = {
    id = 111690030,
    name = "需要喝水吗？"
  },
  [111690031] = {
    id = 111690031,
    name = "一个少女的声音温和平静，让恐惧的年轻商人很快平静下来。"
  },
  [111690032] = {
    id = 111690032,
    name = "......谢谢你，莉亚。"
  },
  [111690033] = {
    id = 111690033,
    name = "这样逃跑不是办法，你别着急，他们看起来不像会立刻杀掉我们。"
  },
  [111690034] = {
    id = 111690034,
    name = "我，我就是太害怕了......呜呜呜......"
  },
  [111690035] = {
    id = 111690035,
    name = "那个叫莉亚的少女又安慰了商人几句话，看得出她情绪稳定，面对这样的打劫，竟然没有恐惧与慌张。"
  },
  [111690036] = {
    id = 111690036,
    name = "（......也许救人的时候，能让她里应外合。）"
  },
  [111690037] = {
    id = 111690037,
    name = "你还在思考的时候，黑衣人又出发了，他们押着车一路驶向了森林里。"
  },
  [111690038] = {
    id = 111690038,
    name = "你皱了皱眉，思考密林里救人和迷路的可能性，增加了刻记号的频率。"
  },
  [111690039] = {
    id = 111690039,
    name = "等一等。"
  },
  [111690040] = {
    id = 111690040,
    name = "少女发出了声音，不急不慢地下了车，几个黑衣人拔出武器严阵以待。"
  },
  [111690041] = {
    id = 111690041,
    name = "我的朋友要去小解，能不能通融一下。"
  },
  [111690042] = {
    id = 111690042,
    name = "找什么理由逃跑！"
  },
  [111690043] = {
    id = 111690043,
    name = "呜呜呜，我，我快憋不住了......"
  },
  [111690044] = {
    id = 111690044,
    name = "给我闭嘴！"
  },
  [111690045] = {
    id = 111690045,
    name = "不管你要带我们去哪儿，你也不想一路拉着臭烘烘的东西吧。"
  },
  [111690046] = {
    id = 111690046,
    name = "妈的烦死了！你去跟着！"
  },
  [111690047] = {
    id = 111690047,
    name = "他推了身边的一个手下，莉亚却再次开了口。"
  },
  [111690048] = {
    id = 111690048,
    name = "他一个男的，不方便吧。"
  },
  [111690049] = {
    id = 111690049,
    name = "嗤，都要死了，还说什么方不方便。要不是上面说了要干净的，你们早就......"
  },
  [111690050] = {
    id = 111690050,
    name = "莉亚皱了皱眉。"
  },
  [111690051] = {
    id = 111690051,
    name = "那我们不走远，就在那儿。"
  },
  [111690052] = {
    id = 111690052,
    name = "莉亚朝你的方向一指，你迅速隐蔽了起来。"
  },
  [111690053] = {
    id = 111690053,
    name = "那就快点！耽搁不少时间了！"
  },
  [111690054] = {
    id = 111690054,
    name = "好好......"
  },
  [111690055] = {id = 111690055, name = "......"},
  [111690056] = {
    id = 111690056,
    name = "眼看莉亚带着女人走了过来，你缓缓后退，躲在了另一棵树后回避。"
  },
  [111690057] = {
    id = 111690057,
    name = "莉亚，我们快跑吧！"
  },
  [111690058] = {
    id = 111690058,
    name = "不，我还不能走。"
  },
  [111690059] = {
    id = 111690059,
    name = "为什么？这么好的机会不跑做什么？大不了就是被抓回来。"
  },
  [111690060] = {
    id = 111690060,
    name = "你走了，给他们留下的就是绝路。"
  },
  [111690061] = {
    id = 111690061,
    name = "莉亚指的是其他被绑架的人，她说话的时候，似有察觉地朝你的方向看了一眼。"
  },
  [111690062] = {
    id = 111690062,
    name = "那些黑衣人要我们死！你刚才没听见吗？咱们能跑一个是一个！"
  },
  [111690063] = {
    id = 111690063,
    name = "那你走吧，我会想办法把他们一起救出去。"
  },
  [111690064] = {
    id = 111690064,
    name = "女商人脸色变得很难看，不会武技在深渊独自逃走，只有被魔物吃掉的下场。"
  },
  [111690065] = {
    id = 111690065,
    name = "磨磨蹭蹭的！完了没有！"
  },
  [111690066] = {
    id = 111690066,
    name = "回去吧，我会把大家一起救出去的。"
  },
  [111690067] = {id = 111690067, name = "......"},
  [111690068] = {
    id = 111690068,
    name = "眼看没有办法说服莉亚，女商人只能和莉亚回去了，在黑衣人骂骂咧咧的声音里重新上了车。"
  },
  [111690069] = {
    id = 111690069,
    name = "等一行人远去，你才走了出来，看见树旁留下的魔法印记，那是一道随时可以激活的攻击魔法。"
  },
  [111690070] = {
    id = 111690070,
    name = "（难道她发现我了？）"
  },
  [111690071] = {
    id = 111690071,
    name = "你心中猜测，沿着车辙继续跟了上去。"
  },
  [111690072] = {
    id = 111690072,
    name = "跟着车辙走到了一处据点，里面传来了说话声，你绕行到隐蔽处，悄悄溜了进去。"
  },
  [111690073] = {
    id = 111690073,
    name = "放开我！你做了什么，我不能动了！"
  },
  [111690074] = {id = 111690074, name = "闭嘴！"},
  [111690075] = {
    id = 111690075,
    name = "黑衣人一脚踹倒了商人，踩在她惊恐的脸上。"
  },
  [111690076] = {
    id = 111690076,
    name = "再闹就把你舌头割了！"
  },
  [111690077] = {
    id = 111690077,
    name = "商人惴惴地点头，紧闭了嘴不敢再吼，商队里的其他人见到后，也立刻咬紧了舌头，不敢发出一点声音。"
  },
  [111690078] = {
    id = 111690078,
    name = "老大，全部都用魔法束缚住了，一个也跑不掉。"
  },
  [111690079] = {
    id = 111690079,
    name = "嗯，这次干得不错，好好守着，等晚上再送过去。"
  },
  [111690080] = {
    id = 111690080,
    name = "放心吧老大，交给我！"
  },
  [111690081] = {
    id = 111690081,
    name = "（送过去？）"
  },
  [111690082] = {
    id = 111690082,
    name = "你心生疑虑，见那女商人被黑衣人拎起来又扔回了车上。"
  },
  [111690083] = {
    id = 111690083,
    name = "就在她即将砸在莉亚脚上的时候，你发现莉亚不引人注意地挪动了一点，完美避开。"
  },
  [111690084] = {
    id = 111690084,
    name = "砰！女商人还没来得及惨叫，就晕了过去。"
  },
  [111690085] = {
    id = 111690085,
    name = "（这个莉亚，果然不是普通商人。）"
  },
  [111690086] = {
    id = 111690086,
    name = "虽然知道莉亚和你都有救人的意愿，但你并不理解，如果只是救人，那半路截逃比深入敌人的巢穴更为容易。"
  },
  [111690087] = {
    id = 111690087,
    name = "（难道她还有其他的目的？）"
  },
  [111690088] = {
    id = 111690088,
    name = "你还没来得及想，就见莉亚动手了，解开了自己的束缚。"
  },
  [111690089] = {
    id = 111690089,
    name = "但她没有立刻行动，而是不着痕迹地观察四周，最后落在了看守商队的黑衣人身上。"
  },
  [111690090] = {
    id = 111690090,
    name = "你在这看好了，我去拿货。"
  },
  [111690091] = {id = 111690091, name = "嗯。"},
  [111690092] = {
    id = 111690092,
    name = "凶狠的黑衣人大步朝你走了过来，你这时才发现自己躲藏的地方，正是一堆木箱，而身后宽阔，这样下去必然被发现。"
  },
  [111690093] = {
    id = 111690093,
    name = "（菲尼斯他们还没来，还是不要轻举妄动。）"
  },
  [111690094] = {
    id = 111690094,
    name = "你小心翼翼地移动着步伐，躲避黑衣人的视线，就在黑衣人即将发现你时，不远处传来了一声惨叫。"
  },
  [111690095] = {
    id = 111690095,
    name = "啊啊，好疼啊！"
  },
  [111690096] = {
    id = 111690096,
    name = "该死的！让她别吵！"
  },
  [111690097] = {
    id = 111690097,
    name = "趁着黑衣人回头的时间，你迅速躲在了一间房屋后，同时看向了莉亚的方向。"
  },
  [111690098] = {
    id = 111690098,
    name = "她的目光朝你的方向扫了一眼，随即又看向了女商人。"
  },
  [111690099] = {
    id = 111690099,
    name = "噤声，他们来了。"
  },
  [111690100] = {
    id = 111690100,
    name = "呜呜呜......真的好疼......刚才你是不是打了我一下？"
  },
  [111690101] = {
    id = 111690101,
    name = "没有，是你自己碰到了。"
  },
  [111690102] = {
    id = 111690102,
    name = "是啊，你也动不了......呜呜呜，早知道先前就该跑的......"
  },
  [111690103] = {
    id = 111690103,
    name = "再吵，就死！"
  },
  [111690104] = {
    id = 111690104,
    name = "女商人的哭声一顿，害怕地打了个嗝。"
  },
  [111690105] = {
    id = 111690105,
    name = "（看来这些黑衣人也怕引来探险者......刚才莉亚是看见我了吗？）"
  },
  [111690106] = {
    id = 111690106,
    name = "你不能确认是否是莉亚的相助，才让你避过眼前的危机，不过那黑衣人只回头吼了一句，又继续打开了箱子。"
  },
  [111690107] = {
    id = 111690107,
    name = "啊，找到了，在这里。"
  },
  [111690108] = {
    id = 111690108,
    name = "他拿着一块拳头般大的乌黑石头，朝着那“老大”跑了过去。"
  },
  [111690109] = {
    id = 111690109,
    name = "老大，你看，就是这个！"
  },
  [111690110] = {
    id = 111690110,
    name = "没想到找祭品还能找到这种好东西，真是意外收获啊！"
  },
  [111690111] = {
    id = 111690111,
    name = "......有点意思，我回去一趟，你看好这批货。"
  },
  [111690112] = {
    id = 111690112,
    name = "好的老大！"
  },
  [111690113] = {
    id = 111690113,
    name = "黑衣人头目拿走了那块石头，大步走出了据点。"
  },
  [111690114] = {
    id = 111690114,
    name = "（回去？难道他们还有别的老巢？）"
  },
  [111690115] = {
    id = 111690115,
    name = "你观察着黑衣人的数量与守卫点，判断着救人的突破口，却在这时，你看到莉亚动了。"
  },
  [111690116] = {id = 111690116, name = "！！！"},
  [111690117] = {
    id = 111690117,
    name = "最先发现的是她身边的女商人，她被魔法束缚着，嘴里发出了无声地喊叫。"
  },
  [111690118] = {
    id = 111690118,
    name = "她用愤恨的眼神控诉莉亚，很明显知道是莉亚让她暂时说不了话。"
  },
  [111690119] = {
    id = 111690119,
    name = "（小声）别激动，和他们一起好好睡一觉，我会把你们都救出去的。"
  },
  [111690120] = {id = 111690120, name = "！！！"},
  [111690121] = {
    id = 111690121,
    name = "女商人并不相信她的话，认为她会丢下他们独自逃亡，但却又无可奈何。"
  },
  [111690122] = {
    id = 111690122,
    name = "（小声）再闹只会把他们都吸引过来哦。"
  },
  [111690123] = {
    id = 111690123,
    name = "（小声）我只是离开一小会儿，很快就回来。"
  },
  [111690124] = {
    id = 111690124,
    name = "她微微抬起了手，手里发出了一团微光，那团光使得女商人在惊恐中昏睡后，又绕到了车旁边的几个黑衣人身边。"
  },
  [111690125] = {
    id = 111690125,
    name = "哈欠......"
  },
  [111690126] = {
    id = 111690126,
    name = "趁着看守恍惚之际，莉亚迅速地下车、脱身，离开据点，动作如云雀般敏捷，一气呵成。"
  },
  [111690127] = {
    id = 111690127,
    name = "呼，差点睡着。"
  },
  [111690128] = {
    id = 111690128,
    name = "看守的黑衣人惊醒后，看了一圈倒在车里的商人们，似乎并没有发现什么不对劲。"
  },
  [111690129] = {
    id = 111690129,
    name = "（对障眼昏睡魔法运用自如，这个莉亚果然不是一般人。）"
  },
  [111690130] = {
    id = 111690130,
    name = "看着莉亚走远，你忽然犹豫了。"
  },
  [111690131] = {
    id = 111690131,
    name = "（目前这些人没有危机，我要不要也跟过去看看......）"
  },
  [111690132] = {
    id = 111690132,
    name = "（这个莉亚到底有什么目的？）"
  },
  [111690133] = {
    id = 111690133,
    name = "下一刻，你果断在残垣上刻上了团队印记，悄悄跟上了莉亚。"
  },
  [111690134] = {
    id = 111690134,
    name = "你跟着莉亚走入了一片森林，树木高耸，枝叶交叠。"
  },
  [111690135] = {
    id = 111690135,
    name = "整个林子被一层淡淡的灰色雾气笼罩，越到森林深处，雾气越深，形成了一道天然的屏障，将这片区域与外界彻底隔绝。"
  },
  [111690136] = {
    id = 111690136,
    name = "（这里很容易迷路。）"
  },
  [111690137] = {
    id = 111690137,
    name = "你在途中刻下记号，盯紧了前方那个若隐若现的身影，她与黑衣人头目也保持着不近的距离，每一步都走得小心翼翼。"
  },
  [111690138] = {
    id = 111690138,
    name = "（这里的浊炁很浓，可一路上竟没见到魔物，看来有人时常肃清巡逻......）"
  },
  [111690139] = {
    id = 111690139,
    name = "不久后，莉亚的脚步停了，她在原地站定了一会儿，侧身朝右方走去，绕过了几棵树，消失了。"
  },
  [111690140] = {id = 111690140, name = "......"},
  [111690141] = {
    id = 111690141,
    name = "你不动声色地靠近，果然在莉亚先前站定的位置看到了一片洼地。"
  },
  [111690142] = {
    id = 111690142,
    name = "洼地中央搭建着几座简易的房屋，被密不透风的灌木丛和扭曲的树木遮挡着视线，驻守大门的黑衣人昏昏欲睡，周围几名黑衣人来回巡逻，透露出一种不祥的气息。"
  },
  [111690143] = {
    id = 111690143,
    name = "（唉，跟丢了啊。）"
  },
  [111690144] = {
    id = 111690144,
    name = "在窥察那个神秘营地之后，视野里失去了莉亚的身影。"
  },
  [111690145] = {
    id = 111690145,
    name = "（是回去还是......）"
  },
  [111690146] = {
    id = 111690146,
    name = "你沉思片刻，很快决定继续深入探查，藏踪蹑迹，无声无息地靠近了那片营地。"
  },
  [111690147] = {
    id = 111690147,
    name = "老哥，打个商量，你帮我站一会儿，我都快馋死了！"
  },
  [111690148] = {
    id = 111690148,
    name = "别着急啊，一会儿老大走了给你留点。"
  },
  [111690149] = {
    id = 111690149,
    name = "你说他早不来晚不来，偏偏在咱们吃烤肉的时候来，搞得我手忙脚乱的，差点挨了一顿训。"
  },
  [111690150] = {
    id = 111690150,
    name = "听说是拿到了好东西，才急急忙忙赶过来的。"
  },
  [111690151] = {
    id = 111690151,
    name = "好东西？难道说那个东西就要成功了？"
  },
  [111690152] = {
    id = 111690152,
    name = "谁知道啊。"
  },
  [111690153] = {
    id = 111690153,
    name = "老哥，别走啊，就帮我一会儿。"
  },
  [111690154] = {
    id = 111690154,
    name = "那不行，万一附近混进来了老鼠，我可负不起责任。"
  },
  [111690155] = {
    id = 111690155,
    name = "这深山老林的，别说是人，魔物都早被你们杀光了。再说，咱们门外有魔法阵，不是从正门进的都——"
  },
  [111690156] = {id = 111690156, name = "砰！！"},
  [111690157] = {
    id = 111690157,
    name = "话没说完，魔法阵就被触发了，一道红光在右前方迅速闪烁，又消失了。"
  },
  [111690158] = {
    id = 111690158,
    name = "什么东西？！"
  },
  [111690159] = {
    id = 111690159,
    name = "这魔法阵每天总要弄死几只小魔物，怕是这会儿又掉陷阱里了，晚上又能加餐了。"
  },
  [111690160] = {
    id = 111690160,
    name = "不对劲，我去看看！"
  },
  [111690161] = {
    id = 111690161,
    name = "黑衣人拿着武器就跑了过去，留下守门人絮絮叨叨。"
  },
  [111690162] = {
    id = 111690162,
    name = "啧，不就是找借口不想帮忙吗......"
  },
  [111690163] = {
    id = 111690163,
    name = "你比巡逻的黑衣人更快，到达红光处的时候，果然看到了站在旁边的莉亚。"
  },
  [111690164] = {id = 111690164, name = "！！！"},
  [111690165] = {
    id = 111690165,
    name = "她无声地看着你，单手垂在下方，在你靠近的时候，眼神充满警惕。"
  },
  [111690166] = {
    id = 111690166,
    name = "（小声）快躲起来！"
  },
  [111690167] = {
    id = 111690167,
    name = "莉亚皱眉看了你一眼，却动也不动，而那黑衣人已经快靠近了。"
  },
  [111690168] = {
    id = 111690168,
    name = "转瞬间，你想到了一种可能性，来不及思考，连拉带扶将莉亚放在了一棵树后。"
  },
  [111690169] = {
    id = 111690169,
    name = "（无声）魔法阵？"
  },
  [111690170] = {
    id = 111690170,
    name = "莉亚抿了抿嘴，警告地看着你扶着她双肩的手，你立刻放开了，正想说些什么的时候，黑衣人已经出现在魔法阵周围。"
  },
  [111690171] = {
    id = 111690171,
    name = "这是......脚印？"
  },
  [111690172] = {id = 111690172, name = "！！！"},
  [111690173] = {
    id = 111690173,
    name = "（糟了，刚才情况紧急，竟然忘了隐藏痕迹！）"
  },
  [111690174] = {
    id = 111690174,
    name = "呵呵，果然是有老鼠来了啊。"
  },
  [111690175] = {
    id = 111690175,
    name = "黑衣人拖着长刀猛地一挥，斩断了一片灌木丛，烈风割破了树旁的草，几乎除了那棵巨树，你们已经失去了遮挡的地方。"
  },
  [111690176] = {
    id = 111690176,
    name = "别躲了，小老鼠，被魔法阵捆住的人，只会成为木头人，怎么都跑不掉。"
  },
  [111690177] = {
    id = 111690177,
    name = "嚓、嚓、嚓......沉重的脚步声贴近了，最后停了下来。你能感觉他就在树后，于是一手护着莉亚，集中精神戒备着即将袭来的攻击。"
  },
  [111690178] = {id = 111690178, name = "......"},
  [111690179] = {
    id = 111690179,
    name = "你忽然感觉袖口被拉扯了一下，莉亚盯着你，无声地说了一句话。"
  },
  [111690180] = {
    id = 111690180,
    name = "找到你了啊，让我看看，送上来的祭品，是什么样？！"
  },
  [111690181] = {
    id = 111690181,
    name = "黑衣人倏然绕到了树后，竟然发现空无一人。"
  },
  [111690182] = {
    id = 111690182,
    name = "嗯？难道我看错了？"
  },
  [111690183] = {
    id = 111690183,
    name = "黑衣人忽觉头顶阴影落下，还没来得及提刀，就被你跃下时砸落，霍霍生风带着魔法的一拳击晕了过去。"
  },
  [111690184] = {
    id = 111690184,
    name = "......好了。啊，抱歉。"
  },
  [111690185] = {
    id = 111690185,
    name = "你松开了抱着莉亚的手。先前情急之下，你带着莉亚抓住树干翻了上去，才得以偷袭成功。"
  },
  [111690186] = {id = 111690186, name = "......"},
  [111690187] = {
    id = 111690187,
    name = "感受到袖子再次被扯动，莉亚的眼睛看向地下即将苏醒的人。"
  },
  [111690188] = {
    id = 111690188,
    name = "砰！又是一记重击，巡逻的黑衣人彻底昏迷了过去。"
  },
  [111690189] = {
    id = 111690189,
    name = "此地不宜久留，我们先离开这里。"
  },
  [111690190] = {id = 111690190, name = "......"},
  [111690191] = {
    id = 111690191,
    name = "手上的袖子被扯着摇了摇，你竟然有一种小朋友在向你撒娇的错觉，你察觉到她不太想离开，还想继续探查。"
  },
  [111690192] = {
    id = 111690192,
    name = "老哥！找到老鼠了吗？要不要帮忙啊！"
  },
  [111690193] = {id = 111690193, name = "！！！"},
  [111690194] = {
    id = 111690194,
    name = "你还没有解除束缚，什么也做不了。"
  },
  [111690195] = {
    id = 111690195,
    name = "你感到袖子被抓紧，她眼神微垂，有些无措。"
  },
  [111690196] = {id = 111690196, name = "走吧。"},
  [111690197] = {
    id = 111690197,
    name = "见她妥协，你弯腰背上了她，迅速沿着记号离开了迷雾重重的森林。"
  },
  [111690198] = {
    id = 111690198,
    name = "离开森林后，你想起来时看到的一个山洞，带着莉亚暂时藏了进去。"
  },
  [111690199] = {
    id = 111690199,
    name = "放......我......下来......"
  },
  [111690200] = {
    id = 111690200,
    name = "莉亚的说话很缓慢且吃力，大部分说着气音，看来魔法的影响还没完全消除。"
  },
  [111690201] = {
    id = 111690201,
    name = "先休息一下吧。莉亚小姐，你能自己解开吗？"
  },
  [111690202] = {
    id = 111690202,
    name = "察觉到莉亚身体的僵硬，你意识到那个魔法阵并不简单。"
  },
  [111690203] = {
    id = 111690203,
    name = "帮我......拿......一个......东西......"
  },
  [111690204] = {
    id = 111690204,
    name = "你耐心地听着，却没听到下半句。"
  },
  [111690205] = {
    id = 111690205,
    name = "想拿什么？"
  },
  [111690206] = {id = 111690206, name = "......"},
  [111690207] = {
    id = 111690207,
    name = "莉亚踟蹰了半晌，才努力地开了口。"
  },
  [111690208] = {
    id = 111690208,
    name = "......魔法......符石......可以......解......开......束缚......"
  },
  [111690209] = {
    id = 111690209,
    name = "魔法符石，在哪里？"
  },
  [111690210] = {id = 111690210, name = "在......"},
  [111690211] = {
    id = 111690211,
    name = "莉亚白皙的脸忽然红了，仿佛白雪上落了桃花。"
  },
  [111690212] = {
    id = 111690212,
    name = "在......我的......腰上......"
  },
  [111690213] = {
    id = 111690213,
    name = "你稍微靠近了，看了一圈莉亚的腰，盈盈一握，没有任何口袋行李一类的物品。"
  },
  [111690214] = {
    id = 111690214,
    name = "在......腰带......里......靠左......"
  },
  [111690215] = {
    id = 111690215,
    name = "莉亚的脸涨红，你顺着她所说的方向发现了一截细小的腰带，几乎和衣服融为一体。"
  },
  [111690216] = {
    id = 111690216,
    name = "我看到了，莉亚小姐。"
  },
  [111690217] = {
    id = 111690217,
    name = "......拿......出来......"
  },
  [111690218] = {id = 111690218, name = "......"},
  [111690219] = {
    id = 111690219,
    name = "你愣了愣，下意识四下看了一眼，竟然没有可以借用的工具。"
  },
  [111690220] = {
    id = 111690220,
    name = "快点......"
  },
  [111690221] = {
    id = 111690221,
    name = "抱歉了，莉亚小姐。"
  },
  [111690222] = {
    id = 111690222,
    name = "你缓缓蹲下身，靠近莉亚的时候，一道淡雅的幽香涌入鼻尖，你来不及遐想，极快地取出了一块扁平的魔法符石，放在了莉亚手中。"
  },
  [111690223] = {
    id = 111690223,
    name = "是这个吗？"
  },
  [111690224] = {
    id = 111690224,
    name = "你退了一步，萦绕的香味散去，也让你不自觉松口气。"
  },
  [111690225] = {
    id = 111690225,
    name = "霎时间，一道光芒在莉亚手中迸散，莉亚一个踉跄，你正打算扶她时，她却不经意地躲开了。"
  },
  [111690226] = {
    id = 111690226,
    name = "谢谢你。"
  },
  [111690227] = {
    id = 111690227,
    name = "没什么，举手之劳。"
  },
  [111690228] = {
    id = 111690228,
    name = "不止这个，还有在森林里的事，我也要谢谢你。"
  },
  [111690229] = {
    id = 111690229,
    name = "既然看到了，就无法坐视不管。莉亚小姐去那里是想做什么？"
  },
  [111690230] = {
    id = 111690230,
    name = "你呢，你跟我一路，又想做什么？"
  },
  [111690231] = {
    id = 111690231,
    name = "原来你早就知道我跟着你。"
  },
  [111690232] = {
    id = 111690232,
    name = "嗯。最开始我以为......后来，你跟着我们到黑衣人的巢穴，我大概能确定，你就是那种奇怪的探险者。"
  },
  [111690233] = {
    id = 111690233,
    name = "奇怪的探险者？"
  },
  [111690234] = {
    id = 111690234,
    name = "难道你跟着我，不是为了宝物吗？"
  },
  [111690235] = {id = 111690235, name = "啊？"},
  [111690236] = {
    id = 111690236,
    name = "黑衣人头目带走的那个石头，是这批行商里唯一值钱的东西，也是蕴含魔法力的宝物，你不知道？"
  },
  [111690237] = {id = 111690237, name = "......"},
  [111690238] = {
    id = 111690238,
    name = "不过你这样的好人我倒是见得不多，能放弃宝物来救人......更奇怪了。"
  },
  [111690239] = {
    id = 111690239,
    name = "放弃宝物？"
  },
  [111690240] = {
    id = 111690240,
    name = "通常寻宝者都会趁黑衣人来抓我的时候，深入营地寻宝，而你......"
  },
  [111690241] = {
    id = 111690241,
    name = "呵呵，莉亚小姐，我想你误会了。"
  },
  [111690242] = {
    id = 111690242,
    name = "你是什么目的，我就是什么目的。"
  },
  [111690243] = {
    id = 111690243,
    name = "你知道我是什么目的？"
  },
  [111690244] = {
    id = 111690244,
    name = "你想救出那些商人。"
  },
  [111690245] = {
    id = 111690245,
    name = "也许我是骗他们的。"
  },
  [111690246] = {
    id = 111690246,
    name = "那你骗了他们吗？"
  },
  [111690247] = {id = 111690247, name = "......"},
  [111690248] = {
    id = 111690248,
    name = "既然你想救人，为什么还跟我来森林里？"
  },
  [111690249] = {
    id = 111690249,
    name = "因为想救人的莉亚小姐孤身潜入，我很好奇，也想看一看黑衣人的另一个老巢，到底是什么。"
  },
  [111690250] = {
    id = 111690250,
    name = "莉亚淡淡地看了你一眼。"
  },
  [111690251] = {
    id = 111690251,
    name = "你去救人吧，我打算回去。"
  },
  [111690252] = {
    id = 111690252,
    name = "说完，她就打算再次走向森林的方向，却被你叫住了。"
  },
  [111690253] = {
    id = 111690253,
    name = "莉亚小姐，你还要再去？"
  },
  [111690254] = {id = 111690254, name = "嗯。"},
  [111690255] = {
    id = 111690255,
    name = "那里防守严密，只靠我们两人，一时也无法彻底铲除那些黑衣人，不如先将那群人救走，再谋算其他事。"
  },
  [111690256] = {
    id = 111690256,
    name = "不，不能再拖了。"
  },
  [111690257] = {
    id = 111690257,
    name = "我们在被劫持的路上，我听到他们提到堕落者。"
  },
  [111690258] = {
    id = 111690258,
    name = "堕落者？"
  },
  [111690259] = {
    id = 111690259,
    name = "我大致可以肯定，他们在利用那些普通人，在做有关堕落者的事，而黑衣人抓人夺宝的行为，绝对不是第一次了。"
  },
  [111690260] = {
    id = 111690260,
    name = "而且，那个头目说过，他们要等到晚上才“送过去”，也就是说，在天黑之前，那几个商人还是安全的。"
  },
  [111690261] = {
    id = 111690261,
    name = "我要利用这段时间，查清他们到底有什么不可告人的阴谋。"
  },
  [111690262] = {
    id = 111690262,
    name = "原来是这样。"
  },
  [111690263] = {
    id = 111690263,
    name = "我见你一路都有刻下记号，看起来并不像为了寻路......你是不是在等同伴来？"
  },
  [111690264] = {
    id = 111690264,
    name = "你惊叹她的冷静与聪慧，大方地承认了这件事。"
  },
  [111690265] = {
    id = 111690265,
    name = "莉亚小姐，你什么都知道。"
  },
  [111690266] = {
    id = 111690266,
    name = "那救人的事就交给你了，我——"
  },
  [111690267] = {
    id = 111690267,
    name = "一起去。"
  },
  [111690268] = {id = 111690268, name = "什么？"},
  [111690269] = {
    id = 111690269,
    name = "那个营地守卫森严，像你之前误触的魔法阵，也许还有更多。有我和你一起，也好相互有个照应。"
  },
  [111690270] = {
    id = 111690270,
    name = "莉亚脸色一僵，作为一个言灵，被魔法反控，还让你帮忙的情况几乎让她无地自容。"
  },
  [111690271] = {
    id = 111690271,
    name = "况且堕落者的事不容小觑，如果不及时阻止，必然会酿成大祸。"
  },
  [111690272] = {
    id = 111690272,
    name = "听完你的话，很快她就调整好了心态，温雅地朝你点点头。"
  },
  [111690273] = {
    id = 111690273,
    name = "那莉亚就先在这里谢过了，走吧。"
  },
  [111690274] = {
    id = 111690274,
    name = "你们重新回到了那片雾气弥漫的森林。"
  },
  [111690275] = {
    id = 111690275,
    name = "......这一片都应该有布置了防御魔法阵。"
  },
  [111690276] = {
    id = 111690276,
    name = "你轻轻扔了一块石头过去，激起了一道涟漪，如果是活物，那一定会被定身束缚，无法动弹。"
  },
  [111690277] = {
    id = 111690277,
    name = "看来从这些地方潜入是不行了，只能从大门进。"
  },
  [111690278] = {
    id = 111690278,
    name = "可是，以我们的力量......"
  },
  [111690279] = {
    id = 111690279,
    name = "不能硬闯，那就巧取。"
  },
  [111690280] = {
    id = 111690280,
    name = "你还记得昨天巡逻的那个黑衣人吗？"
  },
  [111690281] = {
    id = 111690281,
    name = "嗯，他被你打晕了，我很好奇你竟然没有杀了他。"
  },
  [111690282] = {
    id = 111690282,
    name = "杀了他的话，现在营地的防卫就不会是这样了。"
  },
  [111690283] = {
    id = 111690283,
    name = "你指了指洼地中的营地，守门的昏昏欲睡，巡逻的站着聊天，一点也没有紧迫的氛围。"
  },
  [111690284] = {
    id = 111690284,
    name = "那个人回去之后，竟然没有汇报情况？"
  },
  [111690285] = {
    id = 111690285,
    name = "他不会，也不想。"
  },
  [111690286] = {
    id = 111690286,
    name = "一来营地没有外人入侵，二来他连人都没看清就被打晕了，这对他而言是耻辱，对他的组织而言是极大的失误，他一定会掩盖自己的错误，装作什么都没发生。"
  },
  [111690287] = {
    id = 111690287,
    name = "原来是这样。"
  },
  [111690288] = {
    id = 111690288,
    name = "那我们应该怎么巧取？"
  },
  [111690289] = {
    id = 111690289,
    name = "一会儿去大门看看，有没有机会。"
  },
  [111690290] = {
    id = 111690290,
    name = "大门？我们能进去吗？"
  },
  [111690291] = {
    id = 111690291,
    name = "能，我在来的路上准备了一个东西。"
  },
  [111690292] = {
    id = 111690292,
    name = "你拿出了一截魔植，那是低等的魔物，靠着浊炁存活，也毫无狩猎的价值，但不影响它是活的。"
  },
  [111690293] = {
    id = 111690293,
    name = "你想用它来触发魔法阵？"
  },
  [111690294] = {
    id = 111690294,
    name = "嗯，也许那个被打的黑衣人心心念念想要报仇，正好给他一个机会。"
  },
  [111690295] = {
    id = 111690295,
    name = "莉亚被你逗得笑了笑。"
  },
  [111690296] = {
    id = 111690296,
    name = "再被你打一次的机会吗？"
  },
  [111690297] = {
    id = 111690297,
    name = "你无辜地耸了耸肩。"
  },
  [111690298] = {
    id = 111690298,
    name = "谁让他成为那个突破点呢。"
  },
  [111690299] = {
    id = 111690299,
    name = "你将魔植拿了出来，手脚麻利地斩下了附近的藤蔓，将它捆了捆，甩手扔了出去，恰好砸在魔法阵上！"
  },
  [111690300] = {
    id = 111690300,
    name = "砰——魔法阵爆发出一阵红光。"
  },
  [111690301] = {
    id = 111690301,
    name = "什么人！"
  },
  [111690302] = {
    id = 111690302,
    name = "老哥，你又找借口跑啊？"
  },
  [111690303] = {
    id = 111690303,
    name = "滚蛋，等我抓到人给你好好看看！"
  },
  [111690304] = {
    id = 111690304,
    name = "远远传来了说话声，你和莉亚藏在了附近，等着黑衣人的到来。"
  },
  [111690305] = {
    id = 111690305,
    name = "（小声）来了。"
  },
  [111690306] = {
    id = 111690306,
    name = "黑衣人这次明显有备而来，他拖着长刀，一步三回头，十分警惕，走了好一阵才到达魔植所在的地方。"
  },
  [111690307] = {
    id = 111690307,
    name = "（远处大喊）抓到没啊，是什么样的老鼠啊？！"
  },
  [111690308] = {
    id = 111690308,
    name = "妈的，竟然是一只长腿的魔植！"
  },
  [111690309] = {
    id = 111690309,
    name = "（远处大喊）那正好晚上加餐了！"
  },
  [111690310] = {id = 111690310, name = "加——"},
  [111690311] = {
    id = 111690311,
    name = "黑衣人话未说完，你和莉亚同时出手，将他狠狠击晕了过去。"
  },
  [111690312] = {
    id = 111690312,
    name = "看着黑衣人头上的血渍，你不禁对莉亚另眼相看。"
  },
  [111690313] = {
    id = 111690313,
    name = "想不到莉亚小姐不仅对魔法熟稔，武技也有所涉猎。"
  },
  [111690314] = {
    id = 111690314,
    name = "......好像下手重了些。"
  },
  [111690315] = {
    id = 111690315,
    name = "不过能晕过去就好，现在怎么做？"
  },
  [111690316] = {
    id = 111690316,
    name = "你扒了黑衣人的衣服，套在了自己身上。"
  },
  [111690317] = {
    id = 111690317,
    name = "你看起来很熟练，以前经常扒人衣服？"
  },
  [111690318] = {id = 111690318, name = "......"},
  [111690319] = {
    id = 111690319,
    name = "我去门口，帮你拿另一套衣服。"
  },
  [111690320] = {
    id = 111690320,
    name = "莉亚皱了皱眉，正打算说什么时候，你已经拿着魔植走向了门口。"
  },
  [111690321] = {
    id = 111690321,
    name = "老哥，我就说哪儿有什么擅闯的耗子，别说这地方鸟不拉屎的，就算真来了，那也只能给老大的祭坛加料。"
  },
  [111690322] = {id = 111690322, name = "给你。"},
  [111690323] = {
    id = 111690323,
    name = "你把魔植扔给了守门人。"
  },
  [111690324] = {
    id = 111690324,
    name = "你还真把这玩意儿拿回来了？就——"
  },
  [111690325] = {
    id = 111690325,
    name = "黑衣人盯着高高抛来的魔植，你轻松地击中了他的要害，瞬间倒了下去。"
  },
  [111690326] = {
    id = 111690326,
    name = "趁其他人没发现，你扶着他到了大门外，将衣服递给了莉亚。"
  },
  [111690327] = {id = 111690327, name = "......"},
  [111690328] = {
    id = 111690328,
    name = "看莉亚略微嫌弃的脸色，你不禁笑了笑。"
  },
  [111690329] = {
    id = 111690329,
    name = "时间有限，莉亚小姐，快换上吧。"
  },
  [111690330] = {
    id = 111690330,
    name = "这一次莉亚敛容正色，迅速地披上了黑衣斗篷，两人将昏迷的黑衣人扔到森林深处，再回来时，黑衣人营地与先前并无二致。"
  },
  [111690331] = {
    id = 111690331,
    name = "看来那个黑衣人头目还没有离开。"
  },
  [111690332] = {
    id = 111690332,
    name = "我先前探查过，在那边。"
  },
  [111690333] = {
    id = 111690333,
    name = "莉亚带你来到一个房屋前，几个黑衣人迎面，莉亚忽然停住不动，有个黑衣人忽然看了过来。"
  },
  [111690334] = {
    id = 111690334,
    name = "你心道不好，灵机将手搭在她肩上，大大咧咧地笑了一声。"
  },
  [111690335] = {
    id = 111690335,
    name = "别生气了，这次没吃着，下次老哥给你留个魔物腿！"
  },
  [111690336] = {id = 111690336, name = "......"},
  [111690337] = {
    id = 111690337,
    name = "别听他的，上次就他吃得最多，哈哈哈！"
  },
  [111690338] = {
    id = 111690338,
    name = "走，老哥现在就带你去抓新鲜的！"
  },
  [111690339] = {
    id = 111690339,
    name = "你怕在那人眼前露出破绽，掰过她的身子就朝另一边走去，总算没引起那群人的怀疑。"
  },
  [111690340] = {
    id = 111690340,
    name = "（小声）刚才太冒险了。"
  },
  [111690341] = {
    id = 111690341,
    name = "（小声）权宜之计。"
  },
  [111690342] = {
    id = 111690342,
    name = "莉亚忽然比了一个噤声的动作，你们听到某个房间传来说话声，立刻躲到了无人的角落倾听。"
  },
  [111690343] = {
    id = 111690343,
    name = "......阁下，如何？"
  },
  [111690344] = {
    id = 111690344,
    name = "是的......今天刚拿到的......没想到普通的商队还藏着这种好东西。"
  },
  [111690345] = {
    id = 111690345,
    name = "声音断续不明，那个黑衣人头目似乎在和谁说话，态度恭敬。"
  },
  [111690346] = {
    id = 111690346,
    name = "您是说......完毕............晚上就......"
  },
  [111690347] = {
    id = 111690347,
    name = "是！祭品都准备好了！有了这东西，阵法已经完全可以补全！"
  },
  [111690348] = {
    id = 111690348,
    name = "黑衣人头目显得激动，声音都大了几分。"
  },
  [111690349] = {
    id = 111690349,
    name = "您的计划一定能实现，一旦堕落者也能拥有神志，您将拥有一个无敌的军队！"
  },
  [111690350] = {id = 111690350, name = "！！！"},
  [111690351] = {
    id = 111690351,
    name = "（他们打算制造拥有神志的堕落者？！）"
  },
  [111690352] = {
    id = 111690352,
    name = "你与莉亚听得入神，没发现有人出现在了不远处。"
  },
  [111690353] = {
    id = 111690353,
    name = "喂，你们俩在这干嘛呢？！怎么门口都没人守着？！"
  },
  [111690354] = {
    id = 111690354,
    name = "什么人？！！"
  },
  [111690355] = {id = 111690355, name = "快走！"},
  [111690356] = {id = 111690356, name = "这边！"},
  [111690357] = {
    id = 111690357,
    name = "趁房间里的人没追上来，你拉着莉亚往无人处狂奔，黑袍被吹飞，露出了莉亚的真面目。"
  },
  [111690358] = {
    id = 111690358,
    name = "银发飞舞，好似风中的流云。"
  },
  [111690359] = {
    id = 111690359,
    name = "有人入侵！！抓住他们！"
  },
  [111690360] = {
    id = 111690360,
    name = "森林的尽头，是一条宽阔的河流。"
  },
  [111690361] = {
    id = 111690361,
    name = "你们无路可逃了！"
  },
  [111690362] = {
    id = 111690362,
    name = "黑衣人带着两三人追了上来，趁后续的人没到，你率先出手！"
  },
  [111690363] = {
    id = 111690363,
    name = "莉亚小姐！"
  },
  [111690364] = {
    id = 111690364,
    name = "莉亚心领神会，与你一同合击，劲风凛冽，冲在最前的那人被你一拽一踹，踢倒在莉亚身边。"
  },
  [111690365] = {
    id = 111690365,
    name = "也不知莉亚用了什么魔法，那人全身颤抖惨叫，被丢进了河里。"
  },
  [111690366] = {
    id = 111690366,
    name = "带队的黑衣人呆滞了一瞬，没想到你们会突然反击，招呼剩下的三人一起进攻。"
  },
  [111690367] = {
    id = 111690367,
    name = "愣着干什么！一起上！"
  },
  [111690368] = {id = 111690368, name = "！！！"},
  [111690369] = {
    id = 111690369,
    name = "莉亚低吟，一把法杖出现在手中，自她脚下一笔笔魔法纹路延展开来。"
  },
  [111690370] = {
    id = 111690370,
    name = "杀了那个女人！"
  },
  [111690371] = {
    id = 111690371,
    name = "先过我这关！"
  },
  [111690372] = {
    id = 111690372,
    name = "你灵活地在三人眼前周旋，掩护莉亚，领头的黑衣人杀气腾腾，妄图越过你对莉亚动手。"
  },
  [111690373] = {id = 111690373, name = "破！"},
  [111690374] = {
    id = 111690374,
    name = "莉亚脚下的魔法纹路已经完全形成了阵法，顿时光芒盛亮！"
  },
  [111690375] = {
    id = 111690375,
    name = "啊——你、你做了什么？！"
  },
  [111690376] = {
    id = 111690376,
    name = "......唔。"
  },
  [111690377] = {
    id = 111690377,
    name = "你感到身上的力量在不断流逝，和阵中的黑衣人一起失去了力气。"
  },
  [111690378] = {
    id = 111690378,
    name = "瞬息之间，莉亚将三人捆缚，统统扔进了河里，连挣扎都没有就被冲走了。"
  },
  [111690379] = {
    id = 111690379,
    name = "还好吗？"
  },
  [111690380] = {
    id = 111690380,
    name = "魔法阵光芒褪去，你的力量也逐渐回归。"
  },
  [111690381] = {
    id = 111690381,
    name = "好歹......也打声招呼吧，还以为你要连我一起杀了。"
  },
  [111690382] = {
    id = 111690382,
    name = "权宜之计。"
  },
  [111690383] = {
    id = 111690383,
    name = "你张嘴一噎，这句话是你之前跟她说过的。"
  },
  [111690384] = {
    id = 111690384,
    name = "（还挺记仇的啊。）"
  },
  [111690385] = {
    id = 111690385,
    name = "谢谢你刚才掩护我......后面的人快追来了，我们快走吧。"
  },
  [111690386] = {
    id = 111690386,
    name = "你点点头，两人沿着河岸上游奔跑，很快到了你刻下标记的地方。"
  },
  [111690387] = {
    id = 111690387,
    name = "朝左边走。"
  },
  [111690388] = {
    id = 111690388,
    name = "等等......那些黑衣人知道我们发现了他的秘密，一定会来抓我们灭口。"
  },
  [111690389] = {
    id = 111690389,
    name = "我想在这里布置一个魔法陷阱，等他们来之后，将他们一网打尽，再问出堕落者和祭坛的事。"
  },
  [111690390] = {
    id = 111690390,
    name = "莉亚的想法很好，但你却无法赞同。"
  },
  [111690391] = {
    id = 111690391,
    name = "不妥，这样太冒险了。"
  },
  [111690392] = {
    id = 111690392,
    name = "但这是很好的机会。"
  },
  [111690393] = {
    id = 111690393,
    name = "我们不清楚他们的人数，更不清楚他们的实力，万一让自己陷入危险中，就得不偿失了。"
  },
  [111690394] = {
    id = 111690394,
    name = "可是，不深入危险，又如何解决危机？"
  },
  [111690395] = {
    id = 111690395,
    name = "你顿了顿，忽然意识到，莉亚一直做的就是危险的事。"
  },
  [111690396] = {
    id = 111690396,
    name = "她只身在商队中，被抓的时候，身边并没有协助者，她一直是一个人在行动，被魔法阵困住后，似乎也没有考虑过后果。"
  },
  [111690397] = {
    id = 111690397,
    name = "你心中一笑，不得不正视这个孤行一意的少女，她的眉眼天真，却又通透聪慧，此刻却真的在等着你解惑。"
  },
  [111690398] = {
    id = 111690398,
    name = "解决危机不一定用自身作饵，我们要捣毁他们的阴谋，也不只有这一条路。"
  },
  [111690399] = {
    id = 111690399,
    name = "可时间不多了，他们的计划晚上就要开始，我不仅要救人，还要阻止他们。我一个人，没有选择......只有这条路。"
  },
  [111690400] = {
    id = 111690400,
    name = "可你现在不是一个人了。"
  },
  [111690401] = {
    id = 111690401,
    name = "莉亚忽地怔了怔，一双眼微微睁大了。"
  },
  [111690402] = {
    id = 111690402,
    name = "除了我，还有我的同伴，他们很快就会赶来。"
  },
  [111690403] = {
    id = 111690403,
    name = "那我们......"
  },
  [111690404] = {
    id = 111690404,
    name = "现在天快黑了，我们先回去救人！"
  },
  [111690405] = {id = 111690405, name = "好。"},
  [111690406] = {
    id = 111690406,
    name = "你跟着来时的路穿越河道，这是整条河流最狭窄的地方，本有几块乱石铺路，此时河水上涨了些，刚好刚那些石头淹没，漫过了脚踝。"
  },
  [111690407] = {
    id = 111690407,
    name = "小心，水里滑——莉亚小姐！"
  },
  [111690408] = {
    id = 111690408,
    name = "话未说完，莉亚的身体已倒了下去，你及时抓住了她的手扯了回来。"
  },
  [111690409] = {id = 111690409, name = "！！！"},
  [111690410] = {
    id = 111690410,
    name = "谢......谢谢......"
  },
  [111690411] = {
    id = 111690411,
    name = "她的头撞在你胸口，整个身子反倒向了你，你没法立刻推开她站稳，整个重心不稳，向后倒了下去。"
  },
  [111690412] = {id = 111690412, name = "你——"},
  [111690413] = {
    id = 111690413,
    name = "时间在那一刻变得无限缓慢，你看见她因为惊讶无措而微微张开的唇，似乎在说着什么，却无法听得清。"
  },
  [111690414] = {
    id = 111690414,
    name = "那一刻，你对危机的反应帮你做出了下意识的决定——你抓住了她的手，在沉下水前，将莉亚扔上了岸！"
  },
  [111690415] = {id = 111690415, name = "......"},
  [111690416] = {
    id = 111690416,
    name = "你、你没事吧？！！"
  },
  [111690417] = {
    id = 111690417,
    name = "温柔俏皮的河流从你鼻尖溜了过去，耳旁也是哗啦啦的流水声，只模糊地传来了莉亚担忧的声音。"
  },
  [111690418] = {
    id = 111690418,
    name = "还好......水不深。"
  },
  [111690419] = {
    id = 111690419,
    name = "你朝她尴尬地笑了笑，一脚一脚踩稳才过了河。"
  },
  [111690420] = {id = 111690420, name = "噗嗤。"},
  [111690421] = {
    id = 111690421,
    name = "莉亚看你狼狈的样子，忍不住笑出声，却又觉得这样不好。"
  },
  [111690422] = {
    id = 111690422,
    name = "抱歉，我不是故意笑你。"
  },
  [111690423] = {
    id = 111690423,
    name = "没事，快回去救人吧。"
  },
  [111690424] = {
    id = 111690424,
    name = "你不好意思地摆摆手，觉得很是丢人。"
  },
  [111690425] = {
    id = 111690425,
    name = "天色近晚，废弃的据点里已经点燃了火把，废墟中忽明忽暗，隐隐有哭声传来。"
  },
  [111690426] = {
    id = 111690426,
    name = "大哥，就给我们吃一点吧......"
  },
  [111690427] = {
    id = 111690427,
    name = "都是要死的人了，还吃什么？！"
  },
  [111690428] = {
    id = 111690428,
    name = "黑衣人挥了一鞭子，打在商人身上，一声惨叫响起。"
  },
  [111690429] = {
    id = 111690429,
    name = "别打！我不吃了，我不吃了！"
  },
  [111690430] = {
    id = 111690430,
    name = "那就快走！"
  },
  [111690431] = {
    id = 111690431,
    name = "几个黑衣人把商人用一根长绳捆成一串，如同赶牲口般地驱赶商人。"
  },
  [111690432] = {
    id = 111690432,
    name = "看样子赶上了。"
  },
  [111690433] = {
    id = 111690433,
    name = "他们要把人带走，难道带去林子里？"
  },
  [111690434] = {
    id = 111690434,
    name = "不一定，那个森林是黑衣人的大本营，却不一定是他们实施计划的地方。"
  },
  [111690435] = {
    id = 111690435,
    name = "果然，他们将人驱赶的方向，与森林恰恰相反。"
  },
  [111690436] = {
    id = 111690436,
    name = "你说的没错，还好我们回来了，否则他们一定就此殒命。"
  },
  [111690437] = {
    id = 111690437,
    name = "同伴们还没到，我们先跟上——"
  },
  [111690438] = {
    id = 111690438,
    name = "莉亚没等你的话说完，已经挥出了一道魔法，猝不及防地打中了一个黑衣人！"
  },
  [111690439] = {id = 111690439, name = "是你！"},
  [111690440] = {
    id = 111690440,
    name = "黑衣人被这突如其来的袭击吓了一跳，但很快反应过来，纷纷将武器对准了莉亚。"
  },
  [111690441] = {
    id = 111690441,
    name = "你来不及扶额叹气，只能跟着走了出去，站在莉亚身边。"
  },
  [111690442] = {
    id = 111690442,
    name = "原来还有帮手，难怪从我眼皮底下逃走了。"
  },
  [111690443] = {
    id = 111690443,
    name = "把他们统统抓起来，正好给老大多上两个祭品！"
  },
  [111690444] = {
    id = 111690444,
    name = "莉亚一怔，惊讶你的举动。"
  },
  [111690445] = {
    id = 111690445,
    name = "为什么......"
  },
  [111690446] = {
    id = 111690446,
    name = "别说了，专心应敌，保存实力，我来想办法救人。"
  },
  [111690447] = {id = 111690447, name = "好。"},
  [111690448] = {
    id = 111690448,
    name = "刀与剑碰撞在一起，发出刺耳的“铮铮”声。"
  },
  [111690449] = {
    id = 111690449,
    name = "火光下寒芒闪烁，你身形一闪，避开迎面砍来的一刀，顺势一个回旋踢，将一名黑衣人踢倒在地，扬起的尘土阻挡了另一名黑衣人的进攻方向。"
  },
  [111690450] = {
    id = 111690450,
    name = "啊！快来救我们！"
  },
  [111690451] = {
    id = 111690451,
    name = "别、别杀我！"
  },
  [111690452] = {
    id = 111690452,
    name = "那领头的见你们出现后，那些商人蠢蠢欲动，想要逃走，被几鞭子打了回去。"
  },
  [111690453] = {
    id = 111690453,
    name = "谁敢跑我杀了谁！"
  },
  [111690454] = {
    id = 111690454,
    name = "你随手抓起了落在地上的刀，逼退了莉亚身旁的黑衣人，莉亚低吟，法杖带起一道光，下一刻就解开了捆缚商人们的绳子。"
  },
  [111690455] = {
    id = 111690455,
    name = "解、解开了？！！"
  },
  [111690456] = {
    id = 111690456,
    name = "胆小的商人瞪大双眼，不可置信地看着自己的手，"
  },
  [111690457] = {
    id = 111690457,
    name = "愣着干嘛，跟他们拼了！"
  },
  [111690458] = {
    id = 111690458,
    name = "她操起身边的一根粗壮木棍，使尽全身力气朝着黑衣人砸去。"
  },
  [111690459] = {
    id = 111690459,
    name = "商人们受到鼓舞，纷纷拿起能找到的东西，有的挥舞着扁担，有的紧握着石头，开始激烈反抗。"
  },
  [111690460] = {
    id = 111690460,
    name = "有的商人趁着混乱，拼命推搡着身边的黑衣人，撒开腿就跑，边跑边喊“快跑”。"
  },
  [111690461] = {
    id = 111690461,
    name = "都给我去死！"
  },
  [111690462] = {
    id = 111690462,
    name = "胆小的商人被黑衣人踹倒，眼看刀尖就朝他刺了下来，他发出了惊恐地尖叫。"
  },
  [111690463] = {
    id = 111690463,
    name = "救命啊！"
  },
  [111690464] = {
    id = 111690464,
    name = "你的刀临空一档，将商人踢开，一道寒光朝着你的面门袭来，你侧身躲过，那刀几乎是擦着你的鼻尖划过。"
  },
  [111690465] = {id = 111690465, name = "小心！"},
  [111690466] = {
    id = 111690466,
    name = "莉亚的魔法击中黑衣人，一个转身靠在你身后，看着将你们二人包围的黑衣人，神情凝重。"
  },
  [111690467] = {
    id = 111690467,
    name = "那些商人没有武力，不把他们除掉，很难救人。"
  },
  [111690468] = {
    id = 111690468,
    name = "被你救下的商人又被其他的黑衣人牢牢控制，无法脱离魔爪。"
  },
  [111690469] = {
    id = 111690469,
    name = "抱歉，我意气用事，拖累了你。"
  },
  [111690470] = {
    id = 111690470,
    name = "没关系，就把他们一起除掉！"
  },
  [111690471] = {
    id = 111690471,
    name = "大放厥词！"
  },
  [111690472] = {
    id = 111690472,
    name = "黑衣人头目带着另一群人赶了过来，目光如隼地盯着你。"
  },
  [111690473] = {
    id = 111690473,
    name = "门外的，就是你们？"
  },
  [111690474] = {
    id = 111690474,
    name = "想制造堕落者，必将神怒人怨，天地不容！"
  },
  [111690475] = {
    id = 111690475,
    name = "果然听到了我的计划，看来留你们不得了，都给我杀了！"
  },
  [111690476] = {
    id = 111690476,
    name = "明白了，老大！"
  },
  [111690477] = {
    id = 111690477,
    name = "完、完蛋了......"
  },
  [111690478] = {
    id = 111690478,
    name = "商人们看到黑衣人来了帮手，顿时陷入了绝望。"
  },
  [111690479] = {
    id = 111690479,
    name = "你先走吧，去找你的同伴......"
  },
  [111690480] = {
    id = 111690480,
    name = "莉亚声音平缓，似乎对这样的场景司空见惯。"
  },
  [111690481] = {
    id = 111690481,
    name = "呵呵，你在说笑吗，要我扔下你？"
  },
  [111690482] = {
    id = 111690482,
    name = "他们人太多，我用禁术魔法会影响你。"
  },
  [111690483] = {
    id = 111690483,
    name = "你这次倒是先给我打招呼了。"
  },
  [111690484] = {
    id = 111690484,
    name = "嗯，既然一起战斗过，我要尊重你的决定。"
  },
  [111690485] = {
    id = 111690485,
    name = "禁术魔法，会付出代价吧。"
  },
  [111690486] = {
    id = 111690486,
    name = "嗯，我可以承受。"
  },
  [111690487] = {
    id = 111690487,
    name = "那就一起战斗，况且，我的同伴都来了。"
  },
  [111690488] = {
    id = 111690488,
    name = "一场箭雨“唰唰”临空而下，围在你们身边的黑衣人顿时倒下了一片空缺。"
  },
  [111690489] = {
    id = 111690489,
    name = "队长！你的路标简直太难找啦！"
  },
  [111690490] = {
    id = 111690490,
    name = "明明是你迷路了，险些耽搁了时间。"
  },
  [111690491] = {
    id = 111690491,
    name = "蒂娜剑法凌厉，剑破风而上，瞬间逼退了围攻过来的几名黑衣人。"
  },
  [111690492] = {
    id = 111690492,
    name = "好在都赶上了，但队长看起来正享受其中啊。"
  },
  [111690493] = {
    id = 111690493,
    name = "菲尼斯灵活地穿梭在黑衣人之间，手中的寒光一闪，便精准地割破了一名黑衣人的手腕，黑衣人甚至来不及反应就失去了行动力。"
  },
  [111690494] = {
    id = 111690494,
    name = "等你们很久了！安妮斯，先救那些人！"
  },
  [111690495] = {
    id = 111690495,
    name = "是，老师！"
  },
  [111690496] = {
    id = 111690496,
    name = "在蒂娜为安妮斯开出了一条路，护着安妮斯到了那群商人身边。"
  },
  [111690497] = {
    id = 111690497,
    name = "救他，他要死了！"
  },
  [111690498] = {
    id = 111690498,
    name = "没关系，交给我。"
  },
  [111690499] = {
    id = 111690499,
    name = "有了同伴们的加入，莉亚施放魔法挥洒自如，几人联手将黑衣人打得节节败退，黑衣人头目见状，脸色阴沉，转身就掩入了黑暗中。"
  },
  [111690500] = {
    id = 111690500,
    name = "不好，那家伙要逃！"
  },
  [111690501] = {
    id = 111690501,
    name = "莉亚见头目逃走，毫不迟疑地追了上去！"
  },
  [111690502] = {
    id = 111690502,
    name = "莉亚小姐！"
  },
  [111690503] = {
    id = 111690503,
    name = "你制服了一名黑衣人，将他踹到菲尼斯脚下。"
  },
  [111690504] = {
    id = 111690504,
    name = "这里先交给你们！"
  },
  [111690505] = {
    id = 111690505,
    name = "你追着莉亚到了一片荒原。"
  },
  [111690506] = {
    id = 111690506,
    name = "没想到那个家伙慌不择路，竟然选错了方向，这里毫无遮挡，只会更适合言灵发挥。"
  },
  [111690507] = {
    id = 111690507,
    name = "远处魔法的光芒时而闪烁，是莉亚正在和黑衣人交手，而你脚下出现许多淡淡的纹路。"
  },
  [111690508] = {
    id = 111690508,
    name = "不对，这条路的魔纹......是莉亚逼他走的这条路。"
  },
  [111690509] = {
    id = 111690509,
    name = "你心中佩服莉亚对魔法的运用，也看到了前方黑气的弥漫。"
  },
  [111690510] = {
    id = 111690510,
    name = "黑气......这个冲天的气息，是堕落者！"
  },
  [111690511] = {
    id = 111690511,
    name = "你突然想起之前接触的黑衣人组织，他们都多多少少与堕落者相关，但每一次的线索都中断了。"
  },
  [111690512] = {
    id = 111690512,
    name = "也许这一次，能问到一些线索。"
  },
  [111690513] = {
    id = 111690513,
    name = "你加快脚步赶了过去，正好看到一道光芒迸发而出。"
  },
  [111690514] = {
    id = 111690514,
    name = "结束了。"
  },
  [111690515] = {
    id = 111690515,
    name = "当堕落者如鬼魅般贴近的一瞬间，时间仿佛凝固。莉亚的嘴角微微上扬，露出一抹轻蔑的笑容。"
  },
  [111690516] = {id = 111690516, name = "轰——"},
  [111690517] = {
    id = 111690517,
    name = "光芒暴涨，以迅雷不及掩耳之势洞穿了堕落者的心脏。"
  },
  [111690518] = {
    id = 111690518,
    name = "堕落者的身体猛地一僵，脸上的狰狞还未来得及收起，眼中的邪恶光芒便渐渐黯淡下去。他的身体缓缓向后倒去，化为了一片尘土。"
  },
  [111690519] = {
    id = 111690519,
    name = "莉亚依旧站在原地，身姿挺拔，风吹动着她的长袍，宛如一尊女神雕像。"
  },
  [111690520] = {
    id = 111690520,
    name = "仿佛这时感应到了你的到来，她转过身，轻声朝你笑了笑。"
  },
  [111690521] = {
    id = 111690521,
    name = "你来了。"
  },
  [111690522] = {
    id = 111690522,
    name = "刚才那是......"
  },
  [111690523] = {
    id = 111690523,
    name = "堕落者。黑衣人的头目见打不过我，就吃了一瓶药，变成了那样。"
  },
  [111690524] = {
    id = 111690524,
    name = "尽管有所猜测，你心中还是有种不安的预感。"
  },
  [111690525] = {
    id = 111690525,
    name = "他从哪里得到制作堕落者的办法的？"
  },
  [111690526] = {
    id = 111690526,
    name = "他什么都不肯说。"
  },
  [111690527] = {
    id = 111690527,
    name = "......实不相瞒，我之前见过类似的组织，他们妄图将堕落者的力量纳为己用，但最终都落得灰飞烟灭的下场。"
  },
  [111690528] = {
    id = 111690528,
    name = "你是说，这种组织不止一个？"
  },
  [111690529] = {
    id = 111690529,
    name = "那只是我的猜测......况且线索断了，这些组织平日又在暗处行动，只能等了。"
  },
  [111690530] = {
    id = 111690530,
    name = "如果是这样......这些人并不是罪魁祸首，在我们看不见的地方，一定有个祸害世间的惊天阴谋。"
  },
  [111690531] = {
    id = 111690531,
    name = "莉亚第一次露出苦恼的神色。"
  },
  [111690532] = {
    id = 111690532,
    name = "那......我刚才是不是杀错了？"
  },
  [111690533] = {id = 111690533, name = "没有。"},
  [111690534] = {
    id = 111690534,
    name = "堕落者没有神智，只有杀戮，只有死亡才能救赎，救赎无辜人，也是救赎他们自己。"
  },
  [111690535] = {
    id = 111690535,
    name = "你不用有心理负担。"
  },
  [111690536] = {
    id = 111690536,
    name = "嗯，谢谢你。"
  },
  [111690537] = {
    id = 111690537,
    name = "谢我什么，快回去吧，伙伴们应该已经把商队的人救出来了。"
  },
  [111690538] = {id = 111690538, name = "好。"},
  [111690539] = {
    id = 111690539,
    name = "你们走了不远，前方就出现了几簇火把和绰绰人影。"
  },
  [111690540] = {
    id = 111690540,
    name = "队长！队长！"
  },
  [111690541] = {
    id = 111690541,
    name = "尼莉莎朝你们挥手，双眼锃亮，倒映着火光灼灼。"
  },
  [111690542] = {
    id = 111690542,
    name = "别挥了，队长已经看见了，晃得我眼睛疼。"
  },
  [111690543] = {
    id = 111690543,
    name = "就要晃，就要晃。"
  },
  [111690544] = {
    id = 111690544,
    name = "蒂娜一把推开尼莉莎，尼莉莎顺势往安妮斯怀里倒。"
  },
  [111690545] = {
    id = 111690545,
    name = "呜呜，安妮斯，我又被欺负了。"
  },
  [111690546] = {
    id = 111690546,
    name = "呵呵，小莎，老师已经来啦。"
  },
  [111690547] = {
    id = 111690547,
    name = "如何，都救出来了吗？"
  },
  [111690548] = {
    id = 111690548,
    name = "自然是不负所托。"
  },
  [111690549] = {
    id = 111690549,
    name = "在告诉她们之前，我就已经通知了公会，在你离开不久，公会的人也到了，现在那些商队都被安置去了就近的据点里。"
  },
  [111690550] = {
    id = 111690550,
    name = "那些黑衣人呢？"
  },
  [111690551] = {
    id = 111690551,
    name = "都自杀了，但看他们的样子不太像死士，所以是不是自杀，还要等公会调查。"
  },
  [111690552] = {
    id = 111690552,
    name = "这时莉亚走到了你身边，对你的同伴们打量了一番，露出了友善的笑。"
  },
  [111690553] = {
    id = 111690553,
    name = "队长，刚才就想问了，她是......"
  },
  [111690554] = {
    id = 111690554,
    name = "这位是莉亚小姐，为了救这队行商，她假意被抓进敌人巢穴，也是因为她，我才知道那群黑衣人的阴谋。"
  },
  [111690555] = {
    id = 111690555,
    name = "哇，不简单啊！你好啊，莉亚小姐！我叫尼莉莎，这是安妮斯、蒂娜，还有菲尼斯。"
  },
  [111690556] = {
    id = 111690556,
    name = "你们好，其实，莉亚只是我的化名，我的真名，叫阿斯特莉亚。"
  },
  [111690557] = {
    id = 111690557,
    name = "（这个名字......好像在哪里听过......）"
  },
  [111690558] = {
    id = 111690558,
    name = "很感谢你们的相助，能将他们救出来，还多亏了你们。"
  },
  [111690559] = {
    id = 111690559,
    name = "我们也是举手之劳。相比之下，阿斯特莉亚小姐孤身一人深入虎穴，为了陌生人冒险，更让人值得钦佩。"
  },
  [111690560] = {
    id = 111690560,
    name = "我当时也没有考虑太多，只想着既然是遇到了这件事，就不能不管。万事不能尽如人意，能有这样的结果，已经很好了。"
  },
  [111690561] = {
    id = 111690561,
    name = "哈哈，那你和队长还挺合得来的，菲尼斯说，队长也说了一模一样的话呢。"
  },
  [111690562] = {
    id = 111690562,
    name = "是......是吗？"
  },
  [111690563] = {
    id = 111690563,
    name = "呵呵，接下来阿斯特莉亚小姐有什么打算呢？"
  },
  [111690564] = {
    id = 111690564,
    name = "阿斯特莉亚顿了顿，她优雅地摊开手心，一张鎏金请帖在手中浮现。"
  },
  [111690565] = {
    id = 111690565,
    name = "海斯汀斯家族即将在秘密庄园举行宴会，我此次本是想过去的。只是没想到在路上发生了这样的事，也耽搁了一些时间。"
  },
  [111690566] = {id = 111690566, name = "这是？"},
  [111690567] = {
    id = 111690567,
    name = "这是海斯汀斯家族的舞会请帖，就赠予队长了。"
  },
  [111690568] = {
    id = 111690568,
    name = "听起来很有意思的感觉，但你把这个给我家队长，那你不去了？"
  },
  [111690569] = {
    id = 111690569,
    name = "我不需要，海斯汀斯家族是我本家的旁支，这次邀请各位去参加舞会，也是对你们能仗义出手的感激。"
  },
  [111690570] = {
    id = 111690570,
    name = "（原来是她......）"
  },
  [111690571] = {
    id = 111690571,
    name = "我希望你能收下，来秘密庄园参加舞会。"
  },
  [111690572] = {
    id = 111690572,
    name = "你还在犹豫是否会耽误行程时，蒂娜却突然开口。"
  },
  [111690573] = {
    id = 111690573,
    name = "队长，收下吧，不要辜负了阿斯特莉亚小姐一番好意。"
  },
  [111690574] = {
    id = 111690574,
    name = "我的天，蒂娜你转性了？"
  },
  [111690575] = {id = 111690575, name = "......"},
  [111690576] = {
    id = 111690576,
    name = "队长，阿斯特莉亚小姐盛情相邀，你难道忍心拒绝吗？"
  },
  [111690577] = {
    id = 111690577,
    name = "那就多谢了。"
  },
  [111690578] = {
    id = 111690578,
    name = "你拿过了那张请帖，上面有淡淡的魔法纹路，打开竟然有一张地图，上方画着秘密庄园的位置，算算距离，也就四五天的时间。"
  },
  [111690579] = {
    id = 111690579,
    name = "嗯？老师，这是什么？"
  },
  [111690580] = {
    id = 111690580,
    name = "打开请帖后，上方镶有一块可以取下的徽章，呈木质的圆盘形状，刻着繁杂的花纹，有魔法力蕴含其中。"
  },
  [111690581] = {
    id = 111690581,
    name = "据说这叫“女神的祝福”，是庄园主人送给客人的礼物。"
  },
  [111690582] = {
    id = 111690582,
    name = "女神？！"
  },
  [111690583] = {
    id = 111690583,
    name = "只是个噱头罢了，「希望女神」至高无上，对芸芸众生一视同仁，又怎么会仅仅将祝福赐予海斯汀斯呢？"
  },
  [111690584] = {
    id = 111690584,
    name = "说的也是哦。"
  },
  [111690585] = {
    id = 111690585,
    name = "呵呵，此间事了，我还要先去办一些事，就先走了。"
  },
  [111690586] = {
    id = 111690586,
    name = "阿斯特莉亚朝你淡淡地一笑。"
  },
  [111690587] = {
    id = 111690587,
    name = "那么，队长，期待与你再次相见。"
  },
  [111690588] = {
    id = 111690588,
    name = "好。再见，阿斯特莉亚小姐。"
  },
  [111620001] = {
    id = 111620001,
    name = "天色刚亮，春意裹着寒气铺洒在伽罗安据点里。"
  },
  [111620002] = {
    id = 111620002,
    name = "伽罗安据点不大，由一层白皙的薄雾笼罩在据点上空，浊炁极少渗透而下，朦胧地像被浸湿的画。"
  },
  [111620003] = {
    id = 111620003,
    name = "这时，据点西南角的一处院子里，油灯已亮起来了。"
  },
  [111620004] = {
    id = 111620004,
    name = "本已忙到大半夜的瑟瑞，今天再次起了个大早。"
  },
  [111620005] = {
    id = 111620005,
    name = "他小心掀开被窝，轻手轻脚地下床，还是惊扰到了身边正在沉睡的妻子。"
  },
  [111620006] = {
    id = 111620006,
    name = "亲爱的？"
  },
  [111620007] = {
    id = 111620007,
    name = "铃半睁着眼，迷迷糊糊地喊了一声。瑟瑞弯下腰在妻子额头轻柔地一吻。"
  },
  [111620008] = {
    id = 111620008,
    name = "探险队的人已经到了，我要早点出门。时间还早，你再睡一会儿。"
  },
  [111620009] = {id = 111620009, name = "嗯。"},
  [111620010] = {
    id = 111620010,
    name = "听到瑟瑞整理行李的声音，铃揉了揉睡眼，还是起了身。"
  },
  [111620011] = {
    id = 111620011,
    name = "时间还来得及，我烤几个干粮，你在路上吃吧。"
  },
  [111620012] = {
    id = 111620012,
    name = "没事，这次不远，我晚上就回来了。你怀着宝宝，要多休息才行。"
  },
  [111620013] = {
    id = 111620013,
    name = "瑟瑞半蹲在妻子身边，贴近了七八个月的大肚子，轻言细语地说。"
  },
  [111620014] = {
    id = 111620014,
    name = "宝宝，你要乖乖的，不要乱踢妈妈哦......哎哟。"
  },
  [111620015] = {
    id = 111620015,
    name = "话刚说完，瑟瑞感觉自己的脸上遭到了重重一击，他连忙扶住了妻子，妻子却习以为常，笑他的窘样。"
  },
  [111620016] = {
    id = 111620016,
    name = "呵呵，宝宝在和你打招呼呢。"
  },
  [111620017] = {
    id = 111620017,
    name = "两人都因这点小插曲笑了起来。"
  },
  [111620018] = {
    id = 111620018,
    name = "对了，你这回要是去圈落，记得带一些糖回来啊。"
  },
  [111620019] = {
    id = 111620019,
    name = "嗯？你想吃糖？想吃什么口味的？"
  },
  [111620020] = {
    id = 111620020,
    name = "什么啊，孩子要出生了，买一些糖，等孩子出生，好发给那些平日照顾我的邻居，是我父亲家乡那边的习惯，说这样对孩子好。"
  },
  [111620021] = {
    id = 111620021,
    name = "好好，你说买就买，还想要什么？"
  },
  [111620022] = {
    id = 111620022,
    name = "其他不用了，你之前买的布我还没做完衣服，宝宝一年都穿不完。"
  },
  [111620023] = {
    id = 111620023,
    name = "一年怎么够，我看隔壁的小家伙长得可快了，咱们的宝宝说不定比他窜得还快，不多准备点怎么行？"
  },
  [111620024] = {
    id = 111620024,
    name = "好了，快走吧。"
  },
  [111620025] = {
    id = 111620025,
    name = "铃为瑟瑞挂上行李，催促似地推了推他。"
  },
  [111620026] = {
    id = 111620026,
    name = "注意安全，早点回来。"
  },
  [111620027] = {
    id = 111620027,
    name = "嗯，我出门了，你回屋吧，别吹风了。"
  },
  [111620028] = {
    id = 111620028,
    name = "瑟瑞一步三回头，朝铃招了招手。直到看不见瑟瑞的身影，铃才转身回到小屋。"
  },
  [111620029] = {
    id = 111620029,
    name = "......这些日子瑟瑞经常出门，还是做一些干粮备着吧。"
  },
  [111620030] = {
    id = 111620030,
    name = "铃翻出了冬季囤下的几块镜饼，那些食物交叠地放在魔法坛子里，一直保持着阴凉干燥，一整年都不会腐坏。"
  },
  [111620031] = {
    id = 111620031,
    name = "她将镜饼切成了小块放在一边，又拿了一根长条的魔物腿。"
  },
  [111620032] = {
    id = 111620032,
    name = "魔物腿硬邦邦的，她吃力地砍了几刀，也没削下一块来，反而扯到了肚子。"
  },
  [111620033] = {
    id = 111620033,
    name = "她一个踉跄，魔物腿打翻了铁盆，叮铃哐啷响，她扶稳了墙边才没跌倒。"
  },
  [111620034] = {
    id = 111620034,
    name = "小铃，你没事吧？哎呀，这种小事叫我一声啊，你快好好歇着。"
  },
  [111620035] = {
    id = 111620035,
    name = "邻居路过，正好听到了响动，赶紧过来帮忙，把铃扶坐在床上。"
  },
  [111620036] = {
    id = 111620036,
    name = "我没事，谢谢你。"
  },
  [111620037] = {
    id = 111620037,
    name = "谢什么，瑟瑞没事就给我家小孩带点小东西，还教他耍大刀，前两天还跟我说要像瑟瑞一样去做个探险者呢。"
  },
  [111620038] = {
    id = 111620038,
    name = "伽罗安能这么安稳，你和你丈夫出了多少力气，大家都看在眼里的。"
  },
  [111620039] = {
    id = 111620039,
    name = "这魔物腿就这样宰吗？"
  },
  [111620040] = {
    id = 111620040,
    name = "呃，横切成几片就好。我想给瑟瑞做些干粮。"
  },
  [111620041] = {
    id = 111620041,
    name = "交给我吧，你就别动了。"
  },
  [111620042] = {
    id = 111620042,
    name = "我看瑟瑞这段日子经常出门啊，眼看你都要生了，怎么还四处乱走呢。"
  },
  [111620043] = {
    id = 111620043,
    name = "他说想趁现在孩子没出生，多挣些补贴家用，等孩子出生，就陪着我和孩子，哪儿也不去了。"
  },
  [111620044] = {
    id = 111620044,
    name = "真好啊......这魔物腿就这样行吗？"
  },
  [111620045] = {
    id = 111620045,
    name = "嗯，很好了，谢谢你。"
  },
  [111620046] = {
    id = 111620046,
    name = "都说了不用说谢谢，一会儿中午你就去我家吃吧。"
  },
  [111620047] = {
    id = 111620047,
    name = "邻居拉着铃的手腕，铃无法拒绝邀请，点了点头，从坛子里抓出来了一条半大不大的鱼。"
  },
  [111620048] = {
    id = 111620048,
    name = "这里有条腌鱼，拿去加个菜吧。"
  },
  [111620049] = {
    id = 111620049,
    name = "好好，那我家的娃又有口福啦。"
  },
  [111620050] = {
    id = 111620050,
    name = "你那个坛子可真好用啊，东西放里面都不坏的呀，上哪儿买的？"
  },
  [111620051] = {
    id = 111620051,
    name = "是我刻的魔法符文，能让食物一定时间的保鲜期，很基础的魔法。"
  },
  [111620052] = {
    id = 111620052,
    name = "真的？会不会影响你的身子？你这身体可出不得差错啊。"
  },
  [111620053] = {
    id = 111620053,
    name = "只是一点魔法，不碍事的。"
  },
  [111620054] = {
    id = 111620054,
    name = "你这么说我就不客气了，唉，会魔法就是好啊。"
  },
  [111620055] = {
    id = 111620055,
    name = "你们以后还能教孩子武技和魔法，一家三口一起探险，那可真让人羡慕。"
  },
  [111620056] = {
    id = 111620056,
    name = "呵呵，其实现在就很好，如果能和瑟瑞、孩子一起平静地生活，谁也不想过天天走在刀尖上的日子。"
  },
  [111620057] = {
    id = 111620057,
    name = "小铃真是温柔的人啊。"
  },
  [111620058] = {
    id = 111620058,
    name = "铃柔和地弯起嘴角，眼里都是幸福的样子。"
  },
  [111620059] = {
    id = 111620059,
    name = "两人说笑着到了隔壁，邻居的家人也很热情地招待着铃，铃想帮些什么都被劝到一边，对待她像瓷器般小心翼翼。"
  },
  [111620060] = {id = 111620060, name = "......"},
  [111620061] = {
    id = 111620061,
    name = "好了，这样食物就能保存得更久了。"
  },
  [111620062] = {
    id = 111620062,
    name = "铃把魔法符文拓印在了邻居装食物的坛子里。"
  },
  [111620063] = {
    id = 111620063,
    name = "谢谢你啊，小铃，这真是个好宝贝，多亏了你，以后咱们夏天的食物也不会坏了。"
  },
  [111620064] = {
    id = 111620064,
    name = "你们平时帮了我太多，这只是小小的答谢，应该的。"
  },
  [111620065] = {
    id = 111620065,
    name = "别见外了，大家抬头不见低头见，总有遇到难处的时候，快回去好好休息吧。"
  },
  [111620066] = {
    id = 111620066,
    name = "铃微笑着与邻居作别，慢悠悠回到了小屋。"
  },
  [111620067] = {
    id = 111620067,
    name = "屋中有邻居帮忙做好的干粮，铃用绳子封好，在上面扎了一个漂亮的蝴蝶结，想起瑟瑞看到它的样子，忍不住笑了笑。"
  },
  [111620068] = {
    id = 111620068,
    name = "瑟瑞应该在路上了吧。"
  },
  [111620069] = {
    id = 111620069,
    name = "铃慢慢坐在床边，拿起床旁边筐里的半件婴儿衣服，这件衣服只做了一半。"
  },
  [111620070] = {
    id = 111620070,
    name = "铃耐心地缝制着，一坐就坐到了晚上。"
  },
  [111620071] = {
    id = 111620071,
    name = "瑟瑞......还没回来啊。"
  },
  [111620072] = {
    id = 111620072,
    name = "铃有些担心，但又想起瑟瑞让她别担心，担心会影响心情，也会影响孩子。"
  },
  [111620073] = {
    id = 111620073,
    name = "不管怎样，吃点东西吧。"
  },
  [111620074] = {
    id = 111620074,
    name = "铃没有等瑟瑞，独自吃了饭，直到天完全黑了下去，整个据点都熄了灯，瑟瑞还没有回来。"
  },
  [111620075] = {
    id = 111620075,
    name = "哼，不守承诺，等你回来再和你清算了。"
  },
  [111620076] = {
    id = 111620076,
    name = "就罚他不许和我说话吧。"
  },
  [111620077] = {
    id = 111620077,
    name = "铃想着瑟瑞回来后，那一脸委屈求饶的模样，不禁抿着嘴微笑，安详睡去了。"
  },
  [111620078] = {
    id = 111620078,
    name = "一连十几日，瑟瑞仍然没有回来。"
  },
  [111620079] = {
    id = 111620079,
    name = "小铃啊，你也别太担心了，我家那个有时也是十天半月才有一点消息。"
  },
  [111620080] = {
    id = 111620080,
    name = "嗯，他向来有分寸的，这次应该是遇到一些事了吧。"
  },
  [111620081] = {
    id = 111620081,
    name = "是啊，是啊，瑟瑞一向稳重，不像那些愣头青，一个个不要命地去冒险。"
  },
  [111620082] = {
    id = 111620082,
    name = "邻居说着宽慰的话，正在院子里和铃一起晾晒衣物。"
  },
  [111620083] = {
    id = 111620083,
    name = "只是孩子快要出世了，他再不回来......"
  },
  [111620084] = {
    id = 111620084,
    name = "铃低声喃喃，轻轻摸了摸紧绷的肚子，小生命似乎知道她的担忧，在肚子里打了个滚，好似在安抚她。"
  },
  [111620085] = {
    id = 111620085,
    name = "来，小铃，牵着这头。"
  },
  [111620086] = {
    id = 111620086,
    name = "铃拿起被子一角，邻居牵起另一头，抖了抖，伸手一扬，被子平整地搭在了晾晒架上，动作十分娴熟。"
  },
  [111620087] = {
    id = 111620087,
    name = "麻烦你了。"
  },
  [111620088] = {
    id = 111620088,
    name = "都是小事，你一个人在家，什么都不方便，有什么需要就叫我一声。"
  },
  [111620089] = {
    id = 111620089,
    name = "两人正说着话，一个探险者急匆匆跑进了据点，一路走一路大喊着。"
  },
  [111620090] = {
    id = 111620090,
    name = "瑟瑞夫人，哪位是瑟瑞夫人，铃女士！有事，急事！"
  },
  [111620091] = {id = 111620091, name = "！！！"},
  [111620092] = {
    id = 111620092,
    name = "铃听见了动静，只看见探险者一人，心中猛地提了起来。"
  },
  [111620093] = {
    id = 111620093,
    name = "（大声）在这里！铃在这里！"
  },
  [111620094] = {
    id = 111620094,
    name = "别慌别慌，那人看起来只是着急，应该没出什么事。"
  },
  [111620095] = {
    id = 111620095,
    name = "但愿如此。"
  },
  [111620096] = {
    id = 111620096,
    name = "铃在心中默默祈祷了一声，看着年轻的探险者跑了过来，看了一眼铃和她的身形，再次确认。"
  },
  [111620097] = {
    id = 111620097,
    name = "呼，呼......您是铃女士，瑟瑞的夫人吧？"
  },
  [111620098] = {
    id = 111620098,
    name = "铃紧张地点了点头，什么也不敢问，等着他的消息。"
  },
  [111620099] = {
    id = 111620099,
    name = "瑟瑞有话让我带给你，他说......他买了糖，还有一些木匠做的东西，那些东西......"
  },
  [111620100] = {
    id = 111620100,
    name = "他，他呢？"
  },
  [111620101] = {
    id = 111620101,
    name = "瑟瑞人呢？怎么只让你带话？"
  },
  [111620102] = {
    id = 111620102,
    name = "哦，他说这次走得有点远，带的那些东西太多了，怕你担心，让我提前回来给你报个信。"
  },
  [111620103] = {
    id = 111620103,
    name = "他没受伤吧？"
  },
  [111620104] = {
    id = 111620104,
    name = "没呢，夫人放心，他最多明后天一定回来。"
  },
  [111620105] = {
    id = 111620105,
    name = "铃松了一口大气。"
  },
  [111620106] = {
    id = 111620106,
    name = "那就好，那就好......"
  },
  [111620107] = {id = 111620107, name = "唔......"},
  [111620108] = {
    id = 111620108,
    name = "铃刚卸下紧绷的一根弦，便觉得小腹一阵坠胀疼痛，顷刻间变了脸，拧着眉抓紧了邻居的手。"
  },
  [111620109] = {
    id = 111620109,
    name = "疼......疼......"
  },
  [111620110] = {
    id = 111620110,
    name = "哎呀，不好！你这情况，难道是要生了？！"
  },
  [111620111] = {
    id = 111620111,
    name = "邻居赶忙把铃扶向屋内，又嘱咐着探险者去准备热水与补血药剂，还一边安慰着铃。"
  },
  [111620112] = {
    id = 111620112,
    name = "别怕别怕，我是过来人，这时候别紧张，一定要放松，放松，放松......"
  },
  [111620113] = {
    id = 111620113,
    name = "嗯......好疼......"
  },
  [111620114] = {
    id = 111620114,
    name = "铃难受得就势躺倒在床上，不自觉低声哀嚎呼痛。"
  },
  [111620115] = {
    id = 111620115,
    name = "瑟瑞......好疼啊......"
  },
  [111620116] = {
    id = 111620116,
    name = "唉，你说这瑟瑞，天天在你面前晃，怎么关键时刻又不在呢！"
  },
  [111620117] = {
    id = 111620117,
    name = "热水、药剂，都准备好了！"
  },
  [111620118] = {
    id = 111620118,
    name = "别傻站着，赶紧去告诉瑟瑞啊！孩子出生，爹不在像什么话？！"
  },
  [111620119] = {
    id = 111620119,
    name = "可，可我还有别的任务......"
  },
  [111620120] = {
    id = 111620120,
    name = "有什么比生孩子还重要！这可是人命关天的大事！"
  },
  [111620121] = {
    id = 111620121,
    name = "别在这碍手碍脚的，出去出去。"
  },
  [111620122] = {
    id = 111620122,
    name = "邻居把探险者赶出了房门，如同恐吓般地说着。"
  },
  [111620123] = {
    id = 111620123,
    name = "快去报信！这女人生孩子，就是去地狱门口晃荡，要是没有家人拉着，很容易被带走的！他要赶不回来，会后悔一辈子！"
  },
  [111620124] = {
    id = 111620124,
    name = "我，我这就去！"
  },
  [111620125] = {
    id = 111620125,
    name = "探险者似乎被吓到了，跑得飞快，邻居又招呼了几个女人进铃的家里帮忙。"
  },
  [111620126] = {
    id = 111620126,
    name = "整一天一夜，铃一直处于难产的状态，她的脑子空白，如同受刑般痛苦凄惨地叫着。"
  },
  [111620127] = {
    id = 111620127,
    name = "瑟瑞......好疼......你在哪里......"
  },
  [111620128] = {
    id = 111620128,
    name = "她的面色苍白，豆大的汗珠不断从额头滚落，痛苦的呻吟声在房间里回荡。"
  },
  [111620129] = {
    id = 111620129,
    name = "加油啊，铃，使劲！"
  },
  [111620130] = {
    id = 111620130,
    name = "我......我真的没力气了......"
  },
  [111620131] = {
    id = 111620131,
    name = "她脑子疼得糊涂，不禁开始瞎想，想瑟瑞是不是出了事，故意让人报喜不报忧，要不怎么还没回来呢。"
  },
  [111620132] = {
    id = 111620132,
    name = "一钻牛角尖，就再也出不来了，她一会儿觉得辛苦了这么久，瑟瑞这么久没回来，一定出事了，不如就这么跟他一起死了；"
  },
  [111620133] = {
    id = 111620133,
    name = "一会儿又觉得，这么多苦日子都过来了，瑟瑞在她最需要的时候不在，是不是厌倦她了......"
  },
  [111620134] = {
    id = 111620134,
    name = "小铃！！！"
  },
  [111620135] = {
    id = 111620135,
    name = "房屋的门被猛地推开，瑟瑞风尘仆仆地出现，三步并作两步冲到床边。"
  },
  [111620136] = {
    id = 111620136,
    name = "你回来了......"
  },
  [111620137] = {
    id = 111620137,
    name = "小铃，我在，我回来了！"
  },
  [111620138] = {
    id = 111620138,
    name = "他看着邻居满手的血，扑通一声跪下，紧紧抓住铃的手，眼中满是心疼与焦急。"
  },
  [111620139] = {
    id = 111620139,
    name = "亲爱的......刚才......我好害怕......"
  },
  [111620140] = {
    id = 111620140,
    name = "别怕！我在这陪着你，咱们的孩子一定会平安出生的，你也一定会安然无恙！"
  },
  [111620141] = {
    id = 111620141,
    name = "似乎从瑟瑞的话语中获得了力量，铃紧紧咬着牙关，拼尽力气喊出了声。"
  },
  [111620142] = {id = 111620142, name = "......"},
  [111620143] = {
    id = 111620143,
    name = "不知过了多久，通宵达旦的房屋里传来一声响亮的啼哭，清脆洪亮。"
  },
  [111620144] = {
    id = 111620144,
    name = "孩子终于出生了。"
  },
  [111620145] = {
    id = 111620145,
    name = "小铃......"
  },
  [111620146] = {
    id = 111620146,
    name = "瑟瑞顿时红了眼眶，吻了吻面色惨白的铃，才转头去看邻居抱过来的婴儿。"
  },
  [111620147] = {
    id = 111620147,
    name = "是个女孩，恭喜恭喜啊，母女平安真是太好了。"
  },
  [111620148] = {
    id = 111620148,
    name = "女婴生下来皱巴巴的，这时裹在软被里，小小的一团，瑟瑞的心化成了一滩水，轻手轻脚地抱在铃的面前。"
  },
  [111620149] = {
    id = 111620149,
    name = "你看，铃，这是我们的女儿......"
  },
  [111620150] = {
    id = 111620150,
    name = "铃喝了药剂，恢复了些力气，这时才看向女婴，失神地笑了笑。"
  },
  [111620151] = {
    id = 111620151,
    name = "这是我们的女儿......"
  },
  [111620152] = {
    id = 111620152,
    name = "铃，你受苦了......"
  },
  [111620153] = {
    id = 111620153,
    name = "你一直没回来，我担心，又怕不好的心情会影响孩子，只能一直找事做......也许是这样，才让孩子提前出来了......"
  },
  [111620154] = {
    id = 111620154,
    name = "对不起，是我回来晚了。"
  },
  [111620155] = {
    id = 111620155,
    name = "回来就好。"
  },
  [111620156] = {
    id = 111620156,
    name = "铃望着瑟瑞，笑着抚上他强打起精神的脸。"
  },
  [111620157] = {
    id = 111620157,
    name = "欢迎回家，回我们的家。"
  },
  [111620158] = {
    id = 111620158,
    name = "名字？小名就叫西西，多可爱啊！"
  },
  [111620159] = {
    id = 111620159,
    name = "西西......呵呵，你是怎么想到这个名字的？"
  },
  [111620160] = {
    id = 111620160,
    name = "西西，西西，每次喊她的时候，嘴巴都要弯起来，不就是在笑吗？"
  },
  [111620161] = {
    id = 111620161,
    name = "这样不管是我们，还是其他人，只要和宝贝说话，都会笑着叫她西西。"
  },
  [111620162] = {
    id = 111620162,
    name = "她是我们永远的宝贝，永远会看到别人笑脸的宝贝。"
  },
  [111620163] = {
    id = 111620163,
    name = "“哇——”"
  },
  [111620164] = {
    id = 111620164,
    name = "这时，粉团似的西西在瑟瑞怀里大哭了起来，瑟瑞忙哼着唱着哄着她，却怎么也哄不好。"
  },
  [111620165] = {
    id = 111620165,
    name = "西西是不是饿了？"
  },
  [111620166] = {
    id = 111620166,
    name = "瑟瑞反应了过来，忙把孩子给铃，转身跑出了门。"
  },
  [111620167] = {
    id = 111620167,
    name = "我去找人，问问西西能吃什么，什么不能吃！"
  },
  [111620168] = {
    id = 111620168,
    name = "铃愣了愣，想起邻居早教给自己的哺育知识，摇了摇头。"
  },
  [111620169] = {
    id = 111620169,
    name = "当了父亲，还是一个笨蛋。"
  },
  [111620170] = {id = 111620170, name = "......"},
  [111620171] = {
    id = 111620171,
    name = "也不知瑟瑞是不是问过了邻居，等铃喂完西西，他还是没回来。"
  },
  [111620172] = {
    id = 111620172,
    name = "铃抱着西西出了门，热闹的声音如同被撕掉了隔音结界，奔涌而来。"
  },
  [111620173] = {
    id = 111620173,
    name = "恭喜恭喜啊，给孩子取名了没有呀？"
  },
  [111620174] = {
    id = 111620174,
    name = "叫西西。"
  },
  [111620175] = {
    id = 111620175,
    name = "好名字好名字，听起来就让人高兴啊！"
  },
  [111620176] = {
    id = 111620176,
    name = "西西是妹妹吗？"
  },
  [111620177] = {
    id = 111620177,
    name = "对啊，是妹妹。来吃糖，大家都吃！"
  },
  [111620178] = {
    id = 111620178,
    name = "呵呵，是小铃的主意吧，真好啊。"
  },
  [111620179] = {
    id = 111620179,
    name = "瑟瑞被一群人围在中间，挨个发了一包糖，眼睛笑得眯成了缝。"
  },
  [111620180] = {
    id = 111620180,
    name = "看到铃的出现，众人又凑上来恭贺了一番，才各自离开。"
  },
  [111620181] = {
    id = 111620181,
    name = "小铃，你看看这个怎么样？"
  },
  [111620182] = {
    id = 111620182,
    name = "瑟瑞指着院门口才搭起来的花圃，煞有其事地说。"
  },
  [111620183] = {
    id = 111620183,
    name = "这次我们去的那座山里，我发现了很像郁金香的花，我知道你喜欢，就想把这一片也辟出来。"
  },
  [111620184] = {
    id = 111620184,
    name = "铃笑着，仔细辨认了一下旁边的风信子，由衷评价。"
  },
  [111620185] = {
    id = 111620185,
    name = "那这里的石头桌子就不太好看了，不如搭个秋千，上面绕一些紫藤，又漂亮又好玩。"
  },
  [111620186] = {
    id = 111620186,
    name = "好啊，等西西长大些了，我还能推着你们俩在上面玩。"
  },
  [111620187] = {
    id = 111620187,
    name = "这块地可以铺几块石砖和石凳，天气好的时候，就在外面吃饭。"
  },
  [111620188] = {
    id = 111620188,
    name = "好，好。"
  },
  [111620189] = {
    id = 111620189,
    name = "铃喜笑颜开，继续构想着。"
  },
  [111620190] = {
    id = 111620190,
    name = "那边的河水，可以想办法挖一条沟，把活水引过来，旁边再种一棵净魔树......"
  },
  [111620191] = {
    id = 111620191,
    name = "算了，找净魔树太危险了，就移植一些莹草，那个长得快，少一些浊炁，西西住的环境也好。"
  },
  [111620192] = {
    id = 111620192,
    name = "嗯，都听你的。"
  },
  [111620193] = {
    id = 111620193,
    name = "对了，我还给西西买了很多玩具，那时候不知道是男孩还是女孩，就什么都买了一些。"
  },
  [111620194] = {
    id = 111620194,
    name = "瑟瑞把门口的储物箱子打开，里面摆满了各种木匠做的小玩意儿，刀剑法杖，玩偶手环，一应俱全。"
  },
  [111620195] = {
    id = 111620195,
    name = "瑟瑞拿着一把小法杖在西西跟前晃，被西西一手打开，西西的小手被打红了，哭得哇哇叫。"
  },
  [111620196] = {
    id = 111620196,
    name = "啊，西西不哭，爸爸的错！"
  },
  [111620197] = {
    id = 111620197,
    name = "西西依旧哭得响亮。铃抱着西西，好整以暇地看着慌乱的瑟瑞。"
  },
  [111620198] = {
    id = 111620198,
    name = "看这个，这个喜欢吗？"
  },
  [111620199] = {
    id = 111620199,
    name = "瑟瑞拿起一个玩偶，西西哭得更厉害了。"
  },
  [111620200] = {
    id = 111620200,
    name = "这个呢，这个魔法石，亮闪闪的哦！"
  },
  [111620201] = {
    id = 111620201,
    name = "西西哭声变小了，但却转过了眼，似乎并不感兴趣。"
  },
  [111620202] = {
    id = 111620202,
    name = "怎么感觉被嫌弃了......"
  },
  [111620203] = {
    id = 111620203,
    name = "喜欢魔法吗？唔......西西还小，要教她学魔法还是太早了吧。"
  },
  [111620204] = {
    id = 111620204,
    name = "我认识一个圈落的言灵师，是在管理处做学者的，除了咱们教她启蒙的东西，还是需要一个老师。"
  },
  [111620205] = {
    id = 111620205,
    name = "好好，我家西西一定有魔法天赋，你看，她对魔法有感应哦！"
  },
  [111620206] = {
    id = 111620206,
    name = "呵呵，好呀，等你会说话了，妈妈就教你魔法。"
  },
  [111620207] = {
    id = 111620207,
    name = "铃抱着西西蹲在箱子边，魔法石一闪一闪吸引着她的目光。"
  },
  [111620208] = {
    id = 111620208,
    name = "瑟瑞拿着一个又一个木质的“武器”逗弄着西西玩，等到拿出小短剑时候，竟然被西西一把抓住了。"
  },
  [111620209] = {
    id = 111620209,
    name = "西西，这个很危险。"
  },
  [111620210] = {
    id = 111620210,
    name = "西西抓紧不放，瑟瑞不敢跟她争，西西把剑完全拿在手里，重新发出了咯咯的笑声。"
  },
  [111620211] = {
    id = 111620211,
    name = "西西喜欢耍剑啊，好好，等你大些了，爸爸送一柄好剑。"
  },
  [111620212] = {
    id = 111620212,
    name = "呵呵，她哪里懂这些，还是学妈妈的魔法更安全一些。"
  },
  [111620213] = {
    id = 111620213,
    name = "好，都学，都学。"
  },
  [111620214] = {
    id = 111620214,
    name = "两人抱着娃，笑着依偎在一起。"
  },
  [111620215] = {
    id = 111620215,
    name = "亲爱的，咱们找个时间回玛蒙怎么样？"
  },
  [111620216] = {
    id = 111620216,
    name = "......嗯。伽罗安虽然有净化浊炁的结界，但对西西的成长始终不好，回去也好，我们筹备些东西，等西西大些了，再带她下来。"
  },
  [111620217] = {
    id = 111620217,
    name = "嗯，好。"
  },
  [111620218] = {
    id = 111620218,
    name = "以后啊，咱们一家人，天天在一起，就算探险也能一起，等西西嫁人......不，暂时不想她嫁人的事。"
  },
  [111620219] = {
    id = 111620219,
    name = "让我来说，以后西西一定会比我们厉害。"
  },
  [111620220] = {
    id = 111620220,
    name = "她想去哪儿就去哪儿，可以走得更远，去我们不曾去过的，或者我们老了之后去不了的地方。"
  },
  [111620221] = {
    id = 111620221,
    name = "她会活得自由自在，成为她想成为的样子。"
  },
  [111620222] = {
    id = 111620222,
    name = "嗯，一定会的。"
  },
  [111620223] = {
    id = 111620223,
    name = "春去秋来，临近冬日，西西已经大半岁了。"
  },
  [111620224] = {
    id = 111620224,
    name = "除了咿咿呀呀地叫着，她还学会了翻身，抓握，以及短暂的爬行。"
  },
  [111620225] = {
    id = 111620225,
    name = "西西乖，♪♪♪......"
  },
  [111620226] = {
    id = 111620226,
    name = "铃哄着孩子睡着了，拿起布料继续缝制新衣。"
  },
  [111620227] = {
    id = 111620227,
    name = "西西长得很快，铃正抓紧时间为她制作冬装，这时外面出现了一阵喧闹声。"
  },
  [111620228] = {
    id = 111620228,
    name = "咯......嘤嘤......"
  },
  [111620229] = {
    id = 111620229,
    name = "西西醒了呀，我们出去看看什么事吧？"
  },
  [111620230] = {
    id = 111620230,
    name = "铃抱着西西出门，瑟瑞正好拿着东西回屋，铃看向街角处询问。"
  },
  [111620231] = {
    id = 111620231,
    name = "那边怎么有那么多人？"
  },
  [111620232] = {
    id = 111620232,
    name = "小五出门摘莹草，捡了个受重伤的探险者回来。"
  },
  [111620233] = {
    id = 111620233,
    name = "重伤？是魔物？"
  },
  [111620234] = {
    id = 111620234,
    name = "嗯，看起来伤口有很多种，给那家伙包扎的人说，应该不止一种魔物。"
  },
  [111620235] = {
    id = 111620235,
    name = "我也会一点治愈魔法，去看看能不能帮上忙吧。"
  },
  [111620236] = {
    id = 111620236,
    name = "小铃，你的身体才恢复，现在经不起消耗的。"
  },
  [111620237] = {
    id = 111620237,
    name = "没事，我心里有数。"
  },
  [111620238] = {
    id = 111620238,
    name = "伽罗安附近很久没有出现过魔物了，这个情况让我有些担心。"
  },
  [111620239] = {
    id = 111620239,
    name = "瑟瑞认为铃的考虑有道理，决定和铃一起去看看。"
  },
  [111620240] = {
    id = 111620240,
    name = "两人到了人群聚集处，正好看见那昏迷的探险者被抬到了一个邻居的院子里。"
  },
  [111620241] = {
    id = 111620241,
    name = "就放这里，放草席上，对轻点，慢点放下。"
  },
  [111620242] = {
    id = 111620242,
    name = "这进气多出气少的，怕是过不了今晚了啊。"
  },
  [111620243] = {
    id = 111620243,
    name = "血我已经用药剂止住了，就是他被魔物抓伤的地方还有浊炁侵蚀的痕迹，莹草只能阻止不让浊炁扩散，这伤还得要靠他自己熬过来啊。"
  },
  [111620244] = {
    id = 111620244,
    name = "唉，你说年纪轻轻的，就去干这些不要命的活，图什么呢。"
  },
  [111620245] = {
    id = 111620245,
    name = "让我看看吧。"
  },
  [111620246] = {
    id = 111620246,
    name = "铃把西西交给瑟瑞，走到了那名探险者面前。"
  },
  [111620247] = {
    id = 111620247,
    name = "对哦，小铃是会魔法的啊，快给他瞧瞧，这人还有没有救。"
  },
  [111620248] = {
    id = 111620248,
    name = "铃半蹲在探险者身边，手心亮起了魔法的光，缓缓落在了探险者的伤口处。"
  },
  [111620249] = {
    id = 111620249,
    name = "小铃......"
  },
  [111620250] = {
    id = 111620250,
    name = "浊炁已经侵入心肺了，再不清除会侵蚀全身，到时我们面对的不只是他的死亡，甚至有堕落者的可能。"
  },
  [111620251] = {
    id = 111620251,
    name = "堕落者！！那可怕的啊！"
  },
  [111620252] = {
    id = 111620252,
    name = "邻居们听着后退了好几步，躲得远远的，仔细盯着铃施展魔法。"
  },
  [111620253] = {
    id = 111620253,
    name = "小铃，你别太勉强。"
  },
  [111620254] = {
    id = 111620254,
    name = "铃紧抿着唇，魔法力源源不断地治愈着伤者，她的额头逐渐渗出薄汗，脸色也开始苍白。"
  },
  [111620255] = {
    id = 111620255,
    name = "众人紧张地看着，瑟瑞也没有打扰她，直到最后一丝黑气从伤者体内拔除，魔法光芒才消失了。"
  },
  [111620256] = {
    id = 111620256,
    name = "小铃，你还好吗？"
  },
  [111620257] = {
    id = 111620257,
    name = "瑟瑞扶着虚弱的铃，铃笑着摇头。"
  },
  [111620258] = {
    id = 111620258,
    name = "只是有点累，这位探险者的体内没有浊炁了，等他苏醒过来，就能慢慢康复。"
  },
  [111620259] = {
    id = 111620259,
    name = "就是说他不会变堕落者了？能治好了吧？小铃这可是帮了大忙啊。"
  },
  [111620260] = {
    id = 111620260,
    name = "喂，你们看，他是不是要醒了！"
  },
  [111620261] = {
    id = 111620261,
    name = "探险者眉头紧皱，似是忍受不了痛苦，终于睁开了眼睛。"
  },
  [111620262] = {
    id = 111620262,
    name = "......我没死？"
  },
  [111620263] = {
    id = 111620263,
    name = "没死，你命大，被小五捡到了，换个人还没那个力气把你扛回来呢。"
  },
  [111620264] = {
    id = 111620264,
    name = "探险者发现身上缓慢愈合的伤势和嘴里药剂的苦涩味道，对眼前和颜悦色的人们十分感激。"
  },
  [111620265] = {
    id = 111620265,
    name = "谢谢你们救了我......这里是哪里？"
  },
  [111620266] = {
    id = 111620266,
    name = "这里是伽罗安据点，你去的那座山应该看得见咱们据点的净化罩子吧？"
  },
  [111620267] = {
    id = 111620267,
    name = "说起来你是怎么受伤的啊？小五说你这身伤是魔物抓的，是不是真的啊？"
  },
  [111620268] = {
    id = 111620268,
    name = "探险者点了点头，四周的人们却露出了惊讶和紧张的表情。"
  },
  [111620269] = {
    id = 111620269,
    name = "怎么回事哦，伽罗安附近不是好几年没有魔物走动了嘛？"
  },
  [111620270] = {
    id = 111620270,
    name = "有精英探险队经常来清扫的嘛，浊炁也一年比一年淡，一般都没有魔物过来的，那些魔物是从哪里跑来的呀？"
  },
  [111620271] = {
    id = 111620271,
    name = "是魔物群。很多魔物，他们聚集在山的那头，越来越多......"
  },
  [111620272] = {
    id = 111620272,
    name = "我和队友走散了，拼着最后一口气才到了山里晕了过去，后来就被你们救回来了......"
  },
  [111620273] = {
    id = 111620273,
    name = "糟糕，那不就和伽罗安只隔了一座山？那些魔物过来可怎么办啊？"
  },
  [111620274] = {
    id = 111620274,
    name = "不、不会这么巧，是往这边来的吧？"
  },
  [111620275] = {
    id = 111620275,
    name = "他的话说完，四周陷入了沉默。"
  },
  [111620276] = {
    id = 111620276,
    name = "伽罗安据点安逸祥和，很久没有魔物的威胁，面对突如其来的消息，大家都不免露出了担忧的神情。"
  },
  [111620277] = {id = 111620277, name = "......"},
  [111620278] = {
    id = 111620278,
    name = "小铃，别担心，据点的防御工事一直在维护，这几天我带他们一起再进行加固一番。"
  },
  [111620279] = {
    id = 111620279,
    name = "是的啊，有了那些防御工事，一般的魔物还是进不来的，大家都不要太担心呵呵呵呵......"
  },
  [111620280] = {
    id = 111620280,
    name = "咳，我们还有帮手啊，可以去找驻扎在圈落的探险队！"
  },
  [111620281] = {
    id = 111620281,
    name = "对对，只要他们来，再清扫一遍，那些魔物就不会再过来啦！"
  },
  [111620282] = {
    id = 111620282,
    name = "嗯，我还记得圈落里可以发布委托到公会，请探险者来守护伽罗安也是可以的。"
  },
  [111620283] = {
    id = 111620283,
    name = "没错，有这么多办法，大家都不要慌。"
  },
  [111620284] = {
    id = 111620284,
    name = "之前那么多次危机我们都平安过来了，这次也一定可以。"
  },
  [111620285] = {
    id = 111620285,
    name = "嗯！我们立刻找人去报信，那几个探险队我都有熟人的。"
  },
  [111620286] = {
    id = 111620286,
    name = "好，好！有瑟瑞在，就是让人安心啊。"
  },
  [111620287] = {
    id = 111620287,
    name = "......嗯。"
  },
  [111620288] = {
    id = 111620288,
    name = "这日傍晚，铃和瑟瑞正在吃饭的时候，来了一位客人。"
  },
  [111620289] = {
    id = 111620289,
    name = "请问，铃大人是住这里吗？"
  },
  [111620290] = {
    id = 111620290,
    name = "是你？找小铃什么事？"
  },
  [111620291] = {
    id = 111620291,
    name = "当时我神志不清，只知道有人救了我，后来他们说是铃大人，我这次是特意来道谢的。"
  },
  [111620292] = {
    id = 111620292,
    name = "不用叫我大人，叫名字就行。"
  },
  [111620293] = {
    id = 111620293,
    name = "无论如何，这是救命的恩情，请允许我真诚地谢谢您！"
  },
  [111620294] = {
    id = 111620294,
    name = "探险者深深鞠了一躬，铃无措地站着，瑟瑞拍了拍她的肩膀，铃就硬生生地接下了这个谢意。"
  },
  [111620295] = {
    id = 111620295,
    name = "小铃，这是你应得的。"
  },
  [111620296] = {
    id = 111620296,
    name = "......我们也应该谢谢他，是他带来了很关键的消息，才能让我们今早做防备。"
  },
  [111620297] = {
    id = 111620297,
    name = "嗯，你说得对。"
  },
  [111620298] = {
    id = 111620298,
    name = "不，不用了，我什么忙也没帮上。"
  },
  [111620299] = {
    id = 111620299,
    name = "探险者挠了挠头，笑了笑。"
  },
  [111620300] = {
    id = 111620300,
    name = "其实，我这次来，是向你们辞行的。"
  },
  [111620301] = {
    id = 111620301,
    name = "我和队友走散，现在要去跟他们汇合了......这个卷轴，请你们收下。"
  },
  [111620302] = {
    id = 111620302,
    name = "探险者拿出一张魔法卷轴递了过来。"
  },
  [111620303] = {
    id = 111620303,
    name = "这是一张防御的卷轴，里面有一些防御的魔法符文，可以护住心脏的部分。"
  },
  [111620304] = {
    id = 111620304,
    name = "我先前就是因为它才逃过一命，没被魔物杀掉。"
  },
  [111620305] = {
    id = 111620305,
    name = "我没有什么好东西，这个虽然......已经用过了，但我看了，还有效用的，请一定不要嫌弃！"
  },
  [111620306] = {
    id = 111620306,
    name = "......你离开据点还要去探险，这个留着对你更有用。"
  },
  [111620307] = {
    id = 111620307,
    name = "铃大人，这是我的一片心意，请不要拒绝了。"
  },
  [111620308] = {
    id = 111620308,
    name = "探险者说什么也不肯拿回去，铃看他执拗，只好收下了。"
  },
  [111620309] = {
    id = 111620309,
    name = "等我寻到了更好的宝物，会再回来看你们的。"
  },
  [111620310] = {
    id = 111620310,
    name = "探险者显得十分开心，再三感谢之后，才和两人说了再见。"
  },
  [111620311] = {
    id = 111620311,
    name = "年轻真有活力啊，这么快伤就好了。"
  },
  [111620312] = {
    id = 111620312,
    name = "呵呵，你也不老的。"
  },
  [111620313] = {
    id = 111620313,
    name = "两人笑着吃完了饭，瑟瑞想趁天还没黑，打算再去和人一起加固防御工事。"
  },
  [111620314] = {
    id = 111620314,
    name = "早点回家。"
  },
  [111620315] = {
    id = 111620315,
    name = "......嗯，我今天可以不去。"
  },
  [111620316] = {
    id = 111620316,
    name = "瑟瑞一副莫名脸红的样子，铃戳了戳他的脑袋。"
  },
  [111620317] = {
    id = 111620317,
    name = "想什么呢，晚上西西看不见你老哭的。"
  },
  [111620318] = {
    id = 111620318,
    name = "没有！你说得对，是该早点回来。"
  },
  [111620319] = {
    id = 111620319,
    name = "噗......快走吧。"
  },
  [111620320] = {
    id = 111620320,
    name = "铃把瑟瑞推到门口，转身走向院子，院子还在修正，秋千正好搭了一半。"
  },
  [111620321] = {
    id = 111620321,
    name = "铃路过时踉跄了一下，被绊倒的木杆横着，整个人扑在地上摔了一跤。"
  },
  [111620322] = {
    id = 111620322,
    name = "小铃！！！"
  },
  [111620323] = {
    id = 111620323,
    name = "瑟瑞慌忙跑了过来，胸膛急剧起伏，从头到脚打量着铃。"
  },
  [111620324] = {
    id = 111620324,
    name = "你的脚受伤了，我给你上药！"
  },
  [111620325] = {
    id = 111620325,
    name = "那么紧张干什么，以前我们一起探险的时候，也没少受伤。"
  },
  [111620326] = {
    id = 111620326,
    name = "都一样，以前心疼，现在更心疼。"
  },
  [111620327] = {
    id = 111620327,
    name = "瑟瑞拿着药粉轻柔地抹在铃受伤的小腿上，这时屋内正好传来了西西的哭声。"
  },
  [111620328] = {
    id = 111620328,
    name = "去看看西西。"
  },
  [111620329] = {
    id = 111620329,
    name = "瑟瑞扶着铃进屋，抱着大哭的西西哄了又哄，仍然不起作用。"
  },
  [111620330] = {
    id = 111620330,
    name = "西西是不是又饿了？"
  },
  [111620331] = {
    id = 111620331,
    name = "嗯，算着时间，是该喂了。"
  },
  [111620332] = {
    id = 111620332,
    name = "铃正要起身被瑟瑞阻止，他放下西西，对着一排的瓶罐。"
  },
  [111620333] = {
    id = 111620333,
    name = "我来我来，你告诉我怎么做。"
  },
  [111620334] = {
    id = 111620334,
    name = "我来就行，你还是先去加固防御工事吧。"
  },
  [111620335] = {
    id = 111620335,
    name = "不去了。你都受伤了，我要留下照顾你和西西。"
  },
  [111620336] = {
    id = 111620336,
    name = "铃笑着点点头，告诉瑟瑞怎么做西西的辅食。"
  },
  [111620337] = {
    id = 111620337,
    name = "瑟瑞手忙脚乱地忙了好一阵，端出了一碗黑乎乎的东西，有些丧气。"
  },
  [111620338] = {
    id = 111620338,
    name = "小铃，我是不是有点笨。"
  },
  [111620339] = {
    id = 111620339,
    name = "只是在料理上没有天赋吧。"
  },
  [111620340] = {
    id = 111620340,
    name = "铃没有否认，捂嘴笑了笑，一个步骤一个步骤指点瑟瑞去做，总算做出了一顿能让西西吃下去的辅食。"
  },
  [111620341] = {
    id = 111620341,
    name = "宝贝，吃饭啦~"
  },
  [111620342] = {
    id = 111620342,
    name = "瑟瑞在铃的叮嘱下，再三试过了温度和味道，才一口一口喂西西吃掉了。"
  },
  [111620343] = {
    id = 111620343,
    name = "西西真乖，除了饿的时候，从来不闹。"
  },
  [111620344] = {id = 111620344, name = "嗯。"},
  [111620345] = {
    id = 111620345,
    name = "铃唱着小调，把西西哄得睡着了。"
  },
  [111620346] = {
    id = 111620346,
    name = "亲爱的......"
  },
  [111620347] = {
    id = 111620347,
    name = "瑟瑞正想说些什么，外面一阵喧嚣响起，邻居奔跑着大吼的声音惊动了所有人。"
  },
  [111620348] = {
    id = 111620348,
    name = "啊啊啊！魔物、魔物来了！！"
  },
  [111620349] = {id = 111620349, name = "！！！"},
  [111620350] = {
    id = 111620350,
    name = "怎么会？！下午的时候，出去探测的人都说没动静的！"
  },
  [111620351] = {
    id = 111620351,
    name = "瑟瑞把床边的魔法卷轴交给铃，紧张地看了两人一眼。"
  },
  [111620352] = {
    id = 111620352,
    name = "我先出去看看情况！你和西西留在这里。"
  },
  [111620353] = {
    id = 111620353,
    name = "......嗯，要小心啊，情况不对，尽快回来。"
  },
  [111620354] = {
    id = 111620354,
    name = "我知道，如果要走，拼了这条命，我也会带你们母女离开！"
  },
  [111620355] = {
    id = 111620355,
    name = "瑟瑞开门而出，又将嘈乱惊惶的声音关在了门外，只留下不安的铃和熟睡的西西。"
  },
  [111620356] = {
    id = 111620356,
    name = "弓箭，弓箭呢！！"
  },
  [111620357] = {
    id = 111620357,
    name = "弓箭在这里，妈妈，我帮叔叔们搬来了！"
  },
  [111620358] = {
    id = 111620358,
    name = "你来这里干什么，快回家！"
  },
  [111620359] = {
    id = 111620359,
    name = "不，我的力气比妈妈大，我要和妈妈一起守护伽罗安！"
  },
  [111620360] = {
    id = 111620360,
    name = "据点入口处，远处的黑云渐渐逼近，常住在据点的人们纷纷从家中冲出，准备抵抗即将到来的魔物。"
  },
  [111620361] = {
    id = 111620361,
    name = "快来了，大家准备！"
  },
  [111620362] = {
    id = 111620362,
    name = "魔物怎么这么多！"
  },
  [111620363] = {
    id = 111620363,
    name = "黑暗仿佛要将一切吞噬，成群的魔物如汹涌的黑色潮水般，疯狂地朝着据点奔腾而来。"
  },
  [111620364] = {
    id = 111620364,
    name = "大家别怕，我们一定能守住！"
  },
  [111620365] = {
    id = 111620365,
    name = "瑟瑞紧紧握着锋利的剑，身旁的邻居们也严阵以待，他们双手握着弓箭，指关节因用力过度，手心里满是汗水。"
  },
  [111620366] = {
    id = 111620366,
    name = "对，以前可以，这一次也一定可以！"
  },
  [111620367] = {
    id = 111620367,
    name = "瑟瑞听得出他的内心也在颤抖，毕竟眼前的魔物数量如此之多，是以前从未有过的。"
  },
  [111620368] = {
    id = 111620368,
    name = "但他们都知道不能退缩，在深渊常住，迟早会有这么一天，如果守不住伽罗安，那到哪里都不会安宁。"
  },
  [111620369] = {
    id = 111620369,
    name = "这时，一只体型巨大的魔物率先扑了过来。"
  },
  [111620370] = {
    id = 111620370,
    name = "瑟瑞迅速挥剑，一道银色的剑光闪过，与那黑色魔物碰撞在一起，发出“砰”的一声巨响。"
  },
  [111620371] = {
    id = 111620371,
    name = "但这只魔物只是先锋队，后面还有更多的魔物源源不断地涌来，他的心一下子提到了嗓子眼。"
  },
  [111620372] = {
    id = 111620372,
    name = "大家放箭！！后面的魔物上来了！"
  },
  [111620373] = {
    id = 111620373,
    name = "一支支箭矢飞过，直直射向一只正欲扑向瑟瑞的魔物，魔物纷纷受伤倒地。"
  },
  [111620374] = {
    id = 111620374,
    name = "瑟瑞，小心后面！"
  },
  [111620375] = {
    id = 111620375,
    name = "邻居大声喊着。瑟瑞猛地转身，只见一只狡猾的魔物正企图偷袭他。"
  },
  [111620376] = {
    id = 111620376,
    name = "他侧身一闪，手中的剑顺势一挥，那魔物惨叫着倒在地上。"
  },
  [111620377] = {
    id = 111620377,
    name = "这样下去不是办法，魔物越来越多，我们的防线快撑不住了！"
  },
  [111620378] = {
    id = 111620378,
    name = "......呼......去求援的人什么时候回来？"
  },
  [111620379] = {
    id = 111620379,
    name = "不知道！但咱们也不能让这些杂种破坏我们的家！"
  },
  [111620380] = {
    id = 111620380,
    name = "他搬起一块巨大的石块，登上防护墙，用尽全身力气朝着魔物群砸去。"
  },
  [111620381] = {
    id = 111620381,
    name = "“砰”的一声，石块碎裂，同时砸倒了一片魔物。"
  },
  [111620382] = {
    id = 111620382,
    name = "我也来帮忙！"
  },
  [111620383] = {
    id = 111620383,
    name = "小孩拿起一块弹弓，套上了一颗珠子，打入魔物群，炸出了一个大坑。"
  },
  [111620384] = {
    id = 111620384,
    name = "什么东西？"
  },
  [111620385] = {
    id = 111620385,
    name = "是铃姐姐给的魔法珠子！妈妈，我就说我可以保护你的！"
  },
  [111620386] = {
    id = 111620386,
    name = "瑟瑞看见这一幕，心中涌起一股暖流，他更加奋力地挥剑，剑影闪烁，魔物纷纷倒下。"
  },
  [111620387] = {
    id = 111620387,
    name = "可是，魔物仿佛无穷无尽，一波又一波地涌来。"
  },
  [111620388] = {
    id = 111620388,
    name = "一位邻居不小心被一只魔物扑倒，瑟瑞迅速转身，一剑刺中那只魔物，将受伤的邻居救起。"
  },
  [111620389] = {
    id = 111620389,
    name = "大家小心！"
  },
  [111620390] = {
    id = 111620390,
    name = "瑟瑞的心愈发沉重，尽管大家拼尽全力，但魔物的数量实在太多了。"
  },
  [111620391] = {
    id = 111620391,
    name = "糟了，后面还有，好多魔物！"
  },
  [111620392] = {
    id = 111620392,
    name = "怎么办，瑟瑞，我这里快守不住了！"
  },
  [111620393] = {
    id = 111620393,
    name = "那就撤！通知所有人，尽快撤离伽罗安！往圈落跑！"
  },
  [111620394] = {
    id = 111620394,
    name = "怎么会这样？"
  },
  [111620395] = {
    id = 111620395,
    name = "从来微笑的邻居此刻绝望地喊着，眼泪潸然而下。"
  },
  [111620396] = {
    id = 111620396,
    name = "先去通知家人！！否则，一个也走不了！"
  },
  [111620397] = {
    id = 111620397,
    name = "所有人极其不舍地撤退，有的邻居还边跑边回头射箭，试图阻止魔物的追击。"
  },
  [111620398] = {
    id = 111620398,
    name = "别管那么多了，活下去才有希望！"
  },
  [111620399] = {
    id = 111620399,
    name = "瑟瑞艰涩地开口，他没想到突如其来的祸事，怎么就降临到了自己头上。"
  },
  [111620400] = {
    id = 111620400,
    name = "小铃，西西，等我......"
  },
  [111620401] = {
    id = 111620401,
    name = "瑟瑞奋力断后，为大家争取逃跑的时间。"
  },
  [111620402] = {
    id = 111620402,
    name = "一只凶猛的魔物趁机扑向了他，他躲闪不及，被魔物尖锐的爪子划伤了后背，鲜血瞬间染红了衣衫。"
  },
  [111620403] = {id = 111620403, name = "瑟瑞！"},
  [111620404] = {
    id = 111620404,
    name = "邻居又搬了一块大石头，狠狠戳进魔物的眼睛。"
  },
  [111620405] = {id = 111620405, name = "快走！"},
  [111620406] = {
    id = 111620406,
    name = "瑟瑞举剑杀掉那只魔物，竟发现伤口处逐渐开始麻痹，想必那魔物的爪子上带了毒。"
  },
  [111620407] = {id = 111620407, name = "吼——"},
  [111620408] = {
    id = 111620408,
    name = "又一只魔物扑了上来，瑟瑞的手臂又添了一道深深的伤口。"
  },
  [111620409] = {
    id = 111620409,
    name = "他的动作渐渐变得迟缓，每一次挥剑都仿佛用尽了全身的力气，终于在邻居的合力协助下，杀掉了这一波最后的一只魔物。"
  },
  [111620410] = {
    id = 111620410,
    name = "下一波魔物很快就到了，我们没多少时间了，你们挑重要的东西，轻装上路，不要耽搁时间！"
  },
  [111620411] = {
    id = 111620411,
    name = "哎呀，你受伤了！"
  },
  [111620412] = {
    id = 111620412,
    name = "没关系，我回去找小铃，她会一些治愈魔法，这点伤没问题。"
  },
  [111620413] = {
    id = 111620413,
    name = "让小五他们几个都准备一下，下一波魔物很快来了，需要有人为孩子们争取时间。"
  },
  [111620414] = {
    id = 111620414,
    name = "好，我知道了，那你一定要注意安全啊！"
  },
  [111620415] = {
    id = 111620415,
    name = "瑟瑞强撑着身体点点头，和他们分开，走向自己住了许多年的小院。"
  },
  [111620416] = {
    id = 111620416,
    name = "与小铃相识相爱，许下未来的诺言，共同孕育自己的孩子，他最幸福的时光都在这个小院里。"
  },
  [111620417] = {
    id = 111620417,
    name = "他的脑海里不断出现小铃的面容，仿佛走马灯似的回放着。"
  },
  [111620418] = {
    id = 111620418,
    name = "毒好像有些严重啊......"
  },
  [111620419] = {
    id = 111620419,
    name = "他狠心剜下那块中毒的伤口，快速地撒上了止血药粉，又喝下一瓶精神药剂，直起了身子，快速走向属于他的一切。"
  },
  [111620420] = {
    id = 111620420,
    name = "他推开家门，强忍着身体的剧痛，努力站直着身体，声音急切。"
  },
  [111620421] = {
    id = 111620421,
    name = "小铃，带着西西离开，快！"
  },
  [111620422] = {
    id = 111620422,
    name = "铃正在收拾东西，看瑟瑞走进来浑身浴血的样子，不禁心口一疼。"
  },
  [111620423] = {
    id = 111620423,
    name = "你受伤了，我先给你治疗！"
  },
  [111620424] = {
    id = 111620424,
    name = "没时间，来不及了！"
  },
  [111620425] = {
    id = 111620425,
    name = "听我说，小铃，我们刚打退了一波魔物，但我看到更多的魔物还在后面。"
  },
  [111620426] = {
    id = 111620426,
    name = "支援的人还在路上，也许等不到他们，魔物就会闯进来。"
  },
  [111620427] = {
    id = 111620427,
    name = "我们不能继续待在这里了。"
  },
  [111620428] = {
    id = 111620428,
    name = "那我们的家......"
  },
  [111620429] = {
    id = 111620429,
    name = "只要有你在，就是我的家。"
  },
  [111620430] = {
    id = 111620430,
    name = "好，我们一起走！"
  },
  [111620431] = {
    id = 111620431,
    name = "铃在瑟瑞出门的时候，就预见了撤离的可能性，已经把重要的东西装进了行囊。"
  },
  [111620432] = {id = 111620432, name = "小铃。"},
  [111620433] = {
    id = 111620433,
    name = "铃把行囊给瑟瑞，自己去抱起了西西，却被瑟瑞拦下了，将行囊珍重地挂在她的身上。"
  },
  [111620434] = {
    id = 111620434,
    name = "瑟瑞......你什么意思？"
  },
  [111620435] = {
    id = 111620435,
    name = "小铃，你带西西先从后院走，我和小五他们几个约好了，把那些魔物引开——"
  },
  [111620436] = {
    id = 111620436,
    name = "不要！瑟瑞，我们要一起走！"
  },
  [111620437] = {
    id = 111620437,
    name = "......不，瑟瑞，就......不能一起走吗？"
  },
  [111620438] = {
    id = 111620438,
    name = "铃又痛苦又矛盾，他想让瑟瑞做一个小人，只要他们一家人在一起，这样的劫难是可以逃掉的。"
  },
  [111620439] = {
    id = 111620439,
    name = "但她太了解瑟瑞了，瑟瑞就是这样善良热血，纯粹又可爱的人。"
  },
  [111620440] = {
    id = 111620440,
    name = "瑟瑞绝不会让她们置身危险，也不会放弃去拯救那些无辜的人。"
  },
  [111620441] = {
    id = 111620441,
    name = "这就是她所爱的瑟瑞，她曾经为自己找到这样一个灵魂伴侣而骄傲，现在却同样为之痛苦。"
  },
  [111620442] = {
    id = 111620442,
    name = "......小铃，对不起。"
  },
  [111620443] = {
    id = 111620443,
    name = "毒素的麻痹感在逐步侵蚀身体的每个部位，瑟瑞不舍地看着朝夕相伴的爱人。"
  },
  [111620444] = {
    id = 111620444,
    name = "如果他就这样逃走，以他的伤势，不仅逃不掉，还会连累他的妻女。"
  },
  [111620445] = {
    id = 111620445,
    name = "所以他选择了道别。"
  },
  [111620446] = {
    id = 111620446,
    name = "说什么纯善道义，那些都是铃所爱的品性。"
  },
  [111620447] = {
    id = 111620447,
    name = "作为一个探险者，谁又没有为了宝物厮杀过，为了名利争斗过呢？"
  },
  [111620448] = {
    id = 111620448,
    name = "可是他愿意为了铃做一个善良的人。"
  },
  [111620449] = {
    id = 111620449,
    name = "从见到铃的那一天起，他就决定过另一种人生。"
  },
  [111620450] = {
    id = 111620450,
    name = "放弃以前的丛林规则，和铃一起帮助弱小，闲适地在据点里过安宁的生活。"
  },
  [111620451] = {
    id = 111620451,
    name = "他喜欢这样的宁静，和爱人一起，那是比获得宝藏还要幸福的快乐。"
  },
  [111620452] = {
    id = 111620452,
    name = "可天不遂人愿，这段时间太短了，短到他还来不及看见女儿长大。"
  },
  [111620453] = {
    id = 111620453,
    name = "为了孩子。"
  },
  [111620454] = {
    id = 111620454,
    name = "（也为了你。）"
  },
  [111620455] = {
    id = 111620455,
    name = "铃在他道歉的一瞬，眼泪簌簌地落了下来。"
  },
  [111620456] = {
    id = 111620456,
    name = "她似乎知道了什么，但却不敢说出那句话。"
  },
  [111620457] = {
    id = 111620457,
    name = "只要不说出那句话，就不是永别，瑟瑞就还有追上她，与她一起逃亡的机会。"
  },
  [111620458] = {
    id = 111620458,
    name = "快走吧。"
  },
  [111620459] = {
    id = 111620459,
    name = "他轻声催促着铃。"
  },
  [111620460] = {
    id = 111620460,
    name = "时间不多了，不只是据点外迅速靠近的魔物，还是他身体的毒伤。"
  },
  [111620461] = {
    id = 111620461,
    name = "瑟瑞，我爱你。"
  },
  [111620462] = {
    id = 111620462,
    name = "瑟瑞的心又暖又疼，朝铃挤出了一个笑容，挥挥手。"
  },
  [111620463] = {
    id = 111620463,
    name = "我也爱你。"
  },
  [111620464] = {
    id = 111620464,
    name = "瑟瑞微笑着回应。"
  },
  [111620465] = {
    id = 111620465,
    name = "他爱她如生命，这样的爱刻在了他的灵魂里。"
  },
  [111620466] = {
    id = 111620466,
    name = "他愿意为她付出一切。"
  },
  [111620467] = {
    id = 111620467,
    name = "铃忍住泪水转身朝后院走去，与此同时，瑟瑞也踏出了房门。"
  },
  [111620468] = {
    id = 111620468,
    name = "这个家，他想守护，也必须去守护。"
  },
  [111620469] = {
    id = 111620469,
    name = "瑟瑞，快来这边！！"
  },
  [111620470] = {
    id = 111620470,
    name = "远处的人急切呼喊，他的心砰砰直跳，有了更不好的预感，加快脚步朝据点入口疾奔而去。"
  },
  [111620471] = {
    id = 111620471,
    name = "他看到黑云无限靠近，飞行的魔物俯冲而下，刺穿了小孩子的身体。"
  },
  [111620472] = {
    id = 111620472,
    name = "他冲上去砍杀了魔物，将血流不止的小孩翻过身，忽然想起自己将所有的药物留给了铃。"
  },
  [111620473] = {
    id = 111620473,
    name = "小家伙，小家伙！！"
  },
  [111620474] = {
    id = 111620474,
    name = "妈妈......我没保护好她......我去找她了......"
  },
  [111620475] = {
    id = 111620475,
    name = "小孩子停止了呼吸。"
  },
  [111620476] = {
    id = 111620476,
    name = "啊啊啊——"
  },
  [111620477] = {
    id = 111620477,
    name = "瑟瑞踉跄地起身，看着零散地冲入据点的魔物，提剑奋力杀了过去！"
  },
  [111620478] = {
    id = 111620478,
    name = "与此同时，铃抱着西西，见到了地狱般的景象——"
  },
  [111620479] = {
    id = 111620479,
    name = "据点里的妇人与孩子，正在被魔物分食着。"
  },
  [111620480] = {
    id = 111620480,
    name = "它们早已包围了这里，等着美味一个个地送上门。"
  },
  [111620481] = {
    id = 111620481,
    name = "不......不对......"
  },
  [111620482] = {
    id = 111620482,
    name = "铃震惊地看着这一切，在魔物没有被发现时，退到隐蔽的地方。"
  },
  [111620483] = {
    id = 111620483,
    name = "瑟瑞......"
  },
  [111620484] = {
    id = 111620484,
    name = "她恍然惊醒，整个人脸色惨白，转身走回了家的方向。"
  },
  [111620485] = {
    id = 111620485,
    name = "瑟瑞，不要丢下我。"
  },
  [111620486] = {
    id = 111620486,
    name = "铃重新回到了家中。"
  },
  [111620487] = {id = 111620487, name = "西西。"},
  [111620488] = {
    id = 111620488,
    name = "她轻声呼唤着女儿的乳名，怀中的女儿睡得香甜，并不知道眼下的一切。"
  },
  [111620489] = {
    id = 111620489,
    name = "对不起......"
  },
  [111620490] = {
    id = 111620490,
    name = "妈妈要去找爸爸了，我们不能丢下他。"
  },
  [111620491] = {
    id = 111620491,
    name = "外面的那些魔物......只靠我们，逃不出去的。"
  },
  [111620492] = {
    id = 111620492,
    name = "所以，我要和你的爸爸一起战斗，一起打跑它们。"
  },
  [111620493] = {
    id = 111620493,
    name = "我们是一家人，我们三个，一个也不能少，对不对？"
  },
  [111620494] = {
    id = 111620494,
    name = "铃将所有的保命卷轴都放在了西西身上，咬破了指尖血，在她的衣服上画了一个魔法阵。"
  },
  [111620495] = {
    id = 111620495,
    name = "你在这里乖乖等妈妈，千万，千万不要出声哦。"
  },
  [111620496] = {
    id = 111620496,
    name = "铃叠了许多被褥放进了衣柜，把西西轻轻地放了进去。"
  },
  [111620497] = {
    id = 111620497,
    name = "她在衣柜外又画了一道魔法阵，无声地掩上了柜门。"
  },
  [111620498] = {
    id = 111620498,
    name = "西西......"
  },
  [111620499] = {
    id = 111620499,
    name = "衣柜留着缝隙，她透过光，恰好看到女儿可爱的睡颜。"
  },
  [111620500] = {
    id = 111620500,
    name = "妈妈先走了。"
  },
  [111620501] = {
    id = 111620501,
    name = "如果......如果妈妈和爸爸没有等到支援的话......"
  },
  [111620502] = {
    id = 111620502,
    name = "你以后一个人......也要好好的......"
  },
  [111620503] = {
    id = 111620503,
    name = "没有爸爸妈妈的守护，你也一定会成为一个厉害的探险者。"
  },
  [111620504] = {
    id = 111620504,
    name = "等你长大，等你长大......"
  },
  [111620505] = {
    id = 111620505,
    name = "想去哪儿就去哪儿，可以走得更远。"
  },
  [111620506] = {
    id = 111620506,
    name = "去我们不曾去过的，或者去不了的地方......"
  },
  [111620507] = {
    id = 111620507,
    name = "你要活得自由自在，成为你想成为的样子。"
  },
  [111620508] = {
    id = 111620508,
    name = "我亲爱的女儿，妈妈爱你。"
  },
  [111620509] = {
    id = 111620509,
    name = "铃泪流满面，决绝地转身。"
  },
  [111620510] = {
    id = 111620510,
    name = "她毅然走出小屋，奔向那片无归的战场。"
  },
  [111620511] = {
    id = 111620511,
    name = "瑟瑞，我来了。"
  },
  [111620512] = {
    id = 111620512,
    name = "铃一路狂奔，她抽出了许久不用的法杖，一路击杀着冲向她的魔物。"
  },
  [111620513] = {
    id = 111620513,
    name = "那些魔物不断攻入据点，而铃的心越发沉重，却又抱着一丝期待。"
  },
  [111620514] = {
    id = 111620514,
    name = "她看到了许多熟人的尸体，惶恐地寻找着瑟瑞的身影。"
  },
  [111620515] = {
    id = 111620515,
    name = "她害怕在下一刻，就会见到想见却不敢面对的人。"
  },
  [111620516] = {id = 111620516, name = "小铃？"},
  [111620517] = {
    id = 111620517,
    name = "视线中出现铃身影的时候，瑟瑞以为自己看到了幻觉。"
  },
  [111620518] = {
    id = 111620518,
    name = "那是将死之人在弥留之际最想见到的梦。"
  },
  [111620519] = {
    id = 111620519,
    name = "毒液已然侵蚀他的每一滴血液，他的身上已感知不到疼痛。"
  },
  [111620520] = {
    id = 111620520,
    name = "只在麻木地挥动着剑，不让魔物冲入据点，冲进他的家。"
  },
  [111620521] = {
    id = 111620521,
    name = "他望着铃惊惶地向他奔来，心中一片迷茫。"
  },
  [111620522] = {
    id = 111620522,
    name = "为什么铃的样子这么害怕？就像失去了一切那样绝望。"
  },
  [111620523] = {
    id = 111620523,
    name = "嗤......魔物的尖刺不知第几次穿过了他的身体。"
  },
  [111620524] = {
    id = 111620524,
    name = "他的剑脱手，向后栽倒而去。"
  },
  [111620525] = {
    id = 111620525,
    name = "铃杀掉魔物赶到了他的身边，意图支撑着他，两人却一起倒了下去。"
  },
  [111620526] = {
    id = 111620526,
    name = "瑟瑞，瑟瑞，亲爱的，你撑住！"
  },
  [111620527] = {
    id = 111620527,
    name = "她一手抱着瑟瑞，一手施展着治愈魔法。"
  },
  [111620528] = {
    id = 111620528,
    name = "瑟瑞双眼半合，嘴中不断渗出鲜血，这时眼睛突然瞪大了。"
  },
  [111620529] = {
    id = 111620529,
    name = "小铃，真的......是你......"
  },
  [111620530] = {
    id = 111620530,
    name = "别说话，我会治好你......"
  },
  [111620531] = {
    id = 111620531,
    name = "铃抱着的身躯越来越冷，她的手指颤抖，到最后连魔法也耗尽了。"
  },
  [111620532] = {
    id = 111620532,
    name = "你......何苦回来......"
  },
  [111620533] = {
    id = 111620533,
    name = "因为你在这里，我的家在这里......"
  },
  [111620534] = {
    id = 111620534,
    name = "我要救你，救你回去，带着西西，一起回大陆......"
  },
  [111620535] = {
    id = 111620535,
    name = "铃双目通红，一遍又一遍地透支着残余的魔法力。"
  },
  [111620536] = {
    id = 111620536,
    name = "我们还有很长很长的岁月，不要放弃，不要离开！"
  },
  [111620537] = {
    id = 111620537,
    name = "求求你，瑟瑞......"
  },
  [111620538] = {
    id = 111620538,
    name = "她不停喊着瑟瑞的名字，理智告诉她，瑟瑞的伤势已经无力回天。"
  },
  [111620539] = {
    id = 111620539,
    name = "但她无法接受这个事实。"
  },
  [111620540] = {
    id = 111620540,
    name = "小铃......"
  },
  [111620541] = {
    id = 111620541,
    name = "瑟瑞的身体越来越冷，他凝望着铃，脸上露出一抹眷恋的笑。他费力地张开嘴唇，轻声说。"
  },
  [111620542] = {id = 111620542, name = "......"},
  [111620543] = {
    id = 111620543,
    name = "瑟瑞，你说什么？"
  },
  [111620544] = {
    id = 111620544,
    name = "铃将耳朵贴在他的唇边，却听不到他的声音。"
  },
  [111620545] = {
    id = 111620545,
    name = "甚至，连呼吸也一同消失了。"
  },
  [111620546] = {
    id = 111620546,
    name = "铃恐惧地抱着瑟瑞，流下了心痛绝望的泪。"
  },
  [111620547] = {
    id = 111620547,
    name = "啊啊啊......"
  },
  [111620548] = {
    id = 111620548,
    name = "瑟瑞微笑着，仿佛死在她的怀里是一件幸福的事。"
  },
  [111620549] = {
    id = 111620549,
    name = "周围的一切声音在她耳边变得死寂。"
  },
  [111620550] = {
    id = 111620550,
    name = "铃僵直地跪在原地，瞳孔仿佛失去了焦距，完全没有察觉到魔物的靠近。"
  },
  [111620551] = {
    id = 111620551,
    name = "五六只魔物如同狩猎般逐渐将两人包围，这时铃豁然抬头。"
  },
  [111620552] = {
    id = 111620552,
    name = "血阵，破。"
  },
  [111620553] = {
    id = 111620553,
    name = "她的身体周围忽然亮起，犹如一颗闪耀的星，爆发出皓月般的光芒。"
  },
  [111620554] = {id = 111620554, name = "轰——"},
  [111620555] = {
    id = 111620555,
    name = "魔物被一击秒杀，代价却是她剩余的生命力。"
  },
  [111620556] = {
    id = 111620556,
    name = "生死相守，不离不弃。"
  },
  [111620557] = {
    id = 111620557,
    name = "瑟瑞，这是你与我的约定。"
  },
  [111620558] = {
    id = 111620558,
    name = "所以，不要食言啊......"
  },
  [111620559] = {
    id = 111620559,
    name = "铃艰难地站起来，转向家的方向，正有魔物跑向那里。"
  },
  [111620560] = {
    id = 111620560,
    name = "不许去......"
  },
  [111620561] = {
    id = 111620561,
    name = "她艰难地抬起法杖，却一点魔法也使不出来了。"
  },
  [111620562] = {
    id = 111620562,
    name = "不要，不要去那里......"
  },
  [111620563] = {
    id = 111620563,
    name = "铃全身脱力，倒在瑟瑞身边。"
  },
  [111620564] = {
    id = 111620564,
    name = "这时，一道宛如劈开天地的剑光横扫了过去。"
  },
  [111620565] = {
    id = 111620565,
    name = "那些魔物瞬间停滞，在下一秒消散了，尸骨无存。"
  },
  [111620566] = {
    id = 111620566,
    name = "铃的视线模糊，只隐约看到一个青年男子闲庭信步在烟尘中走了出来，横扫一切罪恶。"
  },
  [111620567] = {id = 111620567, name = "救......"},
  [111620568] = {
    id = 111620568,
    name = "铃用尽全力指着那个家，希望来人能看到那里还有一个幸存者。"
  },
  [111620569] = {
    id = 111620569,
    name = "那是她的女儿，她与瑟瑞存在过的证明。"
  },
  [111620570] = {
    id = 111620570,
    name = "可她什么也做不了，甚至连抬抬手指的力气都失去。"
  },
  [111620571] = {
    id = 111620571,
    name = "她献祭一切力量发动的魔法，生命已经到了尽头。"
  },
  [111620572] = {
    id = 111620572,
    name = "最后的时刻，她的意识陷入了黑暗。"
  },
  [111620573] = {
    id = 111620573,
    name = "那些美好的记忆如同破碎的琉璃，化作无数晶莹的星星，点点消散了。"
  },
  [111620574] = {
    id = 111620574,
    name = "哇哇哇哇......"
  },
  [111620575] = {
    id = 111620575,
    name = "仿佛知道了母亲的祝福与永别，一直乖巧安静的西西发出了响亮的啼哭声。"
  },
  [111620576] = {id = 111620576, name = "嗯？"},
  [111620577] = {
    id = 111620577,
    name = "有一个生还者，是婴儿？"
  },
  [111620578] = {
    id = 111620578,
    name = "陆玄只手清理了围在房间外的魔物，走向了那间布满防御结界的衣柜。"
  },
  [111620579] = {
    id = 111620579,
    name = "他轻手一拂，打开魔法阵，那可爱的女婴便瞬间停止了哭泣，好奇地看着他。"
  },
  [111620580] = {
    id = 111620580,
    name = "陆玄轻声叹息，抱着女婴离开了伽罗安。"
  },
  [111620581] = {
    id = 111620581,
    name = "她的生命，才刚刚开始。"
  },
  [111950001] = {
    id = 111950001,
    name = "在你们救下绿野村的两名村民后，竟然在村中发现了重新活过来的村民。"
  },
  [111950002] = {
    id = 111950002,
    name = "永远在头顶的烈日，跪在祭坛上的女祭司，不死的村民......"
  },
  [111950003] = {
    id = 111950003,
    name = "面对这些诡异的谜团，你们对村庄进行了调查，希望能尽快找到回大陆的捷径。"
  },
  [111950004] = {
    id = 111950004,
    name = "队长，快来看！我发现了什么？！"
  },
  [111950005] = {
    id = 111950005,
    name = "尼莉莎在大块岩石区域缝隙间发现了一扇石门，上面布满了层层魔法符文。"
  },
  [111950006] = {
    id = 111950006,
    name = "哇，这里面会不会有宝藏啊！"
  },
  [111950007] = {
    id = 111950007,
    name = "这里不是深渊，这里面应该都是绿野村的东西，别胡思乱想了。"
  },
  [111950008] = {
    id = 111950008,
    name = "问问也不可以呀？也许里面有能让我们回大陆的东西呢？"
  },
  [111950009] = {
    id = 111950009,
    name = "老师，那边来人了。"
  },
  [111950010] = {
    id = 111950010,
    name = "来人正是之前在枯木林里救下的村民之一，看你们围在石门前，走了过来。"
  },
  [111950011] = {
    id = 111950011,
    name = "你们到这里来做什么？"
  },
  [111950012] = {
    id = 111950012,
    name = "请问一下，这个石门后面是什么，可以告诉我们吗？"
  },
  [111950013] = {
    id = 111950013,
    name = "我们也不知道。"
  },
  [111950014] = {
    id = 111950014,
    name = "不知道？"
  },
  [111950015] = {
    id = 111950015,
    name = "那有其他人知道吗？"
  },
  [111950016] = {
    id = 111950016,
    name = "没有。这里是村民们原来的仓库，后来先驱者把它封印之后，就没有人能打开了。"
  },
  [111950017] = {
    id = 111950017,
    name = "好端端的，为什么会让人把仓库封印起来？"
  },
  [111950018] = {
    id = 111950018,
    name = "你们能打开这扇门？"
  },
  [111950019] = {
    id = 111950019,
    name = "如果你们允许的话，我们想试试。"
  },
  [111950020] = {
    id = 111950020,
    name = "可以，要是能打开最好，大家都说这里面有宝藏能带我们离开苦难。"
  },
  [111950021] = {
    id = 111950021,
    name = "你这个人警惕心好低哦，万一我们是强盗，而里面都是财宝怎么办？"
  },
  [111950022] = {
    id = 111950022,
    name = "没关系，反正你们都走不出遗迹，逃不掉的。"
  },
  [111950023] = {id = 111950023, name = "......"},
  [111950024] = {
    id = 111950024,
    name = "得到原住民的首肯，你们开始研究石门上面的魔法符文。"
  },
  [111950025] = {
    id = 111950025,
    name = "安妮斯，有看出什么吗？"
  },
  [111950026] = {
    id = 111950026,
    name = "上面有四层魔法符文，它们环环相扣，如果一个个破坏，会将这道封印彻底锁死。"
  },
  [111950027] = {
    id = 111950027,
    name = "如果用点儿力气，把符文一起毁掉呢？"
  },
  [111950028] = {
    id = 111950028,
    name = "最外层的防御符文和最底层的封印符文相连，很难做到一起破坏。"
  },
  [111950029] = {
    id = 111950029,
    name = "也就是说，只能一次性同时解开这些魔法符文，才可以打开这扇门了。"
  },
  [111950030] = {
    id = 111950030,
    name = "好复杂哦。"
  },
  [111950031] = {
    id = 111950031,
    name = "要不要去把大小姐叫过来，也许她知道。"
  },
  [111950032] = {
    id = 111950032,
    name = "列蒂西雅的办法就是暴力炸开吧......嗯，这种连环魔法符文的方式，我见过，也许可以解决。"
  },
  [111950033] = {
    id = 111950033,
    name = "你有办法？"
  },
  [111950034] = {
    id = 111950034,
    name = "这四层符文是相互依存的关系，只需要找到它们之间的这个关系点，再用魔法共振和捆绑，就能将它们同时摧毁。"
  },
  [111950035] = {
    id = 111950035,
    name = "不愧是老师！"
  },
  [111950036] = {
    id = 111950036,
    name = "定下方案后，你着手寻找就近的材料，很快做出了一个简易的工具，放在门前。"
  },
  [111950037] = {
    id = 111950037,
    name = "四道魔法波动如浪涌而散，众人感受到门前封印的消散。"
  },
  [111950038] = {
    id = 111950038,
    name = "队长，你还有这一手啊？！那以后咱们寻宝不就......嘿嘿嘿......"
  },
  [111950039] = {
    id = 111950039,
    name = "老师好厉害，这样的方法都能想到！"
  },
  [111950040] = {
    id = 111950040,
    name = "呃，其实这个办法不是我想出来的，这是以前和艾瑟儿探险的时候，她用过的办法。"
  },
  [111950041] = {
    id = 111950041,
    name = "哦？听名字是一位小姐。"
  },
  [111950042] = {
    id = 111950042,
    name = "......是老师原来的同伴吗？"
  },
  [111950043] = {
    id = 111950043,
    name = "是偶然结伴同游的探险者，她的行事方式很特别，令人印象深刻。"
  },
  [111950044] = {
    id = 111950044,
    name = "说话之间，蒂娜和尼莉莎已经打开了面前的石门。"
  },
  [111950045] = {
    id = 111950045,
    name = "宝藏我来了——欸？？怎么是空的？！咳咳咳......呛死我了。"
  },
  [111950046] = {
    id = 111950046,
    name = "石屋里除了地面上一层厚厚的灰，什么都没有。"
  },
  [111950047] = {
    id = 111950047,
    name = "竟然是空的......也没有任何宝物留存的痕迹。"
  },
  [111950048] = {
    id = 111950048,
    name = "明明是空的，为什么还要用重重魔法锁起来？"
  },
  [111950049] = {
    id = 111950049,
    name = "遗迹村民愣愣地看着眼前的一切，悲凉地笑了笑。"
  },
  [111950050] = {
    id = 111950050,
    name = "把门关上吧，不要让其他人知道这件事。"
  },
  [111950051] = {id = 111950051, name = "好。"},
  [111950052] = {
    id = 111950052,
    name = "遗迹村民走了，蒂娜看你重新做好了门前的封印，奇怪地问你为什么要这么做。"
  },
  [111950053] = {
    id = 111950053,
    name = "也许对他们来说，打不开的才是希望。"
  },
  [111950054] = {
    id = 111950054,
    name = "原来如此。"
  },
  [111950055] = {
    id = 111950055,
    name = "哎呀，不说这个让人不开心的事啦！队长，你说的那个艾瑟儿，还有什么其他的本领啊？"
  },
  [111950056] = {
    id = 111950056,
    name = "你对她很感兴趣？"
  },
  [111950057] = {
    id = 111950057,
    name = "要是哪天遇到了，我也好向她请教一下其他开锁......啊不是，探险的技能！"
  },
  [111950058] = {
    id = 111950058,
    name = "呵呵，她的确是一个很特别的独行探险者。"
  },
  [111950059] = {
    id = 111950059,
    name = "回村庄的路上，你讲述了你与艾瑟儿如何相识、历险的故事......"
  },
  [111950060] = {
    id = 111950060,
    name = "在还没毕业的时候，我打算成立自己的探险队。"
  },
  [111950061] = {
    id = 111950061,
    name = "那时，我一个人去深渊探险，走累了，恰好到了一个据点。"
  },
  [111950062] = {
    id = 111950062,
    name = "尼莉莎和安妮斯津津有味地听着，你慢慢陷入到了回忆中......"
  },
  [111950063] = {id = 111950063, name = "......"},
  [111950064] = {
    id = 111950064,
    name = "说是据点，但那里更像一个村庄。"
  },
  [111950065] = {
    id = 111950065,
    name = "你到达的时候，已经是傍晚。街上没有来来往往的探险者，只有紧闭大门的房屋。"
  },
  [111950066] = {
    id = 111950066,
    name = "嗯？屋里都有光亮......怎么街道上没有人？"
  },
  [111950067] = {
    id = 111950067,
    name = "大家睡得这么早吗？"
  },
  [111950068] = {
    id = 111950068,
    name = "你走向街道广场最大的房间——据点管事处，敲了敲门。"
  },
  [111950069] = {
    id = 111950069,
    name = "吱呀......门开了，露出了一张双目无神的脸，你怔了怔，看他的装束，也是个探险者。"
  },
  [111950070] = {
    id = 111950070,
    name = "你好，请问这里还有可以住的房间吗？"
  },
  [111950071] = {id = 111950071, name = "......"},
  [111950072] = {
    id = 111950072,
    name = "探险者僵硬地侧过身，让出了一个身位，你走了进去，看见了周围的居民，以及坐在管事处埋着头的接待员。"
  },
  [111950073] = {
    id = 111950073,
    name = "请问——"
  },
  [111950074] = {
    id = 111950074,
    name = "话没问出口，接待员猛地抬起头，吓了你一跳。"
  },
  [111950075] = {id = 111950075, name = "......"},
  [111950076] = {
    id = 111950076,
    name = "他的视线望着天花板，慢慢又下移向了你，你看着那双浑浊无神的眼睛，脊背涌起一阵寒意。"
  },
  [111950077] = {
    id = 111950077,
    name = "那个，请问有多余的房间吗？"
  },
  [111950078] = {
    id = 111950078,
    name = "有、啊。上、楼，第、二、间。"
  },
  [111950079] = {
    id = 111950079,
    name = "接待员回答后，缓慢地从桌子下方拿出了一把钥匙，临空松手。"
  },
  [111950080] = {
    id = 111950080,
    name = "——啪嗒！钥匙落在桌上的声音回响在屋里，你忽然反应过来，进门之后，那些围坐在一起的居民没有说过一句话。"
  },
  [111950081] = {id = 111950081, name = "......"},
  [111950082] = {
    id = 111950082,
    name = "你抓起钥匙，回首时，十余双眼睛直愣愣地看向你。"
  },
  [111950083] = {
    id = 111950083,
    name = "嗯......大家好啊。"
  },
  [111950084] = {
    id = 111950084,
    name = "围坐在桌边的居民仿佛接收了某个指令一般，齐刷刷又转回了头，不再看你了。"
  },
  [111950085] = {
    id = 111950085,
    name = "（这里的人好奇怪......）"
  },
  [111950086] = {
    id = 111950086,
    name = "你心中抱着疑问，往上楼的方向走去。"
  },
  [111950087] = {
    id = 111950087,
    name = "路过那群人旁边，瞧见给你开门的探险者正喝着黑绿色已经发霉的水，你心中霎然一惊。"
  },
  [111950088] = {
    id = 111950088,
    name = "这位，你的水......"
  },
  [111950089] = {
    id = 111950089,
    name = "什、么？"
  },
  [111950090] = {
    id = 111950090,
    name = "那探险者的头机械般地转向你，双眼空洞无神，如深不见底的黑洞，反应了一会儿才回复你。"
  },
  [111950091] = {
    id = 111950091,
    name = "没什么，没什么......"
  },
  [111950092] = {
    id = 111950092,
    name = "你扫了一眼四周的人，硬着头皮上楼去了。"
  },
  [111950093] = {
    id = 111950093,
    name = "（天黑之后，外面更危险......先在这里住一晚，明天一早就走吧。）"
  },
  [111950094] = {
    id = 111950094,
    name = "你做好了打算，在房间周围布置了简单的魔法防护阵。"
  },
  [111950095] = {
    id = 111950095,
    name = "这些魔法阵不能阻挡堕落者或魔物的入侵，但至少能提醒你即将到来的危机。"
  },
  [111950096] = {id = 111950096, name = "......"},
  [111950097] = {
    id = 111950097,
    name = "半夜，你沉浸在不安的睡梦中。"
  },
  [111950098] = {
    id = 111950098,
    name = "突然，你感到一阵细微的刺痛，仿佛有丝线悄然从指尖穿进了自己的血液里。"
  },
  [111950099] = {id = 111950099, name = "！！！"},
  [111950100] = {
    id = 111950100,
    name = "你猛然惊醒，无色透明的丝线正从床下延伸，不断进入你的指尖。"
  },
  [111950101] = {
    id = 111950101,
    name = "你试图扯出那些神秘的丝线，却发现它们仿佛与自己的血肉紧紧相连，根本无法拔除。"
  },
  [111950102] = {
    id = 111950102,
    name = "（怎么回事？防御魔法阵竟然没有反应！）"
  },
  [111950103] = {
    id = 111950103,
    name = "就在这时，房门突然被一股巨大的力量撞击，轰！！"
  },
  [111950104] = {
    id = 111950104,
    name = "轰、轰、轰！撞击声不断传来，门开始摇晃，仿佛随时都会被撞开。"
  },
  [111950105] = {
    id = 111950105,
    name = "你当机立断，决定离开这里。"
  },
  [111950106] = {
    id = 111950106,
    name = "然而，当他打开窗户的那一刻，阳台上那些死气沉沉的居民不知何时已经围拢过来，缓缓朝你逼近。"
  },
  [111950107] = {id = 111950107, name = "......"},
  [111950108] = {
    id = 111950108,
    name = "你的指尖刺痛，丝线一刻不停地将你扯回床边，想抬手却发现手臂已经不受控制......"
  },
  [111950109] = {
    id = 111950109,
    name = "就在这时，天花板突然传来一声巨响，一个被打晕的居民掉了下来，砸在了窗户前，阻拦了那群妄图爬进房间的居民。"
  },
  [111950110] = {
    id = 111950110,
    name = "紧接着，你感到自己被绳索捆绑住，身体迅速被拉了上去！"
  },
  [111950111] = {id = 111950111, name = "啊——"},
  [111950112] = {
    id = 111950112,
    name = "在疼痛的恍惚间，你见到一个女孩，她的面容冷峻，神色清明。"
  },
  [111950113] = {
    id = 111950113,
    name = "她将你拖上房顶的那一瞬，二话不说，抽出一把附带着魔法的刀，迅速斩断了那些丝线！"
  },
  [111950114] = {
    id = 111950114,
    name = "被控制的感觉骤然消失了。"
  },
  [111950115] = {
    id = 111950115,
    name = "你的指尖还有一些麻木，缓缓站起了身。黑夜中，她的相貌看不真切，但你却能感到那股温暖的善意。"
  },
  [111950116] = {
    id = 111950116,
    name = "谢谢......"
  },
  [111950117] = {
    id = 111950117,
    name = "难得还能见到不被那些丝线直接控制的人，顺手救一救而已。"
  },
  [111950118] = {
    id = 111950118,
    name = "她冷淡地扬了扬眉，看你没什么大碍，扔下了一句话。"
  },
  [111950119] = {
    id = 111950119,
    name = "跟我来。"
  },
  [111950120] = {
    id = 111950120,
    name = "那些麻木的居民仍在往你的房间里推挤。"
  },
  [111950121] = {
    id = 111950121,
    name = "但因为魔法阵的原因，他们仿佛触碰着一层看不见的墙壁，无论如何都进不去。"
  },
  [111950122] = {
    id = 111950122,
    name = "有点本事，但是不多。"
  },
  [111950123] = {
    id = 111950123,
    name = "见着这一幕，女孩丢了一句评价，从房顶跳到了隐蔽处。"
  },
  [111950124] = {
    id = 111950124,
    name = "这位小姐，这个据点到底怎么回事？"
  },
  [111950125] = {
    id = 111950125,
    name = "艾瑟儿，我的名字。"
  },
  [111950126] = {
    id = 111950126,
    name = "嗯，艾瑟儿小姐。"
  },
  [111950127] = {
    id = 111950127,
    name = "不用这么麻烦，叫我名字就行。"
  },
  [111950128] = {
    id = 111950128,
    name = "街道上到处是游走的居民，他们的脸色苍白如纸，身体僵硬地移动着。"
  },
  [111950129] = {
    id = 111950129,
    name = "有衣衫褴褛的居民，也有穿着破旧的探险者，仿佛时间在这里停滞了很久。"
  },
  [111950130] = {
    id = 111950130,
    name = "这些人怎么——"
  },
  [111950131] = {
    id = 111950131,
    name = "你话还没说完，艾瑟儿便按住了你的嘴。"
  },
  [111950132] = {
    id = 111950132,
    name = "你感受到唇上的温软，不自觉地点点头。"
  },
  [111950133] = {
    id = 111950133,
    name = "可已经迟了，那些居民似乎触发了某个机关，突然停下了脚步，缓缓地转过头来。"
  },
  [111950134] = {
    id = 111950134,
    name = "该死，快走！"
  },
  [111950135] = {
    id = 111950135,
    name = "居民们发出低沉奇怪的声音，如同野兽一般，然后疯狂地冲向你们。"
  },
  [111950136] = {
    id = 111950136,
    name = "你只觉得一只柔软却有力的手紧紧握住了自己，艾瑟儿拉着你迅速转身，朝着一条狭窄的巷子跑去。"
  },
  [111950137] = {
    id = 111950137,
    name = "艾瑟儿小姐——"
  },
  [111950138] = {id = 111950138, name = "闭嘴！"},
  [111950139] = {
    id = 111950139,
    name = "你被艾瑟儿拉着，两边的景色不断后退，艾瑟儿似乎用了速度加持的魔法，你竟觉得自己仿佛在风中飞驰，不可思议地盯着她的背影。"
  },
  [111950140] = {
    id = 111950140,
    name = "你们在黑夜的巷子里穿梭，前方只有她隐约的身影和模糊的光，就像这样可以跑到黑夜的尽头。"
  },
  [111950141] = {
    id = 111950141,
    name = "远远地甩掉了那些追赶的居民，艾瑟儿在巷子里左拐右拐，找到了一间门口挂着布娃娃的房间，拉着你钻了进去。"
  },
  [111950142] = {
    id = 111950142,
    name = "这里他们不会进来。"
  },
  [111950143] = {
    id = 111950143,
    name = "多谢你，艾瑟儿。"
  },
  [111950144] = {
    id = 111950144,
    name = "先在这里待着吧，等天亮了你就走。"
  },
  [111950145] = {
    id = 111950145,
    name = "她一边说着话，一边点燃了屋里的灯。"
  },
  [111950146] = {
    id = 111950146,
    name = "灯光明亮，显现出了一间装满玩具人偶的房子。"
  },
  [111950147] = {
    id = 111950147,
    name = "好多玩偶！"
  },
  [111950148] = {
    id = 111950148,
    name = "玩具人偶被摆放在柜架上，它们中有布偶和木偶，都是女娃娃的外表，穿着色彩斑斓的裙子，形态各异，栩栩如生，仿佛随时都能活过来。"
  },
  [111950149] = {
    id = 111950149,
    name = "嗯，别去碰它们。"
  },
  [111950150] = {
    id = 111950150,
    name = "不用她提醒，你也知道这间房屋并不一般。"
  },
  [111950151] = {
    id = 111950151,
    name = "刚才那些村民怎么回事？他们就像失去了神智，身上却没有堕落者的气息。"
  },
  [111950152] = {
    id = 111950152,
    name = "不知道，但很多像你一样路过的人，都变成了那样。"
  },
  [111950153] = {
    id = 111950153,
    name = "我是运气不错，一来就到了这间屋子，然后发现了这个据点的怪异之处。"
  },
  [111950154] = {
    id = 111950154,
    name = "除了这里，无论在哪儿，都会被奇怪的丝线控制，然后成为木偶一样的人。"
  },
  [111950155] = {
    id = 111950155,
    name = "这也太诡异了，你知道是什么原因吗？"
  },
  [111950156] = {
    id = 111950156,
    name = "我不知道，也许是有诅咒，也许有人为的操控。"
  },
  [111950157] = {
    id = 111950157,
    name = "总之这里很不安全，等天亮的时候，他们就会回到各自房间，人也会更正常一些。"
  },
  [111950158] = {
    id = 111950158,
    name = "那时候你就赶紧离开吧。"
  },
  [111950159] = {
    id = 111950159,
    name = "嗯好。那你呢？"
  },
  [111950160] = {
    id = 111950160,
    name = "我有留在这里的理由。"
  },
  [111950161] = {
    id = 111950161,
    name = "她没有看你，走到角落打开了地上的箱子，里面有很多奇怪的工具。"
  },
  [111950162] = {
    id = 111950162,
    name = "（既然不愿意告诉我，那就不问了吧。）"
  },
  [111950163] = {
    id = 111950163,
    name = "那些是什么？"
  },
  [111950164] = {
    id = 111950164,
    name = "魔法工具。你的影子挡着我的光了。"
  },
  [111950165] = {
    id = 111950165,
    name = "啊，抱歉。"
  },
  [111950166] = {
    id = 111950166,
    name = "你挪开了些，看见她挑选了一块晶莹剔透的水晶，用一把小锤轻轻敲打，将水晶敲成合适的形状。"
  },
  [111950167] = {
    id = 111950167,
    name = "接着，她拿起一根细长的银丝，将水晶缠绕起来。"
  },
  [111950168] = {
    id = 111950168,
    name = "她的手法娴熟而利落，每一个动作都充满了节奏感，很快一个挂件就完成了。"
  },
  [111950169] = {
    id = 111950169,
    name = "你在做什么？"
  },
  [111950170] = {
    id = 111950170,
    name = "让武器也能附魔的临时挂件。"
  },
  [111950171] = {
    id = 111950171,
    name = "她将挂件随手挂在你的武器上，顿时散发出了光芒。"
  },
  [111950172] = {
    id = 111950172,
    name = "与此同时，那些玩偶突然发生了异变。"
  },
  [111950173] = {
    id = 111950173,
    name = "糟了，这些玩偶果然不简单。"
  },
  [111950174] = {
    id = 111950174,
    name = "首先是离你们最近的布娃娃，它的眼睛突然闪烁起红色的光芒。接着，其他的玩偶也纷纷出现了异常。"
  },
  [111950175] = {
    id = 111950175,
    name = "有的木偶开始扭动身体，发出 “嘎吱嘎吱” 的声音；有的布娃娃则露出诡异的笑容，让人毛骨悚然。"
  },
  [111950176] = {
    id = 111950176,
    name = "小心！！"
  },
  [111950177] = {
    id = 111950177,
    name = "话音刚落，那些玩偶便朝着你们扑了过来。"
  },
  [111950178] = {
    id = 111950178,
    name = "娃娃们挥舞着小小的手臂，一蹦一跳，你斩断了扑上前的娃娃，露出里面腐朽的丝线。"
  },
  [111950179] = {
    id = 111950179,
    name = "它们没有生命，却被什么掌控着。"
  },
  [111950180] = {id = 111950180, name = "唔！"},
  [111950181] = {
    id = 111950181,
    name = "艾瑟儿猝不及防被一群娃娃抱住了腿脚，扑上了脸颊，你将她从娃娃堆中扯出来，竟然看到她身上已缠绕了许多丝线。"
  },
  [111950182] = {
    id = 111950182,
    name = "艾瑟儿！"
  },
  [111950183] = {
    id = 111950183,
    name = "她的双目失去色彩，你立刻挥动武器斩断了那些丝线，那一瞬她的眼神重回清明。"
  },
  [111950184] = {
    id = 111950184,
    name = "这些娃娃也能往人身体里种丝线，我们先离开这里！"
  },
  [111950185] = {id = 111950185, name = "好！"},
  [111950186] = {
    id = 111950186,
    name = "你们在玩偶们扑上来之前，迅速离开了房间，并关闭了房门。"
  },
  [111950187] = {
    id = 111950187,
    name = "而后，里面的声音消失了。"
  },
  [111950188] = {
    id = 111950188,
    name = "消停了。"
  },
  [111950189] = {
    id = 111950189,
    name = "艾瑟儿朝你手里的武器挂件瞥了一眼。"
  },
  [111950190] = {
    id = 111950190,
    name = "看来那些玩偶只要没被魔法影响，就不会出现异变。"
  },
  [111950191] = {
    id = 111950191,
    name = "现在这个房间也不安全了，接下来你打算怎么办？"
  },
  [111950192] = {id = 111950192, name = "......"},
  [111950193] = {
    id = 111950193,
    name = "我打算离开这里之后，去公会告诉他们这里的事。"
  },
  [111950194] = {
    id = 111950194,
    name = "艾瑟儿，你跟我一起走吧。"
  },
  [111950195] = {
    id = 111950195,
    name = "公会？不了。"
  },
  [111950196] = {
    id = 111950196,
    name = "艾瑟儿眉头微皱，和你毫无避讳地直言。"
  },
  [111950197] = {
    id = 111950197,
    name = "......你要去就去吧，这里的问题的确需要有人来解决。"
  },
  [111950198] = {
    id = 111950198,
    name = "你不和我一起？"
  },
  [111950199] = {
    id = 111950199,
    name = "我会在公会来之前，找到我想要的东西。"
  },
  [111950200] = {
    id = 111950200,
    name = "你想找的是什么东西？如果在公会发布委托，他们也能帮你。"
  },
  [111950201] = {
    id = 111950201,
    name = "......不需要。"
  },
  [111950202] = {
    id = 111950202,
    name = "你还想劝劝她，已听到“嚓嚓”的脚步声，有什么东西正在快速地朝你们靠近。"
  },
  [111950203] = {
    id = 111950203,
    name = "是那些居民，他们来了。"
  },
  [111950204] = {
    id = 111950204,
    name = "他们怎么会知道我们离开了房间？"
  },
  [111950205] = {
    id = 111950205,
    name = "现在不是说这个的时候。"
  },
  [111950206] = {
    id = 111950206,
    name = "趁人还没来，你沿着这条路一直跑，跑出据点，他们就不会追你了。"
  },
  [111950207] = {
    id = 111950207,
    name = "来不及了，就这样吧。"
  },
  [111950208] = {
    id = 111950208,
    name = "你拿出了武器，和她并肩而站。"
  },
  [111950209] = {
    id = 111950209,
    name = "艾瑟儿诧异地看了你一眼，嘴角弯了弯。"
  },
  [111950210] = {
    id = 111950210,
    name = "呵，现在想走也来不及了。"
  },
  [111950211] = {
    id = 111950211,
    name = "那些居民已经围了上来，他们眼神空洞，步伐僵硬，却带着一种让人胆寒的压迫感。"
  },
  [111950212] = {
    id = 111950212,
    name = "艾瑟儿，他们都被那些丝线控制着！"
  },
  [111950213] = {
    id = 111950213,
    name = "月光照在街道上，光影间，你看见了那些丝线。"
  },
  [111950214] = {
    id = 111950214,
    name = "那些丝线直直地吊在上方，仿佛被无形的手掌控着。"
  },
  [111950215] = {
    id = 111950215,
    name = "傀儡！原来如此，那家伙还在这个据点里吧。"
  },
  [111950216] = {
    id = 111950216,
    name = "不是诅咒......他们都被人控制了。"
  },
  [111950217] = {
    id = 111950217,
    name = "居民们逐渐靠近，嘴里发出低沉的咆哮声。"
  },
  [111950218] = {
    id = 111950218,
    name = "艾瑟儿率先冲上前去，手中利刃在空中划过一道凌厉的弧线，精准地刺向一个居民的手腕。"
  },
  [111950219] = {
    id = 111950219,
    name = "没有血？！"
  },
  [111950220] = {
    id = 111950220,
    name = "那居民身形一顿，没有流血，也没有倒下，被刺中的手无力地垂下，接着更加跌跌撞撞地扑向艾瑟儿。"
  },
  [111950221] = {
    id = 111950221,
    name = "你一脚踹开居民，临空一划，将空气中看不见的丝线切断，那居民立刻如木偶般倒在了地上。"
  },
  [111950222] = {
    id = 111950222,
    name = "不用伤害他们，斩断那些丝线就可以！"
  },
  [111950223] = {id = 111950223, name = "好！"},
  [111950224] = {
    id = 111950224,
    name = "你明显感到艾瑟儿四周压力一松。"
  },
  [111950225] = {
    id = 111950225,
    name = "没有了心理负担，她和你一起寻找并切断丝线，很快你们面前就躺了一地的居民。"
  },
  [111950226] = {
    id = 111950226,
    name = "可很快又出现了更多的居民，艾瑟儿喘了口气，紧皱着眉。"
  },
  [111950227] = {
    id = 111950227,
    name = "啧，没完没了！"
  },
  [111950228] = {
    id = 111950228,
    name = "这时，她的脚突然被一个倒下的居民抓紧！"
  },
  [111950229] = {
    id = 111950229,
    name = "你及时拉住艾瑟儿，一剑切断那家伙手中的丝线，将艾瑟儿的腿解救出来。"
  },
  [111950230] = {id = 111950230, name = "谢谢。"},
  [111950231] = {
    id = 111950231,
    name = "小心，这些丝线在复原！"
  },
  [111950232] = {id = 111950232, name = "！！！"},
  [111950233] = {
    id = 111950233,
    name = "话刚说完，那些倒下的居民又摇摇摆摆地站了起来。"
  },
  [111950234] = {
    id = 111950234,
    name = "你们重新陷入了艰难地鏖战，极力避免他们将丝线“种”在你们身上。"
  },
  [111950235] = {
    id = 111950235,
    name = "可这些居民就像真的玩偶，不知疼痛，即使被击中，也只是稍微停顿一下，又继续攻击。"
  },
  [111950236] = {
    id = 111950236,
    name = "（再这样下去，我们都会变成傀儡！）"
  },
  [111950237] = {
    id = 111950237,
    name = "走，我们回去！"
  },
  [111950238] = {id = 111950238, name = "喂！"},
  [111950239] = {
    id = 111950239,
    name = "你毫不犹豫地拉起艾瑟儿的手，朝着玩偶房间的方向跑去。"
  },
  [111950240] = {
    id = 111950240,
    name = "居民们在后面紧追不舍，杂乱的脚步声如同催命的鼓点。"
  },
  [111950241] = {
    id = 111950241,
    name = "你们拼尽全力奔跑，终于在村民们追上之前冲进了玩偶房间。"
  },
  [111950242] = {
    id = 111950242,
    name = "砰！你们迅速关上房门，用身体抵住房门。"
  },
  [111950243] = {
    id = 111950243,
    name = "喂，接下来怎么办？"
  },
  [111950244] = {
    id = 111950244,
    name = "你转过身，看着房间里那些本已安静下来的玩偶，又重新睁开了眼睛。"
  },
  [111950245] = {
    id = 111950245,
    name = "喂，接下来怎么办？"
  },
  [111950246] = {
    id = 111950246,
    name = "你与艾瑟儿背靠着房间的门。"
  },
  [111950247] = {
    id = 111950247,
    name = "前方是蠢蠢欲动的玩偶，门后是穷追不舍的居民。"
  },
  [111950248] = {
    id = 111950248,
    name = "如果毁掉这些玩偶，会不会不太礼貌？"
  },
  [111950249] = {
    id = 111950249,
    name = "你的笑话真冷。"
  },
  [111950250] = {
    id = 111950250,
    name = "话虽这么说，但她已拿起了武器，同意了你的提议。"
  },
  [111950251] = {
    id = 111950251,
    name = "虽然它们让人不忍心下手，但我更不想面对外面活生生的人。"
  },
  [111950252] = {
    id = 111950252,
    name = "尽管他们的灵魂已经死了。"
  },
  [111950253] = {
    id = 111950253,
    name = "唰！一只玩偶扑来，被艾瑟儿斩成两段。"
  },
  [111950254] = {
    id = 111950254,
    name = "小心丝线！"
  },
  [111950255] = {
    id = 111950255,
    name = "被斩成两半的玩偶肚子里，涌出了一堆丝线，缠绕在艾瑟儿的武器上，怎么甩也甩不掉。"
  },
  [111950256] = {
    id = 111950256,
    name = "啧，真麻烦啊！"
  },
  [111950257] = {
    id = 111950257,
    name = "这些丝线仿佛有生命一般，迅速朝着你们缠绕过来。"
  },
  [111950258] = {
    id = 111950258,
    name = "一旦缠在人身上，就会如同附骨之疽，让人难以挣脱。"
  },
  [111950259] = {id = 111950259, name = "用火！"},
  [111950260] = {
    id = 111950260,
    name = "你抓起油灯放在艾瑟儿的武器下燃烧，丝线很快脱落，被烧成了灰烬。"
  },
  [111950261] = {
    id = 111950261,
    name = "而那些玩偶似乎有些惧怕的意识，暂时没有再向你们靠近。"
  },
  [111950262] = {
    id = 111950262,
    name = "干脆都烧了。"
  },
  [111950263] = {
    id = 111950263,
    name = "还是不要了......"
  },
  [111950264] = {
    id = 111950264,
    name = "火势一起，我们是没办法阻止的。"
  },
  [111950265] = {
    id = 111950265,
    name = "我也只是说说气话。"
  },
  [111950266] = {
    id = 111950266,
    name = "要是真全烧了，我们又要出去面对外面那群人了。"
  },
  [111950267] = {
    id = 111950267,
    name = "而且我有一种感觉，我要找的东西，一定在这间房子里。"
  },
  [111950268] = {
    id = 111950268,
    name = "你从身后门缝里看了看屋外的居民，他们在门口围了一圈又一圈，死死地盯着房屋。"
  },
  [111950269] = {
    id = 111950269,
    name = "外面那些人好像很害怕这里，没人敢靠近。"
  },
  [111950270] = {
    id = 111950270,
    name = "那就先专心应付这些玩偶吧。"
  },
  [111950271] = {
    id = 111950271,
    name = "被斩成两段的玩偶在地上躺尸，此刻却起了微妙的变化。"
  },
  [111950272] = {
    id = 111950272,
    name = "它肚子里残留的丝线开始自动缝合，颤巍巍地站起来，走两步又摔倒了。"
  },
  [111950273] = {id = 111950273, name = "......"},
  [111950274] = {
    id = 111950274,
    name = "呃......其实，它们还挺可爱的。"
  },
  [111950275] = {
    id = 111950275,
    name = "你抽了抽眼皮。"
  },
  [111950276] = {
    id = 111950276,
    name = "给人身上种丝线那种可爱吗？"
  },
  [111950277] = {
    id = 111950277,
    name = "咳。既然它们怕火，我想到一个办法，但需要一点时间。"
  },
  [111950278] = {
    id = 111950278,
    name = "你帮我看着，别让它们突然过来。"
  },
  [111950279] = {
    id = 111950279,
    name = "火？你真的要烧了它们？"
  },
  [111950280] = {
    id = 111950280,
    name = "好好看着。"
  },
  [111950281] = {
    id = 111950281,
    name = "她再次打开了工具箱，找到两块蕴含冰和火元素的晶石。"
  },
  [111950282] = {
    id = 111950282,
    name = "——铛！！她抡起锤子，一下将两块晶石敲成了粉末。"
  },
  [111950283] = {
    id = 111950283,
    name = "接着，她将火晶石粉末倒入一个小巧的容器中，然后加入几滴凝固的魔法药水，很快容器中形成了一团火焰漩涡，不断地旋转着，将粉末逐渐熔化。"
  },
  [111950284] = {
    id = 111950284,
    name = "接着，艾瑟儿一边控制着火焰的温度，一边以同样的操作将冰元素的晶石做出了同样的漩涡。"
  },
  [111950285] = {
    id = 111950285,
    name = "她将冰层覆盖在熔化的火焰上，瞬间，火焰被冰层紧紧包裹，却依然散发着炽热的温度。"
  },
  [111950286] = {
    id = 111950286,
    name = "火为什么没有熄灭？！"
  },
  [111950287] = {
    id = 111950287,
    name = "水与火，黑与白，这个世界没有什么不可以共存，就连敌人也可以变成朋友。"
  },
  [111950288] = {
    id = 111950288,
    name = "只要恰到好处，就能产生意想不到的效果。"
  },
  [111950289] = {
    id = 111950289,
    name = "她将掌心的冰火弹扔了出去，魔法弹在空中划过一道美丽的弧线，准确地击中了一个玩偶的身体。"
  },
  [111950290] = {id = 111950290, name = "轰！"},
  [111950291] = {
    id = 111950291,
    name = "火焰瞬间蔓延开来，将玩偶的躯体包裹其中，很快，火焰受到了丝线的牵引，蔓延在一个又一个玩偶身体上，一一烧毁。"
  },
  [111950292] = {
    id = 111950292,
    name = "小心，它们开始动了！"
  },
  [111950293] = {
    id = 111950293,
    name = "玩偶们似乎意识到了灭顶危机的到来，开始分散四窜逃走，有的还朝你们扑了上来，被你轻松刺穿后用烛火烧尽。"
  },
  [111950294] = {
    id = 111950294,
    name = "随着冰火弹的不断蔓延，房间里的玩偶群逐渐被消灭殆尽。"
  },
  [111950295] = {
    id = 111950295,
    name = "最后，只剩下一堆被烧毁的玩偶残骸，而这时冰也随之融化了。"
  },
  [111950296] = {
    id = 111950296,
    name = "奇怪，之前我呆在这间屋子的时候，它们为什么不立刻攻击我？"
  },
  [111950297] = {
    id = 111950297,
    name = "反而在你来了之后......"
  },
  [111950298] = {
    id = 111950298,
    name = "她转过身将你从头到脚打量了一番，恍然大悟。"
  },
  [111950299] = {
    id = 111950299,
    name = "啊，难道因为你是男人？"
  },
  [111950300] = {
    id = 111950300,
    name = "啊？什么？"
  },
  [111950301] = {
    id = 111950301,
    name = "因为这些玩偶都是女孩啊！"
  },
  [111950302] = {
    id = 111950302,
    name = "你不禁一怔，忽然觉得她说得很有道理。"
  },
  [111950303] = {
    id = 111950303,
    name = "嗯？这是什么？"
  },
  [111950304] = {
    id = 111950304,
    name = "玩具残骸间，一根漆黑的丝线在缓慢地耸动，以缓慢的速度缩回了玩偶架中，消失不见了。"
  },
  [111950305] = {
    id = 111950305,
    name = "偷偷摸摸的家伙，出来！"
  },
  [111950306] = {
    id = 111950306,
    name = "轰！艾瑟儿武器一扬，锋利的尖刃劈开了玩偶架，露出了背后的一道黑漆漆的通道。"
  },
  [111950307] = {
    id = 111950307,
    name = "......暗道？"
  },
  [111950308] = {
    id = 111950308,
    name = "这里果然暗藏玄机啊。"
  },
  [111950309] = {
    id = 111950309,
    name = "走，进去看看！"
  },
  [111950310] = {
    id = 111950310,
    name = "祝你生日快乐......祝你生日快乐......"
  },
  [111950311] = {
    id = 111950311,
    name = "喑哑的低吟从暗道深处传来，你们对视一眼，警惕地向前走着。"
  },
  [111950312] = {
    id = 111950312,
    name = "祝你生日快乐......祝你生日快乐......"
  },
  [111950313] = {
    id = 111950313,
    name = "歌声低沉而诡异，时断时续，仿佛不是人类嗓子发出的。"
  },
  [111950314] = {
    id = 111950314,
    name = "要点灯吗？"
  },
  [111950315] = {
    id = 111950315,
    name = "试试看。"
  },
  [111950316] = {
    id = 111950316,
    name = "艾瑟儿拿出发光的魔法石，照亮了通道，并没有出现什么异常。"
  },
  [111950317] = {
    id = 111950317,
    name = "不多久，你们走到了暗道的尽头，一间密室出现在眼前。"
  },
  [111950318] = {
    id = 111950318,
    name = "好多玩偶娃娃！"
  },
  [111950319] = {
    id = 111950319,
    name = "密室中堆满了玩偶，各种形态的玩偶让人眼花缭乱。"
  },
  [111950320] = {
    id = 111950320,
    name = "祝你......生日......快乐......"
  },
  [111950321] = {id = 111950321, name = "！！！"},
  [111950322] = {
    id = 111950322,
    name = "密室的一角，歌声还在继续，你们循声看去，竟然是一个男人形态的傀儡。"
  },
  [111950323] = {
    id = 111950323,
    name = "祝你......生日......快乐......"
  },
  [111950324] = {
    id = 111950324,
    name = "这个傀儡看起来很老旧，手肘和腿部都露出了破损的零件，此时正低头“专心”缝制着玩偶，对你们的到来浑然不觉。"
  },
  [111950325] = {
    id = 111950325,
    name = "......是傀儡，没事。"
  },
  [111950326] = {
    id = 111950326,
    name = "这个傀儡，真像活人啊。"
  },
  [111950327] = {
    id = 111950327,
    name = "艾瑟儿，你干什么？"
  },
  [111950328] = {
    id = 111950328,
    name = "艾瑟儿靠近傀儡，听到你的阻止停下了脚步。"
  },
  [111950329] = {
    id = 111950329,
    name = "哦，我就是想研究研究，借鉴一下制作工具的办法。"
  },
  [111950330] = {
    id = 111950330,
    name = "这种会说话的傀儡，还是第一次见。"
  },
  [111950331] = {
    id = 111950331,
    name = "祝你......生日......快乐......"
  },
  [111950332] = {
    id = 111950332,
    name = "傀儡又唱出了这一句，不断重复的歌词，却令人感到阴森瘆人。"
  },
  [111950333] = {
    id = 111950333,
    name = "不过只会这一句，做出这个傀儡的家伙，是想给人送生日礼物吧。"
  },
  [111950334] = {
    id = 111950334,
    name = "生日礼物？"
  },
  [111950335] = {
    id = 111950335,
    name = "你忽然想到一种猜测。"
  },
  [111950336] = {
    id = 111950336,
    name = "你说，这些玩偶，是不是都是生日礼物？"
  },
  [111950337] = {
    id = 111950337,
    name = "那他为什么要把外面那些活人都变成傀儡？"
  },
  [111950338] = {
    id = 111950338,
    name = "......也许这里找得到答案。"
  },
  [111950339] = {
    id = 111950339,
    name = "残破的傀儡还在重复地唱着歌，你们没有轻举妄动，转而看向房间的其他地方。"
  },
  [111950340] = {
    id = 111950340,
    name = "这时，艾瑟儿的目光被一个特别的玩偶吸引住了。"
  },
  [111950341] = {
    id = 111950341,
    name = "那是一个女娃娃玩偶，模样栩栩如生，如同真人一般。"
  },
  [111950342] = {
    id = 111950342,
    name = "这个做得也太好了......"
  },
  [111950343] = {
    id = 111950343,
    name = "艾瑟儿忍不住好奇，缓缓伸出手去触碰那个女娃玩偶。"
  },
  [111950344] = {
    id = 111950344,
    name = "......别碰它......别碰它......别碰它别碰它别碰它别碰它！！"
  },
  [111950345] = {
    id = 111950345,
    name = "她的手指刚刚触碰到女娃玩偶的瞬间，傀儡突然发狂了。"
  },
  [111950346] = {
    id = 111950346,
    name = "他猛地站起身来，发出一声尖锐的叫声。周围的玩偶仿佛受到了召唤，纷纷开始活动起来。"
  },
  [111950347] = {
    id = 111950347,
    name = "无数的丝线暴起，朝你和艾瑟儿激射而至！"
  },
  [111950348] = {
    id = 111950348,
    name = "你扔出手边的所有东西，只能抵挡一时，那些被丝线包裹的武器桌椅，很快又调头袭击而来！"
  },
  [111950349] = {
    id = 111950349,
    name = "尝尝这个！"
  },
  [111950350] = {
    id = 111950350,
    name = "艾瑟儿扔出手中发光的魔法石，在丝线包裹石头后，瞬间催动魔法力引爆！"
  },
  [111950351] = {
    id = 111950351,
    name = "砰！！！丝线炸了一地，那些玩偶也纷纷落在了地上。"
  },
  [111950352] = {
    id = 111950352,
    name = "......你们都该死！你们才是真正的魔物！"
  },
  [111950353] = {
    id = 111950353,
    name = "他还会说话？！难道是触动了防御机制？！"
  },
  [111950354] = {
    id = 111950354,
    name = "你们，统统都该去死！"
  },
  [111950355] = {
    id = 111950355,
    name = "傀儡怒吼一声，整个房间的墙壁突然亮了，显露出可怖的符文和图案。"
  },
  [111950356] = {
    id = 111950356,
    name = "不好，是和灵魂相关的魔法！"
  },
  [111950357] = {
    id = 111950357,
    name = "躲起来！"
  },
  [111950358] = {id = 111950358, name = "轰！！"},
  [111950359] = {
    id = 111950359,
    name = "你撑开魔法屏障，将艾瑟儿护在角落，只见千万条丝线如丝网在屏障上铺开，遮蔽了你和艾瑟儿的视线。"
  },
  [111950360] = {
    id = 111950360,
    name = "视野消失时，艾瑟儿亮出了武器，一层冰火粉末交织在利刃之上，猛地将黑暗划破！"
  },
  [111950361] = {
    id = 111950361,
    name = "不！！小艾、小艾！！"
  },
  [111950362] = {
    id = 111950362,
    name = "利刃扬起的冰火碎粒，将丝线切断，如雨般脱落。残破的傀儡跪走到完美的玩偶娃娃前大声痛哭。"
  },
  [111950363] = {
    id = 111950363,
    name = "......小艾？他不会是在叫你吧？"
  },
  [111950364] = {
    id = 111950364,
    name = "你的这个笑话也很冷。"
  },
  [111950365] = {
    id = 111950365,
    name = "那逼真的女娃正在被烧成灰烬，傀儡发疯般地在地上寻找丝线弥补。"
  },
  [111950366] = {
    id = 111950366,
    name = "小艾......你等着爸爸，爸爸会救活你的！"
  },
  [111950367] = {
    id = 111950367,
    name = "他的行动越来越迟缓，直到趴在地上，嘶哑无力地哭泣。"
  },
  [111950368] = {
    id = 111950368,
    name = "呜呜......是你们......你们害死了小艾......"
  },
  [111950369] = {
    id = 111950369,
    name = "你们把女儿还给我......"
  },
  [111950370] = {
    id = 111950370,
    name = "那傀儡的眼睛中闪烁着微弱的光芒，你与艾瑟儿悚然一惊。"
  },
  [111950371] = {
    id = 111950371,
    name = "你......不是傀儡？！"
  },
  [111950372] = {
    id = 111950372,
    name = "傀儡？哈哈哈哈......"
  },
  [111950373] = {
    id = 111950373,
    name = "他极力地撑起上半身，将破烂的布娃娃抱在怀里。"
  },
  [111950374] = {
    id = 111950374,
    name = "我除了这么做，还能怎么样？"
  },
  [111950375] = {
    id = 111950375,
    name = "小艾死了......小艾死了......"
  },
  [111950376] = {
    id = 111950376,
    name = "你说的小艾，是你手里的这个娃娃？"
  },
  [111950377] = {
    id = 111950377,
    name = "小艾......是我的女儿啊......"
  },
  [111950378] = {
    id = 111950378,
    name = "他轻声说着，嘶哑的声音时不时地断掉。"
  },
  [111950379] = {
    id = 111950379,
    name = "我、是一个魔偶师......"
  },
  [111950380] = {
    id = 111950380,
    name = "小艾生了重病，我带她来深渊寻药......"
  },
  [111950381] = {
    id = 111950381,
    name = "可她还没有等到我找到药，就失去呼吸了......"
  },
  [111950382] = {
    id = 111950382,
    name = "那天是她的生日，我做了好多玩偶娃娃，我还没给她唱生日歌......"
  },
  [111950383] = {
    id = 111950383,
    name = "我，我怎么可能让她死在我面前呢？"
  },
  [111950384] = {
    id = 111950384,
    name = "所以，我用了灵魂转移的禁术，想召回她的灵魂到傀儡身上......"
  },
  [111950385] = {
    id = 111950385,
    name = "这样，小艾就能继续活着，而我，也能继续给她找药。"
  },
  [111950386] = {id = 111950386, name = "......"},
  [111950387] = {id = 111950387, name = "......"},
  [111950388] = {
    id = 111950388,
    name = "可是，可是......"
  },
  [111950389] = {
    id = 111950389,
    name = "小艾被据点的人发现了......他们毁了小艾，杀了小艾......"
  },
  [111950390] = {
    id = 111950390,
    name = "我要杀了他们！！我发誓！！"
  },
  [111950391] = {
    id = 111950391,
    name = "你叹息了一声，大概猜到了接下来发生的事。"
  },
  [111950392] = {
    id = 111950392,
    name = "呵呵呵......他们以为我杀不了他们，就可以高枕无忧吗？！"
  },
  [111950393] = {
    id = 111950393,
    name = "他们以为杀了我，就能心安理得忘记这件事吗？！"
  },
  [111950394] = {
    id = 111950394,
    name = "我早就用抽取转移灵魂的禁术，把自己做成了傀儡藏起来了。"
  },
  [111950395] = {
    id = 111950395,
    name = "然后，我把他们统统做成了傀儡！"
  },
  [111950396] = {
    id = 111950396,
    name = "既然你已经复仇，为什么还要用丝线去控制无辜人？"
  },
  [111950397] = {
    id = 111950397,
    name = "无辜......呵呵，且不说探险者是不是无辜......"
  },
  [111950398] = {
    id = 111950398,
    name = "我发现自己的意识在消失......我需要魔法力作为养料......"
  },
  [111950399] = {
    id = 111950399,
    name = "而这间布满禁术符文的密室，我走不出去，也无法离开了。"
  },
  [111950400] = {
    id = 111950400,
    name = "我只能借傀儡的眼睛，去看，去听，再将他们变成我的傀儡......"
  },
  [111950401] = {
    id = 111950401,
    name = "作茧自缚。"
  },
  [111950402] = {
    id = 111950402,
    name = "呵呵呵呵......我能有什么办法呢......"
  },
  [111950403] = {
    id = 111950403,
    name = "我还不想消失......我还想治好小艾......"
  },
  [111950404] = {
    id = 111950404,
    name = "艾瑟儿看着他怀中抱着的破烂布偶，残忍地说。"
  },
  [111950405] = {
    id = 111950405,
    name = "你的女儿早就死了，在她过生日的那天。"
  },
  [111950406] = {
    id = 111950406,
    name = "可你却因为一己私欲，将她锁在一个不能说不能动的玩偶里。"
  },
  [111950407] = {
    id = 111950407,
    name = "不！我没有禁锢她，那个魔法失败了！"
  },
  [111950408] = {
    id = 111950408,
    name = "傀儡忽然激动起来，又颓丧地惨笑着。"
  },
  [111950409] = {
    id = 111950409,
    name = "对啊......小艾早就不在了......我这么做又是为什么，为什么呢......"
  },
  [111950410] = {
    id = 111950410,
    name = "傀儡缓缓地垂下了头，意识随着房间的丝线一同消散了。"
  },
  [111950411] = {
    id = 111950411,
    name = "随着魔法符文的破解，房间中的一切在缓缓消逝，光芒也如星光散去，重归黑暗。"
  },
  [111950412] = {
    id = 111950412,
    name = "艾瑟儿重新点亮了晶石，正前方的桌子上，一个可爱的玩偶并没有受到影响而销毁。"
  },
  [111950413] = {
    id = 111950413,
    name = "她拿起了那个娃娃，背后写着“生日快乐，我的女儿”。"
  },
  [111950414] = {
    id = 111950414,
    name = "这是何必呢？"
  },
  [111950415] = {
    id = 111950415,
    name = "活就活，死就死，不敢接受现实，还想着找各种理由，都是自以为是的懦夫罢了。"
  },
  [111950416] = {
    id = 111950416,
    name = "她把手中的娃娃抛了抛，正打算重新放回桌上，却看见了另一样东西。"
  },
  [111950417] = {
    id = 111950417,
    name = "嗯？那是什么？"
  },
  [111950418] = {
    id = 111950418,
    name = "地图？残卷？"
  },
  [111950419] = {
    id = 111950419,
    name = "艾瑟儿展开了手中的羊皮卷，睫毛微颤，微微张了张嘴。"
  },
  [111950420] = {
    id = 111950420,
    name = "找到了，就是这个！"
  },
  [111950421] = {
    id = 111950421,
    name = "羊皮卷上方写着不知名地宫的位置，以及一张地图。"
  },
  [111950422] = {
    id = 111950422,
    name = "图上除了标记了地宫明确的入口，还记载了寻找万能药的途径。"
  },
  [111950423] = {
    id = 111950423,
    name = "万能药？你找的是这个？"
  },
  [111950424] = {id = 111950424, name = "不错！"},
  [111950425] = {
    id = 111950425,
    name = "看来这个父亲生前一直在为女儿寻药，并没有放弃过。"
  },
  [111950426] = {id = 111950426, name = "......"},
  [111950427] = {
    id = 111950427,
    name = "艾瑟儿不知想到了什么，这时的表情也变得哀伤了起来。"
  },
  [111950428] = {
    id = 111950428,
    name = "他已经找到了万能药的位置，如果他的女儿再多活些时间，结局或许会不一样。"
  },
  [111950429] = {
    id = 111950429,
    name = "这也许就是命运吧。"
  },
  [111950430] = {
    id = 111950430,
    name = "我不会让这样的悲剧发生。"
  },
  [111950431] = {
    id = 111950431,
    name = "艾瑟儿，你找万能药是为了......"
  },
  [111950432] = {
    id = 111950432,
    name = "我的父亲。"
  },
  [111950433] = {
    id = 111950433,
    name = "他在一次战斗中受到了重伤，从此再也拿不起武器。"
  },
  [111950434] = {
    id = 111950434,
    name = "我要为他找到治好伤病的药，这也是我来这个据点的原因。"
  },
  [111950435] = {
    id = 111950435,
    name = "那你接下来，要去这个地方吗？"
  },
  [111950436] = {id = 111950436, name = "当然。"},
  [111950437] = {
    id = 111950437,
    name = "你感受到她心情重新振作好转，跟你离开密室，一路说着话。"
  },
  [111950438] = {
    id = 111950438,
    name = "有了这个线索，我就能去探索这个地宫了。"
  },
  [111950439] = {
    id = 111950439,
    name = "哦对了，你跟我一起去吧，正好也多个帮手。"
  },
  [111950440] = {id = 111950440, name = "啊？"},
  [111950441] = {
    id = 111950441,
    name = "啊什么？好歹我也是救了你，你难道还要找借口推脱？"
  },
  [111950442] = {
    id = 111950442,
    name = "当然不是。"
  },
  [111950443] = {
    id = 111950443,
    name = "只是，我们除了这张地图，对地宫了解得太少了。"
  },
  [111950444] = {
    id = 111950444,
    name = "那就慢慢探索。"
  },
  [111950445] = {
    id = 111950445,
    name = "在前辈们没有探索深渊的时候，不也是一点点探索出来的吗？"
  },
  [111950446] = {
    id = 111950446,
    name = "嗯，你说得不错。"
  },
  [111950447] = {
    id = 111950447,
    name = "不过就我们两个，不需要多一些人手？"
  },
  [111950448] = {
    id = 111950448,
    name = "不用。与其找那些贪得无厌的家伙，不如和你一起去。"
  },
  [111950449] = {
    id = 111950449,
    name = "为什么？"
  },
  [111950450] = {
    id = 111950450,
    name = "因为你挺符合我的口味。"
  },
  [111950451] = {id = 111950451, name = "......"},
  [111950452] = {
    id = 111950452,
    name = "在这之前，我需要去圈落做一些准备。"
  },
  [111950453] = {
    id = 111950453,
    name = "她打开了玩具屋的房门。"
  },
  [111950454] = {
    id = 111950454,
    name = "外面天色初明，一圈又一圈的傀儡因失去了控制倒在地上，全都没了生机。"
  },
  [111950455] = {
    id = 111950455,
    name = "这么诡异的事，竟然就这样轻松解决了。"
  },
  [111950456] = {
    id = 111950456,
    name = "我想还是去和公会打个招呼，这样据点也不至于就此荒废吧。"
  },
  [111950457] = {
    id = 111950457,
    name = "你还真有一副好心肠。"
  },
  [111950458] = {
    id = 111950458,
    name = "小心点，在这深渊，太好心可是会吃大亏的。"
  },
  [111950459] = {
    id = 111950459,
    name = "她伸手拍了拍你的脸，朝你洒然一笑，转身而去。"
  },
  [111950460] = {
    id = 111950460,
    name = "记得来啊，我会等你的！"
  },
  [111950461] = {
    id = 111950461,
    name = "........................"
  },
  [111950462] = {
    id = 111950462,
    name = "哇啊，好神奇的经历啊！"
  },
  [111950463] = {
    id = 111950463,
    name = "那老师后来有没有去地宫呢？"
  },
  [111950464] = {
    id = 111950464,
    name = "去了，也是在那个地宫里，我才从她那里学会了很多破解机关的手法。"
  },
  [111950465] = {
    id = 111950465,
    name = "真羡慕啊，那时候队长在深渊快乐地和女孩子探险，我只能埋在文书里帮爷爷处理工作。"
  },
  [111950466] = {
    id = 111950466,
    name = "是吗？我以为你那时候很开心呢。"
  },
  [111950467] = {id = 111950467, name = "呃......"},
  [111950468] = {
    id = 111950468,
    name = "队长，东西可以吃了。"
  },
  [111950469] = {
    id = 111950469,
    name = "我去叫列蒂西雅和莉娃。"
  },
  [111950470] = {
    id = 111950470,
    name = "啊，队长，我还没听够呢。"
  },
  [111950471] = {
    id = 111950471,
    name = "那可就是另外一个故事了，有时间讲给你们听。"
  },
  [111950472] = {id = 111950472, name = "好耶！"},
  [111560001] = {
    id = 111560001,
    name = "我又来啦，大姐！"
  },
  [111560002] = {
    id = 111560002,
    name = "一身棕衣的少女熟门熟路地走到了帕纳哈克斯圈落的小摊前，笑眯眯地看着摆摊的老板。"
  },
  [111560003] = {
    id = 111560003,
    name = "我今天有钱了！快把那株草卖给我吧。"
  },
  [111560004] = {
    id = 111560004,
    name = "......什么草？"
  },
  [111560005] = {
    id = 111560005,
    name = "就是上次我看中的铃铛草啊，不是让你给我留着吗？"
  },
  [111560006] = {
    id = 111560006,
    name = "哦，那个我看你几天没来，以为你不需要，就卖掉了。"
  },
  [111560007] = {
    id = 111560007,
    name = "什么？！！"
  },
  [111560008] = {
    id = 111560008,
    name = "唉，已经过了约定的时间，也正好有顾客需要，我就卖给他了。"
  },
  [111560009] = {
    id = 111560009,
    name = "啊？？......"
  },
  [111560010] = {
    id = 111560010,
    name = "听到这话，蒙娜呆愣在了原地，随即眼眶就红了。"
  },
  [111560011] = {
    id = 111560011,
    name = "那我......我应该怎么办啊......"
  },
  [111560012] = {
    id = 111560012,
    name = "明明只缺这一样，只缺这一样，我就能调制出最好的小麦增长剂。"
  },
  [111560013] = {
    id = 111560013,
    name = "我这么久的努力，就要化为泡影，我期待的假期，也要离我远去了......"
  },
  [111560014] = {
    id = 111560014,
    name = "蒙娜喃喃自语，透亮的泪珠在眼眶里打转，看得摊主心慌慌。"
  },
  [111560015] = {
    id = 111560015,
    name = "喂喂，你别哭啊，你一哭，我这生意不好做了啊。"
  },
  [111560016] = {
    id = 111560016,
    name = "这样吧，我给你说哪儿还有，你自己去找找看。"
  },
  [111560017] = {
    id = 111560017,
    name = "蒙娜精神一振。"
  },
  [111560018] = {
    id = 111560018,
    name = "在哪儿在哪儿？"
  },
  [111560019] = {
    id = 111560019,
    name = "西南方向的山谷，有个山洞就长这个。"
  },
  [111560020] = {
    id = 111560020,
    name = "不过后来，那附近出现了魔物，铃铛草也卖不了几个钱，很多人不愿意去了。"
  },
  [111560021] = {
    id = 111560021,
    name = "圈落摊贩告诉了蒙娜具体的位置，蒙娜很认真地点头，表示记下了。"
  },
  [111560022] = {
    id = 111560022,
    name = "那地方魔物不简单，很多探险者都折在那了，你最好找些高手跟你一起再行动，为了几棵草把小命丢了不值得。"
  },
  [111560023] = {
    id = 111560023,
    name = "哦，知道了。"
  },
  [111560024] = {
    id = 111560024,
    name = "你每天下田不容易，下次需要什么跟我说一说，钱不够就先欠着也行。"
  },
  [111560025] = {
    id = 111560025,
    name = "谢谢大姐。"
  },
  [111560026] = {
    id = 111560026,
    name = "谢什么，是你在帮咱们的麦田提高产量呢。这次是我疏忽了，以后我有好东西都给你留一留。"
  },
  [111560027] = {
    id = 111560027,
    name = "蒙娜脸上挂着笑，心里的苦没人知道。"
  },
  [111560028] = {
    id = 111560028,
    name = "（要不是欠了圈落那么多钱，谁想天天下田做研究......）"
  },
  [111560029] = {
    id = 111560029,
    name = "她离开市集，有气无力地想着。"
  },
  [111560030] = {
    id = 111560030,
    name = "到哪儿找高手啊......就差这最后一步了。"
  },
  [111560031] = {
    id = 111560031,
    name = "只差一步，就能做好药剂，自由地去探险了啊！"
  },
  [111560032] = {
    id = 111560032,
    name = "加油，蒙娜！你可以的！"
  },
  [111560033] = {
    id = 111560033,
    name = "正在给自己打气的蒙娜，看见对面走过来一个黑发少女。"
  },
  [111560034] = {
    id = 111560034,
    name = "那黑发少女身负大剑，面有疲色，却沉静凝肃，与她擦身经过时，蒙娜闻到了一股血腥气。"
  },
  [111560035] = {
    id = 111560035,
    name = "（咦，探险者。）"
  },
  [111560036] = {
    id = 111560036,
    name = "看着少女前去的方向，蒙娜心中一道灵光闪过。"
  },
  [111560037] = {
    id = 111560037,
    name = "（公会？对啊，我也可以去公会看看有没有机会啊！）"
  },
  [111560038] = {
    id = 111560038,
    name = "蒙娜二话不说也转身去了公会办事处。"
  },
  [111560039] = {
    id = 111560039,
    name = "麻烦你了。"
  },
  [111560040] = {
    id = 111560040,
    name = "黑发少女递出了一个袋子，交给公会清点。"
  },
  [111560041] = {
    id = 111560041,
    name = "罗亚小姐，这么快就完成委托了！"
  },
  [111560042] = {
    id = 111560042,
    name = "我清点一下，没问题。这是你的酬劳，请拿好。"
  },
  [111560043] = {
    id = 111560043,
    name = "（羡慕啊，这样来钱一定很快吧......）"
  },
  [111560044] = {
    id = 111560044,
    name = "还有需要完成的委托吗？"
  },
  [111560045] = {
    id = 111560045,
    name = "嗯？罗亚小姐这才刚刚回来，不休息一下吗？"
  },
  [111560046] = {
    id = 111560046,
    name = "不了，今天的时间还早。"
  },
  [111560047] = {
    id = 111560047,
    name = "这里有几个委托，都相对难一些，如果能找到帮手最好。"
  },
  [111560048] = {
    id = 111560048,
    name = "没事，我看看。"
  },
  [111560049] = {
    id = 111560049,
    name = "罗亚低头看着公会成员递来的委托记录，神色无波地指向了一条。"
  },
  [111560050] = {
    id = 111560050,
    name = "就这个吧，还有这个。"
  },
  [111560051] = {
    id = 111560051,
    name = "两个委托？罗亚小姐，后面这个是限时的，你确定都接吗？"
  },
  [111560052] = {id = 111560052, name = "嗯。"},
  [111560053] = {
    id = 111560053,
    name = "她转身离开，踏出办事处的大门，明暗交错的光线里，四周是来来往往有说有笑的人，显得那道身影萧索而孤独。"
  },
  [111560054] = {
    id = 111560054,
    name = "罗亚走后，公会成员叹了口气，目光看向了蒙娜。"
  },
  [111560055] = {
    id = 111560055,
    name = "啊，是蒙娜小姐啊，怎么来这里了？是研究上遇到什么困难了吗？"
  },
  [111560056] = {
    id = 111560056,
    name = "没......没问题！我就是路过！"
  },
  [111560057] = {
    id = 111560057,
    name = "新药剂很快研发好了，包在蒙娜身上！"
  },
  [111560058] = {
    id = 111560058,
    name = "（怎么可以让他们小看蒙娜！）"
  },
  [111560059] = {
    id = 111560059,
    name = "好啊，我们一直很期待呢！"
  },
  [111560060] = {id = 111560060, name = "......"},
  [111560061] = {
    id = 111560061,
    name = "蒙娜溜走后，回到了热闹的大街，停下来思考了半晌。"
  },
  [111560062] = {
    id = 111560062,
    name = "要不......还是去山谷里看看？"
  },
  [111560063] = {
    id = 111560063,
    name = "哼，凭蒙娜的本事，还摘不到几株铃铛草吗？！"
  },
  [111560064] = {
    id = 111560064,
    name = "蒙娜气鼓鼓地对自己说，昂首挺胸地走出了圈落，并没注意和罗亚去的是同一个方向。"
  },
  [111560065] = {
    id = 111560065,
    name = "咦，这山谷的血腥气好重啊。"
  },
  [111560066] = {
    id = 111560066,
    name = "难道有探险者已经来过了？"
  },
  [111560067] = {
    id = 111560067,
    name = "蒙娜踏入山谷中，两侧是陡峭的悬崖，崖壁上生长着一些奇形怪状的植物，而铃铛草正在山谷的深处。"
  },
  [111560068] = {
    id = 111560068,
    name = "但此刻，她的直觉告诉自己：别再往里走了，危险！"
  },
  [111560069] = {id = 111560069, name = "......"},
  [111560070] = {
    id = 111560070,
    name = "在什么都没看到的时候，怎么就能这样退缩！"
  },
  [111560071] = {
    id = 111560071,
    name = "蒙娜顶着头皮往前走，脚下的土地潮湿而松软，漆黑的血色越来越明显。"
  },
  [111560072] = {
    id = 111560072,
    name = "真、真的是血啊！"
  },
  [111560073] = {
    id = 111560073,
    name = "血迹一路蜿蜒，有的地方甚至汇聚成了一小滩，蒙娜的心不禁提了起来。"
  },
  [111560074] = {
    id = 111560074,
    name = "呼，原来是魔物。"
  },
  [111560075] = {
    id = 111560075,
    name = "看见魔物尸体时，她呼出一口气。"
  },
  [111560076] = {
    id = 111560076,
    name = "那些形态各异的魔物死状惨烈，都是被斩成几段，断开处平整锋利，看得出下手之人的果决。"
  },
  [111560077] = {
    id = 111560077,
    name = "是个高手啊！"
  },
  [111560078] = {
    id = 111560078,
    name = "沿着血迹，蒙娜往深处探寻去，这与大姐告诉她的山洞方向一致。"
  },
  [111560079] = {
    id = 111560079,
    name = "糟了，那个高手不会是也想要铃铛草吧？！"
  },
  [111560080] = {
    id = 111560080,
    name = "蒙娜捏了捏拳，一副势在必得的样子。"
  },
  [111560081] = {
    id = 111560081,
    name = "绝不能让别人拿走我的铃铛草，否则我离开帕纳哈克斯圈落的日子就遥遥无期了！"
  },
  [111560082] = {
    id = 111560082,
    name = "她加快脚步，一阵激烈的打斗声传入了蒙娜的耳中。"
  },
  [111560083] = {
    id = 111560083,
    name = "有人！果然在那个山洞附近吗！"
  },
  [111560084] = {
    id = 111560084,
    name = "蒙娜握紧手中的法杖，小心翼翼地朝着声音的来源走去。"
  },
  [111560085] = {
    id = 111560085,
    name = "啊，是她！"
  },
  [111560086] = {
    id = 111560086,
    name = "当她绕过一片茂密的灌木丛，眼前的一幕让她吃了一惊。"
  },
  [111560087] = {
    id = 111560087,
    name = "先前擦身而过的黑发少女罗亚，正手持着巨剑和魔物激烈地战斗。"
  },
  [111560088] = {
    id = 111560088,
    name = "四周是零碎的魔物尸体，罗亚面色沉静，迎头撞上魔物的攻击。"
  },
  [111560089] = {
    id = 111560089,
    name = "剑刃与魔物的鳞片碰撞，发出刺耳的声响，火花四溅。"
  },
  [111560090] = {
    id = 111560090,
    name = "砰、砰、砰！"
  },
  [111560091] = {
    id = 111560091,
    name = "一声声巨响回响在深谷，也震醒了蒙娜的心神。"
  },
  [111560092] = {
    id = 111560092,
    name = "要，要帮忙吗？！"
  },
  [111560093] = {
    id = 111560093,
    name = "蒙娜朝她大喊，罗亚置若罔闻，目不斜视，眼前只有这只魔物。"
  },
  [111560094] = {
    id = 111560094,
    name = "黑发少女一跃而起，举剑斩向魔物，轰——"
  },
  [111560095] = {
    id = 111560095,
    name = "地面又被砸出了一个大坑，魔物被斩断了一条尖刺般的腿，血迹飞溅，尖声吼叫。"
  },
  [111560096] = {
    id = 111560096,
    name = "好、好强！"
  },
  [111560097] = {
    id = 111560097,
    name = "罗亚身形如电，趁魔物踉跄时追击而上，再斩了魔物另一条腿。"
  },
  [111560098] = {
    id = 111560098,
    name = "这这这家伙完全不需要我帮忙吧......"
  },
  [111560099] = {
    id = 111560099,
    name = "蒙娜惊叹间，魔物愤怒地反攻，疾速疯狂的晃花了她的眼。"
  },
  [111560100] = {id = 111560100, name = "呵！"},
  [111560101] = {
    id = 111560101,
    name = "罗亚轻喝一声，大剑带着一道耀眼的光芒，狠狠地斩向魔物。"
  },
  [111560102] = {
    id = 111560102,
    name = "只听一声巨响，魔物庞大的身躯轰然倒地，再也没有了动静。"
  },
  [111560103] = {
    id = 111560103,
    name = "蒙娜揉了揉眼睛，看清了死掉的魔物，也看到了罗亚手臂滴落的鲜血。"
  },
  [111560104] = {
    id = 111560104,
    name = "你受伤了！"
  },
  [111560105] = {
    id = 111560105,
    name = "蒙娜两步跑到她面前，少女竟后退了一步，面无表情地看着她。"
  },
  [111560106] = {
    id = 111560106,
    name = "啊，我没有坏心思的！你的伤口在流血，快治疗一下啊。"
  },
  [111560107] = {
    id = 111560107,
    name = "这时她才看得清楚，罗亚身上伤口不止一处，有鲜血不断地渗出。"
  },
  [111560108] = {
    id = 111560108,
    name = "蒙娜赶紧从自己的行囊中取出药物，递向罗亚。"
  },
  [111560109] = {
    id = 111560109,
    name = "我这里有药，你先止血吧。"
  },
  [111560110] = {
    id = 111560110,
    name = "罗亚冷冷地看了蒙娜一眼，果断地拒绝了她的好意。"
  },
  [111560111] = {
    id = 111560111,
    name = "不必了。"
  },
  [111560112] = {
    id = 111560112,
    name = "......啊？"
  },
  [111560113] = {
    id = 111560113,
    name = "罗亚对那些伤口视而不见，越过她而去。"
  },
  [111560114] = {
    id = 111560114,
    name = "不是吧，难道你感觉不到自己在流血吗？"
  },
  [111560115] = {
    id = 111560115,
    name = "这是我的事，和别人没关系。"
  },
  [111560116] = {
    id = 111560116,
    name = "罗亚没有回头，径直离开，她的黑发飞扬，在昏暗的山谷中显得格外孤寂萧索。"
  },
  [111560117] = {
    id = 111560117,
    name = "（这个人......防备心真重啊，都不让人靠近她。）"
  },
  [111560118] = {
    id = 111560118,
    name = "蒙娜望着罗亚的背影，那身姿依旧挺拔，却带着一种无法言说的疲惫。"
  },
  [111560119] = {
    id = 111560119,
    name = "......啊，等等，她杀的不会就是大姐说的那堆难缠的魔物吧？！"
  },
  [111560120] = {
    id = 111560120,
    name = "铃铛草、铃铛草......哇！找到了！"
  },
  [111560121] = {
    id = 111560121,
    name = "蒙娜采摘着新鲜的植物，心中欢呼雀跃。"
  },
  [111560122] = {
    id = 111560122,
    name = "自由，我来了！"
  },
  [111560123] = {
    id = 111560123,
    name = "辛苦你了，蒙娜小姐！"
  },
  [111560124] = {
    id = 111560124,
    name = "这一季度的实验已经全部完成，也取得了有效的成果！"
  },
  [111560125] = {
    id = 111560125,
    name = "我想等到明年，大家一定能迎来更加盛大的收获！"
  },
  [111560126] = {
    id = 111560126,
    name = "（真的完成了！我可以休息不用干活了？！）"
  },
  [111560127] = {
    id = 111560127,
    name = "蒙娜抑制住内心的激动，露出自信了然的表情。"
  },
  [111560128] = {
    id = 111560128,
    name = "呵呵，小意思，还要仰仗负责人的指点，也让我在研发药剂方面有了更多的经验。"
  },
  [111560129] = {
    id = 111560129,
    name = "（种田什么的一点也没有探险好玩，以后我才不要干这个了！）"
  },
  [111560130] = {
    id = 111560130,
    name = "多亏了蒙娜小姐，不仅制作了足以弥补损失的药剂，还能让产量翻倍，真是不愧是这一领域的天才啊！"
  },
  [111560131] = {
    id = 111560131,
    name = "（当然！蒙娜是最聪明的！）"
  },
  [111560132] = {
    id = 111560132,
    name = "哪里哪里，互相学习啦！"
  },
  [111560133] = {
    id = 111560133,
    name = "那个，既然药剂已经研发成功了，我是不是可以......"
  },
  [111560134] = {
    id = 111560134,
    name = "哦，当然！蒙娜小姐功大于过，那些债务完全可以就此抵消。"
  },
  [111560135] = {
    id = 111560135,
    name = "好好，那我——"
  },
  [111560136] = {
    id = 111560136,
    name = "但是呢，这种药剂的效果我们还要再观察一段时间。"
  },
  [111560137] = {
    id = 111560137,
    name = "（啊？！不能走？！）"
  },
  [111560138] = {
    id = 111560138,
    name = "这期间，蒙娜小姐可以在圈落四处走走，散散心，一旦有了结果，我们会及时告诉蒙娜小姐的。"
  },
  [111560139] = {
    id = 111560139,
    name = "......哦。"
  },
  [111560140] = {
    id = 111560140,
    name = "我这是......暂时放假？"
  },
  [111560141] = {
    id = 111560141,
    name = "当然，蒙娜小姐辛苦这么久，也该好好歇息一阵了。"
  },
  [111560142] = {
    id = 111560142,
    name = "蒙娜就快压不住弯起来的笑。"
  },
  [111560143] = {
    id = 111560143,
    name = "那这段时间那些研究人员不会再跟着我了吧？"
  },
  [111560144] = {
    id = 111560144,
    name = "呵呵，蒙娜小姐是自由的。"
  },
  [111560145] = {
    id = 111560145,
    name = "太好了！我放假了！"
  },
  [111560146] = {
    id = 111560146,
    name = "蒙娜昂首阔步走出了管理处，抬头深呼吸一口气。"
  },
  [111560147] = {
    id = 111560147,
    name = "啊，感觉身体突然变轻了呢。"
  },
  [111560148] = {
    id = 111560148,
    name = "一连几天都闷在实验室里，接下来，去哪里逛逛呢！"
  },
  [111560149] = {
    id = 111560149,
    name = "她闲适地走走逛逛，竟然再次看到了罗亚。"
  },
  [111560150] = {
    id = 111560150,
    name = "此时的罗亚看起来状态比上次更加糟糕，她的脸色苍白，眼神中透露出深深的疲惫。"
  },
  [111560151] = {
    id = 111560151,
    name = "但她的脚步依旧是稳重的，像笔直的松竹，千磨万击后仍然坚挺。"
  },
  [111560152] = {id = 111560152, name = "喂......"},
  [111560153] = {
    id = 111560153,
    name = "蒙娜想和她打招呼，忽然忘了这个一面之缘少女的名字。"
  },
  [111560154] = {id = 111560154, name = "......"},
  [111560155] = {
    id = 111560155,
    name = "罗亚听到了她的声音，侧眼看了看，又转身进入了公会办事处，像是个素不相识的路人。"
  },
  [111560156] = {
    id = 111560156,
    name = "咦，她明明看到我了啊。"
  },
  [111560157] = {
    id = 111560157,
    name = "看她的样子，伤好像还没好。这是去交付委托任务的吗，什么任务啊，要花这么几天才完成？"
  },
  [111560158] = {
    id = 111560158,
    name = "蒙娜心中好奇，跟着罗亚进了公会办事处。"
  },
  [111560159] = {
    id = 111560159,
    name = "......一如既往地人多啊！"
  },
  [111560160] = {
    id = 111560160,
    name = "欸，找到了！"
  },
  [111560161] = {
    id = 111560161,
    name = "罗亚正和公会成员说什么，淡淡地点点头，转身又出了门。"
  },
  [111560162] = {
    id = 111560162,
    name = "蒙娜朝她笑了笑，正要打招呼，竟见她头也不回地走了。"
  },
  [111560163] = {
    id = 111560163,
    name = "什么呀，明明看到我了还装看不见。"
  },
  [111560164] = {
    id = 111560164,
    name = "这个家伙，有点目中无人了吧。"
  },
  [111560165] = {
    id = 111560165,
    name = "蒙娜小姐，你在说罗亚啊？"
  },
  [111560166] = {
    id = 111560166,
    name = "蒙娜意识到自己抱怨得大声了，尴尬地看着他。"
  },
  [111560167] = {
    id = 111560167,
    name = "呵呵，我就是关心一下她身上的伤好了没。"
  },
  [111560168] = {
    id = 111560168,
    name = "唉，她刚来交付任务，马上又接了新的走了。"
  },
  [111560169] = {
    id = 111560169,
    name = "新的任务很难吗？"
  },
  [111560170] = {
    id = 111560170,
    name = "蒙娜看他叹息的样子，有些好奇。"
  },
  [111560171] = {
    id = 111560171,
    name = "不是难不难的问题，你看这些，都是她接下并完成的任务。"
  },
  [111560172] = {
    id = 111560172,
    name = "自从她来这里之后，就没有休息过了。"
  },
  [111560173] = {
    id = 111560173,
    name = "这么拼！她很缺钱啊？"
  },
  [111560174] = {
    id = 111560174,
    name = "不是。我们都劝她休息的时候，她说“不能让自己闲下来”，然后又接了新的任务出发了。"
  },
  [111560175] = {
    id = 111560175,
    name = "笔记上一连多页都是罗亚接的委托，几乎完成了这个圈落的一大半。"
  },
  [111560176] = {
    id = 111560176,
    name = "只是罗亚在委托本上留下的名字让蒙娜很在意。"
  },
  [111560177] = {
    id = 111560177,
    name = "这里为什么写的是守望？"
  },
  [111560178] = {
    id = 111560178,
    name = "哦，守望是她探险队的名字。"
  },
  [111560179] = {
    id = 111560179,
    name = "咦，看她独来独往，竟然是有探险队的人啊。"
  },
  [111560180] = {
    id = 111560180,
    name = "蒙娜若有所思。"
  },
  [111560181] = {
    id = 111560181,
    name = "难道真的是缺钱了？"
  },
  [111560182] = {
    id = 111560182,
    name = "不过，再拼也别把命搭进去嘛，看她刚才的样子，就像很久没睡过了。"
  },
  [111560183] = {
    id = 111560183,
    name = "一开始她完成任务的速度快得让人不敢置信，我们都非常惊讶，这些委托沉积很久了，也正好是她来解决了令我们最头疼的问题。"
  },
  [111560184] = {
    id = 111560184,
    name = "只是没想到，她接的委托从开始到现在就没停下。"
  },
  [111560185] = {
    id = 111560185,
    name = "而且不只是杀魔物，帮忙割麦子，摘果子，找东西，这些完全没有挑战性的委托，她也全接了。"
  },
  [111560186] = {
    id = 111560186,
    name = "这下蒙娜是真的吃了一惊。"
  },
  [111560187] = {
    id = 111560187,
    name = "是个狠人啊！一口也不给别人留。"
  },
  [111560188] = {
    id = 111560188,
    name = "唉，她刚才又接了个战斗任务，不光是你，我们都看到她身上有伤了。"
  },
  [111560189] = {
    id = 111560189,
    name = "但她就是不听劝，没办法呐。"
  },
  [111560190] = {id = 111560190, name = "......"},
  [111560191] = {
    id = 111560191,
    name = "你给我找一个任务吧。"
  },
  [111560192] = {
    id = 111560192,
    name = "公会成员把委托本接过来，蒙娜翻找了一下，在最后一页看到罗亚接取的任务，挑了一个和她同一个方向的。"
  },
  [111560193] = {
    id = 111560193,
    name = "就这个了。"
  },
  [111560194] = {
    id = 111560194,
    name = "好的，在这里签字。"
  },
  [111560195] = {
    id = 111560195,
    name = "公会成员立刻调整状态，露出专业的微笑。"
  },
  [111560196] = {
    id = 111560196,
    name = "祝您顺利完成任务，得胜归来。"
  },
  [111560197] = {
    id = 111560197,
    name = "那家伙看起来身体快到极限了，脚步竟也不慢啊。"
  },
  [111560198] = {
    id = 111560198,
    name = "蒙娜紧赶慢赶，终于在前方看到了罗亚的身影。"
  },
  [111560199] = {
    id = 111560199,
    name = "她正靠坐在一棵大树旁边，闭着眼睛，似乎在休息。"
  },
  [111560200] = {
    id = 111560200,
    name = "罗亚紧紧地抱着剑，即使在睡梦中，她看起来也神色不安，周身绷紧没有彻底放松。"
  },
  [111560201] = {
    id = 111560201,
    name = "睡着了啊。"
  },
  [111560202] = {
    id = 111560202,
    name = "蒙娜靠近了些，惊动了罗亚。"
  },
  [111560203] = {
    id = 111560203,
    name = "她猛睁双目，手紧紧握在剑上，看清来人后，眼里的警惕才消退了几分。"
  },
  [111560204] = {id = 111560204, name = "......"},
  [111560205] = {
    id = 111560205,
    name = "别紧张，我就是路过......你继续睡吧。"
  },
  [111560206] = {
    id = 111560206,
    name = "蒙娜蹑手蹑脚地走了两步，回头一看，罗亚又垂下了眼睛，进入假寐状态。"
  },
  [111560207] = {
    id = 111560207,
    name = "（这里睡着很危险啊......）"
  },
  [111560208] = {
    id = 111560208,
    name = "她思考了半秒，退了几步，就对上了罗亚冷冷的目光。"
  },
  [111560209] = {
    id = 111560209,
    name = "别靠近我。"
  },
  [111560210] = {
    id = 111560210,
    name = "蒙娜停下了脚步，看向她眼里的戒备与疲劳，倒是十分不解。"
  },
  [111560211] = {
    id = 111560211,
    name = "不至于吧，我要是害你还能等到现在？"
  },
  [111560212] = {id = 111560212, name = "......"},
  [111560213] = {
    id = 111560213,
    name = "你看起来很累，不如回圈落好好休息，也比在这荒郊野外好啊。"
  },
  [111560214] = {
    id = 111560214,
    name = "不用了，我还有任务要做。"
  },
  [111560215] = {
    id = 111560215,
    name = "是猎杀裂面凶兽吧，我正好有个任务是猎取附近的魔羽翅膀，我们一起啊，互相也有个照应。"
  },
  [111560216] = {
    id = 111560216,
    name = "你知道我的任务？"
  },
  [111560217] = {
    id = 111560217,
    name = "恰巧看到了嘛，要不要一起搭个伴啊？"
  },
  [111560218] = {id = 111560218, name = "不了。"},
  [111560219] = {
    id = 111560219,
    name = "罗亚起身前行，蒙娜一步步跟在她身后，只走了几步，罗亚就停下来，眼神暗含警告。"
  },
  [111560220] = {
    id = 111560220,
    name = "别跟着我。"
  },
  [111560221] = {
    id = 111560221,
    name = "（哼，你说不跟我偏要跟！）"
  },
  [111560222] = {
    id = 111560222,
    name = "我的任务也在这边啊，这条路又不是你一个人的。"
  },
  [111560223] = {id = 111560223, name = "......"},
  [111560224] = {
    id = 111560224,
    name = "罗亚皱了皱眉，什么也没说，继续深入山林，寻找裂面凶兽的踪影。"
  },
  [111560225] = {
    id = 111560225,
    name = "（她的状态很差啊，那手臂还有渗血的痕迹，那次战斗之后都没有好好处理啊。）"
  },
  [111560226] = {
    id = 111560226,
    name = "（这家伙......我长得很可怕吗，怎么看见我就跑？）"
  },
  [111560227] = {
    id = 111560227,
    name = "蒙娜在罗亚身后走着，哪知罗亚越走越快，崎岖的山路如履平地，蒙娜磕磕绊绊才跟上。"
  },
  [111560228] = {
    id = 111560228,
    name = "直到一个平坦的林子，罗亚才停顿了脚步。"
  },
  [111560229] = {
    id = 111560229,
    name = "......你的耐力也太好了吧。"
  },
  [111560230] = {id = 111560230, name = "躲开。"},
  [111560231] = {id = 111560231, name = "什么？"},
  [111560232] = {id = 111560232, name = "锵！！"},
  [111560233] = {
    id = 111560233,
    name = "蒙娜还在发懵，罗亚已举起了大剑挡住了裂面凶兽的偷袭。"
  },
  [111560234] = {
    id = 111560234,
    name = "罗亚的动作凌厉而果断，她挥剑而上，带着一往无前的气势。"
  },
  [111560235] = {
    id = 111560235,
    name = "然而，蒙娜很快就发现她的状态不对，持剑的手偶尔会出现凝滞，招式也不如之前那般流畅。"
  },
  [111560236] = {
    id = 111560236,
    name = "我来帮你！"
  },
  [111560237] = {
    id = 111560237,
    name = "没有丝毫犹豫，立刻抽出法杖，朝魔物打了一团魔法光球。"
  },
  [111560238] = {id = 111560238, name = "轰！！"},
  [111560239] = {
    id = 111560239,
    name = "魔物被彻底激怒，发出一声震天的咆哮，挥舞着巨大的爪子向两人扑来。"
  },
  [111560240] = {id = 111560240, name = "闪开！"},
  [111560241] = {
    id = 111560241,
    name = "罗亚再次拦截住攻击，蒙娜被推到一边，发现罗亚的动作越来越迟缓，显然是受伤不轻。"
  },
  [111560242] = {
    id = 111560242,
    name = "别抗了，看我的！"
  },
  [111560243] = {
    id = 111560243,
    name = "蒙娜再次朝魔物落了一道魔法，故意吸引魔物的注意力。"
  },
  [111560244] = {
    id = 111560244,
    name = "魔物果然转移了注意，蒙娜灵活地躲避着魔物的攻击，用着迟缓与凝滞魔法，很快就用放风筝的方式将魔物耗得浑身是伤。"
  },
  [111560245] = {
    id = 111560245,
    name = "差不多了！快去快去！"
  },
  [111560246] = {
    id = 111560246,
    name = "蒙娜催促罗亚给它最后一击，罗亚怔了怔，举起剑，以最轻松的方式斩杀了魔物。"
  },
  [111560247] = {
    id = 111560247,
    name = "嘿嘿，两个人合作是不是轻轻松松？"
  },
  [111560248] = {id = 111560248, name = "......"},
  [111560249] = {
    id = 111560249,
    name = "对了，你的伤还没好啊，我这里的药给你吧，我自己研发的，很好用的哦。"
  },
  [111560250] = {
    id = 111560250,
    name = "蒙娜再次拿出了药瓶，罗亚摇摇头。"
  },
  [111560251] = {
    id = 111560251,
    name = "谢谢。不用管我。"
  },
  [111560252] = {
    id = 111560252,
    name = "我还有任务，先走了。"
  },
  [111560253] = {
    id = 111560253,
    name = "喂喂！你要不医治，怎么完成之后的任务？"
  },
  [111560254] = {
    id = 111560254,
    name = "罗亚顿了顿，没回头地走了。"
  },
  [111560255] = {
    id = 111560255,
    name = "（怎么会有这么自虐的人啊......）"
  },
  [111560256] = {
    id = 111560256,
    name = "蒙娜摇摇头，三番五次帮忙都不领情，她也不再纠缠。"
  },
  [111560257] = {
    id = 111560257,
    name = "啊，光顾着她，我的任务还没完成呢！"
  },
  [111560258] = {
    id = 111560258,
    name = "她拍了拍脑袋，走向附近的魔羽聚集处。"
  },
  [111560259] = {
    id = 111560259,
    name = "正好试验一下蒙娜新研究的魔法——疾速割草！"
  },
  [111560260] = {
    id = 111560260,
    name = "我这几个月的下田可不是白白浪费的！"
  },
  [111560261] = {
    id = 111560261,
    name = "怀着发泄的心情，蒙娜杀掉了一堆魔羽，满载而归。"
  },
  [111560262] = {
    id = 111560262,
    name = "呼，这才是做探险者的感觉啊。"
  },
  [111560263] = {
    id = 111560263,
    name = "来了来了。看看数量对不对？"
  },
  [111560264] = {
    id = 111560264,
    name = "蒙娜上交魔羽，公会的成员一边清点一边和她聊天。"
  },
  [111560265] = {
    id = 111560265,
    name = "想不到蒙娜小姐不光在研发改良药剂上有才能，连战斗都这么厉害。"
  },
  [111560266] = {
    id = 111560266,
    name = "呵呵，这种低级魔物没什么难度啦。"
  },
  [111560267] = {
    id = 111560267,
    name = "那不一样，据说这群魔物附近是有一只难以对付的裂面凶兽的。"
  },
  [111560268] = {
    id = 111560268,
    name = "蒙娜小姐能在不被发现的情况下拿到这些魔羽，实力可见一斑！"
  },
  [111560269] = {
    id = 111560269,
    name = "啊，那只凶兽啊，被我和罗亚干掉啦！"
  },
  [111560270] = {
    id = 111560270,
    name = "嗯？是那个罗亚小姐？"
  },
  [111560271] = {id = 111560271, name = "对啊。"},
  [111560272] = {
    id = 111560272,
    name = "原来如此，罗亚小姐的确有击杀裂面凶兽的实力，不过她一向独来独往，很少与人合作的。"
  },
  [111560273] = {
    id = 111560273,
    name = "唔，原来不是讨厌我啊。"
  },
  [111560274] = {
    id = 111560274,
    name = "当然不会，罗亚小姐其实是个面冷心热的人，她只是习惯一个人吧。"
  },
  [111560275] = {
    id = 111560275,
    name = "有一次我的同事配合她出任务，她会负责地保护每一个人都不受伤害，真的是非常令人有安全感。"
  },
  [111560276] = {
    id = 111560276,
    name = "的确是这样......"
  },
  [111560277] = {
    id = 111560277,
    name = "蒙娜想起几次魔物的进攻，罗亚都毫无犹豫地挡在她前面，她明明只是一个表露出友好的陌生人而已。"
  },
  [111560278] = {
    id = 111560278,
    name = "只是我们还是非常担忧这样的情况。"
  },
  [111560279] = {
    id = 111560279,
    name = "嗯？怎么了？"
  },
  [111560280] = {
    id = 111560280,
    name = "这几次罗亚小姐的异常，我们几个同事都看在眼里，调查后才发现，她走了大小几个圈落，几乎从来没有休息。"
  },
  [111560281] = {
    id = 111560281,
    name = "这样下去，她迟早会崩溃的。"
  },
  [111560282] = {
    id = 111560282,
    name = "她是不是有什么心事啊？"
  },
  [111560283] = {
    id = 111560283,
    name = "我们问过她是否需要帮助，但她什么都不肯说。"
  },
  [111560284] = {
    id = 111560284,
    name = "罗亚小姐是非常优秀的探险者，也为公会解决了许多委托和难题。"
  },
  [111560285] = {
    id = 111560285,
    name = "如果她出事了，那对公会、圈落，以及整个深渊而言，都是非常可惜的事。"
  },
  [111560286] = {
    id = 111560286,
    name = "是啊，我看她都受伤了，也不愿意停下任务，听起来你们也很苦恼诶。"
  },
  [111560287] = {
    id = 111560287,
    name = "所以，我们想请蒙娜小姐帮个忙。"
  },
  [111560288] = {
    id = 111560288,
    name = "啊？我能帮什么忙？"
  },
  [111560289] = {
    id = 111560289,
    name = "目前罗亚小姐接取的任务有三个，以她的速度，大概两天后就能交付了。"
  },
  [111560290] = {
    id = 111560290,
    name = "在这之后，她一定还会再接任务。"
  },
  [111560291] = {
    id = 111560291,
    name = "嗯嗯，然后呢？"
  },
  [111560292] = {
    id = 111560292,
    name = "这时，我们会给她一个轻松简单的任务，但需要人配合才能做到。"
  },
  [111560293] = {
    id = 111560293,
    name = "如果蒙娜小姐愿意仗义出手，那这件事就好办了。"
  },
  [111560294] = {
    id = 111560294,
    name = "也就是说，你们会给她一个双人任务，然后搭档是我？"
  },
  [111560295] = {id = 111560295, name = "是的。"},
  [111560296] = {
    id = 111560296,
    name = "什么任务啊？"
  },
  [111560297] = {
    id = 111560297,
    name = "圈落东北部的村庄之前收麦子，留下了一些小麻烦，我们大概看了看，都是些很琐碎的事。"
  },
  [111560298] = {
    id = 111560298,
    name = "那些事一个人做不过来，有些实力的探险队也不愿意接这种报酬低的委托，就一直搁置到了现在。"
  },
  [111560299] = {
    id = 111560299,
    name = "要是蒙娜小姐同意，那我们就把这个委托交给罗亚小姐，先让罗亚小姐来找你。"
  },
  [111560300] = {
    id = 111560300,
    name = "我没问题！"
  },
  [111560301] = {
    id = 111560301,
    name = "蒙娜叉腰自信地拍拍胸脯，保证完成任务。"
  },
  [111560302] = {
    id = 111560302,
    name = "蒙娜小姐可以放心，本次委托不需要战斗，只为了让罗亚小姐能轻松地休息一下。"
  },
  [111560303] = {
    id = 111560303,
    name = "嗯，我会尽量劝劝她的。"
  },
  [111560304] = {
    id = 111560304,
    name = "好的，那蒙娜小姐确认没有问题，就请在这里签字吧。"
  },
  [111560305] = {
    id = 111560305,
    name = "蒙娜快速浏览了一遍委托，果然只是一些收割整理，晾晒和寻物的杂事，快速签了字。"
  },
  [111560306] = {
    id = 111560306,
    name = "那接下来，我要在这里等她吗？"
  },
  [111560307] = {
    id = 111560307,
    name = "哦，这倒不用，等罗亚小姐回来，我们会让她来找您的。"
  },
  [111560308] = {
    id = 111560308,
    name = "好啊，那我就回去等她来找我！"
  },
  [111560309] = {
    id = 111560309,
    name = "蒙娜心情愉悦，美滋滋地出门了。"
  },
  [111560310] = {
    id = 111560310,
    name = "第二天。"
  },
  [111560311] = {
    id = 111560311,
    name = "不知道罗亚任务完成得怎么样。"
  },
  [111560312] = {
    id = 111560312,
    name = "她来找我，我应该怎么表现呢？"
  },
  [111560313] = {
    id = 111560313,
    name = "蒙娜整理了一下表情，严肃地咳嗽了两声。"
  },
  [111560314] = {
    id = 111560314,
    name = "（严肃）咳，我是蒙娜，你这次任务的搭档，请多指教。"
  },
  [111560315] = {
    id = 111560315,
    name = "不对，又不是初次见面，没必要这么正式。"
  },
  [111560316] = {
    id = 111560316,
    name = "（微笑）又见面啦，我叫蒙娜，这次我们一起接受委托，希望接下来合作愉快！"
  },
  [111560317] = {
    id = 111560317,
    name = "不对不对，这不是谈生意。"
  },
  [111560318] = {
    id = 111560318,
    name = "罗亚话太少，说不定找到我只会给我一个眼神。"
  },
  [111560319] = {
    id = 111560319,
    name = "蒙娜学着罗亚的样子抄起了手臂。"
  },
  [111560320] = {
    id = 111560320,
    name = "（冷漠）你，跟我走。"
  },
  [111560321] = {
    id = 111560321,
    name = "没错，应该就是这样。"
  },
  [111560322] = {
    id = 111560322,
    name = "蒙娜击了一下手掌心，思考应该如何回应。"
  },
  [111560323] = {
    id = 111560323,
    name = "哼，让我走我就走吗？之前对我爱答不理，我也要做做样子，告诉她我也是有脾气的！"
  },
  [111560324] = {
    id = 111560324,
    name = "啊，要是她真的不理我走了怎么办。"
  },
  [111560325] = {
    id = 111560325,
    name = "唔......算了算了。"
  },
  [111560326] = {
    id = 111560326,
    name = "难得有轻松的任务，就不为难她了。"
  },
  [111560327] = {
    id = 111560327,
    name = "蒙娜点了点头。"
  },
  [111560328] = {
    id = 111560328,
    name = "就这么决定了。"
  },
  [111560329] = {id = 111560329, name = "......"},
  [111560330] = {
    id = 111560330,
    name = "第三天。"
  },
  [111560331] = {
    id = 111560331,
    name = "这次罗亚的任务很难吗，怎么还没来找我？"
  },
  [111560332] = {id = 111560332, name = "......"},
  [111560333] = {id = 111560333, name = "......"},
  [111560334] = {
    id = 111560334,
    name = "再等等吧，作为一个合格的搭档，要相信队友才行。"
  },
  [111560335] = {
    id = 111560335,
    name = "第三天傍晚。"
  },
  [111560336] = {
    id = 111560336,
    name = "不能再等了，万一她有危险，我这么耽搁岂不是害了一条人命！"
  },
  [111560337] = {
    id = 111560337,
    name = "先去公会办事处问问看吧！"
  },
  [111560338] = {
    id = 111560338,
    name = "蒙娜心急火燎地来到了公会办事处，临近夜幕，屋子里已经没有什么人。"
  },
  [111560339] = {
    id = 111560339,
    name = "公会的成员们正在收拾总结一日的工作，结算每日的委托资金与酬劳。"
  },
  [111560340] = {
    id = 111560340,
    name = "蒙娜小姐？！"
  },
  [111560341] = {
    id = 111560341,
    name = "蒙娜两三步滑到委托处，撑着桌子，神色十分凝重。"
  },
  [111560342] = {
    id = 111560342,
    name = "我问你，罗亚上次接的任务是什么？"
  },
  [111560343] = {
    id = 111560343,
    name = "嗯？蒙娜小姐问这个做什么？"
  },
  [111560344] = {
    id = 111560344,
    name = "我怀疑她出事了！"
  },
  [111560345] = {
    id = 111560345,
    name = "什么？！！"
  },
  [111560346] = {
    id = 111560346,
    name = "已经过了两天了，她还没来找我。"
  },
  [111560347] = {
    id = 111560347,
    name = "你不是说，那些任务她两天内就能完成吗？可我现在还没见着人。"
  },
  [111560348] = {
    id = 111560348,
    name = "罗亚小姐没去找你吗？可她已经在我这里接了那个村庄的任务了。"
  },
  [111560349] = {
    id = 111560349,
    name = "蒙娜顿时傻了眼。"
  },
  [111560350] = {
    id = 111560350,
    name = "你说什么？"
  },
  [111560351] = {
    id = 111560351,
    name = "今天早上，罗亚小姐就已经来交付委托了，我也将之前说好的村庄委托交给了她。"
  },
  [111560352] = {
    id = 111560352,
    name = "还特意叮嘱她，这个任务只能两人合作完成，让她去您的住处找你啊。"
  },
  [111560353] = {
    id = 111560353,
    name = "......她，她没来啊！"
  },
  [111560354] = {
    id = 111560354,
    name = "那，这......"
  },
  [111560355] = {
    id = 111560355,
    name = "公会成员从没遇到过这种情况，一时也无所适从。"
  },
  [111560356] = {
    id = 111560356,
    name = "哼，我立刻去找她！"
  },
  [111560357] = {
    id = 111560357,
    name = "竟敢无视合作伙伴，无视蒙娜！想一个人偷偷把任务完成，没门！"
  },
  [111560358] = {
    id = 111560358,
    name = "蒙娜噔噔蹬跑了出去，身后传来公会成员呼喊的声音。"
  },
  [111560359] = {
    id = 111560359,
    name = "祝您和罗亚小姐顺利完成任务，得胜归来！"
  },
  [111480001] = {
    id = 111480001,
    name = "......别磨磨蹭蹭了，要不要......"
  },
  [111480002] = {
    id = 111480002,
    name = "这附近......都是些没啥油水......"
  },
  [111480003] = {
    id = 111480003,
    name = "好不容易......符合......目标，上吧......"
  },
  [111480004] = {
    id = 111480004,
    name = "（前面有两个人。）"
  },
  [111480005] = {
    id = 111480005,
    name = "你朝前走了些，模糊的声音变得更清晰明朗了。"
  },
  [111480006] = {
    id = 111480006,
    name = "我说，毕竟是个女人啊。"
  },
  [111480007] = {
    id = 111480007,
    name = "女人才好啊，待会儿你从正面吸引他的注意力，我从后面......"
  },
  [111480008] = {
    id = 111480008,
    name = "为什么要我去？"
  },
  [111480009] = {
    id = 111480009,
    name = "你要是不去......不得弄死你......"
  },
  [111480010] = {
    id = 111480010,
    name = "（这两个人，竟然打算打劫吗？）"
  },
  [111480011] = {
    id = 111480011,
    name = "远处河边上，有一抹蓝色的身影施然漫步，丝毫没注意身后跟着两个劫匪。"
  },
  [111480012] = {
    id = 111480012,
    name = "我说，既然是女人的话，还是算了吧。"
  },
  [111480013] = {
    id = 111480013,
    name = "哼，一看就是个走失的千金大小姐，她身上一定有不少好东西。就算......也能搜刮......"
  },
  [111480014] = {
    id = 111480014,
    name = "劫匪的声音变得小声了，你靠近了些，你故意踩下了一截树枝，咔嚓——"
  },
  [111480015] = {
    id = 111480015,
    name = "谁？！谁在那边！"
  },
  [111480016] = {
    id = 111480016,
    name = "打扰了，我路过。"
  },
  [111480017] = {
    id = 111480017,
    name = "你朝两人笑了笑，远处那个蓝色的身影只留下一个小点。"
  },
  [111480018] = {
    id = 111480018,
    name = "你刚才听到什么了？"
  },
  [111480019] = {
    id = 111480019,
    name = "关于你们要打劫前面那位女士的事，我什么都没听到。"
  },
  [111480020] = {
    id = 111480020,
    name = "哦，没听到啊。"
  },
  [111480021] = {
    id = 111480021,
    name = "蠢货，他没听到怎么知道我们要打劫？"
  },
  [111480022] = {
    id = 111480022,
    name = "那、那就是听到了！兄弟，怎么办？"
  },
  [111480023] = {
    id = 111480023,
    name = "哼，都是你，磨磨蹭蹭的！那女人已经走了！"
  },
  [111480024] = {
    id = 111480024,
    name = "走了啊......那目标......"
  },
  [111480025] = {
    id = 111480025,
    name = "目标只有换一个了。"
  },
  [111480026] = {
    id = 111480026,
    name = "两人豁然看向了你。"
  },
  [111480027] = {
    id = 111480027,
    name = "我，我觉得可以。"
  },
  [111480028] = {
    id = 111480028,
    name = "谁让你这么倒霉呢。"
  },
  [111480029] = {
    id = 111480029,
    name = "你们的意思是，要打劫我？"
  },
  [111480030] = {
    id = 111480030,
    name = "知道就乖乖把好东西交出来，也免得挨打受苦。"
  },
  [111480031] = {
    id = 111480031,
    name = "哦......这样啊。"
  },
  [111480032] = {
    id = 111480032,
    name = "一段时间后......"
  },
  [111480033] = {
    id = 111480033,
    name = "哎哟......饶命......"
  },
  [111480034] = {
    id = 111480034,
    name = "别打了，别打了！"
  },
  [111480035] = {
    id = 111480035,
    name = "还想打劫我吗？"
  },
  [111480036] = {
    id = 111480036,
    name = "兄弟......还打劫吗......"
  },
  [111480037] = {
    id = 111480037,
    name = "打劫个屁，不打劫了！"
  },
  [111480038] = {
    id = 111480038,
    name = "呵呵，看你们的样子，是第一次打劫吧？"
  },
  [111480039] = {
    id = 111480039,
    name = "对，对，我们知道错了，饶了我们吧！以后都不打劫了！"
  },
  [111480040] = {
    id = 111480040,
    name = "那就滚吧。"
  },
  [111480041] = {
    id = 111480041,
    name = "两人歪裂着嘴，慢腾腾爬了起来。"
  },
  [111480042] = {
    id = 111480042,
    name = "等等，从这边滚。"
  },
  [111480043] = {id = 111480043, name = "是是。"},
  [111480044] = {
    id = 111480044,
    name = "两个劫匪调转了方向，朝你身后跑了。"
  },
  [111480045] = {
    id = 111480045,
    name = "前方河畔，那抹蓝影早已消失在地平线上。"
  },
  [111480046] = {
    id = 111480046,
    name = "穿过河畔，你又见到了那个蓝色的背影，她停下来了，从你的角度看去，有两个人恰好拦下了她。"
  },
  [111480047] = {
    id = 111480047,
    name = "真......巧啊。"
  },
  [111480048] = {
    id = 111480048,
    name = "你走了上去，朝那两个劫匪招了招手。"
  },
  [111480049] = {
    id = 111480049,
    name = "兄弟，又，又是他！"
  },
  [111480050] = {
    id = 111480050,
    name = "怕、怕什么！我们光明正大......"
  },
  [111480051] = {
    id = 111480051,
    name = "两人后退了好几步，这时蓝色的背影转过了身，那是一双比湖泊还令人沉静的眼睛。"
  },
  [111480052] = {
    id = 111480052,
    name = "少女看向你，湖泊微微波动，泛起一丝涟漪。"
  },
  [111480053] = {
    id = 111480053,
    name = "小、小姐，救命啊！"
  },
  [111480054] = {
    id = 111480054,
    name = "对，他刚才打我们......"
  },
  [111480055] = {
    id = 111480055,
    name = "这位小姐，你应该离这两个抢劫犯远一点。"
  },
  [111480056] = {
    id = 111480056,
    name = "抢劫......犯？"
  },
  [111480057] = {
    id = 111480057,
    name = "我，我们没有抢劫！"
  },
  [111480058] = {
    id = 111480058,
    name = "小姐，救救我们啊！"
  },
  [111480059] = {
    id = 111480059,
    name = "两人一下窜到了少女身后，恐惧地看着你，就好像你才是那个罪大恶极的坏蛋。"
  },
  [111480060] = {id = 111480060, name = "......"},
  [111480061] = {
    id = 111480061,
    name = "小姐，帮帮我们，你看我们脸上的伤，都是他刚才打的。"
  },
  [111480062] = {
    id = 111480062,
    name = "......刚还来打劫我，这会儿就别装可怜了。"
  },
  [111480063] = {id = 111480063, name = "嗯？"},
  [111480064] = {
    id = 111480064,
    name = "不，都是误会，误会啊！"
  },
  [111480065] = {
    id = 111480065,
    name = "你把来龙去脉告诉了少女。"
  },
  [111480066] = {
    id = 111480066,
    name = "总之，这种不安好心的人，你还是离远一点吧。"
  },
  [111480067] = {
    id = 111480067,
    name = "少女朝你微微一笑。"
  },
  [111480068] = {
    id = 111480068,
    name = "我知道了，谢谢你的提醒。"
  },
  [111480069] = {
    id = 111480069,
    name = "小姐，我说的是真的......"
  },
  [111480070] = {
    id = 111480070,
    name = "嗯，我也相信你们。这位先生，他们这么做是有不得已的苦衷，我很理解你们救人心切，但以后请不要打劫其他人了。"
  },
  [111480071] = {
    id = 111480071,
    name = "是，是是......"
  },
  [111480072] = {
    id = 111480072,
    name = "我正好有些药物，也许你们能用得着，希望你们的同伴早日痊愈。"
  },
  [111480073] = {
    id = 111480073,
    name = "两个人感恩戴德地接过少女的药。"
  },
  [111480074] = {
    id = 111480074,
    name = "你们还要欧泊吗？"
  },
  [111480075] = {id = 111480075, name = "......"},
  [111480076] = {
    id = 111480076,
    name = "嘿嘿......好——"
  },
  [111480077] = {
    id = 111480077,
    name = "好心的小姐，我们不需要了，不需要了！走，快走。"
  },
  [111480078] = {
    id = 111480078,
    name = "劫匪时不时地看向你，推着人跑远了。"
  },
  [111480079] = {
    id = 111480079,
    name = "啊啦，走得这么着急，忘记问他们的同伴在哪里了。"
  },
  [111480080] = {
    id = 111480080,
    name = "你真的信他们那套说辞？"
  },
  [111480081] = {
    id = 111480081,
    name = "我见过很多打劫者。他们如果真的想打劫，不会说出「有同伴得了传染病」这样的话。"
  },
  [111480082] = {
    id = 111480082,
    name = "传染病？"
  },
  [111480083] = {
    id = 111480083,
    name = "是的，他们的同伴得了一种病。"
  },
  [111480084] = {
    id = 111480084,
    name = "他们说那种病有很强的传染性，只要通过皮肤接触就会患病，一旦发病，会无法控制自己的行为。比如伤害别人，甚至伤害自己。"
  },
  [111480085] = {
    id = 111480085,
    name = "听起来很像......（堕落者？）"
  },
  [111480086] = {
    id = 111480086,
    name = "虽然你的话没说完，但少女仿佛明白你的意思，朝你点点头。"
  },
  [111480087] = {
    id = 111480087,
    name = "是的，很奇怪的传染病，但不太像堕落者。平日里我自己也会研究一些奇怪的病症，这个......病，挺让人担忧的。"
  },
  [111480088] = {
    id = 111480088,
    name = "啊，不好意思。说了这么久，都忘记自我介绍了，我叫舒芙蕾，来自自由学派。"
  },
  [111480089] = {
    id = 111480089,
    name = "互通姓名后，她朝你微微施了一个礼节。"
  },
  [111480090] = {
    id = 111480090,
    name = "自由学派？"
  },
  [111480091] = {
    id = 111480091,
    name = "只是一个不知名的学术交流组织而已，关于那个传染病的事，你有什么线索吗？"
  },
  [111480092] = {
    id = 111480092,
    name = "我也是第一次听说。"
  },
  [111480093] = {
    id = 111480093,
    name = "这样吗，有点可惜呢，我还打算去看看那个病人，看看能不能提供一些帮助。"
  },
  [111480094] = {
    id = 111480094,
    name = "他们既然在这附近打劫，所谓的同伴也不会离得太远。沿着河边下去有一座据点，也许会在那里吧。"
  },
  [111480095] = {
    id = 111480095,
    name = "我对这里的路不太熟，谢谢告知。"
  },
  [111480096] = {
    id = 111480096,
    name = "......（放任她一个人，被骗走钱财都是小事。如果遇到不怀好意的人......）"
  },
  [111480097] = {
    id = 111480097,
    name = "我和你一起去吧。"
  },
  [111480098] = {
    id = 111480098,
    name = "你也对传染病有所涉猎？"
  },
  [111480099] = {
    id = 111480099,
    name = "唔，只是顺路而已。"
  },
  [111480100] = {
    id = 111480100,
    name = "呵呵，谢谢你。那这一路，就请多多关照了。"
  },
  [111480101] = {
    id = 111480101,
    name = "这个据点好热闹。"
  },
  [111480102] = {
    id = 111480102,
    name = "前方传来了吵闹声。"
  },
  [111480103] = {
    id = 111480103,
    name = "他往那边跑了！快追！！你们怎么不拦住他啊！"
  },
  [111480104] = {
    id = 111480104,
    name = "人群一拥而上，又像在躲避什么四散开了。"
  },
  [111480105] = {
    id = 111480105,
    name = "发生了什么事？"
  },
  [111480106] = {
    id = 111480106,
    name = "糟了，快去找默尔克领队，只有他——"
  },
  [111480107] = {
    id = 111480107,
    name = "——轰！！有什么东西倒塌了。"
  },
  [111480108] = {
    id = 111480108,
    name = "啊！我的摊子......别踩，别踩！"
  },
  [111480109] = {
    id = 111480109,
    name = "喧哗声越来越近，有两个人似乎扭打在了一起。"
  },
  [111480110] = {
    id = 111480110,
    name = "快来！别只看着，来帮帮我！"
  },
  [111480111] = {
    id = 111480111,
    name = "不敢、不敢啊！被传染了怎么办？"
  },
  [111480112] = {id = 111480112, name = "传染？"},
  [111480113] = {
    id = 111480113,
    name = "呃啊......"
  },
  [111480114] = {
    id = 111480114,
    name = "探险者被一脚踹开了，踹开他的人头发散乱，双眼泛红抖了抖。"
  },
  [111480115] = {
    id = 111480115,
    name = "啊啊，别过来啊！他开始暴走了！！"
  },
  [111480116] = {
    id = 111480116,
    name = "周围的人又害怕般得退了两步。"
  },
  [111480117] = {
    id = 111480117,
    name = "那个人，好像不对劲。"
  },
  [111480118] = {
    id = 111480118,
    name = "人群分开后，露出了中间发狂的人，他精神错乱般地甩了甩头，猛地看向了舒芙蕾！"
  },
  [111480119] = {
    id = 111480119,
    name = "他身上......"
  },
  [111480120] = {
    id = 111480120,
    name = "那位小姐，快闪开！！"
  },
  [111480121] = {
    id = 111480121,
    name = "——砰！！扑上来的家伙被你一脚踢翻。"
  },
  [111480122] = {
    id = 111480122,
    name = "没事吧？"
  },
  [111480123] = {
    id = 111480123,
    name = "没事，刚才我看到——"
  },
  [111480124] = {
    id = 111480124,
    name = "啊啊啊！！去死......通通去死......"
  },
  [111480125] = {
    id = 111480125,
    name = "他又要发狂了，快制住他！！"
  },
  [111480126] = {
    id = 111480126,
    name = "快跑，快跑！"
  },
  [111480127] = {
    id = 111480127,
    name = "看着发狂的人摇摇晃晃爬了起来，人潮哗地退去了，很快街道上只剩下了零散的几个人。"
  },
  [111480128] = {id = 111480128, name = "......"},
  [111480129] = {
    id = 111480129,
    name = "啊啊啊啊......"
  },
  [111480130] = {
    id = 111480130,
    name = "暴走的人忽然抱住自己的头，用力往旁边房屋的墙上猛砸，砰！砰！砰！"
  },
  [111480131] = {
    id = 111480131,
    name = "这样他会受伤的，我们快阻止他！"
  },
  [111480132] = {
    id = 111480132,
    name = "你与舒芙蕾上前，两三下打晕了自虐的探险者。"
  },
  [111480133] = {
    id = 111480133,
    name = "暂时安定下来了。"
  },
  [111480134] = {
    id = 111480134,
    name = "让我看看他。"
  },
  [111480135] = {
    id = 111480135,
    name = "这位小姐，请不要触碰他！他患了病，会传染给你的。"
  },
  [111480136] = {
    id = 111480136,
    name = "没关系，我研究过一些怪病，也制作过一些药物。"
  },
  [111480137] = {
    id = 111480137,
    name = "哦，这样啊，那你要小心一点啊，他随时可能暴走伤人的。"
  },
  [111480138] = {
    id = 111480138,
    name = "舒芙蕾缓缓蹲下，带着薄纱的手拨开了遮蔽的脏发，发狂的人此时已经昏迷了，整个脸色泛着青色，时不时脸颊的肌肉还在无意识地抖动。"
  },
  [111480139] = {
    id = 111480139,
    name = "怎么样？"
  },
  [111480140] = {
    id = 111480140,
    name = "暂时看不出什么。他的脸色不似常人，也许是中了什么毒。"
  },
  [111480141] = {
    id = 111480141,
    name = "中毒啊，难道毒性会传染？"
  },
  [111480142] = {
    id = 111480142,
    name = "舒芙蕾摇摇头，看向了你。"
  },
  [111480143] = {
    id = 111480143,
    name = "你有看出什么吗？"
  },
  [111480144] = {
    id = 111480144,
    name = "没有，不过我想起了好像在哪儿见过......"
  },
  [111480145] = {
    id = 111480145,
    name = "（谁？）"
  },
  [111480146] = {
    id = 111480146,
    name = "你忽然感觉被其他人注视着，如芒刺背，猛地抬头，街尾一个全身黑衣的人一掠而过。"
  },
  [111480147] = {
    id = 111480147,
    name = "怎么了？"
  },
  [111480148] = {
    id = 111480148,
    name = "没什么，他们人都走光了，这个人怎么办？"
  },
  [111480149] = {
    id = 111480149,
    name = "交给我们吧！你们几个快出来，别躲起来了！"
  },
  [111480150] = {id = 111480150, name = "......"},
  [111480151] = {
    id = 111480151,
    name = "几个人七手八脚地把人抬走了。"
  },
  [111480152] = {
    id = 111480152,
    name = "请问......"
  },
  [111480153] = {
    id = 111480153,
    name = "舒芙蕾叫住了一名面色冷淡的探险者。"
  },
  [111480154] = {
    id = 111480154,
    name = "你们说的传染病，到底是怎么回事？"
  },
  [111480155] = {
    id = 111480155,
    name = "......你认识那个病人？"
  },
  [111480156] = {
    id = 111480156,
    name = "不认识。"
  },
  [111480157] = {
    id = 111480157,
    name = "那就别管，太好奇的话......"
  },
  [111480158] = {
    id = 111480158,
    name = "他没有把话说完，径直离开了。"
  },
  [111480159] = {
    id = 111480159,
    name = "看来他们不太想讨论这件事。"
  },
  [111480160] = {
    id = 111480160,
    name = "传染病的话......会是这样吗？"
  },
  [111480161] = {
    id = 111480161,
    name = "......他们说是就是吧。"
  },
  [111480162] = {
    id = 111480162,
    name = "我见过很多发病的人，这种症状是传染病的可能性微乎其微。不过，还没见到那两个人，竟然就先看到了病人。"
  },
  [111480163] = {
    id = 111480163,
    name = "那两个劫匪？"
  },
  [111480164] = {
    id = 111480164,
    name = "嗯，现在大家都走了，想得到更多情报的话......"
  },
  [111480165] = {
    id = 111480165,
    name = "就先吃点东西。"
  },
  [111480166] = {id = 111480166, name = "什么？"},
  [111480167] = {
    id = 111480167,
    name = "闹这么大的事他们也没出现，我们先去吃点东西吧。"
  },
  [111480168] = {
    id = 111480168,
    name = "......嗯。"
  },
  [111480169] = {
    id = 111480169,
    name = "舒芙蕾慢条斯理地拿出了精致的口袋。你伸手捂了上去。"
  },
  [111480170] = {
    id = 111480170,
    name = "到了据点怎么还吃干粮？走，去酒馆。"
  },
  [111480171] = {
    id = 111480171,
    name = "......酒......欸？"
  },
  [111480172] = {
    id = 111480172,
    name = "你带舒芙蕾进入了酒馆。"
  },
  [111480173] = {
    id = 111480173,
    name = "这里是......"
  },
  [111480174] = {
    id = 111480174,
    name = "酒馆人声嘈杂，突然安静了下来。"
  },
  [111480175] = {
    id = 111480175,
    name = "喝酒的，玩牌的，正在交易的......都同时看向了你们，准确地说是看向了你身后的少女，你侧身挡了挡，遮住了他们的目光。"
  },
  [111480176] = {
    id = 111480176,
    name = "酒保！找个安静点的位置，我家大小姐饿了。"
  },
  [111480177] = {
    id = 111480177,
    name = "是，请跟我来。"
  },
  [111480178] = {
    id = 111480178,
    name = "你看了那群人一眼，他们又转过身去，继续刚才的事。"
  },
  [111480179] = {
    id = 111480179,
    name = "这里安静，大小姐请坐。"
  },
  [111480180] = {
    id = 111480180,
    name = "酒保前方带路，舒芙蕾一路好奇地看着，等你们坐下后，酒馆重新恢复了喧嚣。"
  },
  [111480181] = {
    id = 111480181,
    name = "原来酒馆里面是这样的。"
  },
  [111480182] = {
    id = 111480182,
    name = "大小姐第一次来吧，想吃点什么？"
  },
  [111480183] = {
    id = 111480183,
    name = "什么都可以吗？"
  },
  [111480184] = {
    id = 111480184,
    name = "当然，这圈落附近的餐馆，没有比本店更丰富了。"
  },
  [111480185] = {
    id = 111480185,
    name = "唔，那我要法米利亚黑菌、比斯卡芦笋、姆纳茨烩鸡......酒的话，不需要。甜点......明沙雪葩就可以了。"
  },
  [111480186] = {
    id = 111480186,
    name = "........................"
  },
  [111480187] = {
    id = 111480187,
    name = "大小姐，您说的这些，我听都没听过......"
  },
  [111480188] = {
    id = 111480188,
    name = "酒保尴尬地看着舒芙蕾，你在两人身上感到了窘迫的氛围。"
  },
  [111480189] = {
    id = 111480189,
    name = "我来吧。"
  },
  [111480190] = {
    id = 111480190,
    name = "抱歉，我是给你添麻烦了吗？"
  },
  [111480191] = {
    id = 111480191,
    name = "没关系，我猜你一定没吃过炸虫饼。"
  },
  [111480192] = {
    id = 111480192,
    name = "？？？ 炸......"
  },
  [111480193] = {
    id = 111480193,
    name = "你朝她笑了笑，向酒保要了几个深渊流行的美食，一顿下来，舒芙蕾吃得优雅节制，赏心悦目。"
  },
  [111480194] = {
    id = 111480194,
    name = "谢谢你的招待。"
  },
  [111480195] = {
    id = 111480195,
    name = "味道如何，还吃得惯吗？"
  },
  [111480196] = {
    id = 111480196,
    name = "还好。我的同伴，自由学派的成员带我吃过，一开始，是她们带我接触深渊，直到我熟练后，她们让我一个人历练。"
  },
  [111480197] = {
    id = 111480197,
    name = "她缓慢地说起自己的事，湖水蓝的眼里洋溢着笑意。"
  },
  [111480198] = {
    id = 111480198,
    name = "说起来，这里这么多人，是个打听消息的好地方。"
  },
  [111480199] = {
    id = 111480199,
    name = "还记得我们刚进来的时候吗，有些事，有人也许不想让我们知道。"
  },
  [111480200] = {
    id = 111480200,
    name = "嗯，但我知道为什么你带我来这里了，不需要问，就能听到很多消息。"
  },
  [111480201] = {
    id = 111480201,
    name = "呵呵，那是他们说话太大声了。"
  },
  [111480202] = {
    id = 111480202,
    name = "总之，谢谢你了。今天太晚了，我打算明天再去找找那两个人，我有一种直觉，找到他们，就能知道一些重要的事。"
  },
  [111480203] = {
    id = 111480203,
    name = "（就这样丢下缺乏常识的贵族小姐不管的话......）"
  },
  [111480204] = {
    id = 111480204,
    name = "那就先休息吧，明天见。"
  },
  [111480205] = {
    id = 111480205,
    name = "你也要和我一起调查吗？"
  },
  [111480206] = {
    id = 111480206,
    name = "我对这样的病症也很感兴趣。"
  },
  [111480207] = {
    id = 111480207,
    name = "太好了。有你的助力，相信一切都会更加顺利。"
  },
  [111480208] = {
    id = 111480208,
    name = "（还真是容易相信别人啊......）"
  },
  [111480209] = {
    id = 111480209,
    name = "当晚，你正浅眠时，外面发出了声响。"
  },
  [111480210] = {
    id = 111480210,
    name = "（......难道又有暴走的人？）"
  },
  [111480211] = {
    id = 111480211,
    name = "你离开了房间。"
  },
  [111480212] = {
    id = 111480212,
    name = "（......是舒芙蕾？她离开据点做什么？）"
  },
  [111480213] = {
    id = 111480213,
    name = "你跟在舒芙蕾身后，一直没有打扰她，因为她也正跟着另一个人。"
  },
  [111480214] = {
    id = 111480214,
    name = "那个人一身探险者的装束，有目的地走着，直到一个谷口，他才停了下来。"
  },
  [111480215] = {
    id = 111480215,
    name = "......沙沙。你故意发出了微弱的，只能让舒芙蕾听到的声音。"
  },
  [111480216] = {
    id = 111480216,
    name = "......！！！"
  },
  [111480217] = {
    id = 111480217,
    name = "（小声）嘘......"
  },
  [111480218] = {
    id = 111480218,
    name = "舒芙蕾会意地笑了笑，你无声地靠近。"
  },
  [111480219] = {
    id = 111480219,
    name = "（小声）那个人有什么问题？"
  },
  [111480220] = {
    id = 111480220,
    name = "（小声）听到了一些断断续续的词，就想跟过来看看......"
  },
  [111480221] = {
    id = 111480221,
    name = "（小声）这个地方竟然有人把守。"
  },
  [111480222] = {
    id = 111480222,
    name = "默尔克领队，你来啦！"
  },
  [111480223] = {
    id = 111480223,
    name = "名叫默尔克的人神情凝重地看向山谷。"
  },
  [111480224] = {
    id = 111480224,
    name = "他们还没出来？"
  },
  [111480225] = {
    id = 111480225,
    name = "算算时间，现在也该出来了......啊，来了来了！"
  },
  [111480226] = {
    id = 111480226,
    name = "夜晚的山谷雾影弥漫，几人影影绰绰。"
  },
  [111480227] = {
    id = 111480227,
    name = "是默尔克领队欸！"
  },
  [111480228] = {
    id = 111480228,
    name = "你们回来了。"
  },
  [111480229] = {
    id = 111480229,
    name = "对，我们这次发现了一个关键的地方！"
  },
  [111480230] = {
    id = 111480230,
    name = "安静点，太吵了。"
  },
  [111480231] = {
    id = 111480231,
    name = "几人的声音突然变小了，什么也听不清。"
  },
  [111480232] = {
    id = 111480232,
    name = "（小声）要过去吗？"
  },
  [111480233] = {id = 111480233, name = "......"},
  [111480234] = {
    id = 111480234,
    name = "（小声）唔，偷听是不太好，那就等他说完我们再过去吧。"
  },
  [111480235] = {
    id = 111480235,
    name = "舒芙蕾朝你点了点头。"
  },
  [111480236] = {
    id = 111480236,
    name = "那边的两位。"
  },
  [111480237] = {id = 111480237, name = "！！！"},
  [111480238] = {
    id = 111480238,
    name = "那名领队突然朝你们招了招手。"
  },
  [111480239] = {
    id = 111480239,
    name = "他应该早就发现我们了。"
  },
  [111480240] = {
    id = 111480240,
    name = "领队和身边的探险者说了几句话，向你们走了过来。"
  },
  [111480241] = {
    id = 111480241,
    name = "这位是......舒芙蕾小姐？！"
  },
  [111480242] = {
    id = 111480242,
    name = "你......认识我？"
  },
  [111480243] = {
    id = 111480243,
    name = "是的！当初你在普利据点帮助他人的善举，令我非常钦佩！"
  },
  [111480244] = {
    id = 111480244,
    name = "啊，那些都是微不足道的小事。"
  },
  [111480245] = {
    id = 111480245,
    name = "不，请不要谦虚。对于那些被帮助的人来说，你拯救了他们的生命。对了，我叫默尔克，是一枚银币探险队的队长。"
  },
  [111480246] = {
    id = 111480246,
    name = "（一枚银币？）"
  },
  [111480247] = {
    id = 111480247,
    name = "舒芙蕾小姐既然能跟着我来，一定是很关心「传染病」的事吧。"
  },
  [111480248] = {
    id = 111480248,
    name = "嗯，默尔克先生调查到了什么吗？"
  },
  [111480249] = {
    id = 111480249,
    name = "没错，所谓传染病的源头，就在这个炎日山谷里。只要进入过这个山谷探险的人，在之后，都多多少少出现了一些症状，变得暴躁不安，身体会有块状的青色......"
  },
  [111480250] = {
    id = 111480250,
    name = "大家之所以称它为传染病，是因为那些人都不是同一时间发病，他们连续的，不同程度地出现了症状，具体原因我们还在调查，也许是他们带出了山谷里的东西导致的。"
  },
  [111480251] = {
    id = 111480251,
    name = "山谷里的东西？"
  },
  [111480252] = {
    id = 111480252,
    name = "没错，这也是刚才他们发现的情况。"
  },
  [111480253] = {
    id = 111480253,
    name = "炎日山谷里有一处山洞，洞里有一些不明物质，我们初步判断就是那些东西导致的传染病。"
  },
  [111480254] = {
    id = 111480254,
    name = "不明物质......"
  },
  [111480255] = {
    id = 111480255,
    name = "对。我们准备再进去一趟，正好，我想邀请舒芙蕾小姐......不，是邀请你们二位，请和我们一起查明真相！"
  },
  [111480256] = {id = 111480256, name = "......"},
  [111480257] = {
    id = 111480257,
    name = "舒芙蕾看向了你，似乎在等你的意见。"
  },
  [111480258] = {
    id = 111480258,
    name = "我们确实也在调查这件事。不过你们人手挺充足的，为什么还要拉上我们？"
  },
  [111480259] = {
    id = 111480259,
    name = "那个不明物质如果真的像浊炁能侵蚀人体的话，舒芙蕾小姐的净化能力将带来很大的助益，虽然很冒犯，但这是我诚挚的邀请。拜托了，两位！"
  },
  [111480260] = {
    id = 111480260,
    name = "净化吗？可以的。"
  },
  [111480261] = {id = 111480261, name = "真的？"},
  [111480262] = {
    id = 111480262,
    name = "能够帮到你们，我很高兴。"
  },
  [111480263] = {
    id = 111480263,
    name = "既然这么说，那就约个时间吧。"
  },
  [111480264] = {
    id = 111480264,
    name = "太好了！我要把这个消息告诉他们。"
  },
  [111480265] = {
    id = 111480265,
    name = "默尔克和你们约定好了时间，与队友一同离开了。"
  },
  [111480266] = {id = 111480266, name = "......"},
  [111480267] = {
    id = 111480267,
    name = "在看什么？"
  },
  [111480268] = {
    id = 111480268,
    name = "如果山谷里有危险，可以直接告诉据点的人。为什么......不告诉大家呢？"
  },
  [111480269] = {
    id = 111480269,
    name = "是啊，还派人看守着谷口......事情变得蹊跷起来了。"
  },
  [111480270] = {
    id = 111480270,
    name = "不管怎么样，这都是一个接近真相的好机会。你也是这样认为的吧？"
  },
  [111480271] = {id = 111480271, name = "当然。"},
  [111480272] = {
    id = 111480272,
    name = "你们回到了据点。"
  },
  [111480273] = {
    id = 111480273,
    name = "去山谷的话，需要先筹备一些东西。"
  },
  [111480274] = {
    id = 111480274,
    name = "嗯，我也是这么打算的。"
  },
  [111480275] = {
    id = 111480275,
    name = "我们分头行动？"
  },
  [111480276] = {
    id = 111480276,
    name = "好啊，那么我——"
  },
  [111480277] = {
    id = 111480277,
    name = "大小姐，大小姐~"
  },
  [111480278] = {
    id = 111480278,
    name = "有人在叫你。"
  },
  [111480279] = {
    id = 111480279,
    name = "这里，这里！"
  },
  [111480280] = {
    id = 111480280,
    name = "你们顺声看去，两个人在街道角落里朝你们招了招手。"
  },
  [111480281] = {
    id = 111480281,
    name = "是他们两个。"
  },
  [111480282] = {
    id = 111480282,
    name = "来得正好。"
  },
  [111480283] = {
    id = 111480283,
    name = "走到街角，两人很激动地看着你们。"
  },
  [111480284] = {
    id = 111480284,
    name = "大小姐，那个默尔克是不是找了你们！"
  },
  [111480285] = {
    id = 111480285,
    name = "不，不要去啊！"
  },
  [111480286] = {
    id = 111480286,
    name = "你们怎么知道的？"
  },
  [111480287] = {
    id = 111480287,
    name = "我，我们看到你们从山谷回来......"
  },
  [111480288] = {
    id = 111480288,
    name = "那个山谷被他们占领了，我们不敢进去。"
  },
  [111480289] = {
    id = 111480289,
    name = "占领？默尔克先生说是为了防止有人再去触碰不明物质。"
  },
  [111480290] = {
    id = 111480290,
    name = "大小姐，他是骗你的！"
  },
  [111480291] = {
    id = 111480291,
    name = "什么意思？"
  },
  [111480292] = {
    id = 111480292,
    name = "劫匪往后退了一步，看起来还是很害怕你的样子。"
  },
  [111480293] = {
    id = 111480293,
    name = "......有什么就快说！"
  },
  [111480294] = {
    id = 111480294,
    name = "是是！那个山谷里，有宝物！"
  },
  [111480295] = {id = 111480295, name = "嗯？"},
  [111480296] = {
    id = 111480296,
    name = "对、对，我的同伴，亲眼看见的！"
  },
  [111480297] = {
    id = 111480297,
    name = "是啊，他们只是想利用你们而已！"
  },
  [111480298] = {
    id = 111480298,
    name = "里面......太，太危险了！"
  },
  [111480299] = {
    id = 111480299,
    name = "对，让你们去当先锋，然后自己去拿宝物！"
  },
  [111480300] = {
    id = 111480300,
    name = "宝物......默尔克先生没有和我说宝物的事。"
  },
  [111480301] = {
    id = 111480301,
    name = "果然，我们没说错！既然他只想利用你们，又怎么可能把这件事告诉你呢！大小姐，千万不要上了他的当啊！"
  },
  [111480302] = {id = 111480302, name = "......"},
  [111480303] = {
    id = 111480303,
    name = "等等，你说你的同伴看到了宝物，是什么样的宝物？"
  },
  [111480304] = {
    id = 111480304,
    name = "......你们......也对宝物有兴趣？"
  },
  [111480305] = {
    id = 111480305,
    name = "危、危险，不要去啊......"
  },
  [111480306] = {
    id = 111480306,
    name = "具体什么宝物，我的同伴也没有说......自他从山谷回来，就有点不太正常。"
  },
  [111480307] = {
    id = 111480307,
    name = "一开始只会不停念叨着看到了宝物，过了两天，他开始变得特别容易生气，身体也偶尔变成了青色，跟他接触的，多多少少也出现了这样的症状。"
  },
  [111480308] = {
    id = 111480308,
    name = "还好，后、后来，用了大小姐的药......好、好多了。"
  },
  [111480309] = {
    id = 111480309,
    name = "那能带我见见你们的同伴吗？"
  },
  [111480310] = {
    id = 111480310,
    name = "两名劫匪互相看了一眼，欲言又止的样子。"
  },
  [111480311] = {
    id = 111480311,
    name = "没关系，不方便就算了。"
  },
  [111480312] = {
    id = 111480312,
    name = "那个......他最近情况不太好，我们把他藏起来了。而且，昨天发生的那件事......"
  },
  [111480313] = {
    id = 111480313,
    name = "昨天......有人突然发狂的事？"
  },
  [111480314] = {
    id = 111480314,
    name = "对、对......"
  },
  [111480315] = {
    id = 111480315,
    name = "不，不光是昨天，之前暴走的人，被带走之后都不见了，我听人说，是被秘密处理了。"
  },
  [111480316] = {
    id = 111480316,
    name = "他比划了一个手势。"
  },
  [111480317] = {id = 111480317, name = "？！"},
  [111480318] = {
    id = 111480318,
    name = "也不知道是不是他做的。总之，大小姐，千万不要相信那个默尔克啊！"
  },
  [111480319] = {
    id = 111480319,
    name = "谢谢你告诉我们这个重要的消息。"
  },
  [111480320] = {
    id = 111480320,
    name = "不、不客气，应该的。"
  },
  [111480321] = {
    id = 111480321,
    name = "两人说完就离开了，留下你们在原地沉思。"
  },
  [111480322] = {
    id = 111480322,
    name = "怎么样，明天还去吗？"
  },
  [111480323] = {
    id = 111480323,
    name = "要去的，这件事越来越让人觉得奇怪了。"
  },
  [111480324] = {
    id = 111480324,
    name = "嗯，宝物、秘密处理......每一个信息都让人觉得匪夷所思。"
  },
  [111480325] = {
    id = 111480325,
    name = "......我想在明天之前，再去山谷看看。"
  },
  [111480326] = {
    id = 111480326,
    name = "那就去旁边的山上，这样能直接从上面看到山谷内部，也许能打探到更多的情报。"
  },
  [111480327] = {
    id = 111480327,
    name = "好，那我们现在就出发。"
  },
  [111480328] = {
    id = 111480328,
    name = "别着急，有什么吃饱了再说。"
  },
  [111480329] = {
    id = 111480329,
    name = "嗯。还要去那家酒馆吗？你那天选的食物，我很喜欢。"
  },
  [111480330] = {
    id = 111480330,
    name = "你不嫌弃的话，当然可以。"
  },
  [111480331] = {
    id = 111480331,
    name = "舒芙蕾微微笑了，湖泊般的眼睛弯成了两道潺潺的月牙泉。"
  },
  [111480332] = {
    id = 111480332,
    name = "那这次就由我来点餐吧。"
  },
  [111480333] = {
    id = 111480333,
    name = "这座山上的浊炁，比较其他更浓郁了。"
  },
  [111480334] = {
    id = 111480334,
    name = "嗯，雾气很大，小心脚下。"
  },
  [111480335] = {
    id = 111480335,
    name = "我们沿着山边走，很快就能到山谷上方。"
  },
  [111480336] = {
    id = 111480336,
    name = "嗯，希望能有收获。说起来，舒芙蕾小姐，你觉得哪一个说的才是真话？"
  },
  [111480337] = {
    id = 111480337,
    name = "呵呵，无所谓真假。"
  },
  [111480338] = {
    id = 111480338,
    name = "不管他人怎么说，在真相没有水落石出之前，我都会一直按照自己的方式查下去，坚信自己的路，是自由学派研究学术领域的基本信念。"
  },
  [111480339] = {
    id = 111480339,
    name = "不为左右动摇，舒芙蕾小姐出乎意料地坚定啊。"
  },
  [111480340] = {
    id = 111480340,
    name = "我会试着相信每一个人说的话，也会试着质疑每一条所获得的信息，相信，是因为我不愿错怪他人的好意。"
  },
  [111480341] = {
    id = 111480341,
    name = "质疑，是对结果的负责，我......不想再得到一个错误的答案。"
  },
  [111480342] = {
    id = 111480342,
    name = "（再？）"
  },
  [111480343] = {
    id = 111480343,
    name = "那就去看看，到底哪一个说的是谎言吧。"
  },
  [111480344] = {
    id = 111480344,
    name = "沙沙......附近出现了高高低低的脚步声，舒芙蕾看了你一眼，跟随你一同放轻了脚步，你们悄然接近......"
  },
  [111480345] = {
    id = 111480345,
    name = "（是他？！）"
  },
  [111480346] = {
    id = 111480346,
    name = "沉沉雾霭里，一身黑衣若隐若现，你瞬间冲了上去，拦在了黑衣人面前。"
  },
  [111480347] = {
    id = 111480347,
    name = "哟，来干嘛呢？"
  },
  [111480348] = {id = 111480348, name = "！！！"},
  [111480349] = {
    id = 111480349,
    name = "黑衣人转身就逃。"
  },
  [111480350] = {
    id = 111480350,
    name = "打个招呼而已，别走啊！"
  },
  [111480351] = {
    id = 111480351,
    name = "黑衣人一声不吭，刚跑几步就被舒芙蕾拦下了。"
  },
  [111480352] = {
    id = 111480352,
    name = "你是谁？"
  },
  [111480353] = {
    id = 111480353,
    name = "砰——！"
  },
  [111480354] = {
    id = 111480354,
    name = "咳咳......他往那边跑了！"
  },
  [111480355] = {
    id = 111480355,
    name = "你没事吧？"
  },
  [111480356] = {
    id = 111480356,
    name = "舒芙蕾摇摇头，跟着你追了上去。"
  },
  [111480357] = {
    id = 111480357,
    name = "呼，不见了......"
  },
  [111480358] = {
    id = 111480358,
    name = "跑了一段路，你们没有也看到黑衣人。"
  },
  [111480359] = {
    id = 111480359,
    name = "抱歉，是我太大意了。"
  },
  [111480360] = {
    id = 111480360,
    name = "没事，这是意外。"
  },
  [111480361] = {
    id = 111480361,
    name = "他是谁？"
  },
  [111480362] = {
    id = 111480362,
    name = "你还记得我们制服发病的人时候吗，这个黑衣人，在角落里看着。"
  },
  [111480363] = {
    id = 111480363,
    name = "会不会只是偶尔路过的......"
  },
  [111480364] = {
    id = 111480364,
    name = "如果只是路过，他刚才就不会做贼心虚。"
  },
  [111480365] = {
    id = 111480365,
    name = "嗯，你说得没错。这时候出现在山上，又看见我们就逃跑，难道他和这件事有关？"
  },
  [111480366] = {
    id = 111480366,
    name = "我们尽快上去吧，也许还能发现一些蛛丝马迹。"
  },
  [111480367] = {
    id = 111480367,
    name = "沙沙......沙沙......此时，旁边又传来了脚步声。"
  },
  [111480368] = {id = 111480368, name = "谁？"},
  [111480369] = {
    id = 111480369,
    name = "舒芙蕾小姐！这位阁下！"
  },
  [111480370] = {id = 111480370, name = "......"},
  [111480371] = {
    id = 111480371,
    name = "默尔克先生？！"
  },
  [111480372] = {
    id = 111480372,
    name = "......你怎么会在这里？"
  },
  [111480373] = {
    id = 111480373,
    name = "我来采摘一些明天进山谷需要的莹草，顺便再探查一下周围的情况。你们呢？"
  },
  [111480374] = {id = 111480374, name = "......"},
  [111480375] = {
    id = 111480375,
    name = "我们和你一样，想着要进山谷，总需要一些准备。"
  },
  [111480376] = {
    id = 111480376,
    name = "哦，那太好了，我这里已经准备了足够的份量。既然是邀请两位帮忙，怎么能让两位再辛苦。"
  },
  [111480377] = {id = 111480377, name = "......"},
  [111480378] = {
    id = 111480378,
    name = "哦？默尔克领队真是周全啊，到让我们省了不少心。"
  },
  [111480379] = {
    id = 111480379,
    name = "呵呵，你们还需要准备什么，都交给我吧。"
  },
  [111480380] = {
    id = 111480380,
    name = "默尔克领队，我想问你一件事。"
  },
  [111480381] = {
    id = 111480381,
    name = "小姐想问什么？我一定知无不言。"
  },
  [111480382] = {
    id = 111480382,
    name = "你刚才，有没有看到......什么人？"
  },
  [111480383] = {
    id = 111480383,
    name = "默尔克愣了愣，表露出明显的诧异。"
  },
  [111480384] = {
    id = 111480384,
    name = "什么人？"
  },
  [111480385] = {
    id = 111480385,
    name = "比如，一身黑色的衣服。"
  },
  [111480386] = {
    id = 111480386,
    name = "这个倒是没看见。你们是在找人吗？"
  },
  [111480387] = {
    id = 111480387,
    name = "嗯，那个人行动鬼祟，有点可疑。"
  },
  [111480388] = {
    id = 111480388,
    name = "呵呵，行动可疑也许只是为了躲避魔物吧，这座山上莹草不少，魔物也不少啊。"
  },
  [111480389] = {
    id = 111480389,
    name = "可是......"
  },
  [111480390] = {
    id = 111480390,
    name = "我刚转了一圈，的确什么都没发现。要说可疑的话，你们出现在山上，才是吓了我一跳呢。"
  },
  [111480391] = {id = 111480391, name = "......"},
  [111480392] = {
    id = 111480392,
    name = "哈哈哈哈，开玩笑的，时候不早了，我得把莹草带回去给兄弟们。你们也早些回去吧，好好休息，明天才有更好的精力调查啊。"
  },
  [111480393] = {
    id = 111480393,
    name = "默尔克离开了。"
  },
  [111480394] = {id = 111480394, name = "......"},
  [111480395] = {
    id = 111480395,
    name = "我刚才是不是......太莽撞了？"
  },
  [111480396] = {
    id = 111480396,
    name = "不是，我觉得你干得很漂亮。他的反应......真的很可疑......"
  },
  [111480397] = {
    id = 111480397,
    name = "可他和我说的那些话，并不像撒谎。如果他真的有什么目的，我也不愿意错过这次找出真相、挽救那些病人的机会。"
  },
  [111480398] = {
    id = 111480398,
    name = "要是病人们真的因为我的不管不问而死掉，我会感到很遗憾的。"
  },
  [111480399] = {
    id = 111480399,
    name = "好，好。悲天悯人的大小姐，我们该回去了。"
  },
  [111480400] = {
    id = 111480400,
    name = "不是要探查山谷吗？"
  },
  [111480401] = {
    id = 111480401,
    name = "喏，你看那边，一片迷雾，什么也看不到。"
  },
  [111480402] = {
    id = 111480402,
    name = "舒芙蕾看向满是雾气的山谷，微笑着叹了口气。"
  },
  [111480403] = {
    id = 111480403,
    name = "好在遇到了黑衣人和领队，也不算白来这一趟。"
  },
  [111480404] = {
    id = 111480404,
    name = "嗯，意外的收获。"
  },
  [111480405] = {
    id = 111480405,
    name = "翌日，你与舒芙蕾按照约定来到了炎日山谷，默尔克与他的队员早就等候在了那里。"
  },
  [111480406] = {
    id = 111480406,
    name = "准备好了的话，我们就出发吧。"
  },
  [111480407] = {
    id = 111480407,
    name = "什么嘛，领队~原来你去搬救兵了啊。"
  },
  [111480408] = {
    id = 111480408,
    name = "对，有他们在，一定能帮上大忙的。"
  },
  [111480409] = {
    id = 111480409,
    name = "你说的那个奇怪的不明物质在那里？"
  },
  [111480410] = {
    id = 111480410,
    name = "我们边走边说。"
  },
  [111480411] = {
    id = 111480411,
    name = "我来带路，老三，快跟上！"
  },
  [111480412] = {id = 111480412, name = "......"},
  [111480413] = {
    id = 111480413,
    name = "两个人很快走到前面去了。"
  },
  [111480414] = {
    id = 111480414,
    name = "舒芙蕾小姐，在说这件事之前，我想向你坦白一件事。上一次，是我故意和队员说了一些话，将你引到炎日谷口的。"
  },
  [111480415] = {
    id = 111480415,
    name = "故意？！"
  },
  [111480416] = {
    id = 111480416,
    name = "是的，欺骗了你装作偶遇......我很抱歉。但这次的事件，已经刻不容缓了。"
  },
  [111480417] = {
    id = 111480417,
    name = "什么意思？"
  },
  [111480418] = {
    id = 111480418,
    name = "那个所谓的「传染病」，我已经见到了很多起。已经不止一个据点出现了传染病的事，而且，那些病人，几乎全部都来过这里。"
  },
  [111480419] = {
    id = 111480419,
    name = "难道这种病不是偶然？"
  },
  [111480420] = {
    id = 111480420,
    name = "没错，总之不能再继续下去了，否则，会有越来越多的人出现传染病。"
  },
  [111480421] = {
    id = 111480421,
    name = "为什么那些人会来这里？"
  },
  [111480422] = {
    id = 111480422,
    name = "默尔克顿了顿，继续向前走。"
  },
  [111480423] = {
    id = 111480423,
    name = "实不相瞒，因为有传言说，这里有「宝物」。"
  },
  [111480424] = {id = 111480424, name = "......"},
  [111480425] = {
    id = 111480425,
    name = "「宝物」的事，我们昨天也听说了。"
  },
  [111480426] = {
    id = 111480426,
    name = "什么？是谁告诉你们的?！"
  },
  [111480427] = {
    id = 111480427,
    name = "这很重要吗？"
  },
  [111480428] = {
    id = 111480428,
    name = "那个人如果知道传染病的事还告诉你宝物，一定别有用心。"
  },
  [111480429] = {
    id = 111480429,
    name = "关于宝物的消息，我也是费了些劲才拿到。听说是有人在偷偷以高价贩卖，而大家都想独占这个宝物，就并没有传开。"
  },
  [111480430] = {
    id = 111480430,
    name = "原来是这样。其实，一个病人的同伴告诉了我们关于宝物的消息，让我们远离......远离这个山谷。"
  },
  [111480431] = {
    id = 111480431,
    name = "唉，是的。如果没有充分的准备就来这里，那和自杀也没有分别。"
  },
  [111480432] = {
    id = 111480432,
    name = "领队，快来！里面的烟雾变得更浓了！"
  },
  [111480433] = {
    id = 111480433,
    name = "前方的队员朝你们挥了挥手，默尔克反而在这里停了下来。"
  },
  [111480434] = {
    id = 111480434,
    name = "两位，前面就是山洞了，也就是传言里「宝物」的所在地。如果两位没有想好的话，现在退出还来得及。"
  },
  [111480435] = {
    id = 111480435,
    name = "不，既然决定要做了，那就一直做下去，直到得到那个答案。"
  },
  [111480436] = {
    id = 111480436,
    name = "不愧是舒芙蕾小姐！你还是这么勇敢和善良！"
  },
  [111480437] = {
    id = 111480437,
    name = "等等，如果真的有宝物呢？"
  },
  [111480438] = {id = 111480438, name = "......"},
  [111480439] = {
    id = 111480439,
    name = "我认为里面就算又宝物，也只是能让人抛弃理智发狂的，害人的污秽。"
  },
  [111480440] = {
    id = 111480440,
    name = "如果那个宝物很值钱呢？"
  },
  [111480441] = {
    id = 111480441,
    name = "如果有......解决了这件事之后，我会将宝物双手奉上！"
  },
  [111480442] = {id = 111480442, name = "......"},
  [111480443] = {
    id = 111480443,
    name = "......那倒不至于，我只是随便问问。"
  },
  [111480444] = {
    id = 111480444,
    name = "那就好。我所承诺的，也只能是解决问题之后，如果所谓宝物是一切的恶之源......"
  },
  [111480445] = {
    id = 111480445,
    name = "看来默尔克先生已经有判断了。"
  },
  [111480446] = {
    id = 111480446,
    name = "对，根据我们多次探查得出的结论，那些不明物质，很可能是「宝物」在作祟。知道这里有「宝物」的人越来越多了，必须尽快将这个隐患斩除，否则......"
  },
  [111480447] = {
    id = 111480447,
    name = "默尔克先生有一颗正义之心啊。"
  },
  [111480448] = {
    id = 111480448,
    name = "一切都是为了——"
  },
  [111480449] = {
    id = 111480449,
    name = "呜哇，这里有魔物啊！"
  },
  [111480450] = {id = 111480450, name = "！！！"},
  [111480451] = {
    id = 111480451,
    name = "默尔克冲了上去。"
  },
  [111480452] = {
    id = 111480452,
    name = "你与舒芙蕾对视一眼，随后跟上。"
  },
  [111480453] = {
    id = 111480453,
    name = "哇，之前真是好险啊，幸好领队及时赶到。"
  },
  [111480454] = {
    id = 111480454,
    name = "你要感谢的不只是我。"
  },
  [111480455] = {
    id = 111480455,
    name = "嘻嘻......是啦，是啦，还有温柔的舒芙蕾小姐以及强者阁下。"
  },
  [111480456] = {
    id = 111480456,
    name = "我们到了。"
  },
  [111480457] = {
    id = 111480457,
    name = "洞口被紫色的浓雾笼罩着，看不清洞内的情况。"
  },
  [111480458] = {
    id = 111480458,
    name = "这......不止是浊炁，还有凝成雾的瘴气，我来试试吧。"
  },
  [111480459] = {
    id = 111480459,
    name = "舒芙蕾举起法杖，顶端发出了一圈温和的白色光芒，光芒一圈圈地扩散，如水波一般晕开......"
  },
  [111480460] = {
    id = 111480460,
    name = "不愧是舒芙蕾小姐，这些浓雾都驱散了！"
  },
  [111480461] = {
    id = 111480461,
    name = "呵呵，我只是略尽绵薄之力。"
  },
  [111480462] = {
    id = 111480462,
    name = "进入山洞，默尔克率先打开了魔法照明，明暗交错的暗影里，隐约可见嶙峋的石壁，利刃般的裂缝中长满了苔藓和青草，空气里弥漫着霉味和腐烂的气息。"
  },
  [111480463] = {
    id = 111480463,
    name = "啊，我和老三上次走到这里就回去了。"
  },
  [111480464] = {
    id = 111480464,
    name = "大家小心，前面有奇怪的声音。"
  },
  [111480465] = {
    id = 111480465,
    name = "空气里弥漫着霉味和腐烂的气息，以及似有似无的呜咽。"
  },
  [111480466] = {
    id = 111480466,
    name = "是风声。"
  },
  [111480467] = {
    id = 111480467,
    name = "风吹过石头发出了低沉轻响，令人寒毛直竖。滴答——"
  },
  [111480468] = {
    id = 111480468,
    name = "哇，这里面还有水声......是河流吗？"
  },
  [111480469] = {
    id = 111480469,
    name = "不是，是血......小心！！"
  },
  [111480470] = {
    id = 111480470,
    name = "轰！！！密密麻麻的红色飞行物扑面而来！"
  },
  [111480471] = {id = 111480471, name = "迎战！"},
  [111480472] = {
    id = 111480472,
    name = "一道魔法击溃了最前的先头部队。"
  },
  [111480473] = {
    id = 111480473,
    name = "是飞行魔物！"
  },
  [111480474] = {
    id = 111480474,
    name = "它们怕光！用魔法！"
  },
  [111480475] = {id = 111480475, name = "好！"},
  [111480476] = {
    id = 111480476,
    name = "被抓住弱点的魔物很快被你们消灭了。"
  },
  [111480477] = {
    id = 111480477,
    name = "有舒芙蕾小姐相助，这一次真的轻松很多。"
  },
  [111480478] = {
    id = 111480478,
    name = "夸奖了，还要多亏了他的提醒。"
  },
  [111480479] = {
    id = 111480479,
    name = "好了，快走吧。"
  },
  [111480480] = {
    id = 111480480,
    name = "呵呵，你是害羞了吗？"
  },
  [111480481] = {id = 111480481, name = "......"},
  [111480482] = {
    id = 111480482,
    name = "到了，到了，就在前面！看，那个黑色的罩子！"
  },
  [111480483] = {
    id = 111480483,
    name = "黑雾里，有微光隐约闪烁着，黑雾的边缘缠绕着蜘蛛网般的红线，昭示着不可触犯的「宝物」的确藏匿其中。"
  },
  [111480484] = {
    id = 111480484,
    name = "又要麻烦你了，舒芙蕾小姐。"
  },
  [111480485] = {
    id = 111480485,
    name = "好的，请交给我来处理。"
  },
  [111480486] = {
    id = 111480486,
    name = "短暂的魔法低吟如轻轻地哼唱，耀眼的光束瞬间照亮了整个山洞！"
  },
  [111480487] = {
    id = 111480487,
    name = "看见了，我看见了！"
  },
  [111480488] = {
    id = 111480488,
    name = "安静点，别过去。"
  },
  [111480489] = {
    id = 111480489,
    name = "真的......是「宝、物」啊。"
  },
  [111480490] = {
    id = 111480490,
    name = "他说得咬牙切齿，雾气散后，「宝物」孤零零地摆在前面的地上，释放着极强的压迫感，令人不安，使得整个山洞仿佛都因他得了瘟疫。"
  },
  [111480491] = {
    id = 111480491,
    name = "就是这个玩意儿，害得那么多人为它疯了！"
  },
  [111480492] = {
    id = 111480492,
    name = "默尔克领队！"
  },
  [111480493] = {
    id = 111480493,
    name = "见他拿出了武器，准备毁掉宝物，舒芙蕾及时阻止了他。"
  },
  [111480494] = {id = 111480494, name = "......"},
  [111480495] = {
    id = 111480495,
    name = "我们先靠近看看，再做决定如何？"
  },
  [111480496] = {
    id = 111480496,
    name = "对，是我太冲动了，如果真的毁掉，也许会错失很多信息。"
  },
  [111480497] = {
    id = 111480497,
    name = "你们小心地靠近，安全走到了宝物面前。"
  },
  [111480498] = {
    id = 111480498,
    name = "呼，一切顺利。"
  },
  [111480499] = {
    id = 111480499,
    name = "宝物的表面......是什么？"
  },
  [111480500] = {
    id = 111480500,
    name = "默尔克拿出提前准备的手套戴好，小心地触碰了宝物。"
  },
  [111480501] = {
    id = 111480501,
    name = "有点滑......像涂了一层什么......舒芙蕾小姐，你能看出什么吗？"
  },
  [111480502] = {
    id = 111480502,
    name = "没有，这样的宝物......我也是第一次见到。"
  },
  [111480503] = {
    id = 111480503,
    name = "公会有专门鉴定宝物的场所。"
  },
  [111480504] = {
    id = 111480504,
    name = "那就先带走拿去鉴定一番，袋子在谁那里，给我吧。"
  },
  [111480505] = {
    id = 111480505,
    name = "在我这里哟，领队！"
  },
  [111480506] = {
    id = 111480506,
    name = "活泼的探险者靠近了默尔克。"
  },
  [111480507] = {
    id = 111480507,
    name = "你！！！"
  },
  [111480508] = {
    id = 111480508,
    name = "怎么了？"
  },
  [111480509] = {
    id = 111480509,
    name = "在所有人的视野盲区，一把匕首插入了默尔克的后背，同时「宝物」被装入了口袋。"
  },
  [111480510] = {
    id = 111480510,
    name = "多谢领队带路啊，不然我还没这么容易拿到手呢。"
  },
  [111480511] = {id = 111480511, name = "！！！"},
  [111480512] = {
    id = 111480512,
    name = "血......默尔克领队，你受伤了？！"
  },
  [111480513] = {
    id = 111480513,
    name = "别管我......你们快抓住他！"
  },
  [111480514] = {
    id = 111480514,
    name = "再见了，愚蠢的领队！我会送给你一个最好的礼物！"
  },
  [111480515] = {id = 111480515, name = "你——"},
  [111480516] = {
    id = 111480516,
    name = "始作俑者早趁这一时间逃到了洞口的位置。"
  },
  [111480517] = {
    id = 111480517,
    name = "可是领队你......"
  },
  [111480518] = {
    id = 111480518,
    name = "抓不到，就毁了它，那种邪恶的东西......不能存在于这个世界！"
  },
  [111480519] = {
    id = 111480519,
    name = "沉默寡言的探险者果断冲了出去！"
  },
  [111480520] = {
    id = 111480520,
    name = "呼......呼......呼......"
  },
  [111480521] = {
    id = 111480521,
    name = "默尔克先生，先别乱动，这把匕首有毒！"
  },
  [111480522] = {
    id = 111480522,
    name = "黝黑的血液从默尔克的刀口渗出，他虚弱地趴在地上，神志清醒，舒芙蕾迅速用魔法力包裹了伤口，看向了你。"
  },
  [111480523] = {
    id = 111480523,
    name = "拜托你，我现在不方便，能帮我拿一下解毒药水吗。"
  },
  [111480524] = {id = 111480524, name = "好。"},
  [111480525] = {
    id = 111480525,
    name = "经过舒芙蕾的治疗，默尔克体内的毒素及时祛除了，但他仍然无力地躺在地上。"
  },
  [111480526] = {
    id = 111480526,
    name = "其实很早，我就发现有人在一直走漏消息。"
  },
  [111480527] = {
    id = 111480527,
    name = "我有怀疑过我们之中出现了一个背叛者......但种种巧合，让我一直忽略了这个事实，毕竟，他们一个个从下深渊开始就跟着我......"
  },
  [111480528] = {
    id = 111480528,
    name = "看他的样子，也并不像临时起意。"
  },
  [111480529] = {
    id = 111480529,
    name = "我没想到......会在这时候对我动手......他一定是被人蛊惑了......等我抓住那个人——咳咳咳......"
  },
  [111480530] = {
    id = 111480530,
    name = "默尔克先生，请别激动，你还需要休息一段时间。"
  },
  [111480531] = {
    id = 111480531,
    name = "谢谢你们......想不到因为你们......我才有这一线活下来的可能......唔......"
  },
  [111480532] = {
    id = 111480532,
    name = "默尔克先生！"
  },
  [111480533] = {
    id = 111480533,
    name = "默尔克尝试着起身，但是失败了。"
  },
  [111480534] = {
    id = 111480534,
    name = "你最好别乱动，等药效起了作用，才能自由行动。"
  },
  [111480535] = {
    id = 111480535,
    name = "可是我怕来不及，我不知道他把宝物拿去做什么......"
  },
  [111480536] = {
    id = 111480536,
    name = "听他的意思，有人在接应他，而目前最可疑的，是那个黑衣人。"
  },
  [111480537] = {
    id = 111480537,
    name = "是我们在山上撞见的那个黑衣人？"
  },
  [111480538] = {
    id = 111480538,
    name = "啊！怪我，都怪我......要是当初能多听听你们的话......"
  },
  [111480539] = {
    id = 111480539,
    name = "默尔克蜷缩着抱着头，为自己的自负懊恼。"
  },
  [111480540] = {
    id = 111480540,
    name = "别自责了，等你伤好了可以自己去找他算账。"
  },
  [111480541] = {
    id = 111480541,
    name = "......我怕来不及了，我怕会像几年前那样......"
  },
  [111480542] = {
    id = 111480542,
    name = "几年前？"
  },
  [111480543] = {
    id = 111480543,
    name = "是的，这样的宝物我见过一次，那次我和许多人都失去了意识，而银币大哥为了救人，与「宝物」同归于尽了......"
  },
  [111480544] = {
    id = 111480544,
    name = "银币大哥？"
  },
  [111480545] = {
    id = 111480545,
    name = "他有个规矩，穷人求他办事，他只收一枚银币。我永远记得那个人在生命最后的样子，他说「愿以残破之身，维护正义之道，不悔。」他挡在我的面前，点燃自己化为了灰烬......"
  },
  [111480546] = {
    id = 111480546,
    name = "那一次的火焰久久燃烧不尽，只留下了一枚银币......从那时起，我暗暗发誓，我要像他一样，铲除世间所有的罪恶，拯救像那时候的我一样无助的人。"
  },
  [111480547] = {
    id = 111480547,
    name = "所以，拜托你们，带我追上去！就算燃尽此身，我也要阻止他们的恶行！"
  },
  [111480548] = {
    id = 111480548,
    name = "......默尔克先生，我们走吧。"
  },
  [111480549] = {
    id = 111480549,
    name = "默尔克豁然抬头，双眸迸发出星火般的亮光。"
  },
  [111480550] = {
    id = 111480550,
    name = "好，好，可我不能让你们白跑这一趟！"
  },
  [111480551] = {
    id = 111480551,
    name = "好了，我们愿意帮你，可不是为了那点报酬。对吧，舒芙蕾小姐？"
  },
  [111480552] = {
    id = 111480552,
    name = "呵呵，难得在晦暗疏星的黑夜，还能看到一盏灯火......不介意，就请让我们和你一起同行吧。"
  },
  [111480553] = {
    id = 111480553,
    name = "默尔克低低地笑了，笑声越来越大，他笑得扯到了伤口，嘴角仍然弯着。"
  },
  [111480554] = {
    id = 111480554,
    name = "呵......呵呵......太好了......我的信念，我走的路，不是孤独的......太好了，太好了......"
  },
  [111480555] = {
    id = 111480555,
    name = "默尔克先生队友留下的记号，竟然到了据点。"
  },
  [111480556] = {
    id = 111480556,
    name = "那家伙抢了宝物不逃跑，还到据点来做什么......"
  },
  [111480557] = {
    id = 111480557,
    name = "呼......不管怎样，先进去看看。"
  },
  [111480558] = {
    id = 111480558,
    name = "——哗！"
  },
  [111480559] = {
    id = 111480559,
    name = "远处据点里房屋窜起一道高高的火焰！"
  },
  [111480560] = {
    id = 111480560,
    name = "房屋怎么烧起来了？！"
  },
  [111480561] = {
    id = 111480561,
    name = "救火，快救火！！啊啊，杀了你们，杀光你们！！"
  },
  [111480562] = {
    id = 111480562,
    name = "里面有什么在吵闹？"
  },
  [111480563] = {
    id = 111480563,
    name = "糟了，难道......"
  },
  [111480564] = {
    id = 111480564,
    name = "你们疾速赶到了据点。"
  },
  [111480565] = {
    id = 111480565,
    name = "怎么会这样？！"
  },
  [111480566] = {
    id = 111480566,
    name = "大火以燎原之势，迅速席卷了大半个据点，到处听得到人们惊慌失措的呼喊和惨叫，还有刀剑相博的厮杀声——"
  },
  [111480567] = {
    id = 111480567,
    name = "那些人......是堕落者！"
  },
  [111480568] = {
    id = 111480568,
    name = "怎么会有这么多堕落者？"
  },
  [111480569] = {
    id = 111480569,
    name = "堕落者扑向了探险者，又被一群探险者围攻，接着，更多的堕落者出现了，毫无理智地厮杀在一起。"
  },
  [111480570] = {
    id = 111480570,
    name = "不，那些是......失踪的病人！"
  },
  [111480571] = {
    id = 111480571,
    name = "什么？！"
  },
  [111480572] = {
    id = 111480572,
    name = "还记得之前患病后那些发狂的人吗？"
  },
  [111480573] = {
    id = 111480573,
    name = "我找过他们......但怎么也找不到，没想到，有人把他们藏起来了，还变成了这副鬼样子！"
  },
  [111480574] = {
    id = 111480574,
    name = "默尔克颤抖着扶住断裂的土墙，回到这里，几乎用了他全部的力气。"
  },
  [111480575] = {
    id = 111480575,
    name = "被欲望吞噬的堕落之身，已不再是人类。"
  },
  [111480576] = {
    id = 111480576,
    name = "你跟在舒芙蕾身后，风吹着她垂落的发，柔和的侧面，露出了坚定凛然的目光。"
  },
  [111480577] = {
    id = 111480577,
    name = "请和我先一起救下无辜的探险者。"
  },
  [111480578] = {
    id = 111480578,
    name = "荣幸之至。"
  },
  [111480579] = {
    id = 111480579,
    name = "啊啊啊——"
  },
  [111480580] = {
    id = 111480580,
    name = "——轰！魔法打在堕落者身上，将浊炁净化，更多的堕落者扑了上来，被你们一一击退。"
  },
  [111480581] = {
    id = 111480581,
    name = "默尔克要找的人，看来一定在据点里。"
  },
  [111480582] = {
    id = 111480582,
    name = "他，他怎么不见了？"
  },
  [111480583] = {
    id = 111480583,
    name = "他也许发现队友的记号了......我们先处理眼前的麻烦。"
  },
  [111480584] = {
    id = 111480584,
    name = "你冲至前方，协助陷入鏖战的探险者，舒芙蕾的几次相助，让你全无后顾之忧，不多时，从一个房间里冲出来了一个熟悉的人影。"
  },
  [111480585] = {
    id = 111480585,
    name = "救，救命啊！"
  },
  [111480586] = {
    id = 111480586,
    name = "是你？！"
  },
  [111480587] = {
    id = 111480587,
    name = "他，他要杀我！"
  },
  [111480588] = {
    id = 111480588,
    name = "轰——！房门被撞碎，一个堕落者狰狞扭曲地扑了上来，他的全身全是青色块状，而双眼已布满红丝。"
  },
  [111480589] = {
    id = 111480589,
    name = "小心，他身上有黑气溢出！"
  },
  [111480590] = {
    id = 111480590,
    name = "救、救救我......"
  },
  [111480591] = {
    id = 111480591,
    name = "胆小的探险者又如上次一样，准备躲向舒芙蕾的身后，而你却看到他不该有的眼神与狞笑。"
  },
  [111480592] = {
    id = 111480592,
    name = "让开！！"
  },
  [111480593] = {
    id = 111480593,
    name = "你毫不留情地朝他斩去！锵！"
  },
  [111480594] = {
    id = 111480594,
    name = "啊，被我挡下了哦。"
  },
  [111480595] = {id = 111480595, name = "？！！"},
  [111480596] = {
    id = 111480596,
    name = "呵呵，本来这个小姐是一个不错的实验对象......"
  },
  [111480597] = {
    id = 111480597,
    name = "「吼！！」身边的堕落者再次袭击了过来，你一剑将其斩杀。"
  },
  [111480598] = {
    id = 111480598,
    name = "原来是你，那些堕落者，都是你藏起来的！"
  },
  [111480599] = {
    id = 111480599,
    name = "没错，好几次都被你坏掉了我的好事，不过没关系，主人已经拿到了实验数据了，我的任务也完成了。"
  },
  [111480600] = {
    id = 111480600,
    name = "主人？......你们，是一个组织的？！"
  },
  [111480601] = {
    id = 111480601,
    name = "默尔克的队友，还有他们......应该都是一个组织的人。"
  },
  [111480602] = {
    id = 111480602,
    name = "对对，多亏了那家伙拿回了宝物，不然我还得天天跟这群野兽关在一起，啊啊，想想都恶心死了！"
  },
  [111480603] = {
    id = 111480603,
    name = "你们的主人，不会是那个黑衣人吧？"
  },
  [111480604] = {
    id = 111480604,
    name = "（脸色一变）你知道得太多了！"
  },
  [111480605] = {
    id = 111480605,
    name = "「吼！！」又一个堕落者扑了上来，你率先挡住攻击，看向逃跑的探险者。"
  },
  [111480606] = {
    id = 111480606,
    name = "这里我来处理，你先去追他！"
  },
  [111480607] = {id = 111480607, name = "好！"},
  [111480608] = {
    id = 111480608,
    name = "你腾空一脚踹飞了扑上来的堕落者，一剑刺入要害，瞬时湮灭。"
  },
  [111480609] = {
    id = 111480609,
    name = "太多了......"
  },
  [111480610] = {
    id = 111480610,
    name = "你打打停停，朝舒芙蕾的方向赶去。"
  },
  [111480611] = {
    id = 111480611,
    name = "（受伤）呼......呼......领队......就不能放过我吗？"
  },
  [111480612] = {
    id = 111480612,
    name = "别叫我领队！我没有你这个队员！"
  },
  [111480613] = {
    id = 111480613,
    name = "是默尔克！"
  },
  [111480614] = {
    id = 111480614,
    name = "顺着声音，你走到了一处小巷，那名曾经活泼的探险者已经被逼到了绝路，正哀求着默尔克放了他。"
  },
  [111480615] = {
    id = 111480615,
    name = "领队，你是教会了我很多事，可你还是不懂，我是一个「人」啊......我不想再跟着你东奔西走，你为了所谓的正义，从来不尊重我们的想法，也完全不管我们的死活！"
  },
  [111480616] = {
    id = 111480616,
    name = "道不同，不相为谋。我只是不想在你手下做事了，这难道也有错吗？！"
  },
  [111480617] = {
    id = 111480617,
    name = "看来，你还是不知道自己错在哪里。"
  },
  [111480618] = {
    id = 111480618,
    name = "一个据点、不，也许是几个据点，成百上千的探险者，就这样变成了堕落者，你还认为自己做得对吗？"
  },
  [111480619] = {
    id = 111480619,
    name = "呵呵，救了他们我能得到什么？一句感谢？感谢能当饭吃，感谢能让我变强吗？"
  },
  [111480620] = {
    id = 111480620,
    name = "还不如跟我的主人合作，就这样继续下去，我赚了欧泊，你赚了名声，这样有什么不——"
  },
  [111480621] = {
    id = 111480621,
    name = "默尔克恶狠狠地将剑挥了下去，探险者颈部大动脉的破裂，喷溅了他一脸的鲜血，贯穿他的重剑从肩膀滑到了地上。"
  },
  [111480622] = {
    id = 111480622,
    name = "啊啊啊——"
  },
  [111480623] = {
    id = 111480623,
    name = "你从下深渊就跟着我，学东西总是很快，但你没有学会一件事。人之所以为人，不止是有欲望，还有感情，有为之奋斗的东西，有坚持至今的信仰！"
  },
  [111480624] = {
    id = 111480624,
    name = "而你，背叛了队友，也背叛了我们的信念，你现在只是一个，披着人类外壳，内心腐朽的堕落者！"
  },
  [111480625] = {
    id = 111480625,
    name = "呵......呵......做人......活不......下......去的，我......不想......做一个......人......了......"
  },
  [111480626] = {
    id = 111480626,
    name = "探险者倒在地上，死前眼中流下了泪水。默尔克表情空白，双眼发红，看着自己颤抖的手，似乎还没有接受昔日队员的死。"
  },
  [111480627] = {id = 111480627, name = "......"},
  [111480628] = {
    id = 111480628,
    name = "你默默转身，听到身后有人叫你。"
  },
  [111480629] = {
    id = 111480629,
    name = "我杀了他......我一手教导的......队员......"
  },
  [111480630] = {
    id = 111480630,
    name = "你在后悔吗？"
  },
  [111480631] = {id = 111480631, name = "......"},
  [111480632] = {
    id = 111480632,
    name = "你还要走下去吗？你所坚持的路。"
  },
  [111480633] = {
    id = 111480633,
    name = "......我知道了，我还有没有完成的事。"
  },
  [111480634] = {
    id = 111480634,
    name = "谢谢你，我不会放弃一枚银币，这是我——"
  },
  [111480635] = {
    id = 111480635,
    name = "轰——！！"
  },
  [111480636] = {
    id = 111480636,
    name = "是舒芙蕾小姐的魔法！"
  },
  [111480637] = {
    id = 111480637,
    name = "他转身，突然跪在了地上。"
  },
  [111480638] = {
    id = 111480638,
    name = "她在战斗，你快去帮她！只是一点小伤而已，别管我。"
  },
  [111480639] = {
    id = 111480639,
    name = "你果断离开，顺着魔法的光亮，你判断着战斗的方向，在一条小巷口拦下了那个被追击的人。"
  },
  [111480640] = {
    id = 111480640,
    name = "黑衣人！"
  },
  [111480641] = {
    id = 111480641,
    name = "呵呵，接着！"
  },
  [111480642] = {
    id = 111480642,
    name = "他的黑衣被划破了好几道血痕，这时突然将手中捏着的东西扔向了你。"
  },
  [111480643] = {
    id = 111480643,
    name = "不要接！！"
  },
  [111480644] = {
    id = 111480644,
    name = "——砰！你躲闪到一边，长剑将那东西斩成了两半，紫色的雾气立刻从里面涌了出来。此时，一道驱散的魔法光笼罩而下！"
  },
  [111480645] = {
    id = 111480645,
    name = "小心，那个「宝物」会散发毒气！"
  },
  [111480646] = {
    id = 111480646,
    name = "别跑！！"
  },
  [111480647] = {
    id = 111480647,
    name = "烟雾中，你想抓住那个黑衣人，他却如一尾滑溜的鱼，躲过了你的追捕，一道光束在他脚下亮起，很快失去了踪迹。"
  },
  [111480648] = {id = 111480648, name = "呼......"},
  [111480649] = {
    id = 111480649,
    name = "你回头，舒芙蕾正将雾气锁在魔法罩中，很快，她额上的汗滴落了下来。"
  },
  [111480650] = {
    id = 111480650,
    name = "你......你快走，这里很危险。"
  },
  [111480651] = {
    id = 111480651,
    name = "舒芙蕾小姐，冒犯了。"
  },
  [111480652] = {
    id = 111480652,
    name = "你无声地靠近，轻轻握住她的手，将魔法的力量传递到法杖上，很快，紫色的雾气被尽数净化。"
  },
  [111480653] = {id = 111480653, name = "谢谢。"},
  [111480654] = {
    id = 111480654,
    name = "你摇摇头，退后了一步。她转头看向黑衣人逃走的方向，耳廓微红。"
  },
  [111480655] = {
    id = 111480655,
    name = "那个人很不简单。"
  },
  [111480656] = {
    id = 111480656,
    name = "他说，他收集的实验数据足够回去交代了，我不知道他的话什么意思，但一定是非常危险的事，甚至比这个据点还要危险。"
  },
  [111480657] = {id = 111480657, name = "那——"},
  [111480658] = {
    id = 111480658,
    name = "舒芙蕾小姐！！"
  },
  [111480659] = {
    id = 111480659,
    name = "默尔克带着队员疾走了过来。"
  },
  [111480660] = {
    id = 111480660,
    name = "舒芙蕾小姐，见你没事实在太好了。"
  },
  [111480661] = {
    id = 111480661,
    name = "这个据点的堕落者差不多都肃清了，剩下的有探险队员......咳咳咳......有探险队员清理现场，希望......咳咳咳......希望，不要废弃掉吧......"
  },
  [111480662] = {
    id = 111480662,
    name = "默尔克先生，请保重身体，好好养伤。"
  },
  [111480663] = {
    id = 111480663,
    name = "我没事，我——"
  },
  [111480664] = {
    id = 111480664,
    name = "砰！！默尔克一头栽倒在地。"
  },
  [111480665] = {
    id = 111480665,
    name = "没事，他是劳累过度了，我带他去圈落。"
  },
  [111480666] = {
    id = 111480666,
    name = "......需要我们帮忙吗？"
  },
  [111480667] = {
    id = 111480667,
    name = "不用了，他说过「已经给你们添了很多麻烦。」还有「要好好感谢你们。」"
  },
  [111480668] = {
    id = 111480668,
    name = "不过我不知道领队想用什么来感谢，如果有什么需求的话，请到圈落来找我们。"
  },
  [111480669] = {
    id = 111480669,
    name = "太客气了，我们只是同路人，互相扶持而已。"
  },
  [111480670] = {
    id = 111480670,
    name = "队员带着默尔克离开了。"
  },
  [111480671] = {
    id = 111480671,
    name = "也许默尔克该感到遗憾。"
  },
  [111480672] = {id = 111480672, name = "嗯？"},
  [111480673] = {
    id = 111480673,
    name = "没想过会以这种方式和我们道别吧。"
  },
  [111480674] = {
    id = 111480674,
    name = "呵呵......"
  },
  [111480675] = {
    id = 111480675,
    name = "那个黑衣人逃走了，你还要继续查吗？"
  },
  [111480676] = {
    id = 111480676,
    name = "嗯，我想去找自由学派的其他成员。"
  },
  [111480677] = {
    id = 111480677,
    name = "这件事不容小觑，我想用学术组织的力量去查，把这件事真正地晓之于众，让更多的人，不要被欺骗，麻痹，利用。"
  },
  [111480678] = {
    id = 111480678,
    name = "我相信真相终会破土而出，你呢？"
  },
  [111480679] = {
    id = 111480679,
    name = "她忽然心有灵犀地看了你一眼。"
  },
  [111480680] = {
    id = 111480680,
    name = "湖泊般的双眼再次弯成了一湾潺潺的月牙泉。"
  },
  [111480681] = {
    id = 111480681,
    name = "看来，你的答案和我一样。"
  },
  [111480682] = {
    id = 111480682,
    name = "她转身而去，忽然回过了头,风吹动她的长发，像温柔的涟漪。"
  },
  [111480683] = {
    id = 111480683,
    name = "虽然不舍，但还是要说再见了。"
  },
  [111480684] = {
    id = 111480684,
    name = "放心吧，我们还会再见的。"
  },
  [111480685] = {
    id = 111480685,
    name = "嗯，我也相信，我们终将重逢。"
  },
  [111470001] = {
    id = 111470001,
    name = "说我拈花惹草？"
  },
  [111470002] = {
    id = 111470002,
    name = "西缇丝，猎鹰只是临时探险的同伴，相信我，我的心里只有你。"
  },
  [111470003] = {
    id = 111470003,
    name = "我知道，我是你的负累。"
  },
  [111470004] = {
    id = 111470004,
    name = "不，不......"
  },
  [111470005] = {
    id = 111470005,
    name = "你不愿意和我一起冒险，我很伤心，但我也很理解你，可是你......你为什么一而再再而三都要抛下我。"
  },
  [111470006] = {
    id = 111470006,
    name = "西缇丝，你误会了！我是怕你有危险才没有带上你，实际上......"
  },
  [111470007] = {
    id = 111470007,
    name = "（唔，是情侣在吵架？）"
  },
  [111470008] = {
    id = 111470008,
    name = "你顺着声音看了过去，除了正在吵架的一男一女外，旁边还站了一个轻装持剑的女孩。"
  },
  [111470009] = {
    id = 111470009,
    name = "你这个说法简直......"
  },
  [111470010] = {
    id = 111470010,
    name = "我是真的为你着想才这么做的啊。"
  },
  [111470011] = {
    id = 111470011,
    name = "呵呵，嘴上说着离不开我，实际上和你冒险的却不是我......如果你不想和我继续交往，请光明正大地告诉我，而不是用这样的方式！"
  },
  [111470012] = {
    id = 111470012,
    name = "叫西缇丝的女孩跑开了。"
  },
  [111470013] = {
    id = 111470013,
    name = "喂，西缇丝，你听我说！唉！"
  },
  [111470014] = {
    id = 111470014,
    name = "抱歉啊，猎鹰，我们下次再一起去吧！"
  },
  [111470015] = {
    id = 111470015,
    name = "............"
  },
  [111470016] = {
    id = 111470016,
    name = "年轻的探险者匆匆离去。"
  },
  [111470017] = {
    id = 111470017,
    name = "啊，这下又缺人手了，我的计划......呼，算了，只有再重新找了。"
  },
  [111470018] = {
    id = 111470018,
    name = "她叹了一口气，转身看到了你。"
  },
  [111470019] = {
    id = 111470019,
    name = "咦，你是......探险者？"
  },
  [111470020] = {
    id = 111470020,
    name = "我路过。"
  },
  [111470021] = {
    id = 111470021,
    name = "那也是缘分啊，你要不要和我一起，我带你去个好地方？"
  },
  [111470022] = {id = 111470022, name = "......"},
  [111470023] = {
    id = 111470023,
    name = "抱歉，我没兴趣掺和进你们的......游戏。"
  },
  [111470024] = {
    id = 111470024,
    name = "游戏？喂喂，你是不是误会啦？这是他们两个的问题，和我没关系。"
  },
  [111470025] = {
    id = 111470025,
    name = "嗯，恋爱或者分手都是自由的，这些都是常有的事，我能理解。"
  },
  [111470026] = {
    id = 111470026,
    name = "哈？你在说什——唉，走了啊......算了，那去找找别人吧。"
  },
  [111470027] = {
    id = 111470027,
    name = "她看着你远去的身影，叹了口气。"
  },
  [111470028] = {
    id = 111470028,
    name = "喂，你看，又来一个找宝藏的吧？"
  },
  [111470029] = {
    id = 111470029,
    name = "我在这个据点待了一年多，就没见过这么热闹的时候。"
  },
  [111470030] = {
    id = 111470030,
    name = "（宝藏？）"
  },
  [111470031] = {
    id = 111470031,
    name = "你走进一家酒馆，找到了最后一张空桌。"
  },
  [111470032] = {
    id = 111470032,
    name = "一个人？"
  },
  [111470033] = {
    id = 111470033,
    name = "刚坐下，就有人站在了你的面前。"
  },
  [111470034] = {
    id = 111470034,
    name = "你也是来找宝藏的吧？"
  },
  [111470035] = {
    id = 111470035,
    name = "什么宝藏？"
  },
  [111470036] = {
    id = 111470036,
    name = "我还以为来这里的人都是听了宝藏的传闻过来的。"
  },
  [111470037] = {
    id = 111470037,
    name = "传闻？什么传闻？"
  },
  [111470038] = {
    id = 111470038,
    name = "......你竟然真的不知道啊？"
  },
  [111470039] = {
    id = 111470039,
    name = "不过你既然问了我，我就大发慈悲地告诉你。"
  },
  [111470040] = {id = 111470040, name = "......"},
  [111470041] = {
    id = 111470041,
    name = "多年前，一支神秘的探险队运送了一批货物，而这支探险队被魔物吃掉了，而那批货物，也从此失踪了。后来，有人发现了探险者的尸体，你猜猜在哪儿？"
  },
  [111470042] = {
    id = 111470042,
    name = "......这附近？"
  },
  [111470043] = {
    id = 111470043,
    name = "没错！那个人做了记号，绘制成了一张藏宝图！"
  },
  [111470044] = {
    id = 111470044,
    name = "............"
  },
  [111470045] = {
    id = 111470045,
    name = "兄弟，有兴趣一起寻宝吗？"
  },
  [111470046] = {
    id = 111470046,
    name = "既然那个人已经发现了，为什么不自己拿到宝藏？"
  },
  [111470047] = {id = 111470047, name = "......"},
  [111470048] = {id = 111470048, name = "......"},
  [111470049] = {id = 111470049, name = "......"},
  [111470050] = {
    id = 111470050,
    name = "我想到了！"
  },
  [111470051] = {id = 111470051, name = "？"},
  [111470052] = {
    id = 111470052,
    name = "连一支探险队都能灭掉的魔物一定很强！如果是我，也许会找够人手去试试。"
  },
  [111470053] = {
    id = 111470053,
    name = "不过，听说那个人卖藏宝图的时候把脸遮得严严实实，神神秘秘的，一定是有见不得人的原因！比如社交恐惧，或者说正在被人追杀......"
  },
  [111470054] = {id = 111470054, name = "......"},
  [111470055] = {
    id = 111470055,
    name = "你讲的故事挺精彩的。"
  },
  [111470056] = {
    id = 111470056,
    name = "欸嘿，大家都这么说！怎么样，你要不要跟我们一起寻宝？我看你也是一个人，不如——"
  },
  [111470057] = {
    id = 111470057,
    name = "不好意思，这个人我先看上的哦！"
  },
  [111470058] = {
    id = 111470058,
    name = "猎鹰凑了个脑袋，在桌边坐下了。"
  },
  [111470059] = {id = 111470059, name = "你——"},
  [111470060] = {id = 111470060, name = "嗯？"},
  [111470061] = {
    id = 111470061,
    name = "这把剑......你是荒野游骑兵的人啊......"
  },
  [111470062] = {
    id = 111470062,
    name = "对啊，找宝藏我最在行了，要加入我们吗？"
  },
  [111470063] = {
    id = 111470063,
    name = "不了，不了......"
  },
  [111470064] = {
    id = 111470064,
    name = "探险者退了两步，悻悻地离开了。"
  },
  [111470065] = {
    id = 111470065,
    name = "欸，不是人越多越好吗？"
  },
  [111470066] = {
    id = 111470066,
    name = "（......荒野游骑兵，那个最擅长寻宝的组织啊。）"
  },
  [111470067] = {
    id = 111470067,
    name = "咳咳，那个，我是专程来找你的。"
  },
  [111470068] = {id = 111470068, name = "找我？"},
  [111470069] = {
    id = 111470069,
    name = "我觉得你之前是不是误会了什么，那个人真的只是我找的临时同伴。"
  },
  [111470070] = {
    id = 111470070,
    name = "不过以我的直觉，你更适合做我的临时同伴！你不用担心报酬，宝物的分配都好商量。"
  },
  [111470071] = {
    id = 111470071,
    name = "我没有在意这个。这种大家都要争抢的东西，我不太感兴趣。"
  },
  [111470072] = {
    id = 111470072,
    name = "欸？为什么？一起寻宝才更安全，也更热闹吧！"
  },
  [111470073] = {
    id = 111470073,
    name = "（更安全吗？）"
  },
  [111470074] = {
    id = 111470074,
    name = "你摇了摇头。"
  },
  [111470075] = {
    id = 111470075,
    name = "你真的不想去？"
  },
  [111470076] = {
    id = 111470076,
    name = "你再次摇了摇头。"
  },
  [111470077] = {
    id = 111470077,
    name = "好吧好吧，真可惜啊。不过你要是改变主意了，记得来找我，藏宝图的地点就在据点北边的山林里。"
  },
  [111470078] = {
    id = 111470078,
    name = "你就这么把藏宝地告诉我了？"
  },
  [111470079] = {
    id = 111470079,
    name = "这也不是什么秘密啦，大家都知道。"
  },
  [111470080] = {id = 111470080, name = "......"},
  [111470081] = {
    id = 111470081,
    name = "记得呀，是我先约了你的。"
  },
  [111470082] = {
    id = 111470082,
    name = "......那我走了。"
  },
  [111470083] = {
    id = 111470083,
    name = "猎鹰三步一回头，又看了看你。"
  },
  [111470084] = {
    id = 111470084,
    name = "你不可以找别人哦！"
  },
  [111470085] = {id = 111470085, name = "......"},
  [111470086] = {
    id = 111470086,
    name = "（那边有什么声音？）"
  },
  [111470087] = {
    id = 111470087,
    name = "一阵沉闷的脚步声在远处逐渐清晰。"
  },
  [111470088] = {
    id = 111470088,
    name = "很多人......是在狩猎魔物吗？"
  },
  [111470089] = {
    id = 111470089,
    name = "——啊！！"
  },
  [111470090] = {
    id = 111470090,
    name = "人群中突然传来了凄厉地尖叫声，紧接着一只巨大的魔物轮廓远远的出现在你的视野中。"
  },
  [111470091] = {id = 111470091, name = "！！！"},
  [111470092] = {
    id = 111470092,
    name = "探险者们惊恐地向四周张望，呼喊声响彻郊野。"
  },
  [111470093] = {
    id = 111470093,
    name = "过来了！"
  },
  [111470094] = {
    id = 111470094,
    name = "人们如蝼蚁般穿过灌木与藤蔓，四散奔逃。"
  },
  [111470095] = {
    id = 111470095,
    name = "都往这边跑，快点快点！那边是据点，不要去！"
  },
  [111470096] = {
    id = 111470096,
    name = "但还是有人朝你的方向跑过来了，你看着那群人身后的魔物，正在评估着它的实力......"
  },
  [111470097] = {id = 111470097, name = "！！！"},
  [111470098] = {
    id = 111470098,
    name = "忽然，一股力量将你拉走！"
  },
  [111470099] = {
    id = 111470099,
    name = "是你？！"
  },
  [111470100] = {
    id = 111470100,
    name = "看什么看，快走啊！这里太危险了！"
  },
  [111470101] = {
    id = 111470101,
    name = "你甩了甩手，发现竟然没办法挣脱。"
  },
  [111470102] = {
    id = 111470102,
    name = "别乱动，先到安全的地方！"
  },
  [111470103] = {
    id = 111470103,
    name = "............"
  },
  [111470104] = {
    id = 111470104,
    name = "她带着你边跑边回头看。"
  },
  [111470105] = {
    id = 111470105,
    name = "哎呀呀，魔物朝我们追来了！这边不行，这边是据点！只能用第二套方案了！"
  },
  [111470106] = {
    id = 111470106,
    name = "第二......喂！"
  },
  [111470107] = {
    id = 111470107,
    name = "砰、砰、砰......魔物的脚步声越来越近。"
  },
  [111470108] = {
    id = 111470108,
    name = "又来了，又来了......它它它怎么总追着我们跑啊！"
  },
  [111470109] = {
    id = 111470109,
    name = "奔跑间隙，你看了眼身后，那群探险者已经离魔物远去，只有巨型的魔物还在死命追赶着你们。"
  },
  [111470110] = {
    id = 111470110,
    name = "它要追上来了！你在想什么，专心一点啦！"
  },
  [111470111] = {id = 111470111, name = "轰——"},
  [111470112] = {
    id = 111470112,
    name = "呜哇！！"
  },
  [111470113] = {
    id = 111470113,
    name = "魔物肢体狠狠砸了下来！你带着她一跃而起，躲过了这次攻击。"
  },
  [111470114] = {
    id = 111470114,
    name = "走这边，走这边！快到了，我在这里的安全基地！"
  },
  [111470115] = {
    id = 111470115,
    name = "什么——小心！"
  },
  [111470116] = {
    id = 111470116,
    name = "轰！！魔物再次袭至，猎鹰却慢了一步。"
  },
  [111470117] = {id = 111470117, name = "过来！"},
  [111470118] = {
    id = 111470118,
    name = "你将她拉至身后，长剑挥斩迎上！锵——"
  },
  [111470119] = {
    id = 111470119,
    name = "这个力量！"
  },
  [111470120] = {
    id = 111470120,
    name = "砰！猎鹰朝魔物洒出一把粉沫，魔物如同被烫到般，迅速缩了回去！"
  },
  [111470121] = {
    id = 111470121,
    name = "别硬抗，快过来！"
  },
  [111470122] = {
    id = 111470122,
    name = "猎鹰拽住你的手臂跑出了危险区。"
  },
  [111470123] = {
    id = 111470123,
    name = "呼，呼，在哪里！"
  },
  [111470124] = {
    id = 111470124,
    name = "她指着不远处的山壁，有一个小小的山洞。砰、砰、砰......"
  },
  [111470125] = {
    id = 111470125,
    name = "哎呀！怎么又追上来了？！"
  },
  [111470126] = {
    id = 111470126,
    name = "你们飞速躲入了山洞，魔物也随之而至！"
  },
  [111470127] = {
    id = 111470127,
    name = "锵！！一道凌厉的剑影划过，随着魔物一声痛苦的嘶吼，一截深入洞中的魔物肢体被猎鹰劈了下来！"
  },
  [111470128] = {
    id = 111470128,
    name = "啊啊啊完了，惹怒它了，快走快走！"
  },
  [111470129] = {
    id = 111470129,
    name = "猎鹰捡起魔物爪子，毫不恋战地拉着你跑！"
  },
  [111470130] = {
    id = 111470130,
    name = "吼！！！"
  },
  [111470131] = {
    id = 111470131,
    name = "轰、轰！！魔物身体太过庞大，无法挤入山洞，只能朝洞口怒吼猛撞，震得你脑袋嗡鸣。"
  },
  [111470132] = {
    id = 111470132,
    name = "它怎么把洞口撞碎了啊？！！"
  },
  [111470133] = {
    id = 111470133,
    name = "快跑，里面有个出口！！"
  },
  [111470134] = {
    id = 111470134,
    name = "一阵山摇地动，魔物更为猛烈地嘶吼了一声，冲着浑身伤痕也要撞过来！"
  },
  [111470135] = {
    id = 111470135,
    name = "你是不是跟它有仇？！"
  },
  [111470136] = {
    id = 111470136,
    name = "怎么可能，我——我想起来了！"
  },
  [111470137] = {
    id = 111470137,
    name = "猎鹰拿出了一块木头。"
  },
  [111470138] = {
    id = 111470138,
    name = "我从它老巢里拿的。"
  },
  [111470139] = {
    id = 111470139,
    name = "不朽古木......你可真胆大啊，拿了人家看家宝贝，不追着你才怪。"
  },
  [111470140] = {
    id = 111470140,
    name = "啊？我就是看这东西很值钱才——"
  },
  [111470141] = {
    id = 111470141,
    name = "不行，再值钱也不能要了！"
  },
  [111470142] = {
    id = 111470142,
    name = "猎鹰果断地将木头扔在身后。"
  },
  [111470143] = {id = 111470143, name = "你......"},
  [111470144] = {
    id = 111470144,
    name = "安全第一，安全第一！"
  },
  [111470145] = {
    id = 111470145,
    name = "吼！！！"
  },
  [111470146] = {
    id = 111470146,
    name = "魔物的撞击声还在继续，她拉着你跑向山洞深处的一处水潭。"
  },
  [111470147] = {
    id = 111470147,
    name = "你会游泳吧？不会也没关系，我会救你的！"
  },
  [111470148] = {
    id = 111470148,
    name = "你感到背后一阵推力，掉入了水潭。"
  },
  [111470149] = {
    id = 111470149,
    name = "猎鹰很快在水底抓住了你，顺着水流快速凫水，轻车熟路带你上了岸。"
  },
  [111470150] = {
    id = 111470150,
    name = "呼，这里安全了。"
  },
  [111470151] = {
    id = 111470151,
    name = "............"
  },
  [111470152] = {
    id = 111470152,
    name = "喂，你很厉害啊，之前挡下的那一剑很强，还有自保的能力也很好......来吧，跟我一起寻宝嘛！凭你一眼就认出宝贝的能力，去了藏宝地一定手到擒来！"
  },
  [111470153] = {id = 111470153, name = "......"},
  [111470154] = {
    id = 111470154,
    name = "寻宝是件危险的事，你不是——"
  },
  [111470155] = {
    id = 111470155,
    name = "放心吧，我一向谨慎！我已经做了几套周密的计划，对了，这次是其中一个。"
  },
  [111470156] = {
    id = 111470156,
    name = "你看，我的逃跑路线规划得不错吧~跟我一起，绝对不会让你受伤的！"
  },
  [111470157] = {
    id = 111470157,
    name = "猎鹰目光灼灼，黏湿的发落下水珠，你对上她的视线，看不清哪个更明亮。"
  },
  [111470158] = {id = 111470158, name = "......"},
  [111470159] = {id = 111470159, name = "好吧。"},
  [111470160] = {
    id = 111470160,
    name = "太好了！那我们接下来该好好准备了！这次寻宝我规划了好几条路线呢，是时候展示猎鹰真正的技术了！"
  },
  [111470161] = {
    id = 111470161,
    name = "符石、莹草、药水......让我想想还差些什么，都得买齐才好......"
  },
  [111470162] = {
    id = 111470162,
    name = "回到据点后，猎鹰就掰着指头数着物资，在出发之前做好万全的准备，是猎鹰的习惯。"
  },
  [111470163] = {
    id = 111470163,
    name = "等等，你带这么多垂头草做什么？"
  },
  [111470164] = {
    id = 111470164,
    name = "嗯哼，我自有用处啦。对了，你的武器需要维修吗？我知道一个靠谱的工匠——"
  },
  [111470165] = {id = 111470165, name = "啪——"},
  [111470166] = {id = 111470166, name = "！！！"},
  [111470167] = {
    id = 111470167,
    name = "一道响亮的耳光声传了过来，你听到女孩颤抖而委屈的哽咽声。"
  },
  [111470168] = {
    id = 111470168,
    name = "你真的很让我失望。"
  },
  [111470169] = {
    id = 111470169,
    name = "西缇丝......难道，我不可以有其他的朋友吗？"
  },
  [111470170] = {
    id = 111470170,
    name = "那你去找他们，请不要再来找我，我只会给你带来麻烦，不是吗？"
  },
  [111470171] = {
    id = 111470171,
    name = "她的眼泪大滴大滴落下，看起来像被抛弃了一样。"
  },
  [111470172] = {
    id = 111470172,
    name = "无理取闹，就算我有其他伙伴，你也不用生气成这样吧！"
  },
  [111470173] = {
    id = 111470173,
    name = "啊，让这么可爱的女孩子哭的家伙......"
  },
  [111470174] = {
    id = 111470174,
    name = "真是让人于心不忍啊，那家伙不值得啊......"
  },
  [111470175] = {
    id = 111470175,
    name = "喂，事情不是你们想的那样！西缇丝，你......"
  },
  [111470176] = {
    id = 111470176,
    name = "抱歉，我想通了。我想我们......不合适。"
  },
  [111470177] = {
    id = 111470177,
    name = "......你！你是要跟我分手吗？"
  },
  [111470178] = {
    id = 111470178,
    name = "是，虽然我很难过，难过得连站到这里都花了很大的力气，但是请我们放过彼此吧。"
  },
  [111470179] = {
    id = 111470179,
    name = "不，西缇丝我是喜欢你的......"
  },
  [111470180] = {
    id = 111470180,
    name = "可是你更喜欢你自己。"
  },
  [111470181] = {id = 111470181, name = "......"},
  [111470182] = {
    id = 111470182,
    name = "难道不是吗？"
  },
  [111470183] = {
    id = 111470183,
    name = "不，这是两回事，人都是自由的！"
  },
  [111470184] = {
    id = 111470184,
    name = "那你去寻找你的自由吧。"
  },
  [111470185] = {
    id = 111470185,
    name = "西缇丝......"
  },
  [111470186] = {
    id = 111470186,
    name = "西缇丝咬着唇盯着他，年轻的探险者不再挽留，转身而去。"
  },
  [111470187] = {
    id = 111470187,
    name = "这时西缇丝侧过眼，似乎朝你的方向看了一眼。"
  },
  [111470188] = {
    id = 111470188,
    name = "（嗯？）"
  },
  [111470189] = {
    id = 111470189,
    name = "啊，她朝我们过来了。"
  },
  [111470190] = {
    id = 111470190,
    name = "你......你们好。"
  },
  [111470191] = {
    id = 111470191,
    name = "她的脸上还有泪痕，却朝猎鹰微微笑了笑。"
  },
  [111470192] = {
    id = 111470192,
    name = "你好。那......那个西缇丝小姐是吧，你也不要太伤心了。"
  },
  [111470193] = {
    id = 111470193,
    name = "对于这样的结果，我早就预料到了......对不起，之前，因为我的任性......让你失去了一个临时同伴。"
  },
  [111470194] = {
    id = 111470194,
    name = "啊没关系，我已经找到新的搭档了。"
  },
  [111470195] = {
    id = 111470195,
    name = "猎鹰戳了戳你的手肘，示意你也安慰一下这个可怜的女孩。"
  },
  [111470196] = {id = 111470196, name = "......"},
  [111470197] = {
    id = 111470197,
    name = "是吗......"
  },
  [111470198] = {
    id = 111470198,
    name = "我还打算弥补我的过错，让我代替他，成为你的同伴。"
  },
  [111470199] = {
    id = 111470199,
    name = "西缇丝满含歉意地看着她。"
  },
  [111470200] = {
    id = 111470200,
    name = "我，我能加入你们吗？"
  },
  [111470201] = {
    id = 111470201,
    name = "啊？可是我们人手已经......"
  },
  [111470202] = {
    id = 111470202,
    name = "我不会给你们添麻烦的！"
  },
  [111470203] = {
    id = 111470203,
    name = "西缇丝抓着猎鹰的手，眼神若有似无地看向了你的方向。"
  },
  [111470204] = {
    id = 111470204,
    name = "拜托了，宝物我可以不要！我......我只是不想再一个人。"
  },
  [111470205] = {
    id = 111470205,
    name = "唔，那个......"
  },
  [111470206] = {
    id = 111470206,
    name = "我说，要不就让她一起吧？"
  },
  [111470207] = {
    id = 111470207,
    name = "......可以，多一个人，也多一个帮手。"
  },
  [111470208] = {
    id = 111470208,
    name = "（这个人有点奇怪，不知道有什么目的，放在眼底下，总比藏在暗处好）"
  },
  [111470209] = {
    id = 111470209,
    name = "西缇丝这时正眼看向了你，露出一个笑容。"
  },
  [111470210] = {
    id = 111470210,
    name = "你好，我叫西缇丝，以后......请多多指教。"
  },
  [111470211] = {
    id = 111470211,
    name = "我听说治疗被感情伤害最好的办法，就是投入到新的感情——哦不，是新的事业里！只要有足够的事做，你就不会去想那个男人啦！"
  },
  [111470212] = {
    id = 111470212,
    name = "......嗯。"
  },
  [111470213] = {
    id = 111470213,
    name = "没错，我看看你还需要准备些什么......"
  },
  [111470214] = {
    id = 111470214,
    name = "猎鹰兴冲冲地带着西缇丝筹备物资。"
  },
  [111470215] = {
    id = 111470215,
    name = "差不多了，猎鹰临时寻宝小队，出发！"
  },
  [111470216] = {
    id = 111470216,
    name = "到了到了，这个曾经让我狼狈不堪的森林。"
  },
  [111470217] = {
    id = 111470217,
    name = "你们再次回到了巨型魔物栖息地的附近森林里。"
  },
  [111470218] = {
    id = 111470218,
    name = "走了一路也有些累了，就在这里休息一会儿吧！"
  },
  [111470219] = {
    id = 111470219,
    name = "咦，西缇丝~你在做什么呢，快过来。"
  },
  [111470220] = {
    id = 111470220,
    name = "嗯，我怕大家劳累口渴，准备了一些果子。"
  },
  [111470221] = {
    id = 111470221,
    name = "猎鹰抓起了一个，毫无戒备地咬了一口。"
  },
  [111470222] = {
    id = 111470222,
    name = "啊啊，生津止渴，感觉疲惫都消除了，西缇丝你真好！"
  },
  [111470223] = {
    id = 111470223,
    name = "呵呵，先生，你也尝一块吧。"
  },
  [111470224] = {id = 111470224, name = "......"},
  [111470225] = {
    id = 111470225,
    name = "你靠坐在树边，这时西缇丝走过来缓缓蹲下，捧起果子仰望着你，眼神闪动了一下。"
  },
  [111470226] = {id = 111470226, name = "先生？"},
  [111470227] = {
    id = 111470227,
    name = "她微微扬起嘴角，脸带笑意。"
  },
  [111470228] = {
    id = 111470228,
    name = "我不用了，谢谢。"
  },
  [111470229] = {
    id = 111470229,
    name = "这样啊，啊——"
  },
  [111470230] = {
    id = 111470230,
    name = "她打算起身，脚下一个踉跄，眼看就要栽在你身上！"
  },
  [111470231] = {id = 111470231, name = "！！"},
  [111470232] = {id = 111470232, name = "！！！"},
  [111470233] = {
    id = 111470233,
    name = "西缇丝笑着闭上了眼睛，却没有落入你的怀抱。"
  },
  [111470234] = {id = 111470234, name = "嗯？"},
  [111470235] = {id = 111470235, name = "！！！"},
  [111470236] = {
    id = 111470236,
    name = "你后退了一步，西缇丝闭着眼睛，眼看就要栽倒在地。"
  },
  [111470237] = {id = 111470237, name = "？？？"},
  [111470238] = {
    id = 111470238,
    name = "哎呀，你怎么这么不小心啊？"
  },
  [111470239] = {
    id = 111470239,
    name = "猎鹰及时拉住了西缇丝，西缇丝眼神复杂地看向猎鹰。"
  },
  [111470240] = {
    id = 111470240,
    name = "刚刚好像踩到了什么，所以......"
  },
  [111470241] = {
    id = 111470241,
    name = "嗯嗯，还好我拉住了你呢。"
  },
  [111470242] = {
    id = 111470242,
    name = "谢，谢，你，呢。"
  },
  [111470243] = {
    id = 111470243,
    name = "不用客气，大家都是同伴嘛~他不吃你的果子，我帮你吃呀！"
  },
  [111470244] = {
    id = 111470244,
    name = "猎鹰拿走了西缇丝给你准备的果子。"
  },
  [111470245] = {id = 111470245, name = "......"},
  [111470246] = {
    id = 111470246,
    name = "那先生想吃点别的什么呢？一路来都是你们在杀魔物......我想做点什么，感谢你、你们保护了我。"
  },
  [111470247] = {
    id = 111470247,
    name = "那些都是小事啦！"
  },
  [111470248] = {
    id = 111470248,
    name = "猎鹰啃了一口果子。"
  },
  [111470249] = {
    id = 111470249,
    name = "话说回来，既然已经快到宝藏点了，那就来安排作战计划吧，指挥官！"
  },
  [111470250] = {
    id = 111470250,
    name = "指挥官？"
  },
  [111470251] = {
    id = 111470251,
    name = "是你哦，我只有寻宝和逃跑的经验，团体作战的话，只有交给你这种有经验的探险者来做吧~"
  },
  [111470252] = {
    id = 111470252,
    name = "她把果子含在嘴里，拿起一根树枝在地上画出一条条路。"
  },
  [111470253] = {
    id = 111470253,
    name = "这就是藏宝地附近的路线了。下命令吧，指挥官！"
  },
  [111470254] = {
    id = 111470254,
    name = "............"
  },
  [111470255] = {
    id = 111470255,
    name = "你无奈地同意了，一边思考，一边安排防守和撤退，诱导和陷阱......"
  },
  [111470256] = {
    id = 111470256,
    name = "............"
  },
  [111470257] = {
    id = 111470257,
    name = "而在此期间，你一直感觉到西缇丝的目光，那道目光在你身上缠绕流转，流露着隐秘的心思。"
  },
  [111470258] = {
    id = 111470258,
    name = "（一路上她总是这样......西缇丝到底有什么目的？）"
  },
  [111470259] = {
    id = 111470259,
    name = "那么这几个陷阱的投放，谁去呢？"
  },
  [111470260] = {
    id = 111470260,
    name = "西缇丝吧。"
  },
  [111470261] = {
    id = 111470261,
    name = "我，我吗？"
  },
  [111470262] = {
    id = 111470262,
    name = "按照作战计划，我去引走魔物，猎鹰趁机去拿宝物，我将魔物引到这一处的陷阱里之后，和西缇丝在这里等猎鹰汇合。"
  },
  [111470263] = {
    id = 111470263,
    name = "哦哦，这个我擅长，没问题！"
  },
  [111470264] = {
    id = 111470264,
    name = "引诱魔物这么危险的事，先生一个人去吗？或者猎鹰小姐......"
  },
  [111470265] = {
    id = 111470265,
    name = "是哦，上次我们差点跑不掉呢，要不你和西缇丝一起，她手里的陷阱道具至少还能保命~"
  },
  [111470266] = {
    id = 111470266,
    name = "西缇丝一愣，咬了咬唇。"
  },
  [111470267] = {
    id = 111470267,
    name = "我......我实力不济，怕会成指挥官的拖累，不能因为指挥官保护我而受伤......"
  },
  [111470268] = {
    id = 111470268,
    name = "身为指挥官，保护同伴是应该的。"
  },
  [111470269] = {
    id = 111470269,
    name = "噢噢，不愧是指挥官，有担当！"
  },
  [111470270] = {
    id = 111470270,
    name = "............"
  },
  [111470271] = {
    id = 111470271,
    name = "所以，你要去吗？"
  },
  [111470272] = {
    id = 111470272,
    name = "西缇丝深吸一口气，露出无害的表情。"
  },
  [111470273] = {
    id = 111470273,
    name = "刚才我也是担心你才有顾虑......不过我相信，指挥官会有最好的安排。"
  },
  [111470274] = {
    id = 111470274,
    name = "呵呵，那就按原计划，我一个人去引魔物就够了。大家没有异议吧？"
  },
  [111470275] = {id = 111470275, name = "赞成！"},
  [111470276] = {
    id = 111470276,
    name = "好，我知道了。"
  },
  [111470277] = {
    id = 111470277,
    name = "西缇丝朝你笑了笑。"
  },
  [111470278] = {
    id = 111470278,
    name = "（又来了，那种诡异的感觉......）那就出发吧。"
  },
  [111470279] = {
    id = 111470279,
    name = "这个大大的山洞就是藏宝地啦，同时，这也是一只巨型魔物的老巢。"
  },
  [111470280] = {
    id = 111470280,
    name = "巨型魔物？！"
  },
  [111470281] = {
    id = 111470281,
    name = "进去的时候小心点，在没找到宝藏前，尽量不要惊动它。"
  },
  [111470282] = {id = 111470282, name = "了解~！"},
  [111470283] = {
    id = 111470283,
    name = "猎鹰拿出了一袋东西递给了西缇丝。"
  },
  [111470284] = {
    id = 111470284,
    name = "魔法炸弹，门口一边放上一个，就能困住魔物了！"
  },
  [111470285] = {
    id = 111470285,
    name = "嗯，你们放心进去吧，我会在这里放好陷阱的。"
  },
  [111470286] = {
    id = 111470286,
    name = "嗯嗯，这袋炸弹威力很大的，遇上魔物就扔上去，保你平安。记住，安全第一，安全第一哦！"
  },
  [111470287] = {
    id = 111470287,
    name = "你与猎鹰进入了大型山洞，感觉到身后火热的视线一直注视着你，你回头看去，西缇丝温婉地笑着，和你们招了招手。"
  },
  [111470288] = {
    id = 111470288,
    name = "快过来，指挥官！这边有岔道。根据藏宝图，我们应该走......这边！"
  },
  [111470289] = {
    id = 111470289,
    name = "山洞里寸草不生，魔物的划痕在山壁肆虐。"
  },
  [111470290] = {
    id = 111470290,
    name = "啊，这里有好多低级魔物的尸体！"
  },
  [111470291] = {
    id = 111470291,
    name = "看来那只魔物在这里蛰伏很长的时间了。"
  },
  [111470292] = {
    id = 111470292,
    name = "有宝藏一定会好好守着，是魔物常有的习性啊~"
  },
  [111470293] = {
    id = 111470293,
    name = "你与猎鹰一路摸索，到了山洞深处。"
  },
  [111470294] = {
    id = 111470294,
    name = "（小声）就在前面了。喂，你一会儿就——"
  },
  [111470295] = {id = 111470295, name = "嗯？"},
  [111470296] = {
    id = 111470296,
    name = "猎鹰凑到你面前，忽然抬起了手。"
  },
  [111470297] = {
    id = 111470297,
    name = "干什么？"
  },
  [111470298] = {
    id = 111470298,
    name = "躲什么，你脸花啦，帮你擦一下灰尘！"
  },
  [111470299] = {
    id = 111470299,
    name = "你站在原地默不作声，感受到温热柔滑的指腹触碰到了你的脸。"
  },
  [111470300] = {id = 111470300, name = "吼——"},
  [111470301] = {id = 111470301, name = "！！！"},
  [111470302] = {
    id = 111470302,
    name = "魔物来了，按计划行事！"
  },
  [111470303] = {
    id = 111470303,
    name = "作战就开始了？！那，那你小心点啊！"
  },
  [111470304] = {
    id = 111470304,
    name = "猎鹰快速地躲起来，藏进了最近的一个岔道。"
  },
  [111470305] = {
    id = 111470305,
    name = "吼！！！"
  },
  [111470306] = {
    id = 111470306,
    name = "空气中传来腐烂浊湿的气息，夹杂着岩洞里的粉尘。"
  },
  [111470307] = {id = 111470307, name = "来吧。"},
  [111470308] = {
    id = 111470308,
    name = "你布好了魔法阵，等着魔物自投罗网，很快，你看到了一个巨大的身影快速靠近。"
  },
  [111470309] = {id = 111470309, name = "吼！"},
  [111470310] = {
    id = 111470310,
    name = "不出意外地，魔物被困在了魔法阵里。"
  },
  [111470311] = {
    id = 111470311,
    name = "接下来，就是竞速时间。"
  },
  [111470312] = {
    id = 111470312,
    name = "你转身就跑。"
  },
  [111470313] = {
    id = 111470313,
    name = "（必须在魔物挣脱之前，到达洞口，否则——）"
  },
  [111470314] = {
    id = 111470314,
    name = "西缇丝？！"
  },
  [111470315] = {id = 111470315, name = "先生！"},
  [111470316] = {
    id = 111470316,
    name = "怎么是你？你怎么来了？！"
  },
  [111470317] = {
    id = 111470317,
    name = "我看你们很久没回来，担心——"
  },
  [111470318] = {id = 111470318, name = "吼！"},
  [111470319] = {
    id = 111470319,
    name = "没时间了，快走！"
  },
  [111470320] = {
    id = 111470320,
    name = "你沉下脸色，拉着赶来的西缇丝尽快脱身。"
  },
  [111470321] = {
    id = 111470321,
    name = "陷阱布置好了吗？"
  },
  [111470322] = {
    id = 111470322,
    name = "好、好了！"
  },
  [111470323] = {
    id = 111470323,
    name = "轰！！魔物的肢体砸了过来！"
  },
  [111470324] = {
    id = 111470324,
    name = "砰！一个魔法炸弹飞出，炸响了山壁！几块碎石落下，掩埋了小半条路。"
  },
  [111470325] = {
    id = 111470325,
    name = "你在做什么？！"
  },
  [111470326] = {
    id = 111470326,
    name = "我看它要伤到你——"
  },
  [111470327] = {id = 111470327, name = "吼！"},
  [111470328] = {
    id = 111470328,
    name = "对、对不起，它好像被我激怒了......"
  },
  [111470329] = {id = 111470329, name = "先走！"},
  [111470330] = {
    id = 111470330,
    name = "魔物一路的追击被你挡下，这一次没有猎鹰与你的配合，你与西缇丝逃出山洞时，两人都狼狈不堪。"
  },
  [111470331] = {
    id = 111470331,
    name = "快启用陷阱。"
  },
  [111470332] = {
    id = 111470332,
    name = "好......好！"
  },
  [111470333] = {
    id = 111470333,
    name = "西缇丝拿出一块魔法石，手微微颤抖。"
  },
  [111470334] = {id = 111470334, name = "我来！"},
  [111470335] = {
    id = 111470335,
    name = "你拿过魔法石，放在猎鹰交给西缇丝的启动机关上。"
  },
  [111470336] = {
    id = 111470336,
    name = "轰隆隆——"
  },
  [111470337] = {
    id = 111470337,
    name = "怎么回事？！！"
  },
  [111470338] = {
    id = 111470338,
    name = "地面传来一道又一道能量，晃动得你几乎站不稳，西缇丝紧紧抓住了你的手臂，声音发颤。"
  },
  [111470339] = {
    id = 111470339,
    name = "我看里面有很多陷阱，就......全放下去了......"
  },
  [111470340] = {
    id = 111470340,
    name = "猎鹰不是说只放两个吗，否则——"
  },
  [111470341] = {id = 111470341, name = "吼！"},
  [111470342] = {
    id = 111470342,
    name = "魔物已经近在眼前，此时被一张无形的网束缚，在它四周，大量的岩石和土壤开始崩落，巨大的裂缝迅速蔓延，向着山洞扩展，咔嚓——"
  },
  [111470343] = {
    id = 111470343,
    name = "坚固的岩壁碎裂了。"
  },
  [111470344] = {
    id = 111470344,
    name = "危险，快走！"
  },
  [111470345] = {
    id = 111470345,
    name = "！！！（猎鹰还在里面！）"
  },
  [111470346] = {
    id = 111470346,
    name = "西缇丝想拉着你离开，你回头看了她一眼。"
  },
  [111470347] = {id = 111470347, name = "......"},
  [111470348] = {
    id = 111470348,
    name = "她似乎被你锐利的目光镇住了，吓得一动不动。"
  },
  [111470349] = {
    id = 111470349,
    name = "你走吧，我得去救人。"
  },
  [111470350] = {
    id = 111470350,
    name = "不行，里面太危险了，猎鹰说不定已经......"
  },
  [111470351] = {
    id = 111470351,
    name = "也许她正在等我们救她。"
  },
  [111470352] = {
    id = 111470352,
    name = "可山洞还在塌陷，魔物也随时会挣脱——"
  },
  [111470353] = {
    id = 111470353,
    name = "吼吼！！！"
  },
  [111470354] = {id = 111470354, name = "！！！"},
  [111470355] = {
    id = 111470355,
    name = "砰砰砰！！束缚魔物的网一根根地绷断，西缇丝眼中的恐惧升腾，此刻一个人影跳了出来，满身的烟尘碎石。"
  },
  [111470356] = {
    id = 111470356,
    name = "呜哇！！！"
  },
  [111470357] = {
    id = 111470357,
    name = "猎鹰！！"
  },
  [111470358] = {id = 111470358, name = "！！！"},
  [111470359] = {
    id = 111470359,
    name = "快走快走！这个陷阱管不了多久的！"
  },
  [111470360] = {
    id = 111470360,
    name = "猎鹰带着你们变着方向跑，身后是巨型魔物的咆哮声。"
  },
  [111470361] = {
    id = 111470361,
    name = "呼、呼、幸好我有准备！指挥官，快跟我来！"
  },
  [111470362] = {
    id = 111470362,
    name = "呼......呼......总算......活下来了......"
  },
  [111470363] = {
    id = 111470363,
    name = "............"
  },
  [111470364] = {
    id = 111470364,
    name = "呼，你逃命的手段还真多......"
  },
  [111470365] = {
    id = 111470365,
    name = "当然......当然了......必须准备万全，才能......呼......才能迎接未知的危机......"
  },
  [111470366] = {
    id = 111470366,
    name = "哈......安全第一嘛......"
  },
  [111470367] = {
    id = 111470367,
    name = "你忍不住笑了笑，看向西缇丝时，她正垂着头，眼尾下拉着，一副泫然欲泣的模样。"
  },
  [111470368] = {id = 111470368, name = "喂！"},
  [111470369] = {
    id = 111470369,
    name = "猎鹰拍了拍她的肩。"
  },
  [111470370] = {
    id = 111470370,
    name = "吓到了吧？说实话，我也是第一次见那种魔物，幸好把它困在我早准备的沼泽陷阱里。"
  },
  [111470371] = {
    id = 111470371,
    name = "猎鹰长舒了一口气，又转而振奋起来。"
  },
  [111470372] = {
    id = 111470372,
    name = "对了，我已经找到了宝藏的踪迹啦！山洞深处有一大堆神秘的箱子呢，不过当时情况那么危急，只能先保命要紧了。等我们休息得差不多了，再折回去拿宝藏吧！"
  },
  [111470373] = {
    id = 111470373,
    name = "不着急，我想，西缇丝小姐有话和你说呢。"
  },
  [111470374] = {
    id = 111470374,
    name = "西缇丝身体微颤，咬着唇抬头朝猎鹰看去。"
  },
  [111470375] = {id = 111470375, name = "什么？"},
  [111470376] = {
    id = 111470376,
    name = "那......那个......猎鹰小姐，对、对不起......"
  },
  [111470377] = {
    id = 111470377,
    name = "哈？为什么要道歉？"
  },
  [111470378] = {
    id = 111470378,
    name = "我刚才......把陷阱都用了，差一点害死了你......我......我不是有意的，我只是——"
  },
  [111470379] = {
    id = 111470379,
    name = "说起这个！"
  },
  [111470380] = {
    id = 111470380,
    name = "西缇丝捏紧了手指，神色紧张。"
  },
  [111470381] = {
    id = 111470381,
    name = "幸好你把陷阱全都布置了！没想到那只魔物那么大力气，如果不是你及时变通，我真的要被魔物给踩死了。谢谢你啊，西缇丝！"
  },
  [111470382] = {
    id = 111470382,
    name = "西缇丝张了张嘴，露出羞愧的表情。"
  },
  [111470383] = {
    id = 111470383,
    name = "不......我，我还炸碎了山洞里的通路......猎鹰小姐，我一时失手......"
  },
  [111470384] = {
    id = 111470384,
    name = "一时失手？"
  },
  [111470385] = {id = 111470385, name = "！！！"},
  [111470386] = {
    id = 111470386,
    name = "你的声音并不大，但存在感极强。西缇丝深吸一口气，正犹豫是否坦白，猎鹰却笑了。"
  },
  [111470387] = {
    id = 111470387,
    name = "哈哈哈......你以为我会拿着宝物自己逃走吗？我荒野游骑兵绝对不会抛下任何一个同伴！所以，你是在为这个生气，才炸了山洞？"
  },
  [111470388] = {
    id = 111470388,
    name = "是啊，我也想知道，是什么原因。"
  },
  [111470389] = {
    id = 111470389,
    name = "你好整以暇地看着西缇丝，她却缓缓走向你的身边。"
  },
  [111470390] = {
    id = 111470390,
    name = "先生，对不起......"
  },
  [111470391] = {
    id = 111470391,
    name = "西缇丝的声音暴露了她恐惧的心神。"
  },
  [111470392] = {
    id = 111470392,
    name = "请，请原谅我......"
  },
  [111470393] = {
    id = 111470393,
    name = "猎鹰看了看你们两人，神色坦然。"
  },
  [111470394] = {
    id = 111470394,
    name = "唔，别让可爱女孩露出这样可怜的表情嘛~至少这次计划不是一无所获啊。"
  },
  [111470395] = {
    id = 111470395,
    name = "......你该求得原谅的不是我。"
  },
  [111470396] = {
    id = 111470396,
    name = "西缇丝的眼睫颤了颤，露出歉意的神色。"
  },
  [111470397] = {
    id = 111470397,
    name = "猎鹰小姐，我知道错了，我不该那样做，是我一时糊涂......我......"
  },
  [111470398] = {
    id = 111470398,
    name = "......不用说哦，我知道的。"
  },
  [111470399] = {
    id = 111470399,
    name = "西缇丝猛然抬头，看着猎鹰笑意的脸。"
  },
  [111470400] = {
    id = 111470400,
    name = "你喜欢指挥官是吗？"
  },
  [111470401] = {id = 111470401, name = "！！！"},
  [111470402] = {
    id = 111470402,
    name = "......？？"
  },
  [111470403] = {
    id = 111470403,
    name = "也对，指挥官这么好又这么强，被人喜欢那是一定的。不过之前我说治疗伤痛是投入另一段感情什么的，你竟然还当真了啊。"
  },
  [111470404] = {
    id = 111470404,
    name = "......猎鹰小姐，没有想过自己的未来吗？"
  },
  [111470405] = {
    id = 111470405,
    name = "有啊，未来我要找更多的宝物，让荒野游骑兵的名号，响彻整个深渊！"
  },
  [111470406] = {
    id = 111470406,
    name = "猎鹰小姐真是从容，难怪你这么受人欢迎......"
  },
  [111470407] = {
    id = 111470407,
    name = "啊？是吗......"
  },
  [111470408] = {
    id = 111470408,
    name = "我的愿望很简单......也很奢侈......我只是想找一个可以依靠的人，一起探险，一起生活......"
  },
  [111470409] = {
    id = 111470409,
    name = "指挥官在这方面，是我的理想型。"
  },
  [111470410] = {
    id = 111470410,
    name = "诶，等等！他是我先看上的啊！"
  },
  [111470411] = {id = 111470411, name = "？？？"},
  [111470412] = {
    id = 111470412,
    name = "噗，猎鹰小姐说的，和我不是一件事呢。"
  },
  [111470413] = {
    id = 111470413,
    name = "总之，先生是我遇到过最难对付的男人了，好像随随便便能看透一个人，让我失去自信。"
  },
  [111470414] = {id = 111470414, name = "......"},
  [111470415] = {
    id = 111470415,
    name = "难对付？他很好啊~！懂得保护队友，还陪我寻宝，真的很可靠呢。"
  },
  [111470416] = {id = 111470416, name = "......"},
  [111470417] = {
    id = 111470417,
    name = "呵呵，和他无关，是我自己自作多情，抱歉了，我会好好离开的。"
  },
  [111470418] = {
    id = 111470418,
    name = "嗯？你要走？不行不行，我全新的作战计划里包含了你呢！"
  },
  [111470419] = {
    id = 111470419,
    name = "我......还能继续留下吗？"
  },
  [111470420] = {
    id = 111470420,
    name = "当然！难道要像你的前男友一样，又丢下你不管吗？那可不是我辉煌骑士猎鹰会做的事~"
  },
  [111470421] = {
    id = 111470421,
    name = "指挥官，你说呢？"
  },
  [111470422] = {
    id = 111470422,
    name = "那就出发吧，顺便说说你新的计划。"
  },
  [111470423] = {
    id = 111470423,
    name = "......谢，谢谢你们。"
  },
  [111470424] = {
    id = 111470424,
    name = "猎鹰临时寻宝小队，再次出发！"
  },
  [111470425] = {
    id = 111470425,
    name = "哎呀呀，竟然被人捷足先登了！"
  },
  [111470426] = {
    id = 111470426,
    name = "行至半路，猎鹰用手扒拉着路面的痕迹。"
  },
  [111470427] = {
    id = 111470427,
    name = "少说也有十几个人，还有一辆木质的推车......从碾压情况看，应该搭载了很重的货物......完了，宝物真的被运走了！"
  },
  [111470428] = {
    id = 111470428,
    name = "魔物还被困在沼泽陷阱里。"
  },
  [111470429] = {
    id = 111470429,
    name = "啊，那些家伙，趁我们把魔物引走截胡了！"
  },
  [111470430] = {
    id = 111470430,
    name = "那我们还去山洞吗？"
  },
  [111470431] = {
    id = 111470431,
    name = "猎鹰看向了你。"
  },
  [111470432] = {
    id = 111470432,
    name = "不用了，我们顺着车轮印记找一找吧。"
  },
  [111470433] = {
    id = 111470433,
    name = "唔，如果他们拿了，可不好办啦~"
  },
  [111470434] = {
    id = 111470434,
    name = "这是你们豁出性命才获得的宝藏，本就应该是你们的吧。"
  },
  [111470435] = {
    id = 111470435,
    name = "是我们，我们三个的。不过麻烦就在这里呀，那些宝藏没人看守，也没有人看见是我们制住了魔物。"
  },
  [111470436] = {
    id = 111470436,
    name = "这样过去说宝物就是我们的，就像是抢劫一样~就算有理，也说不通了。"
  },
  [111470437] = {
    id = 111470437,
    name = "先过去看看吧，一切还是未知数。"
  },
  [111470438] = {id = 111470438, name = "也对。"},
  [111470439] = {
    id = 111470439,
    name = "同一时间，森林深处。"
  },
  [111470440] = {
    id = 111470440,
    name = "小心点啊，你们几个！"
  },
  [111470441] = {
    id = 111470441,
    name = "哇，这些箱子真重啊！"
  },
  [111470442] = {
    id = 111470442,
    name = "有宝藏拿还抱怨个啥？"
  },
  [111470443] = {
    id = 111470443,
    name = "嘿嘿，还是你厉害啊！竟然发现了那只魔物不在的空档时间。"
  },
  [111470444] = {
    id = 111470444,
    name = "哼，我也是随便进去看看，本来想和那只魔物大战一场，现在它不用死了，算它走运！"
  },
  [111470445] = {
    id = 111470445,
    name = "得了吧，谁没见过你上次进山洞腿在发抖啊~"
  },
  [111470446] = {
    id = 111470446,
    name = "嘁，我怕的是山洞突然塌了，果然被我猜中了，这次塌得可真厉害啊，那小石头还不停地往我头上掉呢！"
  },
  [111470447] = {
    id = 111470447,
    name = "砰！探险者打开了一个沉重的木箱。"
  },
  [111470448] = {
    id = 111470448,
    name = "让我看看里面有什——"
  },
  [111470449] = {
    id = 111470449,
    name = "欸，怎么是四个木桶？"
  },
  [111470450] = {
    id = 111470450,
    name = "咦，我这边也是两个木桶......"
  },
  [111470451] = {
    id = 111470451,
    name = "等等，这是什么味道？"
  },
  [111470452] = {
    id = 111470452,
    name = "是木桶里发出来的......"
  },
  [111470453] = {
    id = 111470453,
    name = "难道是前辈藏起来的特殊药物？"
  },
  [111470454] = {
    id = 111470454,
    name = "也有可能是魔法师的珍贵魔药~"
  },
  [111470455] = {
    id = 111470455,
    name = "唔，这个味道，为什么我有点熟悉......"
  },
  [111470456] = {
    id = 111470456,
    name = "我......我有点晕，会不会是毒药？"
  },
  [111470457] = {
    id = 111470457,
    name = "老大，这些箱子里，全都是木桶啊！"
  },
  [111470458] = {
    id = 111470458,
    name = "什么？我看看！"
  },
  [111470459] = {
    id = 111470459,
    name = "我，我有一种不好的预感。"
  },
  [111470460] = {
    id = 111470460,
    name = "我也是......"
  },
  [111470461] = {
    id = 111470461,
    name = "我，也是。"
  },
  [111470462] = {
    id = 111470462,
    name = "老大，开不开木桶？"
  },
  [111470463] = {
    id = 111470463,
    name = "开啊，怎么不开？！这辛苦搬出来的东西，是骡子是马总要看看吧？"
  },
  [111470464] = {id = 111470464, name = "开！"},
  [111470465] = {id = 111470465, name = "好！"},
  [111470466] = {
    id = 111470466,
    name = "领头人走到了那装木桶箱子前。"
  },
  [111470467] = {
    id = 111470467,
    name = "老子要开了，你们看清楚了！"
  },
  [111470468] = {
    id = 111470468,
    name = "哐啷！木桶的一角被斩破，从中流出了暗红色的液体......"
  },
  [111470469] = {
    id = 111470469,
    name = "这这这是——"
  },
  [111470470] = {id = 111470470, name = "血？"},
  [111470471] = {
    id = 111470471,
    name = "后脑勺被打了一下。"
  },
  [111470472] = {
    id = 111470472,
    name = "看清楚，是酒！还是他妈的葡萄酒。"
  },
  [111470473] = {
    id = 111470473,
    name = "酒是什么，值钱吗？"
  },
  [111470474] = {
    id = 111470474,
    name = "唉，要是放在地面咱们就发了，深渊里......值不了几个钱。"
  },
  [111470475] = {
    id = 111470475,
    name = "啊？白高兴一场啊，可是这是前辈们留下的酒欸......"
  },
  [111470476] = {
    id = 111470476,
    name = "对啊，这是精英探险者留下的酒啊......"
  },
  [111470477] = {
    id = 111470477,
    name = "唔........."
  },
  [111470478] = {
    id = 111470478,
    name = "沙沙，沙沙——"
  },
  [111470479] = {
    id = 111470479,
    name = "什么人？！"
  },
  [111470480] = {
    id = 111470480,
    name = "找到了，找到了，真的在这里！"
  },
  [111470481] = {
    id = 111470481,
    name = "他们已经......"
  },
  [111470482] = {
    id = 111470482,
    name = "（什么味道？酒？）"
  },
  [111470483] = {
    id = 111470483,
    name = "欸，是你啊。"
  },
  [111470484] = {id = 111470484, name = "对啊。"},
  [111470485] = {
    id = 111470485,
    name = "猎鹰，这些就是我们的宝藏吗？"
  },
  [111470486] = {
    id = 111470486,
    name = "不对哦，这位可爱的小姐，这是我们的宝藏。"
  },
  [111470487] = {
    id = 111470487,
    name = "西缇丝抬头眨了眨眼，一脸无辜。"
  },
  [111470488] = {
    id = 111470488,
    name = "可是，确实是我们的啊~"
  },
  [111470489] = {
    id = 111470489,
    name = "小姐，不管这些宝藏值不值钱，但总要有个先来后到吧？你说是你的，有什么理由吗？"
  },
  [111470490] = {
    id = 111470490,
    name = "因为是我们的指挥官引走了魔物啊~"
  },
  [111470491] = {
    id = 111470491,
    name = "西缇丝回头朝你笑了笑。"
  },
  [111470492] = {id = 111470492, name = "......"},
  [111470493] = {
    id = 111470493,
    name = "哦哦，难怪魔物没在巢穴里。"
  },
  [111470494] = {
    id = 111470494,
    name = "那魔物在哪儿？"
  },
  [111470495] = {
    id = 111470495,
    name = "被猎鹰制伏了哦~是吧，猎鹰。"
  },
  [111470496] = {
    id = 111470496,
    name = "也不算制伏啦，只是关在沼泽陷阱里了。"
  },
  [111470497] = {
    id = 111470497,
    name = "原来是这样......"
  },
  [111470498] = {
    id = 111470498,
    name = "那这些“宝藏”还真的是他们的啊，老大。"
  },
  [111470499] = {
    id = 111470499,
    name = "咳咳，嗯。说得不错，既然你们出了那么大力气，那这些宝藏，也有你们的一份。"
  },
  [111470500] = {
    id = 111470500,
    name = "这么大方？"
  },
  [111470501] = {
    id = 111470501,
    name = "真的？你们都是好人啊！"
  },
  [111470502] = {id = 111470502, name = "......"},
  [111470503] = {id = 111470503, name = "......"},
  [111470504] = {
    id = 111470504,
    name = "老大，这酒怎么分啊？！"
  },
  [111470505] = {id = 111470505, name = "酒？"},
  [111470506] = {
    id = 111470506,
    name = "分什么分，直接喝了吧！"
  },
  [111470507] = {
    id = 111470507,
    name = "好啊！我还没喝过葡萄酒呢！这玩意儿只有贵族才有资格享用吧？！"
  },
  [111470508] = {
    id = 111470508,
    name = "那大家今天都做一天贵族！"
  },
  [111470509] = {
    id = 111470509,
    name = "酒味随着木桶的完全敞开飘香四溢。"
  },
  [111470510] = {
    id = 111470510,
    name = "（这个酒味......没问题吧？）"
  },
  [111470511] = {
    id = 111470511,
    name = "让我尝尝！"
  },
  [111470512] = {
    id = 111470512,
    name = "怎么样，是什么味道啊？"
  },
  [111470513] = {
    id = 111470513,
    name = "兴奋的探险者神色变幻多彩，最后闭了闭眼睛，重新睁开。"
  },
  [111470514] = {
    id = 111470514,
    name = "当，当然是好酒！"
  },
  [111470515] = {
    id = 111470515,
    name = "那就都来点！把你们的水囊倒干净了！今天每个人都有份！"
  },
  [111470516] = {
    id = 111470516,
    name = "（干笑）呵呵。"
  },
  [111470517] = {
    id = 111470517,
    name = "领头人抱着木桶给每个人倒上一个水囊的份量。"
  },
  [111470518] = {
    id = 111470518,
    name = "等等——"
  },
  [111470519] = {
    id = 111470519,
    name = "等什么，这是你的！"
  },
  [111470520] = {
    id = 111470520,
    name = "领头人给了你塞了胀鼓鼓的一袋。"
  },
  [111470521] = {
    id = 111470521,
    name = "“噗——”"
  },
  [111470522] = {
    id = 111470522,
    name = "不知道谁先喝了一口，呛咳声不止。"
  },
  [111470523] = {
    id = 111470523,
    name = "哈哈哈哈，看把你急得，喝不来好东——唔呕......咳咳咳咳咳......"
  },
  [111470524] = {id = 111470524, name = "？？？"},
  [111470525] = {
    id = 111470525,
    name = "没事吧？别着急，慢慢喝。"
  },
  [111470526] = {
    id = 111470526,
    name = "......没，没事，哈哈哈哈。"
  },
  [111470527] = {
    id = 111470527,
    name = "原来这就是酒吗......唔......"
  },
  [111470528] = {
    id = 111470528,
    name = "呕......好......好酒......呕......"
  },
  [111470529] = {
    id = 111470529,
    name = "对对，贵族才能喝到的好酒......不能浪费啊！"
  },
  [111470530] = {
    id = 111470530,
    name = "你闻着那袋酒，里面传出了葡萄腐烂的霉臭味，不知过了多少年的酒，混着发霉的味道，令人一言难尽。"
  },
  [111470531] = {
    id = 111470531,
    name = "指挥官，你也喝啊！"
  },
  [111470532] = {
    id = 111470532,
    name = "............"
  },
  [111470533] = {
    id = 111470533,
    name = "你被按着头抿了一点，一股怪异的苦霉味在嘴边溢开。"
  },
  [111470534] = {
    id = 111470534,
    name = "怎么样怎么样？"
  },
  [111470535] = {
    id = 111470535,
    name = "......你也尝尝？"
  },
  [111470536] = {
    id = 111470536,
    name = "啊，忘记说了，我对酒过敏，好可惜哦~！"
  },
  [111470537] = {
    id = 111470537,
    name = "............"
  },
  [111470538] = {id = 111470538, name = "呵呵。"},
  [111470539] = {
    id = 111470539,
    name = "哈哈哈哈......"
  },
  [111470540] = {
    id = 111470540,
    name = "这么开心？"
  },
  [111470541] = {
    id = 111470541,
    name = "对，我发现了比寻宝更开心的事！那就是大家一起分享这份快乐啊！"
  },
  [111470542] = {
    id = 111470542,
    name = "你不禁也笑了。"
  },
  [111470543] = {
    id = 111470543,
    name = "微风拂过，有光透过树梢洒下，投射出斑驳的光影，照亮了猎鹰明亮的笑脸。"
  },
  [111470544] = {
    id = 111470544,
    name = "这一刻，一切利益与争端似乎变得不再重要。"
  },
  [111110001] = {
    id = 111110001,
    name = "那位小哥......"
  },
  [111110002] = {id = 111110002, name = "？？？"},
  [111110003] = {
    id = 111110003,
    name = "有人在说话，此时又没了声音。你顿了顿看向声音的方向，一个憔悴的男人朝你笑了笑。"
  },
  [111110004] = {id = 111110004, name = "......"},
  [111110005] = {
    id = 111110005,
    name = "你摇了摇头，继续往前。"
  },
  [111110006] = {
    id = 111110006,
    name = "小哥，别走啊，小哥~"
  },
  [111110007] = {
    id = 111110007,
    name = "通常的情况，这些都是贩卖货物的行走商人，不过你并不感兴趣。"
  },
  [111110008] = {
    id = 111110008,
    name = "小哥，嘿嘿~"
  },
  [111110009] = {
    id = 111110009,
    name = "因为他们大多都是行骗者。"
  },
  [111110010] = {
    id = 111110010,
    name = "我这里，有些好货，你要不要来看看？"
  },
  [111110011] = {
    id = 111110011,
    name = "（果然......）"
  },
  [111110012] = {
    id = 111110012,
    name = "喔？是什么好东西？"
  },
  [111110013] = {
    id = 111110013,
    name = "他看你来了兴致，憔悴的双眼冒出精光。"
  },
  [111110014] = {
    id = 111110014,
    name = "这个......小哥，既然是好货，当然都是私藏的。你看，我就赚点带路的钱......"
  },
  [111110015] = {
    id = 111110015,
    name = "他的手摩挲了一下，比划着要钱的意思，你看着他长满老茧的指尖皱了皱眉。"
  },
  [111110016] = {
    id = 111110016,
    name = "那算了。"
  },
  [111110017] = {
    id = 111110017,
    name = "欸欸......就10欧泊，不不5欧泊！"
  },
  [111110018] = {
    id = 111110018,
    name = "你嗤笑一声，不再理他。"
  },
  [111110019] = {
    id = 111110019,
    name = "1欧泊，1欧泊我就带你去！真的不能再少——"
  },
  [111110020] = {
    id = 111110020,
    name = "原来你在这里啊，狗东西！"
  },
  [111110021] = {id = 111110021, name = "！！！"},
  [111110022] = {
    id = 111110022,
    name = "把欠我的钱还给我！"
  },
  [111110023] = {
    id = 111110023,
    name = "我，我先走了！小哥，你要是感兴趣就去圈落的酒馆找我！"
  },
  [111110024] = {
    id = 111110024,
    name = "他撒腿逃走，远远留下了这样一句话。"
  },
  [111110025] = {
    id = 111110025,
    name = "别跑！呼......你认识他？"
  },
  [111110026] = {
    id = 111110026,
    name = "追债的男人打量了你一眼。"
  },
  [111110027] = {
    id = 111110027,
    name = "不认识，他刚才还想骗我的钱。"
  },
  [111110028] = {
    id = 111110028,
    name = "哼，你以后别理他。这家伙是个赌徒，欠了我不少钱了！妈的，亏我那时候还那么相信他！"
  },
  [111110029] = {
    id = 111110029,
    name = "男人骂骂咧咧地走了。"
  },
  [111110030] = {
    id = 111110030,
    name = "赌徒啊......"
  },
  [111110031] = {
    id = 111110031,
    name = "难得到一个圈落，先好好补充一下物资吧。"
  },
  [111110032] = {
    id = 111110032,
    name = "你四下看了一圈，朝最近的旅店走去。"
  },
  [111110033] = {
    id = 111110033,
    name = "住宿吗？都在牌子上，先给钱，后看房。"
  },
  [111110034] = {
    id = 111110034,
    name = "你拿出了几块欧泊，正好是一个房间的价格。"
  },
  [111110035] = {
    id = 111110035,
    name = "哟，看你这么爽快，有个好地方介绍给你，要不要去？"
  },
  [111110036] = {
    id = 111110036,
    name = "好地方？"
  },
  [111110037] = {
    id = 111110037,
    name = "喂，老板，什么好地方，怎么不带我们见识一下？"
  },
  [111110038] = {
    id = 111110038,
    name = "你要是不和他们挤一个房间，我也能带你去见识见识。"
  },
  [111110039] = {
    id = 111110039,
    name = "呵，瞧不起人啊，不就是有几个钱吗。"
  },
  [111110040] = {
    id = 111110040,
    name = "那地方，没钱还真的去不了。"
  },
  [111110041] = {
    id = 111110041,
    name = "所以是什么地方？"
  },
  [111110042] = {
    id = 111110042,
    name = "对啊，什么地方这么神秘？"
  },
  [111110043] = {
    id = 111110043,
    name = "是一个充满美酒、女人、诱惑的销金窟，也是一个让人能一夜暴富的地方！"
  },
  [111110044] = {
    id = 111110044,
    name = "一......一夜暴富？！"
  },
  [111110045] = {
    id = 111110045,
    name = "没错，一般人可没进去的资格！"
  },
  [111110046] = {
    id = 111110046,
    name = "那......那地方在哪里？"
  },
  [111110047] = {
    id = 111110047,
    name = "想知道？咨询费用是这个数。"
  },
  [111110048] = {
    id = 111110048,
    name = "你，你抢钱啊！"
  },
  [111110049] = {
    id = 111110049,
    name = "看看，告诉了你也没用，连这点钱都没有，还想让我带你进去？怕是还没进门就被人赶出来了。"
  },
  [111110050] = {id = 111110050, name = "......"},
  [111110051] = {
    id = 111110051,
    name = "怎么样，客人，你有没有兴趣啊？"
  },
  [111110052] = {
    id = 111110052,
    name = "这么好的地方，你去玩过？"
  },
  [111110053] = {
    id = 111110053,
    name = "哈哈，我就是带人进去，挣点零花，赌博什么的，我没那个运气。"
  },
  [111110054] = {
    id = 111110054,
    name = "所以，那个地方是个赌场？"
  },
  [111110055] = {
    id = 111110055,
    name = "没错。有美食、美酒、美女的赌场，小哥不想体验一回吗？"
  },
  [111110056] = {
    id = 111110056,
    name = "呵呵，好啊，等我想去的时候告诉你，今天还有别的事要做。"
  },
  [111110057] = {
    id = 111110057,
    name = "好好，你的房间在这边，我带你去。"
  },
  [111110058] = {
