    name = "老板，那地方听起来很好玩，真的不能带我们去？"
  },
  [111110059] = {
    id = 111110059,
    name = "要我带路，先拿这个数的欧泊吧。"
  },
  [111110060] = {id = 111110060, name = "哼。"},
  [111110061] = {
    id = 111110061,
    name = "旅店老板殷勤地送你到了房间。"
  },
  [111110062] = {
    id = 111110062,
    name = "客人，想去赌场的话，我随时听候你的差遣。"
  },
  [111110063] = {
