  [111110079] = {
    id = 111110079,
    name = "昨天不是说就这个价？"
  },
  [111110080] = {
    id = 111110080,
    name = "小哥，这一点我也没法带你进去啊......"
  },
  [111110081] = {
    id = 111110081,
    name = "那你也要先把我带进去再说。"
  },
  [111110082] = {id = 111110082, name = "......"},
  [111110083] = {
    id = 111110083,
    name = "不愿意？那把欧泊还我，我找别人了。那几个跟你玩牌的，应该也知道怎么去吧？"
  },
  [111110084] = {
    id = 111110084,
    name = "男人看了一眼牌友，掂了掂当赢来的筹码。"
  },
  [111110085] = {
    id = 111110085,
    name = "好！我带你去！你要是赚了，可别忘了分我点好处。"
  },
  [111110086] = {id = 111110086, name = "呵呵。"},
  [111110087] = {
    id = 111110087,
    name = "你们走后不久，一个金色发辫的少女来到了酒馆。"
  },
  [111110088] = {
