    name = "想去那个地方，只有这条路啊。"
  },
  [111110096] = {
    id = 111110096,
    name = "他佝偻着腰，在附近树上找到一盏熄灭的提灯。"
  },
  [111110097] = {
    id = 111110097,
    name = "来来，把这个点燃。"
  },
  [111110098] = {id = 111110098, name = "点灯？"},
  [111110099] = {
    id = 111110099,
    name = "对对，点灯问路，才会有人开门。"
  },
  [111110100] = {
    id = 111110100,
    name = "你饶有兴趣地走向提灯。"
  },
  [111110101] = {
    id = 111110101,
    name = "小哥，这盏灯用普通的火石点不燃的，得要用魔法火石，这是最低的门槛，防止那些拾荒者进去，当然拾荒者要是敢进去，很快就会被丢出来的。"
  },
  [111110102] = {
    id = 111110102,
    name = "你依言点燃了提灯，咔嚓一声，附近的地面动了动，一条通往地下的通道出现在眼前。"
  },
  [111110103] = {
    id = 111110103,
    name = "就从这里进去，很快就到了！"
  },
  [111110104] = {
    id = 111110104,
    name = "入口竟然在地下，难怪很多人都找不到。"
  },
  [111110105] = {
    id = 111110105,
    name = "嘿嘿，谁会知道这一脚下去，不是地狱而是天堂呢。"
  },
  [111110106] = {
    id = 111110106,
    name = "男人带着你穿过地下通道，来到了一座山谷，眼前是一座古旧的大型房屋，几个赌场打手围在附近蹲着聊天，看到你们出现也没有理会。"
  },
  [111110107] = {
    id = 111110107,
    name = "进去吧。"
