    name = "别乱说话！我可没欠赌场的钱！"
  },
  [111110112] = {
    id = 111110112,
    name = "他推开了赌场的大门。"
  },
  [111110113] = {
    id = 111110113,
    name = "噢噢噢噢......"
  },
  [111110114] = {
    id = 111110114,
    name = "嘈杂和兴奋的欢呼声一瞬间灌入双耳。"
  },
  [111110115] = {
    id = 111110115,
    name = "到了，就是这里，你自己玩开心吧。"
  },
  [111110116] = {
    id = 111110116,
    name = "嗯，你回去吧。"
  },
  [111110117] = {
    id = 111110117,
    name = "......啧，来都来了。"
  },
  [111110118] = {
    id = 111110118,
    name = "啊啊啊忍不住了，我先去爽几把再说！"
  },
  [111110119] = {
    id = 111110119,
    name = "赌场灯火冥冥，弥漫着浓重的烟雾，扑克在荷官手里轻快地翻动，骰子在摇筛杯里簌簌作响......"
  },
  [111110120] = {
    id = 111110120,
    name = "三点、三点、三点！机会来了！！老子全下了，你敢跟吗？！"
