  [111110121] = {
    id = 111110121,
    name = "跟就跟！"
  },
  [111110122] = {
    id = 111110122,
    name = "赌徒们面色紧张，汗水滴落在桌上，欧泊流转不息，一份份筹码碰撞着，发出清脆动听的撞击声。"
  },
  [111110123] = {
    id = 111110123,
    name = "这位小哥哥，面生呢，第一次？"
  },
  [111110124] = {
