    name = "妩媚的女人举着托盘朝你走来。"
  },
  [111110125] = {
    id = 111110125,
    name = "想怎么玩，跟我说说~"
  },
  [111110126] = {id = 111110126, name = "......"},
  [111110127] = {
    id = 111110127,
    name = "呵呵，小哥哥还放不开呢？要筹码的话，可以和我换，要喝酒的话，我也能陪你喝~或者说，你想做些别的......也不是不可以......"
  },
  [111110128] = {
    id = 111110128,
    name = "唔，那就换点筹码吧。"
