    name = "陆玄没有回答，只是用手指在封泥上轻轻摩挲了一下，像是在确认什么，又像是在犹豫。"
  },
  [111830224] = {
    id = 111830224,
    name = "过了几息，他才缓缓开口。"
  },
  [111830225] = {
    id = 111830225,
    name = "这酒，你从哪弄来的。"
  },
  [111830226] = {
    id = 111830226,
    name = "一个塌掉的石室里，就剩这一坛。"
  },
  [111830227] = {id = 111830227, name = "......"},
  [111830228] = {
    id = 111830228,
    name = "运气不错。"
  },
  [111830229] = {
    id = 111830229,
    name = "他说完，手上微微用力，将封泥揭开。"
  },
  [111830230] = {
    id = 111830230,
    name = "一缕酒香缓缓逸散而出。"
  },
  [111830231] = {
    id = 111830231,
    name = "不浓烈，却极其纯净。"
  },
  [111830232] = {
    id = 111830232,
    name = "你下意识吸了一口气。"
  },
  [111830233] = {
    id = 111830233,
    name = "不对......这味道，怎么和我发现时不太一样。"
  },
  [111830234] = {id = 111830234, name = "嗯。"},
  [111830235] = {
    id = 111830235,
    name = "你发现时只是“漏出来的气”，现在才算是真的。"
  },
  [111830236] = {
    id = 111830236,
    name = "酒香在空气中慢慢扩散，没有压迫，却让人不自觉地放松下来，就连远处那若有若无的压迫感，也像是被隔开了一层。"
  },
  [111830237] = {
    id = 111830237,
    name = "深渊里......会有这种东西吗？"
  },
  [111830238] = {id = 111830238, name = "不会。"},
  [111830239] = {
    id = 111830239,
    name = "陆玄回答得很干脆。"
  },
  [111830240] = {
    id = 111830240,
    name = "那这酒——"
  },
  [111830241] = {
    id = 111830241,
    name = "不知道。"
  },
  [111830242] = {
    id = 111830242,
    name = "他打断了你，语气依旧平静，但注意力已经完全落在这坛酒上。"
  },
  [111830243] = {
    id = 111830243,
    name = "陆玄伸手取过两个杯子，不紧不慢地倒酒。"
  },
  [111830244] = {
    id = 111830244,
    name = "酒液清澈，在光线下微微晃动，没有杂质，看不出年代。"
  },
  [111830245] = {
    id = 111830245,
    name = "陆玄盯着杯中的酒，看了片刻。"
  },
  [111830246] = {
    id = 111830246,
    name = "久到你有些不自在。"
  },
  [111830247] = {id = 111830247, name = "大叔？"},
  [111830248] = {
    id = 111830248,
    name = "陆玄这才回过神，将其中一杯递给你。"
  },
  [111830249] = {id = 111830249, name = "尝尝。"},
  [111830250] = {id = 111830250, name = "好。"},
  [111830251] = {
    id = 111830251,
    name = "你接过酒杯，小心地抿了一口。"
  },
  [111830252] = {
    id = 111830252,
    name = "入口的瞬间，你微微一怔。"
  },
  [111830253] = {
    id = 111830253,
    name = "这也太顺了吧......一点刺激感都没有，但酒的芬芳又被完整保留。"
  },
  [111830254] = {
    id = 111830254,
    name = "嗯，是好酒。"
  },
  [111830255] = {
    id = 111830255,
    name = "他也抿了一口，动作很轻，更像是在确认。"
  },
  [111830256] = {
    id = 111830256,
    name = "下一刻——他的手微微一停。"
  },
  [111830257] = {
    id = 111830257,
    name = "时间很短，却没有逃过你的眼睛。"
  },
  [111830258] = {
    id = 111830258,
    name = "看着杯中的酒，陆玄的目光渐渐变深，像是透过它看到了别的东西。"
  },
  [111830259] = {
    id = 111830259,
    name = "空气再次安静下来，比刚才更沉。"
  },
  [111830260] = {id = 111830260, name = "大叔？"},
  [111830261] = {
    id = 111830261,
    name = "你试探着叫了一声。"
  },
  [111830262] = {
    id = 111830262,
    name = "陆玄这才缓缓吐出一口气。"
  },
  [111830263] = {
    id = 111830263,
    name = "......有点意思。"
  },
  [111830264] = {
    id = 111830264,
    name = "他的声音比平时低了一些。"
  },
  [111830265] = {
    id = 111830265,
    name = "这味道......"
  },
  [111830266] = {
    id = 111830266,
    name = "他说到一半，停住了，像是在斟酌，又像是不太确定。"
  },
  [111830267] = {
    id = 111830267,
    name = "怎么了？"
  },
  [111830268] = {
    id = 111830268,
    name = "陆玄沉默了一会儿，轻轻摇头。"
  },
  [111830269] = {
    id = 111830269,
    name = "没什么。"
  },
  [111830270] = {
    id = 111830270,
    name = "只是......好像想起了一点，很久以前的事。"
  },
  [111830271] = {
    id = 111830271,
    name = "你愣住了。"
  },
  [111830272] = {
    id = 111830272,
    name = "很久......以前？"
  },
  [111830273] = {
    id = 111830273,
    name = "陆玄没有立刻回答，只是又喝了一口酒，这一次没有停顿，慢慢咽下。"
  },
  [111830274] = {
    id = 111830274,
    name = "等会再说。"
  },
  [111830275] = {
    id = 111830275,
    name = "先把这杯喝完。"
  },
  [111830276] = {
    id = 111830276,
    name = "陆玄语气恢复了平静。"
  },
  [111830277] = {
    id = 111830277,
    name = "但你能感觉到——有什么东西，被打开了。"
  },
  [111830278] = {
    id = 111830278,
    name = "陆玄端着酒杯，看着杯中的酒出神。"
  },
  [111830279] = {
    id = 111830279,
    name = "你也没有催他。"
  },
  [111830280] = {
    id = 111830280,
    name = "你们就这么安静地坐了一会儿。"
  },
  [111830281] = {
    id = 111830281,
    name = "酒香在空气中缓缓弥漫，让原本压抑的环境多了一丝难得的轻松。"
  },
  [111830282] = {
    id = 111830282,
    name = "......说起来。"
  },
  [111830283] = {
    id = 111830283,
    name = "你晃了晃杯子，打破沉默。"
  },
  [111830284] = {
    id = 111830284,
    name = "我这次下去，碰到的东西有点奇怪。"
  },
  [111830285] = {id = 111830285, name = "嗯？"},
  [111830286] = {
    id = 111830286,
    name = "说说看。"
  },
  [111830287] = {
    id = 111830287,
    name = "有几头魔物，本来已经被我斩掉要害了。"
  },
  [111830288] = {
    id = 111830288,
    name = "但还是能动。"
  },
  [111830289] = {
    id = 111830289,
    name = "不是那种挣扎，是......像被什么东西“拖着”在动。"
  },
  [111830290] = {id = 111830290, name = "......"},
  [111830291] = {
    id = 111830291,
    name = "陆玄喝了一口酒，没有插话。"
  },
  [111830292] = {
    id = 111830292,
    name = "而且那地方的环境也有点怪。"
  },
  [111830293] = {
    id = 111830293,
    name = "具体说不上来，就是......"
  },
  [111830294] = {
    id = 111830294,
    name = "待久了，会很烦。"
  },
  [111830295] = {
    id = 111830295,
    name = "并非浊炁太浓郁的那种不舒服，就是烦。"
  },
  [111830296] = {id = 111830296, name = "浮躁。"},
  [111830297] = {
    id = 111830297,
    name = "对，就是这个感觉。"
  },
  [111830298] = {
    id = 111830298,
    name = "你点了点头。"
  },
  [111830299] = {
    id = 111830299,
    name = "我还以为是我状态不好。"
  },
  [111830300] = {
    id = 111830300,
    name = "不一定。"
  },
  [111830301] = {
    id = 111830301,
    name = "什么意思？"
  },
  [111830302] = {
    id = 111830302,
    name = "陆玄没有立刻回答。"
  },
  [111830303] = {
    id = 111830303,
    name = "他看着杯中的酒，像是在对比什么。"
  },
  [111830304] = {
    id = 111830304,
    name = "深渊本来就不干净。"
  },
  [111830305] = {
    id = 111830305,
    name = "有点变化，不奇怪。"
