  [111830405] = {
    id = 111830405,
    name = "他看着手中的酒杯，像是在透过它，看向更远的地方。"
  },
  [111830406] = {
    id = 111830406,
    name = "过了几息，陆玄才缓缓开口。"
  },
  [111830407] = {
    id = 111830407,
    name = "一个......已经被遗忘了的地方。"
  },
  [111830408] = {
    id = 111830408,
    name = "他的声音低了下来，声音却很坚定。"
  },
  [111830409] = {
    id = 111830409,
    name = "云海道域。"
  },
  [111830410] = {
    id = 111830410,
    name = "空气仿佛在这一刻，轻轻一滞。"
  },
  [111830411] = {
    id = 111830411,
    name = "你下意识重复了一遍。"
  },
  [111830412] = {
    id = 111830412,
    name = "云海道域......"
  },
  [111830413] = {
    id = 111830413,
    name = "这个名字无比陌生，却隐约带着某种重量。"
  },
  [111830414] = {
    id = 111830414,
    name = "你还想再问些什么，但陆玄已经闭上了眼。"
  },
  [111830415] = {
    id = 111830415,
    name = "像是在回忆。"
  },
  [111830416] = {
    id = 111830416,
    name = "也像是——"
  },
  [111830417] = {
    id = 111830417,
    name = "真的回去了。"
  },
  [111830418] = {
    id = 111830418,
    name = "那地方和深渊不太一样。"
  },
  [111830419] = {
    id = 111830419,
    name = "哪里不一样？"
  },
  [111830420] = {
    id = 111830420,
    name = "规矩多。"
  },
  [111830421] = {
    id = 111830421,
    name = "你一愣。"
  },
  [111830422] = {id = 111830422, name = "规矩？"},
  [111830423] = {id = 111830423, name = "嗯。"},
  [111830424] = {
    id = 111830424,
    name = "不是深渊这种，谁强谁说了算。"
  },
  [111830425] = {
    id = 111830425,
    name = "那里——"
  },
  [111830426] = {
    id = 111830426,
    name = "讲出身，讲宗门。"
  },
  [111830427] = {
    id = 111830427,
    name = "也讲规矩。"
  },
  [111830428] = {
    id = 111830428,
    name = "你皱了皱眉。"
  },
  [111830429] = {
    id = 111830429,
    name = "听起来更麻烦了。"
  },
  [111830430] = {
    id = 111830430,
    name = "是更麻烦。"
  },
  [111830431] = {
    id = 111830431,
    name = "陆玄又倒了一点酒，这一次，他喝得很慢。"
  },
  [111830432] = {
    id = 111830432,
    name = "但也更稳定。"
  },
  [111830433] = {id = 111830433, name = "稳定？"},
  [111830434] = {id = 111830434, name = "嗯。"},
  [111830435] = {
    id = 111830435,
    name = "有人管，也有人守。"
  },
  [111830436] = {
    id = 111830436,
    name = "不会像深渊这样，乱成一片。"
  },
  [111830437] = {
    id = 111830437,
    name = "你点了点头。"
  },
  [111830438] = {
    id = 111830438,
    name = "那倒是不错。"
  },
  [111830439] = {
    id = 111830439,
    name = "至少不用天天提防被人阴。"
  },
  [111830440] = {id = 111830440, name = "不。"},
  [111830441] = {
    id = 111830441,
    name = "陆玄看了你一眼。"
  },
  [111830442] = {
    id = 111830442,
    name = "该提防的，一样要提防。"
  },
  [111830443] = {id = 111830443, name = "......"},
  [111830444] = {
    id = 111830444,
    name = "那不是更累了吗？"
  },
  [111830445] = {
    id = 111830445,
    name = "习惯就好。"
  },
  [111830446] = {
    id = 111830446,
    name = "他说得很随意，像是在说一件再普通不过的事。"
  },
  [111830447] = {
    id = 111830447,
    name = "深渊，是探险者的世界。"
  },
  [111830448] = {
    id = 111830448,
    name = "而云海道域——"
  },
  [111830449] = {
    id = 111830449,
    name = "是修士的世界。"
  },
  [111830450] = {
    id = 111830450,
    name = "探险者修行武技、魔法，修士则修行法术。"
  },
  [111830451] = {
    id = 111830451,
    name = "听起来......差别不大？"
  },
  [111830452] = {
    id = 111830452,
    name = "表面上不大。"
  },
  [111830453] = {
    id = 111830453,
    name = "陆玄看着杯中的酒。"
  },
  [111830454] = {
    id = 111830454,
    name = "探险者在踏足深渊之前，彼此之间的竞争算不上激烈。"
  },
  [111830455] = {
    id = 111830455,
    name = "陆玄顿了一下。"
  },
  [111830456] = {
    id = 111830456,
    name = "但修士不一样。"
  },
  [111830457] = {
    id = 111830457,
    name = "从开始修行的那一刻起——"
  },
  [111830458] = {
    id = 111830458,
    name = "就已经在争了。"
  },
  [111830459] = {
    id = 111830459,
    name = "争什么？"
  },
  [111830460] = {id = 111830460, name = "灵气。"},
  [111830461] = {id = 111830461, name = "地位。"},
  [111830462] = {
    id = 111830462,
    name = "还有名望。"
  },
  [111830463] = {
    id = 111830463,
    name = "灵气......类似于魔力吗？"
  },
  [111830464] = {
    id = 111830464,
    name = "陆玄点了点头。"
  },
  [111830465] = {
    id = 111830465,
    name = "宗门弟子之间。"
  },
  [111830466] = {
    id = 111830466,
    name = "宗门与宗门之间。"
  },
  [111830467] = {
    id = 111830467,
    name = "都会争。"
  },
  [111830468] = {
    id = 111830468,
    name = "那不是很残酷？"
  },
  [111830469] = {
    id = 111830469,
    name = "是很残酷。"
  },
  [111830470] = {
    id = 111830470,
    name = "不过——"
  },
  [111830471] = {
    id = 111830471,
    name = "也正因为这样。"
  },
  [111830472] = {
    id = 111830472,
    name = "才会有人拼命往上爬。"
  },
  [111830473] = {
    id = 111830473,
    name = "陆玄的话，让你不禁想象起那个修士纵横、宗门林立的世界。"
  },
  [111830474] = {
    id = 111830474,
    name = "那种地方......强的人很多吧？"
  },
  [111830475] = {id = 111830475, name = "很多。"},
  [111830476] = {
    id = 111830476,
    name = "陆玄再次将手中的酒一饮而尽。"
  },
  [111830477] = {
    id = 111830477,
    name = "你见状，急忙拿起酒坛为他斟满。"
  },
  [111830478] = {
    id = 111830478,
    name = "看着杯中荡漾的酒波，陆玄似乎有些唏嘘。"
  },
  [111830479] = {
    id = 111830479,
    name = "强者能获得更多资源。"
  },
  [111830480] = {
    id = 111830480,
    name = "享受更多赞誉。"
  },
  [111830481] = {
    id = 111830481,
    name = "他顿了一下。"
  },
  [111830482] = {id = 111830482, name = "但——"},
  [111830483] = {
    id = 111830483,
    name = "也会被更多人盯上......"
  },
  [111440001] = {
    id = 111440001,
    name = "深渊中，一头魔物盘踞在狭长的石桥上，低声嘶鸣。"
  },
  [111440002] = {
    id = 111440002,
    name = "......路线被堵住了。"
  },
  [111440003] = {
    id = 111440003,
    name = "看起来还是头目级......"
  },
  [111440004] = {
    id = 111440004,
    name = "魔物低吼，尾巴缓慢拖动地面，碎石发出刺耳摩擦声。"
  },
  [111440005] = {
    id = 111440005,
    name = "如果绕路，会延误委托时间。"
  },
  [111440006] = {
    id = 111440006,
    name = "只能正面突破了。"
  },
  [111440007] = {
    id = 111440007,
    name = "少女握紧长枪，脚步向前。"
  },
  [111440008] = {id = 111440008, name = "别急。"},
  [111440009] = {
    id = 111440009,
    name = "少女动作一顿，但没有立刻回头。"
  },
  [111440010] = {id = 111440010, name = "......"},
  [111440011] = {
    id = 111440011,
    name = "你从后方走近，视线落在魔物身上。"
  },
  [111440012] = {
    id = 111440012,
    name = "这家伙的壳很硬，正面很难突破。"
  },
  [111440013] = {id = 111440013, name = "你是？"},
  [111440014] = {
    id = 111440014,
    name = "路过的探险者。"
  },
  [111440015] = {
    id = 111440015,
    name = "我和这家伙战斗过，它的弱点在颈侧下方，甲壳的缝隙。"
  },
  [111440016] = {
    id = 111440016,
    name = "少女重新看向魔物，目光微沉。"
  },
  [111440017] = {
    id = 111440017,
    name = "......原来如此。"
  },
  [111440018] = {
    id = 111440018,
    name = "多谢提醒。不过——"
  },
  [111440019] = {
    id = 111440019,
    name = "这是我的委托范围。"
  },
  [111440020] = {
    id = 111440020,
    name = "她的语气温和，却带着清晰的界限。"
  },
  [111440021] = {id = 111440021, name = "明白。"},
  [111440022] = {
    id = 111440022,
    name = "我不插手。"
  },
  [111440023] = {
    id = 111440023,
    name = "你后退半步，没有再靠近。"
  },
  [111440024] = {
    id = 111440024,
    name = "空气短暂安静下来，只剩魔物低沉的嘶鸣。"
  },
  [111440025] = {
    id = 111440025,
    name = "魔物缓缓挪动，将身体柔软的部位都缩进甲壳中。"
  },
  [111440026] = {
    id = 111440026,
    name = "它在防御。"
  },
  [111440027] = {
    id = 111440027,
    name = "我看到了。"
  },
  [111440028] = {
    id = 111440028,
    name = "她身形一动，迅速逼近。"
  },
  [111440029] = {
    id = 111440029,
    name = "长枪掠出。"
  },
  [111440030] = {
    id = 111440030,
    name = "魔物猛然甩尾，碎石飞溅。"
  },
  [111440031] = {id = 111440031, name = "......！"},
  [111440032] = {
    id = 111440032,
    name = "她侧身闪避，落地后迅速调整姿态。"
  },
  [111440033] = {
    id = 111440033,
    name = "它在适应你的节奏。"
  },
  [111440034] = {
    id = 111440034,
    name = "反应速度比预期快。"
  },
  [111440035] = {
    id = 111440035,
    name = "再试探下去，你会吃亏。"
  },
  [111440036] = {
    id = 111440036,
    name = "少女沉默片刻，再次调整呼吸。"
  },
  [111440037] = {
    id = 111440037,
    name = "就在她准备再次进攻时——"
  },
  [111440038] = {
    id = 111440038,
    name = "破空声骤然响起。"
  },
  [111440039] = {
    id = 111440039,
    name = "一枚魔弹侧方飞出，划出一道巨大弧线，从后方精准命中魔物。"
  },
  [111440040] = {
    id = 111440040,
    name = "魔物吃痛，身体本能偏转。"
  },
  [111440041] = {
    id = 111440041,
    name = "趁现在。"
  },
  [111440042] = {
    id = 111440042,
    name = "魔物身体偏转瞬间，颈部甲壳缝隙暴露。"
  },
  [111440043] = {
    id = 111440043,
    name = "少女目光一凝。"
  },
  [111440044] = {id = 111440044, name = "明白。"},
  [111440045] = {
    id = 111440045,
    name = "她踏步突进，长枪笔直刺入弱点。"
  },
  [111440046] = {
    id = 111440046,
    name = "魔物发出低沉嘶吼，庞大身躯轰然倒地。"
  },
  [111440047] = {
    id = 111440047,
    name = "尘埃缓缓落下，通路重新归于寂静。"
  },
  [111440048] = {
    id = 111440048,
    name = "少女收起武器，呼吸依旧平稳。"
  },
  [111440049] = {
    id = 111440049,
    name = "刚才那一击......是你制造的破绽。"
  },
  [111440050] = {
    id = 111440050,
    name = "只是稍微牵制了一下，决定胜负的......还是你的攻击。"
  },
  [111440051] = {
    id = 111440051,
    name = "不，如果你没有出手，要等它露出破绽恐怕得费不少力气。"
  },
  [111440052] = {
    id = 111440052,
    name = "她微微低头。"
  },
  [111440053] = {
    id = 111440053,
    name = "多谢你的协助。"
  },
  [111440054] = {
    id = 111440054,
    name = "顺手而已。"
  },
  [111440055] = {
    id = 111440055,
    name = "你看向前方被打通的石桥。"
  },
  [111440056] = {
    id = 111440056,
    name = "你是要去那边的商业据点？"
  },
  [111440057] = {
    id = 111440057,
    name = "抱歉，请恕我无可奉告。"
  },
  [111440058] = {
    id = 111440058,
    name = "看着她的表现以及携带的物件，你大概猜出了她的身份。"
  },
  [111440059] = {
    id = 111440059,
    name = "深渊航线的人？"
  },
  [111440060] = {id = 111440060, name = "......"},
  [111440061] = {
    id = 111440061,
    name = "见少女的眼中闪过一丝警惕，你急忙解释。"
  },
  [111440062] = {
    id = 111440062,
    name = "呵呵，我只是觉得你的言行和我几位深渊航线的朋友很像。"
  },
  [111440063] = {
    id = 111440063,
    name = "听到你的解释，少女才稍微放松了一些。"
  },
  [111440064] = {
    id = 111440064,
    name = "抱歉，明明你才帮助了我......"
  },
  [111440065] = {
    id = 111440065,
    name = "请不用介意。行走深渊，本来就需要多加留意。"
  },
  [111440066] = {
    id = 111440066,
    name = "更何况你还有委托在身，谨慎一些也很有必要。"
  },
  [111440067] = {
    id = 111440067,
    name = "说起来，星云的行事作风就和你们差别很大，我听辉夜说，她好像还因此被处罚了多次。"
  },
  [111440068] = {
    id = 111440068,
    name = "听你说起星云和辉夜，少女似乎终于放下了戒备。"
  },
  [111440069] = {
    id = 111440069,
    name = "是啊，不过她的性格就是那样。"
  },
  [111440070] = {
    id = 111440070,
    name = "呵呵，请问该怎么称呼呢？"
  },
  [111440071] = {id = 111440071, name = "浮光。"},
  [111440072] = {
    id = 111440072,
    name = "原来你就是浮光......"
  },
  [111440073] = {
    id = 111440073,
    name = "她们经常说起你，真是百闻不如一见。"
  },
  [111440074] = {
    id = 111440074,
    name = "听着你的话，浮光盯着你的脸短暂思考了一瞬。"
  },
  [111440075] = {
    id = 111440075,
    name = "难道......阁下就是她们经常提起的那位队长？"
  },
  [111440076] = {
    id = 111440076,
    name = "是的。呵呵，没想到我也会成为她们私下里谈论的对象。"
  },
  [111440077] = {
    id = 111440077,
    name = "队长谦虚了。她们对你可是非常的信任、钦佩。"
  },
  [111440078] = {
    id = 111440078,
    name = "气氛缓和了不少，但浮光的言语依旧克制。"
  },
  [111440079] = {
    id = 111440079,
    name = "浮光小姐也是要去商业据点吧？后续路程同行如何？"
  },
  [111440080] = {
    id = 111440080,
    name = "队长是怎样确定我的目的地的呢？"
  },
  [111440081] = {
    id = 111440081,
    name = "你笑了笑，没有直接回答，顿了一下后才做出解释。"
  },
  [111440082] = {
    id = 111440082,
    name = "独行，装备轻便，并不像长期探险的配置。"
  },
  [111440083] = {
    id = 111440083,
    name = "再加上特殊的身份......前方的商业据点中，许多人都是你们深渊航线的老客户。"
  },
  [111440084] = {
    id = 111440084,
    name = "浮光看了你一眼，似乎在重新评估。"
  },
  [111440085] = {
    id = 111440085,
    name = "观察得很细致。"
  },
  [111440086] = {
    id = 111440086,
    name = "职业习惯。"
  },
  [111440087] = {
    id = 111440087,
    name = "浮光微微一笑。"
  },
  [111440088] = {
    id = 111440088,
    name = "根据深渊航线规定，执行委托过程中，不可以与陌生人有过多交集。"
  },
  [111440089] = {
    id = 111440089,
    name = "那真是遗憾。"
  },
  [111440090] = {
    id = 111440090,
    name = "但被深渊航线几位同伴信任的队长......并不是陌生人。"
  },
  [111440091] = {
    id = 111440091,
    name = "到达商业据点前，就劳烦多多关照了，队长。"
  },
  [111440092] = {
    id = 111440092,
    name = "彼此彼此。"
  },
  [111440093] = {
    id = 111440093,
    name = "你们相视一笑，简单收拾后踏上了行程。"
  },
  [111440094] = {
    id = 111440094,
    name = "离开石桥后，通路逐渐开阔，空气中的魔力波动也趋于稳定。"
  },
  [111440095] = {
    id = 111440095,
    name = "你们并肩前行，脚步声在山石间轻轻回响。"
  },
  [111440096] = {
    id = 111440096,
    name = "前面的路还算安全，再往深一点，魔物分布会变密。"
  },
  [111440097] = {
    id = 111440097,
    name = "嗯，我的路线也是这么标注的。"
  },
  [111440098] = {
    id = 111440098,
    name = "你对这一带很熟悉？"
  },
  [111440099] = {
    id = 111440099,
    name = "算不上熟，只是来过几次。"
  },
  [111440100] = {
    id = 111440100,
    name = "又走了一段，道路出现分岔，一侧较为平整，另一侧则有明显的坍塌痕迹。"
  },
  [111440101] = {
    id = 111440101,
    name = "浮光停下脚步，目光在两条路之间来回扫视。"
  },
  [111440102] = {
    id = 111440102,
    name = "地图上标注的，是左侧。"
  },
  [111440103] = {
    id = 111440103,
    name = "右边虽然近，但不稳定。"
  },
  [111440104] = {
    id = 111440104,
    name = "如果绕路，会多花一些时间。"
  },
  [111440105] = {
    id = 111440105,
    name = "你看了一眼坍塌区域，地面有细微裂纹。"
  },
  [111440106] = {
    id = 111440106,
    name = "这边刚发生过崩塌，短时间内不太会再塌。"
  },
  [111440107] = {
    id = 111440107,
    name = "你的意思是......可以通过？"
  },
  [111440108] = {
    id = 111440108,
    name = "可以，但要快。"
  },
  [111440109] = {
    id = 111440109,
    name = "浮光略微思索。"
  },
  [111440110] = {
    id = 111440110,
    name = "那就走右边。"
  },
  [111440111] = {id = 111440111, name = "好。"},
  [111440112] = {
    id = 111440112,
    name = "你们迅速进入坍塌通道。"
  },
  [111440113] = {
    id = 111440113,
    name = "碎石遍地，脚下不稳，但你们的步伐都控制得极为精准。"
  },
  [111440114] = {
    id = 111440114,
    name = "行进途中，一块松动的岩石突然从上方滑落。"
  },
  [111440115] = {id = 111440115, name = "小心。"},
  [111440116] = {
    id = 111440116,
    name = "你抬手，一道魔力将落石偏转。"
  },
  [111440117] = {
    id = 111440117,
    name = "浮光没有停下脚步，反而借势跃起，轻巧落在前方较高的岩面上。"
  },
  [111440118] = {
    id = 111440118,
    name = "这边可以落脚。"
  },
  [111440119] = {
    id = 111440119,
    name = "配合不错。"
  },
  [111440120] = {
    id = 111440120,
    name = "只是顺势而为。"
  },
  [111440121] = {
    id = 111440121,
    name = "你们一前一后，很快穿过危险区域。"
  },
  [111440122] = {
    id = 111440122,
    name = "离开通道后，视野豁然开朗。"
  },
  [111440123] = {
    id = 111440123,
    name = "浮光轻轻吐出一口气。"
  },
  [111440124] = {
    id = 111440124,
    name = "比预计节省了不少时间。"
  },
  [111440125] = {
    id = 111440125,
    name = "风险也不低。"
  },
  [111440126] = {
    id = 111440126,
    name = "但在可控范围内。"
  },
  [111440127] = {
    id = 111440127,
    name = "她看向你，语气依旧平静。"
  },
  [111440128] = {
    id = 111440128,
    name = "你的判断，很可靠。"
  },
  [111440129] = {
    id = 111440129,
    name = "你执行得也很干净。"
  },
  [111440130] = {
    id = 111440130,
    name = "短暂的对视。"
  },
  [111440131] = {
    id = 111440131,
    name = "气氛比刚才，明显轻松了一些。"
  },
  [111440132] = {
    id = 111440132,
    name = "如果接下来没有意外，应该要不了多久就可以到达了。"
  },
  [111440133] = {
    id = 111440133,
    name = "希望如此。"
  },
  [111440134] = {
    id = 111440134,
    name = "通路逐渐接近外围区域，来往的痕迹也开始变多。"
  },
  [111440135] = {
    id = 111440135,
    name = "地面上出现了车辙印，以及零散的营火残迹。"
  },
  [111440136] = {
    id = 111440136,
    name = "看来离据点不远了。"
  },
  [111440137] = {
    id = 111440137,
    name = "嗯，从这些痕迹来看，前面的人也才刚离开不久。"
  },
  [111440138] = {
    id = 111440138,
    name = "话音刚落——"
  },
  [111440139] = {
    id = 111440139,
    name = "不远处便传来一阵嘈杂声。"
  },
  [111440140] = {
    id = 111440140,
    name = "“站住！”"
  },
  [111440141] = {
    id = 111440141,
    name = "“把东西交出来！”"
  },
  [111440142] = {
    id = 111440142,
    name = "浮光与你同时停下脚步。"
  },
  [111440143] = {
    id = 111440143,
    name = "......有人在交战。"
  },
  [111440144] = {
    id = 111440144,
    name = "你们对视一眼，迅速靠近。"
  },
  [111440145] = {
    id = 111440145,
    name = "前方，一支小型商队正被几名劫匪围住。"
  },
  [111440146] = {
    id = 111440146,
    name = "大爷饶命！饶命啊！"
  },
  [111440147] = {
    id = 111440147,
    name = "少废话！把值钱的都交出来！"
  },
  [111440148] = {
    id = 111440148,
    name = "浮光没有犹豫，已经握住武器。"
  },
  [111440149] = {
    id = 111440149,
    name = "需要出手。"
  },
  [111440150] = {
    id = 111440150,
    name = "我从侧面绕。"
  },
  [111440151] = {
    id = 111440151,
    name = "浮光点头表示赞同。"
  },
  [111440152] = {
    id = 111440152,
    name = "下一刻，她已经冲了出去。"
  },
  [111440153] = {id = 111440153, name = "住手。"},
  [111440154] = {
    id = 111440154,
    name = "她的声音不大，却让场面瞬间一滞。"
  },
  [111440155] = {
    id = 111440155,
    name = "来了个多管闲事的？"
  },
  [111440156] = {
    id = 111440156,
    name = "话音未落，枪影一闪。"
  },
  [111440157] = {
    id = 111440157,
    name = "最前方的劫匪手中武器被直接挑飞。"
  },
  [111440158] = {
    id = 111440158,
    name = "浮光没有追击，而是稳稳站在商队与劫匪之间。"
  },
  [111440159] = {
    id = 111440159,
    name = "啧——找死！"
  },
  [111440160] = {
    id = 111440160,
    name = "几人一拥而上。"
  },
  [111440161] = {
    id = 111440161,
    name = "浮光步伐轻盈，动作干净利落，每一次出手都精准地卸掉对方的战斗能力。"
  },
  [111440162] = {
    id = 111440162,
    name = "与此同时，另一侧，一名试图绕后的劫匪突然被魔力束缚住。"
  },
  [111440163] = {
    id = 111440163,
    name = "别乱动。"
  },
  [111440164] = {id = 111440164, name = "什——"},
  [111440165] = {
    id = 111440165,
    name = "短暂的混乱后，局势迅速被压制。"
  },
  [111440166] = {
    id = 111440166,
    name = "剩下的劫匪见势不妙，纷纷逃窜。"
  },
  [111440167] = {
    id = 111440167,
    name = "得、得救了......！"
  },
  [111440168] = {
    id = 111440168,
    name = "多谢两位恩人，这车上可都是我一家老小的命啊。"
  },
  [111440169] = {
    id = 111440169,
    name = "如果不是你们，我们这批货恐怕就——"
  },
  [111440170] = {
    id = 111440170,
    name = "浮光收起武器，轻轻点头。"
  },
  [111440171] = {
    id = 111440171,
    name = "这条路上最近往来的商人变多，匪徒自然也闻着味来了。"
  },
  [111440172] = {
    id = 111440172,
    name = "有条件可以雇佣一些护卫。"
  },
  [111440173] = {
    id = 111440173,
    name = "唉，下次再出远门，我一定雇佣几个护卫，不省那个钱了。"
  },
  [111440174] = {
    id = 111440174,
    name = "你和浮光对视了一眼，便准备告辞离去。"
  },
  [111440175] = {
    id = 111440175,
    name = "二位，二位且慢！你们是要去前面商业据点吗？"
  },
  [111440176] = {id = 111440176, name = "嗯。"},
  [111440177] = {
    id = 111440177,
    name = "我们能和二位一起走吗？"
  },
  [111440178] = {
    id = 111440178,
    name = "当然，我们会支付酬劳。"
  },
  [111440179] = {
    id = 111440179,
    name = "不必了，我们还有事。"
  },
  [111440180] = {
    id = 111440180,
    name = "可、可是——"
  },
  [111440181] = {
    id = 111440181,
    name = "你看出商人在担忧刚才的劫匪。"
  },
  [111440182] = {
    id = 111440182,
    name = "放心，刚才那伙人被我同伴废掉了战力，一时半会儿不会回来。"
  },
  [111440183] = {
    id = 111440183,
    name = "至于前面，我们会清除沿途的威胁。"
  },
  [111440184] = {
    id = 111440184,
    name = "只要你们不是太慢，自然可以平安抵达。"
  },
  [111440185] = {
    id = 111440185,
    name = "这......那好吧。"
  },
  [111440186] = {
    id = 111440186,
    name = "告别商队后，你们继续朝着商业据点前行。"
  },
  [111440187] = {
    id = 111440187,
    name = "你拒绝得很干脆。"
  },
  [111440188] = {
    id = 111440188,
    name = "委托优先，而且——"
  },
  [111440189] = {
    id = 111440189,
    name = "而且“不可以与陌生人有过多交集”。"
  },
  [111440190] = {
    id = 111440190,
    name = "听着你的话，浮光微微一笑。"
  },
  [111440191] = {
    id = 111440191,
    name = "看来队长已经很熟悉深渊航线的规则了，要来深渊航线兼职吗？"
  },
  [111440192] = {
    id = 111440192,
    name = "呵呵，如果同伴需要我协助，我不会拒绝。"
  },
  [111440193] = {
    id = 111440193,
    name = "你们一边闲聊一边赶路，不远处已隐约可以看到商业据点的建筑了。"
  },
  [111440194] = {
    id = 111440194,
    name = "商业据点。"
  },
  [111440195] = {
    id = 111440195,
    name = "各类商铺林立，行人如织，讨价还价的声音不绝于耳。"
  },
  [111440196] = {
    id = 111440196,
    name = "来往的商人、佣兵、探险者混杂在一起，空气中弥漫着金属、香料与魔力装置运转的气味。"
  },
  [111440197] = {
    id = 111440197,
    name = "与寻常据点相比，这里显得异常热闹。"
  },
  [111440198] = {
    id = 111440198,
    name = "这就是商业据点吗，和寻常据点圈落的氛围完全不一样。"
  },
  [111440199] = {
    id = 111440199,
    name = "比我上次来的时候......人多了不少。"
  },
  [111440200] = {
    id = 111440200,
    name = "浮光带着好奇的目光扫过街道两旁的店铺，似乎有些兴趣，但脚下的速度丝毫没有慢下来。"
  },
  [111440201] = {
    id = 111440201,
    name = "到达一个岔路口时，她便向你辞别。"
  },
  [111440202] = {
    id = 111440202,
    name = "这一路上非常感谢队长的关照。"
  },
  [111440203] = {
    id = 111440203,
    name = "我先去交付委托了。"
  },
  [111440204] = {
    id = 111440204,
    name = "浮光小姐客气了，希望以后还有机会再见。"
  },
  [111440205] = {
    id = 111440205,
    name = "浮光微微点了点头，便转身向远处走去。"
  },
  [111440206] = {
    id = 111440206,
    name = "那接下来就去那几家老店看看吧，希望这次能找到些好东西。"
  },
  [111440207] = {
    id = 111440207,
    name = "你略微沉吟，向着一条小巷走了过去......"
  },
  [111440208] = {
    id = 111440208,
    name = "验货、交接、签字，浮光熟练完成了委托的最后工作。"
  },
  [111440209] = {
    id = 111440209,
    name = "正当她走出办事处，准备去那些感兴趣的商铺逛逛时，一名衣着考究的中年商人匆匆追了上来。"
  },
  [111440210] = {
    id = 111440210,
    name = "浮光小姐，请留步！"
  },
  [111440211] = {
    id = 111440211,
    name = "来人正是刚才接收委托货物的商人。"
  },
  [111440212] = {
    id = 111440212,
    name = "请问还有什么事吗？刚才签字后委托就结束了。"
  },
  [111440213] = {
    id = 111440213,
    name = "商人稍微调整了一下气息，语气稍显急切。"
  },
  [111440214] = {
    id = 111440214,
    name = "当然！浮光小姐是我这段时间遇到过的最出色的受雇者。"
  },
  [111440215] = {
    id = 111440215,
    name = "不仅货物完好无损，而且时间还提前了不少。"
  },
  [111440216] = {
    id = 111440216,
    name = "只是按约完成委托而已。"
  },
  [111440217] = {
    id = 111440217,
    name = "商人突然靠近了一些，压低声音。"
  },
  [111440218] = {
    id = 111440218,
    name = "其实......我这里，还有一份委托......"
  },
  [111440219] = {
    id = 111440219,
    name = "如果是委托相关的事务，您可以前往深渊航线办事处提交需求。"
  },
  [111440220] = {
    id = 111440220,
    name = "当然，我知道深渊航线的流程，而且也知道可以指定承接委托的人员......"
  },
  [111440221] = {
    id = 111440221,
    name = "那您为什么——"
  },
  [111440222] = {
    id = 111440222,
    name = "我这份委托......眼下只有浮光小姐才能胜任！"
  },
  [111440223] = {
    id = 111440223,
    name = "深渊航线办事处那边，想要指定浮光小姐的委托人太多了。"
  },
  [111440224] = {
    id = 111440224,
    name = "如果我现在才去提交申请，根本来不及。"
  },
  [111440225] = {
    id = 111440225,
    name = "看着商人恳切的目光，浮光有些不知所措。"
  },
  [111440226] = {
    id = 111440226,
    name = "她很不擅长拒绝别人的请求，特别是眼前这种带着强烈情感的请求。"
  },
  [111440227] = {
    id = 111440227,
    name = "短暂沉默后，浮光才缓缓开口。"
  },
  [111440228] = {
    id = 111440228,
    name = "我的下一份委托确实还没有派发下来，当下确实能承接你的委托，但组织那边——"
  },
  [111440229] = {
    id = 111440229,
    name = "我明白的！"
  },
  [111440230] = {
    id = 111440230,
    name = "见浮光有答应的可能，商人两眼放光，语气也激动不少。"
  },
  [111440231] = {
    id = 111440231,
    name = "您放心，我会为您向深渊航线那边补全所有的说明材料，相关的费用我也会妥善安排。"
  },
  [111440232] = {
    id = 111440232,
    name = "当然，您的酬劳，绝对会让您满意。"
  },
  [111440233] = {
    id = 111440233,
    name = "商人凑得更近了一些，在浮光耳边低声说了一个数字。"
  },
  [111440234] = {
    id = 111440234,
    name = "浮光眉头微不可察的一动，商人刚才说的数字确实远高于标准。"
  },
  [111440235] = {
    id = 111440235,
    name = "......酬劳确实不菲。"
  },
  [111440236] = {
    id = 111440236,
    name = "那先和我说说是怎样的委托吧，如果超出我的能力——"
  },
  [111440237] = {
    id = 111440237,
    name = "以浮光小姐的实力，肯定没问题！"
  },
  [111440238] = {
    id = 111440238,
    name = "嘿嘿，不过这里不是说话的地方，我们去我店里详谈吧。"
  },
  [111440239] = {
    id = 111440239,
    name = "在几家熟悉的店逛了一番后，你并没有找到想要的东西。"
  },
  [111440240] = {
    id = 111440240,
    name = "还好淘到些新奇的物件，倒也不算白来。"
  },
  [111440241] = {
    id = 111440241,
    name = "你走出小巷，正思考接下来的行动时，突然看到浮光正站在街口四处张望。"
  },
  [111440242] = {
    id = 111440242,
    name = "你略微沉吟，走了上去。"
  },
  [111440243] = {
    id = 111440243,
    name = "遇到什么麻烦了吗，浮光小姐。"
  },
  [111440244] = {
    id = 111440244,
    name = "啊，队长！我、我正在找你。"
  },
  [111440245] = {
    id = 111440245,
    name = "见你突然出现，浮光显得有些惊喜。"
  },
  [111440246] = {id = 111440246, name = "找我？"},
  [111440247] = {id = 111440247, name = "......"},
  [111440248] = {
    id = 111440248,
    name = "片刻后，你从浮光口中得知了她找你的原因。"
  },
  [111440249] = {
    id = 111440249,
    name = "也就是说，那位商人希望你能为他护送一些绝密货物到水滨据点。"
  },
  [111440250] = {
    id = 111440250,
    name = "但你并没有独自完成委托的自信，所以希望我协助你？"
  },
  [111440251] = {
    id = 111440251,
    name = "正是这样。"
  },
  [111440252] = {id = 111440252, name = "......"},
  [111440253] = {
    id = 111440253,
    name = "我记得这个据点中有深渊航线的办事处吧，浮光小姐为何不向同组织的人求助呢。"
  },
  [111440254] = {
    id = 111440254,
    name = "我原本也是这样打算的。"
  },
  [111440255] = {
    id = 111440255,
    name = "但办事处的人告诉我，最近商业据点委托数量很多，别说得力的精英，就连普通办事人员一时都难以找到......"
  },
  [111440256] = {
    id = 111440256,
    name = "眼下我能想到的可靠人选，就只有队长您了。"
  },
  [111440257] = {
    id = 111440257,
    name = "能得到浮光小姐的认可是我的荣幸。"
  },
  [111440258] = {
    id = 111440258,
    name = "不过......我并非深渊航线的人，由我协助不会有问题吗？"
  },
  [111440259] = {
    id = 111440259,
    name = "这确实不符合组织的规定。"
  },
  [111440260] = {
    id = 111440260,
    name = "但这次委托，没有经过组织......"
  },
  [111440261] = {
    id = 111440261,
    name = "浮光的回答让你略感惊讶，在你看来，她并不像一个看中报酬的人。"
  },
  [111440262] = {
    id = 111440262,
    name = "眼下我确实没有别的要紧事务。"
  },
  [111440263] = {
    id = 111440263,
    name = "我能了解一下浮光小姐选择接受这个委托的理由吗？"
  },
  [111440264] = {
    id = 111440264,
    name = "如果希望我协助，我想知道更多详细情况。"
  },
  [111440265] = {id = 111440265, name = "嗯。"},
  [111440266] = {
    id = 111440266,
    name = "前段时间，我居住了很久的一个据点被魔物破坏了，最近正在重建。"
  },
  [111440267] = {
    id = 111440267,
    name = "委托人这次提供的报酬非常丰厚，如果我能完成，就能为那个据点的重建提供更多援助。"
  },
  [111440268] = {
    id = 111440268,
    name = "另外......"
  },
  [111440269] = {
    id = 111440269,
    name = "委托人说这一批绝密货物对他而言非常重要，在向我发起请求时表现非常诚恳。"
  },
  [111440270] = {
    id = 111440270,
    name = "甚至我去他店里详谈时，他的母亲也出来恳求，希望我能再帮她儿子一次。"
  },
  [111440271] = {
    id = 111440271,
    name = "他的母亲？浮光小姐此前说他是一位中年人吧，他的母亲岂不是......"
  },
  [111440272] = {
    id = 111440272,
    name = "嗯，一位慈祥的老夫人。"
  },
  [111440273] = {
    id = 111440273,
    name = "我实在不知道该怎么拒绝，就答应下来了......"
  },
  [111440274] = {
    id = 111440274,
    name = "浮光微微低下头，显得有些低落。"
  },
  [111440275] = {
    id = 111440275,
    name = "似乎对自己接下委托这件事，仍有些不安。"
  },
  [111440276] = {
    id = 111440276,
    name = "原来如此。"
  },
  [111440277] = {
    id = 111440277,
    name = "队长能答应我吗？"
  },
  [111440278] = {
    id = 111440278,
    name = "我似乎没有拒绝浮光小姐的理由。"
  },
  [111440279] = {
    id = 111440279,
    name = "啊！谢谢你，队长！"
  },
  [111440280] = {
    id = 111440280,
    name = "浮光眼睛一亮，显得非常欣喜。"
  },
  [111440281] = {
    id = 111440281,
    name = "队长，那我们——"
  },
  [111440282] = {
    id = 111440282,
    name = "呵呵，不急。"
  },
  [111440283] = {
    id = 111440283,
    name = "在正式答应之前，能带我去见见那个委托人吗？"
  },
  [111440284] = {
    id = 111440284,
    name = "我想再确认一些委托的详细信息。"
  },
  [111440285] = {
    id = 111440285,
    name = "当然没问题！"
  },
  [111440286] = {
    id = 111440286,
    name = "你跟随浮光到达商人的店里后，商人便将一口大箱子搬了出来。"
  },
  [111440287] = {
    id = 111440287,
    name = "你目光微微收紧，看出了木箱布置下的各种魔法防护。"
  },
  [111440288] = {
    id = 111440288,
    name = "防尘、防水、防窥测......"
  },
  [111440289] = {
    id = 111440289,
    name = "这种规格的封装......不常见。"
  },
  [111440290] = {
    id = 111440290,
    name = "商人点头。"
  },
  [111440291] = {
    id = 111440291,
    name = "阁下好眼力。"
  },
  [111440292] = {
    id = 111440292,
    name = "不错，这里面就是我想要二位护送前往水滨据点的货物。"
  },
  [111440293] = {
    id = 111440293,
    name = "这里距水滨据点路途遥远，带着这么明显的货物赶路，此行恐怕不会太轻松。"
  },
  [111440294] = {
    id = 111440294,
    name = "唉，谁说不是呢。"
  },
  [111440295] = {
    id = 111440295,
    name = "所以我才需要可靠的人。"
  },
  [111440296] = {
    id = 111440296,
    name = "商人看向你和浮光，露出一副非你们不可的表情。"
  },
  [111440297] = {
    id = 111440297,
    name = "你和浮光对视了一眼，浮光轻轻点了点头。"
  },
  [111440298] = {
    id = 111440298,
    name = "那么我们聊聊详细的护送要求吧。"
  },
  [111440299] = {
    id = 111440299,
    name = "商人眼睛一亮，脸上堆笑，急忙和你说起自己的需求。"
  },
  [111440300] = {
    id = 111440300,
    name = "这次运送，首先我想要确保的，就是这里面的货物完好无损。"
  },
  [111440301] = {
    id = 111440301,
    name = "其次，我希望二位能对这批货物的来源和目的地完全保密。"
  },
  [111440302] = {
    id = 111440302,
    name = "这是自然。"
  },
  [111440303] = {
    id = 111440303,
    name = "浮光也点了点头。"
  },
  [111440304] = {
    id = 111440304,
    name = "对深渊航线而言，这只是基本要求。"
  },
  [111440305] = {
    id = 111440305,
    name = "多谢二位理解，至于第三点，请二位务必确保这些货物能在约定的时间之前达到。"
  },
  [111440306] = {
    id = 111440306,
    name = "如果延误，哪怕只有一天，对我而言都是巨大损失。"
  },
  [111440307] = {
    id = 111440307,
    name = "你心里默默计算了一下，如果途中没有什么意外，时间倒不是什么问题。"
  },
  [111440308] = {
    id = 111440308,
    name = "但在深渊中长途奔走，想要不发生意外，根本不可能。"
  },
  [111440309] = {
    id = 111440309,
    name = "想到这里，你看向了浮光。"
  },
  [111440310] = {
    id = 111440310,
    name = "浮光似乎也明白了你的意思。"
  },
  [111440311] = {
    id = 111440311,
    name = "老板，之前我说过，约定的时间太紧张了，只要发生一点意外，就可能延误。"
  },
  [111440312] = {
    id = 111440312,
    name = "唉，我也没办法，这批货物关乎我的身家性命，只有拜托你们，我觉得才有可能做到。"
  },
  [111440313] = {
    id = 111440313,
    name = "你摆了摆手，制止了老板继续诉苦。"
  },
  [111440314] = {
    id = 111440314,
    name = "深渊中的危险，老板应该很清楚。"
  },
  [111440315] = {
    id = 111440315,
    name = "时间我们只能尽量确保。"
  },
  [111440316] = {
    id = 111440316,
    name = "而且真到需要抉择的时候，我们只能优先确保你的安全。"
  },
  [111440317] = {
    id = 111440317,
    name = "不、不用管我。"
  },
  [111440318] = {
    id = 111440318,
    name = "老板你不是也要过去吗？"
  },
  [111440319] = {
    id = 111440319,
    name = "对，我也会过去，但你们只需要确保我的货物就行。"
  },
  [111440320] = {
    id = 111440320,
    name = "我今晚会先启程，到水滨据点等你们。"
  },
  [111440321] = {
    id = 111440321,
    name = "意思是本次委托，我们只需要护送货物就可以了吗？"
  },
  [111440322] = {id = 111440322, name = "没错。"},
  [111440323] = {
    id = 111440323,
    name = "如果是这样——"
  },
  [111440324] = {
    id = 111440324,
    name = "你看了一眼浮光，她也冲你肯定的点了点头。"
  },
  [111440325] = {
    id = 111440325,
    name = "那时间上我们应该可以确保。"
  },
  [111440326] = {
    id = 111440326,
    name = "你见识过浮光的身手，如果赶路途中只需要保护货物，遇到危险时，你也有自信能和浮光一起迅速摆脱。"
  },
  [111440327] = {
    id = 111440327,
    name = "太感谢二位了！"
  },
  [111440328] = {
    id = 111440328,
    name = "我就知道你们可以做到！"
  },
  [111440329] = {
    id = 111440329,
    name = "商人兴奋不已，急忙将本次委托的一些信息写下来交给你们。"
  },
  [111440330] = {
    id = 111440330,
    name = "你和浮光在收拾好货物后，决定在据点中休息一晚，补齐远行所需物资，第二天一早出发。"
  },
  [112160001] = {
    id = 112160001,
    name = "素材商店内，艾格尼丝正为后续的修行做准备。"
  },
  [112160002] = {
    id = 112160002,
    name = "魔石......得多准备一点......"
  },
  [112160003] = {
    id = 112160003,
    name = "这个素材看起来也不错......"
  },
  [112160004] = {
    id = 112160004,
    name = "不多时，艾格尼丝便拿着满满一大袋素材放到了柜台上。"
  },
  [112160005] = {
    id = 112160005,
    name = "商人从柜台后探出头来。"
  },
  [112160006] = {
    id = 112160006,
    name = "看着堆满柜台的商品，忧虑的脸上闪过几分喜色。"
  },
  [112160007] = {
    id = 112160007,
    name = "客人眼光真不错，选了不少好东西啊。"
  },
  [112160008] = {
    id = 112160008,
    name = "老板，我一次性采购这么多素材，没有什么优惠吗？"
  },
  [112160009] = {
    id = 112160009,
    name = "商人摆出一副为难的模样。"
  },
  [112160010] = {
    id = 112160010,
    name = "看客人您的样子也是探险者，您应该知道最近生意有多难做吧？"
  },
  [112160011] = {
    id = 112160011,
    name = "唉，特别是这些修行素材，利润可低了。"
  },
  [112160012] = {
    id = 112160012,
    name = "你就别诉苦了，没有优惠就算了。"
  },
  [112160013] = {
    id = 112160013,
    name = "感谢客人理解，这就给您算一下价钱。"
  },
  [112160014] = {
    id = 112160014,
    name = "趁商人算账的功夫，艾格尼丝打量起店内陈列的物件。"
  },
  [112160015] = {
    id = 112160015,
    name = "扫视一圈后，她的眼光落在了一份被皮革包裹的卷轴上。"
  },
  [112160016] = {
    id = 112160016,
    name = "老板，那份卷轴是什么？"
  },
  [112160017] = {
    id = 112160017,
    name = "商人扫了一眼又低头算起了账。"
  },
  [112160018] = {
    id = 112160018,
    name = "那个啊，是一份修行笔记。"
  },
  [112160019] = {
    id = 112160019,
    name = "商人说着用余光瞥了瞥艾格尼丝。"
  },
  [112160020] = {
    id = 112160020,
    name = "放在那有段时间了，一直在等一个识货的客人带走它呢。"
  },
  [112160021] = {
    id = 112160021,
    name = "我能看看吗？"
  },
  [112160022] = {
    id = 112160022,
    name = "一般客人自然不行。"
  },
  [112160023] = {
    id = 112160023,
    name = "但您作为本店的贵宾，就破例让您试看吧。"
  },
  [112160024] = {
    id = 112160024,
    name = "得到商人的许可后，艾格尼丝小心翼翼将其取下、展开。"
  },
  [112160025] = {
    id = 112160025,
    name = "魔法和武技同时修行的可行性推导......魔法和武技同时修行心得......"
  },
  [112160026] = {
    id = 112160026,
    name = "这是......关于魔法和武技双修的手稿。"
  },
  [112160027] = {
    id = 112160027,
    name = "看到内容的瞬间，艾格尼丝的呼吸微微一滞。"
  },
  [112160028] = {
    id = 112160028,
    name = "她强装镇定，假装随意翻看了一下，便将卷轴合上。"
  },
  [112160029] = {
    id = 112160029,
    name = "然而她刚才的一举一动都被“低头”算账的商人看了个清楚。"
  },
  [112160030] = {
    id = 112160030,
    name = "老板，这份修行笔记怎么卖。"
  },
  [112160031] = {
    id = 112160031,
    name = "商人轻轻笑了笑，报出一个让艾格尼丝难以承受的价格。"
  },
  [112160032] = {
    id = 112160032,
    name = "（这份修行笔记看起来是真货，但太贵了......）"
  },
  [112160033] = {
    id = 112160033,
    name = "（如果要买它，这些素材就只能放弃。）"
  },
  [112160034] = {
    id = 112160034,
    name = "（可是如果买了手稿却没有素材......）"
  },
  [112160035] = {
    id = 112160035,
    name = "（如果拜托老板帮忙留一段时间，我去筹钱......）"
  },
  [112160036] = {
    id = 112160036,
    name = "（可恶，早知道就多接一些委托了。）"
  },
  [112160037] = {
    id = 112160037,
    name = "思考了一番，艾格尼丝素材和手稿都不想舍弃，也都想尽快得到。"
  },
  [112160038] = {
    id = 112160038,
    name = "老板，我都卖了这么多素材了，那份修行笔记真不能便宜点吗？"
  },
  [112160039] = {
    id = 112160039,
    name = "客人，那份修行笔记是以前一个客人用来抵账的。"
  },
  [112160040] = {
    id = 112160040,
    name = "价格就是我刚才报给你的，真不赚你钱。"
  },
  [112160041] = {
    id = 112160041,
    name = "抵账......要不我也用其他东西来抵账吧。"
  },
  [112160042] = {
    id = 112160042,
    name = "我身上这些物件，你看看哪些可以抵账。"
  },
  [112160043] = {
    id = 112160043,
    name = "艾格尼丝说着将随身带的一些物品摆到了柜台上。"
  },
  [112160044] = {
    id = 112160044,
    name = "商人简单看了一眼，摇了摇头。"
  },
  [112160045] = {
    id = 112160045,
    name = "客人，您这些物件，我没办法通融啊。"
  },
  [112160046] = {
    id = 112160046,
    name = "艾格尼丝叹了口气，又忽然想到一个方法。"
  },
  [112160047] = {
    id = 112160047,
    name = "对了，老板有什么麻烦吗？我帮你解决麻烦怎么样？"
  },
  [112160048] = {
    id = 112160048,
    name = "唉，麻烦就是赚不到钱。"
  },
  [112160049] = {
    id = 112160049,
    name = "我就这么点儿生意，能雇佣你们探险者的地方太少了。"
  },
  [112160050] = {id = 112160050, name = "......"},
  [112160051] = {
    id = 112160051,
    name = "又沟通了一番依然无果，艾格尼丝有些沮丧，于是带着购买的素材准备离开。"
  },
  [112160052] = {
    id = 112160052,
    name = "看着艾格尼丝离开的背影，商人忽然想起了什么。"
  },
  [112160053] = {
    id = 112160053,
    name = "他在账簿上快速计算了一番，随即喊住了艾格尼丝。"
  },
  [112160054] = {
    id = 112160054,
    name = "客人留步。"
  },
  [112160055] = {
    id = 112160055,
    name = "嗯？老板肯便宜卖给我了吗？"
  },
  [112160056] = {
    id = 112160056,
    name = "这个自然还是不行，不过客人刚才不是说可以帮我解决麻烦吗？"
  },
  [112160057] = {
    id = 112160057,
    name = "我突然想起下个月还真有个委托，如果客人愿意——"
  },
  [112160058] = {
    id = 112160058,
    name = "我就把那份修行笔记就作为委托的酬劳。"
  },
  [112160059] = {
    id = 112160059,
    name = "商人的目光在艾格尼丝身上游移，让艾格尼丝突然觉得一阵恶寒。"
  },
  [112160060] = {
    id = 112160060,
    name = "该不会是——"
  },
  [112160061] = {
    id = 112160061,
    name = "呵呵，您千万别误会。"
  },
  [112160062] = {
    id = 112160062,
    name = "我正经做生意，自然也是正经委托。"
  },
  [112160063] = {
    id = 112160063,
    name = "可是你刚才不是说没有需要雇佣探险者的地方吗？"
  },
  [112160064] = {
    id = 112160064,
    name = "确实不需要探险者，而是需要小姐您这样优雅大方、身材妙曼、容貌气质极佳的人。"
  },
  [112160065] = {
    id = 112160065,
    name = "什么意思？"
  },
  [112160066] = {
