    name = "就在注入的魔力刚接触第二层结构时，一股紊乱魔力突然反冲。"
  },
  [112160241] = {
    id = 112160241,
    name = "艾格尼丝迅速收手，但仍被震退半步。"
  },
  [112160242] = {id = 112160242, name = "......"},
  [112160243] = {
    id = 112160243,
    name = "回路之间存在干扰。"
  },
  [112160244] = {
    id = 112160244,
    name = "彼此之间的连结比想象中更紧密。"
  },
  [112160245] = {
    id = 112160245,
    name = "思索片刻后，她重新调整方案。"
  },
  [112160246] = {
    id = 112160246,
    name = "如果同时处理两个以上的结构，或许才能保持稳定。"
  },
  [112160247] = {
    id = 112160247,
    name = "艾格尼丝再次尝试，这一次，她同时操控两股魔力。"
  },
  [112160248] = {
    id = 112160248,
    name = "结构的稳定性果然提高。"
  },
  [112160249] = {
    id = 112160249,
    name = "她注入的魔力很顺利的便进入了结构深处。"
  },
  [112160250] = {id = 112160250, name = "......"},
  [112160251] = {
    id = 112160251,
    name = "时间一点点流逝，地面多出大量推演痕迹。"
  },
  [112160252] = {
    id = 112160252,
    name = "艾格尼丝不断尝试。"
  },
  [112160253] = {
    id = 112160253,
    name = "不断修正。"
  },
  [112160254] = {id = 112160254, name = "失败。"},
  [112160255] = {
    id = 112160255,
    name = "再尝试。"
  },
  [112160256] = {
    id = 112160256,
    name = "她的动作越来越熟练。"
  },
  [112160257] = {
    id = 112160257,
    name = "节奏越来越快。"
  },
  [112160258] = {
    id = 112160258,
    name = "她完全沉浸在了推演过程中。"
  },
  [112160259] = {
    id = 112160259,
    name = "外界的一切，毫无察觉。"
  },
  [112160260] = {
    id = 112160260,
    name = "这个地方......应该就是这个结构的关键点了。"
  },
  [112160261] = {
    id = 112160261,
    name = "如果能将魔力截断......"
  },
  [112160262] = {
    id = 112160262,
    name = "经过多番尝试，艾格尼丝终于找到了这个结界的破绽。"
  },
  [112160263] = {
    id = 112160263,
    name = "眼下，距离破除结界只差最后一步。"
  },
  [112160264] = {
    id = 112160264,
    name = "又过了一段时间，艾格尼丝突然睁开了紧闭的双眼，表情严肃。"
  },
  [112160265] = {
    id = 112160265,
    name = "多股魔力从指尖涌出，直奔结界的魔法结构深处。"
  },
  [112160266] = {
    id = 112160266,
    name = "原本稳定运转的魔法结构，忽然出现了一丝迟滞。"
  },
  [112160267] = {
    id = 112160267,
    name = "下一瞬——"
  },
  [112160268] = {
    id = 112160268,
    name = "整片空间像是被轻轻“拨动”。"
  },
  [112160269] = {
    id = 112160269,
    name = "空气出现细微波纹。"
  },
  [112160270] = {
    id = 112160270,
    name = "虽然很快又恢复如常，但艾格尼丝确认自己已经找到了破解这个结界的方法。"
  },
  [112160271] = {
    id = 112160271,
    name = "成功了。"
  },
  [112160272] = {
    id = 112160272,
    name = "她平静的语气中夹杂着几分兴奋。"
  },
  [112160273] = {
    id = 112160273,
    name = "又休息了片刻，艾格尼丝确保自己的专注力和状态都已调整到最佳后，双手按向地面。"
  },
  [112160274] = {
    id = 112160274,
    name = "数股魔力向着结界的魔法结构涌去。"
  },
  [112160275] = {
    id = 112160275,
    name = "引导、偏移、截断......"
  },
  [112160276] = {
    id = 112160276,
    name = "不多时，艾格尼丝的额头上已布满细密的汗珠。"
  },
  [112160277] = {
    id = 112160277,
    name = "她身前的空间开始如水波般“荡漾”。"
  },
  [112160278] = {
    id = 112160278,
    name = "随着艾格尼丝的魔力不断涌入，维持结界运转的魔法结构不断停滞。"
  },
  [112160279] = {
    id = 112160279,
    name = "空间“荡漾”的幅度越来越大。"
  },
  [112160280] = {
    id = 112160280,
    name = "突然，伴随着一声清脆的碎裂声，“荡漾”的区域出现了一道极细的缝隙。"
  },
  [112160281] = {
    id = 112160281,
    name = "那缝隙缓慢扩大。"
  },
  [112160282] = {
    id = 112160282,
    name = "像一扇正在开启的门。"
  },
  [112160283] = {
    id = 112160283,
    name = "艾格尼丝站起身，长长吐了一口气。"
  },
  [112160284] = {
    id = 112160284,
    name = "终于......破解了。"
  },
  [112160285] = {
    id = 112160285,
    name = "不过艾格尼丝并没有急着出去。"
  },
  [112160286] = {
    id = 112160286,
    name = "她回头看向整个封印区域。"
  },
  [112160287] = {
    id = 112160287,
    name = "目光比之前更加专注。"
  },
  [112160288] = {
    id = 112160288,
    name = "主要结构已经被破解。"
  },
  [112160289] = {
    id = 112160289,
    name = "魔力循环正在一点点崩溃。"
  },
  [112160290] = {
    id = 112160290,
    name = "她抬起手。"
  },
  [112160291] = {
    id = 112160291,
    name = "指尖再次凝聚魔力。"
  },
  [112160292] = {
    id = 112160292,
    name = "目光落在尚未处理的部分魔法结构上。"
  },
  [112160293] = {
    id = 112160293,
    name = "如果继续处理。"
  },
  [112160294] = {
    id = 112160294,
    name = "再花些时间就能完全解除。"
  },
  [112160295] = {
    id = 112160295,
    name = "艾格尼丝思考着，视线无意间扫过结界外逐渐昏暗的光线。"
  },
  [112160296] = {
    id = 112160296,
    name = "艾格尼丝的动作一顿。"
  },
  [112160297] = {
    id = 112160297,
    name = "下一瞬，她像是突然想起什么。"
  },
  [112160298] = {
    id = 112160298,
    name = "糟糕！时间——"
  },
  [112160299] = {
    id = 112160299,
    name = "竟然在这个结界中耽误了这么久，这下注定要迟到了......"
  },
  [112160300] = {
    id = 112160300,
    name = "艾格尼丝神情有些沮丧。"
  },
  [112160301] = {
    id = 112160301,
    name = "既然已经迟到了，要不就将剩下的结界全部破解......"
  },
  [112160302] = {
    id = 112160302,
    name = "不行，被结界困住是预料之外的事，不管怎样，都必须尽快赶过去，给委托人一个交代。"
  },
  [112160303] = {
    id = 112160303,
    name = "而且那份修行笔记，绝不能错过。"
  },
  [112160304] = {
    id = 112160304,
    name = "艾格尼丝不再犹豫，急忙收拾好行李向结界外走去。"
  },
  [112160305] = {
    id = 112160305,
    name = "即将离开时，她忍不住又回头看了一眼。"
  },
  [112160306] = {
    id = 112160306,
    name = "结界的平衡已经被打破，魔力循环也已中断......"
  },
  [112160307] = {
    id = 112160307,
    name = "放任不管的话，过几天应该也就自然崩溃了。"
  },
  [112160308] = {
    id = 112160308,
    name = "即便有人误入，也不会再被长期困住。"
  },
  [112160309] = {
    id = 112160309,
    name = "艾格尼丝点了点头，迈步跨出了缝隙。"
  },
  [112160310] = {
    id = 112160310,
    name = "必须尽快赶到水滨据点。"
  },
  [112160311] = {
    id = 112160311,
    name = "她的身影迅速远去。"
  },
  [112160312] = {
    id = 112160312,
    name = "不多时，便消失在峡湾尽头。"
  },
  [112170001] = {
    id = 112170001,
    name = "你探险结束，刚回到据点准备休息时，发现桌上放着一封信。"
  },
  [112170002] = {
    id = 112170002,
    name = "白色的信封上点缀着淡蓝色的雪花纹章，散发着淡淡的清冷香气。"
  },
  [112170003] = {
    id = 112170003,
    name = "雪村的信......难道是認？"
  },
  [112170004] = {
    id = 112170004,
    name = "你带着几分疑惑，拆开了信。"
  },
  [112170005] = {
    id = 112170005,
    name = "雪村狩猎祭......"
  },
  [112170006] = {
    id = 112170006,
    name = "邀请近期深渊中活跃的探险者，以及雪村认可的探险者去参加的狩猎庆典吗？"
  },
  [112170007] = {
    id = 112170007,
    name = "似乎还算有趣。"
  },
  [112170008] = {
    id = 112170008,
    name = "上次去雪村时受了不少关照，这段时间难得空闲，正好去拜访一下。"
  },
  [112170009] = {
    id = 112170009,
    name = "你将信封收好，思索片刻，决定去找鎺商量一下，一起返回雪村。"
  },
  [112170010] = {id = 112170010, name = "......"},
  [112170011] = {
    id = 112170011,
    name = "队长果然也收到邀请了啊。"
  },
  [112170012] = {
    id = 112170012,
    name = "对你的到来，鎺似乎并不意外。"
  },
  [112170013] = {
    id = 112170013,
    name = "嗯？难道是你和認又推荐了我吗？"
  },
  [112170014] = {
    id = 112170014,
    name = "哈哈，我们才没那个资格呢。"
  },
  [112170015] = {
    id = 112170015,
    name = "狩猎祭算是雪村最盛大的祭典之一，长老们都非常重视。"
  },
  [112170016] = {
    id = 112170016,
    name = "我们这些年轻一代，也不是每个人都能参加。"
  },
  [112170017] = {
    id = 112170017,
    name = "说着，鎺也拿出了一封和你一样的信。"
  },
  [112170018] = {
    id = 112170018,
    name = "看吧，我们这些在外游历的年轻一代，也要收到信才代表有今年的参与资格。"
  },
  [112170019] = {
    id = 112170019,
    name = "原来如此。看来筛选比我想象中更严格。"
  },
  [112170020] = {
    id = 112170020,
    name = "那是当然。"
  },
  [112170021] = {
    id = 112170021,
    name = "至于我觉得队长一定能收到，当然是因为队长属于得到了雪村认可的人。"
  },
  [112170022] = {
    id = 112170022,
    name = "如果不出意外，今后很长一段时间内，雪村只要有活动都会邀请你。"
  },
  [112170023] = {
    id = 112170023,
    name = "恭喜你咯，队长。"
  },
  [112170024] = {
    id = 112170024,
    name = "真是受宠若惊。"
  },
  [112170025] = {
    id = 112170025,
    name = "你和鎺打趣了几句，便询问她接下来的安排。"
  },
  [112170026] = {
    id = 112170026,
    name = "你什么时候出发呢？"
  },
  [112170027] = {
    id = 112170027,
    name = "明早吧。"
  },
  [112170028] = {
    id = 112170028,
    name = "这么快？"
  },
  [112170029] = {
    id = 112170029,
    name = "当然，我必须尽快将手上的委托处理完，不然很可能赶不上狩猎祭。"
  },
  [112170030] = {
    id = 112170030,
    name = "啊？你不是出发回雪村？"
  },
  [112170031] = {
    id = 112170031,
    name = "嗯，难道队长刚才是问我什么时候出发回去？"
  },
  [112170032] = {id = 112170032, name = "......"},
  [112170033] = {id = 112170033, name = "......"},
  [112170034] = {
    id = 112170034,
    name = "哈哈哈。"
  },
  [112170035] = {
    id = 112170035,
    name = "此前家族给了我一个特殊委托，所以我也没有告诉你们。"
  },
  [112170036] = {
    id = 112170036,
    name = "眼下就快处理好了，我需要完成后才回去。"
  },
  [112170037] = {
    id = 112170037,
    name = "需要我帮忙吗？"
  },
  [112170038] = {
    id = 112170038,
    name = "谢谢队长的好意，但这个委托稍微有点特殊，就不劳烦队长了。"
  },
  [112170039] = {id = 112170039, name = "好吧。"},
  [112170040] = {
    id = 112170040,
    name = "那我只能先行前往雪村了。"
  },
  [112170041] = {id = 112170041, name = "嗯。"},
  [112170042] = {
    id = 112170042,
    name = "真是遗憾，难得和队长单独旅行的机会，只能期待下次了。"
  },
  [112170043] = {
    id = 112170043,
    name = "你就好好处理委托吧。"
  },
  [112170044] = {
    id = 112170044,
    name = "我先到雪村找認，等你回来一起参加狩猎祭。"
  },
  [112170045] = {
    id = 112170045,
    name = "没问题！"
  },
  [112170046] = {
    id = 112170046,
    name = "告别鎺之后，你盘算着时间还算宽裕，便决定去准备有点礼物再前往雪村。"
  },
  [112170047] = {
    id = 112170047,
    name = "鎺说狩猎祭算是雪村最重要的祭典之一......"
  },
  [112170048] = {
    id = 112170048,
    name = "至少得准备点特殊的礼物才行。"
  },
  [112170049] = {
    id = 112170049,
    name = "和鎺分开后，你一边翻阅近期的探险记录，一边思索礼物的种类。"
  },
  [112170050] = {
    id = 112170050,
    name = "突然，你的目光锁定在记录中一头威风凛凛的魔物身上。"
  },
  [112170051] = {
    id = 112170051,
    name = "雪兽......"
  },
  [112170052] = {
    id = 112170052,
    name = "那是一种生活在寒冷区域的头目级魔物。"
  },
  [112170053] = {
    id = 112170053,
    name = "实力强悍，是许多探险者的噩梦。"
  },
  [112170054] = {
    id = 112170054,
    name = "不过雪兽的肉质与角质素材价值极高。"
  },
  [112170055] = {
    id = 112170055,
    name = "尤其是经过特殊处理后的尾肉，深受探险者喜爱，在圈落和据点中能卖到极高的价格。"
  },
  [112170056] = {
    id = 112170056,
    name = "就决定是你了。"
  },
  [112170057] = {
    id = 112170057,
    name = "确认目标后，你立刻着手行动。"
  },
  [112170058] = {
    id = 112170058,
    name = "数小时后，你抵达一处山崖。"
  },
  [112170059] = {
    id = 112170059,
    name = "空气中的温度明显下降。"
  },
  [112170060] = {
    id = 112170060,
    name = "四周逐渐被灰白色的寒雾覆盖。"
  },
  [112170061] = {
    id = 112170061,
    name = "地面上到处都是被利爪拖拽过的痕迹。"
  },
  [112170062] = {
    id = 112170062,
    name = "已经进入它的活动范围了吗......"
  },
  [112170063] = {
    id = 112170063,
    name = "你放缓脚步。"
  },
  [112170064] = {
    id = 112170064,
    name = "同时将手搭上武器。"
  },
  [112170065] = {
    id = 112170065,
    name = "就在你警戒时，远处忽然传来低沉的轰鸣声。"
  },
  [112170066] = {
    id = 112170066,
    name = "下一秒。"
  },
  [112170067] = {
    id = 112170067,
    name = "一头庞大的身影猛地撞碎岩壁，从寒雾中冲了出来。"
  },
  [112170068] = {
    id = 112170068,
    name = "真是急躁的家伙！"
  },
  [112170069] = {
    id = 112170069,
    name = "雪兽发出刺耳咆哮。"
  },
  [112170070] = {
    id = 112170070,
    name = "覆盖寒霜的利爪重重砸落。"
  },
  [112170071] = {
    id = 112170071,
    name = "轰——！"
  },
  [112170072] = {
    id = 112170072,
    name = "地面顿时裂开大片裂痕。"
  },
  [112170073] = {
    id = 112170073,
    name = "你迅速后撤。"
  },
  [112170074] = {
    id = 112170074,
    name = "碎石几乎擦着身体飞过。"
  },
  [112170075] = {
    id = 112170075,
    name = "不愧是头目级......"
  },
  [112170076] = {
    id = 112170076,
    name = "雪兽根本没有停顿。"
  },
  [112170077] = {
    id = 112170077,
    name = "甩动的长尾卷起大片寒气，再次横扫而来。"
  },
  [112170078] = {
    id = 112170078,
    name = "你侧身避开攻击，随后迅速逼近。"
  },
  [112170079] = {
    id = 112170079,
    name = "武器与鳞甲碰撞，爆发出刺耳声响。"
  },
  [112170080] = {
    id = 112170080,
    name = "雪兽吃痛怒吼。"
  },
  [112170081] = {
    id = 112170081,
    name = "整个裂谷都仿佛在震动。"
  },
  [112170082] = {
    id = 112170082,
    name = "寒雾被气流不断搅散。"
  },
  [112170083] = {
    id = 112170083,
    name = "战斗持续了许久。"
  },
  [112170084] = {
    id = 112170084,
    name = "地面上逐渐布满斩痕与碎裂冰层。"
  },
  [112170085] = {
    id = 112170085,
    name = "终于，伴随着最后一击落下，庞大的魔物身体轰然倒地。"
  },
  [112170086] = {id = 112170086, name = "呼......"},
  [112170087] = {
    id = 112170087,
