    name = "最终轻轻点头。"
  },
  [112200317] = {
    id = 112200317,
    name = "庭院重新恢复安静。"
  },
  [112200318] = {
    id = 112200318,
    name = "莎尔拉和莉莉安都显得有些疲惫。"
  },
  [112200319] = {
    id = 112200319,
    name = "玛琳娜静静望着星陨之塔。"
  },
  [112200320] = {id = 112200320, name = "良久。"},
  [112200321] = {
    id = 112200321,
    name = "她轻声开口。"
  },
  [112200322] = {
    id = 112200322,
    name = "看来方向没有错。"
  },
  [112200323] = {
    id = 112200323,
    name = "只是力量还不够。"
