  [112200325] = {
    id = 112200325,
    name = "玛琳娜点头。"
  },
  [112200326] = {
    id = 112200326,
    name = "这些画面。"
  },
  [112200327] = {
    id = 112200327,
    name = "更像是残留记忆。"
  },
  [112200328] = {
    id = 112200328,
    name = "而不是星陨之塔真正的力量。"
  },
  [112200329] = {
    id = 112200329,
    name = "莉莉安低头看向自己的手。"
  },
  [112200330] = {
    id = 112200330,
    name = "那该怎么办？"
  },
  [112200331] = {
    id = 112200331,
    name = "玛琳娜沉思片刻。"
  },
  [112200332] = {
    id = 112200332,
    name = "随后缓缓开口。"
  },
  [112200333] = {
    id = 112200333,
    name = "准备更多鲜血。"
  },
  [112200334] = {
    id = 112200334,
    name = "然后创造一个绝对安全的环境。"
  },
  [112200335] = {
    id = 112200335,
    name = "完全激活星陨之塔。"
  },
  [112200336] = {
    id = 112200336,
    name = "莎尔拉与莉莉安对视一眼，同时点头。"
  },
  [112200337] = {
    id = 112200337,
    name = "你也明白了她的意思。"
  },
  [112200338] = {
    id = 112200338,
    name = "如果刚才那些画面只是开始。"
  },
  [112200339] = {
    id = 112200339,
    name = "那么后续，很可能会真正触及星陨之塔隐藏的秘密。"
  },
  [112200340] = {
    id = 112200340,
    name = "看着三人坚定的目光，你决定冒险一试。"
  },
  [112200341] = {
    id = 112200341,
    name = "那我去寻找一个能够确保安全的地方，在我找到之前，就麻烦你们收集鲜血了。"
  },
  [112200342] = {
    id = 112200342,
    name = "三人同时点头。"
  },
  [112200343] = {
    id = 112200343,
    name = "拜托了。"
  },
  [112200344] = {
    id = 112200344,
    name = "离开庭院后，你思索许久，最终决定去请两个人。"
  },
  [112200345] = {
    id = 112200345,
    name = "一个自然是陆玄。"
  },
  [112200346] = {
    id = 112200346,
    name = "而另一个，则是蕾妮希雅。"
  },
  [112200347] = {
    id = 112200347,
    name = "作为掌握终焉之力的人，蕾妮希雅的实力毋庸置疑。"
  },
  [112200348] = {
    id = 112200348,
    name = "如果真有什么意外，蕾妮希雅的力量足以在关键时候确保几人的生命安全。"
  },
  [112200349] = {
    id = 112200349,
    name = "只要这两人愿意相助，你有信心创造一个“绝对安全”的环境。"
  },
  [112200350] = {id = 112200350, name = "......"},
  [112200351] = {
    id = 112200351,
    name = "数日后，一切准备妥当。"
  },
  [112200352] = {
    id = 112200352,
    name = "激活星陨之塔的鲜血。"
  },
  [112200353] = {
    id = 112200353,
    name = "预警、防护的术式和结界。"
  },
  [112200354] = {
    id = 112200354,
    name = "以及两位负责守护你们的人全部就位。"
  },
  [112200355] = {
    id = 112200355,
    name = "此刻，在一处隐蔽幽静的峡谷中。"
  },
  [112200356] = {
    id = 112200356,
    name = "星陨之塔静静悬浮在一个巨大的阵法中央。"
  },
  [112200357] = {
    id = 112200357,
    name = "你和莎尔拉三人分坐阵法内。"
  },
  [112200358] = {
    id = 112200358,
    name = "互相确认完毕后，你缓缓伸出手。"
  },
  [112200359] = {
    id = 112200359,
    name = "随着魔力催发，一丝血线从盛放鲜血容器中射向星陨之塔。"
  },
  [112200360] = {
    id = 112200360,
    name = "下一瞬，耀眼光芒冲天而起。"
  },
  [112200361] = {
    id = 112200361,
    name = "整个世界仿佛开始崩塌。"
  },
  [112200362] = {
    id = 112200362,
    name = "而你们的意识，也随之坠入了某个被遗忘的世界。"
  },
  [112210001] = {
    id = 112210001,
    name = "自由学派某个集会中心。"
  },
  [112210002] = {
    id = 112210002,
    name = "几张旧木桌摆放在大厅中央，墙壁上挂满了探险者们留下的地图、笔记以及各种奇闻记录。"
  },
  [112210003] = {
    id = 112210003,
    name = "有人正在讨论某处遗迹的新发现。"
  },
  [112210004] = {
    id = 112210004,
    name = "有人正在交换深渊中的最新情报。"
  },
  [112210005] = {
    id = 112210005,
    name = "也有人围坐在一起，分享自己刚刚结束的一场冒险。"
  },
  [112210006] = {
    id = 112210006,
    name = "就众人热闹的议论声中，一名年轻探险者匆匆走了进来。"
  },
  [112210007] = {
    id = 112210007,
    name = "请问......这里是自由学派吗？"
  },
  [112210008] = {
    id = 112210008,
    name = "正在整理资料的自由学派成员抬起头。"
  },
  [112210009] = {id = 112210009, name = "没错。"},
  [112210010] = {
    id = 112210010,
    name = "有什么事情需要帮助吗？"
  },
  [112210011] = {
    id = 112210011,
    name = "我想拜托你们调查一个地方。"
  },
  [112210012] = {id = 112210012, name = "调查？"},
  [112210013] = {
    id = 112210013,
    name = "年轻探险者点了点头。"
  },
  [112210014] = {
    id = 112210014,
    name = "最近，北方的丘陵区域出现了异常情况。"
  },
  [112210015] = {
    id = 112210015,
    name = "那里原本只有一些普通级魔物活动。"
  },
  [112210016] = {
    id = 112210016,
    name = "但是最近一段时间，魔物数量突然增加。"
  },
  [112210017] = {
    id = 112210017,
    name = "甚至有不少探险者因为这个原因，无法继续通过那片区域。"
  },
  [112210018] = {
    id = 112210018,
    name = "自由学派成员皱了皱眉。"
  },
  [112210019] = {
    id = 112210019,
    name = "魔物突然改变活动范围......"
  },
  [112210020] = {
    id = 112210020,
    name = "确实有些异常。"
  },
  [112210021] = {
    id = 112210021,
    name = "我曾拜托公会调查过，但他们只发现那里有一个废弃的遗迹。"
  },
  [112210022] = {
    id = 112210022,
    name = "目前无法确认魔物是否和遗迹有关。"
  },
  [112210023] = {
    id = 112210023,
    name = "想要进一步确认，按照他们的流程，还需要更长的时间。"
  },
  [112210024] = {
    id = 112210024,
    name = "所以，我就想请你们帮忙看看。"
  },
  [112210025] = {
    id = 112210025,
    name = "听说自由学派中奇人众多，你们会有办法吧？"
  },
  [112210026] = {
    id = 112210026,
    name = "就在这时，一直坐在旁边阅读资料的少女合上了书。"
  },
  [112210027] = {
    id = 112210027,
    name = "废弃遗迹？"
  },
  [112210028] = {
    id = 112210028,
    name = "年轻探险者看向她。"
  },
  [112210029] = {id = 112210029, name = "嗯。"},
  [112210030] = {
    id = 112210030,
    name = "根据公会的初步调查，那座遗迹已经荒废很多年了。"
  },
  [112210031] = {
    id = 112210031,
    name = "荒废很久，却突然吸引大量魔物......"
  },
  [112210032] = {
    id = 112210032,
    name = "看来那里应该发生了一些变化。"
  },
  [112210033] = {
    id = 112210033,
    name = "你的意思是？"
  },
  [112210034] = {
    id = 112210034,
    name = "少女站起身。"
  },
  [112210035] = {
    id = 112210035,
    name = "我去调查一下吧。"
  },
  [112210036] = {
    id = 112210036,
    name = "请问您是？"
  },
  [112210037] = {
    id = 112210037,
    name = "自由学派成员，阿芙佳朵。"
  },
  [112210038] = {
    id = 112210038,
    name = "你一个人吗？"
  },
  [112210039] = {id = 112210039, name = "嗯。"},
  [112210040] = {
    id = 112210040,
    name = "可是那里可能存在危险。"
  },
  [112210041] = {
    id = 112210041,
    name = "阿芙佳朵笑了笑。"
  },
  [112210042] = {
    id = 112210042,
    name = "如果因为危险就停下脚步，那大概没有多少地方值得探索了。"
  },
  [112210043] = {
    id = 112210043,
    name = "如果那里真的隐藏着什么秘密，我也很期待能够亲眼见证。"
  },
  [112210044] = {
    id = 112210044,
    name = "年轻探险者露出了安心的表情。"
  },
  [112210045] = {
    id = 112210045,
    name = "那就拜托你了。"
  },
  [112210046] = {
    id = 112210046,
    name = "放心吧。"
  },
  [112210047] = {
    id = 112210047,
    name = "我会尽快查明情况。"
  },
  [112210048] = {
    id = 112210048,
    name = "她拿起自己的装备，准备离开。"
  },
  [112210049] = {
    id = 112210049,
    name = "阿芙佳朵。"
  },
  [112210050] = {
    id = 112210050,
    name = "你不会又打算在完成任务之后，顺便调查遗迹里的秘密吧？"
  },
  [112210051] = {
    id = 112210051,
    name = "阿芙佳朵停顿了一下。"
  },
  [112210052] = {id = 112210052, name = "......"},
  [112210053] = {
    id = 112210053,
    name = "自由学派成员笑了起来。"
  },
  [112210054] = {
    id = 112210054,
    name = "看来我猜对了。"
  },
  [112210055] = {
    id = 112210055,
    name = "只是稍微看看而已。"
  },
  [112210056] = {
    id = 112210056,
    name = "每次你说“稍微看看”，都会完成全面调查后才回来。"
  },
  [112210057] = {
    id = 112210057,
    name = "当心一点，别总让自己置身险境。"
  },
  [112210058] = {
    id = 112210058,
    name = "阿芙佳朵尴尬地笑了笑。"
  },
  [112210059] = {id = 112210059, name = "放心。"},
  [112210060] = {
    id = 112210060,
    name = "我可是很珍惜自己的生命的。"
  },
  [112210061] = {
    id = 112210061,
    name = "经过几日赶路，阿芙佳朵终于抵达了委托中提到的区域。"
  },
  [112210062] = {
    id = 112210062,
    name = "这里比她想象中更加荒凉。"
  },
  [112210063] = {
    id = 112210063,
    name = "曾经存在于此的道路已经被风沙掩埋，只剩下零散的石板露出地面。"
  },
  [112210064] = {
    id = 112210064,
    name = "远处，一座古老遗迹静静矗立在丘陵之间，残破的墙壁上爬满了岁月留下的痕迹。"
  },
  [112210065] = {
    id = 112210065,
    name = "阿芙佳朵站在遗迹外围，没有急着进入，而是先拿出任务记录，仔细确认起上面的内容。"
  },
  [112210066] = {
    id = 112210066,
    name = "魔物最初只是在附近活动，后来逐渐聚集到了遗迹周围......"
  },
  [112210067] = {
    id = 112210067,
    name = "如果只是普通的栖息地变化，应该不会出现这种情况。"
  },
  [112210068] = {
    id = 112210068,
    name = "她收起记录，蹲下身查看地面上的痕迹。"
  },
  [112210069] = {
    id = 112210069,
    name = "这些脚印很新，而且数量比报告中记载的更多。"
  },
  [112210070] = {
    id = 112210070,
    name = "但是它们没有在这里建立巢穴，也没有留下争夺领地的痕迹。"
  },
  [112210071] = {
    id = 112210071,
    name = "阿芙佳朵站起身，看向遗迹深处。"
  },
  [112210072] = {
    id = 112210072,
    name = "它们似乎只是想靠近那里。"
  },
  [112210073] = {
    id = 112210073,
    name = "阿芙佳朵确认了一下装备，沿着魔物留下的痕迹向遗迹入口走去。"
  },
  [112210074] = {
    id = 112210074,
    name = "刚踏入遗迹外围，几只普通级魔物便从废墟后方冲了出来。"
  },
  [112210075] = {
    id = 112210075,
    name = "它们的行动十分急躁，直扑阿芙佳朵。"
  },
  [112210076] = {
    id = 112210076,
    name = "阿芙早有准备，一个闪身躲开攻击，随即弓弦引动，很快将所有魔物击杀。"
  },
  [112210077] = {
    id = 112210077,
    name = "看着倒下的魔物，她并没有露出轻松的表情，反而再次观察起周围。"
  },
  [112210078] = {
    id = 112210078,
    name = "魔物的状态有些奇怪。"
  },
  [112210079] = {
    id = 112210079,
    name = "并不像受到浊炁影响而狂暴，更像是被某种东西吸引。"
  },
  [112210080] = {
    id = 112210080,
    name = "就在她准备继续调查时，身后传来了脚步声。"
  },
  [112210081] = {
    id = 112210081,
    name = "看来这里确实有问题。"
  },
  [112210082] = {
    id = 112210082,
    name = "阿芙佳朵转过身，看见一名背着探险物资的女性探险者从另一侧走来。"
  },
  [112210083] = {
    id = 112210083,
    name = "你也是来调查这座遗迹的吗？"
  },
  [112210084] = {
    id = 112210084,
    name = "探险者点了点头。"
  },
  [112210085] = {
    id = 112210085,
    name = "嗯，我之前接到了附近居民的委托，所以过来看了一下。"
  },
  [112210086] = {
    id = 112210086,
    name = "不过这里比想象中复杂，我调查了一段时间，也没有找到魔物聚集的原因。"
  },
  [112210087] = {
    id = 112210087,
    name = "你有什么发现吗？"
  },
  [112210088] = {
    id = 112210088,
    name = "探险者走到一面残破的石墙旁。"
  },
  [112210089] = {
    id = 112210089,
    name = "这座遗迹虽然已经废弃很久，但很多地方保存得很完整。"
  },
  [112210090] = {
    id = 112210090,
    name = "如果只是自然荒废，应该不会留下这么多完整的结构。"
  },
  [112210091] = {
    id = 112210091,
    name = "阿芙佳朵顺着他的视线看去，墙壁上刻着一些模糊的纹路。"
  },
  [112210092] = {
    id = 112210092,
    name = "她伸手擦去表面的灰尘，认真观察起来。"
  },
  [112210093] = {
    id = 112210093,
    name = "这些纹路不像装饰。"
  },
  [112210094] = {
    id = 112210094,
    name = "你能看懂吗？"
  },
  [112210095] = {
    id = 112210095,
    name = "阿芙佳朵摇了摇头。"
  },
  [112210096] = {
    id = 112210096,
    name = "不能完全理解，不过从排列方式来看，它们更像是一种记录。"
  },
  [112210097] = {
    id = 112210097,
    name = "这里曾经有人生活过，而且他们似乎留下了某些重要的信息。"
  },
  [112210098] = {
    id = 112210098,
    name = "探险者看着遗迹深处。"
  },
  [112210099] = {
    id = 112210099,
    name = "也就是说，我们调查的可能不是一座普通遗迹。"
  },
  [112210100] = {
    id = 112210100,
    name = "至少现在看来是这样。"
  },
  [112210101] = {
    id = 112210101,
    name = "两人继续向遗迹内部探索。"
  },
  [112210102] = {
    id = 112210102,
    name = "越往深处走，过去留下的痕迹越明显。"
  },
  [112210103] = {
    id = 112210103,
    name = "破碎的石台、残缺的壁画，还有一些已经无法辨认用途的古老器具，都说明这里曾经拥有过一段不短的历史。"
  },
  [112210104] = {
    id = 112210104,
    name = "真奇怪。"
  },
  [112210105] = {
    id = 112210105,
    name = "这里不像是被遗弃，更像是发生了什么事情，让这里的人不得不离开。"
  },
  [112210106] = {
    id = 112210106,
    name = "阿芙佳朵点了点头。"
  },
  [112210107] = {
    id = 112210107,
    name = "深渊中有很多这样的地方。"
  },
  [112210108] = {
    id = 112210108,
    name = "有人为了躲避危险离开，有人为了寻找新的道路前进，也有人只是突然消失。"
  },
  [112210109] = {
    id = 112210109,
    name = "每一座遗迹背后，都可能隐藏着一段过去。"
  },
  [112210110] = {
    id = 112210110,
    name = "能够亲眼见证那些被遗忘的故事，也是探险的一部分。"
  },
  [112210111] = {
    id = 112210111,
    name = "闲聊间，两人已来到遗迹中央的一处大厅。"
  },
  [112210112] = {
    id = 112210112,
    name = "这里异常安静。"
  },
  [112210113] = {
    id = 112210113,
    name = "与外面聚集的大量魔物不同，这里甚至没有留下任何战斗痕迹。"
  },
  [112210114] = {
    id = 112210114,
    name = "这里反而没有魔物了。"
  },
  [112210115] = {
    id = 112210115,
    name = "阿芙佳朵没有立刻回答。"
  },
  [112210116] = {
    id = 112210116,
    name = "她走到大厅中央，闭上眼感受了一会周围的浊炁流动。"
  },
  [112210117] = {
    id = 112210117,
    name = "片刻后，她睁开双眼。"
  },
  [112210118] = {
    id = 112210118,
    name = "下面还有空间。"
  },
  [112210119] = {id = 112210119, name = "下面？"},
  [112210120] = {
    id = 112210120,
    name = "阿芙佳朵点了点头。"
  },
  [112210121] = {
    id = 112210121,
    name = "这里的浊炁流动和其他区域不同，应该存在隐藏区域。"
  },
  [112210122] = {
    id = 112210122,
    name = "两人开始寻找入口，最终，阿芙佳朵在石台旁发现了一块与周围略有不同的石板。"
  },
  [112210123] = {
    id = 112210123,
    name = "她轻轻按下机关。"
  },
  [112210124] = {
    id = 112210124,
    name = "伴随着沉闷的声响，地面缓缓打开，一条通往地下的通道出现在两人面前。"
  },
  [112210125] = {
    id = 112210125,
    name = "看来，我们可能要发现这座遗迹真正的秘密了。"
  },
  [112210126] = {
    id = 112210126,
    name = "不过从这里开始，应该不会再像外面那么安全了。"
  },
  [112210127] = {
    id = 112210127,
    name = "阿芙佳朵握紧武器，望向通道深处。"
  },
  [112210128] = {id = 112210128, name = "走吧。"},
  [112210129] = {
    id = 112210129,
    name = "让我们看看，这座被遗忘的遗迹里，到底隐藏着什么。"
  },
  [112210130] = {
    id = 112210130,
    name = "地下遗迹中，昏暗的通道一直延伸向深处。"
  },
  [112210131] = {
    id = 112210131,
    name = "四周十分安静，只有两人的脚步声在墙壁间不断回响。"
  },
  [112210132] = {
    id = 112210132,
    name = "阿芙佳朵走在前方，仔细观察着周围留下的痕迹。"
  },
  [112210133] = {
    id = 112210133,
    name = "这里和上面的遗迹完全不同。"
  },
  [112210134] = {
    id = 112210134,
    name = "嗯，上面的区域更像是被遗弃后的废墟，而这里更像是被刻意封闭起来的地方。"
  },
  [112210135] = {
    id = 112210135,
    name = "探险者看向墙壁上保存完整的纹路。"
  },
  [112210136] = {
    id = 112210136,
    name = "看来这里隐藏着真正的秘密。"
  },
  [112210137] = {
    id = 112210137,
    name = "或许吧，不过深渊里的秘密，往往也伴随着危险。"
  },
  [112210138] = {
    id = 112210138,
    name = "两人继续前进，很快来到了一扇巨大的石门前。"
  },
  [112210139] = {
    id = 112210139,
    name = "石门上刻着与外面相似的符号，只是保存得更加完整。"
  },
  [112210140] = {
    id = 112210140,
    name = "阿芙佳朵走近观察。"
  },
  [112210141] = {
    id = 112210141,
    name = "这些符号应该和遗迹过去的主人有关。"
  },
  [112210142] = {
    id = 112210142,
    name = "能看出它们记录了什么吗？"
  },
  [112210143] = {
    id = 112210143,
    name = "阿芙佳朵摇了摇头。"
  },
  [112210144] = {
    id = 112210144,
    name = "暂时不能，但这里应该不是普通的入口。"
  },
  [112210145] = {
    id = 112210145,
    name = "就在她准备进一步查看时，地面突然传来震动。"
  },
  [112210146] = {
    id = 112210146,
    name = "伴随着一阵机括声，石门周围亮起微弱的光芒。"
  },
  [112210147] = {
    id = 112210147,
    name = "糟糕，我们触发机关了。"
  },
  [112210148] = {
    id = 112210148,
    name = "看来这里的主人并不希望有人轻易进入。"
  },
  [112210149] = {
    id = 112210149,
    name = "下一刻，石门缓缓开启。"
  },
  [112210150] = {
    id = 112210150,
    name = "沉重的脚步声从黑暗中传来，一只巨大的魔物缓缓走出。"
  },
  [112210151] = {
    id = 112210151,
    name = "探险者脸色一变。"
  },
  [112210152] = {
    id = 112210152,
    name = "看来是个棘手的家伙。"
  },
  [112210153] = {
    id = 112210153,
    name = "魔物发出怒吼，朝两人冲来。"
  },
  [112210154] = {
    id = 112210154,
    name = "探险者试图阻挡，却被巨大的力量震退。"
  },
  [112210155] = {
    id = 112210155,
    name = "不要和它硬碰硬。"
  },
  [112210156] = {
    id = 112210156,
    name = "阿芙佳朵观察着魔物的行动。"
  },
  [112210157] = {
    id = 112210157,
    name = "它虽然力量强大，但这里的空间限制了它的行动。"
  },
  [112210158] = {
    id = 112210158,
    name = "我们先周旋一番，寻找机会攻击。"
  },
  [112210159] = {
    id = 112210159,
    name = "探险者应了一声，两人开始配合行动。"
  },
  [112210160] = {
    id = 112210160,
    name = "探险者吸引魔物注意，阿芙佳朵则不断寻找它攻击后的空隙。"
  },
  [112210161] = {
    id = 112210161,
    name = "经过几次交锋，魔物的动作逐渐出现破绽。"
  },
  [112210162] = {
    id = 112210162,
    name = "阿芙佳朵抓住机会，迅速发动攻击。"
  },
  [112210163] = {
    id = 112210163,
    name = "伴随着一声巨响，魔物终于倒下。"
  },
  [112210164] = {
    id = 112210164,
    name = "探险者靠着墙壁休息，长舒了一口气。"
  },
  [112210165] = {
    id = 112210165,
    name = "没想到这里面竟然还藏着这样的魔物。"
  },
  [112210166] = {
    id = 112210166,
    name = "有人故意将魔物封印在此作为看守......看来这个地方确实很重要。"
  },
  [112210167] = {
    id = 112210167,
    name = "刚才如果不是你，我恐怕已经受伤了。"
  },
  [112210168] = {
    id = 112210168,
    name = "不用客气，如果没有你的配合，我也无法找到攻击机会。"
  },
  [112210169] = {
    id = 112210169,
    name = "二人稍作休整，确认周围安全后，才进一步往里走去。"
  },
  [112210170] = {
    id = 112210170,
    name = "石门后方是一间小小的密室。"
  },
  [112210171] = {
    id = 112210171,
    name = "密室中央摆放着一个古老木箱。"
  },
  [112210172] = {
    id = 112210172,
    name = "看来，这就是封印魔物的人想要保护的东西。"
  },
  [112210173] = {id = 112210173, name = "嗯。"},
  [112210174] = {
    id = 112210174,
    name = "现在可以看看，这里究竟留下了什么。"
  },
  [112210175] = {
    id = 112210175,
    name = "阿芙佳朵小心打开木箱，里面并没有想象中的珍贵宝石，也没有强大的武器。"
  },
  [112210176] = {
    id = 112210176,
    name = "只有一卷保存完好的旧羊皮卷。"
  },
  [112210177] = {
    id = 112210177,
    name = "探险者有些意外。"
  },
  [112210178] = {
    id = 112210178,
    name = "这就是遗迹主人留下的东西？"
  },
  [112210179] = {
    id = 112210179,
    name = "阿芙佳朵拿起羊皮卷，仔细查看。"
  },
  [112210180] = {
    id = 112210180,
    name = "虽然看起来普通，但能在这种地方保存这么久，本身就很不寻常。"
  },
  [112210181] = {
    id = 112210181,
    name = "她轻轻展开羊皮卷。"
  },
  [112210182] = {
    id = 112210182,
    name = "上面绘制着一片陌生的区域，复杂的路线交错其中，旁边还留下了一些已经模糊的文字。"
  },
  [112210183] = {
    id = 112210183,
    name = "探险者凑近查看。"
  },
  [112210184] = {
    id = 112210184,
    name = "这是什么地图？"
  },
  [112210185] = {
    id = 112210185,
    name = "阿芙佳朵没有立刻回答，而是继续辨认上面的信息。"
  },
  [112210186] = {
    id = 112210186,
    name = "如果我没有看错......"
  },
  [112210187] = {
    id = 112210187,
    name = "这应该是一张藏宝图。"
  },
  [112210188] = {
    id = 112210188,
    name = "探险者愣了一下。"
  },
  [112210189] = {
    id = 112210189,
    name = "藏宝图？"
  },
  [112210190] = {
    id = 112210190,
    name = "阿芙佳朵点了点头。"
  },
  [112210191] = {
    id = 112210191,
    name = "上面标注了一片沙海区域，还有一个特殊的位置。"
  },
  [112210192] = {
    id = 112210192,
    name = "难道这座遗迹里真的藏着宝藏？"
  },
  [112210193] = {
    id = 112210193,
    name = "阿芙佳朵看着地图，没有立刻露出期待的表情。"
  },
  [112210194] = {
    id = 112210194,
    name = "不一定。"
  },
  [112210195] = {
    id = 112210195,
    name = "不一定？"
  },
  [112210196] = {
    id = 112210196,
    name = "深渊里的藏宝传闻很多，其中有不少最后都只是误传。"
  },
  [112210197] = {
    id = 112210197,
    name = "一张地图，并不能证明宝藏一定存在。"
  },
  [112210198] = {
    id = 112210198,
    name = "探险者仔细观察着羊皮卷。"
  },
  [112210199] = {
    id = 112210199,
    name = "可是它被放在精英级魔物守护的密室里。"
  },
  [112210200] = {
    id = 112210200,
    name = "如果只是普通的假消息，似乎没有必要做到这种程度。"
  },
  [112210201] = {
    id = 112210201,
    name = "你说得没错。"
  },
  [112210202] = {
    id = 112210202,
    name = "她再次看向地图上的路线。"
  },
  [112210203] = {
    id = 112210203,
    name = "而且这张地图的年代，似乎比这座遗迹还要久远。"
  },
  [112210204] = {
    id = 112210204,
    name = "你的意思是？"
  },
  [112210205] = {
    id = 112210205,
    name = "或许这座遗迹的主人，并不是绘制这张藏宝图的人。"
  },
  [112210206] = {
    id = 112210206,
    name = "他们只是发现了这张地图，并将它保存了下来。"
  },
  [112210207] = {
    id = 112210207,
    name = "探险者看向密室四周。"
  },
  [112210208] = {
    id = 112210208,
    name = "如果真是这样，那留下地图的人，究竟是谁？"
  },
  [112210209] = {
    id = 112210209,
    name = "这遗迹的主人为什么没有去寻找呢？"
  },
  [112210210] = {
    id = 112210210,
    name = "阿芙佳朵轻轻摇头。"
  },
  [112210211] = {
    id = 112210211,
    name = "不知道。"
  },
  [112210212] = {
    id = 112210212,
    name = "不过，这正是探险有趣的地方。"
  },
  [112210213] = {
    id = 112210213,
    name = "阿芙佳朵笑了笑，将地图递到探险者面前。"
  },
  [112210214] = {
    id = 112210214,
    name = "这份地图——"
  },
  [112210215] = {
    id = 112210215,
    name = "探险者急忙摆了摆手。"
  },
  [112210216] = {
    id = 112210216,
    name = "没有你我根本到不了这个地方，这图归你了。"
  },
  [112210217] = {
    id = 112210217,
    name = "对方的慷慨让阿芙佳朵略感惊讶。"
  },
  [112210218] = {
    id = 112210218,
    name = "无论这份藏宝图是真还是假，对探险者而言都有着极大的吸引力。"
  },
  [112210219] = {
    id = 112210219,
    name = "似乎是看出阿芙佳朵的疑惑，探险者接着说到。"
  },
  [112210220] = {
    id = 112210220,
    name = "我对自己的实力还是很清楚的，能在这周围一带平安探险就不错了。"
  },
  [112210221] = {
    id = 112210221,
    name = "只有像你这样见多识广，实力强大的探险者，才有追寻这些宝物和传说的资格。"
  },
  [112210222] = {
    id = 112210222,
    name = "这东西对我来说是祸不是福，你就安心收下吧。"
  },
  [112210223] = {
    id = 112210223,
    name = "阿芙佳朵也不再推辞，将藏宝图收了起来。"
  },
  [112210224] = {id = 112210224, name = "谢谢。"},
  [112210225] = {
    id = 112210225,
    name = "我对这张图确实很好奇。"
  },
  [112210226] = {
    id = 112210226,
    name = "因为我想知道，这张地图为什么会出现在这里。"
  },
  [112210227] = {
    id = 112210227,
    name = "是谁绘制了它，又是谁为了寻找它踏上旅途。"
  },
  [112210228] = {
    id = 112210228,
    name = "比起宝物，我更想知道和它有关的故事。"
  },
  [112210229] = {
    id = 112210229,
    name = "呵呵，如果还能再见，下次也和我说说吧，我也很好奇它背后的故事。"
  },
  [112210230] = {id = 112210230, name = "嗯。"},
  [112210231] = {
    id = 112210231,
    name = "完成遗迹调查后，阿芙佳朵带着调查报告返回了自由学派集会中心。"
  },
  [112210232] = {
    id = 112210232,
    name = "阿芙佳朵将任务报告交给负责记录的成员。"
  },
  [112210233] = {
    id = 112210233,
    name = "辛苦了，阿芙佳朵。"
  },
  [112210234] = {
    id = 112210234,
    name = "没想到北方丘陵竟然隐藏着一处地下遗迹，而且还有强大的魔物守护。"
  },
  [112210235] = {
    id = 112210235,
    name = "阿芙佳朵点了点头，取出了那卷旧羊皮卷。"
  },
  [112210236] = {
    id = 112210236,
    name = "这就是魔物守护的东西吗？"
  },
  [112210237] = {
    id = 112210237,
    name = "自由学派的成员一边说着，一边接过查看。"
  },
  [112210238] = {
    id = 112210238,
    name = "黄沙区域？"
  },
  [112210239] = {
    id = 112210239,
    name = "这个地方常年流传着各种宝物传闻。"
  },
  [112210240] = {
    id = 112210240,
    name = "难道这个标记的地方，真的会有宝物？"
  },
  [112210241] = {
    id = 112210241,
    name = "或许吧。"
  },
  [112210242] = {
    id = 112210242,
    name = "呵呵，不过那么多传闻，还从没有人真正发现过宝物。"
  },
  [112210243] = {
    id = 112210243,
    name = "不知道这份地图，是否也和那些传闻一样。"
  },
  [112210244] = {
    id = 112210244,
    name = "这位成员没有继续说下去，她重新将地图卷好。"
  },
  [112210245] = {
    id = 112210245,
    name = "根据咱们的规定，你要上交这份地图吗？"
  },
  [112210246] = {
    id = 112210246,
    name = "如果上交的话我就先送去进行价值估算，再给你对应的金币、素材。"
  },
  [112210247] = {
    id = 112210247,
    name = "如果想留下的话，就没有额外酬劳了。"
  },
  [112210248] = {
    id = 112210248,
    name = "阿芙佳朵笑了笑。"
  },
  [112210249] = {
    id = 112210249,
    name = "你知道我会怎么选择的。"
  },
  [112210250] = {
    id = 112210250,
    name = "自由学派成员叹了口气，看起来有些无奈。"
  },
  [112210251] = {
    id = 112210251,
    name = "她往阿芙佳朵身边凑了凑，低声说到。"
  },
  [112210252] = {
    id = 112210252,
    name = "这份地图虽然真假难辨，但是年份久远，而且是从遗迹中发现的。"
  },
  [112210253] = {
    id = 112210253,
    name = "按照自由学派的标准，估算价值会很高！"
  },
  [112210254] = {
    id = 112210254,
    name = "我知道你喜欢探险，但也要考虑一下自己的生活和修行支出啊。"
  },
  [112210255] = {
    id = 112210255,
    name = "作为这个集会中心里的熟人，阿芙佳朵知道对方的好意。"
  },
  [112210256] = {
    id = 112210256,
    name = "但她还是毫不犹豫地谢绝了。"
  },
  [112210257] = {
    id = 112210257,
    name = "谢谢你的好意。"
  },
  [112210258] = {
    id = 112210258,
    name = "我知道这份地图所指引的地方，大概率什么也没有。"
  },
  [112210259] = {
    id = 112210259,
    name = "不过，我很好奇它背后的故事。"
  },
  [112210260] = {
    id = 112210260,
    name = "唉，真拿你没办法。"
  },
  [112210261] = {
    id = 112210261,
    name = "不过作为朋友，我还是先提醒你一句。"
  },
  [112210262] = {
    id = 112210262,
    name = "那片沙海并不太平。"
  },
  [112210263] = {
    id = 112210263,
    name = "阿芙佳朵从对方手中接过地图，认真点头。"
  },
  [112210264] = {
    id = 112210264,
    name = "我明白。"
  },
  [112210265] = {
    id = 112210265,
    name = "追寻未知的旅途，如果太顺利，反而没什么乐趣了。"
  },
  [112210266] = {
    id = 112210266,
    name = "自由学派成员摇了摇头，没有再劝说。"
  },
  [112210267] = {
    id = 112210267,
    name = "那你准备什么时候出发。"
  },
  [112210268] = {
    id = 112210268,
    name = "休整两天，做好准备就过去吧。"
  },
  [112210269] = {
    id = 112210269,
    name = "又一个人？"
  },
  [112210270] = {id = 112210270, name = "嗯。"},
  [112210271] = {
    id = 112210271,
    name = "可是那边真的很危险噢，我说的可不只是魔物。"
  },
  [112210272] = {
    id = 112210272,
    name = "阿芙佳朵明白她的意思。"
  },
  [112210273] = {
    id = 112210273,
    name = "那片沙海中，存在各种各样的探险者，但她并不在意。"
  },
  [112210274] = {
    id = 112210274,
    name = "放心，我会谨慎行事。"
  },
  [112210275] = {
    id = 112210275,
    name = "几天后，自由学派集会中心。"
  },
  [112210276] = {
    id = 112210276,
    name = "阿芙佳朵坐在木桌旁，将藏宝图摊开，重新确认着上面的路线。"
  },
  [112210277] = {
    id = 112210277,
    name = "地图上的线条已经有些模糊，但依旧能够看出，它最终指向一片遥远的黄沙区域。"
  },
  [112210278] = {
    id = 112210278,
    name = "那里远离大多数探险者活动的范围。"
  },
  [112210279] = {
    id = 112210279,
    name = "也是许多人不愿轻易踏足的地方。"
  },
  [112210280] = {
    id = 112210280,
    name = "此前相熟的自由学派成员路过，看见阿芙佳朵正在研究地图，停下了脚步。"
  },
  [112210281] = {
    id = 112210281,
    name = "还在看那张藏宝图？"
  },
  [112210282] = {
    id = 112210282,
    name = "阿芙佳朵抬起头，笑了笑。"
  },
  [112210283] = {id = 112210283, name = "嗯。"},
  [112210284] = {
    id = 112210284,
    name = "虽然已经确认过很多次，但总觉得每次看，都能发现一些新的东西。"
  },
  [112210285] = {
    id = 112210285,
    name = "自由学派成员走近，看了一眼地图。"
  },
  [112210286] = {
    id = 112210286,
    name = "你真的打算去？"
  },
  [112210287] = {
    id = 112210287,
    name = "阿芙佳朵点了点头。"
  },
  [112210288] = {
    id = 112210288,
    name = "这是我目前最想做的事情。"
  },
  [112210289] = {
    id = 112210289,
    name = "你应该知道，这张地图很可能只是一个过去的传闻。"
  },
  [112210290] = {id = 112210290, name = "嗯。"},
  [112210291] = {
    id = 112210291,
    name = "就算真的存在所谓的宝物，也没人能保证那里安全。"
  },
  [112210292] = {
    id = 112210292,
    name = "我知道。"
  },
  [112210293] = {
    id = 112210293,
    name = "自由学派成员无奈地笑了笑。"
  },
  [112210294] = {
    id = 112210294,
    name = "既然都知道，也还是想去？"
  },
  [112210295] = {
    id = 112210295,
    name = "阿芙佳朵低头看着地图。"
  },
  [112210296] = {
    id = 112210296,
    name = "因为如果所有事情都必须确认安全以后才行动，那么很多值得发现的东西，永远都不会有人见到。"
  },
  [112210297] = {
    id = 112210297,
    name = "自由学派成员沉默了一会。"
  },
  [112210298] = {
    id = 112210298,
    name = "而且，我并不是单纯为了寻找宝物。"
  },
  [112210299] = {
    id = 112210299,
    name = "我更想知道，是什么样的人留下了这张地图，又是什么样的经历，让它最后出现在那座遗迹里。"
  },
  [112210300] = {
    id = 112210300,
    name = "你果然还是老样子。"
  },
  [112210301] = {id = 112210301, name = "什么？"},
  [112210302] = {
    id = 112210302,
    name = "总是对那些没人注意的故事感兴趣。"
  },
  [112210303] = {
    id = 112210303,
    name = "阿芙佳朵笑了起来。"
  },
  [112210304] = {
    id = 112210304,
    name = "或许吧。"
  },
  [112210305] = {
    id = 112210305,
    name = "不过深渊里最有趣的地方，不就是那些隐藏起来的故事吗？"
  },
  [112210306] = {
    id = 112210306,
    name = "之后时间里，阿芙佳朵都在为前往黄沙区域继续准备着。"
  },
  [112210307] = {
    id = 112210307,
    name = "补充饮水，整理地图，检查武器。"
  },
  [112210308] = {
    id = 112210308,
    name = "她也向自由学派的成员询问了不少关于黄沙区域的信息。"
  },
  [112210309] = {
    id = 112210309,
    name = "虽然得到的答案并不多，但每个人都提醒她要小心。"
  },
  [112210310] = {
    id = 112210310,
    name = "又过了几日，一切准备就绪。"
  },
  [112210311] = {
    id = 112210311,
    name = "她背起行囊，最后确认了一遍藏宝图。"
  },
  [112210312] = {
    id = 112210312,
    name = "那么，准备出发了。"
  },
  [112210313] = {
    id = 112210313,
    name = "祝你找到想找的东西。"
  },
  [112210314] = {
    id = 112210314,
    name = "阿芙佳朵停下脚步，回头笑了笑。"
  },
  [112210315] = {id = 112210315, name = "谢谢。"},
  [112210316] = {
    id = 112210316,
    name = "不过比起找到宝物，我更希望能遇见一段值得记住的旅程。"
  },
  [112210317] = {
    id = 112210317,
    name = "第二天清晨。"
  },
  [112210318] = {
    id = 112210318,
    name = "阿芙佳朵独自离开了，朝着黄沙区域的方向前进。"
  },
  [112210319] = {
    id = 112210319,
    name = "一路上，她穿过荒原，翻越丘陵。"
  },
  [112210320] = {
    id = 112210320,
    name = "地图上的路线逐渐变得清晰。"
  },
  [112210321] = {
    id = 112210321,
    name = "而就在她刚进入黄沙区域时，一个陌生的身影引起了她的注意。"
  },
  [112210322] = {
    id = 112210322,
    name = "一名探险者正停留在道路旁，似乎也准备前往同一个方向。"
  },
  [112220001] = {
    id = 112220001,
    name = "探险队驻地。"
  },
  [112220002] = {
    id = 112220002,
    name = "清晨的阳光洒落在驻地中，往日热闹的营地此刻显得有些冷清。"
  },
  [112220003] = {
    id = 112220003,
    name = "由于不少成员正在休假，原本应该忙碌的大厅里，只剩下少数留守成员。"
  },
  [112220004] = {
    id = 112220004,
    name = "你站在桌前，查看着刚刚收到的探索情报。"
  },
  [112220005] = {
    id = 112220005,
    name = "姬玛走到你身旁，好奇地看向桌上的资料。"
  },
  [112220006] = {
    id = 112220006,
    name = "这是新的探索任务？"
  },
  [112220007] = {id = 112220007, name = "嗯。"},
  [112220008] = {
    id = 112220008,
    name = "距离驻地不远的区域，发现了一处从未被记录过的遗迹。"
  },
  [112220009] = {
    id = 112220009,
    name = "姬玛拿起情报，仔细阅读起来。"
  },
  [112220010] = {
    id = 112220010,
    name = "从未记录过的遗迹......"
  },
  [112220011] = {
    id = 112220011,
    name = "这种情况可不常见。"
  },
  [112220012] = {
    id = 112220012,
    name = "发现遗迹的人只确认了入口的位置。"
  },
  [112220013] = {
    id = 112220013,
    name = "他们尝试靠近时，发现附近存在魔物活动的痕迹，所以没有继续深入。"
  },
  [112220014] = {
    id = 112220014,
    name = "姬玛放下手中的资料。"
  },
  [112220015] = {
    id = 112220015,
    name = "也就是说，里面有什么东西，现在还没人知道。"
  },
  [112220016] = {id = 112220016, name = "没错。"},
  [112220017] = {
    id = 112220017,
    name = "姬玛露出期待的笑容。"
  },
  [112220018] = {
    id = 112220018,
    name = "未知的遗迹，隐藏的区域，还有没有人见过的景象......"
  },
  [112220019] = {
    id = 112220019,
    name = "真让人期待。"
  },
  [112220020] = {
    id = 112220020,
    name = "我还以为你第一时间想到的是魔物。"
  },
  [112220021] = {
    id = 112220021,
    name = "怎么可能？"
  },
  [112220022] = {
    id = 112220022,
    name = "虽然战斗确实很重要，但如果探险只是为了不停战斗，那未免太无聊了。"
  },
  [112220023] = {
    id = 112220023,
    name = "姬玛看向远方。"
  },
  [112220024] = {
    id = 112220024,
    name = "真正吸引我的，是那些还没有被发现的东西。"
  },
  [112220025] = {
    id = 112220025,
    name = "看来这一点，你一直没有改变。"
  },
  [112220026] = {id = 112220026, name = "当然。"},
  [112220027] = {
    id = 112220027,
    name = "深渊里总是藏着许多不可思议的景象。"
  },
  [112220028] = {
    id = 112220028,
    name = "也许某一天，我们就会遇到从未有人见过的奇迹。"
  },
  [112220029] = {
    id = 112220029,
    name = "见姬玛如此兴奋，你决定和她先去调查一番。"
  },
  [112220030] = {
    id = 112220030,
    name = "你和姬玛整理好装备，准备前往遗迹。"
  },
  [112220031] = {
    id = 112220031,
    name = "姬玛检查着自己的武器，确认状态。"
  },
  [112220032] = {
    id = 112220032,
    name = "这次只是调查，不要因为发现新遗迹就太过深入。"
  },
  [112220033] = {
    id = 112220033,
    name = "放心吧。"
  },
  [112220034] = {
    id = 112220034,
    name = "我已经不是以前那个只会冲在最前面的小孩子了。"
  },
  [112220035] = {
    id = 112220035,
    name = "嗯，我有感受到你的变化。"
  },
  [112220036] = {
    id = 112220036,
    name = "姬玛疑惑地看向你。"
  },
  [112220037] = {
    id = 112220037,
    name = "什么意思？"
  },
  [112220038] = {
    id = 112220038,
    name = "以前的你，总想着证明自己的实力。"
  },
  [112220039] = {
    id = 112220039,
    name = "遇到危险时，总是冲锋在前，想靠自己一人解决。"
  },
  [112220040] = {
    id = 112220040,
    name = "姬玛沉默了一下。"
  },
  [112220041] = {
    id = 112220041,
    name = "但现在的你，会考虑同伴，会观察环境，也会判断风险。"
  },
  [112220042] = {
    id = 112220042,
    name = "姬玛移开视线。"
  },
  [112220043] = {
    id = 112220043,
    name = "只是稍微成熟了一点而已。"
  },
  [112220044] = {
    id = 112220044,
    name = "不过，变强本来就是为了能够面对更多挑战。"
  },
  [112220045] = {
    id = 112220045,
    name = "所以这次也算是一次检验？"
  },
  [112220046] = {
    id = 112220046,
    name = "姬玛点了点头。"
  },
  [112220047] = {id = 112220047, name = "嗯。"},
  [112220048] = {
    id = 112220048,
    name = "最近一直在修行，也不知道现在的自己究竟到了什么程度。"
  },
  [112220049] = {
    id = 112220049,
    name = "正好借这个机会看看。"
  },
  [112220050] = {
    id = 112220050,
    name = "看来你已经迫不及待了。"
  },
  [112220051] = {id = 112220051, name = "当然。"},
  [112220052] = {
    id = 112220052,
    name = "调查新遗迹的机会可不多见。"
  },
  [112220053] = {
    id = 112220053,
    name = "而且......"
  },
  [112220054] = {
    id = 112220054,
    name = "姬玛看向深渊的方向，眼中闪过期待。"
  },
  [112220055] = {
    id = 112220055,
    name = "说不定那里，会藏着什么有趣的东西。"
  },
  [112220056] = {
    id = 112220056,
    name = "经过半日的赶路，你和姬玛终于抵达了情报中记录的区域。"
  },
  [112220057] = {
    id = 112220057,
    name = "眼前的荒地与周围环境并没有太大区别，若不是提前得知这里存在遗迹，恐怕很难发现隐藏在岩壁后的入口。"
  },
  [112220058] = {
    id = 112220058,
    name = "姬玛观察着周围的环境。"
  },
  [112220059] = {
    id = 112220059,
    name = "这里就是情报中提到的地方？"
  },
  [112220060] = {id = 112220060, name = "嗯。"},
  [112220061] = {
    id = 112220061,
    name = "从周围留下的痕迹来看，魔物应该经常在附近活动。"
  },
  [112220062] = {
    id = 112220062,
    name = "姬玛蹲下身，查看地面上的脚印。"
  },
  [112220063] = {
    id = 112220063,
    name = "数量不少。"
  },
  [112220064] = {
    id = 112220064,
    name = "而且从这些痕迹来看，它们应该已经把这里当成了巢穴。"
  },
  [112220065] = {
    id = 112220065,
    name = "你点了点头。"
  },
  [112220066] = {
    id = 112220066,
    name = "先清理外围的魔物，再进入遗迹调查。"
  },
  [112220067] = {
    id = 112220067,
    name = "姬玛站起身，握紧手中的武器。"
  },
  [112220068] = {
    id = 112220068,
    name = "交给我吧。"
  },
  [112220069] = {
    id = 112220069,
    name = "你看向姬玛。"
  },
  [112220070] = {
    id = 112220070,
    name = "你确定？"
  },
  [112220071] = {id = 112220071, name = "当然。"},
  [112220072] = {
    id = 112220072,
    name = "最近这段时间，我一直在努力修行。"
  },
  [112220073] = {
    id = 112220073,
    name = "如果连这些魔物都需要你出手，那我的修行岂不是完全没有意义了？"
  },
  [112220074] = {
    id = 112220074,
    name = "看来你很有信心。"
  },
  [112220075] = {
    id = 112220075,
    name = "那是当然。"
  },
  [112220076] = {
    id = 112220076,
    name = "不过放心，我不会乱来的。"
  },
  [112220077] = {
    id = 112220077,
    name = "如果遇到无法应对的情况，我会及时请求支援。"
  },
  [112220078] = {
    id = 112220078,
    name = "你点了点头。"
  },
  [112220079] = {id = 112220079, name = "好。"},
  [112220080] = {
    id = 112220080,
    name = "那就看看你的成果吧。"
  },
  [112220081] = {
    id = 112220081,
    name = "随着你们靠近，入口周围的空气逐渐变得压抑。"
  },
  [112220082] = {
    id = 112220082,
    name = "几只魔物从岩石后方出现，注意到了闯入领地的两人。"
  },
  [112220083] = {
    id = 112220083,
    name = "姬玛看向那些魔物。"
  },
  [112220084] = {
    id = 112220084,
    name = "数量比预想中还要多一点。"
  },
  [112220085] = {
    id = 112220085,
    name = "需要我帮忙吗？"
