  [112220101] = {
    id = 112220101,
    name = "我知道。"
  },
  [112220102] = {
    id = 112220102,
    name = "深渊里最危险的，往往不是眼前的敌人。"
  },
  [112220103] = {
    id = 112220103,
    name = "你有些意外地看向姬玛。"
  },
  [112220104] = {
    id = 112220104,
    name = "姬玛笑了笑。"
  },
  [112220105] = {id = 112220105, name = "怎么？"},
  [112220106] = {
    id = 112220106,
    name = "只是觉得，你确实成长了不少。"
  },
  [112220107] = {id = 112220107, name = "当然。"},
  [112220108] = {
    id = 112220108,
    name = "毕竟我可一直都没有停下脚步。"
  },
  [112220109] = {
    id = 112220109,
    name = "走吧，我们进去看看。"
  },
  [112220110] = {
    id = 112220110,
    name = "姬玛点了点头。"
  },
  [112220111] = {id = 112220111, name = "嗯。"},
  [112220112] = {
    id = 112220112,
    name = "不知道里面会有怎样的存在。"
  },
  [112220113] = {
    id = 112220113,
    name = "姬玛的眼神充满了期待，率先走了进去。"
  },
  [112220114] = {
    id = 112220114,
    name = "你和姬玛沿着遗迹中的道路前行。"
  },
  [112220115] = {
    id = 112220115,
    name = "与普通遗迹不同，这里并没有明显的人工建筑痕迹。"
  },
  [112220116] = {
    id = 112220116,
    name = "墙壁是巨大的岩层。"
  },
  [112220117] = {
    id = 112220117,
    name = "周围生长着许多散发微光的植物，将昏暗的空间照亮。"
  },
  [112220118] = {
    id = 112220118,
    name = "姬玛停下脚步，仔细观察着周围。"
  },
  [112220119] = {
    id = 112220119,
    name = "奇怪......"
  },
  [112220120] = {
    id = 112220120,
    name = "怎么了？"
  },
  [112220121] = {
    id = 112220121,
    name = "姬玛走到墙壁旁，伸手轻轻触碰。"
  },
  [112220122] = {
    id = 112220122,
    name = "这里难道是不是人工遗迹，而是天然形成的奇景？"
  },
  [112220123] = {
    id = 112220123,
    name = "这周围完全看不到任何人工痕迹。"
  },
  [112220124] = {
    id = 112220124,
    name = "说着，她走到一株散发微光的植物旁。"
  },
  [112220125] = {
    id = 112220125,
    name = "这些植物也是。"
  },
  [112220126] = {
    id = 112220126,
    name = "我从来没有见过类似的种类。"
  },
  [112220127] = {
    id = 112220127,
    name = "姬玛轻轻靠近，观察着叶片上的纹路。"
  },
  [112220128] = {
    id = 112220128,
    name = "它们似乎会吸收周围的浊炁，然后转化成这种特殊的光芒。"
  },
  [112220129] = {
    id = 112220129,
    name = "看来这里隐藏着不少秘密。"
  },
  [112220130] = {
    id = 112220130,
    name = "姬玛点了点头。"
  },
  [112220131] = {
    id = 112220131,
    name = "你和姬玛继续前进。"
  },
  [112220132] = {
    id = 112220132,
    name = "越深入遗迹，周围的景象越发奇妙。"
  },
  [112220133] = {
    id = 112220133,
    name = "道路两侧甚至出现了漂浮在空中的晶石。"
  },
  [112220134] = {
    id = 112220134,
    name = "一些原本应该向下流淌的水流，竟然违反常理地悬浮在半空。"
  },
  [112220135] = {
    id = 112220135,
    name = "整个空间仿佛拥有自己的规则。"
  },
  [112220136] = {
    id = 112220136,
    name = "姬玛站在一片晶石前，久久没有移开视线。"
  },
  [112220137] = {
    id = 112220137,
    name = "真漂亮......"
  },
  [112220138] = {
    id = 112220138,
    name = "你看向她。"
  },
  [112220139] = {
    id = 112220139,
    name = "很少见你这么安静。"
  },
  [112220140] = {
    id = 112220140,
    name = "姬玛回过神，有些不好意思地笑了一下。"
  },
  [112220141] = {
    id = 112220141,
    name = "因为这种景象真的很难见到。"
  },
  [112220142] = {
    id = 112220142,
    name = "以前听别人讲述深渊中的奇异景象时，我总觉得那些故事像传说一样。"
  },
  [112220143] = {
    id = 112220143,
    name = "但真正亲眼看到的时候，还是会觉得不可思议。"
  },
  [112220144] = {
    id = 112220144,
    name = "所以这也是你想成为探险者的原因之一？"
  },
  [112220145] = {
    id = 112220145,
    name = "姬玛点了点头。"
  },
  [112220146] = {id = 112220146, name = "没错。"},
  [112220147] = {
    id = 112220147,
    name = "我想亲眼见证那些只存在于故事里的东西。"
  },
  [112220148] = {
    id = 112220148,
    name = "未知的区域，失落的遗迹，还有那些没人知道的秘密。"
  },
  [112220149] = {
    id = 112220149,
    name = "她看向前方。"
  },
  [112220150] = {
    id = 112220150,
    name = "如果只是为了力量或者财富，其实有很多其他方法。"
  },
  [112220151] = {
    id = 112220151,
    name = "但只有成为探险者，才能不断遇见这些意想不到的事情。"
  },
  [112220152] = {
    id = 112220152,
    name = "随着逐渐深入，你们来到一片开阔区域。"
  },
  [112220153] = {
    id = 112220153,
    name = "这里没有魔物，也没有战斗留下的痕迹。"
  },
  [112220154] = {
    id = 112220154,
    name = "只有无数奇异的景象静静存在。"
  },
  [112220155] = {
    id = 112220155,
    name = "姬玛慢慢走向中央。"
  },
  [112220156] = {
    id = 112220156,
    name = "如果不是亲眼看到，我恐怕永远不会相信这里存在。"
  },
  [112220157] = {
    id = 112220157,
    name = "深渊总是这样。"
  },
  [112220158] = {
    id = 112220158,
    name = "危险和奇迹，往往只相隔一步。"
  },
  [112220159] = {
    id = 112220159,
    name = "姬玛点了点头。"
  },
  [112220160] = {
    id = 112220160,
    name = "所以才会有人不断来到这里。"
  },
  [112220161] = {
    id = 112220161,
    name = "因为谁也不知道，下一次探索会遇见什么。"
  },
  [112220162] = {
    id = 112220162,
    name = "她看着眼前未知的空间，眼中充满期待。"
  },
  [112220163] = {
    id = 112220163,
    name = "或许这就是探险最吸引人的地方。"
  },
  [112220164] = {
    id = 112220164,
    name = "永远都有新的东西，等待我们发现。"
  },
  [112220165] = {
    id = 112220165,
    name = "不过，也别忘了保持警惕。"
  },
  [112220166] = {
    id = 112220166,
    name = "姬玛笑了一声。"
  },
  [112220167] = {
    id = 112220167,
    name = "知道啦。"
  },
  [112220168] = {
    id = 112220168,
    name = "我可不会因为看到漂亮的景色，就忘记这里是深渊。"
  },
  [112220169] = {
    id = 112220169,
    name = "随着不断深入，周围的环境逐渐变得安静。"
  },
  [112220170] = {
    id = 112220170,
    name = "没有魔物的袭击，也没有危险的气息，仿佛这片遗迹只是单纯地等待着有人发现它。"
  },
  [112220171] = {
    id = 112220171,
    name = "姬玛走在前方，观察着周围的景象。"
  },
  [112220172] = {
    id = 112220172,
    name = "这里真的很奇妙。"
  },
  [112220173] = {
    id = 112220173,
    name = "你已经说过很多次了。"
  },
  [112220174] = {
    id = 112220174,
    name = "因为真的很难不这么想啊。"
  },
  [112220175] = {
    id = 112220175,
    name = "明明是在深渊里，却感觉像进入了另一个世界。"
  },
  [112220176] = {
    id = 112220176,
    name = "她停下脚步，看向远处漂浮的晶石。"
  },
  [112220177] = {
    id = 112220177,
    name = "以前我听别人讲述深渊中的冒险故事时，总觉得那些经历距离自己很遥远。"
  },
  [112220178] = {
    id = 112220178,
    name = "什么发现古老遗迹，遇见未知魔物，找到从未有人见过的区域......"
  },
  [112220179] = {
    id = 112220179,
    name = "那时候的我，总觉得自己一定也要成为那样的探险者。"
  },
  [112220180] = {
    id = 112220180,
    name = "我觉得，你已经是那样的探险者了。"
  },
  [112220181] = {
