  [112220189] = {
    id = 112220189,
    name = "一个人？"
  },
  [112220190] = {
    id = 112220190,
    name = "姬玛点了点头。"
  },
  [112220191] = {
    id = 112220191,
    name = "小时候，我曾经遇到过一个比我厉害很多的家伙。"
  },
  [112220192] = {
    id = 112220192,
    name = "明明只比我大一点，却拥有远超我的实力。"
  },
  [112220193] = {
    id = 112220193,
    name = "姬玛笑了一下。"
  },
  [112220194] = {
    id = 112220194,
    name = "那时候的我，可不服气了。"
  },
  [112220195] = {
    id = 112220195,
    name = "我一直觉得，只要自己足够努力，就一定能追上她。"
  },
  [112220196] = {
    id = 112220196,
    name = "最开始的时候，我只是想赢她一次。"
  },
  [112220197] = {
    id = 112220197,
    name = "想证明自己也很厉害。"
  },
  [112220198] = {
    id = 112220198,
    name = "可是后来，我慢慢发现......"
  },
  [112220199] = {
    id = 112220199,
    name = "正因为有她这样的对手存在，我才会不断前进。"
  },
  [112220200] = {
    id = 112220200,
    name = "虽然以前我总说一定要超过她。"
  },
  [112220201] = {
    id = 112220201,
    name = "但如果没有她，我或许不会变成现在的自己。"
  },
  [112220202] = {
    id = 112220202,
    name = "如果有一天，你再次遇见西比尔。"
