  [112220217] = {
    id = 112220217,
    name = "哼，当然！"
  },
  [112220218] = {
    id = 112220218,
    name = "你们对视一眼，都笑了起来。"
  },
  [112220219] = {id = 112220219, name = "走吧。"},
  [112220220] = {
    id = 112220220,
    name = "前面还有地方没有探索。"
  },
  [112220221] = {
    id = 112220221,
    name = "而且......"
  },
  [112220222] = {
    id = 112220222,
    name = "我也想看看，这座遗迹究竟还藏着什么秘密。"
  },
  [112220223] = {
    id = 112220223,
    name = "随着进一步深入，周围的环境逐渐发生变化。"
  },
  [112220224] = {
    id = 112220224,
    name = "原本散发着微光的植物开始减少，四周也变得更加昏暗。"
  },
  [112220225] = {
    id = 112220225,
    name = "姬玛停下脚步，观察着前方。"
