  [112220226] = {id = 112220226, name = "奇怪。"},
  [112220227] = {
    id = 112220227,
    name = "发现什么了吗？"
  },
  [112220228] = {
    id = 112220228,
    name = "姬玛看向周围。"
  },
  [112220229] = {
    id = 112220229,
    name = "这里的气氛和刚才不一样。"
  },
  [112220230] = {
    id = 112220230,
    name = "前面的区域，似乎没有那些奇异植物存在了。"
  },
  [112220231] = {
    id = 112220231,
    name = "你也察觉到了异常。"
  },
  [112220232] = {
    id = 112220232,
    name = "空气中弥漫着一股冰冷的气息。"
  },
  [112220233] = {
    id = 112220233,
    name = "小心一点。"
  },
  [112220234] = {
    id = 112220234,
    name = "这里可能已经接近遗迹的核心区域。"
  },
  [112220235] = {
    id = 112220235,
    name = "姬玛点了点头。"
  },
  [112220236] = {id = 112220236, name = "嗯。"},
  [112220237] = {
    id = 112220237,
    name = "你们放慢脚步，谨慎前进。"
  },
  [112220238] = {
    id = 112220238,
    name = "然而，就在经过一处宽阔的洞穴时，周围突然传来一阵细微的响动。"
  },
  [112220239] = {
    id = 112220239,
    name = "你定眼看去，黑暗中，数道半透明的身影缓缓浮现。"
  },
  [112220240] = {
