  [112220249] = {
    id = 112220249,
    name = "只听轰的一声，被击中的幽灵瞬间倒地。"
  },
  [112220250] = {
    id = 112220250,
    name = "怎么样，真正的幽灵可不会轻易被我的魔法击败。"
  },
  [112220251] = {
    id = 112220251,
    name = "姬玛这才松了口气，从你身后走了出来，重新握紧武器。"
  },
  [112220252] = {
    id = 112220252,
    name = "可恶的家伙！"
  },
  [112220253] = {
    id = 112220253,
    name = "姬玛低喝一声冲了上去。"
  },
  [112220254] = {
    id = 112220254,
    name = "随着她全力进攻，不多时便将魔物全部击败。"
  },
  [112220255] = {
    id = 112220255,
    name = "真弱啊，连热身都算不上。"
  },
  [112220256] = {
    id = 112220256,
    name = "呵呵，可是你刚才——"
  },
  [112220257] = {
    id = 112220257,
    name = "姬玛立刻打断了你。"
  },
  [112220258] = {
    id = 112220258,
    name = "刚才只是没看清而已。"
  },
  [112220259] = {
    id = 112220259,
    name = "队长不许再提了！"
  },
  [112220260] = {
    id = 112220260,
    name = "呵呵，好，我什么都没看见。"
  },
  [112220261] = {
    id = 112220261,
    name = "姬玛重新看向魔物所在的区域"
  },
  [112220262] = {
    id = 112220262,
    name = "不过它们的行动感觉有些奇怪。"
  },
  [112220263] = {id = 112220263, name = "嗯？"},
  [112220264] = {
    id = 112220264,
    name = "刚才战斗时，它们的机动性还不错，可是它们却没有离开这个区域太远。"
  },
  [112220265] = {
    id = 112220265,
    name = "像是被什么东西固定在了这里。"
  },
  [112220266] = {
    id = 112220266,
    name = "先记录下来吧，回去后再详细分析。"
  },
  [112220267] = {
    id = 112220267,
    name = "你看向洞穴后方。"
  },
  [112220268] = {
    id = 112220268,
    name = "那里有一条更加隐秘的通道。"
  },
  [112220269] = {
    id = 112220269,
    name = "从魔力流动来看，那个通道后方应该就接近遗迹中心了。"
  },
  [112220270] = {
    id = 112220270,
    name = "姬玛露出期待的笑容。"
  },
  [112220271] = {
    id = 112220271,
    name = "那我们快去看看吧。"
  },
  [112220272] = {
    id = 112220272,
    name = "不要忘了刚才说过的话。"
  },
  [112220273] = {
    id = 112220273,
    name = "知道啦。"
  },
  [112220274] = {
    id = 112220274,
    name = "保持警惕。"
  },
  [112220275] = {
    id = 112220275,
    name = "穿过幽灵魔物守护的通道后，你和姬玛来到了一处巨大的空间。"
  },
  [112220276] = {
    id = 112220276,
    name = "这里与之前经过的区域完全不同，宛如一个独立的世界。"
  },
  [112220277] = {
    id = 112220277,
    name = "空间上方漂浮着无数散发柔和光芒的晶体，周围生长着从未见过的植物。"
  },
  [112220278] = {
    id = 112220278,
    name = "清澈的水流悬浮在半空，缓缓流动，仿佛不受重力影响。"
  },
  [112220279] = {
    id = 112220279,
    name = "就连空气中，都弥漫着一种难以言喻的奇妙力量。"
  },
  [112220280] = {
    id = 112220280,
    name = "姬玛停在入口处，久久没有说话。"
  },
  [112220281] = {
    id = 112220281,
    name = "你看向她。"
  },
  [112220282] = {
    id = 112220282,
    name = "怎么了？"
  },
  [112220283] = {
    id = 112220283,
    name = "姬玛回过神。"
  },
  [112220284] = {
    id = 112220284,
    name = "没什么......"
  },
  [112220285] = {
    id = 112220285,
    name = "只是有些惊讶。"
  },
  [112220286] = {
    id = 112220286,
    name = "她慢慢走向前方。"
  },
  [112220287] = {
    id = 112220287,
    name = "这真的不是在梦中吗？"
  },
  [112220288] = {
    id = 112220288,
    name = "姬玛轻轻伸出手，一片光芒从她指尖划过。"
  },
  [112220289] = {
    id = 112220289,
    name = "太不可思议了。"
  },
  [112220290] = {
    id = 112220290,
    name = "明明刚才还是充满危险的遗迹。"
  },
  [112220291] = {
    id = 112220291,
    name = "但这里......"
  },
  [112220292] = {
    id = 112220292,
    name = "感觉像是另一个世界。"
  },
  [112220293] = {id = 112220293, name = "嗯。"},
  [112220294] = {
    id = 112220294,
    name = "能够在深渊中发现这样的地方......"
  },
  [112220295] = {
    id = 112220295,
    name = "果然，探索未知才是最让人期待的事情。"
  },
  [112220296] = {
    id = 112220296,
    name = "你和姬玛缓缓深入。"
  },
  [112220297] = {
    id = 112220297,
    name = "这里没有魔物，也没有战斗留下的痕迹。"
  },
  [112220298] = {
    id = 112220298,
    name = "只有各种无法解释的奇妙景象。"
  },
  [112220299] = {
    id = 112220299,
    name = "姬玛仔细观察着周围。"
  },
  [112220300] = {
    id = 112220300,
    name = "时而记录环境，时而停下来研究那些从未见过的植物。"
  },
  [112220301] = {
    id = 112220301,
    name = "感觉你比刚才战斗的时候还认真。"
  },
  [112220302] = {id = 112220302, name = "当然。"},
  [112220303] = {
    id = 112220303,
    name = "战斗的话，只要找到敌人的弱点，总会有办法解决。"
  },
  [112220304] = {
    id = 112220304,
    name = "但这种地方不一样。"
  },
  [112220305] = {
    id = 112220305,
    name = "如果错过了，可能一辈子都不会再遇到第二次。"
  },
  [112220306] = {
    id = 112220306,
    name = "所以这也是你喜欢探险的原因？"
  },
  [112220307] = {id = 112220307, name = "嗯。"},
  [112220308] = {
    id = 112220308,
    name = "力量、名声、财富，这些东西当然也很重要。"
  },
  [112220309] = {
    id = 112220309,
    name = "但真正让我想不断前进的，是那些未知的景象。"
  },
  [112220310] = {
    id = 112220310,
    name = "因为在抵达之前，谁都不知道等待自己的会是什么。"
  },
  [112220311] = {
    id = 112220311,
    name = "也许这也是很多探险者来到深渊的原因。"
  },
  [112220312] = {id = 112220312, name = "没错。"},
  [112220313] = {
    id = 112220313,
    name = "危险和奇迹，总是同时存在。"
  },
  [112220314] = {
    id = 112220314,
    name = "你和姬玛这片区域的中心位置走去。"
  },
  [112220315] = {
    id = 112220315,
    name = "那里悬浮着一道朦胧的光幕。"
  },
  [112220316] = {
    id = 112220316,
    name = "这层光幕......"
  },
  [112220317] = {
    id = 112220317,
    name = "你感觉到了什么？"
  },
  [112220318] = {
    id = 112220318,
    name = "说不上来。"
  },
  [112220319] = {
    id = 112220319,
    name = "但我感觉，如果触碰到它似乎会发生不得了的事。"
  },
  [112220320] = {
    id = 112220320,
    name = "或许这里的秘密就隐藏在里面。"
  },
  [112220321] = {
    id = 112220321,
    name = "那我们要先撤吗，还是检查一下试试？"
  },
  [112220322] = {
    id = 112220322,
    name = "姬玛看着你的眼睛，思索片刻后给出了自己的回答。"
  },
  [112220323] = {
    id = 112220323,
    name = "我们试试吧，队长。"
  },
  [112220324] = {
    id = 112220324,
    name = "等下次再回来，说不定已经消失不见了。"
  },
  [112220325] = {
    id = 112220325,
    name = "当然，为了安全考虑，就由我来触碰，队长帮我警戒吧。"
  },
  [112220326] = {
    id = 112220326,
    name = "她的眼神中满是期待和憧憬。"
  },
  [112220327] = {
    id = 112220327,
    name = "你思索片刻后，同意了姬玛的方案。"
  },
  [112220328] = {id = 112220328, name = "好。"},
  [112220329] = {
    id = 112220329,
    name = "如果感觉不对，我们马上就撤离。"
  },
  [112220330] = {id = 112220330, name = "嗯。"},
  [112220331] = {
    id = 112220331,
    name = "和你确认后，姬玛将手缓缓伸向了那片梦幻般的光幕。"
  },
  [112230001] = {
    id = 112230001,
    name = "一年一度有关亡灵的庆典快到了，许多探险者已经开始向圈落聚集。"
  },
  [112230002] = {
    id = 112230002,
    name = "不少旅店都已挂出了满员提示，平时略显冷清的公会大厅也热闹了起来。"
  },
  [112230003] = {
    id = 112230003,
    name = "人群围在公告栏前，争相查看最新发布的委托。"
  },
  [112230004] = {
    id = 112230004,
    name = "这个委托我接了。"
  },
  [112230005] = {
    id = 112230005,
    name = "等等，我先看到的。"
  },
  [112230006] = {
    id = 112230006,
    name = "最近的委托怎么越来越难抢了。"
  },
  [112230007] = {
    id = 112230007,
    name = "面对争抢委托的探险者，负责登记的公会成员也只能无奈地表示先到先得。"
  },
  [112230008] = {
    id = 112230008,
    name = "庆典期间探险者数量增加，许多委托都是刚挂出来就没了。"
  },
  [112230009] = {
    id = 112230009,
    name = "看来今天又能早些下班了。"
  },
  [112230010] = {
    id = 112230010,
    name = "为成功接取接取委托的探险者完成登记后，公会成员一脸轻松。"
  },
  [112230011] = {
    id = 112230011,
    name = "然而，当她的目光看向委托公告栏时，脸上的笑容又凝住了。"
  },
  [112230012] = {
    id = 112230012,
    name = "那个委托已经挂了好几天了吧......"
  },
  [112230013] = {
    id = 112230013,
    name = "她看向公告栏最下方的一张委托。"
  },
  [112230014] = {
    id = 112230014,
    name = "上面记录着一处旧村庄的异常情况。"
  },
  [112230015] = {
    id = 112230015,
    name = "明明报酬并不低，为什么一直没人愿意接呢？"
  },
  [112230016] = {
    id = 112230016,
    name = "旁边的探险者听见后，也凑了过来。"
  },
  [112230017] = {
    id = 112230017,
    name = "你说那个和亡灵有关的委托？"
  },
  [112230018] = {id = 112230018, name = "嗯。"},
  [112230019] = {
    id = 112230019,
    name = "那就没办法了。"
  },
  [112230020] = {
    id = 112230020,
    name = "之前已经有好几支队伍去调查过，但最后都失败了。"
  },
  [112230021] = {
    id = 112230021,
    name = "公会成员皱起眉。"
  },
  [112230022] = {id = 112230022, name = "失败？"},
  [112230023] = {
    id = 112230023,
    name = "有人说在那里感受到了强烈的灵力波动，也有人说看到了无法解释的幻象。"
  },
  [112230024] = {
    id = 112230024,
    name = "反正从那里回来的人，都不愿意再接近那个地方。"
  },
  [112230025] = {
    id = 112230025,
    name = "公会成员眉头皱了起来，看起来有些苦恼。"
  },
  [112230026] = {
    id = 112230026,
    name = "如果一直没人处理，很可能影响那附近居民的正常生活。"
  },
  [112230027] = {
    id = 112230027,
    name = "圈落中这么多探险者，就没人能解决吗......"
  },
  [112230028] = {
    id = 112230028,
    name = "就在这时，另一名探险者走了过来。"
  },
  [112230029] = {
    id = 112230029,
    name = "如果你迫切想找人解决的话......"
  },
  [112230030] = {
    id = 112230030,
    name = "我倒是知道一个“专家”。"
  },
  [112230031] = {id = 112230031, name = "谁？"},
  [112230032] = {
    id = 112230032,
    name = "前守夜人，罗蕾娜。"
  },
  [112230033] = {
    id = 112230033,
    name = "公会成员微微一愣。"
  },
  [112230034] = {
    id = 112230034,
    name = "守夜人？"
  },
  [112230035] = {
    id = 112230035,
    name = "没错，专门与亡灵鬼魂打交道的那些家伙。"
  },
  [112230036] = {
    id = 112230036,
    name = "虽然罗蕾娜已经离开守夜人的家族，以探险者身份活动，但关于亡灵的事情......"
  },
  [112230037] = {
    id = 112230037,
    name = "我想这圈落中，应该没有人比她更了解。"
  },
  [112230038] = {
    id = 112230038,
    name = "公会成员看向那份无人接取的委托。"
  },
  [112230039] = {
    id = 112230039,
    name = "前守夜人......"
  },
  [112230040] = {
    id = 112230040,
    name = "公会成员沉默片刻。"
  },
  [112230041] = {
    id = 112230041,
    name = "随后，她上前取下了那份委托。"
  },
  [112230042] = {
    id = 112230042,
    name = "我明白了。"
  },
  [112230043] = {
    id = 112230043,
    name = "总之，我先去拜访她吧。"
  },
  [112230044] = {
    id = 112230044,
    name = "根据那位探险者提供的消息，公会成员来到了一个相对安静的旅店。"
  },
  [112230045] = {
    id = 112230045,
    name = "来到门前，公会成员平复了一下呼吸后，才敲响了房门。"
  },
  [112230046] = {
    id = 112230046,
    name = "片刻后，房门打开。"
  },
  [112230047] = {
    id = 112230047,
    name = "一名少女出现在门后。"
  },
  [112230048] = {
    id = 112230048,
    name = "她装扮朴素，与大部分探险者没什么差别，丝毫没有传闻中守夜人的样子。"
  },
  [112230049] = {
    id = 112230049,
    name = "请问有什么事吗？"
  },
  [112230050] = {
    id = 112230050,
    name = "您是罗蕾娜小姐吗？"
  },
  [112230051] = {
    id = 112230051,
    name = "罗蕾娜点了点头。"
  },
  [112230052] = {id = 112230052, name = "是我。"},
  [112230053] = {
    id = 112230053,
    name = "公会成员连忙拿出手中的委托。"
  },
  [112230054] = {
    id = 112230054,
    name = "我是公会在这个圈落中负责处置委托的人员。"
  },
  [112230055] = {
    id = 112230055,
    name = "这次冒昧前来，是希望您能帮忙处理一份委托。"
  },
  [112230056] = {
    id = 112230056,
    name = "罗蕾娜皱了皱眉，看了一眼委托内容。"
  },
  [112230057] = {
    id = 112230057,
    name = "当看到“亡灵”两个字时，她的目光微微停顿。"
  },
  [112230058] = {
    id = 112230058,
    name = "和亡灵有关？"
  },
  [112230059] = {id = 112230059, name = "是的。"},
  [112230060] = {
    id = 112230060,
    name = "地点是一处废弃村庄，最近那里出现了大量亡灵活动的迹象。"
  },
  [112230061] = {
    id = 112230061,
    name = "已经有不少探险者尝试调查，但都无功而返。"
  },
  [112230062] = {
    id = 112230062,
    name = "罗蕾娜低头看着委托。"
  },
  [112230063] = {
    id = 112230063,
    name = "片刻后，她轻轻叹了一口气。"
  },
  [112230064] = {id = 112230064, name = "抱歉。"},
  [112230065] = {
    id = 112230065,
    name = "你应该找错人了。"
  },
  [112230066] = {
    id = 112230066,
    name = "公会成员愣了一下。"
  },
  [112230067] = {
    id = 112230067,
    name = "找错人？"
  },
  [112230068] = {
    id = 112230068,
    name = "我已经不是守夜人了。"
  },
  [112230069] = {
    id = 112230069,
    name = "处理亡灵，也不再是我的职责。"
  },
  [112230070] = {
    id = 112230070,
    name = "公会成员看着她。"
  },
  [112230071] = {
    id = 112230071,
    name = "可是......"
  },
  [112230072] = {
    id = 112230072,
    name = "大家都说，您曾经是最优秀的守夜人之一。"
  },
  [112230073] = {
    id = 112230073,
    name = "罗蕾娜没有回应。"
  },
  [112230074] = {
    id = 112230074,
    name = "她只是将委托放回公会成员手中。"
  },
  [112230075] = {
    id = 112230075,
    name = "现在我只是一名普通的探险者。"
  },
  [112230076] = {
    id = 112230076,
    name = "公会成员有些焦急。"
  },
  [112230077] = {
    id = 112230077,
    name = "罗蕾娜小姐，我明白您已经离开了守夜人。"
  },
  [112230078] = {
    id = 112230078,
    name = "但是这次的情况不一样。"
  },
  [112230079] = {
    id = 112230079,
    name = "那里附近有普通居民生活，如果亡灵继续聚集，可能会造成危险。"
  },
  [112230080] = {
    id = 112230080,
    name = "罗蕾娜沉默下来。"
  },
  [112230081] = {
    id = 112230081,
    name = "公会成员继续说道。"
  },
  [112230082] = {
    id = 112230082,
    name = "这次的委托和是否是守夜人无关。"
  },
  [112230083] = {
    id = 112230083,
    name = "我们只是希望一个了解亡灵的人，去看看那里到底发生了什么。"
  },
  [112230084] = {
    id = 112230084,
    name = "罗蕾娜看向窗外。"
  },
  [112230085] = {
    id = 112230085,
    name = "街道上的人们正在为庆典做准备。"
  },
  [112230086] = {
    id = 112230086,
    name = "孩子们欢笑着跑过街道，商贩们忙碌地布置摊位。"
  },
  [112230087] = {
    id = 112230087,
    name = "片刻后，她收回目光。"
  },
  [112230088] = {
    id = 112230088,
    name = "让我再看看委托吧。"
  },
  [112230089] = {
    id = 112230089,
    name = "公会成员眼中露出喜色。"
  },
  [112230090] = {
    id = 112230090,
    name = "您愿意接受这个委托了吗？"
  },
  [112230091] = {
    id = 112230091,
    name = "罗蕾娜轻轻点头。"
  },
  [112230092] = {
    id = 112230092,
    name = "我先去看看情况吧。"
  },
  [112230093] = {
    id = 112230093,
    name = "至于能否解决，我还不敢下定论。"
  },
  [112230094] = {
    id = 112230094,
    name = "公会成员松了一口气。"
  },
  [112230095] = {
    id = 112230095,
    name = "无论如何，都非常感谢您。"
  },
  [112230096] = {
    id = 112230096,
    name = "送走公会成员后，罗蕾娜转身回到屋内。"
  },
  [112230097] = {
    id = 112230097,
    name = "她从行李中取出一把古朴的短剑，剑身上刻着守夜人的纹章。"
  },
  [112230098] = {
    id = 112230098,
    name = "她看着手中的剑，神情复杂。"
  },
  [112230099] = {
    id = 112230099,
    name = "看来......"
  },
  [112230100] = {
    id = 112230100,
    name = "这把剑，又要再次派上用场了。"
  },
  [112230101] = {
    id = 112230101,
    name = "根据委托情报，罗蕾娜来到一处村落废墟。"
  },
  [112230102] = {
    id = 112230102,
    name = "从废墟的规模来看，这里曾经生活着不少居民。"
  },
  [112230103] = {
    id = 112230103,
    name = "如今，房屋早已破败，街道上长满杂草，只剩下风吹过废墟时发出的声音。"
  },
  [112230104] = {
    id = 112230104,
    name = "罗蕾娜站在村口，安静地观察着周围。"
  },
  [112230105] = {
    id = 112230105,
    name = "这里确实残留着亡灵的气息。"
  },
  [112230106] = {
    id = 112230106,
    name = "她闭上双眼，感受着空气中的灵力波动。"
  },
  [112230107] = {
    id = 112230107,
    name = "片刻后，罗蕾娜睁开眼睛。"
  },
  [112230108] = {
    id = 112230108,
    name = "不过......"
  },
  [112230109] = {
    id = 112230109,
    name = "并没有感觉到强烈的怨念。"
  },
  [112230110] = {
    id = 112230110,
    name = "她看向村庄深处。"
  },
  [112230111] = {id = 112230111, name = "奇怪。"},
  [112230112] = {
    id = 112230112,
    name = "如果只是这种程度，普通探险者应该完全能解决。"
  },
  [112230113] = {
    id = 112230113,
    name = "罗蕾娜略微思索后，迈步进入了村庄。"
  },
  [112230114] = {
    id = 112230114,
    name = "随着不断深入，她发现这里虽然已经荒废，但并没有想象中的混乱。"
  },
  [112230115] = {
    id = 112230115,
    name = "人们似乎是有组织的撤离。"
  },
  [112230116] = {
    id = 112230116,
    name = "被抛弃的村子吗......"
  },
  [112230117] = {
    id = 112230117,
    name = "突然，不远处传来一阵轻微的声响。"
  },
  [112230118] = {
    id = 112230118,
    name = "罗蕾娜立即停下脚步，保持警戒。"
  },
  [112230119] = {
    id = 112230119,
    name = "谁在那里？"
  },
  [112230120] = {
    id = 112230120,
    name = "等了片刻也没有回应后，罗蕾娜缓缓靠近声音传来的方向。"
  },
  [112230121] = {
    id = 112230121,
    name = "在一间废弃房屋角落，她发现了一个小小的身影。"
  },
  [112230122] = {
    id = 112230122,
    name = "那是一名躲藏起来的小女孩。"
  },
  [112230123] = {
    id = 112230123,
    name = "看到罗蕾娜后，小女孩明显愣了一下。"
  },
  [112230124] = {
    id = 112230124,
    name = "你......你是谁？"
  },
  [112230125] = {
    id = 112230125,
    name = "罗蕾娜放松警戒，尽量让自己的声音保持温和。"
  },
  [112230126] = {
    id = 112230126,
    name = "我叫罗蕾娜，一名普通探险者。"
  },
  [112230127] = {
    id = 112230127,
    name = "我是接到委托，来调查这里的情况。"
  },
  [112230128] = {
    id = 112230128,
    name = "听到“调查”两个字，小女孩的表情变得紧张起来。"
  },
  [112230129] = {
    id = 112230129,
    name = "是亡灵的事吗？"
  },
  [112230130] = {
    id = 112230130,
    name = "罗蕾娜点了点头。"
  },
  [112230131] = {
    id = 112230131,
    name = "你知道什么吗？"
  },
  [112230132] = {
    id = 112230132,
    name = "小女孩张了张口，似乎想说什么，但最终没有说出来。"
  },
  [112230133] = {
    id = 112230133,
    name = "罗蕾娜见此也不勉强。"
  },
  [112230134] = {
    id = 112230134,
    name = "不知道也没关系，总之先出来吧。"
  },
  [112230135] = {
    id = 112230135,
    name = "这里可能会有危险，快回家去吧。"
  },
  [112230136] = {
    id = 112230136,
    name = "罗蕾娜只当小女孩是来废墟玩的孩子，提醒她先回家。"
  },
  [112230137] = {
    id = 112230137,
    name = "小女孩显得有些不情愿，但最终还是向废墟外走去。"
  },
  [112230138] = {
    id = 112230138,
    name = "在快要离开废墟时，小女孩忍不住回头提醒罗蕾娜。"
  },
  [112230139] = {
    id = 112230139,
    name = "姐姐，这个地方真的有亡灵。"
  },
  [112230140] = {
    id = 112230140,
    name = "看着小女孩有些担忧的样子，罗蕾娜点了点头。"
  },
  [112230141] = {
    id = 112230141,
    name = "放心，我正是为了调查此事而来。"
  },
  [112230142] = {
    id = 112230142,
    name = "夕阳逐渐落下。"
  },
  [112230143] = {
    id = 112230143,
    name = "废弃村庄被染上一层昏黄的光。"
  },
  [112230144] = {
    id = 112230144,
    name = "空气中原本稳定的灵力突然开始波动。"
  },
  [112230145] = {
    id = 112230145,
    name = "闭目养神的罗蕾娜睁开了双眼。"
  },
  [112230146] = {
    id = 112230146,
    name = "现在......"
  },
  [112230147] = {
    id = 112230147,
    name = "该开始调查了。"
  },
  [112230148] = {
    id = 112230148,
    name = "罗蕾娜独自在村庄中巡查。"
  },
  [112230149] = {
    id = 112230149,
    name = "她没有急着寻找亡灵，而是仔细观察着周围留下的痕迹。"
  },
  [112230150] = {
    id = 112230150,
    name = "墙壁上的灵力残留。"
  },
  [112230151] = {
    id = 112230151,
    name = "地面上的异常痕迹。"
  },
  [112230152] = {
    id = 112230152,
    name = "亡灵活动的痕迹不少。"
  },
  [112230153] = {
    id = 112230153,
    name = "但是它们的来源，并不像在这里死亡后自然形成的......"
  },
  [112230154] = {
    id = 112230154,
    name = "她走到一处废弃房屋前。"
  },
  [112230155] = {
    id = 112230155,
    name = "房屋内部十分凌乱。"
  },
  [112230156] = {
    id = 112230156,
    name = "但在角落里，却残留着明显的灵力波动。"
  },
  [112230157] = {
    id = 112230157,
    name = "罗蕾娜伸出手，感受着其中的信息。"
  },
  [112230158] = {
    id = 112230158,
    name = "没想到随着夜色降临，竟然会有这么充沛的灵力。"
  },
  [112230159] = {
    id = 112230159,
    name = "游荡的亡灵发现了这个灵力充沛的旧址......"
  },
  [112230160] = {
    id = 112230160,
    name = "然后不断吸引同类过来......最终形成了大量亡灵聚集吗......"
  },
  [112230161] = {
    id = 112230161,
    name = "不过这样倒也说得通了。"
  },
  [112230162] = {
    id = 112230162,
    name = "这种灵力充沛的区域确实不适合人类居住。"
  },
  [112230163] = {
    id = 112230163,
    name = "不过如此大量的亡灵，得做些准备才行。"
  },
  [112230164] = {
    id = 112230164,
    name = "罗蕾娜对这里的情况已经有了大致猜想，不再继续探查，径直走向这个废弃村落的中心。"
  },
  [112230165] = {
    id = 112230165,
    name = "她在周围废弃的石柱上刻下多个对付亡灵的魔法阵。"
  },
  [112230166] = {
    id = 112230166,
    name = "随即便静静等待着它们的到来。"
  },
  [112230167] = {
    id = 112230167,
    name = "当夜幕完全降临，废弃村庄陷入死寂。"
  },
  [112230168] = {
    id = 112230168,
    name = "忽然，一阵阴冷的风吹过，周围的温度骤然下降。"
  },
  [112230169] = {
    id = 112230169,
    name = "波动的灵力猛然增强，不少模糊的身影在村外逐渐浮现，向着村内移动。"
  },
  [112230170] = {
    id = 112230170,
    name = "果然如此。"
  },
  [112230171] = {
    id = 112230171,
    name = "白天无法觉察到它们存在，完全是因为它们躲到村外去了。"
  },
  [112230172] = {
    id = 112230172,
    name = "随着夜里村内灵力增加，它们便回来这里。"
  },
  [112230173] = {
    id = 112230173,
    name = "这样的规模，难怪之前的几支探险小队都失败了。"
  },
  [112230174] = {
    id = 112230174,
    name = "恐怕正是看到这一幕及时逃了。"
  },
  [112230175] = {
    id = 112230175,
    name = "幸好他们没有逞强，不然当这些亡灵全部苏醒时，想逃就来不及了。"
  },
  [112230176] = {
    id = 112230176,
    name = "罗蕾娜虽然赞许着此前探险者逃跑的选择，但自己却丝毫没有要离开的意思。"
  },
  [112230177] = {
    id = 112230177,
    name = "眼见复苏的亡灵越来越多，罗蕾娜激活了自己脚下的一个魔法阵。"
  },
  [112230178] = {
    id = 112230178,
    name = "顿时周围游荡的亡灵都像是发现了美味存在一般，纷纷向罗蕾娜所在的位置赶去。"
  },
  [112230179] = {
    id = 112230179,
    name = "亡灵扭动着，发出一种常人无法感受到的声音。"
  },
  [112230180] = {
    id = 112230180,
    name = "罗蕾娜没有急于攻击。"
  },
  [112230181] = {
    id = 112230181,
    name = "她闭上双眼，感受着这些亡灵的状态。"
  },
  [112230182] = {
    id = 112230182,
    name = "几乎都失去了意识，全凭本能活动吗。"
  },
  [112230183] = {
    id = 112230183,
    name = "或许连留在这个世界的执念都已忘却......"
  },
  [112230184] = {
    id = 112230184,
    name = "罗蕾娜的语气中有些许悲伤，但很快又恢复严肃。"
  },
  [112230185] = {
    id = 112230185,
    name = "看来完全无法交流了。"
  },
  [112230186] = {
    id = 112230186,
    name = "罗蕾娜睁开眼，看着靠近的亡灵，眼里没有一丝畏惧。"
  },
  [112230187] = {
    id = 112230187,
    name = "既然如此，就让我送你们离开吧。"
  },
  [112230188] = {
    id = 112230188,
    name = "似乎感觉到了罗蕾娜的意图，扑向罗蕾娜的亡灵扭动的更厉害了。"
  },
  [112230189] = {
    id = 112230189,
    name = "罗蕾娜眼神一凛，翻手间那柄属于守夜人的短剑已出鞘。"
  },
  [112230190] = {
    id = 112230190,
    name = "随着她口中吟诵数个古怪音节，短剑散发出一股强大力量。"
  },
  [112230191] = {
    id = 112230191,
    name = "冲在最前的亡灵也猛地一怔，被这股力量所震慑，但随即继续向罗蕾娜移动。"
  },
  [112230192] = {
    id = 112230192,
    name = "即便恐惧，也无法抵抗想要吞噬活人的本能吗？"
  },
  [112230193] = {
    id = 112230193,
    name = "见此情形，罗蕾娜似乎终于下定了决心，迎着距离自己最近的亡灵而去。"
  },
  [112230194] = {
    id = 112230194,
    name = "凛冽的剑光闪过，亡灵瞬间呆滞，逐渐透明，随即崩散。"
  },
  [112230195] = {
    id = 112230195,
    name = "剑锋上传来熟悉的、如同划过流水的感觉。"
  },
  [112230196] = {
    id = 112230196,
    name = "是曾经身为守夜人的罗蕾娜再熟悉不过的感觉。"
  },
  [112230197] = {
    id = 112230197,
    name = "（那段经历，果然无法轻易放下啊。）"
  },
  [112230198] = {
    id = 112230198,
    name = "解决第一只亡灵后，罗蕾娜没有丝毫停歇，一转身，向其余亡灵斩去。"
  },
  [112230199] = {
    id = 112230199,
    name = "黑夜中，一道道光芒闪过。"
  },
  [112230200] = {
    id = 112230200,
    name = "涌向罗蕾娜亡灵不断停滞、透明、消散。"
  },
  [112230201] = {
    id = 112230201,
    name = "罗蕾娜忘情舞动着短剑，不知过了多久，周围的亡灵已尽数消散。"
  },
  [112230202] = {
    id = 112230202,
    name = "终于全部解决了吗......"
  },
  [112230203] = {
    id = 112230203,
    name = "罗蕾娜平复了一下呼吸，擦拭掉额头上渗出的细密汗珠。"
  },
  [112230204] = {
    id = 112230204,
    name = "刚才这场战斗，亡灵数量实在太多，即便是身为曾经守夜人的她也费了不少力气。"
  },
  [112230205] = {
    id = 112230205,
    name = "接下来，只要将这里灵力的源头破坏掉，就算彻底解决了。"
  },
  [112230206] = {
    id = 112230206,
    name = "罗蕾娜正准备离去时，突然发现不远处的废屋旁，竟然还藏着一只亡灵。"
  },
  [112230207] = {
    id = 112230207,
    name = "嗯？竟然躲得那么远......"
  },
  [112230208] = {
    id = 112230208,
    name = "没有被我散发的气息吸引吗？还是克制住了想要吞噬活人的本能？"
  },
  [112230209] = {
    id = 112230209,
    name = "罗蕾娜眉头微皱，向那只亡灵走去。"
  },
  [112230210] = {
    id = 112230210,
    name = "就在这时，罗蕾娜身后突然传来急促的脚步声。"
  },
  [112230211] = {id = 112230211, name = "等等！"},
  [112230212] = {
    id = 112230212,
    name = "罗蕾娜一惊，转过身。"
  },
  [112230213] = {
    id = 112230213,
    name = "只见白天送走的那个小女孩气喘吁吁地跑了过来。"
  },
  [112230214] = {
    id = 112230214,
    name = "你怎么回来了？"
  },
  [112230215] = {
    id = 112230215,
    name = "小女孩跑到罗蕾娜身前停了下来，看着罗蕾娜的眼睛。"
  },
  [112230216] = {id = 112230216, name = "不要！"},
  [112230217] = {
    id = 112230217,
    name = "不要伤害它！"
  },
  [112230218] = {
    id = 112230218,
    name = "罗蕾娜愣了一下。"
  },
  [112230219] = {
    id = 112230219,
    name = "你......能看到它？"
  },
  [112230220] = {
    id = 112230220,
    name = "小女孩怯生生的点了点头，随即又很焦急的请求罗蕾娜停手。"
  },
  [112230221] = {
    id = 112230221,
    name = "那个亡灵是个好心的亡灵。"
  },
  [112230222] = {
    id = 112230222,
    name = "昨天晚上我被其他亡灵追逐的时候，就是它帮了我。"
  },
  [112230223] = {
    id = 112230223,
    name = "姐姐，求求你，不要消灭它。"
  },
  [112230224] = {
    id = 112230224,
    name = "昨天晚上......你竟然在这种地方过夜了？"
  },
  [112230225] = {
    id = 112230225,
    name = "见罗蕾娜询问起昨天的事，小女孩一时语塞。"
  },
  [112230226] = {
    id = 112230226,
    name = "罗蕾娜温柔的摸了摸小女孩的头。"
  },
  [112230227] = {
    id = 112230227,
    name = "我并没有在怪罪你，只是有些担心。"
  },
  [112230228] = {
    id = 112230228,
    name = "另外，我不打算消灭那个亡灵。"
  },
  [112230229] = {
    id = 112230229,
    name = "说着，罗蕾娜看向那个亡灵方向。"
  },
  [112230230] = {
    id = 112230230,
    name = "我能感受到它没有恶意。"
  },
  [112230231] = {
    id = 112230231,
    name = "真的吗？"
  },
  [112230232] = {id = 112230232, name = "嗯。"},
  [112230233] = {
    id = 112230233,
    name = "不过你说你能看到它，可以和我说得更详细一点吗？"
  },
  [112230234] = {
    id = 112230234,
    name = "看着罗蕾娜真诚的眼神，小女孩点了点头。"
  },
  [112230235] = {
    id = 112230235,
    name = "我叫莱伊，就住在离这里不远的村子中。"
  },
  [112230236] = {
    id = 112230236,
    name = "我从小就能看到它们，所以并不觉得有什么特别。"
  },
  [112230237] = {
    id = 112230237,
    name = "直到长大一点后，我才知道它们是亡灵，是普通人无法看到的存在。"
  },
  [112230238] = {
    id = 112230238,
    name = "罗蕾娜没有插话，静静听莱伊讲述，不时点点头回应她的话。"
  },
  [112230239] = {
    id = 112230239,
    name = "从莱伊所说的话中，罗蕾娜得知了她昨天在此过夜的前因后果。"
  },
  [112230240] = {
    id = 112230240,
    name = "原来莱伊此前就和那只善意的亡灵见过，虽然它很呆滞，无法对莱伊做出任何回应，但它却不会伤害莱伊。"
  },
  [112230241] = {
    id = 112230241,
    name = "甚至莱伊以前在附近密林中迷路时，它还会为莱伊引路。"
  },
  [112230242] = {
    id = 112230242,
    name = "所以莱伊就将它当作吐露心声的朋友，每当想找人倾诉时，都会来和它诉说。"
  },
  [112230243] = {
    id = 112230243,
    name = "以前这里并未聚集那么多亡灵，莱伊也从未在此遇到过危险。"
  },
  [112230244] = {
    id = 112230244,
    name = "所以昨天莱伊和以往一样，来这里找它倾诉时，却发现多了许多亡灵。"
  },
  [112230245] = {
    id = 112230245,
    name = "这些亡灵感受到莱伊的存在后，便想要袭击她。"
  },
  [112230246] = {
    id = 112230246,
    name = "危急关头，善意的亡灵出现，它怯生生的逼退了想要袭击莱伊的亡灵，又带着莱伊逃到一个废屋中，这才躲过了那些亡灵的搜捕。"
  },
  [112230247] = {
    id = 112230247,
    name = "后来莱伊实在太困了，不知不觉睡了过去，知道听到外面有动静时才醒来。"
  },
  [112230248] = {
    id = 112230248,
    name = "再之后，就是被罗蕾娜找到了。"
  },
  [112230249] = {
    id = 112230249,
    name = "而莱伊离去又回来的原因，则是因为见识过那么多恶意亡灵后，想要回来带罗蕾娜逃跑。"
  },
  [112230250] = {
    id = 112230250,
    name = "只是当她回来时，罗蕾娜已经亡灵展开战斗，她只能躲在一旁静静看着，直到刚才。"
  },
  [112230251] = {
    id = 112230251,
    name = "谢谢你为我担心。"
  },
  [112230252] = {
    id = 112230252,
    name = "不过这样说来，这些亡灵都是最近突然涌现出来的吗？"
  },
  [112230253] = {id = 112230253, name = "嗯。"},
  [112230254] = {
    id = 112230254,
    name = "我上次来这里，大概是一个多月前，当时根本没这么多亡灵。"
  },
  [112230255] = {
    id = 112230255,
    name = "而且它们对我也都没什么敌意。"
  },
  [112230256] = {
    id = 112230256,
    name = "难道是和亡灵有关的庆典将近，它们开始活跃起来了？"
  },
  [112230257] = {
    id = 112230257,
    name = "又因为这个村落遗址存在充沛灵力，所以就开始往这里聚集。"
  },
  [112230258] = {
    id = 112230258,
    name = "罗蕾娜思索片刻，给出了自己的推测。"
  },
  [112230259] = {
    id = 112230259,
    name = "听着罗蕾娜的推测，莱伊像是突然想到了什么，一下跪在罗蕾娜面前。"
  },
  [112230260] = {
    id = 112230260,
    name = "姐姐，求求你，救救我的村子吧！"
  },
  [112230261] = {
    id = 112230261,
    name = "罗蕾娜被她的举动吓了一跳，急忙将她搀扶起来。"
  },
  [112230262] = {
    id = 112230262,
    name = "你的村子发生什么事了吗？"
  },
  [112230263] = {
    id = 112230263,
    name = "亡灵，也是有很多亡灵聚集了过来。"
  },
  [112230264] = {
    id = 112230264,
    name = "村里的大家已经有人出现了噩梦和身体不适，再拖延下去，恐怕......"
  },
  [112230265] = {
    id = 112230265,
    name = "你们村子近期曾有许多人逝世吗？"
  },
  [112230266] = {id = 112230266, name = "没有。"},
  [112230267] = {
    id = 112230267,
    name = "按理说大部分亡灵都是被生前的执念所吸引，只会在去世之地徘徊，怎么会聚集到你村子附近......"
  },
  [112230268] = {
    id = 112230268,
    name = "你见过它们了？"
  },
  [112230269] = {
    id = 112230269,
    name = "嗯，但我不敢靠太近，我能感觉到它们的恶意。"
  },
  [112230270] = {
    id = 112230270,
    name = "罗蕾娜摸了摸莱伊的头，安抚她紧张的情绪。"
  },
  [112230271] = {
    id = 112230271,
    name = "知道了。"
  },
  [112230272] = {
    id = 112230272,
    name = "那我和你一起回去看看吧。"
  },
  [112230273] = {
    id = 112230273,
    name = "不过在那之前，我们必须将这里的收尾工作完成。"
  },
  [112230274] = {
    id = 112230274,
    name = "罗蕾娜看向了不远处的那只亡灵。"
  },
  [112230275] = {
    id = 112230275,
    name = "莱伊见状又紧张了起来。"
  },
  [112230276] = {
    id = 112230276,
    name = "姐姐，你不是说不会消灭它吗？"
  },
  [112230277] = {
    id = 112230277,
    name = "嗯，我不会消灭它。"
  },
  [112230278] = {
    id = 112230278,
    name = "但毕竟人鬼有别，我会是送它去它该去的地方。"
  },
  [112230279] = {
    id = 112230279,
    name = "你就在这等我吧。"
  },
  [112230280] = {
    id = 112230280,
    name = "罗蕾娜安抚好莱伊，缓缓走向那只亡灵。"
  },
  [112230281] = {
    id = 112230281,
    name = "在罗蕾娜低声吟诵的咒语中，那只亡灵的形象逐渐从扭曲化作人形，看起来像是一位中年男子。"
  },
  [112230282] = {
    id = 112230282,
    name = "它对着罗蕾娜鞠了一躬，又冲着莱伊挥了挥手，随后化作无数光点向天空飞去。"
  },
  [112230283] = {
    id = 112230283,
    name = "在送别最后一只亡灵后，罗蕾娜又将这里隐藏的灵力源头彻底破坏，断绝了亡灵再次汇集的可能。"
  },
  [112230284] = {
    id = 112230284,
    name = "做完一切后，她才跟着莱伊走向不远处的村子。"
  },
  [112240001] = {
    id = 112240001,
    name = "深山中，刚结束探索的薇独自走在荒无人迹的小路上。"
  },
  [112240002] = {
    id = 112240002,
    name = "只要穿过这个山谷，再走一段应该就能到下个据点了。"
  },
  [112240003] = {
    id = 112240003,
    name = "不过......这路比想象中还要偏僻啊。"
  },
  [112240004] = {
    id = 112240004,
    name = "薇抬头看向四周。"
  },
  [112240005] = {
    id = 112240005,
    name = "茂密的树林遮挡了视线，连天空都只能透过树叶间的缝隙看到一点。"
  },
  [112240006] = {
    id = 112240006,
    name = "如果按大哥的脾气，肯定会直接用魔法强行开辟一条大路吧？"
  },
  [112240007] = {
    id = 112240007,
    name = "想到这里，薇无奈地笑了笑。"
  },
  [112240008] = {
    id = 112240008,
    name = "然后事后再辩解“这样最有效率”。"
  },
  [112240009] = {
    id = 112240009,
    name = "明明有时候稍微谨慎一点，会更加安全。"
  },
  [112240010] = {
    id = 112240010,
    name = "薇轻轻摇头。"
  },
  [112240011] = {
    id = 112240011,
    name = "虽然嘴上吐槽着家人的做事方式，但提起他们时，她的语气中却总带着淡淡的温柔。"
  },
  [112240012] = {
    id = 112240012,
    name = "不过......也不知道他们现在怎么样了。"
  },
  [112240013] = {
    id = 112240013,
    name = "等下次休假，也回家去看看吧。"
  },
  [112240014] = {
    id = 112240014,
    name = "薇一边自言自语，一边沿着小路前行。"
  },
  [112240015] = {
    id = 112240015,
    name = "忽然，周围的空气突然产生了一丝异常的波动。"
  },
  [112240016] = {
    id = 112240016,
    name = "薇脚步一顿。"
  },
  [112240017] = {id = 112240017, name = "嗯？"},
  [112240018] = {
    id = 112240018,
    name = "薇停下了脚步，握紧手中的法杖。"
  },
  [112240019] = {
    id = 112240019,
    name = "奇怪......"
  },
  [112240020] = {
    id = 112240020,
    name = "薇闭上双眼，仔细感受着周围的魔力变化。"
  },
  [112240021] = {
    id = 112240021,
    name = "片刻后，她睁开眼。"
  },
  [112240022] = {
    id = 112240022,
    name = "这里的魔力流动，有些不自然。"
  },
  [112240023] = {
    id = 112240023,
    name = "难道有人曾在这设置过结界？"
  },
  [112240024] = {
    id = 112240024,
    name = "薇运转探查魔法，环顾四周。"
  },
  [112240025] = {
    id = 112240025,
    name = "原本普通的山谷，此刻在她眼中逐渐变得不同。"
  },
  [112240026] = {
    id = 112240026,
    name = "空气中残留着淡淡的黑色气息——那是属于亡灵的力量。"
  },
  [112240027] = {id = 112240027, name = "亡灵？"},
  [112240028] = {
    id = 112240028,
    name = "薇微微皱眉。"
  },
  [112240029] = {
    id = 112240029,
    name = "而且数量还不少。"
  },
  [112240030] = {
    id = 112240030,
    name = "如果只是普通的游荡亡灵，应该不会影响到附近的人。"
  },
  [112240031] = {
    id = 112240031,
    name = "不过既然遇到了，还是调查一下比较好。"
  },
  [112240032] = {
    id = 112240032,
    name = "薇沉思片刻，决定继续深入山谷。"
  },
  [112240033] = {
    id = 112240033,
    name = "然而随着她不断前进，周围的景象开始发生变化。"
  },
  [112240034] = {
    id = 112240034,
    name = "原本能够看见的道路逐渐消失，四周的树木变得模糊。"
  },
  [112240035] = {
    id = 112240035,
    name = "就连刚才走过的道路，也仿佛被某种力量改变。"
  },
  [112240036] = {
    id = 112240036,
    name = "薇停下脚步，转身看向身后。"
  },
  [112240037] = {
    id = 112240037,
    name = "来时的道路已经完全消失。"
  },
  [112240038] = {id = 112240038, name = "结界？"},
  [112240039] = {
    id = 112240039,
    name = "她抬起法杖，轻轻挥动。"
  },
  [112240040] = {
    id = 112240040,
    name = "一道魔法光芒扩散开来。"
  },
  [112240041] = {
    id = 112240041,
    name = "然而光芒触碰到周围空间时，却像撞上了一面无形的墙壁，迅速消散。"
  },
  [112240042] = {
    id = 112240042,
    name = "竟然真是结界，能隐藏到这种程度......不会只想困住来往探险者吧？"
  },
  [112240043] = {
    id = 112240043,
    name = "觉察不妙，薇立即凝神警戒。"
  },
  [112240044] = {
    id = 112240044,
    name = "就在此时，一道黑影突然从身后袭来。"
  },
  [112240045] = {
    id = 112240045,
    name = "薇迅速转身。"
  },
  [112240046] = {
    id = 112240046,
    name = "法杖挥动，一道魔法屏障瞬间展开。"
  },
  [112240047] = {id = 112240047, name = "轰——"},
  [112240048] = {
    id = 112240048,
    name = "黑影撞击在屏障上，发出沉闷的声响。"
  },
  [112240049] = {
    id = 112240049,
    name = "薇借着反作用力后退数步。"
  },
  [112240050] = {
    id = 112240050,
    name = "这时，她才看清袭击自己的存在。"
  },
  [112240051] = {
    id = 112240051,
    name = "那是一只面目狰狞的亡灵。"
  },
  [112240052] = {
    id = 112240052,
    name = "亡灵见偷袭失败，发出低吼，再次向薇扑来。"
  },
  [112240053] = {
    id = 112240053,
    name = "薇轻轻叹了一口气。"
  },
  [112240054] = {
    id = 112240054,
    name = "明明只是想调查一下情况。"
  },
  [112240055] = {
    id = 112240055,
    name = "看来想离开这里之前，还得先解决一些麻烦了。"
  },
  [112240056] = {
    id = 112240056,
    name = "说话间，薇体内的魔力瞬间凝聚于法杖，数个魔法直扑亡灵而去。"
  },
  [112240057] = {
    id = 112240057,
    name = "山谷中，魔法光芒不断闪烁。"
  },
  [112240058] = {
    id = 112240058,
    name = "数只亡灵从四面八方涌来，将薇包围其中。"
  },
  [112240059] = {
    id = 112240059,
    name = "它们发出低沉的嘶吼，不断向薇发动攻击。"
  },
  [112240060] = {
    id = 112240060,
    name = "薇站在原地，神情依旧平静。"
  },
  [112240061] = {
    id = 112240061,
    name = "看来这个结界里的亡灵，比外面感受到的还要多。"
  },
  [112240062] = {
    id = 112240062,
    name = "而且......它们似乎都被某种力量影响了。"
  },
  [112240063] = {
    id = 112240063,
    name = "薇观察着袭来的亡灵。"
  },
  [112240064] = {
    id = 112240064,
    name = "虽然这些亡灵表现出了明显的攻击性，但薇却没有立刻发动强力魔法。"
  },
  [112240065] = {
    id = 112240065,
    name = "她只是做出适当还击，限制它们，同时不断移动身形，躲避着它们的攻击。"
  },
  [112240066] = {
    id = 112240066,
    name = "你们应该也不是自愿变成这样的吧。"
  },
  [112240067] = {
    id = 112240067,
    name = "只是被困在这里太久了吗......"
  },
  [112240068] = {
    id = 112240068,
    name = "然而亡灵并不能回应她。"
  },
  [112240069] = {
    id = 112240069,
    name = "受到结界力量影响的它们，只剩下本能般的攻击欲望。"
  },
  [112240070] = {
    id = 112240070,
    name = "薇轻轻叹了一口气。"
  },
  [112240071] = {
    id = 112240071,
    name = "看来现在和你们交流也没有意义。"
  },
  [112240072] = {
    id = 112240072,
    name = "下一刻，薇手中的法杖亮起柔和的光芒。"
  },
  [112240073] = {
    id = 112240073,
    name = "一道魔法阵在她脚下展开。"
  },
  [112240074] = {
    id = 112240074,
    name = "随着薇挥动法杖，数道光束向周围扩散。"
  },
  [112240075] = {
    id = 112240075,
    name = "冲在最前方的亡灵被光芒击中，身影瞬间停滞。"
  },
  [112240076] = {
    id = 112240076,
    name = "它们并没有消散。"
  },
  [112240077] = {
    id = 112240077,
    name = "只是被魔法暂时压制，无法继续行动。"
  },
  [112240078] = {id = 112240078, name = "抱歉。"},
  [112240079] = {
    id = 112240079,
    name = "现在只能先让你们安静一下了。"
  },
  [112240080] = {
    id = 112240080,
    name = "薇继续向前。"
  },
  [112240081] = {
    id = 112240081,
    name = "面对不断袭来的亡灵，她精准控制着魔法的力度。"
  },
  [112240082] = {
    id = 112240082,
    name = "每一次攻击，都只是将它们压制。"
  },
  [112240083] = {
    id = 112240083,
    name = "不久后，第一批袭来的亡灵全部被压制。"
  },
  [112240084] = {
    id = 112240084,
    name = "薇站在原地，稍微喘了一口气。"
  },
  [112240085] = {id = 112240085, name = "呼......"},
  [112240086] = {
    id = 112240086,
    name = "数量还真不少。"
  },
  [112240087] = {
    id = 112240087,
    name = "她抬头看向四周。"
  },
  [112240088] = {
    id = 112240088,
    name = "原本应该安静的山谷，此刻依旧弥漫着浓郁的亡灵气息。"
  },
  [112240089] = {
    id = 112240089,
    name = "看来只解决这些游荡的亡灵是不够的。"
  },
  [112240090] = {
    id = 112240090,
    name = "真正的问题，应该还是这个结界。"
  },
  [112240091] = {
    id = 112240091,
    name = "她走到附近的一处岩壁旁。"
  },
  [112240092] = {
    id = 112240092,
    name = "伸手触碰残留在上面的魔力。"
  },
  [112240093] = {
    id = 112240093,
    name = "片刻后，薇的眉头微微皱起。"
  },
  [112240094] = {id = 112240094, name = "果然。"},
  [112240095] = {
    id = 112240095,
    name = "这个结界是由灵力构成，和寻常的魔法结界不同。"
  },
  [112240096] = {
    id = 112240096,
    name = "只要核心没有被破坏，就无法走出去。"
  },
  [112240097] = {
    id = 112240097,
    name = "薇收回手。"
  },
  [112240098] = {
    id = 112240098,
    name = "难怪之前没有发现异常。"
  },
  [112240099] = {
    id = 112240099,
    name = "如果不是进入这里，根本无法察觉这个结界的存在。"
  },
  [112240100] = {
    id = 112240100,
    name = "她重新观察起周围。"
  },
  [112240101] = {
    id = 112240101,
    name = "试图寻找结界的核心位置。"
  },
  [112240102] = {
    id = 112240102,
    name = "然而就在这时，一阵阴冷的气息再次从远处传来。"
  },
  [112240103] = {
    id = 112240103,
    name = "薇立即转身，又有数只亡灵从黑暗中出现。"
  },
  [112240104] = {id = 112240104, name = "......"},
  [112240105] = {
    id = 112240105,
    name = "完全不给我休息的时间吗？"
  },
  [112240106] = {
    id = 112240106,
    name = "亡灵没有给她思考的时间。"
  },
  [112240107] = {
    id = 112240107,
    name = "下一瞬间，它们同时向薇袭来。"
  },
  [112240108] = {
    id = 112240108,
    name = "薇迅速抬起法杖，魔力在空中凝聚。"
  },
  [112240109] = {id = 112240109, name = "轰——"},
  [112240110] = {
    id = 112240110,
    name = "强大的魔法瞬间将最前方的亡灵击退。"
  },
  [112240111] = {
    id = 112240111,
    name = "然而就在薇准备继续寻找结界核心时。"
  },
  [112240112] = {
    id = 112240112,
    name = "另一侧，又出现了新的亡灵气息。"
  },
  [112240113] = {
    id = 112240113,
    name = "薇停下动作。"
  },
  [112240114] = {
    id = 112240114,
    name = "一波接一波......"
  },
  [112240115] = {
    id = 112240115,
    name = "这样下去，根本没有时间调查结界。"
  },
  [112240116] = {
    id = 112240116,
    name = "她看向周围不断出现的亡灵。"
  },
  [112240117] = {
    id = 112240117,
    name = "虽然这些亡灵并不能真正威胁到她。"
  },
  [112240118] = {
    id = 112240118,
    name = "但如果一直这样消耗下去。"
  },
  [112240119] = {
    id = 112240119,
    name = "她迟早会因为无法集中精神破解结界而陷入困境。"
  },
  [112240120] = {
    id = 112240120,
    name = "薇握紧法杖。"
  },
  [112240121] = {
    id = 112240121,
    name = "看来必须先想办法摆脱这种情况。"
  },
  [112240122] = {
    id = 112240122,
    name = "薇再次释放魔法，将靠近的亡灵全部逼退。"
  },
  [112240123] = {
    id = 112240123,
    name = "但望着这片无法离开的山谷。"
  },
  [112240124] = {
    id = 112240124,
    name = "薇难得有种棘手的感觉。"
  },
  [112240125] = {
    id = 112240125,
    name = "（如果继续这样下去......）"
  },
  [112240126] = {
    id = 112240126,
    name = "（恐怕在找到结界核心之前，我就会先被它们拖垮。）"
  },
  [112240127] = {
    id = 112240127,
    name = "无数亡灵的气息依旧不断靠近。"
  },
  [112240128] = {
    id = 112240128,
    name = "而薇的身影，也逐渐被黑暗笼罩。"
  },
  [112240129] = {
    id = 112240129,
    name = "山谷之中。"
  },
  [112240130] = {
    id = 112240130,
    name = "战斗持续了很久。"
  },
  [112240131] = {
    id = 112240131,
    name = "薇站在一片狼藉的地面上。"
  },
  [112240132] = {
    id = 112240132,
    name = "周围弥漫着被击退的亡灵残留的黑色气息。"
  },
  [112240133] = {
    id = 112240133,
    name = "她轻轻呼出一口气。"
  },
  [112240134] = {
    id = 112240134,
    name = "比想象中还要麻烦。"
  },
  [112240135] = {
    id = 112240135,
    name = "薇体内的魔力依旧还算充足。"
  },
  [112240136] = {
    id = 112240136,
    name = "但长时间维持高强度战斗，也让她感到了一丝疲惫。"
  },
  [112240137] = {
    id = 112240137,
    name = "如果只是战斗的话，倒没有什么问题。"
  },
  [112240138] = {
    id = 112240138,
    name = "可是这样下去......"
  },
  [112240139] = {
    id = 112240139,
    name = "她看向不远处。"
  },
  [112240140] = {
    id = 112240140,
    name = "部分被她拘禁的亡灵，正在不断吸收结界内的灵力，试图挣脱束缚。"
  },
  [112240141] = {
    id = 112240141,
    name = "唉，虽然已经知道它们是亡灵，但还是不想对它们动手。"
  },
  [112240142] = {
    id = 112240142,
    name = "从进入结界不久，她已经多次尝试寻找结界核心。"
  },
  [112240143] = {
    id = 112240143,
    name = "可是每当她准备进一步调查时，就会有新的亡灵出现打断她。"
  },
  [112240144] = {
    id = 112240144,
    name = "薇看向天空。"
  },
  [112240145] = {
    id = 112240145,
    name = "然而结界笼罩下的山谷，连时间流动都变得难以判断。"
  },
  [112240146] = {
    id = 112240146,
    name = "不知道已经过去多久了。"
  },
  [112240147] = {
    id = 112240147,
    name = "得尽快想办法离开这里才行。"
  },
  [112240148] = {
    id = 112240148,
    name = "就在这时，周围的温度骤然下降。"
  },
  [112240149] = {
    id = 112240149,
    name = "薇立即警觉起来。"
  },
  [112240150] = {
    id = 112240150,
    name = "一股比之前更加浓郁的亡灵气息，从山谷深处传来。"
  },
  [112240151] = {
    id = 112240151,
    name = "又来了？"
  },
  [112240152] = {
    id = 112240152,
    name = "黑雾翻涌，数只亡灵从其中浮现。"
  },
  [112240153] = {
    id = 112240153,
    name = "与之前不同，这一次，它们出现的位置更加分散。"
  },
  [112240154] = {
    id = 112240154,
    name = "显然是想限制薇的行动。"
  },
  [112240155] = {
    id = 112240155,
    name = "薇轻轻叹了一口气。"
  },
  [112240156] = {
    id = 112240156,
    name = "真是没完没了。"
  },
  [112240157] = {
    id = 112240157,
    name = "下一刻，亡灵同时发动攻击。"
  },
  [112240158] = {
    id = 112240158,
    name = "薇快速后退。"
  },
  [112240159] = {
    id = 112240159,
    name = "手中的法杖划过空气。"
  },
  [112240160] = {
    id = 112240160,
    name = "一道魔法屏障挡住了亡灵的攻击。"
  },
  [112240161] = {
    id = 112240161,
    name = "然而就在她准备反击时。"
  },
  [112240162] = {
    id = 112240162,
    name = "另一只亡灵从侧面袭来。"
  },
  [112240163] = {
    id = 112240163,
    name = "薇迅速转身，魔法光芒瞬间爆发，将那只亡灵击退。"
  },
  [112240164] = {
    id = 112240164,
    name = "但薇也因此错过了最佳压制它们的时机。"
  },
  [112240165] = {
    id = 112240165,
    name = "（越来越聪明了吗......）"
  },
  [112240166] = {
    id = 112240166,
    name = "（还是说，有什么在控制它们？）"
  },
  [112240167] = {
    id = 112240167,
    name = "战斗又持续了一阵，薇的动作终于慢了一瞬。"
  },
  [112240168] = {
    id = 112240168,
    name = "一道黑色灵力擦过她的肩膀。"
  },
  [112240169] = {
    id = 112240169,
    name = "薇迅速拉开距离，看着衣服上的破损，无奈地笑了一下。"
  },
  [112240170] = {
    id = 112240170,
    name = "看来不能再继续这样下去了。"
  },
  [112240171] = {
    id = 112240171,
    name = "薇抬起法杖，准备灭杀所有亡灵，强行破开结界。"
  },
  [112240172] = {
    id = 112240172,
    name = "然而就在这时，薇的余光中，注意到了一个身影。"
  },
  [112240173] = {
    id = 112240173,
    name = "那是一只漂浮在远处的亡灵。"
  },
  [112240174] = {
    id = 112240174,
    name = "与周围那些充满攻击性的亡灵不同。"
  },
  [112240175] = {
    id = 112240175,
    name = "它只是安静地停在那里。"
  },
  [112240176] = {
    id = 112240176,
    name = "没有靠近，也没有发动攻击。"
  },
  [112240177] = {id = 112240177, name = "嗯？"},
  [112240178] = {
    id = 112240178,
    name = "亡灵似乎发现了薇注意到自己。"
  },
  [112240179] = {
    id = 112240179,
    name = "它缓缓转过身，随后向山谷的另一个方向飘去。"
  },
  [112240180] = {
    id = 112240180,
    name = "走了一段距离后，它又停了下来，回头看向薇。"
  },
  [112240181] = {
    id = 112240181,
    name = "薇看着这一幕，眼中露出疑惑。"
  },
  [112240182] = {
    id = 112240182,
    name = "你是在......"
  },
  [112240183] = {
    id = 112240183,
    name = "让我跟过去吗？"
  },
  [112240184] = {
    id = 112240184,
    name = "亡灵没有回应，见薇注意到自己后，又继续朝着远处移动。"
  },
  [112240185] = {
    id = 112240185,
    name = "薇站在原地，看着那个与其他亡灵完全不同的存在。"
  },
  [112240186] = {
    id = 112240186,
    name = "陷阱吗......"
  },
  [112240187] = {
    id = 112240187,
    name = "薇看向周围不断逼近的亡灵。"
  },
  [112240188] = {
    id = 112240188,
    name = "又看向远处走走停停，等待自己的亡灵。"
  },
  [112240189] = {
    id = 112240189,
    name = "薇轻轻叹了一口气。"
  },
  [112240190] = {
    id = 112240190,
    name = "继续留在这里，也不是办法。"
  },
  [112240191] = {
    id = 112240191,
    name = "跟过去看看吧。"
  },
  [112240192] = {
    id = 112240192,
    name = "薇施放出数个魔法，将试图围困自己的亡灵暂时击退，然后立即向着那个引路的亡灵奔去。"
  },
  [112240193] = {
    id = 112240193,
    name = "薇跟随着那只亡灵不断前进。"
  },
  [112240194] = {
    id = 112240194,
    name = "一路上，周围依旧有不少亡灵徘徊。"
  },
  [112240195] = {
    id = 112240195,
    name = "察觉到薇的存在后，它们纷纷靠近。"
  },
  [112240196] = {
    id = 112240196,
    name = "然而每当亡灵准备袭击时，引路的亡灵都会停下来，散发出微弱的灵力，将那些靠近的亡灵吸引到另一侧，为薇争取前进的时间。"
  },
  [112240197] = {
    id = 112240197,
    name = "薇看着这一幕，眼中露出惊讶。"
  },
  [112240198] = {
    id = 112240198,
    name = "原来......"
  },
  [112240199] = {
    id = 112240199,
    name = "你一直是在帮我吗？"
  },
  [112240200] = {
    id = 112240200,
    name = "亡灵没有回应，只是继续向前飘去。"
  },
  [112240201] = {
    id = 112240201,
    name = "薇望着它的背影，轻轻笑了一下。"
  },
  [112240202] = {
    id = 112240202,
    name = "明明自己也是亡灵。"
  },
  [112240203] = {
    id = 112240203,
    name = "却在帮助一个活人。"
  },
  [112240204] = {
    id = 112240204,
    name = "她跟在亡灵身后。"
  },
  [112240205] = {
    id = 112240205,
    name = "逐渐来到一处山谷边缘。"
  },
  [112240206] = {
    id = 112240206,
    name = "这里的空气明显与之前不同。"
  },
  [112240207] = {
    id = 112240207,
    name = "原本笼罩整个山谷的压迫感，在这里变得十分微弱。"
  },
  [112240208] = {
    id = 112240208,
    name = "亡灵停了下来。"
  },
  [112240209] = {
    id = 112240209,
    name = "它漂浮在半空。"
  },
  [112240210] = {
    id = 112240210,
    name = "随后伸出手，指向前方。"
  },
  [112240211] = {
    id = 112240211,
    name = "薇顺着它指引的方向走了几步。"
  },
  [112240212] = {
    id = 112240212,
    name = "下一刻，她发现前方的空间出现了一丝异常波动。"
  },
  [112240213] = {
    id = 112240213,
    name = "那正是结界的薄弱处。"
  },
  [112240214] = {
    id = 112240214,
    name = "原来如此。"
  },
  [112240215] = {
    id = 112240215,
    name = "这个结界并不是完全封闭的。"
  },
  [112240216] = {
    id = 112240216,
    name = "只是利用山谷中的力量制造了一个迷宫。"
  },
  [112240217] = {
    id = 112240217,
    name = "她立即明白了亡灵的意思。"
  },
  [112240218] = {
    id = 112240218,
    name = "薇走到结界边缘，凝聚魔力。"
  },
  [112240219] = {
    id = 112240219,
    name = "随着一道柔和的光芒闪过，原本无法突破的空间逐渐出现裂痕。"
  },
  [112240220] = {
    id = 112240220,
    name = "最终，结界破开了一道出口。"
  },
  [112240221] = {
    id = 112240221,
    name = "外面的光芒照入山谷。"
  },
  [112240222] = {
    id = 112240222,
    name = "薇看着眼前的出口，不禁松了一口气。"
  },
  [112240223] = {
    id = 112240223,
    name = "成功了。"
  },
  [112240224] = {
    id = 112240224,
    name = "她转过身，看向那只帮助自己的亡灵。"
  },
  [112240225] = {
    id = 112240225,
    name = "谢谢你。"
  },
  [112240226] = {
    id = 112240226,
    name = "亡灵安静地漂浮在那里。"
  },
  [112240227] = {
    id = 112240227,
    name = "薇看着它，似乎想到了什么。"
  },
  [112240228] = {
    id = 112240228,
    name = "还有......"
  },
  [112240229] = {
    id = 112240229,
    name = "之前的事情，对不起。"
  },
  [112240230] = {
    id = 112240230,
    name = "亡灵微微晃动了一下。"
  },
  [112240231] = {
    id = 112240231,
    name = "薇露出有些不好意思的表情。"
  },
  [112240232] = {
    id = 112240232,
    name = "我记得你应该挺早就出现了吧？"
  },
  [112240233] = {
    id = 112240233,
    name = "那时我以为你和其他亡灵一样，会攻击我。"
  },
  [112240234] = {
    id = 112240234,
    name = "所以用了魔法把你赶走了好几次。"
  },
  [112240235] = {
    id = 112240235,
    name = "现在想想，可能给你造成困扰了吧。"
  },
  [112240236] = {
    id = 112240236,
    name = "她认真地向亡灵道歉。"
  },
  [112240237] = {
    id = 112240237,
    name = "亡灵伸手在空中比划了一下，又缓缓靠近薇，绕着她轻轻转了一圈，像是在回应她的话。"
  },
  [112240238] = {
    id = 112240238,
    name = "薇看着这一幕，脸上露出温柔的笑容。"
  },
  [112240239] = {
    id = 112240239,
    name = "这是原谅我了的意思吗？"
  },
  [112240240] = {
    id = 112240240,
    name = "亡灵又胡乱比划了一下。"
  },
  [112240241] = {
    id = 112240241,
    name = "随后，它转身朝山谷方向飘去。"
  },
  [112240242] = {
    id = 112240242,
    name = "你要留下来吗？"
  },
  [112240243] = {
    id = 112240243,
    name = "亡灵停顿了一下，随后继续向前。"
  },
  [112240244] = {
    id = 112240244,
    name = "亡灵的身影越来越远，最终消失在山谷的雾气之中。"
  },
  [112240245] = {
    id = 112240245,
    name = "薇站在出口处，看着它离开的方向，心中有些复杂。"
  },
  [112240246] = {
    id = 112240246,
    name = "（明明是亡灵......）"
  },
  [112240247] = {
    id = 112240247,
    name = "（却比很多活着的人，还要温柔。）"
  },
  [112240248] = {
    id = 112240248,
    name = "到达据点时，天色已经逐渐暗了下来。"
  },
  [112240249] = {
    id = 112240249,
    name = "街道两旁挂满了庆典用的装饰。"
  },
  [112240250] = {
    id = 112240250,
    name = "往日安静的据点，也因为庆典临近而变得热闹起来。"
  },
  [112240251] = {
    id = 112240251,
    name = "薇走进常住的旅店。"
  },
  [112240252] = {
    id = 112240252,
    name = "旅店老板看到她回来，连忙迎了上来。"
  },
  [112240253] = {
    id = 112240253,
    name = "薇小姐，你终于回来了。"
  },
  [112240254] = {
    id = 112240254,
    name = "之前听说你这次会从那个山谷方向回来，可把我吓了一跳。"
  },
  [112240255] = {
    id = 112240255,
    name = "薇微微一愣。"
  },
  [112240256] = {
    id = 112240256,
    name = "老板，你知道那个山谷的事情？"
  },
  [112240257] = {
    id = 112240257,
    name = "老板叹了一口气。"
  },
  [112240258] = {
    id = 112240258,
    name = "怎么可能不知道。"
  },
  [112240259] = {
    id = 112240259,
    name = "那可是我们据点附近最重要的一条道路。"
  },
  [112240260] = {
    id = 112240260,
    name = "以前虽然偶尔会有一些奇怪的传闻，但最近这段时间......"
  },
  [112240261] = {
    id = 112240261,
    name = "老板摇了摇头。"
  },
  [112240262] = {
    id = 112240262,
    name = "那里已经完全被那些东西占据了。"
  },
  [112240263] = {
    id = 112240263,
    name = "那些东西？"
  },
  [112240264] = {id = 112240264, name = "亡灵。"},
  [112240265] = {id = 112240265, name = "......"},
  [112240266] = {
    id = 112240266,
    name = "确实有很多亡灵聚集在那里。"
  },
  [112240267] = {
    id = 112240267,
    name = "老板露出担忧的表情。"
  },
  [112240268] = {
    id = 112240268,
    name = "那些亡灵不仅阻断了探险者来这个据点参加庆典的道路。"
  },
  [112240269] = {
    id = 112240269,
    name = "也让不少据点里的人受到影响。"
  },
  [112240270] = {id = 112240270, name = "比如？"},
  [112240271] = {
    id = 112240271,
    name = "有人晚上不停做噩梦。"
  },
  [112240272] = {
    id = 112240272,
    name = "还有一些老人和孩子，莫名其妙地感到身体不舒服。"
  },
  [112240273] = {
    id = 112240273,
    name = "虽然没有什么严重的伤势，但大家心里都不安。"
  },
  [112240274] = {
    id = 112240274,
    name = "老板看向窗外。"
  },
  [112240275] = {
    id = 112240275,
    name = "街道上，人们正在为即将到来的庆典准备。"
  },
  [112240276] = {
    id = 112240276,
    name = "可不少人的脸上，却没有平日庆典前的期待。"
  },
  [112240277] = {
    id = 112240277,
    name = "本来一年一度的亡灵庆典，是大家最期待的时候。"
  },
  [112240278] = {
    id = 112240278,
    name = "大家会点亮灯火，为那些无法归去的灵魂送上祝福。"
  },
  [112240279] = {
    id = 112240279,
    name = "可是今年......"
  },
  [112240280] = {
    id = 112240280,
    name = "不知道是不是因为庆典快到了，附近的亡灵活动越来越频繁。"
  },
  [112240281] = {
    id = 112240281,
    name = "薇若有所思。"
  },
  [112240282] = {
    id = 112240282,
    name = "原来如此。"
  },
  [112240283] = {
    id = 112240283,
    name = "庆典的力量，让它们更加活跃了吗？"
  },
  [112240284] = {
    id = 112240284,
    name = "老板点了点头。"
  },
  [112240285] = {
    id = 112240285,
    name = "以前也出现过类似情况，但从来没有像今年这样严重。"
  },
  [112240286] = {id = 112240286, name = "......"},
  [112240287] = {
    id = 112240287,
    name = "回房后，薇心情有些复杂。"
  },
  [112240288] = {
    id = 112240288,
    name = "她没想到这次亡灵聚集带来的影响这么大。"
  },
  [112240289] = {
    id = 112240289,
    name = "作为探险者，也作为经常到访这个据点的探险者，她觉得自己有责任为这个据点解决这次麻烦。"
  },
  [112240290] = {
    id = 112240290,
    name = "想到此处，薇翻起堆放在一旁书本，决定看看有没有什么解决亡灵的办法。"
  },
  [112240291] = {
    id = 112240291,
    name = "第二天清晨。"
  },
  [112240292] = {
    id = 112240292,
    name = "旅店中，老板正在整理柜台上的物品。"
  },
  [112240293] = {
    id = 112240293,
    name = "看到薇下来后，老板脸上露出了久违的笑容。"
  },
  [112240294] = {
    id = 112240294,
    name = "薇小姐，早上好。"
  },
  [112240295] = {
    id = 112240295,
    name = "早上好，老板。"
  },
  [112240296] = {
    id = 112240296,
    name = "看你的样子，似乎有什么好事发生？"
  },
  [112240297] = {
    id = 112240297,
    name = "老板点了点头。"
  },
  [112240298] = {
    id = 112240298,
    name = "嘿嘿，确实有好事。"
  },
  [112240299] = {
    id = 112240299,
    name = "昨天晚上，我们终于联系到了一位实力强大的探险者。"
  },
  [112240300] = {
    id = 112240300,
    name = "薇微微一怔。"
  },
  [112240301] = {
    id = 112240301,
    name = "探险者？"
  },
  [112240302] = {id = 112240302, name = "嗯。"},
  [112240303] = {
    id = 112240303,
    name = "她已经接受了我们的委托，准备帮我们消灭山谷里的亡灵。"
  },
  [112240304] = {
    id = 112240304,
    name = "老板松了一口气。"
  },
  [112240305] = {
    id = 112240305,
    name = "薇听到这里，也露出了安心的笑容。"
  },
  [112240306] = {
    id = 112240306,
    name = "那确实是一件好事。"
  },
  [112240307] = {
    id = 112240307,
    name = "大家也终于可以安心准备庆典了。"
  },
  [112240308] = {id = 112240308, name = "是啊。"},
  [112240309] = {
    id = 112240309,
    name = "说起来，今年的庆典本来应该比往年更加热闹。"
  },
  [112240310] = {
    id = 112240310,
    name = "希望那些亡灵的问题解决后，大家还能好好享受这一天。"
  },
  [112240311] = {
    id = 112240311,
    name = "薇点了点头，觉得自己也不用再插手了，昨天夜里的准备就当拓展知识面了。"
  },
  [112240312] = {
    id = 112240312,
    name = "然而正当她转身准备上楼时，表情突然凝重了起来。"
  },
  [112240313] = {
    id = 112240313,
    name = "老板察觉到了她的变化。"
  },
  [112240314] = {
    id = 112240314,
    name = "薇小姐？"
  },
  [112240315] = {
    id = 112240315,
    name = "没什么。"
  },
  [112240316] = {
    id = 112240316,
    name = "薇看向窗外，看向山谷所在的方向。"
  },
  [112240317] = {
    id = 112240317,
    name = "那个帮助过自己的亡灵身影，浮现在她脑海中。"
  },
  [112240318] = {
    id = 112240318,
    name = "（如果那位探险者要消灭所有亡灵......）"
  },
  [112240319] = {
    id = 112240319,
    name = "（那个善良的亡灵，也会被消灭吗？）"
  },
  [112240320] = {
    id = 112240320,
    name = "薇回到房间后，再次翻开了那本关于亡灵的古老记录。"
  },
  [112240321] = {
    id = 112240321,
    name = "她看着其中关于“引渡”的部分。"
  },
  [112240322] = {
    id = 112240322,
    name = "将无法离开的亡灵，引导回属于它们的地方。"
  },
  [112240323] = {
    id = 112240323,
    name = "如果真的可以做到......"
  },
  [112240324] = {
    id = 112240324,
    name = "或许就能避免更多不必要的伤害。"
  },
  [112240325] = {
    id = 112240325,
    name = "薇想起那个曾经帮助自己的亡灵，也想起那些被困在山谷中的亡灵。"
  },
  [112240326] = {
    id = 112240326,
    name = "其中或许有恶意的存在。"
  },
  [112240327] = {
    id = 112240327,
    name = "但也一定有......"
  },
  [112240328] = {
    id = 112240328,
    name = "只是忘记如何离开的亡灵。"
  },
  [112240329] = {
    id = 112240329,
    name = "薇闭上眼睛，沉默许久。"
  },
  [112240330] = {
    id = 112240330,
    name = "最终，她做出了决定。"
  },
  [112240331] = {
    id = 112240331,
    name = "在那位探险者抵达之前......"
  },
  [112240332] = {
    id = 112240332,
    name = "我要先去试试。"
  },
  [112240333] = {
    id = 112240333,
    name = "片刻后，薇离开了据点。"
  },
  [112240334] = {
    id = 112240334,
    name = "她换上了另一套为了引渡亡灵而特别准备的装束。"
  },
  [112240335] = {
    id = 112240335,
    name = "带上专门用于引渡亡灵的符咒、道具，向那个山谷走去。"
  },
  [112240336] = {
    id = 112240336,
    name = "（这一次，不是为了击败它们。）"
  },
  [112240337] = {
    id = 112240337,
    name = "（而是为了送它们回去。）"
  },
  [112250001] = {
    id = 112250001,
    name = "深渊据点，玛蒙之地的酒馆。傍晚时分，探险者们三三两两聚在一起。"
  },
  [112250002] = {
    id = 112250002,
    name = "最近一段日子，据点里最热闹的话题只有一个——交界地带的圣物。"
  },
  [112250003] = {
    id = 112250003,
    name = "听说了吗？第一层和第二层的交界地带，出了件圣物！"
  },
  [112250004] = {
    id = 112250004,
    name = "圣物？那可是开发出来能抵消深渊侵蚀的好东西，消息可靠吗？"
  },
  [112250005] = {
    id = 112250005,
    name = "公会情报部都确认了，说是什么......「厄运之匣」，能洗净人身上的霉运！"
  },
  [112250006] = {
    id = 112250006,
    name = "洗净霉运？真有这种东西，我倒想买一个。"
  },
  [112250007] = {
    id = 112250007,
    name = "别做梦了。听说那匣子古怪得很——只有霉运缠身的人才能靠近它，运气好的反而碰都碰不到。"
  },
  [112250008] = {
    id = 112250008,
    name = "还有这种事？那岂不是越倒霉越值钱......"
  },
  [112250009] = {
    id = 112250009,
    name = "角落里，一个抱着酒壶的少女耳朵动了动。"
  },
  [112250010] = {
    id = 112250010,
    name = "洗净霉运......真的假的？"
  },
  [112250011] = {
    id = 112250011,
    name = "深渊里藏着能改变运气的东西，难道我这话还真说着了？"
  },
  [112250012] = {
    id = 112250012,
    name = "她正要凑上去细听，脚下不知被什么绊了一下，整个人扑倒在桌边，酒壶骨碌碌滚出老远。"
  },
  [112250013] = {id = 112250013, name = "哎呀！"},
  [112250014] = {
    id = 112250014,
    name = "满桌的探险者齐刷刷看过来，少女却一骨碌爬起，拍了拍衣服，脸上还挂着笑。"
  },
  [112250015] = {
    id = 112250015,
    name = "没事没事！这叫攒运气，攒够了就全回来了！"
  },
  [112250016] = {
    id = 112250016,
    name = "她弯腰去捡酒壶，一只手却先一步伸过来，将一张盖着公会印章的信笺递到她面前。"
  },
  [112250017] = {id = 112250017, name = "菲欧？"},
  [112250018] = {
    id = 112250018,
    name = "哎？你认识我？"
  },
  [112250019] = {
    id = 112250019,
    name = "公会作战部，蒂娜。找了你三天。"
  },
  [112250020] = {
    id = 112250020,
    name = "少女眨眨眼，打量面前这个沉默寡言的年轻女子——一身利落打扮，眉眼认真，周身透着股不好接近的冷淡。"
  },
  [112250021] = {
    id = 112250021,
    name = "公会的人找我？我这阵子可没惹麻烦......吧？"
  },
  [112250022] = {
    id = 112250022,
    name = "你接委托从不挑剔。有件事，全据点的探险者里，只有你合适。"
  },
  [112250023] = {
    id = 112250023,
    name = "（只有我合适？）"
  },
  [112250024] = {
    id = 112250024,
    name = "什么事啊，神神秘秘的。"
  },
  [112250025] = {
    id = 112250025,
    name = "圣物，「厄运之匣」。需要一个人替公会去拿回它。"
  },
  [112250026] = {
    id = 112250026,
    name = "酒馆里安静了一瞬，随即响起一片倒抽气的声音。"
  },
  [112250027] = {
    id = 112250027,
    name = "让......让她去碰圣物？那东西不是霉运越重越灵吗？"
  },
  [112250028] = {
    id = 112250028,
    name = "全据点最倒霉的，可不就是她嘛......"
  },
  [112250029] = {
    id = 112250029,
    name = "公会作战部临时驻地。作战部部长斯彭德站在地图前，眉头紧锁。"
  },
  [112250030] = {
    id = 112250030,
    name = "交界地带的浊炁气息异常，高塔的人恐怕也已经收到消息了。"
  },
  [112250031] = {
    id = 112250031,
    name = "圣物不能落在高塔手里。蒂娜，你选的人可靠吗？"
  },
  [112250032] = {
    id = 112250032,
    name = "全据点筛选下来，只有她符合条件。霉运缠身，心性却极稳。"
  },
  [112250033] = {
    id = 112250033,
    name = "霉运缠身......真不知道这是福是祸。"
  },
  [112250034] = {
    id = 112250034,
    name = "门外传来一阵咚咚的敲门声，紧接着是欢快的喊声。"
  },
  [112250035] = {
    id = 112250035,
    name = "开门开门！我来接委托啦！"
  },
  [112250036] = {
    id = 112250036,
    name = "门一开，少女带着一身风尘扑进来，进门先绊了一跤。"
  },
  [112250037] = {
    id = 112250037,
    name = "哎哟！——没事没事，地上这门槛设计得不错，防贼。"
  },
  [112250038] = {
    id = 112250038,
    name = "......你就是菲欧？"
  },
  [112250039] = {
    id = 112250039,
    name = "如假包换！射手菲欧，接委托从不挑剔，您说吧，是护送还是探路？打魔物也行，我关键时刻可准了！"
  },
  [112250040] = {
    id = 112250040,
    name = "不是让你打魔物。是让你去带回一件圣物。"
  },
  [112250041] = {
    id = 112250041,
    name = "......圣物？"
  },
  [112250042] = {
    id = 112250042,
    name = "「厄运之匣」。只有霉运缠身的人才能靠近它，你是全据点唯一的人选。"
  },
  [112250043] = {
    id = 112250043,
    name = "霉运缠身......哈哈，我这辈子最不缺的就是霉运！说吧，要我干什么！"
  },
  [112250044] = {
    id = 112250044,
    name = "斯彭德把事情简要说了一遍：圣物现世于第一、二层交界地带，公会想抢先鉴定、带回开发。而菲欧要做的事，是替公会带回它。"
  },
  [112250045] = {
    id = 112250045,
    name = "洗净厄运......真有这种东西，那我不是捡了个大便宜？"
  },
  [112250046] = {
    id = 112250046,
    name = "别高兴太早。圣物现世，各方都会闻风而动。"
  },
  [112250047] = {
    id = 112250047,
    name = "放心放心！我运气虽然差，命可硬着呢！"
  },
  [112250048] = {
    id = 112250048,
    name = "就这样，菲欧的委托定了下来。同行的是你——公会临时指派的护送队长——以及沉默寡言的蒂娜。"
  },
  [112250049] = {
    id = 112250049,
    name = "出发之前，先把你这身装备收拾收拾。"
  },
  [112250050] = {
    id = 112250050,
    name = "收到！——哎呀，箭筒带子又断了。"
  },
  [112250051] = {
    id = 112250051,
    name = "没事没事，出发前把霉运倒干净，路上就顺了！"
  },
  [112250052] = {
    id = 112250052,
    name = "前往交界地带的路途，远比想象中热闹。"
  },
  [112250053] = {
    id = 112250053,
    name = "队伍在第二个补给哨所停下时，一个抱着法杖的少女早已等在路口，见到你们，她紧张地搓了搓手指。"
  },
  [112250054] = {
    id = 112250054,
    name = "那、那个......是蒂娜让我来汇合的，我叫安妮斯。"
  },
  [112250055] = {
    id = 112250055,
    name = "哦哦！你就是那个传闻中的——灾祸魔女？"
  },
  [112250056] = {
    id = 112250056,
    name = "！（脸色一白）你、你也听过我......"
  },
  [112250057] = {
    id = 112250057,
    name = "听过听过！听说你在学校的时候因为这个名头，几乎没人敢跟你组队！"
  },
  [112250058] = {
    id = 112250058,
    name = "对、对不起......要不我还是回去吧，免得连累你们......"
  },
  [112250059] = {
    id = 112250059,
    name = "连累什么呀！来来来，认识一下，我叫菲欧，全据点最倒霉的那个，以后咱俩谁也别嫌弃谁！"
  },
  [112250060] = {id = 112250060, name = "哎？"},
  [112250061] = {
    id = 112250061,
    name = "我跟你讲，我这人有个理论，叫运气守恒——倒霉倒够了，运气自然就回来了！"
  },
  [112250062] = {
    id = 112250062,
    name = "你觉得自己是灾星，我倒觉得，你这是把别人该倒的霉都揽到自己身上了，多厉害！"
  },
  [112250063] = {
    id = 112250063,
    name = "把别人该倒的霉......揽到自己身上？"
  },
  [112250064] = {
    id = 112250064,
    name = "对啊！不然怎么偏偏是你，而不是别人？肯定是你偷偷把大家的霉运都吸走了！"
  },
  [112250065] = {
    id = 112250065,
    name = "安妮斯怔怔地看着面前这个笑得眉眼弯弯的少女，很久没说话。"
  },
  [112250066] = {
    id = 112250066,
    name = "（第一次......有人这么说。）"
  },
  [112250067] = {
    id = 112250067,
    name = "队伍继续上路。有了菲欧和安妮斯，路上果然热闹了不少——一个叽叽喳喳说个不停，一个小声应着，偶尔还会被逗得弯起眼睛。"
  },
  [112250068] = {
    id = 112250068,
    name = "队长，你觉不觉得......今天路上格外的吵？"
  },
  [112250069] = {
    id = 112250069,
    name = "偶尔探险路上热闹一下也不错。"
  },
  [112250070] = {
    id = 112250070,
    name = "哎哎哎！那边有棵果树！你们等等我，我去摘几个！"
  },
  [112250071] = {
    id = 112250071,
    name = "菲欧，小心——"
  },
  [112250072] = {
    id = 112250072,
    name = "话音未落，少女已经踩上树根，一脚踏空，骨碌碌滚进草丛，又顶着一脑袋草叶钻出来，手里还攥着两个果子。"
  },
  [112250073] = {
    id = 112250073,
    name = "嘿嘿，运气守恒，这俩果子归我！"
  },
  [112250074] = {id = 112250074, name = "噗。"},
  [112250075] = {
    id = 112250075,
    name = "安妮斯没忍住笑出了声。这是她很久以来，第一次在路上笑出来。"
  },
  [112250076] = {
    id = 112250076,
    name = "交界地带。浊炁的气息比别处浓重得多，空气里浮着淡淡的灰雾。"
  },
  [112250077] = {
    id = 112250077,
    name = "前方就是圣物现世的位置。大家小心，这里曾有暗域爆发的痕迹。"
  },
  [112250078] = {
    id = 112250078,
    name = "暗域？反正有我顶着，霉运找不上你们！"
  },
  [112250079] = {
    id = 112250079,
    name = "别说这种话！万一真出什么事——呸呸呸，不会出事的！"
  },
  [112250080] = {
    id = 112250080,
    name = "就在一行人准备继续深入时，灰雾忽然向两侧分开，一道带着笑意的声音从雾中传来。"
  },
  [112250081] = {
    id = 112250081,
    name = "真是热闹。公会来得倒快。"
  },
  [112250082] = {
    id = 112250082,
    name = "雾中走出一行人，为首的女子仪态从容，笑吟吟的目光却带着毫不掩饰的审视。她的身后，无间狱的成员无声列阵，封住了去路。"
  },
  [112250083] = {
    id = 112250083,
    name = "无间狱......缇法尼！"
  },
  [112250084] = {
    id = 112250084,
    name = "哦？认识我？那我就不自我介绍了。"
  },
  [112250085] = {
    id = 112250085,
    name = "小妹妹们，前面那件圣物，我们无间狱要了。诸位现在回头，还能平平安安回家。"
  },
  [112250086] = {
    id = 112250086,
    name = "凭什么呀！这是公会先接的委托！"
  },
  [112250087] = {
    id = 112250087,
    name = "公会先接的？呵呵，圣物可没写谁的名字。"
  },
  [112250088] = {
    id = 112250088,
    name = "她说着，目光在几人身上缓缓扫过，最后停在菲欧身上，笑意微微一顿。"
  },
  [112250089] = {
    id = 112250089,
    name = "咦？有意思。霉运缠身......你就是那个能碰圣物的钥匙？"
  },
  [112250090] = {
    id = 112250090,
    name = "是又怎么样！"
  },
  [112250091] = {
    id = 112250091,
    name = "那更好了。省得我再费心去找。"
  },
  [112250092] = {
    id = 112250092,
    name = "你、你想干嘛！"
  },
  [112250093] = {
    id = 112250093,
    name = "那件圣物，对我很重要。为了它，我做了几十年的准备——只要能把它带回去，我毕生研究的那个课题，就有希望了。"
  },
  [112250094] = {
    id = 112250094,
    name = "什么课题......"
  },
  [112250095] = {
    id = 112250095,
    name = "呵呵，小丫头听不懂也没关系。你只要知道，那东西值得我亲自来一趟。"
  },
  [112250096] = {
    id = 112250096,
    name = "她抬手一挥，无间狱成员立刻合围上来。蒂娜拔剑挡在菲欧身前，你握紧武器，气氛瞬间剑拔弩张。"
  },
  [112250097] = {
    id = 112250097,
    name = "你、你别过来！我警告你，我发起飙来可准了！"
  },
  [112250098] = {
    id = 112250098,
    name = "准？那就让我看看，你这把钥匙，到底有几分成色。"
  },
  [112250099] = {
    id = 112250099,
    name = "话音落下，缇法尼的身影骤然逼近——而就在这千钧一发之际，交界地深处忽然传来一声沉闷的嗡鸣。"
  },
  [112250100] = {
    id = 112250100,
    name = "圣物......在回应！"
  },
  [112250101] = {
    id = 112250101,
    name = "！（神色一变）居然现在醒了。好，我倒要看看，谁能抢在谁前面。"
  },
  [112250102] = {
    id = 112250102,
    name = "灰雾深处，一线暗金色的光冲破迷雾，直冲天际。圣物，现世了。"
  },
  [112250103] = {
    id = 112250103,
    name = "交界地的中央，一块嶙峋的黑岩之上，静静放着一只巴掌大的暗金色匣子。"
  },
  [112250104] = {
    id = 112250104,
    name = "匣身无纹，却散发着令人心悸的气息——周围的空气都在微微扭曲，仿佛有什么东西正被它不断吸进去。"
  },
  [112250105] = {
    id = 112250105,
    name = "这就是......「厄运之匣」。"
  },
  [112250106] = {
    id = 112250106,
    name = "传闻没错。靠近它的人，身上的霉运都会被吸走。"
  },
  [112250107] = {
    id = 112250107,
    name = "那我要是靠近......岂不是把霉运都交给它了？"
  },
  [112250108] = {
    id = 112250108,
    name = "嗯。所以你才是唯一的人选。"
  },
  [112250109] = {
    id = 112250109,
    name = "无间狱的人虎视眈眈，公会的人严阵以待，两方对峙，谁也没有先动——因为所有人都知道，能碰到那匣子的，只有一个人。"
  },
  [112250110] = {
    id = 112250110,
    name = "小妹妹，上吧。让我们都看看，传闻到底是真是假。"
  },
  [112250111] = {
    id = 112250111,
    name = "看就看！"
  },
  [112250112] = {
    id = 112250112,
    name = "菲欧深吸一口气，一步一步走向黑岩。离匣子越近，她越觉得周身轻快——那些常年压在身上的、说不清道不明的晦气，正在一点点剥离。"
  },
  [112250113] = {
    id = 112250113,
    name = "咦......真的......不倒霉了？"
  },
  [112250114] = {
    id = 112250114,
    name = "她伸出手，指尖触上匣身。暗金色的匣面忽然亮起柔和的光，仿佛终于等到了自己的主人。"
  },
  [112250115] = {id = 112250115, name = "哇！"},
  [112250116] = {
    id = 112250116,
    name = "下一瞬，一股清凉的暖流顺着指尖涌遍全身。菲欧只觉得这辈子从没这么轻快过——脚下不滑了，呼吸也顺畅了，连风都好像绕着她走。"
  },
  [112250117] = {
    id = 112250117,
    name = "我、我不倒霉了？我真的不倒霉了？！"
  },
  [112250118] = {
    id = 112250118,
    name = "她原地蹦了两下，又原地转了个圈，一脸难以置信。"
  },
  [112250119] = {
    id = 112250119,
    name = "哈哈哈哈哈！运气守恒！我就说攒够了会回来的！今天就是我的转运日！"
  },
  [112250120] = {
    id = 112250120,
    name = "有意思。果然是传说中的样子。"
  },
  [112250121] = {
    id = 112250121,
    name = "圣物认主了。菲欧，快把它带回来。"
  },
  [112250122] = {
    id = 112250122,
    name = "菲欧小心翼翼地捧起匣子，暗金色的光在她掌心里流转，温驯得像只听话的小兽。所有人都松了一口气——除了一个人。"
  },
  [112250123] = {
    id = 112250123,
    name = "队伍最后方，安妮斯忽然晃了晃，脸色一点点变得苍白。"
  },
  [112250124] = {
    id = 112250124,
    name = "奇怪......我......这是怎么了......"
  },
  [112250125] = {
    id = 112250125,
    name = "话音刚落，她脚下不知被什么一绊，整个人向前栽去，手中的法杖脱手飞出，狠狠砸在岩壁上出现了深深的裂痕。"
  },
  [112250126] = {
    id = 112250126,
    name = "我的法杖！"
  },
  [112250127] = {
    id = 112250127,
    name = "菲欧的笑容凝固在脸上。她看看掌心的匣子，又看看狼狈跌坐的安妮斯——一个念头猛地撞进脑海。"
  },
  [112250128] = {
    id = 112250128,
    name = "安妮斯她......她以前从没这么倒霉过。"
  },
  [112250129] = {
    id = 112250129,
    name = "菲欧，你手里的匣子——它在把霉运，转到别处去。"
  },
  [112250130] = {
    id = 112250130,
    name = "交界地的风忽然安静下来。"
  },
  [112250131] = {
    id = 112250131,
    name = "我的猜测没错。「厄运之匣」不会消除霉运，它只是把霉运，从一个人身上，搬到另一个人身上。"
  },
  [112250132] = {
    id = 112250132,
    name = "搬到......另一个人身上？"
  },
  [112250133] = {
    id = 112250133,
    name = "所以刚才我才会......这、这不怪菲欧，是我自己没站稳......"
  },
  [112250134] = {
    id = 112250134,
    name = "不怪你！怎么不怪我！是我拿的匣子！"
  },
  [112250135] = {
    id = 112250135,
    name = "菲欧看看掌心里温驯的匣子，又看看地上安妮斯的法杖，第一次没有接话。"
  },
  [112250136] = {
    id = 112250136,
    name = "她这辈子听过最多的话，就是「你又倒霉了」。可眼前这个才刚刚笑起来、才第一次跟她并肩赶路的女孩，现在却因为她倒霉了。"
  },
  [112250137] = {
    id = 112250137,
    name = "呵呵，原来如此。圣物吸的是厄运，转的也是厄运——倒真是件好宝贝。"
  },
  [112250138] = {
    id = 112250138,
    name = "钥匙小姐，看来你这位同伴，得先替你还一阵子了。"
  },
  [112250139] = {
    id = 112250139,
    name = "你闭嘴！"
  },
  [112250140] = {
    id = 112250140,
    name = "哦？还生气了？那你倒是说说，这匣子，你是要，还是不要？"
  },
  [112250141] = {
    id = 112250141,
    name = "菲欧抱着匣子，站在原地，很久没有说话。她能感觉到，只要匣子在手，她就不会再倒霉——可她也能感觉到，那些被吸走的霉运，正从自己身上，源源不断地流向离她最近的安妮斯。"
  },
  [112250142] = {
    id = 112250142,
    name = "（运气守恒......运气守恒......）"
  },
  [112250143] = {
    id = 112250143,
    name = "（我一直以为，只要我多倒点霉，运气就会回来。可原来，我的霉运不是消失了，是跑到别人身上去了？）"
  },
  [112250144] = {
    id = 112250144,
    name = "菲欧，你、你别哭啊！我真的没事！摔一跤而已！"
  },
  [112250145] = {
    id = 112250145,
    name = "谁哭了！我才没哭！"
  },
  [112250146] = {
    id = 112250146,
    name = "她用力吸了吸鼻子，把匣子往怀里一揣，转身就走。"
  },
  [112250147] = {
    id = 112250147,
    name = "这委托，我不接了！谁爱接谁接！"
  },
  [112250148] = {
    id = 112250148,
    name = "不接了？呵呵，小妹妹，圣物已经认主——你走了，它可就跟着你走了。"
  },
  [112250149] = {
    id = 112250149,
    name = "带着它，你能逃到哪里去呢？"
  },
  [112250150] = {
    id = 112250150,
    name = "话音落下，无间狱的包围圈再次收紧。暗金色的光在菲欧怀中明明灭灭，像一盏不肯熄灭的灯。"
  },
  [112250151] = {
    id = 112250151,
    name = "我不管！反正......反正我不能让它再害安妮斯！"
  },
  [112250152] = {
    id = 112250152,
    name = "风从交界地深处吹来，卷起一地灰雾。圣物、钥匙、追兵、还有那句「运气守恒」——一切，才刚刚开始。"
  },
  [112260001] = {
    id = 112260001,
    name = "圈落据点，午后的街道热闹而喧嚷。"
  },
  [112260002] = {
    id = 112260002,
    name = "阳光从屋顶的缝隙间漏下来，把石板路晒得微微发烫。"
  },
  [112260003] = {
    id = 112260003,
    name = "逐幻者悠闲地走在集市里，手里捧着一袋刚出炉的点心，另一只手则拨弄着摊位上稀奇古怪的小玩意儿。"
  },
  [112260004] = {
    id = 112260004,
    name = "嗯~这家店的果子确实不错，下次要再来多买一点。"
  },
  [112260005] = {
    id = 112260005,
    name = "摊主见她翻来覆去地看一块会发光的石头，笑呵呵地招呼道："
  },
  [112260006] = {
    id = 112260006,
    name = "姑娘好眼光！这可是从北边深谷里带出来的晶石，夜里会发亮，当护身符再好不过了！"
  },
  [112260007] = {
    id = 112260007,
    name = "哦？深谷里的晶石......有意思。它为什么会发光呀？"
  },
  [112260008] = {
    id = 112260008,
    name = "这......这我可说不上来，反正大家都说灵验！"
  },
  [112260009] = {
    id = 112260009,
    name = "呵呵，那还是算了。我只想知道它发光的缘由，不想要一个说不清来历的'灵验'。"
  },
  [112260010] = {
    id = 112260010,
    name = "她把石头放回摊位，转身便听见不远处几个探险者正围着桌子兴奋地议论着什么。"
  },
  [112260011] = {
    id = 112260011,
    name = "听说了吗？深渊里出现了一片会变幻的区域！"
  },
  [112260012] = {
    id = 112260012,
    name = "据说里面藏着惊人秘宝，谁先找到，谁就能一夜成名、翻身发财！"
  },
  [112260013] = {
    id = 112260013,
    name = "已经有好多支队伍连夜出发了，去晚了怕是连汤都喝不上！"
  },
  [112260014] = {
    id = 112260014,
    name = "......又是这种传闻。"
  },
  [112260015] = {
    id = 112260015,
    name = "她本想转身走开，脚步却忽然顿了一下。"
  },
  [112260016] = {
    id = 112260016,
    name = "最邪门的是那片区域会不断变幻形态！一会儿是山，一会儿是林，从来没人能完整记录它的全貌！"
  },
  [112260017] = {
    id = 112260017,
    name = "不断变幻形态？"
  },
  [112260018] = {
    id = 112260018,
    name = "逐幻者折返回去，凑到那几人身边，顺手把最后一块点心塞进嘴里。"
  },
  [112260019] = {
    id = 112260019,
    name = "打扰一下~你们说的那个地方，能再讲详细一点吗？"
  },
  [112260020] = {
    id = 112260020,
    name = "哟，你也想去碰碰运气？那可要抓紧了，去寻宝的人可不少。"
  },
  [112260021] = {
    id = 112260021,
    name = "碰运气？我对秘宝什么的可没啥兴趣。"
  },
  [112260022] = {
    id = 112260022,
    name = "我只是好奇，能让人连完整模样都记不住的奇景，到底是什么样子。"
  },
  [112260023] = {
    id = 112260023,
    name = "探险者们面面相觑，似乎不太理解她的想法。"
  },
  [112260024] = {
    id = 112260024,
    name = "为了点宝物就乌泱泱地挤过去......那哪叫探险，分明是淘金嘛。"
  },
  [112260025] = {
    id = 112260025,
    name = "她拍拍手上的点心屑，眼睛却亮得像找到了什么稀罕物。"
  },
  [112260026] = {
    id = 112260026,
    name = "会移变幻的奇景......这个，倒是值得去看一眼。"
  },
  [112260027] = {
    id = 112260027,
    name = "探险队驻地，傍晚。"
  },
  [112260028] = {
    id = 112260028,
    name = "大厅里点着灯，留守的工会成员正低声交谈着白天的事务。"
  },
  [112260029] = {
    id = 112260029,
    name = "逐幻者推门走进来，绕过人群，在主角对面的椅子上坐下，一脸兴致勃勃。"
  },
  [112260030] = {
    id = 112260030,
    name = "看你心情不错，是逛街买到什么好东西了？"
  },
  [112260031] = {
    id = 112260031,
    name = "嘿嘿，确实买了不少。不过我想说的不是这个。"
  },
  [112260032] = {
    id = 112260032,
    name = "逐幻者压低声音，难得露出认真的神色。"
  },
  [112260033] = {
    id = 112260033,
    name = "队长，深渊里出现了一片会移动的区域，你听说了吗？"
  },
  [112260034] = {
    id = 112260034,
    name = "是据点里传得沸沸扬扬的那个？据说里面藏着秘宝。"
  },
  [112260035] = {
    id = 112260035,
    name = "秘宝什么的我才不管，我是对那片区域本身感兴趣。"
  },
  [112260036] = {
    id = 112260036,
    name = "能不断变化、还没人记录过全貌的奇景，光是想想就让人兴奋，对吧？"
  },
  [112260037] = {
    id = 112260037,
    name = "你对'新奇事物'的执着，倒是一点没变。"
  },
  [112260038] = {
    id = 112260038,
    name = "那当然~现在咱们能结伴同行，不就是要一起寻找新奇有趣的事物嘛。"
  },
  [112260039] = {
    id = 112260039,
    name = "所以这次，你也想去看看。"
  },
  [112260040] = {
    id = 112260040,
    name = "嗯！而且这次去的人鱼龙混杂，说不定还能顺路看个热闹。"
  },
  [112260041] = {
    id = 112260041,
    name = "她说着，又想起什么似的补了一句："
  },
  [112260042] = {
    id = 112260042,
    name = "当然啦，我只是想去看看，不会耽误队里的正事。"
  },
  [112260043] = {
    id = 112260043,
    name = "正好，最近队伍没有紧急任务，我陪你走一趟。"
  },
  [112260044] = {
    id = 112260044,
    name = "诶？队长也去？"
  },
  [112260045] = {
    id = 112260045,
    name = "那片区域连形态都还没人记录过，多半不简单。两个人也好互相照应。"
  },
  [112260046] = {
    id = 112260046,
    name = "哼哼，队长果然够意思！"
  },
  [112260047] = {
    id = 112260047,
    name = "她高兴地一拍桌子，差点把桌上的茶杯震倒，又赶紧扶住，讪讪一笑。"
  },
  [112260048] = {
    id = 112260048,
    name = "那说好了，明天一早出发，你可不许赖床~"
  },
  [112260049] = {
    id = 112260049,
    name = "你倒是先把自己叫醒再说。"
  },
  [112260050] = {
    id = 112260050,
    name = "嘿嘿，我可是有名的早起鸟！"
  },
  [112260051] = {
    id = 112260051,
    name = "出发前夜，驻地大厅的灯火还亮着。"
  },
  [112260052] = {
    id = 112260052,
    name = "主角路过逐幻者的房间，看见门虚掩着，里面传来翻动纸张的声响。"
  },
  [112260053] = {
    id = 112260053,
    name = "推门一看，逐幻者正趴在桌前，面前摊开一张标注得密密麻麻的地图。"
  },
  [112260054] = {
    id = 112260054,
    name = "这么晚还不休息？明天还要赶路。"
  },
  [112260055] = {
    id = 112260055,
    name = "啊，队长。正好，你来看看这条路对不对。"
  },
  [112260056] = {
    id = 112260056,
    name = "主角走过去，发现地图上标着好几条备选路线，旁边还写满了关于地形与魔物出没的笔记。"
  },
  [112260057] = {
    id = 112260057,
    name = "......你平时出门，可没见你准备得这么仔细。"
  },
  [112260058] = {
    id = 112260058,
    name = "那当然啦，平时是出去玩，这次是去探险嘛。"
  },
  [112260059] = {
    id = 112260059,
    name = "难得有个连形态都没人记录全的地方，当然要认真一点。"
  },
  [112260060] = {
    id = 112260060,
    name = "只是这样？"
  },
  [112260061] = {
    id = 112260061,
    name = "......不然还能怎样？"
  },
  [112260062] = {
    id = 112260062,
    name = "逐幻者低头拨弄着桌上的装备，声音轻了些。"
  },
  [112260063] = {
    id = 112260063,
    name = "万一那片区域里藏着什么危险，我总不能拖队长后腿吧。"
  },
  [112260064] = {
    id = 112260064,
    name = "那倒是让我有点意外。你平时不是总说'力量够用就行'？"
  },
  [112260065] = {
    id = 112260065,
    name = "够用是在平时~真到要紧的时候，我可从来不会含糊。"
  },
  [112260066] = {
    id = 112260066,
    name = "嗯，这话我记得。你还说过，太过痴迷力量反而会错过许多有意义的事。"
  },
  [112260067] = {
    id = 112260067,
    name = "对呀！所以我平时才要多享受生活，把没意义的事都省下来，留给真正有意思的事！"
  },
  [112260068] = {
    id = 112260068,
    name = "她说着，又低头检查了一遍武器，确认刃口锋利，才心满意足地收进鞘里。"
  },
  [112260069] = {
    id = 112260069,
    name = "你确实变了不少。"
  },
  [112260070] = {
    id = 112260070,
    name = "嘿嘿，我也是一直走在变强的路上好吧！"
  },
  [112260071] = {
    id = 112260071,
    name = "她拍了拍整理好的背包，重新露出爽朗的笑容。"
  },
  [112260072] = {
    id = 112260072,
    name = "行了行了，队长快去休息吧，明天还要赶路呢！"
  },
  [112260073] = {
    id = 112260073,
    name = "主角转身离开时，听见身后传来逐幻者轻轻的嘀咕："
  },
  [112260074] = {
    id = 112260074,
    name = "希望明天......不会碰上不想见的人吧。"
  },
  [112260075] = {
    id = 112260075,
    name = "深渊边境，前往传闻区域的路途比想象中热闹。"
  },
  [112260076] = {
    id = 112260076,
    name = "一路上，不断有探险者的队伍擦肩而过，个个神色匆匆，恨不得插上翅膀飞到那片区域。"
  },
  [112260077] = {
    id = 112260077,
    name = "瞧瞧这阵仗，不知道的还以为是去赶集呢。"
  },
  [112260078] = {
    id = 112260078,
    name = "都是为了'秘宝'来的。看来传言确实传得挺广。"
  },
  [112260079] = {
    id = 112260079,
    name = "一个个眼睛都盯着宝物，也不怕踩空摔跟头。"
  },
  [112260080] = {
    id = 112260080,
    name = "你不也是为它来的？"
  },
  [112260081] = {
    id = 112260081,
    name = "我才不是为'它'！我是为'它所在的地方'来的，这区别可大着呢。"
  },
  [112260082] = {
    id = 112260082,
    name = "正说着，前方传来一阵喧闹。"
  },
  [112260083] = {
    id = 112260083,
    name = "一支凶神恶煞的队伍迎面走来。为首的是个满脸横肉的高大男人，腰间别着两把弯刀，目光在过往的探险者身上来回扫视，像是在打量猎物。"
  },
  [112260084] = {
    id = 112260084,
    name = "那伙人看起来不太好惹。"
  },
  [112260085] = {
    id = 112260085,
    name = "逐幻者没有接话。主角转头看去，发现她的脚步不知何时停了下来，脸上的笑意也淡了几分。"
  },
  [112260086] = {
    id = 112260086,
    name = "那高大男人显然也认出了逐幻者，眯起眼睛，嘴角勾起一抹意味不明的笑。"
  },
  [112260087] = {
    id = 112260087,
    name = "啧，这不是当年的小丫头吗？怎么，一个人也敢往深渊里跑？"
  },
  [112260088] = {
    id = 112260088,
    name = "呵呵，好久不见呀~没想到你还活着呢。"
  },
  [112260089] = {
    id = 112260089,
    name = "嘴倒是挺硬。怎么，这次也想'捡'点什么回去？"
  },
  [112260090] = {
    id = 112260090,
    name = "我可没兴趣跟你抢东西，只是去看个热闹罢了。"
  },
  [112260091] = {
    id = 112260091,
    name = "最好是这样。这片区域的东西，可不是谁都配碰的。"
  },
  [112260092] = {
    id = 112260092,
    name = "放心，我对你都能看上的'宝贝'，才没什么兴趣。"
  },
  [112260093] = {
    id = 112260093,
    name = "铁牙冷哼一声，目光在逐幻者身上停留片刻，终究没再多说什么，带着队伍大步离去。"
  },
  [112260094] = {
    id = 112260094,
    name = "直到那伙人走远，逐幻者脸上挂着的笑才慢慢淡了下来。"
  },
  [112260095] = {
    id = 112260095,
    name = "你们认识？"
  },
  [112260096] = {
    id = 112260096,
    name = "......算是吧。"
  },
  [112260097] = {
    id = 112260097,
    name = "一个不太愉快的旧识。走吧，别耽误正事。"
  },
  [112260098] = {
    id = 112260098,
    name = "逐幻者迈步向前，语气又恢复了轻松，可主角注意到，她握着武器的手，比平时握得紧了些。"
  },
  [112260099] = {
    id = 112260099,
    name = "（刚才那伙人的头领，看逐幻者的眼神不太对劲。......回头再问问她吧。）"
  },
  [112260100] = {
    id = 112260100,
    name = "越过一道峡谷后，周围的景象开始变得不同寻常。"
  },
  [112260101] = {
    id = 112260101,
    name = "明明是同一片天空，脚下的土地却像活的一样，缓慢地变换着颜色。"
  },
  [112260102] = {
    id = 112260102,
    name = "哇......这地面，怎么一会儿是沙地，一会儿又变成草地了？"
  },
  [112260103] = {
    id = 112260103,
    name = "传闻没有夸张，这片区域确实在变化。"
  },
  [112260104] = {
    id = 112260104,
    name = "而且你看那边——刚才明明是山，现在变成了一片树林。"
  },
  [112260105] = {
    id = 112260105,
    name = "逐幻者快步走到一棵凭空出现的树下，伸手摸了摸树干，又抬头打量着树冠。"
  },
  [112260106] = {
    id = 112260106,
    name = "是真的树。树干上的纹路都清清楚楚......它是什么时候出现在这里的？"
  },
  [112260107] = {
    id = 112260107,
    name = "更奇怪的是，我们没有感觉到任何异常。"
  },
  [112260108] = {
    id = 112260108,
    name = "嗯......像是整个空间都在'呼吸'一样，悄悄地把景色换了副模样。"
  },
  [112260109] = {
    id = 112260109,
    name = "逐幻者从背包里取出纸笔，认真地记录下眼前的景象。"
  },
  [112260110] = {
    id = 112260110,
    name = "这片林子的树木分布、地面土壤，还有空气中浊炁的浓度......都得记下来才行。"
  },
  [112260111] = {
    id = 112260111,
    name = "浊炁的浓度？"
  },
  [112260112] = {
    id = 112260112,
    name = "嗯，浊炁越浓的地方，往往越容易出现奇异的存在。说不定这片区域的变化，就和它有关。"
  },
  [112260113] = {
    id = 112260113,
    name = "......你对这些倒是很了解。"
  },
  [112260114] = {
    id = 112260114,
    name = "嘿嘿，以前跟着导师游历的时候，见过不少奇奇怪怪的地方，多少学了些门道。"
  },
  [112260115] = {
    id = 112260115,
    name = "她说着，又蹲下身，用指尖捻起一把土，放到鼻尖嗅了嗅。"
  },
  [112260116] = {
    id = 112260116,
    name = "这土的气味也不对劲，像是被什么东西浸染过......有意思，太有意思了！"
  },
  [112260117] = {
    id = 112260117,
    name = "看你这样子，是真把它当回事了。"
  },
  [112260118] = {
    id = 112260118,
    name = "那当然！能不断变化的奇景，深渊里恐怕找不出第二处！"
  },
  [112260119] = {
    id = 112260119,
    name = "二人继续深入，周围的景象仍在不断地变化重组，仿佛置身于一场醒着的梦。"
  },
  [112260120] = {
    id = 112260120,
    name = "逐幻者时而驻足观察，时而蹲下记录，全然不见往日的随意，反倒透出一种专注的认真。"
  },
  [112260121] = {
    id = 112260121,
    name = "感觉你比平时战斗的时候还投入。"
  },
  [112260122] = {
    id = 112260122,
    name = "那当然，战斗只要找到弱点总能有办法，这种奇景错过可就再也遇不到了！"
  },
  [112260123] = {
    id = 112260123,
    name = "在她身后不远处，几道黑影远远缀着，没有靠近，也没有离开——正是铁牙那支寻宝队。"
  },
  [112260124] = {
    id = 112260124,
    name = "越深入，变化便越剧烈。"
  },
  [112260125] = {
    id = 112260125,
    name = "空气变得清冽，脚下的土地不再反复变换，而是铺满了一层散发微光的苔藓，仿佛在指引着什么。"
  },
  [112260126] = {
    id = 112260126,
    name = "好漂亮......这些苔藓像是踩在星光上。"
  },
  [112260127] = {
    id = 112260127,
    name = "变化反而变少了，像是接近了某个稳定的中心。"
  },
  [112260128] = {
    id = 112260128,
    name = "那就说明，我们快到传闻里的'核心'了。"
  },
  [112260129] = {
    id = 112260129,
    name = "终于，在一片悬浮着无数光尘的空地上，二人停下了脚步。"
  },
  [112260130] = {
    id = 112260130,
    name = "空地中央，一株巨大的、半透明的植物缓缓舒展着枝叶。它通体流转着柔和的辉光，每一次呼吸般的颤动，周围的空间都会随之轻轻波动，掀起一圈圈光的涟漪。"
  },
  [112260131] = {
    id = 112260131,
    name = "这是......"
  },
  [112260132] = {
    id = 112260132,
    name = "传闻里说的'秘宝'，难道就是这个？"
  },
  [112260133] = {
    id = 112260133,
    name = "它像是......活着的。整个区域的变化，都是它在牵引。"
  },
  [112260134] = {
    id = 112260134,
    name = "逐幻者蹲下身，压低声音，语气里带着罕见的惊叹。"
  },
  [112260135] = {
    id = 112260135,
    name = "那些冲着'宝物'来的人，怕是做梦也想不到，他们要抢的是一件活生生的奇观。"
  },
  [112260136] = {
    id = 112260136,
    name = "如果传言传出去，它的处境只会更危险。"
  },
  [112260137] = {
    id = 112260137,
    name = "所以我才要把它记录下来呀。让更多人知道它是怎么样的存在，或许就不会只想着把它拆走卖钱了。"
  },
  [112260138] = {
    id = 112260138,
    name = "正当二人准备再靠近观察时，身后传来一阵急促的脚步声。"
  },
  [112260139] = {
    id = 112260139,
    name = "找了这么久，总算找到正主了。"
  },
  [112260140] = {
    id = 112260140,
    name = "铁牙带着那伙寻宝队从暗处涌出，将二人团团围住。"
  },
  [112260141] = {
    id = 112260141,
    name = "小丫头，识相的话就赶紧滚。这片区域的东西，归我们了。"
  },
  [112260142] = {
    id = 112260142,
    name = "归你们？呵呵，它本来就不属于任何人。"
  },
  [112260143] = {
    id = 112260143,
    name = "再说了，你们这群人，连它是什么都看不明白，也配说要'归你们'？"
  },
  [112260144] = {
    id = 112260144,
    name = "敬酒不吃吃罚酒。那就别怪我们人多欺负人少了！"
  },
  [112260145] = {
    id = 112260145,
    name = "寻宝队成员纷纷拔出武器，围拢过来。"
  },
  [112260146] = {
    id = 112260146,
    name = "逐幻者却不慌不忙，慢条斯理地活动了一下手腕，目光越过人群，落在铁牙身上。"
  },
  [112260147] = {
    id = 112260147,
    name = "正好，新账旧账，今天一起算了吧。"
  },
  [112270001] = {
    id = 112270001,
    name = "铁壁城，圣诞节前夕。"
  },
  [112270002] = {
    id = 112270002,
    name = "街道上依旧人来人往。"
  },
  [112270003] = {
    id = 112270003,
    name = "探险者们背着行囊，带着刚刚获得的素材和宝物，在城内匆匆穿行。"
  },
  [112270004] = {
    id = 112270004,
    name = "吉光站在人群中，看着眼前忙碌的景象。"
  },
  [112270005] = {id = 112270005, name = "嗯......"},
  [112270006] = {
    id = 112270006,
    name = "总觉得，好像少了点什么。"
  },
  [112270007] = {
    id = 112270007,
    name = "她抬头看向街道两旁。"
  },
  [112270008] = {
    id = 112270008,
    name = "往年的这个时候，城镇里多少都会挂上一些节日装饰。"
  },
  [112270009] = {
    id = 112270009,
    name = "可今年的铁壁城，却几乎看不到任何与圣诞节有关的东西。"
  },
  [112270010] = {
    id = 112270010,
    name = "一名探险者从她身边经过。"
  },
  [112270011] = {id = 112270011, name = "等等！"},
  [112270012] = {
    id = 112270012,
    name = "嗯？吉光，有什么事吗？"
  },
  [112270013] = {
    id = 112270013,
    name = "你知道圣诞节快到了吧？"
  },
  [112270014] = {
    id = 112270014,
    name = "圣诞节？"
  },
  [112270015] = {
    id = 112270015,
    name = "探险者想了想。"
  },
  [112270016] = {
    id = 112270016,
    name = "哦......好像是。"
  },
  [112270017] = {
    id = 112270017,
    name = "什么叫“好像是”啊？"
  },
  [112270018] = {
    id = 112270018,
    name = "最近不是刚发现了新的探索区域吗？大家都在准备出发，哪还有时间过节。"
  },
  [112270019] = {
    id = 112270019,
    name = "探险者说完便匆匆离开。"
  },
  [112270020] = {
    id = 112270020,
    name = "吉光站在原地，看着对方远去的背影。"
  },
  [112270021] = {
    id = 112270021,
    name = "连圣诞节都能忘掉......"
  },
  [112270022] = {
    id = 112270022,
    name = "她又看向不远处。"
  },
  [112270023] = {
    id = 112270023,
    name = "几名探险者正在讨论新的探索路线。"
  },
  [112270024] = {
    id = 112270024,
    name = "“听说那边还有没被发现的宝物。”"
  },
  [112270025] = {
    id = 112270025,
    name = "“这次一定要抢在其他队伍前面。”"
  },
  [112270026] = {
    id = 112270026,
    name = "“赶紧准备，明天就出发。”"
  },
  [112270027] = {
    id = 112270027,
    name = "吉光听了一会儿，忍不住叹了口气。"
  },
  [112270028] = {
    id = 112270028,
    name = "大家还真是有精神啊。"
  },
  [112270029] = {
    id = 112270029,
    name = "她低头看了看手里的日历。"
  },
  [112270030] = {
    id = 112270030,
    name = "圣诞节就在几天之后。"
  },
  [112270031] = {
    id = 112270031,
    name = "不过......"
  },
  [112270032] = {
    id = 112270032,
    name = "以前的探险者，也会这样吗？"
  },
  [112270033] = {
    id = 112270033,
    name = "第二天，吉光决定亲自去问问大家。"
  },
  [112270034] = {
    id = 112270034,
    name = "她在街道上转了一圈，很快就找到了几支正在准备出发的探险队。"
  },
  [112270035] = {
    id = 112270035,
    name = "你们好呀！"
  },
  [112270036] = {
    id = 112270036,
    name = "吉光？怎么了？"
  },
  [112270037] = {
    id = 112270037,
    name = "我有个问题想问问你们。"
  },
  [112270038] = {
    id = 112270038,
    name = "什么问题？"
  },
  [112270039] = {
    id = 112270039,
    name = "圣诞节快到了，你们打算怎么过？"
  },
  [112270040] = {
    id = 112270040,
    name = "几名探险者面面相觑。"
  },
  [112270041] = {
    id = 112270041,
    name = "圣诞节......？"
  },
  [112270042] = {
    id = 112270042,
    name = "对，就是圣诞节。"
  },
  [112270043] = {
    id = 112270043,
    name = "大概......不过吧。"
  },
  [112270044] = {
    id = 112270044,
    name = "为什么？"
  },
  [112270045] = {
    id = 112270045,
    name = "我们刚接到新的探索委托，时间很紧。"
  },
  [112270046] = {
    id = 112270046,
    name = "听说那片区域里还有不少没被发现的遗迹。"
  },
  [112270047] = {
    id = 112270047,
    name = "要是晚一步，说不定就被别人先找到了。"
  },
  [112270048] = {
    id = 112270048,
    name = "所以，比起圣诞节，你们更在意宝物？"
  },
  [112270049] = {
    id = 112270049,
    name = "也不能这么说。"
  },
  [112270050] = {
    id = 112270050,
    name = "只是......这种机会可不是每天都有。"
  },
  [112270051] = {
    id = 112270051,
    name = "吉光看着他们已经整理好的行囊。"
  },
  [112270052] = {
    id = 112270052,
    name = "武器、药品、地图，还有装得满满当当的素材袋。"
  },
  [112270053] = {id = 112270053, name = "也是。"},
  [112270054] = {
    id = 112270054,
    name = "她没有继续追问，而是转身走向另一边。"
  },
  [112270055] = {
    id = 112270055,
    name = "没过多久，她又遇到了几个刚从探索区回来的探险者。"
  },
  [112270056] = {
    id = 112270056,
    name = "那你们呢？圣诞节有什么安排吗？"
  },
  [112270057] = {
    id = 112270057,
    name = "当然没有。"
  },
  [112270058] = {
    id = 112270058,
    name = "这么干脆？"
  },
  [112270059] = {
    id = 112270059,
    name = "探索还没结束呢。"
  },
  [112270060] = {
    id = 112270060,
    name = "再说了，等赚够钱以后，什么时候庆祝都一样。"
  },
  [112270061] = {id = 112270061, name = "哦......"},
  [112270062] = {
    id = 112270062,
    name = "吉光若有所思地点了点头。"
  },
  [112270063] = {
    id = 112270063,
    name = "一路问下来，她得到的答案大同小异。"
  },
  [112270064] = {
    id = 112270064,
    name = "有人想要更多宝物。"
  },
  [112270065] = {
    id = 112270065,
    name = "有人想趁着新区域开放提升自己的实力。"
  },
  [112270066] = {
    id = 112270066,
    name = "有人不想错过难得的机会。"
  },
  [112270067] = {
    id = 112270067,
    name = "还有人只是单纯觉得——圣诞节年年都有，探索机会却不一定。"
  },
  [112270068] = {
    id = 112270068,
    name = "吉光站在街角，看着一队队探险者从身边经过。"
  },
  [112270069] = {
    id = 112270069,
    name = "他们有目标，有计划，也有必须赶上的下一站。"
  },
  [112270070] = {
    id = 112270070,
    name = "只是没有一个人停下来。"
  },
  [112270071] = {
    id = 112270071,
    name = "原来是这样啊。"
  },
  [112270072] = {
    id = 112270072,
    name = "大家不是忘记了圣诞节。"
  },
  [112270073] = {
    id = 112270073,
    name = "只是......已经没有时间去想它了。"
  },
  [112270074] = {
    id = 112270074,
    name = "她抬头看向铁壁城高大的城墙。"
  },
  [112270075] = {
    id = 112270075,
    name = "风从城外吹来，带着远方未知区域的气息。"
  },
  [112270076] = {
    id = 112270076,
    name = "可是这样的话......"
  },
  [112270077] = {
    id = 112270077,
    name = "圣诞节还有什么意义呢？"
  },
  [112270078] = {
    id = 112270078,
    name = "她想了想，又轻轻摇头。"
  },
  [112270079] = {id = 112270079, name = "不对。"},
  [112270080] = {
    id = 112270080,
    name = "一定还有什么，是大家没有想起来的。"
  },
  [112270081] = {
    id = 112270081,
    name = "傍晚，吉光一个人坐在铁壁城的城墙边。"
  },
  [112270082] = {
    id = 112270082,
    name = "城外的风吹过荒野，远处偶尔还能看到探险者赶路的身影。"
  },
  [112270083] = {
    id = 112270083,
    name = "他们背着行囊，朝着未知的方向不断前进。"
  },
  [112270084] = {
    id = 112270084,
    name = "吉光看着那些身影，忽然想起了小时候。"
  },
  [112270085] = {
    id = 112270085,
    name = "那时候，她还跟着家里四处旅行。"
  },
  [112270086] = {
    id = 112270086,
    name = "每到一个新的城镇，她总喜欢跑去听那些旅人讲故事。"
  },
  [112270087] = {
    id = 112270087,
    name = "有时候是发现了不得了的宝物。"
  },
  [112270088] = {
    id = 112270088,
    name = "有时候是在深渊里遇到了强大的魔物。"
  },
  [112270089] = {
    id = 112270089,
    name = "还有时候，明明已经陷入了绝境，却总有人能在最后关头找到办法。"
  },
  [112270090] = {
    id = 112270090,
    name = "然后......大家就这样逢凶化吉了。"
  },
  [112270091] = {
    id = 112270091,
    name = "她忍不住笑了起来。"
  },
  [112270092] = {
    id = 112270092,
    name = "小时候的她，最喜欢听的就是这样的故事。"
  },
  [112270093] = {
    id = 112270093,
    name = "比起宝物究竟价值多少，她更在意故事里的那些人最后有没有平安回来。"
  },
  [112270094] = {
    id = 112270094,
    name = "那个时候的探险者，好像总会回到某个地方。"
  },
  [112270095] = {
    id = 112270095,
    name = "然后把自己的冒险讲给别人听。"
  },
  [112270096] = {
    id = 112270096,
    name = "她低头看向铁壁城内。"
  },
  [112270097] = {
    id = 112270097,
    name = "街道依旧很忙。"
  },
  [112270098] = {
    id = 112270098,
    name = "有人在整理装备，有人在清点素材，还有人在讨论明天要走哪条路线。"
  },
  [112270099] = {
    id = 112270099,
    name = "每个人都在为下一次冒险做准备。"
  },
  [112270100] = {
    id = 112270100,
    name = "现在也是一样嘛。"
  },
  [112270101] = {
    id = 112270101,
    name = "只是......"
  },
  [112270102] = {
    id = 112270102,
    name = "她停顿了一下。"
  },
  [112270103] = {
    id = 112270103,
    name = "大家好像忘了，自己为什么要回来。"
  },
  [112270104] = {
    id = 112270104,
    name = "这句话说出口后，连吉光自己都愣了一下。"
  },
  [112270105] = {
    id = 112270105,
    name = "她沉默片刻，忽然从城墙上跳了下来。"
  },
  [112270106] = {id = 112270106, name = "对了！"},
  [112270107] = {
    id = 112270107,
    name = "既然大家都不回来，那我就去找他们！"
  },
  [112270108] = {
    id = 112270108,
    name = "她拍了拍身上的灰尘，脸上重新露出了熟悉的笑容。"
  },
  [112270109] = {
    id = 112270109,
    name = "圣诞节嘛。"
  },
  [112270110] = {
    id = 112270110,
    name = "总得有人来过才行。"
  },
  [112270111] = {
    id = 112270111,
    name = "她抬头望向远处。"
  },
  [112270112] = {
    id = 112270112,
    name = "那今年......"
  },
  [112270113] = {
    id = 112270113,
    name = "就让我来当一次圣诞老人好了！"
  },
  [112270114] = {
    id = 112270114,
    name = "既然决定要当圣诞老人，吉光立刻开始准备。"
  },
  [112270115] = {
    id = 112270115,
    name = "第一件事，就是准备礼物。"
  },
  [112270116] = {
    id = 112270116,
    name = "圣诞节当然要送礼物啦！"
  },
  [112270117] = {
    id = 112270117,
    name = "她拿出纸和笔，认真地列出了一张清单。"
  },
  [112270118] = {
    id = 112270118,
    name = "那么......大家到底想要什么呢？"
  },
  [112270119] = {
    id = 112270119,
    name = "她决定直接去问。"
  },
  [112270120] = {
    id = 112270120,
    name = "第一个被她找到的探险者正在擦拭自己的武器。"
  },
  [112270121] = {
    id = 112270121,
    name = "如果圣诞老人要送你一份礼物，你最想要什么？"
  },
  [112270122] = {id = 112270122, name = "礼物？"},
  [112270123] = {
    id = 112270123,
    name = "探险者想了想。"
  },
  [112270124] = {
    id = 112270124,
    name = "一把更好的武器吧。"
  },
  [112270125] = {
    id = 112270125,
    name = "好，记下了。"
  },
  [112270126] = {
    id = 112270126,
    name = "第二个人正在整理防具。"
  },
  [112270127] = {id = 112270127, name = "你呢？"},
  [112270128] = {
    id = 112270128,
    name = "高品质的防具。"
  },
  [112270129] = {
    id = 112270129,
    name = "也记下了。"
  },
  [112270130] = {
    id = 112270130,
    name = "第三个人正在清点自己的探索装备。"
  },
  [112270131] = {
    id = 112270131,
    name = "魔力结晶。"
  },
  [112270132] = {
    id = 112270132,
    name = "为什么？"
  },
  [112270133] = {
    id = 112270133,
    name = "可以拿来强化装备。"
  },
  [112270134] = {
    id = 112270134,
    name = "......合理。"
  },
  [112270135] = {
    id = 112270135,
    name = "她继续往下问。"
  },
  [112270136] = {
    id = 112270136,
    name = "有人想要新的地图。"
  },
  [112270137] = {
    id = 112270137,
    name = "有人想要稀有素材。"
  },
  [112270138] = {
    id = 112270138,
    name = "有人想要能够提升魔力的道具。"
  },
  [112270139] = {
    id = 112270139,
    name = "还有人认真地告诉她，希望圣诞老人能送自己一张“没有人去过的遗迹地图”。"
  },
  [112270140] = {
    id = 112270140,
    name = "吉光看着手里的清单，沉默了很久。"
  },
  [112270141] = {
    id = 112270141,
    name = "这真的是圣诞礼物吗？"
  },
  [112270142] = {
    id = 112270142,
    name = "她低头数了数。"
  },
  [112270143] = {
    id = 112270143,
    name = "武器、防具、魔力结晶、探索地图、稀有素材。"
  },
  [112270144] = {
    id = 112270144,
    name = "怎么感觉......"
  },
  [112270145] = {
    id = 112270145,
    name = "我只是把大家的愿望清单换成了另一份探索装备清单？"
  },
  [112270146] = {
    id = 112270146,
    name = "她忍不住笑了起来。"
  },
  [112270147] = {
    id = 112270147,
    name = "不过，既然答应了要当圣诞老人，她还是认真把每个人的愿望都记了下来。"
  },
  [112270148] = {id = 112270148, name = "嗯......"},
  [112270149] = {
    id = 112270149,
    name = "至少先把礼物准备好吧。"
  },
  [112270150] = {
    id = 112270150,
    name = "她看着那张越来越长的清单。"
  },
  [112270151] = {
    id = 112270151,
    name = "不过，总觉得还缺了点什么。"
  },
  [112270152] = {
    id = 112270152,
    name = "吉光想了想，却暂时没有想出答案。"
  },
  [112270153] = {
    id = 112270153,
    name = "于是她收起纸笔，朝着城内的集市走去。"
  },
  [112270154] = {
    id = 112270154,
    name = "没关系。"
  },
  [112270155] = {
    id = 112270155,
    name = "慢慢想，总会找到的。"
  },
  [112270156] = {
    id = 112270156,
    name = "准备礼物的时候，吉光忽然想起了一个问题。"
  },
  [112270157] = {
    id = 112270157,
    name = "对了......"
  },
  [112270158] = {
    id = 112270158,
    name = "她重新拿起纸笔。"
  },
  [112270159] = {
    id = 112270159,
    name = "大家当初为什么会成为探险者呢？"
  },
  [112270160] = {
    id = 112270160,
    name = "这一次，她没有去问大家想要什么礼物。"
  },
  [112270161] = {
    id = 112270161,
    name = "她问的是另一个问题。"
  },
  [112270162] = {
    id = 112270162,
    name = "你为什么成为探险者？"
  },
  [112270163] = {
    id = 112270163,
    name = "第一个回答她的人毫不犹豫。"
  },
  [112270164] = {
    id = 112270164,
    name = "当然是为了钱。"
  },
  [112270165] = {
    id = 112270165,
    name = "哈哈，果然很直接。"
  },
  [112270166] = {
    id = 112270166,
    name = "我是为了名声。"
  },
  [112270167] = {
    id = 112270167,
    name = "我想成为最厉害的探险者。"
  },
  [112270168] = {
    id = 112270168,
    name = "还有人是为了寻找失踪的家人。"
  },
  [112270169] = {
    id = 112270169,
    name = "有人是为了完成和朋友之间的约定。"
  },
  [112270170] = {
    id = 112270170,
    name = "也有人只是因为喜欢冒险，想去看看从来没人见过的地方。"
  },
  [112270171] = {
    id = 112270171,
    name = "吉光把这些答案一一记下来。"
  },
  [112270172] = {
    id = 112270172,
    name = "原来每个人都有自己的理由啊。"
  },
  [112270173] = {
    id = 112270173,
    name = "不过，那都是很久以前的事情了。"
  },
  [112270174] = {id = 112270174, name = "嗯？"},
  [112270175] = {
    id = 112270175,
    name = "现在当然是有新的遗迹就去探索，有宝物就去拿。"
  },
  [112270176] = {
    id = 112270176,
    name = "这不是很正常吗？"
  },
  [112270177] = {
    id = 112270177,
    name = "吉光没有回答。"
  },
  [112270178] = {
    id = 112270178,
    name = "她看着手里的纸。"
  },
  [112270179] = {
    id = 112270179,
    name = "上面写满了不同的答案。"
  },
  [112270180] = {
    id = 112270180,
    name = "钱、名声、家人、约定、冒险。"
  },
  [112270181] = {
    id = 112270181,
    name = "那些答案看起来毫无关系。"
  },
  [112270182] = {
    id = 112270182,
    name = "可不知道为什么，吉光却觉得它们都有些相似。"
  },
  [112270183] = {
    id = 112270183,
    name = "因为最开始的时候，他们都在期待着某件事情。"
  },
  [112270184] = {
    id = 112270184,
    name = "所以......"
  },
  [112270185] = {
    id = 112270185,
    name = "吉光低头看着那张纸。"
  },
  [112270186] = {
    id = 112270186,
    name = "大家不是不想过圣诞节。"
  },
  [112270187] = {
    id = 112270187,
    name = "只是一路走着走着，把最开始的愿望放到身后了。"
  },
  [112270188] = {
    id = 112270188,
    name = "她忽然想起了小时候听过的那些冒险故事。"
  },
  [112270189] = {
    id = 112270189,
    name = "那些故事里的探险者，也会经历危险，也会为了宝物拼尽全力。"
  },
  [112270190] = {
    id = 112270190,
    name = "但最后，他们总会回到同伴身边。"
  },
  [112270191] = {
    id = 112270191,
    name = "然后坐下来，一边吃东西，一边谈论这次冒险。"
  },
  [112270192] = {
    id = 112270192,
    name = "原来是这样。"
  },
  [112270193] = {
    id = 112270193,
    name = "她合上了笔记本。"
  },
  [112270194] = {
    id = 112270194,
    name = "那我知道圣诞节该送什么了。"
  },
  [112270195] = {
    id = 112270195,
    name = "铁壁城的一处仓库里，吉光正忙着清点最后一批东西。"
  },
  [112270196] = {
    id = 112270196,
    name = "桌上摆着包装好的礼物，还有提前准备好的食物。"
  },
  [112270197] = {
    id = 112270197,
    name = "礼物......没问题！"
  },
  [112270198] = {
    id = 112270198,
    name = "食物......也准备好了！"
  },
  [112270199] = {
    id = 112270199,
    name = "嗯，差不多了！"
  },
  [112270200] = {
    id = 112270200,
    name = "她转过身，看着仓库外那棵好不容易弄来的圣诞树。"
  },
  [112270201] = {
    id = 112270201,
    name = "最后是圣诞树！"
  },
  [112270202] = {
    id = 112270202,
    name = "吉光费了好一番功夫，终于把那棵巨大的圣诞树搬到了广场中央。"
  },
  [112270203] = {
    id = 112270203,
    name = "好重......"
  },
  [112270204] = {
    id = 112270204,
    name = "不过，这样才有圣诞节的感觉嘛！"
  },
  [112270205] = {
    id = 112270205,
    name = "她又挂上彩灯和装饰。"
  },
  [112270206] = {id = 112270206, name = "完成！"},
  [112270207] = {
    id = 112270207,
    name = "待一切布置完成，吉光来到了酒馆，向老板购买了大量食物。"
  },
  [112270208] = {
    id = 112270208,
    name = "你准备这么多东西，真的有人来吗？"
  },
  [112270209] = {id = 112270209, name = "当然！"},
  [112270210] = {
    id = 112270210,
    name = "他们只是暂时不知道自己想过圣诞节而已。"
  },
  [112270211] = {id = 112270211, name = "......"},
  [112270212] = {
    id = 112270212,
    name = "等他们回来，一定会很开心的。"
  },
  [112270213] = {
    id = 112270213,
    name = "那我就等着看了。"
  },
  [112270214] = {id = 112270214, name = "嘿嘿。"},
  [112270215] = {
    id = 112270215,
    name = "黄昏时分，吉光站在布置好的会场中央。"
  },
  [112270216] = {
    id = 112270216,
    name = "圣诞树、礼物和食物都已准备完毕。"
  },
  [112270217] = {id = 112270217, name = "好了！"},
  [112270218] = {
    id = 112270218,
    name = "这样就万事俱备了！"
  },
  [112270219] = {
    id = 112270219,
    name = "今年的圣诞节，一定会很热闹！"
  },
  [112270220] = {
    id = 112270220,
    name = "她刚说完，远处忽然传来一阵急促的脚步声。"
  },
  [112270221] = {
    id = 112270221,
    name = "不好了！"
  },
  [112270222] = {
    id = 112270222,
    name = "怎么了？"
  },
  [112270223] = {
    id = 112270223,
    name = "北边发现了一个新的遗迹！"
  },
  [112270224] = {
    id = 112270224,
    name = "新的遗迹？"
  },
  [112270225] = {id = 112270225, name = "对！"},
  [112270226] = {
    id = 112270226,
    name = "听说已经发现了不少好东西！"
  },
  [112270227] = {
    id = 112270227,
    name = "公会已经开始召集探索队了！"
  },
  [112270228] = {id = 112270228, name = "......"},
  [112270229] = {
    id = 112270229,
    name = "街道上的探险者很快重新忙碌起来。"
  },
  [112270230] = {
    id = 112270230,
    name = "有人收拾装备，有人准备补给，还有人已经朝城门赶去。"
  },
  [112270231] = {
    id = 112270231,
    name = "等一下！"
  },
  [112270232] = {
    id = 112270232,
    name = "今天不是圣诞节吗？"
  },
  [112270233] = {
    id = 112270233,
    name = "所以才要抓紧时间啊！"
  },
  [112270234] = {
    id = 112270234,
    name = "可是圣诞节的聚会......"
  },
  [112270235] = {
    id = 112270235,
    name = "下次再参加吧！"
  },
  [112270236] = {
    id = 112270236,
    name = "对不起，我们真的得走了！"
  },
  [112270237] = {id = 112270237, name = "......"},
  [112270238] = {
    id = 112270238,
    name = "城门缓缓打开。"
  },
  [112270239] = {
    id = 112270239,
    name = "一支又一支探险队朝着北方出发。"
  },
  [112270240] = {
    id = 112270240,
    name = "吉光站在广场上，看着刚刚准备好的圣诞会场。"
  },
  [112270241] = {id = 112270241, name = "......"},
  [112270242] = {
    id = 112270242,
    name = "她低头看了看手里的礼物清单。"
  },
  [112270243] = {
    id = 112270243,
    name = "原来如此。"
  },
  [112270244] = {
    id = 112270244,
    name = "吉光忽然笑了起来。"
  },
  [112270245] = {
    id = 112270245,
    name = "既然大家都这么喜欢冒险......"
  },
  [112270246] = {
    id = 112270246,
    name = "她重新背起装满礼物的袋子。"
  },
  [112270247] = {
    id = 112270247,
    name = "那今年的圣诞节......"
  },
  [112270248] = {
    id = 112270248,
    name = "就让我这个圣诞老人亲自去找你们吧！"
  },
  [112280001] = {
    id = 112280001,
    name = "多年以前的新年夜，一座小城的角落里，岁火在风雪中明灭。"
  },
  [112280002] = {
    id = 112280002,
    name = "雪片子打着旋儿落下，把屋顶都盖成了白的。"
  },
  [112280003] = {
    id = 112280003,
    name = "少女露西亚抱着一盏灯笼跑过雪地，脚下一滑，连人带灯跌进雪里。"
  },
  [112280004] = {
    id = 112280004,
    name = "灯笼滚出老远，灯芯浸了雪，怎么点也点不着。"
  },
  [112280005] = {
    id = 112280005,
    name = "呜......好冷！"
  },
  [112280006] = {
    id = 112280006,
    name = "别灭......拜托了，别灭。岁火要是灭了，我就死定了......"
  },
  [112280007] = {
    id = 112280007,
    name = "她急得直跺脚，雪沫溅上裙摆，却怎么也不敢让火苗熄掉。"
  },
  [112280008] = {
    id = 112280008,
    name = "少年主角恰好路过，蹲下来，替她拢住风口。"
  },
  [112280009] = {
    id = 112280009,
    name = "让我来帮你吧？"
  },
  [112280010] = {
    id = 112280010,
    name = "他蹲下身，从怀里取出余烬瓶，倒出一簇跳动的火苗。"
  },
  [112280011] = {
    id = 112280011,
    name = "少年用魔法烘干灯芯，水汽一缕缕地散开，火苗渐渐旺了起来。"
  },
  [112280012] = {
    id = 112280012,
    name = "你的灯芯很弱，要注入魔法烘干才行。"
  },
  [112280013] = {
    id = 112280013,
    name = "余烬瓶......这是探险者的东西？"
  },
  [112280014] = {
    id = 112280014,
    name = "路过。听说这里的岁火很好看，来看一眼。"
  },
  [112280015] = {
    id = 112280015,
    name = "我们这里的人都说，岁火要是能燃过整个冬天，新的一年就会很好很好。"
  },
  [112280016] = {
    id = 112280016,
    name = "远行的人要在这里许愿，归家的人也要在这里点灯。"
  },
  [112280017] = {
    id = 112280017,
    name = "所以岁火对你们来说，是这么要紧的东西？"
  },
  [112280018] = {
    id = 112280018,
    name = "嗯。我们家世代守着这岁火，一辈辈传下来，从没让它灭过。"
  },
  [112280019] = {
    id = 112280019,
    name = "那......你许了什么愿望呢？"
  },
  [112280020] = {
    id = 112280020,
    name = "我......我不知道该许什么愿。"
  },
  [112280021] = {
    id = 112280021,
    name = "我从小就在这里，看着人们来来往往，把愿望交给火。可我自己，好像没有愿望。"
  },
  [112280022] = {
    id = 112280022,
    name = "没有愿望，也不算坏事。"
  },
  [112280023] = {
    id = 112280023,
    name = "你正好可以替岁火，多看看世界。"
  },
  [112280024] = {
    id = 112280024,
    name = "看世界？"
  },
  [112280025] = {
    id = 112280025,
    name = "世界上还有各种各样的灯和火。海边的灯塔、雪原的篝火、深渊边发光的苔藓......"
  },
  [112280026] = {
    id = 112280026,
    name = "那......外面的灯，好看吗？"
  },
  [112280027] = {
    id = 112280027,
    name = "很好看。如果你看过了，再讲给我听——我还没见过那么多灯呢。"
  },
  [112280028] = {
    id = 112280028,
    name = "少年侧过头，看着她，眼里的光比雪还要亮。"
  },
  [112280029] = {
    id = 112280029,
    name = "那些话落进雪里，却在她心里生了根。"
  },
  [112280030] = {
    id = 112280030,
    name = "（世界之外......还有各种各样的灯与火。）"
  },
  [112280031] = {
    id = 112280031,
    name = "火苗在她眼底跳动，她把这句话，偷偷念了一遍又一遍。"
  },
  [112280032] = {
    id = 112280032,
    name = "你叫什么名字？"
  },
  [112280033] = {
    id = 112280033,
    name = "露西亚。你呢？"
  },
  [112280034] = {
    id = 112280034,
    name = "我啊......等我们再相遇的时候，我再告诉你。"
  },
  [112280035] = {
    id = 112280035,
    name = "那......到了那时候，你一定要告诉我！"
  },
  [112280036] = {
    id = 112280036,
    name = "说好了。"
  },
  [112280037] = {
    id = 112280037,
    name = "（遇见的时候......会有那一天的。）"
  },
  [112280038] = {
    id = 112280038,
    name = "少年朝她挥挥手，走进风雪里。"
  },
  [112280039] = {
    id = 112280039,
    name = "第二天清早，少年走了。露西亚站在岁火边，望着他远去的背影，很久很久。"
  },
  [112280040] = {
    id = 112280040,
    name = "雪落在她肩头，她也没有拂去。"
  },
  [112280041] = {
    id = 112280041,
    name = "风卷起她的裙角，她对着那道背影，轻轻说了句「一定」。"
  },
  [112280042] = {
    id = 112280042,
    name = "（说好了......那我，也要有愿望才行。）"
  },
  [112280043] = {
    id = 112280043,
    name = "那年之后，露西亚开始研究承载愿望的术式。"
  },
  [112280044] = {
    id = 112280044,
    name = "她想知道，为什么人们愿意把心愿托给一团火。"
  },
  [112280045] = {
    id = 112280045,
    name = "她把那晚的话，连同那簇火苗，一起收进了心底。"
  },
  [112280046] = {
    id = 112280046,
    name = "火最不会说谎。许过的愿，它都记得。"
  },
  [112280047] = {
    id = 112280047,
    name = "我守着火，火守着大家的愿望。那我的愿望......就让灯替我记得吧。"
  },
  [112280048] = {
    id = 112280048,
    name = "露西亚守着岁火，看着人们一年一年把心愿挂上来，又一年一年点灯回家。"
  },
  [112280049] = {
    id = 112280049,
    name = "（我也想......有一天能被谁记着。）"
  },
  [112280050] = {
    id = 112280050,
    name = "她记着那句「出去看看」，也记着那个再相遇的约定。"
  },
  [112280051] = {
    id = 112280051,
    name = "很多年后，她终于收拾好行囊，踏上了看灯的路。"
  },
  [112280052] = {
    id = 112280052,
    name = "第一站是海边的渔港，然后是雪原的营地、地下城的遗迹......"
  },
  [112280053] = {
    id = 112280053,
    name = "她看过沙漠的星火、海上的灯塔、雪原的篝火，还有深渊边缘发光的苔藓。"
  },
  [112280054] = {
    id = 112280054,
    name = "每看见一盏灯，她都在心里记一笔，怕讲的时候漏了。"
  },
  [112280055] = {
    id = 112280055,
    name = "那些灯，她真的走遍大陆，一盏一盏地看过了。"
  },
  [112280056] = {
    id = 112280056,
    name = "后来她明白了——火不会忘记。灯亮着，愿望就有人记着。"
  },
  [112280057] = {
    id = 112280057,
    name = "而那个少年说过的话，也被她当成一盏灯，一直亮在心里。"
  },
  [112280058] = {
    id = 112280058,
    name = "她轻声说。"
  },
  [112280059] = {
    id = 112280059,
    name = "我好像......也学会许愿了。"
  },
  [112280060] = {
    id = 112280060,
    name = "多年以后，炉火镇的岁火祭将近。酒馆里比平日热闹，墙上挂满了新扎的灯笼。"
  },
  [112280061] = {
    id = 112280061,
    name = "今年雪来得早，街上的灯挂得整整齐齐，像是等谁归来。"
  },
  [112280062] = {
    id = 112280062,
    name = "你独自走进酒馆，在角落的桌边坐下。公会委托栏前，几个同行者正围着议论。"
  },
  [112280063] = {
    id = 112280063,
    name = "年轻的探险者，你也是为岁火祭来的？"
  },
  [112280064] = {
    id = 112280064,
    name = "今年可赶上了——灯油断了货，这几夜浊炁又不安静，公会这才发了委托。"
  },
  [112280065] = {
    id = 112280065,
    name = "灯油断了货？那岁火祭怎么办？"
  },
  [112280066] = {
    id = 112280066,
    name = "往年都是莫里斯提前备好的。今年他病倒了，谁也没想起这茬。"
  },
  [112280067] = {
    id = 112280067,
    name = "莫里斯？是那位守火的老先生吗？"
  },
  [112280068] = {
    id = 112280068,
    name = "可不是嘛。全镇的老老少少，都认得他。"
  },
  [112280069] = {
    id = 112280069,
    name = "一位守了岁火一辈子的老人。年轻时也是探险者，后来不知为什么，就守着这座城不走了。"
  },
  [112280070] = {
    id = 112280070,
    name = "探险者？那他怎么又回来守火了？"
  },
  [112280071] = {
    id = 112280071,
    name = "谁知道呢。有人说是等人，有人说是还愿。反正在他眼里，岁火比命还重。"
  },
  [112280072] = {
    id = 112280072,
    name = "能等这么多年，一定是对他很重要的约定吧？"
  },
  [112280073] = {
    id = 112280073,
    name = "这就说不清了。几十年前的事，镇上老人都讳莫如深。"
  },
  [112280074] = {
    id = 112280074,
    name = "他压低声音。"
  },
  [112280075] = {
    id = 112280075,
    name = "听说啊，他等的，是一个答应过他会回来的人。"
  },
  [112280076] = {
    id = 112280076,
    name = "等金银财宝多好，等什么人啊！"
  },
  [112280077] = {
    id = 112280077,
    name = "那人来过么？"
  },
  [112280078] = {
    id = 112280078,
    name = "没有。可莫里斯还是每年都备好灯油，像是笃定那人总有一天会踏进炉火镇。"
  },
  [112280079] = {
    id = 112280079,
    name = "那多半是等不到了吧。"
  },
  [112280080] = {
    id = 112280080,
    name = "可莫里斯不信。他说，那人答应过，就一定会来。"
  },
  [112280081] = {
    id = 112280081,
    name = "（一年又一年，守着同一个愿望......）"
  },
  [112280082] = {
    id = 112280082,
    name = "他病的......很重吗？"
  },
  [112280083] = {
    id = 112280083,
    name = "说不上来。已经躺了些日子，总念叨「灯要灭了」。人倒是没什么大碍，灯却先怕起来了。"
  },
  [112280084] = {
    id = 112280084,
    name = "火盆里的炭火噼啪一声，蹦出几点火星。"
  },
  [112280085] = {
    id = 112280085,
    name = "就这点报酬？够跑一趟路费吗？还不如在据点躺着呢。"
  },
  [112280086] = {
    id = 112280086,
    name = "就是。再说要新年了，家里还等着呢。走了走了。"
  },
  [112280087] = {
    id = 112280087,
    name = "两个同行者摇摇头，转身离开酒馆。门帘晃了晃，冷风灌进来，又合上。"
  },
  [112280088] = {
    id = 112280088,
    name = "酒馆里一下子安静下来，只有火盆在响。"
  },
  [112280089] = {
    id = 112280089,
    name = "临近新年，果然没人肯接这活儿......"
  },
  [112280090] = {id = 112280090, name = "我接。"},
  [112280091] = {
    id = 112280091,
    name = "你站起身，走到委托栏前，撕下那张单子。"
  },
  [112280092] = {
    id = 112280092,
    name = "你？一个人？"
  },
  [112280093] = {
    id = 112280093,
    name = "嗯。一个人够了。"
  },
  [112280094] = {
    id = 112280094,
    name = "年轻的探险者，你有所不知——岁火祭前夜，浊炁会闹得最凶......"
  },
  [112280095] = {
    id = 112280095,
    name = "那就更要有人守着了。"
  },
  [112280096] = {
    id = 112280096,
    name = "他沉默片刻，给你倒了一杯酒。"
  },
  [112280097] = {
    id = 112280097,
    name = "......那就拜托你了。"
  },
  [112280098] = {
    id = 112280098,
    name = "我不认识那位守火人，但想去看看他。"
  },
  [112280099] = {
    id = 112280099,
    name = "他会高兴的。守火的人，最怕的就是火边没人。"
  },
  [112280100] = {
    id = 112280100,
    name = "你收起委托，目光越过窗棂，望向广场中央。"
  },
  [112280101] = {
    id = 112280101,
    name = "远远的，一团火光正静静燃着，像这座小城的眼睛。"
  },
  [112280102] = {
    id = 112280102,
    name = "雪又下起来了。你谢了老板请的酒，出门朝广场走去。"
  },
  [112280103] = {
    id = 112280103,
    name = "（不知为什么，这团火......好像在哪里见过。）"
  },
  [112280104] = {
    id = 112280104,
    name = "你走出几步，又回头望了一眼。"
  },
  [112280105] = {
    id = 112280105,
    name = "那团火光隔着风雪，安静地亮着，像是也在看你。"
  },
  [112280106] = {
    id = 112280106,
    name = "你裹紧斗篷，朝老守火人的住处走去。"
  },
  [112280107] = {
    id = 112280107,
    name = "巷子深处，一间屋子亮着昏黄的灯。"
  },
  [112280108] = {
    id = 112280108,
    name = "推开门，火炉边床上躺着一位白发老人，正对着炉火出神。"
  },
  [112280109] = {
    id = 112280109,
    name = "您就是莫里斯先生？"
  },
  [112280110] = {
    id = 112280110,
    name = "他没有回头，声音很轻的念叨着。"
  },
  [112280111] = {
    id = 112280111,
    name = "......灯油，灯油怎么办......"
  },
  [112280112] = {
    id = 112280112,
    name = "我是接了委托来的探险者。岁火祭的灯油，会有人备好的。"
  },
  [112280113] = {
    id = 112280113,
    name = "他慢慢转过头，浑浊的眼睛里亮了一下。"
  },
  [112280114] = {
    id = 112280114,
    name = "好......好。有人备，就好。"
  },
  [112280115] = {
    id = 112280115,
    name = "我老了，护不动了。这些年，每年都怕灯油不够......"
  },
  [112280116] = {
    id = 112280116,
    name = "您守着这团火这么多年，就没想过歇一歇吗？"
  },
  [112280117] = {
    id = 112280117,
    name = "他摇摇头，望着窗外的岁火。"
  },
  [112280118] = {
    id = 112280118,
    name = "歇不得。灯还亮着，就有人还等着它。"
  },
  [112280119] = {
    id = 112280119,
    name = "他说这话时，浑浊的眼底映着火光，像是藏着一个没说完的故事。"
  },
  [112280120] = {
    id = 112280120,
    name = "（等的人......就是老板说的那个人吗？）"
  },
  [112280121] = {
    id = 112280121,
    name = "你没有再问。只是替他把炉火拨旺了些。"
  },
  [112280122] = {
    id = 112280122,
    name = "年轻的探险者，岁火祭那夜，浊炁要是来了......守得住吗？"
  },
  [112280123] = {
    id = 112280123,
    name = "守得住。我会守住它。"
  },
  [112280124] = {
    id = 112280124,
    name = "他轻轻笑了。"
  },
  [112280125] = {
    id = 112280125,
    name = "好......那我就，放心了。"
  },
  [112280126] = {
    id = 112280126,
    name = "你走出莫里斯的屋子，雪已经停了。广场上的岁火，正安静地亮着。"
  },
  [112280127] = {
    id = 112280127,
    name = "次日入夜，炉火镇的新年灯市正热闹。"
  },
  [112280128] = {
    id = 112280128,
    name = "沿街挂满各式灯笼，摊贩的吆喝声此起彼伏，空气里飘着灯油和食物的香气。"
  },
  [112280129] = {
    id = 112280129,
    name = "孩子们举着各式小灯，在人群里钻来钻去。"
  },
  [112280130] = {
    id = 112280130,
    name = "你在灯市里穿行，采购岁火祭要用的灯油与火石。"
  },
  [112280131] = {
    id = 112280131,
    name = "你在一家灯油铺前停下，铺子门板上挂着一串旧灯笼。"
  },
  [112280132] = {
    id = 112280132,
    name = "你也是来帮忙的？今年灯油可紧俏，全镇的灯都指着这一炉油呢。"
  },
  [112280133] = {
    id = 112280133,
    name = "是。岁火祭要用，挑些好的灯油。"
  },
  [112280134] = {
    id = 112280134,
    name = "这些都是新熬的，火色正，烧得久。"
  },
  [112280135] = {
    id = 112280135,
    name = "全镇的灯油，都是在你这里采买的？"
  },
  [112280136] = {
    id = 112280136,
    name = "嘿嘿，那你可来对地方了。新灯要添油，旧灯要续油，岁火更是要拿最好的灯油喂着。"
  },
  [112280137] = {
    id = 112280137,
    name = "对了——你们见着那位「守灯人」了吗？"
  },
  [112280138] = {
    id = 112280138,
    name = "守灯人？这两天总听人提起。"
  },
  [112280139] = {
    id = 112280139,
    name = "老板朝街角抬了抬下巴，压低声音。"
  },
  [112280140] = {
    id = 112280140,
    name = "一个女法师，这两日总在街角看灯。有人问她看什么，她说——灯火是人们愿望的象征。"
  },
  [112280141] = {
    id = 112280141,
    name = "喏，她这会儿多半就在那儿看灯呢。"
  },
  [112280142] = {
    id = 112280142,
    name = "（愿望的象征......）"
  },
  [112280143] = {
    id = 112280143,
    name = "听说她也是为岁火祭来的，见镇里缺人手，便留下来搭了把手。这几日的灯油，都是她帮着添的。"
  },
  [112280144] = {
    id = 112280144,
    name = "新年夜愿意留下帮忙的人，不多了。"
  },
  [112280145] = {
    id = 112280145,
    name = "可不是。添灯的手艺，比镇上老人都利索。"
  },
  [112280146] = {
    id = 112280146,
    name = "关于愿望......她还说了什么？"
  },
  [112280147] = {
    id = 112280147,
    name = "她说，看灯火，就是在看这一城人的心。"
  },
  [112280148] = {
    id = 112280148,
    name = "看灯就是在看一城人的心......"
  },
  [112280149] = {
    id = 112280149,
    name = "我们炉火镇的人，都爱把心愿托给灯火。远行的、归家的、求个平安的......灯火亮着，愿就亮着。"
  },
  [112280150] = {
    id = 112280150,
    name = "灯火若灭了，心也就冷了。"
  },
  [112280151] = {
    id = 112280151,
    name = "怎么，你也信这个？"
  },
  [112280152] = {
    id = 112280152,
    name = "说不清。只是觉得......这句话，好像在哪里听过。"
  },
  [112280153] = {
    id = 112280153,
    name = "你握着灯油坛的手，微微一顿。"
  },
  [112280154] = {
    id = 112280154,
    name = "（灯是人们愿望的象征......这话，我好像在哪里听过。）"
  },
  [112280155] = {
    id = 112280155,
    name = "她看得出，哪盏灯在等人吗？"
  },
  [112280156] = {
    id = 112280156,
    name = "她说，人的心事，都写在灯火里。"
  },
  [112280157] = {
    id = 112280157,
    name = "远行的灯火要亮在门口，是盼人归；窗边的小灯，是夜里有人还在等。"
  },
  [112280158] = {
    id = 112280158,
    name = "还说，烧到尽头的灯火，是愿望已经实现了。"
  },
  [112280159] = {
    id = 112280159,
    name = "烧到尽头的灯火......愿望已经实现。"
  },
  [112280160] = {
    id = 112280160,
    name = "夜市的人声还在耳边，那句话却像针一样，轻轻扎了一下。"
  },
  [112280161] = {
    id = 112280161,
    name = "你们说，这看灯的人，心里得装着多少故事？"
  },
  [112280162] = {
    id = 112280162,
    name = "她......是本地人吗？"
  },
  [112280163] = {
    id = 112280163,
    name = "不是。听口音，是走南闯北来的。她说这一带是她最后一站了。"
  },
  [112280164] = {
    id = 112280164,
    name = "最后一站......"
  },
  [112280165] = {
    id = 112280165,
    name = "她要讲给谁听？"
  },
  [112280166] = {
    id = 112280166,
    name = "这我就不知道了。我总见她提着一盏旧提灯，灯罩上还有补过的痕迹。"
  },
  [112280167] = {
    id = 112280167,
    name = "（旧提灯......补过的痕迹。）"
  },
  [112280168] = {
    id = 112280168,
    name = "你付了灯油钱。老板找了零钱，几枚金币在掌心里叮当作响。"
  },
  [112280169] = {
    id = 112280169,
    name = "拎着灯油，你的脚步却慢了下来。"
  },
  [112280170] = {
    id = 112280170,
    name = "（最后一站......讲给一个人听。那该是，很重要的约定吧。）"
  },
  [112280171] = {
    id = 112280171,
    name = "你拎着灯油走在灯市里，一个念头若有若无地浮上来，又被热闹的人声冲散。"
  },
  [112280172] = {
    id = 112280172,
    name = "（守灯人......她到底是个什么样的人？）"
  },
  [112280173] = {
    id = 112280173,
    name = "灯市尽头，一片喧闹之外，好像有什么东西，安静地亮着。"
  },
  [112280174] = {
    id = 112280174,
    name = "（去看看好了。）"
  },
  [112280175] = {
    id = 112280175,
    name = "你拨开人群，朝那片安静的光走去。"
  },
  [112280176] = {
    id = 112280176,
    name = "越走越近，那点光也越发明亮——是一盏被仔细看护着的灯。"
  },
  [112280177] = {
    id = 112280177,
    name = "那是一盏普通的灯，却被添得满满的，火苗稳稳地亮着。"
  },
  [112280178] = {
    id = 112280178,
    name = "灯油的气息，混着雪后的清冷，一起漫过来。"
  },
  [112280179] = {
    id = 112280179,
    name = "那点亮光不偏不倚，正落在这条巷子的尽头。"
  },
  [112280180] = {
    id = 112280180,
    name = "（......就是这里了。）"
  },
  [112280181] = {
    id = 112280181,
    name = "灯下站着一个身影，正俯身拨着灯芯，动作轻得像是怕惊醒了什么。"
  },
  [112280182] = {
    id = 112280182,
    name = "那身影拢了拢斗篷，像是感应到什么，抬头朝这边望了一眼。"
  },
  [112280183] = {
    id = 112280183,
    name = "隔着满街的灯火，你们的目光，在夜色里碰了一下。"
  },
  [112280184] = {
    id = 112280184,
    name = "你怔了一下，心底那点熟悉感，又漫了上来。"
  },
  [112280185] = {
    id = 112280185,
    name = "倒数第二夜，广场中央，岁火熊熊。一名女法师站在火边，正将灯油缓缓添入灯盏。"
  },
  [112280186] = {
    id = 112280186,
    name = "她添油的动作很轻，像怕惊醒了什么。"
  },
  [112280187] = {
    id = 112280187,
    name = "小心些，油满了容易烧起来。"
  },
  [112280188] = {
    id = 112280188,
    name = "谢谢。你......就是那位守灯人？"
  },
  [112280189] = {
    id = 112280189,
    name = "这里的人，这么称呼我。我自己，更喜欢叫自己看火的人。"
  },
  [112280190] = {
    id = 112280190,
    name = "看火的人？"
  },
  [112280191] = {
    id = 112280191,
    name = "看火的人，就是替火守着心愿的人。我们家世代守着岁火，火在，愿就在。"
  },
  [112280192] = {
    id = 112280192,
    name = "你是本地人？"
  },
  [112280193] = {
    id = 112280193,
    name = "不是。路过。岁火祭缺人手，镇里请我留几天，帮忙照看岁火。"
  },
  [112280194] = {
    id = 112280194,
    name = "路过......却愿意留下来守一座城的火。"
  },
  [112280195] = {
    id = 112280195,
    name = "灯是人们愿望的象征。想看一个地方的人，就先看他们的灯。"
  },
  [112280196] = {
    id = 112280196,
    name = "那这座城的人，都在等什么？"
  },
  [112280197] = {
    id = 112280197,
    name = "远行的灯亮在门口，是盼人归；窗边的灯，是夜里有人还在等。"
  },
  [112280198] = {
    id = 112280198,
    name = "有没有一种灯，会一直亮着，不愿熄灭？"
  },
  [112280199] = {
    id = 112280199,
    name = "有啊。有的灯在等一个回不来的人，就会一直亮着，不肯灭。"
  },
  [112280200] = {
    id = 112280200,
    name = "她低头拨了拨灯芯，火苗跳了一下，映亮她低垂的眼睫。"
  },
  [112280201] = {
    id = 112280201,
    name = "你走了很多地方吧？看过很多灯火？"
  },
  [112280202] = {
    id = 112280202,
    name = "嗯。有人跟我说过，世界上还有各种各样的灯火，应该出来看看。"
  },
  [112280203] = {
    id = 112280203,
    name = "我看过很多地方的灯了。这里，是最后一站。"
  },
  [112280204] = {
    id = 112280204,
    name = "最后一站？"
  },
  [112280205] = {
    id = 112280205,
    name = "嗯。看完这一站的灯火，就该把看过的灯火，讲给那个人听了。"
  },
  [112280206] = {
    id = 112280206,
    name = "那个人......是和你约好了的人？"
  },
  [112280207] = {
    id = 112280207,
    name = "她的目光落在火苗上，声音很轻。"
  },
  [112280208] = {
    id = 112280208,
    name = "是。我们说好了的。"
  },
  [112280209] = {
    id = 112280209,
    name = "他......也在等你吗？"
  },
  [112280210] = {
    id = 112280210,
    name = "不知道。可我等了很多年，总要在个好日子里，把故事讲完。"
  },
  [112280211] = {
    id = 112280211,
    name = "她说这话时，声音比岁火还要稳。"
  },
  [112280212] = {
    id = 112280212,
    name = "（等了很多年......就为了讲一个故事。）"
  },
  [112280213] = {
    id = 112280213,
    name = "你呢？为什么来炉火镇？"
  },
  [112280214] = {
    id = 112280214,
    name = "公会委托——护送灯油，守护岁火祭。"
  },
  [112280215] = {
    id = 112280215,
    name = "守护岁火祭......听上去，像是替一座城守着心愿。"
  },
  [112280216] = {
    id = 112280216,
    name = "守着心愿......这话，倒是第一次听人这么说。"
  },
  [112280217] = {
    id = 112280217,
    name = "那正好。你守岁火，我看灯火，目的一样，算半个搭档了。"
  },
  [112280218] = {
    id = 112280218,
    name = "算是......半个搭档？"
  },
  [112280219] = {
    id = 112280219,
    name = "另外半个，得等岁火祭过后才算数。搭档嘛，总要一起扛过点事。"
  },
  [112280220] = {
    id = 112280220,
    name = "她冲你笑了一下，转身继续添灯油。火光在她眼底跳跃，她的睫毛上落了一点金。"
  },
  [112280221] = {
    id = 112280221,
    name = "你走了那么多地方，为什么最后一盏灯火，留在炉火镇？"
  },
  [112280222] = {
    id = 112280222,
    name = "因为有人告诉过我，最好的灯火，要留到重逢的时候再看。"
  },
  [112280223] = {
    id = 112280223,
    name = "最好的灯火，是什么样子的？"
  },
  [112280224] = {
    id = 112280224,
    name = "最好的灯火啊......是让人一看，就想回家的那种。"
  },
  [112280225] = {
    id = 112280225,
    name = "重逢......是很久以后的事吧？"
  },
  [112280226] = {
    id = 112280226,
    name = "说不好。灯火亮着，就总能等到。"
  },
  [112280227] = {
    id = 112280227,
    name = "要是......一直等不到呢？"
  },
  [112280228] = {
    id = 112280228,
    name = "等不到，就继续看灯火。看多了，也就不觉得日子长。"
  },
  [112280229] = {
    id = 112280229,
    name = "她说完，又添了一勺灯油，动作没有一丝迟疑。"
  },
  [112280230] = {
    id = 112280230,
    name = "那盏灯......灯油还够吗？"
  },
  [112280231] = {
    id = 112280231,
    name = "够的。我走一路，添一路，从来没让它灭过。"
  },
  [112280232] = {
    id = 112280232,
    name = "你说的那盏灯，是什么样的灯？"
  },
  [112280233] = {
    id = 112280233,
    name = "是一盏旧提灯。灯罩上补过几道，却擦得很亮。"
  },
  [112280234] = {
    id = 112280234,
    name = "它跟了我很多年，替我记着每一站看过的灯。"
  },
  [112280235] = {
    id = 112280235,
    name = "（旧提灯......补过的灯罩。）"
  },
  [112280236] = {
    id = 112280236,
    name = "你说不清为什么，心口莫名跳了一下。"
  },
  [112280237] = {
    id = 112280237,
    name = "她看了一眼天色。"
  },
  [112280238] = {
    id = 112280238,
    name = "该回去了，明早还要添灯油。"
  },
  [112280239] = {
    id = 112280239,
    name = "她顿了顿，又补了一句。"
  },
  [112280240] = {
    id = 112280240,
    name = "后夜，全城的灯都会点起来。"
  },
  [112280241] = {
    id = 112280241,
    name = "广场上的岁火，正安静地烧着。"
  },
  [112280242] = {
    id = 112280242,
    name = "后天......就是岁火祭了。"
  },
  [112280243] = {
    id = 112280243,
    name = "露西亚没有回头，声音里带着一点期待"
  },
  [112280244] = {
    id = 112280244,
    name = "岁火祭，你会来吧？"
  },
  [112280245] = {id = 112280245, name = "会。"},
  [112280246] = {
    id = 112280246,
    name = "她提着灯，走进灯影里。那点光一晃一晃，像是随时会被夜色带走。"
  },
  [112280247] = {
    id = 112280247,
    name = "你站在原地，莫名觉得这一幕有些眼熟，却想不起在哪里见过。"
  },
  [112280248] = {
    id = 112280248,
    name = "（好像很多年前......也有谁，这样提着一盏灯站在雪里。）"
  },
  [112280249] = {
    id = 112280249,
    name = "只有胸口那一点若有若无的悸动，提醒你——你大概忘了什么重要的事。"
  },
  [112280250] = {
    id = 112280250,
    name = "那一瞬间，你仿佛看见许多年前，雪夜里那个站在岁火边的身影。"
  },
  [112280251] = {
    id = 112280251,
    name = "倒数第二夜，入夜后，岁火忽然明灭不定，火苗压得极低，仿佛被什么东西按住了头。"
  },
  [112280252] = {
    id = 112280252,
    name = "夜风呜咽着刮过广场，卷起地上的雪沫。"
  },
  [112280253] = {
    id = 112280253,
    name = "围观的镇民陆续散去，一边走一边嘀咕。露西亚仍站在火前，一动不动。"
  },
  [112280254] = {
    id = 112280254,
    name = "她的目光始终没有离开火苗，手指在袖口里轻轻攥紧。"
  },
  [112280255] = {
    id = 112280255,
    name = "她拢火的手指收紧了些，指节微微泛白。"
  },
  [112280256] = {
    id = 112280256,
    name = "怪了，这火怎么越烧越矮？是不是灯油掺了水？"
  },
  [112280257] = {
    id = 112280257,
    name = "别乱说，岁火是咱们镇的命根子，谁舍得掺水？"
  },
  [112280258] = {
    id = 112280258,
    name = "那你说，好端端的，它怎么就矮了？"
  },
  [112280259] = {
    id = 112280259,
    name = "你走到露西亚身边，低声问。"
  },
  [112280260] = {
    id = 112280260,
    name = "岁火怎么了？"
  },
  [112280261] = {
    id = 112280261,
    name = "你看，它的火色，比昨天又淡了些。"
  },
  [112280262] = {
    id = 112280262,
    name = "它......在变弱。不是怕火，是怕有东西盯上它了。"
  },
  [112280263] = {
    id = 112280263,
    name = "害怕？什么东西会让火害怕？"
  },
  [112280264] = {
    id = 112280264,
    name = "我照看了几天火，火色一天比一天淡。今夜巡灯，有七盏灯的愿望被取走了。"
  },
  [112280265] = {
    id = 112280265,
    name = "七盏灯？"
  },
  [112280266] = {
    id = 112280266,
    name = "嗯。都是沿湖那一带的老灯，挂了很多年的那种。"
  },
  [112280267] = {
    id = 112280267,
    name = "取走愿望？"
  },
  [112280268] = {
    id = 112280268,
    name = "嗯。火是靠愿望活着的。灯里的愿望少一分，火就弱一分。"
  },
  [112280269] = {
    id = 112280269,
    name = "什么东西会做这种事？"
  },
  [112280270] = {
    id = 112280270,
    name = "取走愿望的浊炁，靠吞噬愿望活着。越吃愿望，就越强。"
  },
  [112280271] = {
    id = 112280271,
    name = "那被取走的愿望，还能找回来吗？"
  },
  [112280272] = {
    id = 112280272,
    name = "只要它还没被吞干净，就还能回来。"
  },
  [112280273] = {
    id = 112280273,
    name = "她望着远处一盏忽明忽暗的灯，眼神沉了沉。"
  },
  [112280274] = {
    id = 112280274,
    name = "一阵风过，岁火猛地一缩。露西亚伸手拢住火苗，指尖轻轻颤了一下。"
  },
  [112280275] = {
    id = 112280275,
    name = "你......还好吗？"
  },
  [112280276] = {
    id = 112280276,
    name = "我没事。只是岁火是炉火镇的心——它要是灭了，明年这一整座城的灯，都会暗下去。"
  },
  [112280277] = {
    id = 112280277,
    name = "那......我们要怎么把愿望找回来？"
  },
  [112280278] = {
    id = 112280278,
    name = "岁火祭那天，全城的灯都会点起来。灯越多，光越盛——被偷走的愿望，会循着光自己回家。"
  },
  [112280279] = {
    id = 112280279,
    name = "也就是说，只要那一夜灯都亮着，愿望就能回来？"
  },
  [112280280] = {
    id = 112280280,
    name = "露西亚微微点头，声音很轻"
  },
  [112280281] = {
    id = 112280281,
    name = "嗯。所以那一夜，一盏灯都不能灭。"
  },
  [112280282] = {
    id = 112280282,
    name = "那我今晚就开始巡灯。"
  },
  [112280283] = {
    id = 112280283,
    name = "不急。先把灯油备足，后夜才是关口。"
  },
  [112280284] = {
    id = 112280284,
    name = "她说这话时，语气很重。火光映着她的侧脸，明明灭灭。"
  },
  [112280285] = {
    id = 112280285,
    name = "我留下和你一起。公会委托本来就是守护岁火祭——也算我一个。"
  },
  [112280286] = {
    id = 112280286,
    name = "......好。那明夜，我们一起。"
  },
  [112280287] = {
    id = 112280287,
    name = "她顿了顿，放轻了声音。"
  },
  [112280288] = {
    id = 112280288,
    name = "......谢谢。"
  },
  [112280289] = {
    id = 112280289,
    name = "她的道谢很短，分量确很重。"
  },
  [112280290] = {
    id = 112280290,
    name = "被偷走愿望的人，会变成什么样？"
  },
  [112280291] = {
    id = 112280291,
    name = "他们只是觉得——「好像没那么期待新年了」。"
  },
  [112280292] = {
    id = 112280292,
    name = "时间久了，不只是新年......所有的事，对他们来说都会变得没有意义。"
  },
  [112280293] = {
    id = 112280293,
    name = "她说完这句，沉默了很久。火光在她脸上明明灭灭。"
  },
  [112280294] = {
    id = 112280294,
    name = "你思考着她的话，忽然明白了什么。"
  },
  [112280295] = {
    id = 112280295,
    name = "被偷走的，其实不是愿望本身。"
  },
  [112280296] = {
    id = 112280296,
    name = "是期待。是对所有东西的期待。"
  },
  [112280297] = {
    id = 112280297,
    name = "露西亚怔了一下，随即抬眼，眼中重新亮起光。"
  },
  [112280298] = {
    id = 112280298,
    name = "对啊......就是对所有事情的期待。"
  },
  [112280299] = {
    id = 112280299,
    name = "所以浊炁吞的，不只是火里的愿望——还有人们心里那些「想等到、想盼到」的东西。"
  },
  [112280300] = {
    id = 112280300,
    name = "嗯。它吞掉期待，人就不会再盼了。可只要灯还亮着，盼就还在。"
  },
  [112280301] = {
    id = 112280301,
    name = "那今晚，我们做些什么？"
  },
  [112280302] = {
    id = 112280302,
    name = "睡觉。养足精神——明夜，可能要守一整夜。"
  },
  [112280303] = {id = 112280303, name = "好。"},
  [112280304] = {
    id = 112280304,
    name = "她抬手，拢了拢被风掀起的发丝，眼底的火光渐渐稳下来。"
  },
  [112280305] = {
    id = 112280305,
    name = "后夜岁火祭，它一定会来。我们要做的，就是让全城的灯，一盏都不灭。"
  },
  [112280306] = {
    id = 112280306,
    name = "嗯。一盏都不灭。"
  },
  [112280307] = {
    id = 112280307,
    name = "夜深了。广场上只剩下岁火的光，和两个并肩而立的人影。"
  },
  [112280308] = {
    id = 112280308,
    name = "风更紧了。远处的黑雾，正悄无声息地，朝炉火镇靠近。"
  },
  [112280309] = {
    id = 112280309,
    name = "露西亚走回屋前，回头看了你一眼。"
  },
  [112280310] = {
    id = 112280310,
    name = "岁火祭见。"
  },
  [112280311] = {
    id = 112280311,
    name = "你望着她的背影，把那一点灯火，记进了心里。"
  },
  [112280312] = {
    id = 112280312,
    name = "当天深夜，你还是不放心岁火的情况，起身决定去看看。"
  },
  [112280313] = {
    id = 112280313,
    name = "你循着一点灯火走过街巷，看见露西亚站在一盏旧灯前。"
  },
  [112280314] = {
    id = 112280314,
    name = "夜已经很深了，巷子里静得能听见雪落的声音。"
  },
  [112280315] = {
    id = 112280315,
    name = "炉火镇的年夜，家家户户都亮着灯，只有这条巷子，安静得不像话。"
  },
  [112280316] = {
    id = 112280316,
    name = "她提着那盏旧提灯，灯罩上有几道修补过的痕迹，却擦得很亮。"
  },
  [112280317] = {
    id = 112280317,
    name = "她看着灯，像是在和谁说话。"
  },
  [112280318] = {
    id = 112280318,
    name = "最后一站了。看完这一站的灯，就......都该讲给他听了。"
  },
  [112280319] = {
    id = 112280319,
    name = "没想到这一走就走了这么久啊。"
  },
  [112280320] = {
    id = 112280320,
    name = "她低着头，仿佛那盏灯能听懂她说话。"
  },
  [112280321] = {
    id = 112280321,
    name = "露西亚？"
  },
  [112280322] = {
    id = 112280322,
    name = "......是你？还没睡？"
  },
  [112280323] = {
    id = 112280323,
    name = "睡不着。出来看看灯。"
  },
  [112280324] = {
    id = 112280324,
    name = "深夜看灯，是怕它灭了？"
  },
  [112280325] = {
    id = 112280325,
    name = "嗯。岁火祭前，每一盏灯都要看一遍才放心。"
  },
  [112280326] = {
    id = 112280326,
    name = "你的灯——很好看。"
  },
  [112280327] = {
    id = 112280327,
    name = "它跟了我很多年了，灯罩都磨旧了。"
  },
  [112280328] = {
    id = 112280328,
    name = "长辈说，每一任守护岁火的人，都提着它，检查新年前的每一盏灯。"
  },
  [112280329] = {
    id = 112280329,
    name = "那这盏灯，陪你走了多远？"
  },
  [112280330] = {
    id = 112280330,
    name = "从第一站开始。沙漠、海边、雪原......它都跟着。"
  },
  [112280331] = {
    id = 112280331,
    name = "守护岁火的人......都会提着它吗？"
  },
  [112280332] = {
    id = 112280332,
    name = "嗯。我家，从祖辈起就守着岁火。"
  },
  [112280333] = {
    id = 112280333,
    name = "我小时候还差点让装着火种的灯灭掉，那时我魔法不足，急得直哭。"
  },
  [112280334] = {
    id = 112280334,
    name = "后来呢？"
  },
  [112280335] = {
    id = 112280335,
    name = "那年我们镇的岁火差点变暗，全城的人拿出自家的灯火，一盏一盏聚在一起，才把它重新点亮。"
  },
  [112280336] = {
    id = 112280336,
    name = "她说着，眼底映着火光，像是又看见了那一年。"
  },
  [112280337] = {
    id = 112280337,
    name = "全城的灯火？"
  },
  [112280338] = {
    id = 112280338,
    name = "嗯。从那以后，我就再没觉得岁火是「我们家」的火了。"
  },
  [112280339] = {
    id = 112280339,
    name = "岁火不是靠哪一个人守着的，是靠着所有人的愿望燃烧着。"
  },
  [112280340] = {
    id = 112280340,
    name = "所以，你才走了那么多地方，看那么多灯火？"
  },
  [112280341] = {
    id = 112280341,
    name = "我也想知道，别处的灯火，都是什么样。"
  },
  [112280342] = {
    id = 112280342,
    name = "她抬眼看你，眼神里有种说不清的东西，像走了很远的路，终于望见了灯火。"
  },
  [112280343] = {
    id = 112280343,
    name = "她没有立刻回答，只是抬手，轻轻拂过灯罩上的一道旧痕。"
  },
  [112280344] = {
    id = 112280344,
    name = "走遍世界后我才知道，真正让火燃着的，从来不只是火气。"
  },
  [112280345] = {
    id = 112280345,
    name = "是愿望。是一个个愿意把心愿托给灯火的人。"
  },
  [112280346] = {
    id = 112280346,
    name = "所以你想看看，别的地方的灯火，都是怎么亮着的？"
  },
  [112280347] = {
    id = 112280347,
    name = "嗯。看多了，才知道一座城的灯火，有多要紧。"
  },
  [112280348] = {
    id = 112280348,
    name = "雪落在她肩头，她没有拂，任由那点白悄悄化开。"
  },
  [112280349] = {
    id = 112280349,
    name = "后夜岁火祭，我们一定能让岁火燃的更旺些吧？"
  },
  [112280350] = {
    id = 112280350,
    name = "她握紧提灯，声音很轻。"
  },
  [112280351] = {
    id = 112280351,
    name = "一定会的。"
  },
  [112280352] = {
    id = 112280352,
    name = "你看着她紧握的手——她是在担心，吃愿望的浊炁会再来。"
  },
  [112280353] = {
    id = 112280353,
    name = "我会和你一起守护这里的岁火，说好了。"
  },
  [112280354] = {
    id = 112280354,
    name = "露西亚抬起头，目光亮了一下"
  },
  [112280355] = {id = 112280355, name = "嗯。"},
  [112280356] = {
    id = 112280356,
    name = "说好了。"
  },
  [112280357] = {
    id = 112280357,
    name = "她说「说好了」三个字的时候，声音轻轻颤了一下。旧提灯里的火光，也跟着晃了晃。"
  },
  [112280358] = {
    id = 112280358,
    name = "雪光映着檐角的冰棱，一闪一闪的。"
  },
  [112280359] = {
    id = 112280359,
    name = "你看着她，忽然觉得，这句话像是早就听过。"
  },
  [112280360] = {
    id = 112280360,
    name = "（说好了......我好像，也跟谁说过这三个字。）"
  },
  [112280361] = {
    id = 112280361,
    name = "长辈说，守护岁火的人，要拼尽一切守护任何愿望之火——要让人的希望和期待，一直传承下去。"
  },
  [112280362] = {
    id = 112280362,
    name = "那这次，我们一起守。"
  },
  [112280363] = {
    id = 112280363,
    name = "好。守护岁火，守护希望和期待。"
  },
  [112280364] = {
    id = 112280364,
    name = "后夜，全城的灯都会亮起来。"
  },
  [112280365] = {
    id = 112280365,
    name = "嗯。到时候，你就能看见整座城的心愿了。"
  },
  [112280366] = {
    id = 112280366,
    name = "她说这话时，语气里没有一丝犹疑，像是真的已经看见明天。"
  },
  [112280367] = {
    id = 112280367,
    name = "岁火祭见。"
  },
  [112280368] = {
    id = 112280368,
    name = "你望着她走远的背影，夜风里飘着灯油的气息。"
  },
  [112280369] = {
    id = 112280369,
    name = "（那点说不清的熟悉感......又悄悄漫了上来。）"
  },
  [112280370] = {
    id = 112280370,
    name = "你回到住处，推开窗，广场上的岁火还在烧。"
  },
  [112280371] = {
    id = 112280371,
    name = "那点火光隔着风雪，安安静静，像是认出了谁。"
  },
  [112280372] = {
    id = 112280372,
    name = "远处，岁火的光在夜色里轻轻摇曳，像是在等一个约定。"
  },
  [112290001] = {
    id = 112290001,
    name = "菲尼斯因为公会的事情需要在据点和你们暂时分开，大家商议后决定先前往下一个地点稍作停留，等待菲尼斯赶上后再一起出发。"
  },
  [112290002] = {
    id = 112290002,
    name = "下一站往铃穗镇方向走，路上还能再接一趟顺路的活。"
  },
  [112290003] = {
    id = 112290003,
    name = "那就挑个钱多的、又不累的——小莎的标准就这么简单。"
  },
  [112290004] = {
    id = 112290004,
    name = "听说那边正在办庆典哦！"
  },
  [112290005] = {
    id = 112290005,
    name = "清晨的据点，委托板前已经挤满了人。"
  },
  [112290006] = {
    id = 112290006,
    name = "木牌一层压着一层，像鱼鳞似的挂满了整面墙。"
  },
  [112290007] = {
    id = 112290007,
    name = "好多啊......看得小莎眼睛都花了。"
  },
  [112290008] = {
    id = 112290008,
    name = "挑委托要挑顺眼的嘛！"
  },
  [112290009] = {
    id = 112290009,
    name = "......应该挑内容合适的。"
  },
  [112290010] = {
    id = 112290010,
    name = "真是假正经。"
  },
  [112290011] = {
    id = 112290011,
    name = "这跟正不正经没关系。"
  },
  [112290012] = {
    id = 112290012,
    name = "大清早就这么有活力。"
  },
  [112290013] = {
    id = 112290013,
    name = "两人同时把脸别了过去。"
  },
  [112290014] = {
    id = 112290014,
    name = "尼莉莎踮起脚，在委托板上翻找起来。"
  },
  [112290015] = {
    id = 112290015,
    name = "护送商队......不行，太远。清理魔物......不行，太累。"
  },
  [112290016] = {
    id = 112290016,
    name = "你已经否掉第十七张了。"
  },
  [112290017] = {
    id = 112290017,
    name = "你挑的全是不用干活的。"
  },
  [112290018] = {
    id = 112290018,
    name = "你懂什么，小莎这叫性价比高选择法。"
  },
  [112290019] = {
    id = 112290019,
    name = "这时，最上层的一张委托单被风吹起了一角。"
  },
  [112290020] = {
    id = 112290020,
    name = "嗯？「铃穗镇 · 庆典护卫」......"
  },
  [112290021] = {
    id = 112290021,
    name = "庆典诶！听着就很好玩！"
  },
  [112290022] = {
    id = 112290022,
    name = "庆典意味着人多，人多意味着秩序难维持。"
  },
  [112290023] = {
    id = 112290023,
    name = "喂，你先看看报酬。"
  },
  [112290024] = {
    id = 112290024,
    name = "尼莉莎把委托单举到眼前，眼睛一点点睁大。"
  },
  [112290025] = {
    id = 112290025,
    name = "这个数字......是不是多写了一个零啊？"
  },
  [112290026] = {
    id = 112290026,
    name = "让我看看......确实没多写。"
  },
  [112290027] = {
    id = 112290027,
    name = "报酬高，通常意味着麻烦也大。"
  },
  [112290028] = {
    id = 112290028,
    name = "「包食宿」——食宿全包还有钱拿，这不就是白捡的吗？"
  },
  [112290029] = {
    id = 112290029,
    name = "先看看工作内容。"
  },
  [112290030] = {
    id = 112290030,
    name = "她把纸举得老高，目光却死死钉在报酬那一栏。"
  },
  [112290031] = {
    id = 112290031,
    name = "你根本没看。"
  },
  [112290032] = {
    id = 112290032,
    name = "小莎看了！"
  },
  [112290033] = {
    id = 112290033,
    name = "那你念出来。"
  },
  [112290034] = {
    id = 112290034,
    name = "......念什么？"
  },
  [112290035] = {
    id = 112290035,
    name = "我们没注意到的信息。"
  },
  [112290036] = {
    id = 112290036,
    name = "尼莉莎不情不愿地把视线往下挪了两行。"
  },
  [112290037] = {
    id = 112290037,
    name = "「协助维持庆典秩序」......看吧，就是站岗。"
  },
  [112290038] = {
    id = 112290038,
    name = "后面还有字。"
  },
  [112290039] = {
    id = 112290039,
    name = "字太小了，看不清。"
  },
  [112290040] = {
    id = 112290040,
    name = "我念。「必要时，配合庆典演出。」"
  },
  [112290041] = {
    id = 112290041,
    name = "空气安静了一瞬。"
  },
  [112290042] = {
    id = 112290042,
    name = "配合演出？"
  },
  [112290043] = {
    id = 112290043,
    name = "诶——！听起来好像很有意思！"
  },
  [112290044] = {
    id = 112290044,
    name = "应该就是简单走过场的活，毕竟我们还要当护卫嘛~"
  },
  [112290045] = {
    id = 112290045,
    name = "你确定要接？"
  },
  [112290046] = {
    id = 112290046,
    name = "报酬这么高，不接白不接。"
  },
  [112290047] = {
    id = 112290047,
    name = "她一把摘下委托单，在签名处刷刷写下名字。"
  },
  [112290048] = {
    id = 112290048,
    name = "哦？这就签了？"
  },
  [112290049] = {
    id = 112290049,
    name = "不知何时，一位戴眼镜的中年人凑了过来。"
  },
  [112290050] = {
    id = 112290050,
    name = "铃穗镇庆典筹备会，我是兰伯特，委托是我发的。"
  },
  [112290051] = {
    id = 112290051,
    name = "请问演出是指——"
  },
  [112290052] = {
    id = 112290052,
    name = "啊，那个到时候再说，来得及。"
  },
  [112290053] = {
    id = 112290053,
    name = "对了，委托上写的可是两名护卫——一位弓手，一位能挡住人群的。"
  },
  [112290054] = {
    id = 112290054,
    name = "这不正好嘛！蒂娜，就当帮个忙嘛。"
  },
  [112290055] = {
    id = 112290055,
    name = "......我不擅长这种事。"
  },
  [112290056] = {
    id = 112290056,
    name = "就是嘛，蒂娜站着不动都像一堵墙。"
  },
  [112290057] = {
    id = 112290057,
    name = "小莎在夸你结实。"
  },
  [112290058] = {
    id = 112290058,
    name = "我不觉得这是夸奖。"
  },
  [112290059] = {
    id = 112290059,
    name = "那就两个人一起？"
  },
  [112290060] = {
    id = 112290060,
    name = "......明白了。只是这一次，请你把条款看清楚。"
  },
  [112290061] = {
    id = 112290061,
    name = "看啦看啦，小莎都记在心里了。"
  },
  [112290062] = {
    id = 112290062,
    name = "三分钟前你连上面写着什么都不知道。"
  },
  [112290063] = {
    id = 112290063,
    name = "好啦好啦，出发出发！"
  },
  [112290064] = {
    id = 112290064,
    name = "你们收好行装，在晨光里离开了据点。"
  },
  [112290065] = {
    id = 112290065,
    name = "那张签了名的委托单被塞进背包——没人注意到，背面印着一行极小的字。"
  },
  [112290066] = {
    id = 112290066,
    name = "「巡礼主题：小红帽与大灰狼」。"
  },
  [112290067] = {
    id = 112290067,
    name = "铃穗镇的入口挂满了铜铃，风一过，整条街都在轻轻地响。"
  },
  [112290068] = {
    id = 112290068,
    name = "屋檐下垂着麦穗编的帘子，摊子上摆满了刚出炉的糖饼。"
  },
  [112290069] = {
    id = 112290069,
    name = "......闻起来比委托单上写的好多了。"
  },
  [112290070] = {
    id = 112290070,
    name = "你又没看委托单。"
  },
  [112290071] = {
    id = 112290071,
    name = "先去找筹备会的人。"
  },
  [112290072] = {
    id = 112290072,
    name = "这边这边！可算把两位盼来了！"
  },
  [112290073] = {
    id = 112290073,
    name = "兰伯特先生？"
  },
  [112290074] = {
    id = 112290074,
    name = "对对，是我。来，先核对一下名单。"
  },
  [112290075] = {
    id = 112290075,
    name = "他从怀里掏出一本厚厚的册子，翻得哗哗响。"
  },
  [112290076] = {
    id = 112290076,
    name = "巡礼主演——尼莉莎小姐，还有蒂娜小姐。"
  },
  [112290077] = {
    id = 112290077,
    name = "......主演？"
  },
  [112290078] = {
    id = 112290078,
    name = "我想您可能搞错了，我们接的是护卫委托。"
  },
  [112290079] = {
    id = 112290079,
    name = "没搞错呀，您看，排练表上都排好了。"
  },
  [112290080] = {
    id = 112290080,
    name = "他把另一张纸摊开，密密麻麻的日程一直排到巡礼当天。"
  },
  [112290081] = {
    id = 112290081,
    name = "这、这上面为什么会有小莎的名字啊？"
  },
  [112290082] = {
    id = 112290082,
    name = "当然有呀，委托单上写了嘛。"
  },
  [112290083] = {
    id = 112290083,
    name = "请把委托单拿出来。"
  },
  [112290084] = {
    id = 112290084,
    name = "尼莉莎在背包里翻了半天，把那张皱巴巴的纸抽了出来。"
  },
  [112290085] = {
    id = 112290085,
    name = "......背面。"
  },
  [112290086] = {id = 112290086, name = "诶？"},
  [112290087] = {
    id = 112290087,
    name = "纸的背面，印着一行小小的字。"
  },
  [112290088] = {
    id = 112290088,
    name = "「巡礼主题：小红帽与大灰狼」......"
  },
  [112290089] = {
    id = 112290089,
    name = "这、这个......什么时候......"
  },
  [112290090] = {
    id = 112290090,
    name = "你签名的时候。"
  },
  [112290091] = {
    id = 112290091,
    name = "小莎不知道背面有字啊！"
  },
  [112290092] = {
    id = 112290092,
    name = "不过小莎，红斗篷说不定很适合你呢。"
  },
  [112290093] = {
    id = 112290093,
    name = "安妮斯！"
  },
  [112290094] = {
    id = 112290094,
    name = "所以，是要她们两个演？"
  },
  [112290095] = {
    id = 112290095,
    name = "对呀。镇上的巡礼年年都办，主演位一直最难定——今年好不容易请到两位正经的探险者。"
  },
  [112290096] = {
    id = 112290096,
    name = "为什么非得是探险者？"
  },
  [112290097] = {
    id = 112290097,
    name = "因为节目里有真射箭的环节呀——小红帽要射落挂在树上的彩铃"
  },
  [112290098] = {
    id = 112290098,
    name = "镇上没人拉得动那么硬的弓。"
  },
  [112290099] = {
    id = 112290099,
    name = "......小莎拉得动。"
  },
  [112290100] = {id = 112290100, name = "对嘛！"},
  [112290101] = {
    id = 112290101,
    name = "我不是在夸自己！"
  },
  [112290102] = {
    id = 112290102,
    name = "至于大灰狼——要接住孩子们一整轮的冲撞，得是个扛得住的，还要有亲和力的"
  },
  [112290103] = {
    id = 112290103,
    name = "......原来如此，所以你才说，一位弓手，一位能挡住人群的。"
  },
  [112290104] = {
    id = 112290104,
    name = "是呀，都说清楚了嘛。"
  },
  [112290105] = {
    id = 112290105,
    name = "哪里清楚了啊！那明明是在问护卫的事！"
  },
  [112290106] = {
    id = 112290106,
    name = "抱歉抱歉......不过小莎刚才的表情，真的好可爱哦。"
  },
  [112290107] = {
    id = 112290107,
    name = "安妮斯你再笑小莎就回去了！"
  },
  [112290108] = {
    id = 112290108,
    name = "那戏服呢？"
  },
  [112290109] = {
    id = 112290109,
    name = "早就做好了。"
  },
  [112290110] = {
    id = 112290110,
    name = "他拍了拍手，两个学徒捧着盖布的托盘走了过来。"
  },
  [112290111] = {
    id = 112290111,
    name = "尺寸是照两位报名时填的做的。"
  },
  [112290112] = {
    id = 112290112,
    name = "小莎什么时候填过尺寸啊！"
  },
  [112290113] = {
    id = 112290113,
    name = "......上个月在据点填过一次登记表，你也在场。"
  },
  [112290114] = {
    id = 112290114,
    name = "那个表不是领装备补助用的吗！"
  },
  [112290115] = {
    id = 112290115,
    name = "大概是同一张。"
  },
  [112290116] = {
    id = 112290116,
    name = "尼莉莎缓缓转过头，看向你。"
  },
  [112290117] = {
    id = 112290117,
    name = "队长，小莎现在跑还来得及吗？"
  },
  [112290118] = {
    id = 112290118,
    name = "签名是你自己签的。"
  },
  [112290119] = {
    id = 112290119,
    name = "可是——"
  },
  [112290120] = {
    id = 112290120,
    name = "报酬很高哦？"
  },
  [112290121] = {
    id = 112290121,
    name = "............好吧。小莎演就是了，但是说好了，只演游行那一天！"
  },
  [112290122] = {
    id = 112290122,
    name = "好好好，就一天。"
  },
  [112290123] = {
    id = 112290123,
    name = "他把托盘上的盖布一掀，上面红斗篷的一角从布下滑落，鲜艳得像一团火。"
  },
  [112290124] = {
    id = 112290124,
    name = "下面压着的黑斗篷和夜色一样神秘厚重。"
  },
  [112290125] = {
    id = 112290125,
    name = "......戏服也这么精致。"
  },
  [112290126] = {
    id = 112290126,
    name = "蒂娜刚刚是不是说了什么？"
  },
  [112290127] = {id = 112290127, name = "没有。"},
  [112290128] = {
    id = 112290128,
    name = "小莎听见了哦。"
  },
  [112290129] = {
    id = 112290129,
    name = "那是幻听。"
  },
  [112290130] = {
    id = 112290130,
    name = "你们俩呀——明明都挺期待的嘛。"
  },
  [112290131] = {
    id = 112290131,
    name = "谁期待了！"
  },
  [112290132] = {
    id = 112290132,
    name = "我没有。"
  },
  [112290133] = {
    id = 112290133,
    name = "两人又一次，同时别开了脸。"
  },
  [112290134] = {
    id = 112290134,
    name = "筹备会的后院是一间小小的木匠工坊。"
  },
  [112290135] = {
    id = 112290135,
    name = "墙上挂满了面具，笑的、怒的、戴花的、长角的。"
  },
  [112290136] = {
    id = 112290136,
    name = "好多面具啊。"
  },
  [112290137] = {
    id = 112290137,
    name = "这些是给游行的人用的，一人一副，戴一整天也不累。"
  },
  [112290138] = {
    id = 112290138,
    name = "那两副呢？"
  },
  [112290139] = {
    id = 112290139,
    name = "蒂娜指着墙角——那里单独摆着一个木匣。"
  },
  [112290140] = {
    id = 112290140,
    name = "......那是主角用的。"
  },
  [112290141] = {id = 112290141, name = "主角？"},
  [112290142] = {
    id = 112290142,
    name = "巡礼的故事里，主角只有两个。"
  },
  [112290143] = {
    id = 112290143,
    name = "一个红斗篷的小姑娘，还有一只大灰狼。"
  },
  [112290144] = {
    id = 112290144,
    name = "这个故事小莎听过，是不是还有个奶奶来着？"
  },
  [112290145] = {
    id = 112290145,
    name = "嗯，小红帽要穿过森林去看奶奶。"
  },
  [112290146] = {
    id = 112290146,
    name = "那狼呢？"
  },
  [112290147] = {
    id = 112290147,
    name = "狼嘛，就是森林里最麻烦的那个。"
  },
  [112290148] = {
    id = 112290148,
    name = "......听起来不是什么好角色。"
  },
  [112290149] = {
    id = 112290149,
    name = "老匠人把木匣捧到桌上，掀开盖子。"
  },
  [112290150] = {
    id = 112290150,
    name = "匣中并排放着两副面具：一副是红色的，一副是黑色的；非常精美，都镶嵌着魔法石。"
  },
  [112290151] = {
    id = 112290151,
    name = "......做得好细。"
  },
  [112290152] = {
    id = 112290152,
    name = "这两副，跟墙上的不一样。"
  },
  [112290153] = {
    id = 112290153,
    name = "当然不一样。墙上的那些，是我照着尺寸做的。"
  },
  [112290154] = {
    id = 112290154,
    name = "这两副，是我年轻时倾注心血按照故事做的。"
  },
  [112290155] = {
    id = 112290155,
    name = "我特别注入了魔法，遇到合适的人带上，在别人眼里就能呈现出适配角色的样子。"
  },
  [112290156] = {
    id = 112290156,
    name = "那不是更旧了吗？"
  },
  [112290157] = {
    id = 112290157,
    name = "是更用心。"
  },
  [112290158] = {
    id = 112290158,
    name = "老匠人把红斗篷那副推到尼莉莎面前。"
  },
  [112290159] = {id = 112290159, name = "试试。"},
  [112290160] = {
    id = 112290160,
    name = "......很轻诶。"
  },
  [112290161] = {id = 112290161, name = "轻？"},
  [112290162] = {
    id = 112290162,
    name = "小莎以为会压得脸疼，结果一点都不。"
  },
  [112290163] = {
    id = 112290163,
    name = "她对着铜镜左右转了转，面具的边沿严丝合缝地贴着脸。"
  },
  [112290164] = {
    id = 112290164,
    name = "镜子里的尼莉莎看起来俨然一副俏皮的小红帽装扮。"
  },
  [112290165] = {
    id = 112290165,
    name = "我也试试。"
  },
  [112290166] = {
    id = 112290166,
    name = "戴上面具，蒂娜看起来也是美丽的狼女模样。"
  },
  [112290167] = {
    id = 112290167,
    name = "哇......蒂娜真的像狼诶。"
  },
  [112290168] = {
    id = 112290168,
    name = "......是吗。"
  },
  [112290169] = {
    id = 112290169,
    name = "多少年了......终于！"
  },
  [112290170] = {id = 112290170, name = "嗯？"},
  [112290171] = {
    id = 112290171,
    name = "这两副面具，年年都拿出来试，年年都戴不上。"
  },
  [112290172] = {
    id = 112290172,
    name = "不是太沉，就是卡得脸疼，没有一个合适的。"
  },
  [112290173] = {
    id = 112290173,
    name = "那今年——"
  },
  [112290174] = {
    id = 112290174,
    name = "今年合适了。终于等到人了啊。"
  },
  [112290175] = {
    id = 112290175,
    name = "老匠人背过身去，用袖子擦了擦眼角。"
  },
  [112290176] = {
    id = 112290176,
    name = "那个......老爷爷？"
  },
  [112290177] = {
    id = 112290177,
    name = "没事没事，风大。"
  },
  [112290178] = {
    id = 112290178,
    name = "哎呀——多么好的一幕呀。"
  },
  [112290179] = {
    id = 112290179,
    name = "安妮斯你又来了。"
  },
  [112290180] = {
    id = 112290180,
    name = "面具很合适。"
  },
  [112290181] = {
    id = 112290181,
    name = "那是当然，我按故事里角色倾注心血做的。"
  },
  [112290182] = {
    id = 112290182,
    name = "镇上还有句老话——戴上这面具的人，都会比平常坦率些。"
  },
  [112290183] = {id = 112290183, name = "坦率？"},
  [112290184] = {
    id = 112290184,
    name = "毕竟戴上了，说话的就不是自己了嘛，是故事里的人。"
  },
  [112290185] = {
    id = 112290185,
    name = "......迷信的说法。"
  },
  [112290186] = {
    id = 112290186,
    name = "也许是吧。不过每年巡礼，总有人戴上面具以后，说了些平时不敢说的话。"
  },
  [112290187] = {
    id = 112290187,
    name = "诶——那不是很有意思！"
  },
  [112290188] = {
    id = 112290188,
    name = "小莎才不会呢。"
  },
  [112290189] = {
    id = 112290189,
    name = "我也不会。"
  },
  [112290190] = {
    id = 112290190,
    name = "你们俩回答得好快哦。"
  },
  [112290191] = {
    id = 112290191,
    name = "因为本来就不会嘛。"
  },
  [112290192] = {
    id = 112290192,
    name = "......大概是吧。"
  },
  [112290193] = {
    id = 112290193,
    name = "（总感觉，这句话没那么简单。）"
  },
  [112290194] = {
    id = 112290194,
    name = "你把视线移回那两副面具上。"
  },
  [112290195] = {
    id = 112290195,
    name = "烛火下，红色面具安静地笑着。"
  },
  [112290196] = {
    id = 112290196,
    name = "而那只黑色的面具上，黄色晶石闪着奇异的光。"
  },
  [112290197] = {
    id = 112290197,
    name = "当天夜里，筹备会发下了剧本。"
  },
  [112290198] = {
    id = 112290198,
    name = "薄薄的一册，封面上画着红斗篷的小姑娘和一条林间小路。"
  },
  [112290199] = {
    id = 112290199,
    name = "就这个？"
  },
  [112290200] = {
    id = 112290200,
    name = "只有八页。"
  },
  [112290201] = {
    id = 112290201,
    name = "尼莉莎翻开第一页，眉毛一点点拧了起来。"
  },
  [112290202] = {
    id = 112290202,
    name = "等一下。这故事里的小红帽，为什么非要走那条路啊？"
  },
  [112290203] = {
    id = 112290203,
    name = "因为那是去奶奶家的路。"
  },
  [112290204] = {
    id = 112290204,
    name = "绕过去不就好了吗？"
  },
  [112290205] = {
    id = 112290205,
    name = "绕过去就不是这个故事了。"
  },
  [112290206] = {
    id = 112290206,
    name = "可是明明有别的路！"
  },
  [112290207] = {
    id = 112290207,
    name = "还有这里——明知道森林里有狼，为什么还要一个人去？"
  },
  [112290208] = {
    id = 112290208,
    name = "为什么不去叫人一起来？为什么路上还要停下来采花？"
  },
  [112290209] = {
    id = 112290209,
    name = "还有最后这里，狼把奶奶吞下去以后——"
  },
  [112290210] = {
    id = 112290210,
    name = "为什么猎人刚好就路过啊？太巧了吧。"
  },
  [112290211] = {
    id = 112290211,
    name = "故事就是这么写的。"
  },
  [112290212] = {
    id = 112290212,
    name = "可是太巧了嘛。"
  },
  [112290213] = {
    id = 112290213,
    name = "所以才说要改剧本呀！"
  },
  [112290214] = {
    id = 112290214,
    name = "......你在跟故事较劲。"
  },
  [112290215] = {
    id = 112290215,
    name = "小莎是在帮她想办法！这个故事里到处都是麻烦。"
  },
  [112290216] = {
    id = 112290216,
    name = "麻烦才叫故事。"
  },
  [112290217] = {
    id = 112290217,
    name = "那小莎宁可不要这种故事。"
  },
  [112290218] = {
    id = 112290218,
    name = "小莎，你其实很认真呢。"
  },
  [112290219] = {
    id = 112290219,
    name = "安妮斯！"
  },
  [112290220] = {
    id = 112290220,
    name = "那蒂娜那边呢？"
  },
  [112290221] = {
    id = 112290221,
    name = "我在看大灰狼的部分。"
  },
  [112290222] = {
    id = 112290222,
    name = "蒂娜的剧本上，密密麻麻写满了小字。"
  },
  [112290223] = {
    id = 112290223,
    name = "诶——你写这么多？"
  },
  [112290224] = {id = 112290224, name = "笔记。"},
  [112290225] = {
    id = 112290225,
    name = "狼什么时候出现，从哪个方向出现，怎么让小红帽注意到它。"
  },
  [112290226] = {
    id = 112290226,
    name = "......你该不会打算照着演吧。"
  },
  [112290227] = {
    id = 112290227,
    name = "接了就该做好。"
  },
  [112290228] = {
    id = 112290228,
    name = "只是游行而已嘛。"
  },
  [112290229] = {
    id = 112290229,
    name = "游行也是给别人看的。"
  },
  [112290230] = {
    id = 112290230,
    name = "真是死板。"
  },
  [112290231] = {
    id = 112290231,
    name = "这跟死不死板没关系。"
  },
  [112290232] = {
    id = 112290232,
    name = "（这两句话，今天已经听过两遍了。）"
  },
  [112290233] = {
    id = 112290233,
    name = "好啦好啦——要不要我出个主意？"
  },
  [112290234] = {
    id = 112290234,
    name = "什么主意？"
  },
  [112290235] = {
    id = 112290235,
    name = "既然你觉得故事不合理，那就改剧本嘛！"
  },
  [112290236] = {
    id = 112290236,
    name = "改成「聪明的小红帽」——遇到狼先绕路，绕不过去就先跑再想办法！"
  },
  [112290237] = {
    id = 112290237,
    name = "......好像也不是不行。"
  },
  [112290238] = {
    id = 112290238,
    name = "那就不是《小红帽》了。"
  },
  [112290239] = {
    id = 112290239,
    name = "可是这样才不会出事啊。"
  },
  [112290240] = {
    id = 112290240,
    name = "故事里的麻烦，本来就是要给人看的。"
  },
  [112290241] = {
    id = 112290241,
    name = "看完以后，才知道遇到麻烦该怎么办。"
  },
  [112290242] = {
    id = 112290242,
    name = "......蒂娜偶尔会说点像样的话嘛。"
  },
  [112290243] = {
    id = 112290243,
    name = "我平时也说的。"
  },
  [112290244] = {id = 112290244, name = "是吗？"},
  [112290245] = {
    id = 112290245,
    name = "......只是你不听而已。"
  },
  [112290246] = {
    id = 112290246,
    name = "那就一边照着演，一边偷偷改一点点？"
  },
  [112290247] = {
    id = 112290247,
    name = "就一点点哦。"
  },
  [112290248] = {
    id = 112290248,
    name = "......可以。"
  },
  [112290249] = {
    id = 112290249,
    name = "两人各自把剧本摊在膝上，谁也不再说话。"
  },
  [112290250] = {
    id = 112290250,
    name = "烛火下，一支笔在纸上沙沙地走。"
  },
  [112290251] = {
    id = 112290251,
    name = "（如果遇到奇怪的人......先跑，再想办法。）"
  },
  [112290252] = {
    id = 112290252,
    name = "（这样写，应该没问题吧。）"
  },
  [112290253] = {
    id = 112290253,
    name = "（「我已经抓到了。」）"
  },
  [112290254] = {
    id = 112290254,
    name = "（......这句台词，为什么会让人有点在意。）"
  },
  [112290255] = {
    id = 112290255,
    name = "（两个人，其实都挺认真的。）"
  },
  [112290256] = {
    id = 112290256,
    name = "夜深了，窗外的铜铃被风吹得轻轻响着。"
  },
  [112290257] = {
    id = 112290257,
    name = "剧本摊在桌上，一直翻到最后一页。"
  },
  [112290258] = {
    id = 112290258,
    name = "巡礼前夜，铃穗镇的中心广场灯火通明。"
  },
  [112290259] = {
    id = 112290259,
    name = "摊子一个挨着一个，糖霜的甜味混着麦酒香飘了满街。"
  },
  [112290260] = {
    id = 112290260,
    name = "哇——这边的糖饼好香！那边的铃铛也好可爱！"
  },
  [112290261] = {
    id = 112290261,
    name = "别走散了。"
  },
  [112290262] = {
    id = 112290262,
    name = "知道啦——"
  },
  [112290263] = {
    id = 112290263,
    name = "安妮斯一溜烟钻进了人群。"
  },
  [112290264] = {
    id = 112290264,
    name = "......她真的听得进去吗。"
  },
  [112290265] = {
    id = 112290265,
    name = "从小就没听过。"
  },
  [112290266] = {
    id = 112290266,
    name = "你们认识很久了？"
  },
  [112290267] = {
    id = 112290267,
    name = "嗯。她一直是这样。"
  },
  [112290268] = {
    id = 112290268,
    name = "两位！这边这边！"
  },
  [112290269] = {
    id = 112290269,
    name = "兰伯特先生在人群中挥着手，身边围了一圈孩子。"
  },
  [112290270] = {
    id = 112290270,
    name = "今晚是彩排，先把面具戴上去转一圈，让孩子们认认脸。"
  },
  [112290271] = {
    id = 112290271,
    name = "现在？在这里？"
  },
  [112290272] = {
    id = 112290272,
    name = "对呀，不然明天他们会吓到的。"
  },
  [112290273] = {
    id = 112290273,
    name = "蒂娜先戴上了面具。"
  },
  [112290274] = {
    id = 112290274,
    name = "面具一戴，她整个人沉静下来，像是从林子里走出来的。"
  },
  [112290275] = {
    id = 112290275,
    name = "孩子们一下子安静了。"
  },
  [112290276] = {
    id = 112290276,
    name = "......呜。"
  },
  [112290277] = {id = 112290277, name = "狼......"},
  [112290278] = {
    id = 112290278,
    name = "最小的那个孩子哇地一声哭了。"
  },
  [112290279] = {id = 112290279, name = "......！"},
  [112290280] = {
    id = 112290280,
    name = "蒂娜手忙脚乱地把面具摘了下来。"
  },
  [112290281] = {
    id = 112290281,
    name = "抱歉，吓到你了。"
  },
  [112290282] = {
    id = 112290282,
    name = "她蹲下身，笨拙地拍着孩子的背。"
  },
  [112290283] = {
    id = 112290283,
    name = "不哭不哭，是我不好。只是面具而已......你看，摘掉就没事了。"
  },
  [112290284] = {
    id = 112290284,
    name = "......真的。可是你刚刚好凶哦。"
  },
  [112290285] = {
    id = 112290285,
    name = "......嗯。我会注意的。"
  },
  [112290286] = {
    id = 112290286,
    name = "孩子抽着鼻子，伸出小手拉住了她的袖子。"
  },
  [112290287] = {
    id = 112290287,
    name = "那你明天还来吗？"
  },
  [112290288] = {
    id = 112290288,
    name = "......来。"
  },
  [112290289] = {
    id = 112290289,
    name = "那我明天不怕你了。"
  },
  [112290290] = {
    id = 112290290,
    name = "孩子破涕为笑，一溜烟跑回了人群里。"
  },
  [112290291] = {
    id = 112290291,
    name = "蒂娜还挺会哄人的嘛。"
  },
  [112290292] = {
    id = 112290292,
    name = "你看到了？"
  },
  [112290293] = {
    id = 112290293,
    name = "小莎什么都没看到哦。"
  },
  [112290294] = {
    id = 112290294,
    name = "......那就好。"
  },
  [112290295] = {
    id = 112290295,
    name = "咳咳——两位，该你了哦？"
  },
  [112290296] = {
    id = 112290296,
    name = "安妮斯不知何时回来了，手里还举着一串糖果。"
  },
  [112290297] = {
    id = 112290297,
    name = "......小莎可以不戴吗。"
  },
  [112290298] = {
    id = 112290298,
    name = "不行不行，孩子们都等着呢。"
  },
  [112290299] = {
    id = 112290299,
    name = "尼莉莎不情不愿地戴上红面具。"
  },
  [112290300] = {
    id = 112290300,
    name = "面具一戴上，她的声音就不自觉地轻快了起来。"
  },
  [112290301] = {
    id = 112290301,
    name = "小红帽姐姐——！"
  },
  [112290302] = {
    id = 112290302,
    name = "一瞬间，四五个孩子围了上来。"
  },
  [112290303] = {
    id = 112290303,
    name = "小红帽，你的篮子里有点心吗？"
  },
  [112290304] = {
    id = 112290304,
    name = "......没有啊。"
  },
  [112290305] = {
    id = 112290305,
    name = "那明天会有吗？"
  },
  [112290306] = {
    id = 112290306,
    name = "明天......可能有吧。"
  },
  [112290307] = {
    id = 112290307,
    name = "耶——！"
  },
  [112290308] = {
    id = 112290308,
    name = "小红帽，森林里有狼怎么办呀？"
  },
  [112290309] = {id = 112290309, name = "......"},
  [112290310] = {
    id = 112290310,
    name = "（......怎么又问这个。）"
  },
  [112290311] = {
    id = 112290311,
    name = "遇到奇怪的人，就先跑，再想办法。"
  },
  [112290312] = {
    id = 112290312,
    name = "跑不掉的话，就大声喊人。"
  },
  [112290313] = {
    id = 112290313,
    name = "记住了！"
  },
  [112290314] = {
    id = 112290314,
    name = "小红帽最厉害了！"
  },
  [112290315] = {
    id = 112290315,
    name = "......哼，那当然。"
  },
  [112290316] = {
    id = 112290316,
    name = "尼莉莎别过脸去，肩膀却轻轻抖了一下。"
  },
  [112290317] = {
    id = 112290317,
    name = "哎呀呀——某人明明乐在其中嘛。"
  },
  [112290318] = {
    id = 112290318,
    name = "安妮斯你再多说一句，小莎就把你糖葫芦抢了。"
  },
  [112290319] = {
    id = 112290319,
    name = "我什么都没说！"
  },
  [112290320] = {
    id = 112290320,
    name = "（这样就好了。）"
  },
  [112290321] = {
    id = 112290321,
    name = "广场中央的铜铃被人敲响，前夜祭正式开场。"
  },
  [112290322] = {
    id = 112290322,
    name = "火光、笑声、糖霜的甜味，一起涌了上来。"
  },
  [112290323] = {
    id = 112290323,
    name = "深夜，小镇安静下来，只剩下风里的铃声。"
  },
  [112290324] = {
    id = 112290324,
    name = "你起身去确认明天的路线，路过广场时，一个红色的身影出现在空地上。"
  },
  [112290325] = {
    id = 112290325,
    name = "（小红帽应该是这样走......不对，太做作了。）"
  },
  [112290326] = {
    id = 112290326,
    name = "（那这样呢......也不对，像在逛街。）"
  },
  [112290327] = {
    id = 112290327,
    name = "她提着空篮子，在月光下一遍遍来回踱步。"
  },
  [112290328] = {
    id = 112290328,
    name = "（遇到狼的时候，先停下，看脚印——）"
  },
  [112290329] = {
    id = 112290329,
    name = "（然后......然后往回走？不行，剧本上不是这么写的。）"
  },
  [112290330] = {
    id = 112290330,
    name = "尼莉莎。"
  },
  [112290331] = {
    id = 112290331,
    name = "——！队、队长？你怎么在这里！"
  },
  [112290332] = {
    id = 112290332,
    name = "我起来看路线。"
  },
  [112290333] = {
    id = 112290333,
    name = "小莎也是来看路线的！"
  },
  [112290334] = {
    id = 112290334,
    name = "......你手里拿的是篮子。"
  },
  [112290335] = {
    id = 112290335,
    name = "篮子也可以用来看路！"
  },
  [112290336] = {
    id = 112290336,
    name = "......好吧，小莎在练习。只是练习！"
  },
  [112290337] = {
    id = 112290337,
    name = "毕竟明天要是走错了会很丢脸嘛，小莎才不是因为想演好才练的。"
  },
  [112290338] = {
    id = 112290338,
    name = "我没说你是。"
  },
  [112290339] = {
    id = 112290339,
    name = "......！（你那表情就是这么说的。）"
  },
  [112290340] = {
    id = 112290340,
    name = "队长好坏。"
  },
  [112290341] = {id = 112290341, name = "噗......"},
  [112290342] = {
    id = 112290342,
    name = "不准笑！"
  },
  [112290343] = {
    id = 112290343,
    name = "尼莉莎抱着篮子，气鼓鼓地转过身。"
  },
  [112290344] = {
    id = 112290344,
    name = "可她没有回房间，而是又走回了空地中央。"
  },
  [112290345] = {
    id = 112290345,
    name = "（......再练一遍，就一遍。）"
  },
  [112290346] = {
    id = 112290346,
    name = "另一边，筹备会门口的灯笼还亮着。"
  },
  [112290347] = {
    id = 112290347,
    name = "蒂娜坐在台阶上，膝上摊着剧本。"
  },
  [112290348] = {
    id = 112290348,
    name = "（「我已经抓到了。」）"
  },
  [112290349] = {
    id = 112290349,
    name = "（......）"
  },
  [112290350] = {
    id = 112290350,
    name = "（「带你回来。」）"
  },
  [112290351] = {
    id = 112290351,
    name = "她念了两遍，又停了下来。"
  },
  [112290352] = {id = 112290352, name = "蒂娜。"},
  [112290353] = {
    id = 112290353,
    name = "......！队长。您怎么还没休息。"
  },
  [112290354] = {
    id = 112290354,
    name = "这句话，你念了很多遍。"
  },
  [112290355] = {
    id = 112290355,
    name = "......只是确认一下语气。"
  },
  [112290356] = {
    id = 112290356,
    name = "我在想，狼说这句话的时候，应该是什么表情。"
  },
  [112290357] = {
    id = 112290357,
    name = "故事里，它应该是得意的。可是我念出来，总觉得不像。"
  },
  [112290358] = {
    id = 112290358,
    name = "不像什么？"
  },
  [112290359] = {
    id = 112290359,
    name = "不像会吃掉小红帽的狼。"
  },
  [112290360] = {
    id = 112290360,
    name = "......也许我演不好这个角色。"
  },
  [112290361] = {
    id = 112290361,
    name = "为什么这么想？"
  },
  [112290362] = {
    id = 112290362,
    name = "因为我做不到。"
  },
  [112290363] = {
    id = 112290363,
    name = "我做不到故意吓唬人，也做不到看着别人遇到麻烦不管。"
  },
  [112290364] = {
    id = 112290364,
    name = "刚刚那个孩子哭了，我第一反应是摘面具。那不是狼该做的事。"
  },
  [112290365] = {
    id = 112290365,
    name = "那是什么？"
  },
  [112290366] = {
    id = 112290366,
    name = "......是我该做的事。"
  },
  [112290367] = {
    id = 112290367,
    name = "蒂娜低下头，手指在剧本边缘摩挲了一下。"
  },
  [112290368] = {
    id = 112290368,
    name = "明天我会照着剧本演。但如果有人需要帮忙，我还是会先去帮忙。"
  },
  [112290369] = {
    id = 112290369,
    name = "哪怕那样，不像一只狼。"
  },
  [112290370] = {
    id = 112290370,
    name = "那就这么演。"
  },
  [112290371] = {
    id = 112290371,
    name = "......可以吗？"
  },
  [112290372] = {
    id = 112290372,
    name = "故事本来就该由演的人来决定。"
  },
  [112290373] = {
    id = 112290373,
    name = "......谢谢您。"
  },
  [112290374] = {
    id = 112290374,
    name = "蒂娜把剧本合上，抬头看向远处的广场。"
  },
  [112290375] = {
    id = 112290375,
    name = "红斗篷的身影还在月光下，一遍遍来回走着。"
  },
  [112290376] = {
    id = 112290376,
    name = "（......那个人，也还没睡啊。）"
  },
  [112290377] = {
    id = 112290377,
    name = "（......算了，就当小莎没看见。）"
  },
  [112290378] = {
    id = 112290378,
    name = "第二天清晨，两副面具被并排放回木匣。"
  },
  [112290379] = {
    id = 112290379,
    name = "匣盖合上前，烛火在两张面容上晃了一下。"
  },
  [112290380] = {
    id = 112290380,
    name = "红斗篷少女在笑，野兽安静地看着前方。"
  },
  [112290381] = {
    id = 112290381,
    name = "巡礼，就要开始了。"
  }
}
